PACKAGE qm_pg IS
-------------------------------------------------------------------------------
--пакет для работы с меткой качества
-- 08.10.2008 Сечин А.А.
-------------------------------------------------------------------------------
/*************************  Метка качества  *****************************************************************************************************
  Основные поля
     1 - достоверность                      Validity                    (0-норма, 1-недостоверные данные, 2-зарезервированные данные(когда их нет или неполнота), 3-под вопросом)
     2 - переполнение                       OVERFLOW                    (0-Нет, 1-Да)
     3 - выход за границы                   OutOfRange                  (0-Нет, 1-Да)
     4 - нарушение калибровки источника     BadReference                (0-Нет, 1-Да)
     5 - дребезг сигнала                    Oscillatory                 (0-Нет, 1-Да)
     6 - сбой                               FAILURE                     (0-Нет, 1-Да)
     7 - устаревшие данные                  OldData                     (0-Нет, 1-Да)
     8 - неустойчивость (противоречивость)  Inconsistent                (0-Нет, 1-Да)
     9 - неточность                         Inaccurate                  (0-Нет, 1-Да)
     10- источник данных                    SOURCE                      (0-процесс, 1-подставлено оператором)
     11- тестовые данные                    Test                        (0-Нет, 1-Да)
     12- заблокированно оператором          OperatorBlocked             (0-Нет, 1-Да)
  Дополнительные поля
     13 -получение исходных данных          DataRecieve                 (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     14 -контроль своевременности данных    DataOnTime                  (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     15 -контроль по ЖС                     MeterLogCheck               (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     16 -контроль границ                    BoundaryCheck               (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     17 -Восстановл по первичным данным     PrimaryRepearing            (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     18 -Верификация по первичным данным    PrimaryVerifivation         (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     19 -Учет ОВ                            BypassUsing                 (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     20 -Дорасчет                           Calculation                 (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     21 -Верификация по балансу             XVerification               (0-обработка не выполнялась,1-недостаточно данных,2-ОК,3-Ошибка)
     22 -Код источника данных               AMRSource                   (0-нет данных,1-осн.прибор,2-дуб.прибор,3-ОИК,4-руч.ввод,5-макет,6-прибор ОВ,7-рез.вычисл автоматический., 8 - рез.вычисл с замещением)
     23 -Признак отчетных данных            ReportData                  (0-Нет, 1-Да)*/
-------------------------------------------------------------------------------
 cn_ok           CONSTANT VARCHAR2 (1)  := '0';   --норма
 cn_invalid      CONSTANT VARCHAR2 (1)  := '1';   --недостоверные данные
