PACKAGE uniinterior3_pg IS
------------------------------------------------------------------------------------------------------------------------
/* Данный пакет используется для написания собственного кода сторонними разработчиками
   Спецификацию пакета менять не  разрешается
   Для написание собственного кода используйте тело пакета а из него можно ретранслировать вызовы к своим пакетам
*/
------------------------------------------------------------------------------------------------------------------------
  -- Возвращает информацию по колонкам таблицы для макета
 PROCEDURE getinfo(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER,
 an_cnfooter OUT NUMBER, col_t OUT common_pg.tcur, row_t OUT common_pg.tcur
 );

/*
an_fid         - Ид формы
an_ispoint      - Признак точки
an_id           - Ид (точки или группы)
ad_from         - Дата с
ad_till         - Дата по
an_cnfixcol --количество фикс колонок
an_cntitle --количество строк в заголовке
col_t -- информация по колонкам таблицы - курсор, строка которого есть
 id - идентификатор колонки
 Title1, Title2, ... (=an_cntitle) - наименование
 TitleCl - цвет заголовка
 TitleAl - выравнивание заголовка
 DataCl - цвет данных
 DataAl - выравнивание данных
 nlock - блокировка редактирования
 nwidth - ширина колонки (если<=0 то auto)
 vmasks - маска колонки (может быть NULL)
row_t -- информация по строкам таблицы - курсор, строка которого есть
 id - идентификатор сторки
 Title1, Title2, ... (=an_cnfixcol) - наименование
 DataCl - цвет данных
 nlock - блокировка редактирования
 vmasks - маска строки (может быть NULL)
*/
------------------------------------------------------------------------------------------------------------------------
-- Возвращает содержимое макета
 PROCEDURE getvalue(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t OUT common_pg.tt_number, quality OUT VARCHAR2, ad_forming_data OUT DATE
 );

------------------------------------------------------------------------------------------------------------------------
-- Возвращает данные для графического представления состава макета (если график не поддерхивается возвращает 0)
 FUNCTION getgrafvalue(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_col NUMBER, an_row NUMBER, av_title OUT VARCHAR2, av_xtitle OUT VARCHAR2,
 av_ytitle OUT VARCHAR2, x_t OUT common_pg.tt_number, y_t OUT common_pg.tt_number
 )
  RETURN NUMBER;

------------------------------------------------------------------------------------------------------------------------
 -- Сохраняет содержимое макета
 PROCEDURE savevalue(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_col NUMBER, an_row NUMBER, an_value NUMBER);
------------------------------------------------------------------------------------------------------------------------

END;                                                                                                                                             -- Package spec
/


