-- Start of DDL Script for Package Body RYDA.ADDPARAM_PG
-- Generated 14.04.2014 9:34:56 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY addparam_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет работы с доп параметрами объектов разных типов
  -- дата создания 07/10/2008 (Сечин А.А.)
  --edited 22.07.09
  gn_task_code          NUMBER DEFAULT 46;
------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_addtable (an_table NUMBER DEFAULT 1)
  RETURN VARCHAR2 IS
 BEGIN
  IF an_table = cn_tab_forms THEN
   RETURN 'form';
  ELSIF an_table = cn_tab_groups THEN
   RETURN 'group';
  ELSE
   RETURN 'point';
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_addparam (an_mid NUMBER, an_type NUMBER, acur_t OUT common_pg.tcur, an_table NUMBER) IS   --Доп параметры объектов (an_table=2- forms; иначе points)
  ln_table NUMBER DEFAULT nvl(an_table,1); 
  ln_mid     NUMBER          DEFAULT NVL (an_mid, 0);
  lv_sql     VARCHAR2 (2000);
  lv_add     VARCHAR2 (2000);
  lv_table   VARCHAR2 (2000) DEFAULT get_addtable (an_table);
 BEGIN
  lv_sql :=
   'SELECT   ' || ln_mid || ' mid, p.nsort, p.vdescr, DECODE (p.ntype, 6, decode(nvl(dbms_lob.getlength(v.bvalue),0),0,''(Clob)'',''(CLOB)''), 7, decode(nvl(dbms_lob.getlength(v.bvalue),0),0,''(Blob)'',''(BLOB)''), v.vvalue) vvalue, p.ntype,'||ln_table||' objtype FROM add' || lv_table
   || 'param p, add' || lv_table || 'paramval v WHERE p.nsort = v.nsort(+) AND ' || ln_mid || ' = v.mid(+) ';

  IF an_table = cn_tab_points THEN
   IF an_type = cn_points_limit THEN
    lv_sql := lv_sql || 'AND p.nsort BETWEEN -30 AND -1 ORDER BY SIGN (p.nsort), ABS (p.nsort), p.vdescr';
   ELSIF an_type = cn_meas THEN
    lv_sql := lv_sql || 'AND p.nsort BETWEEN -50 AND -31 ORDER BY SIGN (p.nsort), ABS (p.nsort), p.vdescr';
   ELSE
    lv_sql := lv_sql || 'AND p.nsort >= 0 ORDER BY SIGN (p.nsort), ABS (p.nsort), p.vdescr';
   END IF;
  ELSIF an_table = cn_tab_forms THEN
   IF an_type = cn_forms_uni THEN
    lv_sql := lv_sql || 'AND p.nsort BETWEEN -14 AND -1 ORDER BY SIGN (p.nsort), ABS (p.nsort), p.vdescr';
   ELSE
    lv_sql := lv_sql || 'AND p.nsort >= 0 ORDER BY SIGN (p.nsort), ABS (p.nsort), p.vdescr';
   END IF;
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE upd_addparam (an_mid NUMBER, at_value common_pg.tt_varchar2, an_table NUMBER) IS   --Обновление доп параметров
 BEGIN
  SAVEPOINT upd_addparam_sp;

  FOR i IN 1 .. at_value.COUNT LOOP
   upd_addparam (an_mid, i, at_value (i));
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT upd_addparam_sp;
   RAISE;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE upd_addparam (an_mid NUMBER, an_sort NUMBER, av_value VARCHAR2, an_table NUMBER) IS   --Обновление доп параметров
  lv_table      VARCHAR2 (2000) DEFAULT get_addtable (an_table);
  lv_tmp        VARCHAR2 (2000) DEFAULT av_value;
  ln_type       NUMBER;
  lv_param      VARCHAR2 (500);
  lv_from_val   VARCHAR2 (100);
  lv_to_val     VARCHAR2 (100);
  lv_from_to    VARCHAR2 (500);
 BEGIN
  EXECUTE IMMEDIATE 'SELECT NVL (MAX (ntype), 0) FROM add' || lv_table || 'param WHERE nsort = :an_sort'
               INTO ln_type
              USING an_sort;

  IF ln_type IN (6, 7) THEN   --CLOB,BLOB
   RETURN;
  END IF;

  EXECUTE IMMEDIATE 'SELECT max(vvalue) FROM ADD' || lv_table || 'paramval WHERE mid = :an_mid AND nsort = :an_sort'
               INTO lv_from_val
              USING an_mid, an_sort;
  lv_to_val := lv_tmp;
  
  IF lv_tmp IS NULL THEN
   EXECUTE IMMEDIATE 'DELETE FROM add' || lv_table || 'paramval WHERE mid = :an_mid AND nsort = :an_sort'
               USING an_mid, an_sort;
   lv_from_to := ': удалено значение "'||lv_from_val||'"';
  ELSE
   IF ln_type = 1 THEN   --INTEGER
    lv_tmp := util_pg.varchar_to_integer (lv_tmp);
   ELSIF ln_type = 2 THEN   --NUMBER
    lv_tmp := util_pg.varchar_to_number (lv_tmp);
   ELSIF ln_type = 3 THEN   --DATE
    lv_tmp := util_pg.varchar_to_date (lv_tmp);
   ELSIF ln_type = 4 THEN   --TIME
    lv_tmp := util_pg.varchar_to_time (lv_tmp);
   ELSIF ln_type = 5 THEN   --DATETIME
    lv_tmp := util_pg.varchar_to_datetime (lv_tmp);
   END IF;

   EXECUTE IMMEDIATE 'UPDATE add' || lv_table || 'paramval SET vvalue = :lv_tmp   WHERE mid =:an_mid AND nsort = :an_sort'
               USING lv_tmp, an_mid, an_sort;
   lv_from_to := ' с  "'||lv_from_val||'" на "'||lv_to_val||'"';

   IF SQL%ROWCOUNT = 0 THEN
    EXECUTE IMMEDIATE 'INSERT INTO add' || lv_table || 'paramval(mid, nsort, vvalue) VALUES (:an_mid ,:an_sort , :lv_tmp)'
                USING an_mid, an_sort, lv_tmp;
    lv_from_to := ' на "'||lv_to_val||'"';
   END IF;
  END IF;

  SELECT vdescr INTO lv_param FROM ADDPOINTPARAM WHERE nsort = an_sort;  

  IF an_table = cn_tab_points THEN  
      IF an_sort BETWEEN -24 AND -1 THEN
        admin_pg.fiscal_p (gn_task_code, 2, 'Изменен параметр границ "'||lv_param||'" для точки '|| util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') ||lv_from_to);
      ELSIF an_sort BETWEEN -50 AND -31 THEN
        admin_pg.fiscal_p (gn_task_code, 2, 'Изменен код канала или код объекта "'||lv_param||'" для точки '|| util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') ||lv_from_to);
      ELSIF an_sort >= 0 THEN
        admin_pg.fiscal_p (gn_task_code, 2, 'Изменен специальный параметр "'||lv_param||'" для точки '|| util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') ||lv_from_to);  
      END IF;
  END IF;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE upd_addparam (an_mid NUMBER, an_sort NUMBER, ac_value IN OUT CLOB, an_table NUMBER) IS   --Обновление доп параметров
 BEGIN
  NULL;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE upd_addparam (an_mid NUMBER, an_sort NUMBER, ab_value IN OUT BLOB, an_table NUMBER) IS   --Обновление доп параметров
  lv_table   VARCHAR2 (2000) DEFAULT get_addtable (an_table);
 BEGIN
  IF an_table = 2 THEN
   IF ab_value IS NULL THEN
    DELETE FROM addformparamval
          WHERE mid = an_mid AND nsort = an_sort;
   ELSE
    UPDATE    addformparamval
          SET bvalue = ab_value
        WHERE mid = an_mid AND nsort = an_sort
    RETURNING bvalue
         INTO ab_value;
   END IF;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO addformparamval
                (mid, nsort, bvalue
                )
         VALUES (an_mid, an_sort, EMPTY_BLOB ()
                )
      RETURNING bvalue
           INTO ab_value;
   END IF;
  ELSE
   IF ab_value IS NULL THEN
    DELETE FROM addpointparamval
          WHERE mid = an_mid AND nsort = an_sort;
   ELSE
    UPDATE    addpointparamval
          SET bvalue = ab_value
        WHERE mid = an_mid AND nsort = an_sort
    RETURNING bvalue
         INTO ab_value;
   END IF;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO addpointparamval
                (mid, nsort, bvalue
                )
         VALUES (an_mid, an_sort, EMPTY_BLOB ()
                )
      RETURNING bvalue
           INTO ab_value;
   END IF;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'ADDPARAM_PG.upd_addparam: Ошибка сохранения BLOB файла. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

-------------------------------------------------------------------------------------------
 FUNCTION get_caption (an_mid NUMBER, an_type NUMBER, an_table NUMBER DEFAULT 1)
  RETURN VARCHAR2   --Обновление доп параметров
                 IS
  lv_ret   VARCHAR2 (512) := 'Дополнительные параметры';
 BEGIN
  IF an_table = cn_tab_points THEN   --Точки учета
   IF an_type = cn_points_limit THEN
    lv_ret := 'Физические и технологические границы точки учета "' || util_pg.get_pointname (an_mid, 0, 0) || '"';
   ELSIF an_type = cn_meas THEN
    lv_ret := 'Коды каналов и коды объектов для точки учета "' || util_pg.get_pointname (an_mid, 0, 0) || '"';
   ELSE
    lv_ret := 'Специальные параметры для точки учета "' || util_pg.get_pointname (an_mid, 0, 0) || '"';
   END IF;
  ELSIF an_table = cn_tab_forms THEN   --Формы учета
   lv_ret := 'Специальные параметры для формы "' || editforms_pg.get_formname (an_mid) || '"';
  END IF;

  RETURN lv_ret;
 END;
-------------------------------------------------------------------------------------------
PROCEDURE get_columbname( acur_t OUT common_pg.tcur) IS   --Для колонок в таблице

 BEGIN
  OPEN acur_t FOR
   SELECT
   SUBSTR(vdescr,1,INSTR(vdescr,' ',1,2))||'|'||SUBSTR(vdescr,INSTR(vdescr,' ',1,2),(LENGTH(vdescr)+1-INSTR(vdescr,' ',1,2))) vname
     FROM addpointparam p
      WHERE
     p.nsort BETWEEN -50 AND -31 ORDER BY SIGN (p.nsort), ABS (p.nsort), p.vdescr;

 END;

END;   -- Package Body
/


