 --Запись в журнал системы
 PROCEDURE ins_journal_p(ad_date DATE, an_mid NUMBER, an_state_cod NUMBER, av_message VARCHAR2, an_event NUMBER, av_code VARCHAR2) IS
  ln_ret              NUMBER;
 BEGIN
  ln_ret := ins_journal_p(ad_date, an_mid, an_state_cod, av_message, an_event, av_code);
 END;

------------------------------------------------------------------------------------------------------------------------
 --Запись в журнал системы
 FUNCTION ins_journal_p(ad_date DATE, an_mid NUMBER, an_state_cod NUMBER, av_message VARCHAR2, an_event NUMBER, av_code VARCHAR2)
  RETURN NUMBER IS
  ln_tmp              NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_tmp
  FROM   DUAL
  WHERE  EXISTS(
          SELECT *
          FROM   journal
          WHERE  mid = an_mid AND date_time = ad_date
                 AND(
                     (an_event <> 0 AND NVL(nevent, -1) = an_event AND NVL(av_code, ' ') = NVL(vcode, ' '))
                     OR(an_event IS NULL AND NVL(state_descr, ' ') = NVL(SUBSTR(av_message, 1, 512), ' ') AND NVL(av_code, ' ') = NVL(vcode, ' '))
                    ));

  IF ln_tmp = 1 THEN
   RETURN 0;
  END IF;

  INSERT INTO journal
              (date_time, mid, state_cod, state_descr, nevent, vcode)
  VALUES      (ad_date, an_mid, an_state_cod, SUBSTR(av_message, 1, 512), an_event, av_code);

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Блокировка с попытками
 FUNCTION lock_p(an_timecount NUMBER, av_tablename VARCHAR2)
  RETURN NUMBER IS
  cn_wait    CONSTANT NUMBER := 4;
  ln_timecount        NUMBER DEFAULT TRUNC(an_timecount) * cn_wait;
 BEGIN
  FOR i IN 1 .. ln_timecount LOOP
   BEGIN
    EXECUTE IMMEDIATE 'LOCK TABLE ' || av_tablename || ' IN EXCLUSIVE MODE NOWAIT';

    RETURN 1;
   EXCEPTION
    WHEN OTHERS THEN
     IF SQLCODE = -54 THEN
      IF i <> ln_timecount THEN
       SYS.DBMS_LOCK.sleep(1 / cn_wait);
      END IF;
     ELSE
      RAISE;
     END IF;
   END;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION lockrow_p(an_timecount NUMBER, av_tablename VARCHAR2, av_column VARCHAR2, ln_id NUMBER)
  RETURN NUMBER IS
  cn_wait    CONSTANT NUMBER := 4;
  ln_timecount        NUMBER DEFAULT TRUNC(an_timecount) * cn_wait;
  ln_ret              NUMBER;
 BEGIN
  FOR i IN 1 .. ln_timecount LOOP
   BEGIN
    EXECUTE IMMEDIATE 'SELECT ' || av_column || ' FROM ' || av_tablename || ' WHERE ' || av_column || '=:id FOR UPDATE NOWAIT'
    INTO              ln_ret
    USING             ln_id;

    RETURN NVL(ln_ret, 0);
   EXCEPTION
    WHEN OTHERS THEN
     IF SQLCODE = -54 THEN
      IF i <> ln_timecount THEN
       SYS.DBMS_LOCK.sleep(1 / cn_wait);
      END IF;
     ELSIF SQLCODE = 100 THEN                                                                                                                        --Нет строк
      RETURN -1;
     ELSIF SQLCODE = -1422 THEN                                                                                                                    --Много строк
      RETURN -2;
     ELSE
      RAISE;
     END IF;
   END;
  END LOOP;

  RETURN 0;
 END;

