--Возвращает дату расчетного периода
 FUNCTION get_calcperiod
  RETURN DATE IS
  ld_ret              DATE;
 BEGIN
  SELECT NVL(MAX(TO_DATE(vvalue, 'dd.mm.yyyy')), TRUNC(SYSDATE) - 1)
  INTO   ld_ret
  FROM   parameter
  WHERE  npid = 19;

  RETURN ld_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Устанавливает дату расчетного периода
 PROCEDURE set_calcperiod(d DATE) IS
 BEGIN
  UPDATE parameter
  SET vvalue = TO_CHAR(d, 'dd.mm.yyyy')
  WHERE  npid = 19;
 END;

------------------------------------------------------------------------------------------------------------------------
--Увеличивает дату расчетного периода
 PROCEDURE add_calcperiod(c NUMBER) IS
 BEGIN
  UPDATE parameter
  SET vvalue = TO_CHAR(TO_DATE(vvalue, 'dd.mm.yyyy') + c, 'dd.mm.yyyy')
  WHERE  npid = 19;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает дату последнего анализа данных
 FUNCTION get_lastdchange
  RETURN DATE IS
  ld_ret              DATE;
 BEGIN
  SELECT NVL(MAX(TO_DATE(vvalue, 'dd.mm.yyyy hh24:mi:ss')), TRUNC(SYSDATE))
  INTO   ld_ret
  FROM   parameter
  WHERE  npid = 4;

  RETURN ld_ret;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN TRUNC(SYSDATE);
 END;

------------------------------------------------------------------------------------------------------------------------
 --Устанавливает дату последнего анализа данных
 PROCEDURE set_lastdchange(d DATE) IS
 BEGIN
  UPDATE parameter
  SET vvalue = TO_CHAR(NVL(d, SYSDATE), 'dd.mm.yyyy hh24:mi:ss')
  WHERE  npid = 4;
 END;

