 PROCEDURE read_srv_parameter(acur_t OUT common_pg.tcur) IS
 -- A.G.Kondakov created 01.08.2008
 -- используется в ASKUE TFormParamCommunicationServer::TreeRead
 BEGIN
  OPEN acur_t FOR
   SELECT min_delta, max_delta, clock_set, metering
