--Правка параметров ComServera
 PROCEDURE set_srv_parameter(an_min_delta NUMBER, an_max_delta NUMBER, av_clock_set VARCHAR2, av_metering VARCHAR2) IS
  cn_task_code        NUMBER DEFAULT 22;
 BEGIN
  UPDATE cs_profile
  SET min_delta = an_min_delta,
      max_delta = an_max_delta,
      clock_set = av_clock_set,
      metering = av_metering;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO cs_profile
               (min_delta, max_delta, clock_set, metering)
   VALUES      (an_min_delta, an_max_delta, av_clock_set, av_metering);
  END IF;

  fiscal_p(cn_task_code, 2, 'Изменены параметры сервера сбора данных');
 END;

