 --Квитирование тревог
 PROCEDURE receipting_p(an_mid NUMBER) IS
  cn_timecount CONSTANT NUMBER := 15;
  cn_task_code        NUMBER DEFAULT 46;
 BEGIN
  IF an_mid IS NULL THEN
   FOR i IN 1 .. cn_timecount LOOP
    BEGIN
     EXECUTE IMMEDIATE 'truncate table JOURNALLAST';

     fiscal_p(cn_task_code, 3, 'Выполнено квитирование всех сообщений системы.');
     COMMIT;
     EXIT;
    EXCEPTION
     WHEN OTHERS THEN
      IF i <> cn_timecount THEN
       SYS.DBMS_LOCK.sleep(1);
      ELSE
       raise_application_error(-20009,
        'Квитирование тревог не может быть проведено ввиду отсутствия возможности блокировки таблицы в течении ' || cn_timecount || ' сек.', TRUE);
      END IF;
    END;
   END LOOP;
  END IF;

  signal(6);
  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Квитирование обрыва связи
 PROCEDURE receipting_chan_p(an_mid NUMBER) IS
  ln_cn               NUMBER DEFAULT 0;
  cn_task_code        NUMBER DEFAULT 505;
 BEGIN
  UPDATE channels
  SET was_dead = NULL,
      is_dead = NULL
  WHERE  cid = an_mid;

  ln_cn := ln_cn + SQL%ROWCOUNT;

  UPDATE last_save
  SET state_cod = 0,
      state_descr = 'Возобновлен штатный режим',
      state_date = SYSDATE,
      nrepeaticcp = 0
  WHERE  mid = an_mid;

  ln_cn := ln_cn + SQL%ROWCOUNT;

  IF ln_cn > 0 THEN
   fiscal_p(cn_task_code, 3, 'Выполнено квитирование сигнала обрыва связи по каналу/точке "' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || '"');
   signal(6);
  END IF;

  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Квитирование предупреждения
 PROCEDURE receipting_warning_p(an_mid NUMBER) IS
  ln_cn               NUMBER DEFAULT 0;
  cn_task_code        NUMBER DEFAULT 505;
 BEGIN
  UPDATE lgstatus
  SET l1 = 1,
      l2 = 1,
      l3 = 1
  WHERE  mid = an_mid;

  ln_cn := ln_cn + SQL%ROWCOUNT;

  DELETE FROM check_status
  WHERE       nprocedure = an_mid;

  ln_cn := ln_cn + SQL%ROWCOUNT;

  IF ln_cn > 0 THEN
   fiscal_p(cn_task_code, 3,
    'Выполнено квитирование сигнала предупреждения по точке/процедуре "' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || '"');
   signal(6);
  END IF;

  COMMIT;
 END;

