 PROCEDURE sendemail(
 av_smtp_server VARCHAR2, av_from_userid VARCHAR2, av_to_userid VARCHAR2, av_subject VARCHAR2, av_body VARCHAR2, av_from_name VARCHAR2 := NULL,
 av_to_name VARCHAR2 := NULL, av_content_type VARCHAR2 := NULL
 ) IS
------------------------------
  c                   UTL_SMTP.connection;
  lv_from_domain      VARCHAR2(200) := SUBSTR(av_from_userid, INSTR(av_from_userid, '@') + 1);
------------------------------
 BEGIN
  --open connection
  c := UTL_SMTP.open_connection(av_smtp_server);
  UTL_SMTP.ehlo(c, lv_from_domain);
  UTL_SMTP.mail(c, av_from_userid);
  UTL_SMTP.rcpt(c, av_to_userid);
  UTL_SMTP.open_data(c);
  --header
  UTL_SMTP.write_raw_data(c, UTL_RAW.cast_to_raw('From: "' || NVL(av_from_name, av_from_userid) || '" <' || av_from_userid || '>'));
  UTL_SMTP.write_data(c, UTL_TCP.crlf);
  UTL_SMTP.write_raw_data(c, UTL_RAW.cast_to_raw('To: "' || NVL(av_to_name, av_to_userid) || '" <' || av_to_userid || '>'));
  UTL_SMTP.write_data(c, UTL_TCP.crlf);
  UTL_SMTP.write_raw_data(c, UTL_RAW.cast_to_raw('Subject: ' || av_subject));
  UTL_SMTP.write_data(c, UTL_TCP.crlf);
  UTL_SMTP.write_raw_data(c, UTL_RAW.cast_to_raw('Content-Type: ' || NVL(av_content_type, 'text/plain')));
  UTL_SMTP.write_data(c, UTL_TCP.crlf);
  UTL_SMTP.write_data(c, UTL_TCP.crlf);
  --body start
  UTL_SMTP.write_raw_data(c, UTL_RAW.cast_to_raw(av_body));
  --close connection
  UTL_SMTP.close_data(c);
  UTL_SMTP.quit(c);
 EXCEPTION
  WHEN UTL_SMTP.transient_error OR UTL_SMTP.permanent_error THEN
   UTL_SMTP.quit(c);
   raise_application_error(-20199, 'Error sending mail: ' || SQLERRM);
  WHEN OTHERS THEN
   raise_application_error(-20199, 'Error sending mail: ' || SQLERRM);
 END;

