 -- Сохранение групп мониторинга опроса для роли
 PROCEDURE set_monitoringgroups_p(an_id_role IN NUMBER, at_id_groups IN common_pg.tt_number) IS
 BEGIN
  SAVEPOINT monitoringgroups_sp;

  DELETE FROM role_groups
  WHERE       role_id = an_id_role;

  IF at_id_groups.COUNT > 0 AND at_id_groups(1) <> 0 THEN
   FOR i IN 1 .. at_id_groups.COUNT LOOP
    INSERT INTO role_groups
                (role_id, gid)
    VALUES      (an_id_role, at_id_groups(i));
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT monitoringgroups_sp;
   raise_application_error(-20001, 'admin_pg.set_monitoringgroups_p: Ошибка вставки канала. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

