-------------------------------------------------------------------------------------------
--построение дерева мониторов на корневом уровне
 PROCEDURE monitors_tree_route(an_role_id NUMBER,                                                                             --идентификатор роли пользователей
                                                 acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   1 havechild, t1.gid taskid, NAME taskname, NVL(sel, -1) accesstype, 1 catalog
   FROM     (SELECT 1 havechild, gid, NAME
             FROM   GROUPS g
             WHERE  PARENT IS NULL AND mid IS NULL AND EXISTS(SELECT *
                                                              FROM   GROUPS
                                                              WHERE  PARENT = g.gid AND mid IS NULL)) t1,
            (SELECT 1 sel, gid
             FROM   role_groups
             WHERE  role_id = an_role_id) t2
   WHERE    t1.gid = t2.gid(+)
   UNION ALL
   SELECT   0 havechild, t1.gid taskid, NAME taskname, NVL(sel, -1) accesstype, 1 catalog
   FROM     (SELECT 0 havechild, gid, NAME
             FROM   GROUPS g
             WHERE  PARENT IS NULL AND mid IS NULL AND NOT EXISTS(SELECT *
                                                                  FROM   GROUPS
                                                                  WHERE  PARENT = g.gid AND mid IS NULL)) t1,
            (SELECT 1 sel, gid
             FROM   role_groups
             WHERE  role_id = an_role_id) t2
   WHERE    t1.gid = t2.gid(+)
   ORDER BY 3;
 END;

-------------------------------------------------------------------------------------------
--построение дерева мониторов на корневом уровне
 PROCEDURE monitors_tree(an_role_id NUMBER,                                                                                   --идентификатор роли пользователей
                                           an_group_id NUMBER,                                                              --идентификатор группы пользователей
                                                              acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   1 havechild, t1.gid taskid, NAME taskname, NVL(sel, -1) accesstype, 1 catalog
   FROM     (SELECT 1 havechild, gid, NAME
             FROM   GROUPS g
             WHERE  PARENT = an_group_id AND mid IS NULL AND EXISTS(SELECT *
                                                                    FROM   GROUPS
                                                                    WHERE  PARENT = g.gid AND mid IS NULL)) t1,
            (SELECT 1 sel, gid
             FROM   role_groups
             WHERE  role_id = an_role_id) t2
   WHERE    t1.gid = t2.gid(+)
   UNION ALL
   SELECT   0 havechild, t1.gid taskid, NAME taskname, NVL(sel, -1) accesstype, 1 catalog
   FROM     (SELECT 0 havechild, gid, NAME
             FROM   GROUPS g
             WHERE  PARENT = an_group_id AND mid IS NULL AND NOT EXISTS(SELECT *
                                                                        FROM   GROUPS
                                                                        WHERE  PARENT = g.gid AND mid IS NULL)) t1,
            (SELECT 1 sel, gid
             FROM   role_groups
             WHERE  role_id = an_role_id) t2
   WHERE    t1.gid = t2.gid(+)
   ORDER BY 3;
 END;

-------------------------------------------------------------------------------------------
--построение дерева задач на корневом уровне
 PROCEDURE tasks_tree_route(an_group_id NUMBER,                                                                                           --идентификатор группы
                                               acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   t.NAME taskname, 1 havechild, t.task_id taskid, '' vfname, NVL(r.naccess_type, -1) accesstype, DECODE(NVL(t.task_cod, 0), 0, 0, 1) catalog
   FROM     tasks t,
            (SELECT task_id, nacc naccess_type
             FROM   role_task
             WHERE  role_id = an_group_id) r
   WHERE    t.task_id = r.task_id(+) AND t.PARENT IS NULL AND EXISTS(SELECT *
                                                                     FROM   tasks
                                                                     WHERE  PARENT = t.task_id)
   UNION ALL
   SELECT   t.NAME taskname, 0 havechild, t.task_id taskid, '' vfname, NVL(r.naccess_type, -1) accesstype, DECODE(NVL(t.task_cod, 0), 0, 0, 1) catalog
   FROM     tasks t,
            (SELECT task_id, nacc naccess_type
             FROM   role_task
             WHERE  role_id = an_group_id) r
   WHERE    t.task_id = r.task_id(+) AND t.PARENT IS NULL AND NOT EXISTS(SELECT *
                                                                         FROM   tasks
                                                                         WHERE  PARENT = t.task_id)
   ORDER BY catalog, taskname;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE tasks_tree(an_group_id NUMBER,                                                                                   --идентификатор группы пользователей
                                         an_task_id NUMBER,                                                                               --идентификатор задачи
                                                           acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   t.NAME taskname, 1 havechild, t.task_id taskid, '' vfname, NVL(r.naccess_type, -1) accesstype, DECODE(NVL(t.task_cod, 0), 0, 0, 1) catalog
   FROM     tasks t,
            (SELECT task_id, nacc naccess_type
             FROM   role_task
             WHERE  role_id = an_group_id) r
   WHERE    t.task_id = r.task_id(+) AND t.PARENT = an_task_id AND EXISTS(SELECT *
                                                                          FROM   tasks
                                                                          WHERE  PARENT = t.task_id)
   UNION ALL
   SELECT   t.NAME taskname, 0 havechild, t.task_id taskid, '' vfname, NVL(r.naccess_type, -1) accesstype, DECODE(NVL(t.task_cod, 0), 0, 0, 1) catalog
   FROM     tasks t,
            (SELECT task_id, nacc naccess_type
             FROM   role_task
             WHERE  role_id = an_group_id) r
   WHERE    t.task_id = r.task_id(+) AND t.PARENT = an_task_id AND NOT EXISTS(SELECT *
                                                                              FROM   tasks
                                                                              WHERE  PARENT = t.task_id)
   ORDER BY catalog, taskname;
 END;

