------------------------------------------------------------------------------------------------------------------------
 --установка прав на задачи роли
 PROCEDURE grants_tasks(an_access_type NUMBER,                                                                                  -- -1-запрет, 0-чтение, 1-запись
                                              an_role_id NUMBER, an_task_id NUMBER) IS
 BEGIN
  IF an_access_type = -1 THEN
   DELETE FROM role_task
   WHERE       role_id = an_role_id AND task_id = an_task_id;
  ELSE
   UPDATE role_task
   SET nacc = an_access_type
   WHERE  role_id = an_role_id AND task_id = an_task_id;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO role_task
                (role_id, task_id, nacc)
    VALUES      (an_role_id, an_task_id, an_access_type);
   END IF;
  END IF;
 END;

--------------------------------------------------------------------------------------------------------
--установка прав на группы мониторинга опроса роли
 PROCEDURE grants_mon(an_access_type NUMBER,                                                                            -- -1-доступ запрещен, 1-доступ разрешен
                                            an_role_id NUMBER, an_gid NUMBER) IS
 BEGIN
  IF an_access_type = -1 THEN
   DELETE FROM role_groups
   WHERE       role_id = an_role_id AND gid = an_gid;
  ELSE
   BEGIN
    INSERT INTO role_groups
                (role_id, gid)
    VALUES      (an_role_id, an_gid);
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     NULL;
    WHEN OTHERS THEN
     RAISE;
   END;
  END IF;
 END;

--------------------------------------------------------------------------------------------------------
 PROCEDURE createorauser_p(av_user VARCHAR2, av_pass VARCHAR2) IS
  lv_user             VARCHAR2(256) DEFAULT UPPER(TRIM(av_user));
  lv_pass             VARCHAR2(256) DEFAULT UPPER(TRIM(av_pass));
 BEGIN
  IF lv_user IS NULL THEN
   raise_application_error(-20005, 'adminnew_pg.insuser_p: Введите имя пользователя. ');
  END IF;

  IF TRIM(lv_pass) IS NULL THEN
   raise_application_error(-20001, 'adminnew_pg.insuser_p: пустой пароль недопустим. ');
  END IF;

  IF lv_user IN('RYDA', 'SYS', 'SYSTEM') THEN
   raise_application_error(-20005,
    'adminnew_pg.deluser_p: Пользователь ' || lv_user || ' является системным пользователем и не могут быть пользователями системы. ');
  END IF;

  EXECUTE IMMEDIATE    'CREATE USER '
                    || lv_user
                    || ' IDENTIFIED BY '
                    || lv_pass
                    || ' DEFAULT TABLESPACE '
                    || lv_deftablespace
                    || ' TEMPORARY TABLESPACE '
                    || lv_tmptablespace;

  EXECUTE IMMEDIATE 'GRANT ' || cv_role || ' TO ' || lv_user;

  EXECUTE IMMEDIATE 'ALTER USER ' || lv_user || ' DEFAULT ROLE ' || cv_role;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'adminnew_pg.createorauser_p: Ошибка при создании пользователя Oracle. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

--------------------------------------------------------------------------------------------------------

 --процедура создания пользователя
 PROCEDURE insuser_p(
 av_user VARCHAR2,                                                                                                                     --имя пользователя Oracle
                  av_username VARCHAR2,                                                                                                       --имя пользователя
                                       an_group NUMBER,                                                                                    --доступ пользователя
                                                       an_admin NUMBER,                                                                 --признак администратора
                                                                       av_password VARCHAR2,                                               --пароль пользователя
                                                                                            an_lock NUMBER,                    --признак блокировки пользователя
 an_user OUT NUMBER                                                                                                                 --идентификатор пользователя
 ) IS
  ln_found            NUMBER;
  lv_user             VARCHAR2(256) DEFAULT UPPER(TRIM(av_user));
 BEGIN
  IF lv_user IS NULL OR TRIM(av_username) IS NULL THEN
   raise_application_error(-20005, 'adminnew_pg.insuser_p: Введите имя пользователя. ');
  END IF;

  IF TRIM(av_password) IS NULL THEN
   raise_application_error(-20001, 'adminnew_pg.insuser_p: пустой пароль недопустим. ');
  END IF;

  IF lv_user IN('RYDA', 'SYS', 'SYSTEM') THEN
   raise_application_error(-20005,
    'adminnew_pg.deluser_p: Пользователь ' || lv_user || ' является системным пользователем и не могут быть пользователями системы. ');
  END IF;

  SELECT COUNT(*)
  INTO   ln_found
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   all_users
                WHERE  username = lv_user);

  IF util_pg.get_customer_id = 1 THEN                                                                                                                  --Для ХЭС
   IF ln_found = 1 THEN
    SELECT users_seq.NEXTVAL
    INTO   an_user
    FROM   DUAL;

    INSERT INTO users
                (user_id, usr, NAME, ADMIN, role_id, nlock)
    VALUES      (an_user, lv_user, av_username, DECODE(an_admin, 1, '*'), an_group, an_lock);

    COMMIT;
   ELSE
    raise_application_error(-20001, 'adminnew_pg.insuser_p: Пользователь с таким именем не существует как пользователь ORACLE. ');
   END IF;
  ELSE                                                                                                                                                --Для Всех
   IF ln_found = 1 THEN
    raise_application_error(-20001, 'adminnew_pg.insuser_p: Пользователь с таким именем уже существует как пользователь ORACLE. ');
   END IF;

   createorauser_p(lv_user, av_password);

   --вставка пользователя
   SELECT users_seq.NEXTVAL
   INTO   an_user
   FROM   DUAL;

   INSERT INTO users
               (user_id, usr, NAME, ADMIN, role_id, nlock)
   VALUES      (an_user, lv_user, av_username, DECODE(an_admin, 1, '*'), an_group, an_lock);

   IF an_lock = 1 THEN
    EXECUTE IMMEDIATE 'ALTER USER ' || lv_user || ' ACCOUNT LOCK';
   ELSE
    EXECUTE IMMEDIATE 'ALTER USER ' || lv_user || ' ACCOUNT UNLOCK';
   END IF;
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'adminnew_pg.insuser_p: Ошибка при создании пользователя системы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;                                                                                                                                                --insuser_p

------------------------------------------------------------------------------------------------------------------------
 --процедура изменения пользователя
 PROCEDURE upduser_p(
 an_user NUMBER,                                                                                                                    --идентификатор пользователя
                av_username VARCHAR2,                                                                                                         --имя пользователя
                                     an_group NUMBER,                                                                                      --доступ пользователя
                                                     an_admin NUMBER,                                                                   --признак администратора
                                                                     av_password VARCHAR2,                                                 --пароль пользователя
                                                                                          an_lock NUMBER                       --признак блокировки пользователя
 ) IS
  lv_user             VARCHAR2(256);
 BEGIN
  SELECT UPPER(usr)
  INTO   lv_user
  FROM   users
  WHERE  user_id = an_user;

  --изменение пользователя
  UPDATE users
  SET NAME = av_username,
      role_id = an_group,
      ADMIN = DECODE(an_admin, 1, '*'),
      nlock = an_lock
  WHERE  user_id = an_user;

  IF TRIM(av_password) IS NOT NULL THEN
   changepassword(lv_user, av_password);
  END IF;

  IF util_pg.get_customer_id <> 1 THEN                                                                                                                 --Для ХЭС
   IF an_lock = 1 THEN
    EXECUTE IMMEDIATE 'ALTER USER ' || lv_user || ' ACCOUNT LOCK';
   ELSE
    EXECUTE IMMEDIATE 'ALTER USER ' || lv_user || ' ACCOUNT UNLOCK';
   END IF;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'adminnew_pg.upduser_p: Ошибка при изменении пользователя системы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;                                                                                                                                                --upduser_p

------------------------------------------------------------------------------------------------------------------------
--процедура удаления пользователя
 PROCEDURE deluser_p(an_user NUMBER) IS
  lv_user             VARCHAR2(64);
 BEGIN
  SELECT UPPER(usr)
  INTO   lv_user
  FROM   users
  WHERE  user_id = an_user;

  IF lv_user IN('RYDA', 'SYS', 'SYSTEM') THEN
   raise_application_error(-20005, 'adminnew_pg.deluser_p: Пользователь ' || lv_user || ' является системным пользователем и не подлежит удалению. ');
  END IF;

  --удаление пользователя
  DELETE FROM users
  WHERE       user_id = an_user;

  COMMIT;

  --удаление пользователя Oracle
  EXECUTE IMMEDIATE 'DROP USER ' || lv_user;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'adminnew_pg.deluser_p: Ошибка при удалении пользователя системы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;                                                                                                                                                --upduser_p

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE changepassword(an_user NUMBER, av_pass VARCHAR2) IS
  lv_user             VARCHAR2(256);
 BEGIN
  SELECT MAX(usr)
  INTO   lv_user
  FROM   users
  WHERE  user_id = an_user;

  IF lv_user IS NULL THEN
   raise_application_error(-20001, 'Пользователь не найден.');
  END IF;

  changepassword(lv_user, av_pass);
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE changepassword(av_user VARCHAR2, av_pass VARCHAR2) IS
  lv_user             VARCHAR2(256) DEFAULT TRIM(UPPER(av_user));
  ln_user             NUMBER;
 BEGIN
  IF av_pass IS NULL THEN
   raise_application_error(-20001, 'Пароль не может быть пустым.');
  END IF;

  IF lv_user IN('RYDA', 'SYS', 'SYSTEM') THEN
   raise_application_error(-20005,
    'adminnew_pg.deluser_p: Пользователь ' || lv_user || ' является системным пользователем и не могут быть пользователями системы. ');
  END IF;

  SELECT MAX(usr)
  INTO   lv_user
  FROM   users
  WHERE  UPPER(usr) = lv_user;

  IF lv_user IS NULL THEN
   raise_application_error(-20001, 'Пользователь не найден.');
  END IF;

  BEGIN
   EXECUTE IMMEDIATE 'ALTER USER ' || lv_user || ' IDENTIFIED BY ' || av_pass;
  EXCEPTION
   WHEN OTHERS THEN
    IF SQLCODE = -1918 AND util_pg.get_customer_id != 1 THEN                                                                                       --не Для ХЭС
     createorauser_p(lv_user, av_pass);
    ELSE
     RAISE;
    END IF;
  END;

  IF util_pg.nadmintype = 0 THEN
   SELECT MAX(user_id)
   INTO   ln_user
   FROM   users
   WHERE  UPPER(usr) = lv_user;

   IF ln_user IS NOT NULL THEN
    UPDATE userpass
    SET PASSWORD = av_pass
    WHERE  user_id = ln_user;

    IF SQL%ROWCOUNT = 0 THEN
     INSERT INTO userpass
                 (user_id, PASSWORD)
     VALUES      (ln_user, av_pass);
    END IF;
   END IF;

   COMMIT;
  END IF;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE changepassword(av_pass VARCHAR2) IS
  lv_user             VARCHAR2(256);
 BEGIN
  changepassword(USER, av_pass);
 END;

