---------------------------------------------------------------------------------------------------
 PROCEDURE grant_particular IS
 BEGIN
  EXECUTE IMMEDIATE 'GRANT INSERT ON forms_ex TO ' || cv_role;

  EXECUTE IMMEDIATE 'GRANT UPDATE ON forms_ex TO ' || cv_role;

  BEGIN
   EXECUTE IMMEDIATE 'grant update on rmakets to ' || cv_role;
  EXCEPTION
   WHEN OTHERS THEN
    NULL;
  END;
 END;

---------------------------------------------------------------------------------------------------
 PROCEDURE grant_to_askue_work IS
  cv_admpack CONSTANT VARCHAR2(128) := 'ADMIN_PG';
 BEGIN
  BEGIN
   EXECUTE IMMEDIATE 'CREATE ROLE ' || cv_role;
  EXCEPTION
   WHEN OTHERS THEN
    NULL;
  END;

  EXECUTE IMMEDIATE 'GRANT CREATE SESSION TO ' || cv_role;

  EXECUTE IMMEDIATE 'GRANT ALTER SESSION TO ' || cv_role;

  grant_particular;

  FOR lc IN (SELECT 'grant select on ' || table_name || ' to ' || cv_role c
             FROM   user_tables
             WHERE  table_name NOT IN('USERPASS')
             UNION ALL
             SELECT 'grant select on ' || view_name || ' to ' || cv_role c
             FROM   user_views
             UNION ALL
             SELECT 'grant execute on ' || object_name || ' to ' || cv_role c
             FROM   user_objects
             WHERE  object_type = 'PROCEDURE'
             UNION ALL
             SELECT 'grant execute on ' || object_name || ' to ' || cv_role c
             FROM   user_objects
             WHERE  object_type = 'FUNCTION'
             UNION ALL
             SELECT 'grant execute on ' || object_name || ' to ' || cv_role c
             FROM   user_objects
             WHERE  object_type = 'PACKAGE' AND object_name NOT IN(cv_admpack)) LOOP
   BEGIN
    EXECUTE IMMEDIATE lc.c;
   EXCEPTION
    WHEN OTHERS THEN
     NULL;
   END;
  END LOOP;
 END;

---------------------------------------------------------------------------------------------------
 PROCEDURE get_sysdate(acur_t OUT common_pg.tcur) IS
 -- A.G.Kondakov created 29.07.2008
