/*Сигнал
an_signal =
 1 - BILL_C
 2 - HALFHOUR_C
 3 - PROFILE_C
 4 - CURR_POWER_C
 5 - FISCAL_C
 6 - JOURNAL_C
*/
 PROCEDURE signal(an_signal NUMBER) IS
  lv_signal           VARCHAR2(32);
 BEGIN
  IF an_signal = 1 THEN
   lv_signal := 'BILL';
  ELSIF an_signal = 2 THEN
   lv_signal := 'HALFHOUR';
  ELSIF an_signal = 3 THEN
   lv_signal := 'PROFILE';
  ELSIF an_signal = 4 THEN
   lv_signal := 'CURR_POWER';
  ELSIF an_signal = 5 THEN
   lv_signal := 'FISCAL';
  ELSIF an_signal = 6 THEN
   lv_signal := 'JOURNAL';
  ELSIF an_signal = 7 THEN
   lv_signal := 'CHANNELS';
  END IF;

  IF lv_signal IS NOT NULL THEN
   SYS.DBMS_ALERT.signal(lv_signal, lv_signal);
  END IF;
 END;

