 -- Используется службой единого времени
 PROCEDURE set_synhronize_state(av_name VARCHAR2, av_ipaddr VARCHAR2, an_precision NUMBER, an_timedifference NUMBER, an_messagetype NUMBER) IS
  lv_name             VARCHAR2(256) DEFAULT TRIM(NVL(av_name, av_ipaddr));
  lv_shortname        VARCHAR2(256) DEFAULT TRIM(av_ipaddr);
  ln_mid              NUMBER;
  ln_ret              NUMBER;
  lv_message          VARCHAR2(256);
  ln_state_cod        NUMBER DEFAULT -1;
 BEGIN
  IF an_messagetype = 0 THEN
   lv_message := 'ПЕВ: Норма.';
  ELSIF an_messagetype = 1 THEN
   lv_message := 'ПЕВ: Превышение границы. Граница=' || an_precision || ' Факт=' || an_timedifference;
  ELSIF an_messagetype = 2 THEN
   lv_message := 'ПЕВ: Заданный узел недоступен.';
  ELSE
   lv_message := 'ПЕВ: Фатальная ошибка.';
  END IF;

  SELECT MAX(mid)
  INTO   ln_mid
  FROM   points
  WHERE  PARENT = util_pg.cn_ctsmid AND UPPER(NAME) = UPPER(lv_name);

  IF ln_mid IS NULL THEN
   SELECT points_seq.NEXTVAL
   INTO   ln_mid
   FROM   DUAL;

   INSERT INTO points
               (mid, PARENT, cod, ind, NAME, short_name, implement_date, tag, npoint)
   VALUES      (ln_mid, util_pg.cn_ctsmid, NULL, 2, lv_name, lv_shortname, SYSDATE, NULL, NULL);
  ELSE
   UPDATE points
   SET short_name = lv_shortname
   WHERE  mid = ln_mid AND NAME <> lv_name;

   SELECT NVL(MAX(state_cod), -1)
   INTO   ln_state_cod
   FROM   last_save
   WHERE  mid = ln_mid;
  END IF;

  IF ln_state_cod = -1 THEN
   ins_last_save(ln_mid, lv_message);
  END IF;

  IF ln_state_cod <> an_messagetype THEN                                                                                                          --Если мигнуло
   ln_ret := ins_journal_p(SYSDATE, ln_mid, an_messagetype, lv_message, NULL, an_messagetype);
  END IF;

  UPDATE last_save
  SET clock = DECODE(an_messagetype, 0, an_timedifference, 1, an_timedifference, 0),
      state_cod = an_messagetype,
      state_descr = lv_message,
      state_date = SYSDATE,
      trial = DECODE(an_messagetype, 0, SYSDATE, trial)
  WHERE  mid = ln_mid;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'admin_pg.set_synhronize_state: ' || SQLERRM);
 END;

