 -- Используется службой диагностики
 PROCEDURE set_diag_state(
 av_source VARCHAR2, av_ip_addr VARCHAR2, ad_time_stamp DATE, ad_next_time_stamp DATE, av_message VARCHAR2, an_state NUMBER, av_state_name VARCHAR2,
 an_error NUMBER, av_error_name VARCHAR2, an_claster VARCHAR2 DEFAULT NULL, an_usel VARCHAR2 DEFAULT NULL
 ) IS
  lv_name             VARCHAR2(256) DEFAULT TRIM(NVL(av_source, av_ip_addr));
  lv_shortname        VARCHAR2(256) DEFAULT TRIM(av_ip_addr);
  ln_mid              NUMBER;
  ln_ret              NUMBER;
  lv_message          VARCHAR2(256);
  ln_state_cod        NUMBER DEFAULT -1;
  ln_state_date       DATE;
  lv_claster          VARCHAR2(256) DEFAULT TRIM(an_claster);
  lv_usel             VARCHAR2(256) DEFAULT TRIM(an_usel);
  lv_name_cl          VARCHAR2(256) DEFAULT NULL;
  lv_mid              NUMBER DEFAULT 0;
 BEGIN
  -- кластер
  IF an_claster IS NOT NULL THEN
   SELECT MAX(mid)
   INTO   ln_mid
   FROM   points
   WHERE  PARENT = util_pg.cn_clmid AND UPPER(NAME) = UPPER(lv_usel);

   IF ln_mid IS NULL THEN
    SELECT points_seq.NEXTVAL
    INTO   ln_mid
    FROM   DUAL;

    INSERT INTO points
                (mid, PARENT, NAME, short_name)
    VALUES      (ln_mid, util_pg.cn_clmid, lv_usel, lv_usel);
   ELSE
    SELECT MAX(s.mid)
    INTO   lv_mid
    FROM   (SELECT MAX(s.state_date) max_date
            FROM   last_save s, points p
            WHERE  p.PARENT = util_pg.cn_clmid AND p.mid = s.mid) d,
           last_save s,
           points p
    WHERE  s.state_date = d.max_date AND p.PARENT = util_pg.cn_clmid AND p.mid = s.mid;
   END IF;

   IF lv_mid <> ln_mid THEN
    ins_last_save(ln_mid, lv_message);

    UPDATE last_save
    SET state_date = ad_time_stamp,
        state_descr = 'Кластер был изменен. Текущий кластер: ' || lv_claster || '(' || lv_usel || ')',
        state_cod = 1
    WHERE  mid = ln_mid;

    ins_last_save(util_pg.cn_clmid, lv_message);

    UPDATE last_save
    SET state_date = ad_time_stamp,
        state_descr = 'Текущий кластер: ' || lv_claster || '(' || lv_usel || ')',
        state_cod = 1,
        luck = ad_time_stamp + 1 / 17280,
        trial = ad_time_stamp
    WHERE  mid = util_pg.cn_clmid;

    ln_ret := ins_journal_p(ad_time_stamp, ln_mid, 0, 'Кластер был изменен. Текущий кластер: ' || lv_claster || '(' || lv_usel || ')', NULL, NULL);
   ELSE
    UPDATE last_save
    SET state_date = ad_time_stamp,
        luck = ad_time_stamp + 1 / 17280,
        trial = ad_time_stamp
    WHERE  mid = util_pg.cn_clmid;
   END IF;
  END IF;

  IF av_message IS NOT NULL THEN
   lv_message := av_message || ': ';
  END IF;

  IF an_state = 0 THEN
   lv_message := 'СД: ' || lv_message || 'Неопределённое состояние.';
  ELSIF an_state = 1 THEN
   lv_message := 'СД: ' || lv_message || 'Штатная работа.';
  ELSIF an_state = 2 THEN
   lv_message := 'СД: ' || lv_message || 'Подсистема приостановлена.';
  ELSIF an_state = 3 THEN
   lv_message := 'СД: ' || lv_message || 'Критическая ошибка.';
  ELSIF an_state > 10000 THEN
   lv_message := 'СД: ' || lv_message || av_state_name;
  END IF;

  SELECT MAX(mid)
  INTO   ln_mid
  FROM   points
  WHERE  PARENT = util_pg.cn_dsmid AND UPPER(NAME) = UPPER(lv_name);

  IF ln_mid IS NULL THEN
   SELECT points_seq.NEXTVAL
   INTO   ln_mid
   FROM   DUAL;

   INSERT INTO points
               (mid, PARENT, cod, ind, NAME, short_name, implement_date, tag, npoint)
   VALUES      (ln_mid, util_pg.cn_dsmid, NULL, 2, lv_name, lv_shortname, SYSDATE, NULL, NULL);
  ELSE
   UPDATE points
   SET short_name = lv_shortname
   WHERE  mid = ln_mid AND NAME <> lv_name;

   SELECT NVL(MAX(state_cod), -1)
   INTO   ln_state_cod
   FROM   last_save
   WHERE  mid = ln_mid;
  END IF;

  IF ln_state_cod = -1 THEN
   ins_last_save(ln_mid, lv_message);
  END IF;

  IF ln_state_cod <> an_state THEN                                                                                                                --Если мигнуло
   ln_ret := ins_journal_p(ad_time_stamp, ln_mid, an_state, lv_message, NULL, NULL);
  END IF;

  UPDATE last_save
  SET state_cod = an_state,
      state_descr = av_state_name,
      state_date = ad_time_stamp,
      luck = ad_next_time_stamp,
      trial = DECODE(an_state, 1, ad_time_stamp, trial)
  WHERE  mid = ln_mid;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'admin_pg.set_diag_state: ' || SQLERRM);
 END;

