 -- Возвращает типы разрешений для деревьев
 PROCEDURE getrighttype_p(an_treetype NUMBER, ret_t OUT common_pg.tcur) IS
 BEGIN
  OPEN ret_t FOR
   SELECT 1 nacc, 'Ручной ввод (РВ)' vacc, 'РВ' vaccshort
   FROM   DUAL
   UNION ALL
   SELECT 2 nacc, 'Редактирование (Ред)' vacc, 'Ред' vaccshort
   FROM   DUAL
   UNION ALL
   SELECT 3 nacc, 'Мониторинг опроса (Мон)' vacc, 'Мон' vaccshort
   FROM   DUAL
   WHERE  an_treetype = 2;
 END;

------------------------------------------------------------------------------------------------------------------------------

 -- Возвращает основной курсор для модуля получения прав
 PROCEDURE getrightinfo_p(an_role NUMBER, an_treetype NUMBER, an_sort NUMBER, ret_t OUT common_pg.tcur) IS
  cn_colcount CONSTANT NUMBER := 4;
  ln_role             NUMBER DEFAULT NVL(an_role, 0);
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF an_treetype = 2 THEN                                                                                                                              --группы
   lv_sql :=
           'select 1 ntype,p.name vname,r.nacc,r.mid id,' || ln_role || ' rgid from points p,ROLEPOINT r where r.role_id=' || ln_role || ' and r.mid=p.mid(+) ';
  ELSE
   lv_sql :=
           'select 2 ntype,p.name vname,r.nacc,r.gid id,' || ln_role || ' rgid from groups p,ROLEGROUP r where r.role_id=' || ln_role || ' and r.gid=p.gid(+) ';
  END IF;

  --Сортировка
  lv_sql := lv_sql || ' ORDER BY ';

  IF ABS(an_sort) > 0 AND ABS(an_sort) <= cn_colcount THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' desc';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1,2,4';

  OPEN ret_t FOR lv_sql;
 END;

----------------------------------------------------------------
  -- Сохранение
 PROCEDURE updright_p(an_role NUMBER, an_treetype NUMBER, an_oldid NUMBER, an_id NUMBER, an_acc NUMBER) IS
 BEGIN
  IF an_treetype = 2 THEN                                                                                                                              --группы
   UPDATE rolegroup
   SET gid = an_id,
       nacc = an_acc
   WHERE  role_id = an_role AND gid = an_oldid;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO rolegroup
                (role_id, gid, nacc)
    VALUES      (an_role, an_id, an_acc);
   END IF;
  ELSE
   UPDATE rolepoint
   SET mid = an_id,
       nacc = an_acc
   WHERE  role_id = an_role AND mid = an_oldid;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO rolepoint
                (role_id, mid, nacc)
    VALUES      (an_role, an_id, an_acc);
   END IF;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'ADMIN_PG.updright_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

----------------------------------------------------------------
   -- Удаление
 PROCEDURE delright_p(an_role NUMBER, an_treetype NUMBER, an_id NUMBER) IS
 BEGIN
  IF an_treetype = 2 THEN                                                                                                                              --группы
   DELETE FROM rolegroup
   WHERE       role_id = an_role AND gid = an_id;
  ELSE
   DELETE FROM rolepoint
   WHERE       role_id = an_role AND mid = an_id;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'ADMIN_PG.delright_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
