PACKAGE BODY adminadd_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет по новой схеме администрированию АСКУЭ
  -- дата создания 21/05/2013 Сечин А.А.
----------------------------------------------------------------
--Проверка прав на ввод данных по точке учета, группе учета (an_treetype - 1 точки, 2 - группы)
/* an_acc - битовая маска прав 0 это разрешен просмотр;
   1 бит - ручной ввод
   2 бит - редактирование  */
 PROCEDURE check_right(an_id NUMBER, an_parent NUMBER, an_treetype NUMBER, an_acc NUMBER) IS
  lv_err              VARCHAR2(512)
                       DEFAULT 'В доступе отказано. Ид1=' || an_id || '; Ид2=' || an_parent || '; Ур.дост=' || an_acc || '; Тип объекта=' || an_treetype || ';';
  ln_ret              NUMBER;
  ln_role             NUMBER;
  ln_admin            NUMBER;
  ln_lock             NUMBER;
  lv_sqltmp           VARCHAR2(4000);
  lv_sql1             VARCHAR2(4000);
  lv_sql2             VARCHAR2(4000);
 BEGIN
  IF USER = 'RYDA' OR util_pg.nhorizadmin = 0 THEN
   RETURN;
  END IF;

  SELECT NVL(MAX(nlock), 1), MAX(DECODE(ADMIN, '*', 1, '1', 1, 0)) nadmin, NVL(MAX(role_id), 0)
  INTO   ln_lock, ln_admin, ln_role
  FROM   users
  WHERE  usr = USER;

  IF ln_lock = 1 THEN                                                                                    --Для заблокированных (или отсутствующих) всегда нельзя
   raise_application_error(-20005, lv_err || ' Шаг=1;');
  END IF;

  IF ln_admin = 1 THEN                                                                                                        --Для администраторов всегда можно
   RETURN;
  END IF;

  IF an_treetype = 1 THEN
   /* --Я думаю второй вариант запроса проще чем этот
   SELECT COUNT(*) INTO   ln_ret FROM   DUAL WHERE  EXISTS(SELECT mid FROM points WHERE mid=:3 CONNECT BY PRIOR mid = PARENT START WITH mid IN(SELECT mid FROM rolepoint WHERE role_id=:1 AND nacc>=:2));*/
   lv_sqltmp := 'SELECT COUNT(*) FROM DUAL WHERE EXISTS(SELECT * FROM rolepoint WHERE role_id=' || ln_role || ' AND BITAND(nacc,' || an_acc;
   lv_sql1 := lv_sqltmp || ')>0 AND mid IN (SELECT mid FROM points where level>1 CONNECT BY PRIOR PARENT=mid START WITH mid=:1))';
   lv_sql2 := lv_sqltmp || ')>0 AND mid IN (SELECT mid FROM points CONNECT BY PRIOR PARENT=mid START WITH mid=:1))';

   IF BITAND(an_acc, 1) = 1 AND NVL(an_id, 0) <> 0 THEN                        --Если проверка ручного ввода по точке то разрешаем давать права на группы точек
    lv_sqltmp :=
        ' OR EXISTS (SELECT * FROM rolegroup WHERE role_id='
     || ln_role
     || ' AND BITAND(nacc,'
     || an_acc
     || ')>0 AND gid IN (SELECT gid FROM groups CONNECT BY PRIOR PARENT=gid START WITH mid='
     || an_id
     || '))';
    lv_sql1 := lv_sql1 || lv_sqltmp;
    lv_sql2 := lv_sql2 || lv_sqltmp;
   END IF;
  ELSIF an_treetype = 2 THEN
   lv_sqltmp := 'SELECT COUNT(*) FROM DUAL WHERE EXISTS(SELECT * FROM rolegroup WHERE role_id=' || ln_role || ' AND BITAND(nacc,' || an_acc;
   lv_sql1 := lv_sqltmp || ')>0 AND gid IN (SELECT gid FROM groups where level>1 CONNECT BY PRIOR PARENT=gid START WITH gid=:1))';
   lv_sql2 := lv_sqltmp || ')>0 AND gid IN (SELECT gid FROM groups CONNECT BY PRIOR PARENT=gid START WITH gid=:1))';
  ELSE
   raise_application_error(-20005, 'Тип не поддерживается. ' || lv_err || ' Шаг=2;');
  END IF;

  IF NVL(an_id, 0) <> 0 THEN                                                                                                            --Проверка по ид объекта
   EXECUTE IMMEDIATE lv_sql1
   INTO              ln_ret
   USING             an_id;

   IF ln_ret = 0 THEN
    raise_application_error(-20005, lv_err || ' Шаг=3;');
   END IF;
  END IF;

  IF NVL(an_parent, 0) <> 0 THEN                                                                                                       --Проверка по ид родителя
   EXECUTE IMMEDIATE lv_sql2
   INTO              ln_ret
   USING             an_parent;

   IF ln_ret = 0 THEN
    raise_application_error(-20005, lv_err || ' Шаг=4;');
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 FUNCTION getall_accmid
  RETURN numarray IS
  lt_accmid           numarray := numarray();
 BEGIN
  IF util_pg.chknhorizadmin = 0 THEN
   SELECT mid
   BULK COLLECT INTO lt_accmid
   FROM   points;
  ELSE
   SELECT DISTINCT mid
   BULK COLLECT INTO lt_accmid
   FROM            points
   CONNECT BY      PRIOR mid = PARENT
   START WITH      mid IN(SELECT mid
                          FROM   rolepoint rp
                          WHERE  rp.role_id = util_pg.roleid_f);
  END IF;

  RETURN lt_accmid;
 END;

------------------------------------------------------------------------------------------------------------------------------
 FUNCTION check_accread(an_id NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  IF util_pg.chknhorizadmin = 0 THEN
   RETURN 1;
  ELSIF an_id is NULL THEN
		 RETURN 0;
  ELSE
   SELECT COUNT(*)
   INTO   ln_ret
   FROM   DUAL
   WHERE  EXISTS(SELECT mid
                 FROM   rolepoint rp
                 WHERE  rp.role_id = util_pg.roleid_f AND mid IN(SELECT     mid
                                                                 FROM       points
                                                                 CONNECT BY PRIOR PARENT = mid
                                                                 START WITH mid = an_id));
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------------
 FUNCTION getfirst_accmid(an_type NUMBER, an_startmid NUMBER)
  RETURN numarray IS
  ln_chknhorizadmin   NUMBER := util_pg.chknhorizadmin;
  ln_role             NUMBER := util_pg.roleid_f;
  lt_accmid           numarray := numarray();
  ln_tmp              NUMBER;
 BEGIN
  IF ln_chknhorizadmin = 0 THEN                                                                                              --Если нет проверки вернем вершину
   SELECT t.mid
   BULK COLLECT INTO lt_accmid
   FROM   (SELECT   an_type mid
           FROM     DUAL
           WHERE    an_startmid IS NULL AND an_type IS NOT NULL
           UNION
           SELECT   mid
           FROM     points
           WHERE    PARENT = an_startmid
           UNION
           SELECT   mid
           FROM     points
           WHERE    an_type IS NULL AND an_startmid IS NULL AND PARENT IS NULL
           ORDER BY 1) t;
  ELSE
    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT     mid
                  FROM       points
                  WHERE      mid IN(SELECT mid
                                    FROM   rolepoint
                                    WHERE  role_id = ln_role)
                  CONNECT BY PRIOR PARENT = mid
                  START WITH mid = NVL(an_startmid, an_type));

    IF ln_tmp > 0 THEN                                                            --Если даны права выше уровня чем вершина типа объектов то стартуем с вершины
     SELECT t.mid
     BULK COLLECT INTO lt_accmid
     FROM   (SELECT   an_type mid
             FROM     DUAL
             WHERE    an_startmid IS NULL
             UNION
             SELECT   mid
             FROM     points
             WHERE    PARENT = an_startmid
             ORDER BY 1) t;
    ELSE                                                                           --иначе посеиваем rolepoint убирая детей тех элементов, на которые даны права
     FOR lc IN (SELECT mid
                FROM   rolepoint
                WHERE  role_id = ln_role AND (mid IN(SELECT     mid
                                                    FROM       points
                                                    CONNECT BY PRIOR mid = PARENT
                                                    START WITH mid = NVL(an_startmid, an_type)) OR (an_type IS NULL AND an_startmid IS NULL))) LOOP
      SELECT COUNT(*)
      INTO   ln_tmp
      FROM   DUAL
      WHERE  NOT EXISTS(SELECT     mid
                        FROM       points
                        WHERE      mid IN(SELECT mid
                                          FROM   rolepoint
                                          WHERE  role_id = ln_role AND mid <> lc.mid)
                        CONNECT BY PRIOR PARENT = mid AND PRIOR mid <> NVL(an_startmid, nvl(an_type,0))
                        START WITH mid = lc.mid);

      IF ln_tmp = 1 THEN
       lt_accmid.EXTEND;
       lt_accmid(lt_accmid.COUNT) := lc.mid;
      END IF;
     END LOOP;
   END IF;
  END IF;

  RETURN lt_accmid;
 END;
------------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                 -- Package Body ADMINADD_PG
/


-- End of DDL Script for Package Body RYDA.ADMINADD_PG

