CREATE OR REPLACE 
PACKAGE BODY alpha_imp_pg IS
------------------------------------------------------------------------------------------------------------------------
 gn_task_code   NUMBER DEFAULT 619;

------------------------------------------------------------------------------------------------------------------------
   -- Интерфейс взаимодействия БД с ПО AlphaImport
   -- дата создания 10/01/2003 Чудаков И.В.
 FUNCTION consump_count_f (ancurr NUMBER, anpred NUMBER, an_digits NUMBER, an_kc NUMBER, an_rn NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN ROUND (util_pg.indicoverturn (ancurr - anpred, an_digits) * an_kc, an_rn);
 END;

 --Вставка графика нагрузки
 PROCEDURE set_halfhour_alpha_aimp (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, av_res OUT VARCHAR2) IS
  ln_er   NUMBER DEFAULT an_er;
  ln_ed   NUMBER DEFAULT an_ed;
  ln_q1   NUMBER DEFAULT an_q1;
  ln_q3   NUMBER DEFAULT an_q3;
 BEGIN
  SAVEPOINT set_halfhour_alpha_aimp_sp;
  av_res := '';
  util_pg.chdr (an_mid, ln_er, ln_ed, ln_q1, ln_q3);
  das_pg.ins_halfhourtmp (an_mid, ad_date, NULL, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, NULL, comsrv_pg.cn_maket, NULL);
  das_pg.checkhalfhour;
 EXCEPTION
  WHEN OTHERS THEN
   av_res := SQLERRM;
   ROLLBACK TO SAVEPOINT set_halfhour_alpha_aimp_sp;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Вставка суточных
 PROCEDURE set_bill_alpha_aimp (an_mid NUMBER, ad_date DATE, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_aerm NUMBER, an_aedm NUMBER,
 an_aq1m NUMBER, an_aq3m NUMBER, an_berm NUMBER, an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_cerm NUMBER, an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER,
 an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER, an_dq3m NUMBER,
                                                                --  av_mtrsn  VARCHAR2,
                                                                av_res OUT VARCHAR2
 ) IS
  av_mtrsn      VARCHAR2 (100);

  CURSOR lcur_sel IS
   SELECT NVL (erm, 0) erm, NVL (edm, 0) edm, NVL (q1m, 0) q1m, NVL (q3m, 0) q3m, NVL (q2m, 0) q2m, NVL (q4m, 0) q4m, NVL (aerm, 0) aerm, NVL (aedm, 0) aedm,
          NVL (aq1m, 0) aq1m, NVL (aq3m, 0) aq3m, NVL (aq2m, 0) aq2m, NVL (aq4m, 0) aq4m, NVL (berm, 0) berm, NVL (bedm, 0) bedm, NVL (bq1m, 0) bq1m,
          NVL (bq3m, 0) bq3m, NVL (bq2m, 0) bq2m, NVL (bq4m, 0) bq4m, NVL (cerm, 0) cerm, NVL (cedm, 0) cedm, NVL (cq1m, 0) cq1m, NVL (cq3m, 0) cq3m,
          NVL (cq2m, 0) cq2m, NVL (cq4m, 0) cq4m, NVL (derm, 0) derm, NVL (dedm, 0) dedm, NVL (dq1m, 0) dq1m, NVL (dq3m, 0) dq3m, NVL (dq2m, 0) dq2m,
          NVL (dq4m, 0) dq4m, NVL (er_mtrsn, ' ')
     FROM billorg
    WHERE mid = an_mid
          AND date_time =
              (SELECT MAX (date_time)
                 FROM billorg
                WHERE mid = an_mid AND date_time < ad_date)   --т.к. пока серийный номер не считывается AND lpad(UPPER(TRIM(er_mtrsn)),20,'0') = lpad(UPPER(TRIM(av_mtrsn)),20,'0')
                                                           ;

  lc            lcur_sel%ROWTYPE;
  lb_found      BOOLEAN;
  ln_kc         NUMBER;
  ln_rn         NUMBER             DEFAULT 10;
  ln_erm        NUMBER             DEFAULT an_erm;
  ln_edm        NUMBER             DEFAULT an_edm;
  ln_q1m        NUMBER             DEFAULT an_q1m;
  ln_q3m        NUMBER             DEFAULT an_q3m;
  ln_aerm       NUMBER             DEFAULT an_aerm;
  ln_aedm       NUMBER             DEFAULT an_aedm;
  ln_aq1m       NUMBER             DEFAULT an_aq1m;
  ln_aq3m       NUMBER             DEFAULT an_aq3m;
  ln_berm       NUMBER             DEFAULT an_berm;
  ln_bedm       NUMBER             DEFAULT an_bedm;
  ln_bq1m       NUMBER             DEFAULT an_bq1m;
  ln_bq3m       NUMBER             DEFAULT an_bq3m;
  ln_cerm       NUMBER             DEFAULT an_cerm;
  ln_cedm       NUMBER             DEFAULT an_cedm;
  ln_cq1m       NUMBER             DEFAULT an_cq1m;
  ln_cq3m       NUMBER             DEFAULT an_cq3m;
  ln_derm       NUMBER             DEFAULT an_derm;
  ln_dedm       NUMBER             DEFAULT an_dedm;
  ln_dq1m       NUMBER             DEFAULT an_dq1m;
  ln_dq3m       NUMBER             DEFAULT an_dq3m;
  ln_er         NUMBER;
  ln_ed         NUMBER;
  ln_q1         NUMBER;
  ln_q3         NUMBER;
  ln_aer        NUMBER;
  ln_aed        NUMBER;
  ln_aq1        NUMBER;
  ln_aq3        NUMBER;
  ln_ber        NUMBER;
  ln_bed        NUMBER;
  ln_bq1        NUMBER;
  ln_bq3        NUMBER;
  ln_cer        NUMBER;
  ln_ced        NUMBER;
  ln_cq1        NUMBER;
  ln_cq3        NUMBER;
  ln_der        NUMBER;
  ln_ded        NUMBER;
  ln_dq1        NUMBER;
  ln_dq3        NUMBER;
  ld_lastsave   DATE;
  ln_digits     NUMBER;
 BEGIN
  av_res := '';
  ln_digits := -1;
  av_mtrsn := '';

  --Проверка того, за данную дату еще нет
  SELECT NVL (MAX (date_time), TO_DATE ('01.01.1900 00:00', 'dd.mm.yyyy hh24:mi'))
    INTO ld_lastsave
    FROM billorg
   WHERE mid = an_mid;

  IF ad_date > ld_lastsave THEN
   --e
   OPEN lcur_sel;

   FETCH lcur_sel
    INTO lc;

   lb_found := lcur_sel%FOUND;

   CLOSE lcur_sel;

   IF lb_found THEN
    SELECT NVL (MAX (kc), 1)
      INTO ln_kc
      FROM feeders
     WHERE mid = an_mid;

    util_pg.chdr (an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m);
    util_pg.chdr (an_mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m);
    util_pg.chdr (an_mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m);
    util_pg.chdr (an_mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m);
    util_pg.chdr (an_mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m);
    ln_er := consump_count_f (ln_erm, lc.erm, ln_digits, ln_kc, ln_rn);
    ln_ed := consump_count_f (ln_edm, lc.edm, ln_digits, ln_kc, ln_rn);
    ln_q1 := consump_count_f (ln_q1m, lc.q1m, ln_digits, ln_kc, ln_rn);
    ln_q3 := consump_count_f (ln_q3m, lc.q3m, ln_digits, ln_kc, ln_rn);
    ln_aer := consump_count_f (ln_aerm, lc.aerm, ln_digits, ln_kc, ln_rn);
    ln_aed := consump_count_f (ln_aedm, lc.aedm, ln_digits, ln_kc, ln_rn);
    ln_aq1 := consump_count_f (ln_aq1m, lc.aq1m, ln_digits, ln_kc, ln_rn);
    ln_aq3 := consump_count_f (ln_aq3m, lc.aq3m, ln_digits, ln_kc, ln_rn);
    ln_ber := consump_count_f (ln_berm, lc.berm, ln_digits, ln_kc, ln_rn);
    ln_bed := consump_count_f (ln_bedm, lc.bedm, ln_digits, ln_kc, ln_rn);
    ln_bq1 := consump_count_f (ln_bq1m, lc.bq1m, ln_digits, ln_kc, ln_rn);
    ln_bq3 := consump_count_f (ln_bq3m, lc.bq3m, ln_digits, ln_kc, ln_rn);
    ln_cer := consump_count_f (ln_cerm, lc.cerm, ln_digits, ln_kc, ln_rn);
    ln_ced := consump_count_f (ln_cedm, lc.cedm, ln_digits, ln_kc, ln_rn);
    ln_cq1 := consump_count_f (ln_cq1m, lc.cq1m, ln_digits, ln_kc, ln_rn);
    ln_cq3 := consump_count_f (ln_cq3m, lc.cq3m, ln_digits, ln_kc, ln_rn);
    ln_der := consump_count_f (ln_derm, lc.derm, ln_digits, ln_kc, ln_rn);
    ln_ded := consump_count_f (ln_dedm, lc.dedm, ln_digits, ln_kc, ln_rn);
    ln_dq1 := consump_count_f (ln_dq1m, lc.dq1m, ln_digits, ln_kc, ln_rn);
    ln_dq3 := consump_count_f (ln_dq3m, lc.dq3m, ln_digits, ln_kc, ln_rn);

    INSERT INTO billorg
                (mid, er, ed, q1, q3, q2, q4, aer, aed, aq1, aq3, aq2, aq4, ber, bed, bq1, bq3, bq2, bq4, cer,
                 ced, cq1, cq3, cq2, cq4, der, ded, dq1, dq3, dq2, dq4, erm, edm, q1m, q3m, q2m, q4m, aerm, aedm,
                 aq1m, aq3m, aq2m, aq4m, berm, bedm, bq1m, bq3m, bq2m, bq4m, cerm, cedm, cq1m, cq3m, cq2m, cq4m, derm, dedm,
                 dq1m, dq3m, dq2m, dq4m, er_mtrsn, ed_mtrsn, q1_mtrsn, q3_mtrsn, q2_mtrsn, q4_mtrsn, date_time, SOURCE, nsource
                )
         VALUES (an_mid, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, ln_aer, ln_aed, ln_aq1, ln_aq3, NULL, NULL, ln_ber, ln_bed, ln_bq1, ln_bq3, NULL, NULL, ln_cer,
                 ln_ced, ln_cq1, ln_cq3, NULL, NULL, ln_der, ln_ded, ln_dq1, ln_dq3, NULL, NULL, ln_erm, ln_edm, ln_q1m, ln_q3m, NULL, NULL, ln_aerm, ln_aedm,
                 ln_aq1m, ln_aq3m, NULL, NULL, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, NULL, NULL, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, NULL, NULL, ln_derm, ln_dedm,
                 ln_dq1m, ln_dq3m, NULL, NULL, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, NULL, NULL, ad_date, 'A-import', comsrv_pg.cn_auto
                );
   ELSE
    util_pg.chdr (an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m);
    util_pg.chdr (an_mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m);
    util_pg.chdr (an_mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m);
    util_pg.chdr (an_mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m);
    util_pg.chdr (an_mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m);

    INSERT INTO billorg
                (mid, erm, edm, q1m, q3m, q2m, q4m, aerm, aedm, aq1m, aq3m, aq2m, aq4m, berm, bedm, bq1m, bq3m, bq2m,
                 bq4m, cerm, cedm, cq1m, cq3m, cq2m, cq4m, derm, dedm, dq1m, dq3m, dq2m, dq4m, er_mtrsn, q1_mtrsn, ed_mtrsn, q3_mtrsn,
                 q2_mtrsn, q4_mtrsn, date_time, SOURCE, nsource
                )
         VALUES (an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m, NULL, NULL, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, NULL, NULL, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, NULL,
                 NULL, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, NULL, NULL, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, NULL, NULL, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn,
                 NULL, NULL, ad_date, 'A-import', comsrv_pg.cn_auto
                );
   END IF;
  ELSE   -- усл по дате
   av_res := 'существующие показания имеют более позднюю дату.';
  END IF;
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body ALPHA_IMP_PG
/


