-- Generated 14.04.2014 9:34:56 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY averrate_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет вычисления весовых коэффициентов для получасовок в пределах суток
------------------------------------------------------------------------------------------------------------------------
--- **************************** OLD  ********************************
------------------------------------------------------------------------------------------------------------------------
 gn_mid     NUMBER;
 gd_start   DATE;
 gd_end     DATE;
 gn_def     NUMBER;
------------------------------------------------------------------------------------------------------------------------
 gt_1       common_pg.tt_number;
 gt_2       common_pg.tt_number;
 gt_3       common_pg.tt_number;
 gt_4       common_pg.tt_number;
 gt_5       common_pg.tt_number;
 gt_6       common_pg.tt_number;

 PROCEDURE averrate_p (an_mid NUMBER, ad_start DATE, ad_end DATE, an_def NUMBER);

 PROCEDURE averrate_p1 (an_mid NUMBER, ad_start DATE, ad_end DATE);

 PROCEDURE averrate_p2 (an_mid NUMBER, ad_start DATE, ad_end DATE);

 PROCEDURE normal_p (at_1 IN OUT common_pg.tt_number);

------------------------------------------------------------------------------------------------------------------------
--- **************************** NEW  ********************************
------------------------------------------------------------------------------------------------------------------------
 gr_oper    toper;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_sql (an_mid NUMBER, ad_date DATE, an_isgroup NUMBER, an_type NUMBER, an_meas NUMBER,an_hourtime NUMBER ,an_summer NUMBER,an_koeff NUMBER )
  RETURN VARCHAR2 IS
  lv_objtable    VARCHAR2 (256);
  lv_table       VARCHAR2 (256) := 'halfhour';
  lv_inverted    VARCHAR2 (256);
  lv_partly_er   VARCHAR2 (256);
  lv_partly_ed   VARCHAR2 (256);
  lv_objsubsel   VARCHAR2 (256);
  lv_sub         VARCHAR2 (600);
  ln_dsummer    NUMBER;
  ln_timezona   NUMBER;
  lv_grouping   VARCHAR(1000);
  lv_sqltimezone VARCHAR(1000);
  ln_koeff   NUMBER;
 BEGIN
   ln_koeff:=an_koeff;
  IF an_isgroup = 1 THEN
   lv_objtable := 'GROUPS';
   lv_inverted := 'G.INVERTED';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1)';

   IF util_pg.get_customer_id = 1 THEN
    lv_sub := '((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null))';
   ELSE
    lv_sub := '(prior gid=parent)';
   END IF;

   SELECT DECODE (MAX (mid), NULL, 'and G.gid in (select gid from groups connect by ' || lv_sub || ' start with gid=' || an_mid || ')', 'and G.gid=' || an_mid)
     INTO lv_objsubsel
     FROM GROUPS
    WHERE gid = an_mid;
  ELSE
   lv_objtable := 'POINTS';
   lv_inverted := '''N''';
   lv_partly_er := '';
   lv_partly_ed := '';

   IF util_pg.isfolder (an_mid) = 1 THEN
    lv_objsubsel := 'and G.mid in (select mid from points connect by prior mid=parent start with mid=' || an_mid || ')';
   ELSE
    lv_objsubsel := 'and G.mid = ' || an_mid || ' ';
   END IF;
  END IF;
 ln_dsummer:=an_summer;
 ln_timezona:=an_hourtime/24;
 IF ln_dsummer=1 THEN
  lv_grouping :=
        ' util_pg.get_num_dt (P.date_time-1/86400,nsource, 
        1/48 ,0,'||ln_timezona||','||ln_dsummer||') ';
 ELSE
    lv_grouping :=
        ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 
        1/48 ,0,'||ln_timezona||','||ln_dsummer||') ';
      
 END IF;
  IF (ln_dsummer = 0) THEN
   lv_sqltimezone :=
    ' and  date_time> to_date(''' || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'')+ ' || ln_timezona || ' - DECODE(' || ln_timezona
    || ',0,0,3/24))
                    and   date_time <=(to_date(''' || TO_CHAR (ad_date+1, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') + ' || ln_timezona || ' + DECODE(' || ln_timezona
    || ',0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) > to_date(''' || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') + ' || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date(''' || TO_CHAR (ad_date+1, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') + ' || ln_timezona;
  ELSE
   lv_sqltimezone :=
    ' AND   P.date_time > to_date(''' || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') + ' || ln_timezona || '
      AND   P.date_time <= to_date(''' || TO_CHAR (ad_date+1, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') + ' || ln_timezona;
  END IF;

 IF an_type = 0 THEN   --по перетоку
   RETURN 'select '||util_pg.hint_ordered||lv_grouping||' num,sum((-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),nvl(P.ed'
          || lv_partly_ed || ',0))*DECODE(' || lv_inverted || ',''y'',1,-1)))/'||ln_koeff||' sm from ' || lv_objtable || ' G,' || lv_table
          || ' P where g.mid=p.mid 
          '|| lv_sqltimezone
            || lv_objsubsel
          || ' group by '||lv_grouping||'
          order by mod('||lv_grouping||',2),num,abs(sm) desc';
  ELSIF (an_type = 1 OR (an_type = 3 AND an_meas IN (1, 3, 4)) OR (an_type = 4 AND an_meas IN (2, 5, 6))) THEN   -- по приему
   RETURN 'select '||util_pg.hint_ordered||lv_grouping||' num,
         sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.ed ' || lv_partly_ed || ',0),
          nvl(P.er ' || lv_partly_er || ' ,0)))/'||ln_koeff||' sm
         from ' || lv_objtable || ' G,' || lv_table || ' P where g.mid=p.mid '
         || lv_sqltimezone || lv_objsubsel || 
          ' group by '||lv_grouping||'
          order by mod('||lv_grouping||',2),num,abs(sm) desc';
  ELSIF (an_type = 2 OR (an_type = 3 AND an_meas IN (2, 5, 6)) OR (an_type = 4 AND an_meas IN (1, 3, 4))) THEN   --по отдаче
   RETURN 'select '||util_pg.hint_ordered||lv_grouping||' num,
         sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.er ' || lv_partly_er || ' ,0),
             nvl(P.ed ' || lv_partly_ed || ' ,0))  )/'||ln_koeff||' sm
          from ' || lv_objtable || ' G,' || lv_table || ' P where g.mid=p.mid '
          || lv_sqltimezone || lv_objsubsel ||
           ' group by '||lv_grouping||'
          order by mod('||lv_grouping||',2),num, abs(sm) desc';
  END IF;
  
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE clear_info (ar_info IN OUT tinfo) IS
 BEGIN
  ar_info.d := NULL;
  ar_info.src := NULL;
  ar_info.sm := NULL;
  ar_info.e := NULL;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_operatingday (an_mid NUMBER, an_omid NUMBER, an_ogid NUMBER, ad_regime DATE, an_shift NUMBER, an_type NUMBER) IS
 BEGIN
  gr_oper.mid := an_mid;
  gr_oper.ID := NVL (NVL (an_omid, an_ogid), an_mid);

  IF an_ogid IS NULL THEN
   gr_oper.isgroup := 0;
  ELSE
   gr_oper.isgroup := 1;
  END IF;

  gr_oper.dregime := ad_regime;
  gr_oper.nshift := an_shift;
  gr_oper.ntype := an_type;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE createtinfo (an_mid NUMBER, ad_from DATE, ad_till DATE, an_type NUMBER, an_inhole NUMBER, an_sm NUMBER, at_inf IN OUT ttinfo, an_findoperatingday NUMBER,an_hourtime NUMBER ,--сдвиг по временной зоне
                                                                                                             an_summer NUMBER, --есть ли переход зима-лето
                                                                                                             an_koeff  NUMBER
                                                                                                             )IS
  cn_step   CONSTANT NUMBER         DEFAULT 1 / 48;
  ld_from            DATE           DEFAULT util_pg.ceil_d (ad_from, cn_step) - cn_step;   --Работаем по началу периода интеграции >d <=d+cn_step а перед выходом записываем дату d:=d+cn_step
  ld_till            DATE           DEFAULT util_pg.ceil_d (ad_till, cn_step) - cn_step;
  ld_tmp             DATE;
  ln_i               NUMBER;
  lr_info            tinfo;
  lr_oper            toper;
  cr_sel             common_pg.tcur;
  ln_pos             NUMBER;
  ln_sm              NUMBER;
  ln_start           NUMBER;
  ln_sum             NUMBER         DEFAULT 0;
  ln_type            NUMBER;
  lb_new             BOOLEAN;
  counter            NUMBER;
  at_inf1            ttinfo;
  a                  NUMBER;
  ln_m               NUMBER;
  ln_num             NUMBER;
  ln_test            NUMBER;
  
 BEGIN
  at_inf.DELETE;
  at_inf1.DELETE;
  
  ln_num:=round(ld_till-ld_from)*48-2 ;
 
  FOR i IN 1..ln_num LOOP
   at_inf1(i).sm:=i;
  END LOOP;

  IF NOT ld_from <= ld_till OR (util_pg.is_dayswitch (ld_from) <> 0 AND TO_CHAR (ld_from, 'HH24') BETWEEN util_pg.switch_f - 1 AND util_pg.switch_f + 2)
     OR (util_pg.is_dayswitch (ld_till) <> 0 AND TO_CHAR (ld_till, 'HH24') BETWEEN util_pg.switch_f - 1 AND util_pg.switch_f + 2) THEN
   raise_application_error (-20001,
                            'Ошибка задания входных параметров: ad_from=''' || TO_CHAR (ad_from, 'dd.mm.yyyy hh24:mi:ss') || ''' ad_till='''
                            || TO_CHAR (ad_till, 'dd.mm.yyyy hh24:mi:ss') || '''');
  END IF;

  --заполняем даты и nsource
  ld_tmp := ld_from;
  ln_i := 1;

  WHILE ld_tmp <= ld_till LOOP
   IF util_pg.is_timeswitch (ld_tmp + cn_step) = 1 AND an_summer<>0 THEN
    ld_tmp := ld_tmp + 1 / 24;
    GOTO to_continue;
   END IF;

   clear_info (lr_info);
   lr_info.d := ld_tmp;
   lr_info.src := util_pg.cn_manualinput;
   at_inf (ln_i) := lr_info;

   IF util_pg.is_timeswitch (ld_tmp + cn_step) = -1 AND an_summer<>0 THEN
    clear_info (lr_info);
    lr_info.d := ld_tmp + cn_step;
    lr_info.src := util_pg.cn_manualinput;
    at_inf (ln_i + 1) := lr_info;
    clear_info (lr_info);
    lr_info.d := ld_tmp;
    lr_info.src := util_pg.cn_manualinputw;
    at_inf (ln_i + 2) := lr_info;
    clear_info (lr_info);
    lr_info.d := ld_tmp + cn_step;
    lr_info.src := util_pg.cn_manualinputw;
    at_inf (ln_i + 3) := lr_info;
    ln_i := ln_i + 3;
    ld_tmp := ld_tmp + cn_step;
   END IF;

   ln_i := ln_i + 1;
   ld_tmp := ld_tmp + cn_step;

   <<to_continue>>
   NULL;
  END LOOP;

  --В случае нуля или короткого интервала короткий выход
  IF NVL (an_sm, 0) = 0 OR at_inf.COUNT <= 1 THEN
   FOR i IN 1 .. at_inf.COUNT LOOP
    at_inf (i).e := an_sm;
    at_inf (i).d := at_inf (i).d + cn_step;
   END LOOP;

   RETURN;
  END IF;

  --Заполняем, образцом
  ln_i := 1;

  WHILE ln_i <= at_inf.COUNT LOOP
   IF ln_i = 1 OR at_inf (ln_i).d = TRUNC (at_inf (ln_i).d) THEN   --На границах дат и сначала запрос на получение образца разноски
    ld_tmp := at_inf (ln_i).d;
    ln_start := ln_i - (util_pg.get_num_dt (at_inf (ln_i).d + cn_step - 1 / 86400, at_inf (ln_i).src, cn_step) - 1);

    IF NOT an_findoperatingday = 1 THEN   --Если не задан образец явно, то ищем его
     lr_oper := gr_oper;

     IF NOT lr_oper.mid = an_mid THEN
      raise_application_error (-20001, 'Не задан образец разноски.');
     END IF;
    ELSE
     FOR lc IN (SELECT   NVL (NVL (o.gid, o.mid), an_mid) ID, DECODE (o.gid, NULL, 0, 1) isgroup, o.dregime, o.nshift, o.ntype
                    FROM operatingday o,
                         (SELECT     ps.*, LEVEL lv
                                FROM points ps
                          CONNECT BY PRIOR PARENT = mid
                          START WITH mid = an_mid) ow,
                         points p,
                         GROUPS g
                   WHERE o.nowner = ow.mid AND o.mid = p.mid(+) AND o.gid = g.gid(+) AND o.dstart <= ld_tmp AND o.nmeas IN (0, an_type)
                ORDER BY ow.lv, o.dstart DESC) LOOP
      lr_oper.mid := an_mid;
      lr_oper.ID := lc.ID;
      lr_oper.isgroup := lc.isgroup;
      lr_oper.dregime := lc.dregime;
      lr_oper.nshift := lc.nshift;
      lr_oper.ntype := lc.ntype;
      EXIT;
     END LOOP;
    END IF;

    ln_type := lr_oper.ntype;
    lr_oper.dat := NVL (lr_oper.dregime, TRUNC (ld_tmp - lr_oper.nshift));
   END IF;

   IF lr_oper.ID <> 0 THEN
      
       OPEN cr_sel FOR get_sql (lr_oper.ID, lr_oper.dat, lr_oper.isgroup, lr_oper.ntype, an_type,an_hourtime,an_summer,an_koeff);

      counter:=ln_start;
    LOOP
     FETCH cr_sel
      INTO ln_pos, ln_sm;

     EXIT WHEN cr_sel%NOTFOUND;

     IF ln_start + ln_pos - 1 >= 1 AND ln_start + ln_pos - 1 <= at_inf.COUNT THEN
      at_inf (ln_start + ln_pos - 1).sm := ln_sm;
      counter:=counter+1;
      at_inf1 (counter).sm:=round(ln_start + ln_pos - 1);
     
      END IF;
    END LOOP;

    CLOSE cr_sel;
   END IF;

   --Если только в дырки, то NULL на место разбивки (чтоб не записать туда)
   --Над конечно проверять дырки отдельно по каждому измерению - но такого не бывает, чтоб по одному было а по другому нет
   IF an_inhole = 1 THEN
    FOR lc IN (SELECT   util_pg.get_num_dt (date_time - 1 / 86400, nsource, cn_step) pos, SUM (er) er, SUM (ed) ed, SUM (q1) q1, SUM (q2) q2, SUM (q3) q3,
                        SUM (q4) q4
                   FROM halfhour
                  WHERE mid = an_mid AND date_time > TRUNC (at_inf (ln_i).d) AND date_time <= TRUNC (at_inf (ln_i).d) + 1
                        AND nsource NOT IN (util_pg.cn_manualinput, util_pg.cn_manualinputw)
               GROUP BY util_pg.get_num_dt (date_time - 1 / 86400, nsource, cn_step)
                 HAVING DECODE (an_type, 1, NULL) * SUM (er) IS NOT NULL OR DECODE (an_type, 2, NULL) * SUM (ed) IS NOT NULL
                        OR DECODE (an_type, 3, NULL) * SUM (q1) IS NOT NULL OR DECODE (an_type, 4, NULL) * SUM (q2) IS NOT NULL
                        OR DECODE (an_type, 5, NULL) * SUM (q3) IS NOT NULL OR DECODE (an_type, 6, NULL) * SUM (q4) IS NOT NULL) LOOP
     IF ln_start + lc.pos - 1 >= 1 AND ln_start + lc.pos - 1 <= at_inf.COUNT THEN
      at_inf (ln_start + lc.pos - 1).sm := NULL;
     END IF;
    END LOOP;
   END IF;
 IF an_summer=0 THEN
   ln_i := ln_start + 1 / cn_step;
 ELSE  
   ln_i := ln_start + 1 / cn_step - 2 * util_pg.is_dayswitch (ld_tmp);
 END IF;
  END LOOP;

  lb_new := FALSE;

  IF util_pg.get_customer_id = 44 AND ln_type = 0 THEN   --если переток и Добасс то бьем по другому алгоритму
   ln_pos := NULL;
   ln_sm := 0;

   FOR i IN 1 .. at_inf.COUNT LOOP
    IF NVL (SIGN (at_inf (i).sm), 0) <> 0 AND SIGN (at_inf (i).sm) <> ln_pos THEN   --Помним что if(NULL<>NULL) это FALSE
     lb_new := TRUE;
     EXIT;
    END IF;

    IF ln_pos IS NULL AND SIGN (at_inf (i).sm) <> 0 THEN
     ln_pos := SIGN (at_inf (i).sm);
    END IF;
   END LOOP;
  END IF;

  IF lb_new THEN
   FOR i IN 1 .. at_inf.COUNT LOOP
    ln_sum := ln_sum + NVL (at_inf (i).sm, 0);   -- сумма образца
   END LOOP;

   ln_sm := an_sm;

   FOR i IN 1 .. at_inf.COUNT LOOP
    IF at_inf (i).sm <> 0 THEN
     at_inf (i).e := ROUND ((NVL (at_inf (i).sm, 0) * an_sm) / NVL (ln_sum, 1));
     ln_sm := ln_sm - at_inf (i).e;
    ELSE   --Только NULL или 0
     at_inf (i).e := at_inf (i).sm;
    END IF;
   END LOOP;
   
 
   --Остатки раскидали
 WHILE ABS (ln_sm) >= 1 LOOP
 ln_test:=ABS (ln_sm);
  FOR j IN 1 .. at_inf1.COUNT LOOP
   a:=at_inf1(j).sm;
    IF ABS (ln_sm) >= 1 AND at_inf (a).sm <> 0 AND SIGN (ln_sm) = SIGN (at_inf (a).sm) THEN
     at_inf (a).e := at_inf (a).e + SIGN (ln_sm);
   -- insert into tmp_vil values('ln_m='||ln_m||' at_inf (a).e='||at_inf (a).e||' a='||a||' '||' ln_sm='||ln_sm);commit;
     ln_sm := ln_sm - SIGN (ln_sm);
    END IF;
   END LOOP;
  IF NVL(ln_test,0)=NVL(ABS (ln_sm),0) THEN
   EXIT;
  END IF; 
 END LOOP;


   IF ABS (ln_sm) >= 1 THEN

     FOR j IN 1 .. at_inf1.COUNT LOOP
      a:=at_inf1(j).sm;
      IF at_inf (a).sm <> 0 AND SIGN (ln_sm) = SIGN (at_inf (a).sm) THEN
      at_inf (a).e := at_inf (a).e + ln_sm;
      
      ln_sm := 0;
       END IF;
    END LOOP;
 
 END IF;
  ELSE
   --Проверяем смену знака и считаем сумму
   ln_pos := NULL;
   ln_sm := 0;

   FOR i IN 1 .. at_inf.COUNT LOOP
    IF NVL (SIGN (at_inf (i).sm), 0) <> 0 AND SIGN (at_inf (i).sm) <> ln_pos THEN   --Помним что if(NULL<>NULL) это FALSE
     raise_application_error (-20001, 'Характеристика образца меняет знак с ''' || TO_CHAR (at_inf (i).d, 'dd.mm.yyyy hh24:mi:ss') || '''.');
    END IF;

    IF ln_pos IS NULL AND SIGN (at_inf (i).sm) <> 0 THEN
     ln_pos := SIGN (at_inf (i).sm);
    END IF;

    ln_sm := ln_sm + ABS (NVL (at_inf (i).sm, 0));
   END LOOP;

   IF ln_pos IS NULL THEN   --Либо нет разбивки либо все равно 0
    FOR i IN 1 .. at_inf.COUNT LOOP
     at_inf (i).sm := 1 / at_inf.COUNT;
    END LOOP;
   ELSE   --нормируем и берем abs
    FOR i IN 1 .. at_inf.COUNT LOOP
     at_inf (i).sm := ABS (at_inf (i).sm / ln_sm);
    END LOOP;
   END IF;

   --А теперь разносим
   ln_sm := an_sm;

   FOR i IN 1 .. at_inf.COUNT LOOP
    IF at_inf (i).sm <> 0 THEN
     at_inf (i).e := TRUNC (an_sm * at_inf (i).sm);
     ln_sm := ln_sm - at_inf (i).e;
   
    ELSE   --Только NULL или 0
     at_inf (i).e := at_inf (i).sm;
    END IF;
   END LOOP;

   --Остатки раскидали


WHILE ABS (ln_sm) >= 1 LOOP
 ln_test:=ABS (ln_sm);   
FOR j IN 1 .. at_inf1.COUNT LOOP

   a:=at_inf1(j).sm;
    IF ABS (ln_sm) >= 1 AND at_inf (a).sm <> 0 AND SIGN (ln_sm) = SIGN (at_inf (a).sm) THEN
     at_inf (a).e := at_inf (a).e + SIGN (ln_sm);

     ln_sm := ln_sm - SIGN (ln_sm);
    END IF;
   END LOOP;
 IF NVL(ln_test,0)=NVL(ABS (ln_sm),0) THEN
   EXIT;
 END IF;  
END LOOP;
   --Остатки раскидали (еще раз)
   IF ABS (ln_sm) >= 1 THEN
   FOR j IN 1 .. at_inf1.COUNT LOOP
      a:=at_inf1(j).sm;
  
     IF ABS (ln_sm) >= 1 AND at_inf (a).sm IS NOT NULL THEN
      at_inf (a).e := at_inf (a).e + SIGN (ln_sm);
      ln_sm :=ln_sm - SIGN (ln_sm);
     END IF;
    END LOOP;
   END IF;

   --Контрольный выстрел
   IF at_inf.COUNT > 0 AND ABS (ln_sm) >= 1 THEN
    at_inf (1).e := NVL (at_inf (1).e, 0) + TRUNC (ln_sm);
   END IF;
  END IF;

  --Поправили дату
  FOR i IN 1 .. at_inf.COUNT LOOP
   at_inf (i).d := at_inf (i).d + cn_step;
  END LOOP;
 END;


------------------------------------------------------------------------------------------------------------------------
--- **************************** OLD  ********************************
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE averrate_p (an_mid NUMBER, ad_start DATE, ad_end DATE, an_def NUMBER) IS
 BEGIN
  IF an_def = 1 THEN
   averrate_p1 (an_mid, ad_start, ad_end);
  ELSE
   averrate_p2 (an_mid, ad_start, ad_end);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вычисления весовых коэффициентов для получасовок в любой период по группе
 PROCEDURE averrate_p1 (an_mid NUMBER, ad_start DATE, ad_end DATE) IS
  CURSOR lcur_sel IS
   SELECT   util_pg.trunchh24_2 (h.date_time) dt, NVL (SUM (h.er), 0) er, NVL (SUM (h.ed), 0) ed, NVL (SUM (h.q1), 0) q1, NVL (SUM (h.q2), 0) q2,
            NVL (SUM (h.q3), 0) q3, NVL (SUM (h.q4), 0) q4
       FROM halfhour h
      WHERE h.mid IN (SELECT     mid
                            FROM GROUPS
                      CONNECT BY PRIOR gid = PARENT
                      START WITH gid = util_pg.hh24gid_f) AND h.mid <> an_mid AND h.date_time > ad_start - 1 / 48 AND h.date_time <= ad_end
   GROUP BY util_pg.trunchh24_2 (h.date_time);

  lc       lcur_sel%ROWTYPE;
  i        NUMBER             DEFAULT 1;
  ld_tmp   DATE               DEFAULT ad_start;
 BEGIN
  gn_mid := an_mid;
  gd_start := ad_start;
  gd_end := ad_end;
  gn_def := 1;
  gt_1.DELETE;
  gt_2.DELETE;
  gt_3.DELETE;
  gt_4.DELETE;
  gt_5.DELETE;
  gt_6.DELETE;

  OPEN lcur_sel;

  FETCH lcur_sel
   INTO lc;

  WHILE ld_tmp <= ad_end LOOP
   IF ld_tmp = lc.dt THEN
    gt_1 (i) := lc.er;
    gt_2 (i) := lc.ed;
    gt_3 (i) := lc.q1;
    gt_4 (i) := lc.q2;
    gt_5 (i) := lc.q3;
    gt_6 (i) := lc.q4;

    IF lcur_sel%FOUND THEN
     FETCH lcur_sel
      INTO lc;
    END IF;
   ELSE
    gt_1 (i) := 0;
    gt_2 (i) := 0;
    gt_3 (i) := 0;
    gt_4 (i) := 0;
    gt_5 (i) := 0;
    gt_6 (i) := 0;
   END IF;

   ld_tmp := ld_tmp + 1 / 48;
   i := i + 1;
  END LOOP;

  CLOSE lcur_sel;

  normal_p (gt_1);
  normal_p (gt_2);
  normal_p (gt_3);
  normal_p (gt_4);
  normal_p (gt_5);
  normal_p (gt_6);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вычисления весовых коэффициентов для получасовок в любой период по режимному дню
 PROCEDURE averrate_p2 (an_mid NUMBER, ad_start DATE, ad_end DATE) IS
  CURSOR lcur_sel IS
   SELECT   util_pg.trunchh24_2 (h.date_time - 1 / 86400) + 1 / 48 dt, NVL (SUM (h.er), 0) er, NVL (SUM (h.ed), 0) ed, NVL (SUM (h.q1), 0) q1,
            NVL (SUM (h.q2), 0) q2, NVL (SUM (h.q3), 0) q3, NVL (SUM (h.q4), 0) q4
       FROM halfhour h
      WHERE h.mid = an_mid AND nsource = util_pg.cn_manualinput
            AND h.date_time > (SELECT NVL (TRUNC (MAX (date_time) - 1 / 86400), ad_start - 1 / 48)
                                 FROM halfhour
                                WHERE mid = an_mid AND nsource = util_pg.cn_manualinput AND TRUNC (date_time - 1 / 86400) <= ad_start) AND h.date_time <= ad_end
   GROUP BY util_pg.trunchh24_2 (h.date_time - 1 / 86400)
   ORDER BY 1;

  lc       lcur_sel%ROWTYPE;
  ld_tmp   DATE                DEFAULT ad_start;
  j        NUMBER;
  k        NUMBER              DEFAULT 1;
  lt_0     common_pg.tt_number;
 BEGIN
  gn_mid := an_mid;
  gd_start := ad_start;
  gd_end := ad_end;
  gn_def := 2;
  gt_1.DELETE;
  gt_2.DELETE;
  gt_3.DELETE;
  gt_4.DELETE;
  gt_5.DELETE;
  gt_6.DELETE;

  FOR i IN -47 .. 48 * (ad_end - ad_start + 1 / 48) LOOP
   gt_1 (i) := 0;
   gt_2 (i) := 0;
   gt_3 (i) := 0;
   gt_4 (i) := 0;
   gt_5 (i) := 0;
   gt_6 (i) := 0;
  END LOOP;

  OPEN lcur_sel;

  FETCH lcur_sel
   INTO lc;

  FOR i IN 1 .. 48 * (ad_end - ad_start + 1 / 48) LOOP
   WHILE lc.dt < ld_tmp LOOP
    j := -47 + (TO_CHAR (lc.dt - 1 / 48, 'SSSSS')) / 1800;
    gt_1 (j) := lc.er;
    gt_2 (j) := lc.ed;
    gt_3 (j) := lc.q1;
    gt_4 (j) := lc.q2;
    gt_5 (j) := lc.q3;
    gt_6 (j) := lc.q4;

    IF lcur_sel%FOUND THEN
     FETCH lcur_sel
      INTO lc;
    ELSE
     EXIT;
    END IF;
   END LOOP;

   IF lc.dt = ld_tmp THEN
    gt_1 (i) := lc.er;
    gt_2 (i) := lc.ed;
    gt_3 (i) := lc.q1;
    gt_4 (i) := lc.q2;
    gt_5 (i) := lc.q3;
    gt_6 (i) := lc.q4;
    lt_0 (k) := i;
    k := k + 1;

    IF lcur_sel%FOUND THEN
     FETCH lcur_sel
      INTO lc;
    END IF;
   ELSE
    gt_1 (i) := gt_1 (i - 48);
    gt_2 (i) := gt_2 (i - 48);
    gt_3 (i) := gt_3 (i - 48);
    gt_4 (i) := gt_4 (i - 48);
    gt_5 (i) := gt_5 (i - 48);
    gt_6 (i) := gt_6 (i - 48);
   END IF;

   ld_tmp := ld_tmp + 1 / 48;
  END LOOP;

  CLOSE lcur_sel;

  FOR i IN -47 .. 0 LOOP
   gt_1.DELETE (i);
   gt_2.DELETE (i);
   gt_3.DELETE (i);
   gt_4.DELETE (i);
   gt_5.DELETE (i);
   gt_6.DELETE (i);
  END LOOP;

  FOR i IN 1 .. lt_0.COUNT LOOP
   j := lt_0 (i);
   gt_1 (j) := 0;
   gt_2 (j) := 0;
   gt_3 (j) := 0;
   gt_4 (j) := 0;
   gt_5 (j) := 0;
   gt_6 (j) := 0;
  END LOOP;

  lt_0.DELETE;
  normal_p (gt_1);
  normal_p (gt_2);
  normal_p (gt_3);
  normal_p (gt_4);
  normal_p (gt_5);
  normal_p (gt_6);
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE normal_p (at_1 IN OUT common_pg.tt_number) IS
  ln_s   NUMBER DEFAULT 0;
 BEGIN
  FOR i IN 1 .. at_1.COUNT LOOP
   ln_s := ln_s + at_1 (i);
  END LOOP;

  IF ln_s = 0 THEN
   FOR i IN 1 .. at_1.COUNT LOOP
    at_1 (i) := 0;
   END LOOP;
  ELSE
   FOR i IN 1 .. at_1.COUNT LOOP
    at_1 (i) := at_1 (i) / ln_s;
   END LOOP;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Функция вычисления весовых коэффициентов для получасовок в любой период
 FUNCTION averrate_f (an_mid NUMBER, an_type NUMBER, ad_start DATE, ad_end DATE, an_def NUMBER   -- 1- расчет весовых пропорционально группе, 0 - по режимному дню
                                                                                              )
  RETURN common_pg.tt_number IS
  ld_start   DATE DEFAULT util_pg.trunchh24_2 (ad_start);
  ld_end     DATE DEFAULT util_pg.trunchh24_2 (ad_end);
 BEGIN
  IF NVL (an_mid, -1) <> NVL (gn_mid, -2) OR NVL (an_def, -1) <> NVL (gn_def, -2)
     OR NVL (ld_start, TO_DATE ('100001', 'YYYYMM')) <> NVL (gd_start, TO_DATE ('100001', 'YYYYMM') - 1)
     OR NVL (ld_end, TO_DATE ('100001', 'YYYYMM')) <> NVL (ld_end, TO_DATE ('100001', 'YYYYMM') - 1) THEN
   averrate_p (an_mid, ld_start, ld_end, an_def);
  END IF;

  IF an_type = 2 THEN
   RETURN gt_2;
  ELSIF an_type = 3 THEN
   RETURN gt_3;
  ELSIF an_type = 4 THEN
   RETURN gt_4;
  ELSIF an_type = 5 THEN
   RETURN gt_5;
  ELSIF an_type = 6 THEN
   RETURN gt_6;
  ELSE
   RETURN gt_1;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
    -- Функция равномерного распределения
 FUNCTION averrate_evenly_f (an_mid NUMBER, ad_start DATE, ad_end DATE)
  RETURN common_pg.tt_number IS
  ld_start   DATE                DEFAULT util_pg.trunchh24_2 (ad_start);
  ld_end     DATE                DEFAULT util_pg.trunchh24_2 (ad_end);
  ld_tmp     DATE;
  lt_1       common_pg.tt_number;
  i          NUMBER;
  n          NUMBER;
 BEGIN
  ld_tmp := ld_start;
  n := 48 * (ld_end - ld_start + 1 / 48);
  i := 1;

  WHILE ld_tmp <= ld_end LOOP
   lt_1 (i) := 1 / n;
   i := i + 1;
   ld_tmp := ld_tmp + 1 / 48;
  END LOOP;

  RETURN lt_1;
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package spec
/


-- End of DDL Script for Package Body RYDA.AVERRATE_PG

