--Чистка БД (архивация и удаление)
 PROCEDURE save4kill(an_maket NUMBER, ad_date DATE) IS
  TYPE tjobs IS TABLE OF INT
   INDEX BY BINARY_INTEGER;

  fjobs               tjobs;
  lv_what             VARCHAR2(4000);
  date_str            VARCHAR(20);
  tname               VARCHAR(40);
  cname               VARCHAR(40);
  iname               VARCHAR(40);
  ld_old              DATE;
  cnt                 NUMBER DEFAULT 0;
  cnt_const           NUMBER DEFAULT 5000;
  job_cnt             NUMBER DEFAULT 1;
  ln_tmp              NUMBER;
 BEGIN
  FOR lc IN (SELECT   t.table_name, t.term, t.vindic_column, t.index_name
             FROM     db_term t
             ORDER BY table_name) LOOP
   ld_old := TRUNC(ad_date) - lc.term;
   save_to_file(lc.table_name, ld_old);

   IF lc.index_name IS NOT NULL THEN
    job_cnt := job_cnt + 1;
    date_str := '''' || TO_CHAR(ld_old, 'dd.mm.yyyy') || '''';
    tname := '''' || lc.table_name || '''';
    cname := '''' || lc.vindic_column || '''';
    iname := '''' || lc.index_name || '''';
    lv_what := 'RYDA.BACKGROUND01_PG.del_journal ( ' || tname || ',' || cname || ',' || iname || ',' || date_str || ' );';

    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT *
                  FROM   user_jobs
                  WHERE  what = lv_what);

    IF ln_tmp = 0 THEN
     DBMS_JOB.submit(fjobs(job_cnt), lv_what, SYSDATE, NULL);
     COMMIT;
    END IF;
   ELSE
    EXECUTE IMMEDIATE    'select count(*) from '
                      || lc.table_name
                      || ' where '
                      || lc.vindic_column
                      || ' <= to_date('''
                      || TO_CHAR(ld_old, 'dd.mm.yyyy')
                      || ''',''dd.mm.yyyy'')+1 and '
                      || lc.vindic_column
                      || ' > to_date('''
                      || TO_CHAR(ld_old, 'dd.mm.yyyy')
                      || ''',''dd.mm.yyyy'') '
    INTO              cnt;

    FOR cur_col IN 1 .. FLOOR(cnt / cnt_const + 1) LOOP
     EXECUTE IMMEDIATE    'delete from '
                       || lc.table_name
                       || ' where '
                       || lc.vindic_column
                       || ' <= to_date('''
                       || TO_CHAR(ld_old, 'dd.mm.yyyy')
                       || ''',''dd.mm.yyyy'')+1 and '
                       || lc.vindic_column
                       || ' > to_date('''
                       || TO_CHAR(ld_old, 'dd.mm.yyyy')
                       || ''',''dd.mm.yyyy'') and rownum <= '
                       || cnt_const;

     COMMIT;
    END LOOP;
   END IF;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.save4kill: ' || SQLERRM(SQLCODE));
 END;                                                                                                                                     -- Procedure SAVE4KILL

------------------------------------------------------------------------------------------------------------------------
 --Чистка БД (date_time <)
 PROCEDURE killdata(an_maket NUMBER, ad_date DATE) IS
  TYPE tjobs IS TABLE OF INT
   INDEX BY BINARY_INTEGER;

  fjobs               tjobs;
  rec_cur             common_pg.tcur;
  ld_old              DATE;
  ld_min              DATE;
  date_str            VARCHAR(20);
  tname               VARCHAR2(50);
  cname               VARCHAR2(50);
  iname               VARCHAR2(50);
  cnt                 NUMBER DEFAULT 0;
  cnt_const           NUMBER DEFAULT 5000;
  job_cnt             NUMBER DEFAULT 1;
 BEGIN
  FOR table_cur IN (SELECT   t.table_name, t.term, t.vindic_column, t.index_name
                    FROM     db_term t
                    WHERE    index_name <> '0'
                    ORDER BY table_name) LOOP
   ld_old := TRUNC(ad_date) - table_cur.term;

   OPEN rec_cur FOR 'select trunc(min(' || table_cur.vindic_column || ')) from ' || table_cur.table_name;

   FETCH rec_cur
   INTO  ld_min;

   CLOSE rec_cur;

   WHILE ld_min <= ld_old LOOP
    save_to_file(table_cur.table_name, ld_min);

    IF table_cur.index_name IS NOT NULL THEN
     job_cnt := job_cnt + 1;
     date_str := '''' || TO_CHAR(ld_min, 'dd.mm.yyyy') || '''';
     tname := '''' || table_cur.table_name || '''';
     cname := '''' || table_cur.vindic_column || '''';
     iname := '''' || table_cur.index_name || '''';
     DBMS_JOB.submit(fjobs(job_cnt), 'RYDA.BACKGROUND01_PG.del_journal ( ' || tname || ',' || cname || ',' || iname || ',' || date_str || ' );', SYSDATE, NULL);
     COMMIT;
    --DBMS_JOB.run (fjobs (job_cnt));
    ELSE
     EXECUTE IMMEDIATE    'select count(*) from '
                       || table_cur.table_name
                       || ' where '
                       || table_cur.vindic_column
                       || ' <= to_date('''
                       || TO_CHAR(ld_min, 'dd.mm.yyyy')
                       || ''',''dd.mm.yyyy'')+1 and '
                       || table_cur.vindic_column
                       || ' > to_date('''
                       || TO_CHAR(ld_min, 'dd.mm.yyyy')
                       || ''',''dd.mm.yyyy'') '
     INTO              cnt;

     FOR cur_col IN 1 .. FLOOR(cnt / cnt_const + 1) LOOP
      EXECUTE IMMEDIATE    'delete from '
                        || table_cur.table_name
                        || ' where '
                        || table_cur.vindic_column
                        || ' <= to_date('''
                        || TO_CHAR(ld_min, 'dd.mm.yyyy')
                        || ''',''dd.mm.yyyy'')+1 and '
                        || table_cur.vindic_column
                        || ' > to_date('''
                        || TO_CHAR(ld_min, 'dd.mm.yyyy')
                        || ''',''dd.mm.yyyy'') and rownum <= '
                        || cnt_const;

      COMMIT;
     END LOOP;
    END IF;

    ld_min := ld_min + 1;
   END LOOP;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.killdata: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Копирование данных на расчетные точки
 PROCEDURE setdataunrealpoints(an_maket NUMBER, ad_date DATE) IS
  cn_step    CONSTANT NUMBER := 1 / 48;
  ld_date             DATE DEFAULT TRUNC(ad_date);
  lc0                 common_pg.tcur;
  lc1                 common_pg.tcur;
  lc2                 common_pg.tcur;
  lt_er               common_pg.tt_number;
  lt_ed               common_pg.tt_number;
  lt_q1               common_pg.tt_number;
  lt_q2               common_pg.tt_number;
  lt_q3               common_pg.tt_number;
  lt_q4               common_pg.tt_number;
  ln_i                NUMBER;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q2               NUMBER;
  ln_q3               NUMBER;
  ln_q4               NUMBER;
  ln_mid              NUMBER;
  ln_realpoint        NUMBER;
  ln_ratio            NUMBER;
  lv_er               VARCHAR2(256);
  lv_ed               VARCHAR2(256);
  lv_q1               VARCHAR2(256);
  lv_q2               VARCHAR2(256);
  lv_q3               VARCHAR2(256);
  lv_q4               VARCHAR2(256);
  lv_sql              VARCHAR2(2000);
  ln_cn               NUMBER DEFAULT util_pg.get_count_dt(ld_date, cn_step);
 BEGIN
  OPEN lc0 FOR 'select distinct mid from realpoint';

  LOOP
   FETCH lc0
   INTO  ln_mid;

   EXIT WHEN lc0%NOTFOUND;

   DELETE      halfhourold
   WHERE       mid = ln_mid AND date_time > ld_date AND date_time <= ld_date + 1;

   FOR i IN 1 .. ln_cn LOOP
    lt_er(i) := NULL;
    lt_ed(i) := NULL;
    lt_q1(i) := NULL;
    lt_q2(i) := NULL;
    lt_q3(i) := NULL;
    lt_q4(i) := NULL;
   END LOOP;

   OPEN lc1 FOR    'SELECT nrealpoint,nvl(nratio,1) nratio,nvl(substr(er,1,2),''null'') er,'
                || 'nvl(substr(ed,1,2),''null'') ed, nvl(substr(q1,1,2),''null'') q1,'
                || 'nvl(substr(q2,1,2),''null'') q2, nvl(substr(q3,1,2),''null'') q3,'
                || 'nvl(substr(q4,1,2),''null'') q4 FROM realpoint where mid='
                || ln_mid
                || ' order by nrealpoint';

   LOOP
    FETCH lc1
    INTO  ln_realpoint, ln_ratio, lv_er, lv_ed, lv_q1, lv_q2, lv_q3, lv_q4;

    EXIT WHEN lc1%NOTFOUND;

    BEGIN
     lv_sql :=
         'select util_pg.get_num_dt(date_time - 1 / 86400, nsource,1/48,0), sum('
      || lv_er
      || '),sum('
      || lv_ed
      || '),sum('
      || lv_q1
      || '),sum('
      || lv_q2
      || '),sum('
      || lv_q3
      || '),sum('
      || lv_q4
      || ') '
      || 'from halfhour where mid='
      || ln_realpoint
      || ' and date_time >to_date('
      || TO_CHAR(ld_date, 'YYYYMMDD')
      || ',''YYYYMMDD'') and '
      || 'date_time <=to_date('
      || TO_CHAR(ld_date + 1, 'YYYYMMDD')
      || ',''YYYYMMDD'') '
      || 'group by util_pg.get_num_dt(date_time - 1 / 86400, nsource,1/48,0) order by 1';

     OPEN lc2 FOR lv_sql;

     LOOP
      FETCH lc2
      INTO  ln_i, ln_er, ln_ed, ln_q1, ln_q2, ln_q3, ln_q4;

      EXIT WHEN lc2%NOTFOUND;
      lt_er(ln_i) := util_pg.sumn(lt_er(ln_i), ln_ratio * ln_er);
      lt_ed(ln_i) := util_pg.sumn(lt_ed(ln_i), ln_ratio * ln_ed);
      lt_q1(ln_i) := util_pg.sumn(lt_q1(ln_i), ln_ratio * ln_q1);
      lt_q2(ln_i) := util_pg.sumn(lt_q2(ln_i), ln_ratio * ln_q2);
      lt_q3(ln_i) := util_pg.sumn(lt_q3(ln_i), ln_ratio * ln_q3);
      lt_q4(ln_i) := util_pg.sumn(lt_q4(ln_i), ln_ratio * ln_q4);
     END LOOP;

     CLOSE lc2;
    EXCEPTION
     WHEN OTHERS THEN
      IF lc2%ISOPEN THEN
       CLOSE lc2;
      END IF;
    END;
   END LOOP;

   CLOSE lc1;

   FOR i IN 1 .. ln_cn LOOP
    IF (lt_er(i) IS NOT NULL) OR(lt_ed(i) IS NOT NULL) OR(lt_q1(i) IS NOT NULL) OR(lt_q2(i) IS NOT NULL) OR(lt_q3(i) IS NOT NULL) OR(lt_q4(i) IS NOT NULL) THEN
     das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + i * cn_step, NULL, lt_er(i), lt_ed(i), lt_q1(i), lt_q3(i), lt_q2(i), lt_q4(i), NULL,
      NULL, NULL);
    END IF;
   END LOOP;
  END LOOP;

  CLOSE lc0;

  COMMIT;
  das_pg.checkhalfhour;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.setdataunrealpoints: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------
  --Сигнал на обновление мониторов
 PROCEDURE refreshmonitor(an_maket NUMBER, ad_date DATE) IS
 BEGIN
  admin_pg.signal(4);                                                                                                                              --curr_power

  IF INSTR(util_pg.get_param(file_pg.gv_param, 1), '1') > 0 THEN                                                                                         --bill
   admin_pg.signal(1);
  END IF;

  IF INSTR(util_pg.get_param(file_pg.gv_param, 1), '2') > 0 THEN                                                                                      --halfhour
   admin_pg.signal(2);
  END IF;

  IF INSTR(util_pg.get_param(file_pg.gv_param, 1), '3') > 0 THEN                                                                                       --profile
   admin_pg.signal(3);
  END IF;

  IF INSTR(util_pg.get_param(file_pg.gv_param, 1), '5') > 0 THEN                                                                                        --fiscal
   admin_pg.signal(5);
  END IF;

  IF INSTR(util_pg.get_param(file_pg.gv_param, 1), '6') > 0 THEN                                                                                       --journal
   admin_pg.signal(6);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.refreshmonitor: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Повторное создание макета после поступления данных
 PROCEDURE recreatemakets(an_maket NUMBER, ad_date DATE) IS
  cn_shift   CONSTANT NUMBER := 30 / 86400;
  --Не захотел заводиться с блокировками (между sysdate и commit проходит время и мы делаем зазор в 30 сек, т.к фоновый процесс работает реже чем раз в 30 сек)
  ln_shift            NUMBER;
  ln_maket            NUMBER;
  lv_param            VARCHAR2(2000);
 BEGIN
  --Вычисляем сдвиг ограничения (для скорости);
  ln_shift := NVL(util_pg.allnumber_f(util_pg.get_param(file_pg.gv_param, 1)), 45);

  FOR i IN 2 .. LENGTH(file_pg.gv_param) LOOP
   --хватаем текущий макет
   ln_maket := util_pg.allnumber_f(util_pg.get_param(file_pg.gv_param, i));

   IF ln_maket > 0 THEN
    SELECT MAX(nmaket), MAX(vparam)
    INTO   ln_maket, lv_param
    FROM   makets
    WHERE  nmaket = ln_maket;

    IF ln_maket IS NULL THEN
     GOTO to_continue;
    END IF;
   ELSE
    GOTO to_continue;
   END IF;

   FOR lc IN (SELECT DISTINCT f.ddate
              FROM            makets m,
                              deportfiles f,
                              deportation d,
                              maketgroups g,
                              maketpoints p,
                              (SELECT   mid, TRUNC(date_time - 1 / 86400) dt, MAX(denter) denter
                               FROM     halfhour
                               WHERE    date_time > TRUNC(SYSDATE) - ln_shift
                               GROUP BY mid, TRUNC(date_time - 1 / 86400)) b
              WHERE           m.nmaket = ln_maket AND makets_pg.is_block(m.nmaket, m.nblock) = 0 AND m.nmaket = d.nmaket
                              AND deportation_pg.is_block(d.ndeportation, d.nblock) = 0 AND m.nmaket = g.nmaket AND g.ngroup = p.ngroup AND p.mid = b.mid(+)
                              AND d.ndeportation = f.ndeportation(+) AND f.ddate = b.dt AND f.denter < b.denter + cn_shift
              UNION
              SELECT DISTINCT f.ddate
              FROM            makets m,
                              deportfiles f,
                              deportation d,
                              maketgroups g,
                              maketpoints p,
                              (SELECT   mid, TRUNC(date_time) - 1 dt, MAX(denter) denter
                               FROM     billorg
                               WHERE    date_time > TRUNC(SYSDATE) - ln_shift
                               GROUP BY mid, TRUNC(date_time)) b
              WHERE           m.nmaket = ln_maket AND makets_pg.is_block(m.nmaket, m.nblock) = 0 AND m.nmaket = d.nmaket
                              AND deportation_pg.is_block(d.ndeportation, d.nblock) = 0 AND m.nmaket = g.nmaket AND g.ngroup = p.ngroup AND p.mid = b.mid(+)
                              AND d.ndeportation = f.ndeportation(+) AND f.ddate = b.dt AND f.denter < b.denter + cn_shift
              ORDER BY        1) LOOP
    file_pg.startimmediate_p(ln_maket, lc.ddate, lv_param);
    COMMIT;
   END LOOP;

   <<to_continue>>
   NULL;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.recreatemakets: ' || SQLERRM(SQLCODE));
 END;

