 PROCEDURE del_journal(tname VARCHAR2, cname VARCHAR2, iname VARCHAR2, dat_str VARCHAR2) IS
  datetime            DATE;
  lv_sql              VARCHAR2(2000);
 BEGIN
  datetime := TO_DATE(dat_str, 'dd.mm.yyyy');
  lv_sql :=
      'delete /*+index ('
   || tname
   || ', '
   || iname
   || ')*/ from '
   || tname
   || ' where '
   || cname
   || ' <= to_date('''
   || TO_CHAR(datetime, 'dd.mm.yyyy')
   || ''',''dd.mm.yyyy'')+1 and '
   || cname
   || ' >  to_date('''
   || TO_CHAR(datetime, 'dd.mm.yyyy')
   || ''',''dd.mm.yyyy'')';

  EXECUTE IMMEDIATE lv_sql;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.del_journal: ' || SQLERRM(SQLCODE));
 END;

----------------------------------------------------------------------------------------------------------------
 --выгрузка в файл
 PROCEDURE save_to_file(av_table_name VARCHAR2, ad_date DATE) IS
  lv_path             VARCHAR2(256);
  handle              UTL_FILE.file_type;
  rec_cur             common_pg.tcur;
  ln_exist            NUMBER;
  file_row            VARCHAR2(4000);
  col_list            VARCHAR2(4000);
  lv_sql              VARCHAR2(4000);
 BEGIN
  lv_path := util_pg.getparamvaluev_f(5);

  EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = '',.''';

  FOR lc IN (SELECT vindic_column, vextention, narchived
             FROM   db_term
             WHERE  table_name = av_table_name) LOOP
   IF lc.narchived <> 1 THEN
    EXIT;
   END IF;

   lv_sql :=
       'select count(*) from dual where exists(select * from '
    || av_table_name
    || ' where '
    || lc.vindic_column
    || ' <= to_date('''
    || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi')
    || ''',''dd.mm.yyyy hh24:mi'')+1 and '
    || lc.vindic_column
    || ' > to_date('''
    || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi')
    || ''',''dd.mm.yyyy hh24:mi'')) ';

   EXECUTE IMMEDIATE lv_sql
   INTO              ln_exist;

   IF ln_exist = 0 THEN
    EXIT;
   END IF;

   handle := UTL_FILE.fopen(lv_path, 'a' || TO_CHAR(ad_date, 'yyyymmdd.') || lc.vextention, 'w', 4000);
   UTL_FILE.put_line(handle, 'LOAD DATA');
   UTL_FILE.put_line(handle, 'INFILE *');
   UTL_FILE.put_line(handle, 'APPEND');
   UTL_FILE.put_line(handle, 'INTO TABLE ' || av_table_name);
   UTL_FILE.put_line(handle, 'FIELDS TERMINATED BY ''`'' OPTIONALLY ENCLOSED BY ''"'' ');
   col_list := '';
   lv_sql := '';

   FOR lc1 IN (SELECT   column_name, data_type
               FROM     user_tab_columns
               WHERE    table_name = UPPER(av_table_name) AND data_type NOT IN('CLOB', 'BLOB')
               ORDER BY column_id) LOOP
    IF lc1.data_type = 'DATE' THEN
     col_list := col_list || ',' || lc1.column_name || ' DATE "dd.mm.yyyy hh24:mi:ss"';
     lv_sql := lv_sql || '|| to_char(' || lc1.column_name || ', ''dd.mm.yyyy hh24:mi:ss'')|| ''`'' ';
    ELSE
     col_list := col_list || ',' || lc1.column_name;
     lv_sql := lv_sql || '||' || lc1.column_name || '|| ''`'' ';
    END IF;
   END LOOP;

   col_list := '(' || SUBSTR(col_list, 2) || ')';
   lv_sql := SUBSTR(lv_sql, 3);
   UTL_FILE.put_line(handle, col_list);
   UTL_FILE.put_line(handle, 'BEGINDATA');
   lv_sql :=
       'select '
    || lv_sql
    || ' from '
    || av_table_name
    || ' where '
    || lc.vindic_column
    || ' <= to_date('''
    || TO_CHAR(ad_date, 'dd.mm.yyyy')
    || ''',''dd.mm.yyyy'')+1 and '
    || lc.vindic_column
    || ' > to_date('''
    || TO_CHAR(ad_date, 'dd.mm.yyyy')
    || ''',''dd.mm.yyyy'') ';

   OPEN rec_cur FOR lv_sql;

   LOOP
    FETCH rec_cur
    INTO  file_row;

    EXIT WHEN rec_cur%NOTFOUND;
    UTL_FILE.put_line(handle, file_row);
   END LOOP;

   CLOSE rec_cur;

   UTL_FILE.fclose(handle);
  END LOOP;

  EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = ''.,''';
 EXCEPTION
  WHEN OTHERS THEN
   UTL_FILE.fclose(handle);

   EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = ''.,''';

   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Перерасчет данных по группе точек за период
 /* Дополнительный параметр представляет собой строку вида сдвиг;ид папки или точки1;ид папки или точки2;ид папки или точки3 и.т.д
    Напрамер: 3;1000 означает перерасчет всех точек учета в папке с ид.=1000 на глубину 3 дня   */
 PROCEDURE recalcpoints(an_maket NUMBER, ad_date DATE) IS
  ln_mid              NUMBER;
  ln_shift            NUMBER;
 BEGIN
  ln_shift := util_pg.allnumber_f(util_pg.get_param(file_pg.gv_param, 1));

  FOR i IN 2 .. LENGTH(file_pg.gv_param) LOOP
   --хватаем Ид точки (ryda.points.mid)
   ln_mid := util_pg.allnumber_f(util_pg.get_param(file_pg.gv_param, i));

   IF ln_mid > 0 THEN                                                                                                    --Проверим что он в дереве точек учета
    SELECT MAX(mid)
    INTO   ln_mid
    FROM   points
    WHERE  mid = ln_mid;

    IF ln_mid IS NULL THEN
     GOTO to_continue;
    END IF;
   ELSE                                                                                          --Закончилась строка file_pg.gv_param (Дополнительный параметр)
    EXIT;
   END IF;

   editfeeders_pg.recalcdiff(ln_mid, ad_date - ln_shift + 1, 1);

   <<to_continue>>
   NULL;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'background01_pg.recalcpoints: ' || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                             -- Package Body BACKGROUND01_PG
/


