-- Start of DDL Script for Package Body RYDA.CALC_PG
-- Generated 14.04.2014 9:34:56 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY calc_pg IS
   gn_Task_Code NUMBER DEFAULT 502;
gn_order NUMBER := 1; -- счетчик строк
gn_group NUMBER; -- id - reportgroup
gn_period NUMBER; -- Период
gd_first DATE; -- Дата окончания прошлого отчетного периода
gd_last  DATE; -- Дата окончания текущего отчетного периода
type t_number is table of number index by BINARY_INTEGER;
gt_consump t_number; -- Сумма расхода подразделения
type t_varchar is table of Varchar2(32) index by BINARY_INTEGER;
gv_type t_varchar;
gv_typeSmall t_varchar;
--==========================================================================================
 --процедура смены периода
 PROCEDURE changeperiod_p IS
  ---------------------------------------------
  ld_1 DATE;
  ld_2 DATE;
  ld_3 DATE;
 ---------------------------------------------
 BEGIN
  BEGIN
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_1
     FROM parameter
    WHERE npid = 1;
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_2
     FROM parameter
    WHERE npid = 2;
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_3
     FROM parameter
    WHERE npid = 3;
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Ошибка заполнения таблицы PARAMETER. ');
  END;
  IF NVL(provcalc_f, 1) != 1 THEN
   raise_application_error(
    -20002, 'ADMIN_PG.changeperiod_p: В данном месяце не проведен расчет. Смена переода расчета запрещена.');
  END IF;
  UPDATE parameter
     SET vvalue = TO_CHAR(ld_3, 'dd.mm.yyyy')
   WHERE npid = 2;
  UPDATE parameter
     SET vvalue = TO_CHAR(ADD_MONTHS(ld_3, 1), 'dd.mm.yyyy')
   WHERE npid = 3;

  admin_pg.fiscal_p(gn_Task_Code,2,'Произведена смена отчетного периода');

 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'ADMIN_PG.changeperiod_p: Ошибка изменения периода. ' || CHR(10) || SQLERRM(SQLCODE));
 END; --changeperiod_p
 ------------------------------------------------------------------------------------------------------------------------
 --процедура смены дня расчета
 PROCEDURE changecalcday_p(an_day NUMBER) IS
  ---------------------------------------------
  ld_3 DATE;
 ---------------------------------------------
 BEGIN
  SAVEPOINT changecalcday_s;
  BEGIN
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_3
     FROM parameter
    WHERE npid = 3;
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Ошибка заполнения таблицы PARAMETER. ');
  END;
  IF an_day IS NULL OR NOT (TRUNC(an_day) BETWEEN 1 AND 31) THEN
   raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Входной параметр процедуры не допустим. ');
  END IF;
  IF TO_DATE(TO_CHAR(ld_3, 'YYYYMM') * 100 + TRUNC(an_day), 'YYYYMMDD') <= SYSDATE THEN
   raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Изменяемая дата не может быть меньше системной. ');
  END IF;
  UPDATE parameter
     SET vvalue = TO_CHAR(TO_DATE(TO_CHAR(ld_3, 'YYYYMM') * 100 + TRUNC(an_day), 'YYYYMMDD'), 'dd.mm.yyyy')
   WHERE npid IN (1, 3);
  DELETE FROM detturnover
        WHERE nperiod = TO_NUMBER(TO_CHAR(ld_3, 'YYYYMM'));
  admin_pg.fiscal_p(gn_Task_Code,2,'Произведена смена расчетного дня');
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT changecalcday_s;
   raise_application_error(-20001, 'ADMIN_PG.changecalcday_p: Ошибка дня расчета. ' || CHR(10) || SQLERRM(SQLCODE));
 END; --changecalcday_p
 ------------------------------------------------------------------------------------------------------------------------
   -- Проверка проведения расчета возвращает 1- Проведен, иначе нет
 FUNCTION provcalc_f
  RETURN NUMBER IS
  ln_count NUMBER;
  ld_3     DATE;
 BEGIN
  SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
    INTO ld_3
    FROM parameter
   WHERE npid = 3;
  SELECT COUNT(*)
    INTO ln_count
    FROM DUAL
   WHERE EXISTS( SELECT *
                   FROM detturnover
                  WHERE nperiod = TO_NUMBER(TO_CHAR(ld_3, 'YYYYMM')));
  RETURN ln_count;
 END;
 ------------------------------------------------------------------------------------------------------------------------

