------------------------------------------------------------------------------------------------------------------------
--Для оптимизации
 gr_transline        edittransformer_line_pg.ttransline;

 --Все по трансформатору иди линии
 PROCEDURE createtranslineinfo(an_id NUMBER);

----------------------------------------------------------------------------------------------------------
 --ПАостроение массива точек, по которым надо выполнить перерасчет (точки, зависимые от an_mid)
 PROCEDURE get_tmp(an_mid NUMBER);

 --ПАостроение массива точек, по которым надо выполнить перерасчет по причине изменения данных в аргументах (переодический расчет)
 PROCEDURE get_calcup(ln_calcup NUMBER);

-----------------------------------------------------------------------------------------------------------------

 --На вход Метка времени зима ()
 PROCEDURE ins_halfhouroldw(
 an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER,
 an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2, an_switch NUMBER DEFAULT NULL,
 an_source NUMBER DEFAULT NULL, an_calc NUMBER DEFAULT NULL, an_lockcopyw NUMBER DEFAULT 0, an_nqm NUMBER DEFAULT NULL, an_round NUMBER DEFAULT 3
 );

