 PROCEDURE getval_vinn(ar_info tcalcinfo, ad_from DATE, ad_till DATE);

 PROCEDURE getvalm(an_sum NUMBER, an_gnsum NUMBER, an_cnt NUMBER, at_ret IN OUT common_pg.tt_double);

------------------------------------------------------------------------------------------------------------------------

 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calcw(ad_from DATE, ad_till DATE, an_mid NUMBER, an_calctype NUMBER) IS
  cn_cnt              NUMBER := 48;                                                                                                               --Шаг расчета
  z1                  NUMBER;
  z2                  NUMBER;
  ln_ret              NUMBER;
  lr_info             tcalcinfo;
  lt_info             ttcalcinfo;
  lr_param            tparaminfo;
  lt_param            ttparaminfo;
  lt_paramval         common_pg.tt_double;
  lt_qm               common_pg.tt_varchar2;
  ln_cnt              NUMBER DEFAULT 0;
  ln_pcnt             NUMBER;
  ln_maxmeas          NUMBER;
  val                 DOUBLE PRECISION;
  ld_from             DATE DEFAULT util_pg.trunchh24_2(ad_from);
  ld_till             DATE DEFAULT util_pg.trunchh24_2(ad_till);
  ld_froml            DATE DEFAULT util_pg.to_localtime(ld_from);
  ld_tilll            DATE DEFAULT util_pg.to_localtime(ld_till);
  ld_tmp              DATE;
  ld_calcperiod       DATE DEFAULT admin_pg.get_calcperiod;
  ln_itemcnt          NUMBER;
  invert              NUMBER;
  lv_sql              VARCHAR2(4000);
  cr_sel              common_pg.tcur;
  lv_formula          VARCHAR2(4000);
  la_val              numarray := numarray();
  ln_ntw              NUMBER;
  ln_nts              NUMBER;
  ln_timeshift        NUMBER;
  ld_fromm            DATE;
  ld_tillg            DATE;
  ld_fromg            DATE;
  ld_test             NUMBER;
  ln_evr              NUMBER := 0;
  lv_subsel           VARCHAR2(1000);
------------------------
  tt_info             tcalcinfo;
  ld_fromh            DATE;
  lv_vqm              VARCHAR2(32);
  ld_tmpr             DATE;
  ln_shiftdate        NUMBER;
  lb_withusing BOOLEAN;
-----------------------------
 BEGIN
  IF an_mid IS NULL THEN
   lv_sql :=
       'select tt.nid , tt.nmeas ,tt.vformula , tt.mid, tt.realcnt, tt.nopttype,
      tt.nswitch , tt.ntimezonew, tt.ntimezones, tt.NHOURERIOD,
      tt.NDIVTYPE ,tt.norder, tt.nform from 
      (
      SELECT   f.nid, f.nmeas,trim(replace(replace(f.vformula,chr(10),chr(32)),chr(13),chr(32))) vformula, f.mid, DECODE (f.nmeas, 0, '
    || cn_meas
    || ', 1) realcnt, NVL (f.nopttype, 0) nopttype, NVL (fd.nswitch, 0) nswitch ,NVL (fd.ntimezonew, 2) ntimezonew, NVL (fd.ntimezones, 3) ntimezones '
    || ', f.NHOURERIOD, f.NDIVTYPE, f.norder, 0 nform '
    || 'FROM pointformula f, feeders fd WHERE f.mid = fd.mid(+) AND fd.ncalcpointtype = '
    || cn_cpt_formula
    || ' union all
      SELECT g.mid nid , 0 nmeas ,'''' vformula , g.mid, 6  realcnt, 0 nopttype,
      0 nswitch , 2 ntimezonew, 3 ntimezones, 0 NHOURERIOD,
      0 NDIVTYPE ,g.norder, g.ntype nform
      from greenpoint g 
      ORDER BY norder, nid ) tt WHERE 1=1 ';                                                                
   IF an_calctype = 1 THEN
/*    lv_sql :=
        lv_sql
     || ' AND tt.mid IN (SELECT mid FROM lastrecforrecalc where ddate=to_date('''
     || TO_CHAR(util_pg.to_localtime(ld_from), 'DD.MM.YYYY')
     || ''',''DD.MM.YYYY'') )';*/
    lb_withusing:=true; 
    lv_sql :=
        lv_sql
     || ' AND tt.mid IN (SELECT mid FROM lastrecforrecalc where ddate=:dat)';
   END IF;
  ELSE
   get_tmp(an_mid);
   lv_sql :=
       ' SELECT   f.nid, f.nmeas,trim(replace(replace(f.vformula,chr(10),chr(32)),chr(13),chr(32))) vformula, f.mid, DECODE (f.nmeas, 0, '
    || cn_meas
    || ', 1) realcnt, NVL (f.nopttype, 0) nopttype, NVL (fd.nswitch, 0) nswitch ,NVL (fd.ntimezonew, 2) ntimezonew, NVL (fd.ntimezones, 3) ntimezones '
    || ', f.NHOURERIOD, f.NDIVTYPE, f.norder, 0 nform '
    || ' FROM pointformula f, feeders fd, lastrecforrecalc r WHERE f.mid = fd.mid(+) AND f.mid=r.mid AND r.ntype=0
      UNION ALL 
      SELECT g.mid nid , 0 nmeas ,'''' vformula , g.mid, 6  realcnt, 0 nopttype,
      0 nswitch , 2 ntimezonew, 3 ntimezones, 0 NHOURERIOD,
      0 NDIVTYPE ,g.norder, g.ntype nform
      from greenpoint g, lastrecforrecalc r WHERE g.mid=r.mid AND r.ntype<>0
      ORDER BY norder, nid ';
  END IF;

 -- lv_sql := lv_sql || ' ORDER BY f.norder, f.nid';
--delete from tmp_vil;
--insert into tmp_vil values (lv_sql);commit;
--FOR lc5 IN (select mid,ntype from lastrecforrecalc)LOOP
-- insert into tmp_vil values (lc5.mid||' '||lc5.ntype);commit;
--END LOOP;
  IF lb_withusing THEN
	  OPEN cr_sel FOR lv_sql USING trunc(util_pg.to_localtime(ld_from));	
  ELSE
 	 OPEN cr_sel FOR lv_sql;
  END IF;

  LOOP
   FETCH cr_sel
   INTO  lr_info.ID, lr_info.meas, lv_formula, lr_info.mid, lr_info.realcnt, lr_info.nopttype, lr_info.nswitch, lr_info.ntw, lr_info.nts, lr_info.nhoureriod,
         lr_info.ndivtype, lr_info.norder, lr_info.nform;

   EXIT WHEN cr_sel%NOTFOUND;
   --Читаем и parse
   --del_halfhouroldw (lc.mid, ld_from, ld_till);
   ln_cnt := ln_cnt + 1;
   lr_info.er := util_pg.cn_random;
   lr_info.ed := util_pg.cn_random;
   lr_info.q1 := util_pg.cn_random;
   lr_info.q3 := util_pg.cn_random;
   lr_info.q2 := util_pg.cn_random;
   lr_info.q4 := util_pg.cn_random;
   lr_info.qm := qm_pg.okqm;                                                                                                               --NULL;--qm_pg.okqm;

   IF (lr_info.nhoureriod = 1) THEN
    cn_cnt := 24;
   ELSE
    cn_cnt := 48;
   END IF;

   ln_itemcnt := ROUND((ld_till - ld_from) * cn_cnt);

   IF NOT(
          (NVL(lr_info.nopttype, 0) = editformula_pg.cn_opttype1 AND util_pg.cn_tzw = lr_info.ntw)
          OR(
             NVL(lr_info.nopttype, 0) IN
                    (editformula_pg.cn_opttype2, editformula_pg.cn_opttype4, editformula_pg.cn_opttype5, editformula_pg.cn_opttype7, editformula_pg.cn_opttype8)
            )
          OR(lr_info.nform IN(1, 2))
         ) THEN
    --Оптимизированные идут мимо DLL
    lr_info.idexpr := parser_pg.newexpression(lv_formula);

    IF lr_info.idexpr < 0 THEN
     raise_application_error(-20001, 'Ошибка компиляции формулы. ' || parser_pg.getparsererrortext);
    END IF;
   ELSE
    lr_info.idexpr := -1;
   END IF;

   lt_info(ln_cnt) := lr_info;
  END LOOP;

  CLOSE cr_sel;

  --Расчет
  FOR i IN 1 .. ln_cnt LOOP
   lr_info := lt_info(i);
   ln_pcnt := 0;
   ln_evr := 0;

   IF (lt_info(i).nhoureriod = 1) THEN
    cn_cnt := 24;
   ELSE
    cn_cnt := 48;
   END IF;

   ln_itemcnt := ROUND((ld_till - ld_from) * cn_cnt);

   IF admin_pg.lockrow_p(30, 'FEEDERS', 'MID', lr_info.mid) <= 0 THEN
    raise_application_error(-20001, 'Проблема блокировки. ');
   END IF;

   IF lr_info.nopttype = editformula_pg.cn_opttype1 AND util_pg.cn_tzw = lr_info.ntw THEN
    --Линейная оптимизация
    calc_opotim1w(lr_info, ld_from, ld_till);
   ELSIF lr_info.nopttype IN(editformula_pg.cn_opttype2, editformula_pg.cn_opttype4, editformula_pg.cn_opttype7, editformula_pg.cn_opttype8) THEN
    getval_30817w(lr_info, ld_from, ld_till);
   ELSIF lr_info.nopttype = editformula_pg.cn_opttype5 THEN
    getval_vinn(lr_info, ld_from, ld_till);
   ELSIF lr_info.nopttype = editformula_pg.cn_opttype6 AND util_pg.cn_tzw = lr_info.ntw THEN
    calc_sum_group(lr_info, ld_from, ld_till);
   ELSIF lr_info.nform = 1 THEN
    copyw(ad_from, ad_till, lr_info.mid, 0, an_calctype);
   ELSIF lr_info.nform = 2 THEN
    IF TRUNC(util_pg.to_localtime(ad_from)) < TRUNC(SYSDATE) THEN
     recalcaverrate(util_pg.to_localtime(ad_from), lr_info.mid, an_calctype);
    END IF;
   ELSE                                                                                   --Если дописал elsif добавь в создание формулы parser_pg.newexpression
    --Сохранили все параметры
    FOR lc IN (SELECT   TRIM(vname) vname, UPPER(TRIM(vparam)) vparam, norder, NVL(nshift / 24, 0) nshift
               FROM     formulparams
               WHERE    nid = lr_info.ID
               ORDER BY norder) LOOP                                                                                                    --Цикл по всем формулам
     ln_pcnt := ln_pcnt + 1;
     lr_param.vname := lc.vname;
     lr_param.norder := lc.norder;
     lr_param.vparam := lc.vparam;
     lr_param.nshift := lc.nshift;
     lt_param(ln_pcnt) := lr_param;
    END LOOP;

    ln_evr := 0;
    la_val.DELETE;
    la_val.EXTEND(ln_pcnt);
    -- z1 := cn_meas * ln_itemcnt;                                                                                                --z1,z2 не надо может так быстрее
    ln_timeshift := util_pg.cn_tzw - lr_info.ntw;

    IF lr_info.ntw = lr_info.nts THEN
     ln_evr := 1;

     IF (util_pg.is_summer(ld_from) = 1) THEN
      ld_fromg := ld_from + ln_timeshift / 24 + 1 / 24;
      ln_shiftdate := lr_param.nshift + ln_timeshift / 24 + 1 / 24;
     ELSE
      ld_fromg := ld_from + ln_timeshift / 24;
      ln_shiftdate := lr_param.nshift + ln_timeshift / 24;
     END IF;

     IF (util_pg.is_summer(ld_till) = 1) THEN
      ld_tillg := ld_till + ln_timeshift / 24 + 1 / 24;
     --  ln_shiftdate:=lr_param.nshift + ln_timeshift / 24 + 1 / 24;
     ELSE
      ld_tillg := ld_till + ln_timeshift / 24;
     -- ln_shiftdate:=lr_param.nshift + ln_timeshift / 24 ;
     END IF;
    ELSE
     -- ln_evr := 0;
     ld_fromg := ld_from + ln_timeshift / 24;
     ld_tillg := ld_till + ln_timeshift / 24;
     ln_shiftdate := lr_param.nshift + ln_timeshift / 24;
    END IF;

      -- IF lr_info.ntw = lr_info.nts THEN
    --  ln_itemcnt := ROUND((util_pg.to_localtime(ld_tillg) - util_pg.to_localtime(ld_fromg)) * cn_cnt);
    ln_itemcnt :=
     ROUND((ld_tillg - ld_fromg) * cn_cnt
      - (2 * util_pg.is_dayswitch(util_pg.to_localtime(ld_tillg))) / cn_cnt
      - (2 * util_pg.is_dayswitch(util_pg.to_localtime(ld_fromg))) / cn_cnt);
--insert into tmp_vil values (ln_itemcnt||' '||to_char(util_pg.to_localtime(ld_tillg),'dd.mm.yyyy hh24:mi:ss')||' '||to_char(util_pg.to_localtime(ld_fromg),'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_tillg,'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_fromg,'dd.mm.yyyy hh24:mi:ss'));commit;
    z1 := cn_meas * ln_itemcnt;

    --  ELSE
     --  ln_itemcnt := ROUND((ld_till - ld_from) * cn_cnt);
     -- END IF;
    FOR k IN 1 .. ln_pcnt LOOP                                                                                   --Ищем значения Цикл по всем параметрам формулы
     z2 := k - 1;

     FOR j IN 1 .. z1 LOOP
      lt_paramval(z2 * z1 + j) := NULL;
--      lt_qm(z2 * z1 + j) := qm_pg.nodataqm;
      lt_qm(z2 * z1 + j) := NULL;                                                                                                                 --qm_pg.okqm;
     END LOOP;

     --Надо проверить  ld_till+lt_param (k).nshift при переходе зима лето при lt_param (k).nshift<>0 как бы не улететь за границы массивов
     lr_param := lt_param(k);
     getvalw(lr_param.vparam, ld_fromg + lr_param.nshift, ld_tillg + lr_param.nshift, k, lt_paramval, lt_qm, ln_evr, ln_itemcnt, ln_shiftdate, cn_cnt);
--  getvalw(lr_param.vparam, ld_fromg + lr_param.nshift, ld_tillg + lr_param.nshift, k, lt_paramval, lt_qm, ln_evr, cn_cnt, ln_shiftdate);
    END LOOP;

    /*  IF ln_evr = 1 THEN
      -- ln_itemcnt := ln_itemcnt - ln_cnt / 24 * util_pg.is_dayswitch(ld_from)- ln_cnt / 24 * util_pg.is_dayswitch(ld_till);
      --  ln_itemcnt := cn_cnt; --ln_itemcnt - ln_cnt / 24 * util_pg.is_dayswitch(ld_froml);
        ln_itemcnt :=  ln_itemcnt - cn_cnt / 24 * util_pg.is_dayswitch(ld_from);
    --  delete from tmp_vil;
     --  insert into tmp_vil values(lr_info.mid||' '||ln_itemcnt);commit;
      ELSE
         ln_itemcnt := ROUND((ld_till - ld_from) * cn_cnt);
      END IF;*/

    --Конец цикла по всем параметрам формулы
    FOR l IN 1 .. ln_itemcnt LOOP                                                                                                                --Цикл по датам
     lr_info := lt_info(i);

     FOR j IN 1 .. lr_info.realcnt LOOP                                                                            --Цикл по всем измерениям (для общих формул)
      z2 := (j - 1) * ln_itemcnt + l;
      -- lv_vqm:=qm_pg.okqm;--lr_info.qm;
      lv_vqm := NULL;                                                                                        --если нет параметров например в формуле константа

      FOR k IN 1 .. ln_pcnt LOOP                                                                                                           --Цикл по параметрам
       IF k = 1 THEN
        lv_vqm := lt_qm((k - 1) * z1 + z2);
        lr_info.qm := lv_vqm;
       ELSE
        lr_info.qm := qm_pg.sumqm(lv_vqm, lt_qm((k - 1) * z1 + z2));
        lv_vqm := lr_info.qm;
       END IF;

       --  lr_info.qm := qm_pg.sumqm(lr_info.qm, lt_qm((k - 1) * z1 + z2));
       la_val(k) := NVL(lt_paramval((k - 1) * z1 + z2), 0);
      END LOOP;

      lr_info.qm := lv_vqm;
      ln_ret := parser_pg.setvarsora(lr_info.idexpr, la_val);

      --insert into tmp_saa(k,j,fid,dat,val,pname) values(k,j,lr_info.ID,ld_date,val,lt_param (k).vparam||'___'||lt_param (k).vname);
      IF ln_ret <> 0 THEN
       raise_application_error(-20001, 'Ошибка задания входных параметров формулы ' || parser_pg.getparsererrortext(ln_ret));
      END IF;

      val := 0;
      ln_ret := parser_pg.evaluate(lr_info.idexpr, val);

      IF ln_ret <> 0 THEN
       raise_application_error(-20001, 'Ошибка вычисления формулы. ' || parser_pg.getparsererrortext(ln_ret));
      END IF;

      IF (ABS(val) > cn_maxmumber) OR(TO_CHAR(val) IS NULL AND val IS NOT NULL) THEN
       --Это борьба с делением на 0 и прочими херовыми числами типа 1/asin(100032)
       val := 0;
      END IF;

      --insert into tmp_saa(k,j,fid,dat,val,pname) values(0,j,lr_info.ID,ld_date,val,'Ret'||lr_info.meas);
      IF lr_info.meas = 1 OR(lr_info.meas = 0 AND j = 1) THEN
       lr_info.er := val;
      ELSIF lr_info.meas = 2 OR(lr_info.meas = 0 AND j = 2) THEN
       lr_info.ed := val;
      ELSIF lr_info.meas = 3 OR(lr_info.meas = 0 AND j = 3) THEN
       lr_info.q1 := val;
      ELSIF lr_info.meas = 4 OR(lr_info.meas = 0 AND j = 4) THEN
       lr_info.q2 := val;
      ELSIF lr_info.meas = 5 OR(lr_info.meas = 0 AND j = 5) THEN
       lr_info.q3 := val;
      ELSIF lr_info.meas = 6 OR(lr_info.meas = 0 AND j = 6) THEN
       lr_info.q4 := val;
      END IF;
     END LOOP;

----------------------------------------------------------------VNB 6.10.2010
     IF lr_info.ntw = lr_info.nts THEN
      IF (
          (util_pg.is_summer(ld_from + l / cn_cnt) = 1 OR util_pg.is_dayswitch(util_pg.to_localtime(ld_from + l / cn_cnt)) = -1)
          --  (util_pg.is_summer(ld_from ) = 1 OR util_pg.is_dayswitch(util_pg.to_localtime(ld_from )) = -1)
          AND util_pg.is_dayswitch(ld_till) <> 1
         ) THEN
       ld_fromm := ld_from + ln_timeshift / 24 + 1 / 24 + l / cn_cnt;
      -- insert into tmp_vil values(to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||' '||l ||' '||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||' '||ln_timeshift||' '||lr_info.meas||' '||lr_info.mid||' '||to_char(ld_fromm,'dd.mm.yyyy hh24:mi:ss')||' '||lr_info.er||' '||ln_timeshift||' '||ln_itemcnt||' '||ln_evr);commit;
      ELSE
       ld_fromm := ld_from + ln_timeshift / 24 + l / cn_cnt;
      END IF;
     ELSE
      ld_fromm := ld_from + l / cn_cnt;
     END IF;

------------------------------------------------------------------------------------------
     IF lr_info.nhoureriod = 1 THEN
      FOR i IN 1 .. 2 LOOP
       ld_fromh := ld_fromm;
       tt_info := lr_info;
       gethourperiod(i, tt_info.ndivtype, ld_fromh, tt_info.er, tt_info.ed, tt_info.q1, tt_info.q2, tt_info.q3, tt_info.q4);
       ins_halfhouroldw(tt_info.mid, ld_fromh, tt_info.er, tt_info.ed, tt_info.q1, tt_info.q3, tt_info.q2, tt_info.q4, NULL, comsrv_pg.cn_calc, tt_info.qm,
        tt_info.nswitch, NULL, 1, 1);
      END LOOP;
     ELSE
      ins_halfhouroldw(lr_info.mid, ld_fromm, lr_info.er, lr_info.ed, lr_info.q1, lr_info.q3, lr_info.q2, lr_info.q4, NULL, comsrv_pg.cn_calc, lr_info.qm,
       lr_info.nswitch, NULL, 1, 1);
     END IF;
    END LOOP;                                                                                                                             --Конец цикла по датам

    la_val.DELETE;
    lt_paramval.DELETE;
    lt_param.DELETE;
   END IF;

   --Чтоб считать bill по заднему числуу
   calcpoint4bill(lr_info.mid, TRUNC(ld_froml), TRUNC(LEAST(ld_tilll, ld_calcperiod + 1)));
   COMMIT;
  END LOOP;                                                                                                                       --Конец цикла по всем формулам

  --Очистка памяти
  FOR i IN 1 .. ln_cnt LOOP
   lr_info := lt_info(i);

   --Очистка памяти
   IF lr_info.idexpr > -1 THEN                                                                                                 --Оптимизированные идут мимо DLL
    ln_ret := parser_pg.deleteexpression(lr_info.idexpr);
   END IF;
  END LOOP;

  lt_info.DELETE;
 -- DELETE from lastrecforrecalc;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'calcformula_pg.calcw: ИД=''' || lr_info.ID || ''' ТУ=''' || lr_info.mid || '''' || CHR(10) || SQLERRM);
 END;

------------------------------------------------------------------------------------------------------------------------
--Копирование на точки
 PROCEDURE copyw(ad_from DATE, ad_till DATE, an_mid NUMBER, an_copytype NUMBER, an_calctype NUMBER) IS
  --an_copytype - 1 кто не имеет детей расчетных 2 - кто имеет детей расчетных иначе всех
  ld_from             DATE DEFAULT util_pg.trunchh24_2(ad_from);
  ld_till             DATE DEFAULT util_pg.trunchh24_2(ad_till);
  ld_froml            DATE DEFAULT util_pg.to_localtime(ld_from);
  ld_tilll            DATE DEFAULT util_pg.to_localtime(ld_till);
  lv_qm               VARCHAR2(32);
  ld_tmp              DATE;
  ld_calcperiod       DATE DEFAULT admin_pg.get_calcperiod;
  lv_sql              VARCHAR2(4000);
  ln_mid              NUMBER := an_mid;
  ln_switch           NUMBER := NULL;
  ln_validity         NUMBER;
  ln_source           NUMBER;
  ln_midblue          NUMBER;
  ln_nqm              NUMBER;
 BEGIN
  ld_tmp := ld_from;

----------------------------------------- Качество энергии VNB 16.09.10
  SELECT MAX(p.mid)
  INTO   ln_midblue
  FROM   points p,
         (SELECT ch.mid
          FROM   channels c, chanpoint ch
          WHERE  c.protocol_id IN(110, 107) AND c.cid = ch.cid) hh
  WHERE  p.PARENT = ln_mid AND p.mid = hh.mid;

  IF admin_pg.lockrow_p(30, 'FEEDERS', 'MID', ln_mid) <= 0 THEN
   raise_application_error(-20001, 'Проблема блокировки. ');
  END IF;

-------------------------------------------------------------------------------------
  FOR lc1 IN (SELECT   t0.date_time, qm_pg.rungqm(t0.vqm) rungqm, t0.norder, t0.vname, t0.mid, t0.er, t0.ed, t0.q1, t0.q3, t0.q2, t0.q4, t0.erm, t0.edm, t0.q1m,
                       t0.q3m, t0.q2m, t0.q4m, t0.vqm, t0.nsource, t0.nmainpoint, t0.snvalidity, t0.snsource
              FROM     (SELECT t.date_time, qm_pg.rungqm(t.vqm) rungqm, NVL(r.norder, p.norder) norder, p.NAME vname, t.mid, t.er, t.ed, t.q1, t.q3, t.q2, t.q4,
                               t.erm, t.edm, t.q1m, t.q3m, t.q2m, t.q4m,
                               DECODE(
                                SIGN(DECODE(SIGN(f.nintegralperiod - 30), 1, 1, 30 / f.nintegralperiod) - t.rowcnt),
                                1, qm_pg.sumqm(t.vqm, qm_pg.nodataqm),
                                t.vqm
                               ) vqm,
                               t.nsource, f.nmainpoint, s.nvalidity snvalidity, s.nsource snsource
                        FROM   (SELECT   h.mid, util_pg.ceilhh24_2(util_pg.to_unlocaltime(h.date_time, h.nsource)) date_time, SUM(h.er) er, SUM(h.ed) ed,
                                         SUM(h.q1) q1, SUM(h.q3) q3, SUM(h.q2) q2, SUM(h.q4) q4, MAX(h.erm) erm, MAX(h.edm) edm, MAX(h.q1m) q1m, MAX(h.q3m) q3m,
                                         MAX(h.q2m) q2m, MAX(h.q4m) q4m, NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm) vqm, COUNT(*) rowcnt,
                                         MAX(h.nsource) nsource
                                FROM     halfhour h
                                WHERE    h.mid IN(SELECT NVL(mid, 0)
                                                  FROM   points
                                                  WHERE  PARENT = ln_mid AND ind = 3) AND h.date_time > ld_from AND h.date_time <= ld_till + 1 / 24
                                         AND util_pg.to_unlocaltime(h.date_time, h.nsource) > ld_from
                                         AND util_pg.to_unlocaltime(h.date_time, h.nsource) <= ld_till
                                GROUP BY h.mid, util_pg.ceilhh24_2(util_pg.to_unlocaltime(h.date_time, h.nsource))) t,
                               (SELECT t.mid, t.norder
                                FROM   points p, priority t
                                WHERE  p.PARENT = ln_mid AND p.mid = t.mid AND ld_froml >= t.dstart AND ld_froml < t.dend) r,
                               feeders f,
                               points p,
                               sourcetypes s
                        WHERE  t.mid = f.mid(+) AND t.mid = r.mid(+) AND t.mid = p.mid(+) AND p.ptype = s.ptype(+)) t0
              ORDER BY 1, 2, 3, 4, 5) LOOP
   WHILE ld_tmp + cn_step < lc1.date_time LOOP                                                                                                 --Пустые вставки
    lv_qm := qm_pg.sbt(qm_pg.nodataqm, 17, qm_pg.cn_add_insuff);                                                --Ставим бит восстановления по первичным данным
    ins_halfhouroldw(ln_mid, ld_tmp + cn_step, NULL, NULL, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, lv_qm, ln_switch, NULL, 1, 1);
    ld_tmp := ld_tmp + cn_step;
   END LOOP;

   IF ld_tmp + cn_step = lc1.date_time THEN
    IF SUBSTR(lc1.vqm, 1, 1) IN(qm_pg.cn_ok, qm_pg.cn_question, qm_pg.cn_invalid, qm_pg.cn_reserv) THEN
     --19.01.2011 раньше было IF SUBSTR(lc1.vqm, 1, 1) IN(qm_pg.cn_ok, qm_pg.cn_question) THEN
     lv_qm := lc1.vqm;

     IF SUBSTR(lv_qm, 1, 1) = qm_pg.cn_ok THEN
      lv_qm := qm_pg.sbt(lv_qm, 17, qm_pg.cn_add_ok);                                                           --Ставим бит восстановления по первичным данным
     ELSE
      lv_qm := qm_pg.sbt(lv_qm, 17, qm_pg.cn_add_err);                                                          --Ставим бит восстановления по первичным данным
     END IF;

     IF lc1.snsource > 0 THEN                                                                                                          --Явное задание источника
      lv_qm := qm_pg.sbt(lv_qm, 22, lc1.snsource);                                                                                                     --Ручник
     ELSE
      IF lc1.nsource IN(util_pg.cn_manualinput, util_pg.cn_manualinputw) THEN
       lv_qm := qm_pg.sbt(lv_qm, 22, qm_pg.cn_manual);                                                                                                 --Ручник
      ELSIF lc1.nmainpoint <> 0 THEN
       lv_qm := qm_pg.sbt(lv_qm, 22, qm_pg.cn_dupl);                                                                                                    --Дубль
      END IF;
     END IF;

---------------------------------------------------VNB 16.09.10
     IF ln_midblue IS NOT NULL THEN
      ln_nqm := set_qe(ln_midblue, lc1.date_time, lc1.nsource);
     ELSE
      ln_nqm := NULL;
     END IF;

-------------------------------------------------------------------------------end;
     ins_halfhouroldw(ln_mid, lc1.date_time, lc1.er, lc1.ed, lc1.q1, lc1.q3, lc1.q2, lc1.q4, lc1.erm, lc1.edm, lc1.q1m, lc1.q3m, lc1.q2m, lc1.q4m, NULL,
      comsrv_pg.cn_calc, lv_qm, ln_switch, NULL, 1, 1, ln_nqm);
    ELSE
     lv_qm := qm_pg.sbt(lc1.vqm, 17, qm_pg.cn_add_err);                                                         --Ставим бит восстановления по первичным данным
     ins_halfhouroldw(ln_mid, lc1.date_time, NULL, NULL, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, lv_qm, ln_switch, NULL, 1, 1);
    END IF;

    ld_tmp := lc1.date_time;
   END IF;
  END LOOP;

  ld_tmp := ld_tmp + cn_step;

  WHILE ld_tmp <= ld_till LOOP                                                                                                                  --Пустые вставки
   lv_qm := qm_pg.sbt(qm_pg.nodataqm, 17, qm_pg.cn_add_insuff);                                                 --Ставим бит восстановления по первичным данным
   ins_halfhouroldw(ln_mid, ld_tmp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, lv_qm, ln_switch, NULL, 1, 1);
   ld_tmp := ld_tmp + cn_step;
  END LOOP;

  --Чтоб считать bill по заднему числуу
  calcpoint4bill(ln_mid, TRUNC(ld_froml), TRUNC(LEAST(ld_tilll, ld_calcperiod + 1)));
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'calcformula_pg.copyw: Ид.=' || ln_mid || ' ' || SQLERRM);
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calc_opotim1w(ar_info tcalcinfo, ad_from DATE, ad_till DATE) IS
  ld_fromh            DATE;
  ner                 NUMBER;
  ned                 NUMBER;
  nq1                 NUMBER;
  nq2                 NUMBER;
  nq3                 NUMBER;
  nq4                 NUMBER;
  ln_cnt              NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_cnt
  FROM   formulparams
  WHERE  nid = ar_info.ID;

  FOR lc IN (SELECT     ad_from
                      +   get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + f.nshift, DECODE(ar_info.nhoureriod, 1, 24, 48))
                        / DECODE(ar_info.nhoureriod, 1, 24, 48) date_time,
                      SUM(f.nsign * DECODE(vparam3, 'AI', h.ed, h.er)) er, SUM(f.nsign * DECODE(vparam3, 'AI', h.er, h.ed)) ed,
                      SUM(f.nsign * DECODE(vparam3, 'AI', h.q3, h.q1)) q1, SUM(f.nsign * DECODE(vparam3, 'AI', h.q1, h.q3)) q3,
                      SUM(f.nsign * DECODE(vparam3, 'AI', h.q4, h.q2)) q2, SUM(f.nsign * DECODE(vparam3, 'AI', h.q2, h.q4)) q4,
                      
                      --sumqm(h.vqm) vqm
                      DECODE(
                       COUNT(DISTINCT f.mid),
                       ln_cnt, NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm),
                       qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
                      ) vqm
             FROM     (SELECT p.nshift / 24 nshift, NVL(SIGN(p.nsign), 1) nsign, p.mid, TRIM(UPPER(util_pg.get_param(p.vparam, 3, cv_d))) vparam3
                       FROM   formulparams p
                       WHERE  nid = ar_info.ID) f,
                      halfhour h
             WHERE    f.mid = h.mid AND h.date_time > ad_from + f.nshift AND h.date_time <= ad_till + f.nshift + 1 / 24
                      AND util_pg.to_unlocaltime(h.date_time, h.nsource) > ad_from + f.nshift
                      AND util_pg.to_unlocaltime(h.date_time, h.nsource) <= ad_till + f.nshift
             GROUP BY   ad_from
                      +   get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + f.nshift, DECODE(ar_info.nhoureriod, 1, 24, 48))
                        / DECODE(ar_info.nhoureriod, 1, 24, 48)
             ORDER BY 1) LOOP
----------------------------------------------------
   IF ar_info.nhoureriod = 1 THEN
    FOR i IN 1 .. 2 LOOP
     IF ar_info.ndivtype = 1 THEN
      IF i = 1 THEN
       ld_fromh := lc.date_time - 1 / 48;
       ner := TRUNC(lc.er / 2);
       ned := TRUNC(lc.ed / 2);
       nq1 := TRUNC(lc.q1 / 2);
       nq2 := TRUNC(lc.q2 / 2);
       nq3 := TRUNC(lc.q3 / 2);
       nq4 := TRUNC(lc.q4 / 2);
      ELSE
       ld_fromh := lc.date_time;
       ner := lc.er - TRUNC(lc.er / 2);
       ned := lc.ed - TRUNC(lc.ed / 2);
       nq1 := lc.q1 - TRUNC(lc.q1 / 2);
       nq2 := lc.q2 - TRUNC(lc.q2 / 2);
       nq3 := lc.q3 - TRUNC(lc.q3 / 2);
       nq4 := lc.q4 - TRUNC(lc.q4 / 2);
      END IF;
     ELSE
      IF i = 1 THEN
       ld_fromh := lc.date_time - 1 / 48;
       ner := ROUND(lc.er - lc.er);
       ned := ROUND(lc.ed - lc.ed);
       nq1 := ROUND(lc.q1 - lc.q1);
       nq2 := ROUND(lc.q2 - lc.q2);
       nq3 := ROUND(lc.q3 - lc.q3);
       nq4 := ROUND(lc.q4 - lc.q4);
      ELSE
       ld_fromh := lc.date_time;
       ner := lc.er;
       ned := lc.ed;
       nq1 := lc.q1;
       nq2 := lc.q2;
       nq3 := lc.q3;
       nq4 := lc.q4;
      END IF;
     END IF;

---------------------------------------------------------
     ins_halfhouroldw(ar_info.mid, ld_fromh, ner, ned, nq1, nq3, nq2, nq4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1);
    END LOOP;
   ELSE
    ins_halfhouroldw(ar_info.mid, lc.date_time, lc.er, lc.ed, lc.q1, lc.q3, lc.q2, lc.q4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1);
   END IF;
  END LOOP;
 END;

