 PROCEDURE calc_sum_group(ar_info tcalcinfo, ad_from DATE, ad_till DATE) IS
  ld_fromh            DATE;
  ner                 NUMBER;
  ned                 NUMBER;
  nq1                 NUMBER;
  nq2                 NUMBER;
  nq3                 NUMBER;
  nq4                 NUMBER;
  ln_cnt              NUMBER;
  ln_kc               NUMBER;
  ln_nshift           NUMBER;
  ln_nsign            NUMBER;
  ln_gid              NUMBER;
  lv_vparam           VARCHAR2(30);
 BEGIN
  /* SELECT COUNT(*)
   INTO   ln_cnt
   FROM   formulparams
   WHERE  nid = ar_info.ID;*/
  SELECT MAX(p.nshift / 24) nshift, MAX(NVL(SIGN(p.nsign), 1)) nsign, MAX(TRIM(UPPER(util_pg.get_param(p.vparam, 2, '.')))) gid,
         MAX(TRIM(UPPER(util_pg.get_param(p.vparam, 3, cv_d)))) vparam3
  INTO   ln_nshift, ln_nsign, ln_gid, lv_vparam
  FROM   formulparams p
  WHERE  nid = ar_info.ID;

--  ln_cnt:=1;
 -- ln_kc := 1;
  ln_kc := NVL(util_pg.get_multiplier(ar_info.mid, ad_from), 1);

  IF util_pg.get_customer_id = 10 AND ln_kc <> 0 THEN                                                                                                --Захотели
   ln_kc := 1 / ln_kc;
  END IF;

  IF util_pg.get_customer_id = 1 THEN
   FOR lc IN (SELECT     ad_from
                       +   get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_nshift, DECODE(ar_info.nhoureriod, 1, 24, 48))
                         / DECODE(ar_info.nhoureriod, 1, 24, 48) date_time,
                       SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))) * ln_kc er,
                       SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))) * ln_kc ed,
                       SUM(DECODE(g.inverted, 'y', h.q3 * DECODE(g.npartly, 1, 0, 1), h.q1 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q1,
                       SUM(DECODE(g.inverted, 'y', h.q1 * DECODE(g.npartly, 2, 0, 1), h.q3 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q3,
                       SUM(DECODE(g.inverted, 'y', h.q4 * DECODE(g.npartly, 1, 0, 1), h.q2 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q2,
                       SUM(DECODE(g.inverted, 'y', h.q2 * DECODE(g.npartly, 2, 0, 1), h.q4 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q4, sumqm(h.vqm) vqm
              /*  DECODE(
                 COUNT(DISTINCT g.mid),
                 ln_cnt, NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm),
                 qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
                ) vqm*/
              FROM     halfhour h, GROUPS g
              WHERE    g.mid = h.mid AND h.date_time > ad_from + ln_nshift AND h.date_time <= ad_till + ln_nshift + 1 / 24
                       AND util_pg.to_unlocaltime(h.date_time, h.nsource) > ad_from + ln_nshift
                       AND util_pg.to_unlocaltime(h.date_time, h.nsource) <= ad_till + ln_nshift
                       AND g.gid IN(SELECT     gid
                                    FROM       GROUPS
                                    CONNECT BY ((PRIOR gid = PARENT) OR(PRIOR nroot2 = nroot2 AND PRIOR nroot1 > 0 AND nroot1 IS NULL))
                                    START WITH gid = ln_gid)
              GROUP BY   ad_from
                       +   get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_nshift, DECODE(ar_info.nhoureriod, 1, 24, 48))
                         / DECODE(ar_info.nhoureriod, 1, 24, 48)
              ORDER BY 1) LOOP
----------------------------------------------------
    IF ar_info.nhoureriod = 1 THEN
     FOR i IN 1 .. 2 LOOP
      IF ar_info.ndivtype = 1 THEN
       IF i = 1 THEN
        ld_fromh := lc.date_time - 1 / 48;
        ner := TRUNC(lc.er / 2);
        ned := TRUNC(lc.ed / 2);
        nq1 := TRUNC(lc.q1 / 2);
        nq2 := TRUNC(lc.q2 / 2);
        nq3 := TRUNC(lc.q3 / 2);
        nq4 := TRUNC(lc.q4 / 2);
       ELSE
        ld_fromh := lc.date_time;
        ner := lc.er - TRUNC(lc.er / 2);
        ned := lc.ed - TRUNC(lc.ed / 2);
        nq1 := lc.q1 - TRUNC(lc.q1 / 2);
        nq2 := lc.q2 - TRUNC(lc.q2 / 2);
        nq3 := lc.q3 - TRUNC(lc.q3 / 2);
        nq4 := lc.q4 - TRUNC(lc.q4 / 2);
       END IF;
      ELSE
       IF i = 1 THEN
        ld_fromh := lc.date_time - 1 / 48;
        ner := ROUND(lc.er - lc.er);
        ned := ROUND(lc.ed - lc.ed);
        nq1 := ROUND(lc.q1 - lc.q1);
        nq2 := ROUND(lc.q2 - lc.q2);
        nq3 := ROUND(lc.q3 - lc.q3);
        nq4 := ROUND(lc.q4 - lc.q4);
       ELSE
        ld_fromh := lc.date_time;
        ner := lc.er;
        ned := lc.ed;
        nq1 := lc.q1;
        nq2 := lc.q2;
        nq3 := lc.q3;
        nq4 := lc.q4;
       END IF;
      END IF;

---------------------------------------------------------
      ins_halfhouroldw(ar_info.mid, ld_fromh, ner, ned, nq1, nq3, nq2, nq4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1);
     END LOOP;
    ELSE
     ins_halfhouroldw(ar_info.mid, lc.date_time, lc.er, lc.ed, lc.q1, lc.q3, lc.q2, lc.q4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1);
    END IF;
   END LOOP;
  ELSE
   FOR lc IN (SELECT     ad_from
                       +   calcformula_pg.get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_nshift, DECODE(ar_info.nhoureriod, 1, 24, 48))
                         / DECODE(ar_info.nhoureriod, 1, 24, 48) date_time,
                       SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))) * ln_kc er,
                       SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))) * ln_kc ed,
                       SUM(DECODE(g.inverted, 'y', h.q3 * DECODE(g.npartly, 1, 0, 1), h.q1 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q1,
                       SUM(DECODE(g.inverted, 'y', h.q1 * DECODE(g.npartly, 2, 0, 1), h.q3 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q3,
                       SUM(DECODE(g.inverted, 'y', h.q4 * DECODE(g.npartly, 1, 0, 1), h.q2 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q2,
                       SUM(DECODE(g.inverted, 'y', h.q2 * DECODE(g.npartly, 2, 0, 1), h.q4 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q4, sumqm(h.vqm) vqm
              /*   DECODE(
                  COUNT(DISTINCT g.mid),
                  ln_cnt, NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm),
                  qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
                 ) vqm*/
              FROM     halfhour h, GROUPS g
              WHERE    g.mid = h.mid AND h.date_time > ad_from + ln_nshift AND h.date_time <= ad_till + ln_nshift + 1 / 24
                       AND util_pg.to_unlocaltime(h.date_time, h.nsource) > ad_from + ln_nshift
                       AND util_pg.to_unlocaltime(h.date_time, h.nsource) <= ad_till + ln_nshift AND g.gid IN(SELECT     gid
                                                                                                              FROM       GROUPS
                                                                                                              CONNECT BY (PRIOR gid = PARENT)
                                                                                                              START WITH gid = ln_gid)
              GROUP BY   ad_from
                       +   calcformula_pg.get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_nshift, DECODE(ar_info.nhoureriod, 1, 24, 48))
                         / DECODE(ar_info.nhoureriod, 1, 24, 48)
              ORDER BY 1) LOOP
----------------------------------------------------
    IF ar_info.nhoureriod = 1 THEN
     FOR i IN 1 .. 2 LOOP
      IF ar_info.ndivtype = 1 THEN
       IF i = 1 THEN
        ld_fromh := lc.date_time - 1 / 48;
        ner := TRUNC(lc.er / 2);
        ned := TRUNC(lc.ed / 2);
        nq1 := TRUNC(lc.q1 / 2);
        nq2 := TRUNC(lc.q2 / 2);
        nq3 := TRUNC(lc.q3 / 2);
        nq4 := TRUNC(lc.q4 / 2);
       ELSE
        ld_fromh := lc.date_time;
        ner := lc.er - TRUNC(lc.er / 2);
        ned := lc.ed - TRUNC(lc.ed / 2);
        nq1 := lc.q1 - TRUNC(lc.q1 / 2);
        nq2 := lc.q2 - TRUNC(lc.q2 / 2);
        nq3 := lc.q3 - TRUNC(lc.q3 / 2);
        nq4 := lc.q4 - TRUNC(lc.q4 / 2);
       END IF;
      ELSE
       IF i = 1 THEN
        ld_fromh := lc.date_time - 1 / 48;
        ner := ROUND(lc.er - lc.er);
        ned := ROUND(lc.ed - lc.ed);
        nq1 := ROUND(lc.q1 - lc.q1);
        nq2 := ROUND(lc.q2 - lc.q2);
        nq3 := ROUND(lc.q3 - lc.q3);
        nq4 := ROUND(lc.q4 - lc.q4);
       ELSE
        ld_fromh := lc.date_time;
        ner := lc.er;
        ned := lc.ed;
        nq1 := lc.q1;
        nq2 := lc.q2;
        nq3 := lc.q3;
        nq4 := lc.q4;
       END IF;
      END IF;

---------------------------------------------------------
      ins_halfhouroldw(ar_info.mid, ld_fromh, ner, ned, nq1, nq3, nq2, nq4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1);
     END LOOP;
    ELSE
     ins_halfhouroldw(ar_info.mid, lc.date_time, lc.er, lc.ed, lc.q1, lc.q3, lc.q2, lc.q4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1);
    END IF;
   END LOOP;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
--На вход ad_day - расчет за (trunc(ad_day)..trunc(ad_day)+1]
 PROCEDURE calc(ad_day DATE, an_mid NUMBER, an_calctype NUMBER) IS
  ld_day              DATE DEFAULT TRUNC(ad_day);
 BEGIN
  calc_constant(ld_day, an_mid, an_calctype);
  calcw(util_pg.to_unlocaltime(ld_day), util_pg.to_unlocaltime(ld_day + 1), an_mid, an_calctype);
  calc_group(ld_day, an_mid, an_calctype);
 END;

------------------------------------------------------------------------------------------------------------------------
--На вход ad_day - расчет за (trunc(ad_day)..trunc(ad_day)+1/24]
 PROCEDURE calc_current(ad_day DATE, an_mid NUMBER, an_calctype NUMBER) IS
  ld_day              DATE DEFAULT TRUNC(ad_day);
  ld_end              DATE DEFAULT TRUNC(ad_day, 'HH24') + 1 / 24;
 BEGIN
  calc_constant(ld_day, an_mid, an_calctype);
  calcw(util_pg.to_unlocaltime(ld_day), util_pg.to_unlocaltime(ld_end), an_mid, an_calctype);
  calc_group(ld_day, an_mid, an_calctype);
 END;

------------------------------------------------------------------------------------------------------------------------
--Вычисление значение по тексту
 PROCEDURE getvalw(
 av_id VARCHAR2, ad_from DATE, ad_till DATE, an_pnum NUMBER, at_ret IN OUT common_pg.tt_double, at_qm IN OUT common_pg.tt_varchar2, an_evr NUMBER,
 an_cnt NUMBER, an_nshift NUMBER, an_ccnt NUMBER
 ) IS
  ln_num              NUMBER;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_bl               NUMBER;
  ln_bl1              NUMBER;
  ln_q1               NUMBER;
  ln_q2               NUMBER;
  ln_q3               NUMBER;
  ln_q4               NUMBER;
  z1                  NUMBER;
  cr_sel              common_pg.tcur;
  lr_c                tcalcinfo;
  lv_datatable        VARCHAR2(32) := 'HALFHOUR';
  lv_type             VARCHAR2(32) := TRIM(UPPER(util_pg.get_param(av_id, 1, cv_d)));
  ln_id               NUMBER := util_pg.allnumber_f(TRIM(util_pg.get_param(av_id, 2, cv_d)));
  lv_prop             VARCHAR2(32) := TRIM(UPPER(util_pg.get_param(av_id, 3, cv_d)));                                                             --'DATNUM';--
  lv_period           VARCHAR2(32) := TRIM(UPPER(util_pg.get_param(av_id, 4, cv_d)));
  lv_objtable         VARCHAR2(32);                                                                                           --Таблица ограничения по объектам
  lv_inverted         VARCHAR2(32);                                                                                                          --Признак инверсии
  lv_partly_er        VARCHAR2(32);                                                                                                    --Частичное вхождение A+
  lv_partly_ed        VARCHAR2(32);                                                                                                    --Частичное вхождение A-
  lv_objsubsel        VARCHAR2(512);                                                                                                  --Ограничение по объектам
  lv_datsubsel        VARCHAR2(1000);                                                                                                     --Ограничение по дате
  lv_what             VARCHAR2(5000);
  lv_group            VARCHAR2(1000);                                                                                                               --Что тянем
  lv_group1           VARCHAR2(1000);                                                                                                       --group by в select
  lv_group2           VARCHAR2(1000);
  lv_group3           VARCHAR2(1000);                                                                                                        --group by в конце
  lv_addday           VARCHAR2(512);                                                                           --Добавление дней (умножение на количество дней)
  lv_sql              VARCHAR2(5000);                                                                                                            --Конечный SQL
  lt_ret              common_pg.tt_double;
  lt_ret1             common_pg.tt_double;
  ln_itemcnt          NUMBER := ROUND((ad_till - ad_from) * an_cnt);
  lv_from             VARCHAR2(32) := TO_CHAR(ad_from, 'dd.mm.yyyy hh24:mi:ss');
  lv_till             VARCHAR2(32) := TO_CHAR(ad_till, 'dd.mm.yyyy hh24:mi:ss');
  ln_switch           NUMBER := 0;
  lv_vqm              VARCHAR2(200);
  lv_lvqm             VARCHAR2(32);
  lv_subsel           VARCHAR2(512) := ' ';
  lv_subsel2          VARCHAR2(512) := ' ';
  lv_dat              VARCHAR(40) := TO_CHAR(util_pg.to_localtime(ad_from - an_nshift), 'dd');
 BEGIN
  /* IF an_evr = 1 THEN
    ln_switch := util_pg.is_dayswitch(ad_from);
    ln_itemcnt := ln_itemcnt - an_cnt / 24 * ln_switch;
   END IF;*/
  ln_itemcnt := an_cnt;
  z1 := (an_pnum - 1) * cn_meas * ln_itemcnt;

  --Разобрали входную строку
  IF lv_period IN('D', 'M') THEN
   --Суточный или месячный параметр (!!! Здесь ограничение - мы считаем с ошибкой если (ad_till - ad_from)>1
   lv_group1 := ' tt.num,';
   lv_group2 := ' group by tt.num ';
   lv_addday := ',(select rownum num from dict where rownum<=' || NVL(ln_itemcnt, 0) || ') tt ';

   IF lv_period = 'D' THEN
    lv_datsubsel :=
        ' and p.date_time>util_pg.to_localtime(to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')) '
     || ' and p.date_time<=util_pg.to_localtime(to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss''))+'
     || ln_switch
     || '/24+1 ';
   --    ' and p.date_time<=trunc(util_pg.to_localtime(to_date(''' || lv_till || ''',''dd.mm.yyyy hh24:mi:ss''))-1/86400)+1 ';
   ELSE
    lv_datsubsel :=
        ' and p.date_time> trunc(util_pg.to_localtime(to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')),''MONTH'') '
     || ' and p.date_time<=add_months(trunc(util_pg.to_localtime(to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')),''MONTH''),1) ';
   END IF;
  ELSIF lv_period IN('CM', 'CD') THEN
   -- нарастающий итог с начала месяца
   lv_group :=
       ' calcformula_pg.get_num_dtw(P.date_time-1/86400,nsource,util_pg.to_unlocaltime(trunc(P.date_time-1/86400-'
    || an_nshift
    || '))+'
    || an_nshift
    || ' ,'
    || an_cnt
    || ') ';
   lv_group3 := ' 0+to_char(p.DATE_TIME-1/86400-(' || an_nshift || '),''dd'')';
   lv_group2 := ' group by ' || lv_group3 || ',' || lv_group;

   IF lv_period =('CM') THEN
    lv_group1 := lv_group3 || ' dd,
     ' ||        lv_group || ' num, ';
    lv_datsubsel :=
        ' and p.date_time>util_pg.to_unlocaltime(trunc(util_pg.to_localtime(to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')),''MONTH''))+'
     || an_nshift
     || ' and p.date_time<=to_date('''
     || lv_till
     || ''',''dd.mm.yyyy hh24:mi:ss'')+1/24 '
     || ' and util_pg.to_unlocaltime(p.date_time,p.nsource)>util_pg.to_unlocaltime(trunc(util_pg.to_localtime(to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')),''MONTH'')) +'
     || an_nshift
     || ' and util_pg.to_unlocaltime(p.date_time,p.nsource)<=to_date('''
     || lv_till
     || ''',''dd.mm.yyyy hh24:mi:ss'') ';
    lv_subsel := ' select tt.num,tt.ers,tt.vqm from (';
    lv_subsel2 := ')tt  
    where tt.dd=' || lv_dat;
   ELSE
    lv_group1 := lv_group || ' num, ';
    lv_datsubsel :=
        ' and p.date_time>to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')'
     || ' and p.date_time<=to_date('''
     || lv_till
     || ''',''dd.mm.yyyy hh24:mi:ss'')+1/24 '
     || ' and util_pg.to_unlocaltime(p.date_time,p.nsource)>to_date('''
     || lv_from
     || ''',''dd.mm.yyyy hh24:mi:ss'')'
     || ' and util_pg.to_unlocaltime(p.date_time,p.nsource)<=to_date('''
     || lv_till
     || ''',''dd.mm.yyyy hh24:mi:ss'') ';
   END IF;
  ELSE
   lv_datsubsel :=
       ' and p.date_time>to_date('''
    || lv_from
    || ''',''dd.mm.yyyy hh24:mi:ss'') '
    || ' and p.date_time<=to_date('''
    || lv_till
    || ''',''dd.mm.yyyy hh24:mi:ss'')+1/24 '
    || ' and util_pg.to_unlocaltime(p.date_time,p.nsource)>to_date('''
    || lv_from
    || ''',''dd.mm.yyyy hh24:mi:ss'') '
    || ' and util_pg.to_unlocaltime(p.date_time,p.nsource)<=to_date('''
    || lv_till
    || ''',''dd.mm.yyyy hh24:mi:ss'') ';
   lv_group1 :=
              ' CALCFORMULA_PG.get_num_dtw(p.date_time - 1 / 86400,p.nsource,to_date(''' || lv_from || ''',''dd.mm.yyyy hh24:mi:ss''),' || an_ccnt || ')   num,';
   lv_group2 :=
           '  group by CALCFORMULA_PG.get_num_dtw(p.date_time - 1 / 86400,p.nsource,to_date(''' || lv_from || ''',''dd.mm.yyyy hh24:mi:ss''),' || an_ccnt || ')';
  END IF;

  IF lv_type = 'GID' THEN
   lv_objtable := 'GROUPS';
   lv_inverted := 'G.INVERTED';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1)';

   IF util_pg.get_customer_id = 1 THEN
    lv_objsubsel :=
        'and G.gid in (select gid from groups connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)) start with gid='
     || ln_id
     || ')';
   ELSE
    lv_objsubsel := 'and G.gid in (select gid from groups connect by (prior gid=parent)  start with gid=' || ln_id || ')';
   END IF;
  ELSIF lv_type = 'MID' THEN
   lv_objtable := 'POINTS';
   lv_inverted := '''N''';
   lv_partly_er := '';
   lv_partly_ed := '';

   IF util_pg.isfolder(ln_id) = 1 AND ln_id <> 1000 THEN
    --Заблокировали суммирование с вершины точек (при ошибках Руч ввода)
    lv_objsubsel := 'and G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=' || ln_id || ')';
   ELSE
    lv_objsubsel := 'and G.mid = ' || ln_id || ' ';
   END IF;
  ELSE
   RETURN;
  END IF;

  --Выясняем что нам нужно
  IF lv_prop IS NULL OR lv_prop IN('A', 'AI') THEN
   lv_what :=
       'sum((DECODE('
    || lv_inverted
    || ',''y'',nvl(P.ed'
    || lv_partly_ed
    || ',0),nvl(P.er'
    || lv_partly_er
    || ',0)))),'
    || 'sum((DECODE('
    || lv_inverted
    || ',''y'',nvl(P.er'
    || lv_partly_er
    || ',0),nvl(P.ed'
    || lv_partly_ed
    || ',0)))),'
    || 'sum((DECODE('
    || lv_inverted
    || ',''y'',nvl(P.q3,0),nvl(P.q1,0)))),'
    || 'sum((DECODE('
    || lv_inverted
    || ',''y'',nvl(P.q1,0),nvl(P.q3,0)))),'
    || 'sum((DECODE('
    || lv_inverted
    || ',''y'',nvl(P.q4,0),nvl(P.q2,0)))),'
    || 'sum((DECODE('
    || lv_inverted
    || ',''y'',nvl(P.q2,0),nvl(P.q4,0)))) ';
   lv_vqm := ' ,sumqm(P.vqm) vqm ';
   lv_sql :=
       'select '
    || util_pg.hint_ordered
    || lv_group1
    || lv_what
    || lv_vqm
    || ' from '
    || lv_objtable
    || ' G,'
    || lv_datatable
    || ' P '
    || lv_addday
    || ' where g.mid=p.mid '
    || ' '
    || lv_datsubsel
    || ' '
    || lv_objsubsel
    || lv_group2;

--delete from tmp_vil;
--insert into tmp_vil values (lv_sql);commit;
   OPEN cr_sel FOR lv_sql;

   LOOP
    IF lv_prop = 'AI' THEN                                                                                                                           --Инверсия
     FETCH cr_sel
     INTO  ln_num, ln_ed, ln_er, ln_q2, ln_q1, ln_q4, ln_q3, lv_lvqm;
    ELSE
     FETCH cr_sel
     INTO  ln_num, ln_er, ln_ed, ln_q1, ln_q2, ln_q3, ln_q4, lv_lvqm;
    END IF;

    EXIT WHEN cr_sel%NOTFOUND;
    at_ret(z1 + ln_num) := ln_er;
    at_ret(z1 + ln_itemcnt + ln_num) := ln_ed;
    at_ret(z1 + 2 * ln_itemcnt + ln_num) := ln_q1;
    at_ret(z1 + 3 * ln_itemcnt + ln_num) := ln_q2;
    at_ret(z1 + 4 * ln_itemcnt + ln_num) := ln_q3;
    at_ret(z1 + 5 * ln_itemcnt + ln_num) := ln_q4;

--SAA 24/05/2012 begin
/*    IF ln_er IS NULL AND ln_ed IS NULL AND ln_q1 IS NULL AND ln_q2 IS NULL AND ln_q3 IS NULL AND ln_q4 IS NULL THEN
     lv_lvqm := qm_pg.sumqm(lv_lvqm, qm_pg.nodataqm);
    END IF;*/

    --SAA 24/05/2012 end
    FOR i IN 1 .. cn_meas LOOP
     at_qm(z1 + (cn_meas - i) * ln_itemcnt + ln_num) := lv_lvqm;                                                                                  --qm_pg.okqm;
    END LOOP;
   END LOOP;

   CLOSE cr_sel;
  ELSIF lv_prop IN('ER', 'ED', 'Q1', 'Q3', 'Q2', 'Q4', 'Q12', 'Q34', 'E', 'Q', 'EE', 'QQ', 'ER_C', 'ED_C') THEN
   IF lv_prop = 'ER' OR lv_prop = 'ER_C' THEN
    lv_what := 'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_partly_ed || ',0),nvl(P.er' || lv_partly_er || ',0))))';
   /* lv_what :='sum(sum((DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_partly_ed || ',0),nvl(P.er' || lv_partly_er || ',0)))))
     over( ORDER BY '||lv_group3||','||lv_group||'
   ROWS BETWEEN unbounded preceding AND CURRENT ROW) ers ';*/
   ELSIF lv_prop = 'ED' OR lv_prop = 'ED_C' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0)))';
   ELSIF lv_prop = 'Q1' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0)))';
   ELSIF lv_prop = 'Q3' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0)))';
   ELSIF lv_prop = 'Q2' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0)))';
   ELSIF lv_prop = 'Q4' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0)))';
   ELSIF lv_prop = 'Q12' THEN                                                                                                                  --Свернутые Q1+Q2
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0)))+sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0)))';
   ELSIF lv_prop = 'Q34' THEN                                                                                                                  --Свернутые Q3+Q4
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0)))+sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0)))';
   ELSIF lv_prop = 'E' THEN                                                                                                                      --Переток ER-ED
    lv_what := 'sum(-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0))*DECODE(' || lv_inverted || ',''y'',1,-1))';
   ELSIF lv_prop = 'Q' THEN                                                                                                            --Переток (Q1-Q3)+(Q2-Q4)
    lv_what :=
        'sum(-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0))*DECODE('
     || lv_inverted
     || ',''y'',1,-1))+sum(-util_pg.sld(P.mid,nvl(P.q2,0),nvl(P.q4,0))*DECODE('
     || lv_inverted
     || ',''y'',1,-1))';
   ELSIF lv_prop = 'EE' THEN                                                                                                                     --Переток ER+ED
    lv_what := 'sum(-(nvl(P.er' || lv_partly_er || ',0)+nvl(P.ed' || lv_partly_ed || ',0))*DECODE(' || lv_inverted || ',''y'',1,-1))';
   ELSIF lv_prop = 'QQ' THEN                                                                                                           --Переток (Q1+Q3)+(Q2+Q4)
    lv_what := 'sum(-(nvl(P.q1,0)+nvl(P.q3,0)+nvl(P.q2,0)+nvl(P.q4,0))*DECODE(' || lv_inverted || ',''y'',1,-1))';
   END IF;

   IF lv_prop = 'ER_C' OR lv_prop = 'ED_C' THEN
    lv_what :=
     'sum(' || lv_what || ' )
         over( ORDER BY ' || lv_group3 || ',' || lv_group || ' 
        ROWS BETWEEN unbounded preceding AND CURRENT ROW) ers ';
   END IF;

   lv_vqm := ' ,sumqm(P.vqm) vqm ';
   lv_sql :=
       lv_subsel
    || 'select '
    || util_pg.hint_ordered
    || lv_group1
    || lv_what
    || lv_vqm
    || ' from '
    || lv_objtable
    || ' G,'
    || lv_datatable
    || ' P '
    || lv_addday
    || ' where g.mid=p.mid '
    || ' '
    || lv_datsubsel
    || ' '
    || lv_objsubsel
    || lv_group2
    || lv_subsel2;

--delete from tmp_vil;
--insert into tmp_vil values (ln_itemcnt||' '||lv_sql);commit;
   OPEN cr_sel FOR lv_sql;

   LOOP
    FETCH cr_sel
    INTO  ln_num, ln_er, lv_lvqm;

    EXIT WHEN cr_sel%NOTFOUND;

    FOR i IN 1 .. cn_meas LOOP
     at_ret(z1 + (cn_meas - i) * ln_itemcnt + ln_num) := ln_er;
     at_qm(z1 + (cn_meas - i) * ln_itemcnt + ln_num) := lv_lvqm;                                                                                  --qm_pg.okqm;
    END LOOP;
   END LOOP;

   CLOSE cr_sel;
  ELSIF lv_prop = 'BALANCEP' OR(lv_type = 'GID' AND lv_prop IN('ADBALANCE', 'ADBALANCEP', 'BALANCEDIF', 'BALANCEDIFP')) THEN
   IF lv_prop = 'BALANCEP' THEN                                                                                                                   --Небаланс в%
    lv_what :=
        '  DECODE (
             (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))),
                0,   (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))),
                (100 * (sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0))))
                       -sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))
                / (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))))
           ) ';
   ELSIF lv_prop = 'ADBALANCE' THEN                                                                                                        --Допустимый небаланс
    lv_what :=
        'util_pg.get_ad_balance ('
     || ln_id
     || ', util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))-1/96, util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))+1/96, NULL)';
   ELSIF lv_prop = 'ADBALANCEP' THEN                                                                                                    --Допустимый небаланс в%
    lv_what :=
        'util_pg.get_ad_balance ('
     || ln_id
     || ', util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))-1/96, util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))+1/96, 1)';
   ELSIF lv_prop = 'BALANCEDIF' THEN                                                                              --Разность факт небаланса и допустим небаланса
    lv_what :=
        'SIGN ( sum(-util_pg.sld(P.mid,nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))*DECODE('
     || lv_inverted
     || ',''y'',1,-1)))
               * GREATEST (ABS ( sum(-util_pg.sld(P.mid,nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))*DECODE('
     || lv_inverted
     || ',''y'',1,-1)))
               - util_pg.get_ad_balance ('
     || ln_id
     || ', util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))-1/96, util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))+1/96, NULL), 0)';
   ELSIF lv_prop = 'BALANCEDIFP' THEN                                                                         --Разность факт небаланса и допустим небаланса в %
    lv_what :=
        'SIGN (DECODE (
             (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))),
                0,   (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))),
                (100 * (sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0))))
                       -sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))
           / (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))))
           ))
                        * GREATEST (ABS ( DECODE (
             (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))),
                0,   (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))),
               (100 * (sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0))))
                       -sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))
                / (GREATEST(sum((DECODE('
     || lv_inverted
     || ',''y'',nvl(P.ed'
     || lv_partly_ed
     || ',0),nvl(P.er'
     || lv_partly_er
     || ',0)))),
                      sum(DECODE('
     || lv_inverted
     || ',''y'',nvl(P.er'
     || lv_partly_er
     || ',0),nvl(P.ed'
     || lv_partly_ed
     || ',0))))))
           ) ) - (util_pg.get_ad_balance ('
     || ln_id
     || ', util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))-1/96, util_pg.ceilhh24_2(util_pg.to_unlocaltime(p.DATE_TIME,p.nsource))+1/96, 1)),
                0)';
   END IF;

   lv_vqm := ' ,sumqm(P.vqm) vqm ';
   lv_sql :=
       'select '
    || util_pg.hint_ordered
    || lv_group1
    || lv_what
    || lv_vqm
    || ' from '
    || lv_objtable
    || ' G,'
    || lv_datatable
    || ' P '
    || lv_addday
    || ' where g.mid=p.mid '
    || ' '
    || lv_datsubsel
    || ' '
    || lv_objsubsel
    || lv_group2;

   OPEN cr_sel FOR lv_sql;

   LOOP
    FETCH cr_sel
    INTO  ln_num, ln_bl, lv_lvqm;

    EXIT WHEN cr_sel%NOTFOUND;

    FOR i IN 1 .. cn_meas LOOP
     at_ret((i - 1) * cn_meas + 1) := ln_bl;
     at_qm((i - 1) * cn_meas + 1) := lv_lvqm;                                                                                                     --qm_pg.okqm;
    END LOOP;
   END LOOP;

   CLOSE cr_sel;
  ELSIF lv_prop IN('CTN', 'CTT', 'CM') THEN
   IF lv_prop = 'CTN' THEN
    SELECT DECODE(NVL(MAX(f.nclasstn), 0), 0, 1 / 2, MAX(f.nclasstn)) ctn
    INTO   ln_er
    FROM   feeders f, meters m
    WHERE  f.mid = ln_id AND f.mid = m.mid(+) AND m.entype(+) = 7;
   ELSIF lv_prop = 'CTT' THEN
    SELECT DECODE(NVL(MAX(f.nclasstt), 0), 0, 1 / 2, MAX(f.nclasstt)) ctt
    INTO   ln_er
    FROM   feeders f, meters m
    WHERE  f.mid = ln_id AND f.mid = m.mid(+) AND m.entype(+) = 7;
   ELSIF lv_prop = 'CM' THEN
    SELECT DECODE(NVL(MAX(m.mclass), 0), 0, 1 / 2, MAX(m.mclass)) cm
    INTO   ln_er
    FROM   feeders f, meters m
    WHERE  f.mid = ln_id AND f.mid = m.mid(+) AND m.entype(+) = 7;
   END IF;

   FOR i IN 1 .. cn_meas * ln_itemcnt LOOP
    at_ret(z1 + i) := ln_er;
    at_qm(z1 + i) := qm_pg.okqm;                                                                                                                        -- null
   END LOOP;
  ELSIF lv_prop IN
              ('SN', 'DPXX', 'IXX', 'TN', 'TP', 'L', 'R0', 'X0', 'UN', 'DPKZ', 'DPBH', 'DPCH', 'DPHH', 'UBH_CH', 'UCH_HH', 'UBH_HH', 'UKZ', 'SBH', 'SCH', 'SHH') THEN
   IF NVL(gr_transline.mid, 0) <> ln_id THEN
    createtranslineinfo(ln_id);
   END IF;

   IF lv_prop = 'SN' THEN
    ln_er := gr_transline.sn;
   ELSIF lv_prop = 'DPXX' THEN
    ln_er := gr_transline.dpxx;
   ELSIF lv_prop = 'IXX' THEN
    ln_er := gr_transline.ixx;
   ELSIF lv_prop = 'TN' THEN
    ln_er := gr_transline.tn;
   ELSIF lv_prop = 'TP' THEN
    ln_er := gr_transline.tp;
   ELSIF lv_prop = 'L' THEN
    ln_er := gr_transline.l;
   ELSIF lv_prop = 'R0' THEN
    ln_er := gr_transline.r0;
   ELSIF lv_prop = 'X0' THEN
    ln_er := gr_transline.x0;
   ELSIF lv_prop = 'UN' THEN
    ln_er := gr_transline.un;
   ELSIF lv_prop = 'DPKZ' THEN
    ln_er := gr_transline.dpkz;
   ELSIF lv_prop = 'DPBH' THEN
    ln_er := gr_transline.dpbh;
   ELSIF lv_prop = 'DPCH' THEN
    ln_er := gr_transline.dpch;
   ELSIF lv_prop = 'DPHH' THEN
    ln_er := gr_transline.dphh;
   ELSIF lv_prop = 'UKZ' THEN
    ln_er := gr_transline.ukz;
   ELSIF lv_prop = 'UBH_CH' THEN
    ln_er := gr_transline.ubh_ch;
   ELSIF lv_prop = 'UCH_HH' THEN
    ln_er := gr_transline.uch_hh;
   ELSIF lv_prop = 'UBH_HH' THEN
    ln_er := gr_transline.ubh_hh;
   ELSIF lv_prop = 'SBH' THEN
    ln_er := gr_transline.sbh;
   ELSIF lv_prop = 'SCH' THEN
    ln_er := gr_transline.sch;
   ELSIF lv_prop = 'SHH' THEN
    ln_er := gr_transline.shh;
   ELSE
    ln_er := NULL;
   END IF;

   FOR i IN 1 .. cn_meas * ln_itemcnt LOOP
    at_ret(z1 + i) := ln_er;
    at_qm(z1 + i) := qm_pg.okqm;                                                                                                                        -- null
   END LOOP;
  ELSIF SUBSTR(lv_prop, 1, 3) = 'APP' THEN
   SELECT MAX(util_pg.allnumber_f(vvalue))
   INTO   ln_er
   FROM   addpointparamval
   WHERE  mid = ln_id
          AND nsort = util_pg.allnumber_f(SUBSTR(lv_prop, DECODE(SUBSTR(lv_prop, 1, 4), 'APPR', 5, 4))) * DECODE(SUBSTR(lv_prop, 1, 4), 'APPR', -1, 1);

   FOR i IN 1 .. cn_meas * ln_itemcnt LOOP
    at_ret(z1 + i) := ln_er;
    at_qm(z1 + i) := qm_pg.okqm;                                                                                                                        -- null
   END LOOP;
  ELSIF SUBSTR(lv_prop, 1, 3) = 'RK' THEN
   ln_er := NVL(util_pg.get_multiplier(ln_id, util_pg.to_localtime(TO_DATE('' || lv_from || '', 'dd.mm.yyyy hh24:mi:ss'))), 1);

   FOR i IN 1 .. cn_meas * ln_itemcnt LOOP
    at_ret(z1 + i) := ln_er;
    at_qm(z1 + i) := qm_pg.okqm;                                                                                                                        -- null
   END LOOP;
---------------------VNB
  ELSIF lv_prop = 'DATNUM' THEN
   FOR i IN 1 .. cn_meas LOOP
    FOR y IN 1 .. ln_itemcnt LOOP
     at_ret(z1 + y) := y;
     at_qm(z1 + y) := qm_pg.okqm;                                                                                                                      -- NULL;
    END LOOP;

    z1 := z1 + i * ln_itemcnt;
   END LOOP;
--------------------------end
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'calcformula_pg.getvalw: ИД=''' || av_id || ''' ' || CHR(10) || SQLERRM);
 END;

