 PROCEDURE createtranslineinfo(an_id NUMBER) IS
 BEGIN
  gr_transline.mid := an_id;

  SELECT MAX(nsn), MAX(ndeltapidling), MAX(niidling), MAX(nworkinghours), MAX(nfullhours), MAX(nl), MAX(nro), MAX(nxo), MAX(nun),
         MAX(DECODE(nwinding, 0, ndeltapsc)), MAX(DECODE(nwinding, 1, ndeltapsc)), MAX(DECODE(nwinding, 2, ndeltapsc)), MAX(DECODE(nwinding, 3, ndeltapsc)),
         MAX(DECODE(nwinding, 0, nusc)), MAX(DECODE(nwinding, 1, nusc)), MAX(DECODE(nwinding, 2, nusc)), MAX(DECODE(nwinding, 3, nusc)),
         MAX(DECODE(nwinding, 1, nsh)), MAX(DECODE(nwinding, 2, nsh)), MAX(DECODE(nwinding, 3, nsh))
  INTO   gr_transline.sn, gr_transline.dpxx, gr_transline.ixx, gr_transline.tn, gr_transline.tp, gr_transline.l, gr_transline.r0, gr_transline.x0,
         gr_transline.un, gr_transline.dpkz, gr_transline.dpbh, gr_transline.dpch, gr_transline.dphh, gr_transline.ukz, gr_transline.ubh_ch,
         gr_transline.uch_hh, gr_transline.ubh_hh, gr_transline.sbh, gr_transline.sch, gr_transline.shh
  FROM   connectionparam
  WHERE  mid = an_id;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calc_constant(ad_date DATE, an_mid NUMBER, an_calctype NUMBER) IS
  ld_date             DATE DEFAULT TRUNC(ad_date);
  ld_calcperiod       DATE DEFAULT admin_pg.get_calcperiod;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_ras              NUMBER;
  ln_cn               NUMBER DEFAULT util_pg.get_count_dt(ld_date, cn_step);
  lv_sql              VARCHAR2(4000);
  cr_sel              common_pg.tcur;
  ln_mid              NUMBER;
  ln_calcpointtype    NUMBER;
  ln_switch           NUMBER;
 BEGIN
  lv_sql := 'SELECT mid, ncalcpointtype, nswitch FROM feeders WHERE ncalcpointtype IN (' || cn_cpt_cons || ',' || cn_cpt_amm || ')';

  IF an_mid > 0 THEN
   lv_sql := lv_sql || ' AND mid IN (SELECT mid FROM points CONNECT BY PRIOR mid = PARENT START WITH mid = :an_mid )';
  END IF;

  IF an_calctype = 1 THEN
   RETURN;
  END IF;

IF an_mid > 0 THEN
  OPEN cr_sel FOR lv_sql USING an_mid;
ELSE
  OPEN cr_sel FOR lv_sql;
END IF;  

  LOOP
   FETCH cr_sel
   INTO  ln_mid, ln_calcpointtype, ln_switch;

   EXIT WHEN cr_sel%NOTFOUND;

   --del_halfhouroldw (lc.mid, util_pg.to_unlocaltime (ld_date), util_pg.to_unlocaltime (ld_date + 1));
   IF ln_calcpointtype = cn_cpt_cons THEN
    ln_ras := util_pg.get_curr_power(ln_mid, ld_date) * util_pg.get_workhours(ln_mid, TO_CHAR(ld_date, 'YYYYMM')) /(24 * TO_CHAR(LAST_DAY(ld_date), 'DD')) / 2;
   ELSE
    ln_ras := util_pg.get_months_consumpt(ln_mid, ld_date) /(24 * TO_CHAR(LAST_DAY(ld_date), 'DD')) / 2;
   END IF;

   IF SIGN(ln_ras) = -1 THEN
    ln_er := 0;
    ln_ed := ABS(ln_ras);
   ELSE
    ln_er := ABS(ln_ras);
    ln_ed := 0;
   END IF;

   FOR i IN 1 .. ln_cn LOOP
    ins_halfhouroldw(ln_mid, util_pg.to_unlocaltime(ld_date) + i * cn_step, ln_er, ln_ed, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, qm_pg.cv_calcqm,
     ln_switch, NULL, 1, 1);
   END LOOP;

   IF ld_date < ld_calcperiod THEN
    calcpoint4bill(ln_mid, ld_date, ld_date + 1);
   END IF;
  END LOOP;

  CLOSE cr_sel;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'CALCFORMULA_PG.calc_constant: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------
--Расчет ГН Переразбивка суточных расходов
 PROCEDURE recalcaverrate(ad_day DATE, an_mid NUMBER, an_calctype NUMBER) IS
  ld_day              DATE DEFAULT TRUNC(ad_day);
  ld_calcperiod       DATE DEFAULT admin_pg.get_calcperiod;
  lv_sql              VARCHAR2(4000);
  ln_mid              NUMBER := an_mid;
 BEGIN
  BEGIN
   SAVEPOINT recalcaverrate_sp;

   FOR lc1 IN (SELECT SUM(er) er, SUM(ed) ed, SUM(q1) q1, SUM(q2) q2, SUM(q3) q3, SUM(q4) q4
               FROM   billorg
               WHERE  mid = ln_mid AND date_time > ld_day AND date_time <= ld_day + 1
                      AND NOT EXISTS(
                          SELECT *
                          FROM   halfhour
                          WHERE  mid = ln_mid AND date_time > ld_day AND date_time <= ld_day + 1
                                 AND nsource IN(util_pg.cn_manualinput, util_pg.cn_manualinputw))) LOOP
    IF NVL(NVL(NVL(lc1.er, lc1.ed), NVL(lc1.q1, lc1.q2)), NVL(lc1.q3, lc1.q4)) IS NOT NULL THEN
     indic_pg.setcorrection(ln_mid, ld_day, ld_day + 1, lc1.er, lc1.ed, lc1.q1, lc1.q2, lc1.q3, lc1.q4, 0, 1, comsrv_pg.cn_maket);

     IF ld_day < ld_calcperiod THEN
      calcpoint4bill(ln_mid, ld_day, ld_day + 1);
     END IF;
    END IF;
   END LOOP;
  EXCEPTION
   WHEN OTHERS THEN
    ROLLBACK TO SAVEPOINT recalcaverrate_sp;
  END;
 END;

