 PROCEDURE calc_group(ad_date DATE, an_mid NUMBER, an_calctype NUMBER) IS
  ld_date             DATE DEFAULT TRUNC(ad_date);
  ld_calcperiod       DATE DEFAULT admin_pg.get_calcperiod;
  ln_kc               NUMBER;
  lv_sql              VARCHAR2(4000);
  cr_sel              common_pg.tcur;
  ln_mid              NUMBER;
  ln_gid              NUMBER;
  ln_switch           NUMBER;
 BEGIN
  lv_sql := 'SELECT c.mid, c.gid, f.nswitch FROM calcpointbygroup c, feeders f WHERE c.mid = f.mid AND f.ncalcpointtype = ' || cn_cpt_sum;

  IF an_mid > 0 THEN
   lv_sql := lv_sql || ' AND c.mid IN (SELECT mid FROM points CONNECT BY PRIOR mid = PARENT START WITH mid = :an_mid)';
  END IF;

  IF an_calctype = 1 THEN
   RETURN;
  END IF;

IF an_mid > 0 THEN
	 OPEN cr_sel FOR lv_sql using an_mid;
ELSE
  OPEN cr_sel FOR lv_sql;
END IF;  

  LOOP
   FETCH cr_sel
   INTO  ln_mid, ln_gid, ln_switch;

   EXIT WHEN cr_sel%NOTFOUND;
   --del_halfhouroldw (lc.mid, util_pg.to_unlocaltime (ld_date), util_pg.to_unlocaltime (ld_date + 1));
   ln_kc := NVL(util_pg.get_multiplier(ln_mid, ld_date), 1);

   IF util_pg.get_customer_id = 10 AND ln_kc <> 0 THEN                                                                                               --Захотели
    ln_kc := 1 / ln_kc;
   END IF;

   IF util_pg.get_customer_id = 1 THEN
    FOR lc1 IN (SELECT   util_pg.ceilhh24_2(util_pg.to_unlocaltime(h.date_time, h.nsource)) date_time,
                         SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))) * ln_kc er,
                         SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))) * ln_kc ed,
                         SUM(DECODE(g.inverted, 'y', h.q3 * DECODE(g.npartly, 1, 0, 1), h.q1 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q1,
                         SUM(DECODE(g.inverted, 'y', h.q1 * DECODE(g.npartly, 2, 0, 1), h.q3 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q3,
                         SUM(DECODE(g.inverted, 'y', h.q4 * DECODE(g.npartly, 1, 0, 1), h.q2 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q2,
                         SUM(DECODE(g.inverted, 'y', h.q2 * DECODE(g.npartly, 2, 0, 1), h.q4 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q4, sumqm(h.vqm) vqm
                FROM     GROUPS g, halfhour h
                WHERE    h.mid = g.mid AND h.date_time > ld_date AND h.date_time <= ld_date + 1
                         AND g.gid IN(SELECT     gid
                                      FROM       GROUPS
                                      CONNECT BY ((PRIOR gid = PARENT) OR(PRIOR nroot2 = nroot2 AND PRIOR nroot1 > 0 AND nroot1 IS NULL))
                                      START WITH gid = ln_gid)
                GROUP BY util_pg.ceilhh24_2(util_pg.to_unlocaltime(h.date_time, h.nsource))) LOOP
     ins_halfhouroldw(ln_mid, lc1.date_time, lc1.er, lc1.ed, lc1.q1, lc1.q3, lc1.q2, lc1.q4, NULL, comsrv_pg.cn_calc, lc1.vqm, ln_switch, NULL, 1, 1);
    END LOOP;
   ELSE
    FOR lc1 IN (SELECT   util_pg.ceilhh24_2(util_pg.to_unlocaltime(h.date_time, h.nsource)) date_time,
                         SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))) * ln_kc er,
                         SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))) * ln_kc ed,
                         SUM(DECODE(g.inverted, 'y', h.q3 * DECODE(g.npartly, 1, 0, 1), h.q1 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q1,
                         SUM(DECODE(g.inverted, 'y', h.q1 * DECODE(g.npartly, 2, 0, 1), h.q3 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q3,
                         SUM(DECODE(g.inverted, 'y', h.q4 * DECODE(g.npartly, 1, 0, 1), h.q2 * DECODE(g.npartly, 2, 0, 1))) * ln_kc q2,
                         SUM(DECODE(g.inverted, 'y', h.q2 * DECODE(g.npartly, 2, 0, 1), h.q4 * DECODE(g.npartly, 1, 0, 1))) * ln_kc q4, sumqm(h.vqm) vqm
                FROM     GROUPS g, halfhour h
                WHERE    h.mid = g.mid AND h.date_time > ld_date AND h.date_time <= ld_date + 1 AND g.gid IN(SELECT     gid
                                                                                                             FROM       GROUPS
                                                                                                             CONNECT BY (PRIOR gid = PARENT)
                                                                                                             START WITH gid = ln_gid)
                GROUP BY util_pg.ceilhh24_2(util_pg.to_unlocaltime(h.date_time, h.nsource))) LOOP
     ins_halfhouroldw(ln_mid, lc1.date_time, lc1.er, lc1.ed, lc1.q1, lc1.q3, lc1.q2, lc1.q4, NULL, comsrv_pg.cn_calc, lc1.vqm, ln_switch, NULL, 1, 1);
    END LOOP;
   END IF;

   IF ld_date < ld_calcperiod THEN
    calcpoint4bill(ln_mid, ld_date, ld_date + 1);
   END IF;
  END LOOP;

  CLOSE cr_sel;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'CALCFORMULA_PG.calc_group: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_halfhouroldw(an_mid NUMBER, ad_from DATE, ad_till DATE)                                                                                --Удаление
                                                                      IS
 BEGIN                                                                                                                                                 --return;
  UPDATE halfhourold
  SET er = NULL,
      ed = NULL,
      q1 = NULL,
      q2 = NULL,
      q3 = NULL,
      q4 = NULL,
      erm = NULL,
      edm = NULL,
      q1m = NULL,
      q2m = NULL,
      q3m = NULL,
      q4m = NULL,
      status = NULL,
      nmetertype = NULL,
      vqm = NULL,
      denter = SYSDATE,
      nexceptcalc = NULL,
      nkc = NULL,
      er_mtrsn = NULL
  WHERE  mid = an_mid AND date_time > ad_from AND date_time <= ad_till + 1 / 24 AND util_pg.to_unlocaltime(date_time, nsource) > ad_from
         AND util_pg.to_unlocaltime(date_time, nsource) <= ad_till AND NOT(nsource BETWEEN 30 AND 49) AND 1 = 2;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_halfhouroldw(
 an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER,
 an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2, an_switch NUMBER, an_source NUMBER, an_calc NUMBER,
 an_lockcopyw NUMBER, an_nqm NUMBER, an_round NUMBER
 ) IS
  ln_mid              NUMBER := an_mid;
  ln_source           NUMBER := NVL(an_source, comsrv_pg.cn_auto);
  lv_qm               VARCHAR2(32) := NVL(av_qm, qm_pg.okqm);                                                                                          --av_qm;
  ld_date             DATE := util_pg.to_localtime(ad_date);
  ln_er               NUMBER := ROUND(an_er, an_round);
  ln_ed               NUMBER := ROUND(an_ed, an_round);
  ln_q1               NUMBER := ROUND(an_q1, an_round);
  ln_q2               NUMBER := ROUND(an_q2, an_round);
  ln_q3               NUMBER := ROUND(an_q3, an_round);
  ln_q4               NUMBER := ROUND(an_q4, an_round);
  ln_switch           NUMBER;
  ln_switchmid        NUMBER;
  ln_tmp              NUMBER;
  ln_tmp1             NUMBER;
  ln_kc               NUMBER;
  ld_ceildate         DATE;
  ln_validity         NUMBER;
 BEGIN
-- insert into tmp_vil values(an_round); commit;
                                                                                                                                               --return;
  DELETE FROM halfhourholes
  WHERE       mid = an_mid AND date_time = ad_date;

  IF util_pg.is_timeswitch(ad_date) = -1 THEN
   ln_source := ln_source + 9;
  END IF;

  util_pg.invert_p(ln_er, ln_ed, 1);
  util_pg.invert_p(ln_q1, ln_q3, 1);
  util_pg.invert_p(ln_q2, ln_q4, 1);

  --Помним про ОВ
  SELECT NVL(MAX(f.nswitch), 0), NVL(MAX(f.kc), 1), MAX(s.nvalidity)
  INTO   ln_tmp, ln_kc, ln_validity
  FROM   feeders f, points p, sourcetypes s
  WHERE  f.mid = an_mid AND p.mid = an_mid AND p.ptype = s.ptype(+);

  IF ln_tmp = 1 THEN
   SELECT MAX(mid)
   INTO   ln_switchmid
   FROM   switches
   WHERE  nswitch = an_mid AND ld_date > dswitch AND ld_date <= NVL(util_pg.ceilhh24_2(descape), comsrvdll_pg.cd_transnull);
  END IF;

  FOR i IN 1 .. 2 LOOP                                                                                                                           --Для ОВ до 2-х
   UPDATE halfhourold
   SET er = DECODE(an_er, util_pg.cn_random, er, ln_er),
       ed = DECODE(an_ed, util_pg.cn_random, ed, ln_ed),
       q1 = DECODE(an_q1, util_pg.cn_random, q1, ln_q1),
       q3 = DECODE(an_q3, util_pg.cn_random, q3, ln_q3),
       q2 = DECODE(an_q2, util_pg.cn_random, q2, ln_q2),
       q4 = DECODE(an_q4, util_pg.cn_random, q4, ln_q4),
       erm = DECODE(an_erm, util_pg.cn_random, erm, an_erm),
       edm = DECODE(an_edm, util_pg.cn_random, edm, an_edm),
       q1m = DECODE(an_q1m, util_pg.cn_random, q1m, an_q1m),
       q3m = DECODE(an_q3m, util_pg.cn_random, q3m, an_q3m),
       q2m = DECODE(an_q2m, util_pg.cn_random, q2m, an_q2m),
       q4m = DECODE(an_q4m, util_pg.cn_random, q4m, an_q4m),
       status = an_status,
       nmetertype = an_metertype,
       vqm =
        qm_pg.setvalidity(DECODE(
          NVL(NVL(DECODE(an_er, util_pg.cn_random, er, ln_er), DECODE(an_ed, util_pg.cn_random, ed, ln_ed)),
           NVL(DECODE(an_q1, util_pg.cn_random, q1, ln_q1), DECODE(an_q3, util_pg.cn_random, q3, ln_q3))),
          NULL, qm_pg.sumqm(lv_qm, qm_pg.nodataqm),
          lv_qm
         ),
         ln_validity),
       denter = SYSDATE,
       nswitch = ln_switch,
       nkc = ln_kc,
       nqe = an_nqm
   WHERE  mid = ln_mid AND date_time = ld_date AND nsource = ln_source
          AND(
              (
               (NVL(er, util_pg.cn_random) <> NVL(ln_er, util_pg.cn_random) OR NVL(ed, util_pg.cn_random) <> NVL(ln_ed, util_pg.cn_random))
               AND(DECODE(an_er, util_pg.cn_random, 0, 1) + DECODE(an_ed, util_pg.cn_random, 0, 1) > 0)
              )
              OR(
                 (
                  NVL(q1, util_pg.cn_random) <> NVL(ln_q1, util_pg.cn_random) OR NVL(q3, util_pg.cn_random) <> NVL(ln_q3, util_pg.cn_random)
                  OR NVL(q2, util_pg.cn_random) <> NVL(ln_q2, util_pg.cn_random) OR NVL(q4, util_pg.cn_random) <> NVL(ln_q4, util_pg.cn_random)
                 )
                 AND(DECODE(an_q1, util_pg.cn_random, 0, 1) + DECODE(an_q3, util_pg.cn_random, 0, 1) > 0)
                )
              OR NVL(erm, util_pg.cn_random) <> NVL(an_erm, util_pg.cn_random) OR NVL(edm, util_pg.cn_random) <> NVL(an_edm, util_pg.cn_random)
              OR NVL(q1m, util_pg.cn_random) <> NVL(an_q1m, util_pg.cn_random) OR NVL(q3m, util_pg.cn_random) <> NVL(an_q3m, util_pg.cn_random)
              OR NVL(q2m, util_pg.cn_random) <> NVL(an_q2m, util_pg.cn_random) OR NVL(q4m, util_pg.cn_random) <> NVL(an_q4m, util_pg.cn_random)
              OR NVL(status, util_pg.cn_random) <> NVL(an_status, util_pg.cn_random)
              OR NVL(nmetertype, util_pg.cn_random) <> NVL(an_metertype, util_pg.cn_random)
              OR NVL(vqm, util_pg.cn_random) <>
                 NVL(qm_pg.setvalidity(DECODE(
                    NVL(NVL(DECODE(an_er, util_pg.cn_random, er, ln_er), DECODE(an_ed, util_pg.cn_random, ed, ln_ed)),
                     NVL(DECODE(an_q1, util_pg.cn_random, q1, ln_q1), DECODE(an_q3, util_pg.cn_random, q3, ln_q3))),
                    NULL, qm_pg.sumqm(lv_qm, qm_pg.nodataqm),
                    lv_qm
                   ),
                   ln_validity),
                  util_pg.cn_random)
              OR NVL(nswitch, util_pg.cn_random) <> NVL(ln_switch, util_pg.cn_random)
             );

   IF SQL%ROWCOUNT = 0 THEN
    SELECT NVL(SUM(DECODE(nsource, ln_source, 1, 0)), 0),
           NVL(SUM(DECODE(nsource, DECODE(MOD(ln_source, 10), 9, util_pg.cn_manualinputw, util_pg.cn_manualinput), 1, 0)), 0)
    INTO   ln_tmp, ln_tmp1
    FROM   halfhourold
    WHERE  mid = ln_mid AND date_time = ld_date;

    --OR EXISTS (SELECT * FROM halfhourold WHERE mid = ln_mid AND date_time = ld_date AND MOD (nsource, 10) = MOD (ln_source, 10))
    IF ln_tmp = 0 AND NOT(NVL(an_calc, 0) = 1 AND ln_tmp1 > 0) THEN                                            --Мы при наличае ручников не дописываем дорасчет
     INSERT INTO halfhourold
                 (mid, date_time, nsource, nswitch, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, status, nmetertype, vqm, nkc, nqe)
     VALUES      (ln_mid, ld_date, ln_source, ln_switch, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_status,
                  an_metertype,
                  qm_pg.setvalidity(DECODE(NVL(NVL(ln_er, ln_ed), NVL(ln_q1, ln_q3)), NULL, qm_pg.sumqm(lv_qm, qm_pg.nodataqm), lv_qm), ln_validity), ln_kc,
                  an_nqm);
    END IF;
   END IF;

   IF ln_switchmid > 0 AND i = 1 THEN                                                                                                                    --Выход
    ln_mid := ln_switchmid;

    IF ln_source IN(util_pg.cn_manualinput, util_pg.cn_manualinputw) THEN
     ln_source := ln_source - 20;
    ELSE
     ln_source := ln_source + 20;
    END IF;

    ln_switch := an_mid;
    lv_qm := qm_pg.sbt(qm_pg.sbt(NVL(lv_qm, qm_pg.cv_okqm), 22, qm_pg.cn_ov), 19, qm_pg.cn_add_ok);
   ELSE
    EXIT;
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_halfhouroldw(
 an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_status NUMBER, an_metertype NUMBER,
 av_qm VARCHAR2, an_switch NUMBER, an_source NUMBER, an_calc NUMBER, an_lockcopyw NUMBER, an_nqm NUMBER, an_round NUMBER
 ) IS
 BEGIN
  -- insert into tmp_vil values (an_round);commit;
  ins_halfhouroldw(an_mid, ad_date, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, NULL, NULL, NULL, NULL, NULL, NULL, an_status, an_metertype, av_qm, an_switch,
   an_source, an_calc, an_lockcopyw, an_nqm, an_round);
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_bill(ad_date DATE, an_dif NUMBER, an_mid NUMBER) IS
  ln_rid              NUMBER;
  ln_daysw            NUMBER;
  ln_dif              NUMBER;
  ln_step             NUMBER;
 BEGIN
  SELECT NVL(MAX(nintegralperiod), 30)
  INTO   ln_step
  FROM   feeders
  WHERE  mid = an_mid;

  ln_dif := ln_step / 1440;
  -- ln_dif := NVL(an_dif, util_pg.stephalfhour_f / 1440);
  -- ln_dif := NVL(an_dif, ln_step/ 1440);
  ln_daysw := util_pg.is_dayswitch(ad_date);
  ln_rid := util_pg.get_rate(ad_date);

--return;
  IF ln_rid IS NULL THEN
   raise_application_error(-20002, 'Не задано расписание тарифных зон.');
  END IF;

  IF NVL(an_mid, 0) > 0 THEN
   DELETE FROM billold
   WHERE       mid = an_mid AND date_time = ad_date + 1;

   INSERT INTO billold
               (mid, date_time, SOURCE, nsource, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2, dq2, q3, aq3, bq3,
                cq3, dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc, vqm, nqe)
    (SELECT   h.mid, ad_date + 1, 'Расч', NVL(SUM(nsource), 0), SUM(er) ers, SUM(DECODE(r.rate, 0, er, 0)) aers, SUM(DECODE(r.rate, 1, er, 0)) bers,
              SUM(DECODE(r.rate, 2, er, 0)) cers, SUM(DECODE(r.rate, 3, er, 0)) ders, SUM(ed) eds, SUM(DECODE(r.rate, 0, ed, 0)) aeds,
              SUM(DECODE(r.rate, 1, ed, 0)) beds, SUM(DECODE(r.rate, 2, ed, 0)) ceds, SUM(DECODE(r.rate, 3, ed, 0)) deds, SUM(q1) q1s,
              SUM(DECODE(r.rate, 0, q1, 0)) aq1s, SUM(DECODE(r.rate, 1, q1, 0)) bq1s, SUM(DECODE(r.rate, 2, q1, 0)) cq1s, SUM(DECODE(r.rate, 3, q1, 0)) dq1s,
              SUM(q2) q2s, SUM(DECODE(r.rate, 0, q2, 0)) aq2s, SUM(DECODE(r.rate, 1, q2, 0)) bq2s, SUM(DECODE(r.rate, 2, q2, 0)) cq2s,
              SUM(DECODE(r.rate, 3, q2, 0)) dq2s, SUM(q3) q3s, SUM(DECODE(r.rate, 0, q3, 0)) aq3s, SUM(DECODE(r.rate, 1, q3, 0)) bq3s,
              SUM(DECODE(r.rate, 2, q3, 0)) cq3s, SUM(DECODE(r.rate, 3, q3, 0)) dq3s, SUM(q4) q4s, SUM(DECODE(r.rate, 0, q4, 0)) aq4s,
              SUM(DECODE(r.rate, 1, q4, 0)) bq4s, SUM(DECODE(r.rate, 2, q4, 0)) cq4s, SUM(DECODE(r.rate, 3, q4, 0)) dq4s, AVG(h.nkc) er_kc, AVG(h.nkc) ed_kc,
              AVG(h.nkc) q1_kc, AVG(h.nkc) q3_kc,
              DECODE(
               COUNT(DISTINCT util_pg.trunc_d(util_pg.to_unlocaltime(h.date_time, h.nsource) - 1 / 86400, ln_dif)),
               ROUND(1 / ln_dif - ROUND((1 / 24) / ln_dif) * ln_daysw), NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm),
               qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
              ) qm,
              bitor(h.nqe) nqe
     FROM     halfhour h, rates r
     WHERE    h.mid = an_mid AND h.date_time > ad_date AND h.date_time <= ad_date + 1 AND r.rid = ln_rid
              AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') >= TO_CHAR(r.TIME, 'sssss')
              AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') < TO_CHAR(r.endtime, 'sssss')
     GROUP BY h.mid);
  /*  ----в 9i не работает
    MERGE INTO billold b
     USING (SELECT   h.mid, ad_date + 1 date_time, 'Расч' src, NVL(SUM(nsource), 0) nsource, SUM(er) ers,
                     SUM(DECODE(r.rate, 0, er, 0)) aers, SUM(DECODE(r.rate, 1, er, 0)) bers,
                     SUM(DECODE(r.rate, 2, er, 0)) cers, SUM(DECODE(r.rate, 3, er, 0)) ders, SUM(ed) eds,
                     SUM(DECODE(r.rate, 0, ed, 0)) aeds, SUM(DECODE(r.rate, 1, ed, 0)) beds,
                     SUM(DECODE(r.rate, 2, ed, 0)) ceds, SUM(DECODE(r.rate, 3, ed, 0)) deds, SUM(q1) q1s,
                     SUM(DECODE(r.rate, 0, q1, 0)) aq1s, SUM(DECODE(r.rate, 1, q1, 0)) bq1s,
                     SUM(DECODE(r.rate, 2, q1, 0)) cq1s, SUM(DECODE(r.rate, 3, q1, 0)) dq1s, SUM(q2) q2s,
                     SUM(DECODE(r.rate, 0, q2, 0)) aq2s, SUM(DECODE(r.rate, 1, q2, 0)) bq2s,
                     SUM(DECODE(r.rate, 2, q2, 0)) cq2s, SUM(DECODE(r.rate, 3, q2, 0)) dq2s, SUM(q3) q3s,
                     SUM(DECODE(r.rate, 0, q3, 0)) aq3s, SUM(DECODE(r.rate, 1, q3, 0)) bq3s,
                     SUM(DECODE(r.rate, 2, q3, 0)) cq3s, SUM(DECODE(r.rate, 3, q3, 0)) dq3s, SUM(q4) q4s,
                     SUM(DECODE(r.rate, 0, q4, 0)) aq4s, SUM(DECODE(r.rate, 1, q4, 0)) bq4s,
                     SUM(DECODE(r.rate, 2, q4, 0)) cq4s, SUM(DECODE(r.rate, 3, q4, 0)) dq4s, AVG(h.nkc) er_kc,
                     AVG(h.nkc) ed_kc, AVG(h.nkc) q1_kc, AVG(h.nkc) q3_kc,
                     DECODE(COUNT(DISTINCT util_pg.trunc_d(util_pg.to_unlocaltime(h.date_time,h.nsource) - 1 / 86400, ln_dif)),
                            ROUND(1 / ln_dif - ROUND((1 / 24) / ln_dif) * ln_daysw), NVL(sumqm(NVL(h.vqm, qm_pg.defqm)),
                                                                                         qm_pg.defqm),
                            qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
                           ) vqm,
                     bitor(h.nqe) nqe, COUNT(*) cn
                FROM halfhour h, rates r
               WHERE h.mid = an_mid
                 AND h.date_time > ad_date
                 AND h.date_time <= ad_date + 1
                 AND r.rid = ln_rid
                 AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') >= TO_CHAR(r.TIME, 'sssss')
                 AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') < TO_CHAR(r.endtime, 'sssss')
            GROUP BY h.mid) e
     ON (b.mid = an_mid AND b.date_time = ad_date + 1)
     WHEN MATCHED THEN
      UPDATE
         SET b.SOURCE = e.src, b.nsource = e.nsource, b.er = e.ers, b.aer = e.aers, b.ber = e.bers, b.cer = e.cers,
             b.der = e.ders, b.ed = e.eds, b.aed = e.aeds, b.bed = e.beds, b.ced = e.ceds, b.ded = e.deds, b.q1 = e.q1s,
             b.aq1 = e.aq1s, b.bq1 = e.bq1s, b.cq1 = e.cq1s, b.dq1 = e.dq1s, b.q2 = e.q2s, b.aq2 = e.aq2s,
             b.bq2 = e.bq2s, b.cq2 = e.cq2s, b.dq2 = e.dq2s, b.q3 = e.q3s, b.aq3 = e.aq3s, b.bq3 = e.bq3s,
             b.cq3 = e.cq3s, b.dq3 = e.dq3s, b.q4 = e.q4s, b.aq4 = e.aq4s, b.bq4 = e.bq4s, b.cq4 = e.cq4s,
             b.dq4 = e.dq4s, b.er_kc = e.er_kc, b.ed_kc = e.ed_kc, b.q1_kc = e.q1_kc, b.q3_kc = e.q3_kc, b.vqm = e.vqm,
             b.nqe = e.nqe
      DELETE
       WHERE (e.cn = 0)
     WHEN NOT MATCHED THEN
      INSERT(b.mid, b.date_time, b.SOURCE, b.nsource, b.er, b.aer, b.ber, b.cer, b.der, b.ed, b.aed, b.bed, b.ced, b.ded,
             b.q1, b.aq1, b.bq1, b.cq1, b.dq1, b.q2, b.aq2, b.bq2, b.cq2, b.dq2, b.q3, b.aq3, b.bq3, b.cq3, b.dq3, b.q4,
             b.aq4, b.bq4, b.cq4, b.dq4, b.er_kc, b.ed_kc, b.q1_kc, b.q3_kc, b.vqm, b.nqe)
      VALUES(e.mid, e.date_time, e.src, e.nsource, e.ers, e.aers, e.bers, e.cers, e.ders, e.eds, e.aeds, e.beds, e.ceds,
             e.deds, e.q1s, e.aq1s, e.bq1s, e.cq1s, e.dq1s, e.q2s, e.aq2s, e.bq2s, e.cq2s, e.dq2s, e.q3s, e.aq3s, e.bq3s,
             e.cq3s, e.dq3s, e.q4s, e.aq4s, e.bq4s, cq4s, e.dq4s, e.er_kc, e.ed_kc, e.q1_kc, e.q3_kc, e.vqm, e.nqe)
       WHERE (e.cn > 0);*/
  ELSE
   DELETE FROM billold
   WHERE       date_time = ad_date + 1;

   INSERT INTO billold
               (mid, date_time, SOURCE, nsource, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2, dq2, q3, aq3, bq3,
                cq3, dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc, vqm, nqe)
    (SELECT   h.mid, ad_date + 1, 'Расч', NVL(SUM(nsource), 0), SUM(er) ers, SUM(DECODE(r.rate, 0, er, 0)) aers, SUM(DECODE(r.rate, 1, er, 0)) bers,
              SUM(DECODE(r.rate, 2, er, 0)) cers, SUM(DECODE(r.rate, 3, er, 0)) ders, SUM(ed) eds, SUM(DECODE(r.rate, 0, ed, 0)) aeds,
              SUM(DECODE(r.rate, 1, ed, 0)) beds, SUM(DECODE(r.rate, 2, ed, 0)) ceds, SUM(DECODE(r.rate, 3, ed, 0)) deds, SUM(q1) q1s,
              SUM(DECODE(r.rate, 0, q1, 0)) aq1s, SUM(DECODE(r.rate, 1, q1, 0)) bq1s, SUM(DECODE(r.rate, 2, q1, 0)) cq1s, SUM(DECODE(r.rate, 3, q1, 0)) dq1s,
              SUM(q2) q2s, SUM(DECODE(r.rate, 0, q2, 0)) aq2s, SUM(DECODE(r.rate, 1, q2, 0)) bq2s, SUM(DECODE(r.rate, 2, q2, 0)) cq2s,
              SUM(DECODE(r.rate, 3, q2, 0)) dq2s, SUM(q3) q3s, SUM(DECODE(r.rate, 0, q3, 0)) aq3s, SUM(DECODE(r.rate, 1, q3, 0)) bq3s,
              SUM(DECODE(r.rate, 2, q3, 0)) cq3s, SUM(DECODE(r.rate, 3, q3, 0)) dq3s, SUM(q4) q4s, SUM(DECODE(r.rate, 0, q4, 0)) aq4s,
              SUM(DECODE(r.rate, 1, q4, 0)) bq4s, SUM(DECODE(r.rate, 2, q4, 0)) cq4s, SUM(DECODE(r.rate, 3, q4, 0)) dq4s, AVG(h.nkc), AVG(h.nkc), AVG(h.nkc),
              AVG(h.nkc),
              DECODE(
               COUNT(DISTINCT util_pg.trunc_d(util_pg.to_unlocaltime(h.date_time, h.nsource) - 1 / 86400, ln_dif)),
               ROUND(1 / ln_dif - ROUND((1 / 24) / ln_dif) * ln_daysw), NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm),
               qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
              ) qm,
              bitor(h.nqe) nqe
     FROM     halfhour h, rates r
     WHERE    h.date_time > ad_date AND h.date_time <= ad_date + 1 AND r.rid = ln_rid AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') >= TO_CHAR(r.TIME, 'sssss')
              AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') < TO_CHAR(r.endtime, 'sssss')
     GROUP BY h.mid);
/*   MERGE INTO billold b
    USING (SELECT   h.mid, ad_date + 1 date_time, 'Расч' src, NVL(SUM(nsource), 0) nsource, SUM(er) ers,
                    SUM(DECODE(r.rate, 0, er, 0)) aers, SUM(DECODE(r.rate, 1, er, 0)) bers,
                    SUM(DECODE(r.rate, 2, er, 0)) cers, SUM(DECODE(r.rate, 3, er, 0)) ders, SUM(ed) eds,
                    SUM(DECODE(r.rate, 0, ed, 0)) aeds, SUM(DECODE(r.rate, 1, ed, 0)) beds,
                    SUM(DECODE(r.rate, 2, ed, 0)) ceds, SUM(DECODE(r.rate, 3, ed, 0)) deds, SUM(q1) q1s,
                    SUM(DECODE(r.rate, 0, q1, 0)) aq1s, SUM(DECODE(r.rate, 1, q1, 0)) bq1s,
                    SUM(DECODE(r.rate, 2, q1, 0)) cq1s, SUM(DECODE(r.rate, 3, q1, 0)) dq1s, SUM(q2) q2s,
                    SUM(DECODE(r.rate, 0, q2, 0)) aq2s, SUM(DECODE(r.rate, 1, q2, 0)) bq2s,
                    SUM(DECODE(r.rate, 2, q2, 0)) cq2s, SUM(DECODE(r.rate, 3, q2, 0)) dq2s, SUM(q3) q3s,
                    SUM(DECODE(r.rate, 0, q3, 0)) aq3s, SUM(DECODE(r.rate, 1, q3, 0)) bq3s,
                    SUM(DECODE(r.rate, 2, q3, 0)) cq3s, SUM(DECODE(r.rate, 3, q3, 0)) dq3s, SUM(q4) q4s,
                    SUM(DECODE(r.rate, 0, q4, 0)) aq4s, SUM(DECODE(r.rate, 1, q4, 0)) bq4s,
                    SUM(DECODE(r.rate, 2, q4, 0)) cq4s, SUM(DECODE(r.rate, 3, q4, 0)) dq4s, AVG(h.nkc) er_kc,
                    AVG(h.nkc) ed_kc, AVG(h.nkc) q1_kc, AVG(h.nkc) q3_kc,
                    DECODE(COUNT(DISTINCT util_pg.trunc_d(util_pg.to_unlocaltime(h.date_time,h.nsource) - 1 / 86400, ln_dif)),
                           ROUND(1 / ln_dif - ROUND((1 / 24) / ln_dif) * ln_daysw), NVL(sumqm(NVL(h.vqm, qm_pg.defqm)),
                                                                                        qm_pg.defqm),
                           qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm)
                          ) vqm,
                    bitor(h.nqe) nqe, COUNT(*) cn
               FROM halfhour h, rates r
              WHERE h.date_time > ad_date
                AND h.date_time <= ad_date + 1
                AND r.rid = ln_rid
                AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') >= TO_CHAR(r.TIME, 'sssss')
                AND TO_CHAR(h.date_time - 1 / 1440, 'sssss') < TO_CHAR(r.endtime, 'sssss')
           GROUP BY h.mid) e
    ON (b.date_time = ad_date + 1 AND b.mid = e.mid)
    WHEN MATCHED THEN
     UPDATE
        SET b.SOURCE = e.src, b.nsource = e.nsource, b.er = e.ers, b.aer = e.aers, b.ber = e.bers, b.cer = e.cers,
            b.der = e.ders, b.ed = e.eds, b.aed = e.aeds, b.bed = e.beds, b.ced = e.ceds, b.ded = e.deds, b.q1 = e.q1s,
            b.aq1 = e.aq1s, b.bq1 = e.bq1s, b.cq1 = e.cq1s, b.dq1 = e.dq1s, b.q2 = e.q2s, b.aq2 = e.aq2s,
            b.bq2 = e.bq2s, b.cq2 = e.cq2s, b.dq2 = e.dq2s, b.q3 = e.q3s, b.aq3 = e.aq3s, b.bq3 = e.bq3s,
            b.cq3 = e.cq3s, b.dq3 = e.dq3s, b.q4 = e.q4s, b.aq4 = e.aq4s, b.bq4 = e.bq4s, b.cq4 = e.cq4s,
            b.dq4 = e.dq4s, b.er_kc = e.er_kc, b.ed_kc = e.ed_kc, b.q1_kc = e.q1_kc, b.q3_kc = e.q3_kc, b.vqm = e.vqm,
            b.nqe = e.nqe
     DELETE
      WHERE (e.cn = 0)
    WHEN NOT MATCHED THEN
     INSERT(b.mid, b.date_time, b.SOURCE, b.nsource, b.er, b.aer, b.ber, b.cer, b.der, b.ed, b.aed, b.bed, b.ced, b.ded,
            b.q1, b.aq1, b.bq1, b.cq1, b.dq1, b.q2, b.aq2, b.bq2, b.cq2, b.dq2, b.q3, b.aq3, b.bq3, b.cq3, b.dq3, b.q4,
            b.aq4, b.bq4, b.cq4, b.dq4, b.er_kc, b.ed_kc, b.q1_kc, b.q3_kc, b.vqm, b.nqe)
     VALUES(e.mid, e.date_time, e.src, e.nsource, e.ers, e.aers, e.bers, e.cers, e.ders, e.eds, e.aeds, e.beds, e.ceds,
            e.deds, e.q1s, e.aq1s, e.bq1s, e.cq1s, e.dq1s, e.q2s, e.aq2s, e.bq2s, e.cq2s, e.dq2s, e.q3s, e.aq3s, e.bq3s,
            e.cq3s, e.dq3s, e.q4s, e.aq4s, e.bq4s, cq4s, e.dq4s, e.er_kc, e.ed_kc, e.q1_kc, e.q3_kc, e.vqm, e.nqe)
      WHERE (e.cn > 0);*/
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20002,
       'CALCFORMULA_PG.ins_bill: Расчет и разноска по зонам суточных расходов: ad_date='''
    || TO_CHAR(ad_date, 'dd.mm.yyyy')
    || ''' an_mid='
    || an_mid
    || ' '
    || SQLERRM(SQLCODE));
 END;

---------------------------------------------------------------------------------------
 PROCEDURE calcpoint4bill(an_mid NUMBER, ad_start DATE, ad_end DATE) IS
  ld_start            DATE := TRUNC(ad_start);
 BEGIN
  IF ld_start = ad_end THEN
   ld_start := ld_start - 1;
  END IF;

  WHILE ld_start < ad_end LOOP
   ins_bill(ld_start, NULL, an_mid);
   ld_start := ld_start + 1;
  END LOOP;
 END;

---------------------------------------------------------------------------------------
 FUNCTION set_qe(an_mid NUMBER, ad_date DATE, an_source NUMBER)
  RETURN NUMBER IS
  ln_mid              NUMBER;
  ln_vevent           NUMBER;
  ld_test             DATE;
  ln_tag              NUMBER;
 BEGIN
  SELECT bitor(util_pg.varch2tonum(p.vevent))
  INTO   ln_vevent
  FROM   pqlog p
  WHERE  p.mid = an_mid AND ad_date >= p.dstart AND ad_date - 1 / 48 <= p.dend;

  IF ln_vevent IS NULL THEN                                                                                                           --если нет записи в PQLOG
   SELECT MIN(luck)
   INTO   ld_test
   FROM   last_save
   WHERE  luck > util_pg.to_unlocaltime(ad_date, an_source) AND mid = an_mid;

   IF ld_test IS NOT NULL THEN                                                                                                                           --0111
    SELECT MAX(tag)
    INTO   ln_tag
    FROM   points
    WHERE  mid = an_mid;

    IF ln_tag = 2 THEN
     ln_vevent := 3;
    ELSE
     ln_vevent := 5;
    END IF;
   ELSE
    ln_vevent := 0;
   END IF;
  END IF;

  RETURN ln_vevent;
 END;

-------------------------------------------------------------------------------------------------------
 PROCEDURE calc_lagging(an_isjob NUMBER) IS
  cn_shift   CONSTANT NUMBER := 1 / 1440;
  ld_sys              DATE := SYSDATE;
  ld_calcperiod       DATE := admin_pg.get_calcperiod;
  ld_last             DATE := admin_pg.get_lastdchange;
  ln_dif              NUMBER := util_pg.stephalfhour_f / 1440;
  lv_error            VARCHAR2(2000);
  f                   NUMBER;
 BEGIN
  DELETE FROM lastrec;

--Метим все не расчетные и записаваем в lastrec , а затем get_calcup рекурсивно использует lastrec и записывает в lastrecforrecalc (при выходе из get_calcup lastrec очищается)
  FOR lc IN (SELECT mid
             FROM   feeders
             WHERE  ncalcpointtype IS NULL
             MINUS
             SELECT f.mid
             FROM   feeders f, points p
             WHERE  f.ncalcpointtype IS NULL AND f.mid = p.mid AND p.ind = 4 AND EXISTS(SELECT *
                                                                                        FROM   points pp
                                                                                        WHERE  pp.PARENT = p.mid AND pp.ind IN(3, 4))) LOOP
   INSERT INTO lastrec
               (mid, ddate)
    SELECT DISTINCT lc.mid, TRUNC(date_time - 1 / 86400) ddate
    FROM            halfhourold
    WHERE           mid = lc.mid AND denter > ld_last - cn_shift
    ORDER BY        1, 2;
  END LOOP;

  --********   Заполним bill для старых периодов и всех не расчетные
  FOR lc IN (SELECT   mid, ddate
             FROM     lastrec
             WHERE    ddate <= ld_calcperiod
             ORDER BY 2 DESC, 1) LOOP
   ins_bill(lc.ddate, ln_dif, lc.mid);
   COMMIT;
  END LOOP;

  --********   А теперь расчет для тек периода
  get_calcup(0);                                                                                            --Заполняем lastrecforrecalc (+ все зависимые точки)
  calc(ld_calcperiod, NULL, 1);                                                            --Расчет текущего периода по lastrecforrecalc (+ все зависимые точки)
  COMMIT;

  --А теперь для lastrecforrecalc (+ все зависимые точки) заполним bill для тек периода
  FOR lc IN (SELECT   mid, ddate
             FROM     lastrecforrecalc
             WHERE    ddate <= ld_calcperiod
             ORDER BY 2 DESC, 1) LOOP
   ins_bill(lc.ddate, ln_dif, lc.mid);
   COMMIT;
  END LOOP;

  --Чистка (заполняли в get_calcup)
  DELETE FROM lastrecforrecalc;

  COMMIT;
  admin_pg.set_lastdchange(ld_sys);

  INSERT INTO jobs
              (njob, date_time)
  VALUES      (3, ld_sys);

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   IF an_isjob = 1 THEN
    lv_error := SQLERRM;
    ROLLBACK;

    INSERT INTO jobs
                (njob, date_time, errortext)
    VALUES      (3, ld_sys, lv_error);

    COMMIT;
   ELSE
    RAISE;
   END IF;
 END;

-------------------------------------------------------------------------------------------------------
--расчет отставших
 FUNCTION calc_lagging_job
  RETURN NUMBER IS
  ln_job              NUMBER;
  lc_proc    CONSTANT VARCHAR2(128) := 'CALCFORMULA_PG.CALC_LAGGING(1);';
 BEGIN
  SELECT MAX(job)
  INTO   ln_job
  FROM   user_jobs
  WHERE  what = lc_proc;

  IF ln_job > 0 THEN
   RETURN ln_job;
  END IF;

  DBMS_JOB.submit(ln_job, lc_proc, SYSDATE, NULL);
  COMMIT;
  RETURN ln_job;
 END;

-------------------------------------------------------------------------------------------------------
 PROCEDURE calc_lagging_job(an_maket NUMBER DEFAULT NULL, ad_date DATE DEFAULT NULL) IS
  ln_ret              NUMBER;
 BEGIN
  ln_ret := calc_lagging_job;
 END;

-------------------------------------------------------------------------------------------------------
 PROCEDURE getval_30817w(ar_info tcalcinfo, ad_from DATE, ad_till DATE) IS
  ln_round            NUMBER := 0;
  ln_everyday         NUMBER := 0;
  ln_bank             NUMBER := 0;
  ld_fromh            DATE;
  ner                 NUMBER;
  ned                 NUMBER;
  nq1                 NUMBER;
  nq2                 NUMBER;
  nq3                 NUMBER;
  nq4                 NUMBER;
  tner                NUMBER;
  tned                NUMBER;
  tnq1                NUMBER;
  tnq2                NUMBER;
  tnq3                NUMBER;
  tnq4                NUMBER;
  ld_from             DATE := util_pg.to_unlocaltime(TRUNC(util_pg.to_localtime(ad_from)));
  ld_till             DATE := ad_till;
  ld_till_l           DATE := util_pg.to_localtime(ld_till);
  nermod              NUMBER := 0;
  nedmod              NUMBER := 0;
  nq1mod              NUMBER := 0;
  nq2mod              NUMBER := 0;
  nq3mod              NUMBER := 0;
  nq4mod              NUMBER := 0;
  tnermod             NUMBER := 0;
  tnedmod             NUMBER := 0;
  tnq1mod             NUMBER := 0;
  tnq2mod             NUMBER := 0;
  tnq3mod             NUMBER := 0;
  tnq4mod             NUMBER := 0;
  an_period           NUMBER;
  ln_mid              NUMBER;
 BEGIN
  IF ar_info.nopttype IN(editformula_pg.cn_opttype2, editformula_pg.cn_opttype7) THEN                                                               --В тысячах
   ln_round := -3;
  END IF;

  IF ar_info.nopttype IN(editformula_pg.cn_opttype7, editformula_pg.cn_opttype8) THEN
   --Сброс остатков каждый день (не переносим на следующий день) и банковское округление
   ln_everyday := 1;
   ln_bank := 1;
  END IF;

  IF ar_info.nhoureriod = 1 THEN
   an_period := 24;
  ELSE
   an_period := 48;
  END IF;

  SELECT MAX(p.mid)
  INTO   ln_mid
  FROM   formulparams p
  WHERE  nid = ar_info.ID;

  FOR lc IN (SELECT                                                                                   /*  ld_from
                                                                                                      + (  util_pg.get_num_dt( h.date_time - 1 / 86400, nsource,
                                                                                                                              1 / an_period, 0, 0, 0)
                                                                                                         / an_period
                                                                                                        ) date_time,*/
                      ld_from + get_num_dtw(h.date_time - 1 / 86400, nsource, ld_from, an_period) / an_period date_time, SUM(h.er) er, SUM(h.ed) ed,
                      SUM(h.q1) q1, SUM(h.q3) q3, SUM(h.q2) q2, SUM(h.q4) q4, sumqm(h.vqm) vqm
             FROM     halfhour h
             WHERE    h.mid = ln_mid                                                                                                               --ar_info.mid
                      AND h.date_time > ld_from AND h.date_time <= ld_till + 1 / 24 AND util_pg.to_unlocaltime(h.date_time, h.nsource) > ld_from
                      AND util_pg.to_unlocaltime(h.date_time, h.nsource) <= ld_till
             GROUP BY (                                                                                             /*  util_pg.get_num_dt(
                                                                                                                                     h.date_time - 1 / 86400
                                                                                                                                          , nsource,
                                                                                                                                         1 / an_period, 0, 0, 0)
                                                                                                                    / an_period*/
                       get_num_dtw(h.date_time - 1 / 86400, nsource, ld_from, an_period) / an_period)
             ORDER BY 1) LOOP
---------------------------------------------------- разложение на получасовки при часовом периоде интеграции
   IF ar_info.nhoureriod = 1 THEN
    FOR i IN 1 .. 2 LOOP
     ld_fromh := lc.date_time;
     ner := lc.er;
     ned := lc.ed;
     nq1 := lc.q1;
     nq2 := lc.q2;
     nq3 := lc.q3;
     nq4 := lc.q4;
     gethourperiod(i, ar_info.ndivtype, ld_fromh, ner, ned, nq1, nq2, nq3, nq4);
     getroundvalue(ar_info.mid, ar_info.meas, util_pg.to_localtime(ld_fromh - 1 / 48), ln_round, ner, nermod, ned, nedmod, nq1, nq1mod, nq2, nq2mod, nq3,
      nq3mod, nq4, nq4mod, ln_everyday, ln_bank);
-------------------------------------------------------end;
   --  insert into tmp_vil values ('zfbgfb');commit;
     ins_halfhouroldw(ar_info.mid, ld_fromh, ner, ned, nq1, nq3, nq2, nq4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1, NULL);
    END LOOP;
   ELSE
    ner := lc.er;
    ned := lc.ed;
    nq1 := lc.q1;
    nq2 := lc.q2;
    nq3 := lc.q3;
    nq4 := lc.q4;
    getroundvalue(ar_info.mid, ar_info.meas, util_pg.to_localtime(lc.date_time - 1 / 48), ln_round, ner, nermod, ned, nedmod, nq1, nq1mod, nq2, nq2mod, nq3,
     nq3mod, nq4, nq4mod, ln_everyday, ln_bank);
    --   insert into tmp_vil values ('vnfvhnfhjtf');commit;
    ins_halfhouroldw(ar_info.mid, lc.date_time, ner, ned, nq1, nq3, nq2, nq4, NULL, comsrv_pg.cn_calc, lc.vqm, ar_info.nswitch, NULL, 1, 1, NULL);
   END IF;
  END LOOP;

  IF ld_till_l = TRUNC(ld_till_l) AND ad_from < ad_till THEN
   UPDATE round30817
   SET er = DECODE(nermod, NULL, er, nermod),
       ed = DECODE(nedmod, NULL, ed, nedmod),
       q1 = DECODE(nq1mod, NULL, q1, nq1mod),
       q2 = DECODE(nq2mod, NULL, q2, nq2mod),
       q3 = DECODE(nq3mod, NULL, q3, nq3mod),
       q4 = DECODE(nq4mod, NULL, q4, nq4mod)
   WHERE  mid = ar_info.mid AND date_time = ld_till_l;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO round30817
                (mid, date_time, er, ed, q1, q2, q3, q4)
    VALUES      (ar_info.mid, ld_till_l, nermod, nedmod, nq1mod, nq2mod, nq3mod, nq4mod);
   END IF;
  END IF;
 END;

-------------------------------------------------------------------------------------------------------------
 PROCEDURE gethourperiod(
 an_i NUMBER, ndivtype NUMBER, an_datetime IN OUT DATE, an_er IN OUT NUMBER, an_ed IN OUT NUMBER, an_q1 IN OUT NUMBER, an_q2 IN OUT NUMBER, an_q3 IN OUT NUMBER,
 an_q4 IN OUT NUMBER
 ) IS
  ld_fromh            DATE;
  ner                 NUMBER;
  ned                 NUMBER;
  nq1                 NUMBER;
  nq2                 NUMBER;
  nq3                 NUMBER;
  nq4                 NUMBER;
 BEGIN
  IF ndivtype = 1 THEN
   IF an_i = 1 THEN
    ld_fromh := an_datetime - 1 / 48;

    IF an_er <> util_pg.cn_random THEN
     ner := TRUNC(an_er / 2);
    ELSE
     ner := an_er;
    END IF;

    IF an_ed <> util_pg.cn_random THEN
     ned := TRUNC(an_ed / 2);
    ELSE
     ned := an_ed;
    END IF;

    IF an_q1 <> util_pg.cn_random THEN
     nq1 := TRUNC(an_q1 / 2);
    ELSE
     nq1 := an_q1;
    END IF;

    IF an_q2 <> util_pg.cn_random THEN
     nq2 := TRUNC(an_q2 / 2);
    ELSE
     nq2 := an_q2;
    END IF;

    IF an_q3 <> util_pg.cn_random THEN
     nq3 := TRUNC(an_q3 / 2);
    ELSE
     nq3 := an_q3;
    END IF;

    IF an_q4 <> util_pg.cn_random THEN
     nq4 := TRUNC(an_q4 / 2);
    ELSE
     nq4 := an_q4;
    END IF;
   ELSE
    ld_fromh := an_datetime;

    IF an_er <> util_pg.cn_random THEN
     ner := an_er - TRUNC(an_er / 2);
    ELSE
     ner := an_er;
    END IF;

    IF an_ed <> util_pg.cn_random THEN
     ned := an_ed - TRUNC(an_ed / 2);
    ELSE
     ned := an_ed;
    END IF;

    IF an_q1 <> util_pg.cn_random THEN
     nq1 := an_q1 - TRUNC(an_q1 / 2);
    ELSE
     nq1 := an_q1;
    END IF;

    IF an_q2 <> util_pg.cn_random THEN
     nq2 := an_q2 - TRUNC(an_q2 / 2);
    ELSE
     nq2 := an_q2;
    END IF;

    IF an_q3 <> util_pg.cn_random THEN
     nq3 := an_q3 - TRUNC(an_q3 / 2);
    ELSE
     nq3 := an_q3;
    END IF;

    IF an_q4 <> util_pg.cn_random THEN
     nq4 := an_q4 - TRUNC(an_q4 / 2);
    ELSE
     nq4 := an_q4;
    END IF;
   END IF;
  ELSE
   IF an_i = 1 THEN
    ld_fromh := an_datetime - 1 / 48;

    IF an_er <> util_pg.cn_random THEN
     ner := ROUND(an_er - an_er);
    ELSE
     ner := an_er;
    END IF;

    IF an_ed <> util_pg.cn_random THEN
     ned := ROUND(an_ed - an_ed);
    ELSE
     ned := an_ed;
    END IF;

    IF an_q1 <> util_pg.cn_random THEN
     nq1 := ROUND(an_q1 - an_q1);
    ELSE
     nq1 := an_q1;
    END IF;

    IF an_q2 <> util_pg.cn_random THEN
     nq2 := ROUND(an_q2 - an_q2);
    ELSE
     nq2 := an_q2;
    END IF;

    IF an_q3 <> util_pg.cn_random THEN
     nq3 := ROUND(an_q3 - an_q3);
    ELSE
     nq3 := an_q3;
    END IF;

    IF an_q4 <> util_pg.cn_random THEN
     nq4 := ROUND(an_q4 - an_q4);
    ELSE
     nq4 := an_q4;
    END IF;
   ELSE
    ld_fromh := an_datetime;
    ner := an_er;
    ned := an_ed;
    nq1 := an_q1;
    nq2 := an_q2;
    nq3 := an_q3;
    nq4 := an_q4;
   END IF;
  END IF;

  an_datetime := ld_fromh;
  an_er := ner;
  an_ed := ned;
  an_q1 := nq1;
  an_q2 := nq2;
  an_q3 := nq3;
  an_q4 := nq4;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE getroundvalue(
 an_mid NUMBER, an_meas NUMBER, ad_fromh DATE, an_round NUMBER, an_ner IN OUT NUMBER, an_nermod IN OUT NUMBER, an_ned IN OUT NUMBER, an_nedmod IN OUT NUMBER,
 an_nq1 IN OUT NUMBER, an_nq1mod IN OUT NUMBER, an_nq2 IN OUT NUMBER, an_nq2mod IN OUT NUMBER, an_nq3 IN OUT NUMBER, an_nq3mod IN OUT NUMBER,
 an_nq4 IN OUT NUMBER, an_nq4mod IN OUT NUMBER, an_everyday NUMBER, an_bank NUMBER
 ) IS
  nerround            NUMBER := util_pg.cn_random;
  nermod              NUMBER;
  nedround            NUMBER := util_pg.cn_random;
  nedmod              NUMBER;
  nq1round            NUMBER := util_pg.cn_random;
  nq1mod              NUMBER;
  nq2round            NUMBER := util_pg.cn_random;
  nq2mod              NUMBER;
  nq3round            NUMBER := util_pg.cn_random;
  nq3mod              NUMBER;
  nq4round            NUMBER := util_pg.cn_random;
  nq4mod              NUMBER;
  testnermod          NUMBER := an_nermod;
  testnedmod          NUMBER := an_nedmod;
  testnq1mod          NUMBER := an_nq1mod;
  testnq2mod          NUMBER := an_nq2mod;
  testnq3mod          NUMBER := an_nq3mod;
  testnq4mod          NUMBER := an_nq4mod;
 BEGIN
  IF ad_fromh = TRUNC(ad_fromh) THEN
   IF ad_fromh = TRUNC(ad_fromh, 'MONTH') OR an_everyday = 1 OR util_pg.nlockrounderr = 1
      OR(TO_CHAR(ad_fromh, 'YYYYMM') = 201305 AND util_pg.get_customer_id IN(41, 43)) THEN
    /*Эта фигня с get_customer_id in (41,43) за 201305 из-за поддержки ошибки, котороя возникла и чтоб при пересчете она сохранялась*/
    testnermod := 0;
    testnedmod := 0;
    testnq1mod := 0;
    testnq2mod := 0;
    testnq3mod := 0;
    testnq4mod := 0;                                                                                                          --Обнуляем остатки в конце месяца
   ELSE
    SELECT NVL(MAX(a.er), 0), NVL(MAX(a.ed), 0), NVL(MAX(a.q1), 0), NVL(MAX(a.q2), 0), NVL(MAX(a.q3), 0), NVL(MAX(a.q4), 0)
    INTO   testnermod, testnedmod, testnq1mod, testnq2mod, testnq3mod, testnq4mod
    FROM   round30817 a
    WHERE  a.mid = an_mid AND a.date_time = ad_fromh;
   END IF;
  END IF;

  IF an_meas = 1 THEN
   nerround := round05(an_ner, testnermod, an_round, an_bank);                                                         -- ROUND(an_ner + testnermod, an_round);
   nermod := (an_ner + testnermod) - nerround;
  ELSIF an_meas = 2 THEN
   nedround := round05(an_ned, testnedmod, an_round, an_bank);
   nedmod := (an_ned + testnedmod) - nedround;
  ELSIF an_meas = 3 THEN
   nq1round := round05(an_nq1, testnq1mod, an_round, an_bank);
   nq1mod := (an_nq1 + testnq1mod) - nq1round;
  ELSIF an_meas = 4 THEN
   nq2round := round05(an_nq2, testnq2mod, an_round, an_bank);
   nq2mod := (an_nq2 + testnq2mod) - nq2round;
  ELSIF an_meas = 5 THEN
   nq3round := round05(an_nq3, testnq3mod, an_round, an_bank);
   nq3mod := (an_nq3 + testnq3mod) - nq3round;
  ELSIF an_meas = 6 THEN
   nq4round := round05(an_nq4, testnq4mod, an_round, an_bank);
   nq4mod := (an_nq4 + testnq4mod) - nq4round;
  ELSIF an_meas = 0 THEN
   nerround := round05(an_ner, testnermod, an_round, an_bank);
   nermod := (an_ner + testnermod) - nerround;
   nedround := round05(an_ned, testnedmod, an_round, an_bank);
   nedmod := (an_ned + testnedmod) - nedround;
   nq1round := round05(an_nq1, testnq1mod, an_round, an_bank);
   nq1mod := (an_nq1 + testnq1mod) - nq1round;
   nq2round := round05(an_nq2, testnq2mod, an_round, an_bank);
   nq2mod := (an_nq2 + testnq2mod) - nq2round;
   nq3round := round05(an_nq3, testnq3mod, an_round, an_bank);
   nq3mod := (an_nq3 + testnq3mod) - nq3round;
   nq4round := round05(an_nq4, testnq4mod, an_round, an_bank);
   nq4mod := (an_nq4 + testnq4mod) - nq4round;
  -- insert into tmp_vil values (nerround||' '||an_mid);
  END IF;

  an_ner := nerround;
  an_nermod := nermod;
  an_ned := nedround;
  an_nedmod := nedmod;
  an_nq1 := nq1round;
  an_nq1mod := nq1mod;
  an_nq2 := nq2round;
  an_nq2mod := nq2mod;
  an_nq3 := nq3round;
  an_nq3mod := nq3mod;
  an_nq4 := nq4round;
  an_nq4mod := nq4mod;
 END;

-------------------------------------------------------------------------------------------------
 PROCEDURE getval_vinn(ar_info tcalcinfo, ad_from DATE, ad_till DATE) IS
  ld_from             DATE;
  ld_till             DATE;
  ld_fromh            DATE;
  ld_fromm            DATE;
  an_period           NUMBER;
  ln_kc               NUMBER := 1;
  lr_info             tcalcinfo;
  lt_info             ttcalcinfo;
  lt_paramval         common_pg.tt_double;
  ln_cnt              NUMBER DEFAULT 0;
  sumed               NUMBER := NULL;
  sumer               NUMBER := NULL;
  sumq1               NUMBER := NULL;
  sumq2               NUMBER := NULL;
  sumq3               NUMBER := NULL;
  sumq4               NUMBER := NULL;
  gnsumed             NUMBER;
  gnsumer             NUMBER;
  gnsumq1             NUMBER;
  gnsumq2             NUMBER;
  gnsumq3             NUMBER;
  gnsumq4             NUMBER;
  nermod              NUMBER := 0;
  nedmod              NUMBER := 0;
  nq1mod              NUMBER := 0;
  nq2mod              NUMBER := 0;
  nq3mod              NUMBER := 0;
  nq4mod              NUMBER := 0;
  teste               NUMBER := 0;
  testq               NUMBER := 0;
  testround           NUMBER := 100;
  test30817           NUMBER := 0;
  ner                 NUMBER;
  ned                 NUMBER;
  nq1                 NUMBER;
  nq2                 NUMBER;
  nq3                 NUMBER;
  nq4                 NUMBER;
  ln_res              NUMBER;
  ln_mid              NUMBER;
  ln_rn               NUMBER DEFAULT 0;
  ln_digits1          NUMBER;
  ln_digits2          NUMBER;
  ln_digits3          NUMBER;
  ln_digits4          NUMBER;
  ln_rn1              NUMBER := 0;
  ln_rn2              NUMBER := 0;
  ln_rn3              NUMBER := 0;
  ln_rn4              NUMBER := 0;
  ln_itemcnt          NUMBER;
  ln_timeshift        NUMBER;
/*  testnermod    NUMBER;
  testnedmod    NUMBER;
  testnq1mod    NUMBER;
  testnq2mod    NUMBER;
  testnq3mod    NUMBER;
  testnq4mod    NUMBER;  */
  reser               NUMBER;
  resed               NUMBER;
  resq1               NUMBER;
  resq2               NUMBER;
  resq3               NUMBER;
  resq4               NUMBER;
  ld_till_l           DATE := util_pg.to_localtime(ad_till);
  TEST                NUMBER;
  rcount              NUMBER := 0;
 BEGIN
/* IF util_pg.get_customer_id = 39 THEN
     getval_vinn2(ar_info , TRUNC(util_pg.to_localtime(ad_from)), TRUNC(util_pg.to_localtime(ad_till)) );
 RETURN;
 END IF;
 */
  SELECT MAX(p.mid)
  INTO   ln_mid
  FROM   formulparams p
  WHERE  nid = ar_info.ID;

/*  FOR lc1 IN (SELECT entype, digits
              FROM   meters
              WHERE  mid = ln_mid) LOOP
   IF lc1.entype = 1 OR lc1.entype = 7 THEN
    ln_digits1 := lc1.digits;
   ELSIF lc1.entype = 2 OR lc1.entype = 7 THEN
    ln_digits2 := lc1.digits;
   ELSIF lc1.entype = 3 OR lc1.entype = 7 THEN
    ln_digits3 := lc1.digits;
   ELSIF lc1.entype = 5 OR lc1.entype = 7 THEN
    ln_digits4 := lc1.digits;
   END IF;
  END LOOP;*/

  /* FOR lc2 IN (SELECT nsort, vvalue
               FROM   addpointparamval
               WHERE  nsort BETWEEN -30 AND -25 AND mid = ln_mid) LOOP
    IF lc2.nsort = -25 THEN
     tester := lc2.vvalue;
    ELSIF lc2.nsort = -26 THEN
     tested := lc2.vvalue;
    ELSIF lc2.nsort = -27 THEN
     testq1 := lc2.vvalue;
    ELSIF lc2.nsort = -28 THEN
     testq2 := lc2.vvalue;
    ELSIF lc2.nsort = -29 THEN
     testq3 := lc2.vvalue;
    ELSIF lc2.nsort = -30 THEN
     testq4 := lc2.vvalue;
    END IF;
   END LOOP;
   */
  FOR lc2 IN (SELECT nsort, vvalue
              FROM   addpointparamval
              -- WHERE  nsort BETWEEN -28 AND -25 AND mid = ln_mid) LOOP
              WHERE  nsort BETWEEN -28 AND -25 AND mid = ar_info.mid) LOOP
   IF lc2.nsort = -25 THEN
    teste := lc2.vvalue;
   ELSIF lc2.nsort = -26 THEN
    testq := lc2.vvalue;
   ELSIF lc2.nsort = -27 THEN
    testround := lc2.vvalue;
   ELSIF lc2.nsort = -28 THEN
    test30817 := lc2.vvalue;
   END IF;
  END LOOP;

--  IF  testround IS NULL THEN testround:=100 END IF;

  --  IF testq2 = 0 THEN
/* IF test30817 = 0 THEN
 --  getval_30817w(ar_info, ad_from, ad_till, an_round);
  getval_30817w(ar_info, ad_from, ad_till, 0);
--   getval_30817w(ar_info, ad_from, ad_till, testround);

   RETURN;
  END IF;*/
  IF test30817 = 0 THEN
   testround := 0;
  END IF;

  ln_rn1 := testround;
  ln_rn2 := testround;
  ln_rn3 := testround;
  ln_rn4 := testround;
  ld_till := TRUNC(util_pg.to_localtime(ad_till));
  ld_from := TRUNC(util_pg.to_localtime(ad_from));

  IF ar_info.nhoureriod = 1 THEN
   an_period := 24;
  ELSE
   an_period := 48;
  END IF;

  ln_itemcnt := ROUND((ld_till - ld_from) * an_period);

  SELECT MAX(NVL(f.kc, 1)), util_pg.cn_tzw - MAX(NVL(ntimezonew, 2))
  -- SELECT MAX(nvl(f.kc,1)), MAX(NVL(NTIMEZONEW,2))
  INTO   ln_kc, ln_timeshift
  FROM   feeders f
  WHERE  f.mid = ln_mid;

  IF ln_kc IS NULL THEN
   ln_kc := 1;
  END IF;

  IF ln_timeshift IS NULL THEN
   ln_timeshift := 0;
  END IF;

  SELECT DECODE(
          test30817,
          0, MAX(DECODE(SIGN(nxt.erm - prv.erm), -1, POWER(10, CEIL(LOG(10, prv.erm))) - prv.erm + nxt.erm, nxt.erm - prv.erm) * ln_kc),
          MAX(ROUND(DECODE(SIGN(nxt.erm - prv.erm), -1, POWER(10, CEIL(LOG(10, prv.erm))) - prv.erm + nxt.erm, nxt.erm - prv.erm) * ln_kc, testround))
         ),
         DECODE(
          test30817,
          0, MAX(DECODE(SIGN(nxt.edm - prv.edm), -1, POWER(10, CEIL(LOG(10, prv.edm))) - prv.edm + nxt.edm, nxt.edm - prv.edm) * ln_kc),
          MAX(ROUND(DECODE(SIGN(nxt.edm - prv.edm), -1, POWER(10, CEIL(LOG(10, prv.edm))) - prv.edm + nxt.edm, nxt.edm - prv.edm) * ln_kc, testround))
         ),
         DECODE(
          test30817,
          0, MAX(DECODE(SIGN(nxt.q1m - prv.q1m), -1, POWER(10, CEIL(LOG(10, prv.q1m))) - prv.q1m + nxt.q1m, nxt.q1m - prv.q1m) * ln_kc),
          MAX(ROUND(DECODE(SIGN(nxt.q1m - prv.q1m), -1, POWER(10, CEIL(LOG(10, prv.q1m))) - prv.q1m + nxt.q1m, nxt.q1m - prv.q1m) * ln_kc, testround))
         ),
         DECODE(
          test30817,
          0, MAX(DECODE(SIGN(nxt.q2m - prv.q2m), -1, POWER(10, CEIL(LOG(10, prv.q2m))) - prv.q2m + nxt.q2m, nxt.q2m - prv.q2m) * ln_kc),
          MAX(ROUND(DECODE(SIGN(nxt.q2m - prv.q2m), -1, POWER(10, CEIL(LOG(10, prv.q2m))) - prv.q2m + nxt.q2m, nxt.q2m - prv.q2m) * ln_kc, testround))
         ),
         DECODE(
          test30817,
          0, MAX(DECODE(SIGN(nxt.q3m - prv.q3m), -1, POWER(10, CEIL(LOG(10, prv.q3m))) - prv.q3m + nxt.q3m, nxt.q3m - prv.q3m) * ln_kc),
          MAX(ROUND(DECODE(SIGN(nxt.q3m - prv.q3m), -1, POWER(10, CEIL(LOG(10, prv.q3m))) - prv.q3m + nxt.q3m, nxt.q3m - prv.q3m) * ln_kc, testround))
         ),
         DECODE(
          test30817,
          0, MAX(DECODE(SIGN(nxt.q4m - prv.q4m), -1, POWER(10, CEIL(LOG(10, prv.q4m))) - prv.q4m + nxt.q4m, nxt.q4m - prv.q4m) * ln_kc),
          MAX(ROUND(DECODE(SIGN(nxt.q4m - prv.q4m), -1, POWER(10, CEIL(LOG(10, prv.q4m))) - prv.q4m + nxt.q4m, nxt.q4m - prv.q4m) * ln_kc, testround))
         )
  INTO   sumer, sumed, sumq1, sumq2, sumq3, sumq4
  FROM   billorg prv, billorg nxt
  WHERE  prv.mid = ln_mid AND nxt.mid = prv.mid AND prv.date_time = ld_from + ln_timeshift / 24                           --TRUNC(util_pg.to_localtime(ad_from))
         AND nxt.date_time = ld_till + ln_timeshift / 24                                                                  --TRUNC(util_pg.to_localtime(ad_till))
         AND prv.nsource = nxt.nsource AND ROWNUM = 1;

  -- insert into tmp_vil  values (to_char(ld_from)||' '||ln_timeshift);commit;
/*  SELECT MAX(ROUND(util_pg.indicoverturn(t2.er - t1.er, ln_digits2) * ln_kc, ln_rn2)) ner,                                                  --показания за сутки
         MAX(ROUND(util_pg.indicoverturn(t2.ed - t1.ed, ln_digits1) * ln_kc, ln_rn1)) ned,
         MAX(ROUND(util_pg.indicoverturn(t2.q1 - t1.q1, ln_digits3) * ln_kc, ln_rn3)) nq1,
         MAX(ROUND(util_pg.indicoverturn(t2.q2 - t1.q2, ln_digits3) * ln_kc, ln_rn3)) nq2,
         MAX(ROUND(util_pg.indicoverturn(t2.q3 - t1.q3, ln_digits4) * ln_kc, ln_rn4)) nq3,
         MAX(ROUND(util_pg.indicoverturn(t2.q4 - t1.q4, ln_digits4) * ln_kc, ln_rn4)) nq4
  INTO   sumer, sumed, sumq1, sumq2, sumq3, sumq4
  FROM   (SELECT mid, b.date_time, b.erm er, b.edm ed, b.q1m q1, b.q2m q2, b.q3m q3, b.q4m q4
          FROM   billorg b
          WHERE  b.mid = ln_mid AND b.date_time = ld_from + ln_timeshift / 24) t1,
         (SELECT mid, b.date_time, b.erm er, b.edm ed, b.q1m q1, b.q2m q2, b.q3m q3, b.q4m q4
          FROM   billorg b
          WHERE  b.mid = ln_mid AND b.date_time = ld_till + ln_timeshift / 24) t2;

 /*
 IF sumer IS NULL AND sumed IS NULL AND sumq1 IS NULL AND sumq2 IS NULL AND sumq3 IS NULL THEN
 --  getval_30817w(ar_info, ad_from, ad_till, an_round);
    getval_30817w(ar_info, ad_from, ad_till, testround);
  --  insert into tmp_vil values(testround||' '||ar_info.mid);
   RETURN;
  END IF;
*/
-- sumq2, sumq3, sumq4*/
  FOR i IN 1 .. ln_itemcnt LOOP
   lr_info.er := NULL;
   lr_info.ed := NULL;
   lr_info.q1 := NULL;
   lr_info.q2 := NULL;
   lr_info.q3 := NULL;
   lr_info.q4 := NULL;
   lt_info(i) := lr_info;
  END LOOP;

  FOR lc IN (SELECT   DECODE(
                       GROUPING(get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_timeshift / 24, an_period)),
                       1, 0,
                       (get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_timeshift / 24, an_period))
                      ) num,
                      SUM(h.er) sumer, SUM(h.ed) sumed, SUM(h.q1) sumq1, SUM(h.q2) sumq2, SUM(h.q3) sumq3, SUM(h.q4) sumq4,
                      DECODE(test30817, 0, SUM(h.er), SUM(ROUND(h.er, ln_rn2))) er, DECODE(test30817, 0, SUM(h.ed), SUM(ROUND(h.ed, ln_rn1))) ed,
                      DECODE(test30817, 0, SUM(h.q1), SUM(ROUND(h.q1, ln_rn3))) q1, DECODE(test30817, 0, SUM(h.q3), SUM(ROUND(h.q3, ln_rn3))) q3,
                      DECODE(test30817, 0, SUM(h.q2), SUM(ROUND(h.q2, ln_rn4))) q2, DECODE(test30817, 0, SUM(h.q4), SUM(ROUND(h.q4, ln_rn4))) q4,
                      sumqm(h.vqm) vqm
             FROM     halfhour h
             WHERE    h.mid = ln_mid AND h.date_time > ad_from + ln_timeshift / 24 AND h.date_time <= ad_till + ln_timeshift / 24 + 1 / 24
                      AND util_pg.to_unlocaltime(h.date_time, h.nsource) > ad_from + ln_timeshift / 24
                      AND util_pg.to_unlocaltime(h.date_time, h.nsource) <= ad_till + ln_timeshift / 24
             GROUP BY ROLLUP(get_num_dtw(h.date_time - 1 / 86400, nsource, ad_from + ln_timeshift / 24, an_period))
             ORDER BY 1) LOOP
   rcount := 1;

   IF lc.num = 0 THEN
    IF sumer IS NULL THEN
     sumer := lc.sumer;
    END IF;

    IF sumer IS NULL THEN
     sumed := lc.sumed;
    END IF;

    IF sumer IS NULL THEN
     sumq1 := lc.sumq1;
    END IF;

    IF sumer IS NULL THEN
     sumq2 := lc.sumq2;
    END IF;

    IF sumer IS NULL THEN
     sumq3 := lc.sumq3;
    END IF;

    IF sumer IS NULL THEN
     sumq4 := lc.sumq4;
    END IF;

    gnsumed := lc.ed;
    gnsumer := lc.er;
    gnsumq1 := lc.q1;
    gnsumq2 := lc.q2;
    gnsumq3 := lc.q3;
    gnsumq4 := lc.q4;
   ELSE
    IF ar_info.nhoureriod = 1 THEN
     FOR i IN 1 .. 2 LOOP
      ld_fromh := ad_from + lc.num / an_period;
      ner := lc.er;
      ned := lc.ed;
      nq1 := lc.q1;
      nq2 := lc.q2;
      nq3 := lc.q3;
      nq4 := lc.q4;
      gethourperiod(i, ar_info.ndivtype, ld_fromh, ner, ned, nq1, nq2, nq3, nq4);
      lr_info.er := ner;
      lr_info.ed := ned;
      lr_info.q1 := nq1;
      lr_info.q2 := nq2;
      lr_info.q3 := nq3;
      lr_info.q4 := nq4;
      lr_info.qm := lc.vqm;

      IF i = 1 THEN
       lt_info(lc.num * 2 - 1) := lr_info;
      ELSE
       lt_info(lc.num * 2) := lr_info;
      END IF;
     END LOOP;
    ELSE
     lr_info.er := lc.er;
     lr_info.ed := lc.ed;
     lr_info.q1 := lc.q1;
     lr_info.q2 := lc.q2;
     lr_info.q3 := lc.q3;
     lr_info.q4 := lc.q4;
     lr_info.qm := lc.vqm;
     lt_info(lc.num) := lr_info;
    END IF;
   END IF;
  END LOOP;

  ln_cnt := ln_itemcnt;

  IF ABS(sumed - gnsumed) > 0 THEN
   -- IF (tested = 0 OR ABS(sumed - gnsumed) <= tested) THEN
   IF (teste = 0 OR ABS(sumed - gnsumed) <= teste) THEN
    FOR i IN 1 .. ln_cnt LOOP
     lt_paramval(i) := lt_info(i).ed;
    END LOOP;

    getvalm(sumed, gnsumed, ln_cnt, lt_paramval);

    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).ed := lt_paramval(i);
    END LOOP;
   ELSE
    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 16, qm_pg.cn_add_err);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 3, qm_pg.cn_yes);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 1, qm_pg.cn_invalid);
    END LOOP;
   END IF;
  END IF;

  IF ABS(sumer - gnsumer) > 0 THEN
   --  IF (tester = 0 OR ABS(sumer - gnsumer) <= tester) THEN
   IF (teste = 0 OR ABS(sumer - gnsumer) <= teste) THEN
    --  insert into tmp_vil values (sumer ||' '||gnsumer||' '|| teste);commit;
    FOR i IN 1 .. ln_cnt LOOP
     lt_paramval(i) := lt_info(i).er;
    END LOOP;

    getvalm(sumer, gnsumer, ln_cnt, lt_paramval);

    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).er := lt_paramval(i);
--       insert into tmp_vil values (lt_paramval(i));commit;
    END LOOP;
   ELSE
    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 16, qm_pg.cn_add_err);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 3, qm_pg.cn_yes);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 1, qm_pg.cn_invalid);
    END LOOP;
   END IF;
  END IF;

  IF ABS(sumq1 - gnsumq1) > 0 THEN
   IF (testq = 0 OR ABS(sumq1 - gnsumq1) <= testq) THEN
    -- IF (testq1 = 0 OR ABS(sumq1 - gnsumq1) <= testq1) THEN
    FOR i IN 1 .. ln_cnt LOOP
     lt_paramval(i) := lt_info(i).q1;
    END LOOP;

    getvalm(sumq1, gnsumq1, ln_cnt, lt_paramval);

    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).q1 := lt_paramval(i);
    END LOOP;
   ELSE
    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 16, qm_pg.cn_add_err);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 3, qm_pg.cn_yes);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 1, qm_pg.cn_invalid);
    END LOOP;
   END IF;
  END IF;

  IF ABS(sumq2 - gnsumq2) > 0 THEN
   IF (testq = 0 OR ABS(sumq2 - gnsumq2) <= testq) THEN
    --  IF (testq2 = 0 OR ABS(sumq2 - gnsumq2) <= testq2) THEN
    FOR i IN 1 .. ln_cnt LOOP
     lt_paramval(i) := lt_info(i).q2;
    END LOOP;

    getvalm(sumq2, gnsumq2, ln_cnt, lt_paramval);

    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).q2 := lt_paramval(i);
    END LOOP;
   ELSE
    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 16, qm_pg.cn_add_err);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 3, qm_pg.cn_yes);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 1, qm_pg.cn_invalid);
    END LOOP;
   END IF;
  END IF;

  IF ABS(sumq3 - gnsumq3) > 0 THEN
   -- IF (testq3 = 0 OR ABS(sumq3 - gnsumq3) <= testq3) THEN
   IF (testq = 0 OR ABS(sumq3 - gnsumq3) <= testq) THEN
    FOR i IN 1 .. ln_cnt LOOP
     lt_paramval(i) := lt_info(i).q3;
    END LOOP;

    getvalm(sumq3, gnsumq3, ln_cnt, lt_paramval);

    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).q3 := lt_paramval(i);
    END LOOP;
   ELSE
    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 16, qm_pg.cn_add_err);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 3, qm_pg.cn_yes);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 1, qm_pg.cn_invalid);
    END LOOP;
   END IF;
  END IF;

  IF ABS(sumq4 - gnsumq4) > 0 THEN
   -- IF (testq4 = 0 OR ABS(sumq4 - gnsumq4) <= testq4) THEN
   IF (testq = 0 OR ABS(sumq4 - gnsumq4) <= testq) THEN
    FOR i IN 1 .. ln_cnt LOOP
     lt_paramval(i) := lt_info(i).q4;
    END LOOP;

    getvalm(sumq4, gnsumq4, ln_cnt, lt_paramval);

    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).q4 := lt_paramval(i);
    END LOOP;
   ELSE
    FOR i IN 1 .. ln_cnt LOOP
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 16, qm_pg.cn_add_err);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 3, qm_pg.cn_yes);
     lt_info(i).qm := qm_pg.sbt(lt_info(i).qm, 1, qm_pg.cn_invalid);
    END LOOP;
   END IF;
  END IF;

  IF test30817 = 0 THEN
   FOR i IN 1 .. ln_cnt LOOP
    ner := lt_info(i).er;
    ned := lt_info(i).ed;
    nq1 := lt_info(i).q1;
    nq2 := lt_info(i).q2;
    nq3 := lt_info(i).q3;
    nq4 := lt_info(i).q4;
    ld_fromm := util_pg.to_localtime(ad_from) + i / an_period;

    --ld_fromh := ad_from + ln_timeshift / 24 + i / an_period;
    IF (
        (ar_info.meas = 0 AND(ner IS NOT NULL OR ned IS NOT NULL OR nq1 IS NOT NULL OR nq2 IS NOT NULL OR nq3 IS NOT NULL OR nq4 IS NOT NULL))
        OR(ar_info.meas = 1 AND ner IS NOT NULL) OR(ar_info.meas = 2 AND ned IS NOT NULL) OR(ar_info.meas = 3 AND nq1 IS NOT NULL)
        OR(ar_info.meas = 4 AND nq2 IS NOT NULL) OR(ar_info.meas = 5 AND nq3 IS NOT NULL) OR(ar_info.meas = 6 AND nq4 IS NOT NULL)
       ) THEN
     getroundvalue(ar_info.mid, ar_info.meas, ld_fromm - 1 / 48, 0, ner, nermod, ned, nedmod, nq1, nq1mod, nq2, nq2mod, nq3, nq3mod, nq4, nq4mod);
    END IF;

--insert into tmp_vil values(to_char(ld_fromm-1/48,'dd.mm.yyyy hh24:mi:ss')||' '||lt_info(i).er||' '||test||' '||ner||' '||nermod); commit;
    lt_info(i).er := ner;
    lt_info(i).ed := ned;
    lt_info(i).q1 := nq1;
    lt_info(i).q2 := nq2;
    lt_info(i).q3 := nq3;
    lt_info(i).q4 := nq4;
   END LOOP;

   IF rcount = 0 AND ld_till_l <> TRUNC(ld_till_l, 'MONTH') THEN
    SELECT NVL(MAX(a.er), 0), NVL(MAX(a.ed), 0), NVL(MAX(a.q1), 0), NVL(MAX(a.q2), 0), NVL(MAX(a.q3), 0), NVL(MAX(a.q4), 0)
    INTO   nermod, nedmod, nq1mod, nq2mod, nq3mod, nq4mod
    FROM   round30817 a
    WHERE  a.mid = ar_info.mid AND a.date_time = util_pg.to_localtime(ad_from);
   END IF;

   UPDATE round30817
   SET er = DECODE(nermod, NULL, er, nermod),
       ed = DECODE(nedmod, NULL, ed, nedmod),
       q1 = DECODE(nq1mod, NULL, q1, nq1mod),
       q2 = DECODE(nq2mod, NULL, q2, nq2mod),
       q3 = DECODE(nq3mod, NULL, q3, nq3mod),
       q4 = DECODE(nq4mod, NULL, q4, nq4mod)
   WHERE  mid = ar_info.mid AND date_time = ld_till_l;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO round30817
                (mid, date_time, er, ed, q1, q2, q3, q4)
    VALUES      (ar_info.mid, ld_till_l, nermod, nedmod, nq1mod, nq2mod, nq3mod, nq4mod);
   END IF;
  END IF;

  FOR i IN 1 .. ln_itemcnt LOOP
   ld_fromh := ad_from + ln_timeshift / 24 + i / an_period;
   ins_halfhouroldw(ar_info.mid, ld_fromh, lt_info(i).er, lt_info(i).ed, lt_info(i).q1, lt_info(i).q3, lt_info(i).q2, lt_info(i).q4, NULL, comsrv_pg.cn_calc,
    lt_info(i).qm, ar_info.nswitch, NULL, 1, 1, NULL, testround);
  END LOOP;
 END;

-------------------------------------------------------------------------------------------------
 PROCEDURE getvalm(an_sum NUMBER, an_gnsum NUMBER, an_cnt NUMBER, at_ret IN OUT common_pg.tt_double) IS
  ln_res              NUMBER;
  ln_cnt              NUMBER := an_cnt;
 BEGIN
  ln_res := an_gnsum - an_sum;

  WHILE (ln_res IS NOT NULL AND ln_res <> 0) AND(ln_cnt > 0) LOOP
   IF at_ret(ln_cnt) > 0 THEN
    IF at_ret(ln_cnt) > ln_res THEN
     at_ret(ln_cnt) := at_ret(ln_cnt) - ln_res;
     ln_res := ABS(ln_res) - ABS(ln_res);
    ELSE
     ln_res := ABS(ln_res) - at_ret(ln_cnt);
     at_ret(ln_cnt) := 0;
    END IF;
   END IF;

   ln_cnt := ln_cnt - 1;
  END LOOP;
 END;

-------------------------------------------------------------------------------------------------
 PROCEDURE get_tmp(an_mid NUMBER) IS
  ln_calc             NUMBER;
 BEGIN
  DELETE FROM lastrecforrecalc;

  DELETE FROM lastrec;

  FOR lc IN (SELECT mid
             FROM   feeders f
             WHERE  f.mid IN(SELECT     mid
                             FROM       points
                             CONNECT BY PRIOR mid = PARENT
                             START WITH mid /*parent*/ = an_mid) AND NVL(ncalcpointtype, 0) = 6) LOOP
   INSERT INTO lastrec a
               (a.mid, a.ddate)
   VALUES      (lc.mid, SYSDATE);

   INSERT INTO lastrecforrecalc a
               (a.mid, a.ddate, a.ntype)
   VALUES      (lc.mid, SYSDATE, 0);
  END LOOP;

  FOR lc1 IN (SELECT DISTINCT tt.mid, tt.nform
              FROM            (SELECT     NVL(g.mid, pp.mid) mid, DECODE(g.mid, NULL, 0, g.ntype) nform
                               FROM       pointformula pp, formulparams fm, greenpoint g                                       --формулы нормальные где есть mid
                               WHERE      pp.nid = fm.nid AND fm.mid > 0 AND fm.mid = g.mid(+)
                               CONNECT BY PRIOR fm.mid = pp.mid                                                                                /*pp.mid=fm.mid*/
                               START WITH pp.mid IN(SELECT mid
                                                    FROM   lastrec)
                               UNION ALL
                               SELECT     DECODE(fm.nform, 0, pp.mid, fm.mid) mid, fm.nform                      --формулы ненормальные где нет mid , а есть gid
                               FROM       pointformula pp,
                                          (SELECT s.nid, kk.mid, DECODE(g.mid, NULL, 0, g.ntype) nform, g.norder
                                           FROM   formulparams s,
                                                  greenpoint g,
                                                  (SELECT     DECODE(
                                                               LEVEL,
                                                               1, PARENT,
                                                               SUBSTR(SYS_CONNECT_BY_PATH(PARENT, '/'), 2, INSTR(SYS_CONNECT_BY_PATH(PARENT, '/'), '/', 2) - 2)
                                                              ) nparent,
                                                              mid
                                                   FROM       GROUPS
                                                   WHERE      mid IS NOT NULL
                                                   CONNECT BY PRIOR gid = PARENT
                                                   START WITH PARENT IN(SELECT util_pg.allnumber_f(TRIM(util_pg.get_param(fm.vparam, 2, '.')))
                                                                        FROM   formulparams fm
                                                                        WHERE  fm.mid IS NULL AND vparam IS NOT NULL)) kk
                                           WHERE  s.mid IS NULL AND util_pg.allnumber_f(TRIM(util_pg.get_param(s.vparam, 2, '.'))) = kk.nparent AND kk.mid = g.mid(+)) fm
                               WHERE      pp.nid = fm.nid
                               CONNECT BY PRIOR fm.mid = pp.mid                                                                                /*pp.mid=fm.mid*/
                               START WITH pp.mid IN(SELECT mid
                                                    FROM   lastrec)) tt
              WHERE           tt.mid NOT IN(SELECT mid
                                            FROM   lastrec)) LOOP
   INSERT INTO lastrecforrecalc a
               (a.mid, a.ddate, a.ntype)
   VALUES      (lc1.mid, SYSDATE, lc1.nform);
  END LOOP;

  DELETE FROM lastrec;

  FOR lc3 IN (SELECT mid
              FROM   feeders f
              WHERE  f.mid IN(SELECT     mid
                              FROM       points
                              CONNECT BY PRIOR mid = PARENT
                              START WITH mid /*parent*/ = an_mid) AND NVL(ncalcpointtype, 0) <> 6) LOOP
   INSERT INTO lastrec a
               (a.mid, a.ddate)
   VALUES      (lc3.mid, SYSDATE);
  END LOOP;

  FOR lc2 IN (SELECT g.mid nid, g.mid, g.norder, g.ntype
              FROM   greenpoint g
              WHERE  g.mid IN(SELECT mid
                              FROM   lastrec)) LOOP
   BEGIN
    INSERT INTO lastrecforrecalc a
                (a.mid, a.ddate, a.ntype)
    VALUES      (lc2.mid, SYSDATE, lc2.ntype);
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     NULL;
   END;

   NULL;
  END LOOP;

  DELETE FROM lastrec;
 END;

-------------------------------------------------------------------------------------------------------
 PROCEDURE get_calcup(ln_calcup NUMBER) IS
  flag                NUMBER := 0;
  ld_calcperiod       DATE := admin_pg.get_calcperiod;
 BEGIN
  FOR lc1 IN (SELECT DISTINCT mid
              FROM            lastrec
              WHERE           ddate >= ld_calcperiod) LOOP
   FOR lc2 IN (SELECT DISTINCT mm.mid
               FROM            (SELECT pp.mid
                                FROM   points p, points pp, feeders fd                                                          --ближайшая зеленая не расчетная
                                WHERE  p.PARENT = pp.mid AND fd.mid(+) = pp.mid AND NVL(fd.ncalcpointtype, 0) NOT IN(4, 6) AND p.mid = lc1.mid AND pp.ind = 4
                                UNION ALL
                                SELECT     mid
                                FROM       points
                                CONNECT BY PRIOR mid = PARENT
                                START WITH mid IN(SELECT nowner
                                                  FROM   operatingday
                                                  WHERE  mid = lc1.mid)                                                                             --простая ГН
                                UNION ALL
                                SELECT p.mid                                                                                      --формула с простым аргументом
                                FROM   pointformula p, formulparams f
                                WHERE  p.nid = f.nid AND f.mid IS NOT NULL AND f.mid = lc1.mid) mm
               -- MINUS
               WHERE           mm.mid NOT IN(SELECT mid
                                             FROM   lastrecforrecalc)) LOOP
    flag := flag + 1;

    FOR lc8 IN (SELECT DISTINCT ddate
                FROM            lastrec
                ORDER BY        1) LOOP
     IF lc8.ddate < ld_calcperiod THEN                                                                                                    --Для старых периодов
      NULL;
     ELSIF lc8.ddate >= ld_calcperiod THEN
      --  INSERT INTO tmp_vil VALUES(lc2.mid||' '||lc8.ddate);commit;
      INSERT INTO lastrecforrecalc
                  (mid, ddate, ntype)
      VALUES      (lc2.mid, lc8.ddate, 1);
     END IF;
    END LOOP;
   END LOOP;
  END LOOP;

  FOR lc3 IN (SELECT DISTINCT gid
              FROM            GROUPS
              CONNECT BY      PRIOR PARENT = gid
              START WITH      mid IN(SELECT DISTINCT mid
                                     FROM            lastrec
                                     WHERE           ddate >= ld_calcperiod)) LOOP
   FOR lc4 IN (SELECT DISTINCT nn.mid
               FROM            (SELECT p.mid                                                                                    --формула с групповым аргументом
                                FROM   pointformula p, formulparams f
                                WHERE  p.nid = f.nid AND f.mid IS NULL AND util_pg.allnumber_f(TRIM(util_pg.get_param(f.vparam, 1, '.'))) = 'GID'
                                       AND util_pg.allnumber_f(TRIM(util_pg.get_param(f.vparam, 2, '.'))) = lc3.gid
                                UNION ALL
                                SELECT     mid
                                FROM       points                                                                                                -- ГН по группе
                                CONNECT BY PRIOR mid = PARENT
                                START WITH mid IN(SELECT nowner
                                                  FROM   operatingday
                                                  WHERE  gid = lc3.gid)) nn
               WHERE           nn.mid NOT IN(SELECT mid
                                             FROM   lastrecforrecalc)) LOOP
    flag := flag + 1;

    FOR lc9 IN (SELECT DISTINCT ddate
                FROM            lastrec
                ORDER BY        1) LOOP
     IF lc9.ddate < ld_calcperiod THEN                                                                                                    --Для старых периодов
      NULL;
     ELSIF lc9.ddate >= ld_calcperiod THEN
      INSERT INTO lastrecforrecalc
                  (mid, ddate, ntype)
      VALUES      (lc4.mid, lc9.ddate, 1);
     END IF;
    END LOOP;
   END LOOP;
  END LOOP;

  DELETE FROM lastrec;

  IF flag > 0 AND ln_calcup < 10000 THEN
   INSERT INTO lastrec
               (mid, ddate)
    SELECT DISTINCT mid, ddate
    FROM            lastrecforrecalc
    WHERE           ntype = 1;

   UPDATE lastrecforrecalc
   SET ntype = 0;

   get_calcup(ln_calcup + 1);
  END IF;
 END;

---------------------------------------------------------------------------------------------------------
 FUNCTION get_num_dtw(d DATE, an_nsourse NUMBER, ad_dfrom DATE, an_nhoureriod NUMBER)
--an_nhoureriod =24 или 48
 RETURN NUMBER IS
 BEGIN
  -- RETURN  round(( util_pg.to_unlocaltime(d,an_nsourse)-ad_dfrom)* an_nhoureriod);
  RETURN TRUNC((util_pg.to_unlocaltime(d, an_nsourse) - ad_dfrom) * an_nhoureriod) + 1;
 END;

---------------------------------------------------------------------------------------------------------
-- Round (только -1/2 на округляем)
 FUNCTION round05(a NUMBER, e NUMBER, an_round NUMBER, an_bank NUMBER)
  RETURN NUMBER IS
  b                   NUMBER := a + NVL(e, 0);
  c                   NUMBER;
 BEGIN
  IF NVL(an_bank, 0) = 1 THEN                                                                                                                  --По банковскому
   c := POWER(10, an_round);

   IF ABS(b - TRUNC(b, an_round)) * c = 1 / 2 AND MOD(TRUNC(b, an_round) * c, 2) = 0 THEN                                                         --Остаток 1/2
    RETURN TRUNC(b, an_round);
   ELSE
    RETURN ROUND(b, an_round);
   END IF;
  ELSE                                                                                                                                  --Обычное математическое
   IF a = 0 AND e = -1 / 2 THEN
    RETURN 0;
   ELSE
    RETURN ROUND(b, an_round);
   END IF;
  END IF;
 END;
------------------------------------------------------------------------------------------------------------------------
END;
