PACKAGE BODY change_meter IS
 -- пакет работы с задачей замены счетчиков
 -- дата создания 11.11.2003 (Коваленко А.С.)
 gn_task_code        NUMBER DEFAULT 48;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE select_border(pquery_type NUMBER, pmid NUMBER, pchangedate VARCHAR2, pmtrsn VARCHAR2, pdata OUT common_pg.tcur) IS
  query_str           VARCHAR2(5000);
 BEGIN
  query_str :=
      'SELECT to_char(MIN(date_time), ''dd.mm.yyyy hh24:mi'')DTMin, to_char(MAX(date_time), ''dd.mm.yyyy hh24:mi'')DTMax 
                FROM ryda.billorg WHERE mid='
   || TO_CHAR(pmid)
   || ' AND date_time>=to_date('''
   || pchangedate
   || ''', ''dd.mm.yyyy hh24:mi'')';

  IF (pquery_type = 1) THEN
   query_str := query_str || ' AND ER_mtrsn =' || pmtrsn;
  END IF;

  IF (pquery_type = 2) THEN
   query_str := query_str || ' AND ED_mtrsn =' || pmtrsn;
  END IF;

  IF (pquery_type = 3) THEN
   query_str := query_str || ' AND ED_mtrsn =' || pmtrsn;
  END IF;

  OPEN pdata FOR query_str;
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE select_data(pmid NUMBER, pentype NUMBER, pdata OUT common_pg.tcur) IS
 BEGIN
  OPEN pdata FOR
   SELECT rm.ID, rm.NAME, rm.smart, rm.mtrsn, rm.digits, rm.mtype, rm.mcurrent, rm.mpower, rm.mconst, rm.mclass, rm.myear, rm.mquarter
   FROM   ryda.meters rm
   WHERE  rm.mid = pmid AND rm.entype = pentype;
 END;

 PROCEDURE change_meter_p(
 an_mid NUMBER,                                                                                                                                       --Ид точки
               -- данные старого счетчика
               ad_date_time_d DATE,                                                                                 --DATE_TIME ( дата демонтирования счетчика )
                                   at_m common_pg.tt_number,                                                          -- Новые показания демонтируемого счетчика
                                                            -- данные нового счетчика
                                                            an_entype NUMBER,                                                                           --ENTYPE
                                                                             av_smart VARCHAR2,                                                          --SMART
                                                                                               av_mtrsn VARCHAR2,                                        --MTRSN
                                                                                                                 ad_date_time DATE,
                                                                                                                         --DATE_TIME ( дата установки счетчика )
 an_digits NUMBER,                                                                                                                                      --DIGITS
                  av_mtype VARCHAR2,                                                                                                                     --MTYPE
                                    an_mcurrent NUMBER,                                                                                               --MCURRENT
                                                       an_mpower NUMBER,                                                                                --MPOWER
                                                                        an_mconst NUMBER,                                                               --MCONST
                                                                                         an_mclass NUMBER,                                              --MCLASS
                                                                                                          an_myear NUMBER,                               --MYEAR
                                                                                                                          an_mquarter NUMBER,         --MQUARTER
 av_memo VARCHAR2,                                                                                                                                       --VMEMO
                  at_new_m common_pg.tt_number                                           -- Добавленная энергия при замене и показания устанавливаемого счетчика
 ) IS
  i                   NUMBER;
  ln_kc               NUMBER;
  ln_data_found       NUMBER DEFAULT 0;
  lt_old_m            common_pg.tt_number;
  lt_m                common_pg.tt_number;
  lt_new_m            common_pg.tt_number;
  ln_erm_h            NUMBER;
  ln_edm_h            NUMBER;
  ln_q1m_h            NUMBER;
  ln_q2m_h            NUMBER;
  ln_q3m_h            NUMBER;
  ln_q4m_h            NUMBER;
  ln_id               NUMBER;
  lv_smart            VARCHAR2(1);                                                                                                                      --SMART
  lv_mtrsn            VARCHAR2(20);                                                                                                                     --MTRSN
  ld_date_time        DATE;                                                                                             --DATE_TIME ( дата установки счетчика )
  ln_digits           NUMBER;                                                                                                                          --DIGITS
  lv_mtype            VARCHAR2(50);                                                                                                                     --MTYPE
  ln_mcurrent         NUMBER;                                                                                                                        --MCURRENT
  ln_mpower           NUMBER;                                                                                                                          --MPOWER
  ln_mconst           NUMBER;                                                                                                                          --MCONST
  ln_mclass           NUMBER;                                                                                                                          --MCLASS
  ln_myear            NUMBER;                                                                                                                           --MYEAR
  ln_mquarter         NUMBER;                                                                                                                        --MQUARTER
 BEGIN
  SELECT kc
  INTO   ln_kc
  FROM   feeders
  WHERE  mid = an_mid;

  SELECT ID, smart, mtrsn, date_time, digits, mtype, mcurrent, mpower, mconst, mclass, myear, mquarter
  INTO   ln_id, lv_smart, lv_mtrsn, ld_date_time, ln_digits, lv_mtype, ln_mcurrent, ln_mpower, ln_mconst, ln_mclass, ln_myear, ln_mquarter
  FROM   meters
  WHERE  mid = an_mid AND entype = an_entype;

  DELETE FROM metershistory
  WHERE       mid = an_mid AND date_time = ld_date_time AND entype = an_entype;

  INSERT INTO metershistory
              (mid, date_time, dend, entype, mtrsn, digits, mtype, mcurrent, mpower, mconst, mclass, myear, mquarter, kc, vmemo)
  VALUES      (an_mid, ld_date_time, ad_date_time_d, an_entype, lv_mtrsn, ln_digits, lv_mtype, ln_mcurrent, ln_mpower, ln_mconst, ln_mclass, ln_myear,
               ln_mquarter, ln_kc, av_memo);

  UPDATE meters
  SET (date_time, smart, entype, mtrsn, digits, mtype, mcurrent, mpower, mconst, mclass, myear, mquarter, kc) =
       (SELECT ad_date_time, av_smart, an_entype, av_mtrsn, an_digits, av_mtype, an_mcurrent, an_mpower, an_mconst, an_mclass, an_myear, an_mquarter, ln_kc
        FROM   DUAL)
  WHERE  mid = an_mid AND entype = an_entype;

  ln_digits := LENGTH(TRUNC(ln_digits));

  FOR i IN 1 .. at_m.COUNT LOOP
   IF at_m(i) < 0 THEN
    lt_m(i) := NULL;
   ELSE
    lt_m(i) := at_m(i);
   END IF;
  END LOOP;

  FOR i IN 1 .. at_new_m.COUNT LOOP
   IF at_new_m(i) < 0 THEN
    lt_new_m(i) := NULL;
   ELSE
    lt_new_m(i) := at_new_m(i);
   END IF;
  END LOOP;

---------------- monthsorg --------------------------------------------------
  lt_old_m.DELETE;

  FOR i IN 1 .. 30 LOOP
   lt_old_m(i) := NULL;
  END LOOP;

  BEGIN
   SELECT erm, aerm, berm, cerm, derm, edm, aedm, bedm, cedm, dedm, q1m, aq1m, bq1m, cq1m, dq1m, q2m, aq2m, bq2m, cq2m, dq2m, q3m, aq3m, bq3m, cq3m, dq3m, q4m,
          aq4m, bq4m, cq4m, dq4m
   INTO   lt_old_m(1), lt_old_m(2), lt_old_m(3), lt_old_m(4), lt_old_m(5), lt_old_m(6), lt_old_m(7), lt_old_m(8), lt_old_m(9), lt_old_m(10), lt_old_m(11),
          lt_old_m(12), lt_old_m(13), lt_old_m(14), lt_old_m(15), lt_old_m(16), lt_old_m(17), lt_old_m(18), lt_old_m(19), lt_old_m(20), lt_old_m(21),
          lt_old_m(22), lt_old_m(23), lt_old_m(24), lt_old_m(25), lt_old_m(26), lt_old_m(27), lt_old_m(28), lt_old_m(29), lt_old_m(30)
   FROM   monthsorg m
   WHERE  mid = an_mid AND date_time = (SELECT MAX(date_time)
                                        FROM   monthsorg
                                        WHERE  date_time < ad_date_time_d AND mid = an_mid AND nsource <> 9 AND nsource > 0)
          AND nsource = (SELECT MAX(nsource)
                         FROM   monthsorg
                         WHERE  date_time = m.date_time AND mid = an_mid AND nsource <> 9 AND nsource > 0);

   ln_data_found := 1;
  EXCEPTION
   WHEN NO_DATA_FOUND THEN
    ln_data_found := 0;
  END;

  DELETE FROM monthsorg
  WHERE       mid = an_mid AND date_time = ad_date_time_d;

  INSERT INTO monthsorg
              (mid, date_time, SOURCE, nsource, remark, er_mtrsn, er_kc, er, aer, ber, cer, der, erm, aerm, berm, cerm, derm, ed_mtrsn, ed_kc, ed, aed, bed,
               ced, ded, edm, aedm, bedm, cedm, dedm, q1_mtrsn, q1_kc, q1, aq1, bq1, cq1, dq1, q1m, aq1m, bq1m, cq1m, dq1m, q2_mtrsn, q2_kc, q2, aq2, bq2, cq2,
               dq2, q2m, aq2m, bq2m, cq2m, dq2m, q3_mtrsn, q3_kc, q3, aq3, bq3, cq3, dq3, q3m, aq3m, bq3m, cq3m, dq3m, q4_mtrsn, q4_kc, q4, aq4, bq4, cq4, dq4,
               q4m, aq4m, bq4m, cq4m, dq4m)
  VALUES      (an_mid, ad_date_time_d, 'Снт', 7, 'Счетчик [' || lv_mtype || '] № ' || lv_mtrsn || ' снят с учета оператором - ' || util_pg.username_f, lv_mtrsn,
               ln_kc, util_pg.indicoverturn(lt_m(1) - lt_old_m(1), ln_digits) * ln_kc, util_pg.indicoverturn(lt_m(2) - lt_old_m(2), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(3) - lt_old_m(3), ln_digits) * ln_kc, util_pg.indicoverturn(lt_m(4) - lt_old_m(4), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(5) - lt_old_m(5), ln_digits) * ln_kc, lt_m(1), lt_m(2), lt_m(3), lt_m(4), lt_m(5), lv_mtrsn, ln_kc,
               util_pg.indicoverturn(lt_m(6) - lt_old_m(6), ln_digits) * ln_kc, util_pg.indicoverturn(lt_m(7) - lt_old_m(7), ln_digits) * ln_kc,
