               util_pg.indicoverturn(lt_m(23) - lt_old_m(23), ln_digits) * ln_kc, util_pg.indicoverturn(lt_m(24) - lt_old_m(24), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(25) - lt_old_m(25), ln_digits) * ln_kc, lt_m(21), lt_m(22), lt_m(23), lt_m(24), lt_m(25), lv_mtrsn, ln_kc,
               util_pg.indicoverturn(lt_m(26) - lt_old_m(26), ln_digits) * ln_kc, util_pg.indicoverturn(lt_m(27) - lt_old_m(27), ln_digits) * ln_kc,
