               util_pg.indicoverturn(lt_m(30) - lt_old_m(30), ln_digits) * ln_kc, lt_m(26), lt_m(27), lt_m(28), lt_m(29), lt_m(30));

  INSERT INTO monthsorg
              (mid, date_time, SOURCE, nsource, remark, er_mtrsn, er_kc, er, aer, ber, cer, der, erm, aerm, berm, cerm, derm, ed_mtrsn, ed_kc, ed, aed, bed,
               ced, ded, edm, aedm, bedm, cedm, dedm, q1_mtrsn, q1_kc, q1, aq1, bq1, cq1, dq1, q1m, aq1m, bq1m, cq1m, dq1m, q2_mtrsn, q2_kc, q2, aq2, bq2, cq2,
               dq2, q2m, aq2m, bq2m, cq2m, dq2m, q3_mtrsn, q3_kc, q3, aq3, bq3, cq3, dq3, q3m, aq3m, bq3m, cq3m, dq3m, q4_mtrsn, q4_kc, q4, aq4, bq4, cq4, dq4,
