               ln_kc, lt_new_m(1), lt_new_m(2), lt_new_m(3), lt_new_m(4), lt_new_m(5), lt_new_m(6), lt_new_m(7), lt_new_m(8), lt_new_m(9), lt_new_m(10),
               av_mtrsn, ln_kc, lt_new_m(11), lt_new_m(12), lt_new_m(13), lt_new_m(14), lt_new_m(15), lt_new_m(16), lt_new_m(17), lt_new_m(18), lt_new_m(19),
