------------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_change_meter_p(an_mid NUMBER, ad_date DATE, an_entype NUMBER) IS
  ld_date             DATE;
 BEGIN
  DELETE FROM billorg
  WHERE       mid = an_mid AND date_time = ad_date AND nsource IN(7, 8);

  DELETE FROM monthsorg
  WHERE       mid = an_mid AND date_time = ad_date AND nsource IN(7, 8);

  FOR lc IN (SELECT *
             FROM   metershistory
             WHERE  mid = an_mid AND dend = ad_date AND entype = an_entype) LOOP
   DELETE FROM metershistory
   WHERE       mid = an_mid AND dend = ad_date AND entype = an_entype;

   SELECT MIN(dend)
   INTO   ld_date
   FROM   metershistory
   WHERE  mid = an_mid AND entype = an_entype AND dend > ad_date;

   IF ld_date IS NULL THEN                                                                                       --Если последняя замена - то копируем в meters
    UPDATE meters
    SET date_time = lc.date_time,
        mtrsn = lc.mtrsn,
        digits = lc.digits,
        mtype = lc.mtype,
        mcurrent = lc.mcurrent,
        mpower = lc.mpower,
        mconst = lc.mconst,
        mclass = lc.mclass,
        myear = lc.myear,
        mquarter = lc.mquarter,
        kc = lc.kc
    WHERE  mid = an_mid AND entype = an_entype;
   ELSE                                                                                                                                   --копируем в следующую
    UPDATE metershistory
    SET date_time = lc.date_time,
        mtrsn = lc.mtrsn,
        digits = lc.digits,
        mtype = lc.mtype,
        mcurrent = lc.mcurrent,
        mpower = lc.mpower,
        mconst = lc.mconst,
        mclass = lc.mclass,
        myear = lc.myear,
        mquarter = lc.mquarter,
        kc = lc.kc
    WHERE  mid = an_mid AND entype = an_entype AND dend = ld_date;
   END IF;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'change_meter_p.del_change_meter_p: Ошибка при замене счетчика. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--чтение дерева точек
 PROCEDURE read_node_p(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF an_mid IS NULL THEN
   lv_sql :=
    ' Select 1 HaveChild,p.mid,decode(p.ind,1,1,2,1,4,4,3)type,p.name,
                         0 ER_POSITION,0 Q1_POSITION,0 ED_POSITION,0 Q3_POSITION,0 SMART,0 KC
                  from points p
                  where p.mid IN(SELECT * FROM   TABLE(adminadd_pg.getfirst_accmid('||util_pg.cn_pntmid||'))) and
                  exists (select * from points where parent=p.mid and cod=0 and (ind<3 or mid in (Select mid from FEEDERS)))
                  union all
                  Select 0 HaveChild,p.mid,decode(p.ind,1,1,2,1,4,4,3),p.name,0 ER_POSITION,0 Q1_POSITION,0 ED_POSITION,0 Q3_POSITION,0 SMART,0 KC
                  from points p
                  where p.mid IN(SELECT * FROM   TABLE(adminadd_pg.getfirst_accmid('||util_pg.cn_pntmid||'))) and
                  not exists (select * from points where parent=p.mid and cod=0 and (ind<3 or mid in (Select mid from FEEDERS)))
                  order by 3,4';
  ELSE
   IF adminadd_pg.check_accread(an_mid)=0 THEN
				raise_application_error(-20002, 'В доступе отказано. an_id='||an_mid);
			END IF;

   lv_sql :=
       ' Select 1 HaveChild,p.mid,decode(p.ind,1,1,2,1,4,4,3)type,p.name,
                         nvl(f.ER_POSITION,0)ER_POSITION,nvl(f.Q1_POSITION,0) Q1_POSITION,nvl(f.ED_POSITION,0)ED_POSITION,
                         nvl(f.Q3_POSITION,0)Q3_POSITION,
                         decode(f.SMART,''*'',1,0)SMART,nvl(f.KC,1)KC
                  from points p,FEEDERS f
                  where p.parent='
    || an_mid
    || ' and p.cod=0 and (p.ind<3 or p.mid in (Select mid from FEEDERS)) and p.mid=f.mid(+) and
                        exists (select * from points where parent=p.mid and cod=0 and (ind<3 or mid in (Select mid from FEEDERS)))
                  union all
                  Select 0 HaveChild,p.mid,decode(p.ind,1,1,2,1,4,4,3),p.name,
                         nvl(f.ER_POSITION,0),nvl(f.Q1_POSITION,0),nvl(f.ED_POSITION,0),nvl(f.Q3_POSITION,0),decode(f.SMART,''*'',1,0),
                         nvl(f.KC,1)
                  from points p,FEEDERS f
                  where p.parent='
    || an_mid
    || ' and p.cod=0 and (p.ind<3 or p.mid in (Select mid from FEEDERS)) and p.mid=f.mid(+) and
                        not exists (select * from points where parent=p.mid and cod=0 and (ind<3 or mid in (Select mid from FEEDERS)))
                  order by 3,4';
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

--------------------------------------------------------------------------------------------------
 PROCEDURE chmeter_p(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
 BEGIN
  lv_sql :=
      'select decode(m.entype,1,''(A+)'',2,''(A-)'',3,''(R+)'',5,''(R-)'',7,Null)entype,m.entype type,m.dend  from metershistory m, feeders f
                                                where m.mid=f.mid and m.mid='
   || an_mid
   || ' order by m.dend desc';

  OPEN acur_t FOR lv_sql;
 END;

-----------------------------------------------------------------------------------------------------------
 PROCEDURE meterdemindic(mmid NUMBER DEFAULT 0, ddate DATE DEFAULT SYSDATE, mtrsn VARCHAR2, data_t OUT common_pg.tcur) IS
 BEGIN
  OPEN data_t FOR
   SELECT
          NVL(b.erm, -1) f1, NVL(b.aerm, -1) f2, NVL(b.berm, -1) f3, NVL(b.cerm, -1) f4, NVL(b.derm, -1) f5, NVL(b.edm, -1) f6, NVL(b.aedm, -1) f7,
          NVL(b.bedm, -1) f8, NVL(b.cedm, -1) f9, NVL(b.dedm, -1) f10, NVL(b.q1m, -1) f11, NVL(b.aq1m, -1) f12, NVL(b.bq1m, -1) f13, NVL(b.cq1m, -1) f14,
          NVL(b.dq1m, -1) f15, NVL(b.q2m, -1) f16, NVL(b.aq2m, -1) f17, NVL(b.bq2m, -1) f18, NVL(b.cq2m, -1) f19, NVL(b.dq2m, -1) f20, NVL(b.q3m, -1) f21,
          NVL(b.aq3m, -1) f22, NVL(b.bq3m, -1) f23, NVL(b.cq3m, -1) f24, NVL(b.dq3m, -1) f25, NVL(b.q4m, -1) f26, NVL(b.aq4m, -1) f27, NVL(b.bq4m, -1) f28,
          NVL(b.cq4m, -1) f29, NVL(b.dq4m, -1) f30
   FROM   billorg b
   WHERE  b.mid = mmid AND b.er_mtrsn = mtrsn AND b.date_time IN(SELECT MAX(date_time)
                                                                 FROM   billorg
                                                                 WHERE  date_time <= ddate);
 END;
--------------------------------------------------------------------------------------------------------------------
