                                            an_nnotreadcurr NUMBER,                                                                   --Не читать текущие сутки
                                                                   an_wait NUMBER,                                                 --Время ожид уст соед  (сек)
                                                                                  an_lockcorrecttime NUMBER,                    --Блокировать коррекцию времени
 an_vaddparam VARCHAR2,                                                                                                                         --Доп параметры
                       an_mid OUT NUMBER                                                                                                            --Ид канала
 ) IS
 BEGIN
  ins_p(an_ischanel, an_parentmid, av_name, av_note, an_protocol_id, an_com_id, av_init_str, av_addr, an_cycle_tout, an_retries, an_retries_tout, an_blocking,
   av_caller_name, an_billdata, an_billdatadepth, an_currdata, an_currdatadepth, an_netparam, an_journal, ad_start, ad_end, an_day, an_parent, an_nnotreadcurr,
   an_wait, NULL, NULL, an_lockcorrecttime, an_vaddparam, an_mid);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки
 PROCEDURE ins_p(
 an_ischanel NUMBER,                                                                                                      --Признак канала 1-канал, иначе группа
                    an_parentmid NUMBER,                                                                                                --Ид родительской группы
                                        av_name VARCHAR2,                                                                                             --Название
                                                         av_note VARCHAR2,                                                                          --Примечание
                                                                          an_protocol_id NUMBER,                                                  --Ид протокола
                                                                                                an_com_id NUMBER,                                  --Ид компорта
                                                                                                                 av_init_str VARCHAR2,    --Строка инициализации
 av_addr VARCHAR2,                                                                                                                      --Коммуникационый адресс
                  an_cycle_tout NUMBER,                                                                                                    --Пауза между циклами
                                       an_retries NUMBER,                                                                               --Кол попыток соединения
                                                         an_retries_tout NUMBER,                                                         --Пауза между попытками
                                                                                an_blocking NUMBER,                                                 --Блокировка
                                                                                                   av_caller_name VARCHAR2,                 --Название опросчика
 an_billdata NUMBER,                                                                                                                              --Коммерческие
                    an_billdatadepth NUMBER,                                                                                              --Коммерческие глубина
                                            an_currdata NUMBER,                                                                                        --Текущие
                                                               an_currdatadepth NUMBER,                                                        --Текущие глубина
                                                                                       an_netparam NUMBER,                                      --Параметры сети
                                                                                                          an_journal NUMBER,                    --Журнал событий
                                                                                                                            ad_start DATE,       --Начало опроса
 ad_end DATE,                                                                                                                                        --Окончание
             an_day NUMBER,                                                                                                                               --День
                           an_parent NUMBER,                                                                                                     --Главный канал
                                            an_nnotreadcurr NUMBER,                                                                    --Не читать текущие сутки
                                                                   an_wait NUMBER,                                                  --Время ожид уст соед  (сек)
                                                                                  av_accuser VARCHAR2,                                    --Пользователь доступа
                                                                                                      av_accpassword VARCHAR2,                  --Пароль доступа
 an_lockcorrecttime NUMBER,                                                                                                      --Блокировать коррекцию времени
                           an_vaddparam VARCHAR2,                                                                                                --Доп параметры
                                                 an_mid OUT NUMBER                                                                                   --Ид канала
 ) IS
  ln_mid              NUMBER;
  ln_cnt              NUMBER;
  ld_sys              DATE DEFAULT TRUNC(SYSDATE);
  ln_parent           NUMBER := an_parentmid;
 BEGIN
  SAVEPOINT editcanals_ins;

  IF NVL(ln_parent, 0) = 0 THEN                                                                                             --Устранение ошибок старых клиентов
   ln_parent := 1;
  END IF;

  adminadd_pg.check_right(ln_mid, ln_parent, 1, 2);

  SELECT points_seq.NEXTVAL
  INTO   ln_mid
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, cod, ind, NAME, short_name, implement_date, tag)
  VALUES      (ln_mid, ln_parent, 0, 2, av_name, '', SYSDATE, an_blocking);

  IF an_ischanel = 1 THEN
   INSERT INTO channels
               (cid, vname, vnote, protocol_id, com_id, init_str, addr, cycle_tout, retries, retries_tout, blocking, caller_name, nbilldata, nbilldatadepth,
                ncurrdata, ncurrdatadepth, nnetparam, njournal, dstart, dend, nday, nparent, nnotreadcurr, nwait, vaccuser, vaccpassword, nlockcorrecttime,
                vaddparam)
   VALUES      (ln_mid, av_name, av_note, an_protocol_id, an_com_id, av_init_str, av_addr, an_cycle_tout, an_retries, an_retries_tout, an_blocking,
                av_caller_name, an_billdata, an_billdatadepth, an_currdata, an_currdatadepth, an_netparam, an_journal, ad_start, ad_end, an_day, an_parent,
                an_nnotreadcurr, NVL(an_wait, 40), av_accuser, av_accpassword, an_lockcorrecttime, an_vaddparam);

   is_valid_data(ln_mid);
  END IF;

  admin_pg.ins_last_save(ln_mid);
  an_mid := ln_mid;

  IF an_ischanel = 1 THEN
   admin_pg.fiscal_p(gn_task_code, 1, 'Добавлен канал опроса ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
  ELSE
   admin_pg.fiscal_p(gn_task_code, 1, 'Добавлена группа опрса ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editcanals_ins;
   raise_application_error(-20001, 'channels_pg.ins_p: Ошибка вставки канала. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

