  -- Процедура обновления данных
 PROCEDURE upd_p(
 an_mid NUMBER,                                                                                                                                      --Ид канала
               an_parentmid NUMBER,                                                                                                     --Ид родительской группы
                                   av_name VARCHAR2,                                                                                                  --Название
                                                    av_note VARCHAR2,                                                                               --Примечание
                                                                     an_protocol_id NUMBER,                                                       --Ид протокола
                                                                                           an_com_id NUMBER,                                       --Ид компорта
                                                                                                            av_init_str VARCHAR2,         --Строка инициализации
 av_addr VARCHAR2,                                                                                                                      --Коммуникационый адресс
                  an_cycle_tout NUMBER,                                                                                                    --Пауза между циклами
                                       an_retries NUMBER,                                                                               --Кол попыток соединения
                                                         an_retries_tout NUMBER,                                                         --Пауза между попытками
                                                                                an_blocking NUMBER,                                                 --Блокировка
                                                                                                   av_caller_name VARCHAR2,                 --Название опросчика
 an_billdata NUMBER,                                                                                                                              --Коммерческие
                    an_billdatadepth NUMBER,                                                                                              --Коммерческие глубина
                                            an_currdata NUMBER,                                                                                        --Текущие
                                                               an_currdatadepth NUMBER,                                                        --Текущие глубина
                                                                                       an_netparam NUMBER,                                      --Параметры сети
                                                                                                          an_journal NUMBER,                    --Журнал событий
                                                                                                                            ad_start DATE,       --Начало опроса
 ad_end DATE,                                                                                                                                        --Окончание
             an_day NUMBER,                                                                                                                               --День
                           an_parent NUMBER,                                                                                                     --Главный канал
                                            an_nnotreadcurr NUMBER,                                                                    --Не читать текущие сутки
                                                                   an_wait NUMBER,                                                  --Время ожид уст соед  (сек)
                                                                                  an_lockcorrecttime NUMBER,                     --Блокировать коррекцию времени
 an_vaddparam VARCHAR2                                                                                                                           --Доп параметры
 ) IS
  lv_accuser          VARCHAR2(300);
  lv_accpassword      VARCHAR2(300);
 BEGIN
  SELECT vaccuser, vaccpassword
  INTO   lv_accuser, lv_accpassword
  FROM   channels
  WHERE  cid = an_mid;

  upd_p(an_mid, an_parentmid, av_name, av_note, an_protocol_id, an_com_id, av_init_str, av_addr, an_cycle_tout, an_retries, an_retries_tout, an_blocking,
   av_caller_name, an_billdata, an_billdatadepth, an_currdata, an_currdatadepth, an_netparam, an_journal, ad_start, ad_end, an_day, an_parent, an_nnotreadcurr,
   an_wait, lv_accuser, lv_accpassword, an_lockcorrecttime, an_vaddparam);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления данных
 PROCEDURE upd_p(
 an_mid NUMBER,                                                                                                                                      --Ид канала
               an_parentmid NUMBER,                                                                                                     --Ид родительской группы
                                   av_name VARCHAR2,                                                                                                  --Название
                                                    av_note VARCHAR2,                                                                               --Примечание
                                                                     an_protocol_id NUMBER,                                                       --Ид протокола
                                                                                           an_com_id NUMBER,                                       --Ид компорта
                                                                                                            av_init_str VARCHAR2,         --Строка инициализации
 av_addr VARCHAR2,                                                                                                                      --Коммуникационый адресс
                  an_cycle_tout NUMBER,                                                                                                    --Пауза между циклами
                                       an_retries NUMBER,                                                                               --Кол попыток соединения
                                                         an_retries_tout NUMBER,                                                         --Пауза между попытками
                                                                                an_blocking NUMBER,                                                 --Блокировка
                                                                                                   av_caller_name VARCHAR2,                 --Название опросчика
 an_billdata NUMBER,                                                                                                                              --Коммерческие
                    an_billdatadepth NUMBER,                                                                                              --Коммерческие глубина
                                            an_currdata NUMBER,                                                                                        --Текущие
                                                               an_currdatadepth NUMBER,                                                        --Текущие глубина
                                                                                       an_netparam NUMBER,                                      --Параметры сети
                                                                                                          an_journal NUMBER,                    --Журнал событий
                                                                                                                            ad_start DATE,       --Начало опроса
 ad_end DATE,                                                                                                                                        --Окончание
             an_day NUMBER,                                                                                                                               --День
                           an_parent NUMBER,                                                                                                     --Главный канал
                                            an_nnotreadcurr NUMBER,                                                                    --Не читать текущие сутки
                                                                   an_wait NUMBER,                                                  --Время ожид уст соед  (сек)
                                                                                  av_accuser VARCHAR2,                                    --Пользователь доступа
                                                                                                      av_accpassword VARCHAR2,                  --Пароль доступа
 an_lockcorrecttime NUMBER,                                                                                                      --Блокировать коррекцию времени
                           an_vaddparam VARCHAR2                                                                                                 --Доп параметры
 ) IS
  ln_cid              NUMBER;
  lv_old_name         VARCHAR2(2000);
  ln_parent           NUMBER := an_parentmid;
 BEGIN
  SAVEPOINT editcanals_upd;

  IF NVL(ln_parent, 0) = 0 THEN                                                                                             --Устранение ошибок старых клиентов
   ln_parent := 1;
  END IF;

  adminadd_pg.check_right(an_mid, ln_parent, 1, 2);

  SELECT NAME
  INTO   lv_old_name
  FROM   points
  WHERE  mid = an_mid;

  IF lv_old_name = av_name THEN
   lv_old_name := util_pg.node_path_f(an_mid, 'points', 'mid', 'parent');
  ELSE
   lv_old_name := util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || ' - ' || av_name;
  END IF;

  UPDATE points
  SET NAME = av_name,
      PARENT = ln_parent,
      tag = an_blocking
  WHERE  mid = an_mid;

  SELECT MAX(cid)
  INTO   ln_cid
  FROM   channels
  WHERE  cid = an_mid;

  IF ln_cid IS NOT NULL THEN
   lv_old_name := 'Изменены атрибуты канала опроса ' || lv_old_name;

   UPDATE channels
   SET vname = av_name,
       vnote = av_note,
       protocol_id = an_protocol_id,
       com_id = an_com_id,
       init_str = av_init_str,
       addr = av_addr,
       cycle_tout = an_cycle_tout,
       retries = an_retries,
       retries_tout = an_retries_tout,
       blocking = an_blocking,
       caller_name = av_caller_name,
       nbilldata = an_billdata,
       nbilldatadepth = an_billdatadepth,
       ncurrdata = an_currdata,
       ncurrdatadepth = an_currdatadepth,
       nnetparam = an_netparam,
       njournal = an_journal,
       dstart = ad_start,
       dend = ad_end,
       nday = an_day,
       nparent = an_parent,
       nnotreadcurr = an_nnotreadcurr,
       nwait = NVL(an_wait, 40),
       ndelivered = 0,
       vaccuser = av_accuser,
       vaccpassword = av_accpassword,
       nlockcorrecttime = an_lockcorrecttime,
       vaddparam = an_vaddparam
   WHERE  cid = an_mid;

   is_valid_data(an_mid);
  ELSE
   lv_old_name := 'Изменены атрибуты группы опроса' || lv_old_name;
  END IF;

  admin_pg.fiscal_p(gn_task_code, 2, lv_old_name);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editcanals_upd;
   raise_application_error(-20001, 'channels_pg.upd_p: Ошибка обновления канала. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p(an_mid NUMBER                                                                                                                        --Ид точки
                              ) IS
  ln_cid              NUMBER;
 BEGIN
  SAVEPOINT editcanals_del;
  adminadd_pg.check_right(an_mid, NULL, 1, 2);

  SELECT COUNT(*)
  INTO   ln_cid
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   channels
                WHERE  cid IN(SELECT     mid
                              FROM       points
                              CONNECT BY PRIOR mid = PARENT
                              START WITH mid = an_mid) AND is_dead IS NOT NULL);

  IF ln_cid > 0 THEN
   raise_application_error(-20001, 'По данному каналу сейчас идет опрос точек учета. Дождитесь окончания опроса.');
  END IF;

  SELECT MAX(cid)
  INTO   ln_cid
  FROM   channels
  WHERE  cid = an_mid;

  IF ln_cid IS NOT NULL THEN
   admin_pg.fiscal_p(gn_task_code, 3, 'Удален канал опроса ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
  ELSE
   admin_pg.fiscal_p(gn_task_code, 3, 'Удалена группа каналов опроса ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
  END IF;

  UPDATE channels
  SET nparent = NULL,
      blocking = 1
  WHERE  nparent = an_mid;

  UPDATE channels
  SET nparent2 = NULL
  WHERE  nparent2 = an_mid;

  DELETE FROM points
  WHERE       mid = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editcanals_del;
   raise_application_error(-20001, 'channels_pg.del_p: Ошибка удаления канала. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура привязки точек (старая)
 PROCEDURE setpoint_p(
 an_cid NUMBER,                                                                                                                                      --Ид канала
               at_mid common_pg.tt_number,                                                                                                        --Мас ид точек
                                          at_nuserescanal common_pg.tt_number                           --Мас признаков работы по дополнительным связным номерам
 ) IS
  lv_message          VARCHAR2(4000);
 BEGIN
  SAVEPOINT channels_set;

  IF at_mid.COUNT > 0 AND at_mid(1) <> 0 THEN
   FOR i IN 1 .. at_mid.COUNT LOOP
    DELETE FROM chanpoint
    WHERE       cid = an_cid AND mid = at_mid(i);
   END LOOP;
  END IF;

  FOR c IN (SELECT *
            FROM   chanpoint
            WHERE  cid = an_cid) LOOP
   lv_message :=
        'Произведена удаление точки ' || util_pg.node_path_f(c.cid, 'points', 'mid', 'parent') || ' - '
        || util_pg.node_path_f(c.mid, 'points', 'mid', 'parent');
   admin_pg.fiscal_p(gn_task_code, 3, lv_message);
  END LOOP;

  DELETE FROM chanpoint
  WHERE       cid = an_cid;

  IF at_mid.COUNT > 0 AND NVL(at_mid(1), 0) <> 0 THEN
   FOR i IN 1 .. at_mid.COUNT LOOP
    INSERT INTO chanpoint
                (cid, mid, nuserescanal)
    VALUES      (an_cid, at_mid(i), at_nuserescanal(i));

    lv_message :=
     'Произведена привязка точки ' || util_pg.node_path_f(an_cid, 'points', 'mid', 'parent') || ' - '
     || util_pg.node_path_f(at_mid(i), 'points', 'mid', 'parent');
    admin_pg.fiscal_p(gn_task_code, 1, lv_message);
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT channels_set;
   raise_application_error(-20001, 'channels_pg.setpoint_p: Ошибка привязки точек к каналам. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура определения временного канала для опроса отдельной точки учета
  -- И. Вештак, 20.11.02
 PROCEDURE tempchannels(
 cid_ NUMBER,                                                                                                                                       -- id канала
             mid_ NUMBER,                                                                                                                            -- id точки
                         retries_ NUMBER,                                                                                                      -- кол-во попыток
                                         retries_tout_ NUMBER,                                                                            -- пауза м/у попытками
                                                              an_billdata NUMBER,                                                                 --Коммерческие
                                                                                 an_billdatadepth NUMBER,                                 --Коммерческие глубина
                                                                                                         an_currdata NUMBER,                           --Текущие
                                                                                                                            an_currdatadepth NUMBER,
 --Текущие глубина
 vuser_ VARCHAR2
 )                                                                                                                                                       -- user
  IS
  newcid              NUMBER;
 BEGIN
  admin_pg.fiscal_p(gn_task_code, 2,
      'Запущен автоматическийопрос точки '
   || util_pg.node_path_f(mid_, 'points', 'mid', 'parent')
   || ' Кличество попыток - '
   || retries_
   || ' Пауза между попытками - '
   || retries_tout_
   || ' сек.');

  SELECT points_seq.NEXTVAL
  INTO   newcid
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, NAME, cod, ind, implement_date)
   (SELECT newcid, 1, p.NAME || '. ' || c.vname, 0, 2, SYSDATE
    FROM   channels c, points p
    WHERE  c.cid = cid_ AND p.mid = mid_);

  INSERT INTO channels
              (cid, vname, protocol_id, com_id, init_str, addr, cycle_tout, retries, retries_tout, blocking, caller_name, nbilldata, nbilldatadepth, ncurrdata,
               ncurrdatadepth, nnotreadcurr, vuser, nkind, nparent,nnetparam, njournal,nlockcorrecttime,vaccuser, vaccpassword,vaddparam)
   (SELECT newcid, p.NAME || '. ' || c.vname vname, c.protocol_id, c.com_id, c.init_str, c.addr, 86400, retries_, retries_tout_, 0, c.caller_name, an_billdata,
           an_billdatadepth, an_currdata, an_currdatadepth, 0, vuser_, 1, decode(1,2,1),c.nnetparam, c.njournal,c.nlockcorrecttime,c.vaccuser, c.vaccpassword,c.vaddparam
    FROM   channels c, points p
    WHERE  c.cid = cid_ AND p.mid = mid_);

  INSERT INTO chanpoint
              (cid, mid)
  VALUES      (newcid, mid_);

  COMMIT;
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   ROLLBACK;
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION is_block(an_cid NUMBER, an_blocking NUMBER, an_kind NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  IF NVL(an_blocking, 0)=0 THEN
  	ln_ret:=0;
  ELSE
			ln_ret:=1;	
  END IF;
  
  IF ln_ret = 0 AND NVL(an_kind, 0) <> 100 THEN
   SELECT     DECODE(NVL(MAX(tag), 0), 0, 0, 1)
   INTO       ln_ret
   FROM       points
   CONNECT BY PRIOR PARENT = mid
   START WITH mid = an_cid;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает паузу между циклами
 FUNCTION cycletout_f(an_channel NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
  ln_channel          NUMBER DEFAULT get_main_channel(an_channel);
 BEGIN
  SELECT MAX(cycle_tout)
  INTO   ln_ret
  FROM   channels
  WHERE  cid = ln_channel;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_main_channel(an_channel NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT     MAX(cid)
  INTO       ln_ret
  FROM       channels
  WHERE      nparent IS NULL
  CONNECT BY PRIOR nparent = cid
  START WITH cid = an_channel;

  RETURN NVL(ln_ret, 0);
 END;

------------------------------------------------------------------------------------------------------------------------
--Проверка правильности данных по отношению родителей (connect by в данных пользователя)
 PROCEDURE is_valid_data(an_cid NUMBER) IS
  ln_tmp              NUMBER;
 BEGIN
  SELECT MAX(ID)
  INTO   ln_tmp
  FROM   (SELECT     MAX(cid) ID
          FROM       channels
          CONNECT BY PRIOR cid = nparent
          START WITH cid = an_cid
          UNION
          SELECT     MAX(cid) ID
          FROM       channels
          CONNECT BY PRIOR nparent = cid
          START WITH cid = an_cid);
 EXCEPTION
  WHEN OTHERS THEN
   IF SQLCODE = -1436 THEN
    raise_application_error(-20001, 'Основной канал указан не корректно. Обнаружено зацикливание связей.');
   ELSE
    RAISE;
   END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION user_f(an_cid NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(256);
 BEGIN
  SELECT MAX(vaccuser)
  INTO   lv_ret
  FROM   channels
  WHERE  cid = an_cid;

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION pass_f(an_cid NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(256);
 BEGIN
  SELECT MAX(vaccpassword)
  INTO   lv_ret
  FROM   channels
  WHERE  cid = an_cid;

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Признак отображения vimportcode
 FUNCTION is_viewimportcode(an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN(37, 61, 113) THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Kondakov A.G.  created    28.07.2008
-------------------------------------------------------------------------------
 PROCEDURE get_mid(an_item NUMBER, acur_t OUT common_pg.tcur) IS
 -- получение mid каналов из списка
 BEGIN
  OPEN acur_t FOR
   SELECT mid
   FROM   srv
   WHERE  nsrv = an_item;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_readnode(an_id NUMBER, an_acc NUMBER, acur_t OUT common_pg.tcur) IS
  -- Читает список каналов
  ln_tmp              NUMBER := 0;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_tmp
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   srv
                WHERE  mid = an_id);

  IF ln_tmp > 0 THEN
                                                                                                  --первый вход (стартуем с вершин)
   OPEN acur_t FOR
    SELECT   DECODE(c.cid, NULL, 1, 0) is_group, (SELECT COUNT(*)
                                                  FROM   points
                                                  WHERE  PARENT = p.mid) has_child, NVL(c.cid, p.mid) cid, p.NAME vname, c.vnote, c.protocol_id, c.com_id,
             c.init_str, c.addr, DECODE(c.nkind, 100, c.cycle_tout2, cycletout_f(c.cid)) cycle_tout, c.retries, c.retries_tout,
             NVL(DECODE(c.nkind, 100, c.blocking2, c.blocking), p.tag) blocking, caller_name, nbilldata, nbilldatadepth, ncurrdata, ncurrdatadepth, nnetparam,
             njournal, TO_CHAR(DECODE(c.nkind, 100, c.dstart2, c.dstart), 'hh24:mi') dstart, TO_CHAR(DECODE(c.nkind, 100, c.dend2, c.dend), 'hh24:mi') dend,
             nday, DECODE(c.nkind, 100, c.nparent2, c.nparent) nparent, DECODE(c.nkind, 100, c.nnotreadcurr2, c.nnotreadcurr) nnotreadcurr, nwait, c.vaccuser,
             DECODE(an_acc, 1, c.vaccpassword, NULL) eusdpassword, c.nlockcorrecttime, c.vaddparam
    FROM     points p, channels c
    WHERE    p.mid IN(SELECT *
                      FROM   TABLE(adminadd_pg.getfirst_accmid(util_pg.cn_cidmid, an_id))) AND p.mid = c.cid(+) AND NVL(nkind, 0) <> 1
    ORDER BY is_group DESC, vname;
  ELSE
   IF adminadd_pg.check_accread(an_id)=0 THEN
				raise_application_error(-20002, 'В доступе отказано. an_id='||an_id);
			END IF;
   OPEN acur_t FOR
    SELECT   DECODE(c.cid, NULL, 1, 0) is_group, (SELECT COUNT(*)
                                                  FROM   points
                                                  WHERE  PARENT = p.mid) has_child, NVL(c.cid, p.mid) cid, p.NAME vname, c.vnote, c.protocol_id, c.com_id,
             c.init_str, c.addr, DECODE(c.nkind, 100, c.cycle_tout2, cycletout_f(c.cid)) cycle_tout, c.retries, c.retries_tout,
             NVL(DECODE(c.nkind, 100, c.blocking2, c.blocking), p.tag) blocking, caller_name, nbilldata, nbilldatadepth, ncurrdata, ncurrdatadepth, nnetparam,
             njournal, TO_CHAR(DECODE(c.nkind, 100, c.dstart2, c.dstart), 'hh24:mi') dstart, TO_CHAR(DECODE(c.nkind, 100, c.dend2, c.dend), 'hh24:mi') dend,
             nday, DECODE(c.nkind, 100, c.nparent2, c.nparent) nparent, DECODE(c.nkind, 100, c.nnotreadcurr2, c.nnotreadcurr) nnotreadcurr, nwait, c.vaccuser,
             DECODE(an_acc, 1, c.vaccpassword, NULL) eusdpassword, c.nlockcorrecttime, c.vaddparam
    FROM     points p, channels c
    WHERE    p.PARENT = an_id AND p.mid = c.cid(+) AND NVL(nkind, 0) <> 1
    ORDER BY is_group DESC, vname;
  END IF;
 END;

