PACKAGE BODY check_pg IS
--
-- Purpose: Процедуры верификации
--
-- MODIFICATION HISTORY
-- Person      Date    Comments
-- ---------   ------  ------------------------------------------
-- Вештак      09.01.03 Создан
-- Вештак      25.06.03 Реализовано замещение в check_status старых сообщений новыми
--                      для отката этой политики необходимо закомментировать оператор под меткой -- Substitute
 ------------------------------------------------------------------------------------------------------------------------
 cn_pointname     CONSTANT NUMBER := 500;
 cn_checksystem   CONSTANT NUMBER := 524;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE verify_qm (an_mid NUMBER, ad_from DATE, ad_to DATE) IS
  ld_ndzdate     DATE                DEFAULT NULL;
  ln_ndzrung     NUMBER              DEFAULT -1;   -- приоритет НДЗ
  ln_ndzmid      NUMBER;
  ln_ndzsource   NUMBER;
  ln_ndzqm       VARCHAR (100);
  lt_ndzval      common_pg.tt_number;   -- собственно значения НДЗ
  ln_ndzop       NUMBER;   -- оценка погрешности НДЗ
  ln_ozcnt       NUMBER              DEFAULT 0;   -- счетчик кол-ва ОЗ
  ln_modul       NUMBER;   -- модуль рассогласования
  ln_tolerance   NUMBER;   -- допуск рассогласования
  ln_kd          NUMBER              DEFAULT 1;   -- поправочный коэффициент
  ln_conscnt     NUMBER              DEFAULT 0;   -- кол-во согласованных ОЗ
  ln_du          NUMBER              DEFAULT 0.5;   -- доверительный уровень
 BEGIN
  FOR lc IN (SELECT   h.*, qm_pg.rungqm (h.vqm) rung, f.nclasstn, f.nclasstt
                 FROM halfhour h, feeders f
                WHERE h.mid IN (SELECT     mid
                                      FROM points
                                CONNECT BY PRIOR mid = PARENT
                                START WITH mid = an_mid) AND h.date_time > ad_from AND h.date_time <= ad_to AND h.mid = f.mid
             ORDER BY h.date_time, qm_pg.rungqm (h.vqm), h.denter) LOOP
   IF ld_ndzdate = lc.date_time THEN   -- смотрим ОЗ с той же меткой времени, что и у НДЗ
    IF lc.rung = 1 OR lc.rung = 2 THEN   -- ОЗ good или questionable, учитываем его
     ln_ozcnt := ln_ozcnt + 1;
     -- посчитать рассогласование
     ln_modul :=
      GREATEST (ABS (NVL (lc.er, 0) - NVL (lt_ndzval (0), 0)), ABS (NVL (lc.ed, 0) - NVL (lt_ndzval (1), 0)), ABS (NVL (lc.q1, 0) - NVL (lt_ndzval (2), 0)),
                ABS (NVL (lc.q2, 0) - NVL (lt_ndzval (3), 0)), ABS (NVL (lc.q3, 0) - NVL (lt_ndzval (4), 0)), ABS (NVL (lc.q4, 0) - NVL (lt_ndzval (5), 0)),
                ABS (NVL (lc.erm, 0) - NVL (lt_ndzval (6), 0)), ABS (NVL (lc.edm, 0) - NVL (lt_ndzval (7), 0)), ABS (NVL (lc.q1m, 0) - NVL (lt_ndzval (8), 0)),
                ABS (NVL (lc.q2m, 0) - NVL (lt_ndzval (9), 0)), ABS (NVL (lc.q3m, 0) - NVL (lt_ndzval (10), 0)), ABS (NVL (lc.q4m, 0) - NVL (lt_ndzval (11), 0)));
     -- считаем допуск
     ln_tolerance := ln_kd * (ln_ndzop - lc.nclasstt);

     IF ln_modul < ln_tolerance THEN   -- данное ОЗ согласованно с НДЗ
      ln_conscnt := ln_conscnt + 1;
     END IF;
    END IF;
   ELSE   -- разбираем предыдущее НДЗ, формируем новое
    -- сначала корректируем метку качества предыдущего НДЗ
    IF ln_ndzrung <> -1 THEN   -- для не первого НДЗ
     IF ln_ozcnt = 0 THEN   -- ставим PrimaryVerification(17)=NoData, если не было ОЗ
      evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 17, 1, ln_ndzsource, ln_ndzqm);
     ELSE
      IF ln_conscnt > ln_ozcnt * ln_du THEN   -- НДЗ согласованное с ОЗ
       evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 17, 2, ln_ndzsource, ln_ndzqm);   -- ставим PrimaryVerification(17)=OK
      ELSE   -- НДЗ несогласованное с ОЗ
       evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 1, 3, ln_ndzsource, ln_ndzqm);   -- ставим Validity(1)=questionable
       evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 17, 3, ln_ndzsource, ln_ndzqm);   -- ставим PrimaryVerification(17)=Error
      END IF;
     END IF;
    END IF;

    -- устанавливаем характеристики нового НДЗ для дальнейшей обработки
    ld_ndzdate := lc.date_time;
    ln_ndzrung := lc.rung;
    ln_ndzsource := lc.nsource;
    ln_ndzmid := lc.mid;
    ln_ndzqm := lc.vqm;
    lt_ndzval (0) := lc.er;
    lt_ndzval (1) := lc.ed;
    lt_ndzval (2) := lc.q1;
    lt_ndzval (3) := lc.q2;
    lt_ndzval (4) := lc.q3;
    lt_ndzval (5) := lc.q4;
    lt_ndzval (6) := lc.erm;
    lt_ndzval (7) := lc.edm;
    lt_ndzval (8) := lc.q1m;
    lt_ndzval (9) := lc.q2m;
    lt_ndzval (10) := lc.q3m;
    lt_ndzval (11) := lc.q4m;
    ln_ndzop := lc.nclasstt;   -- оценка погрешности, разобраться как считать!

    IF ln_ndzrung > 2 THEN   -- НДЗ плохое
     NULL;   -- установить метку если надо, разобраться!
    END IF;

    ln_ozcnt := 0;
    ln_conscnt := 0;
   END IF;
  END LOOP;

  IF ln_ndzrung <> -1 THEN   -- для не первого НДЗ
   IF ln_ozcnt = 0 THEN   -- ставим PrimaryVerification(17)=NoData, если не было ОЗ
    evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 17, 1, ln_ndzsource, ln_ndzqm);
   ELSE
    IF ln_conscnt > ln_ozcnt * ln_du THEN   -- НДЗ согласованное с ОЗ
     evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 17, 2, ln_ndzsource, ln_ndzqm);   -- ставим PrimaryVerification(17)=OK
    ELSE   -- НДЗ несогласованное с ОЗ
     evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 1, 3, ln_ndzsource, ln_ndzqm);   -- ставим Validity(1)=questionable
     evid_terme_pg.set_vqm (ln_ndzmid, ld_ndzdate, 17, 3, ln_ndzsource, ln_ndzqm);   -- ставим PrimaryVerification(17)=Error
    END IF;
   END IF;
  END IF;
 END;

