 PROCEDURE by_balance (an_maket NUMBER, ad_date DATE) IS
  lv_ret        VARCHAR2 (50);
  ln_limit      NUMBER;
  ln_mlimit     NUMBER        DEFAULT 0;
  ln_count      NUMBER        DEFAULT 0;
  ld_date       DATE          DEFAULT TRUNC (ad_date);
  ln_typever    NUMBER;
  ln_minvalue   NUMBER;
  lb_in         BOOLEAN;
  lb_alarm      BOOLEAN;
 /*Верификация по балансам суммируем прием и отдачу прием должен быть на ln_limit больше чем отдача
 */
 BEGIN
  DELETE FROM check_resultsg
        WHERE nprocedure = cn_balance AND ddate > ld_date AND ddate <= ld_date + 1;

  ---Сверка баланса с уставкой
  UPDATE halfhour
     SET vqm = qm_pg.sbt (vqm, 21, qm_pg.cn_add_def)
   WHERE date_time > ld_date AND date_time <= ld_date + 1 AND mid IN (SELECT     mid
                                                                            FROM GROUPS
                                                                           WHERE mid IS NOT NULL
                                                                      CONNECT BY PRIOR gid = PARENT
                                                                      START WITH LOWER (vparam) LIKE 'баланс%') AND vqm <> qm_pg.sbt (vqm, 21, qm_pg.cn_add_def);

  FOR lc IN (SELECT   gid, vparam
                 FROM GROUPS
                WHERE LOWER (vparam) LIKE 'баланс%'
             ORDER BY NAME, gid) LOOP
   BEGIN
    ln_limit := NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 2)), util_pg.get_param (file_pg.gv_param, 1)))), 2) / 100;
    ln_typever := NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 3)), util_pg.get_param (file_pg.gv_param, 2)))), 1440);
    ln_minvalue := NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 4)), util_pg.get_param (file_pg.gv_param, 3)))), 0);
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error (-20002, 'Параметры для верификации не корректны по группе: ' || util_pg.get_groupname (lc.gid, 2));
   END;

   lb_in := FALSE;

   FOR lc1 IN (SELECT s.dat, lc.gid, cn_balance, ln_limit * 100 lim, s.er, s.ed, s.qm
                 FROM (SELECT   TRUNC (ld_date) + TRUNC (TO_CHAR (h.date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever) * 60 * ln_typever / 86400
                                + ln_typever / 1440 dat,
                                NVL (SUM (DECODE (g.inverted, 'y', h.ed * DECODE (g.npartly, 1, 0, 1), h.er * DECODE (g.npartly, 2, 0, 1))), 0) er,
                                NVL (SUM (DECODE (g.inverted, 'y', h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1))), 0) ed, sumqm (h.vqm) qm
                           FROM halfhour h, GROUPS g
                          WHERE h.mid = g.mid AND h.date_time > ld_date AND h.date_time <= ld_date + 1 AND g.gid IN (SELECT     gid
                                                                                                                           FROM GROUPS
                                                                                                                          WHERE mid IS NOT NULL
                                                                                                                     CONNECT BY PRIOR gid = PARENT
                                                                                                                     START WITH gid = lc.gid)
                       GROUP BY TRUNC (TO_CHAR (h.date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever)) s) LOOP
    lb_alarm := ABS (lc1.er - lc1.ed) > ln_limit * GREATEST (lc1.er, lc1.ed) AND ABS (lc1.er - lc1.ed) > ln_minvalue;

    IF lb_alarm THEN
     lb_in := TRUE;

     INSERT INTO check_resultsg
                 (ddate, gid, nprocedure, vparam, nmustbe, nindeed
                 )
          VALUES (lc1.dat, lc.gid, cn_balance, lc1.lim, lc1.er, lc1.ed
                 );
    END IF;

    FOR lc2 IN (SELECT mid
                  FROM points
                 WHERE mid IN (SELECT     mid
                                     FROM GROUPS
                                    WHERE mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = lc.gid) AND ind = 4) LOOP
     IF qm_pg.gbt (lc1.qm, 1) IN (qm_pg.cn_invalid, qm_pg.cn_reserv) THEN   --Если данных нет или они недостоверны, то ставим недостаточно данных
      UPDATE halfhour
         SET vqm = qm_pg.sbt (vqm, 21, qm_pg.cn_add_insuff)
       WHERE mid = lc2.mid AND date_time > lc1.dat - ln_typever / 1440 AND date_time <= lc1.dat AND vqm <> qm_pg.sbt (vqm, 21, qm_pg.cn_add_insuff);
     ELSIF lb_alarm THEN   --Если предупреждение
      UPDATE halfhour
         SET vqm = qm_pg.sbt (qm_pg.sbt (qm_pg.sbt (vqm, 1, qm_pg.cn_question), 21, qm_pg.cn_add_err), 8, qm_pg.cn_yes)
       WHERE mid = lc2.mid AND date_time > lc1.dat - ln_typever / 1440 AND date_time <= lc1.dat
             AND vqm <> qm_pg.sbt (qm_pg.sbt (qm_pg.sbt (vqm, 1, qm_pg.cn_question), 21, qm_pg.cn_add_err), 8, qm_pg.cn_yes)
             AND qm_pg.gbt (vqm, 1) IN (qm_pg.cn_ok, qm_pg.cn_question);
     ELSE   --Иначе Все ОК
      UPDATE halfhour
         SET vqm = qm_pg.sbt (vqm, 21, qm_pg.cn_add_ok)
       WHERE mid = lc2.mid AND date_time > lc1.dat - ln_typever / 1440 AND date_time <= lc1.dat AND vqm <> qm_pg.sbt (vqm, 21, qm_pg.cn_add_ok);
     END IF;
    END LOOP;
   END LOOP;

   IF lb_in THEN
    ln_count := ln_count + 1;
    ln_mlimit := GREATEST (ABS (ln_limit), ABS (ln_mlimit)) * SIGN (GREATEST (ABS (ln_limit), ABS (ln_mlimit)));
   END IF;
  END LOOP;

  ---Сверка баланса с допустимым небалансом
  FOR lc IN (SELECT gid, vparam
               FROM GROUPS
              WHERE LOWER (vparam) LIKE 'небаланс%') LOOP
   NULL;
  END LOOP;

  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной подстанции/линии.';
   ELSE
    lv_ret := ln_count || ' подстанциям/линиям.';
   END IF;

   UPDATE check_status
      SET   --одна прцедура одна строка на первичный ключ не смотри
         ddate = ld_date,
         vtext = 'Сверка по балансам: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret
    WHERE nprocedure = cn_balance;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_balance, ld_date, 'Сверка по балансам: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, cn_balance, 1, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret,
                           cn_checksystem);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_balance;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_balance, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' cостояние: Норма', cn_checksystem);
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.by_balance: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_duplicatemeter (an_maket NUMBER, ad_date DATE) IS
  lv_ret         VARCHAR2 (50);
  ln_limit       NUMBER;
  ln_mlimit      NUMBER          DEFAULT 0;
  ln_count       NUMBER          DEFAULT 0;
  ld_date        DATE            DEFAULT TRUNC (ad_date);
  ln_typever     NUMBER;
  ln_minvalue    NUMBER;
  lv_pointname   VARCHAR2 (4000);
  lb_in          BOOLEAN;
  lb_alarm       BOOLEAN;
  ln_parentmid   NUMBER;
 /* Верификация по дублям разница не должна превышать ln_limit % от MAX */
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_duplicatemeter AND ddate > ld_date AND ddate <= ld_date + 1;

  FOR lc IN (SELECT nmainpoint, mid, verifyparam vparam
               FROM feeders f
              WHERE nmainpoint > 0 AND TRIM (verifyparam) IS NOT NULL) LOOP
   BEGIN
    ln_limit := ABS (NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 1)), util_pg.get_param (file_pg.gv_param, 1)))), 2) / 100);
    ln_typever := NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 2)), util_pg.get_param (file_pg.gv_param, 2)))), 1440);
    ln_minvalue := NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 3)), util_pg.get_param (file_pg.gv_param, 3)))), 0);
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error (-20002, 'Параметры для верификации не корректны по точке: ' || util_pg.get_pointname (lc.mid, 1));
   END;

   lb_in := FALSE;

   FOR lc1 IN
    (SELECT m.dat, ln_limit * 100 lim, DECODE (SIGN (ABS (m.er - d.er) - ln_limit * GREATEST (m.er, d.er)), 1, m.er, m.ed) nmustbe,
            DECODE (SIGN (ABS (m.er - d.er) - ln_limit * GREATEST (m.er, d.er)), 1, d.er, d.ed) nindeed, qm_pg.sumqm (m.qm, d.qm) qm, m.er mer, m.ed med, d.er der,
            d.ed ded
       FROM   --(select TRUNC(ld_date)+ln_typever*rownum/1440 dat from halfhour where rownum<=1440/ln_typever) t
            (SELECT   TRUNC (ld_date) + TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever) * 60 * ln_typever / 86400 + ln_typever / 1440 dat,
                      SUM (er) er, SUM (ed) ed, sumqm (vqm) qm
                 FROM halfhour
                WHERE mid = lc.nmainpoint AND date_time > ld_date AND date_time <= ld_date + 1 AND NOT (nsource BETWEEN 30 AND 49)
             GROUP BY TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever)) m,
            (SELECT   TRUNC (ld_date) + TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever) * 60 * ln_typever / 86400 + ln_typever / 1440 dat,
                      SUM (er) er, SUM (ed) ed, sumqm (vqm) qm
                 FROM halfhour
                WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1 AND NOT (nsource BETWEEN 30 AND 49)
             GROUP BY TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever)) d
      WHERE m.dat = d.dat) LOOP
    lb_alarm :=
     ((ABS (lc1.mer - lc1.der) > ln_limit * GREATEST (lc1.mer, lc1.der)) OR (ABS (lc1.med - lc1.ded) > ln_limit * GREATEST (lc1.med, lc1.ded)))
     AND ((ABS (lc1.mer - lc1.der) > ln_minvalue) OR (ABS (lc1.med - lc1.ded) > ln_minvalue));

    IF lb_alarm THEN
     INSERT INTO check_results
                 (ddate, mid, nprocedure, vparam, nmustbe, nindeed
                 )
          VALUES (lc1.dat, lc.mid, cn_duplicatemeter, lc1.lim, lc1.nmustbe, lc1.nindeed
                 );

     lb_in := TRUE;
    END IF;

    ln_parentmid := util_pg.getsupplypoint (lc.nmainpoint, 1);

    IF qm_pg.gbt (lc1.qm, 1) IN (qm_pg.cn_invalid, qm_pg.cn_reserv) THEN   --Если данных нет или они недостоверны, то ставим недостаточно данных
     UPDATE halfhour
        SET vqm = qm_pg.sbt (vqm, 18, qm_pg.cn_add_insuff)
      WHERE mid = ln_parentmid AND date_time > lc1.dat - ln_typever / 1440 AND date_time <= lc1.dat AND vqm <> qm_pg.sbt (vqm, 18, qm_pg.cn_add_insuff);
    ELSIF lb_alarm THEN   --Если предупреждение
     UPDATE halfhour
        SET vqm = qm_pg.sbt (qm_pg.sbt (qm_pg.sbt (vqm, 1, qm_pg.cn_question), 18, qm_pg.cn_add_err), 8, qm_pg.cn_yes)
      WHERE mid = ln_parentmid AND date_time > lc1.dat - ln_typever / 1440 AND date_time <= lc1.dat
            AND vqm <> qm_pg.sbt (qm_pg.sbt (qm_pg.sbt (vqm, 1, qm_pg.cn_question), 18, qm_pg.cn_add_err), 8, qm_pg.cn_yes)
            AND qm_pg.gbt (vqm, 1) IN (qm_pg.cn_ok, qm_pg.cn_question);
    ELSE   --Иначе Все ОК
     UPDATE halfhour
        SET vqm = qm_pg.sbt (vqm, 18, qm_pg.cn_add_ok)
      WHERE mid = ln_parentmid AND date_time > lc1.dat - ln_typever / 1440 AND date_time <= lc1.dat AND vqm <> qm_pg.sbt (vqm, 18, qm_pg.cn_add_ok);
    END IF;
   END LOOP;

   IF lb_in THEN
    ln_count := ln_count + 1;
    ln_mlimit := GREATEST (ABS (ln_limit), ABS (ln_mlimit)) * SIGN (GREATEST (ABS (ln_limit), ABS (ln_mlimit)));
   END IF;
  END LOOP;

  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке.';
   ELSE
    lv_ret := ln_count || ' точкам.';
   END IF;

   lv_pointname := '';

   FOR lc IN (SELECT DISTINCT mid
                         FROM check_results
                        WHERE nprocedure = cn_duplicatemeter AND ddate > ld_date AND ddate <= ld_date + 1) LOOP
    lv_pointname := SUBSTR (lv_pointname || util_pg.get_pointname (lc.mid, 1), 1, cn_pointname);
    admin_pg.ins_journal_p (SYSDATE, lc.mid, 1, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 || '%.', cn_checksystem);
   END LOOP;

   UPDATE check_status
      SET   --одна прцедура одна строка на первичный ключ не смотри
         ddate = ld_date,
         vtext =
          SUBSTR ('Сверка по дублирующим счетчикам: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret || ' ' || lv_pointname, 1,
                  cn_pointname)
    WHERE nprocedure = cn_duplicatemeter;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext
                )
         VALUES (cn_duplicatemeter, ld_date,
                 SUBSTR ('Сверка по дублирующим счетчикам: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret || ' ' || lv_pointname, 1,
                         cn_pointname)
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, cn_duplicatemeter, 1,
                           TO_CHAR (ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret, cn_checksystem);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_duplicatemeter;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_duplicatemeter, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' состояние: Норма', cn_checksystem);
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.by_duplicatemeter: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkpower (an_maket NUMBER, ad_date DATE) IS
  ln_typever   CONSTANT NUMBER                := 30;
  ld_date               DATE                  DEFAULT util_pg.trunc_d (ad_date, ln_typever / 1440);
  ln_proc               NUMBER;
  ln_fact               NUMBER;
  ln_limit              NUMBER;
  ln_count              NUMBER                DEFAULT 0;
  lv_ret                VARCHAR2 (50);
  lt_sms                common_pg.tt_varchar2;
 BEGIN
  ln_proc := NVL (util_pg.allnumber_f (util_pg.get_param (file_pg.gv_param, 1)), 1);

  DELETE FROM check_resultsg
        WHERE nprocedure = cn_checkpower AND ddate > ld_date AND ddate <= ld_date + ln_typever / 1440;

  FOR lc IN (SELECT DISTINCT gid
                        FROM grouplimit
                       WHERE dstart <= ld_date) LOOP
   ln_fact := (60 / ln_typever) * util_pg.get_saldo (lc.gid, ld_date, ld_date + ln_typever / 1440);
   ln_limit := util_pg.get_grouplimit (lc.gid, ld_date + ln_typever / 1440);

   IF ln_fact > ln_proc * ln_limit THEN
    IF lt_sms.COUNT = 0 THEN
     lt_sms (1) := 'CHECKPOWER WARNING:';
    END IF;

    INSERT INTO check_resultsg
                (ddate, gid, nprocedure, vparam, nmustbe, nindeed
                )
         VALUES (ld_date + ln_typever / 1440, lc.gid, cn_checkpower, ROUND (ln_proc * 100), ln_limit, ln_fact
                );

    ln_count := ln_count + 1;
    lt_sms (1) := lt_sms (1) || ' G.' || lc.gid || ': ' || ROUND (ln_fact) || '/' || ROUND (ln_limit);
   END IF;
  END LOOP;

  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной контрольной группе.';
   ELSE
    lv_ret := ln_count || ' контрольным группам.';
   END IF;

   UPDATE check_status
      SET   --одна прцедура одна строка на первичный ключ не смотри
         ddate = ld_date + ln_typever / 1440,
         vtext = 'Контроль мощности: превышена допустимая граница ' || ln_proc * 100 || '% по ' || lv_ret
    WHERE nprocedure = cn_checkpower;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_checkpower, ld_date + ln_typever / 1440, 'Контроль мощности: превышена допустимая граница ' || ln_proc * 100 || '% по ' || lv_ret
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, cn_checkpower, 1,
                           TO_CHAR (ld_date + ln_typever / 1440, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_proc * 100 || '% по ' || lv_ret,
                           cn_checksystem);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_checkpower;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_checkpower, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' cостояние: Норма', cn_checksystem);
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;

  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p (lt_sms, ld_date);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.checkpower: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_day_and_hour (an_maket NUMBER, ad_date DATE) IS
  lv_ret         VARCHAR2 (50);
  ln_limit       NUMBER;
  ln_mlimit      NUMBER                DEFAULT 0;
  ln_count       NUMBER                DEFAULT 0;
  ld_date        DATE                  DEFAULT TRUNC (ad_date);
  ln_minvalue    NUMBER;
  lv_pointname   VARCHAR2 (4000);
  lt_sms         common_pg.tt_varchar2;
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_day_and_hour AND ddate > ld_date AND ddate <= ld_date + 1;

  FOR lc IN (SELECT mid, verifyday vparam
               FROM feeders f
              WHERE TRIM (verifyday) IS NOT NULL) LOOP
   BEGIN
    ln_limit := ABS (NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 1)), util_pg.get_param (file_pg.gv_param, 1)))), 1) / 100);
    ln_minvalue := ABS (NVL (TO_NUMBER (TRIM (NVL (TRIM (util_pg.get_param (lc.vparam, 2)), util_pg.get_param (file_pg.gv_param, 2)))), 1));
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error (-20002, 'Параметры для верификации суточных расходов не корректны по точке: ' || util_pg.get_pointname (lc.mid, 1));
   END;

   INSERT INTO check_results
               (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
    SELECT ld_date + 1, lc.mid, cn_day_and_hour, ln_limit * 100, DECODE (SIGN (ABS (h.ed - d.ed) - ABS (h.er - d.er)), 1, d.ed, d.er) de,
           DECODE (SIGN (ABS (h.ed - d.ed) - ABS (h.er - d.er)), 1, h.ed, h.er) he
      FROM (SELECT SUM (er) er, SUM (ed) ed
              FROM halfhour
             WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1
            HAVING MAX (date_time) = ld_date + 1) h,
           (SELECT SUM (b.er) er, SUM (b.ed) ed
              FROM billorg b
             WHERE b.mid = lc.mid AND b.date_time = ld_date + 1 AND EXISTS (SELECT *
                                                                              FROM billorg
                                                                             WHERE mid = lc.mid AND date_time = ld_date AND er_mtrsn = b.er_mtrsn)) d
     WHERE (ABS (h.er - d.er) > ln_limit * GREATEST (h.er, d.er) AND ABS (h.er - d.er) > ln_minvalue)
           OR (ABS (h.ed - d.ed) > ln_limit * GREATEST (h.ed, d.ed) AND ABS (h.ed - d.ed) > ln_minvalue);

   IF SQL%ROWCOUNT > 0 THEN
    ln_count := ln_count + 1;
    ln_mlimit := GREATEST (ln_limit, ln_mlimit);
   END IF;
  END LOOP;

  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке.';
   ELSE
    lv_ret := ln_count || ' точкам.';
   END IF;

   lt_sms (1) := 'CHECKDAYHOUR WARNING: ' || ln_count;
   lv_pointname := '';

   FOR lc IN (SELECT DISTINCT mid
                         FROM check_results
                        WHERE nprocedure = cn_day_and_hour AND ddate > ld_date AND ddate <= ld_date + 1) LOOP
    lv_pointname := SUBSTR (lv_pointname || util_pg.get_pointname (lc.mid, 1), 1, cn_pointname);
    admin_pg.ins_journal_p (SYSDATE, lc.mid, 1, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 || '%.', cn_checksystem);
   END LOOP;

   UPDATE check_status
      SET   --одна прцедура одна строка на первичный ключ не смотри
         ddate = ld_date,
         vtext =
           SUBSTR ('Сверка суточных расходов с ГН: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname)
    WHERE nprocedure = cn_day_and_hour;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext
                )
         VALUES (cn_day_and_hour, ld_date,
                 SUBSTR ('Сверка суточных расходов с ГН: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret || ' ' || lv_pointname, 1,
                         cn_pointname)
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, cn_day_and_hour, 1,
                           TO_CHAR (ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' || lv_ret, cn_checksystem);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_day_and_hour;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_day_and_hour, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' состояние: Норма', cn_checksystem);
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;

  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p (lt_sms, ld_date);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.by_day_and_hour: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkmtrsn (an_maket NUMBER, ad_date DATE) IS
  lv_ret         VARCHAR2 (50);
  lv_pointname   VARCHAR2 (4000);
  ld_date        DATE                  DEFAULT TRUNC (ad_date);
  ln_count       NUMBER                DEFAULT 0;
  lt_sms         common_pg.tt_varchar2;
 BEGIN
  SELECT COUNT (DISTINCT b.mid)
    INTO ln_count
    FROM meters m, billorg b
   WHERE b.date_time >= ld_date + 1 AND b.date_time < ld_date + 2 AND b.mid = m.mid AND m.mid IN (SELECT mid
                                                                                                    FROM chanpoint)
         AND (LPAD (m.mtrsn, 100, '0') <> LPAD (b.er_mtrsn, 100, '0') OR (m.mtrsn IS NULL AND b.er_mtrsn IS NOT NULL));

  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке.';
   ELSE
    lv_ret := ln_count || ' точкам.';
   END IF;

   IF lt_sms.COUNT = 0 THEN
    lt_sms (1) := 'CHECKMTRSN WARNING: ' || ln_count;
   END IF;

   lv_pointname := '';

   UPDATE check_status
      SET   --одна прцедура одна строка на первичный ключ не смотри
         ddate = ld_date,
         vtext = SUBSTR ('Контроль номера устройства с НСИ: несоответствие по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname)
    WHERE nprocedure = cn_checkmtrsn;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_checkmtrsn, ld_date, SUBSTR ('Контроль номера устройства с НСИ: несоответствие по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname)
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, cn_checkmtrsn, 1, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' выявлено несоответствие по ' || lv_ret, cn_checksystem);   
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_checkmtrsn;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_checkmtrsn, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' состояние: Норма', cn_checksystem);   
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;

  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p (lt_sms, ld_date);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.checkmtrsn: ' || CHR (10) || SQLERRM (SQLCODE));
 END;
