 -- проверяет факт отображения в АСКУЭ реальной замены счетчика
 -- added by KAG 10.03.2011
 PROCEDURE checkmeters (an_maket NUMBER, ad_date DATE) IS
  lv_ret         VARCHAR2 (50);
  lv_pointmids   VARCHAR2 (4000);
  ld_date        DATE                  DEFAULT TRUNC (ad_date);
  ln_count       NUMBER                DEFAULT 0;
  lt_sms         common_pg.tt_varchar2;
 BEGIN
  FOR lc IN (SELECT DISTINCT b.mid mid
               FROM meters m, billorg b
              WHERE b.date_time >= ld_date AND b.date_time < ld_date + 1 
                    AND b.mid = m.mid AND m.mid IN (SELECT mid FROM chanpoint)
                    AND (LPAD (m.mtrsn, 100, '0') <> LPAD (b.er_mtrsn, 100, '0') OR (m.mtrsn IS NULL AND b.er_mtrsn IS NOT NULL))) LOOP
     lv_pointmids := lv_pointmids || ' ' || lc.mid;
     ln_count := ln_count + 1;                 
  END LOOP;       

  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке: ';
   ELSE
    lv_ret := ln_count || ' точкам: ';
   END IF;

   IF lt_sms.COUNT = 0 THEN
    lt_sms (1) := 'CHECKMTRSN WARNING: ' || ln_count;
   END IF;

   UPDATE check_status
      SET ddate = ld_date,
          vtext = SUBSTR ('Контроль номера устройства с НСИ: несоответствие по ' || lv_ret || ' ИД точек:'||lv_pointmids, 1, cn_pointname)
    WHERE nprocedure = cn_checkmeters;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_checkmeters, ld_date, SUBSTR ('Контроль номера устройства с НСИ: несоответствие по ' || lv_ret || ' ИД точек:'||lv_pointmids, 1, cn_pointname)
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, an_maket, 1, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' выявлено несоответствие по ' || lv_ret || ' ИД точек:'||lv_pointmids);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_checkmeters;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, an_maket, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' состояние: Норма');
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;

  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p (lt_sms, ld_date);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.checkmeters: ' || CHR (10) || SQLERRM (SQLCODE));
 END;
