 PROCEDURE checkcomplete (an_maket NUMBER, ad_date DATE) IS
  ld_date      DATE                  DEFAULT TRUNC (ad_date);
  ln_mustcnt   NUMBER                DEFAULT 48 - 2 * util_pg.is_dayswitch (ld_date);
  ln_fact      NUMBER;
  ln_limit     NUMBER;
  ln_sm        NUMBER;
  ln_count     NUMBER                DEFAULT 0;
  ln_i         NUMBER                DEFAULT 0;
  lv_ret       VARCHAR2 (50);
  lt_sms       common_pg.tt_varchar2;
  ln_group     NUMBER;
  lv_add       VARCHAR2 (4000);
 BEGIN
  DELETE FROM check_resultsg
        WHERE nprocedure = cn_checkcomplete AND ddate > ld_date AND ddate <= ld_date + 1;

  lt_sms (1) := '';

  LOOP
   ln_group := util_pg.allnumber_f (TRIM (util_pg.get_param (file_pg.gv_param, ln_i + 1)));

   IF NVL (ln_group, 0) = 0 THEN
    EXIT;
   ELSE
    ln_i := ln_i + 1;
   END IF;

   SELECT SUM (DECODE (h.cn, ln_mustcnt, 0, 1)) err, COUNT (*) cn, util_pg.get_saldo (ln_group, ld_date, ld_date + 1) sm
     INTO ln_fact, ln_limit, ln_sm
     FROM (SELECT   mid, COUNT (DISTINCT util_pg.trunchh24_2 (date_time - 1 / 86400)) cn
               FROM halfhour
              WHERE date_time > ld_date AND date_time <= ld_date + 1
           GROUP BY mid) h,
          points p
    WHERE p.mid IN (SELECT     mid
                          FROM GROUPS
                         WHERE mid IS NOT NULL
                    CONNECT BY PRIOR gid = PARENT
                    START WITH gid = ln_group) AND p.mid = h.mid(+);

   IF ln_fact <> 0 THEN
    INSERT INTO check_resultsg
                (ddate, gid, nprocedure, vparam, nmustbe, nindeed
                )
         VALUES (ld_date + 1, ln_group, cn_checkcomplete, ln_sm, ln_limit, ln_fact
                );

    ln_count := ln_count + 1;
   END IF;

   lt_sms (ln_i + 1) := 'G.' || ln_group || ': ' || ln_fact || '/' || ln_limit || ';E=' || ROUND (ln_sm / 1000, 3);
   lv_add := lv_add || ' E.' || ln_group || '=' || ROUND (ln_sm / 1000, 3) || ';';
  END LOOP;

  IF ln_count > 0 THEN
   lt_sms (1) := 'CHECKCOMPLETE WARNING';

   IF ln_count = 1 THEN
    lv_ret := 'одной контрольной группе.';
   ELSE
    lv_ret := ln_count || ' контрольным группам.';
   END IF;

   UPDATE check_status
      SET   --одна прцедура одна строка на первичный ключ не смотри
         ddate = ld_date + 1,
         vtext = 'Контроль полноты: данные не полны по ' || lv_ret
    WHERE nprocedure = cn_checkcomplete;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_checkcomplete, ld_date + 1, 'Контроль полноты: данные не полны по ' || lv_ret
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, cn_checkcomplete, 1, TO_CHAR (ld_date + 1, 'dd.mm.yyyy') || ' данные не полны по ' || lv_ret || lv_add, cn_checksystem);
  ELSE
   lt_sms (1) := 'CHECKCOMPLETE OK';

   DELETE FROM check_status
         WHERE nprocedure = cn_checkcomplete;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_checkcomplete, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' cостояние: Норма', cn_checksystem);
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;

  IF lt_sms.COUNT > 0 AND ln_i > 0 THEN
   file_pg.adminevents_p (lt_sms, ld_date);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.checkcomplete: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE report_by_fact (an_maket NUMBER, ad_date DATE) IS   --SAA с 26/06/2009 не поддерживаем из-за _dclosed_
  ln_limit   NUMBER;
  lv_str     VARCHAR2 (50);
  ln_sgn     NUMBER        DEFAULT 1;
  ln_cnt     NUMBER        DEFAULT 0;
 BEGIN
  ln_limit := TO_NUMBER (file_pg.gv_param) / 100;

  IF ln_limit < 0 THEN
   ln_limit := -ln_limit;
   ln_sgn := -1;
  END IF;

  DELETE FROM check_results
        WHERE nprocedure = cn_report_by_fact AND ddate = ad_date;

  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT   ad_date, a.mid, cn_report_by_fact, ln_limit * 100, ABS (SUM (b.er) - SUM (b.ed)), ABS (SUM (a.er) - SUM (a.ed))
       FROM halfhour a, halfhour b
      WHERE b.mid = a.mid AND b.date_time = a.date_time AND a.date_time > ad_date AND a.date_time <= ad_date + 1   /*AND a.dclosed IS NOT NULL*/
   GROUP BY a.mid
     HAVING ln_sgn * ABS (ABS (SUM (b.er) - SUM (b.ed)) - ABS (SUM (a.er) - SUM (a.ed))) > ln_limit * ABS (SUM (b.er) - SUM (b.ed));

  ln_cnt := SQL%ROWCOUNT;

  IF SQL%ROWCOUNT = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_report_by_fact;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_report_by_fact, 0, TO_CHAR (ad_date, 'dd.mm.yy') || ' норма при допустимом отклонении ' || ln_limit * 100 || '%',
                            cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_report_by_fact;

   IF ln_cnt = 1 THEN
    lv_str := 'одной позиции.';
   ELSE
    lv_str := ln_cnt || ' позициям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_report_by_fact, ad_date, 'Сверка отчетных данных по факту: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_report_by_fact, 1,
                            TO_CHAR (ad_date, 'dd.mm.yy') || ' превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str, cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка отчетных данных по факту: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
      WHERE nprocedure = cn_report_by_fact AND ddate = ad_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;

