 PROCEDURE by_itekcoeff (an_maket NUMBER, ad_date DATE) IS
  ln_limit   NUMBER;
  str        VARCHAR2 (50);
  ln_cnt     NUMBER;
  ln_sgn     NUMBER        DEFAULT 1;
 BEGIN
  ln_limit := TO_NUMBER (file_pg.gv_param) / 100;

  IF ln_limit < 0 THEN
   ln_limit := -ln_limit;
   ln_sgn := -1;
  END IF;

  DELETE FROM check_results
        WHERE nprocedure = cn_itekcoeff AND ddate = ad_date;

  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ad_date, i.mid, cn_itekcoeff, ln_limit * 100, ker, f.kc / DECODE (mconst, 0, 0.000001, mconst)
     FROM itekcoeff i, feeders f, meters m
    WHERE f.mid = i.mid AND m.mid = i.mid AND m.entype IN (1, 7) AND i.ker IS NOT NULL
          AND (NVL (i.ker, 1) = 0 OR NVL (m.mconst, 1) = 0 OR ln_sgn * ABS (i.ker - f.kc / DECODE (m.mconst, 0, 1, m.mconst)) / DECODE (i.ker, 0, 1, i.ker) >
                                                                                                                                                             ln_limit);

  ln_cnt := SQL%ROWCOUNT;

  IF ln_cnt = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_itekcoeff;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_itekcoeff, 0, 'Норма при допустимом отклонении ' || ln_limit * 100 || '%', cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_itekcoeff;

   IF ln_cnt = 1 THEN
    str := 'одной позиции.';
   ELSE
    str := ln_cnt || ' позициям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_itekcoeff, ad_date, 'Сверка параметров УСД Итек: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_itekcoeff, 1, 'Превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || str, cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка параметров УСД Итек: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || str
      WHERE nprocedure = cn_itekcoeff AND ddate = ad_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;

