 PROCEDURE by_month_expense (an_maket NUMBER, ad_date DATE) IS
  ln_limit   NUMBER;
  ld_date    DATE;
  ln_count   NUMBER;
  ln_sgn     NUMBER         DEFAULT 1;
  lv_str     VARCHAR2 (128);
 BEGIN
  ld_date := TRUNC (ad_date, 'mm');
  ln_limit := TO_NUMBER (file_pg.gv_param) / 100;

  IF ln_limit < 0 THEN
   ln_limit := -ln_limit;
   ln_sgn := -1;
  END IF;

  DELETE FROM check_results
        WHERE nprocedure = cn_month_expense AND ddate = ld_date;

  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ld_date, a.mid, cn_month_expense, ln_limit * 100, a.val, b.val
     FROM (SELECT   mid, ABS (SUM (NVL (er, 0)) - SUM (NVL (ed, 0))) val
               FROM monthsorg
              WHERE mid IN (SELECT mid
                              FROM points
                             WHERE ptype = 1) AND date_time = ADD_MONTHS (ld_date, 1)
           GROUP BY mid) a,
          (SELECT   mid, ABS (SUM (NVL (er, 0)) - SUM (NVL (ed, 0))) val
               FROM halfhour
              WHERE mid IN (SELECT mid
                              FROM points
                             WHERE ptype = 1) AND date_time > ld_date AND date_time <= ADD_MONTHS (ld_date, 1) AND NOT (nsource BETWEEN 30 AND 49)
           GROUP BY mid) b
    WHERE a.mid = b.mid AND ln_sgn * ABS (a.val - b.val) > ln_limit * a.val;

  ln_count := SQL%ROWCOUNT;

  IF ln_count = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_month_expense;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_month_expense, 0, TO_CHAR (ld_date, 'mm.yyyy') || ' норма при допустимом отклонении ' || ln_limit * 100 || '%',
                            cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_month_expense;

   IF ln_count = 1 THEN
    lv_str := 'одной позиции.';
   ELSE
    lv_str := ln_count || ' позициям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_month_expense, ld_date, 'Сверка месячных расходов: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_month_expense, 1, TO_CHAR (ld_date, 'mm.yyyy') || ' превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str,
                            cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка месячных расходов: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
      WHERE nprocedure = cn_month_expense AND ddate = ld_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;

