 PROCEDURE by_ov (an_maket NUMBER, ad_date DATE) IS
  lv_str     VARCHAR2 (50);
  how_many   NUMBER        DEFAULT 0;
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_ov AND ddate = ad_date;

  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT   ad_date, b.nswitch, cn_ov, 0, 0, COUNT (*)
       FROM halfhour b, halfhour a
      WHERE b.mid IN (SELECT mid
                        FROM switches
                       WHERE dswitch < ad_date + 1 AND NVL (descape, ad_date) + 1 > ad_date) AND b.date_time > ad_date AND b.date_time <= ad_date + 1
            AND b.nsource >= 30 AND b.nsource < 50 AND b.mid = a.mid AND b.date_time = a.date_time AND a.nsource >= 10 AND a.nsource < 30
            AND NVL (a.er, 0) - NVL (a.ed, 0) <> 0
   GROUP BY b.nswitch;

  how_many := SQL%ROWCOUNT;

  IF how_many = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_ov;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_ov, 0, TO_CHAR (ad_date, 'dd.mm.yy') || ' норма ', cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_ov;

   IF how_many = 1 THEN
    lv_str := 'одному переключению.';
   ELSE
    lv_str := how_many || ' переключениям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_ov, ad_date, 'Сверка ОВ: не нулевой расход точки учета по ' || lv_str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_ov, 1, TO_CHAR (ad_date, 'dd.mm.yy') || ' не нулевой расход точки учета по ' || lv_str, cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка ОВ: не нулевой расход точки учета по ' || lv_str
      WHERE nprocedure = cn_ov AND ddate = ad_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;
------------------------------------------------------------------------------------------------------------------------
 -- added by KAG 09.03.2011
 -- проверяем наличие ввода переключения в АСКУЭ при реальном переключении ОВ
 PROCEDURE checkSwitchOV (an_maket NUMBER, ad_date DATE) IS
  lv_str        VARCHAR2 (50);
  how_many      NUMBER        DEFAULT 0;
  ld_date       DATE          DEFAULT trunc(ad_date);
  ln_notswOV    NUMBER        DEFAULT 0;
  lv_switches   VARCHAR2 (500);
 BEGIN
  -- ходим по всем переключателям
  FOR lc IN (SELECT mid ovmid FROM feeders WHERE nswitch = 1 AND nmainpoint IS NULL) LOOP
    SELECT count(*) INTO how_many
      FROM switches
     WHERE nswitch = lc.ovmid AND dswitch < ld_date AND NVL(descape,ld_date+1) >= ld_date+1;
     
    IF how_many = 0 THEN -- если ОВ сейчас не переключен
      SELECT count(*) 
        INTO how_many
        FROM halfhour
       WHERE mid=lc.ovmid AND date_time>ld_date AND date_time <=ld_date+1
             AND (util_pg.sumn(er,ed)<>0 OR util_pg.sumn(q1,q3)<>0 OR util_pg.sumn(q2,q4)<>0);
      IF how_many > 0 THEN -- если есть данные по ОВ
          FOR lc1 IN (SELECT ov.mid midOV, p.mid,
                             util_pg.sumn(ov.er,-1*p.er) erDif, util_pg.sumn(ov.ed,-1*p.ed) edDif, 
                             util_pg.sumn(ov.q1,-1*p.q1) q1Dif, util_pg.sumn(ov.q2,-1*p.q2) q2Dif, 
                             util_pg.sumn(ov.q3,-1*p.q3) q3Dif, util_pg.sumn(ov.q4,-1*p.q4) q4Dif                         
                        FROM halfhour ov, halfhour p
                       WHERE ov.mid = lc.ovmid AND ov.date_time > ld_date AND ov.date_time <= ld_date+1
                             AND ov.nsource >= 10 AND ov.nsource < 30
                             AND ov.mid=p.nswitch(+) AND ov.date_time=p.date_time(+) AND p.nsource(+) >= 30 AND p.nsource(+) < 50 
                      ORDER BY ov.date_time) LOOP
            IF lc1.mid IS NULL OR NVL(lc1.erDif,0)<>0 OR NVL(lc1.edDif,0)<>0 OR 
               NVL(lc1.q1Dif,0)<>0 OR NVL(lc1.q2Dif,0)<>0 OR NVL(lc1.q3Dif,0)<>0 OR NVL(lc1.q4Dif,0)<>0 THEN
                ln_notswOV := ln_notswOV + 1;           
                lv_switches := lv_switches || ' ' || lc.ovmid;
              EXIT;
            END IF;                   
          END LOOP;      
      END IF;
    END IF;    
  END LOOP;
  
  IF ln_notswOV<>0 THEN
   IF ln_notswOV = 1 THEN
    lv_str := 'одному переключению: ';
   ELSE
    lv_str := ln_notswOV || ' переключениям: ';
   END IF;

   UPDATE check_status
      SET   
         ddate = ld_date,
         vtext = SUBSTR ('Сверка ОВ: не введено переключение по ' || lv_str || ' ИД точек:'||lv_switches, 1, cn_pointname)
    WHERE nprocedure = cn_checkSwitchOV;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_checkSwitchOV, ld_date, SUBSTR ('Сверка ОВ: не введено переключение по ' || lv_str || ' ИД точек:'||lv_switches, 1, cn_pointname)
                );
   END IF;

   admin_pg.ins_journal_p (SYSDATE, an_maket, 1, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' не введено переключение по ОВ ' || ' ИД точек:'||lv_switches);

  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_checkSwitchOV;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, an_maket, 0, TO_CHAR (ld_date, 'dd.mm.yyyy') || ' состояние: Норма');
   END IF;
  END IF;

  admin_pg.signal (6);
  COMMIT;
  
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'check_pg.checkSwitchOV: ' || CHR (10) || SQLERRM (SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_duplicatechannel (an_maket NUMBER, ad_date DATE) IS
  ln_limit   NUMBER;
  ln_cnt     NUMBER         DEFAULT 0;
  ln_tmp     NUMBER         DEFAULT 0;
  lv_str     VARCHAR2 (128);
 BEGIN
  ln_limit := ABS (TO_NUMBER (file_pg.gv_param) / 100);

  DELETE FROM check_results
        WHERE nprocedure = cn_duplicatechannel AND ddate = ad_date;

  FOR lc IN (SELECT f.mid
               FROM feeders f, points p
              WHERE f.ncalcpointtype IS NULL AND f.mid = p.mid AND p.ind = 4 AND EXISTS (SELECT *
                                                                                           FROM points pp
                                                                                          WHERE pp.PARENT = p.mid AND pp.ind IN (3, 4))) LOOP
   INSERT INTO check_results
               (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
    SELECT ad_date, lc.mid, cn_duplicatechannel, ln_limit * 100, MAX (ABS (t.er - t.ed)) maxe, MIN (ABS (t.er - t.ed)) mine
      FROM (SELECT   h.mid, NVL (SUM (h.er), 0) er, NVL (SUM (h.ed), 0) ed
                FROM points p, halfhour h
               WHERE p.PARENT = lc.mid AND p.ind = 3 AND p.mid = h.mid AND h.date_time > ad_date AND h.date_time <= ad_date + 1
            GROUP BY h.mid) t
    HAVING MAX (ABS (t.er - t.ed)) - MIN (ABS (t.er - t.ed)) > ln_limit * MAX (ABS (t.er - t.ed));

   ln_cnt := ln_cnt + SQL%ROWCOUNT;
  END LOOP;

  IF ln_cnt = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_duplicatechannel;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_duplicatechannel, 0, TO_CHAR (ad_date, 'dd.mm.yy') || ' норма при допустимом отклонении ' || ln_limit * 100 || '%',
                            cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_duplicatechannel;

   IF ln_cnt = 1 THEN
    lv_str := 'одной позиции.';
   ELSE
    lv_str := ln_cnt || ' позициям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_duplicatechannel, ad_date, 'Сверка по дублям: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_duplicatechannel, 1,
                            TO_CHAR (ad_date, 'dd.mm.yy') || ' превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str, cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка по дублям: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
      WHERE nprocedure = cn_duplicatechannel AND ddate = ad_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_mtrsn (an_maket NUMBER, ad_date DATE) IS
  str        VARCHAR2 (50);
  how_many   NUMBER        DEFAULT 0;
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_mtrsn AND ddate = ad_date;

  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ad_date, f.mid, cn_mtrsn, 0, m.mtrsn, f.canal
     FROM points p, feeders f, meters m
    WHERE p.ptype = 1 AND p.mid = f.mid AND p.mid = m.mid AND m.entype = 1 AND f.canal > 50000000
                                                                                                 -- AND TO_CHAR (f.canal) <> NVL (m.mtrsn, '-') AND m.mtrsn <> 'ПРЕКРАЩЕНИЕ';
          AND f.canal <> util_pg.allnumber_f (m.mtrsn);

  how_many := SQL%ROWCOUNT;

  IF SQL%ROWCOUNT = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_mtrsn;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_mtrsn, 0, 'Устранены несовпадения заводских и связных номеров.', cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_mtrsn;

   IF how_many = 1 THEN
    str := 'одной позиции.';
   ELSE
    str := how_many || ' позициям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_mtrsn, ad_date, 'Сверка связных номеров: нет совпадения с з-д номерами по ' || str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_mtrsn, 1, ' Нет совпадения с з-д номерами по ' || str, cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка связных номеров: нет совпадения с з-д номерами по ' || str
      WHERE nprocedure = cn_mtrsn AND ddate = ad_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_day_expense (an_maket NUMBER, ad_date DATE) IS
  ln_limit   NUMBER;
  lv_str     VARCHAR2 (50);
  ln_sgn     NUMBER        DEFAULT 1;
  ln_cnt     NUMBER        DEFAULT 0;
 BEGIN
  ln_limit := TO_NUMBER (file_pg.gv_param) / 100;

  IF ln_limit < 0 THEN
   ln_limit := -ln_limit;
   ln_sgn := -1;
  END IF;

  DELETE FROM check_results
        WHERE nprocedure = cn_day_expense AND ddate = ad_date;

  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ad_date, b.mid, cn_day_expense, ln_limit * 100, ABS (NVL (o.er, 0) - NVL (o.ed, 0)), ABS (NVL (b.er, 0) - NVL (b.ed, 0))
     FROM itekcoeff i, bill b, billorg o
    WHERE i.mid = b.mid AND i.mid = o.mid AND b.date_time = ad_date + 1 AND o.date_time = ad_date + 1
          AND ln_sgn * ABS (ABS (NVL (b.er, 0) - NVL (b.ed, 0)) - ABS (NVL (o.er, 0) - NVL (o.ed, 0))) > ln_limit * ABS (NVL (o.er, 0) - NVL (o.ed, 0));

  ln_cnt := SQL%ROWCOUNT;

  IF SQL%ROWCOUNT = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_day_expense;

   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.ins_journal_p (SYSDATE, cn_day_expense, 0, TO_CHAR (ad_date, 'dd.mm.yy') || ' норма при допустимом отклонении ' || ln_limit * 100 || '%',
                            cn_checksystem);
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_day_expense;

   IF ln_cnt = 1 THEN
    lv_str := 'одной позиции.';
   ELSE
    lv_str := ln_cnt || ' позициям.';
   END IF;

   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext
                )
         VALUES (cn_day_expense, ad_date, 'Сверка суточных расходов: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
                );

    admin_pg.ins_journal_p (SYSDATE, cn_day_expense, 1, TO_CHAR (ad_date, 'dd.mm.yy') || ' превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str,
                            cn_checksystem);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка суточных расходов: превышено допустимое отклонение ' || ln_limit * 100 || '% по ' || lv_str
      WHERE nprocedure = cn_day_expense AND ddate = ad_date;
   END;
  END IF;

  admin_pg.signal (6);
  COMMIT;
 END;

