  SELECT DECODE (MAX (r.nacc), 1, 1, 0)
    INTO ln_ret
    FROM users u, role_task r
   WHERE u.user_id = NVL (an_user, gn_userid) AND u.role_id = r.role_id AND r.task_id = 97;

