---------------------------------------------------------------------
 PROCEDURE initmenuaccess (an_par1 NUMBER, an_par2 OUT NUMBER, an_par3 OUT NUMBER, an_par4 OUT NUMBER,
  an_par5 OUT NUMBER, an_par6 OUT NUMBER) IS
 -- используется в TSupperMainForm::initMenuAccess
 -- added 06.08.2008 Kondakov A.G.
 BEGIN
 an_par3:=0;
 an_par4:=0;
 an_par5:=0;
an_par6:=0;
 
  SELECT COUNT (*)
    INTO an_par2
    FROM role_task rt, tasks t
   WHERE rt.role_id = an_par1 AND rt.nacc = 1 AND task_cod = 606 AND rt.task_id = t.task_id;

  SELECT NVL (MAX (rt.nacc + 1), 0)
    INTO an_par3
    FROM role_task rt, tasks t
   WHERE rt.role_id = an_par1 AND t.task_cod = 630 AND rt.task_id = t.task_id;

  SELECT NVL (MAX (rt.nacc + 1), 0)
    INTO an_par4
    FROM role_task rt, tasks t
   WHERE rt.role_id = an_par1 AND t.task_cod = 631 AND rt.task_id = t.task_id;

  SELECT NVL (MAX (rt.nacc + 1), 0)
    INTO an_par5
    FROM role_task rt, tasks t
   WHERE rt.role_id = an_par1 AND t.task_cod = 632 AND rt.task_id = t.task_id;
     
  SELECT NVL (MAX (rt.nacc + 1), 0)
    INTO an_par6
   FROM role_task rt, tasks t
  WHERE rt.role_id = an_par1 AND t.task_cod = 663 AND rt.task_id = t.task_id;
  -- an_par6:=1;
 /*606 - код задачи "План выполнения фоновых процессов"
   630 - "Терминал показаний"
   631 - "Терминал опроса"
   632 - "Монитор полноты и своевременности поступления данных"
   -"Обновить БД Качества ЭЭ"*/
 END;

