 -- используется в TSupperMainForm::FormCreate
---VNB 23.09.2008
 BEGIN
  OPEN acur_t FOR
   SELECT   nid nmid, vname,nshift, DECODE(dsummer,NULL,0,1) dsummer
       FROM timezones
   ORDER BY nshift, nid;
 END;
