------------------------------------------------------------------------------------------------------------------------
--Проседура приведения формата углов счетчика к абсолютным углам
/*
an_typeconvert - 1  преобразуем sl-7000
an_typeconvert - 2  преобразуем ARGO
an_typeconvert - 3  Не преобразуем
an_typeconvert - 4  преобразуем ZxD СЭС
Иначе не преобразуем
*/
 PROCEDURE convert_corners(
 an_typeconvert NUMBER, an_mid NUMBER, an_u1 IN OUT NUMBER, an_u2 IN OUT NUMBER, an_u3 IN OUT NUMBER, an_i1 IN OUT NUMBER, an_i2 IN OUT NUMBER,
 an_i3 IN OUT NUMBER
 ) IS
  ln_u1               NUMBER := an_u1;
  ln_u2               NUMBER := an_u2;
  ln_u3               NUMBER := an_u3;
  ln_i1               NUMBER := an_i1;
  ln_i2               NUMBER := an_i2;
  ln_i3               NUMBER := an_i3;
  ln_typeconvert      NUMBER := NVL(util_pg.getcornersparam(an_mid), an_typeconvert);
 BEGIN
  IF ln_typeconvert = 1 THEN                                                                                                                 -- Schlum (SL7000)
   /* - an_fiu1 - угол между U2 и U1, а надо U1
      - an_fiu2 - угол между U3 и U1, а надо U2
      - an_fiu3 - угол между U2 и U3, а надо U3
      - an_fii1 - угол между I1 и U1, а надо I1
      - an_fii2 - угол между I2 и U2, а надо I2
      - an_fii3 - угол между I3 и U3, а надо I3    */
   an_u1 := 0;
   an_u2 := ln_u1;
   an_u3 := ln_u1 + ln_u3;
   an_i1 := an_u1 + ln_i1;
   an_i2 := an_u2 + ln_i2;
   an_i3 := an_u3 + ln_i3;
  ELSIF ln_typeconvert = 2 THEN                                                                                                                          -- ARGO
   /* - an_fiu1 - NULL (подразумевается   0), а надо U1 (  0)
      - an_fiu2 - NULL (подразумевается 120), а надо U2 (120)
      - an_fiu3 - NULL (подразумевается 240), а надо U3 (240)
      - an_fii1 - угол между I1 и U1, а надо I1
      - an_fii2 - угол между I2 и U2, а надо I2
      - an_fii3 - угол между I3 и U3, а надо I3    */
   an_u1 := 0;
   an_u2 := 120;
   an_u3 := 240;
   an_i1 := ln_u1 + ln_i1;
   an_i2 := ln_u2 + ln_i2;
   an_i3 := ln_u3 + ln_i3;
  ELSIF ln_typeconvert = 4 THEN                                                                                                                     -- ZxD с СЭС
   /* - an_fii1 - угол между I1 и U1, а надо I1
      - an_fii2 - угол между I2 и U2, а надо I2
      - an_fii3 - угол между I3 и U3, а надо I3    */
   an_i1 := ln_u1 + ln_i1;
   an_i2 := ln_u2 + ln_i2;
   an_i3 := ln_u3 + ln_i3;
  ELSE
   IF an_u1 IS NOT NULL THEN
    an_u1 := 0;
   END IF;
  END IF;

  --Убираем обороты
  an_u1 := MOD(an_u1, 360);
  an_u2 := MOD(an_u2, 360);
  an_u3 := MOD(an_u3, 360);
  an_i1 := MOD(an_i1, 360);
  an_i2 := MOD(an_i2, 360);
  an_i3 := MOD(an_i3, 360);

  --Делаем все от [0:360]
  IF an_u1 < 0 THEN
   an_u1 := 360 + an_u1;
  END IF;

  IF an_u2 < 0 THEN
   an_u2 := 360 + an_u2;
  END IF;

  IF an_u3 < 0 THEN
   an_u3 := 360 + an_u3;
  END IF;

  IF an_i1 < 0 THEN
   an_i1 := 360 + an_i1;
  END IF;

  IF an_i2 < 0 THEN
   an_i2 := 360 + an_i2;
  END IF;

  IF an_i3 < 0 THEN
   an_i3 := 360 + an_i3;
  END IF;
 END;

