 PROCEDURE get_wstimeinfo(an_mid NUMBER, an_timezonew OUT NUMBER, an_timezones OUT NUMBER) IS
 BEGIN
  SELECT NVL(MAX(ntimezonew), util_pg.cn_tzw), NVL(MAX(ntimezones), util_pg.cn_tzs)
  INTO   an_timezonew, an_timezones
  FROM   feeders
  WHERE  mid = an_mid;
 END;

