 PROCEDURE set_traffic(an_cid NUMBER, ad_open DATE, ad_start DATE, ad_end DATE, an_send NUMBER, an_recv NUMBER, av_user VARCHAR2) IS
  lv_initstr          VARCHAR2(256);
  lv_user             VARCHAR2(256);
 BEGIN
  IF util_pg.locksysjournal_f = 1 THEN
   RETURN;
  END IF;

  SELECT MAX(com_id || ':' || init_str), NVL(TRIM(MAX(vuser)), 'RYDA')
  INTO   lv_initstr, lv_user
  FROM   channels
  WHERE  cid = an_cid;

  UPDATE traffic
  SET dstart = ad_start,
      dend = ad_end,
      nsend = an_send,
      nreceived = an_recv,
      vuser = lv_user,
      vinitstr = lv_initstr
  WHERE  cid = an_cid AND dopen = ad_open;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO traffic
               (cid, dopen, dstart, dend, nsend, nreceived, vuser, vinitstr)
   VALUES      (an_cid, ad_open, ad_start, ad_end, an_send, an_recv, lv_user, lv_initstr);
  END IF;
 END;

