--Вставка текущих
 PROCEDURE set_curr_power_meter(an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, ad_date DATE) IS
  ln_rn               NUMBER DEFAULT 5;
  ln_kc               NUMBER;
  ln_erm              NUMBER DEFAULT an_erm;
  ln_edm              NUMBER DEFAULT an_edm;
  ln_q1m              NUMBER DEFAULT an_q1m;
  ln_q3m              NUMBER DEFAULT an_q3m;
  ln_q2m              NUMBER DEFAULT an_q2m;
  ln_q4m              NUMBER DEFAULT an_q4m;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q3               NUMBER;
  ln_q2               NUMBER;
  ln_q4               NUMBER;
  ln_oerm             NUMBER;
  ln_oedm             NUMBER;
  ln_oq1m             NUMBER;
  ln_oq3m             NUMBER;
  ln_oq2m             NUMBER;
  ln_oq4m             NUMBER;
  ln_k                NUMBER;
  ld_date             DATE DEFAULT SYSDATE;
 --ld_date             DATE := util_pg.convertmeterdate_f(an_mid, SYSDATE);
 BEGIN
  util_pg.chdr(an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);

  SELECT 24 * MAX(ld_date - date_time) dt, NVL(MAX(erm), 0), NVL(MAX(edm), 0), NVL(MAX(q1m), 0), NVL(MAX(q3m), 0), NVL(MAX(q2m), 0), NVL(MAX(q4m), 0)
  INTO   ln_k, ln_oerm, ln_oedm, ln_oq1m, ln_oq3m, ln_oq2m, ln_oq4m
  FROM   curr_power
  WHERE  mid = an_mid;

  IF util_pg.get_typecalcpower(an_mid) = 1 AND ln_k > 0 THEN
   SELECT NVL(MAX(kc), 1)
   INTO   ln_kc
   FROM   feeders
   WHERE  mid = an_mid;

   ln_er := ROUND(ln_kc * util_pg.indicoverturn(ln_erm - ln_oerm, NULL) / ln_k, ln_rn);
   ln_ed := ROUND(ln_kc * util_pg.indicoverturn(ln_edm - ln_oedm, NULL) / ln_k, ln_rn);
   ln_q1 := ROUND(ln_kc * util_pg.indicoverturn(ln_q1m - ln_oq1m, NULL) / ln_k, ln_rn);
   ln_q3 := ROUND(ln_kc * util_pg.indicoverturn(ln_q3m - ln_oq3m, NULL) / ln_k, ln_rn);
   ln_q2 := ROUND(ln_kc * util_pg.indicoverturn(ln_q2m - ln_oq2m, NULL) / ln_k, ln_rn);
   ln_q4 := ROUND(ln_kc * util_pg.indicoverturn(ln_q4m - ln_oq4m, NULL) / ln_k, ln_rn);
  END IF;

  UPDATE curr_power
  SET erm = ln_erm,
      edm = ln_edm,
      q1m = ln_q1m,
      q3m = ln_q3m,
      q2m = ln_q2m,
      q4m = ln_q4m,
      er = ln_er,
      ed = ln_ed,
      q1 = ln_q1,
      q3 = ln_q3,
      q2 = ln_q2,
      q4 = ln_q4,
      cosf = NULL,
      volt = NULL,
      volt2 = NULL,
      volt3 = NULL,
      currento = NULL,
      curr2 = NULL,
      curr3 = NULL,
      nfiu1 = NULL,
      nfiu2 = NULL,
      nfiu3 = NULL,
      nfii1 = NULL,
      nfii2 = NULL,
      nfii3 = NULL,
      ni0 = NULL,
      obsolete = 0,
      date_time = ld_date
  WHERE  mid = an_mid;

  das_pg.insert_cp_in_profile(an_mid);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_curr_power_meter: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Вставка текущих (+ ток в нуле + статус +температура)
 PROCEDURE set_curr_power_meter(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_freq NUMBER, an_cos_fi NUMBER, an_volt1 NUMBER,
 an_volt2 NUMBER, an_volt3 NUMBER, an_curr1 NUMBER, an_curr2 NUMBER, an_curr3 NUMBER, an_fii1 NUMBER, an_fii2 NUMBER, an_fii3 NUMBER, an_fiu1 NUMBER,
 an_fiu2 NUMBER, an_fiu3 NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_i0 NUMBER, an_type NUMBER,
 an_status NUMBER, an_temp NUMBER,an_off NUMBER,ad_off DATE,
 ad_date DATE
 ) IS
  cn_MINFLOAT constant NUMBER :=-9999;
  ln_erm              NUMBER DEFAULT an_erm;
  ln_edm              NUMBER DEFAULT an_edm;
  ln_q1m              NUMBER DEFAULT an_q1m;
  ln_q3m              NUMBER DEFAULT an_q3m;
  ln_q2m              NUMBER DEFAULT an_q2m;
  ln_q4m              NUMBER DEFAULT an_q4m;
  ln_er               NUMBER DEFAULT an_er;
  ln_ed               NUMBER DEFAULT an_ed;
  ln_q1               NUMBER DEFAULT an_q1;
  ln_q3               NUMBER DEFAULT an_q3;
  ln_q2               NUMBER DEFAULT an_q2;
  ln_q4               NUMBER DEFAULT an_q4;
  ln_fii1             NUMBER DEFAULT an_fii1;
  ln_fii2             NUMBER DEFAULT an_fii2;
  ln_fii3             NUMBER DEFAULT an_fii3;
  ln_fiu1             NUMBER DEFAULT an_fiu1;
  ln_fiu2             NUMBER DEFAULT an_fiu2;
  ln_fiu3             NUMBER DEFAULT an_fiu3;
  ln_kc               NUMBER;
  ld_date             DATE := util_pg.convertmeterdate_e_f(an_mid, ad_date);
 BEGIN
  convert_corners(an_type, an_mid, ln_fiu1, ln_fiu2, ln_fiu3, ln_fii1, ln_fii2, ln_fii3);
  util_pg.chdr(an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
  util_pg.chdr(an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4);

  SELECT NVL(MAX(kc), 1)
  INTO   ln_kc
  FROM   feeders
  WHERE  mid = an_mid;

  ln_er := ln_er * ln_kc;
  ln_ed := ln_ed * ln_kc;
  ln_q1 := ln_q1 * ln_kc;
  ln_q3 := ln_q3 * ln_kc;
  ln_q2 := ln_q2 * ln_kc;
  ln_q4 := ln_q4 * ln_kc;

  UPDATE curr_power
  SET erm = ln_erm,
      edm = ln_edm,
      q1m = ln_q1m,
      q3m = ln_q3m,
      q2m = ln_q2m,
      q4m = ln_q4m,
      obsolete = 0,
      date_time = ld_date,
      freq = an_freq,
      cosf = an_cos_fi,
      volt = an_volt1,
      volt2 = an_volt2,
      volt3 = an_volt3,
      currento = an_curr1,
      curr2 = an_curr2,
      curr3 = an_curr3,
      er = ln_er,
      ed = ln_ed,
      q1 = ln_q1,
      q3 = ln_q3,
      q2 = ln_q2,
      q4 = ln_q4,
      nfiu1 = ln_fiu1,
      nfiu2 = ln_fiu2,
      nfiu3 = ln_fiu3,
      nfii1 = ln_fii1,
      nfii2 = ln_fii2,
      nfii3 = ln_fii3,
      ni0 = an_i0,
      nstatus = an_status,
      ntemp = an_temp,
      noff = decode(nvl(sign(an_off-nvl(noff,cn_MINFLOAT)),0),0,noff,an_off),
      doff = decode(nvl(sign(an_off-nvl(noff,cn_MINFLOAT)),0),0,doff,nvl(ad_off,ld_date))
  WHERE  mid = an_mid;

  das_pg.insert_cp_in_profile(an_mid);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_curr_power_meter: ' || SQLERRM(SQLCODE));
 END;

