--Вставка текущих (+ ток в нуле )
 PROCEDURE set_curr_power_meter(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_freq NUMBER, an_cos_fi NUMBER, an_volt1 NUMBER,
 an_volt2 NUMBER, an_volt3 NUMBER, an_curr1 NUMBER, an_curr2 NUMBER, an_curr3 NUMBER, an_fii1 NUMBER, an_fii2 NUMBER, an_fii3 NUMBER, an_fiu1 NUMBER,
 an_fiu2 NUMBER, an_fiu3 NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_i0 NUMBER, an_type NUMBER, ad_date DATE
 ) is
 BEGIN
  set_curr_power_meter(an_mid, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_freq, an_cos_fi, an_volt1, an_volt2, an_volt3, an_curr1, an_curr2, an_curr3,
   an_fii1, an_fii2, an_fii3, an_fiu1, an_fiu2, an_fiu3, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, an_i0, an_type,NULL,NULL,NULL,NULL, ad_date);
 END;
