 PROCEDURE set_curr_quality_meter(
 an_mid NUMBER, ad_start DATE, an_sequence NUMBER, av_phase VARCHAR2, an_beventtype NUMBER, an_mcstimestart NUMBER, ad_end DATE, an_mcstimeend NUMBER,
 an_reference NUMBER, an_beventseq NUMBER, an_magnitude NUMBER, av_pu VARCHAR2, av_duration VARCHAR2, av_event VARCHAR2, av_category VARCHAR2
 ) IS
 BEGIN
  UPDATE pqlog
  SET nbeventtype = an_beventtype,
      nmcstimestart = an_mcstimestart,
      dend = ad_end,
      nmcstimeend = an_mcstimeend,
      nreference = an_reference,
      nbeventseq = an_beventseq,
      nmagnitude = an_magnitude,
      vpu = av_pu,
      vduration = av_duration,
      vevent = av_event,
      vcategory = av_category
  WHERE  mid = an_mid AND dstart = ad_start AND nsequence = an_sequence AND vphase = av_phase;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO pqlog
               (mid, dstart, nsequence, vphase, nbeventtype, nmcstimestart, dend, nmcstimeend, nreference, nbeventseq, nmagnitude, vpu, vduration, vevent,
                vcategory)
   VALUES      (an_mid, ad_start, an_sequence, NVL(av_phase, ' '), an_beventtype, an_mcstimestart, ad_end, an_mcstimeend, an_reference, an_beventseq,
                an_magnitude, av_pu, av_duration, av_event, av_category);
  END IF;
 END;

