--Вставка суточных
 PROCEDURE set_bill_meter(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_aerm NUMBER, an_aedm NUMBER, an_aq1m NUMBER,
 an_aq3m NUMBER, an_aq2m NUMBER, an_aq4m NUMBER, an_berm NUMBER, an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_bq2m NUMBER, an_bq4m NUMBER, an_cerm NUMBER,
 an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER, an_cq2m NUMBER, an_cq4m NUMBER, an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER, an_dq3m NUMBER, an_dq2m NUMBER,
 an_dq4m NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER, ad_date DATE, an_metertype NUMBER
 ) IS
  ld_date             DATE := util_pg.convertmeterdate_e_f(an_mid, ad_date);
  ln_digits           NUMBER;                                                                                                                   -- :=an_digits;

  CURSOR lcur_sel IS
   SELECT NVL(erm, 0) erm, NVL(edm, 0) edm, NVL(q1m, 0) q1m, NVL(q3m, 0) q3m, NVL(q2m, 0) q2m, NVL(q4m, 0) q4m, NVL(aerm, 0) aerm, NVL(aedm, 0) aedm,
          NVL(aq1m, 0) aq1m, NVL(aq3m, 0) aq3m, NVL(aq2m, 0) aq2m, NVL(aq4m, 0) aq4m, NVL(berm, 0) berm, NVL(bedm, 0) bedm, NVL(bq1m, 0) bq1m,
          NVL(bq3m, 0) bq3m, NVL(bq2m, 0) bq2m, NVL(bq4m, 0) bq4m, NVL(cerm, 0) cerm, NVL(cedm, 0) cedm, NVL(cq1m, 0) cq1m, NVL(cq3m, 0) cq3m,
          NVL(cq2m, 0) cq2m, NVL(cq4m, 0) cq4m, NVL(derm, 0) derm, NVL(dedm, 0) dedm, NVL(dq1m, 0) dq1m, NVL(dq3m, 0) dq3m, NVL(dq2m, 0) dq2m,
          NVL(dq4m, 0) dq4m, NVL(er_mtrsn, ' ')
   FROM   billorg
   WHERE  mid = an_mid
          AND date_time = (SELECT MAX(date_time)
                           FROM   billorg
                           WHERE  mid = an_mid AND date_time < ld_date --AND LPAD(UPPER(TRIM(er_mtrsn)), 20, '0') = LPAD(UPPER(TRIM(av_mtrsn)), 20, '0')
																											)
          AND LPAD(UPPER(TRIM(nvl(er_mtrsn,'0'))), 20, '0') = LPAD(UPPER(TRIM(nvl(av_mtrsn,'0'))), 20, '0');

  lc                  lcur_sel%ROWTYPE;
  lb_found            BOOLEAN;
  ln_kc               NUMBER;
  ln_rn               NUMBER DEFAULT 10;
  lv_source           VARCHAR2(32) DEFAULT 'КС';
  ln_erm              NUMBER DEFAULT ROUND(an_erm, cn_roundall);
  ln_edm              NUMBER DEFAULT ROUND(an_edm, cn_roundall);
  ln_q1m              NUMBER DEFAULT ROUND(an_q1m, cn_roundall);
  ln_q3m              NUMBER DEFAULT ROUND(an_q3m, cn_roundall);
  ln_q2m              NUMBER DEFAULT ROUND(an_q2m, cn_roundall);
  ln_q4m              NUMBER DEFAULT ROUND(an_q4m, cn_roundall);
  ln_aerm             NUMBER DEFAULT ROUND(an_aerm, cn_roundall);
  ln_aedm             NUMBER DEFAULT ROUND(an_aedm, cn_roundall);
  ln_aq1m             NUMBER DEFAULT ROUND(an_aq1m, cn_roundall);
  ln_aq3m             NUMBER DEFAULT ROUND(an_aq3m, cn_roundall);
  ln_aq2m             NUMBER DEFAULT ROUND(an_aq2m, cn_roundall);
  ln_aq4m             NUMBER DEFAULT ROUND(an_aq4m, cn_roundall);
  ln_berm             NUMBER DEFAULT ROUND(an_berm, cn_roundall);
  ln_bedm             NUMBER DEFAULT ROUND(an_bedm, cn_roundall);
  ln_bq1m             NUMBER DEFAULT ROUND(an_bq1m, cn_roundall);
  ln_bq3m             NUMBER DEFAULT ROUND(an_bq3m, cn_roundall);
  ln_bq2m             NUMBER DEFAULT ROUND(an_bq2m, cn_roundall);
  ln_bq4m             NUMBER DEFAULT ROUND(an_bq4m, cn_roundall);
  ln_cerm             NUMBER DEFAULT ROUND(an_cerm, cn_roundall);
  ln_cedm             NUMBER DEFAULT ROUND(an_cedm, cn_roundall);
  ln_cq1m             NUMBER DEFAULT ROUND(an_cq1m, cn_roundall);
  ln_cq3m             NUMBER DEFAULT ROUND(an_cq3m, cn_roundall);
  ln_cq2m             NUMBER DEFAULT ROUND(an_cq2m, cn_roundall);
  ln_cq4m             NUMBER DEFAULT ROUND(an_cq4m, cn_roundall);
  ln_derm             NUMBER DEFAULT ROUND(an_derm, cn_roundall);
  ln_dedm             NUMBER DEFAULT ROUND(an_dedm, cn_roundall);
  ln_dq1m             NUMBER DEFAULT ROUND(an_dq1m, cn_roundall);
  ln_dq3m             NUMBER DEFAULT ROUND(an_dq3m, cn_roundall);
  ln_dq2m             NUMBER DEFAULT ROUND(an_dq2m, cn_roundall);
  ln_dq4m             NUMBER DEFAULT ROUND(an_dq4m, cn_roundall);
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q3               NUMBER;
  ln_q2               NUMBER;
  ln_q4               NUMBER;
  ln_aer              NUMBER;
  ln_aed              NUMBER;
  ln_aq1              NUMBER;
  ln_aq3              NUMBER;
  ln_aq2              NUMBER;
  ln_aq4              NUMBER;
  ln_ber              NUMBER;
  ln_bed              NUMBER;
  ln_bq1              NUMBER;
  ln_bq3              NUMBER;
  ln_bq2              NUMBER;
  ln_bq4              NUMBER;
  ln_cer              NUMBER;
  ln_ced              NUMBER;
  ln_cq1              NUMBER;
  ln_cq3              NUMBER;
  ln_cq2              NUMBER;
  ln_cq4              NUMBER;
  ln_der              NUMBER;
  ln_ded              NUMBER;
  ln_dq1              NUMBER;
  ln_dq3              NUMBER;
  ln_dq2              NUMBER;
  ln_dq4              NUMBER;
 BEGIN
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  lc;

  lb_found := lcur_sel%FOUND;

  CLOSE lcur_sel;

  util_pg.chdr(an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
  util_pg.chdr(an_mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m);
  util_pg.chdr(an_mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m);
  util_pg.chdr(an_mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m);
  util_pg.chdr(an_mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m);

  SELECT NVL(MAX(kc), 1)
  INTO   ln_kc
  FROM   feeders
  WHERE  mid = an_mid;

  IF lb_found THEN
   ln_er := ROUND(util_pg.indicoverturn(ln_erm - lc.erm, ln_digits) * ln_kc, ln_rn);
   ln_ed := ROUND(util_pg.indicoverturn(ln_edm - lc.edm, ln_digits) * ln_kc, ln_rn);
   ln_q1 := ROUND(util_pg.indicoverturn(ln_q1m - lc.q1m, ln_digits) * ln_kc, ln_rn);
   ln_q3 := ROUND(util_pg.indicoverturn(ln_q3m - lc.q3m, ln_digits) * ln_kc, ln_rn);
   ln_q2 := ROUND(util_pg.indicoverturn(ln_q2m - lc.q2m, ln_digits) * ln_kc, ln_rn);
   ln_q4 := ROUND(util_pg.indicoverturn(ln_q4m - lc.q4m, ln_digits) * ln_kc, ln_rn);
   ln_aer := ROUND(util_pg.indicoverturn(ln_aerm - lc.aerm, ln_digits) * ln_kc, ln_rn);
   ln_aed := ROUND(util_pg.indicoverturn(ln_aedm - lc.aedm, ln_digits) * ln_kc, ln_rn);
   ln_aq1 := ROUND(util_pg.indicoverturn(ln_aq1m - lc.aq1m, ln_digits) * ln_kc, ln_rn);
   ln_aq3 := ROUND(util_pg.indicoverturn(ln_aq3m - lc.aq3m, ln_digits) * ln_kc, ln_rn);
   ln_aq2 := ROUND(util_pg.indicoverturn(ln_aq2m - lc.aq2m, ln_digits) * ln_kc, ln_rn);
   ln_aq4 := ROUND(util_pg.indicoverturn(ln_aq4m - lc.aq4m, ln_digits) * ln_kc, ln_rn);
   ln_ber := ROUND(util_pg.indicoverturn(ln_berm - lc.berm, ln_digits) * ln_kc, ln_rn);
   ln_bed := ROUND(util_pg.indicoverturn(ln_bedm - lc.bedm, ln_digits) * ln_kc, ln_rn);
   ln_bq1 := ROUND(util_pg.indicoverturn(ln_bq1m - lc.bq1m, ln_digits) * ln_kc, ln_rn);
   ln_bq3 := ROUND(util_pg.indicoverturn(ln_bq3m - lc.bq3m, ln_digits) * ln_kc, ln_rn);
   ln_bq2 := ROUND(util_pg.indicoverturn(ln_bq2m - lc.bq2m, ln_digits) * ln_kc, ln_rn);
   ln_bq4 := ROUND(util_pg.indicoverturn(ln_bq4m - lc.bq4m, ln_digits) * ln_kc, ln_rn);
   ln_cer := ROUND(util_pg.indicoverturn(ln_cerm - lc.cerm, ln_digits) * ln_kc, ln_rn);
   ln_ced := ROUND(util_pg.indicoverturn(ln_cedm - lc.cedm, ln_digits) * ln_kc, ln_rn);
   ln_cq1 := ROUND(util_pg.indicoverturn(ln_cq1m - lc.cq1m, ln_digits) * ln_kc, ln_rn);
   ln_cq3 := ROUND(util_pg.indicoverturn(ln_cq3m - lc.cq3m, ln_digits) * ln_kc, ln_rn);
   ln_cq2 := ROUND(util_pg.indicoverturn(ln_cq2m - lc.cq2m, ln_digits) * ln_kc, ln_rn);
   ln_cq4 := ROUND(util_pg.indicoverturn(ln_cq4m - lc.cq4m, ln_digits) * ln_kc, ln_rn);
   ln_der := ROUND(util_pg.indicoverturn(ln_derm - lc.derm, ln_digits) * ln_kc, ln_rn);
   ln_ded := ROUND(util_pg.indicoverturn(ln_dedm - lc.dedm, ln_digits) * ln_kc, ln_rn);
   ln_dq1 := ROUND(util_pg.indicoverturn(ln_dq1m - lc.dq1m, ln_digits) * ln_kc, ln_rn);
   ln_dq3 := ROUND(util_pg.indicoverturn(ln_dq3m - lc.dq3m, ln_digits) * ln_kc, ln_rn);
   ln_dq2 := ROUND(util_pg.indicoverturn(ln_dq2m - lc.dq2m, ln_digits) * ln_kc, ln_rn);
   ln_dq4 := ROUND(util_pg.indicoverturn(ln_dq4m - lc.dq4m, ln_digits) * ln_kc, ln_rn);
  END IF;

  BEGIN
   INSERT INTO billorg
               (mid, er, ed, q1, q3, q2, q4, aer, aed, aq1, aq3, aq2, aq4, ber, bed, bq1, bq3, bq2, bq4, cer, ced, cq1, cq3, cq2, cq4, der, ded, dq1, dq3, dq2,
                dq4, erm, edm, q1m, q3m, q2m, q4m, aerm, aedm, aq1m, aq3m, aq2m, aq4m, berm, bedm, bq1m, bq3m, bq2m, bq4m, cerm, cedm, cq1m, cq3m, cq2m, cq4m,
                derm, dedm, dq1m, dq3m, dq2m, dq4m, er_mtrsn, ed_mtrsn, q1_mtrsn, q3_mtrsn, q2_mtrsn, q4_mtrsn, date_time, SOURCE, nsource, er_kc, ed_kc,
                q1_kc, q3_kc, q2_kc, q4_kc)
   VALUES      (an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4, ln_aer, ln_aed, ln_aq1, ln_aq3, ln_aq2, ln_aq4, ln_ber, ln_bed, ln_bq1, ln_bq3, ln_bq2,
                ln_bq4, ln_cer, ln_ced, ln_cq1, ln_cq3, ln_cq2, ln_cq4, ln_der, ln_ded, ln_dq1, ln_dq3, ln_dq2, ln_dq4, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m,
                ln_q4m, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m, ln_cerm, ln_cedm, ln_cq1m,
                ln_cq3m, ln_cq2m, ln_cq4m, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn,
                ld_date, lv_source, cn_auto, ln_kc, ln_kc, ln_kc, ln_kc, ln_kc, ln_kc);
  EXCEPTION
   WHEN DUP_VAL_ON_INDEX THEN
    UPDATE billorg
    SET er_mtrsn = av_mtrsn,
        er_kc = ln_kc,
        erm = ln_erm,
        er = ln_er,
        aerm = ln_aerm,
        aer = ln_aer,
        berm = ln_berm,
        ber = ln_ber,
        cerm = ln_cerm,
        cer = ln_cer,
        derm = ln_derm,
        der = ln_der,
        q1_mtrsn = av_mtrsn,
        q1_kc = ln_kc,
        q1m = ln_q1m,
        q1 = ln_q1,
        aq1m = ln_aq1m,
        aq1 = ln_aq1,
        bq1m = ln_bq1m,
        bq1 = ln_bq1,
        cq1m = ln_cq1m,
        cq1 = ln_cq1,
        dq1m = ln_dq1m,
        dq1 = ln_dq1,
        ed_mtrsn = av_mtrsn,
        ed_kc = ln_kc,
        edm = ln_edm,
        ed = ln_ed,
        aedm = ln_aedm,
        aed = ln_aed,
        bedm = ln_bedm,
        bed = ln_bed,
        cedm = ln_cedm,
        ced = ln_ced,
        dedm = ln_dedm,
        ded = ln_ded,
        q3_mtrsn = av_mtrsn,
        q3_kc = ln_kc,
        q3m = ln_q3m,
        q3 = ln_q3,
        aq3m = ln_aq3m,
        aq3 = ln_aq3,
        bq3m = ln_bq3m,
        bq3 = ln_bq3,
        cq3m = ln_cq3m,
        cq3 = ln_cq3,
        dq3m = ln_dq3m,
        dq3 = ln_dq3,
        q2_mtrsn = av_mtrsn,
        q2_kc = ln_kc,
        q2m = ln_q2m,
        q2 = ln_q2,
        aq2m = ln_aq2m,
        aq2 = ln_aq2,
        bq2m = ln_bq2m,
        bq2 = ln_bq2,
        cq2m = ln_cq2m,
        cq2 = ln_cq2,
        dq2m = ln_dq2m,
        dq2 = ln_dq2,
        q4_mtrsn = av_mtrsn,
        q4_kc = ln_kc,
        q4m = ln_q4m,
        q4 = ln_q4,
        aq4m = ln_aq4m,
        aq4 = ln_aq4,
        bq4m = ln_bq4m,
        bq4 = ln_bq4,
        cq4m = ln_cq4m,
        cq4 = ln_cq4,
        dq4m = ln_dq4m,
        dq4 = ln_dq4,
        SOURCE = lv_source
    WHERE  mid = an_mid AND date_time = ld_date AND nsource = cn_auto;
   WHEN OTHERS THEN
    RAISE;
  END;

  IF an_metertype IN(cn_nikkc02 /*,cn_induc_mtx*/) or (an_metertype = cn_matrix and is_only_day_data(an_mid)=1)
     AND(ln_er IS NOT NULL OR ln_ed IS NOT NULL OR ln_q1 IS NOT NULL OR ln_q3 IS NOT NULL OR ln_q2 IS NOT NULL OR ln_q4 IS NOT NULL) THEN
   set_halfhour_meter(an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4, NULL, an_metertype, NULL, util_pg.to_unlocaltime(ld_date), NULL);
   IF an_metertype = cn_matrix THEN
	   comsrvcim_pg.upd_lastsavehalfhour(an_mid, TO_CHAR(util_pg.to_unlocaltime(ld_date), 'dd.mm.yyyy hh24:mi'));
   END IF;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_bill_meter: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Вставка месячных
 PROCEDURE set_months_meter(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_aerm NUMBER, an_aedm NUMBER, an_aq1m NUMBER,
 an_aq3m NUMBER, an_aq2m NUMBER, an_aq4m NUMBER, an_berm NUMBER, an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_bq2m NUMBER, an_bq4m NUMBER, an_cerm NUMBER,
 an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER, an_cq2m NUMBER, an_cq4m NUMBER, an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER, an_dq3m NUMBER, an_dq2m NUMBER,
 an_dq4m NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER,
                                                     --Значность счетчика, необходимо передать 6 - A1R_ParamCalc.DPLocE
                                                     ad_date DATE
 ) IS
  ld_date             DATE := util_pg.convertmeterdate_e_f(an_mid, ad_date);
  ln_digits           NUMBER;                                                                                                                   -- :=an_digits;

  CURSOR lcur_sel IS
   SELECT NVL(erm, 0) erm, NVL(edm, 0) edm, NVL(q1m, 0) q1m, NVL(q3m, 0) q3m, NVL(q2m, 0) q2m, NVL(q4m, 0) q4m, NVL(aerm, 0) aerm, NVL(aedm, 0) aedm,
          NVL(aq1m, 0) aq1m, NVL(aq3m, 0) aq3m, NVL(aq2m, 0) aq2m, NVL(aq4m, 0) aq4m, NVL(berm, 0) berm, NVL(bedm, 0) bedm, NVL(bq1m, 0) bq1m,
          NVL(bq3m, 0) bq3m, NVL(bq2m, 0) bq2m, NVL(bq4m, 0) bq4m, NVL(cerm, 0) cerm, NVL(cedm, 0) cedm, NVL(cq1m, 0) cq1m, NVL(cq3m, 0) cq3m,
          NVL(cq2m, 0) cq2m, NVL(cq4m, 0) cq4m, NVL(derm, 0) derm, NVL(dedm, 0) dedm, NVL(dq1m, 0) dq1m, NVL(dq3m, 0) dq3m, NVL(dq2m, 0) dq2m,
          NVL(dq4m, 0) dq4m, NVL(er_mtrsn, ' ')
   FROM   monthsorg
   WHERE  mid = an_mid
          AND date_time = (SELECT MAX(date_time)
                           FROM   monthsorg
                           WHERE  mid = an_mid AND date_time < ld_date) --AND LPAD(UPPER(TRIM(er_mtrsn)), 20, '0') = LPAD(UPPER(TRIM(av_mtrsn)), 20, '0'))
          AND LPAD(UPPER(TRIM(nvl(er_mtrsn,'0'))), 20, '0') = LPAD(UPPER(TRIM(nvl(av_mtrsn,'0'))), 20, '0');

  lc                  lcur_sel%ROWTYPE;
  lb_found            BOOLEAN;
  ln_kc               NUMBER;
  ln_rn               NUMBER DEFAULT 10;
  lv_source           VARCHAR2(32) DEFAULT 'КС';
  ln_erm              NUMBER DEFAULT ROUND(an_erm, cn_roundall);
  ln_edm              NUMBER DEFAULT ROUND(an_edm, cn_roundall);
  ln_q1m              NUMBER DEFAULT ROUND(an_q1m, cn_roundall);
  ln_q3m              NUMBER DEFAULT ROUND(an_q3m, cn_roundall);
  ln_q2m              NUMBER DEFAULT ROUND(an_q2m, cn_roundall);
  ln_q4m              NUMBER DEFAULT ROUND(an_q4m, cn_roundall);
  ln_aerm             NUMBER DEFAULT ROUND(an_aerm, cn_roundall);
  ln_aedm             NUMBER DEFAULT ROUND(an_aedm, cn_roundall);
  ln_aq1m             NUMBER DEFAULT ROUND(an_aq1m, cn_roundall);
  ln_aq3m             NUMBER DEFAULT ROUND(an_aq3m, cn_roundall);
  ln_aq2m             NUMBER DEFAULT ROUND(an_aq2m, cn_roundall);
  ln_aq4m             NUMBER DEFAULT ROUND(an_aq4m, cn_roundall);
  ln_berm             NUMBER DEFAULT ROUND(an_berm, cn_roundall);
  ln_bedm             NUMBER DEFAULT ROUND(an_bedm, cn_roundall);
  ln_bq1m             NUMBER DEFAULT ROUND(an_bq1m, cn_roundall);
  ln_bq3m             NUMBER DEFAULT ROUND(an_bq3m, cn_roundall);
  ln_bq2m             NUMBER DEFAULT ROUND(an_bq2m, cn_roundall);
  ln_bq4m             NUMBER DEFAULT ROUND(an_bq4m, cn_roundall);
  ln_cerm             NUMBER DEFAULT ROUND(an_cerm, cn_roundall);
  ln_cedm             NUMBER DEFAULT ROUND(an_cedm, cn_roundall);
  ln_cq1m             NUMBER DEFAULT ROUND(an_cq1m, cn_roundall);
  ln_cq3m             NUMBER DEFAULT ROUND(an_cq3m, cn_roundall);
  ln_cq2m             NUMBER DEFAULT ROUND(an_cq2m, cn_roundall);
  ln_cq4m             NUMBER DEFAULT ROUND(an_cq4m, cn_roundall);
  ln_derm             NUMBER DEFAULT ROUND(an_derm, cn_roundall);
  ln_dedm             NUMBER DEFAULT ROUND(an_dedm, cn_roundall);
  ln_dq1m             NUMBER DEFAULT ROUND(an_dq1m, cn_roundall);
  ln_dq3m             NUMBER DEFAULT ROUND(an_dq3m, cn_roundall);
  ln_dq2m             NUMBER DEFAULT ROUND(an_dq2m, cn_roundall);
  ln_dq4m             NUMBER DEFAULT ROUND(an_dq4m, cn_roundall);
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q3               NUMBER;
  ln_q2               NUMBER;
  ln_q4               NUMBER;
  ln_aer              NUMBER;
  ln_aed              NUMBER;
  ln_aq1              NUMBER;
  ln_aq3              NUMBER;
  ln_aq2              NUMBER;
  ln_aq4              NUMBER;
  ln_ber              NUMBER;
  ln_bed              NUMBER;
  ln_bq1              NUMBER;
  ln_bq3              NUMBER;
  ln_bq2              NUMBER;
  ln_bq4              NUMBER;
  ln_cer              NUMBER;
  ln_ced              NUMBER;
  ln_cq1              NUMBER;
  ln_cq3              NUMBER;
  ln_cq2              NUMBER;
  ln_cq4              NUMBER;
  ln_der              NUMBER;
  ln_ded              NUMBER;
  ln_dq1              NUMBER;
  ln_dq3              NUMBER;
  ln_dq2              NUMBER;
  ln_dq4              NUMBER;
 BEGIN
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  lc;

  lb_found := lcur_sel%FOUND;

  CLOSE lcur_sel;

  util_pg.chdr(an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
  util_pg.chdr(an_mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m);
  util_pg.chdr(an_mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m);
  util_pg.chdr(an_mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m);
  util_pg.chdr(an_mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m);

  SELECT NVL(MAX(kc), 1)
  INTO   ln_kc
  FROM   feeders
  WHERE  mid = an_mid;

  IF lb_found THEN
   ln_er := ROUND(util_pg.indicoverturn(ln_erm - lc.erm, ln_digits) * ln_kc, ln_rn);
   ln_ed := ROUND(util_pg.indicoverturn(ln_edm - lc.edm, ln_digits) * ln_kc, ln_rn);
   ln_q1 := ROUND(util_pg.indicoverturn(ln_q1m - lc.q1m, ln_digits) * ln_kc, ln_rn);
   ln_q3 := ROUND(util_pg.indicoverturn(ln_q3m - lc.q3m, ln_digits) * ln_kc, ln_rn);
   ln_q2 := ROUND(util_pg.indicoverturn(ln_q2m - lc.q2m, ln_digits) * ln_kc, ln_rn);
   ln_q4 := ROUND(util_pg.indicoverturn(ln_q4m - lc.q4m, ln_digits) * ln_kc, ln_rn);
   ln_aer := ROUND(util_pg.indicoverturn(ln_aerm - lc.aerm, ln_digits) * ln_kc, ln_rn);
   ln_aed := ROUND(util_pg.indicoverturn(ln_aedm - lc.aedm, ln_digits) * ln_kc, ln_rn);
   ln_aq1 := ROUND(util_pg.indicoverturn(ln_aq1m - lc.aq1m, ln_digits) * ln_kc, ln_rn);
   ln_aq3 := ROUND(util_pg.indicoverturn(ln_aq3m - lc.aq3m, ln_digits) * ln_kc, ln_rn);
   ln_aq2 := ROUND(util_pg.indicoverturn(ln_aq2m - lc.aq2m, ln_digits) * ln_kc, ln_rn);
   ln_aq4 := ROUND(util_pg.indicoverturn(ln_aq4m - lc.aq4m, ln_digits) * ln_kc, ln_rn);
   ln_ber := ROUND(util_pg.indicoverturn(ln_berm - lc.berm, ln_digits) * ln_kc, ln_rn);
   ln_bed := ROUND(util_pg.indicoverturn(ln_bedm - lc.bedm, ln_digits) * ln_kc, ln_rn);
   ln_bq1 := ROUND(util_pg.indicoverturn(ln_bq1m - lc.bq1m, ln_digits) * ln_kc, ln_rn);
   ln_bq3 := ROUND(util_pg.indicoverturn(ln_bq3m - lc.bq3m, ln_digits) * ln_kc, ln_rn);
   ln_bq2 := ROUND(util_pg.indicoverturn(ln_bq2m - lc.bq2m, ln_digits) * ln_kc, ln_rn);
   ln_bq4 := ROUND(util_pg.indicoverturn(ln_bq4m - lc.bq4m, ln_digits) * ln_kc, ln_rn);
   ln_cer := ROUND(util_pg.indicoverturn(ln_cerm - lc.cerm, ln_digits) * ln_kc, ln_rn);
   ln_ced := ROUND(util_pg.indicoverturn(ln_cedm - lc.cedm, ln_digits) * ln_kc, ln_rn);
   ln_cq1 := ROUND(util_pg.indicoverturn(ln_cq1m - lc.cq1m, ln_digits) * ln_kc, ln_rn);
   ln_cq3 := ROUND(util_pg.indicoverturn(ln_cq3m - lc.cq3m, ln_digits) * ln_kc, ln_rn);
   ln_cq2 := ROUND(util_pg.indicoverturn(ln_cq2m - lc.cq2m, ln_digits) * ln_kc, ln_rn);
   ln_cq4 := ROUND(util_pg.indicoverturn(ln_cq4m - lc.cq4m, ln_digits) * ln_kc, ln_rn);
   ln_der := ROUND(util_pg.indicoverturn(ln_derm - lc.derm, ln_digits) * ln_kc, ln_rn);
   ln_ded := ROUND(util_pg.indicoverturn(ln_dedm - lc.dedm, ln_digits) * ln_kc, ln_rn);
   ln_dq1 := ROUND(util_pg.indicoverturn(ln_dq1m - lc.dq1m, ln_digits) * ln_kc, ln_rn);
   ln_dq3 := ROUND(util_pg.indicoverturn(ln_dq3m - lc.dq3m, ln_digits) * ln_kc, ln_rn);
   ln_dq2 := ROUND(util_pg.indicoverturn(ln_dq2m - lc.dq2m, ln_digits) * ln_kc, ln_rn);
   ln_dq4 := ROUND(util_pg.indicoverturn(ln_dq4m - lc.dq4m, ln_digits) * ln_kc, ln_rn);
  END IF;

  INSERT INTO monthsorg
              (mid, er, ed, q1, q3, q2, q4, aer, aed, aq1, aq3, aq2, aq4, ber, bed, bq1, bq3, bq2, bq4, cer, ced, cq1, cq3, cq2, cq4, der, ded, dq1, dq3, dq2,
               dq4, erm, edm, q1m, q3m, q2m, q4m, aerm, aedm, aq1m, aq3m, aq2m, aq4m, berm, bedm, bq1m, bq3m, bq2m, bq4m, cerm, cedm, cq1m, cq3m, cq2m, cq4m,
               derm, dedm, dq1m, dq3m, dq2m, dq4m, er_mtrsn, ed_mtrsn, q1_mtrsn, q3_mtrsn, q2_mtrsn, q4_mtrsn, date_time, SOURCE, nsource, er_kc, ed_kc, q1_kc,
               q3_kc, q2_kc, q4_kc)
  VALUES      (an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4, ln_aer, ln_aed, ln_aq1, ln_aq3, ln_aq2, ln_aq4, ln_ber, ln_bed, ln_bq1, ln_bq3, ln_bq2, ln_bq4,
               ln_cer, ln_ced, ln_cq1, ln_cq3, ln_cq2, ln_cq4, ln_der, ln_ded, ln_dq1, ln_dq3, ln_dq2, ln_dq4, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m,
               ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m,
               ln_cq2m, ln_cq4m, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, ld_date,
               lv_source, cn_auto, ln_kc, ln_kc, ln_kc, ln_kc, ln_kc, ln_kc);
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   UPDATE monthsorg
   SET er_mtrsn = av_mtrsn,
       er_kc = ln_kc,
       erm = ln_erm,
       er = ln_er,
       aerm = ln_aerm,
       aer = ln_aer,
       berm = ln_berm,
       ber = ln_ber,
       cerm = ln_cerm,
       cer = ln_cer,
       derm = ln_derm,
       der = ln_der,
       q1_mtrsn = av_mtrsn,
       q1_kc = ln_kc,
       q1m = ln_q1m,
       q1 = ln_q1,
       aq1m = ln_aq1m,
       aq1 = ln_aq1,
       bq1m = ln_bq1m,
       bq1 = ln_bq1,
       cq1m = ln_cq1m,
       cq1 = ln_cq1,
       dq1m = ln_dq1m,
       dq1 = ln_dq1,
       ed_mtrsn = av_mtrsn,
       ed_kc = ln_kc,
       edm = ln_edm,
       ed = ln_ed,
       aedm = ln_aedm,
       aed = ln_aed,
       bedm = ln_bedm,
       bed = ln_bed,
       cedm = ln_cedm,
       ced = ln_ced,
       dedm = ln_dedm,
       ded = ln_ded,
       q3_mtrsn = av_mtrsn,
       q3_kc = ln_kc,
       q3m = ln_q3m,
       q3 = ln_q3,
       aq3m = ln_aq3m,
       aq3 = ln_aq3,
       bq3m = ln_bq3m,
       bq3 = ln_bq3,
       cq3m = ln_cq3m,
       cq3 = ln_cq3,
       dq3m = ln_dq3m,
       dq3 = ln_dq3,
       q2_mtrsn = av_mtrsn,
       q2_kc = ln_kc,
       q2m = ln_q2m,
       q2 = ln_q2,
       aq2m = ln_aq2m,
       aq2 = ln_aq2,
       bq2m = ln_bq2m,
       bq2 = ln_bq2,
       cq2m = ln_cq2m,
       cq2 = ln_cq2,
       dq2m = ln_dq2m,
       dq2 = ln_dq2,
       q4_mtrsn = av_mtrsn,
       q4_kc = ln_kc,
       q4m = ln_q4m,
       q4 = ln_q4,
       aq4m = ln_aq4m,
       aq4 = ln_aq4,
       bq4m = ln_bq4m,
       bq4 = ln_bq4,
       cq4m = ln_cq4m,
       cq4 = ln_cq4,
       dq4m = ln_dq4m,
       dq4 = ln_dq4,
       SOURCE = lv_source
   WHERE  mid = an_mid AND date_time = ld_date AND nsource = cn_auto;
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_months_meter: ' || SQLERRM(SQLCODE));
 END;

