--Вставка суточных
 PROCEDURE set_bill_uspd(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_aerm NUMBER, an_aedm NUMBER, an_aq1m NUMBER,
 an_aq3m NUMBER, an_aq2m NUMBER, an_aq4m NUMBER, an_berm NUMBER, an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_bq2m NUMBER, an_bq4m NUMBER, an_cerm NUMBER,
 an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER, an_cq2m NUMBER, an_cq4m NUMBER, an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER, an_dq3m NUMBER, an_dq2m NUMBER,
 an_dq4m NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER,
                                                                                                              --Значность счетчика, необходимо передать соответствующую АРГО
                                                     --( для A1R было 6 - A1R_ParamCalc.DPLocE )
                                                     ad_date DATE
 ) IS
 BEGIN
  set_bill_meter(an_mid, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_aerm, an_aedm, an_aq1m, an_aq3m, an_aq2m, an_aq4m, an_berm, an_bedm, an_bq1m,
   an_bq3m, an_bq2m, an_bq4m, an_cerm, an_cedm, an_cq1m, an_cq3m, an_cq2m, an_cq4m, an_derm, an_dedm, an_dq1m, an_dq3m, an_dq2m, an_dq4m, av_mtrsn, an_digits,
   ad_date);
 END;

------------------------------------------------------------------------------------------------------------------------
--Вставка месячных
 PROCEDURE set_months_uspd(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_aerm NUMBER, an_aedm NUMBER, an_aq1m NUMBER,
 an_aq3m NUMBER, an_aq2m NUMBER, an_aq4m NUMBER, an_berm NUMBER, an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_bq2m NUMBER, an_bq4m NUMBER, an_cerm NUMBER,
 an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER, an_cq2m NUMBER, an_cq4m NUMBER, an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER, an_dq3m NUMBER, an_dq2m NUMBER,
 an_dq4m NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER,
                                                                                                              --Значность счетчика, необходимо передать соответствующую АРГО
                                                     --( для A1R 6 - A1R_ParamCalc.DPLocE )
                                                     ad_date DATE
 ) IS
 BEGIN
  set_months_meter(an_mid, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_aerm, an_aedm, an_aq1m, an_aq3m, an_aq2m, an_aq4m, an_berm, an_bedm, an_bq1m,
   an_bq3m, an_bq2m, an_bq4m, an_cerm, an_cedm, an_cq1m, an_cq3m, an_cq2m, an_cq4m, an_derm, an_dedm, an_dq1m, an_dq3m, an_dq2m, an_dq4m, av_mtrsn, an_digits,
   ad_date);
 END;

