------------------------------------------------------------------------------------------------------------------------

 --Вставка графика нагрузки
 PROCEDURE set_halfhour_zxb(an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_status NUMBER, ad_date DATE) IS
  lv_mtrsn            VARCHAR2(256);
  ln_paramtype        NUMBER;
 BEGIN
  SELECT DECODE(MAX(vvalue), '1', 1, 0)
  INTO   ln_paramtype
  FROM   addpointparamval
  WHERE  mid = an_mid AND nsort = 72;

  IF ln_paramtype = 1 THEN                                                                                --Параметризация счетчика на автосохранение показаний
   SELECT NVL(MAX(mtrsn), 'LG')
   INTO   lv_mtrsn
   FROM   meters
   WHERE  mid = an_mid AND entype = 7;

   set_halfhour_zxb(an_mid, NULL, NULL, NULL, NULL, an_er, an_ed, an_q1, an_q3, lv_mtrsn, NULL, an_status, ad_date);
  ELSE
   set_halfhour_meter(an_mid, an_er, an_ed, an_q1, an_q3, NULL, NULL, an_status, cn_lg_zxd, NULL, ad_date, NULL);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
--Вставка графика нагрузки (По показаниям)
 PROCEDURE set_halfhour_zxb(
 an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, av_mtrsn VARCHAR2,
 an_digits NUMBER,                                                                                                                          --Значность счетчика
                  an_status NUMBER, ad_date DATE, an_source NUMBER, an_metertype NUMBER
 ) IS
  -- ld_winter   DATE DEFAULT util_pg.to_localtime (ad_date, 1);
  ld_winter           DATE DEFAULT util_pg.to_localtime(util_pg.convertmeterdate_e_f(an_mid, ad_date), 1);
  ln_source           NUMBER DEFAULT cn_auto;
  ln_digits           NUMBER;                                                                                                                   -- :=an_digits;
  ln_switch           NUMBER;

  CURSOR lcur_sel(lc_source NUMBER) IS
   SELECT 0 ts, NVL(erm, 0) erm, NVL(edm, 0) edm, NVL(q1m, 0) q1m, NVL(q3m, 0) q3m
   FROM   halfhourtmp
   WHERE  mid = an_mid AND date_time = (SELECT MAX(date_time) dt
                                        FROM   halfhourtmp
                                        WHERE  mid = an_mid AND date_time < ad_date                                                 /*AND nsource = lc_source*/
                                                                                   )
          AND LPAD(UPPER(TRIM(NVL(er_mtrsn,'0'))), 20, '0') = LPAD(UPPER(TRIM(NVL(av_mtrsn,'0'))), 20, '0')                                           /*AND nsource = lc_source*/
   UNION ALL
   SELECT util_pg.is_timeswitch(date_time) ts, NVL(erm, 0) erm, NVL(edm, 0) edm, NVL(q1m, 0) q1m, NVL(q3m, 0) q3m
   FROM   halfhour
   WHERE  mid = an_mid AND date_time = (SELECT MAX(date_time) dt
                                        FROM   halfhourold
                                        --halfhourold для быстроты и убрали AND lpad(UPPER(TRIM(er_mtrsn)),20,'0') = lpad(UPPER(TRIM(av_mtrsn)),20,'0')
                                        WHERE  mid = an_mid AND date_time < ld_winter
                                                                                     /*AND (nsource = lc_source OR nsource = lc_source + 9)*/
                                      ) AND LPAD(UPPER(TRIM(NVL(er_mtrsn,'0'))), 20, '0') = LPAD(UPPER(TRIM(NVL(av_mtrsn,0))), 20, '0')
                                                                                                                       /*AND (nsource >= lc_source AND nsource <= lc_source + 9)*/
  ;

  CURSOR lcur_sel1(lc_source NUMBER) IS
   SELECT 0 ts, NVL(erm, 0) erm, NVL(edm, 0) edm, NVL(q1m, 0) q1m, NVL(q3m, 0) q3m
   FROM   halfhour
   WHERE  mid = an_mid
          AND util_pg.to_unlocaltime(date_time, nsource) =
              (SELECT MAX(util_pg.to_unlocaltime(date_time, nsource)) dt
               FROM   halfhourold
               --halfhourold для быстроты и убрали AND lpad(UPPER(TRIM(er_mtrsn)),20,'0') = lpad(UPPER(TRIM(av_mtrsn)),20,'0')
               WHERE  mid = an_mid AND date_time < ld_winter + 3 / 24                                  /*AND (nsource = lc_source OR nsource = lc_source + 9)*/
                      AND date_time >= ld_winter - 3 / 24
                                                         /* AND date_time < ld_winter             /*AND (nsource = lc_source OR nsource = lc_source + 9)*/
                                                         /* AND date_time >= ld_winter - 2 / 24*/
                      AND util_pg.to_unlocaltime(date_time, nsource) < ad_date)
          AND LPAD(UPPER(TRIM(NVL(er_mtrsn,'0'))), 20, '0') = LPAD(UPPER(TRIM(NVL(av_mtrsn,'0'))), 20, '0')
                                                                                         /*AND (nsource >= lc_source AND nsource <= lc_source + 9)*/
          AND date_time < ld_winter AND date_time >= ld_winter - 2 / 24;

  lc                  lcur_sel%ROWTYPE;
  lb_found            BOOLEAN;
  ln_kc               NUMBER;
  ln_rn               NUMBER DEFAULT 10;
  ln_erm              NUMBER DEFAULT an_erm;
  ln_edm              NUMBER DEFAULT an_edm;
  ln_q1m              NUMBER DEFAULT an_q1m;
  ln_q3m              NUMBER DEFAULT an_q3m;
  ln_er               NUMBER DEFAULT an_er;
  ln_ed               NUMBER DEFAULT an_ed;
  ln_q1               NUMBER DEFAULT an_q1;
  ln_q3               NUMBER DEFAULT an_q3;
 BEGIN
  IF an_source = util_pg.cn_manualinput THEN
   ln_source := util_pg.cn_manualinput;
  END IF;

  OPEN lcur_sel(ln_source);

  FETCH lcur_sel
  INTO  lc;

  lb_found := lcur_sel%FOUND;

  CLOSE lcur_sel;

  util_pg.chdr(an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m);
  util_pg.chdr(an_mid, ln_er, ln_ed, ln_q1, ln_q3);

  IF lb_found AND lc.ts = -1 THEN
   OPEN lcur_sel1(ln_source);

   FETCH lcur_sel1
   INTO  lc;

   lb_found := lcur_sel1%FOUND;

   CLOSE lcur_sel1;
  END IF;

  IF lb_found THEN
   SELECT NVL(MAX(kc), 1)
   INTO   ln_kc
   FROM   feeders
   WHERE  mid = an_mid;

   ln_er := ROUND(util_pg.indicoverturn(ln_erm - lc.erm, ln_digits) * ln_kc, ln_rn);
   ln_ed := ROUND(util_pg.indicoverturn(ln_edm - lc.edm, ln_digits) * ln_kc, ln_rn);
   ln_q1 := ROUND(util_pg.indicoverturn(ln_q1m - lc.q1m, ln_digits) * ln_kc, ln_rn);
   ln_q3 := ROUND(util_pg.indicoverturn(ln_q3m - lc.q3m, ln_digits) * ln_kc, ln_rn);
  END IF;

  das_pg.ins_halfhourtmp(an_mid, ad_date, an_source, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, ln_erm, ln_edm, ln_q1m, ln_q3m, NULL, NULL, an_status,
   an_metertype, NULL, av_mtrsn);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_halfhour_zxb: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_halfhour_zxb(
 an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_erm NUMBER, an_edm NUMBER, an_rrm NUMBER, an_rdm NUMBER, an_q1m NUMBER,
 an_q2m NUMBER, an_q3m NUMBER, an_q4m NUMBER, an_tlerm NUMBER, an_tledm NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER,
                                                                                                                    --Значность счетчика
                                                                                                                    an_status NUMBER, ad_date DATE
 ) IS
 BEGIN
  set_halfhour_zxb(an_mid, an_er, an_ed, an_q1, an_q3, an_erm, an_edm, an_rrm, an_rdm, av_mtrsn, an_digits, an_status, ad_date);

  IF an_tlerm IS NOT NULL OR an_tledm IS NOT NULL THEN
   FOR lc IN (SELECT mid, DECODE(er_position, 1, an_tlerm, 2, an_tledm) er, DECODE(ed_position, 1, an_tlerm, 2, an_tledm) ed,
                     DECODE(q1_position, 1, an_tlerm, 2, an_tledm) q1, DECODE(q3_position, 1, an_tlerm, 2, an_tledm) q3,
                     DECODE(er_position, 3, an_tlerm, 4, an_tledm) erm, DECODE(ed_position, 3, an_tlerm, 4, an_tledm) edm,
                     DECODE(q1_position, 3, an_tlerm, 4, an_tledm) q1m, DECODE(q3_position, 3, an_tlerm, 4, an_tledm) q3m, NVL(kc, 1) nkc
              FROM   feeders
              WHERE  nusd = an_mid) LOOP
    IF lc.er IS NOT NULL OR lc.ed IS NOT NULL OR lc.q1 IS NOT NULL OR lc.q3 IS NOT NULL OR lc.erm IS NOT NULL OR lc.edm IS NOT NULL OR lc.q1m IS NOT NULL
       OR lc.q3m IS NOT NULL THEN
     set_halfhour_zxb(lc.mid, lc.er * lc.nkc, lc.ed * lc.nkc, lc.q1 * lc.nkc, lc.q3 * lc.nkc, lc.erm, lc.edm, lc.q1m, lc.q3m, av_mtrsn, an_digits, NULL,
      ad_date);
    END IF;
   END LOOP;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
--Вставка графика нагрузки по индукционникам
 PROCEDURE set_halfhour_zxb_induc(an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER, ad_date DATE) IS
 BEGIN
  set_halfhour_zxb(an_mid, NULL, NULL, NULL, NULL, an_erm, an_edm, an_q1m, an_q3m, av_mtrsn, an_digits, NULL, ad_date);
 END;

