 ) IS
  ln_round            NUMBER DEFAULT 5;
 BEGIN
  IF util_pg.get_customer_id = 10 THEN
   SELECT NVL(MAX(3), ln_round)
   INTO   ln_round
   FROM   points
   WHERE  mid = an_mid AND PARENT IN(1737, 1742);
