   ROUND(an_aq4m, ln_round), ROUND(an_berm, ln_round), ROUND(an_bedm, ln_round), ROUND(an_bq1m, ln_round), ROUND(an_bq3m, ln_round), ROUND(an_bq2m, ln_round),
   ROUND(an_bq4m, ln_round), ROUND(an_cerm, ln_round), ROUND(an_cedm, ln_round), ROUND(an_cq1m, ln_round), ROUND(an_cq3m, ln_round), ROUND(an_cq2m, ln_round),
   ROUND(an_cq4m, ln_round), ROUND(an_derm, ln_round), ROUND(an_dedm, ln_round), ROUND(an_dq1m, ln_round), ROUND(an_dq3m, ln_round), ROUND(an_dq2m, ln_round),
   ROUND(an_dq4m, ln_round), av_mtrsn, an_digits, ad_date);
 END;

