-----------------------------------------------------------------------------------------------------------------------
--Вставка параметров сети
 PROCEDURE set_net_param_alpha(
 an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_volt1 NUMBER, an_volt2 NUMBER, an_volt3 NUMBER, an_curr1 NUMBER, an_curr2 NUMBER,
 an_curr3 NUMBER, an_fiu1 NUMBER, an_fiu2 NUMBER, an_fiu3 NUMBER, an_fii1 NUMBER, an_fii2 NUMBER, an_fii3 NUMBER, an_cos_fi NUMBER, ad_date DATE
 ) IS
  ln_er               NUMBER DEFAULT an_er;
  ln_ed               NUMBER DEFAULT an_ed;
  ln_q1               NUMBER DEFAULT an_q1;
  ln_q3               NUMBER DEFAULT an_q3;
  ln_fiu1             NUMBER DEFAULT an_fiu1;
  ln_fiu2             NUMBER DEFAULT an_fiu2;
  ln_fiu3             NUMBER DEFAULT an_fiu3;
  ln_fii1             NUMBER DEFAULT an_fii1;
  ln_fii2             NUMBER DEFAULT an_fii2;
  ln_fii3             NUMBER DEFAULT an_fii3;
 BEGIN
  util_pg.chdr(an_mid, ln_er, ln_ed, ln_q1, ln_q3);
  convert_corners(0, an_mid, ln_fiu1, ln_fiu2, ln_fiu3, ln_fii1, ln_fii2, ln_fii3);

  IF util_pg.get_typecalcpower(an_mid) = 1 THEN
   UPDATE curr_power
   SET cosf = an_cos_fi,
       volt = an_volt1,
       volt2 = an_volt2,
       volt3 = an_volt3,
       currento = an_curr1,
       curr2 = an_curr2,
       curr3 = an_curr3,
       nfiu1 = ln_fiu1,
       nfiu2 = ln_fiu2,
       nfiu3 = ln_fiu3,
       nfii1 = ln_fii1,
       nfii2 = ln_fii2,
       nfii3 = ln_fii3,
       ni0 = NULL
   WHERE  mid = an_mid;
  ELSE
   UPDATE curr_power
   SET er = ln_er,
       ed = ln_ed,
       q1 = ln_q1,
       q3 = ln_q3,
       cosf = an_cos_fi,
       volt = an_volt1,
       volt2 = an_volt2,
       volt3 = an_volt3,
       currento = an_curr1,
       curr2 = an_curr2,
       curr3 = an_curr3,
       nfiu1 = ln_fiu1,
       nfiu2 = ln_fiu2,
       nfiu3 = ln_fiu3,
       nfii1 = ln_fii1,
       nfii2 = ln_fii2,
       nfii3 = ln_fii3,
       ni0 = NULL
   WHERE  mid = an_mid;

   das_pg.insert_cp_in_profile(an_mid);
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_net_param_alpha: ' || SQLERRM(SQLCODE));
 END;

