--Вставка суточных
 PROCEDURE set_bill_alpha(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_rrm NUMBER, an_rdm NUMBER, an_aerm NUMBER, an_aedm NUMBER, an_aq1m NUMBER, an_aq3m NUMBER, an_berm NUMBER,
 an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_cerm NUMBER, an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER, an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER,
 an_dq3m NUMBER, an_q1m NUMBER, an_q2m NUMBER, an_q3m NUMBER, an_q4m NUMBER, av_mtrsn VARCHAR2, an_digits NUMBER,
                                                                                                                 --Значность счетчика, необходимо передать 6 - Alpha_ParamCalc.DPLocE
                                                                                                                 ad_date DATE
 ) IS
  ln_round            NUMBER DEFAULT 5;
 BEGIN
  IF util_pg.get_customer_id = 10 THEN
   SELECT NVL(MAX(3), ln_round)
   INTO   ln_round
   FROM   points
   WHERE  mid = an_mid AND PARENT IN(1737, 1742);
  END IF;

  IF util_pg.is_indicbyq1234(an_mid) = 1 THEN
   set_bill_meter(an_mid, ROUND(an_erm, ln_round), ROUND(an_edm, ln_round), ROUND(an_q1m, ln_round), ROUND(an_q3m, ln_round), ROUND(an_q2m, ln_round),
    ROUND(an_q4m, ln_round), ROUND(an_aerm, ln_round), ROUND(an_aedm, ln_round), ROUND(an_aq1m, ln_round), ROUND(an_aq3m, ln_round), NULL, NULL,
    ROUND(an_berm, ln_round), ROUND(an_bedm, ln_round), ROUND(an_bq1m, ln_round), ROUND(an_bq3m, ln_round), NULL, NULL, ROUND(an_cerm, ln_round),
    ROUND(an_cedm, ln_round), ROUND(an_cq1m, ln_round), ROUND(an_cq3m, ln_round), NULL, NULL, ROUND(an_derm, ln_round), ROUND(an_dedm, ln_round),
    ROUND(an_dq1m, ln_round), ROUND(an_dq3m, ln_round), NULL, NULL, av_mtrsn, an_digits, ad_date);
  ELSE
   set_bill_meter(an_mid, ROUND(an_erm, ln_round), ROUND(an_edm, ln_round), ROUND(an_rrm, ln_round), ROUND(an_rdm, ln_round), NULL, NULL,
    ROUND(an_aerm, ln_round), ROUND(an_aedm, ln_round), ROUND(an_aq1m, ln_round), ROUND(an_aq3m, ln_round), NULL, NULL, ROUND(an_berm, ln_round),
    ROUND(an_bedm, ln_round), ROUND(an_bq1m, ln_round), ROUND(an_bq3m, ln_round), NULL, NULL, ROUND(an_cerm, ln_round), ROUND(an_cedm, ln_round),
    ROUND(an_cq1m, ln_round), ROUND(an_cq3m, ln_round), NULL, NULL, ROUND(an_derm, ln_round), ROUND(an_dedm, ln_round), ROUND(an_dq1m, ln_round),
    ROUND(an_dq3m, ln_round), NULL, NULL, av_mtrsn, an_digits, ad_date);
  END IF;
 END;

