--Вставка текущих
 PROCEDURE set_curr_power_energy(
 an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_freq NUMBER, an_cos_fi NUMBER, an_volt1 NUMBER, an_curr1 NUMBER, an_volt2 NUMBER,
 an_volt3 NUMBER, an_curr2 NUMBER, an_curr3 NUMBER, ad_date DATE
 ) IS
  ln_er               NUMBER DEFAULT an_er;
  ln_ed               NUMBER DEFAULT an_ed;
  ln_q1               NUMBER DEFAULT an_q1;
  ln_q3               NUMBER DEFAULT an_q3;
 BEGIN
  util_pg.chdr(an_mid, ln_er, ln_ed, ln_q1, ln_q3);

  UPDATE curr_power
  SET er = ln_er,
      ed = ln_ed,
      q1 = ln_q1,
      q3 = ln_q3,
      obsolete = 0,
      date_time = ad_date,
      freq = an_freq,
      cosf = an_cos_fi,
      volt = an_volt1,
      volt2 = an_volt2,
      volt3 = an_volt3,
      currento = an_curr1,
      curr2 = an_curr2,
      curr3 = an_curr3,
      ni0 = NULL
  WHERE  mid = an_mid;

  das_pg.insert_cp_in_profile(an_mid);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_curr_power_energy: ' || SQLERRM(SQLCODE));
 END;

