------------------------------------------------------------------------------------------------------------------------
--Вставка событий
 PROCEDURE mark_status_epqs(an_mid NUMBER, at_date_time common_pg.tt_varchar2, at_event_hi common_pg.tt_number, at_event_lo common_pg.tt_number) IS
  ld_sys              DATE := SYSDATE;
  ld_date             DATE;
  ln_ret              NUMBER := 0;
  ln_inserted         NUMBER DEFAULT 0;
  ln_defevent         NUMBER;
  ln_defvalidity      VARCHAR2(256);
 BEGIN
  SELECT MAX(nevent), MAX(NVL(nvalidity, 0))
  INTO   ln_defevent, ln_defvalidity
  FROM   metereventsdict t
  WHERE  nmetertype = cn_epqs AND neventclass = 0 AND nlock = 0;

  FOR i IN REVERSE 1 .. at_date_time.COUNT LOOP
   ld_date := TO_DATE(at_date_time(i), 'dd.mm.yyyy hh24:mi:ss');

   IF ld_date >= ld_sys THEN
    GOTO to_continue;
   END IF;

   IF at_event_lo(i) > 0 THEN
    FOR lc IN (SELECT nevent, NVL(nvalidity, 0) nvalidity
               FROM   metereventsdict t
               WHERE  nmetertype = cn_epqs AND neventclass = 2 AND BITAND(at_event_lo(i), POWER(2, neventcode)) > 0 AND nlock = 0) LOOP
     ln_ret := GREATEST(admin_pg.ins_journal_p(ld_date, an_mid, lc.nvalidity, '', lc.nevent, at_event_lo(i) || '-' || at_event_hi(i)), ln_ret);
    END LOOP;
   ELSIF at_event_hi(i) > 0 THEN
    ln_ret := GREATEST(admin_pg.ins_journal_p(ld_date, an_mid, ln_defvalidity, '', ln_defevent, at_event_lo(i) || '-' || at_event_hi(i)), ln_ret);
   END IF;

   IF ln_ret > 0 THEN
    UPDATE last_save
    SET journal = GREATEST(NVL(journal, ld_date), ld_date)
    WHERE  mid = an_mid;
   END IF;

   <<to_continue>>
   NULL;
  END LOOP;

  IF ln_inserted > 0 THEN
   admin_pg.signal(6);
  END IF;
 END;

