--Вставка месячных
 PROCEDURE set_conf_nikkc02(
 an_cid NUMBER, at_meter_id common_pg.tt_number, at_model_id common_pg.tt_number, at_addr_hi common_pg.tt_number, at_addr_lo common_pg.tt_number,
 at_serial common_pg.tt_number, at_channel_id common_pg.tt_number, at_denergy common_pg.tt_varchar2, at_dstate common_pg.tt_varchar2,
 at_nstate common_pg.tt_number,at_off common_pg.tt_number
 ) IS
  lt_meter_id         numarray := numarray();
 BEGIN
  SAVEPOINT set_conf_nikkc02_sp;

  IF at_meter_id.COUNT > 0 AND NVL(at_meter_id(1), 0) > 0 THEN
   lt_meter_id.EXTEND(at_meter_id.COUNT);

   FOR i IN 1 .. at_meter_id.COUNT LOOP
    lt_meter_id(i) := at_meter_id(i);
   END LOOP;

   DELETE FROM nikrtconf
   WHERE       cid = an_cid AND nid NOT IN(SELECT *
                                       FROM   TABLE(lt_meter_id));

  ELSE
   DELETE FROM nikrtconf
   WHERE       cid = an_cid;

   RETURN;
  END IF;

		FORALL i IN lt_meter_id.first .. lt_meter_id.last
  	MERGE INTO nikrtconf a
    USING (SELECT     an_cid as cid,at_meter_id(i) as nid, at_model_id(i)  as nmodel, at_addr_hi(i)  as naddrh,at_addr_lo(i)  as naddrl,at_serial(i)  as nserial, 
				at_channel_id(i) as  ncid,to_date(at_denergy(i),'dd.mm.yyyy hh24:mi:ss')  as denergy,to_date(at_dstate(i),'dd.mm.yyyy hh24:mi:ss')  as dstate,at_nstate(i)  as nstate,
				at_off(i) as  noff FROM DUAL) b
   ON (a.cid = b.cid AND a.nid = b.nid)
   WHEN MATCHED THEN
    UPDATE
       SET nmodel = b.nmodel, naddrh = b.naddrh,naddrl = b.naddrl, nserial = b.nserial,
       ncid = b.ncid, denergy = b.denergy,dstate = b.dstate, nstate = b.nstate, noff = b.noff
   WHEN NOT MATCHED THEN
    INSERT(cid, nid, nmodel, naddrh, naddrl, nserial, ncid,denergy, dstate, nstate,noff)
    VALUES(b.cid, b.nid, b.nmodel, b.naddrh, b.naddrl, b.nserial, b.ncid,b.denergy, b.dstate, b.nstate,b.noff);

  lt_meter_id.DELETE;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_conf_nikkc02_sp;
   raise_application_error(-20001, 'comsrv_pg.set_conf_nikkc02: an_cid=''' || an_cid || ''' ' || SQLERRM(SQLCODE));
 END;



