 PROCEDURE mark_mercuryevent(newmid NUMBER, newev_date DATE, newtype NUMBER, FOUND OUT NUMBER) IS
  evtype              NUMBER;
  code                NUMBER DEFAULT 0;
  MESSAGE             VARCHAR2(2000);
 BEGIN
  IF newtype = 1 THEN
   code := 1010;
   MESSAGE := ' Отключение счетчика.';
  END IF;

  IF newtype = 256 THEN
   code := -1010;
   MESSAGE := ' Включение счетчика.';
  END IF;

  IF newtype = 2 THEN
   code := -1001;
   MESSAGE := ' Коррекция часов. Время до коррекции.';
  END IF;

  IF newtype = 512 THEN
   code := 1001;
   MESSAGE := ' Коррекция часов. Время после коррекции.';
  END IF;

  IF newtype = 3 THEN
   code := 1019;
   MESSAGE := ' Коррекция расписания праздничных дней.';
  END IF;

  IF newtype = 4 THEN
   code := 1020;
   MESSAGE := ' Коррекция тарифного расписания.';
  END IF;

  IF newtype = 5 THEN
   code := 1021;
   MESSAGE := ' Сброс регистров накопленной энергии.';
  END IF;

  IF newtype = 6 THEN
   code := 1022;
   MESSAGE := ' Инициализация массива средних мощностей.';
  END IF;

  IF newtype = 7 THEN
   code := 1005;
   MESSAGE := ' Выключение фазы 1 счетчика.';
  END IF;

  IF newtype = 7 * 256 THEN
   code := -1005;
   MESSAGE := ' Включение фазы 1 счетчика.';
  END IF;

  IF newtype = 8 THEN
   code := 1005;
   MESSAGE := ' Выключение фазы 2 счетчика.';
  END IF;

  IF newtype = 8 * 256 THEN
   code := -1005;
   MESSAGE := ' Включение фазы 2 счетчика.';
  END IF;

  IF newtype = 9 THEN
   code := 1005;
   MESSAGE := ' Выключение фазы 3 счетчика.';
  END IF;

  IF newtype = 9 * 256 THEN
   code := -1005;
   MESSAGE := ' Включение фазы 3 счетчика.';
  END IF;

  IF newtype = 10 THEN
   code := 1023;
   MESSAGE := ' Вскрытие счетчика.';
  END IF;

  IF newtype = 10 * 256 THEN
   code := 1023;
   MESSAGE := ' Закрытие счетчика.';
  END IF;

  SELECT evtype
  INTO   evtype
  FROM   ea_events
  WHERE  mid = newmid AND evdate = newev_date AND evtype = newtype;

  FOUND := 1;
 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   INSERT INTO journal
               (date_time, mid, state_cod, state_descr)
   VALUES      (newev_date, newmid, code, MESSAGE);

   INSERT INTO ea_events
               (mid, evdate, evtype)
   VALUES      (newmid, newev_date, newtype);

   FOUND := 0;
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.mark_mercuryevent: ' || SQLERRM(SQLCODE));
 END;

