 PROCEDURE mark_ce6850event(newmid NUMBER, newev_date DATE, newtype NUMBER, FOUND OUT NUMBER, newstate NUMBER) IS
  evtype              NUMBER;
  code                NUMBER DEFAULT 0;
  MESSAGE             VARCHAR2(2000);
