 PROCEDURE set_parametrization_date(an_mid NUMBER, av_date VARCHAR2) IS
  --Установка (сверка) даты параметризации av_date dd.mm.yyyy hh24:mi:ss
  cn_parammet CONSTANT NUMBER := 522;
  ld_date             DATE;
  ld_tmp              DATE;
 BEGIN
  ld_date := TO_DATE(av_date, 'yy-mm-dd hh24:mi:ss');

  SELECT MAX(dparametrization)
  INTO   ld_tmp
  FROM   last_save
  WHERE  mid = an_mid;

  IF NVL(ld_tmp, TO_DATE(190001, 'YYYYMM')) <> ld_date THEN
   UPDATE last_save
   SET dparametrization = ld_date
   WHERE  mid = an_mid;

   IF ld_tmp IS NOT NULL THEN                                                                                     --Изменена дата параметризации генерим тревогу
    admin_pg.ins_journal_p(SYSDATE, an_mid, 0,
     'Изменение с ''' || TO_CHAR(ld_tmp, 'dd.mm.yyyy hh24:mi:ss') || ''' на ''' || TO_CHAR(ld_date, 'dd.mm.yyyy hh24:mi:ss') || '''', cn_parammet);
   END IF;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_parametrization_date: ' || SQLERRM(SQLCODE));
 END;

