-- Процедура загрузки файла PAS (качество энергии *.mdb)
 PROCEDURE load_qe_file(an_mid NUMBER, av_filename VARCHAR2, ad_filedate DATE, ab_filebody OUT BLOB) IS
  ld_sys              DATE := SYSDATE;
 BEGIN
  UPDATE    pasfiles
  SET vfilename = av_filename,
      dfiledate = ad_filedate,
      bfilebody = EMPTY_BLOB(),
      denter = ld_sys
  WHERE     mid = an_mid
  RETURNING bfilebody
  INTO      ab_filebody;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO pasfiles
               (mid, denter, vfilename, dfiledate, bfilebody)
   VALUES      (an_mid, ld_sys, av_filename, ad_filedate, EMPTY_BLOB())
   RETURNING   bfilebody
   INTO        ab_filebody;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.load_qe_file: Ошибка загрузки файла ''' || av_filename || '''' || CHR(10) || SQLERRM(SQLCODE));
 END;
