 FUNCTION connectnextmeter(
 an_mid NUMBER, an_cid NUMBER, ln_mid OUT NUMBER, ln_canal OUT NUMBER, ln_name OUT VARCHAR2, ln_kc OUT NUMBER, ln_tag OUT NUMBER, ln_vinfo OUT VARCHAR2,
 ln_nabc OUT NUMBER, ln_q1234 OUT NUMBER, lv_info_def VARCHAR2, ln_info_len NUMBER, ln_tag_def NUMBER
 )
  RETURN NUMBER IS
 BEGIN
  FOR lc IN (SELECT f.mid, NVL(DECODE(c.nuserescanal, 1, f.rescanal, f.canal), 0) canal, SUBSTR(NVL(p.NAME, 'Без имени'), 1, 31) vname, NVL(f.kc, 1) kc,
                    NVL(p.tag, ln_tag_def) tag, SUBSTR(NVL(TRIM(f.vinfo), lv_info_def), 1, ln_info_len) vinfo, f.nabc, DECODE(f.q1234, '*', 1, 0) q1234
             FROM   points p, feeders f, chanpoint c
             WHERE  f.mid = (SELECT MIN(pp.mid)
                             FROM   points pp
                             WHERE  pp.mid > an_mid AND pp.mid IN(SELECT mid
                                                                  FROM   chanpoint
                                                                  WHERE  cid = an_cid AND nskip IS NULL) AND pp.ind = 3) AND f.mid = p.mid(+) AND f.mid = c.mid(+)
                    AND c.cid = an_cid) LOOP
   ln_mid := lc.mid;
   ln_canal := lc.canal;
   ln_name := lc.vname;
   ln_kc := lc.kc;
   ln_tag := lc.tag;
   ln_vinfo := lc.vinfo;
   ln_nabc := lc.nabc;
   ln_q1234 := lc.q1234;
   RETURN 1;
  END LOOP;

  RETURN 0;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'COMSRVCIM_PG.connectnextmeter: ' || SQLERRM(SQLCODE));
 END;

