 FUNCTION connectnextnp(
 an_cid NUMBER, an_mid OUT common_pg.tt_number, an_canal OUT common_pg.tt_number, an_name OUT common_pg.tt_varchar2, an_kc OUT common_pg.tt_number,
 an_tag OUT common_pg.tt_number, an_vinfo OUT common_pg.tt_varchar2, an_commandoff OUT common_pg.tt_number, an_status OUT common_pg.tt_number,
 an_seqid OUT NUMBER
 )
  RETURN NUMBER IS
  cn_255     CONSTANT NUMBER := 255;
  cd_wdtime           DATE := SYSDATE - 3 / 1440;                                                                                --Время на получени SMS ответа
  ln_cnt              NUMBER := 0;
  ld_tmp              DATE;
 BEGIN
  --БД ведет счетчик пакетов
  SELECT NVL(MAX(nrepeaticcp), 0), MAX(trial)
  INTO   an_seqid, ld_tmp
  FROM   last_save
  WHERE  mid = an_cid;

  IF ld_tmp IS NULL OR TRUNC(ld_tmp) <> TRUNC(SYSDATE) THEN
   UPDATE last_save
   SET nrepeaticcp = 0
   WHERE  mid = an_cid;

   an_seqid := 0;
   COMMIT;
  END IF;

  --Мы второй раз делаем setskippoint_p так как при установки соединения с маршрутизатором он сам может накидать данных
  comsrvdisp_pg.setskippoint_p(an_cid);

  FOR lc IN (SELECT   f.mid, NVL(DECODE(c.nuserescanal, 1, f.rescanal, f.canal), 0) canal, SUBSTR(NVL(p.NAME, 'Без имени'), 1, 31) vname, NVL(f.kc, 1) kc,
                      NVL(p.tag, 0) tag, SUBSTR(NVL(TRIM(f.vinfo), cv_info_def), 1, cn_info_len) vinfo,
                      DECODE(NVL(SIGN(l.dexecmdoff - l.dcmdoff), 0), 1, 0, l.ncmdoff) ncmdoff, cp.nstatus
             FROM     points p, feeders f, last_save l, chanpoint c, curr_power cp
             WHERE    c.cid = an_cid AND c.nskip IS NULL AND c.mid = f.mid(+) AND f.mid = p.mid(+) AND p.ind = 3 AND f.mid = l.mid(+) AND f.mid = cp.mid(+)
                      AND(NVL(l.trial, TO_DATE('190001', 'YYYYMM')) < cd_wdtime OR l.nrepeaticcp < 0)                        /*устаревшие или принятые запросы*/
             ORDER BY NVL(l.trial, TO_DATE('190001', 'YYYYMM')), f.mid) LOOP
   ln_cnt := ln_cnt + 1;
   an_mid(ln_cnt) := lc.mid;
   an_canal(ln_cnt) := lc.canal;
   an_name(ln_cnt) := lc.vname;
   an_kc(ln_cnt) := lc.kc;
   an_tag(ln_cnt) := lc.tag;
   an_vinfo(ln_cnt) := lc.vinfo;
   an_commandoff(ln_cnt) := NVL(lc.ncmdoff, 0);
   an_status(ln_cnt) := NVL(lc.nstatus, 0);

   IF ln_cnt >= cn_255 THEN
    EXIT;
   END IF;
  END LOOP;

  RETURN ln_cnt;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'COMSRVCIM_PG.connectnextnp: ' || SQLERRM(SQLCODE));
 END;

