------------------------------------------------------------------------------------------------------------------------
 --Нужена ли точка (например для сброса питания)
 FUNCTION is_need_point(an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN(26, 51, 52, 100, 115, 118, 131) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Признак клиентского канала
 FUNCTION is_client_canal(an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN(61, 77, 116) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Нужен ли канал>0 (FEEDERS.CANAL>0)
 FUNCTION is_need_canal(an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN(2, 3, 24, 25, 37, 38, 113) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Есть ли bill и halfhour
 FUNCTION is_exists_bill(an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN(22, 23, 24, 25) THEN                                                                                                 --Есть только halfhour
   RETURN 2;
  END IF;

  IF an_protocol IN(117, 126) THEN                                                                                                            --Есть только bill
   RETURN 3;
  END IF;

  RETURN 1;                                                                                                                                           --Есть все
 END;

------------------------------------------------------------------------------------------------------------------------
--Выясняем а есть ли точка, которую нужно опросить (быстрая)
 FUNCTION is_existnecessarypoint(an_channel NUMBER, an_protocol_id NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ld_trsys            DATE DEFAULT TRUNC(ad_sys);
  ln_existsbill       NUMBER;
  ln_tmp              NUMBER;
  ln_notreadcurr      NUMBER;

  CURSOR lcur_sel(lc_needcanal NUMBER) IS
   SELECT cp.mid
   FROM   feeders f, chanpoint cp
   WHERE  cp.cid = an_channel AND cp.mid = f.mid(+) AND f.nblock = 0 AND(lc_needcanal = 0 OR NVL(DECODE(cp.nuserescanal, 1, f.rescanal, f.canal), 0) <> 0);
 BEGIN
--  RETURN is_existnecessarypoint2ls(an_channel, an_protocol_id, ad_sys);
--return 1;

  IF is_need_point(an_protocol_id) = 0 THEN
   RETURN 1;
  END IF;

  ln_existsbill := is_exists_bill(an_protocol_id);

  FOR lc IN lcur_sel(is_need_canal(an_protocol_id)) LOOP
   IF ln_notreadcurr IS NULL THEN
    ln_notreadcurr := get_notreadcurr(an_channel, ad_sys);
   END IF;

   IF ln_notreadcurr = 0 THEN                                                                               --Если нет признака не читать тек сутки возвращаем 1
    RETURN 1;
   END IF;

   --Проверяем наличае данных за тек сутки
   IF ln_existsbill = 2 THEN                                                                                                                 --(только halfhour)
    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(
               SELECT 1 c
               FROM   halfhourold
               WHERE  mid = lc.mid AND date_time >= ld_trsys AND nsource = 10
               UNION ALL
               SELECT 1 c
               FROM   halfhourtmp
               WHERE  mid = lc.mid AND util_pg.to_localtime(date_time) >= ld_trsys AND nsource = 10);
   ELSIF ln_existsbill = 3 THEN                                                                                                                  --(только bill)
    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT 1 c
                  FROM   billorg
                  WHERE  mid = lc.mid AND date_time >= ld_trsys);
   ELSE                                                                                                                                      --(bill и halfhour)
    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT 1 c
                  FROM   billorg
                  WHERE  mid = lc.mid AND date_time >= ld_trsys)
           AND EXISTS(
               SELECT 1 c
               FROM   halfhourold
               WHERE  mid = lc.mid AND date_time >= ld_trsys AND nsource = 10
               UNION ALL
               SELECT 1 c
               FROM   halfhourtmp
               WHERE  mid = lc.mid AND util_pg.to_localtime(date_time) >= ld_trsys AND nsource = 10);
   END IF;

   IF ln_tmp = 0 THEN                                                                                    --Мы нашли точку у которой выяснилось, что чего-то нет.
    RETURN 1;
   END IF;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Выясняем а есть ли точка, которую нужно опросить (быстрая)  (по lastsave)
 FUNCTION is_existnecessarypoint2ls(an_channel NUMBER, an_protocol_id NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ld_trsys            DATE DEFAULT TRUNC(ad_sys);
  ln_existsbill       NUMBER;
  ln_notreadcurr      NUMBER;
  ln_need_canal       NUMBER;
  ln_halfhour         DATE;
  ln_bill             DATE;

  CURSOR lcur_sel(lc_needcanal NUMBER) IS
   SELECT cp.mid
   FROM   feeders f, chanpoint cp
   WHERE  cp.cid = an_channel AND cp.mid = f.mid(+) AND f.nblock = 0 AND(lc_needcanal = 0 OR NVL(DECODE(cp.nuserescanal, 1, f.rescanal, f.canal), 0) <> 0);
 BEGIN
  IF is_need_point(an_protocol_id) = 0 THEN
   RETURN 1;
  END IF;

  ln_existsbill := is_exists_bill(an_protocol_id);

  FOR lc IN lcur_sel(is_need_canal(an_protocol_id)) LOOP
   IF ln_notreadcurr IS NULL THEN
    ln_notreadcurr := get_notreadcurr(an_channel, ad_sys);
   END IF;

   IF ln_notreadcurr = 0 THEN                                                                               --Если нет признака не читать тек сутки возвращаем 1
    RETURN 1;
   END IF;

   SELECT util_pg.to_localtime(MAX(halfhour)) halfhour, MAX(bill) bill
   INTO   ln_halfhour, ln_bill
   FROM   last_save
   WHERE  mid = lc.mid;

   --Проверяем наличае данных за тек сутки
   IF NOT(
          (ln_existsbill = 1 AND ln_bill >= ld_trsys AND ln_halfhour >= ld_trsys) OR(ln_existsbill = 2 AND ln_halfhour >= ld_trsys)
          OR(ln_existsbill = 3 AND ln_bill >= ld_trsys)
         ) THEN
    RETURN 1;
   END IF;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Проверяем доступен ли интервал опроса
 FUNCTION isworktime_f(an_channel NUMBER, an_start NUMBER, an_end NUMBER, an_sys NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER := 0;
 BEGIN
  IF isworktime_d_f(an_start, an_end, an_sys) = 1 THEN
   RETURN 1;
  END IF;

  SELECT COUNT(*)
  INTO   ln_ret
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   chaninterval
                WHERE  cid = an_channel AND isworktime_d_f(TO_CHAR(dstart, 'sssss'), TO_CHAR(dend, 'sssss'), an_sys) = 1);

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Проверяем доступен ли интервал опроса DETERMINISTIC
 FUNCTION isworktime_d_f(an_start NUMBER, an_end NUMBER, an_sys NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF (an_sys BETWEEN NVL(an_start, an_sys) AND NVL(an_end, an_sys)) OR(an_start >= an_end AND(an_sys >= an_start OR an_sys <= an_end)) THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Проверяем доступен ли день опроса
 FUNCTION is_validday(an_day NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ln_sys              NUMBER;
 BEGIN
  IF NVL(an_day, 0) = 0 THEN
   RETURN 1;
  END IF;

  ln_sys := TO_CHAR(ad_sys, 'dd');

  FOR i IN 1 .. CEIL(LENGTH(an_day) / 2) LOOP
   IF ln_sys = TRUNC(MOD(an_day / POWER(100, i - 1), 100)) THEN
    RETURN 1;
   END IF;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает можно ли опрашивать по отношению основной резервный
 FUNCTION is_need_question_by_rezerv(an_channel NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ln_mainchannel      NUMBER DEFAULT channels_pg.get_main_channel(an_channel);
  ln_ret              NUMBER;

  CURSOR lcur_sel IS
   SELECT     c.cid
   FROM       channels c
   WHERE      c.nready IS NULL
                              --Идем по обделанным каналам до тех пор покуда не встретим еще не проверенные а потом просееваем WHERE обделанные
              AND is_existnecessarypoint(c.cid, c.protocol_id, ad_sys) = 1
   CONNECT BY PRIOR c.cid = c.nparent AND c.cid IN(SELECT *
                                                   FROM   TABLE(gt_unlockcid)) AND PRIOR c.nready IS NOT NULL
   START WITH c.cid = ln_mainchannel AND ln_mainchannel IN(SELECT *
                                                           FROM   TABLE(gt_unlockcid));
 BEGIN
  --Если есть опрашиваемые каналы по принципу резервирования значит - отдохни
  SELECT COUNT(*)
  INTO   ln_ret
  FROM   DUAL
  WHERE  EXISTS(SELECT     *
                FROM       channels
                WHERE      is_dead IS NOT NULL
                CONNECT BY PRIOR cid = nparent
                START WITH cid = ln_mainchannel);

  IF ln_ret > 0 THEN
   RETURN 0;
  ELSE
   ln_ret := NULL;
  END IF;

  --Просим канал
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  ln_ret;

  CLOSE lcur_sel;

  IF (an_channel = ln_ret) OR(ln_ret IS NULL AND an_channel = ln_mainchannel) THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Сброс состояния (при соединении и восстановлении)
 PROCEDURE start_p(an_restore NUMBER, an_srv NUMBER) IS
  lv_mess             VARCHAR2(128) DEFAULT 'CSrv: Запущен сервер сбора данных.';
  ln_code             NUMBER DEFAULT 0;
  ln_mid              NUMBER;
 BEGIN
  IF an_restore > 0 THEN
   lv_mess := 'CSrv: Восстановлено подключение к БД в ' || an_restore || ' раз.';
   ln_code := 54;
  ELSE
   UPDATE mtxconf
   SET nstate = 0,
       dstate = SYSDATE;                                                                  --Для нескольких опросчиков это нужно переписать как в UPDATE comports
  END IF;

  SELECT NVL(MAX(mid), 1)
  INTO   ln_mid
  FROM   srv
  WHERE  nsrv = an_srv;

  admin_pg.ins_journal_p(SYSDATE, ln_mid, ln_code, lv_mess, cn_processmet);

  UPDATE channels
  SET nready = NULL,
      is_dead = NULL
  WHERE  com_id IN(SELECT com_id
                   FROM   comports
                   WHERE  nsrv = an_srv) AND(nready IS NOT NULL OR is_dead IS NOT NULL);

  admin_pg.begin_p;

  UPDATE comports
  SET vlastevent = NULL,
      dlastevent = SYSDATE
  WHERE  nsrv = an_srv AND vlastevent IS NOT NULL;

  COMMIT;
  --Копируем данные из TMP
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.start_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Вызывается при остановке опросчика
 PROCEDURE end_p(an_srv NUMBER) IS
  lv_mess             VARCHAR2(128) DEFAULT 'CSrv: Остановлен сервер сбора данных.';
 BEGIN
  admin_pg.ins_journal_p(SYSDATE, an_srv, 0, lv_mess, cn_processmet);

  UPDATE comports
  SET vlastevent = NULL,
      dlastevent = SYSDATE
  WHERE  nsrv = an_srv AND vlastevent IS NOT NULL;

  COMMIT;
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.end_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Помечает точки, которые не нужно опрашивать
 PROCEDURE setskippoint_p(an_channel NUMBER, an_protocol_id NUMBER, ad_sys DATE) IS
  ld_trsys            DATE DEFAULT TRUNC(ad_sys);
  ln_existsbill       NUMBER;
  ln_tmp              NUMBER;

  CURSOR lcur_sel(lc_needcanal NUMBER) IS
   SELECT c.mid
   FROM   feeders f, chanpoint c
   WHERE  c.cid = an_channel AND c.mid = f.mid(+) AND f.nblock = 0 AND(lc_needcanal = 0 OR NVL(DECODE(c.nuserescanal, 1, f.rescanal, f.canal), 0) <> 0);
 BEGIN
  --Можно аккуратней но я решил сначала всех исключить, а затем оставить нужных
  UPDATE chanpoint
  SET nskip = 1
  WHERE  cid = an_channel AND NVL(nskip, 0) <> 1;

  IF get_notreadcurr(an_channel, ad_sys) = 0 THEN                                                          --Если нет признака не читать тек сутки разрешаем все
   UPDATE chanpoint
   SET nskip = NULL
   WHERE  cid = an_channel
          AND mid IN(
              SELECT c.mid
              FROM   feeders f, chanpoint c
              WHERE  c.cid = an_channel AND c.mid = f.mid(+) AND f.nblock = 0
                     AND(is_need_canal(an_protocol_id) = 0 OR NVL(DECODE(c.nuserescanal, 1, f.rescanal, f.canal), 0) <> 0))
          AND nskip IS NOT NULL;
  ELSE                                                                                                                       --Еесть признак не читать тек сутки
   ln_existsbill := is_exists_bill(an_protocol_id);

   FOR lc IN lcur_sel(is_need_canal(an_protocol_id)) LOOP
    --Проверяем наличае данных за тек сутки
    IF ln_existsbill = 2 THEN                                                                                                               --(только halfhour)
     SELECT COUNT(*)
     INTO   ln_tmp
     FROM   DUAL
     WHERE  EXISTS(
               SELECT 1 c
               FROM   halfhourold
               WHERE  mid = lc.mid AND date_time >= ld_trsys AND nsource = 10
               UNION ALL
               SELECT 1 c
               FROM   halfhourtmp
               WHERE  mid = lc.mid AND util_pg.to_localtime(date_time) >= ld_trsys AND nsource = 10);
    ELSIF ln_existsbill = 3 THEN                                                                                                                 --(только bill)
     SELECT COUNT(*)
     INTO   ln_tmp
     FROM   DUAL
     WHERE  EXISTS(SELECT 1 c
                   FROM   billorg
                   WHERE  mid = lc.mid AND date_time >= ld_trsys);
    ELSE                                                                                                                                     --(bill и halfhour)
     SELECT COUNT(*)
     INTO   ln_tmp
     FROM   DUAL
     WHERE  EXISTS(SELECT 1 c
                   FROM   billorg
                   WHERE  mid = lc.mid AND date_time >= ld_trsys)
            AND EXISTS(
                SELECT 1 c
                FROM   halfhourold
                WHERE  mid = lc.mid AND date_time >= ld_trsys AND nsource = 10
                UNION ALL
                SELECT 1 c
                FROM   halfhourtmp
                WHERE  mid = lc.mid AND util_pg.to_localtime(date_time) >= ld_trsys AND nsource = 10);
    END IF;

    IF ln_tmp = 0 THEN                                                                                    --Мы нашли точку у которой выяснилось что чего-то нет.
     UPDATE chanpoint
     SET nskip = NULL
     WHERE  cid = an_channel AND mid = lc.mid AND nskip IS NOT NULL;
    END IF;
   END LOOP;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setskippoint_p(an_channel NUMBER) IS
  ln_protocol         NUMBER;
  ln_port             NUMBER;
 BEGIN
  SELECT MAX(protocol_id), MAX(com_id)
  INTO   ln_protocol, ln_port
  FROM   channels
  WHERE  cid = an_channel;

 --Блокируем для монопольной операции
/*  IF admin_pg.lockrow_p(comsrvdisp_pg.cn_lock, 'PARAMETER', 'NPID', 6) <> 6 THEN
   RETURN;
  END IF;*/
  IF lock_com_id(ln_port) = 0 THEN
   RETURN;
  END IF;

  setskippoint_p(an_channel, ln_protocol);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
 END;

------------------------------------------------------------------------------------------------------------------------
     --Процедура извлечения параметров порта
 FUNCTION getnextchannel_f(
 an_port NUMBER, av_comname OUT VARCHAR2, an_baudrate OUT NUMBER, an_bytesize OUT NUMBER, an_parity OUT NUMBER, an_stopbits OUT NUMBER, an_ncomtype OUT NUMBER,
 an_protocol OUT NUMBER
 )
  RETURN NUMBER IS
  ln_ret              NUMBER;
  ln_delivered        NUMBER;
  ld_sys              DATE DEFAULT SYSDATE;
  ln_com_id           NUMBER;

  CURSOR lcur_sel IS
   SELECT   c.cid, c.ndelivered, NVL(c.protocol_id, 0)
   FROM     channels c, last_save l
   WHERE    c.com_id = an_port AND c.cid IN(SELECT *
                                            FROM   TABLE(gt_unlockcid)) AND /*c.cid = l.mid(+)*/ NVL2(c.nparent, channels_pg.get_main_channel(c.nparent),
                                                                                                 c.cid) = l.mid(+)
            AND(l.trial IS NULL OR ABS(ld_sys - l.trial) * 86400 >= c.cycle_tout)
            AND((c.nparent IS NULL AND c.is_dead IS NULL) OR(c.nparent IS NOT NULL AND is_need_question_by_rezerv(c.cid,ld_sys) = 1
												))
            AND is_existnecessarypoint(c.cid, c.protocol_id, ld_sys) = 1
   ORDER BY c.ndelivered, DECODE(c.nkind, 1, 1, 100, 2, 3), DECODE(c.nparent, NULL, 1, 0), c.vname;
 BEGIN
  --Обновим визуализацию
  UPDATE comports
  SET vlastevent = NULL,
      dlastevent = SYSDATE
  WHERE  com_id = an_port AND vlastevent IS NOT NULL;

  IF SQL%ROWCOUNT > 0 THEN
   COMMIT;
  END IF;

  --Быстрый выход в случае свободного порта
  SELECT COUNT(*)
  INTO   ln_ret
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   channels
                WHERE  com_id = an_port);                                                                                              -- AND an_port IN (4, 5);

  IF ln_ret = 0 THEN
   RETURN 0;
  ELSE
   ln_ret := NULL;
  END IF;

  --Заполняем таблицу разрешенных каналов по блокировкам и доступу
  IF gd_unlockcid IS NULL OR ABS(gd_unlockcid - ld_sys) > cn_unlockcid THEN
   gd_unlockcid := ld_sys;

   SELECT cid
   BULK COLLECT INTO gt_unlockcid
   FROM   channels
   WHERE  (NVL(nkind, 0) = 100 OR(blocking = 0 AND is_validday(nday, ld_sys) = 1 AND cid IN(SELECT     mid
                                                                                            FROM       points
                                                                                            CONNECT BY PRIOR mid = PARENT AND DECODE(NVL(tag, 0), 0, 0, 1) = 0
                                                                                            START WITH mid = 1))) AND is_client_canal(protocol_id) = 1
          AND isworktime_f(cid, TO_CHAR(dstart, 'SSSSS'), TO_CHAR(dend, 'SSSSS'), TO_CHAR(ld_sys, 'SSSSS')) = 1;
  END IF;

  --Блокируем для монопольной операции
/*  IF admin_pg.lockrow_p(cn_lock, 'PARAMETER', 'NPID', 6) <> 6 THEN
   RETURN 0;
  END IF;*/
  IF lock_com_id(an_port) = 0 THEN
   RETURN 0;
  END IF;

  --Удаляем опрошенные временные каналы точек
  FOR lc IN (SELECT cid mid
             FROM   channels
             WHERE  com_id = an_port AND nkind = 1 AND ndelivered = 1 AND is_client_canal(protocol_id) = 1) LOOP
   DELETE FROM points
   WHERE       mid = lc.mid;
  END LOOP;

  --Очищаем зависшие нити (watchdog)
  UPDATE channels
  SET is_dead = NULL
  WHERE  com_id = an_port AND(ld_sys - is_dead) > cn_waitcanal / 1440 AND is_dead IS NOT NULL AND is_client_canal(protocol_id) = 1;

  --Деактивируем оперативный опрос
  FOR lc IN (SELECT cid
             FROM   channels
             WHERE  com_id = an_port AND nkind = 100 AND is_client_canal(protocol_id) = 1
                    AND isworktime_d_f(TO_CHAR(dstart, 'sssss'), TO_CHAR(dend, 'sssss'), TO_CHAR(ld_sys, 'SSSSS')) <> 1) LOOP
   operscan_pg.deactive_p(lc.cid);
  END LOOP;

  --Просим канал
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  ln_ret, ln_delivered, an_protocol;

  CLOSE lcur_sel;

  --Если что-то выбрали
  IF ln_ret > 0 THEN
   --Если выбран уже опрошенный, то сбрасываем флаги у всех
   IF ln_delivered = 1 THEN
    UPDATE channels
    SET ndelivered = 0
    WHERE  com_id = an_port AND ndelivered <> 0 AND NVL(nkind, 0) <> 1 AND is_client_canal(protocol_id) = 1;
   END IF;

   --Помечаем что канал выбран и сразу думаем что он умер (и не просто думаем а говорим что он отдан на откуп) is_dead
   UPDATE channels
   SET ndelivered = 1,
       is_dead = ld_sys,
       nready = NULL
   WHERE  cid = ln_ret;

   --Метим точки которые не нужно опрашивать
   setskippoint_p(ln_ret, an_protocol, ld_sys);

   --Вытягиваем остальную информацию по каналу (порту) для запуска нитей опроса
   SELECT NAME, baudrate, bytesize, parity, stopbits, ncomtype
   INTO   av_comname, an_baudrate, an_bytesize, an_parity, an_stopbits, an_ncomtype
   FROM   comports
   WHERE  com_id = an_port;
  END IF;

  set_log(an_port, ln_ret, ld_sys, NULL, 86400 *(SYSDATE - ld_sys));
  COMMIT;
  RETURN NVL(ln_ret, 0);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.getnextchannel_f: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Дай следующий канал MTX
 FUNCTION getnextmtxchannel_f(an_thread NUMBER, an_protocol OUT NUMBER, an_srv NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
  ln_delivered        NUMBER;
  ld_sys              DATE DEFAULT SYSDATE;

  CURSOR lcur_sel IS
   SELECT   c.cid, c.ndelivered, NVL(c.protocol_id, 0)
   FROM     channels c, last_save l
   WHERE    c.protocol_id = cn_mtxprotocol AND c.com_id IN(SELECT com_id
                                                           FROM   comports
                                                           WHERE  nsrv = an_srv) AND NVL(c.nparent, c.cid) = l.mid(+)
            AND channels_pg.is_block(c.cid, c.blocking, c.nkind) = 0
            AND isworktime_f(c.cid, TO_CHAR(c.dstart, 'SSSSS'), TO_CHAR(c.dend, 'SSSSS'), TO_CHAR(ld_sys, 'SSSSS')) = 1
            AND(NVL(c.nkind, 0) = 100 OR is_validday(c.nday, ld_sys) = 1) AND(l.trial IS NULL OR ABS(ld_sys - l.trial) * 86400 >= cycle_tout)
            AND is_existnecessarypoint(c.cid, c.protocol_id, ld_sys) = 1 AND is_dead IS NULL AND util_pg.allnumber_f(c.addr) > 0
   ORDER BY c.ndelivered, DECODE(c.nkind, 1, 1, 100, 2, 3), DECODE(nparent, NULL, 1, 0), c.vname;
 BEGIN
  --Быстрый выход в случае свободного порта
  SELECT COUNT(*)
  INTO   ln_ret
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   channels
                WHERE  protocol_id = cn_mtxprotocol AND util_pg.allnumber_f(addr) > 0);

  IF ln_ret = 0 THEN
   RETURN 0;
  ELSE
   ln_ret := NULL;
  END IF;

  --Блокируем для монопольной операции
  IF admin_pg.lockrow_p(comsrvdisp_pg.cn_lock, 'PARAMETER', 'NPID', 6) <> 6 THEN
   RETURN 0;
  END IF;

  --Удаляем опрошенные временные каналы точек
  FOR lc IN (SELECT cid mid
             FROM   channels
             WHERE  protocol_id = cn_mtxprotocol AND com_id IN(SELECT com_id
                                                               FROM   comports
                                                               WHERE  nsrv = an_srv) AND nkind = 1 AND ndelivered = 1) LOOP
   DELETE FROM points
   WHERE       mid = lc.mid;
  END LOOP;

  --Очищаем зависшие нити (watchdog)
  UPDATE channels
  SET is_dead = NULL
  WHERE  protocol_id = cn_mtxprotocol AND com_id IN(SELECT com_id
                                                    FROM   comports
                                                    WHERE  nsrv = an_srv) AND(ld_sys - is_dead) > comsrvdisp_pg.cn_waitcanal / 1440 AND is_dead IS NOT NULL;

  --Деактивируем оперативный опрос
  FOR lc IN (SELECT cid
             FROM   channels
             WHERE  protocol_id = cn_mtxprotocol AND com_id IN(SELECT com_id
                                                               FROM   comports
                                                               WHERE  nsrv = an_srv) AND nkind = 100
                    AND isworktime_d_f(TO_CHAR(dstart, 'sssss'), TO_CHAR(dend, 'sssss'), TO_CHAR(ld_sys, 'SSSSS')) <> 1) LOOP
   operscan_pg.deactive_p(lc.cid);
  END LOOP;

  --Просим канал
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  ln_ret, ln_delivered, an_protocol;

  CLOSE lcur_sel;

  --Если что-то выбрали
  IF ln_ret > 0 THEN
   --Если выбран уже опрошенный, то сбрасываем флаги у всех
   IF ln_delivered = 1 THEN
    UPDATE channels
    SET ndelivered = 0
    WHERE  protocol_id = cn_mtxprotocol AND com_id IN(SELECT com_id
                                                      FROM   comports
                                                      WHERE  nsrv = an_srv) AND ndelivered <> 0 AND NVL(nkind, 0) <> 1;
   END IF;

   --Помечаем что канал выбран и сразу думаем что он умер (и не просто думаем а говорим что он отдан на откуп) is_dead
   UPDATE channels
   SET ndelivered = 1,
       is_dead = ld_sys,
       nready = NULL
   WHERE  cid = ln_ret;

   --Метим точки которые не нужно опрашивать
   setskippoint_p(ln_ret, an_protocol, ld_sys);
  END IF;

  set_log(an_thread, ln_ret, ld_sys, NULL);
  COMMIT;
  RETURN NVL(ln_ret, 0);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.getnextmtxchannel_f: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setstatuschannel_p(an_channel NUMBER, an_status NUMBER) IS
  --an_status=0 - OK,=1 - вообще не открыли сокет, иначе ERROR
  ld_sys              DATE DEFAULT SYSDATE;
  ln_mainchannel      NUMBER DEFAULT channels_pg.get_main_channel(an_channel);
  ln_status           NUMBER DEFAULT NVL(an_status, 1);
  ln_protocol         NUMBER;
  ln_port             NUMBER;
  ld_isdead           DATE;
  ln_kind             NUMBER;
  ln_delayfrombegin   NUMBER;
 BEGIN
  SELECT MAX(protocol_id), MAX(com_id), MAX(is_dead), MAX(nkind)
  INTO   ln_protocol, ln_port, ld_isdead, ln_kind
  FROM   channels
  WHERE  cid = an_channel;

/*  IF admin_pg.lockrow_p(cn_lock, 'PARAMETER', 'NPID', 6) <> 6 THEN
    set_log(ln_port, an_channel, ld_sys, ln_status, 86400 *(SYSDATE - ld_sys), 1);
    COMMIT;
    RETURN;
  END IF;*/
  IF lock_com_id(ln_port) = 0 THEN
   set_log(ln_port, an_channel, ld_sys, ln_status, 86400 *(SYSDATE - ld_sys), 1);
   COMMIT;
   RETURN;
  END IF;

  --Удаляем опрошенные временные каналы точек
  IF ln_kind = 1 THEN
   DELETE FROM points
   WHERE       mid = an_channel;

   GOTO to_continue;
  END IF;

  IF ln_status = 0 THEN                                                                                                                 --Все опросилось успешно
   --Если Все ОК то устанавливаем дату последней попытки для дочерних
   UPDATE last_save
   SET luck = ld_sys
   WHERE  mid IN(SELECT     cid
                 FROM       channels
                 CONNECT BY PRIOR cid = nparent
                 START WITH nparent = ln_mainchannel);

   --И для основного помня про настройку паузы между циклами опроса от начала опроса
   ln_delayfrombegin := util_pg.getparamvalue_f(43);                                                                     --Пауза между циклами от начала оопроса

   UPDATE last_save
   SET luck = ld_sys,
       trial = NVL(DECODE(ln_delayfrombegin, 1, ld_isdead), ld_sys)
   WHERE  mid = ln_mainchannel;

   --Сброс nready для всех каналов начиная с основного (мы теперь не облажались)
   UPDATE channels
   SET nready = NULL
   WHERE  cid IN(SELECT     cid
                 FROM       channels
                 CONNECT BY PRIOR cid = nparent
                 START WITH cid = ln_mainchannel) AND nready IS NOT NULL;

   --Пишем в журнал при восстановлении.
   FOR lc IN (SELECT cid, vname
              FROM   channels
              WHERE  cid = an_channel AND was_dead IS NOT NULL) LOOP
    admin_pg.ins_journal_p(SYSDATE, lc.cid, 0, 'Восстановлена связь по каналу ' || lc.vname, cn_processmet);
    admin_pg.signal(6);
   END LOOP;

   --Сбрасываем время смерти
   UPDATE channels
   SET was_dead = NULL,
       is_dead = NULL
   WHERE  cid = an_channel;
  ELSE                                                                                                                                   --Опросилось с ошибками
   --Если не ошибка открытия порта и мы на основном канале второй раз облажались то мы двигаем trial
   IF (ln_status <> 1 OR util_pg.getparamvalue_f(53) = 1) AND an_channel = ln_mainchannel THEN
    UPDATE last_save
    SET trial = ld_sys
    WHERE  mid = ln_mainchannel AND EXISTS(SELECT *
                                           FROM   channels
                                           WHERE  cid = ln_mainchannel AND was_dead IS NOT NULL);
   END IF;

   -- Записывем время последнего чтения с ошибкой для простых каналов (не Итек, Фаг и т.д.)
   IF is_need_canal(ln_protocol) > 0 THEN
    UPDATE last_save
    SET fail = ld_sys
    WHERE  mid = an_channel;
   END IF;

   --Вверх все запрещены (включая самого)
   UPDATE channels
   SET nready = 1
   WHERE  cid IN(SELECT     cid
                 FROM       channels
                 CONNECT BY PRIOR nparent = cid
                 START WITH cid = an_channel) AND NVL(nready, 0) <> 1;

   --Вниз все разрешены
   UPDATE channels
   SET nready = NULL
   WHERE  cid IN(SELECT     cid
                 FROM       channels
                 CONNECT BY PRIOR cid = nparent
                 START WITH nparent = an_channel) AND nready IS NOT NULL;

   --Пишем в журнал при первом сбое.
   FOR lc IN (SELECT cid, vname
              FROM   channels
              WHERE  cid = an_channel AND was_dead IS NULL) LOOP
    admin_pg.ins_journal_p(SYSDATE, lc.cid, 6, 'Нет связи по каналу ' || lc.vname, cn_processmet);
    admin_pg.signal(6);
   END LOOP;

   --Пишем дату смерти
   UPDATE channels
   SET was_dead = DECODE(was_dead, NULL, is_dead, was_dead),
       is_dead = NULL
   WHERE  cid = an_channel;
  END IF;

  --Обновим визуализацию
  IF is_client_canal(ln_protocol) = 1 THEN
   UPDATE comports
   SET vlastevent = NULL,
       dlastevent = SYSDATE
   WHERE  com_id = ln_port;
  END IF;

  --Пишем в журнал
  set_log(NULL, an_channel, ld_sys, ln_status, 86400 *(SYSDATE - ld_sys));

  --Исправляем ошибки по ИТЭК
  IF ln_protocol = cn_itekprotocol THEN
   itekmistake(an_channel, ln_mainchannel, ld_sys);
  END IF;

  <<to_continue>>
  COMMIT;
  --Копируем данные из TMP
  das_pg.checkhalfhour_without_err(0);
  COMMIT;

  --Посылаем сообщение на обновление мониторов
  IF util_pg.getparamvalue_f(24) = 1 THEN
   admin_pg.signal(3);
   admin_pg.signal(4);
  END IF;

  set_log(NULL, an_channel, ld_sys, ln_status, 86400 *(SYSDATE - ld_sys), 1);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.setstatuschannel_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Исправляем ошибки ИТЭК (когда присылает хлам и суточные не сходятся с ГН)
 PROCEDURE itekmistake(an_channel NUMBER, an_main_channel NUMBER, ad_sys DATE) IS
  cn_max_itek_rereads CONSTANT NUMBER := 2;                                            -- макс. кол-во пересчитываний Итека при несовпадении профиля и суточных
  cn_max_itek_diffs CONSTANT NUMBER := 3;                                                      -- допустимое расхождение в импульсах профиля и суточных у Итека
  ln_reread           NUMBER;
  ln_tmp              NUMBER;
 BEGIN
  --Читаем необходимое
  SELECT NVL(MAX(protocol_id), 0), ABS(TRUNC(MAX(nreread)))
  INTO   ln_tmp, ln_reread
  FROM   channels
  WHERE  cid = an_main_channel;

  -- nreread  это YYYYMMDD||itek_rereads
  -- Мы выходим если не итек или исчерпан (или все ОК) лимит перечтений
  IF ln_tmp <> cn_itekprotocol OR(SUBSTR(ln_reread, 1, 8) = TO_CHAR(ad_sys, 'YYYYMMDD') AND NVL(TO_NUMBER(SUBSTR(ln_reread, 9)), 0) >= cn_max_itek_rereads) THEN
   RETURN;
  END IF;

  --Выясняем сколько раз читали
  IF SUBSTR(ln_reread, 1, 8) = TO_CHAR(ad_sys, 'YYYYMMDD') THEN
   ln_reread := NVL(TO_NUMBER(SUBSTR(ln_reread, 9)), 0);
  ELSE
   ln_reread := 0;
  END IF;

  --Копируем из TMP
  das_pg.checkhalfhour_without_err(0);

  --Выясняем а есть ли получасовки
  SELECT COUNT(*)
  INTO   ln_tmp
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   halfhourold h, chanpoint cp
                WHERE  h.date_time = TRUNC(ad_sys) AND h.nsource = 20 AND h.mid = cp.mid AND cp.cid = an_main_channel);

  IF ln_tmp = 0 THEN                                                                                                       --Если еще нет получасовок, то уходим
   RETURN;
  END IF;

  --Двигаем ln_reread где все не хорошо т.е. плохо
  UPDATE channels
  SET nreread = TO_CHAR(ad_sys, 'YYYYMMDD') ||(ln_reread + 1)
  WHERE  cid = an_main_channel
         AND EXISTS(
             SELECT *
             FROM   (SELECT   h.mid, SUM(h.er) - AVG(b.er) r, SUM(h.ed) - AVG(b.ed) d
                     FROM     halfhourold h, billorg b, feeders p, chanpoint cp
                     WHERE    cp.cid = an_main_channel AND h.mid = cp.mid AND b.mid = cp.mid AND p.mid(+) = cp.mid AND h.date_time > TRUNC(ad_sys) - 1
                              AND h.date_time <= TRUNC(ad_sys) AND b.date_time = TRUNC(ad_sys)
                              AND(
                                  h.nsource = DECODE(SIGN(NVL(p.canal, 0) - 50000000), 1, 20, 10)
                                  OR h.nsource = DECODE(SIGN(NVL(p.canal, 0) - 50000000), 1, 29, 19)
                                 ) AND b.nsource = 20
                     GROUP BY h.mid) cc,
                    itekcoeff i
             WHERE  cc.mid = i.mid(+)
                    AND(
                        ABS(NVL(cc.r, 0)) / DECODE(i.ker, 0, 1, NULL, 1, i.ker) >= cn_max_itek_diffs
                        OR ABS(NVL(cc.d, 0)) / DECODE(i.ked, 0, 1, NULL, 1, i.ked) >= cn_max_itek_diffs
                       ));

  IF SQL%ROWCOUNT > 0 THEN
   -- откатываем last_save
   UPDATE last_save
   SET halfhour = util_pg.to_unlocaltime(TRUNC(ad_sys) - 1),
       bill = util_pg.to_unlocaltime(TRUNC(ad_sys) - 1),
       trial = TRUNC(ad_sys) - 1
   WHERE  mid IN(SELECT     cid
                 FROM       channels
                 CONNECT BY PRIOR cid = nparent
                 START WITH cid = an_main_channel);

   -- отмечаем факт отката данных в журнале событий
   admin_pg.ins_journal_p(SYSDATE, an_main_channel, -999, 'Откат данных Итека при несовпадении суточных', cn_processmet);
  ELSE
   -- Ставим на cn_max_itek_rereads, чтоб больше не дергались и выходили быстро без проверки (cn_max_itek_rereads+1 чтоб заметить)
   UPDATE channels
   SET nreread = TO_CHAR(ad_sys, 'YYYYMMDD') ||(cn_max_itek_rereads + 1)
   WHERE  cid = an_main_channel;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
     --Дай канал УППД
 FUNCTION getuppdchannel_f(av_user VARCHAR2, an_port OUT NUMBER, av_comname OUT VARCHAR2, av_pass OUT VARCHAR2, an_srv NUMBER)
  RETURN NUMBER IS
  ld_sys              DATE DEFAULT SYSDATE;
  ln_ret              NUMBER;
 BEGIN
  FOR lc IN (SELECT   c.cid, c.com_id, c.vaccpassword
             FROM     channels c
             WHERE    c.protocol_id = cn_uppdprotocol AND UPPER(vaccuser) = UPPER(av_user) AND channels_pg.is_block(c.cid, c.blocking, c.nkind) = 0
                      AND isworktime_f(c.cid, TO_CHAR(c.dstart, 'SSSSS'), TO_CHAR(c.dend, 'SSSSS'), TO_CHAR(ld_sys, 'SSSSS')) = 1
                      AND(NVL(c.nkind, 0) = 100 OR is_validday(c.nday, ld_sys) = 1) AND nparent IS NULL AND c.com_id IN(SELECT com_id
                                                                                                                        FROM   comports
                                                                                                                        WHERE  nsrv = an_srv)
             ORDER BY c.cid) LOOP
   ln_ret := lc.cid;
   an_port := lc.com_id;
   av_pass := lc.vaccpassword;

   SELECT NAME
   INTO   av_comname
   FROM   comports
   WHERE  com_id = lc.com_id;

   EXIT;
  END LOOP;

  RETURN NVL(ln_ret, 0);
 END;

------------------------------------------------------------------------------------------------------------------------
    --Дай первый канал УППД (работаем на 128 порту)
 FUNCTION getfirstuppdserverchannel_f(
 an_port NUMBER, av_comname OUT VARCHAR2, an_baudrate OUT NUMBER, an_bytesize OUT NUMBER, an_parity OUT NUMBER, an_stopbits OUT NUMBER, an_ncomtype OUT NUMBER,
 an_protocol OUT NUMBER, an_srv NUMBER
 )
  RETURN NUMBER IS
  ln_ret              NUMBER;
  ln_port             NUMBER;
 BEGIN
  SELECT NVL(MAX(c.cid), 0), NVL(MAX(c.com_id), 0)
  INTO   ln_ret, ln_port
  FROM   channels c
  WHERE  c.protocol_id = cn_uppdprotocol AND c.com_id IN(SELECT com_id
                                                         FROM   comports
                                                         WHERE  nsrv = an_srv);

  IF ln_ret > 0 THEN
   SELECT NAME, baudrate, bytesize, parity, stopbits, ncomtype
   INTO   av_comname, an_baudrate, an_bytesize, an_parity, an_stopbits, an_ncomtype
   FROM   comports
   WHERE  com_id = ln_port;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --По опросчику и номеру порта возвращает ид. порта
 FUNCTION getportid_f(an_comnum NUMBER, an_srv NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT MAX(com_id)
  INTO   ln_ret
  FROM   comports
  WHERE  com_num = an_comnum AND nsrv = an_srv;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_srv_info(acur_t OUT common_pg.tcur) IS
 -- используется в dmMain::oqSrv
 BEGIN
  OPEN acur_t FOR
   SELECT   nsrv, vname
   FROM     srv
   ORDER BY nsrv;
 END;

--------------------------------------------------------------------------------------
--Возвращает признак не читать тек сутки
 FUNCTION get_notreadcurr(an_channel NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_ret              NUMBER;
  ln_kind             NUMBER;
  ln_sys              NUMBER DEFAULT TO_CHAR(ad_date, 'sssss');
 BEGIN 
  SELECT NVL(MAX(nnotreadcurr), 0), MAX(nkind)
  INTO   ln_ret, ln_kind
  FROM   channels
  WHERE  cid = an_channel;
		
  IF ln_kind = 100 THEN                                                                         --При оперативном опросе работаем по признакам основного канала
   RETURN ln_ret;
  END IF;

  IF ln_ret = 0 THEN
   SELECT GREATEST(NVL(MAX(nnotreadcurr), ln_ret), ln_ret)
   INTO   ln_ret
   FROM   chaninterval
   WHERE  cid = an_channel AND isworktime_d_f(TO_CHAR(dstart, 'sssss'), TO_CHAR(dend, 'sssss'), ln_sys) = 1;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает переопределенный признак чтения параметров сети
 FUNCTION get_netparam(an_channel NUMBER, an_netparam NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_sys              NUMBER DEFAULT TO_CHAR(ad_date, 'sssss');
  ln_ret              NUMBER := NVL(an_netparam, 0);
 BEGIN
  IF ln_ret = 0 THEN
   SELECT GREATEST(NVL(MAX(nnetparam), ln_ret), ln_ret)
   INTO   ln_ret
   FROM   chaninterval
   WHERE  cid = an_channel AND isworktime_d_f(TO_CHAR(dstart, 'sssss'), TO_CHAR(dend, 'sssss'), ln_sys) = 1;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает переопределенный признак чтения параметров сети
 FUNCTION get_journal(an_channel NUMBER, an_journal NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_sys              NUMBER DEFAULT TO_CHAR(ad_date, 'sssss');
  ln_ret              NUMBER := NVL(an_journal, 0);
 BEGIN
  IF ln_ret = 0 THEN
   SELECT GREATEST(NVL(MAX(njournal), ln_ret), ln_ret)
   INTO   ln_ret
   FROM   chaninterval
   WHERE  cid = an_channel AND isworktime_d_f(TO_CHAR(dstart, 'sssss'), TO_CHAR(dend, 'sssss'), ln_sys) = 1;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Записывает ini файл опросчика в БД
 PROCEDURE set_srvini_p(an_srv NUMBER, at_file common_pg.tt_varchar2) IS
 BEGIN
  DELETE FROM srvini
  WHERE       nsrv = an_srv;

  FOR i IN 1 .. at_file.COUNT LOOP
   INSERT INTO srvini
               (nsrv, norder, vtext)
   VALUES      (an_srv, i, at_file(i));
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.set_srvini_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Записывает log файл опросчика в БД
 PROCEDURE set_srvlog_p(an_srv NUMBER, at_file common_pg.tt_varchar2) IS
 BEGIN
  DELETE FROM srvlog
  WHERE       nsrv = an_srv;

  FOR i IN 1 .. at_file.COUNT LOOP
   INSERT INTO srvlog
               (nsrv, norder, vtext)
   VALUES      (an_srv, i, at_file(i));
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20002, 'comsrvdisp_pg.set_srvlog_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает max размер log файла, который может быть записан в БД
 FUNCTION get_sizesrvlog
  RETURN NUMBER IS
 BEGIN
  RETURN NVL(util_pg.getparamvalue_f(62), 0);
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION lock_com_id(an_com_id NUMBER)
  RETURN NUMBER IS
  ln_com_id           NUMBER;
 BEGIN
  SELECT     com_id
  INTO       ln_com_id
  FROM       comports
  WHERE      com_id = an_com_id
  FOR UPDATE NOWAIT;

  RETURN ln_com_id;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN 0;
 END;
------------------------------------------------------------------------------------------------------------------------
