  IF an_type = comsrv_pg.cn_energy9_satec THEN                                                                                                                                  -- Satec
   comsrv_pg.set_halfhour_energy_simple(an_mid, an_erm, an_edm, an_q1m, an_q3m, NULL, NULL, '<Satec>', an_status, ad_date, 1 / 288);
  ELSIF an_type = comsrv_pg.cn_energy9_v29 THEN                                                                                                                       -- Energy-9 v.29
   comsrv_pg.set_halfhour_zxb(an_mid, an_er, an_ed, an_q1, an_q3, an_erm, an_edm, an_q1m, an_q3m, an_metertype, 8, an_status, ad_date);
  ELSE
   comsrv_pg.set_halfhour_meter(an_mid, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_status, an_metertype,
    av_qm, ad_date);
  END IF;
 END;

