   gv_serial_num := av_mtrsn;
  ELSE
   comsrv_pg.set_months_dllmtr(an_mid, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, an_aer, an_aed, an_aq1, an_aq3, an_aq2, an_aq4, an_ber, an_bed, an_bq1,
    an_bq3, an_bq2, an_bq4, an_cer, an_ced, an_cq1, an_cq3, an_cq2, an_cq4, an_der, an_ded, an_dq1, an_dq3, an_dq2, an_dq4, av_mtrsn, an_type, ad_date);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Вставка месячных показаний
 PROCEDURE set_months_dllmtr_m(
 an_mid NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_aerm NUMBER, an_aedm NUMBER, an_aq1m NUMBER,
 an_aq3m NUMBER, an_aq2m NUMBER, an_aq4m NUMBER, an_berm NUMBER, an_bedm NUMBER, an_bq1m NUMBER, an_bq3m NUMBER, an_bq2m NUMBER, an_bq4m NUMBER, an_cerm NUMBER,
 an_cedm NUMBER, an_cq1m NUMBER, an_cq3m NUMBER, an_cq2m NUMBER, an_cq4m NUMBER, an_derm NUMBER, an_dedm NUMBER, an_dq1m NUMBER, an_dq3m NUMBER, an_dq2m NUMBER,
 an_dq4m NUMBER, an_type NUMBER, ad_date DATE
 ) IS
 BEGIN
  IF an_type IN(2, 8, 9, 11, 13, 14) THEN                                          -- CE-304; Mercury-200; Energy-9 v.42; Alpha A1140; Energy-9 v.29; SEB-2A.07
   comsrv_pg.set_months_meter(an_mid, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_aerm, an_aedm, an_aq1m, an_aq3m, an_aq2m, an_aq4m, an_berm, an_bedm,
    an_bq1m, an_bq3m, an_bq2m, an_bq4m, an_cerm, an_cedm, an_cq1m, an_cq3m, an_cq2m, an_cq4m, an_derm, an_dedm, an_dq1m, an_dq3m, an_dq2m, an_dq4m,
    gv_serial_num, 0, ad_date);
  ELSIF an_type = 6 THEN                                                                                                                                -- Satec
   comsrv_pg.set_months_meter(an_mid, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_aerm, an_aedm, an_aq1m, an_aq3m, an_aq2m, an_aq4m, an_berm, an_bedm,
    an_bq1m, an_bq3m, an_bq2m, an_bq4m, an_cerm, an_cedm, an_cq1m, an_cq3m, an_cq2m, an_cq4m, an_derm, an_dedm, an_dq1m, an_dq3m, an_dq2m, an_dq4m, '<Satec>',
    0, ad_date);
  ELSE
   comsrv_pg.set_months_dllmtr_m(an_mid, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_aerm, an_aedm, an_aq1m, an_aq3m, an_aq2m, an_aq4m, an_berm,
    an_bedm, an_bq1m, an_bq3m, an_bq2m, an_bq4m, an_cerm, an_cedm, an_cq1m, an_cq3m, an_cq2m, an_cq4m, an_derm, an_dedm, an_dq1m, an_dq3m, an_dq2m, an_dq4m,
    an_type, ad_date);
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------
    -- Ввод поправок. an_type =1 - Поправка, иначе просто расход с разбивкой на ГН
 PROCEDURE dblink_set_correction(
 an_mid NUMBER, at_datefrom common_pg.tt_varchar2, at_dateto common_pg.tt_varchar2, at_er common_pg.tt_number, at_ed common_pg.tt_number,
 at_q1 common_pg.tt_number, at_q3 common_pg.tt_number, at_type common_pg.tt_number
 ) IS
  cn_roundall CONSTANT NUMBER := 5;
  ln_delete_all       NUMBER DEFAULT 0;
  lt_val              common_pg.tt_number;
 BEGIN
  das_pg.checkhalfhour_without_err;                                                                                                --Это чтоб в halfhour попало

  FOR i IN 1 .. at_datefrom.COUNT LOOP
   IF at_type(i) = 0 THEN
    ln_delete_all := 1;
   ELSE
    ln_delete_all := 0;
   END IF;

   lt_val(1) := ROUND(at_er(i), cn_roundall);
   lt_val(2) := ROUND(at_ed(i), cn_roundall);
   lt_val(3) := ROUND(at_q1(i), cn_roundall);
   lt_val(4) := ROUND(at_q3(i), cn_roundall);

   FOR z IN 1 .. 4 LOOP
    IF lt_val(z) IS NULL THEN
     lt_val(z) := util_pg.cn_random;
    END IF;
   END LOOP;

   indic_pg.setcorrection(an_mid, TO_DATE(at_datefrom(i), 'DD.MM.YYYY HH24:MI:SS'), TO_DATE(at_dateto(i), 'DD.MM.YYYY HH24:MI:SS'), lt_val(1), lt_val(2),
    lt_val(3), NULL, lt_val(4), NULL, 1, ln_delete_all, NULL);
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvdll_pg.dblink_set_correction: an_mid=' || an_mid || ' ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE mark_dllmtrevent(newmid NUMBER, newev_date DATE, newtype NUMBER, FOUND OUT NUMBER, newstate NUMBER) IS
  evtype              NUMBER;
  code                NUMBER DEFAULT 0;
  MESSAGE             VARCHAR2(2000);
 BEGIN
  IF newtype = 1 THEN                                                                      -- newtype определяет тип счетчика: 1 -- отладка; 2 -- СЕ-304 и т.д.
   MESSAGE := ' Событие DLL счетчика: ' || newstate;                                                                         -- newstate определяет тип события
  END IF;

  IF newtype = 2 THEN                                                                                                                                  -- CE-304
   MESSAGE := ' Событие CE-304: ' || newstate;                                                                               -- newstate определяет тип события
  END IF;

  IF newtype = 3 THEN                                                                            -- newtype определяет тип счетчика: 3 -- DB Link Oracle Khartep
   MESSAGE := ' Событие DB Link Oracle Khartep: ' || newstate;                                                               -- newstate определяет тип события
  END IF;

  IF newtype = 4 THEN                                                                              -- newtype определяет тип счетчика: 4 -- DCOM Energy Vision 2
   MESSAGE := ' Событие Ev2: код ' || MOD(newstate, 65536) || ', параметр ' || TRUNC(newstate / 65536);
  END IF;

  IF newtype = 5 THEN                                                                               -- newtype определяет тип счетчика: 5 -- DB Link Oracle INET
   MESSAGE := ' Событие DB Link Oracle INET: ' || newstate;                                                                  -- newstate определяет тип события
  END IF;

  IF newtype = 11 THEN                                                                                     -- newtype определяет тип счетчика: 11 -- Alpha A1140
--   MESSAGE := ' Событие Alpha A1140: ' || newstate;   -- newstate определяет тип события
   comsrv_pg.mark_a1140event(newmid, newev_date, newstate, FOUND);
   RETURN;
  END IF;

  IF newtype = 14 THEN                                                                                       -- newtype определяет тип счетчика: 14 -- СЭБ 2A.07
--   MESSAGE := ' Событие СЭБ 2A.07: ' || newstate;   -- newstate определяет тип события
   comsrv_pg.mark_seb2a07event(newmid, newev_date, newstate, FOUND);
   RETURN;
  END IF;

  SELECT evtype
  INTO   evtype
  FROM   ea_events
  WHERE  mid = newmid AND evdate = newev_date AND evtype = newstate;

  FOUND := 1;
 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   INSERT INTO journal
               (date_time, mid, state_cod, state_descr)
   VALUES      (newev_date, newmid, code, MESSAGE);

   INSERT INTO ea_events
               (mid, evdate, evtype)
   VALUES      (newmid, newev_date, newstate);

   FOUND := 0;
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrvdll_pg.mark_dllmtrevent: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись журнала
 PROCEDURE set_journal_dllmtr(an_mid NUMBER, an_state_cod NUMBER, av_state_descr VARCHAR2, an_event NUMBER, av_code VARCHAR2, ad_date DATE) IS
  ln_tmp              NUMBER;
 BEGIN
  --Если кода нет в справочнике то заменяем на NULL
  SELECT DECODE(COUNT(*), 1, an_event, NULL)
  INTO   ln_tmp
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   metereventsdict
                WHERE  nevent = an_event);

  ln_tmp := admin_pg.ins_journal_p(ad_date, an_mid, an_state_cod, av_state_descr, ln_tmp, av_code);

  UPDATE last_save
  SET journal = ad_date
  WHERE  mid = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
--   raise_application_error (-20001, 'comsrvdll_pg.set_journal_dllmtr: '|| SQLERRM (SQLCODE));
   raise_application_error(-20001,
       'comsrvdll_pg.set_journal_dllmtr: mid='
    || an_mid
    || 'date='
    || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi:ss')
    || ' cod='
    || an_state_cod
    || ' an_event='
    || an_event
    || ' code='
    || av_code
    || ' descr='
    || av_state_descr
    || ' '
    || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Запись обводников
 PROCEDURE dblink_set_ov(an_switch NUMBER, at_datefrom common_pg.tt_varchar2, at_dateto common_pg.tt_varchar2, at_mid common_pg.tt_number) IS
  cn_khartep_link CONSTANT NUMBER := 1002;
  cn_anonim_link CONSTANT NUMBER := 1004;
  cn_evision2_link CONSTANT NUMBER := 1005;
  ln_mid              NUMBER;
  ld_from             DATE;
  ld_to               DATE;
  ln_commonswitch     NUMBER;
  ln_main             NUMBER := 1;
  ln_parentmid        NUMBER;
  ln_i                NUMBER;
  ln_mid1             NUMBER;
  ln_mid2             NUMBER;
 BEGIN
/*  FOR i IN 1 .. at_datefrom.COUNT LOOP
   INSERT INTO priority1
               (mid, dstart, dend, norder, ni, dsys, nswitch
               )
        VALUES (at_mid (i), TO_DATE (at_datefrom (i), 'DD.MM.YYYY HH24:MI:SS'), TO_DATE (at_dateto (i), 'DD.MM.YYYY HH24:MI:SS'), 0, i, SYSDATE, at_mid (i)
               );
  END LOOP;

  COMMIT;*/
  FOR i IN 1 .. at_datefrom.COUNT LOOP
   IF at_mid(i) = cn_idpriority THEN                                                                         --для Днепра по кривому тянем изменения приоритета
    IF util_pg.get_customer_id = 45 THEN                                                                                                                --Днепр
     IF i = 1 THEN
      SELECT MAX(p.PARENT)
      INTO   ln_parentmid
      FROM   points p, points pa, feeders f, feeders fa
      WHERE  p.mid = an_switch AND p.ind = 3 AND p.PARENT = pa.mid AND pa.ind = 4 AND p.mid = f.mid AND pa.mid = fa.mid AND fa.ncalcpointtype IS NULL
             AND f.nmainpoint > 0;

      --трем все на первом шаге
      DELETE FROM priority
      WHERE       mid IN(SELECT mid
                         FROM   points
                         WHERE  PARENT = ln_parentmid) AND dstart >= cd_transmin;
     END IF;

     ld_from := TO_DATE(at_datefrom(i), 'DD.MM.YYYY HH24:MI:SS');
     ld_to := NVL(TO_DATE(at_dateto(i), 'DD.MM.YYYY HH24:MI:SS'), cd_transnull);

     IF ln_parentmid > 0 AND ld_from > cd_transmin AND ld_to <= cd_transnull THEN
      ln_i := 0;
      --Для Днепра поднимаем по-своему (меняем основной и дубль (индикация по связному номеру) если есть местами а все остальные без изменений)
      ln_mid1 := NULL;
      ln_mid2 := NULL;

      FOR lc IN (SELECT   p.mid, DECODE(SIGN(p2.mid), 1, DECODE(f.canal, 1, 2, 2, 1)) replacemids
                 FROM     points p,
                          feeders f,
                          (SELECT DISTINCT p1.mid
                           FROM            points p1, chanpoint cp, channels c
                           WHERE           p1.PARENT = ln_parentmid AND p1.mid = cp.mid AND cp.cid = c.cid AND c.protocol_id = cn_evision2_link) p2
                 WHERE    p.PARENT = ln_parentmid AND p.mid = f.mid AND p.mid = p2.mid(+)
                 ORDER BY p.norder, p.NAME, p.mid) LOOP
       IF lc.replacemids = 1 THEN
        ln_mid1 := lc.mid;
       ELSIF lc.replacemids = 2 THEN
        ln_mid2 := lc.mid;
       END IF;

       INSERT INTO priority
                   (mid, dstart, dend, norder)
       VALUES      (lc.mid, ld_from, ld_to, ln_i);

       ln_i := ln_i + 1;
      END LOOP;

      IF ln_mid1 > 0 AND ln_mid2 > 0 THEN
       UPDATE priority
       SET mid = DECODE(mid, ln_mid1, ln_mid2, ln_mid2, ln_mid1, mid)
       WHERE  mid IN(ln_mid1, ln_mid2) AND dstart = ld_from;
      END IF;
     END IF;
    END IF;
   ELSE                                                                                                            -- !!! Только здесь настоящие переключения ОВ
    IF ln_commonswitch IS NULL THEN
     ln_commonswitch := util_pg.getsupplypoint(an_switch);

     IF ln_commonswitch <> an_switch THEN
      SELECT COUNT(*)
      INTO   ln_main
      FROM   feeders
      WHERE  mid = an_switch AND nmainpoint IS NULL;
     END IF;

     IF ln_main = 0 THEN                                                                                                      --Работаем только по по главным ОВ
      RETURN;
     END IF;
    END IF;

/*   UPDATE switchessrv1
      SET descape = TO_DATE (at_dateto (i), 'DD.MM.YYYY HH24:MI:SS'),
          mid = at_mid (i)
    WHERE nswitch = an_switch AND dswitch = TO_DATE (at_datefrom (i), 'DD.MM.YYYY HH24:MI:SS');

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO switchessrv1
                (nswitch, dswitch, descape, mid
                )
         VALUES (an_switch, TO_DATE (at_datefrom (i), 'DD.MM.YYYY HH24:MI:SS'), TO_DATE (at_dateto (i), 'DD.MM.YYYY HH24:MI:SS'), at_mid (i)
                );
   END IF;*/
    ld_to := TO_DATE(at_dateto(i), 'DD.MM.YYYY HH24:MI:SS');

    IF ld_to = cd_transnull THEN
     ld_to := NULL;
    END IF;

    IF at_mid(i) = cn_idnoswitch THEN                                                                          --Признак отсутствия данных для главных счетчиков
     DELETE FROM switchessrv
     WHERE       nswitch = ln_commonswitch AND mid <> cn_idnoswitch;

     INSERT INTO switchessrv
                 (nswitch, dswitch, descape, mid)
      SELECT ln_commonswitch, TO_DATE(at_datefrom(i), 'DD.MM.YYYY HH24:MI:SS'), ld_to, cn_idnoswitch
      FROM   DUAL
      WHERE  NOT EXISTS(SELECT *
                        FROM   switchessrv
                        WHERE  nswitch = ln_commonswitch AND mid = cn_idnoswitch);

     EXIT;
    ELSE
     SELECT DECODE(COUNT(DISTINCT f.mid), 1, MAX(f.mid))
     INTO   ln_mid
     FROM   chanpoint cp, channels c, chanpoint cp1, feeders f
     WHERE  cp.mid = an_switch AND cp.cid = c.cid(+) AND c.protocol_id IN(cn_khartep_link, cn_anonim_link) AND cp.cid = cp1.cid AND cp1.mid = f.mid
            AND DECODE(cp1.nuserescanal, 1, f.rescanal, f.canal) = ABS(at_mid(i)) AND f.mid <> an_switch;

     IF ln_mid IS NULL THEN
      SELECT DECODE(COUNT(DISTINCT f.mid), 1, MAX(f.mid))
      INTO   ln_mid
      FROM   chanpoint cp, channels c, chanpoint cp1, feeders f, feeders f1
      WHERE  cp.mid = an_switch AND f1.mid = an_switch AND DECODE(cp.nuserescanal, 1, f1.rescanal, f1.canal) = 1 AND cp.cid = c.cid(+)
             AND c.protocol_id = cn_evision2_link AND cp.cid = cp1.cid AND cp1.mid = f.mid AND DECODE(cp1.nuserescanal, 1, f.rescanal, f.canal) = 1
             AND f.vinfo = TO_CHAR(ABS(at_mid(i))) AND f.mid <> an_switch;
     END IF;
    END IF;

    IF ln_mid > 0 THEN
     BEGIN
      INSERT INTO switchessrv
                  (nswitch, dswitch, descape, mid)
      VALUES      (ln_commonswitch, TO_DATE(at_datefrom(i), 'DD.MM.YYYY HH24:MI:SS'), ld_to, ln_mid);
     EXCEPTION
      WHEN DUP_VAL_ON_INDEX THEN
       UPDATE switchessrv
       SET descape = ld_to,
           mid = ln_mid
       WHERE  nswitch = ln_commonswitch AND dswitch = TO_DATE(at_datefrom(i), 'DD.MM.YYYY HH24:MI:SS');
      WHEN OTHERS THEN
       RAISE;
     END;
    END IF;
   END IF;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvdll_pg.dblink_set_ov: an_switch=' || an_switch || ' ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Запись остальных показаний
 PROCEDURE dblink_set_othersbill(
 an_mid NUMBER, ad_cdatetime common_pg.tt_varchar2, an_type common_pg.tt_number, an_er common_pg.tt_number, an_ed common_pg.tt_number,
 an_q1 common_pg.tt_number, an_q3 common_pg.tt_number, an_q2 common_pg.tt_number, an_q4 common_pg.tt_number, an_erm common_pg.tt_number,
 an_edm common_pg.tt_number, an_q1m common_pg.tt_number, an_q3m common_pg.tt_number, an_q2m common_pg.tt_number, an_q4m common_pg.tt_number
 ) IS
  lv_mtrsn            VARCHAR2(128);
  ln_kc               NUMBER;
  ln_source           NUMBER;
 BEGIN
  IF ad_cdatetime.COUNT > 0 THEN
   SELECT MAX(mtrsn)
   INTO   lv_mtrsn
   FROM   meters
   WHERE  mid = an_mid AND entype = 7;
  ELSE
   RETURN;
  END IF;

  SELECT NVL(MAX(kc), 1)
  INTO   ln_kc
  FROM   feeders
  WHERE  mid = an_mid;

  FOR i IN 1 .. ad_cdatetime.COUNT LOOP
   IF NVL(an_type(i), 0) NOT IN(1, 2, 3, 4) THEN
    EXIT;
   END IF;

   ln_source := an_type(i) + 4;                                                                                                                 --Так получается
   set_othersbill_one(an_mid, an_er(i), an_ed(i), an_q1(i), an_q3(i), an_q2(i), an_q4(i), an_erm(i), an_edm(i), an_q1m(i), an_q3m(i), an_q2m(i), an_q4m(i),
    lv_mtrsn, ln_kc, TO_DATE(ad_cdatetime(i), 'DD.MM.YYYY HH24:MI:SS'), ln_source);
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvdll_pg.dblink_set_othersbill: an_mid=' || an_mid || ' ' || SQLERRM(SQLCODE));
 END;

