------------------------------------------------------------------------------------------------------------------------
--Чтение ГН
 PROCEDURE dblink_get_halfhour(
 an_mid NUMBER, ad_cdatetime OUT common_pg.tt_varchar2, an_er OUT common_pg.tt_number, an_ed OUT common_pg.tt_number, an_q1 OUT common_pg.tt_number,
 an_q3 OUT common_pg.tt_number, an_q2 OUT common_pg.tt_number, an_q4 OUT common_pg.tt_number, an_erm OUT common_pg.tt_number, an_edm OUT common_pg.tt_number,
 an_q1m OUT common_pg.tt_number, an_q3m OUT common_pg.tt_number, an_q2m OUT common_pg.tt_number, an_q4m OUT common_pg.tt_number,
 an_status OUT common_pg.tt_number, an_metertype OUT common_pg.tt_number, av_qm OUT common_pg.tt_varchar2, ad_date DATE, ad_change DATE
 ) IS
  i                   NUMBER DEFAULT 1;
  ln_withov           NUMBER := util_pg.getparamvalue_f(49);
  ln_primaty          NUMBER := util_pg.getparamvalue_f(55);
 BEGIN
  IF ad_change IS NOT NULL THEN
   FOR lc IN (SELECT   util_pg.to_unlocaltime(date_time, nsource) cdt, SUM(er) er, SUM(ed) ed, SUM(q1) q1, SUM(q3) q3, SUM(q2) q2, SUM(q4) q4, MAX(erm) erm,
                       MAX(edm) edm, MAX(q1m) q1m, MAX(q3m) q3m, MAX(q2m) q2m, MAX(q4m) q4m, MAX(status) status, MAX(nmetertype) nmetertype, sumqm(vqm) vqm,
                       MAX(nkc) nkc
              FROM     halfhour
              WHERE    mid = an_mid
                       AND date_time IN(
                           SELECT date_time
                           FROM   halfhourold
                           WHERE  mid = an_mid AND date_time > ad_date - 1 / 24 AND util_pg.to_unlocaltime(date_time, nsource) > ad_date
                           UNION ALL
                           SELECT date_time
                           FROM   halfhourold
                           WHERE  mid = an_mid AND denter > ad_change - cn_enter_shift)
                       AND(ln_withov = 1 OR NOT(nsource BETWEEN 20 AND 49))
              GROUP BY util_pg.to_unlocaltime(date_time, nsource)
              ORDER BY 1) LOOP
    IF ln_primaty = 1 THEN
     an_er(i) := lc.er / lc.nkc;
     an_ed(i) := lc.ed / lc.nkc;
     an_q1(i) := lc.q1 / lc.nkc;
     an_q3(i) := lc.q3 / lc.nkc;
     an_q2(i) := lc.q2 / lc.nkc;
     an_q4(i) := lc.q4 / lc.nkc;
    ELSE
     an_er(i) := lc.er;
     an_ed(i) := lc.ed;
     an_q1(i) := lc.q1;
     an_q3(i) := lc.q3;
     an_q2(i) := lc.q2;
     an_q4(i) := lc.q4;
    END IF;

    an_erm(i) := lc.erm;
    an_edm(i) := lc.edm;
    an_q1m(i) := lc.q1m;
    an_q3m(i) := lc.q3m;
    an_q2m(i) := lc.q2m;
    an_q4m(i) := lc.q4m;
    an_status(i) := lc.status;
    ad_cdatetime(i) := TO_CHAR(lc.cdt, 'dd.mm.yyyy hh24:mi');
    an_metertype(i) := lc.nmetertype;
    av_qm(i) := lc.vqm;
    i := i + 1;

    IF i > cn_maxrowcounth THEN
     EXIT;
    END IF;
   END LOOP;
  ELSE                                                                                                                                                 ---------
   FOR lc IN (SELECT   util_pg.to_unlocaltime(date_time, nsource) cdt, SUM(er) er, SUM(ed) ed, SUM(q1) q1, SUM(q3) q3, SUM(q2) q2, SUM(q4) q4, MAX(erm) erm,
                       MAX(edm) edm, MAX(q1m) q1m, MAX(q3m) q3m, MAX(q2m) q2m, MAX(q4m) q4m, MAX(status) status, MAX(nmetertype) nmetertype, sumqm(vqm) vqm,
                       MAX(nkc) nkc
              FROM     halfhour
              WHERE    mid = an_mid AND date_time > ad_date - 1 / 24 AND util_pg.to_unlocaltime(date_time, nsource) > ad_date
                       AND NOT(nsource BETWEEN 20 AND 49)
              GROUP BY util_pg.to_unlocaltime(date_time, nsource)
              ORDER BY 1) LOOP
    IF ln_primaty = 1 THEN
     an_er(i) := lc.er / lc.nkc;
     an_ed(i) := lc.ed / lc.nkc;
     an_q1(i) := lc.q1 / lc.nkc;
     an_q3(i) := lc.q3 / lc.nkc;
     an_q2(i) := lc.q2 / lc.nkc;
     an_q4(i) := lc.q4 / lc.nkc;
    ELSE
     an_er(i) := lc.er;
     an_ed(i) := lc.ed;
     an_q1(i) := lc.q1;
     an_q3(i) := lc.q3;
     an_q2(i) := lc.q2;
     an_q4(i) := lc.q4;
    END IF;

    an_erm(i) := lc.erm;
    an_edm(i) := lc.edm;
    an_q1m(i) := lc.q1m;
    an_q3m(i) := lc.q3m;
    an_q2m(i) := lc.q2m;
    an_q4m(i) := lc.q4m;
    an_status(i) := lc.status;
    ad_cdatetime(i) := TO_CHAR(lc.cdt, 'dd.mm.yyyy hh24:mi');
    an_metertype(i) := lc.nmetertype;
    av_qm(i) := lc.vqm;
    i := i + 1;

    IF i > cn_maxrowcounth THEN
     EXIT;
    END IF;
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrvdll_pg.dblink_get_halfhour: ' || SQLERRM(SQLCODE));
 END;

