 --Чтение журнала
 PROCEDURE dblink_get_journal(
 an_mid NUMBER, at_datetime OUT common_pg.tt_varchar2, at_state_cod OUT common_pg.tt_number, at_state_descr OUT common_pg.tt_varchar2,
 at_event OUT common_pg.tt_number, at_code OUT common_pg.tt_varchar2, ad_date DATE
 ) IS
  i                   NUMBER DEFAULT 1;
 BEGIN
  FOR lc IN (SELECT   date_time, state_cod, state_descr, nevent, vcode
             FROM     journal
             WHERE    mid = an_mid AND date_time > ad_date
             ORDER BY mid, date_time) LOOP
   at_datetime(i) := TO_CHAR(lc.date_time, 'dd.mm.yyyy hh24:mi:ss');
   at_state_cod(i) := lc.state_cod;
   at_state_descr(i) := SUBSTR(lc.state_descr, 1, 510);
   at_event(i) := lc.nevent;
   at_code(i) := SUBSTR(lc.vcode, 1, 126);
   i := i + 1;

   IF i > cn_maxrowcountj THEN
    EXIT;
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
------------------------------------------------------------------------------------------------------------------------
 --Чтение обводников
 PROCEDURE dblink_get_ov(an_switch NUMBER, at_datefrom OUT common_pg.tt_varchar2, at_dateto OUT common_pg.tt_varchar2, at_mid OUT common_pg.tt_number) IS
  ln_tmp              NUMBER;
  i                   NUMBER DEFAULT 1;
  ld_sys              DATE DEFAULT SYSDATE;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_tmp
  FROM   feeders
  WHERE  mid = an_switch AND nswitch = 1;                                                                                                --Работае только по OV

  IF ln_tmp = 0 THEN
   RETURN;
  END IF;

  FOR lc IN (SELECT   dswitch, NVL(descape, cd_transnull) descape, mid
             FROM     switches s
             WHERE    nswitch = an_switch AND dswitch > cd_transmin
             ORDER BY 1 DESC) LOOP
   at_datefrom(i) := TO_CHAR(lc.dswitch, 'DD.MM.YYYY HH24:MI:SS');
   at_dateto(i) := TO_CHAR(lc.descape, 'DD.MM.YYYY HH24:MI:SS');
   at_mid(i) := lc.mid;
   i := i + 1;

   IF i > cn_maxrowcountj THEN
    EXIT;
   END IF;
  END LOOP;

  IF i = 1 THEN
   at_datefrom(i) := TO_CHAR(ld_sys, 'DD.MM.YYYY HH24:MI:SS');
   at_dateto(i) := TO_CHAR(ld_sys, 'DD.MM.YYYY HH24:MI:SS');
   at_mid(i) := cn_idnoswitch;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Чтение остальных показаний
 PROCEDURE dblink_get_othersbill(
 an_mid NUMBER, ad_cdatetime OUT common_pg.tt_varchar2, an_type OUT common_pg.tt_number, an_er OUT common_pg.tt_number, an_ed OUT common_pg.tt_number,
 an_q1 OUT common_pg.tt_number, an_q3 OUT common_pg.tt_number, an_q2 OUT common_pg.tt_number, an_q4 OUT common_pg.tt_number, an_erm OUT common_pg.tt_number,
 an_edm OUT common_pg.tt_number, an_q1m OUT common_pg.tt_number, an_q3m OUT common_pg.tt_number, an_q2m OUT common_pg.tt_number, an_q4m OUT common_pg.tt_number
 ) IS
  i                   NUMBER DEFAULT 1;
 BEGIN
  FOR lc IN (SELECT   1 ntype, dswitch dat, erm, edm, q1m, q2m, q3m, q4m, DECODE(1, 2, 1, NULL) er, DECODE(1, 2, 1, NULL) ed, DECODE(1, 2, 1, NULL) q1,
                      DECODE(1, 2, 1, NULL) q2, DECODE(1, 2, 1, NULL) q3, DECODE(1, 2, 1, NULL) q4
             FROM     switches s
             WHERE    nswitch = an_mid AND dswitch > cd_transmin
             UNION ALL
             SELECT   2 ntype, descape dat, erme erm, edme edm, q1me q1m, q2me q2m, q3me q3m, q4me q4m, DECODE(1, 2, 1, NULL) er, DECODE(1, 2, 1, NULL) ed,
                      DECODE(1, 2, 1, NULL) q1, DECODE(1, 2, 1, NULL) q2, DECODE(1, 2, 1, NULL) q3, DECODE(1, 2, 1, NULL) q4
             FROM     switches s
             WHERE    nswitch = an_mid AND dswitch > cd_transmin AND descape < cd_transnull
             UNION ALL
             SELECT   DECODE(nsource, 7, 3, 4) ntype, date_time dat, erm, edm, q1m, q2m, q3m, q4m, er, ed, q1, q2, q3, q4
             FROM     billorg s
             WHERE    mid = an_mid AND date_time > cd_transmin AND nsource IN(7, 8)
             ORDER BY 2 DESC) LOOP
   ad_cdatetime(i) := TO_CHAR(lc.dat, 'DD.MM.YYYY HH24:MI:SS');
   an_type(i) := lc.ntype;
   an_er(i) := lc.er;
   an_ed(i) := lc.ed;
   an_q1(i) := lc.q1;
   an_q2(i) := lc.q2;
   an_q3(i) := lc.q3;
   an_q4(i) := lc.q4;
   an_erm(i) := lc.erm;
   an_edm(i) := lc.edm;
   an_q1m(i) := lc.q1m;
   an_q2m(i) := lc.q2m;
   an_q3m(i) := lc.q3m;
   an_q4m(i) := lc.q4m;
   i := i + 1;

   IF i > cn_maxrowcountj - 1 THEN
    EXIT;
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Вставка суточных расходов (Єнергия меркурий облик и.т.д. только расход)
 PROCEDURE set_othersbill_one(
 an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER,
 an_q2m NUMBER, an_q4m NUMBER, av_mtrsn VARCHAR2, an_kc NUMBER, ad_date DATE, an_source NUMBER
 ) IS
  ln_er               NUMBER DEFAULT an_er;
  ln_ed               NUMBER DEFAULT an_ed;
  ln_q1               NUMBER DEFAULT an_q1;
  ln_q3               NUMBER DEFAULT an_q3;
  ln_q2               NUMBER DEFAULT an_q2;
  ln_q4               NUMBER DEFAULT an_q4;
  ln_erm              NUMBER DEFAULT an_erm;
  ln_edm              NUMBER DEFAULT an_edm;
  ln_q1m              NUMBER DEFAULT an_q1m;
  ln_q3m              NUMBER DEFAULT an_q3m;
  ln_q2m              NUMBER DEFAULT an_q2m;
  ln_q4m              NUMBER DEFAULT an_q4m;
 BEGIN
  util_pg.chdr(an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4);
  util_pg.chdr(an_mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);

  UPDATE billorg
  SET (er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, er_mtrsn, ed_mtrsn, q1_mtrsn, q3_mtrsn, q2_mtrsn, q4_mtrsn, er_kc, ed_kc, q1_kc, q3_kc, q2_kc,
       q4_kc) =
       (SELECT ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn,
               av_mtrsn, an_kc, an_kc, an_kc, an_kc, an_kc, an_kc
        FROM   DUAL)
  WHERE  mid = an_mid AND date_time = ad_date AND nsource = an_source;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO billorg
               (mid, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, date_time, SOURCE, nsource, er_mtrsn, ed_mtrsn, q1_mtrsn, q3_mtrsn, q2_mtrsn,
                q4_mtrsn, er_kc, ed_kc, q1_kc, q3_kc, q2_kc, q4_kc)
   VALUES      (an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m, ad_date, 'КС', an_source, av_mtrsn, av_mtrsn,
                av_mtrsn, av_mtrsn, av_mtrsn, av_mtrsn, an_kc, an_kc, an_kc, an_kc, an_kc, an_kc);
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrv_pg.set_bill_eom: ' || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END;
