CREATE OR REPLACE 
PACKAGE BODY comsrverr_pg IS
------------------------------------------------------------------------------------------------------------------------
   -- Содержит текcт ошибок.
   -- дата создания 19/11/2004 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 --Возвращает всю информацию по ошибке (возвращает ид события)
 FUNCTION get_metererrinfo (an_metertype NUMBER, an_event_hi NUMBER, an_event_lo NUMBER, av_code IN OUT VARCHAR2, an_state OUT NUMBER, av_descr OUT VARCHAR2,
 an_lock OUT NUMBER
 )
  RETURN NUMBER IS
 BEGIN
  IF an_metertype = comsrv_pg.cn_sl_7000 THEN   --SL_7000
   av_code := an_event_lo || '-' || an_event_hi;

   FOR lc IN (SELECT nevent, nmetertype, neventclass, neventcode, veventtext, nlock, nvalidity
                FROM metereventsdict
               WHERE nmetertype = comsrv_pg.cn_sl_7000 AND neventclass = 1 AND neventcode = an_event_hi + 1) LOOP
    an_state := NVL (lc.nvalidity, 0);
    an_lock := lc.nlock;

    IF an_event_hi IN (23, 24, 25, 38, 39, 40) THEN
     FOR lc1 IN (SELECT veventtext
                   FROM metereventsdict
                  WHERE nmetertype = comsrv_pg.cn_sl_7000 AND neventclass = 2 AND neventcode = an_event_lo + 1) LOOP
      av_descr := ': ' || lc1.veventtext;
      EXIT;
     END LOOP;

     av_descr := NVL (av_descr, ' Доп. параметр: ' || (an_event_lo + 1));
    END IF;

    RETURN lc.nevent;
   END LOOP;
  ELSIF an_metertype = comsrv_pg.cn_argo THEN   --ARGO
   av_code := an_event_lo || '-' || an_event_hi;

   FOR lc IN (SELECT nevent, nmetertype, neventclass, neventcode, veventtext, nlock, nvalidity
                FROM metereventsdict
               WHERE nmetertype = an_metertype AND neventclass = 1 AND neventcode = an_event_lo * 256 + DECODE (an_event_lo, 0, 0, 1, 0, 4, 0, an_event_hi)) LOOP
    an_state := NVL (lc.nvalidity, 0);
    an_lock := lc.nlock;
    RETURN lc.nevent;
   END LOOP;
  ELSIF an_metertype = comsrv_pg.cn_lg_zxd THEN   --LG ZxD
   av_code := an_event_hi;

   FOR lc IN (SELECT nevent, nmetertype, neventclass, neventcode, veventtext, nlock, nvalidity
                FROM metereventsdict
               WHERE nmetertype = an_metertype AND neventclass = 1 AND neventcode = an_event_hi) LOOP
    an_state := NVL (lc.nvalidity, 0);
    an_lock := lc.nlock;
    RETURN lc.nevent;
   END LOOP;
  END IF;

  av_code := '';
  RETURN NULL;
 END;

------------------------------------------------------------------------------------------------------------------------

 --Возвращает текст ошибки по коду
 FUNCTION errortext (an_code NUMBER, an_type NUMBER)
  RETURN VARCHAR2 IS
  cn_max   CONSTANT NUMBER := 149;
 BEGIN
  IF an_type = comsrv_pg.cn_uspd_64 THEN   --УСД КМ
   IF an_code = 0 THEN
    RETURN 'Штатный режим';
   ELSIF (TRUNC (an_code / 1000) BETWEEN 0 AND 255) AND (MOD (an_code, 1000) BETWEEN 0 AND 255) THEN
    FOR lc IN (SELECT nevent, nmetertype, neventclass, neventcode, veventtext, nlock, nvalidity
                 FROM metereventsdict
                WHERE nmetertype = comsrv_pg.cn_uspd_64 AND neventclass = 1 AND neventcode = TRUNC (an_code / 1000)) LOOP
     FOR lc1 IN (SELECT nevent, nmetertype, neventclass, neventcode, veventtext, nlock, nvalidity
                   FROM metereventsdict
                  WHERE nmetertype = comsrv_pg.cn_uspd_64 AND neventclass = 2 AND neventcode = MOD (an_code, 1000)) LOOP
      RETURN SUBSTR ('Ошибка: ' || lc.veventtext || CHR (13) || CHR (10) || 'Состояние: ' || lc1.veventtext, 1, cn_max);
     END LOOP;

     EXIT;
    END LOOP;
   END IF;
  END IF;

  RETURN 'Код не распознан';
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Блокировка сообщений счетчиков
 PROCEDURE get_metertype (acur_t OUT common_pg.tcur) IS   --Типы счетчиков
 BEGIN
  OPEN acur_t FOR
   SELECT   nmetertype ntype, vname
       FROM metertype m
      WHERE EXISTS (SELECT *
                      FROM metereventsdict
                     WHERE nmetertype = m.nmetertype)
   ORDER BY 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Блокировка сообщений счетчиков
 PROCEDURE get_valid (acur_t OUT common_pg.tcur) IS   --Достоверности
 BEGIN
  OPEN acur_t FOR
   SELECT   2 nvalid, 'Недостоверно' vname
       FROM DUAL
   UNION ALL
   SELECT   1 nvalid, 'Под вопросом' vname
       FROM DUAL
   UNION ALL
   SELECT   0 nvalid, 'Без изменений' vname
       FROM DUAL
   ORDER BY 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_metereventsdict (an_metertype NUMBER, an_sort NUMBER, acur_t OUT common_pg.tcur) IS   --Сообщения счетчиков
  lv_sql                 VARCHAR2 (4000);
  cn_colcount   CONSTANT NUMBER          := 6;
 BEGIN
  -- lv_sql := 'SELECT neventclass, neventcode, veventtext, nlock, decode(NVALIDITY,1,''?'',2,''Н'') NVALIDITY, nmetertype, nevent FROM metereventsdict ';
  lv_sql := 'SELECT neventclass, neventcode, veventtext, nlock nlock, NVALIDITY NVALID , nmetertype, nevent FROM metereventsdict ';

  --Ограничение по типу
  IF an_metertype <> 0 THEN
   lv_sql := lv_sql || ' WHERE nmetertype = ' || an_metertype;
  END IF;

  --Сортировка
  lv_sql := lv_sql || ' ORDER BY ';

  IF ABS (an_sort) > 0 AND ABS (an_sort) <= cn_colcount THEN
   lv_sql := lv_sql || ABS (an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' desc';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1,2';

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_meterstatusbitdict (an_metertype NUMBER, an_sort NUMBER, acur_t OUT common_pg.tcur) IS   --Сообщения счетчиков
  lv_sql                 VARCHAR2 (4000);
  cn_colcount   CONSTANT NUMBER          := 4;
 BEGIN
  lv_sql :=
   'SELECT d.NBIT, d.VEVENTTEXT,
   d.nvalidity, d.NQM, e1.VEVENTTEXT VEVENTTEXT1,e2.VEVENTTEXT VEVENTTEXT2,d.nevent0,d.nevent1,d.nmetertype
   FROM METERSTATUSBITDICT d,METEREVENTSDICT e1,METEREVENTSDICT e2';
  lv_sql := lv_sql || ' WHERE d.nevent0=e1.nevent(+) and d.nevent1=e2.nevent(+) ';

  --Ограничение по типу
  IF an_metertype <> 0 THEN
   lv_sql := lv_sql || ' AND d.nmetertype = ' || an_metertype;
  END IF;

  --Сортировка
  lv_sql := lv_sql || ' ORDER BY ';

  IF ABS (an_sort) > 0 AND ABS (an_sort) <= cn_colcount THEN
   lv_sql := lv_sql || ABS (an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' desc';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' ' || (cn_colcount + 1) || ',1';

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE upd_metereventsdict (an_metertype NUMBER, an_eventclass NUMBER, an_eventcode NUMBER, an_lock NUMBER, an_valid NUMBER) IS   --Обновление блокировки
 BEGIN
  UPDATE metereventsdict
     SET nlock = an_lock,
         nvalidity = an_valid
   WHERE nmetertype = an_metertype AND neventclass = an_eventclass AND neventcode = an_eventcode;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE upd_meterstatusbitdict (an_nmetertype NUMBER, an_nbit NUMBER, an_valid NUMBER, an_NQM NUMBER) IS   --Обновление достоверности
 BEGIN
  UPDATE meterstatusbitdict
     SET nvalidity = an_valid,
         NQM=an_NQM
   WHERE nmetertype = an_nmetertype AND nbit = an_nbit;
 END;
-------------------------------------------------------------------------------------------
PROCEDURE get_NQM (acur_t OUT common_pg.tcur) IS   --Биты метки качества
 BEGIN
  OPEN acur_t FOR
   SELECT   0 nNQM, 'Не изменять' nname
       FROM DUAL
   UNION ALL
   SELECT   2 nNQM, 'Переполнение' nname
       FROM DUAL
   UNION ALL
   SELECT   3 nNQM, 'Выход за границы' nname
       FROM DUAL  
   UNION ALL
   SELECT   4 nNQM, 'Нарушение калибровки источника' nname
       FROM DUAL
   UNION ALL
   SELECT   5 nNQM, 'Дребезг сигнала' nname
       FROM DUAL 
   UNION ALL
   SELECT   6 nNQM, 'Сбой' nname
       FROM DUAL
   UNION ALL
   SELECT   7 nNQM, 'Устаревшие данные' nname
       FROM DUAL
   UNION ALL
   SELECT   8 nNQM, 'Неустойчивость (противоречивость)' nname
       FROM DUAL
   UNION ALL
   SELECT   9 nNQM, 'Неточность' nname
       FROM DUAL
   ORDER BY 1;  
 END;
 -------------------------------------------------------------------------------------------
END;
/


