 -- Убирает лишнее (нули в 4 часе) в строке макетов 30817 и 30917 при переходе на весну . an_makettype =2 - 30917, иначе 30817
 FUNCTION skip_0(av_str VARCHAR2, an_makettype NUMBER DEFAULT 1)
  RETURN VARCHAR2 IS
  cv_sep     CONSTANT VARCHAR2(8) := ':';
  lv_ret              VARCHAR2(4000) := av_str;
  a1                  NUMBER;
  a2                  NUMBER;
  k                   NUMBER := 1;
 BEGIN
  IF an_makettype = 2 THEN                                                                                                             --48 значений типа 30917
   k := 2 * k;
  END IF;

  a1 := INSTR(lv_ret, cv_sep, 1, 2 + 3 * k);
  a2 := INSTR(lv_ret, cv_sep, 1, 2 + 4 * k);

  IF a1 > 0 AND a2 > 0 THEN
   lv_ret := SUBSTR(lv_ret, 1, a1 - 1) || cv_sep || SUBSTR(lv_ret, a2 + 1);
  ELSIF a1 > 0 THEN
   lv_ret := SUBSTR(lv_ret, 1, a1 - 1) || cv_sep;
  END IF;

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Перенос 24-го часа (в макете 30817) и 49-й и 50-й получасовки (в макете 30917) при переходе на зиму из середины в конец. an_makettype =2 - 30917, иначе 30817
 FUNCTION move_val(av_str VARCHAR2, an_makettype NUMBER DEFAULT 1)
  RETURN VARCHAR2 IS
  cv_sep     CONSTANT VARCHAR2(8) := ':';
  lv_ret              VARCHAR2(4000) := av_str;
  a1                  NUMBER;
  a2                  NUMBER;
  a3                  NUMBER;
  k                   NUMBER := 1;
  k_max               NUMBER;
 BEGIN
  IF an_makettype = 2 THEN                                                                                                             --48 значений типа 30917
   k := 2 * k;
  END IF;

  k_max := 2 + 25 * k;

  FOR i IN 1 .. LENGTH(lv_ret) LOOP                                                                                                        --считаем разделители
   IF SUBSTR(lv_ret, i, 1) = cv_sep THEN
    k_max := k_max - 1;
   END IF;

   IF k_max = 0 THEN
    EXIT;
   END IF;
  END LOOP;

  IF k_max > 0 THEN                                                      --Если не полный файл  и надо середину поставить в конец, то просто заполним двоеточием
   lv_ret := lv_ret || LPAD(cv_sep, LEAST(k_max, 2000 - LENGTH(lv_ret)), cv_sep);
  END IF;

  a1 := INSTR(lv_ret, cv_sep, 1, 2 + 4 * k);
  a2 := INSTR(lv_ret, cv_sep, 1, 2 + 5 * k);
  a3 := INSTR(lv_ret, cv_sep, 1, 2 + 25 * k);
  lv_ret :=
   SUBSTR(lv_ret, 1, a1 - 1) || cv_sep || SUBSTR(lv_ret, a2 + 1, a3 -(a2 + 1)) || cv_sep || SUBSTR(lv_ret, a1 + 1, a2 -(a1 + 1)) || cv_sep
   || SUBSTR(lv_ret, a3 + 1);
  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает тип загружаемого файла
 FUNCTION getfiletype(an_cid NUMBER, at_data common_pg.tt_varchar2)
  RETURN NUMBER IS
  lv_fileext          VARCHAR2(256);
  ln_res              NUMBER;
  lv_addparam1        VARCHAR2(2000) := TRIM(util_pg.get_param(get_addparam(an_cid), 1));
 BEGIN
  FOR i IN 1 .. at_data.COUNT LOOP
   IF LENGTH(lv_addparam1) <> 0 THEN
    IF INSTR(at_data(i), lv_addparam1) > 0 THEN
     RETURN cn_30817;
    END IF;
   ELSIF at_data(i) LIKE '%((//_____:%:%:++%' THEN
    IF INSTR(at_data(i), '((//30817:') > 0 THEN
     -- edited by KAG 11.10.2010
     ln_res := check_30817_817(at_data);

     IF ln_res = 3 THEN
      RETURN cn_30817;
     ELSIF ln_res = 2 THEN
      RETURN cn_817;
     ELSIF ln_res = 1 THEN
      RETURN cn_30817_817;
     END IF;
    ELSIF INSTR(at_data(i), '((//30818:') > 0 THEN
     RETURN cn_30818;
    ELSIF INSTR(at_data(i), '((//30816:') > 0 THEN
     RETURN cn_30816;
    ELSIF INSTR(at_data(i), '((//30917:') > 0 THEN
     RETURN cn_30917;
    ELSIF INSTR(at_data(i), '((//10015:') > 0 THEN
     RETURN cn_10015;
    ELSIF INSTR(at_data(i), '((//10014:') > 0 THEN
     RETURN cn_10014;
    ELSIF INSTR(at_data(i), '((//30900:') > 0 THEN
     RETURN cn_30900;
    ELSIF INSTR(at_data(i), '((//30902:') > 0 THEN
     RETURN cn_30902;
    END IF;
   ELSIF at_data(i) LIKE '((//817:%:%:++%' THEN
    RETURN cn_817;
   ELSIF UPPER(at_data(i)) LIKE '##01010%' THEN
    RETURN cn_1010;
   ELSIF UPPER(at_data(i)) LIKE '< DATE=%' THEN
    RETURN cn_30817des;
   ELSIF UPPER(at_data(i)) LIKE '< REC=POINT;%' THEN
    RETURN cn_30917ses;
   ELSIF UPPER(at_data(i)) LIKE '%EDR PROGRAMM%' THEN
    RETURN cn_elvin;
   ELSIF UPPER(at_data(i)) LIKE 'DATE FROM%' THEN
    RETURN cn_zmd;
   ELSIF at_data(i) LIKE '%;%;__.__.____;%;1;_;%' THEN
    RETURN cn_smartf;
   ELSIF at_data(i) LIKE '%#%#%;__.__.____ __:__;%;0' THEN
    RETURN cn_smarth;
   ELSIF UPPER(at_data(i)) LIKE 'ARGO%' THEN
    RETURN cn_argo;
   ELSIF at_data(i) LIKE '%|__.__.____ __:__:__|%|%|%|%|%|%|%|%|%' THEN
    RETURN cn_xartep;
   ELSIF at_data(i) LIKE '%<rdf:RDF%>%' THEN
    RETURN cn_cimrdf;
   END IF;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает дату по строке
 FUNCTION getdatabystr(av_dat VARCHAR2, an_cid NUMBER)
  RETURN DATE IS
  lv_dat              VARCHAR2(512) DEFAULT TRIM(av_dat);
  lv_addparam1        VARCHAR2(2000) := TRIM(util_pg.get_param(get_addparam(an_cid), 2));
 BEGIN
  IF LENGTH(lv_addparam1) <> 0 THEN
   RETURN TO_DATE(lv_dat, lv_addparam1);
  END IF;

  IF LENGTH(lv_dat) = 8 THEN
   RETURN TO_DATE(lv_dat, 'MMDDYYYY');
  ELSIF LENGTH(lv_dat) = 6 THEN
   IF util_pg.get_customer_id = 45 THEN                                                                                                              --Днепр ЭС
    RETURN TO_DATE(lv_dat, 'YYMMDD');
   ELSE
    RETURN TO_DATE(lv_dat, 'MMDDYY');
   END IF;
  ELSE
   RETURN TO_DATE(TO_CHAR(util_pg.get_datebyshortdate(TO_DATE('2004' || lv_dat, 'YYYYMMDD')), 'YYYY') || lv_dat, 'YYYYMMDD');
  END IF;

  raise_application_error(-20001, 'comsrvfile_pg.getdatabystr: Формат даты не распознан.');
 END;

