------------------------------------------------------------------------------------------------------------------------
  -- Универсальный разборщик макетов (автоопределение)
 PROCEDURE universal_p(
 an_operation NUMBER, an_startstate NUMBER, an_endstate IN OUT NUMBER, av_error OUT VARCHAR2, ad_date IN OUT DATE, an_auto NUMBER, an_pars NUMBER
 ) IS
  lc_data             CLOB;
  lb_data             BLOB;
  ln_endstate         NUMBER DEFAULT an_endstate;
  lv_filename         VARCHAR2(256);
  ln_blob             NUMBER := 0;
 BEGIN
  gn_verifierr := 0;
  gd_date := ad_date;
  gn_operation := an_operation;
  gb_pars :=(an_pars = 1);

  SELECT vmaket, cid, vfilename, bmaket
  INTO   lc_data, gn_cid, lv_filename, lb_data
  FROM   rmakets
  WHERE  noperation = an_operation;

  IF lb_data IS NOT NULL THEN
   ln_blob := 1;
  END IF;

  BEGIN
   gt_data := util_pg.convertclob(lc_data);
  EXCEPTION                                                                                                                 -- если в CLOB бред то ставим статус
   WHEN OTHERS THEN
    an_endstate := 2;
    RAISE;
  END;

  IF an_startstate < 3 AND ln_endstate >= 3 THEN
   an_endstate := 1;

   IF ln_blob = 1 THEN                                                                                                                                    --XLS
    gn_type := cn_xls_mold;
   ELSE
    gn_type := getfiletype(gn_cid, gt_data);
   END IF;

   UPDATE rmakets
   SET ntype = gn_type
   WHERE  noperation = an_operation;

   COMMIT;

   IF an_auto = 1 THEN
    SELECT DECODE(MAX(blocking), 0, 7, 5)
    INTO   ln_endstate
    FROM   channels
    WHERE  cid = gn_cid;
   END IF;

   IF gn_type IS NOT NULL THEN
    an_endstate := 2;
    COMMIT;
   END IF;

   IF gn_type = cn_30817 THEN
    IF TRIM(util_pg.get_param(get_addparam(gn_cid), 1)) IS NOT NULL THEN
     l_30817(gn_cid, gt_data);
    ELSE
     l_30817(gn_cid, prepare_nek(gt_data));
    END IF;
   ELSIF gn_type = cn_30818 THEN
--    l_30818(gn_cid, prepare_nek(gt_data));
    l_30818n(gn_cid, prepare_nek(gt_data));
   ELSIF gn_type = cn_30816 THEN
    l_30816(gn_cid, prepare_nek(gt_data));
   ELSIF gn_type = cn_30917 THEN
    l_30917(gn_cid, prepare_nek(gt_data));
   ELSIF gn_type = cn_10015 THEN
    l_10015(gn_cid, prepare_nek(gt_data));
   ELSIF gn_type = cn_10014 THEN
    l_10014(gn_cid, gt_data);
   ELSIF gn_type = cn_30900 THEN
    l_30900(gn_cid, lv_filename, prepare_nek(gt_data));
   --  l_30900(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_30902 THEN
    l_30902(gn_cid, prepare_nek(gt_data));
   ELSIF gn_type = cn_elvin THEN
    lp_elvin(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_elvin60 THEN
    lp_elvin60(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_zmd THEN
    lp_zmd(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_zmd60 THEN
    lp_zmd60(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_smartf THEN
    lp_smartf(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_smarth THEN
    lp_smarth(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_argo THEN
    lp_argo(gn_cid, lv_filename, gt_data);
   ELSIF gn_type = cn_1010 THEN
    l_1010(gn_cid, gt_data);
   ELSIF gn_type = cn_30817des THEN
    l_30817des(gn_cid, gt_data);
   ELSIF gn_type = cn_30917ses THEN
    l_30917ses(gn_cid, gt_data);
   ELSIF gn_type = cn_817 THEN
    l_817(gn_cid, gt_data);
   ELSIF gn_type = cn_30817_817 THEN
    l_30817_817(gn_cid, gt_data);
   ELSIF gn_type = cn_cimrdf THEN
    comsrvrdf_pg.l_cimrdf(gn_cid, lc_data, gd_date);
   ELSIF gn_type = cn_xls_mold THEN
    excelmakets_pg.l_xls(gn_cid, lb_data, gd_date);
   ELSE
    raise_application_error(-20001, 'comsrvfile_pg.parse_file: Файл не распознан.');
   END IF;

   an_endstate := 3;
  ELSE
   SELECT MAX(ntype)
   INTO   gn_type
   FROM   rmakets
   WHERE  noperation = an_operation;
  END IF;

  COMMIT;

  IF an_startstate < 5 AND ln_endstate >= 5 THEN
   /*Верификация*/
   IF gn_verifierr = 1 THEN
    an_endstate := 4;
    RETURN;
   END IF;

   an_endstate := 5;
  END IF;

  COMMIT;

  IF ln_endstate >= 7 THEN
   an_endstate := 6;
   /*Загрузка*/
--   l_load;
   an_endstate := 7;
  END IF;

  COMMIT;
  ad_date := gd_date;
 EXCEPTION
  WHEN OTHERS THEN
   ad_date := gd_date;
   av_error := SQLERRM;
   ROLLBACK;
 END;

----------------------------------------------------------------------------------------------------------------------
-- Общая процедура загрузки файла данных
 PROCEDURE load_file_c(an_cid NUMBER, av_filename VARCHAR2, ad_filedate DATE, ac_data OUT CLOB, an_auto NUMBER, an_operation OUT NUMBER) IS
  ld_sys              DATE DEFAULT SYSDATE;
  an_user             NUMBER;
 BEGIN
  INSERT INTO rmakets
              (noperation, cid, dcreate, vfilename, dfile, nstate, vmaket, user_id)
  VALUES      (makets_seq.NEXTVAL, an_cid, ld_sys, av_filename, NVL(ad_filedate, ld_sys), 0, EMPTY_CLOB(), util_pg.user_f)
  RETURNING   noperation, vmaket
  INTO        an_operation, ac_data;

  admin_pg.ins_journal_p(ld_sys, an_cid, 0, SUBSTR('Файл "' || av_filename || '": Загрузка файла.', 1, 512), cn_filemet, NULL);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvfile_pg.load_file_c: Ошибка загрузки файла ''' || av_filename || '''' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Общая процедура загрузки файла данных
 PROCEDURE load_file_b(an_cid NUMBER, av_filename VARCHAR2, ad_filedate DATE, ac_data OUT BLOB, an_auto NUMBER, an_operation OUT NUMBER) IS
  ld_sys              DATE DEFAULT SYSDATE;
  an_user             NUMBER;
 BEGIN
  INSERT INTO rmakets
              (noperation, cid, dcreate, vfilename, dfile, nstate, bmaket, user_id)
  VALUES      (makets_seq.NEXTVAL, an_cid, ld_sys, av_filename, NVL(ad_filedate, ld_sys), 0, EMPTY_BLOB(), util_pg.user_f)
  RETURNING   noperation, bmaket
  INTO        an_operation, ac_data;

  admin_pg.ins_journal_p(ld_sys, an_cid, 0, SUBSTR('Файл "' || av_filename || '": Загрузка файла.', 1, 512), cn_filemet, NULL);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvfile_pg.load_file_b: Ошибка загрузки файла ''' || av_filename || '''' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION prepare_nek(at_data common_pg.tt_varchar2)
  RETURN common_pg.tt_varchar2 IS
  lt_data             common_pg.tt_varchar2;
  lt_ret              common_pg.tt_varchar2;
  lb_find             BOOLEAN DEFAULT FALSE;
  j                   NUMBER DEFAULT 0;
 BEGIN
  IF at_data.COUNT = 0 THEN
   raise_application_error(-20001, 'Файл не содержит данных.');
  END IF;

  FOR i IN 1 .. at_data.COUNT LOOP
   IF NOT lb_find AND at_data(i) LIKE '%((//_____:%:%:++%' THEN
    lb_find := TRUE;
    j := j + 1;
    lt_data(j) := SUBSTR(at_data(i), INSTR(at_data(i), '((//'));
   ELSIF lb_find THEN
    j := j + 1;

    IF INSTR(at_data(i), '==))') > 0 THEN
     IF TRIM(at_data(i)) = '==))' THEN
      lt_data(j) := at_data(i);
     ELSE
      lt_data(j) := SUBSTR(at_data(i), 1, INSTR(at_data(i), '==))') - 1);
      lt_data(j + 1) := '==))';
     END IF;

     EXIT;
    ELSE
     lt_data(j) := at_data(i);
    END IF;
   END IF;
  END LOOP;

  IF NOT lb_find THEN
   raise_application_error(-20001, 'Отсутствует признак начала данных.');
  END IF;

  --Копируем результат, убирая пустые строки
  j := 0;

  FOR i IN 1 .. lt_data.COUNT LOOP
   IF TRIM(lt_data(i)) IS NOT NULL THEN
    j := j + 1;
    lt_ret(j) := TRIM(lt_data(i));
   END IF;
  END LOOP;

  IF lt_ret(lt_ret.COUNT) <> '==))' THEN
   raise_application_error(-20001, 'Отсутствует признак конца данных.');
  END IF;

  RETURN lt_ret;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrvfile_pg.prepare_nek: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30817(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  lc_from    CONSTANT VARCHAR2(8) := '):(';
  lc_to      CONSTANT VARCHAR2(8) := ')*(';
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_rn               NUMBER DEFAULT 3;
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  ln_parselayer       NUMBER DEFAULT util_pg.getparamvaluev_f(gn_parselayerpid);
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_max              DATE;
  ln_e                NUMBER;
  lt_e                common_pg.tt_number;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  cn_cnt              NUMBER;
  ln_type             NUMBER;
  ln_tmptype          NUMBER;
  ln_block            NUMBER;
  lv_str              VARCHAR(1024);
  ln_sum              NUMBER;
  lv_qm               VARCHAR(1024);                                                                                                                   -- метка
  lt_vqm              common_pg.tt_varchar2;                                                                                         -- метки каждого измерения
  ln_koeff            NUMBER;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_eq1              NUMBER;
  ln_eq3              NUMBER;
  ln_coef             NUMBER;
  lv_type25           VARCHAR(1024) := get_type25(an_cid);
 BEGIN
  DELETE FROM parsingmakets
  WHERE       noperation = gn_operation;

  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data(1);
  ld_date := getdatabystr(util_pg.get_param(lv_ret, 2, lv_separator), an_cid);
  gd_date := ld_date;
  cn_cnt := 24;
  ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := REPLACE(at_data(i), lc_from, lc_to);

   IF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ld_date) = 1 THEN                   --Это день перехода на лето (макет содержит 0 и мы его сотрем)
    lv_ret := skip_0(lv_ret, 1);
   END IF;

   IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ld_date) = -1 THEN     --Это день перехода на зиму (25-й час в середине и мы перенесем его в конец)
    lv_ret := move_val(lv_ret, 1);
   END IF;

   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_tmp := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2));

   IF lv_tmp IS NULL OR INSTR(lv_tmp, ';') > 0 THEN
    raise_application_error(-20001, 'Код точки не указан или указан не верно.');
   END IF;

   --Ищем точку
   SELECT MAX(mid), COUNT(*), MAX(nblock)
   INTO   ln_mid, ln_tmp, ln_block
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid) AND util_pg.get_pos_str(TRIM(UPPER(REPLACE(vimportcode, lc_from, lc_to))), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
    VALUES      (ln_mid);
   END IF;

   --Вставка в parsingmakets
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
   ln_col := 2;
   ln_e := REPLACE(util_pg.get_param(lv_ret, 2, lv_separator), ',', '.');
   parsingmakets_ins(gn_operation, i - 1, 1, REPLACE(lv_tmp, lc_to, lc_from), ln_mid, cn_meast_a, cn_timet_hour_s, 0, ld_date + 1, ln_e);

   FOR j IN 1 .. ln_factcnt LOOP
    IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
     --больше времени сдвига добавяем час
     ln_shift := 1 / 24;
    ELSIF j > cn_cnt THEN
     ln_shift := -1 + (util_pg.switch_f + 1) / 24;
    ELSE
     ln_shift := 0;
    END IF;

    ln_col := 2 + j;

    IF j = ln_factcnt AND INSTR(lv_ret, ';') <> 0 THEN
     ln_e := REPLACE(util_pg.get_param(util_pg.get_param(lv_ret, 2 + j, lv_separator), 1, ';'), ',', '.');
    ELSE
     ln_e := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.');
    END IF;

    parsingmakets_ins(gn_operation, i - 1, j + 1, REPLACE(lv_tmp, lc_to, lc_from), ln_mid, cn_meast_a, cn_timet_hour, 0,
     util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, ln_e);
   END LOOP;
  END LOOP;

  IF gb_pars THEN
   RETURN;
  END IF;

  --Читаем множительный КС  added by KAG 03.06.2009
  SELECT NVL(MAX(util_pg.allnumber_f(addr)), 1000)
  INTO   ln_koeff
  FROM   channels
  WHERE  cid = an_cid;

  IF ln_koeff <= 0 THEN
   ln_koeff := 1000;
  END IF;

  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --В остальных макетах мы это делаем вначале, а здесь мы этим манипулируем на каждой точке т.к из часовок делаем получасовки
   cn_cnt := 24;
   ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. ln_factcnt * 4 LOOP
    lt_e(i) := NULL;
   END LOOP;

   FOR i IN 1 .. 4 LOOP
    lt_vqm(i) := NULL;
   END LOOP;

   lv_qm := '';

   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := REPLACE(at_data(i), lc_from, lc_to);

    IF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ld_date) = 1 THEN                                                     --Это день перехода на лето
     lv_ret := skip_0(lv_ret, 1);
    END IF;

    IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ld_date) = -1 THEN    --Это день перехода на зиму (25-й час в середине и мы перенесем его в конец)
     lv_ret := move_val(lv_ret, 1);
    END IF;

    lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
    --Проверяем что это нужная строка
    lv_tmp := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2));

    SELECT COUNT(*), MAX(util_pg.get_pos_str(TRIM(UPPER(REPLACE(vimportcode, lc_from, lc_to))), lv_tmp))
    INTO   ln_tmp, ln_type
    FROM   feeders
    WHERE  mid = lc.mid AND util_pg.get_pos_str(TRIM(UPPER(REPLACE(vimportcode, lc_from, lc_to))), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN
     ln_sum := 0;

     FOR j IN 1 .. ln_factcnt LOOP
      ln_col := 2 + j;

      IF j = ln_factcnt THEN                                                                      -- от последнего показания надо отделить метку, если она есть
       IF INSTR(lv_ret, ';') = 0 THEN                                                                                        -- проверка на метку, отделенную ;
        lv_qm := util_pg.get_param(lv_ret, 2 + ln_factcnt + 2, lv_separator);                                                                  -- 8битная метка

        IF lv_qm IS NOT NULL THEN
         lv_qm := reports1_pg.convert_8to23bit_qm(lv_qm);
        END IF;
       ELSE
        lv_qm := util_pg.get_param_rev(lv_ret, 1, ';');                                                                                       -- 23битная метка
       END IF;
      END IF;

      IF j = ln_factcnt AND INSTR(lv_ret, ';') <> 0 THEN
       ln_e := REPLACE(util_pg.get_param(util_pg.get_param(lv_ret, 2 + j, lv_separator), 1, ';'), ',', '.') * ln_koeff;
      ELSE
       ln_e := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.') * ln_koeff;
      --*ln_koeff и меняем запятую на точку
      END IF;

      ln_sum := ln_sum + NVL(ln_e, 0);                                                                                                         -- KAG 10.11.2008

      IF ln_e < 0 THEN                                                                                                                 --Если <0 то инвертируем.
       IF ln_type IN(1, 3) THEN
        ln_tmptype := ln_type + 1;
       ELSE
        ln_tmptype := ln_type - 1;
       END IF;

       ln_e := -ln_e;
      ELSE
       ln_tmptype := ln_type;
      END IF;

      lt_e(ln_factcnt *(ln_tmptype - 1) + j) := ln_e;
      lt_vqm(ln_tmptype) := lv_qm;

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + j / cn_cnt;
      END IF;
     END LOOP;

     IF nvl(ln_sum,0) <> NVL(REPLACE(util_pg.get_param(lv_ret, 2, lv_separator), ',', '.') * ln_koeff, 0) AND ln_parselayer = 0 THEN
      -- KAG 10.11.2008 start
      gn_verifierr := 1;
     END IF;                                                                                                                               -- KAG 10.11.2008 end
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   ---------------------------------------VNB 17.01.2012
   IF SUBSTR(lv_type25, 3, 1) = '1' THEN                                                                      -- заменять отсутствующие прием или отдачу на нули
    ln_er := 1;
    ln_ed := 1;
    ln_eq1 := 1;
    ln_eq3 := 1;

    FOR j IN 1 .. ln_factcnt LOOP
     IF lt_e(j) IS NOT NULL THEN
      ln_er := 0;
     END IF;

     IF lt_e(1 * ln_factcnt + j) IS NOT NULL THEN
      ln_ed := 0;
     END IF;

     IF lt_e(2 * ln_factcnt + j) IS NOT NULL THEN
      ln_eq1 := 0;
     END IF;

     IF lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
      ln_eq3 := 0;
     END IF;
    END LOOP;

    IF ln_er = 1 AND ln_ed = 0 THEN
     FOR j IN 1 .. ln_factcnt LOOP
      lt_e(j) := 0;
     END LOOP;
    END IF;

    IF ln_er = 0 AND ln_ed = 1 THEN
     FOR j IN 1 .. ln_factcnt LOOP
      lt_e(1 * ln_factcnt + j) := 0;
     END LOOP;
    END IF;

    IF ln_eq1 = 1 AND ln_eq3 = 0 THEN
     FOR j IN 1 .. ln_factcnt LOOP
      lt_e(2 * ln_factcnt + j) := 0;
     END LOOP;
    END IF;

    IF ln_eq1 = 0 AND ln_eq3 = 1 THEN
     FOR j IN 1 .. ln_factcnt LOOP
      lt_e(3 * ln_factcnt + j) := 0;
     END LOOP;
    END IF;
   END IF;

---------------------------------------VNB 17.01.2012 end;
   --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
   FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
    lt_e(2 * i) := TRUNC(lt_e(i) / 2, ln_rn);
    lt_e(2 * i - 1) := lt_e(i) - lt_e(2 * i);
   END LOOP;

   --А теперь у нас всего больше в 2 раза стало
   cn_cnt := 2 * cn_cnt;
   ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
   -- суммируем метки по каждому измерению
   lv_qm := NULL;

   FOR i IN 1 .. 4 LOOP
    IF lt_vqm(i) IS NOT NULL THEN
     IF lv_qm IS NULL THEN
      lv_qm := lt_vqm(i);
     ELSE
      lv_qm := qm_pg.sumqm(lv_qm, lt_vqm(i));
     END IF;
    END IF;
   END LOOP;

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e(j) IS NOT NULL OR lt_e(1 * ln_factcnt + j) IS NOT NULL OR lt_e(2 * ln_factcnt + j) IS NOT NULL OR lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
      --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j),
      lt_e(2 * ln_factcnt + j), NULL, lt_e(3 * ln_factcnt + j), NULL, ln_rn);
     das_pg.ins_halfhourtmp(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, gn_source, lt_e(j), lt_e(1 * ln_factcnt + j),
      lt_e(2 * ln_factcnt + j), lt_e(3 * ln_factcnt + j), NULL, NULL, NULL, comsrv_pg.cn_maket, lv_qm);
    END IF;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    admin_pg.ins_last_save(lc.mid);

    UPDATE last_save
    SET halfhour = util_pg.to_unlocaltime(ld_max),
        state_date = SYSDATE,
        state_cod = 0,
        clock = 0
    WHERE  mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
  SET halfhour = util_pg.to_unlocaltime(GREATEST(ld_date + 1, NVL(util_pg.to_localtime(halfhour), ld_date + 1)))
  WHERE  mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30817: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30817des(an_cid NUMBER, at_data common_pg.tt_varchar2) IS                                                                -- added by KAG 23.08.2008
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ';';
  ln_rn               NUMBER DEFAULT 0;
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  ln_start            NUMBER DEFAULT 1;
  ln_end              NUMBER DEFAULT 1;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_max              DATE;
  ln_e                NUMBER;
  lt_e                common_pg.tt_number;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  cn_cnt              NUMBER;
  ln_type             NUMBER;
  ln_tmptype          NUMBER;
  ln_block            NUMBER;
  lv_str              VARCHAR(1024);
  ln_cur              NUMBER;
  ln_koeff            NUMBER DEFAULT 1;
  lt_info             averrate_pg.ttinfo;
  lt_bill_e           common_pg.tt_number;
  lb_loadbill         BOOLEAN;
  ln_sld              NUMBER;                                                                                   -- считать сальдо (5й параметр vimportcode = 1)
  ln_sld_tmp          NUMBER;                                                                                              -- временный признак подсчета сальдо
  ln_sld_peretok      NUMBER;                                                                                                               -- суточный переток
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM(at_data(i)) LIKE '< DATE=%') THEN
    ln_start := i;
   END IF;

   IF (TRIM(at_data(i)) LIKE '%; >%') THEN                                                                                -- пока допускаем символы после '%; >'
    ln_end := i;
   END IF;
  END LOOP;

  IF (ln_start < 2) THEN
   raise_application_error(-20001, 'Не найдено начало файла.');
  END IF;

  IF (ln_end <= ln_start) THEN
   raise_application_error(-20001, 'Не найден конец файла.');
  END IF;

  --Проверяем начало
  ln_str := ln_start;
  ln_col := ln_start;
  ld_date := TO_DATE(REPLACE(util_pg.get_param(at_data(ln_start), 1, lv_separator), '< DATE='), 'DDMMYY');
  gd_date := ld_date;

  IF at_data(ln_start) LIKE '%MWT.H%' THEN
   ln_koeff := 1000;                                                                                                   -- если в МВт.ч то будем множить на 1000
  END IF;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN ln_start + 1 .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);

   IF (lv_ret LIKE '< ID=%') THEN
    lv_ret := TRIM(REPLACE(util_pg.get_param(lv_ret, 1, lv_separator), '< ID='));                                                        --получение кода точки

    IF lv_ret IS NULL THEN
     raise_application_error(-20001, 'Код точки не указан или указан не верно.');
    END IF;

    --Ищем точку
    SELECT MAX(mid), COUNT(*), MAX(nblock)
    INTO   ln_mid, ln_tmp, ln_block
    FROM   feeders
    WHERE  mid IN(SELECT mid
                  FROM   chanpoint
                  WHERE  cid = an_cid) AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_ret) BETWEEN 1 AND 4;

    IF ln_tmp > 1 THEN
     raise_application_error(-20001, 'Точка определена не однозначно.');
    ELSIF ln_tmp = 1 AND ln_block = 0 THEN
     INSERT INTO textreport
                 (norder)
     VALUES      (ln_mid);
    END IF;
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --В остальных макетах мы это делаем вначале, а здесь мы этим манипулируем на каждой точке т.к из часовок делаем получасовки
   cn_cnt := 24;
   ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. 50 * 4 LOOP                                                                     -- 4 - кол-во показаний (А+,A-,R+,R-) edited by KAG 12.03.2009
    lt_e(i) := NULL;
   END LOOP;

   FOR i IN 1 .. 4 LOOP
    lt_bill_e(i) := NULL;
   END LOOP;

   lb_loadbill := FALSE;
   ln_sld := 0;
   --Поискали нужные строки
   ln_cur := ln_start;

   FOR i IN ln_start + 1 .. ln_end LOOP
    IF (ln_cur < i) THEN                                                                                    --пропускаем уже рассмотренные при склевании строки
     ln_str := i;
     ln_col := 1;
     ln_cur := i;                                                                                                       -- номер текущей рассматриваемой строки
     lv_ret := TRIM(at_data(i));
     lv_tmp := lv_ret;

     -- ищем и клеем окончание строки при необходимости
     WHILE NOT(lv_tmp LIKE '< ID=%; >') LOOP
      ln_cur := ln_cur + 1;

      IF (ln_cur) > ln_end OR TRIM(at_data(ln_cur)) LIKE '< ID=%' THEN
       --не нашли конец строки (конец файла или началась следующая точка)
       raise_application_error(-20001, 'Не найден конец ' || i || ' строки.');
      END IF;

      IF util_pg.get_param(TRIM(at_data(ln_cur)), 2, '; >') IS NOT NULL THEN                                          -- теперь ругаемся на символы после '%; >'
       raise_application_error(-20001, 'Неразрешенные символы в конце ' || i || ' строки: ' || util_pg.get_param(TRIM(at_data(ln_cur)), 2, '; >'));
      END IF;

      lv_tmp := lv_tmp || TRIM(at_data(ln_cur));                                                                                 -- приклеиваем следующую строку
     END LOOP;

     lv_tmp := UPPER(TRIM(lv_tmp));                                                                              --здесь получили готовую целую строку для точки
     --Проверяем, что это нужная строка
     lv_ret := TRIM(REPLACE(util_pg.get_param(lv_tmp, 1, lv_separator), '< ID='));                                                        --получение кода точки

     SELECT COUNT(*), MAX(util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_ret)),
            MAX(NVL(util_pg.allnumber_f(util_pg.get_param(TRIM(vimportcode), 5, ';')), 0))
     INTO   ln_tmp, ln_type, ln_sld_tmp
     FROM   feeders
     WHERE  mid = lc.mid AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_ret) BETWEEN 1 AND 4;

     --added by KAG 14.10.2009 проверка на отсутствие данных
     IF ln_tmp = 1 AND TRIM(util_pg.get_param(lv_tmp, 2, lv_separator)) = 'ST=-' THEN
      ln_tmp := 0;
     END IF;

     IF ln_tmp = 1 THEN
      ln_sld := ln_sld_tmp;
      -- added by KAG 16.06.2009 для разбора часовок во 2м или 3м блоке
      lv_ret := util_pg.get_param(lv_tmp, 3, lv_separator);

      IF INSTR(lv_ret, ':') = 0 THEN                                                                             -- часовок в 3м блоке нет - будем искать во 2м
       lv_ret := util_pg.get_param(lv_tmp, 2, lv_separator);
      END IF;

      IF INSTR(lv_ret, ':') <> 0 THEN                                                                                                            -- часовки есть
       ln_col := INSTR(lv_ret, ':');
       lv_ret := util_pg.get_param(lv_ret, 2, ':');                                                                                        -- получение часовок
       cn_cnt := 24;
       ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

       FOR j IN 1 .. ln_factcnt LOOP
        ln_col := ln_col + 1;
        ln_e := util_pg.get_param(lv_ret, j, ',') * ln_koeff;                                                        -- переводим в киловатты при необходимости

        IF ln_e < 0 THEN                                                                                                              --Если <0 то инвертируем.
         IF ln_type IN(1, 3) THEN
          ln_tmptype := ln_type + 1;
         ELSE
          ln_tmptype := ln_type - 1;
         END IF;

         ln_e := -ln_e;
        ELSE
         ln_tmptype := ln_type;
        END IF;

        lt_e(ln_factcnt *(ln_tmptype - 1) + j) := ln_e;                                                                           -- заполняем массив значениями

        IF ln_e IS NOT NULL THEN
         ld_max := ld_date + j / cn_cnt;
        END IF;
       END LOOP;
      ELSE                                                                                                                          -- часовок нет, только сумма
       ln_col := INSTR(lv_ret, '=');
       lv_ret := TRIM(util_pg.get_param(lv_ret, 2, '='));                                                                                    -- получение суммы
       averrate_pg.createtinfo(lc.mid, ld_date + 1 / 86400, ld_date + 1, ln_type, 0, TO_NUMBER(lv_ret) * ln_koeff, lt_info);
       lb_loadbill := TRUE;
       cn_cnt := 48;
       ln_factcnt := lt_info.COUNT;

       FOR i IN 1 .. ln_factcnt LOOP
        ln_e := lt_info(i).e;

        IF ln_e < 0 THEN                                                                                                              --Если <0 то инвертируем.
         IF ln_type IN(1, 3) THEN
          ln_tmptype := ln_type + 1;
         ELSE
          ln_tmptype := ln_type - 1;
         END IF;

         ln_e := -ln_e;
        ELSE
         ln_tmptype := ln_type;
        END IF;

        lt_e(ln_factcnt *(ln_tmptype - 1) + i) := ln_e;                                                                           -- заполняем массив значениями

        IF ln_e IS NOT NULL THEN
         ld_max := ld_date + i / cn_cnt;
        END IF;
       END LOOP;

---------------------------------------
-- подсчет суточных
       IF TO_NUMBER(lv_ret) < 0 THEN                                                                                                   --Если <0 то инвертируем.
        IF ln_type IN(1, 3) THEN
         ln_tmptype := ln_type + 1;
        ELSE
         ln_tmptype := ln_type - 1;
        END IF;

        ln_e := -ln_e;
        lt_bill_e(ln_tmptype) := -TO_NUMBER(lv_ret) * ln_koeff;
       ELSE
        ln_tmptype := ln_type;
        lt_bill_e(ln_tmptype) := TO_NUMBER(lv_ret) * ln_koeff;
       END IF;
      END IF;                                                                                                                                   -- часовки/сумма
     END IF;                                                                                                                                -- end if ln_tmp = 1
    END IF;                                                                                                                                        -- ln_cur < i
   END LOOP;                                                                                                                            -- цикл по всем строчкам

   -- added by KAG 19.05.2009
   IF ln_sld = 1 AND lb_loadbill THEN                                                                                                    -- надо считать переток
    -- очищаем от расходов
    FOR i IN 1 .. 50 * 4 LOOP                                                                    -- 4 - кол-во показаний (А+,A-,R+,R-) edited by KAG 12.03.2009
     lt_e(i) := NULL;
    END LOOP;

    -- суточный переток актива
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(1), lt_bill_e(2));                                                                        -- считаем переток

    IF ln_sld_peretok < 0 THEN
     lt_bill_e(2) := -ln_sld_peretok;
     lt_bill_e(1) := NULL;
    ELSE
     lt_bill_e(1) := ln_sld_peretok;
     lt_bill_e(2) := NULL;
    END IF;

    -- суточный переток реактива
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(3), lt_bill_e(4));                                                                        -- считаем переток

    IF ln_sld_peretok < 0 THEN
     lt_bill_e(4) := -ln_sld_peretok;
     lt_bill_e(3) := NULL;
    ELSE
     lt_bill_e(3) := ln_sld_peretok;
     lt_bill_e(4) := NULL;
    END IF;

    -------- считаем актив
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(1), lt_bill_e(2));                                                                        -- считаем переток

    IF ln_sld_peretok IS NOT NULL THEN                                                                                                           -- переток есть
     averrate_pg.createtinfo(lc.mid, ld_date + 1 / 86400, ld_date + 1, 0, 0, ln_sld_peretok, lt_info);
     cn_cnt := 48;
     ln_factcnt := lt_info.COUNT;

     FOR i IN 1 .. ln_factcnt LOOP
      ln_e := lt_info(i).e;

      IF ln_e < 0 THEN                                                                                                                       -- кладем в отдачу
       ln_tmptype := 2;
       ln_e := -ln_e;
      ELSE                                                                                                                                     -- кладем в прием
       ln_tmptype := 1;
      END IF;

      lt_e(ln_factcnt *(ln_tmptype - 1) + i) := ln_e;                                                                             -- заполняем массив значениями

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + i / cn_cnt;
      END IF;
     END LOOP;
    END IF;

    ------- считаем реактив
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(3), lt_bill_e(4));                                                                        -- считаем переток

    IF ln_sld_peretok IS NOT NULL THEN                                                                                                           -- переток есть
     averrate_pg.createtinfo(lc.mid, ld_date + 1 / 86400, ld_date + 1, 0, 0, ln_sld_peretok, lt_info);
     cn_cnt := 48;
     ln_factcnt := lt_info.COUNT;

     FOR i IN 1 .. ln_factcnt LOOP
      ln_e := lt_info(i).e;

      IF ln_e < 0 THEN                                                                                                                       -- кладем в отдачу
       ln_tmptype := 4;
       ln_e := -ln_e;
      ELSE                                                                                                                                     -- кладем в прием
       ln_tmptype := 3;
      END IF;

      lt_e(ln_factcnt *(ln_tmptype - 1) + i) := ln_e;                                                                             -- заполняем массив значениями

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + i / cn_cnt;
      END IF;
     END LOOP;
    END IF;
   END IF;

------------
   ln_str := 1;
   ln_col := 1;

   IF cn_cnt = 24 THEN                                                                                       -- раскидываем только если у нас еще не получасовки
    --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
    FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
     lt_e(2 * i) := TRUNC(lt_e(i) / 2, ln_rn);
     lt_e(2 * i - 1) := lt_e(i) - lt_e(2 * i);
    END LOOP;

    --А теперь у нас всего больше в 2 раза стало
    cn_cnt := 2 * cn_cnt;
    ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
   END IF;

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e(j) IS NOT NULL OR lt_e(1 * ln_factcnt + j) IS NOT NULL OR lt_e(2 * ln_factcnt + j) IS NOT NULL OR lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
      --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j),
      lt_e(2 * ln_factcnt + j), NULL, lt_e(3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j),
      lt_e(3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF lb_loadbill THEN                                                                                                                        -- запись суточных
    comsrv_pg.set_bill_eom(lc.mid, lt_bill_e(1), lt_bill_e(2), lt_bill_e(3), lt_bill_e(4), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
     NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ld_date + 1);

    IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
     admin_pg.ins_last_save(lc.mid);

     UPDATE last_save
     SET halfhour = ld_max,
         bill = GREATEST(NVL(bill, ld_max), ld_max),
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END IF;
   ELSE                                                                                                            -- суточные по данной точке не будут грузится
    IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
     admin_pg.ins_last_save(lc.mid);

     UPDATE last_save
     SET halfhour = ld_max,
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END IF;
   END IF;
  END LOOP;                                                                                                                                    -- цикл по точкам

  IF lb_loadbill THEN
   UPDATE last_save
   SET halfhour = GREATEST(ld_date + 1, NVL(halfhour, ld_date + 1)),
       bill = GREATEST(ld_date + 1, NVL(bill, ld_date + 1))
   WHERE  mid = an_cid;
  ELSE
   UPDATE last_save
   SET halfhour = GREATEST(ld_date + 1, NVL(halfhour, ld_date + 1))
   WHERE  mid = an_cid;
  END IF;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30817des: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

