 -- added by KAG 23.08.2008
 PROCEDURE l_30917ses(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  cn_cnt     CONSTANT NUMBER DEFAULT 48;
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ';';
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  ln_start            NUMBER DEFAULT 1;
  ln_end              NUMBER DEFAULT 1;
  ln_rn               NUMBER DEFAULT 3;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  lv_tmp2             VARCHAR2(4000);
  lv_point            VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ln_cnt              NUMBER DEFAULT 0;
  ld_date             DATE;
  ld_max              DATE;
  lt_e                common_pg.tt_number;
  ln_type             NUMBER;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  ln_block            NUMBER;
  ln_reverse          NUMBER;
  ln_koeff            NUMBER DEFAULT 1;
  lt_m                common_pg.tt_varchar2;
  ln_tzone            NUMBER DEFAULT -2;                                                                                                -- временная зона точки
  ln_ktr              NUMBER DEFAULT 1;                                                                                      -- коэффициент трансформации точки
  ln_stime            NUMBER DEFAULT 0;                                                            -- 1, если часы в сумматоре  переводятся на летнее время,
                                                                                                   -- 0 - если  часы сумматора не меняются независимо от сезона
  ld_mind             DATE;                                                                                                         -- минимальная дата в файле
  ld_maxd             DATE;                                                                                                        -- максимальная дата в файле
  ld_curd             DATE;                                                                                                           -- текущая дата обработки
  ln_metcnt           NUMBER;                                                                  -- формирует кол-во показаний в файле (1-тогда 48, 1/2-тогда 24)
  ln_metcntcur        NUMBER;                                                                                  -- кол-во показаний для одной точки за одну дату
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM(at_data(i)) LIKE '< REC=POINT;%') THEN
    ln_start := i;
    EXIT;
   END IF;
  END LOOP;

  FOR i IN REVERSE 1 .. at_data.COUNT LOOP
   IF (TRIM(at_data(i)) LIKE '%; >%') THEN                                                                                -- пока допускаем символы после '; >'
    ln_end := i;
    EXIT;
   END IF;
  END LOOP;

  IF (ln_start < 2) THEN
   raise_application_error(-20001, 'Некорректное начало файла.');
  END IF;

  IF (ln_end <= ln_start) THEN
   raise_application_error(-20001, 'Не найден конец файла.');
  END IF;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN ln_start .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);

   IF lv_ret LIKE '< REC=POINT;%' THEN
    lv_tmp := TRIM(util_pg.get_param(lv_ret, 2, lv_separator));

    IF SUBSTR(lv_tmp, 1, 3) <> 'ID=' THEN
     raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
    END IF;

    --получаем код точки
    lv_point := SUBSTR(lv_tmp, 4);

    IF TRIM(lv_point) IS NULL THEN
     raise_application_error(-20001, 'Код точки не указан.');
    END IF;

    --Ищем точку
    SELECT MAX(mid), COUNT(*), MAX(nblock)
    INTO   ln_mid, ln_cnt, ln_block
    FROM   feeders
    WHERE  mid IN(SELECT mid
                  FROM   chanpoint
                  WHERE  cid = an_cid) AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_point) BETWEEN 1 AND 4;

    IF ln_cnt > 1 THEN
     raise_application_error(-20001, 'Точка определена неоднозначно.');
    ELSIF ln_cnt = 1 AND ln_block = 0 THEN
     INSERT INTO textreport
                 (norder)
     VALUES      (ln_mid);
    END IF;
   ELSIF lv_ret LIKE '< REC=DAY;%' THEN                                                                                    -- здесь ищем мин и макс дату в файле
    ld_date := TO_DATE(REPLACE(TRIM(util_pg.get_param(lv_ret, 2, lv_separator)), 'DATE='), 'YYMMDD');

    IF ld_mind > ld_date OR ld_mind IS NULL THEN
     ld_mind := ld_date;
    END IF;

    IF ld_maxd < ld_date OR ld_maxd IS NULL THEN
     ld_maxd := ld_date;
    END IF;
   END IF;
  END LOOP;

-------------
  ld_curd := ld_mind;

  WHILE ld_curd >= ld_mind AND ld_curd <= ld_maxd LOOP                                                                             -- цикл по всем датам в файле
   FOR lc IN (SELECT DISTINCT norder mid
              FROM            textreport) LOOP                                                                               -- цикл по точкам загрузки в файле
    IF ln_stime = 0 THEN                                                             -- данные летом приходят по зимнему времени (счетчик не переходит на лето)
     ln_factcnt := cn_cnt;
    ELSE
     ln_factcnt := util_pg.get_count_dt(ld_curd, 1 / cn_cnt);
    END IF;

    --Очистили
    FOR i IN 1 .. ln_factcnt * 4 LOOP
     lt_e(i) := NULL;
     lt_m(i) := NULL;                                                                                                   -- статусы передаваемых значений данных
    END LOOP;

    ln_metcntcur := 0;

    --Поискали нужные строки
    FOR i IN ln_start .. ln_end LOOP                                                                                            -- цикл по всем строчкам в файле
     ln_str := i;
     ln_col := 1;
     lv_ret := TRIM(at_data(i));

     IF lv_ret LIKE '< REC=POINT;%' THEN
      --получаем код точки
      lv_tmp := TRIM(util_pg.get_param(lv_ret, 2, lv_separator));
      lv_point := SUBSTR(lv_tmp, 4);
      --Проверяем, что это нужная строка
      ln_cnt := 0;

      SELECT COUNT(*), MAX(util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_point))
      INTO   ln_cnt, ln_type
      FROM   feeders
      WHERE  mid = lc.mid AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_point) BETWEEN 1 AND 4;

      IF ln_cnt = 1 THEN                                                                               -- устанавливаем параметры зоны только для текущей точки
       -- получаем временную зону точки
       lv_tmp := TRIM(util_pg.get_param(lv_ret, 3, lv_separator));
       ln_col := INSTR(lv_ret, '=', 1, 3);

       IF INSTR(lv_tmp, 'TIME') <> 0 THEN
        lv_tmp := TRIM(util_pg.get_param(lv_tmp, 2, '='));
        ln_tzone := TO_NUMBER(lv_tmp);
       ELSE
        ln_tzone := -2;                                                                                                 -- среднеевропейское время по умолчанию
       END IF;

       -- получаем сдвиг летнего времени
       lv_tmp := TRIM(util_pg.get_param(lv_ret, 4, lv_separator));
       ln_col := INSTR(lv_ret, '=', 1, 4);

       IF INSTR(lv_tmp, 'LTIME') <> 0 THEN
        lv_tmp := TRIM(util_pg.get_param(lv_tmp, 2, '='));
        ln_stime := TO_NUMBER(lv_tmp);
       ELSE
        ln_stime := 0;                                                                                                      -- по умолчанию всегда зимнее время
       END IF;

       -- получаем коэффициент трансформации точки
       lv_tmp := TRIM(util_pg.get_param(lv_ret, 5, lv_separator));
       ln_col := INSTR(lv_ret, '=', 1, 5);

       IF INSTR(lv_tmp, 'KTR') <> 0 THEN
        lv_tmp := TRIM(util_pg.get_param(lv_tmp, 2, '='));
        ln_ktr := TO_NUMBER(lv_tmp);
       ELSE
        ln_ktr := 1;                                                                                                  -- коэффициент трансформации по умолчанию
       END IF;
      END IF;                                                                                                                                      -- ln_cnt = 1
     ELSIF lv_ret LIKE '< REC=DAY;%' THEN
      IF ln_cnt = 1 THEN
       ld_date := TO_DATE(REPLACE(TRIM(util_pg.get_param(lv_ret, 2, lv_separator)), 'DATE='), 'YYMMDD');

       IF ld_date = ld_curd THEN
        IF ln_stime = 0 THEN                                                         -- данные летом приходят по зимнему времени (счетчик не переходит на лето)
         ln_factcnt := cn_cnt;
        ELSE
         ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
        END IF;

        ld_date := ld_date - ln_tzone / 24 - 1 / 24;                                           -- приведение времени к московскому и потом к украинскому зимнему
        ld_max := ld_date - 1;                                                                                                              --Обнулили макс дату
        lv_tmp := TRIM(util_pg.get_param(lv_ret, 3, lv_separator));

        IF INSTR(lv_tmp, 'FORMAT=') = 0 THEN
         raise_application_error(-20001, 'Не указан формат данных (FORMAT=MWT или FORMAT=KWT)');
        END IF;

        IF lv_tmp LIKE 'FORMAT=MWT' THEN
         ln_koeff := 1000;                                                                                               -- если в МВт то будем множить на 1000
        ELSE
         ln_koeff := 1;
        END IF;

        -- s KAG 8.04.2009
        IF INSTR(lv_ret, 'P48=') <> 0 THEN                                                                                        -- это 48 получасовок мощности
         ln_koeff := ln_koeff / 2;
         ln_metcnt := 1;
         lv_tmp := TRIM(REPLACE(util_pg.get_param(lv_ret, 4, lv_separator), 'P48='));                                                       -- получение данных
         lv_tmp2 := TRIM(REPLACE(util_pg.get_param(lv_ret, 5, lv_separator), 'ST48='));                                               -- получение меток данных
        ELSIF INSTR(lv_ret, 'E48=') <> 0 THEN                                                                                      -- это 48 получасовок энергии
         ln_metcnt := 1;
         lv_tmp := TRIM(REPLACE(util_pg.get_param(lv_ret, 4, lv_separator), 'E48='));                                                       -- получение данных
         lv_tmp2 := TRIM(REPLACE(util_pg.get_param(lv_ret, 5, lv_separator), 'ST48='));                                               -- получение меток данных
        ELSIF INSTR(lv_ret, 'P24=') <> 0 THEN                                                                                         -- это 24 часовок мощности
         ln_metcnt := 1 / 2;
         lv_tmp := TRIM(REPLACE(util_pg.get_param(lv_ret, 4, lv_separator), 'P24='));                                                       -- получение данных
         lv_tmp2 := TRIM(REPLACE(util_pg.get_param(lv_ret, 5, lv_separator), 'ST24='));                                               -- получение меток данных
        ELSIF INSTR(lv_ret, 'E24=') <> 0 THEN                                                                                          -- это 24 часовок энергии
         ln_metcnt := 1 / 2;
         lv_tmp := TRIM(REPLACE(util_pg.get_param(lv_ret, 4, lv_separator), 'E24='));                                                       -- получение данных
         lv_tmp2 := TRIM(REPLACE(util_pg.get_param(lv_ret, 5, lv_separator), 'ST24='));                                               -- получение меток данных
        END IF;

        IF ln_metcntcur = 0 THEN
         ln_metcntcur := ln_metcnt;
        ELSIF ln_metcntcur <> ln_metcnt THEN
         raise_application_error(-20001, 'Для одной точки учета за одну и ту же дату имеются одновременно показания с разными периодами интеграции!');
        END IF;

        -- e KAG 8.04.2009
        ln_col := INSTR(lv_ret, '=', 1, 4);

        FOR j IN 1 .. ln_factcnt * ln_metcnt LOOP                                                                                               -- чтение данных
         lt_e(ln_factcnt * ln_metcnt *(ln_type - 1) + j) := util_pg.get_param(lv_tmp, j, ',') * ln_koeff * ln_ktr;

         -- переводим в кВт*ч с учетом КТР
         IF lt_e(ln_factcnt * ln_metcnt *(ln_type - 1) + j) IS NOT NULL THEN
          ld_max := ld_curd - ln_tzone / 24 - 1 / 24 + j /(cn_cnt * ln_metcnt);
         END IF;

         ln_col := ln_col + NVL(LENGTH(lt_e(ln_factcnt * ln_metcnt *(ln_type - 1) + j)), 0) + 1;
        -- +1 - длина запятой-разделителя
        END LOOP;

        ln_col := INSTR(lv_ret, '=', 1, 5);

        FOR j IN 1 .. ln_factcnt * ln_metcnt LOOP                                                                                         -- чтение меток данных
         lt_m(ln_factcnt * ln_metcnt *(ln_type - 1) + j) := util_pg.get_param(lv_tmp2, j, ',');
         ln_col := ln_col + NVL(LENGTH(lt_m(ln_factcnt * ln_metcnt *(ln_type - 1) + j)), 0) + 1;
        -- +1 - длина запятой-разделителя
        END LOOP;
       END IF;                                                                                                                                -- ld_date=ld_curd
      END IF;                                                                                                                                      -- ln_cnt = 1
     END IF;                                                                                                                                       -- POINT/DATE
    END LOOP;                                                                                                                     -- цикл по всем строчкам файла

    ----- разбиваем часовки на получасовки
    IF ln_metcnt = 1 / 2 THEN
     -- показания
     FOR i IN REVERSE 1 .. ln_factcnt * ln_metcnt * 4 LOOP
      lt_e(2 * i) := TRUNC(lt_e(i) / 2, 0);
      lt_e(2 * i - 1) := lt_e(i) - lt_e(2 * i);
     END LOOP;

     -- метки
     FOR i IN REVERSE 1 .. ln_factcnt * ln_metcnt * 4 LOOP
      lt_m(2 * i) := lt_m(i);
      lt_m(2 * i - 1) := lt_m(i);
     END LOOP;
    END IF;

    -- делаем insert в бд для текущей точки
    ld_date := ld_curd - ln_tzone / 24 - 1 / 24;

    SELECT NVL(MAX(ed_position), 0)
    INTO   ln_reverse
    FROM   feeders
    WHERE  mid = lc.mid;

    FOR j IN 1 .. ln_factcnt LOOP
     --Если есть цифры
     IF lt_e(j) IS NOT NULL OR lt_e(1 * ln_factcnt + j) IS NOT NULL OR lt_e(2 * ln_factcnt + j) IS NOT NULL OR lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
      IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
       --больше времени сдвига добавяем час
       ln_shift := 1 / 24;
      ELSIF j > cn_cnt THEN
       ln_shift := -1 + (util_pg.switch_f + 1) / 24;
      ELSE
       ln_shift := 0;
      END IF;

      IF util_pg.get_customer_id = 1 AND ln_reverse > 0 THEN
       util_pg.chdr(lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j), lt_e(3 * ln_factcnt + j));
      ELSIF util_pg.get_customer_id <> 1 THEN
       util_pg.chdr(lc.mid, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j), lt_e(3 * ln_factcnt + j));
      END IF;

      IF ln_stime = 0 THEN                                                            -- данные летом приходят по зимнему времени (счетчик не переходит на лето)
       das_pg.insert_hf_in_profile(lc.mid, ld_date + j / cn_cnt, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j), NULL,
        lt_e(3 * ln_factcnt + j), NULL, ln_rn);
       inshalfhour(lc.mid, ld_date + j / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j), lt_e(3 * ln_factcnt + j));
      ELSE
       das_pg.insert_hf_in_profile(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j),
        lt_e(2 * ln_factcnt + j), NULL, lt_e(3 * ln_factcnt + j), NULL, ln_rn);
       inshalfhour(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j),
        lt_e(3 * ln_factcnt + j));
      END IF;
     END IF;
    END LOOP;

    IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
     admin_pg.ins_last_save(lc.mid);

     UPDATE last_save
     SET halfhour = util_pg.to_unlocaltime(ld_max),
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END IF;
   END LOOP;                                                                                                                  -- цикл по точкам загрузки в файле

   ld_curd := ld_curd + 1;
  END LOOP;                                                                                                                       --- цикл по всем датам в файле

----------------
  UPDATE last_save
  SET halfhour = util_pg.to_unlocaltime(GREATEST(ld_date + 1, NVL(util_pg.to_localtime(halfhour), ld_date + 1)))
  WHERE  mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30917ses: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || ')' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30917(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  cn_cnt     CONSTANT NUMBER DEFAULT 48;
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  ln_rn               NUMBER DEFAULT 3;
  ln_parselayer       NUMBER DEFAULT util_pg.getparamvaluev_f(gn_parselayerpid);
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_max              DATE;
  ln_e                NUMBER;
  lt_e                common_pg.tt_number;
  ln_type             NUMBER;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  ln_block            NUMBER;
  ln_reverse          NUMBER;
  lv_vimportcode      VARCHAR2(100);
  ln_meas             NUMBER;
  lv_type25           VARCHAR(1024) := get_type25(an_cid);
  lv_code             VARCHAR2(8);
 BEGIN
  DELETE FROM parsingmakets
  WHERE       noperation = gn_operation;

  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data(1);
  ld_date := getdatabystr(util_pg.get_param(lv_ret, 2, lv_separator), an_cid);
  gd_date := ld_date;
  ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);

   IF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ld_date) = 1 THEN                                                      --Это день перехода на лето
    lv_ret := skip_0(lv_ret, 2);
   END IF;

   IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ld_date) = -1 THEN     --Это день перехода на зиму (25-й час в середине и мы перенесем его в конец)
    lv_ret := move_val(lv_ret, 2);
   END IF;

   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_vimportcode := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 3));
   lv_code := NVL(SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1), ' ');

   IF lv_code NOT IN('1', '2', '3', '4') AND ln_parselayer = 0 THEN
    raise_application_error(-20001, 'Номер параметра учета не распознан.');
   END IF;

   IF TRIM(lv_vimportcode) IS NULL THEN
    raise_application_error(-20001, 'Код точки не указан.');
   END IF;

   IF lv_code = '1' THEN
    ln_meas := cn_meast_er;
   ELSIF lv_code = '2' THEN
    ln_meas := cn_meast_ed;
   ELSIF lv_code = '3' THEN
    ln_meas := cn_meast_q1;
   ELSIF lv_code = '4' THEN
    ln_meas := cn_meast_q3;
   ELSE
    ln_meas:=NULL;
   END IF;

   --Ищем точку
   SELECT MAX(mid), COUNT(*), MAX(nblock)
   INTO   ln_mid, ln_tmp, ln_block
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid) AND TRIM(UPPER(vimportcode)) = lv_vimportcode AND ln_meas>0;

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
    VALUES      (ln_mid);
   END IF;

   --Вставка в parsingmakets
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
   ln_col := 2;
   ln_e := REPLACE(util_pg.get_param(lv_ret, 2, lv_separator), ',', '.');
   parsingmakets_ins(gn_operation, i - 1, 1, lv_vimportcode, ln_mid, ln_meas, cn_timet_hour_s, 0, ld_date + 1, ln_e);

   FOR j IN 1 .. ln_factcnt LOOP
    IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
     --больше времени сдвига добавяем час
     ln_shift := 1 / 24;
    ELSIF j > cn_cnt THEN
     ln_shift := -1 + (util_pg.switch_f + 1) / 24;
    ELSE
     ln_shift := 0;
    END IF;

    ln_col := 2 + j;
    ln_e := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.');
    parsingmakets_ins(gn_operation, i - 1, j + 1, lv_vimportcode, ln_mid, ln_meas, cn_timet_hour, 0, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift,
     ln_e);
   END LOOP;

  END LOOP;

  IF gb_pars THEN
   RETURN;
  END IF;

  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. ln_factcnt * 4 LOOP
    lt_e(i) := NULL;
   END LOOP;

   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM(at_data(i));

    IF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ld_date) = 1 THEN                                                     --Это день перехода на лето
     lv_ret := skip_0(lv_ret, 2);
    END IF;

    IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ld_date) = -1 THEN    --Это день перехода на зиму (25-й час в середине и мы перенесем его в конец)
     lv_ret := move_val(lv_ret, 2);
    END IF;

    lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

    IF NVL(SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1), ' ') NOT IN('1', '2', '3', '4') THEN
     GOTO to_continue;
    END IF;

    --Проверяем что єто нужная строка
    lv_vimportcode := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 3));

    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT *
                  FROM   feeders
                  WHERE  TRIM(UPPER(vimportcode)) = lv_vimportcode AND mid = lc.mid);

    IF ln_tmp = 1 THEN
     ln_type := SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1);

     FOR j IN 1 .. ln_factcnt LOOP
      ln_col := 2 + j;
      lt_e(ln_factcnt *(ln_type - 1) + j) := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.');

      -- и меняем запятую на точку
      IF lt_e(ln_factcnt *(ln_type - 1) + j) IS NOT NULL THEN
       ld_max := ld_date + j / cn_cnt;
      END IF;
     END LOOP;
    END IF;

    <<to_continue>>
    NULL;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   SELECT NVL(MAX(ed_position), 0)
   INTO   ln_reverse
   FROM   feeders
   WHERE  mid = lc.mid;

   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e(j) IS NOT NULL OR lt_e(1 * ln_factcnt + j) IS NOT NULL OR lt_e(2 * ln_factcnt + j) IS NOT NULL OR lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
      --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     IF util_pg.get_customer_id = 1 AND ln_reverse = -1 THEN
      util_pg.chdr(lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j), lt_e(3 * ln_factcnt + j));
     ELSIF util_pg.get_customer_id <> 1 THEN
      util_pg.chdr(lc.mid, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j), lt_e(3 * ln_factcnt + j));
     END IF;

     das_pg.insert_hf_in_profile(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j),
      lt_e(2 * ln_factcnt + j), NULL, lt_e(3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j),
      lt_e(3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    admin_pg.ins_last_save(lc.mid);

    UPDATE last_save
    SET halfhour = util_pg.to_unlocaltime(ld_max),
        state_date = SYSDATE,
        state_cod = 0,
        clock = 0
    WHERE  mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
  SET halfhour = util_pg.to_unlocaltime(GREATEST(ld_date + 1, NVL(util_pg.to_localtime(halfhour), ld_date + 1)))
  WHERE  mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30917: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

