 PROCEDURE l_30818(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_tmp              DATE;
  ld_max              DATE;
  ln_e                NUMBER;
  lt_e                common_pg.tt_number;
  ln_type             NUMBER;
  lv_mtrsn            VARCHAR2(4000);
  ln_block            NUMBER;
  ln_reverse          NUMBER;
  ln_inverted         NUMBER;                                                                                                        -- added by EVK 21.05.2009
  lv_vimportcode      VARCHAR2(100);
  ln_meas             NUMBER;
  lv_q1234            VARCHAR2(10);
  ld_sys              DATE := SYSDATE;
 BEGIN
  DELETE FROM parsingmakets
  WHERE       noperation = gn_operation;

  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data(1);
  ld_date := getdatabystr(util_pg.get_param(lv_ret, 2, lv_separator), an_cid);
  gd_date := ld_date;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_vimportcode := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 3));

   IF NVL(SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1), ' ') NOT IN('1', '2', '3', '4', '5', '6') THEN
    raise_application_error(-20001, 'Номер параметра учета не распознан.');
   END IF;

   --Ищем точку
   SELECT MAX(mid), COUNT(*), MAX(nblock), MAX(q1234)
   INTO   ln_mid, ln_tmp, ln_block, lv_q1234
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid) AND TRIM(UPPER(vimportcode)) = lv_vimportcode;

   IF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '1' THEN
    ln_meas := cn_meast_er;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '2' THEN
    ln_meas := cn_meast_ed;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '3' THEN
    IF lv_q1234 IS NOT NULL THEN
     ln_meas := 7;
    ELSE
     ln_meas := cn_meast_q1;
    END IF;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '4' THEN
    ln_meas := cn_meast_q2;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '5' THEN
    IF lv_q1234 IS NOT NULL THEN
     ln_meas := 8;
    ELSE
     ln_meas := cn_meast_q3;
    END IF;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '6' THEN
    ln_meas := cn_meast_q4;
   END IF;

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
    VALUES      (ln_mid);
   END IF;

   --Вставка в parsingmakets
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
   ln_col := 2;
   ln_e := REPLACE(util_pg.get_param(lv_ret, 2, lv_separator), ',', '.');
   parsingmakets_ins(gn_operation, i - 1, 1, lv_vimportcode, ln_mid, ln_meas, cn_timet_hour_s, 0, ld_date + 1, ln_e);

   FOR j IN 1 .. 4 LOOP
    ln_col := 2 + j;
    ln_e := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.');
    parsingmakets_ins(gn_operation, i - 1, j + 1, lv_vimportcode, ln_mid, ln_meas, cn_timet_hour, 0, ld_date, ln_e);
   END LOOP;
  END LOOP;

--insert into tmp_saa values(to_char(ld_sys,'yyyymmddhh24miss')||'_0:'||86400*(ld_sys-sysdate)); commit;
  IF gb_pars THEN
   RETURN;
  END IF;

  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. 6 * 5 LOOP
    lt_e(i) := NULL;
   END LOOP;

   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM(at_data(i));
    lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
    --Проверяем что єто нужная строка
    lv_vimportcode := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 3));

    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT *
                  FROM   feeders
                  WHERE  TRIM(UPPER(vimportcode)) = lv_vimportcode AND mid = lc.mid);

    IF ln_tmp = 1 THEN
     ln_type := SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1);

     FOR j IN 1 .. 5 LOOP
      ln_col := 1 + j;
      lt_e(5 *(ln_type - 1) + j) := REPLACE(util_pg.get_param(lv_ret, 1 + j, lv_separator), ',', '.');

      -- и меняем запятую на точку
      IF lt_e(5 *(ln_type - 1) + j) IS NOT NULL THEN
       ld_max := ld_date + 1;
      END IF;
     END LOOP;
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   IF ld_max > ld_date THEN
    SELECT MAX(mtrsn)
    INTO   lv_mtrsn
    FROM   meters
    WHERE  mid = lc.mid AND entype = 7;

    IF util_pg.get_customer_id = 1 THEN                                                                                                               --Для ХОЭ
     SELECT NVL(MIN(ed_position), 0), NVL(MAX(ninverted), 0)
     INTO   ln_reverse, ln_inverted
     FROM   feeders
     WHERE  mid = lc.mid;

     IF NOT((ln_reverse = -1 AND ln_inverted = 0) OR(ln_reverse != -1 AND ln_inverted = 1)) THEN
      FOR i IN 1 .. 5 LOOP
       util_pg.chdr(lc.mid, lt_e(i), lt_e(i + 5), lt_e(i + 10), lt_e(i + 20), lt_e(i + 15), lt_e(i + 25));
      END LOOP;
     END IF;
    END IF;

    comsrv_pg.set_bill_meter(lc.mid, lt_e(1), lt_e(6), lt_e(11), lt_e(21), lt_e(16), lt_e(26), lt_e(2), lt_e(7), lt_e(12), lt_e(22), lt_e(17), lt_e(27),
     lt_e(3), lt_e(8), lt_e(13), lt_e(23), lt_e(18), lt_e(28), lt_e(4), lt_e(9), lt_e(14), lt_e(24), lt_e(19), lt_e(29), lt_e(5), lt_e(10), lt_e(15), lt_e(25),
     lt_e(20), lt_e(30), lv_mtrsn, NULL, ld_max);
    ld_tmp := indic_pg.recalcdiff(lc.mid, ld_max, 5);

    IF ld_max = TRUNC(ld_max, 'MONTH') THEN
     comsrv_pg.set_months_meter(lc.mid, lt_e(1), lt_e(6), lt_e(11), lt_e(21), lt_e(16), lt_e(26), lt_e(2), lt_e(7), lt_e(12), lt_e(22), lt_e(17), lt_e(27),
      lt_e(3), lt_e(8), lt_e(13), lt_e(23), lt_e(18), lt_e(28), lt_e(4), lt_e(9), lt_e(14), lt_e(24), lt_e(19), lt_e(29), lt_e(5), lt_e(10), lt_e(15),
      lt_e(25), lt_e(20), lt_e(30), lv_mtrsn, NULL, ld_max);
     ld_tmp := indic_pg.recalcdiff(lc.mid, ld_max, 6);
    END IF;

    admin_pg.ins_last_save(lc.mid);

    IF util_pg.get_customer_id <> 1 THEN
     UPDATE last_save
     SET bill = GREATEST(NVL(bill, ld_max), ld_max),
         months = GREATEST(NVL(months, DECODE(ld_max, TRUNC(ld_max, 'MONTH'), ld_max, months)), DECODE(ld_max, TRUNC(ld_max, 'MONTH'), ld_max, months)),
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END IF;
   END IF;
  END LOOP;

  UPDATE last_save
  SET bill = GREATEST(ld_date + 1, NVL(bill, ld_date + 1)),
      months = DECODE(TRUNC(ld_date + 1, 'MONTH'), ld_date + 1, GREATEST(ld_date + 1, NVL(months, ld_date + 1)), months)
  WHERE  mid = an_cid;

  DELETE FROM textreport;
--  insert into tmp_saa values(to_char(ld_sys,'yyyymmddhh24miss')||'_1:'||86400*(ld_sys-sysdate)); commit;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30818: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30818n(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  ln_isxoe            NUMBER DEFAULT 0;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_tmp              DATE;
  ln_e                NUMBER;
  lt_e                common_pg.tt_number;
  lv_mtrsn            VARCHAR2(4000);
  lv_vimportcode      VARCHAR2(100);
  ln_meas             NUMBER;
  ld_sys              DATE := SYSDATE;
 BEGIN
  IF util_pg.get_customer_id = 1 THEN
   ln_isxoe := 1;
  END IF;

  DELETE FROM parsingmakets
  WHERE       noperation = gn_operation;

  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data(1);
  gd_date := getdatabystr(util_pg.get_param(lv_ret, 2, lv_separator), an_cid);
  ld_date := gd_date + 1;

  --Пробегаемся по файлу и выписываем все ид точек
  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_vimportcode := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 3));

   IF NVL(SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1), ' ') NOT IN('1', '2', '3', '4', '5', '6') THEN
    raise_application_error(-20001, 'Номер параметра учета не распознан.');
   END IF;

   --Ищем точку
   SELECT MAX(mid), COUNT(*)
   INTO   ln_mid, ln_tmp
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid) AND TRIM(UPPER(vimportcode)) = lv_vimportcode;

   IF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '1' THEN
    ln_meas := cn_meast_er;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '2' THEN
    ln_meas := cn_meast_ed;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '3' THEN
    ln_meas := cn_meast_q1;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '4' THEN
    ln_meas := cn_meast_q2;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '5' THEN
    ln_meas := cn_meast_q3;
   ELSIF SUBSTR(lv_tmp, LENGTH(lv_tmp) - 1, 1) = '6' THEN
    ln_meas := cn_meast_q4;
   END IF;

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка определена не однозначно.');
   END IF;

   --Вставка в parsingmakets
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   FOR j IN 0 .. 4 LOOP
    ln_col := 2 + j;
    ln_e := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.');
    parsingmakets_ins(gn_operation, i - 1, j + 1, lv_vimportcode, ln_mid, ln_meas, cn_timet_day, j, ld_date, ln_e, 1);
   END LOOP;
  END LOOP;

--  INSERT INTO tmp_saa  VALUES      (TO_CHAR(ld_sys, 'yyyymmddhh24miss') || '_0:' || 86400 *(ld_sys - SYSDATE));
  IF gb_pars THEN
   RETURN;
  END IF;

  ln_str := 1;
  ln_col := 1;

  FOR lc IN (SELECT   t.*,
                      CASE
                       WHEN ln_isxoe = 1
                           AND NOT((NVL(f.ed_position, 0) = -1 AND NVL(f.ninverted, 0) = 0)
                                   OR(NVL(f.ed_position, 0) != -1 AND NVL(f.ninverted, 0) = 1)) THEN 1
                       ELSE 0
                      END AS neeninv
             FROM     (SELECT   mid, MAX(DECODE(nmeasure, 1, DECODE(rate, 0, nvalue))) erm, MAX(DECODE(nmeasure, 2, DECODE(rate, 0, nvalue))) edm,
                                MAX(DECODE(nmeasure, 3, DECODE(rate, 0, nvalue))) q1m, MAX(DECODE(nmeasure, 4, DECODE(rate, 0, nvalue))) q2m,
                                MAX(DECODE(nmeasure, 5, DECODE(rate, 0, nvalue))) q3m, MAX(DECODE(nmeasure, 6, DECODE(rate, 0, nvalue))) q4m,
                                MAX(DECODE(nmeasure, 1, DECODE(rate, 1, nvalue))) aerm, MAX(DECODE(nmeasure, 2, DECODE(rate, 1, nvalue))) aedm,
                                MAX(DECODE(nmeasure, 3, DECODE(rate, 1, nvalue))) aq1m, MAX(DECODE(nmeasure, 4, DECODE(rate, 1, nvalue))) aq2m,
                                MAX(DECODE(nmeasure, 5, DECODE(rate, 1, nvalue))) aq3m, MAX(DECODE(nmeasure, 6, DECODE(rate, 1, nvalue))) aq4m,
                                MAX(DECODE(nmeasure, 1, DECODE(rate, 2, nvalue))) berm, MAX(DECODE(nmeasure, 2, DECODE(rate, 2, nvalue))) bedm,
                                MAX(DECODE(nmeasure, 3, DECODE(rate, 2, nvalue))) bq1m, MAX(DECODE(nmeasure, 4, DECODE(rate, 2, nvalue))) bq2m,
                                MAX(DECODE(nmeasure, 5, DECODE(rate, 2, nvalue))) bq3m, MAX(DECODE(nmeasure, 6, DECODE(rate, 2, nvalue))) bq4m,
                                MAX(DECODE(nmeasure, 1, DECODE(rate, 3, nvalue))) cerm, MAX(DECODE(nmeasure, 2, DECODE(rate, 3, nvalue))) cedm,
                                MAX(DECODE(nmeasure, 3, DECODE(rate, 3, nvalue))) cq1m, MAX(DECODE(nmeasure, 4, DECODE(rate, 3, nvalue))) cq2m,
                                MAX(DECODE(nmeasure, 5, DECODE(rate, 3, nvalue))) cq3m, MAX(DECODE(nmeasure, 6, DECODE(rate, 3, nvalue))) cq4m,
                                MAX(DECODE(nmeasure, 1, DECODE(rate, 4, nvalue))) derm, MAX(DECODE(nmeasure, 2, DECODE(rate, 4, nvalue))) dedm,
                                MAX(DECODE(nmeasure, 3, DECODE(rate, 4, nvalue))) dq1m, MAX(DECODE(nmeasure, 4, DECODE(rate, 4, nvalue))) dq2m,
                                MAX(DECODE(nmeasure, 5, DECODE(rate, 4, nvalue))) dq3m, MAX(DECODE(nmeasure, 6, DECODE(rate, 4, nvalue))) dq4m
                       FROM     parsingmakets
                       WHERE    noperation = gn_operation AND mid > 0 AND nvalue IS NOT NULL
                       GROUP BY mid) t,
                      feeders f
             WHERE    t.mid = f.mid(+) AND f.nblock = 0
             ORDER BY 1) LOOP
--Ищем номер счетчика
   lv_mtrsn := NULL;

   FOR lc1 IN (SELECT   mtrsn
               FROM     meters
               WHERE    mid = lc.mid
               ORDER BY DECODE(entype, 7, 0, entype)) LOOP
    lv_mtrsn := lc1.mtrsn;
    EXIT;
   END LOOP;

   IF lc.neeninv = 1 THEN                                                                                                                --Сложная штука для ХОЭ
    comsrv_pg.set_bill_meter(lc.mid, lc.edm, lc.erm, lc.q3m, lc.q1m, lc.q4m, lc.q2m, lc.aedm, lc.aerm, lc.aq3m, lc.aq1m, lc.aq4m, lc.aq2m, lc.bedm, lc.berm,
     lc.bq3m, lc.bq1m, lc.bq4m, lc.bq2m, lc.cedm, lc.cerm, lc.cq3m, lc.cq1m, lc.cq4m, lc.cq2m, lc.dedm, lc.derm, lc.dq3m, lc.dq1m, lc.dq4m, lc.dq2m, lv_mtrsn,
     NULL, ld_date);
    ld_tmp := indic_pg.recalcdiff(lc.mid, ld_date, 5);

    IF ld_date = TRUNC(ld_date, 'MONTH') THEN
     comsrv_pg.set_months_meter(lc.mid, lc.edm, lc.erm, lc.q3m, lc.q1m, lc.q4m, lc.q2m, lc.aedm, lc.aerm, lc.aq3m, lc.aq1m, lc.aq4m, lc.aq2m, lc.bedm, lc.berm,
      lc.bq3m, lc.bq1m, lc.bq4m, lc.bq2m, lc.cedm, lc.cerm, lc.cq3m, lc.cq1m, lc.cq4m, lc.cq2m, lc.dedm, lc.derm, lc.dq3m, lc.dq1m, lc.dq4m, lc.dq2m, lv_mtrsn,
      NULL, ld_date);
     ld_tmp := indic_pg.recalcdiff(lc.mid, ld_date, 6);
    END IF;
   ELSE
    comsrv_pg.set_bill_meter(lc.mid, lc.erm, lc.edm, lc.q1m, lc.q3m, lc.q2m, lc.q4m, lc.aerm, lc.aedm, lc.aq1m, lc.aq3m, lc.aq2m, lc.aq4m, lc.berm, lc.bedm,
     lc.bq1m, lc.bq3m, lc.bq2m, lc.bq4m, lc.cerm, lc.cedm, lc.cq1m, lc.cq3m, lc.cq2m, lc.cq4m, lc.derm, lc.dedm, lc.dq1m, lc.dq3m, lc.dq2m, lc.dq4m, lv_mtrsn,
     NULL, ld_date);
    ld_tmp := indic_pg.recalcdiff(lc.mid, ld_date, 5);

    IF ld_date = TRUNC(ld_date, 'MONTH') THEN
     comsrv_pg.set_months_meter(lc.mid, lc.erm, lc.edm, lc.q1m, lc.q3m, lc.q2m, lc.q4m, lc.aerm, lc.aedm, lc.aq1m, lc.aq3m, lc.aq2m, lc.aq4m, lc.berm, lc.bedm,
      lc.bq1m, lc.bq3m, lc.bq2m, lc.bq4m, lc.cerm, lc.cedm, lc.cq1m, lc.cq3m, lc.cq2m, lc.cq4m, lc.derm, lc.dedm, lc.dq1m, lc.dq3m, lc.dq2m, lc.dq4m, lv_mtrsn,
      NULL, ld_date);
     ld_tmp := indic_pg.recalcdiff(lc.mid, ld_date, 6);
    END IF;
   END IF;

   admin_pg.ins_last_save(lc.mid);

   IF ln_isxoe <> 1 THEN                                                                                                                         --Так попросили
    UPDATE last_save
    SET bill = GREATEST(NVL(bill, ld_date), ld_date),
        months = GREATEST(NVL(months, DECODE(ld_date, TRUNC(ld_date, 'MONTH'), ld_date, months)), DECODE(ld_date, TRUNC(ld_date, 'MONTH'), ld_date, months)),
        state_date = SYSDATE,
        state_cod = 0,
        clock = 0
    WHERE  mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
  SET bill = GREATEST(ld_date, NVL(bill, ld_date)),
      months = DECODE(TRUNC(ld_date, 'MONTH'), ld_date, GREATEST(ld_date, NVL(months, ld_date)), months)
  WHERE  mid = an_cid;
--  INSERT INTO tmp_saa VALUES      (TO_CHAR(ld_sys, 'yyyymmddhh24miss') || '_1:' || 86400 *(ld_sys - SYSDATE));  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30818n: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

