 PROCEDURE l_30816(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_tmp              DATE;
  lt_e                common_pg.tt_number;
  ln_block            NUMBER;
 BEGIN
  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data(1);
  ld_date := getdatabystr(util_pg.get_param(lv_ret, 2, lv_separator), an_cid);
  gd_date := ld_date;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   ln_tmp := SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2);

   --Ищем точку
   SELECT MAX(mid), COUNT(*), MAX(nblock)
   INTO   ln_mid, ln_tmp, ln_block
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid) AND TRIM(UPPER(vimportcode)) = TO_CHAR(ln_tmp);

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
    VALUES      (ln_mid);
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM(at_data(i));
    lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
    ld_tmp := TO_DATE(util_pg.get_param(lv_ret, 2, lv_separator), 'DD.MM.YYYY.HH24.MI.SS');
    --Проверяем что єто нужная строка
    ln_tmp := SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2);

    SELECT COUNT(*)
    INTO   ln_tmp
    FROM   DUAL
    WHERE  EXISTS(SELECT *
                  FROM   feeders
                  WHERE  TRIM(UPPER(vimportcode)) = TO_CHAR(ln_tmp) AND mid = lc.mid);

    IF ln_tmp = 1 THEN
     --Очистили
     FOR i IN 1 .. 27 LOOP
      lt_e(i) := NULL;
     END LOOP;

     FOR j IN 1 .. 27 LOOP
      ln_col := 2 + j;
      lt_e(j) := REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.');                                                -- и меняем запятую на точку
     END LOOP;

/*     COMSRV_PG.set_curr_power_meter (lc.mid, lt_e(7), lt_e(8), lt_e(9), lt_e(10), lt_e(11), lt_e(12),
            lt_e(13), lt_e(14),
            lt_e(15), lt_e(16), lt_e(17),
            lt_e(18), lt_e(19), lt_e(20),
            lt_e(24), lt_e(25), lt_e(26),
            lt_e(21), lt_e(22), lt_e(23),
            lt_e(1), lt_e(2), lt_e(3), lt_e(4), lt_e(5), lt_e(6),
            lt_e(27),
            3, ld_tmp);*/
     UPDATE curr_power
     SET erm = lt_e(7),
         edm = lt_e(8),
         q1m = lt_e(9),
         q3m = lt_e(10),
         q2m = lt_e(11),
         q4m = lt_e(12),
         date_time = ld_tmp,
         freq = lt_e(13),
         cosf = lt_e(14),
         volt = lt_e(15),
         volt2 = lt_e(16),
         volt3 = lt_e(17),
         currento = lt_e(18),
         curr2 = lt_e(19),
         curr3 = lt_e(20),
         er = lt_e(1),
         ed = lt_e(2),
         q1 = lt_e(3),
         q3 = lt_e(4),
         q2 = lt_e(5),
         q4 = lt_e(6),
         nfiu1 = lt_e(21),
         nfiu2 = lt_e(22),
         nfiu3 = lt_e(23),
         nfii1 = lt_e(24),
         nfii2 = lt_e(25),
         nfii3 = lt_e(26),
         ni0 = lt_e(27)
     WHERE  mid = lc.mid;

     IF SQL%ROWCOUNT = 0 THEN
      INSERT INTO curr_power
                  (mid, date_time, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, freq, cosf, volt, volt2, volt3, currento, curr2, curr3, nfiu1, nfiu2,
                   nfiu3, nfii1, nfii2, nfii3, ni0)
      VALUES      (lc.mid, ld_tmp, lt_e(1), lt_e(2), lt_e(3), lt_e(4), lt_e(5), lt_e(6), lt_e(7), lt_e(8), lt_e(9), lt_e(10), lt_e(11), lt_e(12), lt_e(13),
                   lt_e(14), lt_e(15), lt_e(16), lt_e(17), lt_e(18), lt_e(19), lt_e(20), lt_e(21), lt_e(22), lt_e(23), lt_e(24), lt_e(25), lt_e(26), lt_e(27));
     END IF;
    END IF;
   END LOOP;
  END LOOP;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30816: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

