 -- added by KAG 04.03.2011
 PROCEDURE l_10014(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  ln_start            NUMBER DEFAULT 0;
  ln_end              NUMBER DEFAULT 0;
  ln_rn               NUMBER DEFAULT 3;
  ln_block            NUMBER;
  ln_factcnt          NUMBER;
  cn_cnt     CONSTANT NUMBER DEFAULT 24;
  cn_cnt2    CONSTANT NUMBER DEFAULT 48;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  lv_ret              VARCHAR2(4000);
  lv_code             VARCHAR2(4000);
  ln_tmp              NUMBER;
  ln_mid              NUMBER;
  ld_date             DATE;
  ld_max              DATE;
  ld_correction       DATE;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_shift            NUMBER;
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (INSTR(at_data(i), '((//10014') > 0) THEN
    ln_start := i;
   END IF;

   IF (TRIM(at_data(i)) = '==))') THEN
    ln_end := i;
    EXIT;
   END IF;
  END LOOP;

  IF (ln_start = 0) THEN
   raise_application_error(-20001, 'Не найдено начало файла "((//10014"');
  END IF;

  IF (ln_end = 0) THEN
   raise_application_error(-20001, 'Не найден конец файла "==))"');
  END IF;

  ln_str := ln_start;
  ln_col := ln_start;
  lv_ret := at_data(ln_start);                                                                                                  --первая корректная строка файла
  ld_date := getdatabystr(util_pg.get_param(lv_ret, 2, lv_separator), an_cid);                                                --извлечение даты из первой строки
  gd_date := ld_date;
  ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

  -- textreport будем юзать для хранения загруженных дат коррекции точки
  DELETE FROM textreport;

  --Пробегаемся по файлу
  FOR i IN ln_start + 1 .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);
   lv_code := TRIM(util_pg.get_param(lv_ret, 1, lv_separator)) || ':' || TRIM(util_pg.get_param(lv_ret, 2, lv_separator));
   ld_correction := TO_DATE(TRIM(util_pg.get_param(lv_ret, 2, '==,,')), 'dd/mm/yy hh24:mi:ss');

   --Ищем точку по коду импорта, заданному в формате NN:NS:NB, где NS:NB - код точки в макете,
   SELECT MAX(mid), COUNT(*), MAX(nblock)
   INTO   ln_mid, ln_tmp, ln_block
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid)
          AND TRIM(UPPER(util_pg.get_param(vimportcode, 2, lv_separator))) || lv_separator || TRIM(UPPER(util_pg.get_param(vimportcode, 3, lv_separator))) =
                                                                                                                                                        lv_code;

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка для загрузки определена неоднозначно.');
   ELSIF ln_tmp = 0 OR ln_block = 1 THEN                                                                                                 --точки нет - выскочили
    GOTO to_continue;
   END IF;

   -- смотрим, нет ли у нас уже загруженных данных по точке с большим временем коррекции
   SELECT COUNT(*)
   INTO   ln_tmp
   FROM   textreport
   WHERE  norder = ln_mid AND TO_DATE(vtext, 'dd.mm.yyyy hh24:mi:ss') >= ld_correction;

   IF ln_tmp > 0 THEN
    GOTO to_continue;
   ELSE
    INSERT INTO textreport
                (norder, vtext)
    VALUES      (ln_mid, TO_CHAR(ld_correction, 'dd.mm.yyyy hh24:mi:ss'));
   END IF;

   FOR j IN 1 .. cn_cnt LOOP
    IF cn_cnt > ln_factcnt AND j = util_pg.switch_f + 1 THEN                                                                                            --Весна
     GOTO to_continue1;
    END IF;

    ln_er := REPLACE(TRIM(util_pg.get_param(lv_ret, 3 + j, lv_separator)), ',', '.') * 1000;
    --* на 1000 и меняем запятую на точку
    ln_col := 3 + j;

    IF ln_er IS NOT NULL THEN
     ld_max := ld_date + j / cn_cnt;
    END IF;

    IF SIGN(ln_er) IN(0, 1) THEN
     ln_ed := NULL;
    ELSE
     ln_ed := -ln_er;
     ln_er := NULL;
    END IF;

    IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
     --больше времени сдвига добавляем час
     ln_shift := 1 / 24;
    ELSE
     ln_shift := 0;
    END IF;

    das_pg.insert_hf_in_profile(ln_mid, util_pg.to_unlocaltime(ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift, 30, TRUNC(ln_er / 2, ln_rn),
     TRUNC(ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, ln_rn);
    inshalfhour(ln_mid, util_pg.to_unlocaltime(ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift, TRUNC(ln_er / 2, ln_rn), TRUNC(ln_ed / 2, ln_rn));
    das_pg.insert_hf_in_profile(ln_mid, util_pg.to_unlocaltime(ld_date) + 2 * j / cn_cnt2 + ln_shift, 30, ln_er - TRUNC(ln_er / 2, ln_rn),
     ln_ed - TRUNC(ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, ln_rn);
    inshalfhour(ln_mid, util_pg.to_unlocaltime(ld_date) + 2 * j / cn_cnt2 + ln_shift, ln_er - TRUNC(ln_er / 2, ln_rn), ln_ed - TRUNC(ln_ed / 2, ln_rn));

    IF ln_factcnt > cn_cnt AND j = util_pg.switch_f + 1 THEN                                                                               --Зима (добавили час)
     inshalfhour(ln_mid, util_pg.to_unlocaltime(ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift + 1 / 24, TRUNC(ln_er / 2, ln_rn), TRUNC(ln_ed / 2, ln_rn));
     inshalfhour(ln_mid, util_pg.to_unlocaltime(ld_date) + 2 * j / cn_cnt2 + ln_shift + 1 / 24, ln_er - TRUNC(ln_er / 2, ln_rn),
      ln_ed - TRUNC(ln_ed / 2, ln_rn));
    END IF;

    <<to_continue1>>
    NULL;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    admin_pg.ins_last_save(ln_mid);

    UPDATE last_save
    SET halfhour = ld_max + 1,
        state_date = SYSDATE,
        state_cod = 0,
        clock = 0
    WHERE  mid = ln_mid;
   END IF;

   <<to_continue>>
   NULL;
  END LOOP;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_10014: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

