-- added EVK 26.06.2006
 PROCEDURE l_30900(an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  cn_cnt     CONSTANT NUMBER DEFAULT 24;
  cn_cnt2    CONSTANT NUMBER DEFAULT 48;
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_rn               NUMBER DEFAULT 0;
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_max              DATE;
  ld_date             DATE;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  ln_start            NUMBER;
  ln_ttmp             NUMBER;
  ln_e                NUMBER;
  lv_type25           VARCHAR(1024) := get_type25(an_cid);
 BEGIN
  DELETE FROM parsingmakets
  WHERE       noperation = gn_operation;

  -- Ищем начало
  ln_start := 0;

  FOR i IN 1 .. ln_count LOOP
   lv_ret := at_data(i);

   IF INSTR(at_data(i), '((//30900:') > 0 THEN
    ln_start := i;
    EXIT;
   END IF;
  END LOOP;

  IF ln_start > 0 THEN
   ln_str := 1;
   ln_col := 1;
   lv_ret := at_data(ln_start);
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 2, lv_separator));
   ld_date := TO_DATE('20' || lv_tmp, 'YYYYMMDD');
   gd_date := ld_date;
   ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
   --Бегаем по файлу
   ln_start := ln_start + 1;

   FOR i IN ln_start .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := at_data(i);

    IF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ld_date) = 1 THEN                                                     --Это день перехода на лето
     lv_ret := skip_0(lv_ret, 1);
    END IF;

    IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ld_date) = -1 THEN                                                     --Это день перехода на зиму
     lv_ret := move_val(lv_ret, 1);
    END IF;

    IF SUBSTR(lv_ret, 1, 7) = '(3.1.N)' OR INSTR(lv_ret, '(3.1)') > 0 THEN
     IF SUBSTR(lv_ret, 1, 7) = '(3.1.N)' THEN
      ln_ttmp := util_pg.allnumber_f(SUBSTR(lv_ret, INSTR(lv_ret, ':', -1, 2) + 1, INSTR(lv_ret, ':', -1, 1) - INSTR(lv_ret, ':', -1, 2) - 1));
     ELSE
      ln_ttmp := 0;
     END IF;

     SELECT MAX(p.mid), COUNT(*)
     INTO   ln_mid, ln_tmp
     FROM   points p, chanpoint c
     WHERE  c.cid = an_cid AND c.mid = p.mid AND p.tag = ln_ttmp;

     IF ln_tmp > 1 THEN
      raise_application_error(-20002, 'Точка определена не однозначно!.');
     ELSIF ln_tmp = 0 THEN
      ln_e := util_pg.allnumber_f(REPLACE(util_pg.get_param(lv_ret, 2, lv_separator), ',', '.'));
      parsingmakets_ins(gn_operation, i - ln_start + 1, 1, ln_ttmp, NULL, cn_meast_a, cn_timet_hour_s, 0, ld_date + 1, ln_e);

      FOR j IN 1 .. ln_factcnt LOOP
       ln_e := util_pg.allnumber_f(REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.'));
       parsingmakets_ins(gn_operation, i - ln_start + 1, j + 1, ln_ttmp, NULL, cn_meast_a, cn_timet_hour, 0,
        util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, ln_e);                                                                 --точки нет - выскочили
      END LOOP;

      GOTO to_continue;
     END IF;
    ELSE
     GOTO to_continue;
    END IF;

    --Обнулили макс дату
    ld_max := ld_date - 1;
    ln_e := util_pg.allnumber_f(REPLACE(util_pg.get_param(lv_ret, 2, lv_separator), ',', '.'));
    parsingmakets_ins(gn_operation, i - ln_start + 1, 1, ln_ttmp, ln_mid, cn_meast_a, cn_timet_hour_s, 0, ld_date + 1, ln_e);

    FOR j IN 1 .. ln_factcnt LOOP
     ln_ed := util_pg.allnumber_f(REPLACE(util_pg.get_param(lv_ret, 2 + j, lv_separator), ',', '.'));                                 --меняем запятую на точку
     ln_col := j;
     parsingmakets_ins(gn_operation, i - ln_start + 1, j + 1, ln_ttmp, ln_mid, cn_meast_a, cn_timet_hour, 0,
      util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, ln_ed);

     IF ln_ed IS NOT NULL THEN
      ld_max := ld_date + j / cn_cnt;
     END IF;

     IF SIGN(ln_ed) >= 0 THEN
      ln_er := NULL;
     ELSE
      ln_er := -ln_ed;
      ln_ed := NULL;
     END IF;

     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
      --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile(ln_mid, ld_date + (2 * j - 1) / cn_cnt2, 30, TRUNC(ln_er / 2, ln_rn), TRUNC(ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, ln_rn);
     das_pg.insert_hf_in_profile(ln_mid, ld_date + 2 * j / cn_cnt2, 30, ln_er - TRUNC(ln_er / 2, ln_rn), ln_ed - TRUNC(ln_ed / 2, ln_rn), NULL, NULL, NULL,
      NULL, ln_rn);
     das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift, gn_source, TRUNC(ln_er / 2, ln_rn),
      TRUNC(ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_maket, NULL);
     das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + 2 * j / cn_cnt2 + ln_shift, gn_source, ln_er - TRUNC(ln_er / 2, ln_rn),
      ln_ed - TRUNC(ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_maket, NULL);
    END LOOP;

    IF ld_max > ld_date THEN
     UPDATE last_save
     SET halfhour = ld_date + 1,
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = ln_mid;
    END IF;

    <<to_continue>>
    NULL;
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30900: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

