-- added SSP ......
 PROCEDURE lp_zmd(an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  cn_cnt     CONSTANT NUMBER DEFAULT 24;
  cn_cnt2    CONSTANT NUMBER DEFAULT 48;
  lv_separator        VARCHAR2(8) DEFAULT '|';
  ln_rn               NUMBER DEFAULT 3;
  ln_count            NUMBER DEFAULT at_data.COUNT;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_max              DATE;
  ld_date             DATE;
  ln_kc               NUMBER;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q3               NUMBER;
  ln_erm              NUMBER;
  ln_edm              NUMBER;
  ln_q1m              NUMBER;
  ln_q3m              NUMBER;
  ch_st               VARCHAR2(1);
  ln_st               NUMBER;
  ln_shift            NUMBER;
  lv_date             VARCHAR2(32);
  lv_t1               VARCHAR2(32);
  lv_t2               VARCHAR2(32);
  f_dayswitch         NUMBER;
  f_st                NUMBER := 0;
  f_edm               NUMBER := 0;
  f_erm               NUMBER := 0;
  f_q3m               NUMBER := 0;
  f_q1m               NUMBER := 0;
  f_ed                NUMBER := 0;
  f_er                NUMBER := 0;
  f_q3                NUMBER := 0;
  f_q1                NUMBER := 0;
  k                   NUMBER;
  ln_separator        NUMBER := 0;
 --  ff          number;
 BEGIN
  SELECT MAX(c.mid), COUNT(*)
  INTO   ln_mid, ln_tmp
  FROM   feeders f, chanpoint c
  WHERE  c.cid = an_cid AND c.nskip IS NULL AND c.mid = f.mid AND DECODE(c.nuserescanal, 1, f.rescanal, f.canal) = TO_NUMBER(SUBSTR(av_filename, 1, 8));

  IF ln_tmp > 1 THEN
   raise_application_error(-20002, 'Точка определена не однозначно.');
  ELSIF ln_tmp = 0 THEN                                                                                                                              --точки нет
   raise_application_error(-20002, 'Точки нет');
  END IF;

  SELECT NVL(MAX(kc), 1)
  INTO   ln_kc
  FROM   feeders
  WHERE  mid = ln_mid;

  --Бегаем по файлу
  FOR i IN 1 .. ln_count LOOP
   lv_ret := at_data(i);

   IF lv_ret LIKE 'Clock (%' OR lv_ret LIKE 'Часы (%' THEN                                                                        -- строка описания параметров
    --            ln_length:=length(lv_ret);
    k := 1;
    ln_separator := 0;

    LOOP
     k := INSTR(lv_ret, lv_separator, k) + 1;

     IF k > 1 THEN
      ln_separator := ln_separator + 1;
     ELSE
      EXIT;
     END IF;
    END LOOP;

    f_st := 0;
    f_ed := 0;
    f_er := 0;
    f_q1 := 0;
    f_q3 := 0;
    f_edm := 0;
    f_erm := 0;
    f_q1m := 0;
    f_q3m := 0;
    ln_edm := NULL;
    ln_ed := NULL;
    ln_erm := NULL;
    ln_er := NULL;
    ln_q3m := NULL;
    ln_q3 := NULL;
    ln_q1m := NULL;
    ln_q1 := NULL;

    FOR j IN 1 .. ln_separator + 1 LOOP
     lv_tmp := TRIM(util_pg.get_param(lv_ret, j, lv_separator));

     IF lv_tmp LIKE '%Status%' OR lv_tmp LIKE '%Статус%' THEN
      f_st := j;
     ELSIF lv_tmp LIKE '%1.5.0%' THEN
      f_ed := j;
     ELSIF lv_tmp LIKE '%2.5.0%' THEN
      f_er := j;
     ELSIF lv_tmp LIKE '%3.5.0%' THEN
      f_q3 := j;
     ELSIF lv_tmp LIKE '%4.5.0%' THEN
      f_q1 := j;
     ELSIF lv_tmp LIKE '%1.8.0%' THEN
      f_edm := j;
     ELSIF lv_tmp LIKE '%2.8.0%' THEN
      f_erm := j;
     ELSIF lv_tmp LIKE '%3.8.0%' THEN
      f_q3m := j;
     ELSIF lv_tmp LIKE '%4.8.0%' THEN
      f_q1m := j;
     END IF;
    END LOOP;

    IF f_st = 0 THEN
     raise_application_error(-20002, 'Поле статуса неопределено');
    END IF;
   END IF;

   --      IF lv_ret LIKE '__.__.____ __:__:__%' THEN   -- новая получасовка
   IF lv_ret LIKE '__.__.____ __:_0:00%' THEN                                                                                               -- новая получасовка
    lv_tmp := TRIM(util_pg.get_param(lv_ret, f_st, lv_separator));

    IF SUBSTR(lv_tmp, 4, 1) = '8' THEN
     NULL;                                                                                                                                          -- >4 ?????
    ELSE
     ch_st := SUBSTR(lv_tmp, LENGTH(lv_tmp));

     IF ch_st >= '0' AND ch_st <= '8' THEN
      --        ln_st   := TO_NUMBER(substr(lv_tmp,length(lv_tmp)));
      ln_st := TO_NUMBER(ch_st);
      lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
      ld_date := TO_DATE(lv_tmp, 'DD.MM.YYYY HH24:MI:SS');
      f_dayswitch := util_pg.is_dayswitch(TRUNC(ld_date));                                                                                        -- (-1, 1, 0)
      ln_shift := 0;

      IF f_dayswitch = -1 THEN
       IF ln_st < 8 THEN
        ln_shift := -1;
       END IF;
      ELSIF f_dayswitch = 1 THEN
       IF ln_st > 4 THEN
        ln_shift := 1;
       END IF;
      END IF;

      IF f_edm > 0 THEN
       ln_edm := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_edm, lv_separator)));
      END IF;

      IF f_ed > 0 THEN
       ln_ed := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_ed, lv_separator))) * ln_kc;
      END IF;

      IF f_erm > 0 THEN
       ln_erm := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_erm, lv_separator)));
      END IF;

      IF f_er > 0 THEN
       ln_er := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_er, lv_separator))) * ln_kc;
      END IF;

      IF f_q3m > 0 THEN
       ln_q3m := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_q3m, lv_separator)));
      END IF;

      IF f_q3 > 0 THEN
       ln_q3 := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_q3, lv_separator))) * ln_kc;
      END IF;

      IF f_q1m > 0 THEN
       ln_q1m := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_q1m, lv_separator)));
      END IF;

      IF f_q1 > 0 THEN
       ln_q1 := TO_NUMBER(TRIM(util_pg.get_param(lv_ret, f_q1, lv_separator))) * ln_kc;
      END IF;

      das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + ln_shift / 24, gn_source, TRUNC(ln_er / 2, ln_rn), TRUNC(ln_ed / 2, ln_rn),
       TRUNC(ln_q1 / 2, ln_rn), TRUNC(ln_q3 / 2, ln_rn), NULL, NULL, ln_erm, ln_edm, ln_q1m, ln_q3m, NULL, NULL, ln_st, comsrv_pg.cn_lg_zxd, NULL);
     END IF;
    END IF;
   END IF;
  END LOOP;                                                                                                                             --FOR i IN 1 .. ln_count
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvfile_pg.lp_zmd: ' || 'Ошибка загр. данных ' || SQLERRM(SQLCODE));
 END;                                                                                                                                                  -- lp_zmd

