 PROCEDURE l_30902(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_rn               NUMBER DEFAULT 0;                                                                                          -- changed by EVK 09.09.08 !!!
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_max              DATE;
  ln_e                NUMBER;
  lt_e                common_pg.tt_number;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  cn_cnt              NUMBER;
  ln_type             NUMBER;
  ln_tmptype          NUMBER;
  ln_block            NUMBER;
  lv_str              VARCHAR(1024);
  lv_basemonth        VARCHAR2(8);
  lv_basecode         VARCHAR2(8);
 BEGIN
  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data(1);
  lv_basemonth := util_pg.get_param(lv_ret, 2, lv_separator);
  lv_basecode := util_pg.get_param(lv_ret, 3, lv_separator);

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_tmp := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2));

   IF lv_tmp IS NULL OR INSTR(lv_tmp, ';') > 0 THEN
    raise_application_error(-20001, 'Код точки не указан или указан не верно.');
   END IF;

   lv_tmp := TRIM(lv_basecode) || lv_tmp;

   --Ищем точку
   SELECT MAX(mid), COUNT(*), MAX(nblock)
   INTO   ln_mid, ln_tmp, ln_block
   FROM   feeders
   WHERE  mid IN(SELECT mid
                 FROM   chanpoint
                 WHERE  cid = an_cid) AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error(-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
    VALUES      (ln_mid);
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM(at_data(i));
    lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
    --Проверяем что это нужная строка
    lv_tmp := TRIM(lv_basecode) || UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2));

    SELECT COUNT(*), MAX(util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_tmp))
    INTO   ln_tmp, ln_type
    FROM   feeders
    WHERE  mid = lc.mid AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN
     lv_tmp := TRIM(util_pg.get_param(lv_ret, 2, lv_separator));

     IF TO_NUMBER(lv_tmp) > 0 AND TO_NUMBER(lv_tmp) <= 31 THEN
      lv_tmp := TRIM(lv_basemonth) || TRIM(lv_tmp);
      ld_date := TO_DATE(lv_tmp, 'YYMMDD');
      cn_cnt := 24;
      ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
      --Обнулили макс дату
      ld_max := ld_date - 1;

      --Очистили
      FOR i IN 1 .. ln_factcnt * 4 LOOP
       lt_e(i) := NULL;
      END LOOP;

      FOR j IN 1 .. ln_factcnt LOOP
       ln_col := 2 + j;                                                                                                                                  -- ???
       ln_e := REPLACE(util_pg.get_param(lv_ret, 3 + j, lv_separator), ',', '.');                                                    -- меняем запятую на точку

       IF ln_e < 0 THEN                                                                                                               --Если <0 то инвертируем.
        IF ln_type IN(1, 3) THEN
         ln_tmptype := ln_type + 1;
        ELSE
         ln_tmptype := ln_type - 1;
        END IF;

        ln_e := -ln_e;
       ELSE
        ln_tmptype := ln_type;
       END IF;

       lt_e(ln_factcnt *(ln_tmptype - 1) + j) := ln_e;

       IF ln_e IS NOT NULL THEN
        ld_max := ld_date + j / cn_cnt;
       END IF;
      END LOOP;
     END IF;
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
   FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
    lt_e(2 * i) := TRUNC(lt_e(i) / 2, ln_rn);
    lt_e(2 * i - 1) := lt_e(i) - lt_e(2 * i);
   END LOOP;

   --А теперь у нас всего больше в 2 раза стало
   cn_cnt := 2 * cn_cnt;
   ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e(j) IS NOT NULL OR lt_e(1 * ln_factcnt + j) IS NOT NULL OR lt_e(2 * ln_factcnt + j) IS NOT NULL OR lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
      --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j),
      lt_e(2 * ln_factcnt + j), NULL, lt_e(3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j),
      lt_e(3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    admin_pg.ins_last_save(lc.mid);

    UPDATE last_save
    SET halfhour = ld_max,
        state_date = SYSDATE,
        state_cod = 0,
        clock = 0
    WHERE  mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
  SET halfhour = GREATEST(ld_date + 1, NVL(halfhour, ld_date + 1))
  WHERE  mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
    'comsrvfile_pg.l_30902: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- added by KAG 11.10.2010
 -- процедура для проверки макета 30817 на наличие строк из макета 817
 FUNCTION check_30817_817(at_data common_pg.tt_varchar2)
  RETURN NUMBER IS                                                        -- 0-строк нет 1-строки из 30817 и 817 2-только строки из 817 3-только строки из 30817
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_start            NUMBER DEFAULT 0;
  ln_end              NUMBER DEFAULT 0;
  ln_817str           NUMBER DEFAULT 0;                                                                            -- кол-во строк из макета 817 (только сумма)
  ln_30817str         NUMBER DEFAULT 0;                                                                     -- кол-во строк из макета 30817 (сумма и почасовки)
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM(at_data(i)) LIKE '%((//30817%') THEN
    ln_start := i;
   END IF;

   IF (TRIM(at_data(i)) LIKE '%==))%') THEN
    ln_end := i;
   END IF;
  END LOOP;

  IF RTRIM(TRIM(REPLACE(at_data(ln_end), CHR(9), '')), '==))') IS NULL THEN                                                         -- если конец файла отдельно
   ln_end := ln_end - 1;                                                                                           -- уменьшаем, чтоб не попасть на конец файла
  END IF;

  -- считаем кол-во строк типа 817 и 30817
  FOR i IN ln_start + 1 .. ln_end LOOP
   IF LENGTH(TRIM(REPLACE(REPLACE(REPLACE(at_data(i), CHR(10), ''), CHR(9), ''), CHR(13), ''))) > 0 THEN
    IF TRIM(util_pg.get_param(at_data(i), 3, lv_separator)) IS NULL OR TRIM(util_pg.get_param(at_data(i), 4, lv_separator)) IS NULL THEN
     ln_817str := ln_817str + 1;
    ELSE
     ln_30817str := ln_30817str + 1;
    END IF;
   END IF;
  END LOOP;

  IF ln_817str > 0 AND ln_30817str > 0 THEN
   RETURN 1;                                                                                                                                    -- cn_30817_817
  ELSIF ln_817str > 0 AND ln_30817str = 0 THEN
   RETURN 2;                                                                                                                                          -- cn_817
  ELSIF ln_817str = 0 AND ln_30817str > 0 THEN
   RETURN 3;                                                                                                                                        -- cn_30817
  ELSIF ln_817str = 0 AND ln_30817str = 0 THEN
   RETURN 0;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- added by KAG 11.03.2009
 PROCEDURE l_817(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str              NUMBER DEFAULT 0;
  ln_col              NUMBER DEFAULT 0;
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_rn               NUMBER DEFAULT 3;
  ln_count            NUMBER DEFAULT at_data.COUNT - 1;
  ln_start            NUMBER DEFAULT 0;
  ln_end              NUMBER DEFAULT 0;
  ln_parselayer       NUMBER DEFAULT util_pg.getparamvaluev_f(gn_parselayerpid);
  lv_ret              VARCHAR2(4000);
  lv_tmp              VARCHAR2(4000);
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ld_date             DATE;
  ld_max              DATE;
  ld_tmp              DATE;
  lt_e                common_pg.tt_number;
  ln_block            NUMBER;
  ln_type             NUMBER;
  ln_tmptype          NUMBER;
  lt_info             averrate_pg.ttinfo;
  ln_e                NUMBER;
  cn_cnt              NUMBER;
  ln_factcnt          NUMBER;
  ln_shift            NUMBER;
  lt_bill_e           common_pg.tt_number;
  lb_loadbill         BOOLEAN;
  ln_sld              NUMBER;                                                                                   -- считать сальдо (5й параметр vimportcode = 1)
  ln_sld_peretok      NUMBER;                                                                                                               -- суточный переток
  ln_koeff            NUMBER;
  ln_position         NUMBER;                                                                              -- позиция расхода в строчке с несколькими расходами
 BEGIN
  --Ищем начало и конец файла           added by KAG 29.04.2009
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM(at_data(i)) LIKE '%((//%') THEN
    ln_start := i;
   END IF;

   IF (TRIM(at_data(i)) LIKE '%==))%') THEN
    ln_end := i;
   END IF;
  END LOOP;

  IF RTRIM(TRIM(REPLACE(at_data(ln_end), CHR(9), '')), '==))') IS NULL THEN                                                         -- если конец файла отдельно
   ln_end := ln_end - 1;                                                                                           -- уменьшаем, чтоб не попасть на конец файла
  END IF;

  IF (ln_start < 1) THEN
   raise_application_error(-20001, 'Не найдено начало файла.');
  END IF;

  IF (ln_end <= ln_start) THEN
   raise_application_error(-20001, 'Не найден конец файла.');
  END IF;

  --Читаем множительный КС
  SELECT NVL(MAX(util_pg.allnumber_f(addr)), 1)
  INTO   ln_koeff
  FROM   channels
  WHERE  cid = an_cid;

  IF ln_koeff <= 0 THEN
   ln_koeff := 1;
  END IF;

  --Проверяем начало
  ln_str := ln_start;
  ln_col := 1;
  lv_ret := at_data(ln_start);
  lv_tmp := util_pg.get_param(lv_ret, 2, lv_separator);

  IF LENGTH(lv_tmp) = 4 THEN
   ld_date := TO_DATE(EXTRACT(YEAR FROM SYSDATE) || lv_tmp, 'YYYYMMDD');
  ELSIF LENGTH(lv_tmp) = 6 THEN
   ld_date := TO_DATE(lv_tmp, 'YYMMDD');                                                                               -- для 817 макета, помеченного как 30817
  ELSE
   raise_application_error(-20001, 'Неверный формат даты для макета 817. Необходимо MMDD.');
  END IF;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN ln_start + 1 .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data(i);
   lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));

   IF SUBSTR(lv_tmp, 1, 1) <> '(' OR SUBSTR(lv_tmp, LENGTH(lv_tmp)) <> ')' THEN
    raise_application_error(-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_tmp := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2));

   IF lv_tmp IS NULL AND ln_parselayer = 0 THEN
    raise_application_error(-20001, 'Код точки не указан или указан не верно. lv_tmp='||lv_tmp);
   END IF;

   --Ищем точку
   FOR lc IN (SELECT   MAX(mid) mid, COUNT(*) cnt, MAX(nblock) blocked
              FROM     feeders
              WHERE    mid IN(SELECT mid
                              FROM   chanpoint
                              WHERE  cid = an_cid) AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_tmp) BETWEEN 1 AND 4
              GROUP BY NVL(util_pg.get_param(TRIM(UPPER(vimportcode)), 6, ';'), 1)) LOOP
    IF lc.cnt > 1 THEN
     raise_application_error(-20001, 'Точка определена не однозначно.');
    ELSIF lc.cnt = 1 AND lc.blocked = 0 THEN
     INSERT INTO textreport
                 (norder)
     VALUES      (lc.mid);
    END IF;
   END LOOP;                                                                                  -- цикл по точкам с одинаковым кодом импорта, но разными позициями
  END LOOP;

----------
  FOR lc IN (SELECT DISTINCT norder mid
             FROM            textreport) LOOP
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. 50 * 4 LOOP                                                                     -- 4 - кол-во показаний (А+,A-,R+,R-) edited by KAG 12.03.2009
    lt_e(i) := NULL;
   END LOOP;

   FOR i IN 1 .. 4 LOOP
    lt_bill_e(i) := NULL;
   END LOOP;

   lb_loadbill := FALSE;
   ln_sld := 0;
   ln_position := 1;

   --Поискали нужные строки
   FOR i IN ln_start + 1 .. ln_end LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM(at_data(i));
    lv_tmp := TRIM(util_pg.get_param(lv_ret, 1, lv_separator));
    --Убираем скобки
    lv_tmp := UPPER(SUBSTR(lv_tmp, 2, LENGTH(lv_tmp) - 2));

    --Проверяем что єто нужная строка
    SELECT COUNT(*), MAX(util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_tmp)),
           MAX(NVL(util_pg.allnumber_f(util_pg.get_param(TRIM(vimportcode), 5, ';')), 0)),
           MAX(NVL(util_pg.allnumber_f(util_pg.get_param(TRIM(vimportcode), 6, ';')), 1))
    -- позиция расхода в строчке для каждой точки
    INTO   ln_tmp, ln_type, ln_sld, ln_position
    FROM   feeders
    WHERE  mid = lc.mid AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN
     ln_col := INSTR(lv_ret, lv_separator);
     lv_ret := TRIM(util_pg.get_param(lv_ret, ln_position + 1, lv_separator));
     -- получение суммы по позиции для текущей точки
     averrate_pg.createtinfo(lc.mid, ld_date + 1 / 86400, ld_date + 1, ln_type, 0, TO_NUMBER(lv_ret) * ln_koeff, lt_info);
     lb_loadbill := TRUE;
     cn_cnt := 48;
     ln_factcnt := lt_info.COUNT;

     FOR i IN 1 .. ln_factcnt LOOP
      ln_e := lt_info(i).e;

      IF ln_e < 0 THEN                                                                                                                --Если <0 то инвертируем.
       IF ln_type IN(1, 3) THEN
        ln_tmptype := ln_type + 1;
       ELSE
        ln_tmptype := ln_type - 1;
       END IF;

       ln_e := -ln_e;
      ELSE
       ln_tmptype := ln_type;
      END IF;

      lt_e(ln_factcnt *(ln_tmptype - 1) + i) := ln_e;                                                                             -- заполняем массив значениями

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + i / cn_cnt;
      END IF;
     END LOOP;

---------------------------------------
-- подсчет суточных
     IF TO_NUMBER(lv_ret) < 0 THEN                                                                                                     --Если <0 то инвертируем.
      IF ln_type IN(1, 3) THEN
       ln_tmptype := ln_type + 1;
      ELSE
       ln_tmptype := ln_type - 1;
      END IF;

      lt_bill_e(ln_tmptype) := -TO_NUMBER(lv_ret) * ln_koeff;
     ELSE
      ln_tmptype := ln_type;
      lt_bill_e(ln_tmptype) := TO_NUMBER(lv_ret) * ln_koeff;
     END IF;
    END IF;                                                                                                                                         --ln_tmp = 1
   END LOOP;

   -- added by KAG 19.05.2009
   IF ln_sld = 1 THEN                                                                                                                    -- надо считать переток
    -- очищаем от расходов
    FOR i IN 1 .. 50 * 4 LOOP                                                                    -- 4 - кол-во показаний (А+,A-,R+,R-) edited by KAG 12.03.2009
     lt_e(i) := NULL;
    END LOOP;

    -- суточный переток актива
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(1), lt_bill_e(2));                                                                        -- считаем переток

    IF ln_sld_peretok < 0 THEN
     lt_bill_e(2) := -ln_sld_peretok;
     lt_bill_e(1) := NULL;
    ELSE
     lt_bill_e(1) := ln_sld_peretok;
     lt_bill_e(2) := NULL;
    END IF;

    -- суточный переток реактива
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(3), lt_bill_e(4));                                                                        -- считаем переток

    IF ln_sld_peretok < 0 THEN
     lt_bill_e(4) := -ln_sld_peretok;
     lt_bill_e(3) := NULL;
    ELSE
     lt_bill_e(3) := ln_sld_peretok;
     lt_bill_e(4) := NULL;
    END IF;

    -------- считаем актив
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(1), lt_bill_e(2));                                                                        -- считаем переток

    IF ln_sld_peretok IS NOT NULL THEN                                                                                                           -- переток есть
     averrate_pg.createtinfo(lc.mid, ld_date + 1 / 86400, ld_date + 1, 0, 0, ln_sld_peretok, lt_info);
     cn_cnt := 48;
     ln_factcnt := lt_info.COUNT;

     FOR i IN 1 .. ln_factcnt LOOP
      ln_e := lt_info(i).e;

      IF ln_e < 0 THEN                                                                                                                       -- кладем в отдачу
       ln_tmptype := 2;
       ln_e := -ln_e;
      ELSE                                                                                                                                     -- кладем в прием
       ln_tmptype := 1;
      END IF;

      lt_e(ln_factcnt *(ln_tmptype - 1) + i) := ln_e;                                                                             -- заполняем массив значениями

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + i / cn_cnt;
      END IF;
     END LOOP;
    END IF;

    ------- считаем реактив
    ln_sld_peretok := util_pg.sld(lc.mid, lt_bill_e(3), lt_bill_e(4));                                                                        -- считаем переток

    IF ln_sld_peretok IS NOT NULL THEN                                                                                                           -- переток есть
     averrate_pg.createtinfo(lc.mid, ld_date + 1 / 86400, ld_date + 1, 0, 0, ln_sld_peretok, lt_info);
     cn_cnt := 48;
     ln_factcnt := lt_info.COUNT;

     FOR i IN 1 .. ln_factcnt LOOP
      ln_e := lt_info(i).e;

      IF ln_e < 0 THEN                                                                                                                       -- кладем в отдачу
       ln_tmptype := 4;
       ln_e := -ln_e;
      ELSE                                                                                                                                     -- кладем в прием
       ln_tmptype := 3;
      END IF;

      lt_e(ln_factcnt *(ln_tmptype - 1) + i) := ln_e;                                                                             -- заполняем массив значениями

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + i / cn_cnt;
      END IF;
     END LOOP;
    END IF;
   END IF;

------------
   ln_str := ln_start;
   ln_col := 1;

   IF cn_cnt = 24 THEN                                                                                       -- раскидываем только если у нас еще не получасовки
    --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
    FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
     lt_e(2 * i) := TRUNC(lt_e(i) / 2, ln_rn);
     lt_e(2 * i - 1) := lt_e(i) - lt_e(2 * i);
    END LOOP;

    --А теперь у нас всего больше в 2 раза стало
    cn_cnt := 2 * cn_cnt;
    ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);
   END IF;

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e(j) IS NOT NULL OR lt_e(1 * ln_factcnt + j) IS NOT NULL OR lt_e(2 * ln_factcnt + j) IS NOT NULL OR lt_e(3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) *(util_pg.switch_f + 1) AND j <= cn_cnt THEN
      --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e(j), lt_e(1 * ln_factcnt + j),
      lt_e(2 * ln_factcnt + j), NULL, lt_e(3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour(lc.mid, util_pg.to_unlocaltime(ld_date) + j / cn_cnt + ln_shift, lt_e(j), lt_e(1 * ln_factcnt + j), lt_e(2 * ln_factcnt + j),
      lt_e(3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF lb_loadbill THEN                                                                                                                        -- запись суточных
    comsrv_pg.set_bill_eom(lc.mid, lt_bill_e(1), lt_bill_e(2), lt_bill_e(3), lt_bill_e(4), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
     NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ld_date + 1);

    IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
     admin_pg.ins_last_save(lc.mid);

     UPDATE last_save
     SET halfhour = util_pg.to_unlocaltime(ld_max),
         bill = GREATEST(NVL(bill, ld_max), ld_max),
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END IF;
   ELSE                                                                                                           -- суточные по данной точке не будут грузиться
    IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
     admin_pg.ins_last_save(lc.mid);

     UPDATE last_save
     SET halfhour = util_pg.to_unlocaltime(ld_max),
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END IF;
   END IF;
  END LOOP;                                                                                                                                    -- цикл по точкам

  UPDATE last_save
  SET halfhour = util_pg.to_unlocaltime(GREATEST(ld_date + 1, NVL(util_pg.to_localtime(halfhour), ld_date + 1))),
      bill = GREATEST(ld_date + 1, NVL(bill, ld_date + 1))
  WHERE  mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvfile_pg.l_817: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- added by KAG 11.10.2010
 PROCEDURE l_30817_817(an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  lv_separator        VARCHAR2(8) DEFAULT ':';
  ln_start            NUMBER DEFAULT 0;
  ln_end              NUMBER DEFAULT 0;
  ln_817str           NUMBER DEFAULT 0;                                                                            -- кол-во строк из макета 817 (только сумма)
  ln_30817str         NUMBER DEFAULT 0;                                                                     -- кол-во строк из макета 30817 (сумма и почасовки)
  lt_data817          common_pg.tt_varchar2;
  lt_data30817        common_pg.tt_varchar2;
 BEGIN
  BEGIN
   --Ищем начало и конец файла
   FOR i IN 1 .. at_data.COUNT LOOP
    IF (TRIM(at_data(i)) LIKE '%((//30817%') THEN
     ln_start := i;
    END IF;

    IF (TRIM(at_data(i)) LIKE '%==))%') THEN
     ln_end := i;
    END IF;
   END LOOP;

   IF RTRIM(TRIM(REPLACE(at_data(ln_end), CHR(9), '')), '==))') IS NULL THEN                                                        -- если конец файла отдельно
    ln_end := ln_end - 1;                                                                                          -- уменьшаем, чтоб не попасть на конец файла
   END IF;

   ln_817str := 1;
   ln_30817str := 1;
   lt_data817(ln_817str) := at_data(ln_start);
   lt_data30817(ln_30817str) := at_data(ln_start);

   -- разделяем макеты 30817 и 817
   FOR i IN ln_start + 1 .. ln_end LOOP
    IF TRIM(util_pg.get_param(at_data(i), 3, lv_separator)) IS NULL OR TRIM(util_pg.get_param(at_data(i), 4, lv_separator)) IS NULL THEN
     ln_817str := ln_817str + 1;
     lt_data817(ln_817str) := at_data(i);
    ELSE
     ln_30817str := ln_30817str + 1;
     lt_data30817(ln_30817str) := at_data(i);
    END IF;
   END LOOP;

   -- дописываем концовку файла если надо
   IF lt_data817(ln_817str) NOT LIKE '%==))%' THEN
    lt_data817(ln_817str + 1) := '==))';
   END IF;

   IF lt_data30817(ln_30817str) NOT LIKE '%==))%' THEN
    lt_data30817(ln_30817str + 1) := '==))';
   END IF;
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20001, 'comsrvfile_pg.l_30817_817: Ошибка разделения макетов. ' || CHR(10) || SQLERRM(SQLCODE));
  END;

  -- грузим оба макета по отдельности
  l_817(an_cid, lt_data817);
  l_30817(an_cid, prepare_nek(lt_data30817));
 EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20001, 'comsrvfile_pg.l_30817_817: Ошибка загрузки макетов. ' || CHR(10) || SQLERRM(SQLCODE));

 END;

------------------------------------------------------------------------------------------------------------------------
 -- Процедура отметки о копировании файла
 PROCEDURE mark_copy_files(an_cid NUMBER, av_filename VARCHAR2, av_filedate DATE) IS
 BEGIN
  INSERT INTO copyfiles
              (cid, vfilename, dfiledate)
  VALUES      (an_cid, av_filename, av_filedate);
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   NULL;
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrvfile_pg.mark_copy_files: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_source
  RETURN NUMBER IS
 BEGIN
  RETURN gn_source;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- возвращает для канала 1 если на него надо грузить BLOB, иначе грузим CLOB
 FUNCTION is_blobchannel(an_cid NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT NVL(MAX(DECODE(protocol_id, 113, 1, 0)), 0)
  INTO   ln_ret
  FROM   channels
  WHERE  cid = an_cid;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- возвращает доп параметр для канала
 FUNCTION get_addparam(an_cid NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(2000);
 BEGIN
  SELECT MAX(vaddparam)
  INTO   lv_ret
  FROM   channels
  WHERE  cid = an_cid;

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- возвращает вариант парсинга при переводе времени
 FUNCTION get_type25(an_cid NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(2000);
 BEGIN
  SELECT util_pg.get_param(MAX(init_str), 5, ';')
  INTO   lv_ret
  FROM   channels c
  WHERE  cid = an_cid;

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE parsingmakets_ins(
 an_operation NUMBER, an_row NUMBER, an_col NUMBER, av_code VARCHAR2, an_mid NUMBER, an_measure NUMBER, an_timetype NUMBER, an_rate NUMBER, ad_datetime DATE,
 an_value NUMBER, ln_always NUMBER
 ) IS
 BEGIN
  IF ln_always = 1 OR gb_pars THEN
   INSERT INTO parsingmakets
               (noperation, nrow, ncol, vcode, mid, nmeasure, ntimetype, rate, ddatetime, nvalue)
   VALUES      (an_operation, an_row, an_col, av_code, an_mid, an_measure, an_timetype, an_rate, ad_datetime, an_value);
  END IF;
 END;
------------------------------------------------------------------------------------------------------------------------
BEGIN
 IF FALSE AND util_pg.get_customer_id = 1 THEN
  gn_source := 20;
 ELSE
  gn_source := comsrv_pg.cn_auto;
 END IF;
------------------------------------------------------------------------------------------------------------------------
END;
