-- Start of DDL Script for Package Body RYDA.COMSRVMTX_PG
-- Generated 14.04.2014 9:34:57 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY comsrvmtx_pg IS
------------------------------------------------------------------------------------------------------------------------
 cn_mtxport CONSTANT NUMBER := 127;

------------------------------------------------------------------------------------------------------------------------
   -- Интерфейс взаимодействия БД с драйвером МТХ
   -- дата создания 02/04/2012
------------------------------------------------------------------------------------------------------------------------
 --По опросчику возвращает номер IP порта для MTX Router
 FUNCTION getmtxport_f(an_srv NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN NVL(util_pg.allnumber_f(util_pg.get_param(util_pg.getparamvaluev_f(57), an_srv)), 0);
 END;

------------------------------------------------------------------------------------------------------------------------
 --По опросчику возвращает номер IP порта для MTX Router
 FUNCTION getmtxcount_f(an_srv NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN NVL(util_pg.allnumber_f(util_pg.get_param(util_pg.getparamvaluev_f(58), an_srv)), 0);
 END;

------------------------------------------------------------------------------------------------------------------------
 --По адресу MTX Router возвращает его mid
 FUNCTION getmtxmid_f(av_addr VARCHAR2)
  RETURN NUMBER IS
  ln_mid              NUMBER;
 BEGIN
  SELECT NVL(MAX(mid), 0)
  INTO   ln_mid
  FROM   mtxconf
  WHERE  addr = av_addr;

  RETURN ln_mid;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION getmtxcomid_f(an_srv NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER := 0;
  ln_mtxport          NUMBER := getmtxport_f(an_srv);
  ln_mtxcount         NUMBER := getmtxcount_f(an_srv);
 BEGIN
  IF ln_mtxport > 0 AND ln_mtxcount > 0 THEN
   SELECT NVL(MAX(comsrvdisp_pg.getportid_f(cn_mtxport, an_srv)), 0)
   INTO   ln_ret
   FROM   DUAL
   WHERE  EXISTS(SELECT *
                 FROM   channels
                 WHERE  protocol_id = comsrvdisp_pg.cn_mtxprotocol AND com_id IN(SELECT com_id
                                                                                 FROM   comports
                                                                                 WHERE  nsrv = an_srv));
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------

 --Инициализация нити опроса MTX
 FUNCTION initmtx_f(an_ipport OUT NUMBER, an_maxcount OUT NUMBER, an_srv NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER := 0;
  ln_port             NUMBER;
  ln_mtxport          NUMBER := getmtxport_f(an_srv);
  ln_mtxcount         NUMBER := getmtxcount_f(an_srv);
 BEGIN
  IF ln_mtxport > 0 AND ln_mtxcount > 0 THEN
   ln_ret := NVL(comsrvdisp_pg.getportid_f(cn_mtxport, an_srv), 0);
  END IF;

  IF ln_ret > 0 THEN
   an_ipport := ln_mtxport;
   an_maxcount := ln_mtxcount;
   ln_ret := cn_mtxport;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_passivedvs(
 an_cid NUMBER, an_retcid OUT NUMBER, lv_addr OUT VARCHAR2, lv_name OUT VARCHAR2, ln_protocol_id OUT NUMBER, lv_init_str OUT VARCHAR2, ln_retries OUT NUMBER,
 ln_retries_tout OUT NUMBER, ln_is_block OUT NUMBER, ln_billdata OUT NUMBER, ln_billdatadepth OUT NUMBER, ln_techdata OUT NUMBER, ln_techdatadepth OUT NUMBER,
 ln_journal OUT NUMBER, ln_netparam OUT NUMBER, lv_user OUT VARCHAR2, lv_pass OUT VARCHAR2, lv_note OUT VARCHAR2, ln_wait OUT NUMBER
 )
  RETURN NUMBER IS
  ld_sys              DATE := SYSDATE;
 BEGIN
  FOR lc IN (SELECT cid, NVL(addr, '0') addr, SUBSTR(NVL(vname, 'Без имени'), 1, 31) vname, protocol_id, SUBSTR(NVL(init_str, ' '), 1, 63) init_str,
                    NVL(retries, 1) retries, NVL(retries_tout, 0) retries_tout, channels_pg.is_block(cid, blocking, nkind) blocking, nbilldata,
                    NVL(nbilldatadepth, 7) nbilldatadepth, ncurrdata, NVL(ncurrdatadepth, 7) ncurrdatadepth,
                    comsrvdisp_pg.get_journal(an_cid, njournal, ld_sys) njournal, comsrvdisp_pg.get_netparam(an_cid, nnetparam, ld_sys) nnetparam,
                    NVL(vaccuser, ' ') vaccuser, NVL(vaccpassword, ' ') vaccpassword, NVL(vnote, ' ') vnote, nwait
             FROM   channels
             WHERE  cid = an_cid AND protocol_id = comsrvdisp_pg.cn_mtxprotocol) LOOP
   an_retcid := lc.cid;
   lv_addr := lc.addr;
   lv_name := lc.vname;
   ln_protocol_id := lc.protocol_id;
   lv_init_str := lc.init_str;
   ln_retries := lc.retries;
   ln_retries_tout := lc.retries_tout;
   ln_is_block := lc.blocking;
   ln_billdata := lc.nbilldata;
   ln_billdatadepth := lc.nbilldatadepth;
   ln_techdata := lc.ncurrdata;
   ln_techdatadepth := lc.ncurrdatadepth;
   ln_journal := lc.njournal;
   ln_netparam := lc.nnetparam;
   lv_user := lc.vaccuser;
   lv_pass := lc.vaccpassword;
   lv_note := lc.vnote;
   ln_wait := lc.nwait;

   IF ln_techdata = 0 THEN     --ln_techdata - определяет выдачу запроса на чтение конфигурации устройства (список счетчиков). При первом чтении всегда читаем.
    SELECT COUNT(*)
    INTO   ln_techdata
    FROM   DUAL
    WHERE  NOT EXISTS(SELECT *
                      FROM   mtxconfdet
                      WHERE  mid IN(SELECT mid
                                    FROM   mtxconf
                                    WHERE  nmtrsn = util_pg.allnumber_f(lc.addr)));
   END IF;

   RETURN 1;
  END LOOP;

  RETURN 0;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'COMSRVMTX_PG.get_PassiveDVS: ' || SQLERRM(SQLCODE));
 END;

