------------------------------------------------------------------------------------------------------------------------
--Запись журнала
 PROCEDURE set_journal(an_mid NUMBER, an_event common_pg.tt_number, av_date common_pg.tt_varchar2, an_type NUMBER) IS
  cn_deferrcode CONSTANT NUMBER := 630;
  ln_event            NUMBER;
  ld_date             DATE;
  ld_max              DATE;
 BEGIN
  SAVEPOINT set_journal_sp;

  FOR i IN 1 .. an_event.COUNT LOOP
   IF av_date(i) IS NULL OR NVL(an_event(i), 0) <= 0 THEN
    RETURN;
   END IF;

   ld_date := TO_DATE(av_date(i), 'dd.mm.yyyy hh24:mi:ss');

   SELECT NVL(MAX(nevent), cn_deferrcode)
   INTO   ln_event
   FROM   metereventsdict
   WHERE  nmetertype = comsrv_pg.cn_mtx AND neventcode = an_event(i) AND neventclass = DECODE(an_type, 1, 1, 3);

   admin_pg.ins_journal_p(ld_date, an_mid, 0, '', ln_event, an_event(i));
   ld_max := GREATEST(NVL(ld_max, ld_date), ld_max);
  END LOOP;

  UPDATE last_save
  SET journal = ld_max
  WHERE  mid = an_mid AND(NVL(journal, ld_max - 1) < ld_max);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_journal_sp;
   raise_application_error(-20001, 'set_journal: mid=' || an_mid || ' ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_state(
 an_mid NUMBER,                                                                                                                            --Ид точки или канала
               an_state_cod NUMBER,                                                                                                              --Код сообщения
                                   av_state_descr VARCHAR2,                                                                                    --Текст сообщения
                                                           an_clock NUMBER DEFAULT 0                                                         --Расхождение часов
 ) IS
  ln_curr_cod         NUMBER;
  ln_clock            NUMBER := NVL(an_clock, 0);
 BEGIN
  SELECT MAX(NVL(state_cod, 100))
  INTO   ln_curr_cod
  FROM   last_save
  WHERE  mid = an_mid;

  IF ln_curr_cod IS NULL OR ln_curr_cod <> an_state_cod THEN
   IF an_state_cod >= 0 THEN
    comsrvcim_pg.upd_lastsave(an_mid, an_state_cod, av_state_descr, ln_clock);
   ELSE
    comsrvcim_pg.upd_lastsave(an_mid, an_state_cod, 'Штатный режим', ln_clock);
   END IF;

   comsrvcim_pg.ins_journal(an_mid, an_state_cod, NVL(av_state_descr, 'Штатный режим'));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'set_state: mid=' || an_mid || ' ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Запись конфигурации MTX RT
 PROCEDURE set_conf(
 an_cid NUMBER,                                                                                                                                      --Ид канала
               av_addr VARCHAR2,                                                                                                                     --Ком адрес
                                av_mac common_pg.tt_varchar2,                                                                              -- mac адрес счетчика
                                                             an_type common_pg.tt_number,                                                         --тип счетчика
                                                                                         an_production common_pg.tt_number,                   --год изготовления
 an_mtrsn common_pg.tt_number, av_id common_pg.tt_varchar2                                                                                        -- ИД счетчика
 --номер счетчика
 ) IS
  ld_date             DATE;
  ln_mid              NUMBER;
 BEGIN
  SAVEPOINT set_conf_sp;
  ln_mid := getmtxmid_f(av_addr);

  IF ln_mid <= 0 THEN
   raise_application_error(-20001, 'Устройство ''' || av_addr || '''не найдено.');
  END IF;

  DELETE FROM mtxconfdet
  WHERE       mid = ln_mid;

  FOR i IN 1 .. an_mtrsn.COUNT LOOP
   IF NVL(an_mtrsn(i), 0) = 0 THEN
    EXIT;
   END IF;

   IF NVL(an_production(i), 0) < 1900 THEN
    ld_date := TO_DATE('19000101', 'YYYYMMDD');
   ELSE
    ld_date := TO_DATE(an_production(i) || '0101', 'YYYYMMDD');
   END IF;

   INSERT INTO mtxconfdet
               (mid, norder, vmac, ntype, dproduction, nmtrsn, vid)
   VALUES      (ln_mid, i, av_mac(i), an_type(i), ld_date, an_mtrsn(i), av_id(i));
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_conf_sp;
   raise_application_error(-20001, 'set_conf: an_cid=' || an_cid || ' ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Чтение конфигурации MTX RT
 FUNCTION get_conf(
 an_cid NUMBER,                                                                                                                                      --Ид канала
               av_addr OUT VARCHAR2,                                                                                                                 --Ком адрес
                                    av_mac OUT common_pg.tt_varchar2,                                                                      -- mac адрес счетчика
                                                                     an_type OUT common_pg.tt_number,                                             --тип счетчика
                                                                                                     an_production OUT common_pg.tt_number,   --год изготовления
 an_mtrsn OUT common_pg.tt_number,                                                                                                              --номер счетчика
                                  av_id OUT common_pg.tt_varchar2                                                                                 -- ИД счетчика
 )
  RETURN NUMBER                                                                                                     --Возвращает количество элементов в массивах
               IS
  ln_ret              NUMBER := 0;
  ln_mid              NUMBER;
 BEGIN
  SELECT NVL(MAX(addr), ' '), MAX(mid)
  INTO   av_addr, ln_mid
  FROM   mtxconf
  WHERE  nmtrsn = (SELECT util_pg.allnumber_f(MAX(addr))
                   FROM   channels
                   WHERE  cid = an_cid);

  FOR lc IN (SELECT   vmac, ntype, dproduction, nmtrsn, vid
             FROM     mtxconfdet
             WHERE    mid = ln_mid
             ORDER BY norder) LOOP
   ln_ret := ln_ret + 1;
   av_mac(ln_ret) := lc.vmac;
   an_type(ln_ret) := lc.ntype;
   an_production(ln_ret) := TO_CHAR(lc.dproduction, 'YYYY');
   an_mtrsn(ln_ret) := lc.nmtrsn;
   av_id(ln_ret) := lc.vid;
  END LOOP;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_mtxstate(av_addr VARCHAR2,                                                                                                            --Ком адрес
                                         an_mtrsn NUMBER,                                                                                                --Номер
                                                         an_state NUMBER                                                                             --Состояние
                                                                        ) IS
  ln_mid              NUMBER;
 BEGIN
  SAVEPOINT set_mtxstate_sp;

  UPDATE mtxconf
  SET nmtrsn = an_mtrsn,
      nstate = an_state,
      dstate = SYSDATE
  WHERE  addr = av_addr;

  IF SQL%ROWCOUNT = 0 THEN
   SELECT points_seq.NEXTVAL
   INTO   ln_mid
   FROM   DUAL;

   INSERT INTO points
               (mid, PARENT, cod, ind, NAME, short_name, implement_date, tag)
   VALUES      (ln_mid, util_pg.cn_mtxmid, 0, 2, av_addr, '', SYSDATE, 0);

   admin_pg.ins_last_save(ln_mid);

   INSERT INTO mtxconf
               (mid, addr, nmtrsn, nstate)
   VALUES      (ln_mid, av_addr, an_mtrsn, an_state);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_mtxstate_sp;
   raise_application_error(-20001, 'set_mtxstate: addr=' || av_addr || ' ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Для отображения в задаче состояния опроса MTX устройств
 PROCEDURE get_mtxstate(an_sort NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
 BEGIN
  lv_sql :=
      'SELECT   a.mid, a.addr, a.nmtrsn, a.denter, a.nstate, a.dstate, '
   || '        DECODE(nstate, 0, "Неопределено", 1, "Новый", 2, "Присоеденен", 3, "Отсоеденен", 4, "Готов", "Другое") vstate, c.vname, c.cid '
   || 'FROM     mtxconf a, '
   || '         (SELECT util_pg.allnumber_f(addr) addr, vname, cid '
   || '          FROM   channels '
   || '          WHERE  protocol_id = '
   || comsrvdisp_pg.cn_mtxprotocol
   || ') c '
   || 'WHERE    a.nmtrsn = c.addr(+) union '
   || 'SELECT   a.mid, a.addr, a.nmtrsn, a.denter, a.nstate, a.dstate, '
   || '        DECODE(nstate, 0, "Неопределено", 1, "Новый", 2, "Присоеденен", 3, "Отсоеденен", 4, "Готов", "Другое") vstate, c.vname, c.cid '
   || 'FROM     mtxconf a, '
   || '         (SELECT util_pg.allnumber_f(addr) addr, vname, cid '
   || '          FROM   channels '
   || '          WHERE  protocol_id = '
   || comsrvdisp_pg.cn_mtxprotocol
   || ') c '
   || 'WHERE    c.addr = a.nmtrsn(+) '
   || ' ORDER BY ';

  IF ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 3,1 ';
  lv_sql := REPLACE(lv_sql, '"', '''');

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_mtxstatedet(an_mid NUMBER, an_cid NUMBER, an_sort NUMBER, an_filter NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
 BEGIN
  lv_sql :=
      'select * from (SELECT   p.mid, a.norder, a.vmac, a.ntype, '
   || '         DECODE(a.ntype, 1, "1-о фазный счётчик", 2, "3-х фазный счётчик", 3, "3-х фазный счётчик(Т)", 4, "Pulse", 5, "Water", "неизвестный") vtype, '
   || '         a.dproduction, a.nmtrsn, a.vid, p.dcurrpower, p.vname,p.nerror,p.verror '
   || ' FROM     mtxconfdet a, '
   || '         (SELECT DISTINCT f.mid, decode(cp.nuserescanal,1,f.rescanal,f.canal) canal, l.PROFILE dcurrpower, util_pg.get_pointname(f.mid, 1, 1) vname,l.state_cod nerror,l.state_descr verror '
   || '          FROM            mtxconf m, channels c, chanpoint cp, feeders f, last_save l '
   || '          WHERE           m.mid = '
   || an_mid
   || ' AND m.nmtrsn = util_pg.allnumber_f(c.addr) AND c.cid = cp.cid(+) '
   || '                          AND cp.mid = f.mid(+) AND cp.mid = l.mid(+) and c.cid='
   || an_cid
   || ') p '
   || ' WHERE    a.mid = '
   || an_mid
   || ' AND a.nmtrsn = p.canal(+) UNION '
   || '  SELECT f.mid, decode(1,2,1) norder, "" vmac, 0 ntype, "неизвестный" vtype, decode(1,2,sysdate) dproduction, decode(1,2,1) nmtrsn, "" vid, l.PROFILE dcurrpower, '
   || ' util_pg.get_pointname(f.mid, 1, 1) vname,l.state_cod nerror,l.state_descr verror '
   || ' FROM channels c, chanpoint cp, feeders f, last_save l where '
   || ' c.cid = cp.cid(+) AND cp.mid = f.mid(+) AND cp.mid = l.mid(+) and c.cid='
   || an_cid
   || ' and decode(cp.nuserescanal,1,f.rescanal,f.canal) not in (select nmtrsn from mtxconfdet where mid = '
   || an_mid
   || ' )) t where 1=1 ';

  IF BITAND(1, an_filter) = 0 THEN
   lv_sql := lv_sql || 'AND NOT (t.nerror <> 0)';
  END IF;

  IF BITAND(2, an_filter) = 0 THEN
   lv_sql := lv_sql || 'AND NOT (t.nerror IS NULL)';
  END IF;

  IF BITAND(4, an_filter) = 0 THEN
   lv_sql := lv_sql || 'AND NOT (t.nerror = 0)';
  END IF;

  lv_sql := lv_sql || ' ORDER BY ';

  IF ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 2';
  lv_sql := REPLACE(lv_sql, '"', '''');

  OPEN acur_t FOR lv_sql;
 END;

