 PROCEDURE del_mtxconfdet(an_mid NUMBER, an_order NUMBER) IS
 BEGIN
  IF an_order IS NULL THEN
   del_mtxconf(an_mid);
  ELSE
   DELETE FROM mtxconfdet
   WHERE       mid = an_mid AND norder = an_order;
  END IF;
 END;

