 --Чтение конфигурации мастер счетчика (получение списка счетчиков, опрашиваемых основным счетчиком)
 FUNCTION get_master_conf(
 an_cid NUMBER,                                                                                                                                      --Ид канала
               an_mid NUMBER,                                                                                                        --Ид точки (мастер счетчик)
                             at_mid OUT common_pg.tt_number,                                                                                    --Ид точек учета
                                                            at_mac OUT common_pg.tt_varchar2                                            --Список связных номеров
 )
  RETURN NUMBER IS
 BEGIN
  SELECT   f.mid, f.vinfo canal
  BULK COLLECT INTO at_mid, at_mac
  FROM     feeders f
  WHERE    f.nusd = an_mid
--  AND f.canal>0
           AND TRIM(f.vinfo) IS NOT NULL
  ORDER BY 1;

  RETURN at_mid.COUNT;
 END;

