-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_halfhour_child(an_mid NUMBER, an_erm NUMBER, av_mtrsn VARCHAR2, ad_date DATE) IS
  ln_const            NUMBER := 1;
  lb_found            BOOLEAN;
  ln_kc               NUMBER;
  ln_er               NUMBER;
  ln_erm              NUMBER;
  ld_winter           DATE DEFAULT util_pg.to_localtime(util_pg.convertmeterdate_e_f(an_mid, ad_date), 1);
  ln_source           NUMBER DEFAULT comsrv_pg.cn_auto;

  CURSOR lcur_sel IS
   SELECT 0 ts, NVL(q1m, 0) em
   FROM   halfhourtmp
   WHERE  mid = an_mid AND date_time = (SELECT MAX(date_time) dt
                                        FROM   halfhourtmp
                                        WHERE  mid = an_mid AND date_time < ad_date)
          AND LPAD(UPPER(TRIM(er_mtrsn)), 20, '0') = LPAD(UPPER(TRIM(av_mtrsn)), 20, '0')
   UNION ALL
   SELECT util_pg.is_timeswitch(date_time) ts, NVL(q1m, 0) q1m
   FROM   halfhour
   WHERE  mid = an_mid AND date_time = (SELECT MAX(date_time) dt
                                        FROM   halfhourold
                                        WHERE  mid = an_mid AND date_time < ld_winter)
          AND LPAD(UPPER(TRIM(er_mtrsn)), 20, '0') = LPAD(UPPER(TRIM(av_mtrsn)), 20, '0');

  CURSOR lcur_sel1 IS
   SELECT 0 ts, NVL(q1m, 0) em
   FROM   halfhour
   WHERE  mid = an_mid
          AND util_pg.to_unlocaltime(date_time, nsource) =
              (SELECT MAX(util_pg.to_unlocaltime(date_time, nsource)) dt
               FROM   halfhourold
               WHERE  mid = an_mid AND date_time < ld_winter + 3 / 24 AND date_time >= ld_winter - 3 / 24
                      AND util_pg.to_unlocaltime(date_time, nsource) < ad_date)
          AND LPAD(UPPER(TRIM(er_mtrsn)), 20, '0') = LPAD(UPPER(TRIM(av_mtrsn)), 20, '0') AND date_time < ld_winter AND date_time >= ld_winter - 2 / 24;

  lc                  lcur_sel%ROWTYPE;
 BEGIN
  /* Показания свистка в halfhourold.q1m
     Показания счетчика в halfhourold.erm
     Расход в halfhourold.er
     Показания счетчика на ноль свистка находятся в man_inp_hhour.erm */
  SAVEPOINT set_halfhour_sp;
--Ищем кол импульсов на кВтч
  ln_const := editfeeders_pg.get_mconst(an_mid);

--Ищем предыдущие показания
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  lc;

  lb_found := lcur_sel%FOUND;

  CLOSE lcur_sel;

  IF lb_found AND lc.ts = -1 THEN
   OPEN lcur_sel1;

   FETCH lcur_sel1
   INTO  lc;

   lb_found := lcur_sel1%FOUND;

   CLOSE lcur_sel1;
  END IF;

  IF lb_found THEN                                                                                                --По предыдущим показаниям свистка ищем расход
   SELECT NVL(MAX(kc), 1)
   INTO   ln_kc
   FROM   feeders
   WHERE  mid = an_mid;

   ln_er := ROUND(util_pg.indicoverturn(an_erm - lc.em, NULL) * ln_kc / ln_const, cn_rnd);
  END IF;

  --Находим текущие показания счетчика
  ln_erm := ROUND(an_erm / ln_const, cn_rnd) + get_shift_erm(an_mid);
  --Сохраняем результат
  das_pg.ins_halfhourtmp(an_mid, ad_date, comsrv_pg.cn_auto, ln_er, NULL, NULL, NULL, NULL, NULL, ln_erm, NULL, an_erm, NULL, NULL, NULL, 0,
   comsrv_pg.cn_induc_mtx, NULL, av_mtrsn);
  comsrvcim_pg.upd_lastsavehalfhour(an_mid, TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi'));

  IF ld_winter = TRUNC(ld_winter) THEN
   --А теперь суточные                                                                                                       --Граница суток
   comsrv_pg.set_bill_meter(an_mid, ln_erm, NULL, an_erm, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
    NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, av_mtrsn, 0, ld_winter, comsrv_pg.cn_induc_mtx);
   comsrvcim_pg.upd_lastsavebill(an_mid, TO_CHAR(ld_winter, 'dd.mm.yyyy hh24:mi'));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_halfhour_sp;
   raise_application_error(-20001, 'COMSRVMTX_PG.set_halfhour_child: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
--возвращает 1 если точка является счетчиком, подключенным импульсных выходом к свистку mtx
 FUNCTION is_mtx_child(an_mid NUMBER, an_usd NUMBER DEFAULT 0)
  RETURN NUMBER IS
  ln_usd              NUMBER := an_usd;
  ln_tmp              NUMBER;
 BEGIN
  IF ln_usd = 0 THEN
   SELECT MAX(nusd)
   INTO   ln_usd
   FROM   feeders
   WHERE  mid = an_mid;
  END IF;

  IF ln_usd IS NULL THEN
   RETURN 0;
  END IF;

  SELECT COUNT(*)
  INTO   ln_tmp
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   chanpoint
                WHERE  mid = ln_usd AND cid IN(SELECT cid
                                               FROM   channels
                                               WHERE  protocol_id = 120));

  RETURN ln_tmp;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает сдвих стартовых показаний счетчика при нуле свистка (сколько было на счетчике, когда на свистке был ноль)
 FUNCTION get_shift_erm(an_mid NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT NVL(MAX(erm), 0)
  INTO   ln_ret
  FROM   man_inp_hhour
  WHERE  mid = an_mid;

  RETURN ln_ret;
 END;

-----------------------------------------------------------------------------------------------------------------------
-- Обмен с БД МТХ по HTTP
-----------------------------------------------------------------------------------------------------------------------
 FUNCTION connectnextmeter_matrix(
 an_mid NUMBER, an_cid NUMBER, an_retmid OUT NUMBER, ln_canal OUT NUMBER, lv_name OUT VARCHAR2, ln_kc OUT NUMBER, ln_tag OUT NUMBER, ln_cmdoff OUT NUMBER
 )
  RETURN NUMBER IS
  ln_ret              NUMBER := 0;
 BEGIN
  FOR lc IN (SELECT f.mid, NVL(DECODE(c.nuserescanal, 1, f.rescanal, f.canal), 0) canal, SUBSTR(NVL(p.NAME, 'Без имени'), 1, 31) vname, NVL(f.kc, 1) kc,
                    NVL(p.tag, 0) tag, DECODE(NVL(SIGN(l.dexecmdoff - l.dcmdoff), 0), 1, 0, l.ncmdoff) ncmdoff
             FROM   points p, feeders f, chanpoint c, last_save l, curr_power cp
             WHERE  f.mid = (SELECT MIN(pp.mid)
                             FROM   points pp
                             WHERE  pp.mid > an_mid AND pp.mid IN(SELECT mid
                                                                  FROM   chanpoint
                                                                  WHERE  cid = an_cid AND nskip IS NULL) AND pp.ind = 3) AND f.mid = p.mid(+) AND f.mid = c.mid(+)
                    AND c.cid = an_cid AND f.mid = l.mid(+) AND f.mid = cp.mid(+)) LOOP
   an_retmid := lc.mid;
   ln_canal := lc.canal;
   lv_name := lc.vname;
   ln_kc := lc.kc;
   ln_tag := lc.tag;
   ln_cmdoff := NVL(lc.ncmdoff, 0);
   ln_ret := 1;
   EXIT;
  END LOOP;

  IF ln_ret > 0 AND an_retmid > 0 THEN
   editfeeders_pg.ins_last_save(an_retmid);
   COMMIT;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------

 --Вставка графика нагрузки
 PROCEDURE set_halfhour_matrix(an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, ad_date DATE) IS
 BEGIN
  SAVEPOINT set_halfhour_sp;
  comsrv_pg.set_halfhour_meter(an_mid, an_er, NVL(an_ed, 0), an_q1, an_q3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, comsrv_pg.cn_matrix, NULL,
   ad_date);
  comsrvcim_pg.upd_lastsavehalfhour(an_mid, TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_halfhour_sp;
   raise_application_error(-20001, 'COMSRVMTX_PG.set_halfhour_matrix: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
    --Вставка суточных расходов
 PROCEDURE set_bill_matrix(
 an_mid NUMBER, an_er NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_aer NUMBER, an_aq1 NUMBER, an_aq3 NUMBER, an_ber NUMBER, an_bq1 NUMBER, an_bq3 NUMBER,
 an_cer NUMBER, an_cq1 NUMBER, an_cq3 NUMBER, an_der NUMBER, an_dq1 NUMBER, an_dq3 NUMBER, av_mtrsn VARCHAR2, ad_date DATE
 ) IS
 BEGIN
  SAVEPOINT set_bill_sp;
  comsrv_pg.set_bill_meter(an_mid, an_er, NULL, an_q1, an_q3, NULL, NULL, an_aer, NULL, an_aq1, an_aq3, NULL, NULL, an_ber, NULL, an_bq1, an_bq3, NULL, NULL,
   an_cer, NULL, an_cq1, an_cq3, NULL, NULL, an_der, NULL, an_dq1, an_dq3, NULL, NULL, av_mtrsn, NULL, ad_date);
  comsrvcim_pg.upd_lastsavebill(an_mid, TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_halfhour_sp;
   raise_application_error(-20001, 'COMSRVMTX_PG.set_bill_matrix: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Вставка месячных расходов
 PROCEDURE set_months_matrix(
 an_mid NUMBER, an_er NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_aer NUMBER, an_aq1 NUMBER, an_aq3 NUMBER, an_ber NUMBER, an_bq1 NUMBER, an_bq3 NUMBER,
 an_cer NUMBER, an_cq1 NUMBER, an_cq3 NUMBER, an_der NUMBER, an_dq1 NUMBER, an_dq3 NUMBER, av_mtrsn VARCHAR2, ad_date DATE
 ) IS
 BEGIN
  SAVEPOINT set_months_sp;
  comsrv_pg.set_months_meter(an_mid, an_er, NULL, an_q1, an_q3, NULL, NULL, an_aer, NULL, an_aq1, an_aq3, NULL, NULL, an_ber, NULL, an_bq1, an_bq3, NULL, NULL,
   an_cer, NULL, an_cq1, an_cq3, NULL, NULL, an_der, NULL, an_dq1, an_dq3, NULL, NULL, av_mtrsn, NULL, ad_date);
  comsrvcim_pg.upd_lastsavemonths(an_mid, TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_months_sp;
   raise_application_error(-20001, 'COMSRVMTX_PG.set_months_matrix: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
--Результат выполнения команды на отключение (включение) an_cmd - клманда an_ret = 0 принята, иначе код ошибки
 PROCEDURE set_cmd_result(an_mid NUMBER, an_cmd NUMBER, an_ret NUMBER) IS
  cn_state_cod_ok CONSTANT NUMBER := 0;
  cn_state_cod_err CONSTANT NUMBER := 1;
  lv_message          VARCHAR2(256);
 BEGIN
  SAVEPOINT set_cmd_result_sp;

--Мы фиксируем номер запроса к устройству по точке для проверки при получении ответа и на канале для хранения сквозной икрементации номера пакета (0..127)  (an_packid+1 - мы храним следующий)
  IF an_ret = 0 THEN
   UPDATE last_save
   SET trial = SYSDATE,
       state_descr = 'Штатный режим',
       state_date = DECODE(state_cod - cn_state_cod_ok, 0, NVL(state_date, SYSDATE), SYSDATE),
       state_cod = cn_state_cod_ok,
       dexecmdoff = DECODE(SIGN(an_cmd), 1, SYSDATE, dexecmdoff)
   WHERE  mid = an_mid;
  ELSE
   UPDATE last_save
   SET trial = SYSDATE,
       state_descr = 'Команда ' || an_cmd || ' ' || ' не выполнена. Код ошибки MATRIX ' || an_ret,
       state_date = DECODE(state_cod - cn_state_cod_err, 0, NVL(state_date, SYSDATE), SYSDATE),
       state_cod = cn_state_cod_err
   WHERE  mid = an_mid;
  END IF;

  IF an_cmd > 0 AND an_ret = 0 THEN                                                                                    --Посылали сигнал на отключение/включение
   IF an_ret = 1 THEN                                                                                                                    --Сигнал на отключение
    lv_message := 'Отправлена команда на отключение нагрузки';
   ELSE
    lv_message := 'Отправлена команда на включение нагрузки';
   END IF;

   admin_pg.journal_p(an_mid, cn_state_cod_ok, lv_message);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_cmd_result_sp;
   raise_application_error(-20001, 'COMSRVMTX_PG.set_cmd_result: ' || SQLERRM(SQLCODE));
 END;
-----------------------------------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.COMSRVMTX_PG

