CREATE OR REPLACE 
PACKAGE BODY comsrvrdf_pg IS
------------------------------------------------------------------------------------------------------------------------
    -- Интерфейс взаимодействия (закачка файлов) БД с Носиком А.В.
    -- дата создания 08/06/2004 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
--******************************           Interface           *******************************************************--
------------------------------------------------------------------------------------------------------------------------
 -- получение кода импорта по миду точки на канале
 FUNCTION get_impcodebymid (an_mid NUMBER, an_cid NUMBER) 
  RETURN VARCHAR2 IS
  lv_impcode VARCHAR2(1000);
  ln_cnt     NUMBER;
 BEGIN
   SELECT max(f.vimportcode), count(*)
     INTO lv_impcode, ln_cnt
     FROM chanpoint cp, feeders f
    WHERE cp.mid = f.mid AND cid = an_cid AND cp.mid = an_mid;
   IF ln_cnt <> 1 THEN
     lv_impcode := NULL;
   END IF; 
   RETURN lv_impcode;
 END; 
------------------------------------------------------------------------------------------------------------------------
 -- получение мида по коду импорта точки на канале
 FUNCTION get_midbycode (av_impcode VARCHAR2, an_cid NUMBER) 
  RETURN NUMBER IS
  ln_mid     NUMBER;
  ln_cnt     NUMBER;
 BEGIN
   SELECT max(f.mid), count(*)
     INTO ln_mid, ln_cnt
     FROM chanpoint cp, feeders f
    WHERE cp.mid = f.mid AND cid = an_cid AND upper(trim(f.vimportcode)) = upper(trim(av_impcode));
   IF ln_cnt <> 1 THEN
     ln_mid := NULL;
   END IF; 
   RETURN ln_mid;
 END;
 
------------------------------------------------------------------------------------------------------------------------
 -- получение мида по rdf коду точки (по rdfcode ищем mrid в документе, если не находим, то ищем точку по совпадению rdfcode с кодом импорта) 
 -- added by KAG 02.02.2011
 FUNCTION get_midbyrdfcode (av_rdfcode VARCHAR2, at_mrids common_pg.tt_varchar2, at_rdfcodes common_pg.tt_varchar2, an_rdfcnt NUMBER, an_cid NUMBER, an_meas OUT NUMBER) 
  RETURN NUMBER IS
  ln_mid     NUMBER;
  ln_meas    NUMBER;
  ln_cnt     NUMBER;
  ln_ind     NUMBER := 0;
  lv_mrid    VARCHAR2(100);
  lv_ncode   VARCHAR2(50);
  lv_meas    VARCHAR2(50);
 BEGIN
   -- поиск нужного rdfcode
   ln_cnt := 0;
   FOR i IN 1 .. an_rdfcnt LOOP 
     IF av_rdfcode = replace(at_rdfcodes(i),'Analog_') THEN -- (rdfcode = 1032000003.A-THE или AP_d882782)
       ln_ind := i;
       ln_cnt := ln_cnt + 1;
     END IF;
   END LOOP;
   
   IF ln_cnt > 1 THEN 
     raise_application_error(-20001,'В xml-макете указано больше одной точки с одним и тем же mrid для '||av_rdfcode);
   ELSIF ln_cnt = 1 AND at_mrids(ln_ind) IS NOT NULL THEN -- если нашли в макете соответствие rdfcode и mrid 
     lv_mrid := at_mrids(ln_ind);
     ln_cnt := NULL;
     SELECT max(m.mid), max(m.NMEASURE), count(*)
       INTO ln_mid, ln_meas, ln_cnt
       FROM chanpoint cp, mrids m
      WHERE cp.mid = m.mid AND cid = an_cid AND m.mrid = lv_mrid;
   ELSE -- если соответствия rdfcode и mrid не находим, то ищем mid по vimportcode
     ln_cnt := NULL;
     IF INSTR(av_rdfcode,'.') <> 0 THEN -- для значений вида 1032000003.A-THE
             lv_meas := SUBSTR(util_pg.get_param(av_rdfcode,2,'.'),1,2);             
             IF lv_meas = 'A+' THEN
              ln_meas := 1;
             ELSIF lv_meas = 'A-' THEN
              ln_meas := 2;
             ELSIF lv_meas = 'R+' THEN
              ln_meas := 3;
             ELSIF lv_meas = 'R-' THEN
              ln_meas := 4;
             END IF;             
             lv_ncode := util_pg.get_param(av_rdfcode,1,'.');
      ELSE  -- для значений вида AP_d57312             
             lv_meas := SUBSTR (av_rdfcode, 1, 2);    
             IF lv_meas = 'AP' THEN
              ln_meas := 1;
             ELSIF lv_meas = 'AM' THEN
              ln_meas := 2;
             ELSIF lv_meas = 'RP' THEN
              ln_meas := 3;
             ELSIF lv_meas = 'RM' THEN
              ln_meas := 4;
             END IF;    
             lv_ncode := SUBSTR (av_rdfcode, 5);
     END IF;
     SELECT max(f.mid), count(*)
       INTO ln_mid, ln_cnt    
       FROM chanpoint cp, feeders f
      WHERE cp.mid = f.mid AND cid = an_cid AND trim(f.vimportcode) = lv_ncode;

   END IF;  

   IF ln_cnt <> 1 THEN
     ln_mid := NULL;
     an_meas := NULL;
   ELSE
     an_meas := ln_meas;
   END IF;
   RETURN ln_mid;
 END; 
------------------------------------------------------------------------------------------------------------------------
 -- получение даты с учетом метки часового пояса
 -- added by KAG 18.01.2011
 FUNCTION char_to_date (av_date VARCHAR2) 
  RETURN DATE IS
  ld_date   DATE;
  lv_date   VARCHAR2(100);
  ln_tzone  NUMBER;
  ln_pos    NUMBER;
 BEGIN
   ln_pos := instr(av_date,'+') + instr(av_date,'-');
   IF ln_pos <> 0 THEN
     ln_tzone := (2 - to_number(substr(av_date,ln_pos+1)))/24;
     lv_date := SUBSTR(av_date,1,ln_pos-1);          
   ELSE  
     ln_tzone := 0;
     lv_date := av_date;     
   END IF;
   ld_date := to_date(lv_date,'dd.mm.yyyy hh24:mi:ss') + ln_tzone;
   
   RETURN ld_date;
 EXCEPTION 
  WHEN others THEN
   raise_application_error(-20001, 'comsrvrdf_pg.char_to_date: ' || 'Ошибка преобразования даты! ' || SQLERRM(SQLCODE)); 
 END;    
