 -- Added by Semeniuk A.D. 26.05.2010
 PROCEDURE l_cimrdf (an_cid NUMBER, ac_file CLOB,ad_date IN OUT DATE) IS
  CURSOR lcur_cp IS
   SELECT cp.mid, f.vimportcode
     FROM chanpoint cp, feeders f
    WHERE cp.mid = f.mid AND cid = an_cid;

  lp_parser         xmlparser.parser;
  lx_doc            xmldom.domdocument;
  le_elem           xmldom.domelement;
  ln_node           xmldom.domnode;
  lv_nodename       VARCHAR2 (200);
  ln_subnode        xmldom.domnode;
  lv_subnodename    VARCHAR2 (200);
  ln_textnode       xmldom.domnode;
  lv_text           VARCHAR2 (200);
  lm_attrmap        xmldom.domnamednodemap;
  ln_attr           xmldom.domnode;
  lv_attrvalue      VARCHAR (100);
  ln_anind          NUMBER;   -- Итератор для элементов Analog
  ln_avind          NUMBER;   -- Итератор для элементов AnalogValue
  ln_qind           NUMBER;   -- Итератор для элементов MeasurementValueQuality
  lc_temp           CHAR (1);
  ln_temp1          NUMBER;
  ln_temp2          NUMBER;
  lv_tmp            varchar2(100);
  --lt_rdfcodes       common_pg.tt_number;   -- RDF-Идентификаторы измерений (в тегах cim:AnalogValue)
  lt_time           common_pg.tt_varchar2;   -- Временные метки
  --lt_type           common_pg.tt_number;   -- Типы (AP, AM, RP, RM)
  lt_vals           common_pg.tt_number;   -- Значения
  lt_qual           common_pg.tt_varchar2;   -- Метки качества (RDF-Идентификатор)
  lt_anal           common_pg.tt_varchar2;   -- Analog (RDF-Идентификатор)
  lt_qualityid      common_pg.tt_varchar2;   -- RDF-Идентификаторы меток качества
  lt_qualityvalue   common_pg.tt_varchar2;   -- Значения меток качества
  lt_analogid       common_pg.tt_varchar2;   -- RDF-Идентификаторы измерений (в тегах cim:Analog)
  lt_analogmrid     common_pg.tt_varchar2;   -- mRid измерений
  lt_final_mid      common_pg.tt_number;   -- Идентификаторы MID
  lt_final_time     common_pg.tt_varchar2;   -- Временные метки
  lt_final_vqm      common_pg.tt_varchar2;   -- Метки качества (RDF-Идентификатор)
  lt_final_er       common_pg.tt_number;   -- Значения ER
  lt_final_ed       common_pg.tt_number;   -- Значения ED
  lt_final_q1       common_pg.tt_number;   -- Значения Q1
  lt_final_q3       common_pg.tt_number;   -- Значения Q3
  
  lt_distinct_mids  common_pg.tt_number;   -- Список неповторяющихся идентификаторов MID
  lt_hhour_values   common_pg.tt_number;   -- Список значений по всем получасовкам для одного MID и одного measure
  ld_curr_date      DATE;                  -- Текущая дата 
  ld_time           DATE;
  ln_currmeas       NUMBER;                -- Текущее измерение
  ln_cnt            NUMBER;  
 BEGIN
  -- ------------ -------------- ------- ------------ - ---- --
  lp_parser := xmlparser.newparser;
  xmlparser.setvalidationmode (lp_parser, FALSE);
  xmlparser.parseclob (lp_parser, ac_file);
  lx_doc := xmlparser.getdocument (lp_parser);
  le_elem := xmldom.getdocumentelement (lx_doc);   -- получить корневой элемент
  ln_node := xmldom.makenode (le_elem);   -- получить узел, соответствующий корневому элементу
  ln_anind := 0;
  ln_avind := 0;
  ln_qind := 0;
  ln_node := xmldom.getfirstchild (ln_node);   -- получить первого потомка корневого узла

  WHILE NOT xmldom.isnull (ln_node) LOOP   -- для всех потомков узла
   IF (xmldom.getnodetype (ln_node) = xmldom.element_node) THEN   -- если узел является элементом
    lv_nodename := xmldom.getnodename (ln_node);   -- получить имя узла
    lm_attrmap := xmldom.getattributes (ln_node);   -- получить все атрибуты узла
    ln_attr := xmldom.item (lm_attrmap, 0);   -- получить первый атрибут
    lv_attrvalue := xmldom.getnodevalue (ln_attr);   -- получить значение атрибута

            -- перебор всех возможных имен узла
------------------------ DataSet -----------------------------
    IF lv_nodename = 'cim:DataSet' THEN
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла DataSet

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.hasattributes (ln_subnode) THEN   -- если имеются атрибуты
        lm_attrmap := xmldom.getattributes (ln_subnode);   -- получить все атрибуты узла
        ln_attr := xmldom.item (lm_attrmap, 0);   -- получить первый атрибут
        lv_attrvalue := xmldom.getnodevalue (ln_attr);   -- получить значение атрибута
       ELSIF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ Organization -----------------------------
    ELSIF lv_nodename = 'cim:Organization' THEN
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла Organization

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ Analog -----------------------------
    ELSIF lv_nodename = 'cim:Analog' THEN
     ln_anind := ln_anind + 1;   -- Увеличить значение текущего индекса (номера записи) на единицу
     lt_analogid (ln_anind) := lv_attrvalue;
     lt_analogmrid (ln_anind) := '';
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла Analog

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)

        IF (lv_subnodename = 'cim:IdentifiedObject.mRID') THEN
         lt_analogmrid (ln_anind) := NVL (lv_text, '');
        END IF;
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ AnalogValue -----------------------------
    ELSIF lv_nodename = 'cim:AnalogValue' THEN
     ln_avind := ln_avind + 1;   -- Увеличить значение текущего индекса (номера записи) на единицу
     --lt_rdfcodes (ln_avind) := -1;
     lt_time (ln_avind) := 0;
     --lt_type (ln_avind) := 0;
     lt_vals (ln_avind) := 0;
     lt_qual (ln_avind) := '';
     lt_anal (ln_avind) := '';
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла AnalogValue

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.hasattributes (ln_subnode) THEN   -- если имеются атрибуты
        lm_attrmap := xmldom.getattributes (ln_subnode);   -- получить все атрибуты узла
        ln_attr := xmldom.item (lm_attrmap, 0);   -- получить первый атрибут
        lv_attrvalue := xmldom.getnodevalue (ln_attr);   -- получить значение атрибута

        IF (lv_subnodename = 'cim:AnalogValue.MemberOf_Measurement') THEN
          lt_anal (ln_avind) := SUBSTR (lv_attrvalue, 2);  -- берем rdfcode из cim:AnalogValue
        ELSIF (lv_subnodename = 'cim:MeasurementValue.MeasurementValueQuality') THEN
         lt_qual (ln_avind) := SUBSTR (lv_attrvalue, 2);
        END IF;
       ELSIF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)

        IF (lv_subnodename = 'cim:MeasurementValue.timeStamp') THEN
         lt_time (ln_avind) := lv_text;
        ELSIF (lv_subnodename = 'cim:AnalogValue.value') THEN
         lt_vals (ln_avind) := TO_NUMBER (TRANSLATE (lv_text, ',', '.'));
        END IF;
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ MeasurementValueQuality -----------------------------
    ELSIF lv_nodename = 'cim:MeasurementValueQuality' THEN
     ln_qind := ln_qind + 1;   -- Увеличить значение текущего индекса (номера записи) на единицу
     lt_qualityid (ln_qind) := lv_attrvalue;
     lt_qualityvalue (ln_qind) := '00000000000000000000000';
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла AnalogValue

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)

        IF (lv_subnodename = 'cim:Quality61850.validity') THEN   -- 1
         SELECT DECODE (lv_text, 'good', '0', 'invalid', '1', 'reserved', '2', 'questionable', '3', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 0) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 2);
        ELSIF (lv_subnodename = 'cim:Quality61850.overFlow') THEN   -- 2
         SELECT DECODE (lv_text, 'false', '0', 'true', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 1) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 3);
        ELSIF (lv_subnodename = 'cim:Quality61850.outOfRange') THEN   -- 3
         SELECT DECODE (lv_text, 'false', '0', 'true', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 2) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 4);
        ELSIF (lv_subnodename = 'cim:Quality61850.badReference') THEN   -- 4
         SELECT DECODE (lv_text, 'false', '0', 'true', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 3) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 5);
        ELSIF (lv_subnodename = 'cim:Quality61850.oscillatory') THEN   -- 5
         SELECT DECODE (lv_text, 'false', '0', 'true', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 4) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 6);
        ELSIF (lv_subnodename = 'cim:Quality61850.failure') THEN   -- 6
         SELECT DECODE (lv_text, 'false', '0', 'true', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 5) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 7);
        ELSIF (lv_subnodename = 'cim:Quality61850.source') THEN   -- 10
         SELECT DECODE (lv_text, 'process', '0', 'substituted', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 9) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 11);
        ELSIF (lv_subnodename = 'cim:Quality61850.operatorBlocked') THEN   -- 12
         SELECT DECODE (lv_text, 'false', '0', 'true', '1', '0')
           INTO lc_temp
           FROM DUAL;

         lt_qualityvalue (ln_qind) := SUBSTR (lt_qualityvalue (ln_qind), 1, 11) || lc_temp || SUBSTR (lt_qualityvalue (ln_qind), 13);
        END IF;
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ MeasurementType -----------------------------
    ELSIF lv_nodename = 'cim:MeasurementType' THEN
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла MeasurementType

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ Unit -----------------------------
    ELSIF lv_nodename = 'cim:Unit' THEN
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла Unit

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
------------------------ MeasurementValueSource -----------------------------
    ELSIF lv_nodename = 'cim:MeasurementValueSource' THEN
     ln_subnode := xmldom.getfirstchild (ln_node);   -- получить первого потомка узла MeasurementValueSource

     WHILE NOT xmldom.isnull (ln_subnode) LOOP   -- для всех потомков узла
      IF (xmldom.getnodetype (ln_subnode) = xmldom.element_node) THEN   -- если узел является элементом
       lv_subnodename := xmldom.getnodename (ln_subnode);   -- получить имя узла

       IF xmldom.haschildnodes (ln_subnode) THEN   -- если имеются потомки (в том числе текст)
        ln_textnode := xmldom.getfirstchild (ln_subnode);   -- получить текстовый узел (первый потомок данного узла)
        lv_text := xmldom.getnodevalue (ln_textnode);   -- получить текст (значение текстового узла)
       END IF;
      END IF;

      ln_subnode := xmldom.getnextsibling (ln_subnode);   -- получить очередной узел из списка
     END LOOP;
    END IF;
   END IF;

   ln_node := xmldom.getnextsibling (ln_node);   -- получить очередной узел из списка
  END LOOP;

  -------- Добавление измерений в таблицу MRIDS по совпадению rdfcode в макете и vimportcode на точке --------
  -- это возможно не надо!
