 PROCEDURE set_curr_power(
 an_id NUMBER,                                                                                                                --Ид устройства (заводской номер)
              an_packid NUMBER,                                                                                                    --Номер запроса к устройству
                               an_erm NUMBER,                                                                                      --Активная суммарная энергия
                                             an_aerm NUMBER,                                                                      --Активная энергия в тарифе L
                                                            an_berm NUMBER,                                                       --Активная энергия в тарифе M
                                                                           an_cerm NUMBER,                                        --Активная энергия в тарифе H
                                                                                          an_derm NUMBER,                         --Активная энергия в тарифе P
                                                                                                         an_q1m NUMBER,                --реактивная энергия (C)
                                                                                                                       an_q2m NUMBER,  --реактивная энергия (L)
 an_er NUMBER,                                                                                                                      --Текущая активная мощность
              an_rr NUMBER,                                                                                                       --Текущая реактивная мощность
                           an_cos_fi NUMBER,                                                                                                            --COS F
                                            an_volt1 NUMBER,                                                                             --Текущее напряжение a
                                                            an_volt2 NUMBER,                                                             --Текущее напряжение b
                                                                            an_volt3 NUMBER,                                             --Текущее напряжение c
                                                                                            an_curr1 NUMBER,                                    --Текущий ток a
                                                                                                            an_curr2 NUMBER,                    --Текущий ток b
                                                                                                                            an_curr3 NUMBER,    --Текущий ток c
 an_state NUMBER,                                                                                                                             -- Флаг состояния
                 an_temp NUMBER,                                                                                                          --Текущая температура
                                ad_date DATE                                                                                                    --Текущее время
/*
--Осталось
0x21    Флаги состояния (события)
0x22    Флаги состояния (аварии)
0x0F    Время простоя
0x11    Длительность некачественного напряжения
0x12    Длительность диф. тока
0x1A    Активная максимальная средняя мощность
0x1B    Реактивная максимальная средняя мощность (C)
0x1C    Реактивная максимальная средняя мощность (L)
0x1D    Потребление активной энергии за интервал
0x17    Текущий тариф
0x18    Состояние фаз
0x14    Сальдо
0x1E    Активная энергия (канал 1)
0x1F    Активная энергия (канал 2)
0x20    Активная энергия (канал 3)
0x13    Кол-во импульсов до отключения
0x03    Карта простоя

--Флаги состояния
an_state
Флаги передеются словом 16бит  (0..15)
имеют значение следующие биты
bit3  - индикация включена (не знаю что делает)
bit11 - нагрузка отключена
bit13 - признак 3Ф счетчика
*/
 ) IS
  cn_bit11   CONSTANT NUMBER := 2048;                                                                                                             --power(2,11)
  ld_sys              DATE := SYSDATE;
  ln_state            NUMBER;
  ln_mid              NUMBER;
  ln_ok               NUMBER;
  ld_months           DATE;
  ld_bill             DATE;
 BEGIN
  SAVEPOINT set_curr_power_sp;

  FOR lc IN (SELECT DISTINCT f.mid, NVL(f.kc, 1) kc, DECODE(c.nuserescanal, 1, f.rescanal, f.canal) mtrsn
             FROM            feeders f, meters m, chanpoint c, curr_power cp
             WHERE           f.mid = c.mid AND c.cid IN(SELECT cid
                                                        FROM   channels
                                                        WHERE  protocol_id = 117) AND DECODE(c.nuserescanal, 1, f.rescanal, f.canal) = an_id AND f.mid = m.mid(+)
                             AND m.entype(+) = 7 AND f.mid = cp.mid(+)
             ORDER BY        1) LOOP
   ln_mid := lc.mid;

   SELECT NVL(MAX(DECODE(nrepeaticcp, an_packid, 1, 0)), 0), NVL(MAX(bill), ld_sys - 370), NVL(MAX(months), ld_sys - 370)
   INTO   ln_ok, ld_bill, ld_months
   FROM   last_save
   WHERE  mid = ln_mid;

--   IF ln_ok = 1 THEN //Мы не делаем проверки счетчика пакетов SMS на данном этапе

   --Суточные
   IF TRUNC(ad_date) > ld_bill AND(an_erm IS NOT NULL OR an_q1m IS NOT NULL OR an_q2m IS NOT NULL) THEN
    comsrv_pg.set_bill_meter(ln_mid, an_erm, NULL, an_q1m, NULL, an_q2m, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
     NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, lc.mtrsn, NULL, ad_date);
    ld_bill := TRUNC(ad_date);
    --А теперь пишем в halfhour
    comsrv_pg.set_halfhour_energy_simple(ln_mid, an_erm, NULL, an_q1m, NULL, an_q2m, NULL, lc.mtrsn, NULL, util_pg.to_unlocaltime(ad_date));
   END IF;

   --Месячные
   IF TRUNC(ad_date, 'MONTH') > ld_months AND(an_erm IS NOT NULL OR an_q1m IS NOT NULL OR an_q2m IS NOT NULL) THEN
    comsrv_pg.set_months_meter(ln_mid, an_erm, NULL, an_q1m, NULL, an_q2m, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
     NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, lc.mtrsn, NULL, ad_date);
    ld_months := TRUNC(ad_date, 'MONTH');
   END IF;

   --Текущие
   IF BITAND(an_state, cn_bit11) = cn_bit11 THEN
    ln_state := 1;
   ELSE
    ln_state := BITAND(an_state, cn_bit11);
   END IF;

   comsrv_pg.set_curr_power_meter(ln_mid, an_erm, NULL, an_q1m, NULL, an_q2m, NULL, NULL, an_cos_fi, an_volt1, an_volt2, an_volt3, an_curr1, an_curr2, an_curr3,
    NULL, NULL, NULL, NULL, NULL, NULL, an_er * lc.kc, NULL, an_rr * lc.kc, NULL, NULL, NULL, NULL, NULL, an_state, an_temp, ln_state, NULL, ad_date);

   UPDATE last_save
   SET PROFILE = ad_date,
       bill = ld_bill,
       months = ld_months,
       nrepeaticcp = -1
   WHERE  mid = ln_mid;
--   END IF;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_curr_power_sp;
   raise_application_error(-20001, 'COMSRVRTR_PG.set_curr_power: id=' || an_id || ' mid=' || ln_mid || ' ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись пакета
 PROCEDURE set_frame(
 an_id NUMBER,                                                                                                                 --Ид устройства (заводской номер)
              av_source VARCHAR2,                                                                                                                     --Источник
                                 an_packid NUMBER,                                                                                               --Номер запроса
                                                  an_framecnt NUMBER,                                             --Общще количество пакетов-ответа на an_packid
                                                                     an_framenum NUMBER,                                                   --Номер пакета-ответа
                                                                                        av_frame VARCHAR2                                        --Текст пакетов
 ) IS
  ld_sys              DATE := SYSDATE;
  ln_operation        NUMBER;
  ln_state            NUMBER;
  cn_shift   CONSTANT NUMBER := 2 / 24;
 BEGIN
  SAVEPOINT set_frame_sp;

--Ищем только те, кто не собран
  SELECT NVL(MAX(noperation), 0)
  INTO   ln_operation
  FROM   rtrsms
  WHERE  nid = an_id AND npackid = an_packid AND nframecnt = an_framecnt AND nstate = 0;

  IF ln_operation > 0 THEN
                   --Если между SMS более cn_shift то мы считаем что это пакеты от разных SMS (an_packid не бесконечный а до 127 и часто могут быть повторения)
   SELECT DECODE(SIGN((ld_sys - MIN(denter)) - cn_shift), 1, 0, ln_operation)
   INTO   ln_operation
   FROM   rtrsmsdet
   WHERE  noperation = ln_operation;
  END IF;

  IF ln_operation = 0 THEN
   SELECT sms_seq.NEXTVAL
   INTO   ln_operation
   FROM   DUAL;

   IF an_framecnt = 1 THEN                                                                         -- Если один пакет помещается в одну SMS то состояние готов.
    ln_state := 1;
   ELSE
    ln_state := 0;
   END IF;

   INSERT INTO rtrsms
               (noperation, nid, vsource, npackid, nframecnt, nstate)
   VALUES      (ln_operation, an_id, av_source, an_packid, an_framecnt, ln_state);
  END IF;

--А теперь записуем SMS
  BEGIN
   INSERT INTO rtrsmsdet
               (noperation, nframenum, denter, vframe)
   VALUES      (ln_operation, an_framenum, ld_sys, av_frame);
  EXCEPTION
   WHEN DUP_VAL_ON_INDEX THEN                                                                                    --Вторая SMS (такого не видел но всякое бывает)
    UPDATE rtrsmsdet
    SET vframe = av_frame,
        denter = ld_sys
    WHERE  noperation = ln_operation AND nframenum = an_framenum;
   WHEN OTHERS THEN
    RAISE;
  END;

--Обновляем состояние (только в случаее update rtrsms)
  IF ln_state IS NULL THEN
   UPDATE rtrsms
   SET nstate = 1
   WHERE  noperation = ln_operation AND nframecnt = (SELECT COUNT(*)
                                                     FROM   rtrsmsdet
                                                     WHERE  noperation = ln_operation);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_frame_sp;
   RAISE;
 END;

-----------------------------------------------------------------------------------------------------------------------
--Чтение пакетов возвращает ИД набора данных (набора пакетов)
 FUNCTION get_readypack(av_ret OUT common_pg.tt_varchar2                                                                                        --массив пакетов
                                                        )
  RETURN NUMBER IS
  ln_operation        NUMBER;
  i                   NUMBER := 0;
 BEGIN
  SELECT NVL(MIN(noperation), 0)
  INTO   ln_operation
  FROM   rtrsms
  WHERE  nstate = 1;

  IF ln_operation > 0 THEN
   FOR lc IN (SELECT   vframe
              FROM     rtrsmsdet
              WHERE    noperation = ln_operation
              ORDER BY nframenum) LOOP
    i := i + 1;
    av_ret(i) := lc.vframe;
   END LOOP;
  END IF;

  RETURN ln_operation;
 END;

-----------------------------------------------------------------------------------------------------------------------
--Запись состояния о разборе пакетов
 PROCEDURE set_statepack(an_operation NUMBER,                                                                  --Ид набора данных (то что вернула get_readypack)
                                             an_state NUMBER                                                                               --0-OK, >0 код ошибки
                                                            ) IS
 BEGIN
  IF an_state = 0 THEN
   DELETE FROM rtrsms
   WHERE       noperation = an_operation;
  ELSE
   UPDATE rtrsms
   SET nstate = 2
   WHERE  noperation = an_operation;
  END IF;

  COMMIT;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_state_point(an_cid NUMBER, an_mid NUMBER, an_packid NUMBER) IS
  ln_tmp              NUMBER;
  cn_state_cod        constant NUMBER:=1;
  lv_message          VARCHAR2(256);
 BEGIN
  SAVEPOINT set_state_point_sp;
  --Может первый раз тогда insert в last_save
  editfeeders_pg.ins_last_save(an_mid);

--Мы фиксируем номер запроса к устройству по точке для проверки при получении ответа и на канале для хранения сквозной икрементации номера пакета (0..127)  (an_packid+1 - мы храним следующий)
  SELECT MAX(ncmdoff)
  INTO   ln_tmp
  FROM   last_save
  WHERE  mid = an_mid AND SIGN(ncmdoff) = 1 AND NVL(dexecmdoff, dcmdoff) <= dcmdoff;

  UPDATE last_save
  SET trial = SYSDATE,
      nrepeaticcp = an_packid - 1,                                                                                                                --an_packid-0,
      dexecmdoff = DECODE(SIGN(ln_tmp), 1, SYSDATE, dexecmdoff),
      state_descr = 'Штатный режим',
      state_date = DECODE(NVL(state_cod, 0), 0, NVL(state_date, SYSDATE), SYSDATE)
  WHERE  mid = an_mid;

  UPDATE last_save
  SET nrepeaticcp = an_packid                                                                                                      --nrepeaticcp = an_packid + 1
  WHERE  mid = an_cid;

  IF ln_tmp > 0 THEN                                                                                                   --Посылали сигнал на отключение/включение
   IF ln_tmp = 1 THEN                                                                                                                    --Сигнал на отключение    
    lv_message := 'Отправлена команда на отключение нагрузки';
   ELSE
    lv_message := 'Отправлена команда на включение нагрузки';
   END IF;

   admin_pg.journal_p(an_mid, cn_state_cod, lv_message);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_state_point_sp;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Для отображения в задаче состояния опроса RTR NP устройств
 PROCEDURE get_rtrstate(an_sort NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
 BEGIN
  lv_sql :=
      'SELECT c.addr, c.vname, c.cid, p.implement_date, l.nrepeaticcp, p.mid '
   || 'FROM points p, last_save l, '
   || '(SELECT util_pg.allnumber_f(addr) addr, vname, cid '
   || '          FROM   channels '
   || '          WHERE  protocol_id = 117) c '
   || 'WHERE c.cid = p.mid(+) and c.cid = l.mid '
   || 'ORDER BY ';

  IF ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 3,1 ';
  lv_sql := REPLACE(lv_sql, '"', '''');

  OPEN acur_t FOR lv_sql;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Для отображения в задаче состояния опроса RTR NP устройств
 PROCEDURE get_rtrstatedet(an_cid NUMBER, an_sort NUMBER, an_filter NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
  cn_bit13   CONSTANT NUMBER := 8192;
 BEGIN
  lv_sql :=
      'SELECT f.mid, f.canal, DECODE(bitand(cp.NSTATUS,'
   || cn_bit13
   || '),'
   || cn_bit13
   || ', "3-х фазный счётчик", 0, "1-о фазный счётчик", "неизвестный") tag, l.PROFILE dcurrpower, util_pg.get_pointname(f.mid, 1, 1) vname,l.state_cod nerror,l.state_descr verror, '
   || ' SUBSTR(NVL(TRIM(f.vinfo), "'
   || comsrvcim_pg.cv_info_def
   || '"), 1, '
   || comsrvcim_pg.cn_info_len
   || ') vinfo ,nvl(rt.stall,0) stall,nvl(rt.stnorma,0) stnorma, nvl(rt.sterr,0) sterr,nvl(rt.stwait,0) stwait, '
   || ' decode(sign(l.nrepeaticcp)+1+nvl(rt.stall,0),0,0,decode(sign(rt.sterr),1,2,1)) cmstate, '
   || ' decode(sign(l.nrepeaticcp),-1, "норм.", "ожидание ответа") vstate,decode(cp.noff,1,''Откл'',0,''Вкл'') voff,cp.doff '
   || ' FROM (select c1.cid,cp1.mid,decode(cp1.nuserescanal,1,f1.rescanal,f1.canal) canal, f1.vinfo '
   || ' from channels c1, chanpoint cp1, feeders f1 where c1.cid='
   || NVL(an_cid, 0)
   || ' AND c1.cid = cp1.cid(+) AND cp1.mid = f1.mid(+)) f, last_save l,curr_power cp, points p, '
   || ' (select nid,count(*) stall,sum(decode(nstate,1,1,0)) stnorma,sum(decode(nstate,2,1,0)) sterr,sum(decode(nstate,0,1,0)) stwait from rtrsms  group by nid) rt'
   || '          WHERE f.mid = l.mid(+) AND f.mid = p.mid(+) AND f.canal=rt.nid(+) AND f.mid=cp.mid(+) ';

  IF BITAND(1, an_filter) = 0 THEN
   lv_sql := lv_sql || 'AND NOT (decode(sign(l.nrepeaticcp)+1+nvl(rt.stall,0),0,0,decode(sign(rt.sterr),1,2,1)) = 2)';
  END IF;

  IF BITAND(2, an_filter) = 0 THEN
   lv_sql := lv_sql || 'AND NOT (decode(sign(l.nrepeaticcp)+1+nvl(rt.stall,0),0,0,decode(sign(rt.sterr),1,2,1)) = 1)';
  END IF;

  IF BITAND(4, an_filter) = 0 THEN
   lv_sql := lv_sql || 'AND NOT (decode(sign(l.nrepeaticcp)+1+nvl(rt.stall,0),0,0,decode(sign(rt.sterr),1,2,1)) = 0)';
  END IF;

  lv_sql := lv_sql || 'ORDER BY ';

  IF ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1 ';
  lv_sql := REPLACE(lv_sql, '"', '''');

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_rtrdetcurpower(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT cp.mid, cp.date_time, cp.obsolete, cp.er, cp.q1, cp.ed, cp.q3, cp.freq, cp.cosf, cp.volt, cp.currento, cp.volt2, cp.volt3, cp.curr2, cp.curr3,
          cp.erm, cp.edm, cp.q1m, cp.q3m, cp.q2, cp.q4, cp.q2m, cp.q4m, cp.nfiu1, cp.nfiu2, cp.nfiu3, cp.nfii1, cp.nfii2, cp.nfii3, cp.ni0, cp.noff, cp.doff,
          cp.nstatus, cp.ntemp, ls.dcmdoff, ls.ncmdoff, ls.dexecmdoff,
          DECODE(
           cp.noff,
           1, 'Отключен ' || TO_CHAR(cp.doff, 'dd.mm.yyyy hh24:mi:ss'),
           2, 'Включен ' || TO_CHAR(cp.doff, 'dd.mm.yyyy hh24:mi:ss'),
           'Неизвестно'
          ) voff,
          DECODE(
           ls.dcmdoff,
           NULL, '',
           'Команда ' || DECODE(ls.ncmdoff, 1, 'на ОТКЛЮЧЕНИЕ', 2, 'на ВКЛЮЧЕНИЕ', 'ОТМЕНА') || ' выдана ' || TO_CHAR(ls.dcmdoff, 'dd.mm.yyyy hh24:mi:ss')
          ) vcmdoff,
          DECODE(
           ls.dcmdoff,
           NULL, '',
           DECODE(
            ls.ncmdoff,
            0, '',
            DECODE(ls.dexecmdoff, NULL, 'Команда ожидает передачи роутеру.', 'Команда передана роутеру ' || TO_CHAR(ls.dexecmdoff, 'dd.mm.yyyy hh24:mi:ss'))
           )
          ) vexecmdoff
   FROM   curr_power cp, last_save ls
   WHERE  cp.mid = an_mid AND cp.mid = ls.mid(+);
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE reset_packetid(an_cid NUMBER) IS
 BEGIN
  UPDATE last_save
  SET nrepeaticcp = 0
  WHERE  mid = an_cid;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_nikstate(an_cid NUMBER, an_sort NUMBER, an_filter NUMBER, acur_t OUT common_pg.tcur) IS
  ln_cid              NUMBER := NVL(an_cid, 0);
  lv_sql              VARCHAR2(4000);
  lv_filter           VARCHAR2(4000);

  FUNCTION bitexists(x NUMBER, bit NUMBER)                                                         --BITEXISTS проверяет наличае бита bit (с нуля) в значении x
   RETURN BOOLEAN IS
  BEGIN
   IF BITAND(x, POWER(2, bit)) = POWER(2, bit) THEN
    RETURN TRUE;
   END IF;

   RETURN FALSE;
  END;
 BEGIN
  IF bitexists(an_filter, 0) THEN                                                                                             --Не описано в конфигурации АСКУЭ
   lv_filter := lv_filter || ' AND tt.mid is null ';
  END IF;

  IF bitexists(an_filter, 1) THEN                                                                                       --Не описано в конфигурации Концентратор
   lv_filter := lv_filter || ' AND tt.nserial is null ';
  END IF;

  IF bitexists(an_filter, 2) THEN                                                                                        --Состояние опроса концентратором Опрос
   lv_filter := lv_filter || ' AND tt.nstate=0 ';
  END IF;

  IF bitexists(an_filter, 3) THEN                                                                                       --Состояние опроса концентратором Ошибка
   lv_filter := lv_filter || ' AND tt.nstate<>0 ';
  END IF;

  IF bitexists(an_filter, 4) THEN                                                                                               --Состояние реле питания Включен
   lv_filter := lv_filter || ' AND tt.noff=0 ';
  END IF;

  IF bitexists(an_filter, 5) THEN                                                                                              --Состояние реле питания Отключен
   lv_filter := lv_filter || ' AND tt.noff=1 ';
  END IF;

  IF bitexists(an_filter, 6) THEN                                                                                                 --Состояние опроса АСКУЭ Опрос
   lv_filter := lv_filter || ' AND tt.state_cod=0 ';
  END IF;

  IF bitexists(an_filter, 7) THEN                                                                                                --Состояние опроса АСКУЭ Ошибка
   lv_filter := lv_filter || ' AND tt.state_cod<>0 ';
  END IF;

  IF lv_filter IS NOT NULL THEN
   lv_filter := ' WHERE 1=1 ' || lv_filter;
  END IF;

  lv_sql :=
      'select * from (select cp.mid,pa.name paname,p.name,f.canal,COMSRVRTR_PG.get_lastmetdate(cp.mid) BILL,ls.state_cod,n.nserial,n.denergy,n.nstate,n.noff,n.nmodel,n.naddrh,n.naddrl,n.cid,n.NID,ls.STATE_DESCR
from chanpoint cp,feeders f,points p,points pa,NIKRTCONF n, last_save ls  
where cp.cid='
   || ln_cid
   || ' and cp.mid=f.mid(+) and cp.mid=ls.mid(+) and cp.mid=p.mid(+) and p.parent=pa.mid(+) and '
   || ln_cid
   || '=n.cid(+) and f.canal=n.nserial(+) '
   || 'union all
select decode(1,2,1) mid, decode(1,2,'''') paname,decode(1,2,'''') name,decode(1,2,1) canal,decode(1,2,SYSDATE) BILL,decode(1,2,1) state_cod, n.nserial,n.denergy,n.nstate,n.noff,n.nmodel,n.naddrh,n.naddrl,n.cid,n.NID,decode(1,2,'''') STATE_DESCR
from NIKRTCONF n 
where n.cid='
   || ln_cid
   || ' and n.nserial not in (select f.canal from chanpoint cp,feeders f where  cp.cid='
   || ln_cid
   || ' and cp.mid=f.mid) ) tt '
   || lv_filter;
  lv_sql := lv_sql || ' ORDER BY ';

  IF ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 2,3,4,7,1,15 ';

  OPEN acur_t FOR lv_sql;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Дата последних показаний по счетчику в АСКУЭ
 FUNCTION get_lastmetdate(an_mid NUMBER)
  RETURN DATE IS
  ld_ret              DATE;
 BEGIN
  SELECT MAX(date_time)
  INTO   ld_ret
  FROM   billorg
  WHERE  mid = an_mid;

  RETURN ld_ret;
 END;
-----------------------------------------------------------------------------------------------------------------------
END;
/


