 --Записывает статистику данные ГН по точке
 PROCEDURE set_stat(an_group NUMBER,                                                                                              --Ид точки maketgroups.ngroup
                                    ad_date DATE                                                              --Дата, за которую необходимо получить информацию
                                                );

--Запись массива УППД в uppddata
 PROCEDURE insert_uppddata(an_maket NUMBER, ad_date DATE);

 --Возвращает ид макета по каналу
 FUNCTION get_maketid(an_channel NUMBER)                                                                                                     --Ид канала опроса
  RETURN NUMBER;

-----------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------
  --Возвращает ид макета по каналу
 FUNCTION get_maketid(an_channel NUMBER)                                                                                                     --Ид канала опроса
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(init_str), 5))), 0)
  INTO   ln_ret
  FROM   channels
  WHERE  cid = an_channel;

  RETURN ln_ret;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Возвращает следующую точку по каналу с ид.>an_mid (maket)
 FUNCTION get_next_point(
 an_channel NUMBER,                                                                                                                           --Ид канала опроса
                   an_group NUMBER,                                                                                                --Ид точки maketgroups.ngroup
                                   av_code OUT VARCHAR2,                                              --Код точки maketgroups.vcode (Код канала в терминах УППД)
 av_name OUT VARCHAR2                                                                                   --Наименование точки maketgroups.vname (Для отображения)
 )
  RETURN NUMBER IS
  ln_maket            NUMBER;
  ln_id               NUMBER;
 BEGIN
  gn_channel := an_channel;
  ln_maket := get_maketid(an_channel);

  --Найдем все остальное
  SELECT MAX(ngroup), MAX(vcode), MAX(vname)
  INTO   ln_id, av_code, av_name
  FROM   maketgroups
  WHERE  nmaket = ln_maket AND ngroup = (SELECT MIN(ngroup)
                                         FROM   maketgroups
                                         WHERE  ngroup > an_group AND nmaket = ln_maket);

  RETURN NVL(ln_id, 0);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrvuppd_pg.get_next_point: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Возвращает данные ГН по точке
 PROCEDURE get_datalp(
 an_group NUMBER,                                                                                                                  --Ид точки maketgroups.ngroup
                 ad_date DATE,                                                                                 --Дата, за которую необходимо получить информацию
                              at_data OUT common_pg.tt_number,                                                          --Массив данных (23, 24 или 25 значений)
                                                              an_maket NUMBER
 ) IS
  ln_maket            NUMBER;
  ln_sign             NUMBER;
  ln_groupcode        NUMBER;
  ln_subgroupcode     NUMBER;
  ln_temp             NUMBER;
  ln_count            NUMBER;                                                                                                          -- кол-во часов в сутках
  ln_hc               NUMBER;                                                                                                     -- реал кол-во часов в сутках
  ln_null             NUMBER DEFAULT 1;
  ln_needround30817   NUMBER;
  nb_subgroups        NUMBER DEFAULT 0;                                                                                              -- added by EVK 02.04.2009
  lb_25               BOOLEAN;
  ln_needtrunc        NUMBER;                                                                                                      -- делать TRUNC вместо ROUND
  lv_bstr             VARCHAR2(2000);
 BEGIN
  SAVEPOINT get_datalp_sp;
  ln_count := 24 - util_pg.is_dayswitch(ad_date);
  ln_hc := ln_count;

  IF ln_count = 23 THEN
   ln_count := 24;
  END IF;                                                                                                                             -- added by EVK 30.03.2009

  lb_25 :=(util_pg.getparamvalue_f(44) = 1);

  FOR i IN 1 .. ln_count LOOP
   at_data(i) := NULL;
  END LOOP;

  -- Чистим временные таблицы
  DELETE FROM m30817;

  --Найдем ид макета
  IF an_maket > 0 THEN
   ln_maket := an_maket;
  ELSE
   SELECT COUNT(*)
   INTO   nb_subgroups
   FROM   maketformulas
   WHERE  ngroup = an_group;

   SELECT MAX(nmaket)
   INTO   ln_maket
   FROM   maketgroups
   WHERE  ngroup = an_group;
  END IF;

  IF NVL(ln_maket, 0) = 0 THEN
   RETURN;
  END IF;

  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = ln_maket;

  IF util_pg.get_param(lv_bstr, 9) = '1' THEN
   ln_needtrunc := 1;
  ELSE
   ln_needtrunc := 0;
  END IF;

  IF NVL(an_group, 0) = 0 OR nb_subgroups > 0 THEN
   -- если это итоговая группа - делаем как раньше, added by EVK 02.04.2009
   DELETE FROM makettemp;

   -- Выборка в рабочую таблицу формул расчета агрегированных макетных строк
   INSERT INTO makettemp
               (ngroup, nsubgroup, nsign)
    SELECT ngroup, nsubgroup, nsign
    FROM   maketformulas
    WHERE  ngroup IN(SELECT ngroup
                     FROM   maketgroups
                     WHERE  nmaket = ln_maket);

   -- В рабочей таблице проставляются ид всех строк макета, кроме агрегированных
   INSERT INTO m30817
               (ngroup, HOUR, kwh, err)
    SELECT ngroup, 0, DECODE(ln_null, 0, 0, NULL), 0
    FROM   maketgroups
    WHERE  nmaket = ln_maket AND ngroup NOT IN(SELECT ngroup
                                               FROM   makettemp);

   -- По тем строкам, где есть данные рассчитываются и сохраняются расходы без 25 часа
   INSERT INTO m30817
               (ngroup, HOUR, kwh)
    SELECT   p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24') + 1,
             SUM(p.nkc
              * DECODE(
                 ntype,
                 1, h.er,
                 2, h.ed,
                 3, h.q1,
                 4, h.q3,
                 5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                 6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                ))
    FROM     maketgroups g, maketpoints p, halfhour h
    WHERE    g.nmaket = ln_maket AND g.ngroup NOT IN(SELECT ngroup
                                                     FROM   makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC(ad_date)
             AND h.date_time <= TRUNC(ad_date) + 1 AND h.nsource NOT IN(19, 29, 39, 49, 59)
    GROUP BY p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24');

   -- Отдельно сохраняется 25 час, помеченный кодом источника 19
   IF ln_count = 25 THEN
    INSERT INTO m30817
                (ngroup, HOUR, kwh)
     SELECT   p.ngroup, 25,
              SUM(p.nkc
               * DECODE(
                  ntype,
                  1, h.er,
                  2, h.ed,
                  3, h.q1,
                  4, h.q3,
                  5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                  6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                 ))
     FROM     maketgroups g, maketpoints p, halfhour h
     WHERE    g.nmaket = ln_maket AND g.ngroup NOT IN(SELECT ngroup
                                                      FROM   makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC(ad_date)
              AND h.date_time <= TRUNC(ad_date) + 1 AND h.nsource IN(19, 29, 39, 49, 59)
     GROUP BY p.ngroup;
   END IF;

   -- По строкам, где не оказалось данных проставляются нули
   FOR i IN 1 .. ln_count LOOP
    INSERT INTO m30817
                (ngroup, HOUR, kwh, err)
     (SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), 0
      FROM   m30817
      WHERE  HOUR = 0
      MINUS
      SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), 0
      FROM   m30817
      WHERE  HOUR = i);
   END LOOP;

   -- Округление с учетом ошибки предыдущего шага, запись ошибки текущего шага
   ln_needround30817 := util_pg.needround30817_f;

   FOR i IN 1 .. ln_count LOOP
    IF NOT(ln_hc = 23 AND i = util_pg.switch_f + 1) THEN
     IF ln_hc = 23 AND i = util_pg.switch_f + 2 THEN
      ln_temp := 2;
     ELSE
      ln_temp := 1;
     END IF;

     UPDATE m30817 m
     SET (kwh, err) =
          (SELECT util_pg.round_trunc(a.kwh, ln_needtrunc, b.err + NVL(c.err, 0)),
                  NVL(a.kwh, 0) + b.err + NVL(c.err, 0) - util_pg.round_trunc(NVL(a.kwh, 0), ln_needtrunc, b.err + NVL(c.err, 0))
           FROM   m30817 a,
                  m30817 b,
                  (SELECT me.ngroup, DECODE(ln_needround30817, 1, DECODE(TO_CHAR(ad_date, 'DD'), 1, 0, me.err), 0) err
                   FROM   maketerr me
                   WHERE  i = 1 AND me.ddate = TRUNC(ad_date) - 1) c
           WHERE  a.ngroup = b.ngroup AND a.HOUR = b.HOUR + ln_temp AND a.ngroup = m.ngroup AND a.HOUR = i AND a.ngroup = c.ngroup(+))
     WHERE  HOUR = i;
    END IF;
   END LOOP;

   --Запоминаем остатки округления на след день
   IF ln_needround30817 = 1 THEN
    DELETE FROM maketerr
    WHERE       ddate = TRUNC(ad_date) AND ngroup IN(SELECT ngroup
                                                     FROM   m30817);

    INSERT INTO maketerr
                (ngroup, ddate, err)
     SELECT ngroup, TRUNC(ad_date), err
     FROM   m30817
     WHERE  HOUR = ln_count;
   END IF;

   -- В рабочей таблице проставляются ид агрегированных строк и все часы суток
   FOR i IN 0 .. ln_count LOOP
    INSERT INTO m30817
                (ngroup, HOUR, kwh)
     SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL)
     FROM   maketgroups
     WHERE  nmaket = ln_maket AND ngroup IN(SELECT ngroup
                                            FROM   makettemp);
   END LOOP;

   LOOP
    -- Выбираем из рабочей таблицы очередную составляющую агрегированной строки или выходим, если таблица пуста
    BEGIN
     SELECT ngroup, nsubgroup, nsign
     INTO   ln_groupcode, ln_subgroupcode, ln_sign
     FROM   makettemp
     WHERE  nsubgroup NOT IN(SELECT ngroup
                             FROM   makettemp) AND ROWNUM = 1;
    EXCEPTION
     WHEN NO_DATA_FOUND THEN
      EXIT;
    END;

    -- Расчет и аккумулирование составляющей в агрегированной строке
    FOR i IN 1 .. ln_count LOOP
     BEGIN
      SELECT ln_sign * kwh
      INTO   ln_temp
      FROM   m30817
      WHERE  ngroup = ln_subgroupcode AND HOUR = i;
     EXCEPTION
      WHEN NO_DATA_FOUND THEN
       IF ln_null = 0 THEN
        ln_temp := 0;
       ELSE
        ln_temp := NULL;
       END IF;
     END;

     UPDATE m30817
     SET kwh = util_pg.sumn(kwh, ln_temp)
     WHERE  ngroup = ln_groupcode AND HOUR = i;
    END LOOP;

    -- удаляем из временной таблицы обработанную составляющую
    DELETE FROM makettemp
    WHERE       ngroup = ln_groupcode AND nsubgroup = ln_subgroupcode;
   END LOOP;
  ELSE                                                                                -- если группа не итоговая, то упрощенный вариант, added by EVK 02.04.2009
   INSERT INTO m30817
               (ngroup, HOUR, kwh)
    SELECT   p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24') + 1,
             ROUND(SUM(p.nkc
               * DECODE(
                  ntype,
                  1, h.er,
                  2, h.ed,
                  3, h.q1,
                  4, h.q3,
                  5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                  6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                 )))
    FROM     maketpoints p, halfhour h
    WHERE    p.ngroup = an_group AND h.mid = p.mid AND h.date_time > TRUNC(ad_date) AND h.date_time <= TRUNC(ad_date) + 1
             AND h.nsource NOT IN(19, 29, 39, 49, 59)
    GROUP BY p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24');

   -- Отдельно сохраняется 25 час, помеченный кодом источника 19
   IF ln_count = 25 THEN
    INSERT INTO m30817
                (ngroup, HOUR, kwh)
     SELECT   p.ngroup, 25,
              ROUND(SUM(p.nkc
                * DECODE(
                   ntype,
                   1, h.er,
                   2, h.ed,
                   3, h.q1,
                   4, h.q3,
                   5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                   6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                  )))
     FROM     maketpoints p, halfhour h
     WHERE    p.ngroup = an_group AND h.mid = p.mid AND h.date_time > TRUNC(ad_date) AND h.date_time <= TRUNC(ad_date) + 1 AND h.nsource IN(19, 29, 39, 49, 59)
     GROUP BY p.ngroup;
   END IF;

   -- По строкам, где не оказалось данных проставляются нули
   FOR i IN 1 .. ln_count LOOP
    INSERT INTO m30817
                (ngroup, HOUR, kwh, err)
     (SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), 0
      FROM   m30817
      WHERE  HOUR = 0
      MINUS
      SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), 0
      FROM   m30817
      WHERE  HOUR = i);
   END LOOP;
  END IF;                                                                                                                       -- added by EVK 02.04.2009 - END

  IF ln_count = 24 AND lb_25 THEN
   INSERT INTO m30817
               (ngroup, HOUR, kwh, err)
    SELECT ngroup, 25, 0, 0
    FROM   m30817
    WHERE  HOUR = 1;
  END IF;

  -- По всем строкам считается расход за сутки
  UPDATE m30817 m
  SET kwh = (SELECT NVL(SUM(kwh), 0)
             FROM   m30817
             WHERE  ngroup = m.ngroup)
  WHERE  HOUR = 0;

  IF an_maket > 0 THEN
   insert_uppddata(an_maket, ad_date);
  ELSE
   FOR i IN 1 .. ln_count LOOP
    SELECT NVL(SUM(kwh), 0)
    INTO   at_data(i)
    FROM   m30817
    WHERE  ngroup = an_group AND HOUR = i;
   END LOOP;

   IF ln_count = 24 AND lb_25 THEN
    at_data(25) := 0;
   END IF;

   set_stat(an_group, ad_date);
  END IF;

  -- Чистим временные таблицы
  DELETE FROM m30817;

  DELETE FROM makettemp;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT get_datalp_sp;
   raise_application_error(-20001, 'comsrvuppd_pg.get_datalp: ' || SQLERRM(SQLCODE));
 END;

