 --Возвращает данные Энергии по точке
 PROCEDURE get_dataen(
 an_group NUMBER,                                                                                                                  --Ид точки maketgroups.ngroup
                 ad_date DATE,                                                                                 --Дата, за которую необходимо получить информацию
 at_data OUT common_pg.tt_number                                                                 --Массив данных (5 значений суммарное, пик, день, ночь, резерв)
 ) IS
 BEGIN
  FOR i IN 1 .. 5 LOOP
   at_data(i) := NULL;
  END LOOP;
 --Напишу когда надо будет
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'comsrvuppd_pg.get_dataen: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
   --Записывает данные ГН по точке
 PROCEDURE set_datalp(
 an_cid NUMBER,                                                                                                                         --Ид канала channels.cid
               ad_date DATE,                                                                                                                              --Дата
                            an_obj NUMBER,                                                                                                         --Ид. объекта
                                          an_channel NUMBER,                                                                                        --Ид. канала
                                                            an_step NUMBER,                                                              --Шаг профиля в минутах
                                                                           at_data common_pg.tt_number                                           --Массив данных
 ) IS
  lt_e                common_pg.tt_number;
  lv_obj              VARCHAR2(256);
  ln_cid              NUMBER;
  ln_mid              NUMBER;
  ln_tmp              NUMBER;
  ln_block            NUMBER;
  ln_type             NUMBER;
  ld_max              DATE;
  ld_date             DATE DEFAULT TRUNC(ad_date);
  ln_switch           NUMBER;                                                                            -- признак перехода зима/лето, added by EVK 31.03.2009
  k                   NUMBER;                                                                           -- счетчик часовок/получасовок, added by EVK 31.03.2009
 BEGIN
  --    raise_application_error(-20001, an_cid||';'||ad_date||';'||an_obj||';'||an_channel||';'||an_step||';'||at_data.count);
  --5779;04.06.06;3025;78;60;24

  --Найдем ид канала
  SELECT     NVL(MAX(cid), 0)
  INTO       ln_cid
  FROM       channels
  WHERE      util_pg.allnumber_f(TRIM(util_pg.get_param(init_str, 2))) = an_obj
  CONNECT BY PRIOR cid = nparent
  START WITH cid = an_cid;

  IF ln_cid = 0 OR at_data.COUNT = 0 THEN                                                                                                        --не то объект
   RETURN;
  END IF;

  SELECT MAX(mid), COUNT(*), MAX(nblock), MAX(util_pg.get_pos_str(TRIM(UPPER(vimportcode)), an_channel))
  INTO   ln_mid, ln_tmp, ln_block, ln_type
  FROM   feeders
  WHERE  mid IN(SELECT mid
                FROM   chanpoint
                WHERE  cid = ln_cid) AND util_pg.get_pos_str(TRIM(UPPER(vimportcode)), an_channel) BETWEEN 1 AND 4;

  IF NOT(ln_tmp = 1 AND ln_block = 0) THEN
   RETURN;
  END IF;

  ld_max := ld_date - 1;
  ln_switch := util_pg.is_dayswitch(ld_date);                                                                                         -- added by EVK 31.03.2009
  k := 0;                                                                                                                             -- added by EVK 31.03.2009

  --Поискали нужные строки
  FOR i IN 1 .. at_data.COUNT LOOP
   IF ln_switch = 1 AND an_step = 60 AND i = util_pg.switch_f + 1 THEN                                                               -- added by EVK 31.03.2009
    NULL;                                                                                                                                -- пропускаем один час
   ELSIF ln_switch = 1 AND an_step = 30 AND(i = 2 * util_pg.switch_f + 1 OR i = 2 * util_pg.switch_f + 2) THEN
    NULL;                                                                                                                           -- пропускаем 2 получасовки
   ELSE
    k := k + 1;

    --Очистили
    FOR j IN 1 .. 4 LOOP
     lt_e(j) := NULL;
    END LOOP;

    IF ln_type = 1 AND at_data(i) >= 0 THEN
     lt_e(1) := at_data(i);
    ELSIF ln_type = 2 AND at_data(i) >= 0 THEN
     lt_e(2) := at_data(i);
    ELSIF ln_type = 3 AND at_data(i) >= 0 THEN
     lt_e(3) := at_data(i);
    ELSIF ln_type = 4 AND at_data(i) >= 0 THEN
     lt_e(4) := at_data(i);
    ELSIF ln_type = 1 AND at_data(i) < 0 THEN
     lt_e(2) := -at_data(i);
    ELSIF ln_type = 2 AND at_data(i) < 0 THEN
     lt_e(1) := -at_data(i);
    ELSIF ln_type = 3 AND at_data(i) < 0 THEN
     lt_e(4) := -at_data(i);
    ELSIF ln_type = 4 AND at_data(i) < 0 THEN
     lt_e(3) := -at_data(i);
    END IF;

    IF lt_e(1) IS NOT NULL OR lt_e(2) IS NOT NULL OR lt_e(3) IS NOT NULL OR lt_e(4) IS NOT NULL THEN
     IF an_step = 60 THEN
      das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + (k * an_step - 30) / 1440, NULL, TRUNC(lt_e(1) / 2), TRUNC(lt_e(2) / 2),
       TRUNC(lt_e(3) / 2), TRUNC(lt_e(4) / 2), NULL, NULL, NULL, comsrv_pg.cn_uppd, NULL);
      das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + k * an_step / 1440, NULL, lt_e(1) - TRUNC(lt_e(1) / 2), lt_e(2) - TRUNC(lt_e(2) / 2),
       lt_e(3) - TRUNC(lt_e(3) / 2), lt_e(4) - TRUNC(lt_e(4) / 2), NULL, NULL, NULL, comsrv_pg.cn_uppd, NULL);
     ELSE
      das_pg.ins_halfhourtmp(ln_mid, util_pg.to_unlocaltime(ld_date) + k * an_step / 1440, NULL, lt_e(1), lt_e(2), lt_e(3), lt_e(4), NULL, NULL, NULL,
       comsrv_pg.cn_uppd, NULL);
     END IF;

     ld_max := util_pg.to_unlocaltime(ld_date) + k * an_step / 1440;
    END IF;
   END IF;
  END LOOP;

  IF ld_max > ld_date THEN
   admin_pg.ins_last_save(ln_mid);

   UPDATE last_save
   SET halfhour = ld_max,
       state_date = SYSDATE,
       state_cod = 0,
       clock = 0
   WHERE  mid = ln_mid;
  END IF;

  COMMIT;
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvuppd_pg.set_datalp: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
   --Записывает данные ГН по точке
 PROCEDURE set_datalpn(
 an_cid NUMBER,                                                                                                                         --Ид канала channels.cid
               ad_date DATE,                                                                                                                              --Дата
                            an_type NUMBER,                                                                                 --Тип данных (Расход, Показания, ГН)
                                           an_obj NUMBER,                                                                                          --Ид. объекта
                                                         an_channel NUMBER,                                                                         --Ид. канала
                                                                           an_step NUMBER,                                               --Шаг профиля в минутах
                                                                                          at_data common_pg.tt_number                            --Массив данных
 ) IS
  cn_c       CONSTANT NUMBER := -31;
  cn_o       CONSTANT NUMBER := -41;
  ln_mid              NUMBER;
  ld_date             DATE DEFAULT util_pg.to_unlocaltime(TRUNC(ad_date));
  lt_e                common_pg.tt_number;
  ln_tmp              NUMBER;
  ln_iter             NUMBER := 0;
 BEGIN
  FOR lc IN (SELECT   cp.mid, MOD(ABS(app.nsort), 10) nsort
             FROM     chanpoint cp, addpointparam app, addpointparamval apv
             WHERE    cp.cid = an_cid AND cp.mid = apv.mid AND apv.nsort = app.nsort AND app.nsort BETWEEN cn_o - 9 AND cn_c
                      AND(apv.vvalue = TO_CHAR(an_channel) OR apv.vvalue = TO_CHAR(an_obj))
             GROUP BY cp.mid, MOD(ABS(app.nsort), 10)
             HAVING   COUNT(*) = 2) LOOP
   --Очистили
   FOR i IN 1 .. at_data.COUNT LOOP
    FOR j IN 1 .. 6 LOOP
     lt_e(j) := NULL;
    END LOOP;

    IF lc.nsort IN(1, 5) THEN
     lt_e(1) := at_data(i);
    ELSIF lc.nsort IN(2) THEN
     lt_e(2) := at_data(i);
    ELSIF lc.nsort IN(3, 6, 7) THEN
     lt_e(3) := at_data(i);
    ELSIF lc.nsort IN(4, 9) THEN
     lt_e(4) := at_data(i);
    ELSIF lc.nsort IN(8) THEN
     lt_e(5) := at_data(i);
    ELSIF lc.nsort IN(0) THEN
     lt_e(6) := at_data(i);
    END IF;

    FOR i IN 1 .. 3 LOOP
     IF NVL(lt_e(2 * i - 1), 0) < 0 OR NVL(lt_e(2 * i), 0) < 0 THEN                                                                            --Меняем местами
      ln_tmp := ABS(lt_e(2 * i - 1));
      lt_e(2 * i - 1) := ABS(lt_e(2 * i));
      lt_e(2 * i) := ln_tmp;
     END IF;
    END LOOP;

    ln_iter := ln_iter + 1;

    IF an_step = 60 THEN
     calcformula_pg.ins_halfhouroldw(lc.mid, ld_date + (ln_iter * an_step - 30) / 1440, NVL(TRUNC(lt_e(1) / 2), util_pg.cn_random),
      NVL(TRUNC(lt_e(2) / 2), util_pg.cn_random), NVL(TRUNC(lt_e(3) / 2), util_pg.cn_random), NVL(TRUNC(lt_e(4) / 2), util_pg.cn_random),
      NVL(TRUNC(lt_e(5) / 2), util_pg.cn_random), NVL(TRUNC(lt_e(6) / 2), util_pg.cn_random), NULL, NULL, NULL, NULL, NULL, NULL, 1);
     calcformula_pg.ins_halfhouroldw(lc.mid, ld_date + ln_iter * an_step / 1440, NVL(lt_e(1) - TRUNC(lt_e(1) / 2), util_pg.cn_random),
      NVL(lt_e(2) - TRUNC(lt_e(2) / 2), util_pg.cn_random), NVL(lt_e(3) - TRUNC(lt_e(3) / 2), util_pg.cn_random),
      NVL(lt_e(4) - TRUNC(lt_e(4) / 2), util_pg.cn_random), NVL(lt_e(5) - TRUNC(lt_e(5) / 2), util_pg.cn_random),
      NVL(lt_e(6) - TRUNC(lt_e(6) / 2), util_pg.cn_random), NULL, NULL, NULL, NULL, NULL, NULL, 1);
    ELSE
     calcformula_pg.ins_halfhouroldw(lc.mid, ld_date + ln_iter * an_step / 1440, NVL(lt_e(1), util_pg.cn_random), NVL(lt_e(2), util_pg.cn_random),
      NVL(lt_e(3), util_pg.cn_random), NVL(lt_e(4), util_pg.cn_random), NVL(lt_e(5), util_pg.cn_random), NVL(lt_e(6), util_pg.cn_random), NULL, NULL, NULL,
      NULL, NULL, NULL, 1);
    END IF;
   END LOOP;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvuppd_pg.set_datalpn: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Записывает статистику данные ГН по точке
 PROCEDURE set_stat(an_group NUMBER,                                                                                               --Ид точки maketgroups.ngroup
                                    ad_date DATE                                                               --Дата, за которую необходимо получить информацию
                                                ) IS
  ld_sys              DATE := SYSDATE;
  ln_operation        NUMBER;
  ln_maket            NUMBER;
  ln_group            NUMBER;
 BEGIN
  SAVEPOINT set_stat_sp;

  SELECT MAX(nmaket)
  INTO   ln_maket
  FROM   maketgroups
  WHERE  ngroup = an_group;

  SELECT NVL(MIN(ngroup), -1)
  INTO   ln_group
  FROM   maketgroups
  WHERE  nmaket = ln_maket;

  IF gn_channel IS NULL OR ln_group <> an_group THEN
   RETURN;
  END IF;

  SELECT uppdoperation_seq.NEXTVAL
  INTO   ln_operation
  FROM   DUAL;

  INSERT INTO uppdstat
              (noperation, cid, ddate, denter, nstate, dsend, verror, user_id, nnotfull)
  VALUES      (ln_operation, gn_channel, ad_date, ld_sys, 1, ld_sys, '', common_pg.userid_f, 0);

  INSERT INTO uppddata
              (noperation, ngroup, norder, nvalue, nqm)
   SELECT ln_operation, ngroup, HOUR, NVL(kwh, 0), DECODE(SIGN((ld_sys - ad_date) - DECODE(HOUR, 0, 24, HOUR) / 24 - cn_shift_qm), 1, cn_qmok, cn_qmnodata)
   FROM   m30817;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT set_stat_sp;
 END;

-----------------------------------------------------------------------------------------------------------------------
--Запись массива УППД в uppddata
 PROCEDURE insert_uppddata(an_maket NUMBER, ad_date DATE) IS
  ln_operation        NUMBER;
  ld_sys              DATE DEFAULT SYSDATE;
 BEGIN
  SELECT MAX(noperation)
  INTO   ln_operation
  FROM   uppdstat
  WHERE  cid = gn_channel AND ddate = ad_date AND nstate = 0;

  IF ln_operation > 0 THEN
   UPDATE uppdstat
   SET denter = ld_sys,
       dsend = NULL,
       verror = '',
       user_id = common_pg.userid_f,
       nnotfull = 0
   WHERE  noperation = ln_operation;

   DELETE FROM uppddata
   WHERE       noperation = ln_operation;
  ELSE
   SELECT uppdoperation_seq.NEXTVAL
   INTO   ln_operation
   FROM   DUAL;

   INSERT INTO uppdstat
               (noperation, cid, ddate, denter, nstate, dsend, verror, user_id, nnotfull)
   VALUES      (ln_operation, gn_channel, ad_date, ld_sys, 0, NULL, '', common_pg.userid_f, 0);
  END IF;

  INSERT INTO uppddata
              (noperation, ngroup, norder, nvalue, nqm)
   SELECT ln_operation, ngroup, HOUR, NVL(kwh, 0), DECODE(SIGN((ld_sys - ad_date) - DECODE(HOUR, 0, 24, HOUR) / 24 - cn_shift_qm), 1, cn_qmok, cn_qmnodata)
   FROM   m30817;
 END;

-----------------------------------------------------------------------------------------------------------------------
--Создание массива данных для отправки по УППД
 PROCEDURE create_uppddata(an_channel NUMBER) IS
  ln_maket            NUMBER;
  ln_shift            NUMBER;
  ld_halfhour         DATE;
  ln_depth            NUMBER;
  ld_sys              DATE := SYSDATE;
  lt_data             common_pg.tt_number;
  ln_block            NUMBER;
  ln_notactive        NUMBER := 0;
 --0 - Передача макета в автомате за текущие сутки постоянно, 1- иначе только за пред сутки один раз
 BEGIN
  editfeeders_pg.ins_last_save(an_channel, '');
  ln_maket := get_maketid(an_channel);

  IF NVL(ln_maket, 0) = 0 THEN
   RETURN;
  END IF;

--Корректируем время старта
  SELECT MAX(NVL(nshift, 0)) / 1440, MAX(nblock) nblock
  INTO   ln_shift, ln_block
  FROM   makets
  WHERE  nmaket = ln_maket;

  IF ln_block = 1 THEN
   RETURN;
  END IF;

--Читаем глубину
  SELECT NVL(MAX(nbilldatadepth), cn_defbilldatadepth), NVL(MAX(nnotreadcurr), 0)
  INTO   ln_depth, ln_notactive
  FROM   channels
  WHERE  cid = an_channel;

--Читаем время старта
  SELECT TRUNC(GREATEST(NVL(MAX(halfhour) + ln_notactive, ld_sys - ln_depth + 1), ld_sys - ln_depth + 1))
  INTO   ld_halfhour
  FROM   last_save s
  WHERE  s.mid = an_channel;

  --  raise_application_error (-20001, 'ld_halfhour=' || ld_halfhour || ' TRUNC (ld_sys - ln_shift)=' || (TRUNC (ld_sys - ln_shift))||' ln_shift='||ln_shift);
  WHILE ld_halfhour <= TRUNC(ld_sys - ln_shift - ln_notactive) LOOP
   get_datalp(0, ld_halfhour, lt_data, ln_maket);

   UPDATE last_save
   SET halfhour = ld_halfhour
   WHERE  mid = an_channel;

   ld_halfhour := ld_halfhour + 1;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'comsrvuppd_pg.create_uppddata: ' || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
--Возвращает следующий канал УППД (строку макета) отсортировано по коду объекта для групировки каналов по объектам (UPPD ver 3), а потом по ngroup
--an_defobject - Мы поддерживаем код объекта по умолчанию из строки инициализации модема
 FUNCTION get_next_chan_ext3(an_maket NUMBER, an_group NUMBER, an_defobject NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
  ln_object           NUMBER;
  ln_code             NUMBER;
  ln_group            NUMBER := NVL(an_group, 0);
 BEGIN
/*
 --Это старый вариант без сортировки по кодам объектов
 SELECT min(ngroup) into ln_ret FROM maketgroups WHERE ngroup > an_group AND nmaket = an_maket) LOOP
 return ln_ret;
 */

  --Нашли код канала входящей строки макета
  SELECT DECODE(COUNT(*), 0, 0, NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(vcode), 2))), an_defobject))
  INTO   ln_object
  FROM   maketgroups
  WHERE  nmaket = an_maket AND ngroup = ln_group;

  FOR lc IN (SELECT   ngroup
             FROM     maketgroups
             WHERE    nmaket = an_maket
                      AND(
                          NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(vcode, 2))), an_defobject) > ln_object
                          OR(NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(vcode, 2))), an_defobject) = ln_object AND ln_object > 0 AND ngroup > ln_group)
                         )
             ORDER BY NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(vcode, 2))), an_defobject), ngroup) LOOP
   ln_ret := lc.ngroup;
   EXIT;
  END LOOP;

  RETURN ln_ret;
 END;

-----------------------------------------------------------------------------------------------------------------------

 --Возвращает ид операции по каналу (движение по каналам -> операциям-> maketgroups.ngroup (при первом входе заполняем таблицу UPPDSTAT))
 --В maketgroups.vcode пишем код канала;код объекта если код объекта не задан берем из channels.init_str
 FUNCTION get_next_point_ext3(
 an_channel NUMBER,                                                                                                                           --Ид канала опроса
                   an_operation NUMBER,                                                                                                            --Ид операции
                                       an_group IN OUT NUMBER,                                                                     --Ид точки maketgroups.ngroup
                                                              an_code OUT NUMBER,                     --Код точки maketgroups.vcode (Код канала в терминах УППД)
 av_name OUT VARCHAR2,                                                                                  --Наименование точки maketgroups.vname (Для отображения)
                      av_date OUT VARCHAR2,                                                                                                        --Дата данных
                                           an_object OUT NUMBER                                                                    --Код объекта в терминах УППД
 )
  RETURN NUMBER IS
  ln_maket            NUMBER;
  ln_ret              NUMBER DEFAULT NVL(an_operation, 0);
  ln_depth            NUMBER;
  ln_object           NUMBER;
 BEGIN
  gn_channel := an_channel;
--Найдем ид макета
  ln_maket := get_maketid(an_channel);

  SELECT NVL(MAX(nbilldatadepth), cn_defbilldatadepth), NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(init_str), 2))), 0)
  INTO   ln_depth, ln_object
  FROM   channels
  WHERE  cid = an_channel;

  IF ln_ret = 0 THEN                                                                                                                          --На первом входе
   an_group := 0;
   create_uppddata(an_channel);
  END IF;

  IF NVL(an_group, 0) > 0 THEN
   SELECT NVL(MAX(ngroup), 0), NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(vcode), 1))), 0), MAX(vname),
          NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(vcode), 2))), ln_object)
   INTO   an_group, an_code, av_name, an_object
   FROM   maketgroups
   WHERE  nmaket = ln_maket AND ngroup = get_next_chan_ext3(ln_maket, an_group, ln_object);
  END IF;

  IF an_group = 0 THEN
   SELECT NVL(MIN(noperation), 0)
   INTO   ln_ret
   FROM   uppdstat
   WHERE  cid = an_channel AND ddate >= TRUNC(SYSDATE) - ln_depth + 1 AND nstate = 0 AND noperation > an_operation;

   IF ln_ret >= 0 THEN
    SELECT NVL(MAX(ngroup), 0), NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(vcode), 1))), 0), MAX(vname),
           NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(vcode), 2))), ln_object)
    INTO   an_group, an_code, av_name, an_object
    FROM   maketgroups
    WHERE  nmaket = ln_maket AND ngroup = get_next_chan_ext3(ln_maket, an_group, ln_object);
   END IF;
  END IF;

  IF ln_ret > 0 THEN
   SELECT TO_CHAR(MAX(ddate), 'dd.mm.yyyy hh24:mi')
   INTO   av_date
   FROM   uppdstat
   WHERE  noperation = ln_ret;
  END IF;

  RETURN ln_ret;
 END;

-----------------------------------------------------------------------------------------------------------------------
  --Возвращает ид операции по каналу (движение по каналам -> операциям-> maketgroups.ngroup (при первом входе заполняем таблицу UPPDSTAT))
 FUNCTION get_next_point_ext(
 an_channel NUMBER,                                                                                                                           --Ид канала опроса
                   an_operation NUMBER,                                                                                                            --Ид операции
                                       an_group IN OUT NUMBER,                                                                     --Ид точки maketgroups.ngroup
                                                              an_code OUT NUMBER,                    --Код точки maketgroups.vcode  (Код канала в терминах УППД)
 av_name OUT VARCHAR2,                                                                                  --Наименование точки maketgroups.vname (Для отображения)
                      av_date OUT VARCHAR2                                                                                      --Дата данных DD.MM.YYYY HH24:MI
 )
  RETURN NUMBER IS
  ln_object           NUMBER;
 BEGIN
  RETURN get_next_point_ext3(an_channel, an_operation, an_group, an_code, av_name, av_date, ln_object);
 END;

-----------------------------------------------------------------------------------------------------------------------

 --Возвращает данные ГН по точке
 PROCEDURE get_datalp_ext(
 an_operation NUMBER, an_group NUMBER,                                                                                             --Ид точки maketgroups.ngroup
                                      at_data OUT common_pg.tt_number,                                                  --Массив данных (23, 24 или 25 значений)
 at_qm OUT common_pg.tt_number                                                                                          --Массив данных (23, 24 или 25 значений)
 ) IS
  ld_date             DATE;
  ln_count            NUMBER;
 BEGIN
  IF util_pg.getparamvalue_f(44) = 1 THEN
   ln_count := 25;
  ELSE
   SELECT MAX(ddate)
   INTO   ld_date
   FROM   uppdstat
   WHERE  noperation = an_operation;

   ln_count := 24 - util_pg.is_dayswitch(ld_date);

   IF ln_count = 23 THEN
    ln_count := 24;
   END IF;                                                                                                                            -- added by EVK 30.03.2009
  END IF;

  FOR i IN 1 .. ln_count LOOP
   at_data(i) := 0;
  END LOOP;

  FOR lc IN (SELECT   norder, nvalue, NVL(nqm, cn_qmok) nqm
             FROM     uppddata
             WHERE    noperation = an_operation AND ngroup = an_group AND norder > 0
             ORDER BY norder) LOOP
   at_data(lc.norder) := lc.nvalue;
   at_qm(lc.norder) := lc.nqm;
  END LOOP;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Устанавливает статус передачи
 PROCEDURE set_sender_state_ext(an_operation NUMBER,                                                                                               --Ид операции
                                                    an_group NUMBER,                                                                                 --Ид группы
                                                                    an_state NUMBER,                                                                      --0-ОК
                                                                                    av_error VARCHAR2) IS
  ld_date             DATE := SYSDATE;
 BEGIN
  UPDATE uppdstat
  SET dsend = ld_date,
      nstate = DECODE(an_state, 0, 1, 2),
      verror = av_error
  WHERE  noperation = an_operation AND an_group = (SELECT MAX(ngroup)
                                                   FROM   uppddata
                                                   WHERE  noperation = an_operation);

  COMMIT;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Устанавливает статус передачи (для групповой передачи 29.02.2012)
 PROCEDURE set_sender_state_ext3(an_operation NUMBER, an_state NUMBER,                                                                                    --0-ОК
                                                                      av_error VARCHAR2) IS
  ld_date             DATE := SYSDATE;
 BEGIN
  UPDATE uppdstat
  SET dsend = ld_date,
      nstate = DECODE(an_state, 0, 1, 2),
      verror = av_error
  WHERE  noperation = an_operation;

  COMMIT;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE run_p(an_objid NUMBER, ad_dstart DATE, ad_dfinish DATE) IS
  ld_dat              DATE DEFAULT TRUNC(ad_dstart);
  lt_data             common_pg.tt_number;
 BEGIN
  WHILE ld_dat <= TRUNC(ad_dfinish) LOOP
   FOR lc IN (SELECT cid, util_pg.allnumber_f(util_pg.get_param(init_str, 5, ';')) nmaket
              FROM   channels
              WHERE  util_pg.is_uppd2(protocol_id) = 1 AND(NVL(an_objid, 0) = 0 OR cid IN(SELECT     mid
                                                                                          FROM       points
                                                                                          CONNECT BY PRIOR mid = PARENT
                                                                                          START WITH mid = an_objid))) LOOP
    IF lc.nmaket > 0 THEN
     gn_channel := lc.cid;
     get_datalp(0, ld_dat, lt_data, lc.nmaket);
    END IF;
   END LOOP;

   ld_dat := ld_dat + 1;
  END LOOP;
 END;

----------------------------------------------------------------------------------------------------------------
 PROCEDURE send_uppdmaket(an_noperation NUMBER) IS
  ln_tmp              NUMBER;
  ld_sys              DATE := SYSDATE;
 BEGIN
  SELECT MAX(nstate)
  INTO   ln_tmp
  FROM   uppdstat
  WHERE  noperation = an_noperation;

  IF NVL(ln_tmp, 0) = 0 THEN
   RETURN;
  END IF;

  SELECT uppdoperation_seq.NEXTVAL
  INTO   ln_tmp
  FROM   DUAL;

  INSERT INTO uppdstat
              (noperation, cid, ddate, denter, nstate, user_id, nnotfull)
   SELECT ln_tmp, cid, ddate, ld_sys, 0, common_pg.userid_f, nnotfull
   FROM   uppdstat
   WHERE  noperation = an_noperation;

  INSERT INTO uppddata
              (noperation, ngroup, norder, nvalue, nqm)
   SELECT ln_tmp, ngroup, norder, nvalue, nqm
   FROM   uppddata
   WHERE  noperation = an_noperation;
 END;
--------------------------------------------------------------------------------------------------------------
END;                                                                                                                               -- Package Body comsrvuppd_pg
/


-- End of DDL Script for Package Body RYDA.COMSRVUPPD_PG

