PACKAGE BODY cts_pg IS
--пакет для работы с системой единого времени
-- 01.10.2008 Виленская Н.Б.
-------------------------------------------------------------------------------
 PROCEDURE getdata (acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   l.mid field0, l.state_cod field1, (p.NAME || ' ( ' || p.short_name || ' ) ') field2, l.state_date field3, l.state_descr field4, (l.clock / 1000) field5,
            l.trial field6
       FROM last_save l, points p
      WHERE l.mid IN (SELECT mid
                        FROM points
                       WHERE PARENT = util_pg.cn_ctsmid) AND p.mid = l.mid(+)
   ORDER BY p.NAME;
 END;

-----------------------------------------------------------------------------
 PROCEDURE sortdata (an_sort NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql    VARCHAR2 (4000);
  ln_sort   NUMBER;
 BEGIN
  ln_sort := ABS (an_sort) + 1;
  lv_sql :=
   'SELECT  l.mid field0,l.state_cod field1,(p.name||'' ( ''||p.short_name||'' ) '') field2,l.state_date field3,
            l.state_descr field4 ,(l.clock/1000) field5, l.trial field6
            FROM last_save l,points p WHERE l.mid IN(SELECT mid FROM points WHERE parent='
   || util_pg.cn_ctsmid || ') and p.mid=l.mid(+)
            ORDER BY  ';

  IF ABS (an_sort) > 0 THEN
   lv_sql := lv_sql || ln_sort;

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1';

  OPEN acur_t FOR lv_sql;
 END;

-------------------------------------------------------------------------------------------------------
 --В supermain.cpp решает показывать кнопку СЕД или нет
 FUNCTION is_showe
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT COUNT (*)
    INTO ln_ret
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM points
                  WHERE PARENT IN (util_pg.cn_ctsmid, util_pg.cn_dsmid, util_pg.cn_clmid));

  RETURN ln_ret;
 END;

-------------------------------------------------------------------------------------------------------
 PROCEDURE getdata_ds (acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   l.mid field0, l.state_cod field1, p.NAME || DECODE (TRIM (p.short_name), '', '', ' ( ' || p.short_name || ' ) ') field2, l.state_date field3,
            l.state_descr field4, l.luck field5, l.trial field6
       FROM last_save l, points p
      WHERE (p.PARENT = util_pg.cn_dsmid OR p.mid = util_pg.cn_clmid) AND p.mid = l.mid(+)
   ORDER BY DECODE (p.mid, util_pg.cn_clmid, 1, 2), p.NAME;
 END;

-----------------------------------------------------------------------------
 PROCEDURE sortdata_ds (an_sort NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql    VARCHAR2 (4000);
  ln_sort   NUMBER;
 BEGIN
  ln_sort := ABS (an_sort) + 1;
  lv_sql :=
   'SELECT  l.mid field0,l.state_cod field1,p.name||decode(trim(p.short_name),'''','''','' ( ''||p.short_name||'' ) '') field2,l.state_date field3,
            l.state_descr field4 , l.luck field5, l.trial field6
            FROM last_save l,points p WHERE l.mid IN(SELECT mid FROM points WHERE parent='
   || util_pg.cn_dsmid || 'OR mid = ' || util_pg.cn_clmid || ') and p.mid=l.mid(+)
            ORDER BY  ';

  IF ABS (an_sort) > 0 THEN
   lv_sql := lv_sql || ln_sort;

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1';

  OPEN acur_t FOR lv_sql;
 END;

-------------------------------------------------------------------------------------------------------
 --В supermain.cpp решает, каким цветом показывать кнопку СЕВ или СД
 PROCEDURE show_cts_ds (serv NUMBER, show_serv OUT NUMBER) IS
 BEGIN
  SELECT COUNT (*)
    INTO show_serv
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM last_save l
                  WHERE l.mid IN (SELECT mid
                                    FROM points
                                   WHERE PARENT = serv) AND ((serv = util_pg.cn_ctsmid AND l.state_cod > 0) OR (serv = util_pg.cn_dsmid AND l.state_cod <> 1)));
 END;
-----------------------------------------------------------------------------------------
END;
/


