CREATE OR REPLACE 
PACKAGE BODY das_pg IS
---------------------------------------------------------------------------------------
-- Диспетчер закрытия суток и копирования в halfhour.
-- Вештак      24.11.02 Создан
-- Сечин       05.04.03 Модификация
-- Вештак      23.05.03 Процедуры закрытия и отката расчетных суток
-- Сечин       24.09.03 Модификация Процедуры закрытия и отката расчетных суток (откат на несколько дней)
-- Сечин       19.12.08 Модификация Закрытие суток и replicator вынесли
-- Сечин       08.11.10 Полная переработка
---------------------------------------------------------------------------------------
---------------      Interface        -------------------------------------------------
---------------------------------------------------------------------------------------
 cn_lock    CONSTANT NUMBER := 30;

---------------------------------------------------------------------------------------
---------------      Implementation   -------------------------------------------------
---------------------------------------------------------------------------------------
 PROCEDURE closeday(ad_date DATE) IS
  ld_sys              DATE := TRUNC(SYSDATE);
  ld_date             DATE := TRUNC(ad_date);
  ln_dif              NUMBER;
 BEGIN
  IF ld_date >= ld_sys THEN
   RETURN;
  END IF;

  ln_dif := util_pg.stephalfhour_f / 1440;

  IF admin_pg.lock_p(cn_lock, 'billold') <> 1 THEN
   raise_application_error(-20009, 'Закрытие периода не может быть проведено ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
    TRUE);
  END IF;

  -- Расчет и разноска по зонам суточных расходов
  calcformula_pg.ins_bill(ld_date, ln_dif);
  admin_pg.set_calcperiod(LEAST(GREATEST(ld_date, admin_pg.get_calcperiod), ld_sys - 1));
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Полный расчет дня (поднятие,формулы,дорасчет, мощность, среднее и.т.д, bill)
 PROCEDURE calctotalday(ad_date DATE) IS
  ld_date             DATE := TRUNC(ad_date);
 BEGIN
  calcformula_pg.calc(ad_date);
  COMMIT;
  closeday(ad_date);
  COMMIT;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE closeperiod(an_maket NUMBER, ad_date DATE) IS
  ld_start            DATE;
  ld_date             DATE DEFAULT TRUNC(LEAST(ad_date, SYSDATE - 1));
  ln_dif              NUMBER;
 BEGIN
  ld_start := admin_pg.get_calcperiod;

  IF ld_start >= ld_date THEN
   ld_start := ld_date - 1;
  END IF;

  ln_dif := ld_date - ld_start;

  FOR i IN 1 .. ln_dif LOOP
   calctotalday(ld_start + i);
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE rollbackperiod(an_maket NUMBER, ad_date DATE) IS
  ld_sys              DATE := SYSDATE;
  ld_date             DATE DEFAULT TRUNC(LEAST(ad_date, ld_sys - 1));
 BEGIN
  IF admin_pg.lock_p(cn_lock, 'billold') <> 1 THEN
   raise_application_error(-20009,
    'Перерасчет суточных расходов не может быть проведен ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.', TRUE);
  END IF;

  DELETE FROM billold
  WHERE       date_time > TRUNC(ld_date) + 1;

  admin_pg.set_calcperiod(ld_date);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'das_pg.rollbackperiod: ' || SQLERRM(SQLCODE));
 END;

---------------------------------------------------------------------------------------
 PROCEDURE recalcperiod(an_maket NUMBER, ad_date DATE) IS
 BEGIN
  rollbackperiod(an_maket, ad_date - 1);
  closeperiod(an_maket);
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calconeday4bill(an_maket NUMBER, ad_date DATE) IS
 BEGIN
  recalcperiod(an_maket, TRUNC(LEAST(SYSDATE - 20, ad_date)));
 END;

---------------------------------------------------------------------------------------
 PROCEDURE calcpoint4bill(an_mid NUMBER, ad_start DATE, ad_end DATE) IS
 BEGIN
  calcformula_pg.calcpoint4bill(an_mid, ad_start, ad_end);
 END;

---------------------------------------------------------------------------------------
 PROCEDURE checkhalfhour(an_commit NUMBER) IS
  ln_needrounderr     NUMBER DEFAULT util_pg.needrounderr_f;
  ln_switchmid        NUMBER;
  ln_tmp              NUMBER;
  src                 NUMBER;
  er_                 NUMBER;
  ed_                 NUMBER;
  q1_                 NUMBER;
  q2_                 NUMBER;
  q3_                 NUMBER;
  q4_                 NUMBER;
  ld_calcperiod       DATE;
  lv_qm               VARCHAR2(32);
  ld_sys              DATE;
  ld_min              DATE;
  ld_max              DATE;
 BEGIN
  SAVEPOINT checkhalfhour_sp;

  IF admin_pg.lock_p(cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error(-20009,
    'Расчет получасовых расходов не может быть проведен ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.', TRUE);
  END IF;

  ld_sys := SYSDATE;
  ld_calcperiod := admin_pg.get_calcperiod;

  FOR lc IN (SELECT t.*, util_pg.to_localtime(t.dwinter) date_time, util_pg.is_timeswitch(t.dwinter) istmw
             FROM   (SELECT   h.mid, h.er, h.ed, h.q1, h.q2, h.q3, h.q4, h.erm, h.edm, h.q1m, h.q2m, h.q3m, h.q4m, h.er_mtrsn, h.status, h.nsource,
                              NVL(f.kc, 1) nkc, NVL(f.nswitch, 0) nswitch, h.vqm, h.nmetertype,
                              util_pg.convertmeterdate_f(h.date_time, f.ntimezonew, f.ntimezones) dwinter, s.nvalidity, s.nsource snsource
                     FROM     halfhourtmp h, feeders f, points p, sourcetypes s
                     WHERE    h.mid = f.mid(+) AND h.mid = p.mid(+) AND p.ptype = s.ptype(+)
                     ORDER BY h.mid, h.date_time) t) LOOP
   --Базовое присвоение метки
   IF lc.nmetertype = comsrv_pg.cn_inet THEN                                                                                                        -- Донбасс;
    lv_qm := qm_pg.intet_to_qm(lc.status);
   ELSIF lc.nmetertype = comsrv_pg.cn_ev2 THEN                                                                                                         -- Днепр;
    lv_qm := qm_pg.ev2_to_qm(lc.status);
   ELSE                                                                                                                                                   --Наши
    lv_qm := NVL(lc.vqm, qm_pg.cv_okqm);
   END IF;

   IF lc.nvalidity IS NOT NULL THEN
    lv_qm := qm_pg.setvalidity(lv_qm, lc.nvalidity);
   END IF;

   --Метка получения исходных данных
   IF qm_pg.gbt(lv_qm, 13) <> qm_pg.cn_add_err THEN
    IF NVL(NVL(lc.er, lc.ed), NVL(lc.q1, lc.q3)) IS NULL THEN
     lv_qm := qm_pg.sbt(lv_qm, 1, qm_pg.cn_reserv);
     lv_qm := qm_pg.sbt(lv_qm, 13, qm_pg.cn_add_insuff);
    ELSE
     lv_qm := qm_pg.sbt(lv_qm, 13, qm_pg.cn_add_ok);
    END IF;
   END IF;

   --Метка источника данных
   IF qm_pg.gbt(lv_qm, 13) = qm_pg.cn_add_ok THEN
    IF lc.nsource IN(util_pg.cn_manualinput, util_pg.cn_manualinputw) THEN                                                                            --Ручники
     lv_qm := qm_pg.sbt(lv_qm, 22, qm_pg.cn_manual);
    ELSIF lc.nmetertype IN(comsrv_pg.cn_maket, comsrv_pg.cn_uppd) THEN                                                                                   --Макет
     lv_qm := qm_pg.sbt(lv_qm, 22, qm_pg.cn_maket);
    ELSIF lc.nmetertype IN(comsrv_pg.cn_oik, comsrv_pg.cn_oikdonbas) THEN                                                                                  --Оик
     lv_qm := qm_pg.sbt(lv_qm, 22, qm_pg.cn_oik);
    ELSIF lc.snsource > 0 THEN
     lv_qm := qm_pg.sbt(lv_qm, 22, lc.snsource);                                                                                              --Источник данных
    END IF;

    --Ессли источники cn_add_def,cn_oik,cn_manual,cn_maket
    IF qm_pg.gbt(lv_qm, 22) IN(qm_pg.cn_add_def, qm_pg.cn_oik, qm_pg.cn_oik, qm_pg.cn_manual, qm_pg.cn_maket, qm_pg.cn_calcr) THEN
     lv_qm := qm_pg.sbt(lv_qm, 10, qm_pg.cn_subst);
    END IF;
   END IF;

   --Контроль своевременности (!!!! потом напишем)
   IF qm_pg.gbt(lv_qm, 1) IN(qm_pg.cn_question, qm_pg.cn_ok) THEN
    lv_qm := qm_pg.sbt(lv_qm, 14, qm_pg.cn_add_ok);
   END IF;

   --Метка по журналу событий счетчика (статусным байтам счетчиков)
   lv_qm := qm_pg.get_qm_by_status(lc.nmetertype, lc.status, lv_qm);
   -- Метка по контролю границ
   lv_qm := qm_pg.checklimit(lc.mid, lv_qm, lc.er, lc.ed, lc.q1, lc.q2, lc.q3, lc.q4);

   IF lc.nsource = util_pg.cn_manualinput THEN
    src := util_pg.cn_manualinput;
   /*ELSIF lc.nsource = 20 THEN
    src := 20;*/
   ELSE
    src := comsrv_pg.cn_auto;
   END IF;                                                                                         -- по коду нити и связному номеру определяем дубль / не дубль

   -- Учет ОВ
   ln_switchmid := 0;

   IF lc.nswitch = 1 THEN
    SELECT NVL(MAX(mid), 0)
    INTO   ln_switchmid
    FROM   switches
    WHERE  nswitch = lc.mid AND lc.date_time > dswitch AND lc.date_time <= NVL(util_pg.ceilhh24_2(descape), comsrvdll_pg.cd_transnull);
   END IF;

   -- производим округление с переносом остатков
   IF ln_needrounderr = 1 THEN
    SELECT MAX(mid) mid, TRUNC(lc.er + NVL(MAX(er), 0)) er, TRUNC(lc.ed + NVL(MAX(ed), 0)) ed, TRUNC(lc.q1 + NVL(MAX(q1), 0)) q1,
           TRUNC(lc.q2 + NVL(MAX(q2), 0)) q2, TRUNC(lc.q3 + NVL(MAX(q3), 0)) q3, TRUNC(lc.q4 + NVL(MAX(q4), 0)) q4
    INTO   ln_tmp, er_, ed_, q1_, q2_, q3_, q4_
    FROM   round_errors
    WHERE  mid = lc.mid AND nsource = src;

    IF ln_tmp IS NULL THEN                                                                                                                  --Еще нет в таблице
     INSERT INTO round_errors
                 (mid, nsource, er, ed, q1, q2, q3, q4)
     VALUES      (lc.mid, src, 0, 0, 0, 0, 0, 0);
    END IF;

    -- сохраняем в БД остатки
    UPDATE round_errors
    SET er = NVL(er, 0) + NVL(lc.er, 0) - NVL(er_, 0),
        ed = NVL(ed, 0) + NVL(lc.ed, 0) - NVL(ed_, 0),
        q1 = NVL(q1, 0) + NVL(lc.q1, 0) - NVL(q1_, 0),
        q2 = NVL(q2, 0) + NVL(lc.q2, 0) - NVL(q2_, 0),
        q3 = NVL(q3, 0) + NVL(lc.q3, 0) - NVL(q3_, 0),
        q4 = NVL(q4, 0) + NVL(lc.q4, 0) - NVL(q4_, 0)
    WHERE  mid = lc.mid AND nsource = src;
   ELSE
    er_ := lc.er;
    ed_ := lc.ed;
    q1_ := lc.q1;
    q2_ := lc.q2;
    q3_ := lc.q3;
    q4_ := lc.q4;
   END IF;

   IF lc.istmw = -1 THEN                                                                                         --Время перехода с лета на зиму (nsource=19,29)
    src := src + 9;
   END IF;

   SELECT DECODE(lc.nsource, util_pg.cn_manualinput, MAX(nsource), MIN(nsource))
   INTO   ln_tmp
   FROM   halfhourold
   WHERE  mid = lc.mid AND date_time = lc.date_time
          AND DECODE(nsource, util_pg.cn_manualinput, comsrv_pg.cn_auto, util_pg.cn_manualinputw, comsrv_pg.cn_auto + 9, nsource) =
                                                                                                       DECODE(
                                                                                                        lc.nsource,
                                                                                                        util_pg.cn_manualinput, src - 40,
                                                                                                        src
                                                                                                       );

   BEGIN                                                                              -- BEGIN EXCEPTION здесь на всякиий случай для поддержки старых повторений
    IF ln_tmp > 0 THEN
     UPDATE halfhourold
     SET er = er_,
         ed = ed_,
         q1 = q1_,
         q2 = q2_,
         q3 = q3_,
         q4 = q4_,
         erm = lc.erm,
         edm = lc.edm,
         q1m = lc.q1m,
         q2m = lc.q2m,
         q3m = lc.q3m,
         q4m = lc.q4m,
         er_mtrsn = lc.er_mtrsn,
         status = lc.status,
         nkc = lc.nkc,
         vqm = lv_qm,
         denter = ld_sys,
         nsource = src
     WHERE  mid = lc.mid AND date_time = lc.date_time AND nsource = ln_tmp;
    ELSE
     INSERT INTO halfhourold
                 (mid, date_time, nsource, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status, nkc, vqm)
     VALUES      (lc.mid, lc.date_time, src, er_, ed_, q1_, q2_, q3_, q4_, lc.erm, lc.edm, lc.q1m, lc.q2m, lc.q3m, lc.q4m, lc.er_mtrsn, lc.status, lc.nkc,
                  lv_qm);
    END IF;
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     RAISE;

     --если есть запись по этой точке на это время - производим UPDATE
     UPDATE halfhourold
     SET er = er_,
         ed = ed_,
         q1 = q1_,
         q2 = q2_,
         q3 = q3_,
         q4 = q4_,
         erm = lc.erm,
         edm = lc.edm,
         q1m = lc.q1m,
         q2m = lc.q2m,
         q3m = lc.q3m,
         q4m = lc.q4m,
         er_mtrsn = lc.er_mtrsn,
         status = lc.status,
         nkc = lc.nkc,
         vqm = lv_qm,
         denter = ld_sys
     WHERE  mid = lc.mid AND date_time = lc.date_time AND nsource = src;
   END;

   IF ln_switchmid > 0 THEN                                                                                                   -- дублируем данные по ОВ на точку
    lv_qm := qm_pg.sbt(qm_pg.sbt(lv_qm, 22, qm_pg.cn_ov), 19, qm_pg.cn_add_ok);

    IF lc.nsource = 50 THEN
     src := src - 20;
    ELSE
     src := src + 20;
    END IF;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, nsource, nswitch, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status, nkc, vqm)
     VALUES      (ln_switchmid, lc.date_time, src, lc.mid, er_, ed_, q1_, q2_, q3_, q4_, lc.erm, lc.edm, lc.q1m, lc.q2m, lc.q3m, lc.q4m, lc.er_mtrsn,
                  lc.status, lc.nkc, lv_qm);
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      --если есть запись по этой точке на это время - производим UPDATE
      UPDATE halfhourold
      SET nswitch = lc.mid,
          er = er_,
          ed = ed_,
          q1 = q1_,
          q2 = q2_,
          q3 = q3_,
          q4 = q4_,
          erm = lc.erm,
          edm = lc.edm,
          q1m = lc.q1m,
          q2m = lc.q2m,
          q3m = lc.q3m,
          q4m = lc.q4m,
          er_mtrsn = lc.er_mtrsn,
          status = lc.status,
          nkc = lc.nkc,
          vqm = lv_qm,
          denter = ld_sys
      WHERE  mid = ln_switchmid AND date_time = lc.date_time AND nsource = src;
    END;
   END IF;

   ld_max := lc.dwinter;
  END LOOP;

  DELETE FROM halfhourtmp;

  IF an_commit = 1 THEN
   COMMIT;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT checkhalfhour_sp;
   raise_application_error(-20001, 'das_pg.checkhalfhour_new: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkhalfhour_without_err(an_commit NUMBER) IS
 BEGIN
  checkhalfhour(an_commit);
 EXCEPTION
  WHEN OTHERS THEN
   NULL;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION getholeinhalfhour(ad_date DATE, an_mid NUMBER, an_ret48 NUMBER, an_type NUMBER)
  RETURN common_pg.tt_number IS
  lt_ret              common_pg.tt_number;
  i                   NUMBER;

  CURSOR lcur_sel IS
   SELECT   ROWNUM dt
   FROM     halfhourold
   WHERE    ROWNUM < 49
   MINUS
   SELECT   TRUNC(TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800) + 1 dt
   FROM     halfhour
   WHERE    mid = an_mid AND date_time > TRUNC(ad_date) AND date_time <= TRUNC(ad_date) + 1
   GROUP BY TRUNC(TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800)
   HAVING   (
             (
              an_type IS NULL
              AND(SUM(er) IS NOT NULL OR SUM(ed) IS NOT NULL OR SUM(q1) IS NOT NULL OR SUM(q2) IS NOT NULL OR SUM(q3) IS NOT NULL OR SUM(q4) IS NOT NULL)
             )
             OR(an_type IS NOT NULL AND DECODE(an_type, 1, SUM(er), 2, SUM(ed), 3, SUM(q1), 5, SUM(q3), 4, SUM(q2), 6, SUM(q4)) IS NOT NULL)
            )
   MINUS
   SELECT   util_pg.switch_f * 2 + 1
   FROM     DUAL
   WHERE    util_pg.is_dayswitch(ad_date) = 1
   MINUS
   SELECT   util_pg.switch_f * 2 + 2
   FROM     DUAL
   WHERE    util_pg.is_dayswitch(ad_date) = 1
   ORDER BY 1;
 BEGIN
  i := 0;

  FOR lc IN lcur_sel LOOP
   i := i + 1;
   lt_ret(i) := lc.dt;
  END LOOP;

  IF an_ret48 = 1 AND lt_ret.COUNT = 0 THEN
   IF util_pg.is_dayswitch(ad_date) = 1 THEN
    FOR i IN 1 .. 46 LOOP
     IF i > util_pg.switch_f * 2 THEN
      lt_ret(i) := i + 2;
     ELSE
      lt_ret(i) := i;
     END IF;
    END LOOP;
   ELSE
    FOR i IN 1 .. 48 LOOP
     lt_ret(i) := i;
    END LOOP;
   END IF;
  END IF;

  RETURN lt_ret;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE correchalfhour(ad_date DATE, an_mid NUMBER) IS
  ln_source           NUMBER DEFAULT 9;
  ld_date             DATE DEFAULT TRUNC(ad_date);
  ln_dg               NUMBER;
  ld_tmp              DATE;
  ln_cn               NUMBER;
  ln_k                NUMBER;
  ln_cnreal           NUMBER;
  ln_ser              NUMBER;
  ln_sed              NUMBER;
  ln_sq1              NUMBER;
  ln_sq3              NUMBER;
  ln_sq2              NUMBER;
  ln_sq4              NUMBER;
  lt_er               common_pg.tt_number;
  lt_ed               common_pg.tt_number;
  lt_q1               common_pg.tt_number;
  lt_q3               common_pg.tt_number;
  lt_q2               common_pg.tt_number;
  lt_q4               common_pg.tt_number;
  lt_hole             common_pg.tt_number;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q3               NUMBER;
  ln_q2               NUMBER;
  ln_q4               NUMBER;
  z                   NUMBER;

  CURSOR lc_selmid IS
   SELECT f.mid, NVL(f.kc, 1) kc, LENGTH(TRUNC(digits)) dg
   FROM   feeders f, meters m
   WHERE  f.mid = m.mid(+) AND m.entype(+) = 7 AND(an_mid IS NULL OR an_mid = f.mid);

  CURSOR lc_selmindt(lc_mid NUMBER, lc_mtrsn VARCHAR2) IS
   SELECT   date_time dt, nsource, 0 b, erm, edm, q1m, q3m, q2m, q4m
   FROM     halfhour
   WHERE    mid = lc_mid AND er_mtrsn = lc_mtrsn AND NVL(erm, edm) IS NOT NULL AND date_time = ld_date
   UNION ALL
   SELECT   date_time dt, nsource, 1 b, erm, edm, q1m, q3m, q2m, q4m
   FROM     monthsorg
   WHERE    mid = lc_mid AND NVL(er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL(erm, edm) IS NOT NULL
            AND date_time =
                (SELECT MAX(date_time) dt
                 FROM   monthsorg
                 WHERE  mid = lc_mid AND date_time BETWEEN ADD_MONTHS(ld_date, -2) AND ld_date AND TRUNC(date_time) = date_time
                        AND NVL(er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL(erm, edm) IS NOT NULL)
   UNION ALL
   SELECT   date_time dt, nsource, 2 b, erm, edm, q1m, q3m, q2m, q4m
   FROM     billorg
   WHERE    mid = lc_mid AND NVL(er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL(erm, edm) IS NOT NULL
            AND date_time =
                (SELECT MAX(date_time) dt
                 FROM   billorg
                 WHERE  mid = lc_mid AND date_time BETWEEN ADD_MONTHS(ld_date, -2) AND ld_date AND TRUNC(date_time) = date_time
                        AND NVL(er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL(erm, edm) IS NOT NULL)
   ORDER BY 1 DESC, 2 DESC, 3;

  CURSOR lc_selmaxdt(lc_mid NUMBER) IS
   SELECT   date_time dt, nsource, erm, edm, q1m, q3m, q2m, q4m, er_mtrsn mtrsn
   FROM     halfhour
   WHERE    mid = lc_mid AND er_mtrsn IS NOT NULL AND NVL(erm, edm) IS NOT NULL AND date_time = ld_date + 1
   UNION ALL
   SELECT   date_time dt, nsource, erm, edm, q1m, q3m, q2m, q4m, NVL(er_mtrsn, ed_mtrsn) mtrsn
   FROM     monthsorg
   WHERE    mid = lc_mid AND NVL(er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL(erm, edm) IS NOT NULL
            AND date_time = (SELECT MIN(date_time) dt
                             FROM   monthsorg
                             WHERE  mid = lc_mid AND date_time >= ld_date + 1 AND NVL(er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL(erm, edm) IS NOT NULL)
   UNION ALL
   SELECT   date_time dt, nsource, erm, edm, q1m, q3m, q2m, q4m, NVL(er_mtrsn, ed_mtrsn) mtrsn
   FROM     billorg
   WHERE    mid = lc_mid AND NVL(er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL(erm, edm) IS NOT NULL
            AND date_time = (SELECT MIN(date_time) dt
                             FROM   billorg
                             WHERE  mid = lc_mid AND date_time >= ld_date + 1 AND NVL(er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL(erm, edm) IS NOT NULL)
   ORDER BY 1, 2;
 BEGIN
  IF an_mid IS NULL THEN
   DELETE FROM halfhourold
   WHERE       date_time > ld_date AND date_time <= ld_date + 1 AND nsource = ln_source;

   IF util_pg.is_dayswitch(ld_date) = 1 THEN
    DELETE FROM halfhourold
    WHERE       date_time > ld_date + util_pg.switch_f / 24 AND date_time <= ld_date + (util_pg.switch_f + 1) / 24;
   END IF;
  ELSE
   DELETE FROM halfhourold
   WHERE       mid = an_mid AND date_time > ld_date AND date_time <= ld_date + 1 AND nsource = ln_source;

   IF util_pg.is_dayswitch(ld_date) = 1 THEN
    DELETE FROM halfhourold
    WHERE       mid = an_mid AND date_time > ld_date + util_pg.switch_f / 24 AND date_time <= ld_date + (util_pg.switch_f + 1) / 24;
   END IF;
  END IF;

  FOR lc IN lc_selmid LOOP
   FOR lc1 IN lc_selmaxdt(lc.mid) LOOP
    FOR lc2 IN lc_selmindt(lc.mid, lc1.mtrsn) LOOP
     DELETE FROM halfhourold
     WHERE       mid = lc.mid AND date_time > ld_date + 1 AND date_time <= util_pg.ceilhh24_2(lc1.dt) AND nsource = ln_source;

     SELECT NVL(ROUND(util_pg.indicoverturn(lc1.erm - lc2.erm, ln_dg) * lc.kc), 0) - NVL(SUM(er), 0) er,
            NVL(ROUND(util_pg.indicoverturn(lc1.edm - lc2.edm, ln_dg) * lc.kc), 0) - NVL(SUM(ed), 0) ed,
            NVL(ROUND(util_pg.indicoverturn(lc1.q1m - lc2.q1m, ln_dg) * lc.kc), 0) - NVL(SUM(q1), 0) q1,
            NVL(ROUND(util_pg.indicoverturn(lc1.q3m - lc2.q3m, ln_dg) * lc.kc), 0) - NVL(SUM(q3), 0) q3,
            NVL(ROUND(util_pg.indicoverturn(lc1.q2m - lc2.q2m, ln_dg) * lc.kc), 0) - NVL(SUM(q2), 0) q2,
            NVL(ROUND(util_pg.indicoverturn(lc1.q4m - lc2.q4m, ln_dg) * lc.kc), 0) - NVL(SUM(q4), 0) q4
     INTO   ln_er, ln_ed, ln_q1, ln_q3, ln_q2, ln_q4
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time > lc2.dt AND date_time <= util_pg.ceilhh24_2(lc1.dt) AND(NVL(nsource, 0) < 30 OR NVL(nsource, 0) > 49);

     IF ld_date + 1 <> lc1.dt THEN                                                                                            --(-) Только на последний день ()
      ln_er := GREATEST(ln_er, 0);
      ln_ed := GREATEST(ln_ed, 0);
      ln_q1 := GREATEST(ln_q1, 0);
      ln_q3 := GREATEST(ln_q3, 0);
      ln_q2 := GREATEST(ln_q2, 0);
      ln_q4 := GREATEST(ln_q4, 0);
     END IF;

     IF ln_er = 0 AND ln_ed = 0 AND ln_q1 = 0 AND ln_q3 = 0 AND ln_q2 = 0 AND ln_q4 = 0 THEN
      EXIT;
     END IF;

     ln_cn := 48 *(util_pg.ceilhh24_2(lc1.dt) - ld_date);

     IF util_pg.is_dayswitch(ld_date) = 1 THEN                                                                                         --При переходе на лето -2
      lt_hole := getholeinhalfhour(ld_date, lc.mid, 1);
      --Ищем дырки
      ln_cnreal := lt_hole.COUNT;
     ELSE
      ln_cnreal := ln_cn;
     END IF;

     ln_ser := ln_er;
     ln_sed := ln_ed;
     ln_sq1 := ln_q1;
     ln_sq3 := ln_q3;
     ln_sq2 := ln_q2;
     ln_sq4 := ln_q4;
     ln_k := 1;

     FOR i IN 1 .. ln_cn LOOP
      IF lt_hole.COUNT = 0 OR(ln_k <= lt_hole.COUNT AND lt_hole(ln_k) = i) THEN                                                                           --Или
       ln_k := ln_k + 1;
       lt_er(i) := TRUNC(ln_er / ln_cnreal);
       ln_ser := ln_ser - lt_er(i);
       lt_ed(i) := TRUNC(ln_ed / ln_cnreal);
       ln_sed := ln_sed - lt_ed(i);
       lt_q1(i) := TRUNC(ln_q1 / ln_cnreal);
       ln_sq1 := ln_sq1 - lt_q1(i);
       lt_q3(i) := TRUNC(ln_q3 / ln_cnreal);
       ln_sq3 := ln_sq3 - lt_q3(i);
       lt_q2(i) := TRUNC(ln_q2 / ln_cnreal);
       ln_sq2 := ln_sq2 - lt_q2(i);
       lt_q4(i) := TRUNC(ln_q4 / ln_cnreal);
       ln_sq4 := ln_sq4 - lt_q4(i);
      ELSE
       lt_er(i) := 0;
       lt_ed(i) := 0;
       lt_q1(i) := 0;
       lt_q3(i) := 0;
       lt_q2(i) := 0;
       lt_q4(i) := 0;
      END IF;
     END LOOP;

     IF ld_date + 1 <> lc1.dt THEN
      ln_ser := 0;
      ln_sed := 0;
      ln_sq1 := 0;
      ln_sq3 := 0;
      ln_sq2 := 0;
      ln_sq4 := 0;
     END IF;

     --ln_ser:=trunc(ln_ser*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     --ln_sed:=trunc(ln_sed*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     --ln_sq1:=trunc(ln_sq1*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     --ln_sq3:=trunc(ln_sq3*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     ln_k := 1;

     FOR i IN 1 .. 48 LOOP
      IF lt_hole.COUNT = 0 OR(ln_k <= lt_hole.COUNT AND lt_hole(ln_k) = i) THEN
       ln_k := ln_k + 1;

       IF ABS(ln_ser) >= 1 THEN
        lt_er(i) := lt_er(i) + SIGN(ln_ser);
        ln_ser := ln_ser - SIGN(ln_ser);
       END IF;

       IF ABS(ln_sed) >= 1 THEN
        lt_ed(i) := lt_ed(i) + SIGN(ln_sed);
        ln_sed := ln_sed - SIGN(ln_sed);
       END IF;

       IF ABS(ln_sq1) >= 1 THEN
        lt_q1(i) := lt_q1(i) + SIGN(ln_sq1);
        ln_sq1 := ln_sq1 - SIGN(ln_sq1);
       END IF;

       IF ABS(ln_sq3) >= 1 THEN
        lt_q3(i) := lt_q3(i) + SIGN(ln_sq3);
        ln_sq3 := ln_sq3 - SIGN(ln_sq3);
       END IF;

       IF ABS(ln_sq2) >= 1 THEN
        lt_q2(i) := lt_q2(i) + SIGN(ln_sq2);
        ln_sq2 := ln_sq2 - SIGN(ln_sq2);
       END IF;

       IF ABS(ln_sq4) >= 1 THEN
        lt_q4(i) := lt_q4(i) + SIGN(ln_sq4);
        ln_sq4 := ln_sq4 - SIGN(ln_sq4);
       END IF;
      END IF;
     END LOOP;

     IF util_pg.is_dayswitch(ld_date) = -1 THEN
      --день перевода времени осенью (все подгоняем на 02:30 03:00)
      FOR i IN 1 .. 48 LOOP
       z := 2 *(util_pg.switch_f + 1);

       IF i <> z THEN
        lt_er(z) := lt_er(z) + lt_er(i);
        lt_ed(z) := lt_ed(z) + lt_ed(i);
        lt_q1(z) := lt_q1(z) + lt_q1(i);
        lt_q3(z) := lt_q3(z) + lt_q3(i);
        lt_q2(z) := lt_q2(z) + lt_q2(i);
        lt_q4(z) := lt_q4(z) + lt_q4(i);
        lt_er(i) := 0;
        lt_ed(i) := 0;
        lt_q1(i) := 0;
        lt_q3(i) := 0;
        lt_q2(i) := 0;
        lt_q4(i) := 0;
       END IF;
      END LOOP;

      lt_er(z - 1) := TRUNC(lt_er(z) / 2);
      lt_er(z) := lt_er(z) - lt_er(z - 1);
      lt_ed(z - 1) := TRUNC(lt_ed(z) / 2);
      lt_ed(z) := lt_ed(z) - lt_ed(z - 1);
      lt_q1(z - 1) := TRUNC(lt_q1(z) / 2);
      lt_q1(z) := lt_q1(z) - lt_q1(z - 1);
      lt_q3(z - 1) := TRUNC(lt_q3(z) / 2);
      lt_q3(z) := lt_q3(z) - lt_q3(z - 1);
      lt_q2(z - 1) := TRUNC(lt_q2(z) / 2);
      lt_q2(z) := lt_q2(z) - lt_q2(z - 1);
      lt_q4(z - 1) := TRUNC(lt_q4(z) / 2);
      lt_q4(z) := lt_q4(z) - lt_q4(z - 1);
     END IF;

     FOR i IN 1 .. 48 LOOP                                                                                                 ------Считаем больше а пишем на сутки
      IF lt_er(i) <> 0 OR lt_ed(i) <> 0 OR lt_q1(i) <> 0 OR lt_q3(i) <> 0 OR lt_q2(i) <> 0 OR lt_q4(i) <> 0 THEN
       INSERT INTO halfhourold
                   (mid, date_time, nsource, er, ed, q1, q3, q2, q4, nkc)
       VALUES      (lc.mid, ld_date + i / 48, ln_source, lt_er(i), lt_ed(i), lt_q1(i), lt_q3(i), lt_q2(i), lt_q4(i), lc.kc);
      END IF;
     END LOOP;

     EXIT;
    END LOOP;

    EXIT;
   END LOOP;

   lt_hole.DELETE;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20002, 'das_pg.correchalfhour: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE insert_hf_in_profile(
 an_mid NUMBER, ad_date DATE,                                                                                                       --ad_date передавать по зиме
                             an_period NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER, an_rn NUMBER
 ) IS
  ln_stepprofile      NUMBER DEFAULT util_pg.stepprofile_f;
  ln_cnprf            NUMBER DEFAULT 24 * 60 / an_period;
  ln_tmp              NUMBER;
  ln_ser              NUMBER;
  ln_sed              NUMBER;
  ln_sq1              NUMBER;
  ln_sq2              NUMBER;
  ln_sq3              NUMBER;
  ln_sq4              NUMBER;
  ln_ter              common_pg.tt_number;
  ln_ted              common_pg.tt_number;
  ln_tq1              common_pg.tt_number;
  ln_tq2              common_pg.tt_number;
  ln_tq3              common_pg.tt_number;
  ln_tq4              common_pg.tt_number;
  ld_date             DATE;
  ln_source           NUMBER;
 BEGIN
  IF /*Доп проверка*/ an_period > ln_stepprofile AND MOD(an_period, ln_stepprofile) = 0 AND util_pg.get_typekeephalfhour(an_mid) = 2 THEN
                                                                                                                           --Расчитывать PROFILE по ГН счетчика
   ln_ser := an_er;
   ln_sed := an_ed;
   ln_sq1 := an_q1;
   ln_sq2 := an_q2;
   ln_sq3 := an_q3;
   ln_sq4 := an_q4;
   ln_tmp := an_period / ln_stepprofile;

   --Рисуем профиль PROFILE
   FOR i IN 1 .. ln_tmp LOOP                                                                                                             --Сначала целочисленно
    ln_ter(i) := TRUNC(an_er / ln_tmp, an_rn);
    ln_ted(i) := TRUNC(an_ed / ln_tmp, an_rn);
    ln_tq1(i) := TRUNC(an_q1 / ln_tmp, an_rn);
    ln_tq2(i) := TRUNC(an_q2 / ln_tmp, an_rn);
    ln_tq3(i) := TRUNC(an_q3 / ln_tmp, an_rn);
    ln_tq4(i) := TRUNC(an_q4 / ln_tmp, an_rn);
    ln_ser := ln_ser - ln_ter(i);
    ln_sed := ln_sed - ln_ted(i);
    ln_sq1 := ln_sq1 - ln_tq1(i);
    ln_sq2 := ln_sq2 - ln_tq2(i);
    ln_sq3 := ln_sq3 - ln_tq3(i);
    ln_sq4 := ln_sq4 - ln_tq4(i);
   END LOOP;

   FOR i IN 1 .. ln_tmp LOOP                                                                                                              --Затем расскидываем 1
    IF ln_ser > 0 THEN
     ln_ter(i) := ln_ter(i) + LEAST(1, ln_ser);
     ln_ser := ln_ser - LEAST(1, ln_ser);
    END IF;

    IF ln_sed > 0 THEN
     ln_ted(i) := ln_ted(i) + LEAST(1, ln_sed);
     ln_sed := ln_sed - LEAST(1, ln_sed);
    END IF;

    IF ln_sq1 > 0 THEN
     ln_tq1(i) := ln_tq1(i) + LEAST(1, ln_sq1);
     ln_sq1 := ln_sq1 - LEAST(1, ln_sq1);
    END IF;

    IF ln_sq2 > 0 THEN
     ln_tq2(i) := ln_tq2(i) + LEAST(1, ln_sq2);
     ln_sq2 := ln_sq2 - LEAST(1, ln_sq2);
    END IF;

    IF ln_sq3 > 0 THEN
     ln_tq3(i) := ln_tq3(i) + LEAST(1, ln_sq3);
     ln_sq3 := ln_sq3 - LEAST(1, ln_sq3);
    END IF;

    IF ln_sq4 > 0 THEN
     ln_tq4(i) := ln_tq4(i) + LEAST(1, ln_sq4);
     ln_sq4 := ln_sq4 - LEAST(1, ln_sq4);
    END IF;
   END LOOP;

   FOR i IN 1 .. ln_tmp LOOP                                                                                                                 --теперь записываем
    ld_date := ad_date - 1 / ln_cnprf + i /(ln_cnprf * ln_tmp);

    IF util_pg.newhalfhour_f = 1 AND util_pg.is_timeswitch(ld_date) = -1 THEN
     --Время перехода с лета на зиму (nsource=19,29)
     ln_source := comsrv_pg.cn_auto + 9;
    ELSE
     ln_source := comsrv_pg.cn_auto;
    END IF;

    ld_date := util_pg.to_localtime(ld_date);

    BEGIN
     INSERT INTO PROFILE
                 (mid, date_time, nsource, er, ed, q1, q2, q3, q4)
     VALUES      (an_mid, ld_date, ln_source, ln_ter(i), ln_ted(i), ln_tq1(i), ln_tq2(i), ln_tq3(i), ln_tq4(i));
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE PROFILE
      SET er = ln_ter(i),
          ed = ln_ted(i),
          q1 = ln_tq1(i),
          q2 = ln_tq2(i),
          q3 = ln_tq3(i),
          q4 = ln_tq4(i)
      WHERE  mid = an_mid AND date_time = ld_date AND nsource = ln_source;
    END;
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'das_pg.insert_hf_in_profile: ' || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Вычисяем Профиль по curr_power_arch
 PROCEDURE insert_cp_in_profile(an_mid NUMBER) IS
  ln_stepprofile      NUMBER;
  ln_rn      CONSTANT NUMBER := 5;
  ld_start            DATE;
  ld_end              DATE;
  ld_tmp              DATE;
  lt_ras              common_pg.tt_number;
  k1                  NUMBER;
  k2                  NUMBER;
 BEGIN
  --Если не ведем архив параметров сети то выходим
  IF NVL(util_pg.is_calc_profile_by_cp(an_mid), 0) <> 1 THEN
   RETURN;
  END IF;

  ln_stepprofile := util_pg.stepprofile_f;

  SELECT date_time, er, ed, q1, q2, q3, q4
  INTO   ld_end, lt_ras(7), lt_ras(8), lt_ras(9), lt_ras(10), lt_ras(11), lt_ras(12)
  FROM   curr_power
  WHERE  mid = an_mid;

  SELECT date_time, er, ed, q1, q2, q3, q4
  INTO   ld_start, lt_ras(1), lt_ras(2), lt_ras(3), lt_ras(4), lt_ras(5), lt_ras(6)
  FROM   curr_power_arch
  WHERE  mid = an_mid AND date_time = (SELECT MAX(date_time)
                                       FROM   curr_power_arch
                                       WHERE  mid = an_mid AND date_time < ld_end);

  ld_tmp := util_pg.ceil_d(ld_start + 1 / 86400, 60 * ln_stepprofile / 86400);

  WHILE ld_tmp <= ld_end LOOP
   IF (ld_tmp - ld_start) < 60 * ln_stepprofile / 86400 THEN
    k1 := (ld_tmp - ld_start) * 24;
   ELSE
    k1 := 0;
   END IF;

   k2 := (60 * ln_stepprofile / 86400) * 24 - k1;

   BEGIN
    INSERT INTO PROFILE
                (mid, date_time, er, ed, q1, q2, q3, q4)
    VALUES      (an_mid, ld_tmp, ROUND(k1 * lt_ras(1) + k2 * lt_ras(7), ln_rn), ROUND(k1 * lt_ras(2) + k2 * lt_ras(8), ln_rn),
                 ROUND(k1 * lt_ras(3) + k2 * lt_ras(9), ln_rn), ROUND(k1 * lt_ras(4) + k2 * lt_ras(10), ln_rn), ROUND(k1 * lt_ras(5) + k2 * lt_ras(11), ln_rn),
                 ROUND(k1 * lt_ras(6) + k2 * lt_ras(12), ln_rn));
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     UPDATE PROFILE
     SET er = ROUND(k1 * lt_ras(1) + k2 * lt_ras(7), ln_rn),
         ed = ROUND(k1 * lt_ras(2) + k2 * lt_ras(8), ln_rn),
         q1 = ROUND(k1 * lt_ras(3) + k2 * lt_ras(9), ln_rn),
         q2 = ROUND(k1 * lt_ras(4) + k2 * lt_ras(10), ln_rn),
         q3 = ROUND(k1 * lt_ras(5) + k2 * lt_ras(11), ln_rn),
         q4 = ROUND(k1 * lt_ras(6) + k2 * lt_ras(12), ln_rn)
     WHERE  mid = an_mid AND date_time = ld_tmp;
   END;

   ld_tmp := ld_tmp + 60 * ln_stepprofile / 86400;
  END LOOP;
 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   NULL;
  WHEN OTHERS THEN
   raise_application_error(-20001, 'das_pg.insert_cp_in_profile: ' || SQLERRM(SQLCODE));
 END;

