 PROCEDURE ins_halfhourtmp(
 an_mid NUMBER, ad_date DATE, an_source NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_erm NUMBER,
 an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2, av_mtrsn VARCHAR2
 ) IS
  ln_source           NUMBER DEFAULT NVL(an_source, comsrv_pg.cn_auto);
 BEGIN
  DELETE FROM halfhourholes
  WHERE       mid = an_mid AND date_time = ad_date;

  INSERT INTO halfhourtmp
              (mid, date_time, nsource, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, status, nmetertype, vqm, er_mtrsn)
  VALUES      (an_mid, ad_date, ln_source, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_status, an_metertype,
               av_qm, av_mtrsn);
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   UPDATE halfhourtmp
   SET er = an_er,
       ed = an_ed,
       q1 = an_q1,
       q3 = an_q3,
       q2 = an_q2,
       q4 = an_q4,
       erm = an_erm,
       edm = an_edm,
       q1m = an_q1m,
       q3m = an_q3m,
       q2m = an_q2m,
       q4m = an_q4m,
       status = an_status,
       nmetertype = an_metertype,
       vqm = av_qm,
       er_mtrsn = av_mtrsn
   WHERE  mid = an_mid AND date_time = ad_date AND nsource = ln_source;
  WHEN OTHERS THEN
   raise_application_error(-20002, 'das_pg.ins_halfhourtmp: an_mid=' || an_mid || ' ' || SQLERRM(SQLCODE));
 END;

