 PROCEDURE ins_halfhourtmp_one_type(
 an_type NUMBER, an_mid NUMBER, ad_date DATE, an_source NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER,
 an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2, av_mtrsn VARCHAR2
 ) IS
  -- added by KAG 12.11.2008
  ln_source           NUMBER DEFAULT NVL(an_source, comsrv_pg.cn_auto);
 BEGIN
  INSERT INTO halfhourtmp
              (mid, date_time, nsource, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, status, nmetertype, vqm, er_mtrsn)
  VALUES      (an_mid, ad_date, ln_source, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, NULL, NULL, NULL, NULL, NULL, NULL, an_status, an_metertype, av_qm,
               av_mtrsn);
