    WHERE  mid = an_mid AND date_time = ad_date AND nsource = ln_source;
   ELSIF an_type = 2 THEN
    UPDATE halfhourtmp
    SET ed = an_ed,
        q2 = an_q2,
        q4 = an_q4,
        erm = NULL,
        edm = NULL,
        q1m = NULL,
        q3m = NULL,
        q2m = NULL,
        q4m = NULL,
        status = an_status,
        nmetertype = an_metertype,
        vqm = av_qm,
        er_mtrsn = av_mtrsn
    WHERE  mid = an_mid AND date_time = ad_date AND nsource = ln_source;
   ELSIF an_type = 3 THEN
    UPDATE halfhourtmp
    SET q1 = an_q1,
        q2 = an_q2,
        q4 = an_q4,
        erm = NULL,
        edm = NULL,
        q1m = NULL,
        q3m = NULL,
        q2m = NULL,
        q4m = NULL,
        status = an_status,
        nmetertype = an_metertype,
        vqm = av_qm,
        er_mtrsn = av_mtrsn
    WHERE  mid = an_mid AND date_time = ad_date AND nsource = ln_source;
   ELSIF an_type = 4 THEN
    UPDATE halfhourtmp
    SET q3 = an_q3,
        q2 = an_q2,
        q4 = an_q4,
        erm = NULL,
        edm = NULL,
        q1m = NULL,
        q3m = NULL,
        q2m = NULL,
        q4m = NULL,
        status = an_status,
        nmetertype = an_metertype,
        vqm = av_qm,
        er_mtrsn = av_mtrsn
    WHERE  mid = an_mid AND date_time = ad_date AND nsource = ln_source;
   END IF;
  WHEN OTHERS THEN
   raise_application_error(-20002, 'das_pg.ins_halfhourtmp_one_type: an_mid=' || an_mid || ' ' || SQLERRM(SQLCODE));
 END;

