 PROCEDURE copyswitches IS
  cn_shiftdat CONSTANT NUMBER := 1;
  ld_transmin         DATE DEFAULT comsrvdll_pg.cd_transmin;
  ln_tmp              NUMBER;
  ld_min              DATE;
  lb_possible         BOOLEAN;
 BEGIN
  FOR lc1 IN (SELECT   nswitch nswitch, MIN(mid) mid
              FROM     switchessrv
              GROUP BY nswitch
              ORDER BY 1) LOOP
   IF admin_pg.lock_p(cn_lock, 'switchessrv') <> 1 THEN
    RETURN;
   END IF;

   IF lc1.mid = comsrvdll_pg.cn_idnoswitch THEN                                                                               --Если нет данных то удаляем у нас
    FOR lc IN (SELECT   ID
               FROM     switches
               WHERE    nswitch = lc1.nswitch AND dswitch > ld_transmin
               ORDER BY dswitch DESC) LOOP
     switches_pg.del_p(lc.ID);
    END LOOP;
   ELSE
    --Делаем временную
    DELETE FROM switchessrvp;

    INSERT INTO switchessrvp
                (dswitch, descape, mid)
     SELECT dswitch, (SELECT     MAX(descape)
                      FROM       switchessrv
                      CONNECT BY dswitch <= PRIOR NVL(descape, comsrvdll_pg.cd_transnull) AND dswitch > PRIOR dswitch AND nswitch = lc1.nswitch
                      START WITH dswitch = t.dswitch AND nswitch = lc1.nswitch) descape, util_pg.getsupplypoint(mid) mid
     FROM   switchessrv t
     WHERE  nswitch = lc1.nswitch AND NOT EXISTS(SELECT *
                                                 FROM   switchessrv
                                                 WHERE  dswitch < t.dswitch AND NVL(descape, comsrvdll_pg.cd_transnull) >= t.dswitch AND nswitch = lc1.nswitch);

    --Удаляем лишнее
    FOR lc IN (SELECT   dswitch, descape, mid
               FROM     switches
               WHERE    nswitch = lc1.nswitch AND dswitch > ld_transmin + cn_shiftdat
               MINUS
               SELECT   dswitch, descape, mid
               FROM     switchessrvp
               ORDER BY 1) LOOP
     FOR lc2 IN (SELECT ID
                 FROM   switches
                 WHERE  nswitch = lc1.nswitch AND mid = lc.mid AND dswitch = lc.dswitch) LOOP
      switches_pg.del_p(lc2.ID);
     END LOOP;
    END LOOP;

    --Добавляем новое
    FOR lc IN (SELECT   dswitch, descape, mid
               FROM     switchessrvp
               MINUS
               SELECT   dswitch, descape, mid
               FROM     switches
               WHERE    nswitch = lc1.nswitch
               ORDER BY 1) LOOP
     BEGIN
--     savepoint sp_insupd_sw;
      switches_pg.ins_p(lc1.nswitch, lc.dswitch, lc.descape, lc.mid, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ln_tmp);
     EXCEPTION
      WHEN OTHERS THEN
       NULL;
     --   rollback to savepoint sp_insupd_sw;
     END;
    END LOOP;
   END IF;

   DELETE FROM switchessrv
   WHERE       nswitch = lc1.nswitch;

   COMMIT;
  END LOOP;

  DELETE FROM switchessrvp;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;
-----------------------------------------------------------------------------------------------------------------------
END;
/


