 -- added by KAG 12.03.2010
 -- если задать an_curline то проход по файлу будет до следующего признака точки
 PROCEDURE import_elvin (an_mid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2, an_curline NUMBER) IS
  cn_cnt    CONSTANT NUMBER          DEFAULT 24;
  cn_cnt2   CONSTANT NUMBER          DEFAULT 48;
  ln_str             NUMBER          DEFAULT 0;
  ln_col             NUMBER          DEFAULT 0;
  lv_separator       VARCHAR2 (8)    DEFAULT '|';
  lv_separator1      VARCHAR2 (8)    DEFAULT ' ';
  ln_rn              NUMBER          DEFAULT 3;
  ln_count           NUMBER          DEFAULT at_data.COUNT;
  lv_ret             VARCHAR2 (4000);
  lv_tmp             VARCHAR2 (4000);
  ln_mid             NUMBER          DEFAULT an_mid;
  ln_tmp             NUMBER;
  ld_max             DATE;
  ld_date            DATE;
  ln_kc              NUMBER;
  ln_er              NUMBER;
  ln_ed              NUMBER;
  ln_q1              NUMBER;
  ln_q3              NUMBER;
  ln_factcnt         NUMBER;
  ln_shift           NUMBER;
  lv_date            VARCHAR2 (32);
  lv_t2              VARCHAR2 (32);
  f_dayswitch        NUMBER;
  ln_from            NUMBER;
 BEGIN
  SELECT NVL (MAX (kc), 1)
    INTO ln_kc
    FROM feeders
   WHERE mid = ln_mid;

  IF an_curline = -1 THEN
   ln_from := 1;
  ELSE
   ln_from := an_curline + 1;
  END IF;

  --Бегаем по файлу
  FOR i IN ln_from .. ln_count LOOP
   IF an_curline <> -1 AND at_data (i) LIKE '%ID=%' THEN   -- ходим по файлу до новой точки
    das_pg.checkhalfhour;
    RETURN;
   END IF;

   IF at_data (i) LIKE '____/__/__%' THEN   -- новая дата
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator1));
    lv_date := REPLACE (lv_tmp, '/');
    f_dayswitch := util_pg.is_dayswitch (TO_DATE (lv_date, 'YYYYMMDD'));   -- (-1, 1, 0)
   END IF;

   IF at_data (i) LIKE '%__:__ .. __:__%' THEN   -- новая получасовка
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));
    lv_t2 := SUBSTR (lv_tmp, LENGTH (lv_tmp) - 4);
    ln_shift := 0;

    IF f_dayswitch = -1 THEN
     IF TO_NUMBER (REPLACE (lv_t2, ':')) > util_pg.switch_f * 100 THEN
      ln_shift := -1;
     END IF;
    ELSIF f_dayswitch = 1 THEN
     IF TO_NUMBER (REPLACE (lv_t2, ':')) > util_pg.switch_f * 100 THEN
      ln_shift := 1;
     END IF;
    END IF;

    IF lv_t2 = '24:00' THEN
     ld_date := TO_DATE (lv_date, 'YYYYMMDD') + 1;
    ELSIF lv_t2 = '24:30' THEN
     ld_date := TO_DATE (lv_date || ' 00:30', 'YYYYMMDD HH24:MI') + 1;
    ELSIF lv_t2 = '25:00' THEN
     ld_date := TO_DATE (lv_date || ' 01:00', 'YYYYMMDD HH24:MI') + 1;
    ELSE
     ld_date := TO_DATE (lv_date || ' ' || lv_t2, 'YYYYMMDD HH24:MI');
    END IF;

    ln_ed := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 4, lv_separator))) * ln_kc / 1000;
    ln_er := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 5, lv_separator))) * ln_kc / 1000;
    ln_q3 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 6, lv_separator))) * ln_kc / 1000;
    ln_q1 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 7, lv_separator))) * ln_kc / 1000;
    das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime (ld_date) + ln_shift / 24, util_pg.cn_manualinput, TRUNC (ln_er / 2, ln_rn),
                            TRUNC (ln_ed / 2, ln_rn), TRUNC (ln_q1 / 2, ln_rn), TRUNC (ln_q3 / 2, ln_rn), NULL, NULL, NULL, comsrv_pg.cn_elvin, NULL);
   /*das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime (ld_date) + ln_shift / 24, comsrv_pg.cn_auto,
                           TRUNC (ln_er / 2, ln_rn), TRUNC (ln_ed / 2, ln_rn),
                           TRUNC (ln_q1 / 2, ln_rn), TRUNC (ln_q3 / 2, ln_rn), NULL, NULL,
                           NULL, comsrv_pg.cn_elvin, NULL);    */
   END IF;
  END LOOP;   --FOR i IN 1 .. ln_count

  das_pg.checkhalfhour;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'DATA_IMPORT_PG.import_elvin: ' || 'Ошибка загрузки данных ' || SQLERRM (SQLCODE));
 END;   -- import_elvin

