 -- added by KAG 22.03.2010
 PROCEDURE import_mercury (an_mid NUMBER, at_data common_pg.tt_varchar2) IS
  cn_cnt   CONSTANT NUMBER                DEFAULT 48;
  ln_str            NUMBER                DEFAULT 0;
  ln_col            NUMBER                DEFAULT 0;
  lv_separator      VARCHAR2 (8)          DEFAULT ';';
  ln_count          NUMBER                DEFAULT at_data.COUNT - 1;
  ln_start          NUMBER                DEFAULT 1;
  ln_end            NUMBER                DEFAULT 1;
  ln_rn             NUMBER                DEFAULT 3;
  lv_ret            VARCHAR2 (4000);
  lv_tmp            VARCHAR2 (4000);
  lv_tmp2           VARCHAR2 (4000);
  lv_point          VARCHAR2 (4000);
  ln_mid            NUMBER;
  ln_cnt            NUMBER                DEFAULT 0;
  ld_date           DATE;
  ld_max            DATE;
  lt_e              common_pg.tt_number;
  ln_type           NUMBER;
  ln_factcnt        NUMBER;
  ln_block          NUMBER;
  ln_koeff          NUMBER                DEFAULT 1;
  lt_m              common_pg.tt_varchar2;
  ln_kс             NUMBER                DEFAULT 1;   -- коэффициент трансформации точки
  ld_mind           DATE;   -- минимальная дата в файле
  ld_maxd           DATE;   -- максимальная дата в файле
  ld_curd           DATE;   -- текущая дата обработки
  ln_metcnt         NUMBER;   -- формирует кол-во показаний в файле (1-тогда 48, 1/2-тогда 24)
  ln_metcntcur      NUMBER;   -- кол-во показаний для одной точки за одну дату
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM (at_data (i)) LIKE '< REC=POINT;%') THEN
    ln_start := i;
    EXIT;
   END IF;
  END LOOP;

  FOR i IN REVERSE 1 .. at_data.COUNT LOOP
   IF (TRIM (at_data (i)) LIKE '%; >%') THEN   -- пока допускаем символы после '; >'
    ln_end := i;
    EXIT;
   END IF;
  END LOOP;

  IF (ln_start < 2) THEN
   raise_application_error (-20001, 'Некорректное начало файла.');
  END IF;

  IF (ln_end <= ln_start) THEN
   raise_application_error (-20001, 'Не найден конец файла.');
  END IF;

  -- чтение КТР для точки
  SELECT NVL (MAX (f.kc), 1)
    INTO ln_kс
    FROM feeders f
   WHERE f.mid = an_mid;

  --Пробегаемся по файлу и выписываем все ид точек
  FOR i IN ln_start .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);

   IF lv_ret LIKE '< REC=POINT;%' THEN
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));

    IF SUBSTR (lv_tmp, 1, 6) <> 'COUNT=' THEN
     raise_application_error (-20001, 'Отсутствует признак серийного номера счетчика.');
    END IF;

    --получаем код точки
    lv_point := SUBSTR (lv_tmp, 7);
   /*IF TRIM (lv_point) IS NULL THEN
    raise_application_error (-20001, 'Серийный номер счетчика не указан.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_cnt, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM meters
                   WHERE mtrsn = lv_point) AND mid = an_mid;

   IF ln_cnt <> 1 THEN
    raise_application_error (-20001, 'Для точки загрузки не найден указанный в файле счетчик с номером '||lv_point);
   END IF;*/
   ELSIF lv_ret LIKE '< REC=DAY;%' THEN   -- здесь ищем мин и макс дату в файле
    ld_date := TO_DATE (REPLACE (TRIM (util_pg.get_param (lv_ret, 2, lv_separator)), 'DATE='), 'YYMMDD');

    IF ld_mind > ld_date OR ld_mind IS NULL THEN
     ld_mind := ld_date;
    END IF;

    IF ld_maxd < ld_date OR ld_maxd IS NULL THEN
     ld_maxd := ld_date;
    END IF;
   END IF;
  END LOOP;

-------------
  ld_curd := ld_mind;

  WHILE ld_curd >= ld_mind AND ld_curd <= ld_maxd LOOP   -- цикл по всем датам в файле
   ln_factcnt := cn_cnt;   -- данные летом приходят по зимнему времени (счетчик не переходит на лето)

   --ln_factcnt := util_pg.get_count_dt (ld_curd, 1 / cn_cnt);

   --Очистили
   FOR i IN 1 .. ln_factcnt * 4 LOOP
    lt_e (i) := NULL;
    lt_m (i) := NULL;   -- статусы передаваемых значений данных
   END LOOP;

   ln_metcntcur := 0;

   --Поискали нужные строки
   FOR i IN ln_start .. ln_end LOOP   -- цикл по всем строчкам в файле
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));

    IF lv_ret LIKE '< REC=POINT;%' THEN
     -- получаем тип энерегии точки
     lv_tmp := TRIM (util_pg.get_param (lv_ret, 3, lv_separator));
     ln_col := INSTR (lv_ret, '=', 1, 3);

     IF INSTR (lv_tmp, 'ID') <> 0 THEN
      lv_tmp := TRIM (RTRIM (util_pg.get_param (lv_tmp, 2, '='), '>'));

      IF lv_tmp = 'A+' THEN
       ln_type := 1;
      ELSIF lv_tmp = 'A-' THEN
       ln_type := 2;
      ELSIF lv_tmp = 'R+' THEN
       ln_type := 3;
      ELSIF lv_tmp = 'R-' THEN
       ln_type := 4;
      ELSE
       raise_application_error (-20001, 'Для счетчика с номером ' || lv_point || ' не задан тип энергии!');
      END IF;
     END IF;
    ELSIF lv_ret LIKE '< REC=DAY;%' THEN
     ld_date := TO_DATE (REPLACE (TRIM (util_pg.get_param (lv_ret, 2, lv_separator)), 'DATE='), 'YYMMDD');

     IF ld_date = ld_curd THEN
      ln_factcnt := cn_cnt;   -- данные летом приходят по зимнему времени (счетчик не переходит на лето)
      --ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);
      ld_max := ld_date - 1;   --Обнулили макс дату
      ln_koeff := 1;   -- коэффициент кВт/МВт м.б. 1000

      IF INSTR (lv_ret, 'P48=') <> 0 THEN   -- это 48 получасовок мощности
       ln_koeff := ln_koeff / 2;
       ln_metcnt := 1;
       lv_tmp := TRIM (REPLACE (util_pg.get_param (lv_ret, 3, lv_separator), 'P48='));   -- получение данных
       lv_tmp2 := TRIM (REPLACE (util_pg.get_param (lv_ret, 4, lv_separator), 'ST48='));   -- получение меток данных
      ELSIF INSTR (lv_ret, 'E48=') <> 0 THEN   -- это 48 получасовок энергии
       ln_metcnt := 1;
       lv_tmp := TRIM (REPLACE (util_pg.get_param (lv_ret, 3, lv_separator), 'E48='));   -- получение данных
       lv_tmp2 := TRIM (REPLACE (util_pg.get_param (lv_ret, 4, lv_separator), 'ST48='));   -- получение меток данных
      ELSIF INSTR (lv_ret, 'P24=') <> 0 THEN   -- это 24 часовок мощности
       ln_metcnt := 1 / 2;
       lv_tmp := TRIM (REPLACE (util_pg.get_param (lv_ret, 3, lv_separator), 'P24='));   -- получение данных
       lv_tmp2 := TRIM (REPLACE (util_pg.get_param (lv_ret, 4, lv_separator), 'ST24='));   -- получение меток данных
      ELSIF INSTR (lv_ret, 'E24=') <> 0 THEN   -- это 24 часовок энергии
       ln_metcnt := 1 / 2;
       lv_tmp := TRIM (REPLACE (util_pg.get_param (lv_ret, 3, lv_separator), 'E24='));   -- получение данных
       lv_tmp2 := TRIM (REPLACE (util_pg.get_param (lv_ret, 4, lv_separator), 'ST24='));   -- получение меток данных
      END IF;

      IF ln_metcntcur = 0 THEN
       ln_metcntcur := ln_metcnt;
      ELSIF ln_metcntcur <> ln_metcnt THEN
       raise_application_error (-20001, 'Для одной точки учета за одну и ту же дату имеются одновременно показания с разными периодами интеграции!');
      END IF;

      ln_col := INSTR (lv_ret, '=', 1, 3);

      FOR j IN 1 .. ln_factcnt * ln_metcnt LOOP   -- чтение данных
       lt_e (ln_factcnt * ln_metcnt * (ln_type - 1) + j) := util_pg.get_param (lv_tmp, j, ',') * ln_koeff * ln_kс;   -- переводим в кВт*ч с учетом КТР

       IF lt_e (ln_factcnt * ln_metcnt * (ln_type - 1) + j) IS NOT NULL THEN
        ld_max := ld_curd - 1 / 24 + j / (cn_cnt * ln_metcnt);
       END IF;

       ln_col := ln_col + NVL (LENGTH (lt_e (ln_factcnt * ln_metcnt * (ln_type - 1) + j)), 0) + 1;   -- +1 - длина запятой-разделителя
      END LOOP;

      ln_col := INSTR (lv_ret, '=', 1, 4);

      FOR j IN 1 .. ln_factcnt * ln_metcnt LOOP   -- чтение меток данных
       lt_m (ln_factcnt * ln_metcnt * (ln_type - 1) + j) := util_pg.get_param (lv_tmp2, j, ',');
       ln_col := ln_col + NVL (LENGTH (lt_m (ln_factcnt * ln_metcnt * (ln_type - 1) + j)), 0) + 1;   -- +1 - длина запятой-разделителя
      END LOOP;
     END IF;   -- ld_date=ld_curd
    END IF;   -- POINT/DATE
   END LOOP;   -- цикл по всем строчкам файла

   ----- разбиваем часовки на получасовки
   IF ln_metcnt = 1 / 2 THEN
    -- показания
    FOR i IN REVERSE 1 .. ln_factcnt * ln_metcnt * 4 LOOP
     lt_e (2 * i) := TRUNC (lt_e (i) / 2, 0);
     lt_e (2 * i - 1) := lt_e (i) - lt_e (2 * i);
    END LOOP;

    -- метки
    FOR i IN REVERSE 1 .. ln_factcnt * ln_metcnt * 4 LOOP
     lt_m (2 * i) := lt_m (i);
     lt_m (2 * i - 1) := lt_m (i);
    END LOOP;
   END IF;

   -- делаем insert в бд для текущей точки
   ld_date := ld_curd;

   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
     --comsrv_pg.set_halfhour_mercury (an_mid, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), lt_e (3 * ln_factcnt + j), NULL, NULL, ld_date + j / cn_cnt);
     util_pg.chdr (an_mid, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), lt_e (3 * ln_factcnt + j));
     das_pg.ins_halfhourtmp (an_mid, ld_date + j / cn_cnt, util_pg.cn_manualinput, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                             lt_e (3 * ln_factcnt + j), NULL, NULL, NULL, comsrv_pg.cn_mercury, NULL);
    END IF;
   END LOOP;

   IF util_pg.get_customer_id NOT IN (1) AND ld_max > ld_date THEN
    admin_pg.ins_last_save (an_mid);

    UPDATE last_save
       SET halfhour = ld_max,
           state_date = SYSDATE,
           state_cod = 0,
           clock = 0
     WHERE mid = an_mid;
   END IF;

   ld_curd := ld_curd + 1;
  END LOOP;   --- цикл по всем датам в файле

----------------
  das_pg.checkhalfhour;

  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001,
                            'data_import_pg.import_mercury: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || ')' || CHR (10)
                            || SQLERRM (SQLCODE));
 END;

-------------------------------------------------------------------------------------------
 -- added by KAG 19.03.2009
 PROCEDURE l_lg (an_cid NUMBER, ac_file IN OUT CLOB) IS
  cn_headerl   CONSTANT NUMBER                DEFAULT 73;   -- длина заголовка блока
  cn_footerl   CONSTANT NUMBER                DEFAULT 23;   -- длина концевика блока
  cn_tariffl   CONSTANT NUMBER                DEFAULT 1;   -- длина тарифа
  cn_statel    CONSTANT NUMBER                DEFAULT 2;   -- длина состояния
  ln_cnt                NUMBER                DEFAULT 48;   -- Количество интегральных периодов
  ln_rn                 NUMBER                DEFAULT 3;   -- точность
  ln_str                NUMBER                DEFAULT 0;
  ln_col                NUMBER                DEFAULT 0;
  ln_count              NUMBER;   -- число строк в файле
  lv_ret                VARCHAR2 (4000);   -- обрабатываемая строка(блок) файла
  lv_tmp                VARCHAR2 (4000);
  ln_mid                NUMBER;
  ln_tmp                NUMBER;
  ln_block              NUMBER;
  ld_date               DATE;
  ld_max                DATE;
  ln_dim                NUMBER;   -- Размерность данных в файле
  ln_koeff              NUMBER;
  ln_type               NUMBER;
  ln_reverse            NUMBER;
  ln_shift              NUMBER;
  lt_e                  common_pg.tt_number;
  ln_sum                NUMBER;
  ln_factcnt            NUMBER;
  ln_from               NUMBER;
  ln_to                 NUMBER;
  ld_mind               DATE;   -- минимальная дата в файле
  ld_maxd               DATE;   -- максимальная дата в файле
  ld_curd               DATE;   -- текущая дата обработки
  lt_data               common_pg.tt_varchar2;
  ln_offset             NUMBER;
  ln_chars              NUMBER;   -- длина строки разбивки
  ln_flehgth            NUMBER;   -- длина clob файла
  lb_makeins            BOOLEAN;   -- делать вставку для текущей точки на текущую дату
 BEGIN
  -- разбивка файла
  ln_offset := 1;
  ln_flehgth := DBMS_LOB.getlength (ac_file);
  ln_str := 1;

  WHILE ln_flehgth - ln_offset > cn_headerl LOOP   -- ходим, пока есть еще блоки данных
   ln_chars := cn_headerl;
   DBMS_LOB.READ (ac_file, ln_chars, ln_offset, lv_tmp);   -- читаем заголовок блока
   ln_col := 19;
   ln_dim := TO_NUMBER (SUBSTR (lv_tmp, 19, 21 - 19));   -- размерность
   ln_col := 37;
   ln_cnt := TO_NUMBER (SUBSTR (lv_tmp, 37, 43 - 37));   -- Количество интегральных периодов
   ln_chars := cn_headerl + ln_cnt * (ln_dim + cn_tariffl + cn_statel) + cn_footerl;   -- считаем длину блока
   DBMS_LOB.READ (ac_file, ln_chars, ln_offset, lt_data (ln_str));   -- теперь читаем весь блок целиком
   ln_tmp := INSTR (lt_data (ln_str), CHR (12));   -- признак конца блока

   IF ln_tmp = 0 THEN
    raise_application_error (-20001, 'Не найден признак конца блока номер ' || ln_str || ' на позиции ' || ln_chars);
   ELSIF ln_tmp <> 0 AND ln_tmp < ln_chars THEN
    raise_application_error (-20001, 'Обнаружен неожиданный признак конца блока на позиции: строка=' || ln_str || ', столбец=' || ln_tmp || '. ');
   END IF;

   ln_offset := ln_offset + ln_chars;
   ln_str := ln_str + 1;
  END LOOP;

  ln_count := lt_data.COUNT;
  ln_tmp := 0;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 1 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := lt_data (i);
   lv_tmp := SUBSTR (lv_ret, 11, 19 - 11);

   IF lv_tmp IS NULL THEN
    raise_application_error (-20001, 'Код точки не указан или указан не верно.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder
                )
         VALUES (ln_mid
                );
   END IF;

   -- ищем минимальную и максимальную дату в файле
   ld_date := TO_DATE (SUBSTR (lv_ret, 23, 33 - 23), 'yymmddhh24mi');

   IF ld_mind > ld_date OR ld_mind IS NULL THEN
    ld_mind := ld_date;
   END IF;

   IF ld_maxd < ld_date OR ld_maxd IS NULL THEN
    ld_maxd := ld_date;
   END IF;
  END LOOP;

----------
  ld_curd := ld_mind;

  WHILE ld_curd >= ld_mind AND ld_curd <= ld_maxd LOOP   -- цикл по всем датам в файле
   FOR lc IN (SELECT DISTINCT norder mid
                         FROM textreport) LOOP   -- цикл по точкам загрузки
    --Очистили
    FOR i IN 1 .. ln_cnt * 4 LOOP   -- 4 - кол-во показаний (А+,A-,R+,R-)
     lt_e (i) := NULL;
    END LOOP;

    lb_makeins := FALSE;

    --ищем нужные строки
    FOR i IN 1 .. ln_count LOOP   -- s цикл по строчкам
     ln_str := i;
     lv_ret := lt_data (i);
     ln_col := 11;   -- Условный код RTU
     lv_tmp := SUBSTR (lv_ret, 11, 19 - 11);

     --Проверяем что это нужная строка
     SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp))
       INTO ln_tmp, ln_type
       FROM feeders
      WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

     IF ln_tmp = 1 THEN
      lv_tmp := SUBSTR (lv_ret, 23, 33 - 23);   -- Дата и время 1-го значения данных в формате: ГГММДДЧЧММ
      ld_date := (TO_DATE (lv_tmp, 'yymmddhh24mi'));

      IF ld_date = ld_curd THEN
       lb_makeins := TRUE;
       ln_col := 19;
       ln_dim := TO_NUMBER (SUBSTR (lv_ret, 19, 21 - 19));   -- размерность
       ln_col := 37;
       ln_cnt := TO_NUMBER (SUBSTR (lv_ret, 37, 43 - 37));   -- Количество интегральных периодов
       ln_factcnt := ln_cnt;   -- пока считаем, что перехода на лето нет и всегда ln_factcnt = ln_cnt

       IF ln_cnt = 48 AND TO_NUMBER (SUBSTR (lv_ret, 21, 23 - 21)) = 3 THEN   -- если у нас мощность за получасовки, то переводим их в энергию
        ln_koeff := 1 / 2;
       ELSE
        ln_koeff := 1;
       END IF;

       ld_date := ld_curd - 1 / ln_cnt + 1 / 24;   -- отнимаем период первого измерения и приводим Европу зимой в Украину зимой
       ld_max := ld_date - 1;   -- обнуляем max дату

       IF LENGTH (lv_ret) <> cn_headerl + ln_cnt * (ln_dim + cn_tariffl + cn_statel) + cn_footerl THEN
        raise_application_error (-20001,
                                 'Длина блока данных номер ' || ln_str || ' имеет неправильную длину. Должна быть ' || cn_headerl
                                 + ln_cnt * (ln_dim + cn_tariffl + cn_statel) + cn_footerl);
       END IF;

       ln_sum := 0;   -- контрольная сумма

       FOR i IN 1 .. ln_factcnt LOOP
        ln_from := cn_headerl + (i - 1) * (ln_dim + cn_tariffl + cn_statel);
        ln_col := ln_from;
        ln_to := ln_from + ln_dim;
        lv_tmp := SUBSTR (lv_ret, ln_from, ln_to - ln_from);
        lt_e (ln_factcnt * (ln_type - 1) + i) := TO_NUMBER (lv_tmp) * ln_koeff;   -- заполняем массив значениями

        IF lt_e (ln_factcnt * (ln_type - 1) + i) IS NOT NULL THEN
         ld_max := ld_date + i / ln_cnt;
         ln_sum := ln_sum + lt_e (ln_factcnt * (ln_type - 1) + i);
        END IF;
       END LOOP;

       ln_from := ln_to + cn_tariffl + cn_statel;

       IF ln_sum <> TO_NUMBER (SUBSTR (lv_ret, ln_from, 12)) * ln_koeff THEN   -- сверка с контрольной суммой
        raise_application_error (-20001,
                                 'Контрольная сумма для блока данных номер ' || ln_str || ' не совпадает: ' || 'вычисленная=' || TO_NUMBER (ln_sum) || '; из файла='
                                 || TO_NUMBER (SUBSTR (lv_ret, ln_from, 12)) * ln_koeff);
       END IF;
      END IF;   -- ld_date=ld_curd
     END IF;   -- ln_tmp = 1
    END LOOP;   -- e цикл по строчкам

    -- делаем insert в бд для текущей точки, если для текущей точки на текущую дату была найдена хоть одна строчка в файле
    IF lb_makeins THEN
     ld_date := ld_curd - 1 / ln_cnt + 1 / 24;   -- отнимаем период первого измерения и приводим Европу зимой в Украину зимой

     SELECT NVL (MAX (ed_position), 0)
       INTO ln_reverse
       FROM feeders
      WHERE mid = lc.mid;

     FOR j IN 1 .. ln_factcnt LOOP
      --Если есть цифры
      IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
       IF ln_factcnt > ln_cnt AND j > (ln_cnt / 24) * (util_pg.switch_f + 1) AND j <= ln_cnt THEN   --больше времени сдвига добавяем час
        ln_shift := 1 / 24;
       ELSIF j > ln_cnt THEN
        ln_shift := -1 + (util_pg.switch_f + 1) / 24;
       ELSE
        ln_shift := 0;
       END IF;

       IF util_pg.get_customer_id IN (1) AND ln_reverse > 0 THEN
        util_pg.chdr (lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), lt_e (3 * ln_factcnt + j));
       END IF;

       /*das_pg.insert_hf_in_profile (lc.mid, util_pg.to_unlocaltime (ld_date) + j / ln_cnt + ln_shift, 24 * 60 / ln_cnt, lt_e (j), lt_e (1 * ln_factcnt + j),
                                    lt_e (2 * ln_factcnt + j), NULL, lt_e (3 * ln_factcnt + j), NULL, ln_rn);
       inshalfhour (lc.mid, util_pg.to_unlocaltime (ld_date) + j / ln_cnt + ln_shift, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                    lt_e (3 * ln_factcnt + j));*/
       -- лето к зиме не надо приводить, так как данные и так всегда передаются по зиме
       das_pg.insert_hf_in_profile (lc.mid, ld_date + j / ln_cnt + ln_shift, 24 * 60 / ln_cnt, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), NULL,
                                    lt_e (3 * ln_factcnt + j), NULL, ln_rn);
       das_pg.ins_halfhourtmp (lc.mid, ld_date + j / ln_cnt + ln_shift, comsrv_pg.cn_auto, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                               lt_e (3 * ln_factcnt + j), NULL, NULL, NULL, comsrv_pg.cn_maket, NULL);
      END IF;
     END LOOP;

     IF util_pg.get_customer_id NOT IN (1) AND ld_max > ld_date THEN
      admin_pg.ins_last_save (lc.mid);

      UPDATE last_save
         SET halfhour = ld_max,
             state_date = SYSDATE,
             state_cod = 0,
             clock = 0
       WHERE mid = lc.mid;
     END IF;
    END IF;   -- if lb_makeins
   END LOOP;   -- цикл по точкам загрузки

   ld_curd := ld_curd + 1;
  END LOOP;   -- цикл по всем датам в файле

----------------
  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_cid;

  DELETE FROM textreport;

  COMMIT;
  -- ручная загрузка
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001,
                            'comsrvfile_pg.l_LG: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || ')' || CHR (10) || SQLERRM (SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body DATA_IMPORT_PG
/


