        EXECUTE IMMEDIATE lv_sql;*/
        
         IF lv_setcolstrr IS NOT NULL THEN   
        
         EXECUTE IMMEDIATE'UPDATE RYDA.'||lv_testTablename||' R SET ('||lv_setcolstrr||') =
            (SELECT  '||lv_setcolstrk||' FROM RYDAARCH.'||lv_testTablename||' K 
                    WHERE ' ||lv_primarycol||')
            WHERE EXISTS 
             (SELECT  '||lv_setcolstrk||' FROM RYDAARCH.'||lv_testTablename||' K 
                    WHERE ' ||lv_primarycol||')';
                    
        --    insert into tmp_vil values (lv_sql); commit;          
                    
       END IF;    
      
         
        BEGIN 
          lv_sql:='INSERT INTO RYDA.'||lv_testTablename||' K ('||lv_colstrk||')
                   (SELECT ' ||lv_colstrr||' FROM RYDAARCH.'||lv_testTablename||' R
                    MINUS
                    SELECT ' ||lv_colstr||' FROM RYDA.'||lv_testTablename||' A )';
               --    insert into tmp_vil values (lv_sql); commit;
          EXECUTE IMMEDIATE lv_sql;
         EXCEPTION
         WHEN OTHERS 
         THEN 
            NULL;
         END; 
    
        
          
        
           EXECUTE IMMEDIATE 'DELETE FROM RYDA.'||lv_testTablename||' W
              WHERE (' ||lv_primarycolw||')IN
             (SELECT ' ||lv_primarycolr||' FROM RYDA.'||lv_testTablename||' R
                    MINUS
                    SELECT ' ||lv_primarycola||' FROM RYDAARCH.'||lv_testTablename||' A )';

      end if;

commit;
end;



-------------------------------------------------------------------------------------------------------------------------------
END;
/


