CREATE OR REPLACE 
PACKAGE BODY dbterm_pg IS
--------------------------------------------------------------------
-- пакет работы с таблицей DB_TERM
-- дата создания 10/02/2003 (Калак С.С.)
   gn_Task_Code NUMBER DEFAULT 21;
--------------------------------------------------------------------
  --Процедура обновления данных по параметрам хранения таблицы
  PROCEDURE upd_term(
     av_tablename   VARCHAR2,
     an_term        NUMBER,
     an_narchived   NUMBER,
     av_extension   VARCHAR2) IS
     lv_data_name   VARCHAR2(200);
  BEGIN
    SELECT data_name INTO lv_data_name FROM DB_TERM WHERE table_name = av_tablename;
    UPDATE DB_TERM
    SET term = an_term, narchived = an_narchived, vextention = av_extension
    WHERE table_name = av_tablename;
   admin_pg.fiscal_p(gn_Task_Code,2,'Изменены параметры хранения для '||lv_data_name);
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20001, 'DBTERM_PG.upd_term: Ошибка изменения параметров хранения таблиц. ' || CHR(10) || SQLERRM(SQLCODE));
  END;
---------------------------------------------------------------------
 PROCEDURE tree_read (acur_t OUT common_pg.tcur) IS
 -- используется в TFormControlVolueDB::TreeRead
 -- added 04.08.2008 Kondakov A.G.
 BEGIN
   OPEN acur_t FOR
      SELECT  data_name, table_name, term, narchived, vextention
       FROM  db_term
       ORDER BY 1;
 END;
---------------------------------------------------------------------
END; -- Package Body DBTERM_PG
/


