CREATE OR REPLACE 
PACKAGE BODY deportation_pg IS
------------------------------------------------------------------------------------------------------------------------
 -- пакет работы с каналами экспорта данных
 -- дата создания 26/07/2002 (Сечин А.А.)
 cn_task_code CONSTANT NUMBER DEFAULT 506;

------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p(
 av_name VARCHAR2,                                                                                                                                  -- Название
                  av_note VARCHAR2,                                                                                                               -- Примечание
                                   an_maket NUMBER,                                                                                                -- Ид макета
                                                   an_type NUMBER,                                                                               -- Тип отсылки
                                                                  av_address VARCHAR2,                                                                 -- Адрес
                                                                                      an_parent NUMBER,                                  -- Ид основного канала
                                                                                                       ad_from DATE,                              -- Отсылать с
                                                                                                                    ad_till DATE,                -- Отсылать по
 an_block NUMBER,                                                                                                                                 -- Блокировка
                 an_retries_tout NUMBER,                                                                                           -- Пауза между попытками мин
                                        an_retries NUMBER,                                                                                -- Количество попыток
                                                          av_param VARCHAR2,                                                               -- Параметры отсылки
                                                                            an_deportation OUT NUMBER,                                             -- Ид канала
                                                                                                      an_parent_mid NUMBER,                 -- Родительский мид
 an_isfolder NUMBER                                                                                                                            -- Признак папки
 ) IS
  ln_mid              NUMBER;
  lv_mname            VARCHAR2(200);
  ln_parent           NUMBER := NVL(an_parent_mid, 3);
 BEGIN
  SAVEPOINT deportation_ins;
  adminadd_pg.check_right(ln_mid, ln_parent, 1, 2);

  SELECT points_seq.NEXTVAL
  INTO   ln_mid
  FROM   DUAL;

  IF an_isfolder = 0 THEN                                                                                                                               --Канал
   INSERT INTO points
               (mid, PARENT, cod, ind, NAME, short_name, implement_date)
   VALUES      (ln_mid, ln_parent, 0, 2, av_name, '', SYSDATE);

   INSERT INTO deportation
               (ndeportation, vname, vnote, nmaket, ntype, vaddress, nparent, dfrom, dtill, nblock, nretries_tout, nretries, vparam)
   VALUES      (ln_mid, av_name, av_note, DECODE(an_parent, NULL, an_maket, NULL), an_type, av_address, an_parent, ad_from, ad_till, an_block, an_retries_tout,
                an_retries, TRIM(av_param));
  ELSE                                                                                                                                                   --Папка
   INSERT INTO points
               (mid, PARENT, cod, ind, NAME, short_name, implement_date, tag)
   VALUES      (ln_mid, NVL(an_parent_mid, 3), 0, 2, av_name, '', SYSDATE, an_block);
  END IF;

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = an_maket;

  admin_pg.fiscal_p(cn_task_code, 1, 'Добавлен канал отсылки ' || av_name || ' для макета ' || lv_mname);
  an_deportation := ln_mid;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT deportation_ins;
   raise_application_error(-20001, 'DEPORTATION_pg.ins_p: Ошибка добавления каналами экспорта. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   -- Процедура обновления
 PROCEDURE upd_p(
 an_deportation NUMBER,                                                                                                                             -- Ид канала
                       av_name VARCHAR2,                                                                                                             -- Название
                                        av_note VARCHAR2,                                                                                          -- Примечание
                                                         an_maket NUMBER,                                                                           -- Ид макета
                                                                         an_type NUMBER,                                                          -- Тип отсылки
                                                                                        av_address VARCHAR2,                                            -- Адрес
                                                                                                            an_parent NUMBER,             -- Ид основного канала
 ad_from DATE,                                                                                                                                     -- Отсылать с
              ad_till DATE,                                                                                                                       -- Отсылать по
                           an_block NUMBER,                                                                                                        -- Блокировка
                                           an_retries_tout NUMBER,                                                                  -- Пауза между попытками мин
                                                                  an_retries NUMBER,                                                       -- Количество попыток
                                                                                    av_param VARCHAR2,                                      -- Параметры отсылки
                                                                                                      an_parent_mid NUMBER,                  -- Родительский мид
 an_isfolder NUMBER                                                                                                                             -- Признак папки
 ) IS
  lv_mname            VARCHAR2(200);
  lv_oldname          VARCHAR2(200);
  ln_parent           NUMBER := NVL(an_parent_mid, 3);
 BEGIN
  SAVEPOINT deportation_upd;
  adminadd_pg.check_right(an_deportation, ln_parent, 1, 2);

  --   SELECT vname INTO lv_mName FROM makets WHERE nmaket = an_maket;
  IF an_isfolder = 0 THEN                                                                                                                               --Канал
   SELECT vname
   INTO   lv_oldname
   FROM   deportation
   WHERE  ndeportation = an_deportation;

   IF lv_oldname = av_name THEN
    lv_oldname := 'Изменены атрибуты канала отсылки ' || av_name || ' Адрес:' || av_address || ' Для макета ' || lv_mname;
   ELSE
    lv_oldname := 'Изменены атрибуты канала отсылки ' || lv_oldname || ' - ' || av_name || ' Адрес:' || av_address || ' Для макета ' || lv_mname;
   END IF;

   admin_pg.fiscal_p(cn_task_code, 2, lv_oldname);

   UPDATE points
   SET NAME = av_name,
       PARENT = ln_parent
   WHERE  mid = an_deportation;

   UPDATE deportation
   SET vname = av_name,
       vnote = av_note,
       nmaket = DECODE(an_parent, NULL, an_maket, NULL),
       ntype = an_type,
       vaddress = av_address,
       nparent = an_parent,
       dfrom = ad_from,
       dtill = ad_till,
       nblock = an_block,
       nretries_tout = an_retries_tout,
       nretries = an_retries,
       vparam = TRIM(av_param)
   WHERE  ndeportation = an_deportation;
  ELSE
   UPDATE points
   SET NAME = av_name,
       PARENT = NVL(an_parent_mid, 3),
       tag = an_block
   WHERE  mid = an_deportation;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT deportation_upd;
   raise_application_error(-20001, 'DEPORTATION_pg.upd_p: Ошибка обновления каналами экспорта. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p(an_deportation NUMBER                                                                                                               --Ид канала
                                      ) IS
  lv_oldname          VARCHAR2(200);
  l_exists            INTEGER;
 BEGIN
  SAVEPOINT deportation_del;
  adminadd_pg.check_right(an_deportation, NULL, 1, 2);

  SELECT COUNT(*)
  INTO   l_exists
  FROM   deportation
  WHERE  ndeportation = an_deportation;

  IF l_exists = 1 THEN
   SELECT vname
   INTO   lv_oldname
   FROM   deportation
   WHERE  ndeportation = an_deportation;

   lv_oldname := 'Удален канал отсылки ' || lv_oldname;
   admin_pg.fiscal_p(cn_task_code, 3, lv_oldname);

   UPDATE deportation
   SET nparent = NULL,
       nblock = 1
   WHERE  nparent = an_deportation;
  END IF;

  DELETE FROM points
  WHERE       mid = an_deportation;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT deportation_del;
   raise_application_error(-20001, 'DEPORTATION_pg.del_p: Ошибка удаления каналами экспорта. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
    -- Фиксации статуса отправки файла макета (используется в службе отправки макетов)
 PROCEDURE setdeportstatus_p(an_maindeportation NUMBER, an_deportation NUMBER, ad_date DATE, av_file VARCHAR2, an_state NUMBER, av_error VARCHAR2) IS
  ln_state            NUMBER;
  ld_sys              DATE DEFAULT SYSDATE;
  ln_send             NUMBER DEFAULT 0;
  lv_name             VARCHAR2(256);
 BEGIN
  admin_pg.ins_last_save(an_deportation, 'Отсылка не проводилась');

  UPDATE deportfiles
  SET nstate = an_state,
      verror = av_error,
      dsend = DECODE(NVL(an_state, 0), 1, ld_sys, NULL)
  WHERE  ndeportation = an_maindeportation AND ddate = ad_date;

  IF NVL(an_state, 0) <> 1 THEN                                                                                               --Если ошибка то пишем ln_state:=1
   ln_state := 1;
  ELSE
   ln_state := 0;
  END IF;

  FOR lc IN (SELECT DECODE(ln_state, 1, 6, ln_state) nstate,
                    DECODE(ln_state, 1, 'Нет связи по каналу. ' || av_error, 'Восстановлена связь по каналу ' || p.NAME) vstate
             FROM   last_save l, points p
             WHERE  l.mid = an_deportation AND NVL(l.state_cod, 0) <> ln_state AND l.mid = p.mid(+)) LOOP                          --Если прошла смена состояния
   admin_pg.journal_p(an_deportation, lc.nstate, lc.vstate);
   ln_send := 1;
  END LOOP;

  IF ln_state = 0 THEN                                                                                                               --Пишем что макет отправлен
   SELECT MAX(m.vname)
   INTO   lv_name
   FROM   deportation d, makets m
   WHERE  d.ndeportation = an_maindeportation AND d.nmaket = m.nmaket(+);

   admin_pg.journal_p(an_deportation, 0,
    'Отправлен макет: ''' || lv_name || ''' за ' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') || '. Файл:''' || av_file || '''.');
   ln_send := 1;
  END IF;

  UPDATE last_save
  SET state_date = DECODE(NVL(state_cod, 0), ln_state, state_date, ld_sys),
      state_cod = ln_state,
      state_descr = DECODE(ln_state, 1, SUBSTR(av_error, 1, 150), ' Штатный режим:  '),
      luck = DECODE(ln_state, 0, ld_sys, luck),
      fail = DECODE(ln_state, 1, ld_sys, fail),
      trial = ld_sys
  WHERE  mid = an_deportation;

  IF ln_send = 1 THEN                                                                                                              --Если что-то писали в журнал
   admin_pg.signal(6);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'DEPORTATION_pg.setdeportstatus_p: Ошибка фиксации состояния отправки файла. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
-- возвращает ветку дерева для каналов расслыки
 PROCEDURE getdepchannelstree(an_parent NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(8000);
  lv_sqladd           VARCHAR2(8000);
 BEGIN
  IF NVL(an_parent, 0) = 0 THEN
   IF adminadd_pg.check_accread(util_pg.cn_depmid) = 1 THEN                                                                          --Права на вершину каналов
    lv_sqladd := 'p.parent=' || util_pg.cn_depmid || ' AND';
   ELSE
    lv_sqladd := 'p.mid in (SELECT * FROM TABLE(adminadd_pg.getfirst_accmid(' || util_pg.cn_depmid || '))) AND';                                      --Вершина
   END IF;
  ELSE
   IF adminadd_pg.check_accread(an_parent) = 1 THEN
    lv_sqladd := 'p.parent=' || an_parent || ' AND';
   ELSE                                                                                                                                               --Нет Прав
    raise_application_error(-20002, 'В доступе отказано. an_id=' || an_parent);
   END IF;
  END IF;

  lv_sql :=
      'SELECT   0 havechild, 0 isfolder, p.mid, vname, vnote, nmaket, ntype, vaddress, nparent, TO_CHAR(dfrom, ''hh24:mi'') dfrom, TO_CHAR(dtill, ''hh24:mi'') dtill,
            nretries, nretries_tout, nblock, vparam
   FROM     deportation d, points p WHERE '
   || lv_sqladd
   || ' d.ndeportation = p.mid AND d.nmaket in (select * from table(adminadd_pg.getall_accmid))
   UNION ALL
   SELECT   1 havechild, 1 isfolder, p.mid, p.NAME vname, '''' vnote, NULL nmaket, NULL ntype, '''' vaddress, p.PARENT nparent, '''' dfrom, '''' dtill, NULL nretries,
            NULL nretries_tout, tag nblock, '''' vparam
   FROM     points p WHERE '
   || lv_sqladd
   || ' NOT EXISTS(SELECT 1 FROM   deportation WHERE  ndeportation = p.mid) AND EXISTS(SELECT 1 FROM   points WHERE  PARENT = p.mid)
   UNION ALL
   SELECT   0 havechild, 1 isfolder, p.mid, p.NAME vname, '''' vnote, NULL nmaket, NULL ntype, '''' vaddress, p.PARENT nparent, '''' dfrom, '''' dtill, NULL nretries,
            NULL nretries_tout, tag nblock, '''' vparam
   FROM     points p WHERE '
   || lv_sqladd
   || ' NOT EXISTS(SELECT 1 FROM   deportation WHERE  ndeportation = p.mid) AND NOT EXISTS(SELECT 1 FROM   points WHERE  PARENT = p.mid)
   ORDER BY isfolder DESC, havechild DESC, vname';

  OPEN acur_t FOR lv_sql;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'DEPORTATION_PG.getdepchannelstree: Ошибка чтения ветки дерева каналов рассылки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Возращает список макетов/осн. каналов
 PROCEDURE getlist(flag NUMBER, acur_t OUT common_pg.tcur) IS
   lv_sql              VARCHAR2(8000);
 BEGIN
  IF flag = 0 THEN  --Список макетов
			lv_sql := ' SELECT m.nmaket ndeportation, m.vname FROM makets m, deportprocedures p WHERE m.nprocedure = p.nprocedure(+) AND p.ntype = 0';
		  IF adminadd_pg.check_accread(util_pg.cn_makmid) = 0 THEN --Это оптимизация
  			lv_sql := lv_sql||' AND m.nmaket in (select * from table(adminadd_pg.getall_accmid))';
		  END IF;
  ELSIF flag = 1 THEN                                                                                                                  --Список основных каналов
    lv_sql := ' SELECT   m.ndeportation, m.vname FROM deportation m ';
		  IF adminadd_pg.check_accread(util_pg.cn_depmid) = 0 THEN --Это оптимизация
  			lv_sql := lv_sql||' WHERE m.ndeportation in (select * from table(adminadd_pg.getall_accmid))';
  		END IF;    
  END IF;
  lv_sql := lv_sql||' ORDER BY m.vname';
  OPEN acur_t FOR lv_sql;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'DEPORTATION_PG.getlist: Ошибка чтения для '||lv_sql|| CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION is_block(an_deportation NUMBER, an_blocking NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER := an_blocking;
 BEGIN
  IF an_blocking IS NULL THEN
   SELECT NVL(MAX(nblock), 0)
   INTO   ln_ret
   FROM   deportation
   WHERE  ndeportation = an_deportation;
  END IF;

  IF ln_ret <> 0 THEN
   ln_ret := 1;
  ELSE
   SELECT     DECODE(NVL(MAX(tag), 0), 0, 0, 1)
   INTO       ln_ret
   FROM       points
   CONNECT BY PRIOR PARENT = mid
   START WITH mid = an_deportation;
  END IF;

  RETURN ln_ret;
 END;
------------------------------------------------------------------------------------------------------------------------END; -- Package Body
END;
/


-- End of DDL Script for Package Body RYDA.DEPORTATION_PG

-- Start of DDL Script for Package Body RYDA.DETAILPOINT_PG
-- Generated 14.04.2014 9:34:57 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY detailpoint_pg
IS
-------------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------------------------
FUNCTION test_points(an_idgroup NUMBER,an_ispoints NUMBER)
RETURN NUMBER IS
 ln_testcalc NUMBER;
BEGIN
 IF (an_ispoints = 1) THEN
   /* select decode(f.ncalcpointtype,6,1,DECODE(p.ind,4,2,0))
    INTO ln_testcalc
    FROM feeders f,points p
     WHERE f.mid=p.mid
     and  f.MID= an_idgroup;*/
     SELECT COUNT(*) 
     INTO ln_testcalc
     FROM pointformula
     WHERE MID= an_idgroup;
     IF ln_testcalc>0 THEN RETURN 1;
     ELSE
       SELECT DECODE(MAX(p.ind),4,2,0)
       INTO ln_testcalc 
       FROM points p
       WHERE MID= an_idgroup;
       RETURN nvl(ln_testcalc,0);
     END IF;
  ELSE
   /* select decode(f.ncalcpointtype,6,1,DECODE(p.ind,4,2,0))
     INTO ln_testcalc
     FROM feeders f,points p
     WHERE f.mid=p.mid
     and  f.MID= (SELECT mid FROM groups WHERE gid=an_idgroup);*/
    SELECT COUNT(*) 
     INTO ln_testcalc
     FROM pointformula
     WHERE MID =(SELECT mid FROM groups WHERE gid=an_idgroup);
     IF ln_testcalc>0 THEN RETURN 1;
     ELSE
         ln_testcalc:=0;
         SELECT COUNT(*)
         INTO ln_testcalc 
         FROM points p
         WHERE MID= (SELECT mid FROM groups WHERE gid=an_idgroup);
         
       IF ln_testcalc>0 THEN  
            SELECT DECODE(MAX(p.ind),4,2,0)
             INTO ln_testcalc 
             FROM points p
             WHERE MID= (SELECT mid FROM groups WHERE gid=an_idgroup);
             RETURN nvl(ln_testcalc,0);
       ELSE
          RETURN nvl(ln_testcalc,0);
       END IF;      
     END IF;
 END IF;
 --RETURN nvl(ln_testcalc,0);
END;
------------------------------------------------------------------------------------------------------------------------------
PROCEDURE get_points( an_idgroup NUMBER,an_meas NUMBER,acur_t OUT common_pg.tcur)
 IS

lv_sql VARCHAR2(4000);
ln_testmeas NUMBER;
ln_meas NUMBER;
BEGIN
   select COUNT(*)
   into ln_testmeas
   from pointformula b 
   where b.mid= an_idgroup
   and b.nmeas= an_meas;
  IF ln_testmeas=0 THEN
  ln_meas:=0;
  ELSE
  ln_meas:=an_meas;
  END IF;
 
   lv_sql :=' select b.nid,  NVL(f.mid,DETAILPOINT_PG.get_mid(util_pg.get_param(f.vparam,2,''.''))) mid,
              f.vname||'':  ''||nvl(nvl(p.short_name, p.name ),
             DETAILPOINT_PG.get_name(NVL(f.mid,DETAILPOINT_PG.get_mid(util_pg.get_param(f.vparam,2,''.'')))))name,
             f.norder,b.vformula,f.vparam,
             TRIM (UPPER (util_pg.get_param (f.vparam, 3, ''.'')))||''.''||TRIM (UPPER (util_pg.get_param (f.vparam, 4, ''.''))) type,
             DETAILPOINT_PG.test_points(util_pg.get_param(f.vparam,2,''.''),DECODE(util_pg.get_param(f.vparam,1,''.''),''GID'',0,1))test,
             p.ind,DETAILPOINT_PG.if_summ(util_pg.get_param (f.vparam, 3, ''.'')) summ,
             NVL(editfeeders_pg.formulameas_p(' || an_idgroup ||'), '' '') vtypeformula,
             f.nshift,nvl(b.NOPTTYPE,0) NOPTTYPE,b.NHOURERIOD, NVL (fd.ntimezonew, 2) ntimezonew, NVL (fd.ntimezones, 3) ntimezones
             from pointformula b,formulparams f,points p,feeders fd 
             where b.mid=' || an_idgroup ||'
             and b.nid=f.nid 
             and p.mid(+)=f.mid 
             and p.mid = fd.mid
             and b.nmeas= '||ln_meas||'
             union all
             select b.nid, b.mid, nvl(util_pg.get_shortname_f(p.short_name,p.mid),util_pg.get_name_f(p.name,p.mid))name,
             -1 norder,b.vformula,'' '' vparam,
             DECODE(nvl(b.nmeas,0),0, ''Общая'',1 ,''A+'' , 2, ''A-'' , 3 , ''R+'' , 5 , ''R-'') type ,
             1 test,p.ind,1 summ,
             NVL(editfeeders_pg.formulameas_p(' || an_idgroup ||'), '' '') vtypeformula,
             0 nshift,1 NOPTTYPE ,b.NHOURERIOD, 2 ntimezonew, 3 ntimezones
             from pointformula b,points p 
             where b.mid=' || an_idgroup ||'
             and p.mid=b.mid 
             and b.nmeas= '||ln_meas||' 
             ORDER BY norder ';
             

 OPEN acur_t FOR lv_sql; 
 
 END;
