   PROCEDURE get_data
    ( ad_from DATE, ad_till DATE,an_count NUMBER,
      av_param VARCHAR2,
      an_shift NUMBER,
      an_nhoureriod NUMBER,
      an_ntimezonew NUMBER,
      an_ntimezones NUMBER,  
      at_paramval  OUT   common_pg.tt_double,
      at_qm  OUT   common_pg.tt_varchar2
     -- ,an_timezona NUMBER
      )
   
    IS
   -- ln_timezona NUMBER;  
 --   ld_from DATE ;
 --   ld_till DATE ;
    ld_from             DATE DEFAULT util_pg.trunchh24_2(util_pg.to_unlocaltime(ad_from));
    ld_till             DATE DEFAULT util_pg.trunchh24_2(util_pg.to_unlocaltime(ad_till));
  
    lt_paramval  common_pg.tt_double;
    lt_qm     common_pg.tt_varchar2;
     an_qmsumm VARCHAR2(50):=NULL;
     an_summ NUMBER :=NULL;
     tn_qmsumm VARCHAR2(50):=NULL;
     tn_summ NUMBER :=NULL;
     test_issumm NUMBER;
     powercoeff NUMBER :=INTERIOR_PG.get_powercoeff;
     ld_fromg DATE;
     ld_tillg DATE;
     ln_evr NUMBER:=0;
     cn_cnt NUMBER;
     ln_shiftdate NUMBER;
     ln_itemcnt NUMBER;
     ln_timeshift NUMBER;
   BEGIN
  --  ld_from  := util_pg.to_unlocaltime(ad_from+1/86400)+ln_timezona;
  --  ld_till  := util_pg.to_unlocaltime(ad_from+1)+ln_timezona;
   
 /*  IF an_timezona=1 THEN
     ln_evr := 1;
 
     IF (util_pg.is_summer(ad_from) = 1) THEN
      ld_fromg := ad_from  + an_timezona / 24 + 1 / 24;
     
     ELSE
      ld_fromg := ad_from  + an_timezona / 24;
    
     END IF;

     IF (util_pg.is_summer(ad_till) = 1) THEN
      ld_tillg := ad_till  + an_timezona / 24 + 1 / 24;
    
     ELSE
      ld_tillg := ad_till + an_timezona / 24;
     
     END IF;
    ELSE
     ld_fromg := ad_from  + an_timezona / 24;
     ld_tillg := ad_till + an_timezona / 24;
    
    END IF; */
    
   
   IF (an_nhoureriod = 1) THEN
    cn_cnt := 24;
   ELSE
    cn_cnt := 48;
   END IF; 
    ln_timeshift := util_pg.cn_tzw - an_ntimezonew;
    IF an_ntimezonew=an_ntimezones  THEN
     ln_evr := 1;

     IF (util_pg.is_summer(ld_from) = 1) THEN
      ld_fromg := ld_from + ln_timeshift / 24 + 1 / 24;
      ln_shiftdate := an_shift/24+ ln_timeshift / 24 + 1 / 24;
     ELSE
      ld_fromg := ld_from + ln_timeshift / 24;
      ln_shiftdate := an_shift/24 + ln_timeshift / 24;
     END IF;

     IF (util_pg.is_summer(ld_till) = 1) THEN
      ld_tillg := ld_till + ln_timeshift / 24 + 1 / 24;
     --  ln_shiftdate:=an_shift/24 + an_timezona / 24 + 1 / 24;
     ELSE
      ld_tillg := ld_till + ln_timeshift / 24;
     -- ln_shiftdate:=an_shift/24 + an_timezona / 24 ;
     END IF;
    ELSE
     -- ln_evr := 0;
     ld_fromg := ld_from + ln_timeshift / 24;
     ld_tillg := ld_till + ln_timeshift / 24;
     ln_shiftdate := an_shift/24 + ln_timeshift / 24;
    END IF;
--insert into tmp_vil values (to_char(ld_fromg,'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_tillg,'dd.mm.yyyy hh24:mi:ss'));commit;
      -- IF lr_info.ntw = lr_info.nts THEN
    --  ln_itemcnt := ROUND((util_pg.to_localtime(ld_tillg) - util_pg.to_localtime(ld_fromg)) * cn_cnt);
    ln_itemcnt :=
     ROUND((ld_tillg - ld_fromg) * cn_cnt
      - (2 * util_pg.is_dayswitch(util_pg.to_localtime(ld_tillg))) / cn_cnt
      - (2 * util_pg.is_dayswitch(util_pg.to_localtime(ld_fromg))) / cn_cnt);
    
     FOR j IN 1 .. an_count-1 LOOP
      lt_paramval (j) := NULL;
      lt_qm (j) := NULL;
     END LOOP;
  CALCFORMULA_PG.getvalw (av_param, ld_fromg+an_shift/24 , ld_tillg+an_shift/24, 1, lt_paramval, lt_qm, ln_evr ,ln_itemcnt ,ln_shiftdate,cn_cnt);
 --    CALCFORMULA_PG.getvalw (av_param, ld_fromg+an_shift/24 , ld_tillg+an_shift/24, 1, lt_paramval, lt_qm, ln_evr ,48 ,an_shift/24+an_timezona,48);
--getvalw(lr_param.vparam, ld_fromg + lr_param.nshift, ld_tillg + lr_param.nshift, k, lt_paramval, lt_qm, ln_evr, ln_itemcnt, ln_shiftdate, cn_cnt);
     test_issumm:=if_summ(util_pg.get_param (av_param, 3, '.'));
      FOR k IN 1 .. an_count-1 LOOP                                                                    --Цикл по параметрам
     
      
      at_qm(k+1) := lt_qm(k);
      IF TRIM(UPPER(util_pg.get_param (av_param, 3, '.')))='DATNUM' THEN
      at_paramval(k+1) :=lt_paramval(k);
      ELSE
      at_paramval(k+1) := lt_paramval(k)/powercoeff;
      END IF;
      IF test_issumm = 1 THEN
              if k=1 then
            
              tn_qmsumm:=lt_qm(k);
              an_qmsumm:=tn_qmsumm;
              else
              an_qmsumm:=qm_pg.sumqm (tn_qmsumm, lt_qm(k));
              tn_qmsumm:=an_qmsumm;
              end if;
              tn_summ:=NVL(an_summ,0);
              an_summ:=NVL(tn_summ,0)+nvl(lt_paramval(k)/powercoeff,0); 
            
      ELSE 
        an_qmsumm:=NULL;
      END IF;
      
     
      END LOOP;
      
      IF an_summ IS NULL THEN
        at_qm(1) :=NULL;
      ELSE
        at_qm(1) :=an_qmsumm;
      END IF;
      at_paramval(1) :=an_summ;
    
     
   END;
-----------------------------------------------------------------------------------------------------------------------------------------------
FUNCTION get_mid(an_idgroup NUMBER)
RETURN NUMBER IS
rec NUMBER;
BEGIN
 SELECT MAX(mid)
 INTO rec
 FROM GROUPS 
 WHERE gid=an_idgroup;
 RETURN rec;
END;
----------------------------------------------------------------------------------------------------------
FUNCTION get_name(an_idgroup NUMBER)
RETURN VARCHAR2 IS
rec VARCHAR2(200);
BEGIN
 SELECT nvl(p.short_name,p.name)name
 INTO rec
 FROM POINTS p
 WHERE mid=an_idgroup;
 RETURN rec;
END;
-----------------------------------------------------------------------------------------------------------
FUNCTION if_summ(av_param VARCHAR2)
RETURN NUMBER IS

BEGIN
 IF TRIM(UPPER(av_param)) IN ('A', 'AI','ER', 'ED', 'Q1', 'Q3', 'Q2', 'Q3', 'Q12', 'Q34', 'E', 'Q', 'EE', 'QQ')THEN
 RETURN 1;
 ELSE 
 RETURN 0;
 END IF;
END;
-------------------------------------------------------------------------------------------------------
FUNCTION priority_f (an_mid NUMBER,an_ind NUMBER,ad_date DATE)
 RETURN NUMBER IS
 res NUMBER;
  BEGIN
  IF an_ind=3 THEN
    SELECT MAX(r.norder)
    INTO res
    from priority r  
    where r.mid=an_mid
    and ad_date<=r.dend
    and ad_date>r.dstart;
  END IF;
 RETURN res;   
   END;

----------------------------------------------------------------------------------------------------
FUNCTION get_timeshift(an_idgroup NUMBER)
RETURN NUMBER IS
rec NUMBER;
BEGIN
 rec:=0;
 SELECT util_pg.cn_tzw - MAX(NVL (ntimezonew, 2)) ntimezonew
 INTO rec
 FROM FEEDERS
 WHERE mid=an_idgroup;
 RETURN rec;
END;
----------------------------------------------------------------------------------------------------------
END;
/


