CREATE OR REPLACE 
PACKAGE BODY editfeedergroup_pg IS
 -- пакет работы с группами присоединений
 -- дата создания 28/12/2001 (Сечин А.А.)
 gn_task_code NUMBER DEFAULT 40;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p(
  an_parent         NUMBER, --Родитель
  av_name           VARCHAR2, --Название
  av_short_name     VARCHAR2, --Краткое название
  an_mid        OUT NUMBER --Ид точки
                          ) IS
  ln_mid NUMBER;
 BEGIN
  SAVEPOINT editfeedergroup_ins;
   adminadd_pg.check_right(ln_mid, an_parent, 1, 2);
		  
  SELECT points_seq.NEXTVAL
    INTO ln_mid
    FROM DUAL;
  an_mid := ln_mid;
  INSERT INTO points
              (mid, parent, cod, ind, name, short_name, implement_date, tag, npoint)
       VALUES (ln_mid, an_parent, 0, 2, av_name, av_short_name, SYSDATE, NULL, NULL);
  IF util_pg.get_customer_id = 1 THEN
   ln_mid := editfeeders_pg.insgroup(ln_mid);
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, 1, 'Добавлена группа точек ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editfeedergroup_ins;
   raise_application_error(
    -20001, 'editfeedergroup_pg.ins_p: Ошибка группы присоединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура обновления данных
 PROCEDURE upd_p(
  an_mid        NUMBER, --Ид точки
  an_parent     NUMBER, --Родитель
  av_name       VARCHAR2, --Название
  av_short_name VARCHAR2 --Краткое название
                        ) IS
  ln_gid  NUMBER;
  ln_gid1 NUMBER;
 BEGIN
  SAVEPOINT editfeedergroup_upd;
  adminadd_pg.check_right(an_mid, an_parent, 1, 2);

  UPDATE points
     SET name = av_name,
         short_name = av_short_name,
         parent = an_parent
   WHERE mid = an_mid;
  IF util_pg.get_customer_id = 1 THEN
   ln_gid := editfeeders_pg.insgroup(an_parent);
   ln_gid1 := editfeeders_pg.insgroup(an_mid);
   UPDATE groups
      SET name = av_name,
          parent = ln_gid
    WHERE nroot1 = 1 AND nroot2 = an_mid;
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Изменены атрибуты группы точек ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editfeedergroup_upd;
   raise_application_error(
    -20001, 'editfeedergroup_pg.upd_p: Ошибка обновления группы присоединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура вставки для АСРПБ
 PROCEDURE ins_p_a(
  an_parent         NUMBER, --Родитель
  av_name           VARCHAR2, --Название
  av_short_name     VARCHAR2, --Краткое название
  an_point          NUMBER, --Ид прома
  an_mid        OUT NUMBER --Ид точки
                          ) IS
  ln_mid NUMBER;
 BEGIN
  adminadd_pg.check_right(ln_mid, an_parent, 1, 2);
  SELECT points_seq.NEXTVAL
    INTO ln_mid
    FROM DUAL;
  an_mid := ln_mid;
  INSERT INTO points
              (mid, parent, cod, ind, name, short_name, implement_date, tag, npoint)
       VALUES (ln_mid, an_parent, 0, 2, av_name, av_short_name, SYSDATE, NULL, an_point);
  ln_mid := editfeeders_pg.insgroup(ln_mid);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'editfeedergroup_pg.ins_p: Ошибка группы присоединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки для импорта
 PROCEDURE ins_p_synchro(
  an_parent         NUMBER, --Родитель
  av_name           VARCHAR2, --Название
  av_short_name     VARCHAR2, --Краткое название
  an_root           NUMBER, --Ид точки в родительской БД
  an_mid        OUT NUMBER --Ид точки
                          ) IS
  ln_mid NUMBER;
 BEGIN
  adminadd_pg.check_right(ln_mid, an_parent, 1, 2);
		  SELECT points_seq.NEXTVAL
    INTO ln_mid
    FROM DUAL;
  an_mid := ln_mid;
  INSERT INTO points
              (mid, parent, cod, ind, name, short_name, implement_date, tag, nroot)
       VALUES (ln_mid, an_parent, 0, 2, av_name, av_short_name, SYSDATE, NULL, an_root);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'editfeedergroup_pg.ins_p_synchro: Ошибка группы присоединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура обновления данных для АСРПБ
 PROCEDURE upd_p_a(
  an_mid        NUMBER, --Ид точки
  an_parent     NUMBER, --Родитель
  av_name       VARCHAR2, --Название
  av_short_name VARCHAR2 --Краткое название
                        ) IS
  ln_gid  NUMBER;
  ln_gid1 NUMBER;
 BEGIN
  adminadd_pg.check_right(an_mid, an_parent, 1, 2);
  UPDATE points
     SET name = av_name,
         short_name = av_short_name,
         parent = an_parent
   WHERE mid = an_mid;
  ln_gid := editfeeders_pg.insgroup(an_parent);
  ln_gid1 := editfeeders_pg.insgroup(an_mid);
  UPDATE groups
     SET name = av_name,
         parent = ln_gid
   WHERE nroot1 = 1 AND nroot2 = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'editfeedergroup_pg.upd_p: Ошибка обновления группы присоединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура удаления данных
 PROCEDURE del_p(an_mid NUMBER --Ид точки
                              ) IS
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);
  
  admin_pg.fiscal_p(gn_task_code, 3, 'Удалена группа точек ' || util_pg.node_path_f(
                                                                      an_mid, 'points', 'mid', 'parent'));
  DELETE FROM points
        WHERE mid = an_mid;
  DELETE FROM groups
        WHERE nroot1 = 1 AND nroot2 = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'editfeedergroup_pg.del_p: Ошибка удаления группы присоединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
     -- Редактирование аттрибутов предприятия
 PROCEDURE interprise_p(
  an_mid        IN OUT NUMBER, --Ид точки
  av_name              VARCHAR2, --Название
  av_short_name        VARCHAR2, --Краткое название
  an_cod               NUMBER --Код предприятия
                             ) IS
 BEGIN
  adminadd_pg.check_right(an_mid, util_pg.cn_pntmid, 1, 2);

  IF NVL(an_mid, 0) = 0 THEN
   SELECT points_seq.NEXTVAL
     INTO an_mid
     FROM DUAL;
   INSERT INTO points
               (mid, parent, cod, ind, name, short_name)
        VALUES (an_mid, NULL, 0, 1, av_name, av_short_name);
   INSERT INTO enterprise
               (mid, cod)
        VALUES (an_mid, an_cod);
  ELSE
   UPDATE points
      SET name = av_name,
          short_name = av_short_name
    WHERE mid = an_mid;
   UPDATE enterprise
      SET cod = an_cod
    WHERE mid = an_mid;
  END IF;
  admin_pg.fiscal_p(gn_task_code, 2, 'Изменены атрибуты предприятия');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'editfeedergroup_pg.interprise_p: Ошибка обновления аттрибут предприятия. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_enterprise_data (an_mid OUT NUMBER, av_pname OUT VARCHAR2, av_psname OUT VARCHAR2, an_pcod OUT NUMBER) IS
 -- используется в TFormIntrpriseReneme::ReadData
 -- added by Kondakov A.G. 31.07.2008
 BEGIN
  SELECT nvl(max(p.mid),0),max(p.NAME),max(p.short_name),max(e.cod)
  INTO an_mid,av_pname,av_psname,an_pcod
  FROM points p,enterprise e WHERE p.mid=e.mid;
 END;
--------------------------------------------------------------------------------------
END; -- Package Body
/


