 PROCEDURE get_measure(an_mid NUMBER, an_objtype NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   s.vname, m.mrid, s.nmeasure, an_mid mid
