 PROCEDURE get_procedurelist (an_idtype NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT 1 ID, 'procedure1' pname
     FROM DUAL
    UNION ALL 
    SELECT 2 ID, 'procedure2' pname
     FROM DUAL;
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Bod
/


