------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_mesttype(acur_t OUT common_pg.tcur) IS                                                                                   --Вернем типы измерений
 BEGIN
  OPEN acur_t FOR
   SELECT 0 nid, 'Общая' vname
   FROM   DUAL
   UNION ALL
   SELECT 1 nid, 'A+' vname
   FROM   DUAL
   UNION ALL
   SELECT 2 nid, 'A-' vname
   FROM   DUAL
   UNION ALL
   SELECT 3 nid, 'R+' vname
   FROM   DUAL
   UNION ALL
   SELECT 5 nid, 'R-' vname
   FROM   DUAL;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_function(acur_t OUT common_pg.tcur, an_parent NUMBER) IS                                                                 --Вернем базовую функцию
 BEGIN
  IF NVL(an_parent, 0) = 0 THEN
   OPEN acur_t FOR
    SELECT   nid, nparent, ntype, vname, vformula vvalue, vmemo, 1 havechild
    FROM     baseformula a
    WHERE    nparent IS NULL AND EXISTS(SELECT *
                                        FROM   baseformula
                                        WHERE  nparent = a.nid)
    UNION ALL
    SELECT   nid, nparent, ntype, vname, vformula vvalue, vmemo, 0 havechild
    FROM     baseformula a
    WHERE    nparent IS NULL AND NOT EXISTS(SELECT *
                                            FROM   baseformula
                                            WHERE  nparent = a.nid)
    ORDER BY 3, 4, 1;
  ELSE
   OPEN acur_t FOR
    SELECT   nid, nparent, ntype, vname, vformula vvalue, vmemo, 1 havechild
    FROM     baseformula a
    WHERE    nparent = an_parent AND EXISTS(SELECT *
                                            FROM   baseformula
                                            WHERE  nparent = a.nid)
    UNION ALL
    SELECT   nid, nparent, ntype, vname, vformula vvalue, vmemo, 0 havechild
    FROM     baseformula a
    WHERE    nparent = an_parent AND NOT EXISTS(SELECT *
                                                FROM   baseformula
                                                WHERE  nparent = a.nid)
    ORDER BY 3, 4, 1;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_functionext(an_id NUMBER, an_type OUT NUMBER, av_name OUT VARCHAR2, av_formula OUT VARCHAR2, av_memo OUT VARCHAR2, acur_t OUT common_pg.tcur) IS
 --Вернем все про базовую функцию
 BEGIN
  FOR lc IN (SELECT ntype, vname, vformula, vmemo
             FROM   baseformula
             WHERE  nid = an_id) LOOP
   an_type := lc.ntype;
   av_name := lc.vname;
   av_formula := lc.vformula;
   av_memo := lc.vmemo;
   EXIT;
  END LOOP;

  OPEN acur_t FOR
   SELECT   nid, norder, vname, vparam, vmemo
   FROM     baseformulparams
   WHERE    nid = an_id
   ORDER BY norder;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_function(an_id NUMBER)                                                                                                  --Удаляет базовую функцию
                                     IS
 BEGIN
  DELETE FROM baseformula
  WHERE       nid = an_id;

  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------------
--Сохраняем базовую функцию
 PROCEDURE save_function(an_id IN OUT NUMBER, an_parent NUMBER, an_type NUMBER, av_name VARCHAR2, av_formula VARCHAR2, av_memo VARCHAR2) IS
 BEGIN
  IF NVL(an_id, 0) = 0 THEN
   SELECT points_seq.NEXTVAL
   INTO   an_id
   FROM   DUAL;

   INSERT INTO baseformula
               (nid, nparent, ntype, vname, vformula, vmemo)
   VALUES      (an_id, an_parent, an_type, av_name, av_formula, av_memo);
  ELSE
   UPDATE baseformula
   SET nparent = an_parent,
       ntype = an_type,
       vname = av_name,
       vformula = av_formula,
       vmemo = av_memo
   WHERE  nid = an_id;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE save_function(
 an_id IN OUT NUMBER, an_parent NUMBER, an_type NUMBER, av_name VARCHAR2, av_formula VARCHAR2, av_memo VARCHAR2, at_name common_pg.tt_varchar2,
 at_param common_pg.tt_varchar2, at_memo common_pg.tt_varchar2
 ) IS
 BEGIN
  save_function(an_id, an_parent, an_type, av_name, av_formula, av_memo);

  DELETE FROM baseformulparams
  WHERE       nid = an_id;

  IF at_name.COUNT > 0 AND at_name(1) IS NOT NULL THEN
   FOR i IN 1 .. at_name.COUNT LOOP
    INSERT INTO baseformulparams
                (nid, norder, vname, vparam, vmemo)
    VALUES      (an_id, i, at_name(i), at_param(i), at_memo(i));
   END LOOP;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_formula(
 an_mid NUMBER, an_meas IN OUT NUMBER, av_formula OUT VARCHAR2, av_memo OUT VARCHAR2, an_nhoureriod OUT NUMBER, an_ndivtype OUT NUMBER,
 acur_t OUT common_pg.tcur
 ) IS                                                                                                                                   --Вернем все про формулу
  ln_id               NUMBER;
 BEGIN
  FOR lc IN (SELECT   nid, nmeas, vformula, vmemo, nhoureriod, ndivtype
             FROM     pointformula
             WHERE    mid = an_mid AND(an_meas IS NULL OR nmeas = an_meas)
             ORDER BY DECODE(nmeas, an_meas, 1, 2), nmeas) LOOP
   an_meas := lc.nmeas;
   ln_id := lc.nid;
   av_formula := lc.vformula;
   av_memo := lc.vmemo;
   an_nhoureriod := lc.nhoureriod;
   an_ndivtype := lc.ndivtype;
   EXIT;
  END LOOP;

  OPEN acur_t FOR
   SELECT   nid, norder, vname, vparam, vmemo, get_objnamebyparam(vparam) objname, nshift
   FROM     formulparams
   WHERE    nid = ln_id
   ORDER BY norder;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE save_formula(
 an_mid NUMBER, an_meas NUMBER, av_formula VARCHAR2, av_memo VARCHAR2, an_nhoureriod NUMBER, an_ndivtype NUMBER, at_name common_pg.tt_varchar2,
 at_param common_pg.tt_varchar2, at_memo common_pg.tt_varchar2, at_shift common_pg.tt_varchar2
 ) IS
  ln_id               NUMBER;
  lt_paramname        common_pg.tt_varchar2;
  lv_error            VARCHAR2(400);
  ln_err              NUMBER;
  lv_formula          VARCHAR2(4000);
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);
  lv_formula := LOWER(TRIM(REPLACE(REPLACE(av_formula, CHR(10), CHR(32)), CHR(13), CHR(32))));

  IF (lv_formula LIKE 'round30817(%,2)' OR lv_formula LIKE 'round30817(%,4)') AND an_meas <> 0 THEN
   raise_application_error(-20001, 'Формулы типа ''round30817'' применяются только с общим типом измерений');
  END IF;

  SELECT MAX(nid)
  INTO   ln_id
  FROM   pointformula
  WHERE  mid = an_mid AND nmeas = an_meas;

  IF ln_id IS NULL THEN
   SELECT points_seq.NEXTVAL
   INTO   ln_id
   FROM   DUAL;

   INSERT INTO pointformula
               (nid, mid, nmeas, vformula, vmemo, nhoureriod, ndivtype)
   VALUES      (ln_id, an_mid, an_meas, av_formula, av_memo, an_nhoureriod, an_ndivtype);
  ELSE
   UPDATE pointformula
   SET vformula = av_formula,
       vmemo = av_memo,
       nhoureriod = an_nhoureriod,
       ndivtype = an_ndivtype
   WHERE  nid = ln_id;
  END IF;

  UPDATE feeders
  SET ncalcpointtype = 6
  WHERE  mid = an_mid AND NVL(ncalcpointtype, 0) <> 6;

  DELETE FROM formulparams
  WHERE       nid = ln_id;

  ln_err := analysis_formula(av_formula, lt_paramname, lv_error);

  IF ln_err <> 0 THEN
   raise_application_error(-20001, lv_error);
  END IF;

  ln_err := 0;

  IF lt_paramname.COUNT <> at_name.COUNT THEN
   ln_err := 1;
  END IF;

  IF ln_err > 0 THEN
   raise_application_error(-20001, 'Аргументы не соответствуют формуле');
  END IF;

  IF at_name.COUNT > 0 AND at_name(1) IS NOT NULL THEN
   FOR j IN 1 .. lt_paramname.COUNT LOOP
    FOR i IN 1 .. at_name.COUNT LOOP
     IF get_mid(at_param(i)) = 1000 THEN
      raise_application_error(-20001, 'Использование корневой папки в качестве аргумента недопустимо');
     END IF;

     IF lt_paramname(j) = at_name(i) THEN
      INSERT INTO formulparams
                  (nid, norder, vname, vparam, vmemo, nshift, mid)
      VALUES      (ln_id, j, at_name(i), at_param(i), at_memo(i), at_shift(i), get_mid(at_param(i)));

      EXIT;
     ELSIF i = at_name.COUNT THEN
      raise_application_error(-20001, 'Имена аргументов не соответствуют формуле');
     END IF;
    END LOOP;
   END LOOP;
  END IF;

  IF (lv_formula LIKE 'round30817(%,1)' OR lv_formula LIKE 'round30817(%,3)' OR lv_formula LIKE 'round30817(%,5)' OR lv_formula LIKE 'round30817(%,6)')
     --  AND an_meas = 0
     AND at_name.COUNT = 1 AND UPPER(TRIM(util_pg.get_param(at_param(1), 1, '.'))) = 'MID' THEN
   IF lv_formula LIKE 'round30817(%,1)' THEN
    UPDATE pointformula
    SET nopttype = cn_opttype2
    WHERE  nid = ln_id;
   ELSIF lv_formula LIKE 'round30817(%,3)' THEN
    UPDATE pointformula
    SET nopttype = cn_opttype4
    WHERE  nid = ln_id;
   ELSIF lv_formula LIKE 'round30817(%,5)' THEN
    UPDATE pointformula
    SET nopttype = cn_opttype7
    WHERE  nid = ln_id;
   ELSE
    UPDATE pointformula
    SET nopttype = cn_opttype8
    WHERE  nid = ln_id;
   END IF;
  ELSIF (lv_formula LIKE 'round30817(%,2)' OR lv_formula LIKE 'round30817(%,4)') AND an_meas = 0 AND at_name.COUNT = 1
        AND UPPER(TRIM(util_pg.get_param(at_param(1), 1, '.'))) = 'MID' THEN
    UPDATE pointformula
    SET nopttype = cn_opttype5
    WHERE  nid = ln_id;
  ELSIF(
        an_meas = 0 AND at_param.COUNT = 1 AND UPPER(TRIM(util_pg.get_param(at_param(1), 1, '.'))) = 'GID'
        AND   INSTR(av_formula, '*')
            + INSTR(av_formula, '/')
            + INSTR(av_formula, '(')
            + INSTR(av_formula, ')')
            + util_pg.substr_cnt(av_formula, '+')
            + util_pg.substr_cnt(av_formula, '-') = 0
       ) THEN
   UPDATE pointformula
   SET nopttype = cn_opttype6
   WHERE  nid = ln_id;
  ELSE
   FOR i IN (SELECT   f.nid, COUNT(p.nid) cn, SUM(DECODE(UPPER(TRIM(util_pg.get_param(vparam, 3, '.'))), 'A', 1, 'AI', 1, 0)) sma,
                      SUM(DECODE(UPPER(TRIM(util_pg.get_param(vparam, 1, '.'))), 'MID', 1, 0)) smmid
             --
             FROM     pointformula f, formulparams p
             WHERE    f.nmeas = 0 AND p.nid = f.nid AND f.nid = ln_id
             GROUP BY f.nid) LOOP
    IF i.cn = i.sma AND i.cn = i.smmid AND INSTR(av_formula, '*') + INSTR(av_formula, '/') + INSTR(av_formula, '(') + INSTR(av_formula, ')') = 0
       AND util_pg.substr_cnt(av_formula, '+') + util_pg.substr_cnt(av_formula, '-') < i.cn THEN                                         --Линейная оптимизация
     UPDATE pointformula
     SET nopttype = cn_opttype1
     WHERE  nid = i.nid;

     FOR j IN (SELECT p.nid, p.norder, SUBSTR(f.vformula, INSTR(f.vformula, p.vname) - 1, 1) psign, INSTR(f.vformula, p.vname) - 1 ppos
               FROM   pointformula f, formulparams p
               WHERE  f.nid = i.nid AND p.nid = i.nid) LOOP
      IF j.psign = '+' OR j.ppos = 0 THEN
       UPDATE formulparams
       SET nsign = 1
       WHERE  nid = i.nid AND norder = j.norder;
      ELSE
       UPDATE formulparams
       SET nsign = -1
       WHERE  nid = i.nid AND norder = j.norder;
      END IF;
     END LOOP;
    ELSE
     UPDATE pointformula
     SET nopttype = NULL
     WHERE  nid = i.nid;
    END IF;
   END LOOP;
  END IF;

  order_formula;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
--Удаление формулы
 PROCEDURE delete_formula(an_mid NUMBER, an_meas NUMBER) IS
 BEGIN
  IF an_meas IS NOT NULL THEN
   DELETE FROM pointformula
   WHERE       mid = an_mid AND nmeas = an_meas;
  ELSE
   DELETE FROM pointformula
   WHERE       mid = an_mid;
  END IF;

  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE order_formula IS
  lv_ret              VARCHAR2(256);
 BEGIN
  SAVEPOINT editformula_sp;
  orderformula_pg.order_formula;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editformula_sp;
   raise_application_error(-20001, 'EDITFORMULA_PG.order_formula: ' || SQLERRM(SQLCODE));
 END order_formula;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_pointname(av_param VARCHAR2, av_pntname OUT VARCHAR2) IS
 BEGIN
  av_pntname := get_objnamebyparam(av_param);
 END get_pointname;

------------------------------------------------------------------------------------------------------------------------

 --Анализ формулы =0 все ОК иначе ошибка
 FUNCTION analysis_formula(av_formula VARCHAR2, at_paramname OUT common_pg.tt_varchar2, av_error OUT VARCHAR2)
  RETURN NUMBER IS
  ln_idexpr           PLS_INTEGER;
  ln_varcount         PLS_INTEGER;
  ln_err              NUMBER DEFAULT 0;
  bad_formula         EXCEPTION;
  lv_ret              VARCHAR2(256);
 BEGIN
  ln_idexpr := parser_pg.newexpression(TRIM(REPLACE(REPLACE(av_formula, CHR(10), CHR(32)), CHR(13), CHR(32))));

  IF ln_idexpr < 0 THEN
   ln_err := -10;
   RAISE bad_formula;
  END IF;

  ln_varcount := parser_pg.getnbusedvars(ln_idexpr);

  IF ln_varcount < 0 THEN
   ln_err := -10;
   RAISE bad_formula;
  END IF;

  FOR i IN 1 .. ln_varcount LOOP
   lv_ret := '';
   ln_err := parser_pg.getusedvar(ln_idexpr, i - 1, lv_ret, 256);

   IF ln_err <> 0 THEN                                                                                                                           -- есть ошибка
    RAISE bad_formula;
   END IF;

   at_paramname(i) := lv_ret;
  END LOOP;

  IF ln_varcount = 0 THEN
   at_paramname(1) := ' ';
  END IF;

  av_error := 'Нет ошибок';
  RETURN 0;
 EXCEPTION
  WHEN bad_formula THEN
   IF ln_err = -10 THEN                                                                                                      -- надо узнать реальный код ошибки
    ln_err := parser_pg.getparsererror;
   END IF;

   av_error := parser_pg.getparsererrortext(ln_err);
   RETURN ln_err;
  WHEN OTHERS THEN
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
--Расчет формулы =0 все ОК иначе ошибка an_res-результат вычисления
 FUNCTION calc_formula(av_formula VARCHAR2, at_paramname common_pg.tt_varchar2, at_paramvalue common_pg.tt_number, an_res OUT NUMBER, av_error OUT VARCHAR2)
  RETURN NUMBER IS
  ln_idexpr           PLS_INTEGER;
  ln_varcount         PLS_INTEGER;
  ldp_varval          DOUBLE PRECISION;
  ln_err              NUMBER DEFAULT 0;
  bad_formula         EXCEPTION;
 BEGIN
  ln_idexpr := parser_pg.newexpression(TRIM(REPLACE(REPLACE(av_formula, CHR(10), CHR(32)), CHR(13), CHR(32))));

  IF ln_idexpr < 0 THEN
   ln_err := -10;
   RAISE bad_formula;
  END IF;

  ln_varcount := parser_pg.getnbusedvars(ln_idexpr);

  IF ln_varcount < 0 THEN
   ln_err := -10;
   RAISE bad_formula;
  END IF;

  FOR i IN 1 .. ln_varcount LOOP
   ldp_varval := at_paramvalue(i);
   ln_err := parser_pg.setvar(ln_idexpr, i - 1, at_paramname(i), ldp_varval);

   IF ln_err <> 0 THEN                                                                                                                           -- есть ошибка
    RAISE bad_formula;
   END IF;
  END LOOP;

  ln_err := parser_pg.evaluate(ln_idexpr, an_res);

  IF ln_err <> 0 THEN
   RAISE bad_formula;
  END IF;

  av_error := 'Нет ошибок';
  RETURN 0;
 EXCEPTION
  WHEN bad_formula THEN
   IF ln_err = -10 THEN                                                                                                      -- надо узнать реальный код ошибки
    ln_err := parser_pg.getparsererror;
   END IF;

   av_error := parser_pg.getparsererrortext(ln_err);
   RETURN ln_err;
  WHEN OTHERS THEN
   RAISE;
 END;

