--Возвращает наименование объекта по тегу параметра
 FUNCTION get_objnamebyparam(av_param VARCHAR2)
  RETURN VARCHAR2 IS
  lv_param            VARCHAR2(128) DEFAULT UPPER(av_param);
  ln_id               NUMBER DEFAULT util_pg.allnumber_f(TRIM(util_pg.get_param(lv_param, 2, '.')));
  lv_objtype          VARCHAR2(128) DEFAULT TRIM(util_pg.get_param(lv_param, 1, '.'));
  lv_name             VARCHAR2(128);
 BEGIN
  IF lv_objtype = 'GID' THEN
   SELECT MAX(NAME)
   INTO   lv_name
   FROM   GROUPS
   WHERE  gid = ln_id;
  ELSIF lv_objtype = 'MID' THEN
   SELECT MAX(NAME)
   INTO   lv_name
   FROM   points
   WHERE  mid = ln_id;
  END IF;

  RETURN lv_name;
 END;

