 PROCEDURE read_tree_mid(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT 1 havechilde, tab.mid, tab.param,(tab.vname || ' - ' || poi_t.NAME || ' (' || tab.vparam || ')') text, poi_t.ind
   FROM   (SELECT pf.nid, pf.mid, /*util_pg.get_param(fp.vparam, 2, '.')*/ fp.mid param, fp.vparam, fp.vname
           FROM   pointformula pf, formulparams fp
           WHERE  pf.nid = fp.nid) tab,
          points poi_t
   WHERE  tab.mid = an_mid AND poi_t.mid = tab.param AND EXISTS(SELECT *
                                                                FROM   pointformula pf
                                                                WHERE  pf.mid = tab.param)
   UNION ALL
   SELECT 0 havechilde, tab.mid, tab.param,(tab.vname || ' - ' || poi_t.NAME || ' (' || tab.vparam || ')') text, poi_t.ind
   FROM   (SELECT pf.nid, pf.mid, /*util_pg.get_param(fp.vparam, 2, '.')*/ fp.mid param, fp.vparam, fp.vname
           FROM   pointformula pf, formulparams fp
           WHERE  pf.nid = fp.nid) tab,
          points poi_t
   WHERE  tab.mid = an_mid AND poi_t.mid = tab.param AND NOT EXISTS(SELECT *
                                                                    FROM   pointformula pf
                                                                    WHERE  pf.mid = tab.param);
 END;

