 PROCEDURE read_tree_in_param(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT DISTINCT 1 havechilde, tab.mid, tab.param,(poi_t.NAME || ' (' || tab.mid || ')') text, poi_t.ind
   FROM            (SELECT pf.nid, pf.mid, util_pg.get_param(fp.vparam, 2, '.') param, fp.vparam, fp.vname
                    FROM   pointformula pf, formulparams fp
                    WHERE  pf.nid = fp.nid) tab,
                   points poi_t
   WHERE           tab.param = an_mid AND poi_t.mid = tab.mid AND EXISTS(SELECT *
                                                                         FROM   formulparams fp
                                                                         WHERE  util_pg.get_param(fp.vparam, 2, '.') = tab.mid)
   UNION ALL
   SELECT DISTINCT 0 havechilde, tab.mid, tab.param,(poi_t.NAME || ' (' || tab.mid || ')') text, poi_t.ind
   FROM            (SELECT pf.nid, pf.mid, util_pg.get_param(fp.vparam, 2, '.') param, fp.vparam, fp.vname
                    FROM   pointformula pf, formulparams fp
                    WHERE  pf.nid = fp.nid) tab,
                   points poi_t
   WHERE           tab.param = an_mid AND poi_t.mid = tab.mid AND NOT EXISTS(SELECT *
                                                                             FROM   formulparams fp
                                                                             WHERE  util_pg.get_param(fp.vparam, 2, '.') = tab.mid);
 END;

