 FUNCTION get_mid(av_param VARCHAR2)
  RETURN NUMBER IS
  lv_param            VARCHAR2(128) DEFAULT UPPER(av_param);
  ln_id               NUMBER DEFAULT util_pg.allnumber_f(TRIM(util_pg.get_param(lv_param, 2, '.')));
  lv_objtype          VARCHAR2(128) DEFAULT TRIM(util_pg.get_param(lv_param, 1, '.'));
  ln_res              NUMBER;
 BEGIN
  IF lv_objtype = 'GID' THEN
   SELECT MAX(mid)
   INTO   ln_res
   FROM   GROUPS
   WHERE  gid = ln_id;
  ELSIF lv_objtype = 'MID' THEN
   ln_res := ln_id;
  END IF;

  RETURN ln_res;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_tree_in_param2(an_mid NUMBER, an_param NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF an_param IS NULL THEN
   OPEN acur_t FOR
    SELECT DISTINCT ll.havechilde, ll.mid, ll.text, ll.vname, ll.ind, ll.imind
    FROM            (SELECT 1 havechilde, p.mid,(util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text, util_pg.get_pointname(p.mid, 0, 0) vname,
                            1 ind, 27 imind
                     FROM   pointformula p
                     WHERE  NOT EXISTS(SELECT *
                                       FROM   formulparams f
                                       WHERE  f.mid = p.mid) AND p.mid IN(SELECT DISTINCT mid
                                                                          FROM            (SELECT tt.mid, t.mid param, t.nid
                                                                                           FROM   formulparams t, pointformula tt
                                                                                           WHERE  tt.nid = t.nid) mm
                                                                          CONNECT BY      PRIOR mm.mid = mm.param                              --mm.param=mm.mid
                                                                          START WITH      mm.param = an_mid)
                     UNION ALL
                     SELECT 1 havechilde, p.mid,(util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text, util_pg.get_pointname(p.mid, 0, 0) vname,
                            1 ind, 27 imind
                     FROM   pointformula p
                     WHERE  NOT EXISTS(SELECT *
                                       FROM   formulparams f
                                       WHERE  f.mid = p.mid)
                            AND p.mid IN(SELECT DISTINCT mid
                                         FROM            (SELECT tt.mid, util_pg.allnumber_f(TRIM(util_pg.get_param(t.vparam, 2, '.'))) param, t.nid
                                                          FROM   formulparams t, pointformula tt
                                                          WHERE  tt.nid = t.nid) mm
                                         CONNECT BY      PRIOR mm.mid = mm.param                                                               --mm.param=mm.mid
                                         START WITH      mm.param IN(SELECT     gid
                                                                     FROM       GROUPS
                                                                     CONNECT BY PRIOR PARENT = gid
                                                                     START WITH mid = an_mid))
                     UNION ALL
                     SELECT 1 havechilde, p.mid,(util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text, util_pg.get_pointname(p.mid, 0, 0) vname,
                            1 ind, 27 imind
                     FROM   pointformula p
                     WHERE  NOT EXISTS(SELECT *
                                       FROM   formulparams f
                                       WHERE  f.mid = p.mid) AND p.mid IN(SELECT DISTINCT mid
                                                                          FROM            (SELECT tt.mid, t.mid param, t.nid
                                                                                           FROM   formulparams t, pointformula tt
                                                                                           WHERE  tt.nid = t.nid) mm
                                                                          CONNECT BY      PRIOR mm.mid = mm.param                              --mm.param=mm.mid
                                                                          START WITH      mm.param IN(SELECT p.PARENT
                                                                                                      FROM   points p, greenpoint g
                                                                                                      WHERE  an_mid = p.mid AND p.PARENT = g.mid AND g.ntype = 1))
                     UNION ALL
                     SELECT 1 havechilde, p.mid,(util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text, util_pg.get_pointname(p.mid, 0, 0) vname,
                            1 ind, 27 imind
                     FROM   pointformula p
                     WHERE  NOT EXISTS(SELECT *
                                       FROM   formulparams f
                                       WHERE  f.mid = p.mid)
                            AND p.mid IN(SELECT DISTINCT mid
                                         FROM            (SELECT tt.mid, util_pg.allnumber_f(TRIM(util_pg.get_param(t.vparam, 2, '.'))) param, t.nid
                                                          FROM   formulparams t, pointformula tt
                                                          WHERE  tt.nid = t.nid AND t.mid IS NULL) mm
                                         CONNECT BY      PRIOR mm.mid = mm.param                                                               --mm.param=mm.mid
                                         START WITH      mm.param IN(SELECT gid
                                                                     FROM   operatingday
                                                                     WHERE  gid IN(SELECT     gid
                                                                                   FROM       GROUPS
                                                                                   CONNECT BY PRIOR PARENT = gid
                                                                                   START WITH mid = an_mid)))
                     UNION ALL
                     SELECT 1 havechilde, p.mid,(util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text, util_pg.get_pointname(p.mid, 0, 0) vname,
                            1 ind, 27 imind
                     FROM   pointformula p
                     WHERE  NOT EXISTS(SELECT *
                                       FROM   formulparams f
                                       WHERE  f.mid = p.mid) AND p.mid IN(SELECT DISTINCT mid
                                                                          FROM            (SELECT tt.mid, t.mid param, t.nid
                                                                                           FROM   formulparams t, pointformula tt
                                                                                           WHERE  tt.nid = t.nid) mm
                                                                          CONNECT BY      PRIOR mm.mid = mm.param                              --mm.param=mm.mid
                                                                          START WITH      mm.param IN(SELECT mid
                                                                                                      FROM   operatingday
                                                                                                      WHERE  mid = an_mid))) ll;
  ELSE
   OPEN acur_t FOR
    SELECT DISTINCT DECODE(p.mid, an_mid, 0, 1) havechilde, p.mid,(util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text,
                    util_pg.get_pointname(p.mid, 0, 0) vname, DECODE(p.mid, an_mid, editformula_pg.get_ind(an_mid), 1) ind,
                    
                    /*0  - TMainForm::iImageList индекс иконки "синяя точка"
                      26 - TMainForm::iImageList индекс иконки "зеленая точка"
                      27 - TMainForm::iImageList индекс иконки "функция"*/
                    DECODE(p.mid, an_mid, DECODE(editformula_pg.get_ind(an_mid), 1, 27, 3, 0, 4, 26), 27) imind
    FROM            formulparams p
    WHERE           p.nid IN(SELECT nid
                             FROM   pointformula f
                             WHERE  f.mid = an_param) AND p.mid IN(SELECT DISTINCT mid
                                                                   FROM            (SELECT tt.mid, t.mid param, t.nid
                                                                                    FROM   formulparams t, pointformula tt
                                                                                    WHERE  tt.nid = t.nid) mm
                                                                   CONNECT BY      PRIOR mm.mid = mm.param                                     --mm.param=mm.mid
                                                                   START WITH      mm.param = an_mid
                                                                   UNION ALL
                                                                   SELECT an_mid
                                                                   FROM   DUAL)
    UNION ALL
    SELECT DISTINCT DECODE(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), an_mid, 0, 1) havechilde,
                    util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))),
                    DECODE(
                     util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))),
                     an_mid,(
                         util_pg.get_pointname(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), 0, 0)
                      || ' ('
                      || util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.')))
                      || ')'
                     ),
                     (
                         util_pg.get_groupname(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))))
                      || ' ('
                      || util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.')))
                      || ')'
                     )
                    ) text,
                    DECODE(
                     util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))),
                     an_mid, util_pg.get_pointname(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), 0, 0),
                     util_pg.get_groupname(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))))
                    ) vname,
                    DECODE(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), an_mid, editformula_pg.get_ind(an_mid), 1) ind,
                    
                    /*0  - TMainForm::iImageList индекс иконки "синяя точка"
                      26 - TMainForm::iImageList индекс иконки "зеленая точка"
                      27 - TMainForm::iImageList индекс иконки "функция"*/
                    DECODE(
                     util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))),
                     an_mid, DECODE(editformula_pg.get_ind(an_mid), 1, 27, 3, 0, 4, 26),
                     2
                    ) imind
    FROM            formulparams p
    WHERE           p.nid IN(SELECT nid
                             FROM   pointformula f
                             WHERE  f.mid = an_param)
                    AND util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))) IN(
                                                               SELECT DISTINCT param
                                                               --   OR   p.mid   IN (SELECT DISTINCT mid
                                                               FROM            (SELECT tt.mid,
                                                                                       util_pg.allnumber_f(TRIM(util_pg.get_param(t.vparam, 2, '.'))) param,
                                                                                       t.nid
                                                                                FROM   formulparams t, pointformula tt
                                                                                WHERE  tt.nid = t.nid AND t.mid IS NULL /*and tt.nid=62836*/) mm
                                                               CONNECT BY      PRIOR mm.mid = mm.param                                         --mm.param=mm.mid
                                                               START WITH      mm.param IN(SELECT     gid
                                                                                           FROM       GROUPS
                                                                                           CONNECT BY PRIOR PARENT = gid
                                                                                           START WITH mid = an_mid));
                                                          /*       UNION ALL
                                    SELECT an_mid
                                 FROM DUAL)
  /*    UNION ALL
        SELECT DISTINCT DECODE(p.mid, an_mid, 0, 1) havechilde, p.mid,
                      (util_pg.get_pointname(p.mid, 0, 0) || ' (' || p.mid || ')') text,
                      util_pg.get_pointname(p.mid, 0, 0) vname, DECODE(p.mid, an_mid, editformula_pg.get_ind(an_mid), 1) ind,

                     --0  - TMainForm::iImageList индекс иконки "синяя точка"
                     --   26 - TMainForm::iImageList индекс иконки "зеленая точка"
                     --   27 - TMainForm::iImageList индекс иконки "функция"
                      DECODE(p.mid, an_mid, DECODE(editformula_pg.get_ind(an_mid), 1, 27, 3, 0, 4, 26), 26) imind
                 FROM formulparams p
                WHERE p.nid IN(SELECT nid
                                 FROM pointformula f
                                WHERE f.mid = an_param)
                  AND p.mid IN(SELECT DISTINCT param
                                          FROM (SELECT tt.mid, t.mid param, t.nid
                                                  FROM formulparams t, pointformula tt
