                     util_pg.get_pointname(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), 0, 0) ,
                      util_pg.get_groupname(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))))) vname,
                      DECODE(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), an_mid, editformula_pg.get_ind(an_mid), 1) ind,

                      --0  - TMainForm::iImageList индекс иконки "синяя точка"
                       -- 26 - TMainForm::iImageList индекс иконки "зеленая точка"
                       -- 27 - TMainForm::iImageList индекс иконки "функция"
                      DECODE(util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))), an_mid, DECODE(editformula_pg.get_ind(an_mid), 1, 27, 3, 0, 4, 26), 8) imind
           FROM formulparams p
                WHERE p.nid IN(SELECT nid
                                 FROM pointformula f
                                WHERE f.mid = an_param
                                )
            and  util_pg.allnumber_f(TRIM(util_pg.get_param(p.vparam, 2, '.'))) IN (SELECT DISTINCT param
    --   OR   p.mid   IN (SELECT DISTINCT mid
                                   FROM (SELECT tt.mid, util_pg.allnumber_f(TRIM(util_pg.get_param(t.vparam, 2, '.'))) param, t.nid
                                                                              FROM formulparams t, pointformula tt
                                                                             WHERE tt.nid = t.nid and t.mid is null) mm
                                                                CONNECT BY PRIOR mm.mid = mm.param      --mm.param=mm.mid
                                                                START WITH mm.param
                                                                 IN (
                                                                  select gid from operatingday
                                                                where gid in (
                                                                SELECT gid FROM GROUPS
                                                                CONNECT BY PRIOR parent=gid
                                                                START WITH mid = an_mid))
                                    --                                UNION ALL
                                --   SELECT an_mid
                                -- FROM DUAL*/
  END IF;
 /* SELECT distinct 1 havechilde, tab.mid, tab.param,(poi_t.NAME || ' (' || tab.mid || ')') text, poi_t.ind
    FROM (SELECT pf.nid, pf.mid, util_pg.get_param(fp.vparam, 2, '.') param, fp.vparam, fp.vname
            FROM pointformula pf, formulparams fp
           WHERE pf.nid = fp.nid) tab,
         points poi_t
   WHERE tab.param = an_mid AND poi_t.mid = tab.mid AND EXISTS(SELECT *
                                                                 FROM formulparams fp
                                                                WHERE util_pg.get_param(fp.vparam, 2, '.') = tab.mid)
  UNION ALL
  SELECT distinct 0 havechilde, tab.mid, tab.param,(poi_t.NAME || ' (' || tab.mid || ')') text, poi_t.ind
    FROM (SELECT pf.nid, pf.mid, util_pg.get_param(fp.vparam, 2, '.') param, fp.vparam, fp.vname
            FROM pointformula pf, formulparams fp
           WHERE pf.nid = fp.nid) tab,
         points poi_t
   WHERE tab.param = an_mid AND poi_t.mid = tab.mid AND NOT EXISTS(SELECT *
                                                                     FROM formulparams fp
                                                                    WHERE util_pg.get_param(fp.vparam, 2, '.') =
                                                                                                                tab.mid);*/
