---------------------------------------------------------------------------------------------
 FUNCTION get_ind(an_mid NUMBER)
  RETURN NUMBER IS
  ln_ind              NUMBER;
 BEGIN
  SELECT MAX(ncalcpointtype)
  INTO   ln_ind
  FROM   feeders
  WHERE  mid = an_mid;

  IF (ln_ind = 6) THEN
   RETURN 1;
  ELSE
   SELECT MAX(ind)
   INTO   ln_ind
   FROM   points
   WHERE  mid = an_mid;

   RETURN ln_ind;
  END IF;
 END;

------------------------------------------------------------------------------------------
--Создание формулы из группы
 PROCEDURE create_formula_from_group(an_mid NUMBER, an_gid NUMBER) IS
  ln_cnt              NUMBER := 0;
  lv_formula          VARCHAR2(2000) := 'a1';
  lt_name             common_pg.tt_varchar2;
  lt_param            common_pg.tt_varchar2;
  lt_memo             common_pg.tt_varchar2;
  lt_shift            common_pg.tt_varchar2;
 BEGIN
  FOR lc IN (SELECT     mid, DECODE(inverted, 'y', 'AI', 'A') param, NAME
             FROM       GROUPS
             WHERE      mid > 0
             CONNECT BY PRIOR gid = PARENT
             START WITH gid = an_gid) LOOP
   ln_cnt := ln_cnt + 1;

   IF ln_cnt > 1 THEN
    lv_formula := lv_formula || '+a' || ln_cnt;
   END IF;

   lt_name(ln_cnt) := 'a' || ln_cnt;
   lt_param(ln_cnt) := 'MID.' || lc.mid || '.' || lc.param;
   lt_memo(ln_cnt) := 'Автоматически определяемое';
   lt_shift(ln_cnt) := 0;
  END LOOP;

  IF ln_cnt > 0 THEN
   UPDATE feeders
   SET ncalcpointtype = 6
   WHERE  mid = an_mid;

   delete_formula(an_mid);
   save_formula(an_mid, 0, lv_formula, 'Автогенерация по группе Ид.=' || an_gid, 0, 0, lt_name, lt_param, lt_memo, lt_shift);
  ELSE
   raise_application_error(-20001, 'Указанная группа не содержит точек.');
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                             -- Package Body
/


