PACKAGE BODY editgroups_pg IS
 -- пакет работы с группами
 -- дата создания 29/10/2001 (Сечин А.А.)
 gn_task_code        NUMBER DEFAULT 10;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки (общая)
 PROCEDURE ins_p_all(
 an_askue NUMBER,                                                                                                        --1-изменения из АСКУЭ, иначе из АСРПП
                 an_parent NUMBER,                                                                                                                   --Родитель
                                  av_name VARCHAR2,                                                                                                  --Название
                                                   av_short_name VARCHAR2,                                                                   --Краткое название
                                                                          an_mid NUMBER,                                                             --Ид точки
                                                                                        an_limit_id NUMBER,                                         --Ид лимита
                                                                                                           an_inverted NUMBER,         --Признак инвертирования
 an_group_total NUMBER,                                                                                                        --Признак суммирования по группе
                       an_root1 NUMBER,                                                                                                       --Ид группы прома
                                       an_root2 NUMBER,                                                                                       --Ид группы прома
                                                       an_emergencyreserve NUMBER,                                                            --Аварийная бронь
                                                                                  an_technologyreserve NUMBER,                          --Технологическая бронь
                                                                                                              av_param VARCHAR2,                 --Доп параметр
 an_partly NUMBER,                                                                                                                   --Признак частичного вхожд
                  an_fromperiod NUMBER,                                                                                                              --Период с
                                       an_tillperiod NUMBER,                                                                                        --Период по
                                                            an_ndirection NUMBER,                                                              --коеф.вхождения
                                                                                 an_gid OUT NUMBER                                                  --Ид группы
 ) IS
  ln_gid              NUMBER;
 BEGIN
  adminadd_pg.check_right(ln_gid, an_parent, 2, 2);

  SELECT groups_seq.NEXTVAL
  INTO   ln_gid
  FROM   DUAL;

  an_gid := ln_gid;

  INSERT INTO GROUPS
              (gid, PARENT, NAME, short_name, mid, inverted, group_total, nroot1, nroot2, nemergencyreserve, ntechnologyreserve, vparam, npartly, nfromperiod,
               ntillperiod, nkc)
  VALUES      (ln_gid, an_parent, av_name, av_short_name, an_mid, DECODE(an_mid, NULL, 'n', DECODE(an_inverted, 1, 'y', 'n')),
               DECODE(ABS(SIGN(an_mid)), 1, 'n', DECODE(an_askue, 1, DECODE(an_group_total, 1, 'y', 'n'), 'y')), an_root1, an_root2, an_emergencyreserve,
               an_technologyreserve, av_param, an_partly, NVL(an_fromperiod, 190001), an_tillperiod, an_ndirection);
 /*  IF an_parent IS NULL THEN
    INSERT INTO form_group
                (gid, fid)
     (SELECT ln_gid, fid
        FROM forms
       WHERE codetemplate <> 0);
   END IF;*/
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'editgroups_pg.ins_p: Ошибка вставки группы учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления данных (общая)
 PROCEDURE upd_p_all(
 an_askue NUMBER,                                                                                                         --1-изменения из АСКУЭ, иначе из АСРПП
                 an_gid NUMBER,                                                                                                                      --Ид группы
                               an_parent NUMBER,                                                                                                      --Родитель
                                                av_name VARCHAR2,                                                                                     --Название
                                                                 av_short_name VARCHAR2,                                                      --Краткое название
                                                                                        an_limit_id NUMBER,                                          --Ид лимита
                                                                                                           an_inverted NUMBER,          --Признак инвертирования
 an_group_total NUMBER,                                                                                                         --Признак суммирования по группе
                       an_emergencyreserve NUMBER,                                                                                             --Аварийная бронь
                                                  an_technologyreserve NUMBER,                                                           --Технологическая бронь
                                                                              av_param VARCHAR2,                                                  --Доп параметр
                                                                                                an_partly NUMBER,                          --частичное вхождение
                                                                                                                 an_fromperiod NUMBER,                --Период с
 an_tillperiod NUMBER,                                                                                                                               --Период по
                      an_ndirection NUMBER                                                                                                      --коеф.вхождения
 ) IS
 BEGIN
  adminadd_pg.check_right(an_gid, an_parent, 2, 2);

  IF util_pg.get_customer_id = 1 AND an_askue = 1 THEN                                                                                                    --ХЭС
   UPDATE GROUPS
   SET group_total = DECODE(ABS(SIGN(mid)), 1, 'n', DECODE(an_askue, 1, DECODE(an_group_total, 1, 'y', 'n'), group_total)),
       vparam = av_param
   WHERE  gid = an_gid;
  ELSE
   UPDATE GROUPS
   SET PARENT = an_parent,
       NAME = av_name,
       short_name = av_short_name,
       inverted = DECODE(mid, NULL, 'n', DECODE(an_inverted, 1, 'y', 'n')),
       group_total = DECODE(ABS(SIGN(mid)), 1, 'n', DECODE(an_askue, 1, DECODE(an_group_total, 1, 'y', 'n'), group_total)),
       nemergencyreserve = DECODE(an_askue, 1, an_emergencyreserve, nemergencyreserve),
       ntechnologyreserve = DECODE(an_askue, 1, an_technologyreserve, ntechnologyreserve),
       vparam = DECODE(an_askue, 1, av_param, vparam),
       npartly = an_partly,
       nfromperiod = NVL(an_fromperiod, 190001),
       ntillperiod = an_tillperiod,
       nkc = an_ndirection
   WHERE  gid = an_gid;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'editgroups_pg.upd_p: Ошибка обновления группы учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

