  -- Процедура вставки
 PROCEDURE ins_p(
 an_parent NUMBER,                                                                                                                                   --Ро7дитель
                  av_name VARCHAR2,                                                                                                                   --Название
                                   av_short_name VARCHAR2,                                                                                    --Краткое название
                                                          an_mid NUMBER,                                                                              --Ид точки
                                                                        an_limit_id NUMBER,                                                          --Ид лимита
                                                                                           an_inverted NUMBER,                          --Признак инвертирования
                                                                                                              an_group_total NUMBER,
                                                                                                                                    --Признак суммирования по группе
                                                                                                                                    an_emergencyreserve NUMBER,
 --Аварийная бронь
 an_technologyreserve NUMBER,                                                                                                            --Технологическая бронь
                             av_param VARCHAR2,                                                                                                   --Доп параметр
                                               an_partly NUMBER,                                                                      --Признак частичного вхожд
