                                                                                     an_tillperiod NUMBER,                                           --Период по
                                                                                                          an_gid OUT NUMBER                          --Ид группы
 ) IS
 BEGIN
  SAVEPOINT editgroups_ins;
  ins_p_all(1, an_parent, av_name, av_short_name, an_mid, an_limit_id, an_inverted, an_group_total, NULL, NULL, an_emergencyreserve, an_technologyreserve,
