------------------------------------------------------------------------------------------------------------------------
   -- Процедура изменения лимитов по группе
 PROCEDURE updlimit_p(
 an_gid NUMBER,                                                                                                                                      --Ид группы
               at_start common_pg.tt_varchar2,                                                                                           --Дата ввода в действие
                                              at_limitcons common_pg.tt_number,                                                                    --Потребление
                                                                               at_limitcapm common_pg.tt_number,                                 --Нагрузка утро
 at_limitcape common_pg.tt_number                                                                                                               --Нагрузка вечер
 ) IS
  lt_tmp              common_pg.tt_varchar2;
 BEGIN
  FOR i IN 1 .. at_start.COUNT LOOP
   lt_tmp(i) := NULL;
  END LOOP;

  updlimit_p(an_gid, at_start, at_limitcons, at_limitcapm, at_limitcape, lt_tmp, lt_tmp, lt_tmp, lt_tmp);
 END;

------------------------------------------------------------------------------------------------------------------------
     -- Процедура изменения лимитов по группе
 PROCEDURE updlimit_p(
 an_gid NUMBER,                                                                                                                                      --Ид группы
               at_start common_pg.tt_varchar2,                                                                                           --Дата ввода в действие
                                              at_limitcons common_pg.tt_number,                                                                    --Потребление
                                                                               at_limitcapm common_pg.tt_number,                                 --Нагрузка утро
 at_limitcape common_pg.tt_number,                                                                                                              --Нагрузка вечер
                                  at_morning_start common_pg.tt_varchar2,                                                                             --Утро нач
                                                                         at_morning_end common_pg.tt_varchar2,                                        --Утро кон
                                                                                                              at_evening_start common_pg.tt_varchar2,
 --Вечер нач
 at_evening_end common_pg.tt_varchar2                                                                                                                --Вечер кон
 ) IS
 BEGIN
  SAVEPOINT editgroups_updlimit;

  DELETE FROM grouplimit
  WHERE       gid = an_gid;

  IF at_start.COUNT > 0 AND LENGTH(at_start(1)) > 0 THEN
   FOR i IN 1 .. at_start.COUNT LOOP
    INSERT INTO grouplimit
                (gid, dstart, nlimitcons, nlimitcapm, nlimitcape, morning_start, morning_end, evening_start, evening_end)
    VALUES      (an_gid, TO_DATE(at_start(i), 'dd.mm.yyyy'), at_limitcons(i), at_limitcapm(i), at_limitcape(i),
                 TO_DATE(at_morning_start(i), 'dd.mm.yyyy hh24:mi:ss'), TO_DATE(at_morning_end(i), 'dd.mm.yyyy hh24:mi:ss'),
                 TO_DATE(at_evening_start(i), 'dd.mm.yyyy hh24:mi:ss'), TO_DATE(at_evening_end(i), 'dd.mm.yyyy hh24:mi:ss'));
   END LOOP;
  END IF;

  admin_pg.fiscal_p(gn_task_code, 2, 'Изменены лимиты для группы ' || util_pg.node_path_f(an_gid, 'groups', 'gid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editgroups_updlimit;
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE find_node(an_gid NUMBER, acur_t OUT common_pg.tcur) IS
 -- путь к точке начиная с коренного узла
 BEGIN
  OPEN acur_t FOR
   SELECT   gid
   FROM     (SELECT     ROWNUM n, gid
             FROM       GROUPS
             CONNECT BY PRIOR PARENT = gid
             START WITH gid = an_gid)
   ORDER BY n DESC;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE readnodegroup_p(an_gid NUMBER, acur_t OUT common_pg.tcur) IS
 -- дерево групп
 BEGIN
  IF an_gid IS NULL THEN
   OPEN acur_t FOR
    SELECT   1 havechild, gid, NVL(mid, 0) ind, NAME, short_name, nemergencyreserve, ntechnologyreserve, 0 nlimits, DECODE(group_total, 'y', 1, 0) nsum,
             DECODE(inverted, 'y', 1, 0) inverted, DECODE(mid, NULL, 0, 1), util_pg.get_pointname(mid, 2) infoarea, vparam, npartly, nfromperiod, ntillperiod,
             NVL(nkc, 1) kc
    FROM     GROUPS g
    WHERE    PARENT IS NULL AND EXISTS(SELECT *
                                       FROM   GROUPS
                                       WHERE  PARENT = g.gid)
    UNION ALL
    SELECT   0 havechild, gid, NVL(mid, 0) ind, NAME, short_name, nemergencyreserve, ntechnologyreserve, 0 nlimits, DECODE(group_total, 'y', 1, 0) nsum,
             DECODE(inverted, 'y', 1, 0) inverted, DECODE(mid, NULL, 0, 1), util_pg.get_pointname(mid, 2) infoarea, vparam, npartly, nfromperiod, ntillperiod,
             NVL(nkc, 1) kc
    FROM     GROUPS g
    WHERE    PARENT IS NULL AND NOT EXISTS(SELECT *
                                           FROM   GROUPS
                                           WHERE  PARENT = g.gid)
    ORDER BY 11, 4;
  ELSE
   OPEN acur_t FOR
    SELECT   1 havechild, gid, NVL(mid, 0) ind, NAME, short_name, nemergencyreserve, ntechnologyreserve, 0 nlimits, DECODE(group_total, 'y', 1, 0) nsum,
             DECODE(inverted, 'y', 1, 0) inverted, DECODE(mid, NULL, 0, 1), util_pg.get_pointname(mid, 2) infoarea, vparam, npartly, nfromperiod, ntillperiod,
             NVL(nkc, 1) kc
    FROM     GROUPS g
    WHERE    PARENT = an_gid AND EXISTS(SELECT *
                                        FROM   GROUPS
                                        WHERE  PARENT = g.gid)
    UNION ALL
    SELECT   0 havechild, gid, NVL(mid, 0) ind, NAME, short_name, nemergencyreserve, ntechnologyreserve, 0 nlimits, DECODE(group_total, 'y', 1, 0) nsum,
             DECODE(inverted, 'y', 1, 0) inverted, DECODE(mid, NULL, 0, 1), util_pg.get_pointname(mid, 2) infoarea, vparam, npartly, nfromperiod, ntillperiod,
             NVL(nkc, 1) kc
    FROM     GROUPS g
    WHERE    PARENT = an_gid AND NOT EXISTS(SELECT *
                                            FROM   GROUPS
                                            WHERE  PARENT = g.gid)
    ORDER BY 11, 4;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------------
 PROCEDURE readnodepoints_p(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- дерево точек
 BEGIN
  IF an_mid IS NULL THEN
   OPEN acur_t FOR
    SELECT   1 havechild, mid gid, DECODE(p.ind, 1, 0, 2, 0, 3, 3, 600, 6, 610, 8, 500, 7, 620, 9, 4) ind, p.norder,
             DECODE(p.ind, 1, DECODE(p.cod, 0, 1, 1000), 2, DECODE(p.cod, 0, 1, 1000), 3, 3, 4, 3, 600, 6, 610, 8, 500, 5, 620, 9) tt, NAME, short_name
    FROM     points p
    WHERE    p.mid IN(SELECT *
                      FROM   TABLE(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid))) AND EXISTS(SELECT *
                                                                                            FROM   points
                                                                                            WHERE  PARENT = p.mid)
    UNION ALL
    SELECT   0 havechild, mid gid, DECODE(p.ind, 1, 0, 2, 0, 3, 3, 600, 6, 610, 8, 500, 7, 620, 9, 4) ind, p.norder,
             DECODE(p.ind, 1, DECODE(p.cod, 0, 1, 1000), 2, DECODE(p.cod, 0, 1, 1000), 3, 3, 4, 3, 600, 6, 610, 8, 500, 5, 620, 9) tt, NAME, short_name
    FROM     points p
    WHERE    p.mid IN(SELECT *
                      FROM   TABLE(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid))) AND NOT EXISTS(SELECT *
                                                                                                FROM   points
                                                                                                WHERE  PARENT = p.mid)
    ORDER BY 4, 5, 6;
  ELSE
  	IF adminadd_pg.check_accread(an_mid)=0 THEN
				raise_application_error(-20002, 'В доступе отказано. an_id='||an_mid);  	
			END IF;

   OPEN acur_t FOR
    SELECT   1 havechild, mid gid, DECODE(p.ind, 1, 0, 2, 0, 3, 3, 600, 6, 610, 8, 500, 7, 620, 9, 4) ind, p.norder,
             DECODE(p.ind, 1, DECODE(p.cod, 0, 1, 1000), 2, DECODE(p.cod, 0, 1, 1000), 3, 3, 4, 3, 600, 6, 610, 8, 500, 5, 620, 9) tt, NAME, short_name
    FROM     points p
    WHERE    p.PARENT = an_mid AND EXISTS(SELECT *
                                          FROM   points
                                          WHERE  PARENT = p.mid)
    UNION ALL
    SELECT   0 havechild, mid gid, DECODE(p.ind, 1, 0, 2, 0, 3, 3, 600, 6, 610, 8, 500, 7, 620, 9, 4) ind, p.norder,
             DECODE(p.ind, 1, DECODE(p.cod, 0, 1, 1000), 2, DECODE(p.cod, 0, 1, 1000), 3, 3, 4, 3, 600, 6, 610, 8, 500, 5, 620, 9) tt, NAME, short_name
    FROM     points p
    WHERE    p.PARENT = an_mid AND NOT EXISTS(SELECT *
                                              FROM   points
                                              WHERE  PARENT = p.mid)
    ORDER BY 4, 5, 6;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------
 PROCEDURE readlimit_p(an_gid NUMBER, acur_t OUT common_pg.tcur) IS
 -- лимиты
 BEGIN
  IF an_gid IS NULL THEN
   OPEN acur_t FOR
    SELECT   l.gid, TO_CHAR(l.dstart, 'dd.mm.yyyy') date_limit, l.nlimitcons, l.nlimitcapm, l.nlimitcape, TO_CHAR(l.morning_start, 'hh24:mi') stmot,
             TO_CHAR(l.morning_end, 'hh24:mi') enmot, TO_CHAR(l.evening_start, 'hh24:mi') stevt, TO_CHAR(l.evening_end, 'hh24:mi') enevt
    FROM     grouplimit l, GROUPS g
    WHERE    g.PARENT IS NULL AND g.gid = l.gid
    ORDER BY DECODE(g.mid, NULL, 0, 1), g.NAME, l.dstart DESC;
  ELSE
   OPEN acur_t FOR
    SELECT   l.gid, TO_CHAR(l.dstart, 'dd.mm.yyyy') date_limit, l.nlimitcons, l.nlimitcapm, l.nlimitcape, TO_CHAR(l.morning_start, 'hh24:mi') stmot,
             TO_CHAR(l.morning_end, 'hh24:mi') enmot, TO_CHAR(l.evening_start, 'hh24:mi') stevt, TO_CHAR(l.evening_end, 'hh24:mi') enevt
    FROM     grouplimit l, GROUPS g
    WHERE    g.PARENT = an_gid AND g.gid = l.gid
    ORDER BY DECODE(g.mid, NULL, 0, 1), g.NAME, l.dstart DESC;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------------
 PROCEDURE submenu_p(an_fid NUMBER, an_role NUMBER, an_gid NUMBER, acur_t OUT common_pg.tcur) IS
 -- меню
 BEGIN
  IF an_fid IS NULL THEN
   OPEN acur_t FOR
    SELECT DISTINCT DECODE(f.codetemplate, NULL, 1, 0) CHILD, f.fid, f.codetemplate, f.nameform, f.commentform, f.enablecontrols, f.stepprofile, f.namealert,
                    f.vprocname
    FROM            forms f
    WHERE           f.PARENT IS NULL AND f.monitor = an_role
    CONNECT BY      PRIOR f.PARENT = f.fid
    START WITH      f.monitor = an_role AND f.fid IN(SELECT fid
                                                     FROM   form_group
                                                     WHERE  gid IN(SELECT     gid
                                                                   FROM       GROUPS
                                                                   CONNECT BY PRIOR PARENT = gid
                                                                   START WITH gid = an_gid))
    ORDER BY        1, f.nameform DESC;
  ELSE
   OPEN acur_t FOR
    SELECT DISTINCT DECODE(f.codetemplate, NULL, 1, 0) CHILD, f.fid, f.codetemplate, f.nameform, f.commentform, f.enablecontrols, f.stepprofile, f.namealert,
                    f.vprocname
    FROM            forms f
    WHERE           f.PARENT = an_fid AND f.monitor = an_role
    CONNECT BY      PRIOR f.PARENT = f.fid
    START WITH      f.monitor = an_role AND f.fid IN(SELECT fid
                                                     FROM   form_group
                                                     WHERE  gid IN(SELECT     gid
                                                                   FROM       GROUPS
                                                                   CONNECT BY PRIOR PARENT = gid
                                                                   START WITH gid = an_gid))
    ORDER BY        1, f.nameform DESC;
  END IF;
 END;
----------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                             -- Package Body
/


