CREATE OR REPLACE 
PACKAGE BODY edittransformer_line_pg IS
-- MODIFICATION HISTORY
-- Person      Date    Comments
-- ---------   ------  ------------------------------------------
-- Kalak       170804  Create
  ------------------------------------------------------------------------------
  ------------------------------------------------------------------------------
  -- Процедуры для работы с силовыми трансформаторами
  ------------------------------------------------------------------------------
   -- процедура вставки силового 2-х обмоточного трансформатора
 PROCEDURE inst2_p(
 av_name VARCHAR2, an_parent NUMBER,                                                                                            -- id Подстанции трансформатора
                                    an_sn NUMBER, an_dpxx NUMBER, an_dpkz NUMBER, an_ixx NUMBER, an_ukz NUMBER, an_workinghours NUMBER, an_fullhours NUMBER,
 an_mid OUT NUMBER                                                                                                                  -- id нового трансформатора
 ) IS
  lv_parent           VARCHAR2(150);
  ln_connectionparam  NUMBER;
 BEGIN
  adminadd_pg.check_right(NULL, an_parent, 1, 2);

  SELECT points_seq.NEXTVAL, p.NAME
  INTO   an_mid, lv_parent
  FROM   points p
  WHERE  p.mid = an_parent;

  SELECT points_seq.NEXTVAL
  INTO   ln_connectionparam
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, NAME, ind)
  VALUES      (an_mid, an_parent, av_name, 600);

  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nsn, ndeltapidling, ndeltapsc, niidling, nusc, nworkinghours, nfullhours)
  VALUES      (ln_connectionparam, an_mid, av_name, an_sn, an_dpxx, an_dpkz, an_ixx, an_ukz, an_workinghours, an_fullhours);

  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлен 2-х обмоточный трансформатор <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.inst2_p: Ошибка при вставке трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 -- процедура изменения силового 2-х обмоточного трансформатора
 PROCEDURE updt2_p(
 an_mid NUMBER,                                                                                                                             -- id трансформатора
               av_name VARCHAR2, an_parent NUMBER,                                                                               -- id Подстанции трансформатора
                                                  an_sn NUMBER, an_dpxx NUMBER, an_dpkz NUMBER, an_ixx NUMBER, an_ukz NUMBER, an_workinghours NUMBER,
 an_fullhours NUMBER
 ) IS
  lv_parent           VARCHAR2(150);
 BEGIN
  adminadd_pg.check_right(an_mid, an_parent, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = an_parent;

  UPDATE points
  SET PARENT = an_parent,
      NAME = av_name
  WHERE  mid = an_mid;

  UPDATE connectionparam
  SET vname = av_name,
      nsn = an_sn,
      ndeltapidling = an_dpxx,
      ndeltapsc = an_dpkz,
      niidling = an_ixx,
      nusc = an_ukz,
      nworkinghours = an_workinghours,
      nfullhours = an_fullhours
  WHERE  mid = an_mid;

  admin_pg.fiscal_p(gn_task_code, 2, 'Изменены параметры трансформатора <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.updt2_p: Ошибка при изменении параметров трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 -- процедура удаления силового 2-х обмоточного трансформатора
 PROCEDURE delt2_p(an_mid NUMBER                                                                                                            -- id трансформатора
                                ) IS
  lv_parent           VARCHAR2(150);
  lv_name             VARCHAR2(150);
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = (SELECT PARENT
                  FROM   points
                  WHERE  mid = an_mid);

  SELECT p.NAME
  INTO   lv_name
  FROM   points p
  WHERE  p.mid = an_mid;

  admin_pg.fiscal_p(gn_task_code, 3, 'Удален трансформатор <' || lv_name || '> на подстанции <' || lv_parent || '>.');

  DELETE FROM points
  WHERE       mid = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.delt2_p: Ошибка при удалении трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 -- процедура вставки силового 3-х обмоточного трансформатора
 PROCEDURE inst3_p(
 av_name VARCHAR2, an_parent NUMBER,                                                                                             -- id Подстанции трансформатора
                                    an_sn NUMBER, an_su NUMBER, an_sm NUMBER, an_sd NUMBER, an_dpxx NUMBER, an_dpkzu NUMBER, an_dpkzm NUMBER, an_dpkzd NUMBER,
 an_ixx NUMBER, an_ukzu NUMBER, an_ukzm NUMBER, an_ukzd NUMBER, an_workinghours NUMBER, an_fullhours NUMBER, an_mid OUT NUMBER       -- id нового трансформатора
 ) IS
  lv_parent           VARCHAR2(150);
  ln_connectionparam1 NUMBER;
  ln_connectionparam2 NUMBER;
  ln_connectionparam3 NUMBER;
 BEGIN
  adminadd_pg.check_right(NULL, an_parent, 1, 2);

  SELECT points_seq.NEXTVAL, p.NAME
  INTO   an_mid, lv_parent
  FROM   points p
  WHERE  p.mid = an_parent;

  SELECT points_seq.NEXTVAL
  INTO   ln_connectionparam1
  FROM   DUAL;

  SELECT points_seq.NEXTVAL
  INTO   ln_connectionparam2
  FROM   DUAL;

  SELECT points_seq.NEXTVAL
  INTO   ln_connectionparam3
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, NAME, ind)
  VALUES      (an_mid, an_parent, av_name, 610);

-- Высокая обмотка
  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nsn, nsh, ndeltapidling, ndeltapsc, niidling, nusc, nworkinghours, nfullhours, nwinding)
  VALUES      (ln_connectionparam1, an_mid, av_name || ' (Высокая)', an_sn, an_su, an_dpxx, an_dpkzu, an_ixx, an_ukzu, an_workinghours, an_fullhours, 1);

-- Средняя обмотка
  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nsn, nsh, ndeltapidling, ndeltapsc, niidling, nusc, nworkinghours, nfullhours, nwinding)
  VALUES      (ln_connectionparam2, an_mid, av_name || ' (Средняя)', NULL, an_sm, NULL, an_dpkzm, NULL, an_ukzm, an_workinghours, an_fullhours, 2);

-- Низкая обмотка
  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nsn, nsh, ndeltapidling, ndeltapsc, niidling, nusc, nworkinghours, nfullhours, nwinding)
  VALUES      (ln_connectionparam3, an_mid, av_name || ' (Низкая)', NULL, an_sd, NULL, an_dpkzd, NULL, an_ukzd, an_workinghours, an_fullhours, 3);

  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлен 3-х обмоточный трансформатор <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.inst3_p: Ошибка при вставке трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
   -- процедура изменения силового 3-х обмоточного трансформатора
 PROCEDURE updt3_p(
 an_mid NUMBER,                                                                                                                            -- id  трансформатора
               av_name VARCHAR2, an_parent NUMBER,                                                                               -- id Подстанции трансформатора
                                                  an_sn NUMBER, an_su NUMBER, an_sm NUMBER, an_sd NUMBER, an_dpxx NUMBER, an_dpkzu NUMBER, an_dpkzm NUMBER,
 an_dpkzd NUMBER, an_ixx NUMBER, an_ukzu NUMBER, an_ukzm NUMBER, an_ukzd NUMBER, an_workinghours NUMBER, an_fullhours NUMBER
 ) IS
  lv_parent           VARCHAR2(150);
 BEGIN
  adminadd_pg.check_right(an_mid, an_parent, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = an_parent;

  UPDATE points
  SET PARENT = an_parent,
      NAME = av_name
  WHERE  mid = an_mid;

-- Высокая обмотка
  UPDATE connectionparam
  SET vname = av_name || ' (Высокая)',
      nsn = an_sn,
      nsh = an_su,
      ndeltapidling = an_dpxx,
      ndeltapsc = an_dpkzu,
      niidling = an_ixx,
      nusc = an_ukzu,
      nworkinghours = an_workinghours,
      nfullhours = an_fullhours
  WHERE  mid = an_mid AND nwinding = 1;

-- Средняя обмотка
  UPDATE connectionparam
  SET vname = av_name || ' (Средняя)',
      nsn = NULL,
      nsh = an_sm,
      ndeltapidling = NULL,
      ndeltapsc = an_dpkzm,
      niidling = NULL,
      nusc = an_ukzm,
      nworkinghours = an_workinghours,
      nfullhours = an_fullhours
  WHERE  mid = an_mid AND nwinding = 2;

-- Низкая обмотка
  UPDATE connectionparam
  SET vname = av_name || ' (Низкая)',
      nsn = NULL,
      nsh = an_sd,
      ndeltapidling = NULL,
      ndeltapsc = an_dpkzd,
      niidling = NULL,
      nusc = an_ukzd,
      nworkinghours = an_workinghours,
      nfullhours = an_fullhours
  WHERE  mid = an_mid AND nwinding = 3;

  admin_pg.fiscal_p(gn_task_code, 2, 'Изменены параметры трансформатора <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.updt3_p: Ошибка при изменении параметров трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
   -- процедура удаления силового 3-х обмоточного трансформатора
 PROCEDURE delt3_p(an_mid NUMBER                                                                                                            -- id трансформатора
                                ) IS
  lv_parent           VARCHAR2(150);
  lv_name             VARCHAR2(150);
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = (SELECT PARENT
                  FROM   points
                  WHERE  mid = an_mid);

  SELECT p.NAME
  INTO   lv_name
  FROM   points p
  WHERE  p.mid = an_mid;

  admin_pg.fiscal_p(gn_task_code, 3, 'Удален трансформатор <' || lv_name || '> на подстанции <' || lv_parent || '>.');

  DELETE FROM points
  WHERE       mid = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.delt3_p: Ошибка при удалении трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

