------------------------------------------------------------------------------
-- Процедуры для работы с реакторами
------------------------------------------------------------------------------
 -- процедура вставки реактора
 PROCEDURE insr_p(
 av_name VARCHAR2, an_parent NUMBER,                                                                                                      -- id Подстанции линии
                                    an_un NUMBER, an_sn NUMBER, an_dp NUMBER, an_workinghours NUMBER, an_fullhours NUMBER,
 an_mid OUT NUMBER                                                                                                                         -- id нового реактора
 ) IS
  lv_parent           VARCHAR2(150);
  ln_connectionparam  NUMBER;
 BEGIN
  adminadd_pg.check_right(NULL, an_parent, 1, 2);

  SELECT points_seq.NEXTVAL, p.NAME
  INTO   an_mid, lv_parent
  FROM   points p
  WHERE  p.mid = an_parent;

  SELECT points_seq.NEXTVAL
  INTO   ln_connectionparam
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, NAME, ind)
  VALUES      (an_mid, an_parent, av_name, 620);

  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nun, nsn, ndeltapsc, nworkinghours, nfullhours)
  VALUES      (ln_connectionparam, an_mid, av_name, an_un, an_sn, an_dp, an_workinghours, an_fullhours);

  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлен реактор <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.insr_p: Ошибка при вставке реактора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
   -- процедура изменения параметров реактора
 PROCEDURE updr_p(
 an_mid NUMBER,                                                                                                                            -- id нового реактора
               av_name VARCHAR2, an_parent NUMBER,                                                                                        -- id Подстанции линии
                                                  an_un NUMBER, an_sn NUMBER, an_dp NUMBER, an_workinghours NUMBER, an_fullhours NUMBER
 ) IS
  lv_parent           VARCHAR2(150);
 BEGIN
  adminadd_pg.check_right(an_mid, an_parent, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = an_parent;

  UPDATE points
  SET PARENT = an_parent,
      NAME = av_name
  WHERE  mid = an_mid;

  UPDATE connectionparam
  SET vname = av_name,
      nsn = an_sn,
      nun = an_un,
      ndeltapsc = an_dp,
      nworkinghours = an_workinghours,
      nfullhours = an_fullhours
  WHERE  mid = an_mid;

  admin_pg.fiscal_p(gn_task_code, 2, 'Изменены параметры реактора <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.updr_p: Ошибка при изменении параметров реактора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
   -- процедура удаления реактора
 PROCEDURE delr_p(an_mid NUMBER                                                                                                             -- id трансформатора
                               ) IS
  lv_parent           VARCHAR2(150);
  lv_name             VARCHAR2(150);
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = (SELECT PARENT
                  FROM   points
                  WHERE  mid = an_mid);

  SELECT p.NAME
  INTO   lv_name
  FROM   points p
  WHERE  p.mid = an_mid;

  admin_pg.fiscal_p(gn_task_code, 3, 'Удален реактор <' || lv_name || '> на подстанции <' || lv_parent || '>.');

  DELETE FROM points
  WHERE       mid = an_mid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.delr_p: Ошибка при удалении реактора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
-- Процедуры для работы с измерительными трансформаторами
------------------------------------------------------------------------------
 -- процедура удаления измерительных трансформаторов
 PROCEDURE del_p(an_id IN NUMBER                                                                                          -- id'ов для удаляемого трансформатора
                                ) IS
  lv_name             VARCHAR2(256);
  lv_parent           VARCHAR2(256);
  ln_mid              NUMBER;
 BEGIN
  SELECT t.vname, p.NAME, p.mid
  INTO   lv_name, lv_parent, ln_mid
  FROM   transformer t, points p
  WHERE  t.ntransformer = an_id AND t.mid = p.mid;

  adminadd_pg.check_right(ln_mid, NULL, 1, 2);
  admin_pg.fiscal_p(gn_task_code, 3, 'Удален трансформатор <' || lv_name || '> на подстанции <' || lv_parent || '>.');

  DELETE FROM transformer t
  WHERE       t.ntransformer = an_id;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.del_p: Ошибка при удалении трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 -- процедура вставки измерительного трансформатора
 PROCEDURE ins_p(
 an_mid NUMBER,                                                                                                                 -- mid Подстанции трансформатора
               av_name VARCHAR2,                                                                                                      -- Название трансформатора
                                an_type NUMBER,                                                                                            -- Тип трансформатора
                                               ad_indate DATE,                                                                                 -- Дата установки
                                                              an_val1 NUMBER,                                                              -- первичная величина
                                                                             an_val2 NUMBER,                                               -- вторичная величина
                                                                                            an_id OUT NUMBER                         -- id нового трансформатора
 ) IS
  lv_parent           VARCHAR2(2048);
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);

  SELECT points_seq.NEXTVAL, p.NAME
  INTO   an_id, lv_parent
  FROM   points p
  WHERE  p.mid = an_mid;

  INSERT INTO transformer
              (ntransformer, mid, vname, ntype, dinstall, nvalue1, nvalue2)
  VALUES      (an_id, an_mid, av_name, an_type, ad_indate, an_val1, an_val2);

  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлен трансформатор <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.ins_p: Ошибка при вставке трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 -- процедура изменения параметров измерительного трансформатора
 PROCEDURE upd_p(
 an_id NUMBER,                                                                                                                              -- id трансформатора
              an_mid NUMBER,                                                                                                    -- mid Подстанции трансформатора
                            av_name VARCHAR2,                                                                                         -- Название трансформатора
                                             an_type NUMBER,                                                                               -- Тип трансформатора
                                                            ad_indate DATE,                                                                    -- Дата установки
                                                                           an_val1 NUMBER,                                                 -- первичная величина
                                                                                          an_val2 NUMBER                                   -- вторичная величина
 ) IS
  lv_parent           VARCHAR2(2048);
 BEGIN
  adminadd_pg.check_right(an_mid, NULL, 1, 2);

  SELECT p.NAME
  INTO   lv_parent
  FROM   points p
  WHERE  p.mid = an_mid;

  UPDATE transformer
  SET mid = an_mid,
      vname = av_name,
      ntype = an_type,
      dinstall = ad_indate,
      nvalue1 = an_val1,
      nvalue2 = an_val2
  WHERE  ntransformer = an_id;

  admin_pg.fiscal_p(gn_task_code, 2, 'Изменены параметры трансформатора <' || av_name || '> на подстанции <' || lv_parent || '>.');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.upd_p: Ошибка при изменении параметров трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 -- процедура замены измерительного трансформатора
 PROCEDURE change_p(
 an_id NUMBER,                                                                                                                              -- id трансформатора
              ad_indate DATE,                                                                                                                  -- Дата установки
                             ad_outdate DATE,                                                                                                     -- Дата замены
                                             an_val1 NUMBER,                                                                  -- первичная величина для уст. тр.
                                                            an_val2 NUMBER                                                    -- вторичная величина для уст. тр.
 ) IS
  lv_name             VARCHAR(2048);
  lv_parent           VARCHAR(2048);
 BEGIN
  SAVEPOINT change_transformers;

  SELECT t.vname, p.NAME
  INTO   lv_name, lv_parent
  FROM   transformer t, points p
  WHERE  t.ntransformer = an_id AND p.mid = t.mid;

  INSERT INTO transformerhistory
              (ntransformer, dinstall, dend, nvalue1, nvalue2)
   SELECT t.ntransformer, ad_indate, ad_outdate, t.nvalue1, t.nvalue2
   FROM   transformer t
   WHERE  t.ntransformer = an_id;

  UPDATE transformer t
  SET t.dinstall = ad_outdate,
      t.nvalue1 = an_val1,
      t.nvalue2 = an_val2
  WHERE  t.ntransformer = an_id;

  admin_pg.fiscal_p(gn_task_code, 1, 'Произведена замена трансформатора <' || lv_name || '> на подстанции <' || lv_parent || '>.');
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT change_transformers;
   raise_application_error(-20001, 'EDITTRANSFORMER_PG.change_p: Ошибка при замене трансформатора.' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------
 PROCEDURE readnode_p(an_mid NUMBER, an_parent NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF an_parent IS NOT NULL THEN
   IF adminadd_pg.check_accread(an_mid)=0 THEN
				raise_application_error(-20002, 'В доступе отказано. an_id='||an_mid);
			END IF;

   OPEN acur_t FOR
    SELECT   1 f_edit, p.mid f_id, p.NAME f_name, 0 f_istrans, 0 f_type, 0 f_val1, 0 f_val2, 0 f_val3, 0 f_val4, 0 f_val5, 0 f_val6, 0 f_val7, 0 f_val8,
             0 f_val9, 0 f_val10, 0 f_val11, 0 f_val12, 0 f_val13, 0 f_val14
    FROM     points p
    WHERE    p.PARENT = an_mid AND p.ind < 3 AND EXISTS(SELECT *
                                                        FROM   points p1
                                                        WHERE  p1.PARENT = p.mid AND p1.ind /*IN (500,600,610,620))--*/ NOT IN(3, 4))
    UNION ALL
    -- Выбор узлов без детей
    SELECT   0 havechild, p.mid, p.NAME, 0 transformer, 0 TYPE, 0 f_val1, 0 f_val2, 0 f_val3, 0 f_val4, 0 f_val5, 0 f_val6, 0 f_val7, 0 f_val8, 0 f_val9,
             0 f_val10, 0 f_val11, 0 f_val12, 0 f_val13, 0 f_val14
    FROM     points p
    WHERE    p.PARENT = an_mid AND p.ind < 3 AND NOT EXISTS(SELECT *
                                                            FROM   points p1
                                                            WHERE  p1.PARENT = p.mid AND p1.ind /*IN (500,600,610,620))--*/ NOT IN(3, 4))
    UNION ALL
    -- Выбор двухобмоточных трансформаторов
    SELECT   0 f_edit, p.mid f_id, p.NAME f_name, 1 f_istrans, DECODE(p.ind, 600, 3, 610, 4, 500, 5, 620, 6, 0) f_type, cp.nsn f_sn, cp.ndeltapidling f_dpxx,
             cp.ndeltapsc f_dpkz, cp.niidling f_ixx, cp.nusc f_ukz, cp.nworkinghours f_whours, cp.nfullhours f_fhours, 0 f_val8, 0 f_val9, 0 f_val10,
             0 f_val11, 0 f_val12, 0 f_val13, 0 f_val14
    FROM     connectionparam cp, points p
    WHERE    p.PARENT = an_mid AND p.ind = 600 AND cp.mid = p.mid
    UNION ALL
    -- Выбор трехобмоточных трансформаторов
    SELECT   0 f_edit, p.mid f_id, p.NAME f_name, 1 f_istrans, DECODE(p.ind, 600, 3, 610, 4, 500, 5, 620, 6, 0) f_type, cp1.nsn f_sn, cp1.nsh f_su,
             cp2.nsh f_sm, cp3.nsh f_sd, cp1.ndeltapidling f_dpxx, cp1.ndeltapsc f_dpkzu, cp2.ndeltapsc f_dpkzm, cp3.ndeltapsc f_dpkzd, cp1.niidling f_ixx,
             cp1.nusc f_ukzu, cp2.nusc f_ukzm, cp3.nusc f_ukzd, cp1.nworkinghours f_whours, cp1.nfullhours f_fhours
    FROM     connectionparam cp1, connectionparam cp2, connectionparam cp3, points p
    WHERE    p.PARENT = an_mid AND p.ind = 610 AND cp1.mid = p.mid AND cp1.nwinding = 1 AND cp2.mid = p.mid AND cp2.nwinding = 2 AND cp3.mid = p.mid
             AND cp3.nwinding = 3
    UNION ALL
    -- Выбор линий
    SELECT   0 f_edit, p.mid f_id, p.NAME f_name, 1 f_istrans, DECODE(p.ind, 600, 3, 610, 4, 500, 5, 620, 6, 0) f_type, cp.nro f_ro, cp.nxo f_xo, cp.nl f_l,
             cp.nun f_un, 0 f_val5, 0 f_val6, 0 f_val7, 0 f_val8, 0 f_val9, 0 f_val10, 0 f_val11, 0 f_val12, 0 f_val13, 0 f_val14
    FROM     connectionparam cp, points p
    WHERE    p.PARENT = an_mid AND p.ind = 500 AND cp.mid = p.mid
    UNION ALL
    -- Выбор реактора
    SELECT   0 f_edit, p.mid f_id, p.NAME f_name, 1 f_istrans, DECODE(p.ind, 600, 3, 610, 4, 500, 5, 620, 6, 0) f_type, cp.nun f_un, cp.nsn f_sn,
             cp.ndeltapsc f_dp, cp.nworkinghours f_fhours, cp.nfullhours f_chours, 0 f_val6, 0 f_val7, 0 f_val8, 0 f_val9, 0 f_val10, 0 f_val11, 0 f_val12,
             0 f_val13, 0 f_val14
    FROM     connectionparam cp, points p
    WHERE    p.PARENT = an_mid AND p.ind = 620 AND cp.mid = p.mid
    ORDER BY 4, 3;
  ELSE
   OPEN acur_t FOR
    SELECT 1 f_edit, mid f_id, NAME f_name, 0 f_istrans, 0 f_type, 0 f_val1, 0 f_val2, 0 f_val3, 0 f_val4, 0 f_val5, 0 f_val6, 0 f_val7, 0 f_val8, 0 f_val9,
           0 f_val10, 0 f_val11, 0 f_val12, 0 f_val13, 0 f_val14
    FROM   points
    WHERE  mid IN(SELECT *
                  FROM   TABLE(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid)));
  END IF;
 END;

----------------------------------------------------------------------------------------------------------------
 PROCEDURE calclossparam_p(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   nconnectionparam
   FROM     connectionparam
   WHERE    mid = an_mid
   ORDER BY nwinding;
 END;

-------------------------------------------------------------------------------------------------------------
 PROCEDURE worktime_p(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   naccperiod, nworkinghours, nfullhours
   FROM     pointfullhours
   WHERE    mid = an_mid
   ORDER BY 1 DESC;
 END;
--------------------------------------------------------------------------------------------------------------
END;
