 PROCEDURE get_meterstreeroot(acur_t OUT common_pg.tcur) IS                                                         -- первичное дерево(SelectPoint->OraQuery1)
 BEGIN
  OPEN acur_t FOR
   SELECT   1 havechild, p.mid, DECODE(p.ind, 1, 0, 2, 0, 3, 1, 5) TYPE, p.norder, DECODE(p.ind, 1, 0, 2, 0, 5) tt, p.NAME, f.kc, NVL(f.ninverted, 0)
                                                                                                                                                     ninverted
   FROM     points p, feeders f
   WHERE    p.cod = 0 AND p.mid IN(SELECT *
                                   FROM   TABLE(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid))) AND EXISTS(SELECT *
                                                                                                            FROM   points
                                                                                                            WHERE  PARENT = p.mid AND cod = 0) AND p.mid = f.mid(+)
   UNION ALL
   SELECT   0 havechild, p.mid, DECODE(p.ind, 1, 0, 2, 0, 3, 1, 5) TYPE, p.norder, DECODE(p.ind, 1, 0, 2, 0, 5) tt, p.NAME, f.kc, NVL(f.ninverted, 0)
                                                                                                                                                     ninverted
   FROM     points p, feeders f
   WHERE    p.cod = 0 AND p.mid IN(SELECT *
                                   FROM   TABLE(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid))) AND NOT EXISTS(SELECT *
                                                                                                                FROM   points
                                                                                                                WHERE  PARENT = p.mid AND cod = 0)
            AND p.mid = f.mid(+)
   ORDER BY norder, tt, NAME;
 END;

-----------------------------------------------------------------------------
 PROCEDURE get_meterstreechilds(an_parent NUMBER,                                                                                                  --ид.родителя
                                                 acur_t OUT common_pg.tcur) IS                                   -- при раскрытии дерева(SelectPoint->OraQuery3)
 BEGIN
  IF adminadd_pg.check_accread(an_parent) = 0 THEN
   raise_application_error(-20002, 'В доступе отказано. an_id=' || an_parent);
  END IF;

  OPEN acur_t FOR
   SELECT   1 havechild, p.mid, DECODE(p.ind, 1, 0, 2, 0, 3, 1, 5) TYPE, p.norder, DECODE(p.ind, 1, 0, 2, 0, 5) tt, p.NAME, f.kc, NVL(f.ninverted, 0) ninverted
   FROM     points p, feeders f
   WHERE    p.cod = 0 AND p.PARENT = an_parent AND EXISTS(SELECT *
                                                          FROM   points
                                                          WHERE  PARENT = p.mid AND cod = 0) AND p.mid = f.mid(+)
   UNION ALL
   SELECT   0 havechild, p.mid, DECODE(p.ind, 1, 0, 2, 0, 3, 1, 5) TYPE, p.norder, DECODE(p.ind, 1, 0, 2, 0, 5) tt, p.NAME, f.kc, NVL(f.ninverted, 0) ninverted
   FROM     points p, feeders f
   WHERE    p.cod = 0 AND p.PARENT = an_parent AND NOT EXISTS(SELECT *
                                                              FROM   points
                                                              WHERE  PARENT = p.mid AND cod = 0) AND p.mid = f.mid(+)
   ORDER BY norder, tt, NAME;
 END;

