 PROCEDURE get_pointslist(acur_t OUT common_pg.tcur) IS                                                        -- список счетчиков(TMainWin1702->OQryPointsList)
  lv_sql              VARCHAR2(8000);
 BEGIN
  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                             --Права на вершину точек
   lv_sql := ' and f.mid in (select * from table (adminadd_pg.getall_accmid)) ';
  END IF;

  lv_sql :=
      'SELECT util_pg.get_pointname(p2.mid, 3, 0) NAME, p2.NAME name_1, p2.mid, f.kc, NVL(f.ninverted, 0) ninverted FROM points p2,feeders f WHERE f.mid = p2.mid(+) '
   || lv_sql--||' and rownum=1 '
   || ' ORDER BY 1, 2,3';

  OPEN acur_t FOR lv_sql;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_passpoints(acur_t OUT common_pg.tcur) IS                                                        -- список счетчиков(TMainWin1702->OQryPassPoints)
  lv_sql              VARCHAR2(8000);
 BEGIN
  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                             --Права на вершину точек
   lv_sql := ' and f.mid in (select * from table (adminadd_pg.getall_accmid)) ';
  END IF;

  lv_sql :=
      'SELECT util_pg.get_pointname(p2.mid, 3, 0) NAME, p2.NAME name_1, util_pg.get_pointparentid(p2.mid) mid, p2.mid mid_1 FROM points p2, feeders f WHERE f.mid = p2.mid(+) '
   || lv_sql
   || ' ORDER BY 1, 2,3';

  OPEN acur_t FOR lv_sql;
 END;

