 PROCEDURE get_passgroups(acur_t OUT common_pg.tcur) IS                                                  -- список групп счетчиков(TMainWin1702->OQryPassGroups)
  lv_sql              VARCHAR2(8000);
 BEGIN
  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                             --Права на вершину точек
   lv_sql := ' and f.mid in (select * from table (adminadd_pg.getall_accmid)) ';
  END IF;

  lv_sql :=
           'SELECT DISTINCT p1.NAME, p1.mid FROM points p1, points p2, feeders f WHERE f.mid = p2.mid(+) AND p2.PARENT = p1.mid(+)' || lv_sql || ' ORDER BY 1,2';

  OPEN acur_t FOR lv_sql;
 END;

-----------------------------------------------------------------------------------------------------------
 PROCEDURE get_currpower(an_wilbiadd NUMBER,                                                                --если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                            acur_t OUT common_pg.tcur) IS                             -- на момент врремени текущие(TMainWin1702->OQryCurrPower)
  lv_sql              VARCHAR2(8000);
 BEGIN
  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                             --Права на вершину точек
   lv_sql := ' and c.mid in (select * from table (adminadd_pg.getall_accmid)) ';
  END IF;

  lv_sql :=
      'SELECT   p1.NAME, p2.NAME, c.date_time, c.mid, c.er, DECODE('
   || nvl(an_wilbiadd,0)
   || ', 1, c.q1, util_pg.sumn(c.q1, c.q2)) q1, c.ed, DECODE('
   || nvl(an_wilbiadd,0)
   || ', 1, c.q3, util_pg.sumn(c.q3, c.q4)) q3, c.q2, c.q4, c.erm, c.q1m, c.edm, c.q3m, c.q2m, c.q4m, c.freq, c.cosf, c.volt, c.volt2,'||
            'c.volt3, c.currento, c.curr2, c.curr3, c.ni0, decode(c.noff,1,''Откл'',0,''Вкл'') voff, c.doff,c.nstatus, c.ntemp '||
   ' FROM curr_power c, points p1, points p2  WHERE c.mid = p2.mid(+) AND p2.PARENT = p1.mid(+) '
   || lv_sql
   || 'ORDER BY 1,2,4';

  OPEN acur_t FOR lv_sql;
 END;

--------------------------------------------------------------------
 PROCEDURE get_profile(
 ad_prdt DATE,                                                                                                         --временная точка среза на осн верхн гран
              an_wilbiadd NUMBER,                                                                           --если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                 av_table NUMBER,                  --таблица для минутных -1 "minutemeas"("profileevid"), для ГН - 2  "hourmeas"("halfhourevid")
 acur_t OUT common_pg.tcur
 ) IS
  -- на момент врремени минутные или ГН(TMainWin1702->OQryProfile,OQryHH)
  lv_tablename        VARCHAR2(100);
  lv_sql              VARCHAR2(8000);
 BEGIN
  IF (av_table = 1) THEN
   lv_tablename := ' profile ';                                                                                                              --название таблицы
  ELSE
   lv_tablename := ' halfhourold ';                                                                                                          --название таблицы
  END IF;

  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                              --Права на вершину точек
   lv_sql := ' and f.mid in (select * from table (adminadd_pg.getall_accmid)) ';
  END IF;

   -- ad_prDT;//временная точка среза на осн верхн гран
  -- an_WilBiAdd; //если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
  -- av_Table;//таблица для минутных - "minutemeas"("profileevid"), для ГН - "hourmeas"("halfhourevid")
  -- Name - Группа учёта (подстанция)
  -- Name_1 - Точка учёта
  -- date_time - Дата, время
  -- mid -- ид.точки
  -- er - Расход A+ [кВтч]
  -- q1 - Расход R+ [кВАрч]
  -- ed - Расход A- [кВтч]
  -- q3 - Расход R- [кВАрч]
  -- q2 - Расход Q2 [кВАрч]
  -- q4 - Расход Q4 [кВАрч]
  -- erm - Показания A+ [кВтч]
  -- q1m - Показания R+ [кВАрч]
  -- edm - Показания A- [кВтч]
  -- q3m - Показания R- [кВАрч]
  -- q2m - Показания Q2M [кВАрч]
  -- q4m - Показания  Q4M [кВАрч]
  -- kc - К. трансф.
  lv_sql :=
      'select  p1.Name, p2.Name, h.mid,
  h.er, h.ed,
  decode(:par2, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1,
  decode(:par2, 1, h.q3, util_pg.sumn(h.q3, h.q4)) q3,
  h.q2, h.q4, h.erm, h.edm,
  decode(:par2, 1, h.q1m, util_pg.sumn(h.q1m, h.q2m)) q1m,
  decode(:par2, 1, h.q3m, util_pg.sumn(h.q3m, h.q4m)) q3m,
  h.q2m, h.q4m,
  f.kc
  FROM
   '
   || lv_tablename
   || ' h , points p1, points p2, feeders f
  WHERE
    f.mid = h.mid AND h.date_time = :par1 AND
    f.mid=p2.mid(+) AND p2.parent=p1.mid(+) '
   || lv_sql
   || ' ORDER BY p1.NAME, p2.NAME';

  OPEN acur_t FOR lv_sql USING an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, ad_prdt;
 END;

------------------------------------------------------------------------
 PROCEDURE get_billormonth(
 ad_prlbdt DATE,                                                                                                                    -- floor( prDT )время начало
                ad_prhbdt DATE,                                                                                                           --prLBDT+1 время конец
                               an_chbzone NUMBER,                                                                                               -- тарифные зоны
                                                 an_wilbiadd NUMBER,                                       -- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                                                    av_table NUMBER,                        -- таблица 3- суточные "bill" или 4-месячные "month"
 acur_t OUT common_pg.tcur
 ) IS
  -- на момент врремени суточные или месячные(TMainWin1702->OQryBill,OQryMonth)
  lv_dattime          VARCHAR2(200);
  lv_tablename        VARCHAR2(2000);                                                                                                        --название таблицы
  lv_sql              VARCHAR2(10000);
 BEGIN
  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                             --Права на вершину точек
   lv_sql := ' where z.mid in (select * from table (adminadd_pg.getall_accmid)) ';
  END IF;

  IF (av_table = 3) THEN
   lv_tablename :=
    ' (select b.date_time,p1.Name p1Name, p2.Name p2Name, b.mid,b.er, b.q1, b.ed, b.q3, b.q2, b.q4, b.erm, b.q1m, b.edm, b.q3m, b.q2m, b.q4m,
b.aer, b.aq1, b.aed, b.aq3, b.aq2, b.aq4, b.aerm, b.aq1m, b.aedm, b.aq3m, b.aq2m, b.aq4m,b.ber, b.bq1, b.bed, b.bq3, b.bq2, b.bq4, b.berm, b.bq1m, b.bedm, b.bq3m, b.bq2m, b.bq4m
,b.cer, b.cq1, b.ced, b.cq3, b.cq2, b.cq4, b.cerm, b.cq1m, b.cedm, b.cq3m, b.cq2m, b.cq4m,b.der, b.dq1, b.ded, b.dq3, b.dq2, b.dq4, b.derm, b.dq1m, b.dedm, b.dq3m, b.dq2m, b.dq4m
,f.kc, b.er_mtrsn,b.denter FROM  billorg b, points p1, points p2, feeders f WHERE f.mid=p2.mid(+) AND p2.parent=p1.mid(+) AND f.mid=b.mid) t ';
   --название таблицы
   lv_dattime := ' to_char( date_time, '' hh24:mi '')  ';                                               --заглушка вместо sysdate д.б.столбец таблицы ddatetime
  ELSE
   lv_tablename :=
    ' (select b.date_time,p1.Name p1Name, p2.Name p2Name, b.mid,b.er, b.q1, b.ed, b.q3, b.q2, b.q4, b.erm, b.q1m, b.edm, b.q3m, b.q2m, b.q4m,b.aer, b.aq1, b.aed, b.aq3, 
b.aq2, b.aq4, b.aerm, b.aq1m, b.aedm, b.aq3m, b.aq2m, b.aq4m,b.ber, b.bq1, b.bed, b.bq3, b.bq2, b.bq4, b.berm, b.bq1m, b.bedm, b.bq3m, b.bq2m, b.bq4m,
b.cer, b.cq1, b.ced, b.cq3, b.cq2, b.cq4, b.cerm, b.cq1m, b.cedm, b.cq3m, b.cq2m, b.cq4m,b.der, b.dq1, b.ded, b.dq3, b.dq2, b.dq4, b.derm, b.dq1m, b.dedm, b.dq3m, b.dq2m, b.dq4m,
f.kc, b.er_mtrsn, b.denter FROM  MONTHSORG b, points p1, points p2, feeders f WHERE f.mid=p2.mid(+) AND p2.parent=p1.mid(+) AND f.mid=b.mid) t ';
   lv_dattime := ' to_char( date_time, '' dd hh24:mi '') ';
  END IF;

  lv_sql :=
      'select * from (select p1Name p11Name, p2Name p21Name, p1Name, p2Name, mid , ''S'', 1, er,
 decode(:par4, 1, q1, util_pg.sumn(q1, q2)) q1,ed, decode(:par4, 1, q3, util_pg.sumn(q3, q4)) q3,
 q2, q4, erm, decode(:par4, 1, q1m, util_pg.sumn(q1m, q2m)) q1m,  edm,  decode(:par4, 1, q3m, util_pg.sumn(q3m, q4m)) q3m, 
 q2m, q4m,TO_CHAR(kc, ''99999990.000'') kc ,er_mtrsn ,'
   || lv_dattime
   || ' date_time_str FROM '
   || lv_tablename
   || ' where t.date_time >= :par1 and t.date_time < :par2 '
   || 'union all
 SELECT '''', '''', p1Name, p2Name, mid, ''A'', 2,aer,decode(:par4, 1, aq1, util_pg.sumn(aq1, aq2)) aq1,      aed,
 decode(:par4, 1, aq3, util_pg.sumn(aq3, aq4)) aq3,aq2, aq4,aerm,decode(:par4, 1, aq1m, util_pg.sumn(aq1m, aq2m)) aq1m,      aedm,
 decode(:par4, 1, aq3m, util_pg.sumn(aq3m, aq4m)) aq3m,      aq2m, aq4m,'''', '''', '''' FROM '
   || lv_tablename
   || ' where t.date_time >= :par1 and t.date_time < :par2  and 1=:par3'
   || ' union all
 SELECT '''', '''', p1Name, p2Name, mid , ''B'', 3 , ber, decode(:par4, 1, bq1, util_pg.sumn(bq1, bq2)) bq1,      bed,
 decode(:par4, 1, bq3, util_pg.sumn(bq3, bq4)) bq3,bq2, bq4, berm,decode(:par4, 1, bq1m, util_pg.sumn(bq1m, bq2m)) bq1m,      bedm,
 decode(:par4, 1, bq3m, util_pg.sumn(bq3m, bq4m)) bq3m,      bq2m, bq4m , '''', '''', '''' FROM '
   || lv_tablename
   || ' where t.date_time >= :par1 and t.date_time < :par2 and 1=:par3 '
   || 'union all
 SELECT '''', '''', p1Name, p2Name, mid, ''C'', 4,cer,decode(:par4, 1, cq1, util_pg.sumn(cq1, cq2)) cq1,ced,
 decode(:par4, 1, cq3, util_pg.sumn(cq3, cq4)) cq3,cq2, cq4, cerm,decode(:par4, 1, cq1m, util_pg.sumn(cq1m, cq2m)) cq1m,cedm,
 decode(:par4, 1, cq3m, util_pg.sumn(cq3m, cq4m)) cq3m,cq2m, cq4m ,'''', '''', '''' FROM '
   || lv_tablename
   || ' where t.date_time >= :par1 and  t.date_time < :par2 and 1=:par3 '
   || 'union all
 SELECT '''', '''', p1Name, p2Name, mid,''D'', 5, der,decode(:par4, 1, dq1, util_pg.sumn(dq1, dq2)) dq1,ded,
 decode(:par4, 1, dq3, util_pg.sumn(dq3, dq4)) dq3,dq2,dq4, derm,decode(:par4, 1, dq1m, util_pg.sumn(dq1m, dq2m)) dq1m,
 dedm,decode(:par4, 1, dq3m, util_pg.sumn(dq3m, dq4m)) dq3m,dq2m, dq4m      ,      '''', '''', '''' FROM     '
   || lv_tablename
   || ' where t.date_time >= :par1 and t.date_time < :par2 and 1=:par3) z '
   || lv_sql
   || ' order by 3, 4, 7';

  OPEN acur_t FOR lv_sql
  USING an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, ad_prlbdt, ad_prhbdt, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, ad_prlbdt, ad_prhbdt,
        an_chbzone, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, ad_prlbdt, ad_prhbdt, an_chbzone, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd,
        ad_prlbdt, ad_prhbdt, an_chbzone, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, ad_prlbdt, ad_prhbdt, an_chbzone;
 END;

--ad_prLBDT - floor( prDT )время начало
--ad_prHBDT -prLBDT+1 время конец
--an_ChBZone - тарифные зоны
--an_WilBiAdd - если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
--av_table - таблица 3- суточные "bill" или 4-месячные "month"
--------------------------------

 ----------------------------------------------------------------------------------------------------------
 PROCEDURE get_maxdt(
 an_table NUMBER,                                                                                                                                  --имя таблицы
                 an_chbsrezishbound NUMBER,                                  --(ChBSrezIsHBound->Checked)?an_ChBSrezIsHBound=1:an_ChBSrezIsHBound=0 показать для
                                           ad_prlbdt DATE,                                                 --период от; если an_ChBSrezIsHBound==0 параметр NULL
                                                          ad_prhbdt DATE,                                   --период до;если an_ChBSrezIsHBound==0 параметр NULL
                                                                         acur_t OUT common_pg.tcur
 ) IS                                                                                      -- возвращает мах дату в таблице в периоде от-до(TMainWin1702->MaxDT)
  lv_tablename        VARCHAR2(40);                                                                                                               --имя таблицы
 BEGIN
  IF (an_table = 1) THEN
   lv_tablename := ' profile ';
  ELSIF(an_table = 2) THEN
   lv_tablename := ' halfhourold ';
  ELSIF(an_table = 3) THEN
   lv_tablename := ' billorg ';
  ELSIF(an_table = 4) THEN
   lv_tablename := ' monthsorg ';
  END IF;

  IF an_chbsrezishbound = 1 THEN
   OPEN acur_t FOR 'select max( date_time ) from ' || lv_tablename || ' where  date_time >:par3  and  date_time <=:par4' USING ad_prlbdt, ad_prhbdt;
  ELSE
   OPEN acur_t FOR 'select max( date_time ) from ' || lv_tablename;
  END IF;
 END;

-------------------------------------------------------------------------------------
 PROCEDURE get_passdt(
 an_id NUMBER,                                                                                                                                        --ид.точки
              ad_prlbdt DATE,                                                                                                                       -- период от
                             ad_prhbdt DATE,                                                                                                        -- период до
                                            an_table NUMBER,                          --имя таблицы 0-"profileevid",1-"halfhourevid",2-"billevid",3-"monthsevid"
 acur_t OUT common_pg.tcur
 ) IS                                                                                      -- возвращает  дату в периоде от-до для точки(TMainWin1702->OQryPass)
  lv_tablename        VARCHAR2(100);
  lv_sql              VARCHAR2(2000);
 BEGIN
  IF (an_table = 0) THEN
   lv_tablename := ' profile ';
  ELSIF(an_table = 1) THEN
   lv_tablename := ' halfhourold ';
  ELSIF(an_table = 2) THEN
   lv_tablename := ' billorg ';
  ELSIF(an_table = 3) THEN
   lv_tablename := ' monthsorg ';
  END IF;

  lv_sql :=
      'select
     h.date_time
     FROM '
   || lv_tablename
   || '
        h
     WHERE
       ( h.mid = :par1 )
    AND
    ( h.date_time >= :par2 )
   AND
    ( h.date_time <= :par3 )
  ORDER BY
    h.date_time';

  OPEN acur_t FOR lv_sql USING an_id, ad_prlbdt, ad_prhbdt;
 END;

-------------------------------------------------------------------------------------------------------
 PROCEDURE get_histprofile(
 an_id NUMBER,                                                                                                                                        --ид.точки
              ad_prlbdt DATE,                                                                                                                        --период от
                             ad_prhbdt DATE,                                                                                                         --период до
                                            an_wilbiadd NUMBER,                                            -- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                                               acur_t OUT common_pg.tcur, an_sort_date NUMBER                  -- 0 - по убыванию (по умолчанию)
 ) IS
  -- в глубину по времени минутные(TMainWin1702->OQryHistProfile)
  lv_sort_date        VARCHAR2(100);
 BEGIN
  IF (an_sort_date = 0) THEN
   lv_sort_date := ' h.date_time desc ';
  ELSE
   lv_sort_date := ' h.date_time ';
  END IF;

  OPEN acur_t FOR    'select
  h.date_time,
  h.mid, h.er, h.ed,
  decode(:par4, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1,
  decode(:par4, 1, h.q3, util_pg.sumn(h.q3,h.q4)) q3,
  h.q2, h.q4, h.erm, h.edm,
  decode(:par4, 1, h.q1m, util_pg.sumn(h.q1m, h.q2m)) q1m,
  decode(:par4, 1, h.q3m, util_pg.sumn(h.q3m,h.q4m)) q3m,
  h.q2m, h.q4m, to_char(h.denter, ''dd.mm.yyyy hh24:mi'') denter,
  TO_NUMBER(NULL) status, h.vqm, '''' metername
  FROM PROFILE h WHERE ( h.mid = :par1 ) AND ( h.date_time >= :par2 ) AND ( h.date_time <= :par3 ) ORDER BY '
                  || lv_sort_date USING an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt;
 END;

----------------------------------------------------------------------------------------------------------------
 PROCEDURE get_histhh(
 an_id NUMBER,                                                                                                                                        --ид.точки
              ad_prlbdt DATE,                                                                                                                        --период от
                             ad_prhbdt DATE,                                                                                                         --период до
                                            an_wilbiadd NUMBER,                                            -- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                                               an_memshowp NUMBER,                       -- if(!cbShowP->Checked)an_MemShowP=0 отображать потери
                                                                                  an_memonlycalc NUMBER,
                                                                                                        --if(ParamsF->MemOnlyCalc)an_MemOnlyCalc=1 только расчетные данные
                                                                                                        acur_t OUT common_pg.tcur,
 an_sort_date NUMBER                                                                                                           -- 0 - по убыванию (по умолчанию)
 ) IS
  lv_sql              VARCHAR2(4000);
  -- в глубину по времени ГН(TMainWin1702->OQryHistHH)
  lv_nsource          VARCHAR2(400);
  lv_nexccalc         VARCHAR2(400);
  lv_sort_date        VARCHAR2(100);
 BEGIN
  IF (an_memshowp = 0) THEN
   lv_nsource := ' and ((nsource>=0 or nsource<-5000) and nsource<>100) ';
  ELSE
   lv_nsource := ' ';
  END IF;

  IF (an_memonlycalc = 1) THEN
   lv_nexccalc := ' and nexceptcalc is null ';
  ELSE
   lv_nexccalc := ' ';
  END IF;

  IF (an_sort_date = 0) THEN
   lv_sort_date := ' h.date_time desc ';
  ELSE
   lv_sort_date := ' h.date_time ';
  END IF;

  lv_sql :=
      
--  OPEN acur_t FOR
      'select h.date_time,h.nsource,h.nexceptcalc, h.mid, h.er, h.ed,
                             decode(:par4, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1,
                             decode(:par4, 1, h.q3, util_pg.sumn(h.q3, h.q4)) q3,
                             h.q2, h.q4, h.erm, h.edm,
                             decode(:par4, 1, h.q1m, util_pg.sumn(h.q1m, h.q2m)) q1m,
                             decode(:par4, 1, h.q3m, util_pg.sumn(h.q3m, h.q4m)) q3m,
                              h.q2m, h.q4m,
                             to_char(h.denter, ''dd.mm.yyyy hh24:mi'') denter,
                             h.status, h.vqm, t.vname metername
                              FROM halfhourold h, metertype t
                             WHERE h.nmetertype=t.nmetertype(+)
                             AND ( h.mid = :par1 )
                             AND ( h.date_time >= :par2 ) AND ( h.date_time <= :par3 )'
   || lv_nsource
   || lv_nexccalc
   || ' order by '
   || lv_sort_date;

--insert into tmp_vil values (lv_sql); commit;
  OPEN acur_t FOR lv_sql USING an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_npterm(
 an_id NUMBER,                                                                                                                                        --ид.точки
              ad_prlbdt DATE,                                                                                                                        --период от
                             ad_prhbdt DATE,                                                                                                         --период до
                                            an_wilbiadd NUMBER,                                            -- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                                               an_memshowp NUMBER,                       -- if(!cbShowP->Checked)an_MemShowP=0 отображать потери
                                                                                  an_memonlycalc NUMBER,
                                                                                                        --if(ParamsF->MemOnlyCalc)an_MemOnlyCalc=1 только расчетные данные
                                                                                                        acur_t OUT common_pg.tcur
 ) IS
  -- терминал профиля нагрузки(TMainWin1702->NPTermOQry)
  lv_nsource          VARCHAR2(400);
  lv_nexccalc         VARCHAR2(400);
 BEGIN
  IF (an_memshowp = 0) THEN
   lv_nsource := ' and ((nsource>=0 or nsource<-5000) and nsource<>100) ';
  ELSE
   lv_nsource := ' ';
  END IF;

  IF (an_memonlycalc = 1) THEN
   lv_nexccalc := ' and nexceptcalc is null ';
  ELSE
   lv_nexccalc := ' ';
  END IF;

  OPEN acur_t FOR    'select h.date_time, h.NSOURCE, h.NEXCEPTCALC, h.mid, h.er,
                             decode(:par4, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1, h.ed,
                             decode(:par4, 1, h.q3, util_pg.sumn(h.q3, h.q4)) q3,h.status, decode(1,2,sysdate) dclosed
                             FROM halfhourold h
                             WHERE ( h.mid = :par1 ) AND ( h.date_time >= :par2 ) AND ( h.date_time <= :par3 ) '
                  || lv_nsource
                  || lv_nexccalc
                  || ' order by h.date_time' USING an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_histbillormonth(
 an_id NUMBER,                                                                                                                                        --ид.точки
              ad_prlbdt DATE,                                                                                                                        --период от
                             ad_prhbdt DATE,                                                                                                         --период до
                                            an_chbzone NUMBER,                                                     -- тарифные зоны    ParamsF->ChBZone->Checked
                                                              an_wilbiadd NUMBER,                          -- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                                                                 an_tablename NUMBER,                --имя таблицы 2-"billevid" , 3-"monthsevid"
 acur_t OUT common_pg.tcur, an_sort_date NUMBER                                                                                -- 0 - по убыванию (по умолчанию)
 ) IS
  -- в глубину по времени суточные(TMainWin1702->OQryHistBill)
  ln_tablename        VARCHAR2(100);
  lv_sort_date        VARCHAR2(100);
 BEGIN
  IF (an_tablename = 2) THEN
   ln_tablename := ' billorg ';
  ELSE
   ln_tablename := ' monthsorg ';
  END IF;

  IF (an_sort_date = 0) THEN
   lv_sort_date := ' 2 desc ';
  ELSE
   lv_sort_date := ' 2 ';
  END IF;

  OPEN acur_t FOR    'select
      to_char( date_time, ''dd.mm.yy   hh24:mi'' ), date_time
      ,
      ''S'', 1,''S'' bb
      ,
      er,
      decode(:par5, 1, q1, util_pg.sumn(q1, q2)) q1,
      ed,
      decode(:par5, 1, q3, util_pg.sumn(q3, q4)) q3,
      q2, q4, erm,
      decode(:par5, 1, q1m, util_pg.sumn(q1m, q2m)) q1m,
      edm,
      decode(:par5, 1, q3m, util_pg.sumn(q3m, q4m)) q3m,
      q2m, q4m, to_char(denter, ''dd.mm.yyyy hh24:mi'') denter
      ,
      er_mtrsn
 FROM
      '
                  || ln_tablename
                  || '
 WHERE
        ( mid = :par1 )
        AND
        (  date_time >= :par2 )
        AND
        (  date_time <= :par3 )
UNION ALL
SELECT
      '''', date_time
      , ''A'', 2,''A'' bb
      ,
      aer,
      decode(:par5, 1, aq1, util_pg.sumn(aq1, aq2)) aq1,
      aed,
      decode(:par5, 1, aq3, util_pg.sumn(aq3, aq4)) aq3,
      aq2, aq4, aerm,
      decode(:par5, 1, aq1m, util_pg.sumn(aq1m, aq2m)) aq1m,
      aedm,
      decode(:par5, 1, aq3m, util_pg.sumn(aq3m, aq4m)) aq3m,
      aq2m, aq4m, to_char(denter, ''dd.mm.yyyy hh24:mi'') denter
      ,
      ''''
 FROM
      '
                  || ln_tablename
                  || '
 WHERE
        ( mid = :par1 )
        AND
        (  date_time >= :par2 )
        AND
        (  date_time <= :par3 )
        AND 1=:par4
UNION ALL
SELECT
      '''', date_time
      , ''B'', 3,''B'' bb
      ,
      ber,
      decode(:par5, 1, bq1, util_pg.sumn(bq1, bq2)) bq1,
      bed,
      decode(:par5, 1, bq3, util_pg.sumn(bq3, bq4)) bq3,
      bq2, bq4, berm,
      decode(:par5, 1, bq1m, util_pg.sumn(bq1m, bq2m)) bq1m,
      bedm,
      decode(:par5, 1, bq3m, util_pg.sumn(bq3m, bq4m)) bq3m,
      bq2m, bq4m, to_char(denter, ''dd.mm.yyyy hh24:mi'') denter
      ,
      ''''
 FROM
      '
                  || ln_tablename
                  || '
 WHERE
        ( mid = :par1 )
        AND
        (  date_time >= :par2 )
        AND
        (  date_time <= :par3 )
        AND 1=:par4
UNION ALL
SELECT
      '''', date_time
      , ''C'', 4,''C'' bb
      ,
      cer,
      decode(:par5, 1, cq1, util_pg.sumn(cq1, cq2)) cq1,
      ced,
      decode(:par5, 1, cq3, util_pg.sumn(cq3, cq4)) cq3,
      cq2, cq4, cerm,
      decode(:par5, 1, cq1m, util_pg.sumn(cq1m, cq2m)) cq1m,
      cedm,
      decode(:par5, 1, cq3m, util_pg.sumn(cq3m, cq4m)) cq3m,
      cq2m, cq4m, to_char(denter, ''dd.mm.yyyy hh24:mi'') denter
      ,
      ''''
 FROM
      '
                  || ln_tablename
                  || '
 WHERE
        ( mid = :par1 )
        AND
        (  date_time >= :par2 )
        AND
        (  date_time <= :par3 )
        AND 1=:par4
UNION ALL
SELECT
      '''', date_time
      ,''D'', 5,''D'' bb
      ,
      der,
      decode(:par5, 1, dq1, util_pg.sumn(dq1, dq2)) dq1,
      ded,
      decode(:par5, 1, dq3, util_pg.sumn(dq3, dq4)) dq3,
      dq2,
      dq4, derm,
      decode(:par5, 1, dq1m, util_pg.sumn(dq1m, dq2m)) dq1m,
      dedm,
      decode(:par5, 1, dq3m, util_pg.sumn(dq3m, dq4m)) dq3m,
      dq2m, dq4m, to_char(denter, ''dd.mm.yyyy hh24:mi'') denter
      ,
      ''''
 FROM
      '
                  || ln_tablename
                  || '
 WHERE
        ( mid = :par1 )
        AND
        (  date_time >= :par2 )
        AND
        (  date_time <= :par3 )
        AND 1=:par4
ORDER BY '
                  || lv_sort_date
                  || ', 4'
  USING an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt,
        ad_prhbdt, an_chbzone, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt, an_chbzone, an_wilbiadd, an_wilbiadd,
        an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt, an_chbzone, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt,
        an_chbzone;
 END;

