 FUNCTION findpoint(an_mid NUMBER, av_name VARCHAR2, av_code VARCHAR2, av_mtrsn VARCHAR2, av_pmid VARCHAR2, av_canal VARCHAR2, av_account VARCHAR2)
  RETURN NUMBER IS
 BEGIN
  --Перенаправил Сечин 26.09.2013
  RETURN editfeeders_pg.findpoint(an_mid, av_name, av_code, av_mtrsn, av_pmid, NULL, av_canal, av_account);
 END;

------------------------------------------------------------------------------
 -- функция возвращает права 0-нет, 1-чтение, 2-изменение
 -- added by KAG 20.11.2008
 FUNCTION get_rights
  RETURN NUMBER IS
  ln_ret              NUMBER DEFAULT 0;
 BEGIN
  SELECT DECODE(USER, 'RYDA', 2, NVL(MAX(rt.nacc + 1), 0))
  INTO   ln_ret
  FROM   role_task rt, tasks t
  WHERE  rt.role_id = (SELECT MAX(role_id)
                       FROM   users
                       WHERE  UPPER(usr) = USER) AND t.task_cod = 630 AND rt.task_id = t.task_id;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------
 -- процедура возвращает измененную в базе метку
 -- added by KAG 25.11.2008
 PROCEDURE set_vqm(an_mid NUMBER, ad_date DATE, an_bit NUMBER, an_bitvalue NUMBER, an_source NUMBER, av_vqm IN OUT VARCHAR2) IS
  lv_ret              VARCHAR2(100);
 BEGIN
  lv_ret := qm_pg.sbt(av_vqm, an_bit, TO_CHAR(an_bitvalue));

  UPDATE halfhourold
  SET vqm = lv_ret
  WHERE  mid = an_mid AND date_time = ad_date AND nsource = an_source;

  av_vqm := lv_ret;
 END;

------------------------------------------------------------------------------
 -- процедура обновляет в базе метку или включение в расчет
 -- added by KAG 25.11.2008
 PROCEDURE upd_vqm_exceptcalc(an_mid NUMBER, ad_date DATE, an_source NUMBER, an_exceptcalc NUMBER, av_vqm VARCHAR2) IS
 BEGIN
  indic_pg.setexceptcalc(an_mid, ad_date, an_source, an_exceptcalc);

  UPDATE halfhourold
  SET vqm = av_vqm
  WHERE  mid = an_mid AND date_time = ad_date AND nsource = an_source;
 END;

--------------------------------------------------------------------------------------------------------------------------
 -- процедура получает текущие значения и параметры качества электроэнергии (КСС)
 -- added by KAG 12.12.2008
 PROCEDURE get_currpowqlt_p(
 an_id NUMBER,                                                                                                                                        --ид точки
              ad_prlbdt DATE,                                                                                                                        --период от
                             ad_prhbdt DATE,                                                                                                         --период до
                                            an_wilbiadd NUMBER,                                            -- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                                               an_sort_date NUMBER,                                            -- 0 - по убыванию (по умолчанию)
                                                                                   acur_t OUT common_pg.tcur
 ) IS
  lv_sort_date        VARCHAR2(100);
 BEGIN
  IF (an_sort_date = 0) THEN
   lv_sort_date := ' cp.date_time desc ';
  ELSE
   lv_sort_date := ' cp.date_time ';
  END IF;

  OPEN acur_t FOR    'SELECT 
      cp.date_time,
      cp.mid, cp.er, cp.ed,
      decode(:par4, 1, cp.q1, util_pg.sumn(cp.q1, cp.q2)) q1,
      decode(:par4, 1, cp.q3, util_pg.sumn(cp.q3, cp.q4)) q3,
      cp.q2, cp.q4, cp.erm, cp.edm,
      decode(:par4, 1, cp.q1m, util_pg.sumn(cp.q1m, cp.q2m)) q1m,
      decode(:par4, 1, cp.q3m, util_pg.sumn(cp.q3m, cp.q4m)) q3m,
      cp.q2m, cp.q4m,
      cp.cosf, cp.freq,
      cp.volt ua, cp.volt2 ub, cp.volt3 uc, 
      cp.NFIU1 an_ua, cp.NFIU2 an_ub, cp.NFIU3 an_uc, 
      cp.currento ia, cp.curr2 ib, cp.curr3 ic, 
      cp.NFII1 an_ia, cp.NFII2 an_ib, cp.NFII3 an_ic, cp.NI0,decode(cp.noff,1,''Откл'',0,''Вкл'') voff, cp.doff,cp.nstatus, cp.ntemp
   FROM
    curr_power_arch cp
   WHERE
    cp.mid = :par1 
    AND cp.date_time >= :par2 
    AND cp.date_time <= :par3 
   ORDER BY '
                  || lv_sort_date USING an_wilbiadd, an_wilbiadd, an_wilbiadd, an_wilbiadd, an_id, ad_prlbdt, ad_prhbdt;
 END;

--------------------------------------------------------------------------------------------------------------------------
 -- процедура получает историю журнала сообщений
 -- added by KAG 24.12.2008
 PROCEDURE get_histjournal(
 an_id NUMBER,                                                                                                                                        --ид точки
              ad_prlbdt DATE,                                                                                                                        --период от
                             ad_prhbdt DATE,                                                                                                         --период до
                                            an_sort_date NUMBER,                                                               -- 0 - по убыванию (по умолчанию)
                                                                acur_t OUT common_pg.tcur
 ) IS
  lv_sort_date        VARCHAR2(100);
 BEGIN
  IF (an_sort_date = 0) THEN
   lv_sort_date := ' j.date_time desc ';
  ELSE
   lv_sort_date := ' j.date_time ';
  END IF;

  OPEN acur_t FOR    'SELECT 
      j.*, d.veventtext
   FROM
    journal j, metereventsdict d
   WHERE
    j.mid = :par1 
    AND j.date_time >= :par2 
    AND j.date_time <= :par3 
    AND j.nevent = d.nevent(+)
   ORDER BY '
                  || lv_sort_date USING an_id, ad_prlbdt, ad_prhbdt;
 END;

------------------------------------------------------------------------------
 -- функция возвращает имя ближайшего родителя-папки для точки
 -- added by KAG 27.01.2010
 FUNCTION get_parent_point(an_mid NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(400);
 BEGIN
  SELECT MAX(p1.NAME)
  INTO   lv_ret
  FROM   points p1
  WHERE  p1.mid IN(SELECT     PARENT
                   FROM       points
                   CONNECT BY PRIOR PARENT = mid AND ind IN(3, 4)
                   START WITH mid = an_mid) AND p1.ind IN(1, 2);

  RETURN lv_ret;
 END;

