 --Сохранение ГН
 PROCEDURE inshalfhour(an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER,
 an_q2 NUMBER, an_q4 NUMBER, an_rn NUMBER
 ) IS
 BEGIN
  IF an_er IS NOT NULL OR an_ed IS NOT NULL OR an_q1 IS NOT NULL OR an_q3 IS NOT NULL THEN
     das_pg.insert_hf_in_profile(an_mid, ad_date, 30,
                                 an_er, an_ed, an_q1, NULL,
                                 an_q3, NULL, an_rn);
     das_pg.ins_halfhourtmp(an_mid, ad_date, comsrv_pg.cn_auto, 
                            an_er, an_ed, an_q1, an_q3, NULL, NULL,
                            NULL, comsrv_pg.cn_maket, NULL);                            
  END IF;
 END; 
--------------------------------------------------------------------------------
 -- конвертирует номер строки и столбца в адрес ячейки
 FUNCTION conv_cell (an_row NUMBER, an_col NUMBER) 
  RETURN VARCHAR2 IS
  lv_res VARCHAR2(100);
 BEGIN
  lv_res := ORDExcel_PG.ConvertFormulaA1('R'||an_row||'C'||an_col);
  RETURN lv_res;
 END;
--------------------------------------------------------------------------------
 -- наполняет данными Excel-макет 
 PROCEDURE complete_xls_maket (an_mid NUMBER, av_vlname VARCHAR2, ad_startdate DATE, ad_findate DATE, an_rnd NUMBER)
  IS
  lv_res            NUMBER;
  ld_startdate      DATE := trunc(ad_startdate);
  ld_finishdate     DATE := trunc(ad_findate);
  ln_row            NUMBER;
  lv_pname          VARCHAR2(1000);
  lv_qm             VARCHAR2(100);
  ln_timezone       NUMBER;
  ln_timeshift      NUMBER;
  lv_timezone       VARCHAR2(400);  
  lv_bpswitch       VARCHAR2(100);
  ld_prevdate       DATE;
  ln_er             NUMBER;
  ln_ed             NUMBER;
  ln_q1             NUMBER;
  ln_q3             NUMBER;
  ln_koeff          NUMBER DEFAULT 1000; -- вывод в МВт
  lv_mask           VARCHAR2(100); -- маска для вывода чисел
 BEGIN 
  SELECT '#0.'||RPAD('0',an_rnd,'0') INTO lv_mask FROM dual;
  
  SELECT NVL(av_vlname, p.NAME), 
        --decode(util_pg.is_summer(ld_startdate),1,f.ntimezones,0,f.ntimezonew) timezone, 
        decode(f.nswitch,1,'On','Off') bpswitch 
   INTO lv_pname, lv_bpswitch
   FROM feeders f, points p 
  WHERE f.mid = an_mid AND p.mid=f.mid;  
  ln_timezone := 1; -- всегда Европа зимой
  ln_timeshift := 1/24;
  
  SELECT '(GMT'||to_char(ln_timezone,'sfm00')||':00)'||decode(ln_timezone,1,' Central European Time','') 
    INTO lv_timezone FROM dual;
  
  -- выводим шапку (статика)
  lv_res := ORDExcel_PG.insertdata('A4','Name:','BSTR');
  lv_res := ORDExcel_PG.insertdata('A5','Start Time:','BSTR');
  lv_res := ORDExcel_PG.insertdata('A6','End Time:','BSTR');
  lv_res := ORDExcel_PG.insertdata('A7','Time Zone:','BSTR');
  lv_res := ORDExcel_PG.insertdata('A8','Report Time:','BSTR');
  lv_res := ORDExcel_PG.insertdata('A9','Validity:','BSTR');
  lv_res := ORDExcel_PG.insertdata('A10','Bypass switch:','BSTR');
  -- выводим шапку (динамика)
  lv_res := ORDExcel_PG.insertdata('B4','Report: '||lv_pname,'BSTR');
  lv_res := ORDExcel_PG.insertdata('B5',to_char(ld_startdate,'dd.mm.yyyy hh24:mi'),'BSTR');
  lv_res := ORDExcel_PG.insertdata('B6',to_char(ld_finishdate,'dd.mm.yyyy hh24:mi'),'BSTR');
  lv_res := ORDExcel_PG.insertdata('B7',lv_timezone,'BSTR');
  lv_res := ORDExcel_PG.insertdata('B8',to_char(sysdate,'dd.mm.yyyy hh24:mi'),'BSTR');
  lv_res := ORDExcel_PG.insertdata('B10',lv_bpswitch,'BSTR');  
  lv_res := ORDExcel_PG.SetRangeFont ('A4', 'B10', 14, 'Times New Roman', FALSE);
  lv_res := ORDExcel_PG.SetAlignmentData('B4','B10','HorizontalAlignment',2);  
  
  --шапка таблицы
  lv_res := ORDExcel_PG.SetRangeBorders ('A12', 'A13', '11110000', 3, 1);
  lv_res := ORDExcel_PG.SetRangeBorders ('B12', 'E13', '11110000', 3, 1);
  lv_res := ORDExcel_PG.SetRangeBorders ('B12', 'E13', '00000100', 2, 9);
  lv_res := ORDExcel_PG.SetRangeBorders ('B13', 'E13', '00001000', 2, 1);
  lv_res := ORDExcel_PG.SetAlignmentData('A12','E13','HorizontalAlignment',3);
  lv_res := ORDExcel_PG.SetAlignmentData('B12','B12','HorizontalAlignment',2);
  lv_res := ORDExcel_PG.insertdata('A12','Time Axis','BSTR');
  lv_res := ORDExcel_PG.insertdata('B12',lv_pname,'BSTR');
  lv_res := ORDExcel_PG.insertdata('A13','hh:mm','BSTR');
  lv_res := ORDExcel_PG.insertdata('B13','AE+ [MWh]','BSTR');
  lv_res := ORDExcel_PG.insertdata('C13','AE- [MWh]','BSTR');
  lv_res := ORDExcel_PG.insertdata('D13','RE+ [Mvarh]','BSTR');
  lv_res := ORDExcel_PG.insertdata('E13','RE- [Mvarh]','BSTR');
  
  -- приводим к Украине
  ld_startdate := util_pg.to_localtime(ld_startdate)+ln_timeshift;
  ld_finishdate := util_pg.to_localtime(ld_finishdate)+ln_timeshift;
  -- собственно таблица  
  ln_row := 13;
  FOR lc IN (SELECT util_pg.to_unlocaltime(CASE WHEN to_char(date_time,'mi') BETWEEN 1 AND 30 
                                                THEN trunc(date_time,'hh')+30/1440 
                                                ELSE round(date_time,'hh') END)-ln_timeshift dthh,
                    er, ed, q1, q3, vqm 
               FROM halfhour 
              WHERE date_time > ld_startdate 
                    AND date_time <= ld_finishdate 
                    AND mid = an_mid
              ORDER BY date_time) LOOP      
      IF lc.dthh <> ld_prevdate OR ld_prevdate IS NULL THEN
        IF ld_prevdate IS NOT NULL THEN
          ln_row := ln_row + 1;
          lv_res := ORDExcel_PG.insertdata('A'||ln_row,nvl(to_char(ld_prevdate,'dd.mm.yyyy hh24:mi'),''),'BSTR');
          lv_res := ORDExcel_PG.InsertDataRealIfNull('B'||ln_row,ln_er/ln_koeff);          
          lv_res := ORDExcel_PG.InsertDataRealIfNull('C'||ln_row,ln_ed/ln_koeff);
          lv_res := ORDExcel_PG.InsertDataRealIfNull('D'||ln_row,ln_q1/ln_koeff);          
          lv_res := ORDExcel_PG.InsertDataRealIfNull('E'||ln_row,ln_q3/ln_koeff);                    
          lv_qm := qm_pg.sumqm(lv_qm,lc.vqm);
        ELSE
          lv_qm := lc.vqm;
        END IF;
        ld_prevdate := lc.dthh;
        ln_er := lc.er;
        ln_ed := lc.ed;
        ln_q1 := lc.q1;
        ln_q3 := lc.q3;        
      ELSE
        ln_er := util_pg.sumn(ln_er,lc.er);
        ln_ed := util_pg.sumn(ln_ed,lc.ed);
        ln_q1 := util_pg.sumn(ln_q1,lc.q1);
        ln_q3 := util_pg.sumn(ln_q3,lc.q3);
        lv_qm := qm_pg.sumqm(lv_qm,lc.vqm);
      END IF;
    
  END LOOP;
  
  IF ld_prevdate IS NOT NULL THEN -- надо выплюнуть последнюю строчку 
      ln_row := ln_row + 1;
      lv_res := ORDExcel_PG.insertdata('A'||ln_row,nvl(to_char(ld_prevdate,'dd.mm.yyyy hh24:mi'),''),'BSTR');
      lv_res := ORDExcel_PG.InsertDataRealIfNull('B'||ln_row,ln_er/ln_koeff);          
      lv_res := ORDExcel_PG.InsertDataRealIfNull('C'||ln_row,ln_ed/ln_koeff);
      lv_res := ORDExcel_PG.InsertDataRealIfNull('D'||ln_row,ln_q1/ln_koeff);          
      lv_res := ORDExcel_PG.InsertDataRealIfNull('E'||ln_row,ln_q3/ln_koeff);
  END IF;
  
  IF ln_row > 13 THEN      
      lv_res := ORDExcel_PG.insertdata('B9',nvl(reports2_pg.get_vqm(lv_qm,1),''),'BSTR');
      lv_res := ORDExcel_PG.SetRangeBorders ('A12', 'E'||ln_row, '11110000', 3, 1);
      lv_res := ORDExcel_PG.SetRangeBorders ('A14', 'E'||ln_row, '00001100', 2, 1);
      lv_res := ORDExcel_PG.SetAlignmentData('B14', 'E'||ln_row,'HorizontalAlignment',4);
      lv_res := ORDExcel_PG.SetRangeFormat('B14', 'E'||ln_row,lv_mask);
  END IF;
  lv_res := ORDExcel_PG.SetRangeFont ('A12', 'E'||ln_row, 12, 'Times New Roman', FALSE);
  
  -- настраиваем шапку с показаниями
  lv_res := ORDExcel_PG.insertdata('A'||(ln_row+1),'AEC+ [kWh] =','BSTR');        
  lv_res := ORDExcel_PG.insertdata('A'||(ln_row+2),'AEC- [kWh] =','BSTR');        
  lv_res := ORDExcel_PG.insertdata('A'||(ln_row+3),'REC+ [kvarh] =','BSTR');        
  lv_res := ORDExcel_PG.insertdata('A'||(ln_row+4),'REC- [kvarh] =','BSTR');
  lv_res := ORDExcel_PG.SetAlignmentData('A'||(ln_row+1),'A'||(ln_row+4),'HorizontalAlignment',4);
  lv_res := ORDExcel_PG.SetRangeBorders ('A'||(ln_row+1),'B'||(ln_row+4), '11110000', 3, 1);
  lv_res := ORDExcel_PG.SetRangeBorders ('A'||(ln_row+1),'B'||(ln_row+4), '00001100', 2, 1);
  lv_res := ORDExcel_PG.SetRangeFont ('A'||(ln_row+1),'B'||(ln_row+4), 12, 'Times New Roman', FALSE);
  lv_res := ORDExcel_PG.SetRangeFormat('B'||(ln_row+1),'B'||(ln_row+4),lv_mask);
  
  -- выводим показания на ld_finishdate 
  lv_res := ORDExcel_PG.InsertDataRealIfNull('B'||(ln_row+1),util_pg.get_meterage(an_mid, ld_finishdate, 1, 0, NULL, 0));
  lv_res := ORDExcel_PG.InsertDataRealIfNull('B'||(ln_row+2),util_pg.get_meterage(an_mid, ld_finishdate, 2, 0, NULL, 0));
  lv_res := ORDExcel_PG.InsertDataRealIfNull('B'||(ln_row+3),util_pg.get_meterage(an_mid, ld_finishdate, 3, 0, NULL, 0));
  lv_res := ORDExcel_PG.InsertDataRealIfNull('B'||(ln_row+4),util_pg.get_meterage(an_mid, ld_finishdate, 5, 0, NULL, 0));
  
  -- настраиваем ширину колонок
  lv_res := ORDExcel_PG.SetColumnWidth(1,20);
  lv_res := ORDExcel_PG.SetColumnWidth(2,20);
  lv_res := ORDExcel_PG.SetColumnWidth(3,20);
  lv_res := ORDExcel_PG.SetColumnWidth(4,20);
  lv_res := ORDExcel_PG.SetColumnWidth(5,20);
  
 END;   
--------------------------------------------------------------------------------
 -- создает Excel-макет 
 PROCEDURE create_xls_maket (an_mid NUMBER, av_vlname VARCHAR2, ad_startdate DATE, ad_findate DATE, av_filename VARCHAR2, av_fileversion NUMBER, av_sheetname VARCHAR2, an_rnd NUMBER) 
  IS
  lv_res            NUMBER;
 BEGIN
  -- создаем объект Excel.Application и листом av_sheetname
  lv_res := ORDExcel_PG.CreateExcelWorkSheet('', av_sheetname);
  
  complete_xls_maket(an_mid, av_vlname, ad_startdate, ad_findate, an_rnd);
  
  lv_res := ORDExcel_PG.SaveExcelFile(av_filename,av_fileversion);
  IF lv_res = 0 THEN
    dbms_output.put_line(av_filename);
  ELSE
    raise_application_error(-20001, 'Файл '||av_filename||' не был сохранён!');
  END IF;

  -- закрываем все дескрипторы и Excel
  lv_res := ORDExcel_PG.ExitExcel();
 EXCEPTION
  WHEN OTHERS THEN
   lv_res := ORDExcel_PG.ExitExcel();
   raise_application_error(-20001, 'EXCELMAKETS_PG.create_xls_maket: ' || CHR(10) || SQLERRM(SQLCODE));     
 END;
--------------------------------------------------------------------------------  
 -- создает Excel-файлы для каждой точки в макете
 PROCEDURE create_xls_makets (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_g IS
   SELECT   mg.ngroup, mg.vcode, mg.vname, (SELECT count(*) FROM maketpoints WHERE ngroup=mg.ngroup) pointcnt
       FROM maketgroups mg
      WHERE mg.nmaket = an_maket            
   ORDER BY mg.vname, pointcnt DESC;

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mp.mid, p.NAME
     FROM maketpoints mp, points p
    WHERE mp.ngroup = lc_group AND mp.mid=p.mid;
    
  lv_bstr           VARCHAR2(2000);   
  lv_fpath          VARCHAR2(1000);
  lv_filext         VARCHAR2(100);
  ln_filecnt        NUMBER;
  ln_fileversion    NUMBER := 56; -- Excel 2003 
  lv_filegroups     VARCHAR2(2000);   -- maketgroups, по которым были сгенерированы файлы (разделены символом '_')
  lv_pointcode      VARCHAR2(256);
 BEGIN
   SELECT MAX (vvalue)
     INTO lv_fpath
     FROM parameter
    WHERE npid = 10;

   IF lv_fpath IS NULL THEN
    raise_application_error (-20002, 'Не задан каталог для хранения файлов рассылки в таблице конфигураций PARAMETER.');
   END IF;
   
  SELECT REPLACE(av_fname,'.txt')
    INTO av_fname
    FROM dual;
  SELECT DECODE(ln_fileversion,56,'.xls',51,'.xlsx','.xls')
    INTO lv_filext
    FROM dual;
 
  SELECT MAX(vparam)
    INTO lv_bstr
    FROM makets
   WHERE nmaket = an_maket;

  ln_filecnt := 0;
  lv_filegroups := '';
  FOR lc_g IN lcur_g LOOP
    IF lc_g.pointcnt > 1 THEN 
      raise_application_error (-20002, 'В макете для группы '||lc_g.vname||' задано больше одной точки!');
    END IF;
    FOR lc_p IN lcur_p(lc_g.ngroup) LOOP
      lv_pointcode := NVL(lc_g.vcode, lc_p.NAME);
      create_xls_maket (lc_p.mid, lv_pointcode, ad_date, ad_date+1, lv_fpath||lc_g.ngroup||'-'||av_fname||lv_filext, 
                        ln_fileversion, 
                        NVL(util_pg.get_param(lv_bstr,1,';'),'Sheet1'),
                        NVL(util_pg.get_param(lv_bstr,2,';'),5));
      lv_filegroups := lv_filegroups || lc_g.ngroup ||'_';
      ln_filecnt := ln_filecnt + 1;
    END LOOP;
  END LOOP; 
  
  -- возвращаем имя файла, где первым параметром идет уникальный ID операции, а потом lv_filegroups
  av_fname := av_fname||'_'||lv_filegroups||lv_filext;
 
 END; 
-------------------------------------------------------------------------------- 
 -- загружает данные из Excel-файла на диске
 PROCEDURE load_xls_maket (an_cid NUMBER, av_fname VARCHAR2, ad_date IN OUT DATE, av_sheetname VARCHAR2)
 IS
  lv_res            NUMBER;
  ln_mid            NUMBER;
  lv_importcode     VARCHAR2(1000);
  ln_er             NUMBER;
  ln_ed             NUMBER;
  ln_q1             NUMBER;
  ln_q3             NUMBER;
  ln_mer            NUMBER;
  ln_med            NUMBER;
  ln_mq1            NUMBER;
  ln_mq3            NUMBER;
  ld_nextdate       DATE;
  ld_tmp            DATE;
  ln_koeff          NUMBER := 1000/4;  -- мощность приходит в МВт за 15 мин
  lv_mtrsn          VARCHAR2 (100);
  ln_digits         NUMBER;
  ln_shift          NUMBER := 0; -- разница в часах между временем счетчика и украинским локальным временем
  ln_rn             NUMBER                DEFAULT 4;  -- точность данных
  ln_stcol          NUMBER :=1;
  ln_strow          NUMBER :=1;
  lv_tmp            VARCHAR2(4000);
 BEGIN
  -- создаем объект Excel.Application
  lv_res := ORDExcel_PG.CreateExcelApplication('');
  IF lv_res != 0 THEN
    raise_application_error(-20001, 'Ошибка запуска Excel!');
  END IF;    
  -- открываем файл c листом Лист1
  lv_res := ORDExcel_PG.OpenExcelFile(av_fname, av_sheetname);
  IF lv_res != 0 THEN
    raise_application_error(-20001, 'Ошибка открытия файла '||av_fname);
  END IF;
   
  -- поиск в первых трех колонках стартовой ячейки со значением "Start Time"
  FOR rw IN 1..10 LOOP 
    FOR cln IN 1..3 LOOP
      lv_tmp := ORDExcel_PG.GetDataStr(conv_cell(rw,cln));
      IF lv_tmp = 'Start Time' THEN
        ln_strow := rw;
        ln_stcol := cln;
        EXIT;
      END IF;
    END LOOP;
  END LOOP;     
  IF ln_strow = 1 AND ln_stcol = 1 THEN
    raise_application_error(-20001, 'Не найдена стартовая позиция в файле!');
  END IF;
  
  lv_importcode := ORDExcel_PG.GetDataStr(conv_cell(ln_strow+4,ln_stcol+1));

  SELECT max(f.mid) INTO ln_mid
    FROM chanpoint cp, feeders f 
   WHERE cp.cid = an_cid AND f.mid = cp.mid AND f.vimportcode = TRIM(lv_importcode);
  
  IF ln_mid IS NULL THEN
    dbms_output.put_line('не найдена точка канала!');
    lv_res := ORDExcel_PG.ExitExcel();
    RETURN;
  END IF;
  
  SELECT TRIM (MAX (mtrsn)), MAX (DIGITS)
    INTO lv_mtrsn, ln_digits
    FROM meters
   WHERE mid = ln_mid;       
  
  ad_date := ORDExcel_PG.GetDataDate(conv_cell(ln_strow,ln_stcol+1));
  FOR str IN ln_strow+7 .. ln_strow+102 LOOP
    BEGIN
      -- читаем дату счетчика
      ld_tmp := ORDExcel_PG.GetDataDate(conv_cell(str,ln_stcol));
     
      -- теперь будем грузить 15-минутные показания, по которым расчитываются расходы
      -- а если нет показаний то расходы будут считаться по мощностям
      -- читаем мощности и приводим их к расходам 
      ln_er := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+1))*ln_koeff;
      ln_ed := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+2))*ln_koeff;
      ln_q1 := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+3))*ln_koeff;
      ln_q3 := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+4))*ln_koeff;
      
      -- читаем показания
      ln_mer := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+5));
      ln_med := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+6));
      ln_mq1 := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+7));
      ln_mq3 := ORDExcel_PG.GetDataReal(conv_cell(str,ln_stcol+8));
      
      -- на вход даем время счетчика, так как учитываются настройки час. пояса счетчика
      comsrv_pg.set_halfhour_zxb (ln_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_mer, ln_med, ln_mq1, ln_mq3, lv_mtrsn, ln_digits, NULL, ld_tmp, COMSRV_PG.cn_auto, COMSRV_PG.cn_maket);
      
      IF ld_tmp = trunc(ld_tmp) THEN -- вставка суточных показаний
         comsrv_pg.set_bill_meter(ln_mid, ln_mer, ln_med, ln_mq1, ln_mq3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 
                        lv_mtrsn, ln_digits, ld_tmp);
      END IF;
        
    EXCEPTION
      WHEN others THEN
        dbms_output.put_line('Даты больше не обнаружены! ');        
        EXIT;
    END;

  END LOOP;
  
  -- перерасчет расхода за следующие ближайшие показания 
  IF ld_tmp IS NOT NULL THEN
    -- находим разницу между временем счетчика и локальным временем Украины в базе
    ln_shift := util_pg.to_localtime(util_pg.convertmeterdate_e_f(ln_mid, ld_tmp), 1) - ld_tmp;
    SELECT min(date_time)
      INTO ld_nextdate
      FROM halfhour 
     WHERE mid = ln_mid
           AND date_time>ld_tmp+ln_shift -- приводим время счетчика к Украине локальному
           AND (erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL);
           
    IF ld_nextdate IS NOT NULL THEN
      SELECT er, ed, q1, q3, erm, edm, q1m, q3m
        INTO ln_er, ln_ed, ln_q1, ln_q3, ln_mer, ln_med, ln_mq1, ln_mq3
        FROM halfhour
       WHERE mid = ln_mid AND date_time=ld_nextdate;
      -- на вход даем время счетчика, так как учитываются настройки час. пояса счетчика
      comsrv_pg.set_halfhour_zxb (ln_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_mer, ln_med, ln_mq1, ln_mq3, lv_mtrsn, ln_digits, NULL, ld_nextdate-ln_shift, COMSRV_PG.cn_auto, COMSRV_PG.cn_maket);
    END IF;
  END IF;
  
  COMMIT;
  das_pg.checkhalfhour_without_err;
  COMMIT;
  -- закрытие Excel
  lv_res := ORDExcel_PG.ExitExcel(); 
 
 EXCEPTION
  WHEN OTHERS THEN
   lv_res := ORDExcel_PG.ExitExcel();
   raise_application_error(-20001, 'EXCELMAKETS_PG.load_xls_maket: ' || CHR(10) || SQLERRM(SQLCODE)); 
 END; 
-------------------------------------------------------------------------------- 
 PROCEDURE l_xls (an_cid NUMBER, ac_file BLOB, ad_date IN OUT DATE)
 IS
  gr_file       SYS.UTL_FILE.file_type;
  lv_location   VARCHAR2(400) := 'C:\temp\';
  lv_filename   VARCHAR2(100) := 'fname.xls';
  ln_bufsize    CONSTANT NUMBER := 10000;
  lr_buff       RAW(10000);
  ln_pos        NUMBER;
  ln_amount     NUMBER;
 BEGIN
  -- сохраняем BLOB во временный файл на диске
  gr_file := utl_file.fopen(lv_location,lv_filename,'wb');
  
  IF ac_file IS NULL THEN
    raise_application_error(-20001,'Передан пустой BLOB!');
  END IF;
  
  ln_pos := 1;  
  LOOP
    ln_amount := ln_bufsize;
    dbms_lob.READ(ac_file, ln_amount, ln_pos, lr_buff);
    utl_file.put_raw(gr_file, lr_buff);
    ln_pos := ln_pos + ln_amount;
    EXIT WHEN ln_amount < ln_bufsize;
  END LOOP;
  
  -- читаем и грузим в БД данные из файла на диске      
  load_xls_maket (an_cid, lv_location||lv_filename, ad_date);  
 
  --удаляем временный файл с диска
  IF utl_file.is_open(gr_file) THEN
    utl_file.fclose(gr_file);
  END IF;  
  utl_file.fremove(lv_location,lv_filename);
  
 EXCEPTION
  WHEN OTHERS THEN
   IF utl_file.is_open(gr_file) THEN
     utl_file.fclose(gr_file);
   END IF;  
   utl_file.fremove(lv_location,lv_filename);
   raise_application_error(-20001, 'EXCELMAKETS_PG.l_xls: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 --------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.EXCELMAKETS_PG

