CREATE OR REPLACE 
PACKAGE BODY feederscoef_pg
IS
--------------------------------------------------------------------------------------------------------------------------
  -- Возвращает основной курсор
 PROCEDURE getinfo(an_mid NUMBER, ret_t OUT common_pg.tcur) IS

 BEGIN

  OPEN ret_t FOR
 
  'select f.mid, f.dstart , f.dend, f.kc from feederscoef f where mid= '||an_mid||'
  order by f.dstart';
  
 END;
 ----------------------------------------------------------------
    -- Сохранение
 PROCEDURE upd_p(an_mid NUMBER,ad_oldstart DATE,ad_start DATE,ad_dend DATE,an_kc NUMBER) IS
 ln_count NUMBER;
 ld_dstart DATE;
 ld_dend DATE;
 BEGIN
 
 --IF (ad_oldstart<>ad_start OR ad_olddend<>ad_dend )THEN
   del_p(an_mid,ad_oldstart);
 -- END IF;
  
  
   SELECT count(*)
    INTO
      ln_count
       FROM feederscoef
    WHERE mid=an_mid
    AND (ad_start< dend AND nvl(ad_dend,to_date('01.01.3000','dd.mm.yyyy'))> dstart);
  
 IF ln_count <> 0 THEN
  SELECT dstart,dend
    INTO
      ld_dstart,
      ld_dend
    FROM feederscoef
    WHERE mid=an_mid AND rownum <2
    AND (ad_start< dend AND nvl(ad_dend,to_date('01.01.3000','dd.mm.yyyy'))> dstart);
  raise_application_error(-20001, 'Данный период пересекается с периодом '||ld_dstart ||' - '||ld_dend ||
 ' для которого расчетный коэффициент уже задан ');
  
 ELSE

/* UPDATE feederscoef
     SET dend = ad_dend,
         kc = an_kc
   WHERE mid = an_mid AND dstart= ad_start;
   IF SQL%ROWCOUNT = 0 THEN*/
       INSERT INTO feederscoef
               (mid, dstart, dend, kc)
        VALUES (an_mid, ad_start, ad_dend, an_kc);
--   END IF;
   COMMIT;
 END IF;
 
 EXCEPTION
   WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'feederscoef_pg.upd_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ----------------------------------------------------------------
     -- Удаление
 PROCEDURE del_p(an_mid NUMBER, ad_start DATE) IS
 BEGIN
  DELETE FROM feederscoef
        WHERE mid = an_mid AND dstart = ad_start;
 
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'feederscoef_pg.del_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
-------------------------------------------------------------------------------------------
-- возвращает расчетный коэффициент
FUNCTION getcoeff(an_mid NUMBER, ad_date DATE)
RETURN NUMBER IS
ln_c NUMBER;
BEGIN
 SELECT decode(nvl(c.kc,0),0,nvl(f.kc,1),c.kc)kc
 INTO ln_c
 FROM
  (SELECT kc,mid FROM feeders WHERE mid=an_mid)f,
     (SELECT kc,mid FROM
      feederscoef
         WHERE mid=an_mid
              AND ad_date BETWEEN dstart AND dend)c
WHERE f.mid=c.mid(+);
RETURN ln_c;
END;

----------------------------------------------------------------------------------------------
END;
/


