 PROCEDURE startrep_p(an_maket NUMBER, ad_date DATE, av_param VARCHAR2) IS
  CURSOR lcur_sel IS
   SELECT m.nmaket, p.ntype, p.vprocedure,
          DECODE(
           p.nperiod,
           0, ad_date,
           1, TRUNC(ad_date, 'HH24'),
           2, TRUNC(ad_date, 'DD'),
           3, TRUNC(ad_date, 'D'),
           4, util_pg.truncdec(ad_date),
           5, TRUNC(ad_date, 'MM'),
           6, util_pg.trunc_d(ad_date, 1 / 96),
           8, util_pg.trunc_d(ad_date, 1 / 48)
          ) doldcreated,
          m.vname mname
   FROM   deportprocedures p, makets m
   WHERE  m.nmaket = an_maket AND m.nprocedure = p.nprocedure(+) AND p.ntype = 0;

  lv_orgfname         VARCHAR2(2000);
  ln_handle           INTEGER;
  ln_ret              NUMBER;
  lc                  lcur_sel%ROWTYPE;
 BEGIN
  setout_p(1);
  gn_immediate := 1;
  gvcurr_param := av_param;

  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  lc;

  IF lcur_sel%NOTFOUND THEN
   CLOSE lcur_sel;

   raise_application_error(-20002, 'Задание не найдено.');
  END IF;

  CLOSE lcur_sel;

  ln_handle := SYS.DBMS_SQL.open_cursor;
  SYS.DBMS_SQL.parse(ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_maket,:lc_dat,:lc_fname); END;', SYS.DBMS_SQL.native);
  SYS.DBMS_SQL.bind_variable(ln_handle, 'lc_maket', lc.nmaket);
  SYS.DBMS_SQL.bind_variable(ln_handle, 'lc_dat', lc.doldcreated);
  SYS.DBMS_SQL.bind_variable(ln_handle, 'lc_fname', lv_orgfname, 2000);

  IF SYS.DBMS_SQL.EXECUTE(ln_handle) < 0 THEN
   raise_application_error(-20002, 'Ошибка запуска макета.');
  END IF;

  SYS.DBMS_SQL.variable_value(ln_handle, 'lc_fname', lv_orgfname);
  SYS.DBMS_SQL.close_cursor(ln_handle);
 EXCEPTION
  WHEN OTHERS THEN
   IF SYS.DBMS_SQL.is_open(ln_handle) THEN
    SYS.DBMS_SQL.close_cursor(ln_handle);
   END IF;

   RAISE;
 END;

-------------------------------------------------------------------------------------------------
  --Чтение файла
 FUNCTION readfile_f(av_name VARCHAR2, av_fpath VARCHAR2)
  RETURN common_pg.tt_varchar2 IS
  lt_ret              common_pg.tt_varchar2;
  gr_file             SYS.UTL_FILE.file_type;
  lv_fname            VARCHAR2(2000) DEFAULT av_name;
  lv_fpath            VARCHAR2(2000) DEFAULT av_fpath;
  lv_ret              VARCHAR2(4000);
 BEGIN
  BEGIN
   IF lv_fpath IS NULL THEN
    SELECT MAX(vvalue)
    INTO   lv_fpath
    FROM   parameter
    WHERE  npid = 10;
   END IF;

   IF lv_fpath IS NULL THEN
    raise_application_error(-20002, 'Не задан каталог для хранения файлов рассылки в таблице конфигураций.');
   END IF;

   lv_fname := lv_fpath || lv_fname;
   gr_file := SYS.UTL_FILE.fopen(lv_fpath, lv_fname, 'r');

   BEGIN
    LOOP
     SYS.UTL_FILE.get_line(gr_file, lv_ret);
     lt_ret(lt_ret.COUNT + 1) := lv_ret;
    END LOOP;
   EXCEPTION
    WHEN NO_DATA_FOUND THEN
     NULL;
    WHEN OTHERS THEN
     RAISE;
   END;

   SYS.UTL_FILE.fclose_all;
   RETURN lt_ret;
  EXCEPTION
   WHEN SYS.UTL_FILE.invalid_path THEN
    raise_application_error(-20001, common_pg.geterrtext(1) || lv_fname);
   WHEN SYS.UTL_FILE.invalid_operation THEN
    raise_application_error(-20001, common_pg.geterrtext(2) || lv_fname);
   WHEN SYS.UTL_FILE.invalid_filehandle THEN
    raise_application_error(-20001, common_pg.geterrtext(3) || lv_fname);
   WHEN SYS.UTL_FILE.write_error THEN
    raise_application_error(-20001, common_pg.geterrtext(4) || lv_fname);
   WHEN OTHERS THEN
    RAISE;
  END;
 EXCEPTION
  WHEN OTHERS THEN
   SYS.UTL_FILE.fclose_all;
   RAISE;
 END;

-------------------------------------------------------------------------------------------------
   --Возвращает переодичность фоновой процедуры (в днях)
 FUNCTION getdeportprocperiod_n_f(an_period NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_period = 0 THEN
   RETURN 0;
  ELSIF an_period = 1 THEN
   RETURN 1 / 24;
  ELSIF an_period = 2 THEN
   RETURN 1;
  ELSIF an_period = 3 THEN
   RETURN 7;
  ELSIF an_period = 4 THEN
   RETURN 10;
  ELSIF an_period = 5 THEN
   RETURN 31;
  ELSIF an_period = 6 THEN
   RETURN 1 / 96;
  ELSIF an_period = 8 THEN
   RETURN 1 / 48;
  ELSE
   RETURN NULL;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Возвращает переодичность фоновой процедуры (название)
 FUNCTION getdeportprocperiod_v_f(an_period NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  IF an_period = 0 THEN
   RETURN 'Периодически';
  ELSIF an_period = 1 THEN
   RETURN 'Ежечасно';
  ELSIF an_period = 2 THEN
   RETURN 'Ежесуточно';
  ELSIF an_period = 3 THEN
   RETURN 'Еженедельно';
  ELSIF an_period = 4 THEN
   RETURN 'Подекадно';
  ELSIF an_period = 5 THEN
   RETURN 'Ежемесячно';
  ELSIF an_period = 6 THEN
   RETURN 'Каждые 15 минут';
  ELSIF an_period = 8 THEN
   RETURN 'Каждые 30 минут';
  ELSE
   RETURN 'Не определен';
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает полноту формирования макета
 FUNCTION is_fullmaket(an_deportation NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT NVL(MAX(nnotfull), 0)
  INTO   ln_ret
  FROM   deportfiles
  WHERE  ndeportation = an_deportation AND ddate = ad_date;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Универсальный макет посылки сообщений
 PROCEDURE mevents_p(an_id NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
 BEGIN
  FOR lc IN (SELECT   *
             FROM     textreport
             ORDER BY norder) LOOP
   file_pg.out_p(lc.vtext);
  END LOOP;

  DELETE FROM textreport;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE data_init(an_procedure NUMBER, acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcRun::DataInit
 BEGIN
  OPEN acur_t FOR
   SELECT   m.vname, NVL(d.vmemo, '') vmemo, d.vprocedure, file_pg.getdeportprocperiod_n_f(d.nperiod) nperiod, m.nshift, d.ntype, NVL(m.vparam, '') vparam
   FROM     deportprocedures d, makets m
   WHERE    d.nprocedure = m.nprocedure AND m.nmaket = an_procedure AND d.nperiod <> 7
   ORDER BY 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_processes_sh(acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcsSched::ReadProcesses
 BEGIN
  OPEN acur_t FOR
   SELECT   dp.ntype, m.nmaket, m.vname, m.nprocedure, m.vnote, file_pg.getdeportprocperiod_v_f(dp.nperiod) nperiod, m.nshift, m.vparam, m.verror,
            TO_CHAR(m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift / 1440, 'dd.mm.yyyy hh24:mi:ss') nextcreated, m.ncycle,
            m.nblock, dp.vname vprocedure, TO_CHAR(m.dlastcreated, 'dd.mm.yyyy hh24:mi:ss') vlastcreated
   FROM     makets m, deportprocedures dp
   WHERE    dp.nprocedure = m.nprocedure
   ORDER BY m.nshift, m.vname;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_processes_sh(an_parent NUMBER, an_treetype NUMBER, acur_t OUT common_pg.tcur) IS
   -- an_treetype=0 дерево макетов an_treetype=1 дерево процессов
  -- added 24.02.2010  Kondakov A.G.
  lv_folders          VARCHAR2(4000);
  lv_processes        VARCHAR2(4000);
 BEGIN
  lv_processes :=
   ' SELECT  0 isfolder, 0 havechild, dp.ntype, m.nmaket, m.vname, m.nprocedure, m.vnote, file_pg.getdeportprocperiod_v_f (dp.nperiod) nperiod, m.nshift, m.vparam, m.verror,
                            TO_CHAR (m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f (dp.nperiod) + m.nshift / 1440, ''dd.mm.yyyy hh24:mi:ss'') nextcreated, m.ncycle, m.nblock,
                            dp.vname vprocedure, TO_CHAR (m.dlastcreated, ''dd.mm.yyyy hh24:mi:ss'') vlastcreated
                       FROM makets m, deportprocedures dp
                      WHERE dp.nprocedure = m.nprocedure ';

  IF an_parent IS NULL THEN                                                                                                             -- корневая псевдопапка
   lv_folders :=
    'SELECT 1 isfolder, 1 havechild, null ntype, -1 nmaket, ''Задания'' vname, null nprocedure, '''' vnote, '''' nperiod, null nshift, '''' vparam, '''' verror,
                          '''' nextcreated, NULL ncycle, 0 nblock, '''' vprocedure, '''' vlastcreated
                     FROM dual ';
  ELSIF an_parent = -1 THEN                                                                                                      -- папки с макетами и заданиями
   lv_folders :=
    'SELECT 1 isfolder, 1 havechild, 0 ntype, 4 nmaket, ''Макеты'' vname, null nprocedure, '''' vnote, '''' nperiod, null nshift, '''' vparam, '''' verror,
                          '''' nextcreated, NULL ncycle, 0 nblock, '''' vprocedure, '''' vlastcreated
                     FROM dual 
                   UNION ALL
                   SELECT 1 isfolder, 1 havechild, 1 ntype, 4 nmaket, ''Фоновые процессы'' vname, NULL nprocedure, '''' vnote, '''' nperiod, NULL nshift, '''' vparam, '''' verror,
                          '''' nextcreated, NULL ncycle, 0 nblock, '''' vprocedure, '''' vlastcreated
                     FROM dual ';
  ELSE
   lv_folders :=
       'select 1 isfolder, 0 havechild, '
    || an_treetype
    || ' ntype, p.mid nmaket, name vname, null nprocedure, '''' vnote, '''' nperiod, null nshift, '''' vparam, '''' verror,
                                '''' nextcreated, NULL ncycle, p.tag nblock, '''' vprocedure, '''' vlastcreated
                    FROM points p WHERE parent = '
    || an_parent
    || ' AND ptype='
    || (an_treetype + 1)
    || '
                         AND NOT EXISTS (SELECT * FROM makets WHERE nmaket=p.mid)
                         AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid AND ptype='
    || (an_treetype + 1)
    || ')
                   UNION ALL
                   SELECT 1 isfolder, 1 havechild, '
    || an_treetype
    || ' ntype, p.mid nmaket, NAME vname, NULL nprocedure, '''' vnote, '''' nperiod, NULL nshift, '''' vparam, '''' verror,
                                '''' nextcreated, NULL ncycle, p.tag nblock, '''' vprocedure, '''' vlastcreated
                    FROM points p WHERE parent = '
    || an_parent
    || ' AND ptype='
    || (an_treetype + 1)
    || '
                         AND NOT EXISTS (SELECT * FROM makets WHERE nmaket=p.mid) 
                         AND EXISTS (SELECT * FROM points WHERE parent=p.mid AND ptype='
    || (an_treetype + 1)
    || ') ';
   lv_processes :=
       ' SELECT  0 isfolder, 0 havechild, dp.ntype, m.nmaket nmaket, m.vname, m.nprocedure, m.vnote, file_pg.getdeportprocperiod_v_f (dp.nperiod) nperiod, m.nshift, m.vparam, m.verror,
                            TO_CHAR (m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f (dp.nperiod) + m.nshift / 1440, ''dd.mm.yyyy hh24:mi:ss'') nextcreated, m.ncycle, m.nblock,
                            dp.vname vprocedure, TO_CHAR (m.dlastcreated, ''dd.mm.yyyy hh24:mi:ss'') vlastcreated
                       FROM makets m, deportprocedures dp
                      WHERE dp.nprocedure = m.nprocedure AND m.nmaket IN (SELECT mid FROM points START WITH mid='
    || an_parent
    || ' CONNECT BY parent=PRIOR mid) AND dp.ntype='
    || an_treetype;
  END IF;

  OPEN acur_t FOR lv_folders || ' union all ' || lv_processes || ' order by isfolder desc, havechild desc, nshift, vname';
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'file_pg.read_processes_sh: Ошибка чтения ветки дерева задач. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_processes(acur_t OUT common_pg.tcur,an_proctype NUMBER) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcs::ReadProcesses
 BEGIN
  OPEN acur_t FOR
   SELECT   dp.ntype, m.nmaket, m.vname, m.nprocedure, m.vnote, file_pg.getdeportprocperiod_v_f(dp.nperiod) nperiod, m.nshift, m.vparam, m.verror,
            TO_CHAR(m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift / 1440, 'dd.mm.yyyy hh24:mi:ss') nextcreated, m.ncycle,
            m.nblock, TO_CHAR(dlastcreated, 'dd.mm.yyyy hh24:mi:ss') lastcreated
   FROM     makets m, deportprocedures dp
   WHERE    dp.nprocedure = m.nprocedure and (an_proctype is NULL or (an_proctype in (1,3) and dp.ntype=0) or (an_proctype in (2,3) and dp.ntype=1))
   ORDER BY m.nshift;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_combo(acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcs::ReadCombo
 BEGIN
  OPEN acur_t FOR
   SELECT   nprocedure, vname, file_pg.getdeportprocperiod_v_f(dp.nperiod) nperiod
   FROM     deportprocedures dp
   ORDER BY vname;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Отсекает до границы периода
 FUNCTION truncdeportperiod_f(ad_date DATE, an_period NUMBER, an_procedure NUMBER)
  RETURN DATE IS
 BEGIN
  IF an_period IN(-1, 0) THEN
   RETURN ad_date;
  ELSIF an_period = 1 THEN
   RETURN TRUNC(ad_date, 'HH24');
  ELSIF an_period = 2 THEN
   RETURN TRUNC(ad_date, 'DD');
  ELSIF an_period = 3 THEN
   RETURN TRUNC(ad_date, 'D');
  ELSIF an_period = 4 THEN
   RETURN util_pg.truncdec(ad_date);
  ELSIF an_period = 5 THEN
   RETURN TRUNC(ad_date, 'MM');
  ELSIF an_period = 6 THEN
   RETURN util_pg.trunc_d(ad_date, 1 / 96);
  END IF;

  RETURN NULL;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Добавляет к дате 1 период
 FUNCTION adddeportperiod_f(ad_date DATE, an_period NUMBER, an_procedure NUMBER)
  RETURN DATE IS
  ld_date             DATE DEFAULT truncdeportperiod_f(ad_date, an_period);
 BEGIN
  IF an_period IN(-1, 0) THEN
   RETURN ld_date;
  ELSIF an_period = 1 THEN
   RETURN ld_date + 1 / 24;
  ELSIF an_period = 2 THEN
   RETURN ld_date + 1;
  ELSIF an_period = 3 THEN
   RETURN ld_date + 7;
  ELSIF an_period = 4 THEN
   RETURN util_pg.add_dec(ld_date, 1);
  ELSIF an_period = 5 THEN
   RETURN ADD_MONTHS(ld_date, 1);
  ELSIF an_period = 6 THEN
   RETURN ld_date + 1 / 96;
  END IF;

  RETURN NULL;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_notfull IS
 BEGIN
  gn_notfull := 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setstatusimport_p(an_operation NUMBER, ad_date DATE, an_state NUMBER, av_error VARCHAR2) IS
 BEGIN
  UPDATE rmakets
  SET verror = av_error,
      ddate = ad_date,
      nstate = an_state,
      dload = DECODE(an_state, 7, SYSDATE, NULL),
      user_id = util_pg.user_f
  WHERE  noperation = an_operation;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'file_pg.setstatusimport_p: Ошибка обновления статуса. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
-------------------------------------------------------------------------------------------
END;
