CREATE OR REPLACE 
PACKAGE BODY filereport_pg IS
  ------------------------------------------------------------------------------------------------------------------------
    -- пакет по созданию отчетов в файл
    -- дата создания 27/07/2002 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 gn_currline      NUMBER;
 gn_currid        NUMBER;
 gn_currispoint   NUMBER;
 gd_currfrom      DATE;
 gd_currtill      DATE;
 gv_currname      VARCHAR2 (256);
------------------------------------------------------------------------------------------------------------------------
 gt_header        common_pg.tt_varchar2;
 gb_useheader     BOOLEAN               := FALSE;

------------------------------------------------------------------------------------------------------------------
 FUNCTION gn_group
  RETURN NUMBER IS
 BEGIN
  RETURN gn_currid;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION gd_from
  RETURN DATE IS
 BEGIN
  RETURN gd_currfrom;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION gd_till
  RETURN DATE IS
 BEGIN
  RETURN gd_currtill;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION gv_name
  RETURN VARCHAR2 IS
 BEGIN
  RETURN gv_currname;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION gn_ispoint
  RETURN NUMBER IS
 BEGIN
  RETURN gn_currispoint;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE main_p (an_form NUMBER, an_group NUMBER, ad_from DATE, ad_till DATE, is_point NUMBER, av_procname VARCHAR2) IS
  lv_procname   VARCHAR2 (2000);
  ln_handle     INTEGER;
  ln_ret        NUMBER;
  ln_root1      NUMBER;
  ln_root2      NUMBER;
  lv_time       VARCHAR2 (8);
  lv_rdat       VARCHAR2 (8);
 BEGIN
  gn_currid := an_group;
  gn_currispoint := NVL (is_point, 0);
  gd_currfrom := ad_from;
  gd_currtill := ad_till;
  gn_currline := 0;

  IF gn_currispoint = 1 THEN   --точка
   SELECT MAX (NAME)
     INTO gv_currname
     FROM points
    WHERE mid = an_group;
  ELSE   --группа
   SELECT MAX (NAME), MAX (nroot1), MAX (nroot2)
     INTO gv_currname, ln_root1, ln_root2
     FROM GROUPS
    WHERE gid = an_group;

   IF ln_root1 > 1 AND ln_root2 IS NOT NULL THEN
    SELECT MAX (gid)
      INTO gn_currid
      FROM GROUPS
     WHERE nroot1 IS NULL AND nroot2 = ln_root2;
   END IF;
  END IF;

  DELETE FROM textreport;

  COMMIT;

  IF av_procname IS NULL THEN
   SELECT RTRIM (LTRIM (MAX (vprocname))), NVL (MAX (SUBSTR (enablecontrols, 2, 1)), '0'), NVL (MAX (SUBSTR (enablecontrols, 3, 1)), '0')
     INTO lv_procname, lv_time, lv_rdat
     FROM forms
    WHERE fid = an_form;

   IF lv_procname IS NULL THEN
    raise_application_error (-20002, 'filereport_pg.main_p: Не задана отчетная процедура.');
   END IF;
  ELSE
   lv_procname := av_procname;
   lv_time := '1';
   lv_rdat := '1';
  END IF;

  --Если время не учитываем то отсекаем
  IF lv_time = '0' THEN
   gd_currtill := TRUNC (gd_currtill);
   gd_currfrom := TRUNC (gd_currfrom);
  END IF;

  --Если дату 'по' не учитываем то +1
  IF lv_rdat = '0' THEN
   gd_currtill := gd_currfrom + 1;
  END IF;

  file_pg.setout_p (1);
  ln_handle := SYS.DBMS_SQL.open_cursor;
  SYS.DBMS_SQL.parse (ln_handle, 'begin ' || lv_procname || '; end;', SYS.DBMS_SQL.native);
  ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
  SYS.DBMS_SQL.close_cursor (ln_handle);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;

   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE put_p (av_text VARCHAR2) IS
 BEGIN
  gn_currline := gn_currline + 1;

  INSERT INTO textreport
              (norder, vtext
              )
       VALUES (gn_currline, av_text
              );
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setheaderrow_p (av_headerrow VARCHAR2, an_pos NUMBER) IS
 BEGIN
  IF an_pos > 0 THEN
   gt_header (an_pos) := av_headerrow;
   gb_useheader := TRUE;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------
 PROCEDURE setuseheader_p (tf BOOLEAN) IS
 BEGIN
  gb_useheader := tf;

  IF NOT tf THEN
   gt_header.DELETE;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------
 PROCEDURE printheader_p IS
 BEGIN
  FOR i IN gt_header.FIRST .. gt_header.LAST LOOP
   IF gt_header.EXISTS (i) THEN
    put_p (gt_header (i));
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------
 PROCEDURE clear_table IS
 BEGIN
  gn_currline := 0;

  DELETE FROM textreport;

  COMMIT;
 END;

------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_value(an_noperation NUMBER) IS
  lt_text             VARCHAR2(10000);
  ln_flag             NUMBER DEFAULT 0;
  ln_sum              NUMBER DEFAULT 0;
  ln_maket            NUMBER;
  ln_object           NUMBER;
 BEGIN
  clear_table;

  SELECT NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(init_str), 5))), 0), NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(c.init_str), 2))), 0)
  INTO   ln_maket, ln_object
  FROM   channels c
  WHERE  c.cid = (SELECT u.cid
                  FROM   uppdstat u
                  WHERE  u.noperation = an_noperation);

  SELECT TO_CHAR(MAX(ddate), 'yyyymmdd')
  INTO   lt_text
  FROM   uppdstat
  WHERE  noperation = an_noperation;

  SELECT NVL(TRIM(util_pg.get_param(MAX(vparam), 3)), util_pg.enterprise_char_f) || ':' || lt_text
  INTO   lt_text
  FROM   makets
  WHERE  nmaket = ln_maket;

  put_p('((//' || lt_text||':');

  FOR lc IN (SELECT   m.ngroup, m.vname,
                         '('
                      || NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(m.vcode, 2))), ln_object)
                      || '):('                      
                      || NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(m.vcode, 1))), 0)
                      || ')' vcode
             FROM     maketgroups m
             WHERE    m.nmaket = ln_maket
             ORDER BY 2, 1) LOOP
   ln_sum := 0;
   lt_text := '';

   FOR lc1 IN (SELECT   a.noperation, a.ngroup, a.norder, a.nvalue
               FROM     uppddata a
               WHERE    a.ngroup = lc.ngroup AND a.noperation = an_noperation
               ORDER BY a.norder) LOOP
    lt_text := lt_text || ':' || lc1.nvalue;
    ln_sum := ln_sum + NVL(lc1.nvalue, 0);
   END LOOP;

   --put_p(lc.vname || ':' || lc.vcode || lt_text || ':');
   put_p(lc.vcode || lt_text || ':');
   lt_text := '';
  END LOOP;

  put_p('==))');
 END;
-------------------------------------------------------------------------------------------------------------------
END;   -- Package Body REPORTS1_PG
/


