CREATE OR REPLACE 
PACKAGE BODY iccp_stat_pg AS
----------------------------------------------------------------------------------------------------
 PROCEDURE get_reason (res OUT common_pg.tcur) IS
 BEGIN
  OPEN res FOR
   SELECT   c.cid cid, c.vname cname
       FROM channels c, protocols p
      WHERE c.protocol_id = p.protocol_id AND p.protocol_id = 77
   ORDER BY 2;
 END;

----------------------------------------------------------------------------------------------------------
 PROCEDURE read_data (av_time_from VARCHAR2, av_time_till VARCHAR2, at_mid common_pg.tt_number, a_cur OUT common_pg.tcur) IS
  lv_subsel   VARCHAR2 (100);
 BEGIN
  lv_subsel := at_mid (1);

  IF (at_mid.COUNT > 1) THEN
   FOR i IN 2 .. at_mid.COUNT LOOP
    lv_subsel := lv_subsel || ', ' || at_mid (i);
   END LOOP;
  END IF;

  OPEN a_cur FOR 'select vname channel,nreason, decode(nreason,
                                       2,''ГН'',
                                       5,''ЖС'',
                                       6,''Сут.'',
                                       4,''ping'') statcs,
                                        DECODE(nreason,4,NULL,cnt) cycles,
            decode(cnt, 0, null, trunc(dura/cnt)) duration_sec,
            decode(cnt, 0, null, DECODE(nreason,4,trunc(send),trunc(send/cnt))) polls,
            decode(send, 0, null, trunc(lost/send*100, 2)) lost_pc,
            decode(send, 0, null, trunc(crtn/send*100, 2)) corrects_pc,
            decode(send, 0, null, trunc(errs/send*100, 2)) errors_pc,
            cnct connections, dcnt disconnections, mind min_del_msec, maxd max_del_msec,
   decode(rcvd, 0, null, trunc(aver/rcvd)) delay_msec

  from ( 
        SELECT count(*) cnt,nreason,i.CID,vname, sum(nsend) send, sum(nreceived) rcvd, sum(nloss) lost,
       sum(ncorrection) crtn, sum(nerror) errs, sum(nconnect) cnct, sum(ndisconnect) dcnt, sum(nduration) dura,
       min(nmindelay) mind, max(nmaxdelay) maxd, sum(navgdelay*nreceived) aver
    FROM iccpstat i
          ,channels c
        where i.CID = c.CID
        and c.CID in ('
                 || lv_subsel || ')
        and nreason in (2,5,6,4)
        and nsend > 0
    and ddate >= to_date(''' || av_time_from || ''',''dd.mm.yyyy hh24:mi:ss'')
        and ddate<=to_date(''' || av_time_till || ''',''dd.mm.yyyy hh24:mi:ss'')
        group by i.cid,nreason,vname
    )
          order by 1,2';
 END;

---------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_monitor (srt NUMBER DEFAULT 2, res OUT common_pg.tcur) IS
  lv_sql   VARCHAR2 (1000);
  v_srt    VARCHAR2 (32);
 BEGIN
  SELECT DECODE (ABS (srt), 3, ' STATE', 4, ' ASSOC', 5, ' state_date', 6, ' MESS_DATE', 7, ' MESS', ' NNAME')
    INTO v_srt
    FROM DUAL;

  lv_sql :=
   'select p.mid, 
    p.name NNAME, 
    decode(nvl(l.state_cod,0), 0, ''Остановлена'', 1, ''Запущена'', ''Остановленa с ошибкой ''||to_char(l.state_cod)) STATE,
     to_char(decode(iccp_stat_pg.get_work_associations(p.mid),0,''Нет'',''Акт'')||''[''||to_char(iccp_stat_pg.get_work_associations(p.mid))||'' из ''||to_char(iccp_stat_pg.get_all_associations(p.mid))||'']'') ASSOC, 
     l.state_date state_date, 
     to_char(l.luck,''DD.MM.YYYY HH24:MI:SS'') MESS_DATE,
     case 
        when 
            ((sysdate - l.luck) * 1440 > 10) AND (nvl(l.state_cod,0) = 1) then  ''Зависла''
        else 
            l.state_descr 
     end 
        MESS
        from points p, Last_Save l
           where p.parent = :iccpmid AND l.mid = p.mid
           order by '
   || v_srt;

  IF srt < 0 THEN
   lv_sql := lv_sql || ' desc';
  END IF;

  OPEN res FOR lv_sql USING util_pg.cn_iccpmid;
 END;

-----------------------------------------------------------------------------------------------------
/* PROCEDURE get_messages (dt_from DATE, dt_till DATE, an_id NUMBER, res OUT common_pg.tcur) IS
  ld_sys   DATE := SYSDATE;
 BEGIN
  OPEN res FOR
   SELECT   TO_CHAR (dlastevent, 'DD.MM.YYYY HH24:MI:SS') || ' ' || vlastevent mess
       FROM iccpevents
      WHERE mid IN (SELECT     mid
                          FROM points
                    CONNECT BY PRIOR mid = PARENT
                    START WITH mid = an_id) AND dlastevent BETWEEN dt_from AND dt_till
   ORDER BY norder DESC;
 END;
*/
-----------------------------------------------------------------------------------------------------
 PROCEDURE get_associations (mmid NUMBER DEFAULT 0, srt NUMBER DEFAULT 2, res OUT common_pg.tcur) IS
  lv_sql   VARCHAR2 (1000);
  v_srt    VARCHAR2 (32);
 BEGIN
  SELECT DECODE (ABS (srt), 3, ' STATE', 4, ' state_date', 5, ' MESS_DATE', 6, 'MESS', ' NNAME')
    INTO v_srt
    FROM DUAL;

  lv_sql :=
   'select p.mid, p.name NNAME, decode(l.state_cod, 0, ''Неактивна'', 1, ''Активна'', ''Остановленa с ошибкой ''||to_char(l.state_cod)) STATE,
     l.state_date state_date, to_char(l.luck,''DD.MM.YYYY HH24:MI:SS'')MESS_DATE, l.state_descr MESS
     from points p, Last_Save l where p.parent = :mmid AND p.mid = l.mid order by '|| v_srt;

  IF srt < 0 THEN
   lv_sql := lv_sql || ' desc';
  END IF;

  OPEN res FOR lv_sql USING mmid;
 END;

-----------------------------------------------------------------------------------------------------
 FUNCTION get_all_associations (mmid NUMBER)
  RETURN NUMBER IS
  ret   NUMBER DEFAULT 0;
 BEGIN
  SELECT COUNT (p.mid)
    INTO ret
    FROM points p
   WHERE p.PARENT = mmid;

  RETURN ret;
 END;

-----------------------------------------------------------------------------------------------------
 FUNCTION get_work_associations (mmid NUMBER)
  RETURN NUMBER IS
  ret   NUMBER DEFAULT 0;
 BEGIN
  SELECT COUNT (p.mid)
    INTO ret
    FROM points p, last_save l
   WHERE p.PARENT = mmid AND p.mid = l.mid AND l.state_cod > 0;

  RETURN ret;
 END;

-----------------------------------------------------------------------------------------------------
 PROCEDURE update_servname (mmid NUMBER DEFAULT 0, newname VARCHAR2) IS
 BEGIN
  UPDATE points p
     SET p.NAME = newname
   WHERE p.mid = mmid;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'ICCP_STAT_PG.update_ServName: Ошибка изменения таблицы points. ' || CHR (10) || SQLERRM (SQLCODE));
   ROLLBACK;
 END;
------------------------------------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.ICCP_STAT_PG

