CREATE OR REPLACE 
PACKAGE BODY iccpdisp_pg IS
------------------------------------------------------------------------------------------------------------------------
   -- Интерфейс взаимодействия БД с ICCP
   -- дата создания 17/10/2010 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
/*   ----Тест
declare
ln_srv NUMBER:=1;
ln_type NUMBER:=0;
lt_association common_pg.tt_varchar2;
begin
for i in 1..10 loop
lt_association(i):='Ассоциация '||i;
end loop;
ICCPDISP_PG.start_p (ln_srv,0,lt_association);
ICCPDISP_PG.stop_p (ln_srv);
end;
*/
------------------------------------------------------------------------------------------------------------------------
 --******************************          Декларация           ******************************************************--
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE falive_p(an_srvmid NUMBER);

------------------------------------------------------------------------------------------------------------------------
--*******************        Вспомогательные процедуры диспетчера                  ******************************************--
------------------------------------------------------------------------------------------------------------------------
--Возвращает mid по номеру сервера
 FUNCTION get_midbysrvnum(an_srv NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT MIN(mid)
    INTO ln_ret
    FROM points
   WHERE PARENT = util_pg.cn_iccpmid AND short_name = an_srv;

  RETURN ln_ret;
 END;

 ------------------------------------------------------------------------------------------------------------------------
--Возвращает mid по номеру сервера
 FUNCTION get_midbyassname(an_srvmid NUMBER, av_name VARCHAR2)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT MIN(mid)
    INTO ln_ret
    FROM points
   WHERE PARENT = an_srvmid AND short_name = av_name;

  RETURN ln_ret;
 END;

 ------------------------------------------------------------------------------------------------------------------------
--*******************        Основные процедуры диспетчера                  ******************************************--
------------------------------------------------------------------------------------------------------------------------
   --Запуск клиента/сервера ICCP an_type - 0/1 Клиент - сервер ICCP
 PROCEDURE start_p(an_srv NUMBER, an_type NUMBER, at_association common_pg.tt_varchar2) IS
  ld_sys      DATE   := SYSDATE;
  ln_srvmid   NUMBER := get_midbysrvnum(an_srv);
  ln_tmpmid   NUMBER;
 BEGIN
  IF at_association.COUNT = 0 THEN
   RETURN;
  END IF;

--Если не нашли, то добавляем
  IF ln_srvmid IS NULL THEN
   editfeedergroup_pg.ins_p(util_pg.cn_iccpmid, an_srv, an_srv, ln_srvmid);
   admin_pg.ins_last_save(ln_srvmid, '');
  END IF;

  DELETE FROM textreport;                                                 --Нужна временная таблица для следующих Select

  FOR i IN 1 .. at_association.COUNT LOOP
   INSERT INTO textreport
               (norder, vtext
               )
        VALUES (i, at_association(i)
               );
  END LOOP;

--Удаляем лишнее
  FOR lc IN (SELECT NVL(mid, 0) mid
               FROM points
              WHERE PARENT = ln_srvmid AND NAME NOT IN(SELECT vtext
                                                         FROM textreport)) LOOP
   DELETE FROM points
         WHERE mid = lc.mid;
  END LOOP;

--Добавляем новое
  FOR lc IN (SELECT vtext vname
               FROM textreport
             MINUS
             SELECT NAME vname
               FROM points
              WHERE PARENT = ln_srvmid) LOOP
   editfeedergroup_pg.ins_p(ln_srvmid, lc.vname, lc.vname, ln_tmpmid);
   admin_pg.ins_last_save(ln_tmpmid, '');
  END LOOP;

--Обновляем состояние ассоциаций
  UPDATE last_save
     SET state_date = ld_sys,
         state_descr = 'Не активна',
         luck = NULL,
         state_cod = 0
   WHERE mid IN(SELECT mid
                  FROM points
                 WHERE PARENT = ln_srvmid);

--Обновляем состояние сервиса
  UPDATE last_save
     SET state_date = ld_sys,
         luck = ld_sys,
         state_descr = 'Работает',
         state_cod = 1
   WHERE mid = ln_srvmid;

  ln_tmpmid := admin_pg.ins_journal_p(ld_sys, ln_srvmid, 0, 'Запущена', NULL, NULL);

--Чистим временныое
  DELETE FROM textreport;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'iccpdisp_pg.start_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Вызывается при остановке клиента/сервера ICCP an_stoptype-0 Норма, иначе код ошибки
 PROCEDURE stop_p(an_srv NUMBER, an_endcode NUMBER) IS
  ld_sys      DATE   := SYSDATE;
  ln_srvmid   NUMBER := get_midbysrvnum(an_srv);
 BEGIN
--Обновляем состояние ассоциаций
  UPDATE last_save
     SET state_date = ld_sys,
         state_descr = 'Неактивна',
         luck = NULL,
         state_cod = 0
   WHERE mid IN(SELECT mid
                  FROM points
                 WHERE PARENT = ln_srvmid);

--Обновляем состояние сервиса
  UPDATE last_save
     SET state_date = ld_sys,
         luck = ld_sys,
         state_descr = 'Остановлена',
         state_cod = -ABS(an_endcode)
   WHERE mid = ln_srvmid;

  ln_srvmid := admin_pg.ins_journal_p(ld_sys, ln_srvmid, -ABS(an_endcode), 'Остановлена', NULL, NULL);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'iccpdisp_pg.stop_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Я жив
 PROCEDURE falive_p(an_srvmid NUMBER) IS
  ld_sys   DATE := SYSDATE;
 BEGIN
  UPDATE last_save
     SET luck = ld_sys,
         clock = NVL(clock, 0) + 1
   WHERE mid = an_srvmid;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'iccpdisp_pg.falive_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Я жив
 PROCEDURE alive_p(an_srv NUMBER) IS
 BEGIN
  falive_p(get_midbysrvnum(an_srv));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Установка связи
 PROCEDURE begin_ass_p(an_srv NUMBER, av_assname VARCHAR2) IS
  ld_sys      DATE   := SYSDATE;
  ln_srvmid   NUMBER := get_midbysrvnum(an_srv);
  ln_assmid   NUMBER := get_midbyassname(ln_srvmid, av_assname);
 BEGIN
--Обновляем состояние ассоциации
  UPDATE last_save
     SET state_date = ld_sys,
         luck = ld_sys,
         state_descr = 'Активна',
         state_cod = 1
   WHERE mid = ln_assmid;

  ln_srvmid := admin_pg.ins_journal_p(ld_sys, ln_assmid, 0, 'Перешла в состояние Активна', NULL, NULL);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'iccpdisp_pg.begin_ass_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Разрыв связи
 PROCEDURE end_ass_p(an_srv NUMBER, av_assname VARCHAR2, an_endcode NUMBER DEFAULT 0) IS
  ld_sys      DATE   := SYSDATE;
  ln_srvmid   NUMBER := get_midbysrvnum(an_srv);
  ln_assmid   NUMBER := get_midbyassname(ln_srvmid, av_assname);
 BEGIN
--Обновляем состояние ассоциации
  UPDATE last_save
     SET state_date = ld_sys,
         luck = ld_sys,
         state_descr = 'Неактивна',
         state_cod = -ABS(an_endcode)
   WHERE mid = ln_assmid;

  ln_srvmid := admin_pg.ins_journal_p(ld_sys, ln_assmid, -ABS(an_endcode), 'Перешла в состояние Неактивна', NULL, NULL);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'iccpdisp_pg.end_ass_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Запись сообщения
 PROCEDURE message_p(an_srv NUMBER, av_assname VARCHAR2, av_mes VARCHAR2) IS
 BEGIN
--Обновляем состояние ассоциации
  set_iccp_event_p(get_midbyassname(get_midbysrvnum(an_srv), av_assname), av_mes);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'iccpdisp_pg.message_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись события по iccp в log
 PROCEDURE set_iccp_event_p(an_mid NUMBER, av_event VARCHAR2) IS
  ld_sys     DATE   DEFAULT SYSDATE;
  ln_order   NUMBER;
  ln_seq     NUMBER;
 BEGIN
  IF NVL(util_pg.locksysjournal_f, 0) <> 1 THEN
   BEGIN
    INSERT INTO iccpevents
                (norder, mid, dlastevent, vlastevent
                )
         VALUES (iccp_seq.NEXTVAL, an_mid, ld_sys, av_event
                );
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     SELECT MAX(norder)
       INTO ln_order
       FROM iccpevents;

     SELECT iccp_seq.NEXTVAL
       INTO ln_seq
       FROM DUAL;

     WHILE ln_seq <= ln_order AND ln_seq > 0 LOOP
      SELECT iccp_seq.NEXTVAL
        INTO ln_seq
        FROM DUAL;
     END LOOP;

     INSERT INTO iccpevents
                 (norder, mid, dlastevent, vlastevent
                 )
          VALUES (iccp_seq.NEXTVAL, an_mid, ld_sys, av_event
                 );
    WHEN OTHERS THEN
     RAISE;
   END;
  END IF;

  UPDATE last_save
     SET luck = ld_sys,
         state_descr = SUBSTR(av_event, 1, 150)
   WHERE mid = an_mid;
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                                                                         -- Package Body ICCPDISP_PG
/


-- End of DDL Script for Package Body RYDA.ICCPDISP_PG

