CREATE OR REPLACE 
PACKAGE BODY imp_others_ev2 IS
 ------------------------------------------------------------------------------------------------------------------------
    -- пакет поддержки синхронизации ТУ с Energy Vision
    -- дата создания 07/05/2008 Сечин А.А.
 ------------------------------------------------------------------------------------------------------------------------
     -- Сохранение конфигурации по системе Возвращает npoints.mid
 PROCEDURE setconfigstatus(
  an_root           NUMBER, --Ид. корня в дереве ТУ
  av_systemname     VARCHAR2, --Наименование локальной системы
  an_mid        OUT NUMBER) --Ид объекта в локальной системе
                            IS
 BEGIN
  admin_pg.begin_p;
  --Ищем подходящую вершину если она есть, если нашли то выходим иначе создаем заново
  FOR lc IN (SELECT     mid
                   FROM points
                  WHERE name = UPPER(av_systemname) AND ind IN (1, 2)
             CONNECT BY PRIOR mid = parent
             START WITH mid = an_root
               ORDER BY LEVEL, mid) LOOP
   an_mid := lc.mid;
   RETURN;
  END LOOP;
  editfeedergroup_pg.ins_p_a(an_root, UPPER(av_systemname), UPPER(av_systemname), NULL, an_mid);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'imp_others_ev2.setconfigstatus: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 -- Сохранение конф счетчика
 PROCEDURE setmeterconfig(
  an_mid       NUMBER, --Ид объекта в локальной системе
  an_id        NUMBER, --Локальный идентификатор счетчика
  ad_stamp     DATE, --метка времени конфигурации
  av_name      VARCHAR2, -- наименование места установки прибора учета
  av_desc      VARCHAR2, -- описание (комментарий)
  av_metertype VARCHAR2, -- тип счетчика
  av_serial    VARCHAR2, --  серийный номер
  an_objectid  NUMBER, -- глобальный идентификатор энергообъекта
  an_kc        NUMBER -- Коеф счетчика
                     ) IS
  ln_mid  NUMBER;
  ln_cnt  NUMBER;
  lv_name VARCHAR2(2000) DEFAULT av_name;
  ld_date DATE;
 BEGIN
  SELECT     MAX(mid), COUNT(*)
        INTO ln_mid, ln_cnt
        FROM points
       WHERE nroot = an_id
  CONNECT BY PRIOR mid = parent
  START WITH parent = an_mid;
  IF av_desc IS NOT NULL THEN
   lv_name := lv_name || ' (' || av_desc || ')';
  END IF;
  lv_name := SUBSTR(lv_name, 1, 40);
  IF ln_cnt > 1 THEN
   raise_application_error(-20005, 'Точка учета для синхронизации данных определена неодназначно.');
  ELSIF ln_cnt = 1 THEN
   editfeeders_pg.upd_p_a(
    ln_mid, an_mid, 3, lv_name || '_' || an_id, lv_name, 0, 0, 0, 0, 1, 0, SUBSTR(av_desc, 1, 8), 0, 0, 0, NVL(
                                                                                                            an_kc, 1),
    0);
   UPDATE meters
      SET mtrsn = av_serial,
          mtype = av_metertype,
          date_time = DECODE(ad_stamp, TO_DATE('30.12.1899', 'dd.mm.yyyy'), date_time, ad_stamp)
    WHERE mid = ln_mid AND entype = 7;
  ELSE
   editfeeders_pg.ins_p_synchro(
    an_mid, 3, lv_name || '_' || an_id, lv_name, 1, 0, SUBSTR(av_desc, 1, 8), 0, 0, 0, NVL(an_kc, 1), an_id, 0, ln_mid);
   IF ad_stamp = TO_DATE('30.12.1899', 'dd.mm.yyyy') THEN
    ld_date := SYSDATE;
   ELSE
    ld_date := ad_stamp;
   END IF;
   editfeeders_pg.upd_meters_a(
    ln_mid, 7, '*', av_serial, ld_date, 1000000 - 1 / 1000, av_metertype, 5, 100, 10000, 1 / 2, TO_CHAR(ld_date, 'YYYY'),
    TRUNC((TO_CHAR(ld_date, 'MM') - 1) / 3) + 1);
  END IF;
  UPDATE feeders
     SET canal = an_id
   WHERE mid = ln_mid;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'imp_others_ev2.setmeterconfig: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body imp_others_ev2
/


-- End of DDL Script for Package Body RYDA.IMP_OTHERS_EV2

-- Start of DDL Script for Package Body RYDA.IMP_OTHERS_KH
-- Generated 14.04.2014 9:34:58 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY imp_others_kh IS
 ------------------------------------------------------------------------------------------------------------------------
    -- пакет поддержки синхронизации ТУ с АСКУЭ Хартэп
    -- дата создания 23/06/2008 Сечин А.А.
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE synchronize(
  an_mid  NUMBER, --Ид корня
  an_id   NUMBER, --Ид вершины в удаленной БД
  av_link VARCHAR2 -- наименование link на удаленную БД
                  ) IS
  lc_sel        common_pg.tcur;
  lt_parent     common_pg.tt_number;
  ln_mid        NUMBER;
  ln_parent     NUMBER;
  ln_level      NUMBER;
  ln_ind        NUMBER;
  lv_name       VARCHAR2(256);
  lv_short_name VARCHAR2(256);
  ln_tmpmid     NUMBER;
  ln_smart      NUMBER;
  ln_q1234      NUMBER;
  lv_cellnum    VARCHAR2(2000);
  ln_power      NUMBER;
  ln_current1   NUMBER;
  ln_current2   NUMBER;
  ln_kc         NUMBER;
  ln_power2     NUMBER;
 BEGIN
  lt_parent(0) := an_mid;
  DELETE FROM points
        WHERE parent = an_mid;
  OPEN lc_sel FOR 'select mid,parent,level,ind,name,short_name from points@' || av_link ||
                  ' connect by prior mid=parent start with parent=' || an_id;
  LOOP
   FETCH lc_sel INTO ln_mid, ln_parent, ln_level, ln_ind, lv_name, lv_short_name;
   EXIT WHEN lc_sel%NOTFOUND;
   IF ln_ind in (3,4) THEN --точка
    EXECUTE IMMEDIATE 'select DECODE(smart, ''*'',1,0),DECODE(q1234, ''*'',1,0),CELLNUM,power,current1,current2,kc,power2 from feeders@' ||
                      av_link || ' where mid=' || ln_mid
     INTO ln_smart, ln_q1234, lv_cellnum, ln_power, ln_current1, ln_current2, ln_kc, ln_power2;
    editfeeders_pg.ins_p_synchro(
     lt_parent(ln_level - 1), ln_ind, lv_name, lv_short_name, ln_smart, ln_q1234, lv_cellnum, ln_power, ln_current1,
     ln_current2, ln_kc, ln_mid, ln_power2, ln_tmpmid);
    UPDATE feeders
       SET canal = ln_mid
     WHERE mid = ln_tmpmid;
   ELSE --папка
    editfeedergroup_pg.ins_p_synchro(lt_parent(ln_level - 1), lv_name, lv_short_name, ln_mid, ln_tmpmid);
   END IF;
   lt_parent(ln_level) := ln_tmpmid;
   COMMIT;
  END LOOP;
  CLOSE lc_sel;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'imp_others_kh.synchronize: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body imp_others_kh
/


-- End of DDL Script for Package Body RYDA.IMP_OTHERS_KH

-- Start of DDL Script for Package Body RYDA.INDIC_PG
-- Generated 14.04.2014 9:34:58 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY indic_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет работы с показаниями
  -- дата создания 13/10/2001 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
---------------      Interface        -------------------------------------------------
------------------------------------------------------------------------------------------------------------------------
 gn_1               NUMBER DEFAULT 5;   --Округление показаний
 gn_2               NUMBER DEFAULT 3;   --Округление расхода
 cn_lock   CONSTANT NUMBER := 30;
 cn_rn     CONSTANT NUMBER := 10;   --макс кол знаков при отсутствии округления квт*ч
 gn_outputgroup     NUMBER;
 gn_task_code       NUMBER;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE in_hole (an_mid NUMBER, an_kind NUMBER, ad_date DATE, an_type NUMBER, an_r NUMBER);

 PROCEDURE calc_hh24_round (an_mid NUMBER, an_table NUMBER, an_kind NUMBER, ad_date DATE, an_type NUMBER, an_r NUMBER,an_hourtime NUMBER DEFAULT 0,--сдвиг по временной зоне
                                                                                                             an_summer NUMBER DEFAULT 1 --есть ли переход зима-лето
                                                                                                             );

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calc_hh24 (an_mid NUMBER, an_table NUMBER, an_kind NUMBER, ad_date DATE, an_type NUMBER, an_r NUMBER,an_hourtime NUMBER ,--сдвиг по временной зоне
                                                                                                             an_summer NUMBER  --есть ли переход зима-лето
                                                                                                             ) IS
  lv_param   VARCHAR2 (256);
 BEGIN
  IF util_pg.get_customer_id = 3 THEN
   SELECT util_pg.get_param (MAX (vinfo), 1)
     INTO lv_param
     FROM feeders
    WHERE mid = an_mid;

   IF lv_param = '1' THEN
    calc_hh24_rejime (an_mid, an_table, an_kind, ad_date, an_type, an_r);
   END IF;
  ELSE
   calc_hh24_round (an_mid, an_table, an_kind, ad_date, an_type, an_r,an_hourtime,an_summer);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calc_hh24_rejime (an_mid NUMBER, an_table NUMBER, an_kind NUMBER, ad_date DATE, an_type NUMBER, an_r NUMBER) IS
  ln_r       NUMBER              DEFAULT NVL (ROUND (an_r), 0);
  ld_begin   DATE                DEFAULT util_pg.trunchh24_2 (getlastdate (an_mid, ad_date, an_type, 0, an_table, an_kind));
  ld_end     DATE                DEFAULT util_pg.trunchh24_2 (ad_date);
  lt_koef    common_pg.tt_number;
  kk         NUMBER              DEFAULT 1;
  ln_sm      NUMBER              DEFAULT 0;
  ld_tmp     DATE;
  ln_tmp     NUMBER;
  ln_kc      NUMBER;
 BEGIN
  ld_begin := NVL (ld_begin, TRUNC (ld_end) - 1);

  IF ROUND (ln_r, 2) < 0 OR ld_begin IS NULL OR ld_end IS NULL OR ld_begin >= ld_end THEN
   raise_application_error (-20001, 'indic_pg.calc_hh24_rejime: Не допустимые входные параметры.');
  END IF;

  UPDATE halfhour
     SET er = DECODE (an_type, 1, NULL, er),
         ed = DECODE (an_type, 2, NULL, ed),
         q1 = DECODE (an_type, 3, NULL, q1),
         q2 = DECODE (an_type, 4, NULL, q2),
         q3 = DECODE (an_type, 5, NULL, q3),
         q4 = DECODE (an_type, 6, NULL, q4),
         denter = SYSDATE
   WHERE mid = an_mid AND date_time > ld_begin AND date_time <= ld_end AND nsource = util_pg.cn_calcinput;

  SELECT ln_r - NVL (SUM (DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)), 0), ld_begin + 1 / 48
    --,util_pg.trunchh24_2(NVL(MAX(date_time), ld_begin) + 1 / 48) dt
  INTO   ln_r, ld_begin
    FROM halfhour
   WHERE mid = an_mid AND date_time > ld_begin AND date_time <= ld_end AND DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL;

  IF ROUND (ln_r, 2) < 0 THEN
   RETURN;
  --raise_application_error(-20001, 'indic_pg.calc_hh24_rejime: Ошибка вставки расхода. В БД уже есть расход за данный период, полученный автоматически больше вводимого.');
  ELSIF ld_begin > ld_end THEN
   raise_application_error (-20001, 'indic_pg.calc_hh24_rejime: Ошибка вставки расхода. В БД уже есть расход за данный период.');
  END IF;

  lt_koef := averrate_pg.averrate_f (an_mid, an_type, ld_begin, ld_end, 0);

  FOR i IN 1 .. lt_koef.COUNT LOOP
   lt_koef (i) := TRUNC (ln_r * lt_koef (i));
   ln_sm := ln_sm + lt_koef (i);
  END LOOP;

  ln_sm := ln_r - ln_sm;
  ld_tmp := ld_begin;

  FOR i IN 1 .. lt_koef.COUNT LOOP
   IF ln_sm >= 1 AND lt_koef (i) > 0 THEN
    ln_sm := ln_sm - 1;
    lt_koef (i) := lt_koef (i) + 1;
   END IF;
  END LOOP;

  FOR i IN 1 .. lt_koef.COUNT LOOP
   IF ln_sm >= 1 THEN
    ln_sm := ln_sm - 1;
    ln_tmp := lt_koef (i) + 1;

    IF i = lt_koef.COUNT AND ln_sm >= 1 THEN
     NULL;
    --raise_application_error(-20001, 'i='||i||'ln_sm='||ln_sm||' lt_koef.COUNT='||lt_koef.COUNT||' ld_tmp='||ld_tmp||' ld_begin='||ld_begin||' ld_end='||ld_end);
    END IF;
   ELSE
    ln_tmp := lt_koef (i);
   END IF;

   ln_tmp := ROUND (ln_tmp, cn_rn);

   SELECT MAX (kc)
     INTO ln_kc
     FROM feeders
    WHERE mid = an_mid;

   UPDATE halfhour
      SET er = DECODE (an_type, 1, ln_tmp, er),
          ed = DECODE (an_type, 2, ln_tmp, ed),
          q1 = DECODE (an_type, 3, ln_tmp, q1),
          q2 = DECODE (an_type, 4, ln_tmp, q2),
          q3 = DECODE (an_type, 5, ln_tmp, q3),
          q4 = DECODE (an_type, 6, ln_tmp, q4),
          nkc = ln_kc,
          denter = SYSDATE
    WHERE mid = an_mid AND date_time = ld_tmp AND nsource = util_pg.cn_calcinput;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO halfhour
                (mid, date_time, nsource, er, ed, q1,
                 q2, q3, q4, nkc
                )
         VALUES (an_mid, ld_tmp, util_pg.cn_calcinput, DECODE (an_type, 1, ln_tmp, NULL), DECODE (an_type, 2, ln_tmp, NULL), DECODE (an_type, 3, ln_tmp, NULL),
                 DECODE (an_type, 4, ln_tmp, NULL), DECODE (an_type, 5, ln_tmp, NULL), DECODE (an_type, 6, ln_tmp, NULL), ln_kc
                );
   END IF;

   ld_tmp := ld_tmp + 1 / 48;
  END LOOP;

  das_pg.calcpoint4bill (an_mid, ld_begin, ld_end);
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calc_hh24_round (an_mid NUMBER, an_table NUMBER, an_kind NUMBER, ad_date DATE, an_type NUMBER, an_r NUMBER,an_hourtime NUMBER,--сдвиг по временной зоне
                                                                                                             an_summer NUMBER  --есть ли переход зима-лето
                                                                                                             ) IS
  ln_r       NUMBER             DEFAULT NVL (ROUND (an_r), 0);
  ld_begin   DATE               DEFAULT util_pg.trunchh24_2 (getlastdate (an_mid, ad_date, an_type, 0, an_table, an_kind));
  ld_end     DATE               DEFAULT util_pg.trunchh24_2 (ad_date);
  lt_info    averrate_pg.ttinfo;
  ln_tmp     NUMBER;
  ln_kc      NUMBER;
 BEGIN

   
  IF an_table IN (6, 8) THEN   --Только последние сутки
   ld_begin := GREATEST (ld_begin, TRUNC (ld_end) - 1);
  ELSIF an_table = 9 THEN   --Дырки
   in_hole (an_mid, an_kind, ad_date, an_type, an_r);
   RETURN;
  END IF;

  SAVEPOINT calc_hh24_sp;
  ld_begin := NVL (ld_begin, TRUNC (ld_end) - 1);

  IF ROUND (ln_r, 2) < 0 OR ld_begin IS NULL OR ld_end IS NULL OR ld_begin >= ld_end THEN
   raise_application_error (-20001, 'indic_pg.calc_hh24_round: Не допустимые входные параметры.');
  END IF;

  IF (an_summer = 0) THEN 
  UPDATE halfhour
     SET er = DECODE (an_type, 1, NULL, er),
         ed = DECODE (an_type, 2, NULL, ed),
         q1 = DECODE (an_type, 3, NULL, q1),
         q2 = DECODE (an_type, 4, NULL, q2),
         q3 = DECODE (an_type, 5, NULL, q3),
         q4 = DECODE (an_type, 6, NULL, q4),
         denter = SYSDATE
   WHERE mid = an_mid AND util_pg.to_unlocaltime (date_time) > ld_begin+an_hourtime/24
    AND util_pg.to_unlocaltime (date_time) <= ld_end+an_hourtime/24
     AND nsource IN (util_pg.cn_manualinput, util_pg.cn_manualinputw);
 
   SELECT ln_r - NVL (SUM (DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)), 0), util_pg.trunchh24_2 (NVL (MAX (date_time), ld_begin) + 1 / 48) dt
    INTO ln_r, ld_begin
    FROM halfhour
   WHERE mid = an_mid AND util_pg.to_unlocaltime (date_time) > ld_begin+an_hourtime/24 
   AND util_pg.to_unlocaltime (date_time) <= ld_end+an_hourtime/24 
   AND DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL;
  ELSE
  UPDATE halfhour
     SET er = DECODE (an_type, 1, NULL, er),
         ed = DECODE (an_type, 2, NULL, ed),
         q1 = DECODE (an_type, 3, NULL, q1),
         q2 = DECODE (an_type, 4, NULL, q2),
         q3 = DECODE (an_type, 5, NULL, q3),
         q4 = DECODE (an_type, 6, NULL, q4),
         denter = SYSDATE
   WHERE mid = an_mid AND date_time > ld_begin+an_hourtime/24
    AND date_time <= ld_end+an_hourtime/24
     AND nsource IN (util_pg.cn_manualinput, util_pg.cn_manualinputw);
     
     SELECT ln_r - NVL (SUM (DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)), 0), util_pg.trunchh24_2 (NVL (MAX (date_time), ld_begin) + 1 / 48) dt
    INTO ln_r, ld_begin
    FROM halfhour
   WHERE mid = an_mid AND date_time > ld_begin+an_hourtime/24 AND date_time <= ld_end+an_hourtime/24 
   AND DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL;
 END IF;
 
  

  IF ROUND (ln_r, 2) < 0 OR ld_begin > ld_end THEN
   IF util_pg.getparamvalue_f (32) = 1 THEN
    ROLLBACK TO SAVEPOINT calc_hh24_sp;
    RETURN;
   ELSE
    IF ROUND (ln_r, 2) < 0 THEN
     raise_application_error (-20001,
                              'indic_pg.calc_hh24_round: Ошибка вставки расхода. В БД уже есть расход за данный период, полученный автоматически больше вводимого.');
    ELSIF ld_begin > ld_end THEN
     raise_application_error (-20001, 'indic_pg.calc_hh24_round: Ошибка вставки расхода. В БД уже есть расход за данный период.');
    END IF;
   END IF;
  END IF;
  
 

  averrate_pg.createtinfo (an_mid, ld_begin, ld_end, an_type, 1, ln_r, lt_info,1,an_hourtime, an_summer );

  SELECT MAX (kc)
    INTO ln_kc
    FROM feeders
   WHERE mid = an_mid;
   
  
   if an_summer=0 then
 
        FOR i IN 1 .. lt_info.COUNT LOOP
       lt_info (i).d := util_pg.to_localtime(lt_info (i).d) +an_hourtime/24; -- an_hourtime;
       end loop;
    end if;
 

  FOR i IN 1 .. lt_info.COUNT LOOP
   ln_tmp := lt_info (i).e;

   UPDATE halfhour
      SET er = DECODE (an_type, 1, ln_tmp, er),
          ed = DECODE (an_type, 2, ln_tmp, ed),
          q1 = DECODE (an_type, 3, ln_tmp, q1),
          q2 = DECODE (an_type, 4, ln_tmp, q2),
          q3 = DECODE (an_type, 5, ln_tmp, q3),
          q4 = DECODE (an_type, 6, ln_tmp, q4),
          vqm = qm_pg.cv_manualqm,
          nkc = ln_kc,
          denter = SYSDATE
    WHERE mid = an_mid AND date_time = lt_info (i).d AND nsource = lt_info (i).src;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO halfhour
                (mid, date_time, nsource, er, ed, q1,
                 q2, q3, q4, nkc, vqm
                )
         VALUES (an_mid, lt_info (i).d, lt_info (i).src, DECODE (an_type, 1, ln_tmp, NULL), DECODE (an_type, 2, ln_tmp, NULL), DECODE (an_type, 3, ln_tmp, NULL),
                 DECODE (an_type, 4, ln_tmp, NULL), DECODE (an_type, 5, ln_tmp, NULL), DECODE (an_type, 6, ln_tmp, NULL), ln_kc, qm_pg.cv_manualqm
                );
   END IF;
  END LOOP;

  das_pg.calcpoint4bill (an_mid, ld_begin, ld_end);
 END;

