 /* Пересчитывает расход по показаниям (ad_date - стартовая дата > больше которой нужно пересчитать,
    возвращает дату следующих показаний или NULL - если дошли до конца)
    an_table =5 BILLORG иначе MONTHS
 */
 FUNCTION recalcdiff (an_mid NUMBER, ad_date DATE, an_table NUMBER DEFAULT 5)
  RETURN DATE IS
  ld_date     DATE;
  ln_digits   NUMBER;
  ln_erm      NUMBER;
  ln_edm      NUMBER;
  ln_q1m      NUMBER;
  ln_q3m      NUMBER;
  ln_q2m      NUMBER;
  ln_q4m      NUMBER;
  ln_aerm     NUMBER;
  ln_aedm     NUMBER;
  ln_aq1m     NUMBER;
  ln_aq3m     NUMBER;
  ln_aq2m     NUMBER;
  ln_aq4m     NUMBER;
  ln_berm     NUMBER;
  ln_bedm     NUMBER;
  ln_bq1m     NUMBER;
  ln_bq3m     NUMBER;
  ln_bq2m     NUMBER;
  ln_bq4m     NUMBER;
  ln_cerm     NUMBER;
  ln_cedm     NUMBER;
  ln_cq1m     NUMBER;
  ln_cq3m     NUMBER;
  ln_cq2m     NUMBER;
  ln_cq4m     NUMBER;
  ln_derm     NUMBER;
  ln_dedm     NUMBER;
  ln_dq1m     NUMBER;
  ln_dq3m     NUMBER;
  ln_dq2m     NUMBER;
  ln_dq4m     NUMBER;
 BEGIN
  SELECT LENGTH (TRUNC (MAX (digits)))
    INTO ln_digits
    FROM meters
   WHERE mid = an_mid AND entype = 7;

  IF an_table = 5 THEN   --Мы инвертируем, потому что знаем что set_bill_meter вернет назад
   FOR lc IN (SELECT *
                FROM billorg
               WHERE mid = an_mid AND date_time = (SELECT MIN (date_time)
                                                     FROM billorg
                                                    WHERE mid = an_mid AND date_time > ad_date)) LOOP
    ln_erm := lc.erm;
    ln_edm := lc.edm;
    ln_q1m := lc.q1m;
    ln_q3m := lc.q3m;
    ln_q2m := lc.q2m;
    ln_q4m := lc.q4m;
    ln_aerm := lc.aerm;
    ln_aedm := lc.aedm;
    ln_aq1m := lc.aq1m;
    ln_aq3m := lc.aq3m;
    ln_aq2m := lc.aq2m;
    ln_aq4m := lc.aq4m;
    ln_berm := lc.berm;
    ln_bedm := lc.bedm;
    ln_bq1m := lc.bq1m;
    ln_bq3m := lc.bq3m;
    ln_bq2m := lc.bq2m;
    ln_bq4m := lc.bq4m;
    ln_cerm := lc.cerm;
    ln_cedm := lc.cedm;
    ln_cq1m := lc.cq1m;
    ln_cq3m := lc.cq3m;
    ln_cq2m := lc.cq2m;
    ln_cq4m := lc.cq4m;
    ln_derm := lc.derm;
    ln_dedm := lc.dedm;
    ln_dq1m := lc.dq1m;
    ln_dq3m := lc.dq3m;
    ln_dq2m := lc.dq2m;
    ln_dq4m := lc.dq4m;
    util_pg.chdr (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
    util_pg.chdr (lc.mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m);
    util_pg.chdr (lc.mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m);
    util_pg.chdr (lc.mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m);
    util_pg.chdr (lc.mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m);
    comsrv_pg.set_bill_meter (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m, ln_berm, ln_bedm,
                              ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m,
                              ln_dq4m, lc.er_mtrsn, ln_digits, lc.date_time);
    ld_date := lc.date_time;
   END LOOP;
  ELSE
   FOR lc IN (SELECT *
                FROM monthsorg
               WHERE mid = an_mid AND date_time = (SELECT MIN (date_time)
                                                     FROM monthsorg
                                                    WHERE mid = an_mid AND date_time > ad_date)) LOOP
    ln_erm := lc.erm;
    ln_edm := lc.edm;
    ln_q1m := lc.q1m;
    ln_q3m := lc.q3m;
    ln_q2m := lc.q2m;
    ln_q4m := lc.q4m;
    ln_aerm := lc.aerm;
    ln_aedm := lc.aedm;
    ln_aq1m := lc.aq1m;
    ln_aq3m := lc.aq3m;
    ln_aq2m := lc.aq2m;
    ln_aq4m := lc.aq4m;
    ln_berm := lc.berm;
    ln_bedm := lc.bedm;
    ln_bq1m := lc.bq1m;
    ln_bq3m := lc.bq3m;
    ln_bq2m := lc.bq2m;
    ln_bq4m := lc.bq4m;
    ln_cerm := lc.cerm;
    ln_cedm := lc.cedm;
    ln_cq1m := lc.cq1m;
    ln_cq3m := lc.cq3m;
    ln_cq2m := lc.cq2m;
    ln_cq4m := lc.cq4m;
    ln_derm := lc.derm;
    ln_dedm := lc.dedm;
    ln_dq1m := lc.dq1m;
    ln_dq3m := lc.dq3m;
    ln_dq2m := lc.dq2m;
    ln_dq4m := lc.dq4m;
    util_pg.chdr (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
    util_pg.chdr (lc.mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m);
    util_pg.chdr (lc.mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m);
    util_pg.chdr (lc.mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m);
    util_pg.chdr (lc.mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m);
    comsrv_pg.set_months_meter (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m, ln_berm, ln_bedm,
                                ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m, ln_derm, ln_dedm, ln_dq1m, ln_dq3m,
                                ln_dq2m, ln_dq4m, lc.er_mtrsn, ln_digits, lc.date_time);
    ld_date := lc.date_time;
   END LOOP;
  END IF;

  RETURN ld_date;
 END;

