   -- Устанавливает признак включения, исключения из расчета.
 PROCEDURE setexceptcalc (an_mid NUMBER, ad_date DATE, an_source NUMBER, an_exceptcalc NUMBER) IS
  lv_state   VARCHAR2 (16);
 BEGIN
  gn_task_code := 630;

  IF an_exceptcalc IS NULL THEN
   lv_state := 'ВКЛЮЧЕН';
  ELSE
   lv_state := 'ИСКЛЮЧЕН';
  END IF;

  UPDATE halfhourold
     SET nexceptcalc = an_exceptcalc,denter=sysdate
   WHERE mid = an_mid AND date_time = ad_date AND nsource = an_source;
 
  admin_pg.fiscal_p (gn_task_code, 2,
                     'Изменено состояние включения в расчет на ''' || lv_state || ''' за ' || TO_CHAR (ad_date, 'DD.MM.YYYY HH24:MI:SS') || ' по точке учета '
                     || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
  calcformula_pg.calc_lagging_job;
 END;

------------------------------------------------------------------------------------------------------------------------
    -- Ввод поправок.
 PROCEDURE setcorrection (an_mid NUMBER, ad_from DATE, ad_till DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER,
 an_manual NUMBER, an_delete_all NUMBER, an_source NUMBER
 ) IS
  ln_source    NUMBER              DEFAULT an_source;
  ld_from      DATE                DEFAULT ad_from + 1 / 86400;
  ld_till      DATE                DEFAULT ad_till;
  ln_src       NUMBER              DEFAULT comsrv_pg.cn_auto;
  lv_qm        VARCHAR2 (32)       DEFAULT qm_pg.sbt (qm_pg.sbt (qm_pg.cv_okqm, 13, qm_pg.cn_add_ok), 10, qm_pg.cn_subst);
  lt_val       common_pg.tt_number;
  lt_info      averrate_pg.ttinfo;
  lt_tmpinfo   averrate_pg.ttinfo;
  lt_retval    common_pg.tt_number;
  ln_cnt       NUMBER;
 BEGIN
  IF ad_from IS NULL OR ad_till IS NULL THEN
   RETURN;
  END IF;

  IF an_delete_all = 1 THEN
   UPDATE halfhour
      SET er = DECODE (an_er, util_pg.cn_random, er),
          ed = DECODE (an_ed, util_pg.cn_random, ed),
          q1 = DECODE (an_q1, util_pg.cn_random, q1),
          q2 = DECODE (an_q2, util_pg.cn_random, q2),
          q3 = DECODE (an_q3, util_pg.cn_random, q3),
          q4 = DECODE (an_q4, util_pg.cn_random, q4)
    WHERE mid = an_mid AND date_time > ad_from AND date_time <= ad_till;

   DELETE FROM halfhour
         WHERE mid = an_mid AND date_time > ad_from AND date_time <= ad_till AND NVL (NVL (er, ed), NVL (q1, q3)) IS NULL;
  END IF;

  IF an_manual = 1 THEN
   lv_qm := qm_pg.sbt (lv_qm, 22, qm_pg.cn_manual);
   ln_src := util_pg.cn_manualinput;
  ELSIF ln_source = comsrv_pg.cn_maket THEN
   lv_qm := qm_pg.sbt (lv_qm, 22, qm_pg.cn_maket);
  END IF;

  lt_val (1) := an_er;
  lt_val (2) := an_ed;
  lt_val (3) := an_q1;
  lt_val (4) := an_q2;
  lt_val (5) := an_q3;
  lt_val (6) := an_q4;
  --Мы  сначала вычислим количество.
  averrate_pg.createtinfo (an_mid, ld_from, ld_till, 1, 0, 0, lt_info);
  ln_cnt := lt_info.COUNT;

  FOR i IN 1 .. 6 * ln_cnt LOOP
   lt_retval (i) := NULL;
  END LOOP;

  --Разбивка
  FOR j IN 1 .. 6 LOOP
   IF lt_val (j) = util_pg.cn_random THEN
    FOR i IN 1 .. ln_cnt LOOP
     lt_retval ((j - 1) * ln_cnt + i) := util_pg.cn_random;
    END LOOP;
   ELSIF lt_val (j) IS NOT NULL THEN
    lt_tmpinfo.DELETE;
    averrate_pg.createtinfo (an_mid, ld_from, ld_till, j, 0, lt_val (j), lt_tmpinfo);

    FOR i IN 1 .. ln_cnt LOOP
     IF i <= lt_tmpinfo.COUNT THEN
      lt_retval ((j - 1) * ln_cnt + i) := lt_tmpinfo (i).e;
     END IF;
    END LOOP;
   END IF;
  END LOOP;

  FOR i IN 1 .. ln_cnt LOOP
   calcformula_pg.ins_halfhouroldw (an_mid, util_pg.to_unlocaltime (lt_info (i).d, lt_info (i).src), lt_retval (i), lt_retval (ln_cnt + i),
                                    lt_retval (2 * ln_cnt + i), lt_retval (4 * ln_cnt + i), lt_retval (3 * ln_cnt + i), lt_retval (5 * ln_cnt + i), NULL, ln_source,
                                    lv_qm, NULL, ln_src, NULL, 1);
  END LOOP;

  IF an_manual = 1 THEN
   file_pg.startbyevents_p (47, an_mid, ld_from, ld_till);
   das_pg.calcpoint4bill (an_mid, TRUNC (ld_from), util_pg.ceil_d (ld_till, 1));
   admin_pg.fiscal_p (gn_task_code, 1,
                      'Произведен ввод поправки за период с ' || TO_CHAR (ad_from, 'DD.MM.YYYY HH24:MI') || ' по ' || TO_CHAR (ad_till, 'DD.MM.YYYY HH24:MI')
                      || ' по точке учета ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
   COMMIT;
   calcformula_pg.calc_lagging_job;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001,
                            'indic_pg.setcorrection: Ошибка ввода поправки. mid=' || an_mid || ' ' || 'date=''' || TO_CHAR (ad_from, 'dd.mm.yyyy hh24:mi:ss')
                            || '''' || CHR (10) || SQLERRM (SQLCODE));
 END;
