  --возвращает  an_midTimeZone;
 PROCEDURE set_timezone(an_midtimezone NUMBER) IS
 BEGIN
  gn_timezone := an_midtimezone;

  SELECT -NVL(MAX(nshift) / 24, 0), DECODE(MAX(dsummer), NULL, 0, 1)
  INTO   gn_timezoneshift, gn_dsummer
  FROM   timezones
  WHERE  nid = an_midtimezone;
 END;

