--// Для перемещения по спискам
 PROCEDURE interior_groupjump(
 an_groupislist NUMBER, an_stepprofile NUMBER, an_id_group NUMBER, an_period NUMBER, an_periodstart NUMBER, an_periodfinish NUMBER, acur_t OUT common_pg.tcur
 )                                                                                              --TInterior::GroupJump(long value) // Для перемещения по спискам
  IS
  lv_sql              VARCHAR(4000);
  lv_subselect        VARCHAR(1000);
 BEGIN
  subselect_p(an_stepprofile, an_periodstart, an_periodfinish, an_period, lv_subselect);

  IF (an_groupislist = 2) THEN
   lv_sql :=
       ' SELECT nvl(max(gr.gid),0) gid FROM groups g1, groups gr
       WHERE g1.gid='
    || an_id_group
    || ' AND g1.nroot2 = gr.nroot2 AND gr.nroot1 IS NULL  '
    || lv_subselect;
  ELSE
   lv_sql :=
    ' SELECT nvl(sum(decode(gr.nroot2, NULL, 1, 2)),0) GroupIsList
     FROM GROUPS gr WHERE gr.gid = ' || an_id_group || ' AND gr.nroot1 > 10  ' || lv_subselect;
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

