 PROCEDURE decperiod_p(an_ispoints NUMBER, av_decperiod OUT VARCHAR2) IS
 BEGIN
  IF (an_ispoints = 0) AND util_pg.get_customer_id IN(1, 51) THEN
   av_decperiod :=
       ' *DECODE(sign( to_number(to_char(P.date_time-1/86400, ''yyyymm'' ))-nvl(G.nfromperiod,0)),-1,NULL,1) '
    || '  *DECODE(sign(nvl(G.ntillperiod,299912)- to_number(to_char(P.date_time-1/86400, ''yyyymm'' ))),-1,NULL,1) ';
  ELSE
   av_decperiod := ' ';
  END IF;
 END;

