 PROCEDURE subselect_p(an_stepprofile NUMBER, an_fromperiod NUMBER, an_tillperiod NUMBER, an_period NUMBER, av_subselect OUT VARCHAR2) IS
 BEGIN
  IF util_pg.get_customer_id IN(1, 51) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    --  av_subselect := ' AND ( nvl(g.nfromperiod,0)<='||an_tillperiod||' OR nvl(g.ntillperiod,299912)>='||an_fromperiod||') ';
    av_subselect := ' AND ( nvl(gr.nfromperiod,0)<=' || an_tillperiod || ' OR nvl(gr.ntillperiod,299912)>=' || an_fromperiod || ') ';
   ELSE
    --  av_subselect := ' AND ('||an_period||' BETWEEN  nvl(g.nfromperiod,0) AND nvl(g.ntillperiod,299912)) ';
    av_subselect := ' AND (' || an_period || ' BETWEEN  nvl(gr.nfromperiod,0) AND nvl(gr.ntillperiod,299912)) ';
   END IF;
  ELSE
   av_subselect := ' ';
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE grouping_p(an_stepprofile NUMBER, av_firstdate VARCHAR2, an_stepprof NUMBER, av_grouping OUT VARCHAR2) IS
  ln_timezona         NUMBER;
  ln_dsummer          NUMBER;
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;
  ln_dsummer := interior_pg.get_dsummer;

  IF (ln_dsummer = 1) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    av_grouping := ' 0+to_char(P.date_time-1/86400- ' || ln_timezona || ',''mm'') ';
   ELSIF(an_stepprofile = gn_stpday) THEN
    av_grouping := ' 0+to_char(P.date_time-1/86400- ' || ln_timezona || ',''dd'') ';
   ELSIF(an_stepprofile = gn_stphour) THEN
    av_grouping := ' util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/' || an_stepprof || ' ,0,' || ln_timezona || ',' || ln_dsummer || ') ';
   ELSIF(an_stepprofile = gn_stpminute) THEN
    av_grouping :=
        ' 1+FLOOR((P.date_time-'
     || ln_timezona
     || '-
    to_date('''
     || av_firstdate
     || ''',''dd.mm.yyyy hh24:mi:ss'') + '
     || ln_timezona
     || ')*86400/'
     || an_stepprof
     || ' ) ';
   END IF;
  ELSE
   IF (an_stepprofile = gn_stpmonth) THEN
    av_grouping := ' 0+to_char(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ',nsource),''mm'') ';
   ELSIF(an_stepprofile = gn_stpday) THEN
    av_grouping := ' 0+to_char(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ',nsource),''dd'') ';
   ELSIF(an_stepprofile = gn_stphour) THEN
    av_grouping :=
     ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/' || an_stepprof || ' ,0,' || ln_timezona || ',' || ln_dsummer
     || ') ';
   ELSIF(an_stepprofile = gn_stpminute) THEN
    av_grouping :=
        ' 1+FLOOR((util_pg.to_unlocaltime (P.date_time - '
     || ln_timezona
     || ',nsource)-
    to_date('''
     || av_firstdate
     || ''',''dd.mm.yyyy hh24:mi:ss'') + '
     || ln_timezona
     || ')*86400/'
     || an_stepprof
     || ' ) ';
   END IF;
  END IF;
 END;

