  ln_timezona         NUMBER;
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;

  -- IF (ln_timeZona <= 0) THEN
  IF (an_stepprofile = gn_stpmonth) THEN
   av_grouping := ' 0+to_char(P.date_time,''mm'') ';
  ELSIF(an_stepprofile = gn_stpday) THEN
   av_grouping := ' 0+to_char(P.date_time,''dd'') ';
  END IF;
/*  ELSE
   IF (an_stepprofile = gn_stpmonth) THEN
      av_grouping := ' 0+util_pg.to_unlocaltime (P.date_time,nsource) ';
   ELSIF (an_stepprofile = gn_stpday) THEN
      av_grouping := ' 0+util_pg.to_unlocaltime (P.date_time,nsource) ';

  END IF;*/
 END;

