-- возвращает имя таблицы
 PROCEDURE interior2_choiceoftable_p(an_bird NUMBER, an_stepprofile NUMBER, av_oracletable OUT VARCHAR2) IS
 BEGIN
  IF (an_stepprofile = gn_stpmonth OR an_stepprofile = gn_stpday) AND gn_timezoneshift = 0 THEN
   av_oracletable := ' bill';
  ELSIF(an_stepprofile = gn_stphour OR an_stepprofile = gn_stpmonth OR an_stepprofile = gn_stpday) THEN
   av_oracletable := ' halfhour';
  ELSIF(an_stepprofile = gn_stpminute) THEN
   av_oracletable := ' profile';
  END IF;
 /* --Следующее мы перестали поддерживать
 IF (an_bird = 1) THEN av_oracletable := av_oracletable || '_l';  ELSIF (an_bird = 2) THEN   av_oracletable := av_oracletable || '_ol';  END IF;  */
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE choiceoftable_tariff_p(an_bird NUMBER, av_oracletable OUT VARCHAR2) IS
 BEGIN
-- av_oracletable := ' bill ';
  av_oracletable := ' halfhour';
 /* --Следующее мы перестали поддерживать
 IF (an_bird = 1) THEN av_oracletable := av_oracletable || '_l';  ELSIF (an_bird = 2) THEN   av_oracletable := av_oracletable || '_ol';  END IF;  */
 END;

---------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior1_selectdata_p(
 an_ispoints NUMBER, an_stepprofile NUMBER, an_codetemplate NUMBER, av_rowcount VARCHAR2, an_bird NUMBER, an_powerprofile NUMBER,
                                                                                                               --// Количество строк при выводе графика нагрузки
 an_stepprof NUMBER,                                                                                                      --//Минимальный шаг профиля в секундах
                    av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER,
 an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef          VARCHAR2(200);                                                            -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted         VARCHAR2(150);
  lv_subsel           VARCHAR2(1000);
  lv_subselect        VARCHAR2(400);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(400);
  lv_partly_ed        VARCHAR2(400);
  lv_decnsourcesec    VARCHAR2(1000);
  lv_decnsourcef      VARCHAR2(1000);
  lv_decperiod        VARCHAR2(400);
  lv_paramlist        VARCHAR2(2000);
  lv_grouping         VARCHAR2(1000);
  lv_oracletable      VARCHAR2(150);
  lv_sqltimezone      VARCHAR2(2000);
  ln_timezona         NUMBER;
  ln_countrow         NUMBER;
  ln_countfull        NUMBER;
  lv_sql              VARCHAR2(10000);
  lv_sql1             VARCHAR2(4000);
  lv_sql2             VARCHAR2(4000);
  lv_sql3             VARCHAR2(4000);
  lv_sql4             VARCHAR2(4000);
-----------------------------------
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;

  IF (gn_dsummer = 0) THEN
   lv_sqltimezone :=
       ' and  date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24))
                    and   date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
      AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  END IF;

----------------------------------------------------------------------------------------------------
  IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                   --год
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                 --месяц
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), lv_grouping, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSE                                                                                                                                    -- получасовки и сутки
   ln_countfull :=
    interior_pg.get_rowcount(an_idgroup, an_ispoints, av_rowcount, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period,
     TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'));
   ln_countrow :=
    interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
     an_periodforyearfinish, an_period);
  END IF;

-----------------------------------------------------------------------------------------------------------
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  takeofpartquerifornsorse_p(an_codetemplate, an_ispoints, an_stepprofile, av_rowcount, av_firstdate, av_lastdate, an_idgroup, interior_pg.get_hourtimezone,
   ln_countfull, ln_countrow, lv_decnsourcesec, lv_decnsourcef);
  /*  lv_decnsourcesec:=' ,0 ';
    lv_decnsourcef:=' ,0 ';*/
  decperiod_p(an_ispoints, lv_decperiod);
  interior2_choiceoftable_p(an_bird, an_stepprofile, lv_oracletable);
  grouping_p(an_stepprofile, av_firstdate, an_stepprof, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder(an_idgroup) = 1 THEN
    lv_subsel :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_idgroup || ') ';
   ELSE
    lv_subsel := ' G.mid=' || an_idgroup;
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
    lv_subsel :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_idgroup
     || lv_subselect
     || ') ';
   ELSE
    lv_subsel :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect
     || ') ';
   END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  IF (
      an_codetemplate = gn_aebo_pow_f OR an_codetemplate = gn_aero_pow_f OR an_codetemplate = gn_aedo_pow_f OR an_codetemplate = gn_rebo_pow_f
      OR an_codetemplate = gn_rero_pow_f OR an_codetemplate = gn_redo_pow_f
     ) THEN
   IF (an_stepprofile = gn_stphour) THEN
    lv_powkoef := '* ' ||(60 / an_powerprofile);
   ELSIF(an_stepprofile = gn_stpminute) THEN
    lv_powkoef := '* ' ||(3600 / an_stepprof);
   END IF;
  END IF;

  IF (an_codetemplate = gn_aebo_f OR an_codetemplate = gn_aebo_pow_f OR an_codetemplate = gn_aebo_sum_f) THEN
   lv_paramlist :=
       ' sum( -util_pg.sld( P.mid, P.er '
    || lv_powkoef
    || lv_partly_er
    || ', P.ed '
    || lv_powkoef
    || lv_partly_ed
    || ') *DECODE( '
    || lv_inverted
    || ' ,''y'',1,-1) '
    || lv_decperiod
    || ' )/'
    || gn_powercoeff
    || ' ';
  ELSIF(
        an_codetemplate = gn_aero_f OR an_codetemplate = gn_aero_pow_f OR an_codetemplate = gn_aero_sum_f OR an_codetemplate = gn_water_f
        OR an_codetemplate = gn_heat_f OR an_codetemplate = gn_gas_f
       ) THEN
   lv_paramlist :=
       ' sum(DECODE( '
    || lv_inverted
    || ' ,''y'',P.ed '
    || lv_powkoef
    || lv_partly_ed
    || ',P.er '
    || lv_powkoef
    || lv_partly_er
    || ' ) '
    || lv_decperiod
    || ' )/'
    || gn_powercoeff
    || '  ';
  ELSIF(an_codetemplate = gn_aedo_f OR an_codetemplate = gn_aedo_pow_f OR an_codetemplate = gn_aedo_sum_f) THEN
   lv_paramlist :=
       ' sum(DECODE( '
    || lv_inverted
    || ' ,''y'',P.er '
    || lv_powkoef
    || lv_partly_er
    || ' , P.ed '
    || lv_powkoef
    || lv_partly_ed
    || ' ) '
    || lv_decperiod
    || ' )/'
    || gn_powercoeff
    || ' ';
  ELSIF(an_codetemplate = gn_rebo_f OR an_codetemplate = gn_rebo_pow_f OR an_codetemplate = gn_rebo_sum_f) THEN
   lv_paramlist :=
       ' util_pg.sumn(sum(( -util_pg.sld( P.mid,P.q1 '
    || lv_powkoef
    || ',P.q3 '
    || lv_powkoef
    || ' ))*DECODE( '
    || lv_inverted
    || ' ,''y'',1,-1) '
    || lv_decperiod
    || ' ) , sum(( -util_pg.sld( P.mid, P.q2 '
    || lv_powkoef
    || ' , P.q4 '
    || lv_powkoef
    || ' ))*DECODE( '
    || lv_inverted
    || ' ,''y'',1,-1) '
    || lv_decperiod
    || ' ))/'
    || gn_powercoeff
    || ' ';
  ELSIF(an_codetemplate = gn_rero_f OR an_codetemplate = gn_rero_pow_f OR an_codetemplate = gn_rero_sum_f) THEN
   lv_paramlist :=
       ' util_pg.sumn(sum(DECODE( '
    || lv_inverted
    || ' ,''y'',P.q3 '
    || lv_powkoef
    || ' ,P.q1 '
    || lv_powkoef
    || ' ) '
    || lv_decperiod
    || ' ),sum(DECODE( '
    || lv_inverted
    || ' ,''y'',P.q4 '
    || lv_powkoef
    || ',P.q2 '
    || lv_powkoef
    || ') '
    || lv_decperiod
    || ' ))/'
    || gn_powercoeff
    || ' ';
  ELSIF(an_codetemplate = gn_redo_f OR an_codetemplate = gn_redo_pow_f OR an_codetemplate = gn_redo_sum_f) THEN
   lv_paramlist :=
       ' util_pg.sumn(sum(DECODE( '
    || lv_inverted
    || ' ,''y'',P.q1 '
    || lv_powkoef
    || ' ,P.q3 '
    || lv_powkoef
    || ' ) '
    || lv_decperiod
    || ' ), sum(DECODE( '
    || lv_inverted
    || ' ,''y'',P.q2 '
    || lv_powkoef
    || ',P.q4 '
    || lv_powkoef
    || ') '
    || lv_decperiod
    || ' ))/'
    || gn_powercoeff
    || ' ';
  END IF;

  IF (
      an_codetemplate = gn_redo_sum_f OR an_codetemplate = gn_rero_sum_f OR an_codetemplate = gn_rebo_sum_f OR an_codetemplate = gn_aedo_sum_f
      OR an_codetemplate = gn_aero_sum_f OR an_codetemplate = gn_aebo_sum_f
     ) THEN
   lv_sql :=
       ' select '
    || util_pg.hint_ordered
    || 'decode(grouping('
    || lv_grouping
    || ' ),
   1,0, '
    || lv_grouping
    || ' ) BGroup  ,
        decode(grouping('
    || lv_grouping
    || ' ),1,
          last_value ('
    || lv_paramlist
    || ')
     over (ORDER BY  '
    || lv_grouping
    || '  ROWS BETWEEN unbounded preceding AND CURRENT ROW),
     sum(
   '
    || lv_paramlist
    || '
     )
     over (ORDER BY  '
    || lv_grouping
    || '  ROWS BETWEEN unbounded preceding AND CURRENT ROW)
     ) AParam,
      decode(grouping('
    || lv_grouping
    || '),1 '
    || lv_decnsourcesec
    || lv_decnsourcef
    || ') decnsour
  FROM  '
    || lv_table
    || '  G, '
    || lv_oracletable
    || '  P where G.mid=P.mid
       '
    || lv_sqltimezone
    || '
     and '
    || lv_subsel
    || '  group by rollup('
    || lv_grouping
    || ')
     ORDER BY 1 ';
  ELSE
   lv_sql :=
       'select '
    || util_pg.hint_ordered
    || 'decode(grouping('
    || lv_grouping
    || '),1,0,'
    || lv_grouping
    || ') BGroup ,
    '
    || lv_paramlist
    || ' AParam ,
      decode(grouping('
    || lv_grouping
    || '),1 '
    || lv_decnsourcesec
    || lv_decnsourcef
    || ') decnsour  from  '
    || lv_table
    || '  G, '
    || lv_oracletable
    || '  P where G.mid=P.mid
   '
    || lv_sqltimezone
    || '
   and '
    || lv_subsel
    || '  group by rollup('
    || lv_grouping
    || ')
     ORDER BY 1 ';
  END IF;

--delete from tmp_vil;
--insert into tmp_vil values(an_idgroup||' av_rowcount='||av_rowcount||' ln_countfull='||ln_countfull||' '||lv_sql);commit;
  OPEN acur_t FOR lv_sql;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior2_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_codetemplate NUMBER,                                                                --код монитора fd->CodeTemplate
                                                                 av_rowcount VARCHAR2,                                                               -- RowCount
                                                                                      an_bird NUMBER,       --//переменная состояния. задается на форме fd->bird
 an_powerprofile NUMBER,                                                                                       --// Количество строк при выводе графика нагрузки
                        an_stepprof NUMBER,                                                                               --//Минимальный шаг профиля в секундах
                                           av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef          VARCHAR2(400);                                                            -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted         VARCHAR2(150);
  lv_subsel           VARCHAR2(1000);
  lv_subselect        VARCHAR2(1000);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(600);
  lv_partly_ed        VARCHAR2(600);
  lv_decnsourcesec    VARCHAR2(1000);
  lv_decnsourcef      VARCHAR2(1000);
  lv_decperiod        VARCHAR2(600);
  lv_paramlist        VARCHAR2(4000);
  lv_grouping         VARCHAR2(600);
  lv_oracletable      VARCHAR2(150);
  ln_timezona         NUMBER;
  ln_countrow         NUMBER;
  ln_countfull        NUMBER;
  lv_sqltimezone      VARCHAR2(2000);
  lv_sql              VARCHAR2(10000);
-----------------------------------
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;

  IF (gn_dsummer = 0) THEN
   lv_sqltimezone :=
       ' and  date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
                    and   date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE(interior_pg.get_hourtimezone,0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
         AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  END IF;

----------------------------------------------------------------------------------------------------
  IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                   --год
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                 --месяц
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), lv_grouping, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSE                                                                                                                                    -- получасовки и сутки
   ln_countfull :=
    interior_pg.get_rowcount(an_idgroup, an_ispoints, av_rowcount, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period,
     TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'));
   ln_countrow :=
    interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
     an_periodforyearfinish, an_period);
  END IF;

-----------------------------------------------------------------------------------------------------------
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  takeofpartquerifornsorse_p(an_codetemplate, an_ispoints,                                                                                    --группа или точка
   an_stepprofile,                                                                                                                                -- детализация
   av_rowcount,                                                                                                                                                --
   av_firstdate, av_lastdate, an_idgroup, interior_pg.get_hourtimezone, ln_countfull, ln_countrow, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p(an_ispoints,                                                                                                                    --группа или точка
   lv_decperiod);
  interior2_choiceoftable_p(an_bird, an_stepprofile, lv_oracletable);
  grouping_p(an_stepprofile, av_firstdate, an_stepprof, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder(an_idgroup) = 1 THEN
    lv_subsel :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_idgroup || ') ';
   ELSE
    lv_subsel := ' G.mid=' || an_idgroup;
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
    lv_subsel :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_idgroup
     || lv_subselect
     || ') ';
   ELSE
    lv_subsel :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect
     || ') ';
   END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  IF (
      an_codetemplate = gn_aebo_rebo_pow_f OR an_codetemplate = gn_aero_aedo_pow_f OR an_codetemplate = gn_rero_redo_pow_f OR an_codetemplate = gn_rq2_rq3_pow_f
      OR an_codetemplate = gn_rq1_rq4_pow_f
     ) THEN
   IF (an_stepprofile = gn_stphour) THEN
    lv_powkoef := '* ' || TO_CHAR(60.0 / an_powerprofile);
   ELSIF(an_stepprofile = gn_stpminute) THEN
    lv_powkoef := '* ' || TO_CHAR(3600.0 / an_stepprof);
   END IF;
  END IF;

  IF (an_codetemplate = gn_aebo_rebo_f OR an_codetemplate = gn_aebo_rebo_pow_f /*OR an_codetemplate = gn_aebo_rebo_sum_f*/) THEN
   lv_paramlist :=
       ' ,sum((-util_pg.sld( P.mid,P.er '
    || lv_powkoef
