 ---------------------------------------------------------------------------------------------------------------
-- В мониторе выводяться даты формирования данных
 PROCEDURE interiorfulldat_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_codetemplate NUMBER,                                                                --код монитора fd->CodeTemplate
                                                                 av_rowcount VARCHAR2,                                                               -- RowCount
                                                                                      an_bird NUMBER,       --//переменная состояния. задается на форме fd->bird
 an_powerprofile NUMBER,                                                                                       --// Количество строк при выводе графика нагрузки
                        an_stepprof NUMBER,                                                                               --//Минимальный шаг профиля в секундах
                                           av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef          VARCHAR2(400);                                                            -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted         VARCHAR2(150);
  lv_subsel           VARCHAR2(1000);
  lv_subselect        VARCHAR2(1000);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(600);
  lv_partly_ed        VARCHAR2(600);
  lv_decnsourcesec    VARCHAR2(1000);
  lv_decnsourcef      VARCHAR2(1000);
  lv_decperiod        VARCHAR2(600);
  lv_paramlist        VARCHAR2(4000);
  lv_grouping         VARCHAR2(600);
  lv_oracletable      VARCHAR2(150);
  lv_firstdate        DATE;
  lv_lastdate         DATE;
  ln_countrow         NUMBER;
  ln_countfull        NUMBER;
  ln_timezona         VARCHAR2(400);
  lv_sqltimezone      VARCHAR2(2000);
  lv_sql              VARCHAR2(10000);
-----------------------------------
 BEGIN
  /* lv_firstdate := (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone);
   lv_lastdate := (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone);

   IF (gn_timezoneshift > 0) THEN
    lv_sqltimezone := ' AND   util_pg.to_unlocaltime (date_time, nsource) >= :par1
                     AND   util_pg.to_unlocaltime (date_time, nsource) <= :par2 ';
   ELSE
    lv_sqltimezone :=
     ' AND   util_pg.to_unlocaltime (date_time, nsource) >= util_pg.to_unlocaltime (:par1)
                     AND   util_pg.to_unlocaltime (date_time, nsource) <= util_pg.to_unlocaltime (:par2) ';
   END IF;*/
  ln_timezona := interior_pg.get_hourtimezone;

  IF (gn_dsummer = 0) THEN
   lv_sqltimezone :=
       ' and  date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
                    and   date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE(interior_pg.get_hourtimezone,0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
         AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  END IF;

----------------------------------------------------------------------------------------------------
  IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                   --год
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                 --месяц
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), lv_grouping, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSE                                                                                                                                    -- получасовки и сутки
   ln_countfull :=
    interior_pg.get_rowcount(an_idgroup, an_ispoints, av_rowcount, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period,
     TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'));
   ln_countrow :=
    interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
     an_periodforyearfinish, an_period);
  END IF;

-----------------------------------------------------------------------------------------------------------
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  takeofpartquerifornsorse_p(an_codetemplate, an_ispoints,                                                                                    --группа или точка
   an_stepprofile,                                                                                                                                -- детализация
   av_rowcount,                                                                                                                                                --
   av_firstdate, av_lastdate, an_idgroup, interior_pg.get_hourtimezone, ln_countfull, ln_countrow, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p(an_ispoints,                                                                                                                    --группа или точка
   lv_decperiod);
  lv_oracletable := ' halfhour ';

  IF (an_bird = 1) THEN
   lv_oracletable := lv_oracletable || '_l';
  ELSIF(an_bird = 2) THEN
   lv_oracletable := lv_oracletable || '_ol';
  END IF;

  grouping_p(an_stepprofile, av_firstdate, an_stepprof, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder(an_idgroup) = 1 THEN
    lv_subsel :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_idgroup || ') ';
   ELSE
    lv_subsel := ' G.mid=' || an_idgroup;
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
    lv_subsel :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_idgroup
     || lv_subselect
     || ') ';
   ELSE
    lv_subsel :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect
     || ') ';
   END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  lv_paramlist :=
        ' ,to_char(MAX(p.denter+ ' || ln_timezona || ')  ,''yyyyddmm'') AParam,
       to_char(MAX(p.denter+ ' || ln_timezona || '),''yyyyhh24miss'')  BParam ';
  lv_sql :=
      'select '
   || util_pg.hint_ordered
   || 'decode(grouping('
   || lv_grouping
   || '),1,0,'
   || lv_grouping
   || ') BGroup '
   || lv_paramlist
   || '
      , decode(grouping('
   || lv_grouping
   || '),1 '
   || lv_decnsourcesec
   || lv_decnsourcef
   || ') decnsour,
      util_pg.sumn(SUM(p.er),SUM(p.ed)) test,
      DECODE(sign(MAX(p.date_time)-sysdate),-1,DECODE(util_pg.sumn(SUM(p.er),SUM(p.ed)),NULL,2,5),999) testdate
       from
               '
   || lv_table
   || ' G, '
   || lv_oracletable
   || ' P  where G.mid=P.mid '
   || lv_sqltimezone
   || '
                 AND  '
   || lv_subsel
   || '
                GROUP BY rollup('
   || lv_grouping
   || ')
                ORDER BY 1';

  OPEN acur_t FOR lv_sql;
--insert into tmp_vil values(lv_sql);
--commit;
 END;

---------------------------------------------------------------------------------------------------------------------------
--T2xDrawTableChartInterior::clickComposition
 PROCEDURE interior_clickcomp1_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_subselect        VARCHAR2(200);
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql := ' select nvl(parent,0)IdGroup from points where mid = ' || an_idgroup;
  ELSIF(an_ispoints = 0) THEN
   subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
   lv_sql := 'select nvl(gr.parent,0)IdGroup from groups gr where gr.gid = ' || an_idgroup || lv_subselect;
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------------
--T2xDrawTableChartInterior::clickComposition
 PROCEDURE interior_clickcomp2_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_subselect        VARCHAR2(200);
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql :=
       ' select nvl(UTIL_PG.GET_NAME_F(name,MID), UTIL_PG.GET_SHORTNAME_F(short_name,MID))Name,
                    nvl(UTIL_PG.GET_SHORTNAME_F(short_name,MID), UTIL_PG.GET_NAME_F(NAME,MID))ShortName, ''y'' GROUP_TOTAL,48 integral
                    FROM points WHERE mid = '
    || an_idgroup;
  ELSIF(an_ispoints = 0) THEN
   subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
   lv_sql :=
       'select nvl(UTIL_PG.GET_NAME_F(gr.name,gr.MID), UTIL_PG.GET_SHORTNAME_F(gr.short_name,gr.MID))Name,
                    nvl(UTIL_PG.GET_SHORTNAME_F(gr.short_name,gr.MID), UTIL_PG.GET_NAME_F(gr.NAME,gr.MID))ShortName, nvl(gr.GROUP_TOTAL,''n'') GROUP_TOTAL,48 integral
               FROM GROUPS gr WHERE gr.gid = '
    || an_idgroup
    || lv_subselect;
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior4_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_codetemplate NUMBER,                                                                --код монитора fd->CodeTemplate
                                                                 av_rowcount VARCHAR2,                                                               -- RowCount
                                                                                      an_bird NUMBER,       --//переменная состояния. задается на форме fd->bird
 an_powerprofile NUMBER,                                                                                       --// Количество строк при выводе графика нагрузки
                        an_stepprof NUMBER,                                                                               --//Минимальный шаг профиля в секундах
                                           av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef          VARCHAR2(400);                                                            -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted         VARCHAR2(150);
  lv_subsel           VARCHAR2(1000);
  lv_subselect        VARCHAR2(1000);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(600);
  lv_partly_ed        VARCHAR2(600);
  lv_decnsourcesec    VARCHAR2(1000);
  lv_decnsourcef      VARCHAR2(1000);
  lv_decperiod        VARCHAR2(600);
  lv_paramlist        VARCHAR2(6000);
  lv_grouping         VARCHAR2(600);
  lv_oracletable      VARCHAR2(150);
  lv_grouping2        VARCHAR2(600);
  lv_sqltimezone      VARCHAR2(2000);
  lv_sql              VARCHAR2(10000);
  lv_dbalans          VARCHAR2(150);
  lv_ind              VARCHAR2(10);
  lv_ind2             VARCHAR2(100);
  lv_ratezona         VARCHAR2(100);
  ln_timezona         NUMBER;
  ln_countrow         NUMBER;
  ln_countfull        NUMBER;
  lv_subrate          VARCHAR2(400);
  lv_sql1             VARCHAR2(4000);
  lv_sql2             VARCHAR2(4000);
  ln_dsummer          NUMBER;
-----------------------------------
 BEGIN
-- INSERT INTO tmp_vil
 -- VALUES ('12');
  COMMIT;

  IF (
      (
       an_codetemplate = gn_aero_aera_aerb_aerc_f OR an_codetemplate = gn_aedo_aeda_aedb_aedc_f OR an_codetemplate = gn_aebo_aeba_aebb_aebc_f
       OR an_codetemplate = gn_rero_rera_rerb_rerc_f OR an_codetemplate = gn_redo_reda_redb_redc_f OR an_codetemplate = gn_rebo_reba_rebb_rebc_f
       OR an_codetemplate = gn_aera_aerb_aerc_aerd_f OR an_codetemplate = gn_aeda_aedb_aedc_aedd_f OR an_codetemplate = gn_rera_rerb_rerc_rerd_f
       OR an_codetemplate = gn_reda_redb_redc_redd_f
      )
      AND(an_stepprofile = gn_stphour OR an_stepprofile = gn_stpminute)
     ) THEN
   raise_application_error(-20001, 'Монитор не поддерживает данный профиль.' || CHR(10) || SQLERRM(SQLCODE));
  END IF;

  IF (
      (
       an_codetemplate = gn_aero_aera_aerb_aerc_f OR an_codetemplate = gn_aedo_aeda_aedb_aedc_f OR an_codetemplate = gn_aebo_aeba_aebb_aebc_f
       OR an_codetemplate = gn_rero_rera_rerb_rerc_f OR an_codetemplate = gn_redo_reda_redb_redc_f OR an_codetemplate = gn_rebo_reba_rebb_rebc_f
       OR an_codetemplate = gn_aera_aerb_aerc_aerd_f OR an_codetemplate = gn_aeda_aedb_aedc_aedd_f OR an_codetemplate = gn_rera_rerb_rerc_rerd_f
       OR an_codetemplate = gn_reda_redb_redc_redd_f
      )
      AND(gn_ratezona = 0)
     ) THEN
   raise_application_error(-20001, 'Для данного часового пояса не задано расписание тарифных зон' || CHR(10) || SQLERRM(SQLCODE));
  END IF;

  ln_timezona := interior_pg.get_hourtimezone;
  ln_dsummer := interior_pg.get_dsummer;

  IF (ln_dsummer = 0) THEN
   lv_sqltimezone :=
       'and P.date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24))
                  and   P.date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24))
                  AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
   lv_subrate :=
       ' AND TO_CHAR (util_pg.to_unlocaltime (P.date_time- 1 / 1440, nsource) - '
    || ln_timezona
    || ', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
                  AND TO_CHAR (util_pg.to_unlocaltime (P.date_time- 1 / 1440, nsource)- '
    || ln_timezona
    || ', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';
   lv_grouping2 := ' trunc(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ', nsource)) ';
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                       AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
   lv_subrate :=
       ' AND TO_CHAR (P.date_time - 1 / 1440- '
    || ln_timezona
    || ', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
                  AND TO_CHAR (P.date_time - 1 / 1440- '
    || ln_timezona
    || ', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';
   lv_grouping2 := ' trunc(p.date_time-1/86400- ' || ln_timezona || ') ';
  END IF;

----------------------------------------------------------------------------------------------------
  IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                   --год
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                 --месяц
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), lv_grouping, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSE                                                                                                                                    -- получасовки и сутки
   ln_countfull :=
    interior_pg.get_rowcount(an_idgroup, an_ispoints, av_rowcount, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period,
     TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'));
   ln_countrow :=
    interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
     an_periodforyearfinish, an_period);
  END IF;

-----------------------------------------------------------------------------------------------------------
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  takeofpartquerifornsorse_p(an_codetemplate, an_ispoints,                                                                                    --группа или точка
   an_stepprofile,                                                                                                                                -- детализация
   av_rowcount,                                                                                                                                                --
   av_firstdate, av_lastdate, an_idgroup, ln_timezona, ln_countfull, ln_countrow, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p(an_ispoints,                                                                                                                    --группа или точка
   lv_decperiod);

  IF (
      an_codetemplate = gn_aero_aera_aerb_aerc_f OR an_codetemplate = gn_aedo_aeda_aedb_aedc_f OR an_codetemplate = gn_aebo_aeba_aebb_aebc_f
      OR an_codetemplate = gn_rero_rera_rerb_rerc_f OR an_codetemplate = gn_redo_reda_redb_redc_f OR an_codetemplate = gn_rebo_reba_rebb_rebc_f
      OR an_codetemplate = gn_aera_aerb_aerc_aerd_f OR an_codetemplate = gn_aeda_aedb_aedc_aedd_f OR an_codetemplate = gn_rera_rerb_rerc_rerd_f
      OR an_codetemplate = gn_reda_redb_redc_redd_f
     ) THEN
   groupingtariff_p(an_stepprofile, an_stepprof, lv_grouping);
  ELSE
   grouping_p(an_stepprofile, av_firstdate, an_stepprof, lv_grouping);
  END IF;

  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder(an_idgroup) = 1 THEN
    lv_subsel :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_idgroup || ') ';
   ELSE
    lv_subsel := ' G.mid=' || an_idgroup;
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
   lv_ind := ' ';
   lv_ind2 := ' ';
  ELSE
   lv_ind := TO_CHAR(ispointingroup(an_idgroup));
   lv_ind2 := '*DECODE(' || lv_ind || ',0,NULL,1) ';
   lv_inverted := 'G.inverted';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
    lv_subsel :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_idgroup
     || lv_subselect
     || ') ';
   ELSE
    lv_subsel :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect
     || ') ';
   END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  IF (an_codetemplate = gn_balance_pow_f OR an_codetemplate = gn_re_balance_pow_f) THEN
   IF (an_stepprofile = gn_stphour) THEN
    lv_powkoef := '* ' || TO_CHAR(60.0 / an_powerprofile);
   ELSIF(an_stepprofile = gn_stpminute) THEN
    lv_powkoef := '* ' || TO_CHAR(3600.0 / an_stepprof);
   END IF;
  END IF;

  IF (an_codetemplate = gn_aero_aera_aerb_aerc_f) THEN                                                          -- //Активная принятая общая и по тарифам [кВтч]
   lv_paramlist :=
       ',sum(DECODE(p.inverted,''y'',p.ed,p.er))/'
    || gn_powercoeff
    || '  AParam,
    sum(DECODE(p.inverted,''y'',p.aed,p.aer))/'
    || gn_powercoeff
    || '  BParam,
    sum(DECODE(p.inverted,''y'',p.bed,p.ber))/'
    || gn_powercoeff
    || '  CParam,
    sum(DECODE(p.inverted,''y'',p.ced,p.cer))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_aedo_aeda_aedb_aedc_f) THEN                                                        -- //Активная отданная общая и по тарифам [кВтч]
   lv_paramlist :=
       ',sum(DECODE(p.inverted,''y'',p.er,p.ed))/'
    || gn_powercoeff
    || '  AParam,
    sum(DECODE(p.inverted,''y'',p.aer,p.aed))/'
    || gn_powercoeff
    || '  BParam,
    sum(DECODE(p.inverted,''y'',p.ber,p.bed))/'
    || gn_powercoeff
    || '  CParam,
    sum(DECODE(p.inverted,''y'',p.cer,p.ced))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_rero_rera_rerb_rerc_f) THEN                                                     -- //Реактивная принятая общая и по тарифам [кВАрч]
   lv_paramlist :=
       ',(sum(DECODE(p.inverted,''y'',p.q3,p.q1))+sum(DECODE(p.inverted,''y'',p.q4,p.q2)))/'
    || gn_powercoeff
    || '  AParam,
    (sum(DECODE(p.inverted,''y'',p.aq3,p.aq1))+sum(DECODE(p.inverted,''y'',p.aq4,p.aq2)))/'
    || gn_powercoeff
    || '  BParam,
    (sum(DECODE(p.inverted,''y'',p.bq3,p.bq1))+sum(DECODE(p.inverted,''y'',p.bq4,p.bq2)))/'
    || gn_powercoeff
    || '  CParam,
    (sum(DECODE(p.inverted,''y'',p.cq3,p.cq1))+sum(DECODE(p.inverted,''y'',p.cq4,p.cq2)))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_redo_reda_redb_redc_f) THEN                                                     -- //Реактивная отданная общая и по тарифам [кВАрч]
   lv_paramlist :=
       ',(sum(DECODE(p.inverted,''y'',p.q1,p.q3))+sum(DECODE(p.inverted,''y'',p.q2,p.q4)))/'
    || gn_powercoeff
    || '  AParam,
    (sum(DECODE(p.inverted,''y'',p.aq1,p.aq3))+sum(DECODE(p.inverted,''y'',p.aq2,p.aq4)))/'
    || gn_powercoeff
    || '  BParam,
    (sum(DECODE(p.inverted,''y'',p.bq1,p.bq3))+sum(DECODE(p.inverted,''y'',p.bq2,p.bq4)))/'
    || gn_powercoeff
    || '  CParam,
    (sum(DECODE(p.inverted,''y'',p.cq1,p.cq3))+sum(DECODE(p.inverted,''y'',p.cq2,p.cq4)))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_aera_aerb_aerc_aerd_f) THEN                                                                 --//Активная принятая по тарифам [кВтч]
   lv_paramlist :=
       ',sum(DECODE(p.inverted,''y'',p.aed,p.aer))/'
    || gn_powercoeff
    || '  AParam,
    sum(DECODE(p.inverted,''y'',p.bed,p.ber))/'
    || gn_powercoeff
    || '  BParam,
    sum(DECODE(p.inverted,''y'',p.ced,p.cer))/'
    || gn_powercoeff
    || '  CParam,
    sum(DECODE(p.inverted,''y'',p.ded,p.der))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_aeda_aedb_aedc_aedd_f) THEN                                                                -- //Активная отданная по тарифам [кВтч]
   lv_paramlist :=
       ',sum(DECODE(p.inverted,''y'',p.aer,p.aed))/'
    || gn_powercoeff
    || '  AParam,
    sum(DECODE(p.inverted,''y'',p.ber,p.bed))/'
    || gn_powercoeff
    || '  BParam,
    sum(DECODE(p.inverted,''y'',p.cer,p.ced))/'
    || gn_powercoeff
    || '  CParam,
    sum(DECODE(p.inverted,''y'',p.der,p.ded))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_rera_rerb_rerc_rerd_f) THEN                                                             -- //Реактивная принятая по тарифам [кВАрч]
   lv_paramlist :=
       ',(sum(DECODE(p.inverted,''y'',p.aq3,p.aq1))+sum(DECODE(p.inverted,''y'',p.aq4,p.aq2)))/'
    || gn_powercoeff
    || '  AParam,
    (sum(DECODE(p.inverted,''y'',p.bq3,p.bq1))+sum(DECODE(p.inverted,''y'',p.bq4,p.bq2)))/'
    || gn_powercoeff
    || '  BParam,
    (sum(DECODE(p.inverted,''y'',p.cq3,p.cq1))+sum(DECODE(p.inverted,''y'',p.cq4,p.cq2)))/'
    || gn_powercoeff
    || '  CParam,
    (sum(DECODE(p.inverted,''y'',p.dq3,p.dq1))+sum(DECODE(p.inverted,''y'',p.dq4,p.dq2)))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_reda_redb_redc_redd_f) THEN                                                             -- //Реактивная отданная по тарифам [кВАрч]
   lv_paramlist :=
       ',(sum(DECODE(p.inverted,''y'',p.aq1,p.aq3))+sum(DECODE(p.inverted,''y'',p.aq2,p.aq4)))/'
    || gn_powercoeff
    || '  AParam,
    (sum(DECODE(p.inverted,''y'',p.bq1,p.bq3))+sum(DECODE(p.inverted,''y'',p.bq2,p.bq4)))/'
    || gn_powercoeff
    || '  BParam,
    (sum(DECODE(p.inverted,''y'',p.cq1,p.cq3))+sum(DECODE(p.inverted,''y'',p.cq2,p.cq4)))/'
    || gn_powercoeff
    || '  CParam,
    (sum(DECODE(p.inverted,''y'',p.dq1,p.dq3))+sum(DECODE(p.inverted,''y'',p.dq2,p.dq4)))/'
    || gn_powercoeff
    || '  DParam';
   choiceoftable_tariff_p(an_bird, lv_oracletable);
  ELSIF(an_codetemplate = gn_aebo_aeba_aebb_aebc_f) THEN                                               --// 921 Переток активной э/э (общая и по тарифам) [кВтч]
   lv_paramlist :=
       ',sum((-util_pg.sld(P.mid,p.er,p.ed))*DECODE( p.inverted ,''y'',1,-1))/'
    || gn_powercoeff
    || '  AParam,
    sum((-util_pg.sld(P.mid,p.aer,p.aed))*DECODE( p.inverted ,''y'',1,-1))/'
    || gn_powercoeff
    || '  BParam,
    sum((-util_pg.sld(P.mid,p.ber,p.bed))*DECODE( p.inverted ,''y'',1,-1))/'
    || gn_powercoeff
    || '  CParam,
    sum((-util_pg.sld(P.mid,p.cer,p.ced))*DECODE( p.inverted ,''y'',1,-1))/'
    || gn_powercoeff
    || '  DParam ';
