    || ') and nschedulelist='
    || lv_ratezona
    || '))
 '
    || lv_subrate
    || '
 group by p.mid, '
    || lv_grouping2
    || ') p
 group by rollup('
    || lv_grouping
    || ')
 order by 1  ';
  --по тарифам реактив.
  ELSIF(
        an_codetemplate = gn_rero_rera_rerb_rerc_f OR an_codetemplate = gn_redo_reda_redb_redc_f OR an_codetemplate = gn_rebo_reba_rebb_rebc_f
        OR an_codetemplate = gn_rera_rerb_rerc_rerd_f OR an_codetemplate = gn_reda_redb_redc_redd_f
       ) THEN
   lv_ratezona := interior_pg.get_ratezona;
   lv_sql :=
       '  select
   decode(grouping('
    || lv_grouping
    || ') ,1,0,
   '
    || lv_grouping
    || ')  BGroup'
    || lv_paramlist
    || ' ,
   SUMQM(p. decnsour) decnsour

   from
   (select '
    || util_pg.hint_ordered
    || 'p.mid,
   '
    || lv_grouping2
    || ' date_time,
   max('
    || lv_inverted
    || ') inverted,

   sum(p.q1'
    || lv_partly_er
    || lv_decperiod
    || ' ) q1,
   sum(p.q2'
    || lv_partly_ed
    || lv_decperiod
    || ' ) q2 ,
   sum(p.q3'
    || lv_partly_er
    || lv_decperiod
    || ' ) q3,
   sum(p.q4'
    || lv_partly_ed
    || lv_decperiod
    || ' ) q4 ,
  sum(DECODE(r.rate,0,p.q1'
    || lv_partly_er
    || ') '
    || lv_decperiod
    || ' ) aq1,
  sum(DECODE(r.rate,0,p.q2'
    || lv_partly_ed
    || ') '
    || lv_decperiod
    || ' ) aq2,
  sum(DECODE(r.rate,0,p.q3'
    || lv_partly_er
    || ') '
    || lv_decperiod
    || ' ) aq3,
  sum(DECODE(r.rate,0,p.q4'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) aq4,
  sum(DECODE(r.rate,1,p.q1'
    || lv_partly_er
    || ')'
    || lv_decperiod
    || ') bq1,
  sum(DECODE(r.rate,1,p.q2'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ') bq2,
  sum(DECODE(r.rate,1,p.q3'
    || lv_partly_er
    || ')'
    || lv_decperiod
    || ') bq3,
  sum(DECODE(r.rate,1,p.q4'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) bq4,
  sum(DECODE(r.rate,2,p.q1'
    || lv_partly_er
    || ')'
    || lv_decperiod
    || ' ) cq1,
  sum(DECODE(r.rate,2,p.q2'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) cq2,
  sum(DECODE(r.rate,2,p.q3'
    || lv_partly_er
    || ')'
    || lv_decperiod
    || ') cq3,
  sum(DECODE(r.rate,2,p.q4'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ') cq4,
  sum(DECODE(r.rate,3,p.q1'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) dq1,
  sum(DECODE(r.rate,3,p.q2'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) dq2,
  sum(DECODE(r.rate,3,p.q1'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) dq3,
  sum(DECODE(r.rate,3,p.q2'
    || lv_partly_ed
    || ')'
    || lv_decperiod
    || ' ) dq4,
  decode(sign(util_pg.get_countpoint_f('
    || an_idgroup
    || ', 0 )
   *to_char(trunc(add_months((to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '),
    0+to_char( '
    || lv_grouping2
    || ',''mm'') ))
   -1/86400,''dd'' ) -count(*)),1,qm_pg.sumqm(nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm),qm_pg.nodataqm),
   nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm))  decnsour
 from '
    || lv_table
    || ' G, '
    || lv_oracletable
    || ' P, rates r where G.mid=P.mid
 and '
    || lv_subsel
    || lv_sqltimezone
    || ' and r.rid=(select rid from rate_list where nschedulelist='
    || lv_ratezona
    || ' and SWITCH_DATE=(select max(SWITCH_DATE) from rate_list where SWITCH_DATE<=trunc(p.date_time- '
    || ln_timezona
    || ') and nschedulelist='
    || lv_ratezona
    || '))
'
    || lv_subrate
    || '
group by p.mid, '
    || lv_grouping2
    || ') p 
group by rollup('
    || lv_grouping
    || ')
order by 1  ';
  ELSE
   --обычные балансы
   lv_sql :=
       'select '
    || util_pg.hint_ordered
    || 'decode(grouping('
    || lv_grouping
    || '),1,0,'
    || lv_grouping
    || ') BGroup'
    || lv_paramlist
    || ', decode(grouping('
    || lv_grouping
    || '),1 '
    || lv_decnsourcesec
    || lv_decnsourcef
    || ') decnsour  from  '
    || lv_table
    || ' G, '
    || lv_oracletable
    || ' P WHERE G.mid=P.mid
                '
    || lv_sqltimezone
    || '
               AND '
    || lv_subsel
    || ' GROUP BY rollup('
    || lv_grouping
    || ')
                ORDER BY 1';
  END IF;

-- INSERT INTO tmp_vil  VALUES (lv_sql);
--COMMIT;
  OPEN acur_t FOR lv_sql;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior4_notbalanse_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_codetemplate NUMBER,                                                                --код монитора fd->CodeTemplate
                                                                 av_rowcount VARCHAR2,                                                               -- RowCount
                                                                                      an_bird NUMBER,       --//переменная состояния. задается на форме fd->bird
 an_powerprofile NUMBER,                                                                                       --// Количество строк при выводе графика нагрузки
                        an_stepprof NUMBER,                                                                               --//Минимальный шаг профиля в секундах
                                           av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef          VARCHAR2(400);                                                            -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted         VARCHAR2(150);
  lv_subsel           VARCHAR2(1000);
  lv_subselect        VARCHAR2(1000);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(600);
  lv_partly_ed        VARCHAR2(600);
  lv_decnsourcesec    VARCHAR2(1000);
  lv_decnsourcef      VARCHAR2(1000);
  lv_decperiod        VARCHAR2(600);
  lv_paramlist        VARCHAR2(4000);
  lv_grouping         VARCHAR2(600);
  lv_oracletable      VARCHAR2(150);
  lv_firstdate        DATE;
  lv_lastdate         DATE;
  ln_timezona         NUMBER;
  ln_countrow         NUMBER;
  ln_countfull        NUMBER;
  lv_sql              VARCHAR2(10000);
  lv_cparam           VARCHAR2(4000);
  lv_ind              VARCHAR2(10);
  lv_ind2             VARCHAR2(100);
  lv_sqltimezone      VARCHAR2(2000);
  lv_dparam           VARCHAR2(2000);
  lv_cparamsub        VARCHAR2(2000);
-----------------------------------
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;

  IF (gn_dsummer = 0) THEN
   lv_sqltimezone :=
       'and P.date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24))
                  and   P.date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24))
                  AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                       AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  END IF;

----------------------------------------------------------------------------------------------------
  IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                   --год
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                 --месяц
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), lv_grouping, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSE                                                                                                                                    -- получасовки и сутки
   ln_countfull :=
    interior_pg.get_rowcount(an_idgroup, an_ispoints, av_rowcount, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period,
     TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'));
   ln_countrow :=
    interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
     an_periodforyearfinish, an_period);
  END IF;

-----------------------------------------------------------------------------------------------------------
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  takeofpartquerifornsorse_p(an_codetemplate, an_ispoints,                                                                                    --группа или точка
   an_stepprofile,                                                                                                                                -- детализация
   av_rowcount,                                                                                                                                                --
   av_firstdate, av_lastdate, an_idgroup, interior_pg.get_hourtimezone, ln_countfull, ln_countrow, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p(an_ispoints,                                                                                                                    --группа или точка
   lv_decperiod);
  grouping_p(an_stepprofile, av_firstdate, an_stepprof, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder(an_idgroup) = 1 THEN
    lv_subsel :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_idgroup || ') ';
   ELSE
    lv_subsel := ' G.mid=' || an_idgroup;
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
   lv_ind := ' ';
   lv_ind2 := ' ';
  ELSE
   lv_ind := TO_CHAR(ispointingroup(an_idgroup));
   lv_ind2 := '*DECODE(' || lv_ind || ',0,NULL,1) ';
   lv_inverted := 'G.inverted';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
    lv_subsel :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_idgroup
     || lv_subselect
     || ') ';
   ELSE
    lv_subsel :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect
     || ') ';
   END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  interior2_choiceoftable_p(an_bird, an_stepprofile, lv_oracletable);

  IF (an_stepprofile = gn_stpmonth) THEN
   lv_cparam :=
       ' decode(tt.BGroup,0,(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' , TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' ,
 TO_DATE ('''
    || av_lastdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '   ,1 ,'''
    || lv_oracletable
    || ''') '
    || lv_ind2
    || ' ),
(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' ,add_months ( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' ,BGroup-1 ),
add_months ( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '  ,BGroup ),1,'''
    || lv_oracletable
    || ''' ) '
    || lv_ind2
    || ' ))';
  ELSIF(an_stepprofile = gn_stpday) THEN
   lv_cparam :=
       'decode(tt.BGroup,0,(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' , TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' ,
 TO_DATE ('''
    || av_lastdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '   ,1 ,'''
    || lv_oracletable
    || ''') '
    || lv_ind2
    || ' ),
(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' ,( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' +BGroup-1 ),
 ( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '+BGroup ),1,'''
    || lv_oracletable
    || ''' ) '
    || lv_ind2
    || '))';
  ELSIF(an_stepprofile = gn_stphour) THEN
   lv_cparam :=
       'decode(tt.BGroup,0,(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' , TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' ,
 TO_DATE ('''
    || av_lastdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '   ,1 ,'''
    || lv_oracletable
    || ''') '
    || lv_ind2
    || ' ),
(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' ,( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' +((BGroup-1)/'
    || an_stepprof
    || ') ),
 ( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '+(BGroup/'
    || an_stepprof
    || ') ),1,'''
    || lv_oracletable
    || ''' ) '
    || lv_ind2
    || '))';
  ELSIF(an_stepprofile = gn_stpminute) THEN
   lv_cparam :=
       'decode(tt.BGroup,0,(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' , TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' ,
 TO_DATE ('''
    || av_lastdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '   ,1 ,'''
    || lv_oracletable
    || ''') '
    || lv_ind2
    || ' ),
(util_pg.get_ad_balance ( '
    || an_idgroup
    || ' ,( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' +((BGroup-1)*86400/'
    || an_stepprof
    || ') ),
 ( TO_DATE ('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '+(BGroup*86400/'
    || an_stepprof
    || ') ),1,'''
    || lv_oracletable
    || ''' ) '
    || lv_ind2
    || '))';
  END IF;

  lv_paramlist :=
      ' ,sum( -util_pg.sld( P.mid, P.er'
   || lv_powkoef
   || lv_partly_er
   || ', (P.ed'
   || lv_powkoef
   || lv_partly_ed
   || ' ) )*DECODE('
   || lv_inverted
   || ',''y'',1,-1)'
   || lv_decperiod
   || ' )/'
   || gn_powercoeff
   || ' AParam '
   ||                                                                                                           --//Фактический небаланс Активной энергии [кВтч]
      ' ,DECODE(sum(DECODE('
   || lv_inverted
   || ',''y'',P.ed'
   || lv_powkoef
   || lv_partly_ed
   || ',P.er'
   || lv_powkoef
   || lv_partly_er
   || ')'
   || lv_decperiod
   || lv_ind2
   || '),0,0,
    sum( -util_pg.sld( P.mid, P.er'
   || lv_powkoef
   || lv_partly_er
   || ', (P.ed'
   || lv_powkoef
   || lv_partly_ed
   || ' ) )*DECODE('
   || lv_inverted
   || ',''y'',1,-1)'
   || lv_decperiod
   || lv_ind2
   || ')/
    sum(DECODE('
   || lv_inverted
   || ',''y'',P.ed'
   || lv_powkoef
   || lv_partly_ed
   || ',P.er'
   || lv_powkoef
   || lv_partly_er
   || ')'
   || lv_decperiod
   || ')*100) BParam    ';                                                                                            --// небаланс активной фактический процент

  IF (an_codetemplate = gn_not_balance_aer_f) THEN
   lv_paramlist :=
       lv_paramlist
    || ', decode(grouping('
    || lv_grouping
    || '),1,
    last_value ( sum( -util_pg.sld( P.mid, P.er'
    || lv_powkoef
    || lv_partly_er
    || ', (P.ed'
    || lv_powkoef
    || lv_partly_ed
    || ' ) )*DECODE('
    || lv_inverted
    || ',''y'',1,-1)'
    || lv_decperiod
    || lv_ind2
    || ')) over (ORDER BY  '
    || lv_grouping
    || '  ROWS BETWEEN unbounded preceding AND CURRENT ROW),
    sum( sum( -util_pg.sld( P.mid, P.er'
    || lv_powkoef
    || lv_partly_er
    || ', (P.ed'
    || lv_powkoef
    || lv_partly_ed
    || ' ) )*DECODE('
    || lv_inverted
    || ',''y'',1,-1)'
    || lv_decperiod
    || lv_ind2
    || ')) over (ORDER BY  '
    || lv_grouping
    || '   ROWS BETWEEN unbounded preceding AND CURRENT ROW)) bbbparam ,
    
     decode(grouping('
    || lv_grouping
    || '),1,
    last_value (sum(DECODE('
    || lv_inverted
    || ',''y'',P.ed'
    || lv_powkoef
    || lv_partly_ed
    || ',P.er'
    || lv_powkoef
    || lv_partly_er
    || ')'
    || lv_decperiod
    || ')) over (ORDER BY '
    || lv_grouping
    || '  ROWS BETWEEN unbounded preceding AND CURRENT ROW),             
      sum(sum(DECODE('
    || lv_inverted
    || ',''y'',P.ed'
    || lv_powkoef
    || lv_partly_ed
    || ',P.er'
    || lv_powkoef
    || lv_partly_er
    || ')'
    || lv_decperiod
    || ')) over (ORDER BY  '
    || lv_grouping
    || '   ROWS BETWEEN unbounded preceding AND CURRENT ROW)) mmmparam ';
  END IF;

  IF (an_codetemplate = gn_not_balance_f) THEN
   lv_dparam := ' 0';
  ELSE
   lv_dparam := ' decode(tt.mmmparam,0,0,(tt.bbbparam/tt.mmmparam)*100) ';
  END IF;

  lv_sql :=
      ' select tt.bgroup,tt.aparam,tt.bparam,
 '
   || lv_cparam
   || ' CParam,
 '
   || lv_dparam
   || ' dparam,tt.decnsour FROM
(SELECT '
   || util_pg.hint_ordered
   || 'decode(grouping( '
   || lv_grouping
   || ' ) ,1,0 ,
'
   || lv_grouping
   || ' ) BGroup '
   || lv_paramlist
   || ', decode(grouping('
   || lv_grouping
   || '),1 '
   || lv_decnsourcesec
   || lv_decnsourcef
   || ') decnsour
    FROM   '
   || lv_table
   || '  G,  '
   || lv_oracletable
   || '  P
               WHERE G.mid=P.mid
                '
   || lv_sqltimezone
   || '
               AND  '
   || lv_subsel
   || '
     GROUP BY rollup( '
   || lv_grouping
   || ' ))tt
     ORDER BY 1 ';

--insert into tmp_vil values(lv_sql);
--commit;
  OPEN acur_t FOR lv_sql;
 END;

