 PROCEDURE interiordu2chart_formdescr_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_idgroup NUMBER, av_datest VARCHAR2, av_dateen VARCHAR2, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect        VARCHAR2(200);
  lv_datest           DATE;
  lv_dateen           DATE;
  lv_sql              VARCHAR2(4000);
  ln_timezona         NUMBER;
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;

  IF (an_ispoints = 1) THEN
   lv_sql :=
       'select TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime,date_time from
           (
           SELECT date_time FROM curr_power WHERE mid ='
    || an_idgroup
    || '
           UNION
           SELECT date_time FROM curr_power_arch WHERE mid = '
    || an_idgroup
    || '
            AND date_time >= to_date('''
    || av_datest
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
            AND date_time <= to_date('''
    || av_dateen
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
              )
             ORDER BY 2 DESC';
  ELSE
   subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
   lv_sql :=
       'select TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime,date_time
                  FROM
                    (
                      SELECT date_time FROM curr_power WHERE mid = (SELECT gr.MID FROM GROUPS gr WHERE gr.GID='
    || an_idgroup
    || '
                      '
    || lv_subselect
    || ' )
                      UNION
                      SELECT date_time FROM curr_power_arch WHERE mid = (SELECT gr.MID FROM GROUPS gr WHERE gr.GID='
    || an_idgroup
    || '
                      '
    || lv_subselect
    || ' )
           AND date_time >= to_date('''
    || av_datest
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
            AND date_time <= to_date('''
    || av_dateen
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    )
                  ORDER BY 2 DESC';
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

