 PROCEDURE interiordu2chart_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_idgroup NUMBER, av_date VARCHAR2, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_subselect        VARCHAR2(1000);
  lv_sql              VARCHAR2(10000);
  ld_start            DATE;
  ld_end              DATE;
  ld_date             DATE DEFAULT TO_DATE(av_date, 'dd.mm.yyyy hh24:mi:ss');
-----------------------------------
 BEGIN
  IF an_stepprofile = gn_stpmonth THEN
   ld_start := TRUNC(ld_date, 'yyyy');
   ld_end := TRUNC(ADD_MONTHS(ld_date, 12), 'yyyy');
  ELSIF an_stepprofile = gn_stpday THEN
   ld_start := TRUNC(ld_date, 'mm');
   ld_end := TRUNC(ADD_MONTHS(ld_date, 1), 'mm');
  ELSIF an_stepprofile = gn_stphour THEN
   ld_start := TRUNC(ld_date, 'dd');
   ld_end := TRUNC(ld_date, 'dd') + 1;
  ELSE
   raise_application_error(-20001, 'Шаг монитора задан неверно!');
  END IF;

  IF (an_ispoints = 1) THEN
   lv_sql :=
       ' select * from
                   (
                      SELECT TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime, date_time,
                          mid, (er-ed)/'
    || gn_powercoeff
    || ' na, (q1-q3)/'
    || gn_powercoeff
    || ' nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power WHERE mid = '
    || an_idgroup
    || ' 
                      UNION 
                      SELECT TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime, date_time,
                          mid, (er-ed)/'
    || gn_powercoeff
    || ' na, (q1-q3)/'
    || gn_powercoeff
    || ' nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power_arch WHERE mid = '
    || an_idgroup
    || ' 
                        AND date_time + INTERIOR_PG.get_hourtimezone > :par2
                        AND date_time + INTERIOR_PG.get_hourtimezone <= :par3                        
                    ) ORDER BY date_time DESC';
  --AND date_time+ INTERIOR_PG.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
  ELSE
   --subselect_p (an_stepprofile, lv_subselect);
   subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
   lv_sql :=
       'select * from
                    (
                      SELECT   TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime, date_time,
                          mid, (er-ed)/'
    || gn_powercoeff
    || ' na, (q1-q3)/'
    || gn_powercoeff
    || ' nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power 
                       WHERE mid = (SELECT gr.MID FROM GROUPS gr WHERE gr.GID='
    || an_idgroup
    || lv_subselect
    || ' )
                           --AND date_time+ INTERIOR_PG.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
                      UNION 
                      SELECT   TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime, date_time,
                          mid, (er-ed)/'
    || gn_powercoeff
    || ' na, (q1-q3)/'
    || gn_powercoeff
    || ' nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power_arch 
                       WHERE mid = (SELECT gr.MID FROM GROUPS gr WHERE gr.GID='
    || an_idgroup
    || lv_subselect
    || ' )
                            --AND date_time+ interior_pg.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
                        AND date_time + INTERIOR_PG.get_hourtimezone > :par2
                        AND date_time + INTERIOR_PG.get_hourtimezone <= :par3
                    ) ORDER BY date_time DESC';
  END IF;

  OPEN acur_t FOR lv_sql USING ld_start, ld_end;
 END;

