 PROCEDURE editformlist_getshemas_p(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   monitor, NVL(NAME, '') NAME
   FROM     monitor_schemes
   ORDER BY 1;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_readgroupnode_p(an_nodeparent NUMBER,                                                                                 --наличие родителя
                                                             an_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_nodeparent = 0) THEN
   OPEN acur_t FOR
    SELECT   1 havechild, gid, NAME
    FROM     GROUPS g
    WHERE    PARENT IS NULL AND mid IS NULL AND EXISTS(SELECT *
                                                       FROM   GROUPS
                                                       WHERE  PARENT = g.gid AND mid IS NULL)
    UNION ALL
    SELECT   0 havechild, gid, NAME
    FROM     GROUPS g
    WHERE    PARENT IS NULL AND mid IS NULL AND NOT EXISTS(SELECT *
                                                           FROM   GROUPS
                                                           WHERE  PARENT = g.gid AND mid IS NULL)
    ORDER BY 3;
  ELSE
   OPEN acur_t FOR
    SELECT   1 havechild, gid, NAME
    FROM     GROUPS g
    WHERE    PARENT = an_id AND mid IS NULL AND EXISTS(SELECT *
                                                       FROM   GROUPS
                                                       WHERE  PARENT = g.gid AND mid IS NULL)
    UNION ALL
    SELECT   0 havechild, gid, NAME
    FROM     GROUPS g
    WHERE    PARENT = an_id AND mid IS NULL AND NOT EXISTS(SELECT *
                                                           FROM   GROUPS
                                                           WHERE  PARENT = g.gid AND mid IS NULL)
    ORDER BY 3;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_readnode1_p(
 an_nodeparent NUMBER,                                                                                                                        --наличие родителя
                      an_tv NUMBER,                                                                                                               --какое дерево
                                   an_id NUMBER, an_currentschema NUMBER, acur_t OUT common_pg.tcur
 ) IS
 BEGIN
  IF (an_tv = 1) THEN
   IF (an_nodeparent = 0) THEN
    OPEN acur_t FOR
     SELECT   1 havechild, t.fid, NVL(t.codetemplate, 0) codetemplate, t.nameform, t.commentform, t.enablecontrols, NVL(t.stepprofile, 0) stepprofile,
              t.namealert, DECODE(NVL(t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL(t.mid, 0) mid,
              util_pg.get_pointname(t.mid, 0, 0) midname
     FROM     forms t, form_templates ft
     WHERE    t.PARENT IS NULL AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND EXISTS(SELECT *
                         FROM   forms
                         WHERE  PARENT = t.fid AND monitor = an_currentschema)
     UNION ALL
     SELECT   0 havechild, t.fid, NVL(t.codetemplate, 0), t.nameform, t.commentform, t.enablecontrols, NVL(t.stepprofile, 0), t.namealert,
              DECODE(NVL(t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL(t.mid, 0),
              util_pg.get_pointname(t.mid, 0, 0) midname
     FROM     forms t, form_templates ft
     WHERE    t.PARENT IS NULL AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND NOT EXISTS(SELECT *
                             FROM   forms
                             WHERE  PARENT = t.fid AND monitor = an_currentschema)
     ORDER BY 9, 4;
   ELSE
    OPEN acur_t FOR
     SELECT   1 havechild, t.fid, NVL(t.codetemplate, 0) codetemplate, t.nameform, t.commentform, t.enablecontrols, NVL(t.stepprofile, 0) stepprofile,
              t.namealert, DECODE(NVL(t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL(t.mid, 0) mid,
              util_pg.get_pointname(t.mid, 0, 0) midname
     FROM     forms t, form_templates ft
     WHERE    t.PARENT = an_id AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND EXISTS(SELECT *
                         FROM   forms
                         WHERE  PARENT = t.fid AND monitor = an_currentschema)
     UNION ALL
     SELECT   0 havechild, t.fid, NVL(t.codetemplate, 0), t.nameform, t.commentform, t.enablecontrols, NVL(t.stepprofile, 0), t.namealert,
              DECODE(NVL(t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL(t.mid, 0),
              util_pg.get_pointname(t.mid, 0, 0) midname
     FROM     forms t, form_templates ft
     WHERE    t.PARENT = an_id AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND NOT EXISTS(SELECT *
                             FROM   forms
                             WHERE  PARENT = t.fid AND monitor = an_currentschema)
     ORDER BY 9, 4;
   END IF;
  ELSE
   IF (an_nodeparent = 0) THEN
    OPEN acur_t FOR
     SELECT   1 havechild, template_id fid, NVL(codetemplate, 0) codetemplate, nameform, commentform, enablecontrols, NVL(stepprofile, 0) stepprofile,
              namealert, DECODE(NVL(codetemplate, 0), 0, 0, 1) priz, '' vprocname, '' nameform, enablecontrols, 0 mid, '' midname
     FROM     form_templates t
     WHERE    PARENT IS NULL AND EXISTS(SELECT *
                                        FROM   form_templates
                                        WHERE  PARENT = t.template_id)
     UNION ALL
     SELECT   0 havechild, template_id, NVL(codetemplate, 0), nameform, commentform, enablecontrols, NVL(stepprofile, 0), namealert,
              DECODE(NVL(codetemplate, 0), 0, 0, 1) priz, '', '', enablecontrols, 0, ''
     FROM     form_templates t
     WHERE    PARENT IS NULL AND NOT EXISTS(SELECT *
                                            FROM   form_templates
                                            WHERE  PARENT = t.template_id)
     ORDER BY 9, 4;
   ELSE
    OPEN acur_t FOR
     SELECT   1 havechild, template_id fid, NVL(codetemplate, 0) codetemplate, nameform, commentform, enablecontrols, NVL(stepprofile, 0) stepprofile,
              namealert, DECODE(NVL(codetemplate, 0), 0, 0, 1) priz, '' vprocname, nameform, enablecontrols, 0 mid, '' midname
     FROM     form_templates t
     WHERE    PARENT = an_id AND EXISTS(SELECT *
                                        FROM   form_templates
                                        WHERE  PARENT = t.template_id)
     UNION ALL
     SELECT   0 havechild, template_id, NVL(codetemplate, 0), nameform, commentform, enablecontrols, NVL(stepprofile, 0), namealert,
              DECODE(NVL(codetemplate, 0), 0, 0, 1) priz, '', nameform, enablecontrols, 0, ''
     FROM     form_templates t
     WHERE    PARENT = an_id AND NOT EXISTS(SELECT *
                                            FROM   form_templates
                                            WHERE  PARENT = t.template_id)
     ORDER BY 9, 4;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_readnode2_p(an_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   g.gid, f.fid
   FROM     form_group g, forms f
   WHERE    g.fid = f.fid AND f.PARENT = an_id
   ORDER BY DECODE(NVL(f.codetemplate, 0), 0, 0, 1), f.nameform;
 END;

--------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_vclone_p(an_id1 NUMBER, an_id2 NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT e.fid fd1, fd.fid fd2
   FROM   forms_ex e, forms f, forms fd
   WHERE  e.fid = f.fid AND f.monitor = an_id1 AND fd.monitor = an_id2
          AND(fd.codetemplate = f.codetemplate OR(fd.codetemplate IS NULL AND f.codetemplate IS NULL))
          AND(fd.nameform = f.nameform OR(fd.nameform IS NULL AND f.nameform IS NULL))
          AND(fd.commentform = f.commentform OR(fd.commentform IS NULL AND f.commentform IS NULL))
          AND(fd.enablecontrols = f.enablecontrols OR(fd.enablecontrols IS NULL AND f.enablecontrols IS NULL))
          AND(fd.stepprofile = f.stepprofile OR(fd.stepprofile IS NULL AND f.stepprofile IS NULL))
          AND(fd.namealert = f.namealert OR(fd.namealert IS NULL AND f.namealert IS NULL))
          AND(fd.vprocname = f.vprocname OR(fd.vprocname IS NULL AND f.vprocname IS NULL)) AND(fd.mid = f.mid OR(fd.mid IS NULL AND f.mid IS NULL));
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE chartinterior_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_codetemplate NUMBER,                                                                --код монитора fd->CodeTemplate
                                                                 an_stepprof NUMBER,                                      --//Минимальный шаг профиля в секундах
                                                                                    av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER,
 an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_inverted         VARCHAR2(150);
  lv_subsel           VARCHAR2(1000);
  lv_subselect        VARCHAR2(400);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(400);
  lv_partly_ed        VARCHAR2(400);
  lv_decperiod        VARCHAR2(400);
  lv_paramlist        VARCHAR2(600);
  lv_grouping         VARCHAR2(200);
  ln_timezona         NUMBER;
  lv_sqltimezone      VARCHAR2(2000);
  lv_sql              VARCHAR2(8000);
-----------------------------------
 BEGIN
  decperiod_p(an_ispoints,                                                                                                                   --группа или точка
   lv_decperiod);
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  ln_timezona := interior_pg.get_hourtimezone;

  IF (gn_dsummer = 0) THEN
   lv_sqltimezone :=
       ' and  date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24))
                    and   date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
      AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  END IF;

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder(an_idgroup) = 1 THEN
    lv_subsel :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_idgroup || ') ';
   ELSE
    lv_subsel := ' G.mid=' || an_idgroup;
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
    lv_subsel :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_idgroup
     || lv_subselect
     || ') ';
   ELSE
    lv_subsel :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect
     || ') ';
   END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  lv_grouping := ' floor((date_time-to_date(''' || av_firstdate || ''',''dd.mm.yyyy hh24:mi:ss''))*86400/' || an_stepprof || ') ';

  IF (an_codetemplate = gn_apro_c) THEN
   lv_paramlist :=
       ',sum((-util_pg.sld(P.mid,nvl(P.er'
    || lv_partly_er
    || ',0),
                     nvl(P.ed'
    || lv_partly_ed
    || ',0)))*DECODE('
    || lv_inverted
    || ',''y'',1,-1)'
    || lv_decperiod
    || ')*3600/'
    || an_stepprof
    || '/'
    || gn_powercoeff
    || ' ';
  ELSIF(an_codetemplate = gn_rpro_c) THEN
   lv_paramlist :=
       ',sum((-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)))*DECODE('
    || lv_inverted
    || ',''y'',1,-1)'
    || lv_decperiod
    || ')*3600/'
    || an_stepprof
    || '/'
    || gn_powercoeff
    || ' ';
  END IF;

  lv_sql :=
      'select '
   || util_pg.hint_ordered
   || lv_grouping
   || 'BCount'
   || lv_paramlist
   || 'AParam from  '
   || lv_table
   || 'G ,profile  P 
  WHERE P.mid=G.mid '
   || lv_sqltimezone
   || '
     AND '
   || lv_subsel
   || '
     GROUP BY '
   || lv_grouping
   || 'ORDER BY 1';

  OPEN acur_t FOR lv_sql;
 END;

