  lv_sql :=' select (SELECT MAX(gid) from groups where mid=gr.mid) mid,f.vname||''  ''||nvl(util_pg.get_shortname_f(gr.short_name,gr.mid),util_pg.get_name_f(gr.name,gr.mid))name ,48 integral
             from pointformula b,formulparams f,points gr
