   subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
   lv_sql :=
       'select gr.gid mid, nvl(util_pg.get_shortname_f(gr.short_name,gr.mid),util_pg.get_name_f(gr.name,gr.mid))name ,48 integral
         FROM GROUPS gr WHERE gr.parent = '
