 PROCEDURE limitpowerint_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                         -- детализация fd->StepProfile только gn_stpHour,gn_stpMinute
                                          an_codetemplate NUMBER,                                                                --код монитора fd->CodeTemplate
                                                                 av_rowcount VARCHAR2,                                                               -- RowCount
                                                                                      an_powerprofile NUMBER,  --// Количество строк при выводе графика нагрузки
 an_stepprof NUMBER,                                                                                                      --//Минимальный шаг профиля в секундах
                    av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect        VARCHAR2(1000);
  lv_table            VARCHAR2(150);
  lv_partly_er        VARCHAR2(600);
  lv_partly_ed        VARCHAR2(600);
  lv_decnsourcesec    VARCHAR2(1000);
  lv_decnsourcef      VARCHAR2(1000);
  lv_decperiod        VARCHAR2(600);
  lv_paramlist        VARCHAR2(4000);
  lv_grouping         VARCHAR2(600);
  ln_timezona         NUMBER;
  ln_countrow         NUMBER;
  ln_countfull        NUMBER;
  an_periodforyearstart NUMBER;
  an_periodforyearfinish NUMBER;
  lv_sqltimezone      VARCHAR2(2000);
  lv_sql              VARCHAR2(10000);
  lv_subsel           VARCHAR2(1000);
-----------------------------------
 BEGIN
  ln_timezona := interior_pg.get_hourtimezone;
  an_periodforyearstart := 190001;
  an_periodforyearfinish := 300001;

  IF (gn_dsummer = 0) THEN
   lv_sqltimezone :=
       ' and  date_time>= (to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24))
                    and   date_time <=(to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  ELSE
   lv_sqltimezone :=
       ' AND   P.date_time >= to_date('''
    || av_firstdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona
    || '
      AND   P.date_time <= to_date('''
    || av_lastdate
    || ''',''dd.mm.yyyy hh24:mi:ss'') + '
    || ln_timezona;
  END IF;

----------------------------------------------------------------------------------------------------
  IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                   --год
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                 --месяц
   IF gn_timezoneshift <> 0 OR an_codetemplate = gn_full_data THEN                                                                       --для таблицы halfhour
    ln_countfull :=
     interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), lv_grouping, an_stepprofile, an_periodforyearstart,
      an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   ELSE
    ln_countfull := interior_pg.get_countpoint_f(an_idgroup, an_ispoints, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period);
    ln_countrow := ln_countfull;
   END IF;
  ELSE                                                                                                                                    -- получасовки и сутки
   ln_countfull :=
    interior_pg.get_rowcount(an_idgroup, an_ispoints, av_rowcount, an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period,
     TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'));
   ln_countrow :=
    interior_pg.get_step(an_idgroup, an_ispoints, TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'), 0, an_stepprofile, an_periodforyearstart,
     an_periodforyearfinish, an_period);
  END IF;

-----------------------------------------------------------------------------------------------------------
  subselect_p(an_stepprofile, 190001, 300001, an_period, lv_subselect);
  takeofpartquerifornsorse_p(an_codetemplate, an_ispoints,                                                                                    --группа или точка
   an_stepprofile,                                                                                                 -- детализация только gn_stpHour,gn_stpMinute
   av_rowcount,                                                                                                                                                --
   av_firstdate, av_lastdate, an_idgroup, interior_pg.get_hourtimezone, ln_countfull, ln_countrow, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p(an_ispoints,                                                                                                                    --группа или точка
   lv_decperiod);

  IF (an_ispoints = 1) THEN
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  IF util_pg.get_customer_id = 1 AND ifnroot_f(an_idgroup) > 0 THEN
   lv_subsel :=
       ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
    || lv_subselect
    || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
    || lv_subselect
    || ' ))
       start with gr.gid='
    || an_idgroup
    || lv_subselect
    || ') ';
  ELSE
   lv_subsel :=
    ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_idgroup || lv_subselect || ') ';
  END IF;

  IF (an_codetemplate = gn_apbo_f) THEN
   lv_paramlist :=
       ',sum(DECODE(G.inverted,''y'',-util_pg.sld(P.mid,nvl(P.er'
    || lv_partly_er
    || ',0),
                  nvl(P.ed'
    || lv_partly_ed
    || ',0)),util_pg.sld(P.mid,nvl(P.er'
    || lv_partly_er
    || ',0),
                  nvl(P.ed'
    || lv_partly_ed
    || ',0)))'
    || lv_decperiod
    || ')*3600/'
    || an_stepprof
    || '/'
    || gn_powercoeff
    || ' ';
  ELSIF(an_codetemplate = gn_rpbo_f) THEN
   lv_paramlist :=
       ',sum(DECODE(G.inverted,''y'',-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)),
                  util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)))'
    || lv_decperiod
    || ')*3600/'
    || an_stepprof
    || '/'
    || gn_powercoeff
    || ' ';
  END IF;

  IF (an_stepprofile = gn_stphour) THEN
   lv_grouping := ' 1+FLOOR((date_time- to_date(''' || av_firstdate || ''',''dd.mm.yyyy hh24:mi:ss''))*' || TO_CHAR(1440.0 / an_powerprofile) || ' )';
   lv_table := ' halfhour ';
  ELSIF(an_stepprofile = gn_stpminute) THEN
   lv_grouping := ' 1+FLOOR((date_time- to_date(''' || av_firstdate || ''',''dd.mm.yyyy hh24:mi:ss''))*86400/' || an_stepprof || ') ';
   lv_table := ' profile ';
  END IF;

  lv_sql :=
      'select '
   || util_pg.hint_ordered
   || lv_grouping
   || ' BGroup'
   || lv_paramlist
   || ' AParam '
   || lv_decnsourcef
   || ' decnsour from groups G,'
   || lv_table
   || ' P
  WHERE G.mid=P.mid
      '
   || lv_sqltimezone
   || '
     AND   '
   || lv_subsel
   || ' GROUP BY '
   || lv_grouping
   || ' ORDER BY 1';

  OPEN acur_t FOR lv_sql;
 END;

-------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE limitpowerint_selectdata2_p(
 an_sec NUMBER, an_stepprof NUMBER,                                                                                       --//Минимальный шаг профиля в секундах
                                   av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   CEIL((
                  TRUNC(TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                + (morning_start - TRUNC(morning_start))
                - (TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                + an_sec
               )
             * 86400
             / an_stepprof) morning_start,
              FLOOR((
                    TRUNC(TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                  + (morning_end - TRUNC(morning_end))
                  - (TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                  + an_sec
                 )
               * 86400
               / an_stepprof)
            + 2 morning_end,
            CEIL((
                  TRUNC(TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                + (evening_start - TRUNC(evening_start))
                - (TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                + an_sec
               )
             * 86400
             / an_stepprof) evening_start,
              FLOOR((
                    TRUNC(TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                  + (evening_end - TRUNC(evening_end))
                  - (TO_DATE(av_firstdate, 'dd.mm.yyyy hh24:mi:ss'))
                  + an_sec
                 )
               * 86400
               / an_stepprof)
            + 2 evening_end,
            num, date_time
   FROM     (SELECT gl.morning_start, gl.morning_end, gl.evening_start, gl.evening_end, 1 num, gl.dstart date_time
             FROM   (SELECT   gid, MAX(dstart) dstart
                     FROM     grouplimit
                     WHERE    dstart <(TO_DATE(av_lastdate, 'dd.mm.yyyy hh24:mi:ss')) AND morning_start IS NOT NULL AND morning_end IS NOT NULL
                              AND evening_start IS NOT NULL AND evening_end IS NOT NULL
                     GROUP BY gid) mgl,
                    grouplimit gl,
                    (SELECT     gid
                     FROM       GROUPS g
                     WHERE      EXISTS(
                                 SELECT *
                                 FROM   grouplimit
                                 WHERE  gid = g.gid AND dstart <(TO_DATE(av_lastdate, 'dd.mm.yyyy hh24:mi:ss')) AND morning_start IS NOT NULL
                                        AND morning_end IS NOT NULL AND evening_start IS NOT NULL AND evening_end IS NOT NULL)
                                AND ROWNUM = 1
                     CONNECT BY PRIOR g.PARENT = g.gid AND(an_period BETWEEN NVL(g.nfromperiod, 0) AND NVL(g.ntillperiod, 299912))
                     START WITH g.gid = an_idgroup AND(an_period BETWEEN NVL(g.nfromperiod, 0) AND NVL(g.ntillperiod, 299912))) g
             WHERE  g.gid = mgl.gid AND mgl.gid = gl.gid(+) AND mgl.dstart = gl.dstart(+)
             UNION ALL
             SELECT morning_start, morning_end, evening_start, evening_end, 2 num, date_time
             FROM   maxhours
             WHERE  date_time <=(TO_DATE(av_lastdate, 'dd.mm.yyyy hh24:mi:ss')))
   ORDER BY 5, 6 DESC;
 END;

