 PROCEDURE tduinterior_formdescr_p(an_idgroup NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   gid, NVL(util_pg.get_shortname_f(short_name, mid), util_pg.get_name_f(NAME, mid)) short_name
   FROM     GROUPS
   WHERE    PARENT = an_idgroup AND(an_period BETWEEN NVL(nfromperiod, 0) AND NVL(ntillperiod, 299912))
   ORDER BY 2;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    av_obsoletetimelimit VARCHAR2, an_tempgid NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_partly_er        VARCHAR2(500);
  lv_partly_ed        VARCHAR2(500);
  lv_sub              VARCHAR2(500);
 BEGIN
  IF (an_ispoints = 0) THEN
   lv_partly_er := ' *decode(c.NPARTLY,2,0,1) * abs(nvl(c.NKC,1)) ';
   lv_partly_ed := ' *decode(c.NPARTLY,1,0,1) * abs(nvl(c.NKC,1)) ';
  ELSE
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  END IF;

  IF util_pg.get_customer_id = 1 THEN
   lv_sub := ' (prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null) ';
  ELSE
   lv_sub := ' (prior gid=parent)';
  END IF;

  OPEN acur_t FOR    'select
        decode(nvl(sum(obsolete),1),0,to_number(to_char(max(c.date_time),''-ddmmhh24mi'')),
        nvl(sum(obsolete),1)) obsolete,
        round(sum(decode(obsolete,0,(-util_pg.sld( c.mid,nvl(c.er'
                  || lv_partly_er
                  || ',0),nvl(c.ed'
                  || lv_partly_ed
                  || ',0)))*c.inverted,null))/'
                  || gn_powercoeff
                  || ',3)DT,
        round(sum(decode(obsolete,0,(-util_pg.sld( c.mid,nvl(c.q1,0),nvl(c.q3,0)))*c.inverted,NULL))/'
                  || gn_powercoeff
                  || ',3)DAT,
        to_char(max(c.date_time),''-ddmmhh24mi'') cur_date
        FROM (
        SELECT c.mid,date_time,er,ed,q1,q3,
        decode(sign('
                  || av_obsoletetimelimit
                  || '-abs(sysdate-decode(implement_date,null,sysdate,c.date_time))),1,0,1) obsolete,
        decode(inverted,''y'',1,-1) inverted,NPARTLY,NKC FROM curr_power c, points p,
         (SELECT mid,inverted,NPARTLY,NKC FROM GROUPS
         CONNECT BY ( '
                  || lv_sub
                  || '  AND ('
                  || an_period
                  || ' BETWEEN  nvl(nfromperiod,0) AND nvl(ntillperiod,299912))
         )
         START WITH gid='
                  || an_tempgid
                  || ' AND ('
                  || an_period
                  || ' BETWEEN  nvl(nfromperiod,0) AND nvl(ntillperiod,299912))
         ) f
         WHERE f.mid=c.mid AND c.mid=p.mid(+)) c ';
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_clickcomposition_p(an_arow NUMBER, an_idgroup NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_arow = 0) THEN
   OPEN acur_t FOR
    SELECT NVL(PARENT, 0) idgroup
    FROM   GROUPS
    WHERE  gid = an_idgroup;
  ELSE
   OPEN acur_t FOR
    SELECT COUNT(*) tempidgroup
    FROM   GROUPS
    WHERE  PARENT = an_idgroup;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_clickcomp2_p(an_idgroup NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT NVL(util_pg.get_name_f(NAME, mid), util_pg.get_shortname_f(short_name, mid)) NAME,
          NVL(util_pg.get_shortname_f(short_name, mid), util_pg.get_name_f(NAME, mid)) shortname, NVL(group_total, 'n') sumgroup
   FROM   GROUPS
   WHERE  gid = an_idgroup;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tconsumlimit_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    av_obsoletetimelimit VARCHAR2, an_stepprofile NUMBER,                                          -- детализация только gn_stpHour,gn_stpMinute
                                                                         an_groupislist NUMBER, an_tempgid NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subtab           VARCHAR2(1000);
  lv_partly_er        VARCHAR2(400);
  lv_partly_ed        VARCHAR2(400);
  lv_subselect        VARCHAR2(1000);
  lv_sql              VARCHAR2(10000);
  lv_sub              VARCHAR2(400);
 BEGIN
  IF (an_stepprofile = gn_stpmonth) THEN
   lv_subtab := ' AND ( nvl(g2.nfromperiod,0)<=' || an_periodforyearfinish || ' OR nvl(g2.ntillperiod,299912)>=' || an_periodforyearstart || ' ) ';
  ELSE
   lv_subtab := ' AND ( ' || an_period || '  BETWEEN  nvl(g2.nfromperiod,0) AND nvl(g2.ntillperiod,299912))';
  END IF;

  IF (an_ispoints = 0) THEN
   lv_partly_er := '*decode(c.NPARTLY,2,0,1)* abs(nvl(c.NKC,1)) ';
   lv_partly_ed := '*decode(c.NPARTLY,1,0,1)* abs(nvl(c.NKC,1)) ';
  ELSE
   lv_partly_er := '';
   lv_partly_ed := '';
  END IF;

  IF util_pg.get_customer_id = 1 AND ifnroot_f(an_tempgid) > 0 THEN
   lv_sub := ' (prior gr.gid=gr.parent) or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null) ';
  ELSE
   lv_sub := ' (prior gr.gid=gr.parent)';
  END IF;

  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  lv_sql :=
      'select limit, fact/'
   || gn_powercoeff
   || ' afact, fact/'
   || gn_powercoeff
   || '-limit limfact, armor, nvl(obsolete,1)obs
              FROM (SELECT
              decode(sum(obsolete),0,to_char(max(c.date_time),''-hh24mi''),sum(obsolete)) obsolete,
              sum(decode(obsolete,0,(-util_pg.sld(c.mid,nvl(c.er'
   || lv_partly_er
   || ',0),nvl(c.ed'
   || lv_partly_ed
   || ',0)))*c.inverted,null)) fact
              FROM (SELECT c.mid,date_time,er,ed,q1,q3,
              decode(sign('
   || av_obsoletetimelimit
   || '-abs(sysdate-decode(implement_date,null,sysdate,c.date_time))),1,0,1) obsolete,
              decode(inverted,''y'',1,-1) inverted,NPARTLY,NKC FROM curr_power c, points p,
              (SELECT gr.mid,gr.inverted,gr.NPARTLY, gr.NKC FROM GROUPS gr
              CONNECT BY ('
   || lv_sub
   --(prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)
   || lv_subselect
   || ' )
              START WITH gr.gid='
   || an_tempgid
   || lv_subselect
   || ' ) f
              WHERE f.mid=c.mid AND c.mid=p.mid(+))c),
              (SELECT sum(decode(flag,1,c.NLIMITCAPM,-1,c.NLIMITCAPE))/'
   || gn_powercoeff
   || ' LIMIT ,sum(NEMERGENCYRESERVE)/'
   || gn_powercoeff
   || ' armor
              FROM (SELECT decode(decode(sign(to_number(to_char(util_pg.planhour_f(1),''sssss''))-to_number(to_char(sysdate,''sssss''))),0,-1,1,1,-1,-1)+
              decode(sign(to_number(to_char(util_pg.planhour_f(2),''sssss''))-to_number(to_char(sysdate,''sssss''))),0,-1,1,1,-1,-1)
              ,2,-1,-2,-1,0,1) flag FROM dual), ';

  IF (an_groupislist = 1) THEN
   lv_sql :=
       lv_sql
    || ' grouplimit c,(select gid,NEMERGENCYRESERVE from groups
                     WHERE gid=(SELECT g2.gid FROM GROUPS g1, GROUPS g2
                     WHERE g1.gid='
    || an_tempgid
    || ' AND g1.nroot2 = g2.nroot2 AND g2.nroot1 IS NULL
                      '
    || lv_subtab
    || ' )) g ';
  ELSE
   lv_sql := lv_sql || ' grouplimit c,(select gr.gid,gr.NEMERGENCYRESERVE from groups gr where gr.gid=' || an_tempgid || lv_subselect || ' ) g ';
  END IF;

  lv_sql := lv_sql || ' where c.gid=g.gid and c.dstart=(select max(dstart) from grouplimit where gid=c.gid and dstart<sysdate))';

  OPEN acur_t FOR lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tconsumlimit_formdescr_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    an_stepprofile NUMBER,                                                                                        -- детализация fd->StepProfile
                                          an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_subselect        VARCHAR2(200);
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql := 'select g.mid, nvl(short_name,name)name from points g where parent = ' || an_idgroup || ' order by 2';
  ELSE
   subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
   lv_sql := 'select gr.gid mid, nvl(gr.short_name,gr.name)name from groups gr where gr.parent = ' || an_idgroup || lv_subselect || ' ORDER BY 2';
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

