 PROCEDURE tconsumimbalance_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    av_obsoletetimelimit VARCHAR2, an_codetemplate NUMBER, an_stepprofile NUMBER,                  -- детализация только gn_stpHour,gn_stpMinute
 an_tempgid NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER, av_firstdate VARCHAR2, av_lastdate VARCHAR2,
 acur_t OUT common_pg.tcur
 ) IS
  lv_subtab           VARCHAR2(1000);
  lv_partly_er        VARCHAR2(400);
  lv_partly_ed        VARCHAR2(400);
  lv_subselect        VARCHAR2(1000);
  lv_sql              VARCHAR2(10000);
  lv_table            VARCHAR2(200);
  lv_decperiod        VARCHAR2(400);
  lv_oracletable      VARCHAR2(200);
  lv_sub              VARCHAR2(400);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_table := 'points';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_table := 'groups';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;

  IF util_pg.get_customer_id = 1 AND ifnroot_f(an_tempgid) > 0 THEN
   lv_sub := ' (prior gr.gid=gr.parent) or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null) ';
  ELSE
   lv_sub := ' (prior gr.gid=gr.parent)';
  END IF;

  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  decperiod_p(an_ispoints, lv_decperiod);

  IF (an_codetemplate = gn_consumimbalance_pow_f) THEN
   lv_sql :=
       ' SELECT to_char(sysdate, ''dd.mm.yyyy hh24:mi'')currTime, ain, aall, decode(ain,0,-100,aall/ain*100)dat, obsolete
                FROM
                (SELECT SUM(DECODE(G.inverted,''y'',nvl(P.ed'
    || lv_partly_ed
    || ',0),nvl(P.er'
    || lv_partly_er
    || ',0)))/'
    || gn_powercoeff
    || ' ain,
                SUM((-util_pg.sld(P.mid,nvl(P.er'
    || lv_partly_er
    || ',0),nvl(P.ed'
    || lv_partly_ed
    || ',0)))*DECODE(G.inverted,''y'',1,-1)'
    || lv_decperiod
    || ')/'
    || gn_powercoeff
    || ' aall,
                SUM(decode( sign('
    || av_obsoletetimelimit
    || '-abs(sysdate-P.date_time)),1,P.obsolete,1)) obsolete
                FROM curr_power P, '
    || lv_table
    || ' g
                WHERE P.mid = g.mid AND g.gid IN
                 (SELECT gr.gid FROM GROUPS gr
                 CONNECT BY ('
    || lv_sub
    || lv_subselect
    || ' )
                 START WITH gr.gid='
    || an_tempgid
    || lv_subselect
    || ' )) ';
  ELSE
   interior2_choiceoftable_p(0, an_stepprofile, lv_oracletable);
   lv_sql :=
       ' SELECT to_char(sysdate, ''hh24:mi'') currTime, ain, aall, decode(ain,0,decode(aall,0,0,-100),aall/ain*100) dat, obsolete
                FROM
                (SELECT SUM(DECODE(G.inverted,''y'',nvl(P.ed'
    || lv_partly_ed
    || ',0),nvl(P.er'
    || lv_partly_er
    || ',0)))/'
    || gn_powercoeff
    || ' ain,
                SUM((-util_pg.sld(P.mid,nvl(P.er'
    || lv_partly_er
    || ',0),nvl(P.ed'
    || lv_partly_ed
    || ',0)))*DECODE(G.inverted,''y'',1,-1)'
    || lv_decperiod
    || ')/'
    || gn_powercoeff
    || ' aall,
                0 obsolete
                FROM '
    || lv_table
    || ' G , '
    || lv_oracletable
    || ' P
                WHERE G.mid=P.mid AND date_time >= (to_date('''
    || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss''))
                AND  date_time <= (to_date('''
    || av_lastdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'')) AND g.gid IN
                 (SELECT gr.gid FROM GROUPS gr
                 CONNECT BY ('
    || lv_sub
    || lv_subselect
    || ' )
                 START WITH gr.gid='
    || an_tempgid
    || lv_subselect
    || ')) ';
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

