 PROCEDURE tdecadinterior_selectdata_p(
 an_ispoints NUMBER,                                                                                                            --группа или точка fd-> IsPoints
                    av_datetime VARCHAR2, an_codetemplate NUMBER, an_stepprofile NUMBER,                           -- детализация только gn_stpHour,gn_stpMinute
                                                                                        an_tempgid NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subtab           VARCHAR2(1000);
  lv_partly_er        VARCHAR2(400);
  lv_partly_ed        VARCHAR2(400);
  lv_subselect        VARCHAR2(1000);
  lv_sql              VARCHAR2(10000);
  lv_table            VARCHAR2(200);
  lv_decperiod        VARCHAR2(400);
  lv_inverted         VARCHAR2(200);
  lv_paramlist        VARCHAR2(1000);
  ln_hourtimezone     NUMBER;
  lv_oracletable      VARCHAR2(200) := 'bill';
 BEGIN
  subselect_p(an_stepprofile, an_periodforyearstart, an_periodforyearfinish, an_period, lv_subselect);
  ln_hourtimezone := interior_pg.get_hourtimezone;

  IF (an_ispoints = 1) THEN
   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';

   IF util_pg.isfolder(an_tempgid) = 1 THEN
    lv_subtab :=
            ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4)' || gv_sqlcod || ' start with mid=' || an_tempgid || ') ';
   ELSE
    lv_subtab := ' G.mid=' || an_tempgid || ' ';
   END IF;

   lv_inverted := '''n''';
  ELSE
   lv_table := ' groups ';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';

   IF util_pg.get_customer_id = 1 AND ifnroot_f(an_tempgid) > 0 THEN
    lv_subtab :=
        ' G.gid in (select gr.gid from groups gr connect by ((prior gr.gid=gr.parent '
     || lv_subselect
     || ' )
      or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null '
     || lv_subselect
     || ' ))
       start with gr.gid='
     || an_tempgid
     || lv_subselect
     || ') ';
   ELSE
    lv_subtab :=
     ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent ' || lv_subselect || ' start with gr.gid=' || an_tempgid || lv_subselect
     || ') ';
   END IF;

   lv_inverted := 'G.inverted';
  END IF;

  decperiod_p(an_ispoints, lv_decperiod);

  IF (an_codetemplate = gn_aero_decad_f) THEN
   lv_paramlist := ' sum(DECODE(' || lv_inverted || ',''y'',P.ed' || lv_partly_ed || ', P.er' || lv_partly_er || ')' || lv_decperiod || ')/' || gn_powercoeff;
  ELSIF(an_codetemplate = gn_aebo_decad_f) THEN
   lv_paramlist :=
       ' sum( -util_pg.sld( P.mid, P.er'
    || lv_partly_er
    || ',
                 (P.ed'
    || lv_partly_ed
    || ' ) )*DECODE('
    || lv_inverted
    || ',''y'',1,-1)'
    || lv_decperiod
    || ')/'
    || gn_powercoeff;
  END IF;

  lv_paramlist :=
      ' sum(
  '
   || lv_paramlist
   || '
     )     over (ORDER BY  CEIL(to_char(p.date_time-1/86400,''dd'')/10)  ROWS BETWEEN unbounded preceding AND CURRENT ROW)
      val  , 0 nsource ';
  lv_sql :=
      'select kk.val,kk.nsource,ll.rn from (
  SELECT '
   || util_pg.hint_ordered
   || '
  
  CEIL(to_char(p.date_time-1/86400,''dd'')/10)A,
 
  '
   || lv_paramlist
   || '
    
 FROM '
   || lv_table
   || '  G, '
   || lv_oracletable
   || ' P 
 WHERE G.mid=P.mid AND
              date_time > trunc((to_date('''
   || av_datetime
   || ''', ''dd.mm.yyyy hh24:mi:ss'')+ '
   || ln_hourtimezone
   || '),''mm'')
              AND   date_time <=  add_months(trunc((to_date('''
   || av_datetime
   || ''', ''dd.mm.yyyy hh24:mi:ss'')+ '
   || ln_hourtimezone
   || '),''mm''),1)
           
              AND '
   || lv_subtab
   || '
  group by  (CEIL(to_char(p.date_time-1/86400,''dd'')/10))
  )kk,
  (select rownum rn from dict where rownum<4)ll
  where
  kk.A(+)=ll.rn
  order by ll.rn';

  /* AND   sysdate > add_months(trunc((to_date('''||av_datetime||''', ''dd.mm.yyyy hh24:mi:ss'')+ '||ln_hourtimezone||'),''mm''),1)*/

  --  delete from tmp_vil; INSERT INTO tmp_vil       VALUES (lv_sql);  COMMIT;
  OPEN acur_t FOR lv_sql;
 END;

----------------------------------------------------------------------------------------------------------------------
 PROCEDURE monitorlist_readtreen_p(an_nodeparent NUMBER, an_monitor NUMBER, an_monitor_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_nodeparent = 0) THEN
   OPEN acur_t FOR
    SELECT   1 havechild, monitor_id, mschema, NAME, dsize, DECODE(dsize, 0, 1, 2)
    FROM     monitors m
    WHERE    mschema = an_monitor AND nparent IS NULL AND EXISTS(SELECT *
                                                                 FROM   monitors
                                                                 WHERE  nparent = m.monitor_id)
    UNION ALL
    SELECT   0 havechild, monitor_id, mschema, NAME, dsize, DECODE(dsize, 0, 1, 2)
    FROM     monitors m
    WHERE    mschema = an_monitor AND nparent IS NULL AND NOT EXISTS(SELECT *
                                                                     FROM   monitors
                                                                     WHERE  nparent = m.monitor_id)
    ORDER BY 6, 4;
  ELSE
   OPEN acur_t FOR
    SELECT   1 havechild, monitor_id, mschema, NAME, dsize, DECODE(dsize, 0, 1, 2)
    FROM     monitors m
    WHERE    mschema = an_monitor AND nparent = an_monitor_id AND EXISTS(SELECT *
                                                                         FROM   monitors
                                                                         WHERE  nparent = m.monitor_id)
    UNION ALL
    SELECT   0 havechild, monitor_id, mschema, NAME, dsize, DECODE(dsize, 0, 1, 2)
    FROM     monitors m
    WHERE    mschema = an_monitor AND nparent = an_monitor_id AND NOT EXISTS(SELECT *
                                                                             FROM   monitors
                                                                             WHERE  nparent = m.monitor_id)
    ORDER BY 6, 4;
  END IF;
 END;

--------------------------------------------------------------------------------------------------------------------------
 PROCEDURE journalsys_selectdata_p(
 an_idgroup NUMBER, an_filter NUMBER, av_code VARCHAR2, av_orderstr VARCHAR2, av_selecteddate VARCHAR2, an_stepprof NUMBER, an_adv_filter NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_sql              VARCHAR2(5000);
  lv_tmp              VARCHAR2(1000);
  lv_ev1_filter       VARCHAR2(1000);
  lv_ev2_filter       VARCHAR2(10000);
 BEGIN
  lv_sql :=
   'SELECT   j.date_time field1,
         DECODE (pp.ind, 3, p.NAME || '' / '') || pp.NAME field2, d.veventtext||j.state_descr field3,
         j.state_cod field0, j.vcode field4
    FROM points p, points pp, journal j,METEREVENTSDICT d
   WHERE ( j.date_time >=decode(:par3,1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyyy''),
   2,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),3,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))
   -6,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi'')))
    AND j.date_time <decode(:par3,1,add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyyy''),12),
    2,add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),1),3,
    trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1))
     AND p.mid(+) = pp.PARENT
     AND j.mid = pp.mid AND j.nevent=d.nevent(+)';

  IF (an_idgroup <> 0) THEN
   lv_sql := lv_sql || ' AND (j.mid IN (SELECT  mid FROM points CONNECT BY PRIOR mid = PARENT  START WITH mid =' || an_idgroup || ' )) ';
  END IF;

  IF (an_filter <> 0) THEN
   lv_sql := lv_sql || 'AND (state_cod=DECODE(' || TO_CHAR(an_filter) || ',1,0,state_cod+1) OR state_cod<>DECODE(' || an_filter || ',2,0,state_cod)) ';
  END IF;

  IF (av_code IS NOT NULL) THEN
   lv_sql := lv_sql || ' AND (';

   FOR i IN 1 .. INSTR(av_code, ',', -1, 1) + 1 LOOP
    lv_tmp := util_pg.get_param(av_code, i, ',');

    IF lv_tmp IS NOT NULL THEN
     IF INSTR(lv_tmp, '%') > 0 OR INSTR(lv_tmp, '_') > 0 THEN
      lv_sql := lv_sql || ' j.vcode LIKE ''' || lv_tmp || ''' OR ';
     ELSE
      lv_sql := lv_sql || ' j.vcode = ''' || lv_tmp || ''' OR ';
     END IF;
    ELSE
     EXIT;
    END IF;
   END LOOP;

   lv_sql := RTRIM(lv_sql, 'OR ');
   lv_sql := lv_sql || ' ) ';
  END IF;

  IF (an_adv_filter > 0) THEN
   lv_ev1_filter :=                                                                                                   -- основной фильтр по основным сообщениям
                  ' AND j.nevent in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid=' || an_adv_filter || ') ';

   FOR lc_f IN                                                                                                       -- собираем фильтр по вторичным сообщениям
    (SELECT d.neventcode
     FROM   metereventsdict d, filters f
     WHERE  d.nevent = f.nevent AND d.neventclass = 2 AND f.nevent IN(SELECT     nevent
                                                                      FROM       filters
                                                                      WHERE      nevent IS NOT NULL
                                                                      CONNECT BY PRIOR nid = nparent
                                                                      START WITH nid = ABS(an_adv_filter))) LOOP
    lv_ev2_filter := lv_ev2_filter || ' j.vcode LIKE ''' ||(lc_f.neventcode - 1) || '%'' OR ';
   END LOOP;

   IF lv_ev2_filter IS NOT NULL THEN
    lv_ev2_filter := ' AND (' || RTRIM(lv_ev2_filter, 'OR ') || ')';
   END IF;
  ELSIF(an_adv_filter < 0) THEN
   lv_ev1_filter :=                                                                                                   -- основной фильтр по основным сообщениям
       ' AND (j.nevent NOT in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid='
    || (-1) * an_adv_filter
    || ') OR j.nevent IS NULL )';

   FOR lc_f IN                                                                                                        -- собираем фильтр по вторичным сообщениям
    (SELECT d.neventcode
     FROM   metereventsdict d, filters f
     WHERE  d.nevent = f.nevent AND d.neventclass = 2 AND f.nevent IN(SELECT     nevent
                                                                      FROM       filters
                                                                      WHERE      nevent IS NOT NULL
                                                                      CONNECT BY PRIOR nid = nparent
                                                                      START WITH nid = ABS(an_adv_filter))) LOOP
    lv_ev2_filter := lv_ev2_filter || ' j.vcode NOT LIKE ''' ||(lc_f.neventcode - 1) || '%'' AND ';
   END LOOP;

   IF lv_ev2_filter IS NOT NULL THEN
    lv_ev2_filter := ' AND ((' || RTRIM(lv_ev2_filter, 'AND ') || ') OR j.vcode IS NULL)';
   END IF;
  END IF;

  IF lv_ev2_filter IS NOT NULL THEN
   IF an_adv_filter > 0 THEN
    lv_sql := lv_sql || lv_ev1_filter || ' UNION ' || lv_sql || lv_ev2_filter || ' ORDER BY ' || av_orderstr;
   ELSIF an_adv_filter < 0 THEN
    lv_sql := lv_sql || lv_ev1_filter || ' INTERSECT ' || lv_sql || lv_ev2_filter || ' ORDER BY ' || av_orderstr;
   END IF;

   OPEN acur_t FOR lv_sql
   USING an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate, av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate,
         av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate, av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate,
         av_selecteddate, av_selecteddate;
  ELSE
   lv_sql := lv_sql || lv_ev1_filter || ' ORDER BY ' || av_orderstr;

   OPEN acur_t FOR lv_sql
   USING an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate, av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate,
         av_selecteddate;
  END IF;
 END;

--------------------------------------------------------------------------------------------------------------------
 PROCEDURE journal_selectdata_p(
 an_idgroup NUMBER, an_filter1_type NUMBER, an_filter2_mid NUMBER, av_orderstr VARCHAR2, av_selecteddate VARCHAR2, an_stepprof NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_sql              VARCHAR2(5000);
 BEGIN
  lv_sql :=
   'SELECT f.Date_Time field1, f.Name field2, f.Message field3, f.Task_Job field0
     FROM Fiscal f, users u
     WHERE u.NAME=f.NAME
     AND f.Date_Time>=decode(:par3,1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyyy''),2,
     trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),3,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))-6,
     trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi'')))
     AND f.Date_Time<decode(:par3,1,add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyy''),12),2,
     add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),1),3,
     trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1) ';

  IF (an_idgroup <> 0) THEN
   lv_sql := lv_sql || 'and f.Task_Cod in (SELECT task_Cod FROM tasks CONNECT BY prior Task_Id = Parent START WITH Task_Id =' || TO_CHAR(an_idgroup) || ' ) ';
  END IF;

  IF (an_filter1_type <> 0) THEN
   lv_sql := lv_sql || 'and task_job=' || TO_CHAR(an_filter1_type) || '  ';
  END IF;

  IF (an_filter2_mid <> 0) THEN
   lv_sql := lv_sql || 'and u.user_id=' || TO_CHAR(an_filter2_mid) || '  ';
  END IF;

  lv_sql := lv_sql || ' ORDER BY ' || av_orderstr;

  OPEN acur_t FOR lv_sql
  USING an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate, av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate,
        av_selecteddate;
 END;

