 PROCEDURE interioralert_refreshdata1_p(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT COUNT(*) iflag
   FROM   (SELECT state_date c, TO_CHAR(state_date, 'dd.mm.yy hh24:mi:ss') a, 'Нет связи по каналу ' || vname || '. ' || state_descr b
           FROM   last_save l, channels c
           WHERE  l.mid = c.cid AND l.state_cod <> 0
           UNION
           SELECT state_date c, TO_CHAR(state_date, 'dd.mm.yy hh24:mi:ss') a, 'Нет связи по каналу ' || vname || '. ' || state_descr b
           FROM   last_save l, deportation c
           WHERE  l.mid = c.ndeportation AND l.state_cod <> 0
           UNION
           SELECT state_date c, TO_CHAR(state_date, 'dd.mm.yy hh24:mi:ss') a, 'Нет данных по точке учета ' || NAME || '. ' || state_descr b
           FROM   last_save l, points p
           WHERE  l.mid = p.mid AND state_cod > 0 AND p.mid IN(SELECT mid
                                                               FROM   chanpoint
                                                               WHERE  cid IN(SELECT cid
                                                                             FROM   channels
                                                                             WHERE  was_dead IS NOT NULL)));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interioralert_refreshdata2_p(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   COUNT(*) iflag
   FROM     (SELECT l.date_time c, TO_CHAR(l.date_time, 'dd.mm.yy hh24:mi') a,
                       pa.NAME
                    || DECODE(pa.NAME, '', '', ' / ')
                    || p.NAME
                    || ': '
                    || DECODE(l1, 0, ' Нет фазы А.', '')
                    || DECODE(l2, 0, ' Нет фазы В.', '')
                    || DECODE(l3, 0, ' Нет фазы C.', '') b
             FROM   points p, points pa, lgstatus l
             WHERE  p.mid = l.mid AND p.PARENT = pa.mid(+) AND l.u <> 0 AND l1 + l2 + l3 < 3
             UNION
             SELECT ddate c, TO_CHAR(ddate, 'dd.mm.yy hh24:mi') a, vtext b
             FROM   check_status) aass
   ORDER BY c DESC;
 END;

