 PROCEDURE interioralert_refreshdata3_p(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT COUNT(*) iflag
   FROM   DUAL
   WHERE  EXISTS(SELECT *
                 FROM   journallast);
 END;

