 PROCEDURE journalalert_p(
 an_tag NUMBER, av_orderstr VARCHAR2, an_filter2_mid NUMBER, an_filter2_type NUMBER, av_code VARCHAR2, an_adv_filter NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_sql              VARCHAR2(8000);
  lv_addsql           VARCHAR2(8000);
  lv_tmp              VARCHAR2(1000);
  lv_ev1_filter       VARCHAR2(1000);
  lv_ev2_filter       VARCHAR2(10000);
 BEGIN
  IF (an_tag = 1) THEN
   IF an_filter2_mid > 0 THEN
    lv_addsql := ' AND l.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=' || an_filter2_mid || ') ';
   END IF;

   lv_sql :=
       'select mid field1, a field4, b field3, c field2, n field5
                  FROM (SELECT l.mid, state_date c, state_date a, ''Нет связи по каналу ''||vname||''. ''||state_descr b,a.com_num n
                        FROM last_save l, channels c, comports a
                        WHERE l.mid = c.cid AND l.STATE_COD<>0 AND c.com_id=a.com_id '
    || lv_addsql
    || 'UNION
                       SELECT l.mid, state_date c, state_date a, ''Нет связи по каналу ''||vname||''. ''||state_descr b, NULL n
                        FROM last_save l, deportation c
                        WHERE l.mid = c.ndeportation AND l.STATE_COD<>0 '
    || lv_addsql
    || 'UNION
                        SELECT p.mid, state_date c, state_date a, util_pg.get_pointname (p1.mid, 3, 0) /*p1.NAME*/||'' Нет данных по точке учета ''||p.NAME||''. ''||state_descr b, NULL n
                        FROM last_save l, points p , points p1
                        WHERE p1.mid = p.parent AND l.mid = p.mid AND l.state_cod > 0 AND
                          l.mid IN(SELECT mid FROM chanpoint WHERE cid IN (SELECT cid FROM channels WHERE was_dead IS NOT NULL))'
    || lv_addsql
    || ') aass
                  ORDER BY '
    || av_orderstr;

   OPEN acur_t FOR lv_sql;
  ELSIF(an_tag = 2) THEN
   IF an_filter2_mid > 0 THEN
    lv_addsql := ' AND l.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=' || an_filter2_mid || ') ';
   END IF;

   lv_sql :=
       'select mid field1, a field4, b field3, c field2
                  FROM
                    (
                           SELECT l.mid,l.date_time c, l.date_time a,
                           pa.NAME||decode(pa.NAME,'''','''','' / '')||p.NAME||'': ''||decode(l1, 0, '' Нет фазы А.'','''')||decode(l2, 0, '' Нет фазы В.'','''')||decode(l3, 0, '' Нет фазы C.'','''') b
                         FROM points p,points pa, LGstatus l
                         WHERE p.mid = l.mid AND p.parent=pa.mid(+) AND l.u <> 0 AND l.l1+l.l2+l.l3 < 3 '
    || lv_addsql
    || '
                         UNION ALL
                         SELECT NPROCEDURE mid,ddate c, ddate a, vtext b
                         FROM check_status
                    ) aass
                  ORDER BY '
    || av_orderstr;

   OPEN acur_t FOR lv_sql;
  ELSIF(an_tag = 3) THEN
   IF an_filter2_mid > 0 THEN
    lv_addsql := ' AND l.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=' || an_filter2_mid || ') ';
   END IF;

   IF an_filter2_type <> 0 THEN
    lv_addsql := lv_addsql || ' AND decode(l.state_cod,0,1,2)=' || an_filter2_type || ' ';
   END IF;

   lv_sql :=
       'select decode(l.state_cod,0,0,1) field1, l.date_time field4,
                    substr(pa.NAME||decode(pa.NAME,'''','''','' / '')||p.NAME||'': ''||d.veventtext||l.state_descr,1,170) field3,
                    l.date_time field2, l.vcode field5
                  FROM journallast l, points p, points pa,METEREVENTSDICT d
                  WHERE l.mid = p.mid(+) AND p.parent=pa.mid(+) AND l.nevent=d.nevent(+) '
    || lv_addsql;

   IF (av_code IS NOT NULL) THEN
    lv_sql := lv_sql || ' AND (';

    FOR i IN 1 .. INSTR(av_code, ',', -1, 1) + 1 LOOP
     lv_tmp := util_pg.get_param(av_code, i, ',');

     IF lv_tmp IS NOT NULL THEN
      IF INSTR(lv_tmp, '%') > 0 OR INSTR(lv_tmp, '_') > 0 THEN
       lv_sql := lv_sql || ' l.vcode LIKE ''' || lv_tmp || ''' OR ';
      ELSE
       lv_sql := lv_sql || ' l.vcode = ''' || lv_tmp || ''' OR ';
      END IF;
     ELSE
      EXIT;
     END IF;
    END LOOP;

    lv_sql := RTRIM(lv_sql, 'OR ');
    lv_sql := lv_sql || ' ) ';
   END IF;

   IF (an_adv_filter > 0) THEN
    lv_ev1_filter :=                                                                                                  -- основной фильтр по основным сообщениям
                  ' AND l.nevent in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid=' || an_adv_filter || ') ';

    FOR lc_f IN                                                                                                      -- собираем фильтр по вторичным сообщениям
     (SELECT d.neventcode
      FROM   metereventsdict d, filters f
      WHERE  d.nevent = f.nevent AND d.neventclass = 2 AND f.nevent IN(SELECT     nevent
                                                                       FROM       filters
                                                                       WHERE      nevent IS NOT NULL
                                                                       CONNECT BY PRIOR nid = nparent
                                                                       START WITH nid = ABS(an_adv_filter))) LOOP
     lv_ev2_filter := lv_ev2_filter || ' l.vcode LIKE ''' ||(lc_f.neventcode - 1) || '%'' OR ';
    END LOOP;

    IF lv_ev2_filter IS NOT NULL THEN
     lv_ev2_filter := ' AND (' || RTRIM(lv_ev2_filter, 'OR ') || ')';
    END IF;
   ELSIF(an_adv_filter < 0) THEN
    lv_ev1_filter :=                                                                                                  -- основной фильтр по основным сообщениям
        ' AND (l.nevent NOT in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid='
     || (-1) * an_adv_filter
     || ') OR l.nevent IS NULL )';

    FOR lc_f IN                                                                                                       -- собираем фильтр по вторичным сообщениям
     (SELECT d.neventcode
      FROM   metereventsdict d, filters f
      WHERE  d.nevent = f.nevent AND d.neventclass = 2 AND f.nevent IN(SELECT     nevent
                                                                       FROM       filters
                                                                       WHERE      nevent IS NOT NULL
                                                                       CONNECT BY PRIOR nid = nparent
                                                                       START WITH nid = ABS(an_adv_filter))) LOOP
     lv_ev2_filter := lv_ev2_filter || ' l.vcode NOT LIKE ''' ||(lc_f.neventcode - 1) || '%'' AND ';
    END LOOP;

    IF lv_ev2_filter IS NOT NULL THEN
     lv_ev2_filter := ' AND ((' || RTRIM(lv_ev2_filter, 'AND ') || ') OR l.vcode IS NULL)';
    END IF;
   END IF;

   IF lv_ev2_filter IS NOT NULL THEN
    IF an_adv_filter > 0 THEN
     lv_sql := lv_sql || lv_ev1_filter || ' UNION ' || lv_sql || lv_ev2_filter || ' ORDER BY ' || av_orderstr;
    ELSIF an_adv_filter < 0 THEN
     lv_sql := lv_sql || lv_ev1_filter || ' INTERSECT ' || lv_sql || lv_ev2_filter || ' ORDER BY ' || av_orderstr;
    END IF;
   ELSE
    lv_sql := lv_sql || lv_ev1_filter || ' ORDER BY ' || av_orderstr;
   END IF;

   OPEN acur_t FOR lv_sql;
  END IF;
 END;

