-- Проверка если это точка в дереве групп? для мониторов баланс
 FUNCTION ispointingroup(an_idgroup NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_ret
  FROM   GROUPS g
  WHERE  g.gid = an_idgroup AND mid IS NULL;

  RETURN ln_ret;
 END;

