 PROCEDURE get_schedulelist(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   --SELECT   s.nschedulelist, ( s.vname||'/'||t.vname ) vname,DECODE(t.dsummer,NULL,0,1)dsummer,t.nid
   SELECT   s.nschedulelist, s.vname, DECODE(t.dsummer, NULL, 0, 1) dsummer, t.nid
   FROM     schedulelist s, timezones t
   WHERE    s.nid = t.nid
   ORDER BY 1;
 END;

--------------------------------------------------------------------------------------------------------------
 PROCEDURE get_timezoneshift(an_midtimezone NUMBER, an_date DATE, an_nshift OUT NUMBER) IS
  ln_shift            NUMBER;
  ln_date             DATE;
 BEGIN
  SELECT DECODE(MAX(dsummer), NULL, 0, 1), MAX(dsummeresc) dd
  INTO   ln_shift, ln_date
  FROM   timezones
  WHERE  nid = an_midtimezone;

  IF (ln_date IS NOT NULL AND ln_date < an_date) THEN
   an_nshift := 0;
  ELSE
   an_nshift := ln_shift;
  END IF;
 END;

-------------------------------------------------------------------------------------------------------------
 PROCEDURE get_timezone(an_midtimezone NUMBER, an_nshift OUT NUMBER) IS
 BEGIN
  SELECT NVL(MAX(nshift), 0)
  INTO   an_nshift
  FROM   timezones
  WHERE  nid = an_midtimezone;
 END;

---------------------------------------------------------------------------------------------------------------
--возвращает кусок SQL-кода в зависимости от входящих параметров
 PROCEDURE takeofpartquerifornsorse_p(
 an_codetemplate NUMBER, an_ispoints NUMBER, an_stepprofile NUMBER, av_rowcount VARCHAR2, av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_id NUMBER,
 ln_timezona NUMBER, ln_countfull NUMBER, ln_countrow NUMBER, av_decnsourcesec OUT VARCHAR2, av_decnsourcef OUT VARCHAR2
 ) IS
  cv_sm               VARCHAR2(256);
  lv_rc1              VARCHAR2(400);
  lv_rc2              VARCHAR2(400);
  lv_grouping         VARCHAR2(400);
  lv_subsel           VARCHAR2(1000);
  ln_step             NUMBER;
 BEGIN
  --raise_application_error (-20001, gn_showvalidity);
  IF gn_showvalidity = 2 THEN                                                                                                   --метка качества электроэнергии
   cv_sm := ', util_pg.num_to_bin(bitor(p.NQE)) ';
   av_decnsourcef := cv_sm;
   av_decnsourcesec := cv_sm;
  ELSIF gn_showvalidity = 1 THEN                                                                                                         --метка качества данных
   IF (an_codetemplate = gn_full_data) THEN
    cv_sm := '''00'',''01''';
   ELSE
    cv_sm := 'qm_pg.sumqm(nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm),qm_pg.nodataqm),nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm)';
   END IF;

   IF (
       an_codetemplate = gn_aero_aera_aerb_aerc_f OR an_codetemplate = gn_aedo_aeda_aedb_aedc_f OR an_codetemplate = gn_aebo_aeba_aebb_aebc_f
       OR an_codetemplate = gn_rero_rera_rerb_rerc_f OR an_codetemplate = gn_redo_reda_redb_redc_f OR an_codetemplate = gn_rebo_reba_rebb_rebc_f
       OR an_codetemplate = gn_aera_aerb_aerc_aerd_f OR an_codetemplate = gn_aeda_aedb_aedc_aedd_f OR an_codetemplate = gn_rera_rerb_rerc_rerd_f
       OR an_codetemplate = gn_reda_redb_redc_redd_f
      ) THEN
    groupingtariff_p(an_stepprofile, ln_step, lv_grouping);
   ELSE
    grouping_p(an_stepprofile, av_firstdate, ln_step, lv_grouping);
   END IF;

   IF (an_stepprofile = gn_stpmonth) THEN                                                                                                                  --год
    av_decnsourcef :=
        ' ,decode(sign('
     || ln_countfull
     || '
       *to_char(trunc(add_months((to_date('''
     || av_firstdate
     || ''',''dd.mm.yyyy hh24:mi:ss'') + '
     || ln_timezona
     || ')
      ,'
     || lv_grouping
     || '))
       -1/86400,''dd'' )-count(*)),1,'
     || cv_sm
     || ') ';
    av_decnsourcesec :=
        ' ,decode(sign('
     || ln_countrow
     || '*round(
       to_date('''
     || av_lastdate
     || ''',''dd.mm.yyyy hh24:mi:ss'') + '
     || ln_timezona
     || '
       -
       to_date('''
     || av_firstdate
     || ''',''dd.mm.yyyy hh24:mi:ss'') + '
     || ln_timezona
     || ')* 48
         -count(*)),1,'
     || cv_sm
     || ') ';
   ELSIF(an_stepprofile = gn_stpday) THEN                                                                                                                --месяц
    av_decnsourcef := ' ,decode(sign(' || ln_countfull || '
        -count(*)),1,' || cv_sm || ') ';
    av_decnsourcesec := ' ,decode(sign(' || ln_countrow || '*
       ' ||             av_rowcount || '-count(*)),1,' || cv_sm || ') ';
   ELSE                                                                                                                                   -- получасовки и сутки
    av_decnsourcef := ' ,decode(sign(' || ln_countfull || '-count(*)),1,' || cv_sm || ') ';
    av_decnsourcesec := ' ,decode(sign(' || ln_countrow || '-count(*)),1,' || cv_sm || ') ';
   END IF;
  ELSE                                                                                                                              --не выводить метку качества
   cv_sm := ', 00 ';
   av_decnsourcef := cv_sm;
   av_decnsourcesec := cv_sm;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_step(
 an_gid NUMBER, an_type NUMBER, ad_dat DATE, an_plus NUMBER, an_stepprofile NUMBER, an_fromperiod NUMBER, an_tillperiod NUMBER, an_period NUMBER
 )
  RETURN NUMBER IS
  ln_val              NUMBER;
  ld_dat              DATE;
  lv_subsel           VARCHAR2(1000);
 BEGIN
-- return 0;

  --60/nvl(MAX(NINTEGRALPERIOD),30)*is_dayswitch (ad_dat)
  --ld_dat := ad_dat + an_plus;
  -- ln_timezona := interior_pg.get_hourtimezone;
  ld_dat := ad_dat + interior_pg.get_hourtimezone;

  IF an_type = 1 THEN
   IF util_pg.isfolder(an_gid) = 1 THEN
    SELECT SUM(24 *(60 / NVL(nintegralperiod, 30)) - 60 / NVL(nintegralperiod, 30) * util_pg.is_dayswitch(ld_dat))
    INTO   ln_val
    FROM   feeders
    WHERE  mid IN(SELECT     p.mid
                  FROM       points p
                  CONNECT BY PRIOR p.mid = p.PARENT AND PRIOR p.ind NOT IN(3, 4)
                  START WITH p.mid = an_gid);
   ELSE
    --SELECT MAX (24 * (60 / nintegralperiod))
    SELECT MAX(24 *(60 / NVL(nintegralperiod, 30)) - 60 / NVL(nintegralperiod, 30) * util_pg.is_dayswitch(ld_dat))
    INTO   ln_val
    FROM   feeders
    WHERE  mid = an_gid;
   END IF;
  ELSE
   IF util_pg.get_customer_id = 1 THEN
    IF (an_stepprofile = gn_stpmonth) THEN
     --SELECT SUM (24 * (60 / NVL (nintegralperiod, 30)))
     SELECT SUM(24 *(60 / NVL(nintegralperiod, 30)) - 60 / NVL(nintegralperiod, 30) * util_pg.is_dayswitch(ld_dat))
     INTO   ln_val
     FROM   feeders
     WHERE  mid IN(
             SELECT     gr.mid
             FROM       GROUPS gr
             CONNECT BY (
                         (PRIOR gr.gid = gr.PARENT AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod))
                         OR(
                            PRIOR gr.nroot2 = gr.nroot2 AND PRIOR gr.nroot1 > 0 AND gr.nroot1 IS NULL
                            AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod)
                           )
                        )
             START WITH gr.gid = an_gid AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod));
    ELSE
     --SELECT SUM (24 * (60 / NVL (nintegralperiod, 30)))
     SELECT SUM(24 *(60 / NVL(nintegralperiod, 30))) - 60 / NVL(MAX(nintegralperiod), 30) * util_pg.is_dayswitch(ld_dat)
     INTO   ln_val
     FROM   feeders
     WHERE  mid IN(
             SELECT     gr.mid
             FROM       GROUPS gr
             CONNECT BY (
                         (PRIOR gr.gid = gr.PARENT AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)))
                         OR(
                            PRIOR gr.nroot2 = gr.nroot2 AND PRIOR gr.nroot1 > 0 AND gr.nroot1 IS NULL
                            AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912))
                           )
                        )
             START WITH gr.gid = an_gid AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)));
    END IF;
   ELSE
    -- SELECT SUM (24 * (60 / NVL (nintegralperiod, 30)))
    SELECT SUM(24 *(60 / NVL(nintegralperiod, 30)) - 60 / NVL(nintegralperiod, 30) * util_pg.is_dayswitch(ld_dat))
    INTO   ln_val
    FROM   feeders
    WHERE  mid IN(SELECT     gr.mid
                  FROM       GROUPS gr
                  CONNECT BY PRIOR gr.gid = gr.PARENT
                  START WITH gr.gid = an_gid);
   END IF;
  END IF;

  RETURN NVL(ln_val, 0);
 END;

------------------------------------------------------------------------------------------------------------------
 FUNCTION get_rowcount(
 an_gid NUMBER, an_type NUMBER, av_rowcount VARCHAR2, an_stepprofile NUMBER, an_fromperiod NUMBER, an_tillperiod NUMBER, an_period NUMBER, ad_dat DATE
 )
--FUNCTION get_step (an_gid NUMBER)
 RETURN NUMBER IS
  ln_val              NUMBER;
  lv_subsel           VARCHAR2(1000);
  ld_dat              DATE;
  ln_kc NUMBER;
 BEGIN
  ld_dat := ad_dat + interior_pg.get_hourtimezone;
  ln_kc :=nvl((24/av_rowcount),1);

  IF an_type = 1 THEN
   IF util_pg.isfolder(an_gid) = 1 THEN
    SELECT SUM(DECODE(
             SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / nintegralperiod * util_pg.is_dayswitch(ld_dat))),
             -1,ln_kc * 60 / nintegralperiod,
             1
            ))
    INTO   ln_val
    FROM   feeders
    WHERE  mid IN(SELECT     p.mid
                  FROM       points p
                  CONNECT BY PRIOR p.mid = p.PARENT AND PRIOR p.ind NOT IN(3, 4)
                  START WITH p.mid = an_gid);
   ELSE
    SELECT MAX(DECODE(
             SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / nintegralperiod * util_pg.is_dayswitch(ld_dat))),
             -1,ln_kc* 60 / nintegralperiod,
             1
            ))
    INTO   ln_val
    FROM   feeders
    WHERE  mid = an_gid;
   END IF;
  ELSE
   IF util_pg.get_customer_id = 1 THEN
    IF ifnroot_f(an_gid) > 0 THEN
     IF (an_stepprofile = gn_stpmonth) THEN
      SELECT SUM(DECODE(
               SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / nintegralperiod * util_pg.is_dayswitch(ld_dat))),
               -1, 60 / nintegralperiod,
               1
              ))
      INTO   ln_val
      FROM   feeders
      WHERE  mid IN(
              SELECT     gr.mid
              FROM       GROUPS gr
              CONNECT BY (
                          (PRIOR gr.gid = gr.PARENT AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod))
                          OR(
                             PRIOR gr.nroot2 = gr.nroot2 AND PRIOR gr.nroot1 > 0 AND gr.nroot1 IS NULL
                             AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod)
                            )
                         )
              START WITH gr.gid = an_gid AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod));
     ELSE
      SELECT SUM(DECODE(
               SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / nintegralperiod * util_pg.is_dayswitch(ld_dat))),
               -1,ln_kc * 60 / nintegralperiod,
               1
              ))
      INTO   ln_val
      FROM   feeders
      WHERE  mid IN(
              SELECT     gr.mid
              FROM       GROUPS gr
              CONNECT BY (
                          (PRIOR gr.gid = gr.PARENT AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)))
                          OR(
                             PRIOR gr.nroot2 = gr.nroot2 AND PRIOR gr.nroot1 > 0 AND gr.nroot1 IS NULL
                             AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912))
                            )
                         )
              START WITH gr.gid = an_gid AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)));
     END IF;
    ELSE
     IF (an_stepprofile = gn_stpmonth) THEN
      SELECT SUM(DECODE(
               SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / NVL((nintegralperiod), 30) * util_pg.is_dayswitch(ld_dat))),
               -1, 60 / nintegralperiod,
               1
              ))
      INTO   ln_val
      FROM   feeders
      WHERE  mid IN(SELECT     gr.mid
                    FROM       GROUPS gr
                    CONNECT BY ((PRIOR gr.gid = gr.PARENT AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod)))
                    START WITH gr.gid = an_gid AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod));
     ELSE
      SELECT SUM(DECODE(
               SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / nintegralperiod * util_pg.is_dayswitch(ld_dat))),
               -1,ln_kc * 60 / nintegralperiod,
               1
              ))
      INTO   ln_val
      FROM   feeders
      WHERE  mid IN(SELECT     gr.mid
                    FROM       GROUPS gr
                    CONNECT BY ((PRIOR gr.gid = gr.PARENT AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912))))
                    START WITH gr.gid = an_gid AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)));
     END IF;
    END IF;
   ELSE
    SELECT SUM(DECODE(
             SIGN(av_rowcount -(24 *(60 / nintegralperiod) - 60 / nintegralperiod * util_pg.is_dayswitch(ld_dat))),
             -1,ln_kc * 60 / nintegralperiod,
             1
            ))
    INTO   ln_val
    FROM   feeders
    WHERE  mid IN(SELECT     gr.mid
                  FROM       GROUPS gr
                  CONNECT BY PRIOR gr.gid = gr.PARENT
                  START WITH gr.gid = an_gid);
   END IF;
  END IF;

  RETURN NVL(ln_val, 1);
 END;

------------------------------------------------------------------------------------------------------------------
 -- Вычисление количества точек в группе an_type-1 points, иначе - groups
 FUNCTION get_countpoint_f(an_id NUMBER, an_type NUMBER, an_stepprofile NUMBER, an_fromperiod NUMBER, an_tillperiod NUMBER, an_period NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
-- return 0;
  IF an_type = 1 THEN
   IF util_pg.isfolder(an_id) = 1 THEN
    SELECT     COUNT(*)
    INTO       ln_ret
    FROM       points
    WHERE      mid IN(SELECT mid
                      FROM   feeders)
    CONNECT BY PRIOR mid = PARENT AND PRIOR ind NOT IN(3, 4)
    START WITH mid = an_id;
   ELSE
    ln_ret := 1;
   END IF;
  ELSE
   IF util_pg.get_customer_id = 1 THEN
    IF ifnroot_f(an_id) > 0 THEN
     IF (an_stepprofile = gn_stpmonth) THEN
      SELECT COUNT(*)
      INTO   ln_ret
      FROM   (SELECT DISTINCT gr.mid
              FROM            GROUPS gr
              WHERE           gr.mid IN(SELECT mid
                                        FROM   feeders)
              CONNECT BY      (
                               (PRIOR gr.gid = gr.PARENT AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod))
                               OR(
                                  PRIOR gr.nroot2 = gr.nroot2 AND PRIOR gr.nroot1 > 0 AND gr.nroot1 IS NULL
                                  AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod)
                                 )
                              )
              START WITH      gr.gid = an_id AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod))
      WHERE  mid IS NOT NULL;
     ELSE
      SELECT COUNT(*)
      INTO   ln_ret
      FROM   (SELECT DISTINCT gr.mid
              FROM            GROUPS gr
              WHERE           gr.mid IN(SELECT mid
                                        FROM   feeders)
              CONNECT BY      (
                               (PRIOR gr.gid = gr.PARENT AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)))
                               OR(
                                  PRIOR gr.nroot2 = gr.nroot2 AND PRIOR gr.nroot1 > 0 AND gr.nroot1 IS NULL
                                  AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912))
                                 )
                              )
              START WITH      gr.gid = an_id AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)))
      WHERE  mid IS NOT NULL;
     END IF;
    ELSE
     IF (an_stepprofile = gn_stpmonth) THEN
      SELECT COUNT(*)
      INTO   ln_ret
      FROM   (SELECT DISTINCT gr.mid
              FROM            GROUPS gr
              WHERE           gr.mid IN(SELECT mid
                                        FROM   feeders)
              CONNECT BY      ((PRIOR gr.gid = gr.PARENT AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod)))
              START WITH      gr.gid = an_id AND(NVL(gr.nfromperiod, 0) <= an_tillperiod OR NVL(gr.ntillperiod, 299912) >= an_fromperiod))
      WHERE  mid IS NOT NULL;
     ELSE
      SELECT COUNT(*)
      INTO   ln_ret
      FROM   (SELECT DISTINCT gr.mid
              FROM            GROUPS gr
              WHERE           gr.mid IN(SELECT mid
                                        FROM   feeders)
              CONNECT BY      ((PRIOR gr.gid = gr.PARENT AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912))))
              START WITH      gr.gid = an_id AND(an_period BETWEEN NVL(gr.nfromperiod, 0) AND NVL(gr.ntillperiod, 299912)))
      WHERE  mid IS NOT NULL;
     END IF;
    END IF;
   ELSE
    SELECT COUNT(*)
    INTO   ln_ret
    FROM   (SELECT DISTINCT mid
            FROM            GROUPS
            WHERE           mid IN(SELECT mid
                                   FROM   feeders)
            CONNECT BY      PRIOR gid = PARENT
            START WITH      gid = an_id)
    WHERE  mid IS NOT NULL;
   END IF;
  END IF;

  RETURN NVL(ln_ret, 1);
 END;

-------------------------------------------------------------------------------------------------------------------
--для ХЭС нужно ли обрезать группы по nroot
 FUNCTION ifnroot_f(an_id NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_ret
  FROM   (SELECT     g.gid
          FROM       GROUPS g
          CONNECT BY PRIOR g.PARENT = g.gid
          START WITH g.gid = an_id) tt
  WHERE  tt.gid IN(gn_parent1, gn_parent2);

  RETURN ln_ret;
 END;
------------------------------------------------------------------------------------------------------------------
END;
/


