CREATE OR REPLACE 
PACKAGE BODY loadct_pg IS
------------------------------------------------------------------------------------------------------------------------
   -- Интерфейс взаимодействия БД с загрузчиком CT
   -- дата создания 02/12/2001 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 cn_offset   CONSTANT NUMBER := 0;
--100000000;
 cn_source   CONSTANT NUMBER := 10;

------------------------------------------------------------------------------------------------------------------------
--Вставка 3-х минуток
-- изменения от 05.11.2003, EVK
 PROCEDURE set_profile (an_mid NUMBER, ad_date DATE, an_er NUMBER) IS
  ln_mid     NUMBER DEFAULT util_pg.getpointid (an_mid + cn_offset);
  old_min    NUMBER;
  new_min    NUMBER;
  new_date   DATE;
 BEGIN
  IF ln_mid IS NULL THEN
   RETURN;
  END IF;

  UPDATE curr_power
     SET er = an_er,
         obsolete = 0,
         date_time = ad_date
   WHERE mid = ln_mid;

  old_min := TO_NUMBER (TO_CHAR (ad_date, 'mi'));
  new_min := ROUND (old_min / 3, 0) * 3;

  IF old_min != new_min THEN
--        ad_date:=ad_date+1/(24*60*(new_min-old_min));
   SELECT ad_date + (1 / (24 * 60 * (new_min - old_min)))
     INTO new_date
     FROM DUAL;
  ELSE
   new_date := ad_date;
  END IF;

  UPDATE PROFILE
     SET er = an_er / 20
   WHERE mid = ln_mid AND date_time = new_date;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO PROFILE
               (mid, date_time, er
               )
        VALUES (ln_mid, new_date, an_er / 20
               );
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   RAISE;
 END;

 ------------------------------------------------------------------------------------------------------------------------
