 END;
*/

 --Вставка графика нагрузки
 PROCEDURE set_halfhour (an_mid NUMBER, ad_date DATE, an_type NUMBER, an_val common_pg.tt_number) IS
  ld_start   DATE   DEFAULT TRUNC (ad_date) + 1 / 48;
  i          NUMBER DEFAULT 1;
  ln_mid     NUMBER DEFAULT util_pg.getpointid (an_mid + cn_offset);
  ln_kc      NUMBER;
 BEGIN
  IF ln_mid IS NULL THEN
   RETURN;
  END IF;

  SELECT MAX (kc)
    INTO ln_kc
    FROM feeders
   WHERE mid = ln_mid;

  WHILE ld_start <= TRUNC (ad_date) + 1 AND i <= an_val.COUNT LOOP
   IF an_type = 1 THEN
    UPDATE halfhourold
       SET er = an_val (i) / 2,
           denter = SYSDATE
     WHERE mid = ln_mid AND date_time = ld_start AND nsource = cn_source;

    IF SQL%ROWCOUNT = 0 THEN
     INSERT INTO halfhourold
                 (mid, date_time, er, nsource, nkc
                 )
          VALUES (ln_mid, ld_start, an_val (i) / 2, cn_source, ln_kc
                 );
    END IF;
   ELSIF an_type = 2 THEN
    UPDATE halfhourold
       SET q1 = an_val (i) / 2,
           denter = SYSDATE
     WHERE mid = ln_mid AND date_time = ld_start AND nsource = cn_source;

    IF SQL%ROWCOUNT = 0 THEN
     INSERT INTO halfhourold
                 (mid, date_time, q1, nsource, nkc
                 )
          VALUES (ln_mid, ld_start, an_val (i) / 2, cn_source, ln_kc
                 );
    END IF;
   END IF;

   ld_start := ld_start + 1 / 48;
   i := i + 1;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Вставка суточных
 PROCEDURE set_bill (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_q1 NUMBER) IS
  ln_mid   NUMBER DEFAULT util_pg.getpointid (an_mid + cn_offset);
  ln_kc    NUMBER;
 BEGIN
  IF ln_mid IS NULL THEN
   RETURN;
  END IF;

  SELECT MAX (kc)
    INTO ln_kc
    FROM feeders
   WHERE mid = ln_mid;

  UPDATE bill
     SET er = an_er,
         q1 = an_q1
   WHERE mid = ln_mid AND date_time = TRUNC (ad_date) + 1 AND nsource = cn_source;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO bill
               (mid, date_time, er, q1, nsource, er_kc, q1_kc
               )
        VALUES (ln_mid, TRUNC (ad_date) + 1, an_er, an_q1, cn_source, ln_kc, ln_kc
               );
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Окончание загрузки
 -- 3-х , получасовки, сутиочные 0 или 1
 PROCEDURE set_signal (av_mask VARCHAR2) IS
 BEGIN
  NULL;
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body LOADCT_PG
