CREATE OR REPLACE 
PACKAGE BODY loss_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- пакет работы с потерями
   -- дата создания 24/02/2003 (Сечин А.А.)
 gn_task_code NUMBER DEFAULT 46;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p(
  an_mid                    NUMBER, --Ид точки
  av_name                   VARCHAR2, --Название
  an_sn                     NUMBER, --NSN
  an_sh                     NUMBER, --NSH
  an_deltapidling           NUMBER, --NDELTAPIDLING
  an_deltapsc               NUMBER, --NDELTAPSC
  an_iidling                NUMBER, --NIIDLING
  an_usc                    NUMBER, --Uкз% /
  an_ro                     NUMBER, --NRO
  an_xo                     NUMBER, --NXO
  an_l                      NUMBER, --NL
  an_un                     NUMBER, --NUN
  an_energypercent          NUMBER, --Процент вхождения
  an_workinghours           NUMBER, --Время работы
  an_fullhours              NUMBER, --Полное время
  an_notincludeconsump      NUMBER, --Расход не учитывать
  an_parallelconnection     NUMBER, --Паралельное соединение
  an_renergypercent         NUMBER, --Потери Реактив
  an_procent                NUMBER, --Расчет по процентам
  an_connectionparam    OUT NUMBER --Ид параметра
                                  ) IS
  ln_connectionparam NUMBER;
 BEGIN
  SAVEPOINT loss_ins;
  SELECT points_seq.NEXTVAL
    INTO ln_connectionparam
    FROM DUAL;
  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nsn, nsh, ndeltapidling, ndeltapsc, niidling, nusc,
               nro, nxo, nl, nun, nenergypercent, nworkinghours, nfullhours, nnotincludeconsump,
               nparallelconnection, nrenergypercent, nprocent)
       VALUES (ln_connectionparam, an_mid, av_name, an_sn, an_sh, an_deltapidling, an_deltapsc, an_iidling, an_usc,
               an_ro, an_xo, an_l, an_un, an_energypercent, an_workinghours, an_fullhours, an_notincludeconsump,
               an_parallelconnection, an_renergypercent, an_procent);
  an_connectionparam := ln_connectionparam;
  admin_pg.fiscal_p(
   gn_task_code, 1, 'Для точки ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || ' добавлен параметр потерь ' ||
                    NVL(av_name, an_connectionparam));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_ins;
   raise_application_error(
    -20001, 'loss_pg.ins_p: Ошибка вставки параметров присоединения. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
