   gn_task_code, 2, 'Изменено время работы точки ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_settime;
   raise_application_error(
    -20001, 'loss_pg.settime_p: Задания времени работы точки учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
