    -- Процедура привязки точек
 PROCEDURE setpoint_p(
  an_connectionparam NUMBER, --Ид канала
  at_mid             common_pg.tt_number, --Мас ид точек
  at_type            common_pg.tt_number, --Мас типов расчета
  at_kc              common_pg.tt_number, --Мас КС
  at_recompens       common_pg.tt_number --Мас расчета реактива
                                        ) IS
  ln_a    NUMBER        DEFAULT 1;
  ln_mid  NUMBER;
  lv_name VARCHAR2(200);
 BEGIN
  SAVEPOINT loss_set;
  DELETE FROM usedconsumpt
        WHERE nconnectionparam = an_connectionparam;
  IF  at_mid.COUNT > 0 AND at_mid(1) <> 0 THEN
   FOR i IN 1 .. at_mid.COUNT LOOP
    INSERT INTO usedconsumpt
                (nconnectionparam, mid, ntype, nkc,
                 nrecompens)
         VALUES (an_connectionparam, at_mid(i), at_type(i), at_kc(i),
                 DECODE(at_recompens(i), 1, 1, 0, NULL, at_recompens(i)));
    ln_a := ln_a + 1;
   END LOOP;
  END IF;
  SELECT mid, vname
    INTO ln_mid, lv_name
    FROM connectionparam
   WHERE nconnectionparam = an_connectionparam;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Для точки ' || util_pg.node_path_f(ln_mid, 'points', 'mid', 'parent') ||
                    ' изменена привязка точек в параметре потерь ' || NVL(lv_name, an_connectionparam));
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   ROLLBACK TO SAVEPOINT loss_set;
   raise_application_error(
    -20001, 'loss_pg.setpoint_p: Ошибка привязки точек к параметру. ' || CHR(10) || 'Повторное вхождение ' ||
            util_pg.get_pointname(at_mid(ln_a), 1) || ' с одинаковым видом измерения.' || CHR(10) || SQLERRM(SQLCODE));
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_set;
   raise_application_error(
    -20001, 'loss_pg.setpoint_p: Ошибка привязки точек к параметру. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура привязки точек для долевых потерь
    -- Add by KSS
 PROCEDURE setsharedpoint_p(
  an_connectionparam NUMBER, --Ид канала
  at_mid             common_pg.tt_number, --Мас ид точек
  at_calc            common_pg.tt_number --Мас расчета реактива
                                        ) IS
  ln_a    NUMBER        DEFAULT 1;
  ln_mid  NUMBER;
  lv_name VARCHAR2(200);
 BEGIN
  SAVEPOINT lossshared_set;
  DELETE FROM sharedconnectionparam
        WHERE nconnectionparam = an_connectionparam;
  IF  at_mid.COUNT > 0 AND at_mid(1) <> 0 THEN
   FOR i IN 1 .. at_mid.COUNT LOOP
    INSERT INTO sharedconnectionparam
                (nconnectionparam, mid, nnotincludeconsump)
         VALUES (an_connectionparam, at_mid(i), at_calc(i));
    ln_a := ln_a + 1;
   END LOOP;
  END IF;
  SELECT mid, vname
    INTO ln_mid, lv_name
    FROM connectionparam
   WHERE nconnectionparam = an_connectionparam;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Для точки ' || util_pg.node_path_f(ln_mid, 'points', 'mid', 'parent') ||
                    ' изменена привязка долевых точек в параметре потерь ' || NVL(lv_name, an_connectionparam));
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   ROLLBACK TO SAVEPOINT lossshared_set;
   raise_application_error(
    -20001, 'loss_pg.setsharedpoint_p: Ошибка привязки долевых точек к параметру. ' || CHR(10) ||
            'Повторное вхождение <' || util_pg.get_pointname(at_mid(ln_a), 1) || '> с одинаковыми параметрами.' || CHR(
                                                                                                                    10) ||
            SQLERRM(SQLCODE));
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT lossshared_set;
   raise_application_error(
    -20001, 'loss_pg.setpoint_p: Ошибка привязки долевых точек к параметру. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура изменения паралельных соединений
    -- Add by KSS
 PROCEDURE setparallelconn_p(
  an_mid          common_pg.tt_number, --Ид параметра
  an_par   IN OUT common_pg.tt_number,
  --Ид паралельной связки (0-новая)
  an_group        common_pg.tt_number,
  an_del          NUMBER DEFAULT 0) IS
  ln_count NUMBER;
  lv_name  VARCHAR2(512);
 BEGIN
  SAVEPOINT losparallel_set;
  UPDATE connectionparam
     SET nparallelconnection = NULL
   WHERE nparallelconnection IS NOT NULL;
  DELETE FROM parallelconnection;
  IF  an_del = 0 AND an_mid.COUNT > 0 AND an_mid(1) <> 0 THEN
   FOR i IN 1 .. an_mid.COUNT LOOP
    IF an_par(i) = 0 THEN
     FOR j IN 1 .. an_group.COUNT LOOP
      IF i <> j THEN
       IF  an_group(i) = an_group(j) AND an_par(j) <> 0 THEN
        an_par(i) := an_par(j);
        EXIT;
       END IF;
      END IF;
     END LOOP;
     IF an_par(i) = 0 THEN
      SELECT points_seq.NEXTVAL
        INTO an_par(i)
        FROM DUAL;
     END IF;
    END IF;
    SELECT COUNT(nparallelconnection)
      INTO ln_count
      FROM parallelconnection
     WHERE nparallelconnection = an_par(i);
    IF ln_count = 0 THEN
     INSERT INTO parallelconnection
                 (nparallelconnection)
          VALUES (an_par(i));
    END IF;
    UPDATE connectionparam
       SET nparallelconnection = an_par(i)
     WHERE nconnectionparam = an_mid(i);
   --        WHERE mid = an_mid (i);
   END LOOP;
  END IF;
  admin_pg.fiscal_p(gn_task_code, 2, 'Произведено изменение параметров паралельных соединений.');
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT losparallel_set;
   raise_application_error(
    -20001, 'loss_pg.setpoint_p: Ошибка изменения паралельных соединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура изменения зависимых параметров
    -- Add by KSS
 PROCEDURE setrelatedconn_p(
  an_conn      common_pg.tt_number, --Ид параметра
  an_firstconn common_pg.tt_number, --Ид первичного параметра
  an_kc        common_pg.tt_number --Коэффициент зависимости
                                  ) IS
 BEGIN
  SAVEPOINT losrelated_set;
  DELETE FROM relatedparam;
  IF  an_conn.COUNT > 0 AND an_conn(1) <> 0 THEN
   FOR i IN 1 .. an_conn.COUNT LOOP
    INSERT INTO relatedparam
                (nconnectionparam, nfirstparam, nkc)
         VALUES (an_conn(i), an_firstconn(i), an_kc(i));
   END LOOP;
  END IF;
  admin_pg.fiscal_p(gn_task_code, 2, 'Произведено изменение зависимых параметров.');
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT losrelated_set;
   raise_application_error(
    -20001, 'loss_pg.setpoint_p: Ошибка изменения зависимых соединений. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setparamtime_p(
  an_connparam    NUMBER, --Ид параметра
  at_period       common_pg.tt_number, --Период
  at_workinghours common_pg.tt_number, --Время работы
  at_fullhours    common_pg.tt_number --Полное время
                                     ) IS
 BEGIN
  SAVEPOINT loss_settime;
  DELETE FROM connectionparamfullhours
        WHERE nconnectionparam = an_connparam;
  IF  at_period.COUNT > 0 AND at_period(1) <> 0 THEN
   FOR i IN 1 .. at_period.COUNT LOOP
    INSERT INTO connectionparamfullhours
                (nconnectionparam, naccperiod, nfullhours, nworkinghours)
         VALUES (an_connparam, at_period(i), at_fullhours(i), at_workinghours(i));
   END LOOP;
  END IF;
  admin_pg.fiscal_p(gn_task_code, 2, 'Изменено время работы параметра ' || an_connparam);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_setparamtime;
   raise_application_error(
    -20001, 'loss_pg.setparamtime_p: Задания времени работы точки учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
