CREATE OR REPLACE 
PACKAGE BODY maketarm_pg IS
-------------------------------------------------------------------------------------------
--****                       Implementation                                          ****--
-------------------------------------------------------------------------------------------
 PROCEDURE send_maket(an_maket NUMBER, ad_date DATE, an_deportation NUMBER) IS
 BEGIN
  UPDATE deportfiles
  SET nstate = 0,
      dsend = NULL,
      verror = NULL
  WHERE  ddate = ad_date AND(an_deportation IS NULL OR ndeportation = an_deportation) AND ndeportation IN(SELECT ndeportation
                                                                                                          FROM   deportation
                                                                                                          WHERE  nmaket = an_maket);

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- для поддержки старых версий клиента
 PROCEDURE readnode_p(an_parent NUMBER, an_ismaket NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF an_ismaket = 1 THEN
   IF an_parent IS NULL THEN
    OPEN acur_t FOR
     SELECT   m.nmaket, 1 objtype, 1 ismaket, m.vname, m.nblock, m.verror, 0 nparent,
              TO_CHAR(m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift / 1440, 'dd.mm.yyyy hh24:mi:ss') nextcreated, dp.nperiod
     FROM     makets m, deportprocedures dp
     WHERE    dp.nprocedure = m.nprocedure AND nmaket NOT IN(SELECT NVL(util_pg.allnumber_f(util_pg.get_param(init_str, 5, ';')), 0)
                                                             FROM   channels
                                                             WHERE  util_pg.is_uppd2(protocol_id) = 1) AND dp.ntype = 0
     ORDER BY m.vname;
   ELSE
    OPEN acur_t FOR
     SELECT     ndeportation nmaket, 2 objtype, 1 ismaket, vname, nblock, '' verror, nparent, '' nextcreated, 0 nperiod
     FROM       deportation
     CONNECT BY PRIOR ndeportation = nparent
     START WITH nmaket = an_parent
     ORDER BY   vname;
   END IF;
  ELSE
   IF an_parent IS NULL THEN
    OPEN acur_t FOR
     SELECT   p.mid nmaket, 1 objtype, 0 ismaket, p.NAME vname, 0 nblock, '' verror, 0 nparent, '' nextcreated, 1 nperiod
     FROM     points p
     WHERE    mid IN(SELECT PARENT
                     FROM   points p, channels c
                     WHERE  p.mid = c.cid(+) AND NVL(c.nkind, 0) <> 1 AND util_pg.is_uppd2(c.protocol_id) = 1)
     ORDER BY vname;
   ELSE
    OPEN acur_t FOR
     SELECT   c.cid nmaket, 2 objtype, 0 ismaket, c.vname, channels_pg.is_block(c.cid, c.blocking, c.nkind) nblock, '' verror, 1 nparent, '' nextcreated, 1 nperiod
     FROM     channels c
     WHERE    c.cid IN(SELECT mid
                       FROM   points
                       WHERE  PARENT = an_parent) AND util_pg.is_uppd2(protocol_id) = 1
     ORDER BY vname;
   END IF;
  /*SELECT DISTINCT c.cid nmaket, 1 objtype, 0 ismaket, c.vname, 0 nblock, u.verror, 0 nparent, '' nextcreated, 1 nperiod
             FROM channels c, uppdstat u
            WHERE c.cid = u.cid(+) AND util_pg.is_uppd2(protocol_id) = 1
         ORDER BY vname;*/
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE readnode_p(an_parent NUMBER, an_partype NUMBER, an_ismaket NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF an_ismaket = 1 THEN                                                                                                                      -- дерево макетов
   IF an_partype = 1 THEN                                                                                                                   -- родитель - макет
    OPEN acur_t FOR
     SELECT     0 havechild, ndeportation nmaket, 2 objtype, 1 ismaket, vname, nblock, '' verror, nparent, '' nextcreated, 0 nperiod
     FROM       deportation
     CONNECT BY PRIOR ndeportation = nparent
     START WITH nmaket = an_parent
     ORDER BY   vname;
   ELSIF an_partype = 0 THEN                                                                                                                 -- родитель - папка
    OPEN acur_t FOR
     SELECT   1 havechild, m.nmaket, 1 objtype, 1 ismaket, m.vname, m.nblock, m.verror, p.PARENT nparent,
              TO_CHAR(m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift / 1440, 'dd.mm.yyyy hh24:mi:ss') nextcreated, dp.nperiod
     FROM     makets m, deportprocedures dp, points p
     WHERE    dp.nprocedure = m.nprocedure AND m.nmaket NOT IN(SELECT NVL(util_pg.allnumber_f(util_pg.get_param(init_str, 5, ';')), 0)
                                                               FROM   channels
                                                               WHERE  util_pg.is_uppd2(protocol_id) = 1) AND dp.ntype = 0 AND p.mid = m.nmaket
              AND p.PARENT = DECODE(an_parent, 0, 4, an_parent) AND EXISTS(SELECT 1
                                                                           FROM   deportation
                                                                           WHERE  nmaket = m.nmaket)
     UNION ALL
     SELECT   0 havechild, m.nmaket, 1 objtype, 1 ismaket, m.vname, m.nblock, m.verror, p.PARENT nparent,
              TO_CHAR(m.doldcreated + 2 * file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift / 1440, 'dd.mm.yyyy hh24:mi:ss') nextcreated, dp.nperiod
     FROM     makets m, deportprocedures dp, points p
     WHERE    dp.nprocedure = m.nprocedure AND m.nmaket NOT IN(SELECT NVL(util_pg.allnumber_f(util_pg.get_param(init_str, 5, ';')), 0)
                                                               FROM   channels
                                                               WHERE  util_pg.is_uppd2(protocol_id) = 1) AND dp.ntype = 0 AND p.mid = m.nmaket
              AND p.PARENT = DECODE(an_parent, 0, 4, an_parent) AND NOT EXISTS(SELECT 1
                                                                               FROM   deportation
                                                                               WHERE  nmaket = m.nmaket)
     UNION ALL
     SELECT   1 havechild, p.mid nmaket, 0 objtype, 1 ismaket, p.NAME vname, p.tag nblock, '' verror, p.PARENT nparent, '' nextcreated, 0 nperiod
     FROM     points p
     WHERE    p.PARENT = DECODE(an_parent, 0, 4, an_parent) AND p.ptype = 1 AND EXISTS(SELECT *
                                                                                       FROM   points
                                                                                       WHERE  PARENT = p.mid) AND NOT EXISTS(SELECT *
                                                                                                                             FROM   makets
                                                                                                                             WHERE  nmaket = p.mid)
     UNION ALL
     SELECT   0 havechild, p.mid nmaket, 0 objtype, 1 ismaket, p.NAME vname, p.tag nblock, '' verror, p.PARENT nparent, '' nextcreated, 0 nperiod
     FROM     points p
     WHERE    p.PARENT = DECODE(an_parent, 0, 4, an_parent) AND p.ptype = 1 AND NOT EXISTS(SELECT *
                                                                                           FROM   points
                                                                                           WHERE  PARENT = p.mid) AND NOT EXISTS(SELECT *
                                                                                                                                 FROM   makets
                                                                                                                                 WHERE  nmaket = p.mid)
     ORDER BY objtype, havechild DESC, vname;
   END IF;
  ELSE                                                                                                                                            -- дерево УППД
   IF an_parent = 0 THEN                                                                                                              -- папки-родители каналов
    OPEN acur_t FOR
     SELECT   1 havechild, p.mid nmaket, 0 objtype, 0 ismaket, p.NAME vname, 0 nblock, '' verror, 0 nparent, '' nextcreated, 1 nperiod
     FROM     points p
     WHERE    mid IN(SELECT PARENT
                     FROM   points p, channels c
                     WHERE  p.mid = c.cid(+) AND NVL(c.nkind, 0) <> 1 AND util_pg.is_uppd2(c.protocol_id) = 1)
     ORDER BY vname;
   ELSE                                                                                                                                           -- сами каналы
    OPEN acur_t FOR
     SELECT   0 havechild, c.cid nmaket, 2 objtype, 0 ismaket, c.vname, channels_pg.is_block(c.cid, c.blocking, c.nkind) nblock, '' verror, 1 nparent, '' nextcreated,
              1 nperiod
     FROM     channels c
     WHERE    c.cid IN(SELECT mid
                       FROM   points
                       WHERE  PARENT = an_parent) AND util_pg.is_uppd2(protocol_id) = 1
     ORDER BY vname;
   END IF;
  END IF;
 END;

