 PROCEDURE readnodeinfo_p(
 an_objid NUMBER, an_objtype NUMBER, an_tbstate0 NUMBER, an_tbstate1 NUMBER, an_tbstate2 NUMBER, an_orderstr NUMBER, av_dfrom VARCHAR2, av_dtill VARCHAR2,
 an_ismaket NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_swhere           VARCHAR2(1000) DEFAULT ' ';
  lv_orderstr         VARCHAR2(100) DEFAULT ' ';
  lv_sql              VARCHAR2(10000);
 BEGIN
  IF an_ismaket = 1 THEN
   IF an_objid IS NOT NULL THEN
    IF an_objtype = 0 THEN
     SELECT    ' and d.nmaket in (select mid from points 
                START WITH mid = '
            || DECODE(an_objid, 0, 4, an_objid)
            || ' CONNECT BY parent = PRIOR mid) '
     INTO   lv_swhere
     FROM   DUAL;
    ELSIF an_objtype = 1 THEN
     lv_swhere := ' and d.nmaket = ' || an_objid;
    ELSIF an_objtype = 2 THEN
     lv_swhere := ' and df.ndeportation = ' || an_objid;
    END IF;
   END IF;
  ELSE
   IF an_objtype IN(0, 1) THEN
    SELECT    ' and c.cid in (select mid from points 
                START WITH mid = '
           || DECODE(NVL(an_objid, 0), 0, 1, NVL(an_objid, 0))
           || ' CONNECT BY parent = PRIOR mid) '
    INTO   lv_swhere
    FROM   DUAL;
   ELSIF an_objtype = 2 THEN
    lv_swhere := ' and c.cid = ' || an_objid;
   END IF;
  END IF;

  IF an_tbstate0 + an_tbstate1 + an_tbstate2 <> 3 THEN
   lv_swhere := lv_swhere || ' and df.nstate in (-1 ';

   IF (an_tbstate0 = 1) THEN
    lv_swhere := lv_swhere || ',0';
   ELSIF(an_tbstate1 = 1) THEN
    lv_swhere := lv_swhere || ',1';
   ELSIF(an_tbstate2 = 1) THEN
    lv_swhere := lv_swhere || ',2';
   END IF;

   lv_swhere := lv_swhere || ') ';
  END IF;

  IF an_orderstr <> 0 THEN
   IF an_orderstr < 0 THEN
    lv_orderstr := ABS(an_orderstr) || ' desc';
   ELSE
    lv_orderstr := an_orderstr;
   END IF;
  ELSE
   lv_orderstr := '2 desc,3,5 desc';
  END IF;

  IF (an_ismaket = 1) THEN
   lv_sql :=
       ' SELECT df.nstate,df.ddate period, m.vname Maket,
            df.ddate+file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift/1440 MustBeCreated,
            df.denter Created,d.vname Channel, df.dsend,
            round((df.dsend-(df.ddate+file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift/1440))*1440) nDelay,
            decode(file_pg.is_fullmaket(df.ndeportation,df.ddate), 1 , ''Да'', 0, ''Нет'') isfull,
            nvl(u.NAME,''Система'') sender , df.verror,
            d.nmaket, dp.nperiod, 0 noperation,df.ndeportation
            FROM deportfiles df, deportation d, makets m,users u,deportprocedures dp
            WHERE df.ndeportation = d.ndeportation(+)
            AND d.nmaket = m.nmaket(+) AND df.ddate>=to_date('''
    || av_dfrom
    || ''',''dd.mm.yyyy hh24:mi:ss'')
             AND df.ddate<=to_date('''
    || av_dtill
    || ''',''dd.mm.yyyy hh24:mi:ss'')
             AND df.USER_ID=u.USER_ID(+) AND m.nprocedure = dp.nprocedure(+)
             AND d.nmaket NOT IN (SELECT
                    NVL(util_pg.allnumber_f (util_pg.get_param (init_str, 5, '';'')),0) FROM channels WHERE
                    util_pg.is_uppd2(protocol_id)=1)';
  ELSE
   lv_sql :=
       'select df.nstate, df.ddate  period, c.vname Maket,
             df.ddate+nvl(to_char(c.dstart,''sssss'')/86400,0)+1  MustBeCreated,
             df.denter Created, c.vname Channel,df.dsend,
             round((df.dsend-(df.ddate+nvl(to_char(c.dstart,''sssss'')/86400,0)))*86400) nDelay,
             decode(df.nnotfull,0 , ''Да'', 1, ''Нет'') isfull,
             nvl(s.NAME,''Система'') sender,df.verror,
             c.cid nmaket,
             NULL nperiod,
             df.noperation,
             0 ndeportation
             FROM channels c , uppdstat df,users s
             WHERE c.cid=df.cid
             AND df.ddate>=to_date('''
    || av_dfrom
    || ''',''dd.mm.yyyy hh24:mi:ss'')
            AND df.ddate<=to_date('''
    || av_dtill
    || ''',''dd.mm.yyyy hh24:mi:ss'')
            AND df.user_id= s.user_id(+)
            AND util_pg.is_uppd2(c.PROTOCOL_ID)=1 ';
  END IF;

  lv_sql := lv_sql || lv_swhere || 'order by ' || lv_orderstr;

  OPEN acur_t FOR lv_sql;
 END;

