 PROCEDURE proc_info_maketarm(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
 an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_object           NUMBER;
  ln_maket            NUMBER;
 BEGIN
  an_cnfixcol := 3;
  an_cntitle := 1;

  SELECT NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(init_str), 5))), 0), NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(MAX(init_str), 2))), 0)
  INTO   ln_maket, ln_object
  FROM   channels c
  WHERE  c.cid = (SELECT MAX(u.cid)
                  FROM   uppdstat u
                  WHERE  u.noperation = an_id);

  OPEN col_t FOR
   SELECT   -4 ID, 'Наименование' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_btnface datacl,
            uniinterior_pg.cn_left dataal, 1 nlock, 200 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   -3 ID, 'Канал' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_btnface datacl,
            uniinterior_pg.cn_right dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   -2 ID, 'Объект' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_btnface datacl,
            uniinterior_pg.cn_right dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   -1 ID, 'Сумма ' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_yellow datacl,
            uniinterior_pg.cn_center dataal, 0 nlock, 100 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   tt.dt ID, LPAD(tt.dt, 2, '0') || ':00' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_white datacl,
            uniinterior_pg.cn_center dataal, 0 nlock, 70 nwidth, '' vmasks
   FROM     (SELECT ROWNUM dt
             FROM   dict
             WHERE  ROWNUM <= DECODE(util_pg.getparamvalue_f(44), 1, 25, decode(24 - util_pg.is_dayswitch(ad_from),23,24,24 - util_pg.is_dayswitch(ad_from)))) tt
   ORDER BY 1;

  OPEN row_t FOR
   SELECT   m.ngroup ID, m.vname title1, NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(m.vcode, 1))), 0) title2,
            NVL(util_pg.allnumber_f(TRIM(util_pg.get_param(m.vcode, 2))), ln_object) title3, uniinterior_pg.cn_white datacl, uniinterior_pg.cn_right dataal,
            0 nlock, '' vmasks, 0 srt
   FROM     maketgroups m
   WHERE    m.nmaket = ln_maket
   ORDER BY 2, 1;
 END;

--------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_value_maketarm(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  ln_maket            NUMBER;
  temp                NUMBER;
  ln_count            NUMBER;
  k                   NUMBER;
  ln_sum              NUMBER;
 BEGIN
  data_t.DELETE;

  IF util_pg.getparamvalue_f(44) = 1 THEN
   ln_count := 25;
  ELSE
   ln_count := 24 - util_pg.is_dayswitch(ad_from);
	  IF ln_count=23 THEN
 	 	ln_count:=24;
  	END IF;
  END IF;

  SELECT NVL(util_pg.allnumber_f(util_pg.get_param(MAX(init_str), 5, ';')), 0)
  INTO   ln_maket
  FROM   channels c
  WHERE  c.cid = (SELECT MAX(u.cid)
                  FROM   uppdstat u
                  WHERE  u.noperation = an_id);

  k := 0;

  FOR lc IN (SELECT   m.ngroup, m.vname
             FROM     maketgroups m
             WHERE    m.nmaket = ln_maket
             ORDER BY 2, 1) LOOP
   temp := data_t.COUNT;

   --  ln_sum:=0;
   FOR i IN 1 ..(ln_count + 1) LOOP
    data_t(temp + i) := NULL;
   END LOOP;

   FOR lc1 IN (SELECT   a.noperation, a.ngroup, a.norder, a.nvalue
               FROM     uppddata a
               WHERE    a.ngroup = lc.ngroup AND a.noperation = an_id AND norder <= ln_count
               ORDER BY a.norder) LOOP
    --  ln_sum:=ln_sum+lc1.nvalue;
    data_t((lc1.norder + 1) + (ln_count + 1) * k) := lc1.nvalue;
   END LOOP;

   -- data_t(0+(ln_count+1)*k):=ln_sum;
   k := k + 1;
  END LOOP;
 END;

---------------------------------------------------------------------------------------------------------------------
 FUNCTION f_value_maketarm(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_col NUMBER, an_row NUMBER, av_title OUT VARCHAR2, av_xtitle OUT VARCHAR2,
 av_ytitle OUT VARCHAR2, x_t OUT common_pg.tt_number, y_t OUT common_pg.tt_number
 )
  RETURN NUMBER IS
  ln_count            NUMBER:=24;
 BEGIN
  IF util_pg.getparamvalue_f(44) = 1 THEN
   ln_count := 25;
  ELSE
   NULL;
   ln_count := 24 - util_pg.is_dayswitch(ad_from);
	  IF ln_count=23 THEN
 	 	ln_count:=24;
  	END IF;
  END IF;

  SELECT m.vname
  INTO   av_title
  FROM   maketgroups m
  WHERE  m.ngroup = an_row;

  av_xtitle := 'Час.';
  av_ytitle := 'тыс. КВтч.';

  FOR i IN 1 .. ln_count LOOP
   x_t(i) := i;
   y_t(i) := NULL;
  END LOOP;

  FOR lc IN (SELECT   a.nvalue, a.norder
             FROM     uppddata a
             WHERE    a.ngroup = an_row AND a.noperation = an_id AND a.norder <> 0 and a.norder<=ln_count
             ORDER BY a.norder) LOOP
   y_t(lc.norder) := lc.nvalue;
  END LOOP;

  RETURN y_t.COUNT;
 END;

