 PROCEDURE setstatusimport_p(an_operation NUMBER, ad_date DATE, an_state NUMBER, av_error VARCHAR2 DEFAULT NULL);

------------------------------------------------------------------------------------------------------------------------
---                      Implementation
------------------------------------------------------------------------------------------------------------------------
--Возвращает состояние макета (загружаемые rmakets.nstate)
 FUNCTION getstatemaket_r(an_state NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  IF an_state = 0 THEN
   RETURN 'Не разбирался и требует загрузки';
  ELSIF an_state = 1 THEN
   RETURN 'Ошибка идентификации макета';
  ELSIF an_state = 2 THEN
   RETURN 'Ошибка разбора макета';
  ELSIF an_state = 3 THEN
   RETURN 'Макет разобран и требует загрузки';
  ELSIF an_state = 4 THEN
   RETURN 'Ошибка верификации макета';
  ELSIF an_state = 5 THEN
   RETURN 'Макет верифицирован и требует загрузки';
  ELSIF an_state = 6 THEN
   RETURN 'Ошибка загрузки макета';
  ELSIF an_state = 7 THEN
   RETURN 'Макет загружен';
  END IF;

  RETURN 'Состояние не определено';
 END;

--------------------------------------------------------------------------------
    --Возвращает тип макета (загружаемые rmakets.ntype)
 FUNCTION gettypemaket_r(an_type NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  IF an_type = 1 THEN
   RETURN '30817';
  ELSIF an_type = 2 THEN
   RETURN '30917';
  ELSIF an_type = 3 THEN
   RETURN '30818';
  ELSIF an_type = 4 THEN
   RETURN '10015';
  ELSIF an_type = 5 THEN
   RETURN 'Формат XARTEP (ГН)';
  ELSIF an_type = 6 THEN
   RETURN '30816';
  ELSIF an_type = 7 THEN
   RETURN '30818';
  ELSIF an_type = 9 THEN
   RETURN '30900';
  ELSIF an_type = 10 THEN
   RETURN 'elvin';
  ELSIF an_type = 11 THEN
   RETURN 'zmd';
  ELSIF an_type = 12 THEN
   RETURN 'Smart_F';
  ELSIF an_type = 13 THEN
   RETURN 'Smart_H';
  ELSIF an_type = 14 THEN
   RETURN 'argo';
  ELSIF an_type = 15 THEN
   RETURN 'elvin';
  ELSIF an_type = 16 THEN
   RETURN 'zmd';
  ELSIF an_type = 17 THEN
   RETURN '30902';
  ELSIF an_type = 21 THEN
   RETURN '1010';
  ELSIF an_type = 26 THEN
   RETURN 'донецкая ЭС';
  ELSIF an_type = 27 THEN
   RETURN 'северная ЭС';
  ELSIF an_type = 28 THEN
   RETURN '817';
  ELSIF an_type = 29 THEN
   RETURN '30817_817';
  ELSIF an_type = 30 THEN
   RETURN 'CIM/RDF';
  ELSIF an_type = 31 THEN
   RETURN 'Молдова XLS';
  ELSIF an_type = 32 THEN
   RETURN '10014';
  END IF;

  RETURN NULL;
 END;

------------------------------------------------------------------------------
 PROCEDURE setstatusimport_p(an_operation NUMBER, ad_date DATE, an_state NUMBER, av_error VARCHAR2) IS
 BEGIN
  UPDATE rmakets
  SET verror = av_error,
      ddate = ad_date,
      nstate = an_state,
      dload = DECODE(an_state, 7, SYSDATE, NULL),
      user_id = common_pg.userid_f
  WHERE  noperation = an_operation;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'setstatusimport_p: Ошибка обновления статуса. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

-------------------------------------------------------------------------------------------------
   -- Выполнить разбор и верификацию макета из файла первичных данных
 PROCEDURE reload_maket(an_operation NUMBER) IS
 BEGIN
  file_pg.immediateimport_p(an_operation, 0, 5);
 END;

------------------------------------------------------------------------------
 -- Выполнить верификацию макета
 PROCEDURE verify_maket(an_operation NUMBER) IS
 BEGIN
  file_pg.immediateimport_p(an_operation, 3, 5);
 END;

------------------------------------------------------------------------------
    -- Проверяет загружен ли макет
 FUNCTION is_loaded(an_operation NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_ret
  FROM   rmakets
  WHERE  noperation = an_operation AND nstate >= 7;

  RETURN NVL(ln_ret, 0);
 END;

------------------------------------------------------------------------------
  -- Выполнить загрузку макета
 PROCEDURE load_maket(an_operation NUMBER) IS
 BEGIN
  file_pg.immediateimport_p(an_operation, 5, 7);
 END;

-------------------------------------------------------------------------------------------
-- Удаляет макет
 PROCEDURE delete_maket(an_operation NUMBER) IS
  ln_state            NUMBER;
 BEGIN
  SELECT MAX(nstate)
  INTO   ln_state
  FROM   rmakets
  WHERE  noperation = an_operation;

  IF ln_state >= 7 THEN
   raise_application_error(-20001, 'MAKETRECIEVE_PG.delete_maket: Данный макет уже обработан и загружен. Удаление загруженных макетов запрещено.');
  END IF;

  DELETE FROM rmakets
  WHERE       noperation = an_operation;

  COMMIT;
 END;

