--чтение дерева каналов
 PROCEDURE readtreenode_p(an_objid NUMBER, maket_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_objid IS NULL) THEN
   OPEN maket_t FOR
    SELECT   1 havechild, p.mid ID, DECODE(NVL(c.cid, 0), 0, 0, 1) ntype, c.blocking nblock, ' ' verror, NVL(c.vname, NVL(p.NAME, ' ')) vname,
             NVL(c.vname, NVL(p.NAME, ' ')) pinfo
    FROM     points p, channels c
    WHERE    p.PARENT = 1 AND p.mid = c.cid(+) AND NVL(c.protocol_id, 37) IN(37, 113)
             AND EXISTS(SELECT *
                        FROM   channels
                        WHERE  cid IN(SELECT     mid
                                      FROM       points
                                      CONNECT BY PRIOR mid = PARENT
                                      START WITH PARENT = p.mid) AND NVL(protocol_id, 37) IN(37, 113))
    UNION ALL
    SELECT   0 havechild, p.mid, DECODE(NVL(c.cid, 0), 0, 0, 1) ntype, c.blocking, ' ' verror, NVL(c.vname, NVL(p.NAME, ' ')) NAME,
             NVL(c.vname, NVL(p.NAME, ' ')) pinfo
    FROM     points p, channels c
    WHERE    p.PARENT = 1 AND p.mid = c.cid(+) AND NVL(c.protocol_id, 37) IN(37, 113)
             AND NOT EXISTS(SELECT *
                            FROM   channels
                            WHERE  cid IN(SELECT     mid
                                          FROM       points
                                          CONNECT BY PRIOR mid = PARENT
                                          START WITH PARENT = p.mid) AND NVL(protocol_id, 37) IN(37, 113))
    ORDER BY 3, 6;
  ELSE
   OPEN maket_t FOR
    SELECT   1 havechild, p.mid ID, DECODE(NVL(c.cid, 0), 0, 0, 1) ntype, c.blocking nblock, ' ' verror, NVL(c.vname, NVL(p.NAME, ' ')) vname,
             NVL(c.vname, NVL(p.NAME, ' ')) pinfo
    FROM     points p, channels c
    WHERE    p.PARENT = an_objid AND p.mid = c.cid(+) AND NVL(c.protocol_id, 37) IN(37, 113)
             AND EXISTS(SELECT *
                        FROM   channels
                        WHERE  cid IN(SELECT     mid
                                      FROM       points
                                      CONNECT BY PRIOR mid = PARENT
                                      START WITH PARENT = p.mid) AND NVL(protocol_id, 37) IN(37, 113))
    UNION ALL
    SELECT   0 havechild, p.mid, DECODE(NVL(c.cid, 0), 0, 0, 1) ntype, c.blocking, ' ' verror, NVL(c.vname, NVL(p.NAME, ' ')) NAME,
             NVL(c.vname, NVL(p.NAME, ' ')) pinfo
    FROM     points p, channels c
    WHERE    p.PARENT = an_objid AND p.mid = c.cid(+) AND NVL(c.protocol_id, 37) IN(37, 113)
             AND NOT EXISTS(SELECT *
                            FROM   channels
                            WHERE  cid IN(SELECT     mid
                                          FROM       points
                                          CONNECT BY PRIOR mid = PARENT
                                          START WITH PARENT = p.mid) AND NVL(protocol_id, 37) IN(37, 113))
    ORDER BY 3, 6;
  END IF;
 END;

