 PROCEDURE readtreenodeinfo_p(
 an_objtype NUMBER, an_objid NUMBER, an_filter IN common_pg.tt_number, av_orderstr VARCHAR2, ad_dfrom VARCHAR2, ad_dtill VARCHAR2, maket_t OUT common_pg.tcur
 ) IS
  lv_sql              VARCHAR2(4000);
  lv_swhere           VARCHAR2(400);
  lv_s                VARCHAR(400);
  ln_objid            NUMBER;
 BEGIN
  IF an_objid IS NULL THEN
   ln_objid := 1;
  ELSE
   ln_objid := an_objid;
  END IF;

  lv_sql :=
      'SELECT a.nstate,c.VNAME channel, a.dcreate, a.ddate,  a.dload,
    maketrecieve_pg.getstatemaket_r(a.nstate) vstate,
    maketrecieve_pg.gettypemaket_r(a.NTYPE) ntypem,
    a.noperation, 
    decode(a.user_id,null,''Система'', nvl(util_pg.username_f(a.user_id),''Система'')) recipient,
           a.verror,
           a.user_id,
           a.dfile, 
           a.ntype,
           a.user_id,      
           To_char(a.dcreate,''dd.mm.yyyy  hh24:mi:ss'') c_dcreate,
           To_char(a.ddate,''dd.mm.yyyy '') c_ddate,
           To_char(a.dload,''dd.mm.yyyy  hh24:mi:ss'')c_dload, a.cid, a.vfilename
           FROM rmakets a,channels c 
           WHERE a.dcreate >=to_date('''
   || ad_dfrom
   || ''',''dd.mm.yyyy hh24:mi:ss'')
            and a.dcreate<=to_date('''
   || ad_dtill
   || ''',''dd.mm.yyyy hh24:mi:ss'')
            and a.cid=c.cid';

  IF an_objtype = 1 THEN
   lv_swhere := ' and a.cid=' || ln_objid;
  ELSE
   lv_swhere := ' and a.cid IN (select mid from points connect by prior mid=parent start with parent=' || ln_objid || ' )';
  END IF;

  lv_s := ' and nvl(a.nstate,0) in (-1 ';

  FOR i IN 1 .. an_filter.COUNT LOOP
   IF an_filter(i) = 1 THEN
    lv_s := '' || lv_s || ',0,3,5 ';
   ELSIF an_filter(i) = 2 THEN
    lv_s := '' || lv_s || ',7 ';
   ELSIF an_filter(i) = 3 THEN
    lv_s := '' || lv_s || ',1,2,4,6 ';
   END IF;
  END LOOP;

  lv_sql := lv_sql || lv_swhere || lv_s || ' )' || av_orderstr;

  OPEN maket_t FOR lv_sql;
 END;

