-------------------------------------------------------------------------------------------------------
 FUNCTION getmakettype(an_operation NUMBER)
  RETURN NUMBER IS
  ln_type             NUMBER;
 BEGIN
  SELECT MAX(r.ntype)
  INTO   ln_type
  FROM   rmakets r
  WHERE  r.noperation = an_operation;

  RETURN ln_type;
 END;

---------------------------------------------------------------------------------------------------------
 FUNCTION getmaketdate_f(an_operation NUMBER)
  RETURN DATE IS
  ld_date             DATE;
 BEGIN
  SELECT MAX(ddate)
  INTO   ld_date
  FROM   rmakets
  WHERE  noperation = an_operation;

  RETURN ld_date;
 END;

------------------------------------------------------------------------------
 PROCEDURE getmaketinfo(
 an_operation NUMBER, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER, an_cnfooter OUT NUMBER, col_t OUT common_pg.tcur, row_t OUT common_pg.tcur
 ) IS
  ln_type             NUMBER := getmakettype(an_operation);
 BEGIN
  IF ln_type = comsrvfile_pg.cn_30817 THEN
   getmaketinfo_30817(an_operation, an_cnfixcol, an_cntitle, an_cnfooter, col_t, row_t);
  ELSIF ln_type = comsrvfile_pg.cn_30917 THEN
   getmaketinfo_30917(an_operation, an_cnfixcol, an_cntitle, an_cnfooter, col_t, row_t);
  ELSIF ln_type = comsrvfile_pg.cn_cimrdf THEN
   getmaketinfo_cimrdf(an_operation, an_cnfixcol, an_cntitle, an_cnfooter, col_t, row_t);
  ELSIF ln_type = comsrvfile_pg.cn_30818 THEN
   getmaketinfo_30818(an_operation, an_cnfixcol, an_cntitle, an_cnfooter, col_t, row_t);
  ELSIF ln_type = comsrvfile_pg.cn_30900 THEN
   getmaketinfo_30900(an_operation, an_cnfixcol, an_cntitle, an_cnfooter, col_t, row_t);
  ELSE
   an_cnfixcol := 0;
   an_cntitle := 1;
   an_cnfooter := 0;

   OPEN col_t FOR
    SELECT -1 ID, 'Назва показникa' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_btnface datacl,
           uniinterior_pg.cn_left dataal, 1 nlock, 150 nwidth, '' vmasks
    FROM   DUAL;

   OPEN row_t FOR
    SELECT 0 ID, '' title1, uniinterior_pg.cn_white datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  1 = 2;
  END IF;
 END;

------------------------------------------------------------------------------
 PROCEDURE getmaketinfo_30817(
 an_operation NUMBER, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER, an_cnfooter OUT NUMBER, col_t OUT common_pg.tcur, row_t OUT common_pg.tcur
 ) IS
  cn_step    CONSTANT NUMBER := 1;
  cn_all              NUMBER := cn_24 * cn_step;
  ld_date             DATE := TRUNC(getmaketdate_f(an_operation));
  ln_ver              NUMBER;
  lv_error            VARCHAR2(2000);
  ln_endstate         NUMBER DEFAULT 7;
  ln_switch           NUMBER;
 BEGIN
  IF ld_date IS NOT NULL THEN
   comsrvfile_pg.universal_p(an_operation, 0, ln_endstate, lv_error, ld_date, 0, 1);
  END IF;

  ln_switch := util_pg.is_dayswitch(ld_date);
  an_cnfixcol := 2;
  an_cntitle := 1;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT   -3 ID, 'Назва показника' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_left titleal, uniinterior_pg.cn_btnface datacl,
            uniinterior_pg.cn_left dataal, 1 nlock, 150 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   -2 ID, 'КОД' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_center titleal, uniinterior_pg.cn_btnface datacl,
            uniinterior_pg.cn_center dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   -1 ID, 'СУМА' title1, uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_center titleal, uniinterior_pg.cn_sumtec datacl,
            uniinterior_pg.cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM     DUAL
   UNION ALL
   SELECT   tt.rm ID,
            
            -- DECODE(tt.rm, cn_all + 1,(util_pg.switch_f + 1) || '''', tt.rm) || ' год' title1,
            REPLACE(DECODE(
              SIGN(tt.rm - cn_all),
              1, TO_CHAR(ld_date + (cn_step * util_pg.switch_f + 1 + MOD(tt.rm - 1, cn_step)) / cn_all, 'hh24') || cv_add,
              TO_CHAR(ld_date + tt.rm / cn_all, 'hh24')
             ),
             '00', '24') title1,
            uniinterior_pg.cn_btnface titlecl, uniinterior_pg.cn_center titleal, uniinterior_pg.cn_white datacl, uniinterior_pg.cn_right dataal, 0 nlock,
            45 nwidth, '' vmasks
   FROM     (SELECT     ROWNUM rm
             FROM       DUAL
             CONNECT BY LEVEL <= cn_all - cn_step * DECODE(ln_switch, -1, -1, 0)
             MINUS
             SELECT     cn_step * util_pg.switch_f + ROWNUM rm
             FROM       DUAL
             WHERE      ln_switch = 1
             CONNECT BY LEVEL <= cn_step) tt
   ORDER BY ID;

  OPEN row_t FOR
   SELECT DISTINCT p.nrow ID, f.NAME title1, p.vcode title2, uniinterior_pg.cn_white datacl, 0 nlock, '' vmasks
   FROM            (SELECT   nrow, MAX(vcode) vcode, MAX(mid) mid
                    FROM     parsingmakets
                    WHERE    noperation = an_operation AND nrow >= 1
                    GROUP BY nrow) p,
                   points f
   WHERE           p.mid = f.mid(+)
   ORDER BY        p.nrow;
 END;

