 PROCEDURE getmaketvalue(an_operation NUMBER, at_ret OUT common_pg.tt_number) IS
  ln_row              NUMBER;
  ln_col              NUMBER;
 BEGIN
  SELECT MAX(nrow) rw, MAX(ncol) ncl
  INTO   ln_row, ln_col
  FROM   parsingmakets
  WHERE  noperation = an_operation;

  FOR i IN 1 ..(ln_row * ln_col) LOOP
   at_ret(i) := NULL;
  END LOOP;

  FOR lv IN (SELECT   MAX(nvalue) nvalue, nrow, ncol
             FROM     parsingmakets
             WHERE    noperation = an_operation AND(nrow BETWEEN 1 AND ln_row) AND(ncol BETWEEN 1 AND ln_col)
             GROUP BY nrow, ncol
             ORDER BY nrow, ncol) LOOP
   at_ret((lv.nrow - 1) * ln_col + lv.ncol) := lv.nvalue;
  END LOOP;
 END;

