   --Возвращает ид макета по группе
 FUNCTION getmaketid_by_group(an_group NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT MAX(nmaket)
  INTO   ln_ret
  FROM   maketgroups
  WHERE  ngroup = an_group;

  RETURN ln_ret;
 END;

