-- Старая  Процедура вставки макета
 PROCEDURE ins_m(
 an_nprocedure NUMBER,                                                                                                                            --ид процедуры
                      av_vname VARCHAR2,                                                                                                            --Имя макета
                                        av_vnote VARCHAR2,                                                                                          --Коментарий
                                                          an_nblock NUMBER,                                                                         --Блокировка
                                                                           an_ncycle NUMBER,                                    --Выполнять невыполненые вовремя
                                                                                            an_shift NUMBER,                     --Сдвиг старта формирования мин
                                                                                                            av_param VARCHAR2,                        --Параметр
 an_nmaket OUT NUMBER                                                                                                                                --Ид макета
 ) IS
 BEGIN
  ins_m(an_nprocedure, av_vname, av_vnote, an_nblock, an_ncycle, an_shift, av_param, 4, an_nmaket);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки макета
 PROCEDURE ins_m(
 an_nprocedure NUMBER,                                                                                                                            --ид процедуры
                      av_vname VARCHAR2,                                                                                                            --Имя макета
                                        av_vnote VARCHAR2,                                                                                          --Коментарий
                                                          an_nblock NUMBER,                                                                         --Блокировка
                                                                           an_ncycle NUMBER,                                    --Выполнять невыполненые вовремя
                                                                                            an_shift NUMBER,                     --Сдвиг старта формирования мин
                                                                                                            av_param VARCHAR2,                        --Параметр
                                                                                                                              an_parent NUMBER,   -- Ид родителя
 an_nmaket OUT NUMBER                                                                                                                                --Ид макета
 ) IS
  ln_mid              NUMBER;
  lv_procname         VARCHAR2(2000);
  ln_parent           NUMBER := an_parent;
 BEGIN
  SAVEPOINT makets_ins;

  IF NVL(ln_parent, 0) = 0 THEN                                                                                             --Устранение ошибок старых клиентов
   ln_parent := 4;
  END IF;

  adminadd_pg.check_right(ln_mid, ln_parent, 1, 2);

  SELECT points_seq.NEXTVAL
  INTO   ln_mid
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, cod, ind, NAME, short_name, implement_date)
  VALUES      (ln_mid, ln_parent, 0, 2, av_vname, '', SYSDATE);

  INSERT INTO makets
              (nmaket, nprocedure, vname, vnote, nblock, ncycle, nshift, vparam)
  VALUES      (ln_mid, an_nprocedure, av_vname, av_vnote, an_nblock, an_ncycle, an_shift, av_param);

  an_nmaket := ln_mid;

  SELECT MAX(vname)
  INTO   lv_procname
  FROM   deportprocedures
  WHERE  nprocedure = an_nprocedure;

  admin_pg.fiscal_p(cn_taskid_process, 1, 'Добавлен фоновый процесс (макет) ' || av_vname || ' Для запуска процедуры ' || lv_procname);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT makets_ins;
   raise_application_error(-20001, 'makets_pg.ins_m: Ошибка вставки макета "' || av_vname || '".' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки папки
 PROCEDURE ins_f(av_vname VARCHAR2,                                                                                                                  --Имя папки
                                   an_nblock NUMBER,                                                                                          --Блокировка папки
                                                    an_parent NUMBER,                                                                             -- Ид родителя
                                                                     an_mid OUT NUMBER                                                                --Ид папки
                                                                                      ) IS
  ln_mid              NUMBER;
  ln_parent           NUMBER := an_parent;
 BEGIN
  SAVEPOINT folder_ins;

  IF NVL(ln_parent, 0) = 0 THEN                                                                                             --Устранение ошибок старых клиентов
   ln_parent := 4;
  END IF;

  adminadd_pg.check_right(ln_mid, ln_parent, 1, 2);

  SELECT points_seq.NEXTVAL
  INTO   ln_mid
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, cod, ind, NAME, short_name, implement_date, ptype, tag)
  VALUES      (ln_mid, ln_parent, 0, 2, av_vname, '', SYSDATE, 1, an_nblock);

  -- PTYPE: 1-папки макетов,2-фон.процессов; TAG=1-блокировка
  an_mid := ln_mid;
  admin_pg.fiscal_p(cn_taskid_makets, 1, 'Добавлена папка в дереве макетов ' || av_vname);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT folder_ins;
   raise_application_error(-20001, 'makets_pg.ins_f: Ошибка вставки папки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки группы
 PROCEDURE ins_g(
 an_nmaket NUMBER,                                                                                                                                   --Ид макета
                  av_vcode VARCHAR2,                                                                                                                --Код строки
                                    av_vname VARCHAR2,                                                                                             --Имя грруппы
                                                      av_vnote VARCHAR2,                                                                            --Коментарий
                                                                        an_ngroup OUT NUMBER                                                         --Ид группы
 ) IS
  ln_mid              NUMBER;
  lv_maketname        VARCHAR2(2000);
 BEGIN
  adminadd_pg.check_right(an_nmaket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_maketname
  FROM   makets
  WHERE  nmaket = an_nmaket;

  SELECT maketgroups_seq.NEXTVAL
  INTO   ln_mid
  FROM   DUAL;

  an_ngroup := ln_mid;

  INSERT INTO maketgroups
              (ngroup, nmaket, vcode, vname, vnote)
  VALUES      (ln_mid, an_nmaket, av_vcode, av_vname, av_vnote);

  admin_pg.fiscal_p(cn_taskid_makets, 1, 'Добавлена группа в макет ' || lv_maketname || '\' || av_vname);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.ins_g: Ошибка вставки группы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки/обновления агрегатной подгруппы
 PROCEDURE chg_a(an_ngroup NUMBER,                                                                                                        --Ид агрегатной группы
                                  an_nsubgroup NUMBER,                                                                                   --Ид суммируемой группы
                                                      an_nsign NUMBER                                                                         --Знак для расчёта
                                                                     ) IS
  ln_exists           NUMBER;
  lv_gname            VARCHAR2(2000);
  ln_maket            NUMBER := getmaketid_by_group(an_ngroup);
 BEGIN
  adminadd_pg.check_right(ln_maket, NULL, 1, 2);

  SELECT vname
  INTO   lv_gname
  FROM   maketgroups
  WHERE  ngroup = an_ngroup;

  SELECT COUNT(*)
  INTO   ln_exists
  FROM   maketformulas
  WHERE  ngroup = an_ngroup AND nsubgroup = an_nsubgroup;

  IF (ln_exists = 0) THEN
   INSERT INTO maketformulas
               (ngroup, nsubgroup, nsign)
   VALUES      (an_ngroup, an_nsubgroup, an_nsign);

   admin_pg.fiscal_p(cn_taskid_makets, 1, 'Добавлена агрегирующая группа в макет ' || lv_gname);
  ELSE
   UPDATE maketformulas
   SET nsign = an_nsign
   WHERE  ngroup = an_ngroup AND nsubgroup = an_nsubgroup;

   admin_pg.fiscal_p(cn_taskid_makets, 2, 'Изменена агрегатная группа ' || lv_gname);
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.chg_p: Ошибка изменения агрегатной подгруппы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки точки
 PROCEDURE chg_p(an_ngroup NUMBER,                                                                                                                   --Ид группы
                                  an_mid NUMBER,                                                                                                     --Мид точки
                                                an_nkc NUMBER,                                                                           --Коэффициент вхождения
                                                              an_ntype NUMBER                                                                    --Тип измерений
                                                                             ) IS
  ln_exists           NUMBER;
  lv_gname            VARCHAR2(2000);
  lv_mname            VARCHAR2(2000);
  ln_maket            NUMBER := getmaketid_by_group(an_ngroup);
 BEGIN
  adminadd_pg.check_right(ln_maket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = ln_maket;

  SELECT MAX(vname)
  INTO   lv_gname
  FROM   maketgroups
  WHERE  ngroup = an_ngroup;

  SELECT COUNT(*)
  INTO   ln_exists
  FROM   DUAL
  WHERE  EXISTS(SELECT *
                FROM   maketpoints
                WHERE  mid = an_mid AND ngroup = an_ngroup);

  IF (ln_exists = 0) THEN
   INSERT INTO maketpoints
               (ngroup, mid, nkc, ntype)
   VALUES      (an_ngroup, an_mid, an_nkc, an_ntype);
  ELSE
   UPDATE maketpoints
   SET nkc = an_nkc,
       ntype = an_ntype
   WHERE  mid = an_mid AND ngroup = an_ngroup;
  END IF;

  admin_pg.fiscal_p(cn_taskid_makets, 1,
   'В группу макета ' || lv_mname || '\' || lv_gname || ' добавлена точка ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.chg_p: Ошибка изменения точки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
-- Старая Процедура обновления макета
 PROCEDURE upd_m(
 an_nmaket NUMBER,                                                                                                                                   --Ид макета
                  an_nprocedure NUMBER,                                                                                                           --ид процедуры
                                       av_vname VARCHAR2,                                                                                           --Имя макета
                                                         av_vnote VARCHAR2,                                                                         --Коментарий
                                                                           an_nblock NUMBER,                                                        --Блокировка
                                                                                            an_ncycle NUMBER,                   --Выполнять невыполненые вовремя
                                                                                                             an_shift NUMBER,    --Сдвиг старта формирования мин
 av_param VARCHAR2                                                                                                                                    --Параметр
 ) IS
 BEGIN
  upd_m(an_nmaket, an_nprocedure, av_vname, av_vnote, an_nblock, an_ncycle, an_shift, av_param, 4);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления макета
 PROCEDURE upd_m(
 an_nmaket NUMBER,                                                                                                                                   --Ид макета
                  an_nprocedure NUMBER,                                                                                                           --ид процедуры
                                       av_vname VARCHAR2,                                                                                           --Имя макета
                                                         av_vnote VARCHAR2,                                                                         --Коментарий
                                                                           an_nblock NUMBER,                                                        --Блокировка
                                                                                            an_ncycle NUMBER,                   --Выполнять невыполненые вовремя
                                                                                                             an_shift NUMBER,    --Сдвиг старта формирования мин
 av_param VARCHAR2,                                                                                                                                   --Параметр
                   an_parent NUMBER                                                                                                               -- Ид родителя
 ) IS
  CURSOR lc_maket(lc_nid NUMBER) IS
   SELECT nshift, nblock
   FROM   makets
   WHERE  nmaket = lc_nid;

  lv_oldmaketname     VARCHAR2(2000);
  lv_procname         VARCHAR2(2000);
  lv_oldprocname      VARCHAR2(2000);
  lv_comment          VARCHAR2(2000);
  ln_parent           NUMBER := an_parent;
 BEGIN
  SAVEPOINT makets_upd;

  IF NVL(ln_parent, 0) = 0 THEN                                                                                             --Устранение ошибок старых клиентов
   ln_parent := 4;
  END IF;

  adminadd_pg.check_right(an_nmaket, ln_parent, 1, 2);

  SELECT MAX(vname)
  INTO   lv_procname
  FROM   deportprocedures
  WHERE  nprocedure = an_nprocedure;

  SELECT MAX(vname)
  INTO   lv_oldmaketname
  FROM   makets
  WHERE  nmaket = an_nmaket;

  SELECT MAX(vname)
  INTO   lv_oldprocname
  FROM   deportprocedures
  WHERE  nprocedure = (SELECT nprocedure
                       FROM   makets
                       WHERE  nmaket = an_nmaket);

  IF lv_oldmaketname <> av_vname THEN
   lv_oldmaketname := lv_oldmaketname || ' - ' || av_vname;
  END IF;

  lv_oldmaketname := ' Изменены параметры процесса "' || lv_oldmaketname || '".';
  lv_oldmaketname := lv_oldmaketname || ' Вызываемая процедура "' || lv_oldprocname || '".';

  IF lv_oldprocname <> lv_procname THEN
   lv_oldmaketname := lv_oldmaketname || ' - ' || lv_procname;
  END IF;

  lv_oldmaketname := lv_oldmaketname || ' Измененные параметры:';

  FOR i IN lc_maket(an_nmaket) LOOP
   IF i.nshift <> an_shift THEN
    SELECT comments
    INTO   lv_comment
    FROM   user_col_comments
    WHERE  table_name = 'MAKETS' AND column_name = 'NSHIFT';

    lv_oldmaketname := lv_oldmaketname || ' "' || lv_comment || '"';
   END IF;

   IF i.nblock <> an_nblock THEN
    SELECT comments
    INTO   lv_comment
    FROM   user_col_comments
    WHERE  table_name = 'MAKETS' AND column_name = 'NBLOCK';

    lv_oldmaketname := lv_oldmaketname || ' "' || lv_comment || '"';
   END IF;
  END LOOP;

  admin_pg.fiscal_p(cn_taskid_process, 2, lv_oldmaketname);

  UPDATE points
  SET NAME = av_vname,
      PARENT = ln_parent
  WHERE  mid = an_nmaket;

  UPDATE makets
  SET nprocedure = an_nprocedure,
      vname = av_vname,
      vnote = av_vnote,
      nblock = an_nblock,
      ncycle = an_ncycle,
      nshift = an_shift,
      vparam = av_param
  WHERE  nmaket = an_nmaket;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT makets_upd;
   raise_application_error(-20001, 'makets_pg.upd_m: Ошибка обновления макета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления папки
 PROCEDURE upd_f(av_name VARCHAR2,                                                                                                                   --Имя папки
                                  an_block NUMBER,                                                                                            --Блокировка папки
                                                  an_parent NUMBER,                                                                               -- Ид родителя
                                                                   an_mid NUMBER                                                                      --Ид папки
                                                                                ) IS
  ln_mid              NUMBER;
  lv_oldname          VARCHAR2(4000);
  ln_oldblocking      NUMBER;
  lv_message          VARCHAR2(8000);
  ln_oldparmid        NUMBER;
  lv_oldparname       VARCHAR2(1000);
  lv_newparname       VARCHAR2(1000);
 BEGIN
  SAVEPOINT folder_upd;
  adminadd_pg.check_right(an_mid, an_parent, 1, 2);

  SELECT MAX(NAME), MAX(tag), MAX(PARENT)
  INTO   lv_oldname, ln_oldblocking, ln_oldparmid
  FROM   points
  WHERE  mid = an_mid;

  IF lv_oldname <> av_name THEN
   lv_message := lv_message || ' имя: ' || lv_oldname || ' --> ' || av_name || ';';
  END IF;

  IF ln_oldblocking <> an_block THEN
   SELECT lv_message || ' блокировка: на ' || DECODE(an_block, 1, 'заблокировано', 'разблокировано') || ';'
   INTO   lv_message
   FROM   DUAL;
  END IF;

  IF ln_oldparmid <> an_parent THEN
   SELECT MAX(NAME)
   INTO   lv_oldparname
   FROM   points
   WHERE  mid = ln_oldparmid;

   SELECT MAX(NAME)
   INTO   lv_newparname
   FROM   points
   WHERE  mid = DECODE(an_parent, 0, 4, an_parent);

   lv_message := lv_message || ' перемещение: ' || lv_oldparname || ' --> ' || lv_newparname;
  END IF;

  UPDATE points
  SET NAME = av_name,
      tag = an_block,
      PARENT = DECODE(an_parent, 0, 4, an_parent)
  WHERE  mid = an_mid;

  IF lv_message <> '' THEN
   admin_pg.fiscal_p(cn_taskid_makets, 2, 'Изменены параметры папки в дереве макетов - ' || lv_message);
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT folder_upd;
   raise_application_error(-20001, 'makets_pg.upd_f: Ошибка обновления папки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура клонирования макета
 FUNCTION clone_m(an_nmaket NUMBER                                                                                                      --Ид клонируемого макета
                                  )
  RETURN NUMBER IS
  ln_maket            NUMBER;
  ln_group            NUMBER;
  old_gr              common_pg.tt_number;
  new_gr              common_pg.tt_number;
  cnt                 NUMBER := 0;
  cnt_name            NUMBER := 1;
  cnt_makets          NUMBER;
 BEGIN
  SAVEPOINT makets_clone;
  adminadd_pg.check_right(an_nmaket, NULL, 1, 2);

  FOR lc IN (SELECT m.nprocedure, m.vname, m.vnote, m.nblock, m.ncycle, m.nshift, m.vparam, p.PARENT
             FROM   makets m, points p
             WHERE  m.nmaket = an_nmaket AND m.nmaket = p.mid) LOOP
   LOOP
    SELECT COUNT(*)
    INTO   cnt_makets
    FROM   DUAL
    WHERE  EXISTS(SELECT *
                  FROM   makets
                  WHERE  vname = lc.vname || ' (клон' || cnt_name || ')');

    IF cnt_makets = 0 THEN
     makets_pg.ins_m(lc.nprocedure, lc.vname || ' (клон' || cnt_name || ')', lc.vnote, lc.nblock, lc.ncycle, lc.nshift, lc.vparam, lc.PARENT, ln_maket);
     EXIT;
    END IF;

    cnt_name := cnt_name + 1;
   END LOOP;

   FOR group_row IN (SELECT ngroup, vcode, vname, vnote
                     FROM   maketgroups
                     WHERE  nmaket = an_nmaket) LOOP
    makets_pg.ins_g(ln_maket, group_row.vcode, group_row.vname, group_row.vnote, ln_group);
    cnt := cnt + 1;
    old_gr(cnt) := group_row.ngroup;
    new_gr(cnt) := ln_group;

    FOR points_row IN (SELECT mid, nkc, ntype
                       FROM   maketpoints
                       WHERE  ngroup = group_row.ngroup) LOOP
     makets_pg.chg_p(ln_group, points_row.mid, points_row.nkc, points_row.ntype);
    END LOOP;
   END LOOP;

   FOR k IN 1 .. cnt LOOP
    IF (makets_pg.isagregat(old_gr(k)) = 1) THEN
     FOR subgroups_row IN (SELECT nsubgroup, nsign
                           FROM   maketformulas
                           WHERE  ngroup = old_gr(k)) LOOP
      FOR j IN 1 .. cnt LOOP
       IF (subgroups_row.nsubgroup = old_gr(j)) THEN
        makets_pg.chg_a(new_gr(k), new_gr(j), subgroups_row.nsign);
       END IF;
      END LOOP;
     END LOOP;
    END IF;
   END LOOP;
  END LOOP;

  COMMIT;
  RETURN ln_maket;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT makets_clone;
   raise_application_error(-20001, 'makets_pg.clone_m: Ошибка клонирования макета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления группы
 PROCEDURE upd_g(
 an_ngroup NUMBER,                                                                                                                                   --Ид группы
                  an_nmaket NUMBER,                                                                                                                  --Ид макета
                                   av_vcode VARCHAR2,                                                                                               --Код строки
                                                     av_vname VARCHAR2,                                                                            --Имя грруппы
                                                                       av_vnote VARCHAR2                                                            --Коментарий
 ) IS
  lv_gname            VARCHAR2(2000);
  lv_mname            VARCHAR2(2000);
 BEGIN
  adminadd_pg.check_right(an_nmaket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = an_nmaket;

  SELECT MAX(vname)
  INTO   lv_gname
  FROM   maketgroups
  WHERE  ngroup = an_ngroup;

  lv_mname := ' Изменены параметры группы макета ' || lv_mname || '\' || lv_gname;

  IF lv_gname <> av_vname THEN
   lv_mname := lv_mname || ' - ' || av_vname;
  END IF;

  admin_pg.fiscal_p(cn_taskid_makets, 2, lv_mname);

  UPDATE maketgroups
  SET nmaket = an_nmaket,
      vcode = av_vcode,
      vname = av_vname,
      vnote = av_vnote
  WHERE  ngroup = an_ngroup;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.upd_g: Ошибка обновления группы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления макета
 PROCEDURE del_m(an_nmaket NUMBER                                                                                                                    --Ид макета
                                 ) IS
  lv_mname            VARCHAR2(2000);
  lv_oldprocname      VARCHAR2(2000);
 BEGIN
  SAVEPOINT makets_del;
  adminadd_pg.check_right(an_nmaket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_oldprocname
  FROM   deportprocedures
  WHERE  nprocedure = (SELECT nprocedure
                       FROM   makets
                       WHERE  nmaket = an_nmaket);

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = an_nmaket;

  admin_pg.fiscal_p(cn_taskid_process, 3, 'Удален фоновый процесс (макет) ' || lv_mname || ' Для вызова процедуры ' || lv_oldprocname);

  DELETE FROM points
  WHERE       mid = an_nmaket;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT makets_del;
   raise_application_error(-20001, 'makets_pg.del_m: Ошибка удаления макета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления группы
 PROCEDURE del_g(an_ngroup NUMBER                                                                                                                    --Ид группы
                                 ) IS
  lv_gname            VARCHAR2(2000);
  lv_mname            VARCHAR2(2000);
  ln_maket            NUMBER := getmaketid_by_group(an_ngroup);
 BEGIN
  adminadd_pg.check_right(ln_maket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = ln_maket;

  SELECT MAX(vname)
  INTO   lv_gname
  FROM   maketgroups
  WHERE  ngroup = an_ngroup;

  admin_pg.fiscal_p(cn_taskid_makets, 3, 'Удалена группа в макете ' || lv_mname || '\' || lv_gname);

  DELETE FROM maketgroups
  WHERE       ngroup = an_ngroup;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.del_g: Ошибка удаления группы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления точки
 PROCEDURE del_p(an_mid NUMBER,                                                                                                                       --Ид точки
                               an_ngroup NUMBER                                                                                                      --Ид группы
                                               ) IS
  lv_gname            VARCHAR2(2000);
  lv_mname            VARCHAR2(2000);
  ln_maket            NUMBER := getmaketid_by_group(an_ngroup);
 BEGIN
  adminadd_pg.check_right(ln_maket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = ln_maket;

  SELECT MAX(vname)
  INTO   lv_gname
  FROM   maketgroups
  WHERE  ngroup = an_ngroup;

  admin_pg.fiscal_p(cn_taskid_makets, 3,
   'Удалена точка в макете ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || ' С группы ' || lv_mname || '\' || lv_gname);

  DELETE FROM maketpoints
  WHERE       mid = an_mid AND ngroup = an_ngroup;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.del_p: Ошибка удаления точки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления агрегатной подгруппы
 PROCEDURE del_a(an_ngroup NUMBER,                                                                                                                   --Ид группы
                                  an_nsubgroup NUMBER                                                                                             --Ид подгруппы
                                                     ) IS
  lv_gname            VARCHAR2(2000);
  lv_sgname           VARCHAR2(2000);
  lv_mname            VARCHAR2(2000);
  ln_maket            NUMBER := getmaketid_by_group(an_ngroup);
 BEGIN
  adminadd_pg.check_right(ln_maket, NULL, 1, 2);

  SELECT MAX(vname)
  INTO   lv_mname
  FROM   makets
  WHERE  nmaket = ln_maket;

  SELECT MAX(vname)
  INTO   lv_gname
  FROM   maketgroups
  WHERE  ngroup = an_ngroup;

  SELECT MAX(vname)
  INTO   lv_sgname
  FROM   maketgroups
  WHERE  ngroup = an_nsubgroup;

  admin_pg.fiscal_p(cn_taskid_makets, 3, 'Удалена подгруппа в макете ' || lv_mname || '\' || lv_gname || '\' || lv_sgname);

  DELETE FROM maketformulas
  WHERE       ngroup = an_ngroup AND nsubgroup = an_nsubgroup;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.del_g: Ошибка удаления подгруппы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Функция выявления агрегатной ггруппы
 FUNCTION isagregat(an_group NUMBER)
  RETURN NUMBER IS
  an_count            NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   an_count
  FROM   maketformulas
  WHERE  ngroup = an_group;

  IF an_count > 0 THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
   -- Создание группы из groups.gid
    --an_type=1 - делать только прием,an_type=2 - отдача иначе сальдо
 PROCEDURE createfromgroup(an_group NUMBER, an_gid NUMBER, an_type NUMBER) IS
 BEGIN
  SAVEPOINT makets_crg;
  adminadd_pg.check_right(getmaketid_by_group(an_group), NULL, 1, 2);

  DELETE FROM maketpoints
  WHERE       ngroup = an_group;

  INSERT INTO maketpoints
              (ngroup, mid, nkc, ntype)
   SELECT an_group, mid, DECODE(ntype, 2, -nkc, nkc), ntype
   FROM   (SELECT     mid, SUM(DECODE(inverted, 'y', -1, 1)) nkc,
                      DECODE(MAX(DECODE(npartly, 1, 1, 0)) + MAX(DECODE(npartly, 2, 1, 0)), 2, 5, MAX(DECODE(npartly, 1, 1, 2, 2, 5))) ntype
           FROM       GROUPS
           WHERE      mid > 0
           CONNECT BY PRIOR gid = PARENT
           START WITH gid = an_gid
           GROUP BY   mid);

  IF an_type = 1 THEN
   DELETE FROM maketpoints
   WHERE       ngroup = an_group AND nkc < 0 AND ntype IN(1, 2);

   UPDATE maketpoints
   SET ntype = DECODE(SIGN(nkc), 1, 1, 2)
   WHERE  ngroup = an_group AND ntype = 5 AND nkc <> 0;

   UPDATE maketpoints
   SET nkc = 1
   WHERE  ngroup = an_group;
  ELSIF an_type = 2 THEN
   DELETE FROM maketpoints
   WHERE       ngroup = an_group AND nkc > 0 AND ntype IN(1, 2);

   UPDATE maketpoints
   SET ntype = DECODE(SIGN(nkc), 1, 2, 1)
   WHERE  ngroup = an_group AND ntype = 5 AND nkc <> 0;

   UPDATE maketpoints
   SET nkc = 1
   WHERE  ngroup = an_group;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT makets_crg;
   raise_application_error(-20001, 'makets_pg.createfromgroup: Ошибка создания группы. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает период процедуры макета
 FUNCTION getperiodmaket(an_maket NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT MAX(d.nperiod)
  INTO   ln_ret
  FROM   makets m, deportprocedures d
  WHERE  m.nmaket = an_maket AND m.nprocedure = d.nprocedure;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- возвращает ветку дерева для макетов
 PROCEDURE getmakettree(an_id NUMBER, an_type NUMBER, acur_t OUT common_pg.tcur)
                                                                                -- an_type: mtNone=0,mtMaket=1,mtGroup=2,mtPoint=3,mtAgrGroup=4,mtSubGroup=5,mtFolder=6
 IS
  lv_sql              VARCHAR2(8000);
  lv_sqladd           VARCHAR2(8000);
 BEGIN
  IF an_type = 0 OR an_type = 6 THEN                                                                                                        -- макеты с папками
   IF an_type = 0 THEN
    IF adminadd_pg.check_accread(util_pg.cn_makmid) = 1 THEN                                                                         --Права на вершину макетов
     lv_sqladd := 'AND p.parent=' || util_pg.cn_makmid;
    ELSE
     lv_sqladd := 'AND p.mid in (SELECT * FROM TABLE(adminadd_pg.getfirst_accmid(' || util_pg.cn_makmid || ')))';                                     --Вершина
    END IF;
   ELSE
    IF adminadd_pg.check_accread(an_id) = 1 THEN
     lv_sqladd := 'AND p.parent=' || an_id;
    ELSE                                                                                                                                              --Нет Прав
     raise_application_error(-20002, 'В доступе отказано. an_id='||an_id);
    END IF;
   END IF;

   lv_sql :=
       'SELECT p.parent, 1 HaveChild, 1 Type, m.nmaket mid, m.vname, m.vnote, m.nprocedure, m.nblock, m.ncycle, m.nshift, m.vparam, To_char(m.doldcreated,''dd.mm.yyyy hh24:mi:ss'')LastDate, m.verror 
                 FROM makets m, points p
                WHERE m.nmaket=p.mid '
    || lv_sqladd
    || ' AND EXISTS(SELECT * FROM maketgroups WHERE nmaket=m.nmaket) AND EXISTS (SELECT * FROM DEPORTPROCEDURES WHERE nprocedure=m.nprocedure AND ntype=0) 
                UNION ALL 
               SELECT p.parent, 0 HaveChild, 1 TYPE, nmaket, vname, vnote, nprocedure, nblock, ncycle, nshift, vparam, To_char(doldcreated,''dd.mm.yyyy hh24:mi:ss''), verror 
                 FROM makets m, points p 
                WHERE m.nmaket=p.mid '
    || lv_sqladd
    || ' AND NOT EXISTS(SELECT * FROM maketgroups WHERE nmaket=m.nmaket) AND EXISTS (SELECT * FROM DEPORTPROCEDURES WHERE nprocedure=m.nprocedure AND ntype=0)
                UNION ALL 
               SELECT p.parent, 1 havechild, 6 TYPE, p.mid, NAME vname, '''' vnote, NULL nprocedure, p.tag nblock, NULL ncycle, NULL nshift, '''' vparam, NULL, '''' verror
                 FROM points p
                WHERE p.ptype=1 '
    || lv_sqladd
    || ' AND EXISTS (SELECT * FROM points WHERE parent=p.mid) AND NOT EXISTS (SELECT * FROM makets WHERE nmaket=p.mid)
                UNION ALL
               SELECT p.parent, 0 havechild, 6 TYPE, p.mid, NAME vname, '''' vnote, NULL nprocedure, p.tag nblock, NULL ncycle, NULL nshift, '''' vparam, NULL, '''' verror 
                 FROM points p WHERE p.ptype=1 '
    || lv_sqladd
    || ' AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid) AND NOT EXISTS (SELECT * FROM makets WHERE nmaket=p.mid)
               ORDER BY TYPE DESC,havechild desc, vname ';
  ELSIF an_type = 1 THEN                                                                                             -- группы и агрегирующие группы для макетов
   lv_sql :=
       'SELECT 1 HaveChild, 4 Type, ngroup mid, vname , vnote, vcode 
                     FROM maketgroups gr 
                    WHERE nmaket = '
    || an_id
    || ' AND (makets_pg.isagregat(gr.ngroup) = 1) 
                   UNION ALL 
                   SELECT 1 HaveChild, 2 TYPE, ngroup, vname, vnote, vcode 
                     FROM maketgroups gr 
                    WHERE nmaket = '
    || an_id
    || ' AND EXISTS(SELECT * FROM maketpoints WHERE ngroup=gr.ngroup) 
                   UNION ALL 
                   SELECT 0 HaveChild, 2 TYPE, ngroup, vname, vnote, vcode 
                     FROM maketgroups gr 
                    WHERE nmaket = '
    || an_id
    || ' AND NOT EXISTS(SELECT * FROM maketpoints WHERE ngroup=gr.ngroup) AND (makets_pg.isagregat(gr.ngroup) <> 1) 
                   ORDER BY TYPE DESC, vname ';
  ELSIF an_type = 2 THEN                                                                                                                     -- точки для группы
   lv_sql :=
       'SELECT 0 HaveChild, 3 Type, mp.mid, UTIL_PG.Get_Pointname(mp.MID,1) vname, mp.ngroup, ps.short_name, mp.nkc, mp.ntype 
                 FROM maketpoints mp, points ps 
                WHERE ngroup = '
    || an_id
    || ' AND ps.mid = mp.mid 
                ORDER BY vname ';
  ELSIF an_type = 4 THEN                                                                                                     -- подгруппы для агрегирующих групп
   lv_sql :=
       'SELECT 0 HaveChild, 5 Type, gr.nsubgroup mid, g.vname , g.vnote, g.vcode, gr.nsign, gr.ngroup 
                 FROM maketformulas gr, maketgroups g 
                WHERE gr.ngroup = '
    || an_id
    || ' AND g.ngroup = gr.nsubgroup 
                ORDER BY vname ';
  END IF;

  OPEN acur_t FOR lv_sql;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.getmakettree: Ошибка чтения ветки дерева макетов. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- возвращает ветку дерева точек
 PROCEDURE getpointstree(an_id NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(8000);
 BEGIN
  IF an_id = 0 THEN                                                                                                                                   -- корень
   lv_sql :=
       'SELECT 1 HaveChild, decode(ind,1,2,2,2,3) TYPE, mid, NAME vname, short_name
                 FROM points p 
                WHERE p.mid IN(SELECT * FROM   TABLE(adminadd_pg.getfirst_accmid('
    || util_pg.cn_pntmid
    || '))) AND EXISTS(SELECT * FROM points WHERE parent=p.mid)
               UNION ALL
               SELECT 0 HaveChild, decode(ind,1,2,2,2,3) ind, mid, NAME, short_name
                 FROM points p 
                WHERE p.mid IN(SELECT * FROM   TABLE(adminadd_pg.getfirst_accmid('
    || util_pg.cn_pntmid
    || '))) AND NOT EXISTS(SELECT * FROM points WHERE parent=p.mid)
                ORDER BY 2,4 ';
  ELSE
   IF adminadd_pg.check_accread(an_id) = 0 THEN
    raise_application_error(-20002, 'В доступе отказано. an_id='||an_id);
   END IF;

   lv_sql :=
       'SELECT 1 HaveChild, decode(ind,1,2,2,2,3) TYPE, mid, NAME vname, short_name
                 FROM points p 
                WHERE Parent='
    || an_id
    || ' AND EXISTS(SELECT * FROM points WHERE parent=p.mid)
				     UNION ALL 
               SELECT 0 HaveChild, decode(ind,1,2,2,2,3) ind, mid, NAME, short_name
                 FROM points p 
                WHERE Parent='
    || an_id
    || ' AND NOT EXISTS(SELECT * FROM points WHERE parent=p.mid) ORDER BY 2,4 ';
  END IF;

  OPEN acur_t FOR lv_sql;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'makets_pg.getpointstree: Ошибка чтения ветки дерева точек. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

