   -- Процедура копирования групп в макете
 FUNCTION copy_mg(an_nmaket NUMBER                                                                                                   --Ид макета для копирования
                                  ,
 av_str VARCHAR2                                                                                                                   --Типы измерений XXX, X - 0/1
                )
  RETURN NUMBER IS
  cnt                 NUMBER := 0;
  cnt_name            NUMBER := 1;
  cnt_grps            NUMBER := 0;
  cnt_pts             NUMBER;
  ln_group            NUMBER;
  valid               NUMBER := 1;
  lc                  NUMBER;
  gname               VARCHAR2(2000);
  gcode               NUMBER;
  gnote               NUMBER;
  canupdate           NUMBER;

  TYPE t_linkrec IS RECORD(
   val                 NUMBER,
   rval                NUMBER
  );

  TYPE t_linkarray IS TABLE OF t_linkrec
   INDEX BY BINARY_INTEGER;

  linkarray           t_linkarray;
 BEGIN
  SAVEPOINT maketgroups_copy;
  linkarray(1).val := 1;
  linkarray(1).rval := 1;
  linkarray(2).val := 2;
  linkarray(2).rval := 2;
  linkarray(3).val := 5;
  linkarray(5).rval := 3;

  IF (LENGTH(av_str) = 3) AND(av_str != '000') THEN
   FOR lc IN 1 .. 3 LOOP
    IF NOT(SUBSTR(av_str, lc, 1) IN('0', '1')) THEN
     valid := 0;
     EXIT;
    END IF;
   END LOOP;

   IF (valid = 1) THEN
    FOR points_row IN (SELECT *
                       FROM   maketpoints
                       WHERE  ngroup IN(SELECT ngroup
                                        FROM   maketgroups
                                        WHERE  nmaket = an_nmaket)) LOOP
     IF SUBSTR(av_str, linkarray(points_row.ntype).rval, 1) = '0' THEN
      canupdate := 1;
     ELSE
      canupdate := 0;
     END IF;

     FOR lc IN 1 .. 3 LOOP
      -- Есть ли у нас точки заданного типа?
      SELECT COUNT(*)
      INTO   cnt_pts
      FROM   DUAL
      WHERE  EXISTS(
              SELECT *
              FROM   maketpoints
              WHERE  (maketpoints.ntype = linkarray(lc).val) AND(maketpoints.mid = points_row.mid)
                     AND(maketpoints.ngroup IN(SELECT ngroup
                                               FROM   maketgroups
                                               WHERE  maketgroups.nmaket = an_nmaket)));

      IF (SUBSTR(av_str, lc, 1) = '1') AND(cnt_pts < 1) THEN
       --Добавляем точку с нужным нам типом
       IF canupdate = 1 THEN
        canupdate := 0;
        --Меняем тип существующей точки
        makets_pg.chg_p(points_row.ngroup,                                                                                                             --Группа
         points_row.mid,                                                                                                                            --Мид точки
         points_row.nkc,                                                                                                                --Коэффициент вхождения
         linkarray(lc).val                                                                                                                      --Тип измерений
                          );
       ELSE
        cnt_name := 1;

        SELECT vname, vcode, vnote
        INTO   gname, gcode, gnote
        FROM   maketgroups
        WHERE  ngroup = points_row.ngroup;

        LOOP
         --Подбираем название для новой группы
         SELECT COUNT(*)
         INTO   cnt_grps
         FROM   DUAL
         WHERE  EXISTS(SELECT *
                       FROM   maketgroups
                       WHERE  vname = gname || '_' || cnt_name);

         IF cnt_grps = 0 THEN
          --Создаем новую группу
          makets_pg.ins_g(an_nmaket, gcode, gname || '_' || cnt_name, gnote, ln_group);
          --Вставляем точку
          makets_pg.chg_p(ln_group, points_row.mid,                                                                                                 --Мид точки
           points_row.nkc,                                                                                                              --Коэффициент вхождения
           linkarray(lc).val                                                                                                                    --Тип измерений
                            );
          EXIT;
         END IF;

         cnt_name := cnt_name + 1;
        END LOOP;
       END IF;

       cnt := cnt + 1;
      ELSE
       IF (SUBSTR(av_str, lc, 1) = '0') AND(cnt_pts > 0) THEN
        --Удаляем точку
        DELETE FROM maketpoints
        WHERE       mid = points_row.mid AND ntype = linkarray(lc).val AND ngroup IN(SELECT ngroup
                                                                                     FROM   makets
                                                                                     WHERE  nmaket = an_nmaket);

        cnt := cnt - 1;
       END IF;
      END IF;
     END LOOP;
    END LOOP;

    --Удаляем пустые группы
    DELETE FROM maketgroups
    WHERE       maketgroups.nmaket = an_nmaket AND NOT EXISTS(SELECT *
                                                              FROM   maketpoints
                                                              WHERE  maketpoints.ngroup = maketgroups.ngroup);

    COMMIT;
   ELSE
    raise_application_error(-20001, 'makets_pg.copy_mg: Ошибка копирования макета. ' || CHR(10) || 'Входная строка может содержать символы только "0" или "1"');
   END IF;
  ELSE
   raise_application_error(-20001,
    'makets_pg.copy_mg: Ошибка копирования макета. ' || CHR(10) || 'Входная строка должна содержать 3 символа и отличаться от "000"');
  END IF;

  RETURN cnt;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT maketgroups_copy;
   raise_application_error(-20001, 'makets_pg.copy_mg: Ошибка копирования макета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION is_block(an_maket NUMBER, an_blocking NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER := an_blocking;
 BEGIN
  IF an_blocking IS NULL THEN
   SELECT NVL(MAX(nblock), 0)
   INTO   ln_ret
   FROM   makets
   WHERE  nmaket = an_maket;
  END IF;

  IF ln_ret <> 0 THEN
   ln_ret := 1;
  ELSE
   SELECT     DECODE(NVL(MAX(tag), 0), 0, 0, 1)
   INTO       ln_ret
   FROM       points
   CONNECT BY PRIOR PARENT = mid
   START WITH mid = an_maket;
  END IF;

  RETURN ln_ret;
 END;
