--Процедура возвращает точки+ тип измерений для фиксированных колонок
 PROCEDURE read_row_p (an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER, an_ispoint NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_sub   VARCHAR2 (200);
  lv_sql   VARCHAR2 (4000);
  lv_d     VARCHAR (40);
 BEGIN
  IF an_ispoint = 1 THEN
   lv_d := ' ';
   lv_sub := ' (select mid from points where ind = 3 start with mid = ' || an_mid || '
                       connect by prior mid = parent) ';
  ELSE
   lv_d := 'distinct';
   lv_sub := ' (select mid from groups where mid is not null start with gid = ' || an_mid || ' connect by prior gid = parent) ';
  END IF;

  lv_sql :=
   'select ' || lv_d
   || ' f.mid,
         f.vcode||decode(f.vcode,NULL,'''',''  '')||pa.name||''/''||p.name  name,
     indic_pg.measurename(mn.nmeasure,decode(f.q1234,''*'',1,0)) type,
     m.position, pa.name,p.name,  mn.nmeasure, m.mtrsn, nvl(f.kc,1) KC
     from (select rownum nmeasure from dict where rownum<=6) mn ,meters m,feeders f,
          points p,points pa
      where mn.nmeasure in ( '
   || an_er || ', ' || an_ed || ', ' || an_q1 || ', ' || an_q2 || ', ' || an_q3 || ', ' || an_q4 || ' )
                      and f.mid in  ' || lv_sub
   || '
                     and f.mid=m.mid(+)
                        and indic_pg.is_availability(mn.nmeasure,decode(f.q1234,''*'',1,0),f.er_position,
                        f.ed_position,f.q1_position,f.q3_position)=1
                        and mn.nmeasure=decode(m.entype,7,mn.nmeasure,m.entype)
                        and f.mid=p.mid(+) and p.parent=pa.mid(+)
     order by m.position, pa.name,p.name,mn.nmeasure';

  OPEN acur_t FOR lv_sql;
 END;

