 -- insert into tmp_vil values(ln_tt||' '||test_date||' '||ln_edit); commit;
 
 IF ln_edit=1 THEN
   IF util_pg.is_dayswitch (lv_dates)=-1 AND util_pg.is_dayswitch (trunc(to_date( ad_date_test,'dd.mm.yyyy hh24:mi:ss')))<>1 THEN
   ln_switch_f:=util_pg.switch_f;
   lv_subtest:='AND (to_char(P.date_time-1/86400,''hh24'')<>'||ln_switch_f||' OR (to_char(P.date_time-1/86400,''hh24'')='||ln_switch_f||' and nsource not in (19, 29, 39, 49, 59)))';
  
   ELSIF util_pg.is_dayswitch (lv_dates)=-1 AND util_pg.is_dayswitch (trunc(to_date( ad_date_test,'dd.mm.yyyy hh24:mi:ss')))=1 THEN
   ln_switch_f:=util_pg.switch_f;
   lv_subtest:='AND to_char(P.date_time-1/86400,''hh24'')<>'||ln_switch_f;
  
   ELSE
   ln_switch_f:=util_pg.switch_f;
   lv_subtest:='AND to_char(P.date_time,''hh24'')<>'||ln_switch_f;
   END IF;
 ELSE
   lv_subtest:='';
 END IF ;

IF an_test_mid=an_mid THEN
  IF an_ispoint = 1 THEN
   lv_d := ' ';
   lv_sub := ' (select mid from points where ind = 3 start with mid = ' || an_mid || '
                       connect by prior mid = parent) ';
  ELSE
   lv_d := ' distinct ';
   lv_sub := ' (select mid from groups where mid is not null start with gid = ' || an_mid || ' connect by prior gid = parent) ';
  END IF;
ELSE
  IF an_ispoint = 1 THEN
   lv_d := ' ';
   lv_sub := ' ( ' || an_test_mid || ') ';
  ELSE
   lv_d := ' distinct ';
   lv_sub := ' ( ' || an_test_mid || ' ) ';
  END IF;
END IF;  
   ----------------------------------------------------------------------------------------------------
   IF (ln_dsummer = 0) THEN
   lv_sqltimezone :=
    '  AND   util_pg.to_unlocaltime (P.date_time, nsource) > to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'')+ 1 / 86400+' || ln_timezona
    || '   AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'') + 1 + ' || ln_timezona;
  ELSE
   lv_sqltimezone :=
    ' AND   P.date_time > to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+' || ln_timezona || '
      AND   P.date_time <= to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'')+1 + ' || ln_timezona;
  END IF;
 
   ln_countfull:=interior_pg.get_rowcount(an_mid , an_ispoint, '24'  , 
   24 ,190001 , 300001 ,ln_dat,to_date( lv_dates,'dd.mm.yyyy hh24:mi:ss'));
  
  
  ln_countrow:=  interior_pg.get_step(an_mid, an_ispoint,
  to_date( lv_dates,'dd.mm.yyyy hh24:mi:ss'),0 ,24 ,
  190001 , 300001 ,ln_dat );
 

 
  /* interior_pg.grouping_p (24, to_date( lv_dates,'dd.mm.yyyy hh24:mi:ss'), an_stepprof, lv_grouping);*/
  
  IF ln_edit<>0 THEN
    select trunc(to_date( ad_date_test,'dd.mm.yyyy hh24:mi:ss'))-trunc(to_date(ad_date,'dd.mm.yyyy hh24:mi:ss')) into ln_hh from dual;
   
    IF ln_dsummer=1 THEN
     lv_grouping := ' util_pg.get_num_dt (P.date_time-1/86400+'||ln_hh||',nsource, 1/' || an_stepprof || ' ,0,' || ln_timezona || ',' || ln_dsummer || ') ';
    ELSE
     lv_grouping :=
        ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400+'||ln_hh||',nsource),nsource, 1/' || an_stepprof || ' ,0,' || ln_timezona || ',' || ln_dsummer || ') ';
    END IF;
  
  
  ELSE
    IF ln_dsummer=1 THEN
     lv_grouping := ' util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/' || an_stepprof || ' ,0,' || ln_timezona || ',' || ln_dsummer || ') ';
    ELSE
     lv_grouping :=
        ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/' || an_stepprof || ' ,0,' || ln_timezona || ',' || ln_dsummer || ') ';
    END IF;
 END IF;

-----------------------------------------------------------------------------------------------------------
  interior_pg.takeofpartquerifornsorse_p (1, an_ispoint, 24, '24', lv_dates, lv_datef, an_mid, 0,ln_countfull,ln_countrow,lv_decnsourcesec, lv_decnsourcef);
  lv_sql :=
   'select tt.mid,tt.type from  (select ' || lv_d
   || ' f.mid,
      mn.nmeasure type,m.position, pa.name,p.name,mn.nmeasure
       from (select rownum nmeasure from dict where rownum<=6) mn ,meters m,feeders f,
       points p,points pa
      where mn.nmeasure in ( '
   || an_er || ', ' || an_ed || ', ' || an_q1 || ', ' || an_q2 || ', ' || an_q3 || ', ' || an_q4 || ' )
                      and f.mid in  ' || lv_sub
   || '
                     and f.mid=m.mid(+)
                        and indic_pg.is_availability(mn.nmeasure,decode(f.q1234,''*'',1,0),f.er_position,
                        f.ed_position,f.q1_position,f.q3_position)=1
                        and mn.nmeasure=decode(m.entype,7,mn.nmeasure,m.entype)
                        and f.mid=p.mid(+) and p.parent=pa.mid(+)
     order by m.position, pa.name,p.name,mn.nmeasure)tt';
  --  delete from tmp_vil;  
--  insert into tmp_vil values(lv_sql);
--    commit;
  lv_sql2 :=   
 
   'SELECT   DECODE (GROUPING ('|| lv_grouping||') 
    ,
                                         1, 0,
         '|| lv_grouping||' 
                                       ) bgroup,
                            DECODE( :par3 ,1,SUM(p.er)/'||gn_koeff||' ,
                            2,SUM(p.ed)/'||gn_koeff||' ,
                            3,SUM(p.Q1)/'||gn_koeff||' ,
                            4,SUM(p.Q2)/'||gn_koeff||' ,
                            5,SUM(p.Q3)/'||gn_koeff||' ,
                            6,SUM(p.Q4)/'||gn_koeff||' ) aparam
                         '
   || lv_decnsourcef
   || ' decnsour
                       FROM halfhour p
                         WHERE p.mid = :par4
                        '|| lv_sqltimezone||' '||lv_subtest||'
                         GROUP BY ROLLUP ('|| lv_grouping||')
                        ORDER BY 1';
  t_data := 0;
  
--insert into tmp_vil values(lv_sql2||' '||util_pg.is_dayswitch (trunc(to_date( ad_date_test,'dd.mm.yyyy hh24:mi:ss')))); commit;  
ln_i:=0;
  OPEN cur_t FOR lv_sql;

  LOOP
   FETCH cur_t
    INTO ln_mid, ln_type;

   EXIT WHEN cur_t%NOTFOUND;
   IF an_test_mid<>an_mid THEN
     ln_mid:=an_mid;
   END IF;

   IF (ln_mid IS NOT NULL AND ln_type IS NOT NULL) THEN
    t_data := data_t.COUNT;
     
-- insert into tmp_vil values(t_data); commit;  

--util_pg.is_dayswitch (lv_dates)
 --  FOR z IN 1 .. (an_stepprof + 1 - ((an_stepprof / 24) * util_pg.is_dayswitch (lv_dates))) LOOP
  FOR z IN 1 .. test_date LOOP
     data_t (t_data + z) := NULL;
    END LOOP;
  
    
--delete from tmp_vil;
--insert into tmp_vil values(lv_sql2);
-- commit;
--ln_edit:=0;


 
 -- ln_edit:=1; 
 
-- insert into tmp_vil values(ln_edit||' '||ln_tt||' '||test_date);commit; 
    OPEN cur_t2 FOR lv_sql2 USING ln_type, ln_mid; --, lv_dates, lv_datef;

    --   USING an_stepprof, an_stepprof, ln_type, ln_mid, ln_mid, lv_dates,
      --       lv_datef, an_stepprof;

    
    LOOP
     FETCH cur_t2
      INTO ln_bgroup, ln_param, ln_decnsour;

     EXIT WHEN cur_t2%NOTFOUND;
 
        IF (ln_edit<>0) THEN
           data_t ((ln_bgroup + 1) + test_date * ln_row) :=ln_param; -- TRUNC (ln_param, 3);
        ELSE
           data_t ((ln_bgroup + 1) + ((an_stepprof + 1 - ((an_stepprof / 24) * util_pg.is_dayswitch (lv_dates))) * ln_row)) := ln_param; --TRUNC (ln_param, 3);
        END IF;  
         --  t_data := t_data + 1;
      
     

   
    END LOOP;
       
        IF (ln_edit=-1 ) then
          FOR i IN 1..an_stepprof/24 LOOP
            IF util_pg.is_dayswitch (lv_dates)=-1 THEN
            data_t (4*(an_stepprof/24)+i+1 + test_date * ln_row) := data_t (3*(an_stepprof/24)+i+1 + test_date * ln_row);
            ELSE
            data_t (3*(an_stepprof/24)+i+1 + test_date * ln_row) := data_t (2*(an_stepprof/24)+i+1 + test_date * ln_row);
            END IF;
        --  insert into tmp_vil values( data_t (3*(an_stepprof/24)+i +  ((an_stepprof + 1 - ((an_stepprof / 24) * util_pg.is_dayswitch (lv_dates))) * ln_row))||' '||(3*(an_stepprof/24)+i +  ((an_stepprof + 1 - ((an_stepprof / 24) * util_pg.is_dayswitch (lv_dates))) * ln_row)));
        --   commit;
           END LOOP;
          ln_sum:=0;
           FOR i in 2..test_date LOOP
             ln_sum:=ln_sum+nvl(data_t(i+(test_date * ln_row)),0); 
          --   insert into tmp_vil values( data_t(i+(test_date * ln_row))||' '||ln_sum); commit; 
           END LOOP;
           data_t (1+test_date * ln_row) :=ln_sum;
        END IF;

    CLOSE cur_t2;
 
    ln_row := ln_row + 1;
   END IF;
  END LOOP;

  CLOSE cur_t;
  
 /* FOR i in 1..data_t.count LOOP
--  insert into tmp_vil values(data_t(i));
           commit;
  END LOOP;*/
  
 END;

