 PROCEDURE test_data_p(an_mid NUMBER,ad_date VARCHAR2,an_type NUMBER,an_r NUMBER,an_stepprof NUMBER,
                       data_t OUT common_pg.tt_number)
 IS
  ln_r   NUMBER  DEFAULT ROUND (an_r,0);
  lv_dates DATE;
  lv_datef DATE;
  t_data NUMBER;
  lt_info    averrate_pg.ttinfo;
  ln_tmp NUMBER;
  y NUMBER;
 --t_info NUMBER;
  ln_timezona NUMBER;
  ln_testsummer NUMBER;
  
  
 BEGIN
 ln_timezona := MANUAL_IN_PG.get_hourtime;
 IF to_date(ad_date,'dd.mm.yyyy hh24:mi:ss')<util_pg.cd_alwayssummer THEN
 ln_testsummer:= MANUAL_IN_PG.get_summer;
 ELSE
 ln_testsummer:=0;
 END IF;
 
/*IF (interior_pg.get_dsummer = 0) THEN 
 lv_dates := util_pg.to_localtime(TRUNC(TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')))+ln_timezona;
 lv_datef := util_pg.to_localtime(TRUNC(TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')))+ln_timezona+1;
ELSE*/
 lv_dates := TRUNC(TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss'))+1/86400 + ln_timezona;
 lv_datef := TRUNC(TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss'))+ln_timezona + 1;
--END IF;
 averrate_pg.createtinfo (an_mid, lv_dates, lv_datef, an_type, 1, ln_r, lt_info,1,0,ln_testsummer,gn_koeff);
 
 

  data_t.DELETE;
  t_data := data_t.COUNT;
  FOR z IN 1 .. (an_stepprof  - ((an_stepprof / 24) * util_pg.is_dayswitch (lv_dates)*ln_testsummer)) LOOP
     data_t (t_data + z) := NULL;
  END LOOP;

-- t_data := data_t.COUNT;
-- insert into tmp_vil values (t_data||'  '||an_stepprof||' '||util_pg.is_dayswitch (lv_dates)||' '||ln_testsummer);commit;
  
  y:=1;
 --  FOR i IN 1 .. an_stepprof  LOOP
  FOR i IN 1 ..(an_stepprof  - ((an_stepprof / 24) * util_pg.is_dayswitch (lv_dates)*ln_testsummer)) LOOP
    ln_tmp :=0;
    IF  an_stepprof<48 THEN
      ln_tmp := lt_info (y).e;
      y:=y+1;
      ln_tmp := ln_tmp+lt_info (y).e;
      y:=y+1;
    ELSE
      ln_tmp := lt_info (y).e;
      y:=y+1;
    END IF;
     data_t(i):=ln_tmp;
  
   END LOOP;
 END;   
