 PROCEDURE save_data_p (an_mid NUMBER, an_type NUMBER, ad_date VARCHAR2, an_kc NUMBER, data_t common_pg.tt_number, an_step NUMBER, an_test NUMBER) IS
  lv_type     VARCHAR2 (40);
  ld_date     DATE;
  ln_ret      NUMBER;
  ln_data     NUMBER;
  lv_kc       VARCHAR2 (200)      DEFAULT NVL (TO_CHAR (an_kc), 'NULL');
  data_in     common_pg.tt_number;
  ln_count    NUMBER;
  TEST        NUMBER;
  test1       NUMBER;
  lv_qm       VARCHAR2 (40);
  ln_sourse   NUMBER;
  y           NUMBER;
  ln_step     NUMBER;
  ln_timezona NUMBER;
  lv_sqltimezone VARCHAR2 (2000);
 BEGIN
 
 adminadd_pg.check_right(an_mid, NULL, 1, 1);
  -- для разбивки по получасам
  TEST := 0;

  --  IF an_step = 24
  IF data_t.COUNT < 26 THEN
   ln_step := an_step * 2;

   FOR i IN 1 .. data_t.COUNT LOOP
    IF data_t (i) IS NOT NULL THEN
     data_in (TEST + 1) := ROUND (data_t (i) / 2);
     data_in (TEST + 2) := data_t (i) - data_in (TEST + 1);
     TEST := data_in.COUNT;
    ELSE
     data_in (TEST + 1) := NULL;
     data_in (TEST + 2) := NULL;
     TEST := data_in.COUNT;
    END IF;
   END LOOP;
  ELSE
   ln_step := an_step;

   FOR i IN 1 .. data_t.COUNT LOOP
    IF data_t (i) IS NOT NULL THEN
     data_in (i) := data_t (i)* gn_koeff;
    ELSE
     data_in (i) := NULL;
    END IF;
   END LOOP;
  END IF;

-----------------------------------------
  IF an_type = 2 THEN
   lv_type := 'ed';
  ELSIF an_type = 3 THEN
   lv_type := 'q1';
  ELSIF an_type = 4 THEN
   lv_type := 'q2';
  ELSIF an_type = 5 THEN
   lv_type := 'q3';
  ELSIF an_type = 6 THEN
   lv_type := 'q4';
  ELSE
   lv_type := 'er';
  END IF;
ln_timezona := MANUAL_IN_PG.get_hourtime;

  IF (MANUAL_IN_PG.get_summer = 0) THEN
   lv_sqltimezone :=
    '  AND   util_pg.to_unlocaltime (P.date_time, nsource) > to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'')+ ' || ln_timezona
    || '   AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'') + 1 + ' || ln_timezona;
  ELSE
   lv_sqltimezone :=
    ' AND   P.date_time > to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'') + ' || ln_timezona || '
      AND   P.date_time <= to_date(''' || ad_date || ''',''dd.mm.yyyy hh24:mi:ss'')+1 + ' || ln_timezona;
  END IF;
  
  --  IF (gn_testmid <> an_mid)
  IF (an_test = 1) THEN
  /* DELETE FROM halfhour p
         WHERE p.mid = an_mid AND date_time >= TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss') + 1 / 86400 AND date_time <= TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')
                                                                                                                       + 1;

   */
   EXECUTE IMMEDIATE ' DELETE FROM halfhour p
         WHERE p.mid ='|| an_mid ||lv_sqltimezone;
                                                            
  -- COMMIT;
  END IF;

  gn_testmid := an_mid;
--  ld_date := TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')+ln_timezona;
 IF (MANUAL_IN_PG.get_summer = 0) THEN
  ld_date := util_pg.to_localtime(TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss'))+ln_timezona;
 ELSE
  ld_date := TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')+ln_timezona;
 END IF;
  test1 := 0;
  y := 0;

  FOR i IN 1 .. data_in.COUNT LOOP
   ln_data := data_in (i);
   

   IF (util_pg.is_dayswitch (TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')) > 0 AND ld_date = TRUNC (ld_date) + (util_pg.switch_f) / 24 AND test1 = 0) THEN
    ld_date := ld_date + 1 / 24;
    test1 := 1;
   ELSIF (util_pg.is_dayswitch (TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')) < 0 AND ld_date = TRUNC (ld_date) + (util_pg.switch_f + 1) / 24 AND test1 = 0) THEN
    ld_date := ld_date - 1 / 24;
    test1 := 1;
   END IF;
 

   ld_date := ld_date + 1 / ln_step;
  -- IF ln_data IS NOT NULL THEN
   lv_qm := qm_pg.cv_manualqm;
 --  ELSE
 --  lv_qm := qm_pg.cv_nodataqm;
 --  END IF;
   ln_sourse := 50;

   IF ( util_pg.is_dayswitch (TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')) < 0 AND test1 <> 0 AND y < ln_step / 24) THEN
    ln_sourse := 59;
    y := y + 1;
   END IF;

 --  IF ln_data IS NOT NULL THEN
 --select  vqm into lv_vqm from halfhour vqm where mid = an_mid and date_time= ld_date;
-- IF lv_vqm<>qm_pg.calcqm THEN 
-- select count(*) into test from halfhour where mid=an_mid and date_time=ld_date and || lv_type ||=ln_data;


    EXECUTE IMMEDIATE 'UPDATE halfhour  SET ' || lv_type
                      || '= :pardata ,NKC= :parkc , vqm = :parqm  where mid=:parmid
      and date_time=:pard and nsource=:sourse'
                USING ln_data, lv_kc, lv_qm, an_mid, ld_date, ln_sourse;

 --   IF SQL%ROWCOUNT = 0 AND  ln_data IS NOT NULL THEN 
 IF SQL%ROWCOUNT = 0 THEN 
     EXECUTE IMMEDIATE 'INSERT INTO halfhour (mid, date_time, ' || lv_type || ',NKC,vqm,nsource )
         VALUES(:parmid ,:pard, :pardate,:parkc,:parqm,:sourse) '
                 USING an_mid, ld_date, ln_data, lv_kc, lv_qm, ln_sourse;
    END IF;
    
  
-- ELSE
-- raise_application_error (-20001, 'manual_in_pg.Save_Data_p: Данные получены автоматически.Ручной ввод невозможен ' || CHR (10) || SQLERRM (SQLCODE));
--  END IF;
  END LOOP;

  EXECUTE IMMEDIATE 'UPDATE  halfhour p SET p.vqm='||qm_pg.cv_nodataqm||'
                    WHERE p.mid='|| an_mid ||lv_sqltimezone||' and (p.ed IS NULL AND p.er IS NULL AND p.q1 IS NULL AND p.q2 IS NULL AND p.q3 IS NULL AND p.q4 IS NULL)';

  IF (an_test = 1) THEN
   admin_pg.fiscal_p (609, 2,
                      'Изменен расход по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' на '
                      || TO_CHAR (TO_DATE (ad_date, 'dd.mm.yyyy hh24:mi:ss')+ln_timezona, 'dd.mm.yyyy hh24:mi:ss'));
  END IF;
  calcformula_pg.calc_lagging_job;
 --  END IF;                        
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'manual_in_pg.Save_Data_p: Ошибка вставки ' || CHR (10) || SQLERRM (SQLCODE));
 END;

