 PROCEDURE read_node_p (an_mid NUMBER, if_point NUMBER, acur_t OUT common_pg.tcur) IS
 lv_sql VARCHAR2(4000);
 lv_subsql VARCHAR2(1000);
 ln_parent NUMBER;
 BEGIN
 
 
  IF an_mid IS NULL THEN
  
  IF util_pg.get_customer_id = 1 AND util_pg.getparamvalue_f(13) IS NOT NULL THEN
    ln_parent:= util_pg.getparamvalue_f(13);
    lv_subsql:=' PARENT ='||ln_parent;
  ELSE
    lv_subsql:=' PARENT IS NULL ';
  END IF;
  
  -- OPEN acur_t FOR
  
  lv_sql:=' SELECT   1 havechild, mid, DECODE (ind, 3, 1, 0) TYPE, NAME, 1 point
        FROM points p
       WHERE cod = 0 AND p.mid IN(SELECT * FROM   TABLE(adminadd_pg.getfirst_accmid('||util_pg.cn_pntmid||'))) AND EXISTS (SELECT *
                                                                 FROM points
                                                                WHERE PARENT = p.mid AND cod = 0)
    UNION ALL
    SELECT   0 havechild, mid, DECODE (ind, 3, 1, 0) TYPE, NAME, 1 point
        FROM points p
       WHERE cod = 0 AND p.mid IN(SELECT * FROM   TABLE(adminadd_pg.getfirst_accmid('||util_pg.cn_pntmid||'))) AND NOT EXISTS (SELECT *
                                                                     FROM points
                                                                    WHERE PARENT = p.mid AND cod = 0)
    UNION ALL
    SELECT   1 havechild, gid mid, DECODE (mid, NULL, 4, 1) TYPE, NVL (NAME, '' '') NAME, 0 point
        FROM GROUPS p
       WHERE '||lv_subsql||' AND EXISTS (SELECT *
                                          FROM GROUPS
                                         WHERE PARENT = p.gid)
    UNION ALL
    SELECT   0 havechild, gid, DECODE (mid, NULL, 4, 1) TYPE, NVL (NAME, '' '') NAME, 0 point
        FROM GROUPS p
       WHERE '||lv_subsql||' AND NOT EXISTS (SELECT *
                                              FROM GROUPS
                                             WHERE PARENT = p.gid)
    ORDER BY 3, 4 ';
    OPEN acur_t FOR lv_sql;
  ELSE
   IF if_point = 1 THEN
	   IF adminadd_pg.check_accread(an_mid)=0 THEN
					raise_application_error(-20002, 'В доступе отказано. an_id='||an_mid);
				END IF;
    OPEN acur_t FOR
     SELECT   1 havechild, mid, DECODE (ind, 3, 1, 0) TYPE, NAME, 1 point
         FROM points p
        WHERE cod = 0 AND PARENT = an_mid AND EXISTS (SELECT *
                                                        FROM points
                                                       WHERE PARENT = p.mid AND cod = 0)
     UNION ALL
     SELECT   0 havechild, mid, DECODE (ind, 3, 1, 0) TYPE, NAME, 1 point
         FROM points p
        WHERE cod = 0 AND PARENT = an_mid AND NOT EXISTS (SELECT *
                                                            FROM points
                                                           WHERE PARENT = p.mid AND cod = 0)
     ORDER BY 3, 4;
   ELSE
    OPEN acur_t FOR
     SELECT   1 havechild, gid mid, DECODE (mid, NULL, 4, 1) TYPE, NVL (NAME, ' ') NAME, 0 point
         FROM GROUPS p
        WHERE PARENT = an_mid AND EXISTS (SELECT *
                                            FROM GROUPS
                                           WHERE PARENT = p.gid)
     UNION ALL
     SELECT   0 havechild, gid, DECODE (mid, NULL, 4, 1) TYPE, NVL (NAME, ' ') NAME, 0 point
         FROM GROUPS p
        WHERE PARENT = an_mid AND NOT EXISTS (SELECT *
                                                FROM GROUPS
                                               WHERE PARENT = p.gid)
     ORDER BY 3, 4;
   END IF;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------
 PROCEDURE find_node_p (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT     mid
         FROM points
   CONNECT BY PRIOR PARENT = mid AND cod = 0
   START WITH mid = an_mid AND cod = 0
   UNION ALL
   SELECT     gid mid
         FROM GROUPS
   CONNECT BY PRIOR PARENT = gid
   START WITH gid = an_mid;
 END;

------------------------------------------------------------------------------------------------------------
 PROCEDURE read_maxvalue_p (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   DECODE (a.nsort, -1, a.vvalue/gn_koeff, NULL) apmin, DECODE (a.nsort, -2, a.vvalue/gn_koeff, NULL) apmax, DECODE (a.nsort, -3, a.vvalue/gn_koeff, NULL) apmina,
            DECODE (a.nsort, -4, a.vvalue/gn_koeff, NULL) apmaxa, DECODE (a.nsort, -5, a.vvalue/gn_koeff, NULL) apminf, DECODE (a.nsort, -6, a.vvalue/gn_koeff, NULL) apmaxf,
            DECODE (a.nsort, -7, a.vvalue/gn_koeff, NULL) ammin, DECODE (a.nsort, -8, a.vvalue/gn_koeff, NULL) ammax, DECODE (a.nsort, -9, a.vvalue/gn_koeff, NULL) ammina,
            DECODE (a.nsort, -10, a.vvalue/gn_koeff, NULL) ammaxa, DECODE (a.nsort, -11, a.vvalue/gn_koeff, NULL) amminf, DECODE (a.nsort, -12, a.vvalue/gn_koeff, NULL) ammaxf,
            DECODE (a.nsort, -13, a.vvalue/gn_koeff, NULL) rpmin, DECODE (a.nsort, -14, a.vvalue/gn_koeff, NULL) rpmax, DECODE (a.nsort, -15, a.vvalue/gn_koeff, NULL) rpmina,
            DECODE (a.nsort, -16, a.vvalue/gn_koeff, NULL) rpmaxa, DECODE (a.nsort, -17, a.vvalue/gn_koeff, NULL) rpminf, DECODE (a.nsort, -18, a.vvalue/gn_koeff, NULL) rpmaxf,
            DECODE (a.nsort, -19, a.vvalue/gn_koeff, NULL) rmmin, DECODE (a.nsort, -20, a.vvalue/gn_koeff, NULL) rmmax, DECODE (a.nsort, -21, a.vvalue/gn_koeff, NULL) rmmina,
            DECODE (a.nsort, -22, a.vvalue/gn_koeff, NULL) rmmaxa, DECODE (a.nsort, -23, a.vvalue/gn_koeff, NULL) rmminf, DECODE (a.nsort, -24, a.vvalue/gn_koeff, NULL) rmmaxf
       FROM addpointparamval a
      WHERE a.mid = an_mid AND a.nsort BETWEEN -24 AND -1
   ORDER BY a.nsort DESC;
 END;
----------------------------------------------------------------------------------------------------------
PROCEDURE set_koeff (an_koeff NUMBER) IS
BEGIN
  IF an_koeff=0 THEN
   gn_koeff:=1; 
  ELSE
   gn_koeff:=1000;
  END IF;
END;
--------------------------------------------------------------------------------------
FUNCTION get_koeff
  RETURN NUMBER IS
 BEGIN
   RETURN gn_koeff;
 END;
--------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.MANUAL_IN_PG

-- Start of DDL Script for Package Body RYDA.MANUAL_IN_START_METERS_PG
-- Generated 14.04.2014 9:34:58 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY manual_in_start_meters_pg IS
------------------------------------------------------------------------------------------
 PROCEDURE read_node_p(an_mid NUMBER, an_ispoint NUMBER, acur_t OUT common_pg.tcur) IS
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF (an_ispoint = 1) THEN
   lv_sql :=
       'select distinct f.mid, f.vcode||decode(f.vcode,NULL,'''',''  '')||pa.name||''/''||p.name vname,
                       
                        m.mtrsn, nvl(f.kc,1) KC, m.digits,NVL(DECODE(m.mconst, 0, 1, m.mconst), 1) mconst, 
                         b.erm em, 
                          b.er e,
                          b.DATE_TIME  ddate                      
                       
                      from meters m,feeders f,points p,points pa,MAN_INP_HHOUR b 
                        where f.mid in (select mid from ryda.points where ind = 3 start with mid = '
    || an_mid
    || ' connect by prior mid = parent)  
                         and f.mid=m.mid(+)and m.entype(+) = 7 and f.mid=b.mid(+) 
                         and ryda.comsrvmtx_pg.is_mtx_child(f.mid , f.nusd )=1
                         and f.mid=p.mid(+) and p.parent=pa.mid(+)';
  ELSE
   lv_sql :=
       'select 
                        distinct  
                        f.mid, f.vcode||decode(f.vcode,NULL,'''',''  '')||pa.name||''/''||p.name vname,
                        
                        m.mtrsn, nvl(f.kc,1) KC, m.digits,NVL(DECODE(m.mconst, 0, 1, m.mconst), 1) mconst, 
                        b.erm em, 
                        b.er e,                        
                        b.DATE_TIME ddate
                      from meters m,feeders f,points p,points pa ,MAN_INP_HHOUR b
                       where f.mid in (select mid from ryda.groups where mid is not null start with gid =  '
    || an_mid
    || ' connect by prior gid = parent)  
                        and f.mid=m.mid(+) and m.entype(+) = 7 and f.mid=b.mid(+)
                        and ryda.comsrvmtx_pg.is_mtx_child(f.mid , f.nusd )=1
                        and f.mid=p.mid(+) and p.parent=pa.mid(+)';
  END IF;

  IF adminadd_pg.check_accread(util_pg.cn_pntmid) = 0 THEN                                                                              --Права на вершину точек
   lv_sql := lv_sql || ' and f.mid in (select * from table (adminadd_pg.getall_accmid))';
  END IF;

  lv_sql := lv_sql || ' order by  2,1';

--INSERT INTO TMP_VIL VALUES(lv_sql);COMMIT;
  OPEN acur_t FOR lv_sql;
 END;

-------------------------------------------------------------------------------------------
 PROCEDURE save_data_p(an_mid NUMBER, an_er NUMBER, an_erm NUMBER, ad_date DATE) IS
  lv_sql              VARCHAR2(2000);
  lv_subup            VARCHAR2(400) := ' ER=:ner, ERM=:nerm ';
  lv_subins           VARCHAR(400) := ' ER,ERM ';
 BEGIN
  SAVEPOINT manual_in_start_sp;
  adminadd_pg.check_right(an_mid, NULL, 1, 1);

  EXECUTE IMMEDIATE ' UPDATE MAN_INP_HHOUR  SET DATE_TIME=:ddate,  ' || lv_subup || '   WHERE MID=:anmid '
  USING             ad_date, an_er, an_erm, an_mid;

  IF SQL%ROWCOUNT = 0 THEN
   EXECUTE IMMEDIATE '  INSERT INTO MAN_INP_HHOUR (MID,DATE_TIME,' || lv_subins || ')
  VALUES(:nmid,:ddate,:ner ,:nerm)'
   USING             an_mid, ad_date, an_er, an_erm;
  END IF;

  editfeeders_pg.recalcdiff(an_mid, ad_date - 1 / 86400);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT manual_in_start_sp;
   raise_application_error(-20001, 'MANUAL_IN_START_METERS_PG.Save_Data_p: Ошибка вставки ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------
 FUNCTION test_data_p(an_mid NUMBER, an_er NUMBER, ad_date DATE, an_k NUMBER)
  RETURN NUMBER IS
  ln_erm              NUMBER;
 BEGIN
  SELECT MAX(q1m)
  INTO   ln_erm
  FROM   halfhour h
  WHERE  h.mid = an_mid AND h.date_time <= util_pg.ceilhh24_2(ad_date) AND h.date_time >= util_pg.ceilhh24_2(ad_date) - 1 / 48;

  IF ln_erm IS NULL THEN
   raise_application_error(-20001, 'Отсутствуют показания датчика импульсов на ''' || TO_CHAR(util_pg.ceilhh24_2(ad_date), 'dd.mm.yyyy hh24:mi') || '''');
  END IF;

  RETURN ROUND(an_er - ln_erm / an_k, comsrvmtx_pg.cn_rnd);
 END;
---------------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.MANUAL_IN_START_METERS_PG

