CREATE OR REPLACE 
PACKAGE BODY manual_meter_in
IS
--Пакет для нового ручного ввода показаний
--Виленская Н.Б. 12.02.2010
----------------------------------------------------------------------------------------------------------------
--Процедура возвращает точки+ тип измерений для фиксированных колонок

PROCEDURE read_row_p (an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER,
                      an_ispoint NUMBER,
                      an_table NUMBER,ad_seldat DATE,acur_t OUT common_pg.tcur
 ) IS
  lv_sub   VARCHAR2 (200);
  lv_sql   VARCHAR2 (4000);
  lv_d     VARCHAR (40);
 BEGIN
  IF an_ispoint = 1 THEN
   lv_d := ' ';
   lv_sub := '(select mid from points where ind = 3 start with mid = ' || an_mid || ' connect by prior mid = parent) ' ;
  
  ELSE
   lv_d := ' distinct ';
   lv_sub :=' (select mid from groups where mid is not null start with gid = ' || an_mid || ' connect by prior gid = parent) ';
   
  END IF;

  lv_sql :=
 
'select ' || lv_d
   || 'f.mid,
   f.vcode||decode(f.vcode,NULL,'''',''  '')||util_pg.get_pointname(p.mid,3,0)||''/''||p.name name,
    indic_pg.measurename(mn.nmeasure,decode(f.q1234,''*'',1,0)) type, 
  DECODE(mn.nmeasure,1,f.er_position,2,f.ed_position,3,f.q1_position,5,f.q3_position) Position, 
  mn.nmeasure, m.mtrsn, nvl(f.kc,1) KC, m.digits, m.position,
  indic_pg.getlastdate(f.mid,:par2 ,mn.nmeasure,NULL,'||an_table||',1) lastd,
  indic_pg.getlastindic(f.mid,:par3,mn.nmeasure,NULL,'||an_table||') lastind,
  indic_pg.getnextdate(f.mid,:par2,mn.nmeasure,NULL,'||an_table||',1)nextd,
  indic_pg.getlastindic(f.mid,indic_pg.getnextdate(f.mid,:par2,mn.nmeasure,NULL,'||an_table||',1)+1,mn.nmeasure,NULL,'||an_table||') nextind,
  decode(mn.nmeasure,1,b.erm,2,b.edm,3,b.q1m,4,b.q2m,5,b.q3m,6,b.q4m) em, 
  decode(mn.nmeasure,1,b.er,2,b.ed,3,b.q1,4,b.q2,5,b.q3,6,b.q4) e 
  from (select rownum nmeasure from dict where rownum<=6) mn,
  BILLORG b,meters m,feeders f,points p 
  where mn.nmeasure in (' || an_er || ', ' || an_ed || ', ' || an_q1 || ', ' || an_q2 || ', ' || an_q3 || ', ' || an_q4 || ') 
  and nvl(b.nsource,0) not in (7,8)
  and f.mid in '||lv_sub||' 
  and f.mid=b.mid(+) and b.date_time(+)= :par1 
  and f.mid=m.mid(+) 
  and indic_pg.is_availability(mn.nmeasure,
  decode(f.q1234,''*'',1,0),f.er_position,f.ed_position,f.q1_position,f.q3_position)=1
  and mn.nmeasure=decode(m.entype,7,mn.nmeasure,m.entype)
  and f.mid=p.mid(+) 
  order by m.position, name ,mn.nmeasure';
  
 
  
  OPEN acur_t FOR lv_sql USING ad_seldat,ad_seldat,ad_seldat,ad_seldat,ad_seldat;
  
 END;
-----------------------------------------------------------------------------------------------------------------
 PROCEDURE read_minmaxvalue_p (an_mid NUMBER,an_meas NUMBER, acur_t OUT common_pg.tcur) IS
 lv_sql VARCHAR2(2000);
 lv_subsql VARCHAR2(400);
 BEGIN
 --(пред. низ; пред.верх; аварийн.  низ; аварийн.  верх; физ.  низ; физ. верх)
  IF an_meas=1 THEN --А птр.
   lv_subsql:='(-1,-2,-3,-4,-5,-6)';
  ELSIF an_meas=2 THEN --А выд.
   lv_subsql:='(-7,-8,-9,-10,-11,-12)';
  ELSIF an_meas=3 OR an_meas=4 THEN  --Р птр. Q1 Q2
   lv_subsql:='(-13,-14,-15,-16,-17,-18)';
   ELSIF an_meas=5 OR an_meas=6 THEN  --Р выд. Q3 Q4
   lv_subsql:='(-19,-20,-21,-22,-23,-24)';  
  END IF;
  
  
  
 lv_sql:='  SELECT   DECODE (a.nsort, -1, a.vvalue,-7, a.vvalue,-13, a.vvalue,-19, a.vvalue, NULL) predmin, 
         DECODE (a.nsort, -2, a.vvalue,-8, a.vvalue,-14, a.vvalue,-20, a.vvalue, NULL) predmax, 
         DECODE (a.nsort, -3, a.vvalue,-9, a.vvalue,-15, a.vvalue,-21, a.vvalue, NULL) avarmin,
         DECODE (a.nsort, -4, a.vvalue,-10, a.vvalue,-16, a.vvalue,-22, a.vvalue, NULL) avarmax,
         DECODE (a.nsort, -5, a.vvalue,-11, a.vvalue,-17, a.vvalue,-23, a.vvalue, NULL) fizmin,
         DECODE (a.nsort, -6, a.vvalue,-12, a.vvalue,-18, a.vvalue,-24, a.vvalue, NULL) fizmax
    FROM addpointparamval a
   WHERE a.mid = '||an_mid||' AND a.nsort IN '||lv_subsql||'
   ORDER BY a.nsort DESC';
  
-- insert into tmp_vil values(an_mid||' '||lv_sql);
--commit;  
   OPEN acur_t FOR lv_sql;
  
 END;
 -----------------------------------------------------------------------------------------------------------------
END;
/


