CREATE OR REPLACE 
PACKAGE BODY maxhours_pg IS
 -- пакет работы с часами макс нагрузки
 -- дата создания 30/07/2002 (Сечин А.А.)
 gn_task_code        NUMBER DEFAULT 33;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки
 PROCEDURE ins_p(
 ad_date_time DATE,                                                                                                                     --Дата ввода в действие
                   ad_morning_start DATE,                                                                                                            --Утро нач
                                         ad_morning_end DATE,                                                                                        --Утро кон
                                                             ad_evening_start DATE,                                                                 --Вечер нач
                                                                                   ad_evening_end DATE,                                             --Вечер кон
                                                                                                       an_maxhour_id OUT NUMBER                            --Ид
 ) IS
  ln_maxhour_id       NUMBER;
 BEGIN
  IF TO_NUMBER(TO_CHAR(ad_morning_start, 'SSSSS')) >= TO_NUMBER(TO_CHAR(ad_morning_end, 'SSSSS'))
     OR TO_NUMBER(TO_CHAR(ad_morning_end, 'SSSSS')) >= TO_NUMBER(TO_CHAR(ad_evening_start, 'SSSSS'))
     OR TO_NUMBER(TO_CHAR(ad_evening_start, 'SSSSS')) >= TO_NUMBER(TO_CHAR(ad_evening_end, 'SSSSS')) THEN
   raise_application_error(-20001, 'Ошибка задания часов нагрузки. Интервалы утреннего и вечернего максимума не должны пересекаться. ');
  END IF;

  SELECT limits_seq.NEXTVAL
  INTO   ln_maxhour_id
  FROM   DUAL;

  INSERT INTO maxhours
              (maxhour_id, date_time, morning_start, morning_end, evening_start, evening_end)
  VALUES      (ln_maxhour_id, ad_date_time, TRUNC(ad_date_time) +(ad_morning_start - TRUNC(ad_morning_start)),
               TRUNC(ad_date_time) +(ad_morning_end - TRUNC(ad_morning_end)), TRUNC(ad_date_time) +(ad_evening_start - TRUNC(ad_evening_start)),
               TRUNC(ad_date_time) +(ad_evening_end - TRUNC(ad_evening_end)));

  an_maxhour_id := ln_maxhour_id;
  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлено расписание часов максимальной нагрузки на дату ' || TO_CHAR(ad_date_time, 'dd.mm.yyyy'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'maxhours_pg.ins_p: Ошибка добавления часов макс нагрузки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления данных
 PROCEDURE upd_p(
 an_maxhour_id NUMBER,                                                                                                                                      --Ид
                      ad_date_time DATE,                                                                                                 --Дата ввода в действие
                                        ad_morning_start DATE,                                                                                        --Утро нач
                                                              ad_morning_end DATE,                                                                    --Утро кон
                                                                                  ad_evening_start DATE,                                             --Вечер нач
                                                                                                        ad_evening_end DATE                          --Вечер кон
 ) IS
 BEGIN
  IF TO_NUMBER(TO_CHAR(ad_morning_start, 'SSSSS')) >= TO_NUMBER(TO_CHAR(ad_morning_end, 'SSSSS'))
     OR TO_NUMBER(TO_CHAR(ad_morning_end, 'SSSSS')) >= TO_NUMBER(TO_CHAR(ad_evening_start, 'SSSSS'))
     OR TO_NUMBER(TO_CHAR(ad_evening_start, 'SSSSS')) >= TO_NUMBER(TO_CHAR(ad_evening_end, 'SSSSS')) THEN
   raise_application_error(-20001, 'Ошибка задания часов нагрузки. Интервалы утреннего и вечернего максимума не должны пересекаться.');
  END IF;

  UPDATE maxhours
  SET date_time = ad_date_time,
      morning_start = TRUNC(ad_date_time) +(ad_morning_start - TRUNC(ad_morning_start)),
      morning_end = TRUNC(ad_date_time) +(ad_morning_end - TRUNC(ad_morning_end)),
      evening_start = TRUNC(ad_date_time) +(ad_evening_start - TRUNC(ad_evening_start)),
      evening_end = TRUNC(ad_date_time) +(ad_evening_end - TRUNC(ad_evening_end))
  WHERE  maxhour_id = an_maxhour_id;

  admin_pg.fiscal_p(gn_task_code, 2, 'Изменено расписание часов максимальной нагрузки на дату ' || TO_CHAR(ad_date_time, 'dd.mm.yyyy'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'maxhours_pg.upd_p: Ошибка изменения часов макс нагрузки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Процедура удаления данных
 PROCEDURE del_p(an_maxhour_id NUMBER                                                                                                                       --Ид
                                     ) IS
  ld_date_time        DATE;
 BEGIN
  SELECT date_time
  INTO   ld_date_time
  FROM   maxhours
  WHERE  maxhour_id = an_maxhour_id;

  admin_pg.fiscal_p(gn_task_code, 3, 'Удалено расписание часов максимальной нагрузки на дату ' || TO_CHAR(ld_date_time, 'dd.mm.yyyy'));

  DELETE FROM maxhours
  WHERE       maxhour_id = an_maxhour_id;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'maxhours_pg.del_p: Ошибка удаления часов макс нагрузки. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
-- Процедура чтения данных
 PROCEDURE read_data_p(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   maxhour_id, TO_CHAR(date_time, 'DD.MM.YYYY') dt, TO_CHAR(morning_start, 'HH24:MI') ms, TO_CHAR(morning_end, 'HH24:MI') me,
            TO_CHAR(evening_start, 'HH24:MI') es, TO_CHAR(evening_end, 'HH24:MI') ee
   FROM     maxhours
   ORDER BY date_time DESC;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_maxhours(ad_date DATE)
  RETURN datarray IS
  ld_date             DATE := TRUNC(ad_date);
  lt_date             datarray := datarray();
 BEGIN
  SELECT ld_date + d.dat / 24 dt
  BULK COLLECT INTO lt_date
  FROM   maxhours m,
         (SELECT     ROWNUM dat
          FROM       DUAL
          CONNECT BY LEVEL <= 24) d
  WHERE  m.date_time = (SELECT MIN(date_time)
                        FROM   maxhours
                        WHERE  date_time <= ld_date)
         AND(
             (d.dat > TO_CHAR(m.morning_start, 'HH24') AND d.dat <= TO_CHAR(m.morning_end, 'HH24'))
             OR(d.dat > TO_CHAR(m.evening_start, 'HH24') AND d.dat <= TO_CHAR(m.evening_end, 'HH24'))
            );

  RETURN lt_date;
 END;
------------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                             -- Package Body
/


-- End of DDL Script for Package Body RYDA.MAXHOURS_PG

