CREATE OR REPLACE 
PACKAGE BODY meterparameter_pg IS
 ------------------------------------------------------------------------------------------------------------------------
 -- Возвращает основной курсор
 PROCEDURE getparam(an_mid NUMBER, ret_t OUT common_pg.tcur) IS
 BEGIN
  OPEN ret_t FOR
   SELECT mp.mid, mp.ddate, mp.vfilename, mp.BFILE, mp.vnote
     FROM meterparameter mp
    WHERE mp.mid = NVL(an_mid, 0);
 END;
 ----------------------------------------------------------------
   -- Сохранение
 PROCEDURE upd_p(an_mid NUMBER, ad_olddate DATE, ad_date DATE, av_fname VARCHAR2, ab_file IN OUT BLOB, av_note VARCHAR2) IS
 BEGIN
  IF ab_file IS NULL THEN
   UPDATE meterparameter
      SET ddate = ad_date,
          vfilename = av_fname,
          BFILE = EMPTY_BLOB(),
          vnote = av_note
    WHERE mid = an_mid AND ddate = ad_olddate;
  ELSE
   UPDATE    meterparameter
         SET ddate = ad_date,
             vfilename = av_fname,
             BFILE = ab_file,
             vnote = av_note
       WHERE mid = an_mid AND ddate = ad_olddate
   RETURNING BFILE
        INTO ab_file;
  END IF;
  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO meterparameter
               (mid, ddate, vfilename, BFILE, vnote)
        VALUES (an_mid, ad_date, av_fname, EMPTY_BLOB(), av_note)
     RETURNING BFILE
          INTO ab_file;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'METERPARAMETER_PG.upd_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ----------------------------------------------------------------
    -- Удаление
 PROCEDURE del_p(an_mid NUMBER, ad_date DATE) IS
 BEGIN
  DELETE FROM meterparameter
        WHERE mid = an_mid AND ddate = ad_date;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'METERPARAMETER_PG.del_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ----------------------------------------------------------------
 -- Получение даты параметризации счетчика при его опросе
 FUNCTION get_param_date(an_mid NUMBER) 
 RETURN VARCHAR2 IS
  lv_date VARCHAR2(100);
 BEGIN
  SELECT TO_CHAR(MAX(dparametrization),'dd.mm.yyyy hh24:mi:ss') INTO lv_date
    FROM last_save
   WHERE mid=an_mid;
  RETURN lv_date;
  
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'METERPARAMETER_PG.get_param_date: ' || CHR(10) || SQLERRM(SQLCODE));
 END; 
----------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.METERPARAMETER_PG

-- Start of DDL Script for Package Body RYDA.METERS_PG
-- Generated 14.04.2014 9:34:58 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY      meters_pg IS
 --------------------------------------------------------------------
 -- пакет работы с таблицей METERS
 -- дата создания 05/02/2004 (Сечин А.А)
 gn_task_code NUMBER DEFAULT 47;
 --------------------------------------------------------------------
 PROCEDURE create_tree(top NUMBER, tree OUT common_pg.tcur) IS
 BEGIN
 OPEN tree FOR
  SELECT m.ID ,m.MID ,m.NAME ,m.POSITION ,m.ENTYPE ,m.SMART ,m.MTRSN ,
         to_char(nvl(m.DATE_TIME,sysdate),'dd.mm.yyyy')DATE_TIME ,m.DIGITS ,m.MTYPE ,
         m.MCURRENT ,m.MPOWER ,m.MCONST ,m.MCLASS ,m.MYEAR ,m.MQUARTER
  FROM  ryda.meters m,ryda.points p
  WHERE m.mid IN (SELECT mid FROM ryda.points
                  CONNECT BY PRIOR mid = parent START WITH mid=top) and m.mid=p.mid(+) and p.ind<>4 
  ORDER BY p.name,p.mid, m.ENTYPE;
 END;
 
   --Процедура обновления данных
 PROCEDURE upd_p(
  an_mid       NUMBER,
  ad_date_time DATE,
  av_mtrsn     VARCHAR2,
  an_digits    NUMBER,
  av_mtype     VARCHAR2,
  an_mcurrent  NUMBER,
  an_mpower    NUMBER,
  an_myear     NUMBER,
  av_mquarter  NUMBER,
  an_mconst    NUMBER,
  an_mclass    NUMBER,
  an_entype    NUMBER) IS
  lv_name VARCHAR2(2000);
 BEGIN
  SAVEPOINT meters_sp;
  UPDATE meters
     SET date_time = ad_date_time,
         mtrsn = av_mtrsn,
         digits = an_digits,
         mtype = av_mtype,
         mcurrent = an_mcurrent,
         mpower = an_mpower,
         myear = an_myear,
         mquarter = av_mquarter,
         mconst = an_mconst,
         mclass = an_mclass
   WHERE mid = an_mid AND entype = an_entype;
  SELECT MAX(name)
    INTO lv_name
    FROM meters
   WHERE mid = an_mid AND entype = an_entype;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Изменена  информация по счетчику ''' || lv_name || ''' по точке: ''' ||
          util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || '''');
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT meters_sp;
   raise_application_error(
    -20001, 'meters_pg.upd_p: Ошибка изменения параметров счетчика. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
---------------------------------------------------------------------
END; -- Package Body METERS_PG
/


