 PROCEDURE get_SysDate(acur_t OUT common_pg.tcur) IS -- выполнялась в TfmMonitorMeters::TfmMonitorMeter
 BEGIN
   OPEN acur_t FOR
        SELECT to_char(sysdate,'dd.mm.yyyy hh24:mi') day1, to_char(sysdate-1,'dd.mm.yyyy hh24:mi') day2 FROM dual;
 END;
