 PROCEDURE get_GraphHistor(an_flag NUMBER, at_nodes common_pg.tt_number, av_from VARCHAR2, av_to VARCHAR2, an_table NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- рисуем историю наличия связи (TfmMonitorMeters::GraphIstoir)
  v_nodes    VARCHAR2(4000);
 BEGIN
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' a.mid IN (' ||v_nodes|| ') AND ';
  END IF;
  IF (an_flag=1) THEN
        OPEN acur_t FOR 'select distinct p.mid from CHANPOINT a,points p
                         WHERE '||v_nodes||' p.mid=a.cid ';
  ELSIF (an_flag=2) THEN
        OPEN acur_t FOR 'SELECT a.date_time, decode(a.state_cod,0,1,0) st, d.VEVENTTEXT||a.state_descr state_descr FROM journal a,METEREVENTSDICT d
                         WHERE a.nevent=d.nevent(+) and  a.state_cod IN (0,1,2,6) AND '||v_nodes||
                         'a.date_time>=to_date(:meFrom,''dd.mm.yyyy hh24:mi'')
                         AND a.date_time<=to_date(:meTo,''dd.mm.yyyy hh24:mi'')
                         ORDER BY a.date_time'
                        using av_from, av_to;
  ELSE
        RETURN;
  END IF;
 END;
