 PROCEDURE get_GraphKomm_2(an_flag NUMBER, at_nodes common_pg.tt_number, av_from VARCHAR2,
                        av_to VARCHAR2, an_table NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- построение коммерческого графика для одного узла дерева (TfmMonitorMeters::GraphKomm)
   table_name   VARCHAR2(1000);
   v_nodes    VARCHAR2(4000);
 BEGIN
  table_name := monitor_meters_pg.get_table_name(an_table);
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' h.mid IN (' ||v_nodes|| ') AND ';
  END IF;

  IF (table_name = ' BILLORG ') THEN
        OPEN acur_t FOR 'select trunc(date_time) dtm,trunc(1440*(max(denter)-trunc(date_time))) dt from '||table_name||' h
                         WHERE  '||v_nodes||' h.date_time >=trunc(to_date(:meFrom,''dd.mm.yyyy hh24:mi''))+1
                         AND h.date_time < util_pg.ceil_d(to_date(:meTo,''dd.mm.yyyy hh24:mi''),1)+1
                         GROUP BY trunc(date_time) ORDER BY 1'
                        using av_from, av_to;
  ELSE
    IF (an_flag = 1) THEN
        OPEN acur_t FOR 'select trunc(date_time-1/86400)+1 dtm,trunc(1440*(max(denter)-trunc(date_time-1/86400)-1)) dt from '||table_name||' h
                         WHERE '||v_nodes||' 
                         h.date_time >trunc(to_date(:meFrom,''dd.mm.yyyy hh24:mi''))
                         AND h.date_time <= util_pg.ceil_d(to_date(:meTo,''dd.mm.yyyy hh24:mi''),1)                           
                         GROUP BY trunc(date_time-1/86400) ORDER BY 1'
                        using av_from, av_to;
    ELSE
        OPEN acur_t FOR 'select trunc(date_time-1/86400)+1 dtm,trunc(1440*(max(denter)-trunc(date_time-1/86400)-1)) dt
                         FROM (SELECT min(denter) denter, util_pg.trunc_d(date_time,util_pg.stephalfhour_f()/1440) date_time
                               FROM HALFHOUROLD  h WHERE  '||v_nodes||
                               ' h.date_time >trunc(to_date(:meTo,''dd.mm.yyyy hh24:mi''))
                               AND h.date_time <= util_pg.ceil_d(to_date(:meTo,''dd.mm.yyyy hh24:mi''),1) AND h.nsource>0
                               GROUP BY mid, util_pg.trunc_d(date_time,util_pg.stephalfhour_f()/1440) )
                         GROUP BY trunc(date_time-1/86400) ORDER BY 1'
                        using av_from, av_to;
    END IF;
  END IF;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_GraphTeh(an_flag NUMBER, at_nodes common_pg.tt_number, av_from VARCHAR2,
                        av_to VARCHAR2, an_table NUMBER, av_step VARCHAR2, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- построение графиков технического контроля для одного узла дерева (TfmMonitorMeters::GraphTeh)
   table_name   VARCHAR2(1000);
   v_nodes    VARCHAR2(4000);
 BEGIN
  table_name := monitor_meters_pg.get_table_name(an_table);
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' h.mid IN (' ||v_nodes|| ') AND ';
  END IF;
  IF (table_name = ' HALFHOUR ' OR table_name = ' PROFILE ')THEN
    IF (table_name = ' PROFILE ' OR an_flag = 1) THEN
      OPEN acur_t FOR  'SELECT util_pg.trunc_d(date_time-1/86400,' ||av_step|| '/1440)+' ||av_step|| '/1440 date_time,
                        trunc(1440*(max(denter)-util_pg.trunc_d(date_time-1/86400,' ||av_step|| '/1440)-' ||av_step|| '/1440)) dt
                        FROM '||table_name||' h WHERE '||v_nodes||' h.date_time >trunc(to_date(:meFrom,''dd.mm.yyyy hh24:mi''))
                        AND h.date_time <=util_pg.ceil_d(to_date(:meTo,''dd.mm.yyyy hh24:mi''),' ||av_step|| '/1440)
                        GROUP BY util_pg.trunc_d(date_time-1/86400,' ||av_step|| '/1440) ORDER BY 1'
                       using av_from, av_to;
    ELSE
      OPEN acur_t FOR 'select util_pg.trunc_d(date_time-1/86400,' ||av_step|| '/1440)+' ||av_step|| '/1440 date_time,
                       trunc(1440*(max(denter)-util_pg.trunc_d(date_time-1/86400,' ||av_step|| '/1440)-' ||av_step|| '/1440)) dt
                       FROM (SELECT min(h.denter) denter,util_pg.trunc_d(date_time,' ||av_step|| '/1440) date_time
                             FROM HALFHOUROLD h WHERE '||v_nodes||
                             ' h.date_time >trunc(to_date(:meFrom,''dd.mm.yyyy hh24:mi''))
                             AND h.date_time <=util_pg.ceil_d(to_date(:meTo,''dd.mm.yyyy hh24:mi''),' ||av_step|| '/1440)
                             AND h.nsource>0 GROUP BY mid, util_pg.trunc_d(date_time,' ||av_step|| '/1440) )
                       GROUP BY util_pg.trunc_d(date_time-1/86400,' ||av_step|| '/1440) ORDER BY 1'
                      using av_from, av_to;
    END IF;
  ELSE
    OPEN acur_t FOR 'select trunc(date_time) date_time,trunc(1440*(max(denter)-trunc(date_time))) dt
                     FROM '||table_name||' h
                     WHERE '||v_nodes||' h.date_time >=trunc(to_date(:meFrom,''dd.mm.yyyy hh24:mi''))+1
                     AND h.date_time < util_pg.ceil_d(to_date(:meTo,''dd.mm.yyyy hh24:mi''),1)+1
                     GROUP BY trunc(date_time) ORDER BY 1'
                    using av_from, av_to;
  END IF;

 END;
