 PROCEDURE get_Tree(an_flag NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- процедуры для построения дерева (TfmMonitorMeters->oqTree, TfmMonitorMeters->oqVTree)
  lv_sql    VARCHAR2(4000);
 BEGIN
  IF (an_flag=1) THEN
        lv_sql := 'SELECT mid id ,NAME, parent, mid mid FROM points WHERE cod=0 AND parent IS NULL ORDER BY NAME';
  ELSIF (an_flag=2) THEN
        lv_sql := 'SELECT mid id ,NAME, parent, mid mid FROM points WHERE cod=0 AND parent=' ||an_mid|| ' ORDER BY NAME';
  ELSIF (an_flag=3) THEN
        lv_sql := 'SELECT gid id, NAME, parent, mid FROM GROUPS WHERE parent IS NULL ORDER BY NAME';
  ELSIF (an_flag=4) THEN
        lv_sql := 'SELECT gid id, NAME, parent, mid FROM GROUPS WHERE parent=' ||an_mid|| ' ORDER BY NAME';
  ELSIF (an_flag=5) THEN
        lv_sql := 'SELECT DECODE(c.CID,NULL,0,1) IS_GROUP, (SELECT COUNT(*) FROM POINTS WHERE PARENT=p.MID) HAS_CHILD,
                  NVL(c.CID, p.MID) id , p.mid, p.NAME ,decode(c.nkind,100,c.NPARENT2,c.NPARENT) PARENT,
                  NVL(decode(c.nkind,100,c.BLOCKING2,c.BLOCKING), p.TAG) BLOCKING FROM POINTS p, CHANNELS c
                  WHERE p.MID=c.CID(+) AND nvl(nkind,0)<>1 AND p.PARENT=1 ORDER BY IS_GROUP DESC, p.NAME';
  ELSIF (an_flag=6) THEN
        lv_sql := 'SELECT DECODE(c.CID,NULL,0,1) IS_GROUP, (SELECT COUNT(*) FROM POINTS WHERE PARENT=p.MID) HAS_CHILD,
                  NVL(c.CID, p.MID) id , p.mid, p.NAME ,decode(c.nkind,100,c.NPARENT2,c.NPARENT) PARENT,
                  NVL(decode(c.nkind,100,c.BLOCKING2,c.BLOCKING), p.TAG) BLOCKING FROM POINTS p, CHANNELS c
                  WHERE p.MID=c.CID(+) AND nvl(nkind,0)<>1 AND p.PARENT=' ||an_mid|| ' ORDER BY IS_GROUP DESC, p.NAME';
  ELSIF (an_flag=7) THEN
        lv_sql := 'SELECT  p.mid id, p.mid, 2 IS_GROUP, 0 parent ,''ПС ''||
                  (SELECT NAME FROM points WHERE mid=(SELECT parent FROM points WHERE mid=c.cid)) ||
                  '' - ''||''ТУ ''||p.NAME NAME FROM CHANPOINT c,POINTS p
                  WHERE c.mid=p.mid AND c.cid=' ||an_mid|| ' ORDER BY NAME';
  END IF;
  OPEN acur_t FOR lv_sql;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_VTree2(an_flag NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- вспомогательные процедуры для построения дерева (TfmMonitorMeters->oqVTree2)
  lv_sql    VARCHAR2(4000);
 BEGIN
  IF (an_flag=1) THEN
        lv_sql := 'SELECT util_pg.get_customer_id() bd_id FROM dual';
  ELSIF (an_flag=2) THEN
        lv_sql := 'SELECT parent FROM points WHERE mid='||an_mid;
  ELSIF (an_flag=3) THEN
        lv_sql := 'SELECT parent,mid FROM GROUPS WHERE gid=' ||an_mid;
  ELSIF (an_flag=4) THEN
        lv_sql := 'SELECT cid parent FROM CHANPOINT WHERE mid=' ||an_mid|| ' AND ROWNUM=1';
  ELSIF (an_flag=5) THEN
        lv_sql := 'SELECT name FROM points WHERE mid=(SELECT mid FROM enterprise)';
  ELSIF (an_flag=6) THEN
        lv_sql := 'SELECT decode(c.nkind,100,c.NPARENT2,c.NPARENT) PARENT,
                                 NVL(decode(c.nkind,100,c.BLOCKING2,c.BLOCKING), p.TAG) BLOCKING
                       FROM POINTS p, CHANNELS c WHERE p.MID=c.CID(+) AND nvl(nkind,0)<>1 AND p.mid='||an_mid;
  ELSIF (an_flag=7) THEN
        lv_sql := 'SELECT name FROM points WHERE mid='||an_mid;
  ELSIF (an_flag=8) THEN
        lv_sql := 'SELECT name FROM GROUPS WHERE gid='||an_mid;
  ELSIF (an_flag=9) THEN
        lv_sql := 'SELECT UTIL_PG.Get_Pointname(' ||an_mid|| ',1,0) NAME FROM dual';
  ELSIF (an_flag=10) THEN
        lv_sql := 'SELECT * FROM points WHERE parent='||an_mid;
  ELSIF (an_flag=11) THEN
        lv_sql := 'SELECT * FROM GROUPS WHERE parent='||an_mid;
  ELSIF (an_flag=12) THEN
        lv_sql := 'SELECT * FROM chanpoint WHERE cid='||an_mid;
   ELSIF (an_flag=13) THEN
        lv_sql := 'select mid id from points connect by  mid=prior parent start with mid='||an_mid;
  ELSIF (an_flag=14) THEN
        lv_sql := 'select gid id from groups connect by gid=prior parent start with gid='||an_mid;
  ELSIF (an_flag=15) THEN
        lv_sql := 'SELECT * FROM chanpoint WHERE cid='||an_mid;
  END IF;
  OPEN acur_t FOR lv_sql;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_oqVspom(an_flag NUMBER, at_nodes common_pg.tt_number, av_date VARCHAR2, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- (TfmJournal->oqVspom)
 v_nodes    VARCHAR2(4000);
 BEGIN
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' j.mid IN (' ||v_nodes|| ') AND ';
  END IF;
  IF (an_flag=1) THEN
    OPEN acur_t FOR
              'SELECT date_time FROM
              ( SELECT j.date_time FROM journal j WHERE '||v_nodes||
              ' j.date_time>=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')ORDER BY date_time)
              WHERE ROWNUM=1'
             using av_date;
  ELSIF (an_flag=2) THEN
    OPEN acur_t FOR
              'SELECT count(*) cnt FROM journal j, points p
              WHERE p.mid=j.mid AND '||v_nodes||
              ' j.date_time<=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')
              AND state_cod=0'
             using av_date;
  ELSIF (an_flag=3) THEN
    OPEN acur_t FOR
              'SELECT count(*) cnt FROM journal j, points p
              WHERE p.mid=j.mid AND '||v_nodes||
              ' j.date_time<=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')
              AND state_cod<>0'
             using av_date;
  ELSIF (an_flag=4) THEN
    OPEN acur_t FOR
              'SELECT count(*) cnt FROM journal j, points p
              WHERE p.mid=j.mid AND '||v_nodes||
              ' j.date_time<=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')'
             using av_date;
  END IF;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_oqData(an_flag NUMBER, at_nodes common_pg.tt_number, av_date VARCHAR2, an_sort NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- (TfmJournal->oqData)
  lv_sql    VARCHAR2(4000);
  v_nodes    VARCHAR2(4000);
 BEGIN
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' j.mid IN (' ||v_nodes|| ') AND ';
  END IF;
  IF (an_flag=1) THEN
    lv_sql := 'SELECT j.state_cod,j.date_time,p.NAME pname, d.VEVENTTEXT||j.state_descr  NAME
              FROM journal j, points p,METEREVENTSDICT d
              WHERE p.mid=j.mid AND j.nevent=d.nevent(+) AND '||v_nodes||
              ' j.date_time<=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')
              AND j.state_cod=0 ORDER BY ';
  ELSIF (an_flag=2) THEN
    lv_sql := 'SELECT j.state_cod,j.date_time,p.NAME pname, d.VEVENTTEXT||j.state_descr  NAME
              FROM journal j, points p,METEREVENTSDICT d
              WHERE p.mid=j.mid AND j.nevent=d.nevent(+) AND '||v_nodes||
              ' j.date_time<=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')
              AND state_cod<>0 ORDER BY ';
  ELSIF (an_flag=3) THEN
    lv_sql := 'SELECT j.state_cod,j.date_time,p.NAME pname, d.VEVENTTEXT||j.state_descr  NAME
              FROM journal j, points p,METEREVENTSDICT d
              WHERE p.mid=j.mid AND j.nevent=d.nevent(+) AND '||v_nodes||
              ' j.date_time<=to_date(:s_date,''dd.mm.yyyy hh24:mi:ss'')
              ORDER BY ';
  END IF;
  IF  ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);
   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;
   lv_sql := lv_sql || ',';
  END IF;
  lv_sql := lv_sql || ' 1';
  OPEN acur_t FOR lv_sql
              using av_date;
 END;
--------------------------------------------------------------------------------------
 FUNCTION get_table_name (an_table_flag NUMBER) RETURN VARCHAR2 IS
 -- функция возвращает имя таблицы по ее флагу
 BEGIN
    IF (an_table_flag = 1) THEN
        RETURN ' HALFHOUR ';
    ELSIF (an_table_flag = 2) THEN
        RETURN ' BILLORG ';
    ELSIF (an_table_flag = 3) THEN
        RETURN ' MONTHSORG ';
    ELSIF (an_table_flag = 4) THEN
        RETURN ' PROFILE ';
    ELSE
        RETURN 'no_table';
    END IF;
 END;
--------------------------------------------------------------------------------------
 FUNCTION get_v_nodes(an_mid NUMBER, at_nodes common_pg.tt_number) RETURN VARCHAR2 IS
 -- функция возвращает строку с подзапросом для получения mid узлов
  v_nodes    VARCHAR2(4000);
 BEGIN
  IF (at_nodes(at_nodes.first) = 0) THEN
    v_nodes := '0';
  ELSIF (at_nodes(at_nodes.first) = -1) THEN
    v_nodes := ' select mid from (select * from points where cod=0) 
                 CONNECT BY PRIOR mid=parent START WITH parent='||an_mid;
  ELSIF (at_nodes(at_nodes.first) = -2) THEN
    v_nodes := ' select mid from groups where mid is not null
                 CONNECT BY PRIOR gid=parent START WITH parent='||an_mid;
  ELSIF (at_nodes(at_nodes.first) = -3) THEN
    v_nodes := ' select p.mid from CHANPOINT c,POINTS p
                                  WHERE c.mid=p.mid AND cid IN
                                  (SELECT  c.CID FROM POINTS p, CHANNELS c
                                  WHERE p.MID=c.CID(+) AND nvl(nkind,0)<>1  AND c.cid IS NOT NULL
                                  CONNECT BY PRIOR p.mid=p.PARENT START WITH p.parent='||an_mid||' ) ';
  ELSIF (at_nodes(at_nodes.first) = -4) THEN
    v_nodes := ' select p.mid from CHANPOINT c,POINTS p
                 WHERE c.mid=p.mid AND cid ='||an_mid;
  ELSIF (at_nodes(at_nodes.first) = -5) THEN
    v_nodes := 'select mid from points connect by prior mid=parent
                                       START WITH parent=' || an_mid;
  ELSIF (at_nodes(at_nodes.first) = -6) THEN
    v_nodes := 'select mid from groups where mid is not null connect by prior gid=parent
                                     START WITH parent=' || an_mid;
  ELSIF (at_nodes(at_nodes.first) = -7) THEN
    v_nodes := 'select mid from groups where gid=' || an_mid;
  ELSE
    FOR i IN 1 .. at_nodes.COUNT LOOP
      v_nodes := v_nodes || TO_CHAR(at_nodes(i)) || ',';
    END LOOP;
    v_nodes := RTRIM(v_nodes,',');
  END IF;
  RETURN v_nodes;
 END;
--------------------------------------------------------------------------------------
PROCEDURE get_ShutOff_PU(at_nodes common_pg.tt_number, av_from DATE, av_to DATE, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- построение графика Отключение ПУ (TfmMonitorMeters::Graph)
  lv_sql    VARCHAR(4000);
  v_nodes    VARCHAR2(4000);
 BEGIN
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  /*IF (length(v_nodes) <> 0) THEN
    v_nodes := ' mid IN (' ||v_nodes|| ') AND ';
  END IF;*/
  OPEN acur_t FOR 'select date_time, decode(state_cod,1010,0,1) st from journal where state_cod in (1010,-1010)
                   AND ' || ' mid IN (' ||v_nodes|| ') AND ' || ' date_time>=:av_from
                   AND date_time<=:av_to 
                   ORDER BY date_time'
                   using av_from, av_to;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_oqGraph(an_flag NUMBER, an_table NUMBER, at_nodes common_pg.tt_number, av_from DATE, av_to DATE,
                          av_contr DATE, an_node_count NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- (TfmMonitorMeters->oqGraph)
  table_name   VARCHAR2(1000);
  lv_sql     VARCHAR2(10000);
  v_nodes    VARCHAR2(4000);
 BEGIN
  table_name := monitor_meters_pg.get_table_name(an_table);
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' h.mid IN (' ||v_nodes|| ') AND ';
  END IF;
    IF (an_flag=1) THEN
      OPEN acur_t FOR
             'SELECT util_pg.trunc_d(date_time-1/86400,30/1440)+30/1440 dt,max(decode(nsource,50,1,0)) nsource
              FROM '||table_name||' h WHERE  '||v_nodes||' h.date_time >= :meFrom
              AND h.date_time <= :meTo AND h.DENTER <=:contr
              GROUP BY util_pg.trunc_d(date_time - 1 / 86400,30/1440)
              HAVING count(DISTINCT mid)=' ||an_node_count|| ' ORDER BY 1'
             using av_from, av_to, av_contr;
    ELSIF (an_flag=2) THEN
      OPEN acur_t FOR
              'SELECT  trunc(date_time) dt,max(decode(nsource,50,1,0)) nsource
              FROM '||table_name||' h WHERE '||v_nodes||' h.date_time >= :meFrom
              AND h.date_time <= :meTo
              AND h.DENTER <= :contr
              GROUP BY trunc(date_time) HAVING count(DISTINCT mid)=' ||an_node_count|| ' ORDER BY 1'
             using av_from, av_to, av_contr;
    END IF;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_CntPossPoints(an_flag NUMBER, av_step VARCHAR2, av_from DATE, av_to DATE, acur_t OUT common_pg.tcur) IS
 --вычисляется количество возможных точек (TfmMonitorMeters::Graph)
 BEGIN
  IF (an_flag=1) THEN
        OPEN acur_t FOR 'select decode( :av_step,0,0,trunc(cnt_m*24*60/ :av_step)+1) cnt
                  FROM(SELECT :av_to-:av_from cnt_m FROM dual)'
                  using av_step, av_step, av_to, av_from;
  ELSIF (an_flag=2) THEN
        OPEN acur_t FOR 'select trunc(:av_to) -
                  trunc(:av_from)+1 cnt FROM dual'
                  using av_to, av_from;
  ELSIF (an_flag=3) THEN
        OPEN acur_t FOR 'select trunc(MONTHS_BETWEEN(:av_to,
                  :av_from))+1 cnt FROM dual'
                  using av_to, av_from;
  ELSE
        RETURN;
  END IF;
 END;
--------------------------------------------------------------------------------------
PROCEDURE get_GraphKomm(an_flag NUMBER, at_nodes common_pg.tt_number, av_from DATE,
                        av_to DATE, an_table NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- построение коммерческого графика для одного узла дерева (TfmMonitorMeters::GraphKomm)
   table_name   VARCHAR2(1000);
   v_nodes    VARCHAR2(4000);
 BEGIN
  table_name := monitor_meters_pg.get_table_name(an_table);
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' h.mid IN (' ||v_nodes|| ') AND ';
  END IF;

  IF (table_name = ' BILLORG ') THEN
        OPEN acur_t FOR 'select trunc(date_time) dtm,trunc(1440*(max(denter)-trunc(date_time))) dt from '||table_name||' h
                         WHERE  '||v_nodes||' h.date_time >=TRUNC(:meFrom)+1
                         AND h.date_time < util_pg.ceil_d(:meTo,1)+1
                         GROUP BY trunc(date_time) ORDER BY 1'
                        using av_from, av_to;
  ELSE
    IF (an_flag = 1) THEN
        OPEN acur_t FOR 'select trunc(date_time-1/86400)+1 dtm,trunc(1440*(max(denter)-trunc(date_time-1/86400)-1)) dt from '||table_name||' h
                         WHERE '||v_nodes||' 
                         h.date_time >trunc(:meFrom)
                         AND h.date_time <= util_pg.ceil_d(:meTo,1)                           
                         GROUP BY trunc(date_time-1/86400) ORDER BY 1'
                        using av_from, av_to;
    ELSE
        OPEN acur_t FOR 'select trunc(date_time-1/86400)+1 dtm,trunc(1440*(max(denter)-trunc(date_time-1/86400)-1)) dt
                         FROM (SELECT min(denter) denter, util_pg.trunc_d(date_time,util_pg.stephalfhour_f()/1440) date_time
                               FROM HALFHOUROLD  h WHERE  '||v_nodes||
                               ' h.date_time >trunc(:meTo)
                               AND h.date_time <= util_pg.ceil_d(:meTo,1) AND h.nsource>0
                               GROUP BY mid, util_pg.trunc_d(date_time,util_pg.stephalfhour_f()/1440) )
                         GROUP BY trunc(date_time-1/86400) ORDER BY 1'
                        using av_from, av_to;
    END IF;
  END IF;
 END;
--------------------------------------------------------------------------------------

END;
/


