-- Start of DDL Script for Package Body RYDA.MSENDER_PG
-- Generated 14.04.2014 9:34:59 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY msender_pg
IS
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE SourceDir (acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
       SELECT VVALUE FROM PARAMETER WHERE npid = 10;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'MSENDER_PG.SourceDir: Ошибка чтения данных. ' || CHR(10) || SQLERRM(SQLCODE));
 END; 
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE MainChannels (acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
       SELECT d.NDEPORTATION ndep, ddate d, vname, d.NTYPE, d.VADDRESS, d.NPARENT,to_char(d.DFROM, 'hh24:mi'), 
           to_char(d.DTILL, 'hh24:mi'), d.NRETRIES_TOUT, d.NRETRIES, f.vfile, f.vfilename, f.nattach, d.VPARAM
       FROM DEPORTATION d, DEPORTFILES f
       WHERE d.NDEPORTATION = f.NDEPORTATION AND deportation_pg.is_block(d.ndeportation,d.nblock)=0 AND f.nstate<>1 AND
             ((d.DFROM IS NULL OR d.DTILL IS NULL) OR (to_char(d.DFROM,'SSSSS')<=to_char(sysdate, 'SSSSS') 
             AND to_char(sysdate, 'SSSSS')<to_char(d.DTILL,'SSSSS')))
       ORDER BY f.NDEPORTATION,f.ddate;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'MSENDER_PG.MainChannels: Ошибка чтения данных. ' || CHR(10) || SQLERRM(SQLCODE));
 END; 
  ------------------------------------------------------------------------------------------------------------------------   \
  PROCEDURE NoSendFiles (acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
       SELECT ndeportation, ddate, vfile, vfilename, nattach FROM DEPORTFILES d WHERE nstate=2
        ORDER BY ndeportation, ddate;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'MSENDER_PG.NoSendFiles: Ошибка чтения данных. ' || CHR(10) || SQLERRM(SQLCODE));
 END; 
  ------------------------------------------------------------------------------------------------------------------------ 
  PROCEDURE ReservChannels (an_parent number,acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
       SELECT level, vname, NTYPE, VADDRESS, NPARENT,to_char(DFROM, 'hh24:mi'), to_char(DTILL, 'hh24:mi'), NRETRIES_TOUT, NRETRIES, 
                VPARAM, ndeportation
       FROM DEPORTATION d WHERE deportation_pg.is_block(d.ndeportation,d.nblock)=0 AND ((DFROM IS NULL OR DTILL IS NULL) OR
                (to_char(DFROM,'SSSSS')<=to_char(sysdate, 'SSSSS') AND to_char(DTILL,'SSSSS')>to_char(sysdate, 'SSSSS')))
       CONNECT BY prior ndeportation = nparent START WITH nparent = an_parent
       ORDER BY level;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'MSENDER_PG.ReservChannels: Ошибка чтения данных. ' || CHR(10) || SQLERRM(SQLCODE));
 END; 
  ------------------------------------------------------------------------------------------------------------------------ 
 END; -- Package Body MSENDER_PG
/


-- End of DDL Script for Package Body RYDA.MSENDER_PG

