CREATE OR REPLACE 
PACKAGE BODY operatingday_pg IS
------------------------------------------------------------------------------------------------------------------------
 gn_task_code CONSTANT NUMBER := 46;

------------------------------------------------------------------------------------------------------------------------
  -- пакет по задаче ввод типа разносок суточных расходов
  -- дата создания 29/11/2007 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 -- Возвращает основной курсор
 PROCEDURE getinfo(an_mid NUMBER, ad_from DATE, ad_till DATE, an_sort NUMBER, ret_t OUT common_pg.tcur) IS
  ln_mid              NUMBER DEFAULT NVL(an_mid, 0);
  lv_sql              VARCHAR2(4000);
  cn_colcount CONSTANT NUMBER := 6;
 BEGIN
  lv_sql :=
      'select util_pg.get_pointname(o.nowner,0,0) owname,o.dstart,util_pg.get_pointname(o.mid,0,0) pname,g.name gname,'
   || 'o.dregime,o.nshift,'
   || ln_mid
   || ' mid, o.nowner owmid,o.mid pmid,g.gid ,
    decode(1,2,1,o.ntype) ntype '
   || 'from OPERATINGDAY o,(select * from points connect by prior parent =mid start with mid='
   || ln_mid
   || ') ow, points p,groups g where o.nowner=ow.mid and o.mid=p.mid(+) and o.gid=g.gid(+)';

  --Ограничение по дате
  IF ad_from IS NOT NULL THEN
   lv_sql := lv_sql || ' and o.dstart>=to_date(''' || TO_CHAR(ad_from, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'')';
  END IF;

  IF ad_till IS NOT NULL THEN
   lv_sql := lv_sql || ' and o.dstart<=to_date(''' || TO_CHAR(ad_till, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'')';
  END IF;

  --Сортировка
  lv_sql := lv_sql || ' ORDER BY ';

  IF ABS(an_sort) > 0 AND ABS(an_sort) <= cn_colcount THEN
   lv_sql := lv_sql || ABS(an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' desc';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' ' ||(cn_colcount + 1) || ' desc,2 desc';

  OPEN ret_t FOR lv_sql;
 END;

----------------------------------------------------------------
   -- Сохранение
 PROCEDURE upd_p(
 an_owner NUMBER, ad_start_old DATE, ad_start DATE, an_mid NUMBER, an_gid NUMBER, ad_regime DATE, an_shift NUMBER, an_type NUMBER, an_meas NUMBER
 ) IS
  ln_type             NUMBER DEFAULT 2;
 BEGIN
  UPDATE operatingday
  SET dstart = ad_start,
      mid = an_mid,
      gid = an_gid,
      dregime = ad_regime,
      nshift = NVL(an_shift, 0),
      ntype = an_type,
      nmeas = an_meas
  WHERE  nowner = an_owner AND dstart = ad_start_old;

  IF SQL%ROWCOUNT = 0 THEN
   ln_type := 1;

   INSERT INTO operatingday
               (nowner, dstart, mid, gid, dregime, nshift, ntype, nmeas)
   VALUES      (an_owner, ad_start, an_mid, an_gid, ad_regime, an_shift, an_type, an_meas);
  END IF;

  admin_pg.fiscal_p(gn_task_code, ln_type,
   'Произведено изменение правил разноски на ГН для ' || util_pg.node_path_f(an_owner, 'points', 'mid', 'parent') || ' с ' || TO_CHAR(ad_start, 'dd.mm.yyyy'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'operatingday_pg.upd_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

----------------------------------------------------------------
    -- Удаление
 PROCEDURE del_p(an_owner NUMBER, ad_start DATE) IS
 BEGIN
  DELETE FROM operatingday
  WHERE       nowner = an_owner AND dstart = ad_start;

  IF SQL%ROWCOUNT > 0 THEN
   admin_pg.fiscal_p(gn_task_code, 3,
    'Произведено удаление правила разноски на ГН для ' || util_pg.node_path_f(an_owner, 'points', 'mid', 'parent') || ' с ' || TO_CHAR(ad_start, 'dd.mm.yyyy'));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'operatingday_pg.del_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
-------------------------------------------------------------------------------------------
END;                                                                                                                                 -- Package Body switchts_pg
/


-- End of DDL Script for Package Body RYDA.OPERATINGDAY_PG

