CREATE OR REPLACE 
PACKAGE BODY operscan_pg IS
------------------------------------------------------------------------------------------------------------------------
   -- пакет работы со схемами оперативного опроса и оперативным опросом
   -- дата создания 01/02/2004 (Сечин А.А.)
 gn_task_code        constant NUMBER :=505;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_p(av_name VARCHAR2,                                                                                                             --название схемы
                                  at_cid common_pg.tt_number, an_operscanschemas OUT NUMBER) IS
  ln_ret              NUMBER;
 BEGIN
  SAVEPOINT operscan_ins;
  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлена схема оперативного опроса ' || av_name);

  SELECT roles_seq.NEXTVAL
  INTO   ln_ret
  FROM   DUAL;

  INSERT INTO operscanschemas
              (noperscanschemas, vname)
  VALUES      (ln_ret, av_name);

  IF at_cid.COUNT > 0 AND at_cid(1) <> 0 THEN
   FOR i IN 1 .. at_cid.COUNT LOOP
    INSERT INTO schemchannels
                (noperscanschemas, cid)
    VALUES      (ln_ret, at_cid(i));

    admin_pg.fiscal_p(gn_task_code, 1,
     ' В схему оперативного опроса ' || av_name || ' добавлен канал ' || util_pg.node_path_f(at_cid(i), 'points', 'mid', 'parent'));
   END LOOP;
  END IF;

  an_operscanschemas := ln_ret;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT operscan_ins;
   raise_application_error(-20001, 'operscan_pg.ins_p: Ошибка вставки схемы оперативного опроса. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE upd_p(an_operscanschemas NUMBER,                                                                                                           --Ид схемы
                                           av_name VARCHAR2,                                                                                    --название схемы
                                                            at_cid common_pg.tt_number) IS
  lv_name             VARCHAR2(200);
 BEGIN
  SAVEPOINT operscan_upd;

  SELECT vname
  INTO   lv_name
  FROM   operscanschemas
  WHERE  noperscanschemas = an_operscanschemas;

  IF lv_name <> av_name THEN
   lv_name := lv_name || ' - ' || av_name;
  END IF;

  admin_pg.fiscal_p(gn_task_code, 2, ' Изменены параметры схемы оперативного опроса ' || lv_name);
  lv_name := av_name;

  UPDATE operscanschemas
  SET vname = av_name
  WHERE  noperscanschemas = an_operscanschemas;

  DELETE FROM schemchannels
  WHERE       noperscanschemas = an_operscanschemas;

  IF at_cid.COUNT > 0 AND at_cid(1) <> 0 THEN
   FOR i IN 1 .. at_cid.COUNT LOOP
    INSERT INTO schemchannels
                (noperscanschemas, cid)
    VALUES      (an_operscanschemas, at_cid(i));

    admin_pg.fiscal_p(gn_task_code, 1,
     ' В схему оперативного опроса ' || lv_name || ' добавлен канал ' || util_pg.node_path_f(at_cid(i), 'points', 'mid', 'parent'));
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT operscan_upd;
   raise_application_error(-20001, 'operscan_pg.upd_p: Ошибка обновления схемы оперативного опроса. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_p(an_operscanschemas NUMBER                                                                                                            --Ид схемы
                                          ) IS
  lv_name             VARCHAR2(200);
 BEGIN
  SELECT vname
  INTO   lv_name
  FROM   operscanschemas
  WHERE  noperscanschemas = an_operscanschemas;

  admin_pg.fiscal_p(gn_task_code, 3, ' Удалена схема оперативного опроса ' || lv_name);

  DELETE FROM operscanschemas
  WHERE       noperscanschemas = an_operscanschemas;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE active_p(an_cid NUMBER,                                                                                                                   --Ид канала
                                  ad_end DATE,                                                                                                  --дата окончания
                                              an_cycle_tout NUMBER) IS
  ln_protocol         NUMBER;
 BEGIN
  SELECT MAX(protocol_id)
  INTO   ln_protocol
  FROM   channels
  WHERE  cid = an_cid;

  IF comsrvdisp_pg.is_client_canal(ln_protocol) = 0 AND ln_protocol NOT IN(comsrvdisp_pg.cn_mtxprotocol) THEN
   raise_application_error(-20001, 'Запуск оперативного опроса для канала серверного типа запрещен.');
  END IF;

  admin_pg.fiscal_p(gn_task_code, 2,
      'Запущен оперативный опрос по каналу '
   || util_pg.node_path_f(an_cid, 'points', 'mid', 'parent')
   || ' Дата окончания '
   || TO_CHAR(SYSDATE, 'dd.mm.yyyy ')
   || TO_CHAR(ad_end, 'hh24:mi:ss')
   || ' Период опроса '
   || an_cycle_tout
   || ' сек.');

  --Для незапущенных каналов nvl(nkind,0) <> 100;
  UPDATE channels
  SET cycle_tout2 = DECODE(NVL(nkind, 0), 0, cycle_tout, cycle_tout2),
      blocking2 = DECODE(NVL(nkind, 0), 0, blocking, blocking2),
      dstart2 = DECODE(NVL(nkind, 0), 0, dstart, dstart2),
      dend2 = DECODE(NVL(nkind, 0), 0, dend, dend2),
      nparent2 = DECODE(NVL(nkind, 0), 0, nparent, nparent2),
      nnotreadcurr2 = DECODE(NVL(nkind, 0), 0, nnotreadcurr, nnotreadcurr2),
      dstart = SYSDATE,
      dend = ad_end,
      cycle_tout = an_cycle_tout,
      blocking = 0,
      nparent = NULL,
      nnotreadcurr = 0,
      nkind = 100,
      ndelivered = 0,
      vuser = user
  WHERE  cid = an_cid AND NVL(nkind, 0) <> 100;

  --Для запущенных каналов nkind = 100;
  UPDATE channels
  SET dstart = SYSDATE,
      dend = ad_end,
      cycle_tout = an_cycle_tout,
      vuser = user
  WHERE  cid = an_cid AND nkind = 100;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE deactive_p(an_cid NUMBER                                                                                                                  --Ид канала
                                   ) IS
 BEGIN
  admin_pg.fiscal_p(gn_task_code, 2, 'Остановлен оперативный опрос по каналу ' || util_pg.node_path_f(an_cid, 'points', 'mid', 'parent'));

  UPDATE channels
  SET nkind = 0,
      vuser = NULL,
      cycle_tout = cycle_tout2,
      blocking = blocking2,
      dstart = dstart2,
      dend = dend2,
      nparent = nparent2,
      nnotreadcurr = nnotreadcurr2
  WHERE  cid = an_cid AND nkind = 100;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_chquery(acur_t OUT common_pg.tcur) IS
 -- A.G.Kondakov created 29.07.2008
 -- используется в ASKUEADM TFormOperScanSchList
 BEGIN
  OPEN acur_t FOR
   SELECT   c.cid, c.vname cname, 0 scid, c.blocking
   FROM     channels c
   ORDER BY 2;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_oqchannels(an_noperscanschemas NUMBER, acur_t OUT common_pg.tcur) IS
 -- A.G.Kondakov created 29.07.2008
 -- используется в ASKUEADM TFormOperScanSchList::TreeViewSchemChange
 BEGIN
  OPEN acur_t FOR
   SELECT cid
   FROM   schemchannels
   WHERE  noperscanschemas = an_noperscanschemas;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_parameters(av_sort NUMBER, av_desc NUMBER, acur_t OUT common_pg.tcur) IS
  -- A.G.Kondakov created 29.07.2008
  -- используется в ASKUEADM TfmParam
  --edited 21.01.2009 by Kruglova M.O.
  lv_sql              VARCHAR2(4000);
 BEGIN
  IF av_sort IS NOT NULL THEN
   lv_sql := 'SELECT * FROM parameter order by ' || av_sort;

   IF av_desc = 1 OR av_desc IS NULL THEN
    lv_sql := 'SELECT * FROM parameter order by ' || av_sort || ' asc, ';
   ELSE
    lv_sql := 'SELECT * FROM parameter order by ' || av_sort || ' desc, ';
   END IF;
  ELSE
   lv_sql := 'SELECT * FROM parameter order by ';
  END IF;

  lv_sql := lv_sql || '1';

  OPEN acur_t FOR lv_sql;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_channel_points(an_id NUMBER, acur_t OUT common_pg.tcur) IS
 -- added 06.08.2008 Kondakov A.G.
 -- Запрос для выбора точек канала
 BEGIN
  OPEN acur_t FOR
   SELECT   c.mid, util_pg.get_pointname(p.mid, 3, 0) pname, p.NAME
   FROM     chanpoint c, points p
   WHERE    c.cid = an_id AND c.mid = p.mid
   ORDER BY pname, p.NAME;
 /*  SELECT c.mid,p1.NAME pname,p.NAME
   FROM chanpoint c, points p, points p1
   WHERE c.cid=an_id AND c.mid=p.mid AND p.parent = p1.mid(+)
   ORDER BY p1.NAME, p.NAME;*/
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_channels_for_role(an_sch_id NUMBER, acur_t OUT common_pg.tcur, an_filter_mid NUMBER, av_orderstr VARCHAR2, an_pointid NUMBER) IS
  -- added 06.08.2008 Kondakov A.G.
  -- Формируем массив каналов для текущей роли
  lv_sql              VARCHAR2(2000);
  lv_orderstr         VARCHAR2(1000);
  lv_subsel           VARCHAR2(1000);
 BEGIN
  IF LOWER(av_orderstr) LIKE '%com_id%' THEN
   lv_orderstr := 'c.' || TRIM(av_orderstr);
  ELSE
   lv_orderstr := av_orderstr;
  END IF;

  IF LOWER(lv_orderstr) NOT LIKE '%vname%' THEN
   lv_orderstr := lv_orderstr || ' ,vname';
  END IF;

  IF (an_pointid <> util_pg.cn_pntmid) THEN
   lv_subsel :=
       ' and c.cid in (select h.cid from chanpoint h where h.mid in (select p.mid from points p
                connect by prior p.mid=p.parent start with p.mid='
    || an_pointid
    || ' )) ';
  ELSE
   lv_subsel := ' ';
  END IF;

  lv_sql :=
      ' SELECT rownum-1 rn, s.cid, c.vname vname, to_char( c.dstart, ''hh24:mi'' ) dstart, to_char( c.dend, ''hh24:mi'' ) dend,
              c.cycle_tout, u.name vuser, c.nready, nvl(c.nkind, 0) nkind, c.blocking, c.nparent,
              c.nnotreadcurr, c.retries, c.retries_tout, c.nbilldata, nvl(c.nbilldatadepth,0) nbilldatadepth,
              c.ncurrdata, nvl(c.ncurrdatadepth,0) ncurrdatadepth, ''COM''||c.COM_ID com_id,
              decode(c.is_dead,NULL,1,0) is_dead,pr.name prname
       FROM schemchannels s, channels c, protocols pr,users u
       WHERE s.noperscanschemas='
   || an_sch_id
   || ' AND s.cid = c.cid AND c.protocol_id=pr.protocol_id(+) and c.vuser=u.usr(+)
             AND c.cid IN (SELECT pn.mid FROM points pn
                            START WITH pn.mid = '
   || an_filter_mid
   || '
                            CONNECT BY pn.parent = PRIOR pn.mid) '
   || lv_subsel
   || ' ORDER BY '
   || lv_orderstr;

  OPEN acur_t FOR lv_sql;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_channels_for_shema(an_role_id NUMBER, acur_t OUT common_pg.tcur) IS
 -- added 06.08.2008 Kondakov A.G.
 -- Формирование таблицы каналов для данной схемы
 BEGIN
  OPEN acur_t FOR
   SELECT NVL(noperscanschemas, '') currscanschid
   FROM   ROLES
   WHERE  role_id = an_role_id;
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                             -- Package Body
/


