CREATE OR REPLACE 
PACKAGE BODY orderformula_pg AS
-------------------------------------------------------------------------------
 FUNCTION check_cycle_formula
  RETURN NUMBER;

---------------------------------------------------------------------------
 FUNCTION check_formula
  RETURN NUMBER;

-------------------------------------------------------------------------------
 PROCEDURE order_formula IS
  pformulaa           strarray := strarray();
  fresulta            numarray := numarray();
  fida                numarray := numarray();
  nid_out             numarray := numarray();
  nid_in              numarray := numarray();
  norder              numarray := numarray();
  norder1             numarray := numarray();
  ln_ret              NUMBER;
  lv_mess             VARCHAR2(2000);
 BEGIN
-- ln_ret := check_cycle_formula;  --Проверка зацикливания выполняется в C++ коде - поэтомуц закоментировали
  IF ln_ret > 0 THEN
   raise_application_error(-20001, 'Обнаружено зацикливание формул для параметра Ид.=' || ln_ret);
  END IF;

  /* SELECT  tt.mid ,t.mid
   BULK COLLECT INTO nid_out, nid_in
   FROM formulparams t,pointformula tt
   where  t.nid=tt.nid and tt.mid>0
   order by tt.norder,t.norder;*/
  SELECT DISTINCT mm.PARENT, mm.mid, mm.nn, mm.nn2
  BULK COLLECT INTO nid_out, nid_in, norder, norder1
  FROM            (SELECT   tt.mid PARENT, t.mid, tt.norder nn, t.norder nn2
                   FROM     formulparams t, pointformula tt 
                   WHERE    t.nid = tt.nid AND tt.mid > 0 AND t.nshift > -24 and tt.mid in (select mid from feeders where ncalcpointtype=CALCFORMULA_PG.cn_cpt_formula)
                   UNION ALL
                   SELECT   kk.mid, ll.mid, kk.nn, kk.nn2
                   FROM     (SELECT p.mid, util_pg.allnumber_f(TRIM(util_pg.get_param(f.vparam, 2, '.'))) param, p.norder nn, f.norder nn2
                             FROM   pointformula p, formulparams f
                             WHERE  p.nid = f.nid AND f.mid IS NULL and p.mid in (select mid from feeders where ncalcpointtype=CALCFORMULA_PG.cn_cpt_formula)) kk,
                            (SELECT     DECODE(
                                         LEVEL,
                                         1, PARENT,
                                         SUBSTR(SYS_CONNECT_BY_PATH(PARENT, '/'), 2, INSTR(SYS_CONNECT_BY_PATH(PARENT, '/'), '/', 2) - 2)
                                        ) nparent,
                                        mid
                             FROM       GROUPS
                             CONNECT BY PRIOR gid = PARENT
                             START WITH PARENT IN(SELECT util_pg.allnumber_f(TRIM(util_pg.get_param(t.vparam, 2, '.')))
                                                  FROM   formulparams t
                                                  WHERE  t.mid IS NULL)) ll
                   WHERE    kk.param = ll.nparent AND ll.mid IS NOT NULL
                   UNION ALL
                   SELECT   p.PARENT, p.mid, g.norder, g.norder
                   FROM     points p, greenpoint g
                   WHERE    p.PARENT = g.mid AND g.ntype = 1
                   UNION ALL
                   SELECT   op.nowner, tt.mid, gr.norder nn, gr.norder nn2
                   FROM     operatingday op,
                            greenpoint gr,
                            (SELECT     DECODE(
                                         LEVEL,
                                         1, PARENT,
                                         SUBSTR(SYS_CONNECT_BY_PATH(PARENT, '/'), 2, INSTR(SYS_CONNECT_BY_PATH(PARENT, '/'), '/', 2) - 2)
                                        ) nparent,
                                        gid, mid
                             FROM       GROUPS
                             WHERE      mid IS NOT NULL
                             CONNECT BY PRIOR gid = PARENT
                             START WITH PARENT IN(SELECT o.gid
                                                  FROM   operatingday o,
                                                         (SELECT     mid
                                                          FROM       points ps
                                                          CONNECT BY PRIOR PARENT = mid
                                                          START WITH mid IN(SELECT f.mid
                                                                            FROM   greenpoint f
                                                                            WHERE  f.ntype = 2)) ow
                                                  WHERE  o.nowner = ow.mid AND o.gid IS NOT NULL)) tt
                   WHERE    op.gid = tt.nparent AND gr.mid = op.nowner
                   UNION ALL
                   SELECT   o.nowner, o.mid, grn.norder nn, grn.norder nn2
                   FROM     operatingday o,
                            greenpoint grn,
                            (SELECT     mid
                             FROM       points ps
                             CONNECT BY PRIOR PARENT = mid
                             START WITH mid IN(SELECT f.mid
                                               FROM   greenpoint f
                                               WHERE  f.ntype = 2)) ow
                   WHERE    o.nowner = ow.mid AND grn.mid = o.nowner AND o.gid IS NULL
                   ORDER BY nn, nn2) mm
                   ORDER BY nn, nn2;

  /* SELECT   mid, mid, vformula
    BULK COLLECT INTO fresulta,fida,pformulaa
       FROM pointformula
   ORDER BY norder;*/
  SELECT   p.mid, p.mid, p.vformula, p.norder nn
  BULK COLLECT INTO fresulta, fida, pformulaa, norder
  FROM     pointformula p where p.mid in (select mid from feeders where ncalcpointtype=CALCFORMULA_PG.cn_cpt_formula)
  UNION ALL
  SELECT   g.mid, g.mid, '1', g.norder
  FROM     greenpoint g
  ORDER BY nn;

  IF fida.COUNT = 0 THEN
   RETURN;
  END IF;

  ln_ret := parser_pg.order_formula(fida, fresulta, pformulaa, nid_out, nid_in);

  IF ln_ret = 6 AND fida.COUNT > 0 THEN
   lv_mess := 'Обнаружено зацикливание формул для параметра Ид.=' || fida(1) || '; Всего зацикливаний: ' || fida.COUNT || ';';

   FOR i IN 2 .. LEAST(fida.COUNT, 5) LOOP
    lv_mess := lv_mess || ' Ид' || i || '=' || fida(i) || ';';
   END LOOP;

   raise_application_error(-20001,lv_mess);
  END IF;

  FOR i IN 1 .. fresulta.COUNT LOOP
   UPDATE pointformula
   SET norder = i
   WHERE  mid = fresulta(i);

   IF SQL%ROWCOUNT = 0 THEN
    UPDATE greenpoint
    SET norder = i
    WHERE  mid = fresulta(i);
   END IF;
  -- dbms_output.put_line (i||','||fidA(i));
  END LOOP;

  FOR lc IN (SELECT nid
             FROM   pointformula                                                                                                      --для формул с константами
             MINUS
             SELECT nid
             FROM   formulparams) LOOP
   UPDATE pointformula
   SET norder = 0
   WHERE  nid = lc.nid;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'order_formula: Order Formula Error ' || CHR(10) || SQLERRM(SQLCODE));
 END;

-------------------------------------------------------------------------------------------------
 FUNCTION check_cycle_formula                                                                                                                         --короткая
  RETURN NUMBER IS
  ln_tmp              NUMBER;
 BEGIN
  SELECT     MAX(nid)
  INTO       ln_tmp
  FROM       (SELECT DISTINCT tt.mid, util_pg.allnumber_f(util_pg.get_param(t.vparam, 2, '.')) param, t.nid
              FROM            formulparams t, pointformula tt
              WHERE           tt.nid = t.nid) mm
  CONNECT BY PRIOR mm.param = mm.mid
  START WITH mm.mid IN(SELECT DISTINCT mid
                       FROM            pointformula);

  RETURN 0;
 EXCEPTION
  WHEN OTHERS THEN
   IF SQLCODE = -1436 THEN                                                                                                   --connect by в данных пользователя
    ln_tmp := check_formula;
    RETURN ln_tmp;
   END IF;

   RAISE;
 END;

------------------------------------------------------------------------------------------------------
 FUNCTION check_formula                                                                                                                                --длинная
  RETURN NUMBER IS
  ln_tmp              NUMBER;
 BEGIN
  FOR lc IN (SELECT DISTINCT mid
             FROM            pointformula) LOOP
   ln_tmp := lc.mid;

   SELECT     MAX(nid)
   INTO       ln_tmp
   FROM       (SELECT DISTINCT tt.mid, util_pg.allnumber_f(util_pg.get_param(t.vparam, 2, '.')) param, t.nid
               FROM            formulparams t, pointformula tt
               WHERE           tt.nid = t.nid) mm
   CONNECT BY PRIOR mm.param = mm.mid
   START WITH mm.mid = lc.mid;
  END LOOP;

  RETURN 0;
 EXCEPTION
  WHEN OTHERS THEN
   IF SQLCODE = -1436 THEN                                                                                                   --connect by в данных пользователя
    RETURN ln_tmp;
   END IF;

   RAISE;
 END;
------------------------------------------------------------------------------------------------------
END;
/


