    IF (i!=0) THEN	
	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
	dbms_output.put_line('error deleting RangeToken');
	dbms_output.put_line(error_description);
	dbms_output.put_line(error_helpfile);
	END IF; 
    dbms_output.put_line('deleting border_token='||border_token);
    i:=ORDCOM.DestroyObject(border_token);
    IF (i!=0) THEN	
	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
	dbms_output.put_line('error deleting border_token');
	dbms_output.put_line(error_description);
	dbms_output.put_line(error_helpfile);
	END IF;  
    dbms_output.put_line('deleting font_token='||font_token);
    i:=ORDCOM.DestroyObject(font_token);
    IF (i!=0) THEN	
	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
	dbms_output.put_line('error deleting font_token');
	dbms_output.put_line(error_description);
	dbms_output.put_line(error_helpfile);
	END IF;
    dbms_output.put_line('deleting columns_token='||columns_token);
    i:=ORDCOM.DestroyObject(columns_token);
    IF (i!=0) THEN	
	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
	dbms_output.put_line('error deleting columns_token');
	dbms_output.put_line(error_description);
	dbms_output.put_line(error_helpfile);
	END IF;   
    

	i:=ORDCOM.DestroyObject(applicationToken);
	IF (i!=0) THEN	
	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
	dbms_output.put_line(error_src);
	dbms_output.put_line(error_description);
	dbms_output.put_line(error_helpfile);
	END IF;
	i:=ORDCOM.DestroyObject(ChartObjectToken);
	i:=ORDCOM.DestroyObject(Chart1Token);
	i:=ORDCOM.DestroyObject(ChartObject1);
	i:=ORDCOM.DestroyObject(dummyToken);
	RETURN i;
END ExitExcel;
