 -- устанавливает границы для указанного диапазона
 FUNCTION SetRangeBorders (fromcell VARCHAR, tocell VARCHAR, borders VARCHAR, line_weight NUMBER, line_style NUMBER)
  RETURN BINARY_INTEGER IS 
/* borders = '00000000' где 1 в позиции номер
                        1,'xlEdgeBottom'=9, 
                        2,'xlEdgeLeft'=7, 
                        3,'xlEdgeTop'=8, 
                        4,'xlEdgeRight'=10, 
                        5,'xlInsideVertical'=11, 
                        6,'xlInsideHorizontal'=12, 
                        7,'xlDiagonalUp'=6, 
                        8,'xlDiagonalDown'=5
   line_weight = {2-xlThin 3-xlMedium 4-xlThick}
   line_style = {1-xlContinuous 9-xlDouble } */
  border_type         NUMBER := 0;
 BEGIN
	ORDCOM.InitArg();
	ORDCOM.SetArg(fromcell, 'BSTR');
	ORDCOM.SetArg(tocell, 'BSTR');
	i:=ORDCOM.GetProperty(WorkSheetToken, 'Range', 2, RangeToken);
    dbms_output.put_line('RangeToken='||RangeToken);
  
    FOR n IN 1..length(borders) LOOP
      SELECT decode(n,
                    1,9,
                    2,7,
                    3,8,
                    4,10,
                    5,11,
                    6,12,
                    7,6,
                    8,5,  
                    0) INTO border_type FROM dual;
      IF border_type <> 0 THEN
          -- получение границы нужного типа
          ORDCOM.InitArg();
          ORDCOM.SetArg(border_type, 'I2');
          i:=ORDCOM.GetProperty(RangeToken, 'Borders', 1, border_token);
          dbms_output.put_line(n||' border_token='||border_token);
            
          IF SUBSTR(borders,n,1) = '1' THEN          
              -- выставляем толщину линии
              IF line_weight IS NOT NULL THEN
                  i:=ORDCOM.SetProperty(border_token, 'Weight', line_weight, 'I2');
                  IF ( i != 0 ) THEN
                  dbms_output.put_line('ERROR! ');
                    	  ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
                    	  dbms_output.put_line(error_src);
                    	  dbms_output.put_line(error_description);
                    	  dbms_output.put_line(error_helpfile);
                  END IF; 
                  dbms_output.put_line('Setting Range('||fromcell||':'||tocell||').Borders('||border_type||').Weight='||line_weight);	
              END IF;
              -- выставляем стиль линии
              IF line_style IS NOT NULL THEN
                  i:=ORDCOM.SetProperty(border_token, 'LineStyle', line_style, 'I2');
                  dbms_output.put_line('Setting Range('||fromcell||':'||tocell||').Borders('||border_type||').LineStyle='||line_style);	
              END IF;
          END IF;   
          dbms_output.put_line('deleting border_token='||border_token);
          i:=ORDCOM.DestroyObject(border_token); 
          IF (i!=0) THEN	
          	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
        	dbms_output.put_line('error deleting border_token');
        	dbms_output.put_line(error_description);
        	dbms_output.put_line(error_helpfile);
          END IF;
      END IF;   
      
    END LOOP;
    dbms_output.put_line('deleting RangeToken='||RangeToken);
    i:=ORDCOM.DestroyObject(RangeToken); 
    IF (i!=0) THEN	
	ORDCOM.GetLastError(error_src, error_description, error_helpfile, error_helpID);
	dbms_output.put_line('error deleting RangeToken');
	dbms_output.put_line(error_description);
	dbms_output.put_line(error_helpfile);
	END IF;

    RETURN i;
 END;
