 FUNCTION getparsererror
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "GetParserError"
  LIBRARY parser;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION getparsererrortext(an_err PLS_INTEGER DEFAULT NULL)
  RETURN VARCHAR2 IS
  ln_err              PLS_INTEGER DEFAULT NVL(an_err, getparsererror);
 BEGIN
  IF ln_err = 1 THEN
   RETURN 'Неправильный HANDLER экземпляра формулы';
  ELSIF ln_err = 2 THEN
   RETURN 'Ошибка в синтаксисе формулы';
  ELSIF ln_err = 3 THEN
   RETURN 'В формуле использован неизвестный аргумент';
  ELSIF ln_err = 4 THEN
   RETURN 'Неверное значение аргумента';
  ELSIF ln_err = 5 THEN
   RETURN 'Недостаточно памяти';
  END IF;

  RETURN 'Неизвестная ошибка. Код: ' || ln_err;
 END;

