 FUNCTION setvars(idexpr BINARY_INTEGER, val IN OUT DOUBLE PRECISION)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "SetVars"
  LIBRARY parser
  PARAMETERS(
   idexpr INT,
   val DOUBLE
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION setvarsora(idexpr BINARY_INTEGER, fresultarr IN numarray)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "SetVarsOra"
  LIBRARY parser
  WITH CONTEXT
  PARAMETERS(
   idexpr INT,
   CONTEXT,
   fresultarr ocicoll
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION parser_proc(expr VARCHAR2, RESULT OUT NUMBER)
  RETURN NUMBER IS
  idexpr              NUMBER;                                                                                                                  -- Id Expression
  varcount            NUMBER;                                                                                                  -- Count  expression's variables
  varname             t;                                                                                                      -- array of expressions variables
  val                 n;                                                                                               -- array of expressions variables values
  v                   NUMBER;                                                                                                     -- expressions variable value
  error               NUMBER;                                                                                                                  -- execute error
 BEGIN
  idexpr := newexpression(expr);
  varcount := getnbusedvars(idexpr);

  FOR j IN 0 .. varcount - 1 LOOP
   varname(j) := ' ';
   error := getusedvar(idexpr, j, varname(j), 256);
  END LOOP;

  FOR i IN 1 .. 10000 LOOP
   --    получить значения параметров формулы
   FOR j IN 0 .. varcount - 1 LOOP
    val(j) := j * 10 + 10;
   END LOOP;

   FOR i IN 0 .. varcount - 1 LOOP
    v := val(i);
    error := setvar(idexpr, i, varname(i), v);
   END LOOP;

   error := evaluate(idexpr, RESULT);
  END LOOP;

  RETURN error;
 END;

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION order_formula(fidarr IN OUT numarray, fresultarr IN OUT numarray, pformulaarr IN OUT strarray, noutarr IN numarray, ninarr IN numarray)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "OrderFormula"
  LIBRARY parser
  WITH CONTEXT
  PARAMETERS(
   CONTEXT,
   fidarr ocicoll,
   fresultarr ocicoll,
   pformulaarr ocicoll,
   noutarr ocicoll,
   ninarr ocicoll
  );
-------------------------------------------------------------------------------------------------------------------------
END;
/


