CREATE OR REPLACE 
PACKAGE BODY pgok_pg IS
------------------------------------------------------------------------------------------------------------------------
--Копирование данных из таблиц с ПГОК в получасовки
 PROCEDURE copy_pgok_data2 (an_maket NUMBER, ad_date DATE) IS
  cn_step   CONSTANT NUMBER          := 1 / 48;
  ld_date            DATE            DEFAULT TRUNC (ad_date - 1);
  ld_tmp             DATE;
  ln_rn              NUMBER          DEFAULT 3;
  lc0                common_pg.tcur;
  lc1                common_pg.tcur;
  ln_val_k           NUMBER;   -- значение выхода в тоннах
  ln_val_u           NUMBER;   -- значение удельного выхода
  ln_val_r           NUMBER;   -- значение расхода в кВт
  ln_mid_k           NUMBER;   -- mid точки с выходом (kонцентратом)
  ln_mid_u           NUMBER;   -- mid соответствующей точки с уд. выходом
  ln_ras_gid         NUMBER;   -- gid секции с расходом, из которой берутся данные
  ln_section         NUMBER;
  ln_section_u       NUMBER;
  lv_table           VARCHAR2 (256);
  lv_sql             VARCHAR2 (2000);
  ln_temp            NUMBER;
 BEGIN
  OPEN lc0 FOR
   SELECT   konc.mid k_mid, konc.vcode k_vcode, ud.mid u_mid, ud.vcode u_vcode, ud.ras_gid ras_gid
       FROM (SELECT mid, util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) vcode
               FROM feeders
              WHERE UPPER (vcode) LIKE 'KONC/_%' ESCAPE '/' AND util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) BETWEEN 1 AND 15) konc,
            (SELECT mid, util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) vcode, util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 3, '_'))
                                                                                                                                                             ras_gid
               FROM feeders
              WHERE UPPER (vcode) LIKE 'UD/_%' ESCAPE '/' AND util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) BETWEEN 1 AND 15) ud
      WHERE konc.vcode = ud.vcode(+)
   ORDER BY k_vcode;

  LOOP
   FETCH lc0
    INTO ln_mid_k, ln_section, ln_mid_u, ln_section_u, ln_ras_gid;

   EXIT WHEN lc0%NOTFOUND;

   DELETE FROM halfhourold
         WHERE mid = ln_mid_k AND date_time > ld_date;

   IF ln_mid_u IS NOT NULL THEN
    DELETE FROM halfhourold
          WHERE mid = ln_mid_u AND date_time > ld_date;
   END IF;

   IF ln_section IS NULL THEN
    raise_application_error (-20001, 'Не найден номер секции в коде точки ' || ln_mid_k);
   END IF;

   IF ln_section BETWEEN 1 AND 8 THEN
    lv_table := ' RYDA_OF1 ';
   ELSIF ln_section BETWEEN 10 AND 15 THEN
    lv_table := ' RYDA_OF2 ';
   ELSE
    raise_application_error (-20001, 'Номер секции в коде точки ' || ln_mid_k || ' выходит за границы возможных.');
   END IF;

   DBMS_OUTPUT.put_line ('----------------- ' || lv_table);

   BEGIN
    lv_sql :=
     'SELECT konc.k_date, konc.k_val, rashod.r_val
                FROM
                (SELECT SUM(util_pg.sld(h.mid,NVL(h.er*DECODE(g.NPARTLY,2,0,1),0),NVL(h.ed*DECODE(g.NPARTLY,1,0,1),0))*DECODE(G.INVERTED,''y'',-1,1)) r_val,
                        trunc(h.date_time-1/86400,''hh24'')+1/24 r_date
                  FROM halfhour h, GROUPS g
                 WHERE :ln_ras_gid IS NOT NULL AND :ln_mid_u IS NOT NULL
                       AND g.gid IN (SELECT gid FROM GROUPS WHERE mid>0 CONNECT BY PRIOR gid=parent START WITH parent=:ln_ras_gid)
                       AND h.mid=g.mid
                       AND h.date_time > :ld_date
                 GROUP BY trunc(h.date_time-1/86400,''hh24'')+1/24
                 ORDER BY r_date DESC) rashod,
                (SELECT orderdate+tekchassm/24 k_date, m_'
     || ln_section || ' k_val FROM ' || lv_table || ' WHERE orderdate > :ld_date) konc
                WHERE konc.k_date=rashod.r_date(+)';

    OPEN lc1 FOR lv_sql USING ln_ras_gid, ln_mid_u, ln_ras_gid, ld_date, ld_date;

    LOOP
     FETCH lc1
      INTO ld_tmp, ln_val_k, ln_val_r;

     EXIT WHEN lc1%NOTFOUND;
     DBMS_OUTPUT.put_line ('ld_date=' || TO_CHAR (ld_date, 'dd.mm.yy hh24:mi:ss') || CHR (13) || ' ln_val_k=' || ln_val_k || ' ln_val_r=' || ln_val_r);

     -- вставка выхода в тоннах
     IF (ln_val_k IS NOT NULL) THEN
      ln_temp := TRUNC (ln_val_k / 2, 0);
      DBMS_OUTPUT.put_line ('вставка первой половины ' || ln_temp || '_точки ' || ln_mid_k);
      das_pg.ins_halfhourtmp (ln_mid_k, util_pg.to_unlocaltime (ld_tmp - 1 / 48), NULL, ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
      ln_temp := ln_val_k - ln_temp;
      DBMS_OUTPUT.put_line ('вставка второй половины ' || ln_temp || '_точки ' || ln_mid_k);
      das_pg.ins_halfhourtmp (ln_mid_k, util_pg.to_unlocaltime (ld_tmp), NULL, ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
      DBMS_OUTPUT.put_line ('конец вставки ВЫВОДА');
     END IF;

     -- подсчет удельного расхода в кВтч/т
     IF ln_val_k IS NOT NULL AND ln_val_r IS NOT NULL AND ln_val_k <> 0 THEN
      ln_val_u := TRUNC (ln_val_r / ln_val_k, ln_rn);
     ELSE
      ln_val_u := NULL;
     END IF;

     DBMS_OUTPUT.put_line (' ln_val_u=' || ln_val_u);

     -- вставка выхода в тоннах
     IF (ln_val_u IS NOT NULL) THEN
      ln_temp := TRUNC (ln_val_u / 2, 0);
      DBMS_OUTPUT.put_line ('_вставка первой половины ' || ln_temp || '_точки ' || ln_mid_u);
      das_pg.ins_halfhourtmp (ln_mid_u, util_pg.to_unlocaltime (ld_tmp - 1 / 48), NULL, ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
      ln_temp := ln_val_u - ln_temp;
      DBMS_OUTPUT.put_line ('_вставка второй половины ' || ln_temp || '_точки ' || ln_mid_u);
      das_pg.ins_halfhourtmp (ln_mid_u, util_pg.to_unlocaltime (ld_tmp), NULL, ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
      DBMS_OUTPUT.put_line ('конец вставки УДЕЛЬНЫХ');
     END IF;
    END LOOP;

    CLOSE lc1;
   EXCEPTION
    WHEN OTHERS THEN
     IF lc1%ISOPEN THEN
      CLOSE lc1;
     END IF;

     DBMS_OUTPUT.put_line ('---------------------------- ЗАЛЕТ! ');
   END;
  END LOOP;

  CLOSE lc0;

  COMMIT;
  das_pg.checkhalfhour;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'PGOK_PG.copy_pgok_data: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE copy_pgok_data (an_maket NUMBER, ad_date DATE) IS
  cn_step   CONSTANT NUMBER          := 1 / 48;
  ld_date            DATE            DEFAULT TRUNC (ad_date - 1);
  ld_tmp             DATE;
  ln_rn              NUMBER          DEFAULT 3;
  lc0                common_pg.tcur;
  lc1                common_pg.tcur;
  ln_val_k           NUMBER;   -- значение выхода в тоннах
  ln_val_u           NUMBER;   -- значение удельного выхода
  ln_val_r           NUMBER;   -- значение расхода в кВт
  ln_mid_k           NUMBER;   -- mid точки с выходом (kонцентратом)
  ln_mid_u           NUMBER;   -- mid соответствующей точки с уд. выходом
  ln_ras_gid         NUMBER;   -- gid секции с расходом, из которой берутся данные
  ln_section         NUMBER;
  ln_section_u       NUMBER;
  lv_table           VARCHAR2 (256);
  lv_sql             VARCHAR2 (2000);
  ln_temp            NUMBER;
 BEGIN
  OPEN lc0 FOR
   SELECT   konc.mid k_mid, konc.vcode k_vcode, ud.mid u_mid, ud.vcode u_vcode, ud.ras_gid ras_gid
       FROM (SELECT mid, util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) vcode
               FROM feeders
              WHERE UPPER (vcode) LIKE 'KONC/_%' ESCAPE '/' AND util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) BETWEEN 1 AND 15) konc,
            (SELECT mid, util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) vcode, util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 3, '_'))
                                                                                                                                                             ras_gid
               FROM feeders
              WHERE UPPER (vcode) LIKE 'UD/_%' ESCAPE '/' AND util_pg.allnumber_f (util_pg.get_param (TRIM (vcode), 2, '_')) BETWEEN 1 AND 15) ud
      WHERE konc.vcode = ud.vcode(+)
   ORDER BY k_vcode;

  LOOP
   FETCH lc0
    INTO ln_mid_k, ln_section, ln_mid_u, ln_section_u, ln_ras_gid;

   EXIT WHEN lc0%NOTFOUND;

   IF ln_section IS NULL THEN
    raise_application_error (-20001, 'Не найден номер секции в коде точки ' || ln_mid_k);
   END IF;

   IF ln_section BETWEEN 1 AND 8 THEN
    lv_table := ' RYDA_OF1 ';
   ELSIF ln_section BETWEEN 10 AND 15 THEN
    lv_table := ' RYDA_OF2 ';
   ELSE
    raise_application_error (-20001, 'Номер секции в коде точки ' || ln_mid_k || ' выходит за границы возможных.');
   END IF;

   BEGIN
    lv_sql :=
     'SELECT konc.k_date, konc.k_val, rashod.r_val
                FROM
                (SELECT SUM(util_pg.sld(h.mid,NVL(h.er*DECODE(g.NPARTLY,2,0,1),0),NVL(h.ed*DECODE(g.NPARTLY,1,0,1),0))*DECODE(G.INVERTED,''y'',-1,1)) r_val,
                        trunc(h.date_time-1/86400,''hh24'')+1/24 r_date
                  FROM halfhour h, GROUPS g
                 WHERE :ln_ras_gid IS NOT NULL AND :ln_mid_u IS NOT NULL
                       AND g.gid IN (SELECT gid FROM GROUPS WHERE mid>0 CONNECT BY PRIOR gid=parent START WITH parent=:ln_ras_gid)
                       AND h.mid=g.mid
                       AND h.date_time > :ld_date
                 GROUP BY trunc(h.date_time-1/86400,''hh24'')+1/24
                 ORDER BY r_date DESC) rashod,
                (SELECT (case when tekchassm in (21,22,23) then orderdate-1            
                                                           else orderdate end) + tekchassm/24 k_date, 
                        m_'
     || ln_section || ' k_val FROM ' || lv_table || ' WHERE orderdate > :ld_date) konc
                WHERE konc.k_date=rashod.r_date(+)';

    OPEN lc1 FOR lv_sql USING ln_ras_gid, ln_mid_u, ln_ras_gid, ld_date, ld_date;

    LOOP
     FETCH lc1
      INTO ld_tmp, ln_val_k, ln_val_r;

     EXIT WHEN lc1%NOTFOUND;

     -- вставка выхода в тоннах
     IF (ln_val_k IS NOT NULL) THEN
      ln_temp := TRUNC (ln_val_k / 2, 0);
      calcformula_pg.ins_halfhouroldw (ln_mid_k, util_pg.to_unlocaltime (ld_tmp - 1 / 48), ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
      ln_temp := ln_val_k - ln_temp;
      calcformula_pg.ins_halfhouroldw (ln_mid_k, util_pg.to_unlocaltime (ld_tmp), ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

      IF ln_val_k <> 0 THEN
       UPDATE curr_power
          SET er = ln_val_k,
              date_time = ld_tmp
        WHERE mid = ln_mid_k AND date_time < ld_tmp;
      END IF;
     END IF;

     -- подсчет удельного расхода в кВтч/т
     IF ln_val_k = 0 THEN
      ln_val_u := 0;
     ELSE
      ln_val_u := TRUNC (ln_val_r / ln_val_k, ln_rn);
     END IF;

     -- вставка выхода в тоннах
     IF (ln_val_u IS NOT NULL) THEN
      ln_temp := TRUNC (ln_val_u / 2, 0);
      calcformula_pg.ins_halfhouroldw (ln_mid_u, util_pg.to_unlocaltime (ld_tmp - 1 / 48), ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
      ln_temp := ln_val_u - ln_temp;
      calcformula_pg.ins_halfhouroldw (ln_mid_u, util_pg.to_unlocaltime (ld_tmp), ln_temp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

      IF ln_val_u <> 0 THEN
       UPDATE curr_power
          SET er = ln_val_u,
              date_time = ld_tmp
        WHERE mid = ln_mid_u AND date_time < ld_tmp;
      END IF;
     END IF;
    END LOOP;

    CLOSE lc1;
   EXCEPTION
    WHEN OTHERS THEN
     IF lc1%ISOPEN THEN
      CLOSE lc1;
     END IF;
--dbms_output.put_line('---------------------------- ЗАЛЕТ! ');
   END;
  END LOOP;

  CLOSE lc0;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'PGOK_PG.copy_pgok_data: ' || SQLERRM (SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_pline_loss (ad_start DATE, an_mid NUMBER, an_etype NUMBER)
  RETURN NUMBER IS
  ln_ret        NUMBER := 0;
  ln_er         NUMBER;
  ln_q1         NUMBER;
 BEGIN
  -- edited by KAG 17.03.2010
  /*IF an_act = 1 THEN -- потери актива
      SELECT sum(nvl((power(er+ed,2) + power(q1+q2+q3+q4,2)) * cp.nro * cp.nl / (0.5*cp.nun*cp.nun*100000),0)) 
        INTO ln_ret
        FROM billorg b, connectionparam cp
        WHERE b.mid = an_mid
        AND b.date_time = trunc(ad_start)
        AND b.mid=cp.mid;
  ELSIF an_act = 0 THEN -- потери реактива  
      SELECT sum(nvl((power(er+ed,2) + power(q1+q2+q3+q4,2)) * cp.nxo * cp.nl / (0.5*cp.nun*cp.nun*100000),0)) 
        INTO ln_ret
        FROM billorg b, connectionparam cp
        WHERE b.mid = an_mid
        AND b.date_time = trunc(ad_start)
        AND b.mid=cp.mid;
  END IF;*/ 
  SELECT nvl(sum(er*kc),0), nvl(sum(q1*kc),0)
        INTO ln_er, ln_q1 
        FROM (SELECT erm - (lag(erm,1) over (ORDER BY date_time)) er, 
                     q1m - (lag(q1m,1) over (ORDER BY date_time)) q1,
                     f.kc
                FROM billorg b, feeders f
               WHERE b.mid = an_mid
                     AND (b.date_time = trunc(ad_start) OR b.date_time = trunc(ad_start)+1)
                     AND b.mid=f.mid);  
  
  IF an_etype = 1 THEN -- потери актива      
      SELECT max(nvl((ln_er*ln_er + ln_q1*ln_q1) * cp.nro * cp.nl * 0.001 / (cp.nun*cp.nun*24),0)) 
        INTO ln_ret
        FROM connectionparam cp
       WHERE cp.mid = an_mid;
  ELSIF an_etype = 0 THEN -- потери реактива  
      SELECT max(nvl((ln_er*ln_er + ln_q1*ln_q1) * cp.nxo * cp.nl * 0.001 / (cp.nun*cp.nun*24),0)) 
        INTO ln_ret
        FROM connectionparam cp
       WHERE cp.mid = an_mid;
  END IF;
  RETURN ln_ret;
 END; 
------------------------------------------------------------------------------------------------------------------------
  -- Enter further code below as specified in the Package spec.
END;
/


