CREATE OR REPLACE 
PACKAGE BODY plsql1_pg IS
  ------------------------------------------------------------------------------------------------------------------------
    -- пакет по созданию отчетов в файл
    -- дата создания 27/07/2002 Сечин А.А.
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE report1_p IS
  CURSOR lcur_sel IS
   SELECT     mid, DECODE(inverted, 'y', 1, 0) inv, npartly, nfromperiod, ntillperiod
         FROM GROUPS
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
   START WITH gid = filereport_pg.gn_group;
  CURSOR lcur_sel1(lc_mid NUMBER, lc_inv NUMBER, lc_partly NUMBER, lc_nfromperiod NUMBER, lc_ntillperiod NUMBER) IS
   SELECT   TRUNC(
             TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800) +
            1 dt,
            SUM(
             DECODE(
              lc_inv, 1, -util_pg.sld(
                           mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                                          ed * DECODE(lc_partly, 1, 0, 1), 0)),
              util_pg.sld(
               mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                              ed * DECODE(lc_partly, 1, 0, 1), 0))) *
             DECODE(SIGN(TRUNC(date_time) - TO_DATE(NVL(lc_nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(lc_ntillperiod, 299912), 'yyyymm')) + 1) - date_time), -1, NULL, 1)) *
            2
              er
       FROM halfhour
      WHERE mid = lc_mid AND date_time > filereport_pg.gd_from AND date_time <= filereport_pg.gd_till
   GROUP BY TRUNC(TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800);
  lt_er    common_pg.tt_number;
  lv_name  VARCHAR2(2000);
  ln_bill  NUMBER              DEFAULT 0;
  ln_month NUMBER              DEFAULT 0;
  lv_time  VARCHAR2(10);
 BEGIN
  FOR i IN 1 .. 48 LOOP
   lt_er(i) := 0; --null;
  END LOOP;
  FOR lc IN lcur_sel LOOP
   FOR lc1 IN lcur_sel1(lc.mid, lc.inv, lc.npartly, lc.nfromperiod, lc.ntillperiod) LOOP
    IF lc1.er IS NOT NULL THEN
     lt_er(lc1.dt) := NVL(lt_er(lc1.dt), 0) + lc1.er;
     ln_bill := ln_bill + lc1.er / 2;
    END IF;
   END LOOP;
  END LOOP;
  SELECT SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(
                              h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                 h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
           util_pg.sld(
            h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                               h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) er
    INTO ln_month
    FROM halfhour h, GROUPS g
   WHERE h.mid = g.mid
     AND h.date_time > TRUNC(filereport_pg.gd_from, 'month')
     AND h.date_time <= filereport_pg.gd_till
     AND g.gid IN (SELECT     gid
                         FROM GROUPS
                        WHERE mid IS NOT NULL
                   CONNECT BY PRIOR gid = parent
                   START WITH gid = filereport_pg.gn_group);
  filereport_pg.put_p('    График нагрузки по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p('      за '|| TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY') /*|| ' по ' ||
   TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY')*/ || '  МВт ');
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('Потребление Акт. энергии за сутки ', 51, ' ') ||
                      TO_CHAR(ln_bill / 1000, '99999999990.999'));
  filereport_pg.put_p(
   LPAD('Потребление Акт. энергии с начала месяца ', 51, ' ') || TO_CHAR(
                                                                  ln_month / 1000, '99999999990.999'));
  filereport_pg.put_p('');
  filereport_pg.put_p('+'|| LPAD('-', 65, '-') || '+');
  filereport_pg.put_p('| Время |Мощность МВт | Время |Мощность МВт | Время |Мощность МВт  ');
  filereport_pg.put_p('+'|| LPAD('-', 65, '-') || '+');
  FOR i IN 1 .. 16 LOOP
   lv_name := '| ';
   FOR j IN 1 .. 3 LOOP
    IF  i = 16 AND j = 3 THEN
     lv_time := '24:00';
    ELSE
     lv_time := TO_CHAR(TRUNC(SYSDATE) + (16 * (j - 1) + i) / 48, 'HH24:MI');
    END IF;
    lv_name := lv_name || lv_time || ' ' ||
               TO_CHAR(ROUND(lt_er(16 * (j - 1) + i) / 1000, 3), '99999990.999') ||
               ' | ';
   END LOOP;
   filereport_pg.put_p(SUBSTR(lv_name, 1, 100));
  END LOOP;
  filereport_pg.put_p('+'|| LPAD('-', 65, '-') || '+');
 END;
