 --Трехстолбцовый график нагрузки для ЦТ ХЭС (поднимаем график)
 PROCEDURE report1x_p IS
  CURSOR lcur_sel IS
   SELECT     mid, DECODE(inverted, 'y', 1, 0) inv, npartly, nfromperiod, ntillperiod
         FROM GROUPS
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
   START WITH gid = filereport_pg.gn_group;
  CURSOR lcur_sel1(lc_mid NUMBER, lc_inv NUMBER, lc_partly NUMBER, lc_nfromperiod NUMBER, lc_ntillperiod NUMBER) IS
   SELECT   TRUNC(
             TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800) +
            1 dt,
            SUM(
             DECODE(
              lc_inv, 1, -util_pg.sld(
                           mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                                          ed * DECODE(lc_partly, 1, 0, 1), 0)),
              util_pg.sld(
               mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                              ed * DECODE(lc_partly, 1, 0, 1), 0))) *
             DECODE(SIGN(TRUNC(date_time) - TO_DATE(NVL(lc_nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(lc_ntillperiod, 299912), 'yyyymm')) + 1) - date_time), -1, NULL, 1)) *
            2
              er
       FROM halfhour
      WHERE mid = lc_mid AND date_time > filereport_pg.gd_from AND date_time <= filereport_pg.gd_till
   GROUP BY TRUNC(TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800);
  lt_er     common_pg.tt_number;
  lv_name   VARCHAR2(2000);
  ln_bill   NUMBER              DEFAULT 0;
  ln_billm  NUMBER              DEFAULT 0;
  ln_month  NUMBER              DEFAULT 0;
  lv_time   VARCHAR2(10);
  ln_diff   NUMBER;
  ln_tmp    NUMBER;
  ln_sumtmp NUMBER              DEFAULT 0;
 BEGIN
  FOR i IN 1 .. 48 LOOP
   lt_er(i) := 0; --null;
  END LOOP;
  FOR lc IN lcur_sel LOOP
   FOR lc1 IN lcur_sel1(lc.mid, lc.inv, lc.npartly, lc.nfromperiod, lc.ntillperiod) LOOP
    IF lc1.er IS NOT NULL THEN
     lt_er(lc1.dt) := NVL(lt_er(lc1.dt), 0) + lc1.er;
     ln_bill := ln_bill + lc1.er / 2;
    END IF;
   END LOOP;
  END LOOP;
  SELECT SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(
                              h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                 h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
           util_pg.sld(
            h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                               h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) er
    INTO ln_month
    FROM bill h, GROUPS g
   WHERE h.mid = g.mid
     AND h.date_time > TRUNC(filereport_pg.gd_from, 'month')
     AND h.date_time <= filereport_pg.gd_till
     AND g.gid IN (SELECT     gid
                         FROM GROUPS
                        WHERE mid IS NOT NULL
                   CONNECT BY PRIOR gid = parent
                   START WITH gid = filereport_pg.gn_group);
  SELECT SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(
                              h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                 h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
           util_pg.sld(
            h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                               h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) er
    INTO ln_billm
    FROM bill h, GROUPS g
   WHERE h.mid = g.mid
     AND h.date_time > filereport_pg.gd_from
     AND h.date_time <= filereport_pg.gd_till
     AND g.gid IN (SELECT     gid
                         FROM GROUPS
                        WHERE mid IS NOT NULL
                   CONNECT BY PRIOR gid = parent
                   START WITH gid = filereport_pg.gn_group);
  filereport_pg.put_p('    График нагрузки по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p('      за '|| TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY') /*|| ' по ' ||
   TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY')*/ || '  МВт ');
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('Потребление Акт. энергии за сутки ', 51, ' ') ||
                      TO_CHAR(ln_billm / 1000, '99999999990.999'));
  filereport_pg.put_p(
   LPAD('Потребление Акт. энергии с начала месяца ', 51, ' ') || TO_CHAR(
                                                                  ln_month / 1000, '99999999990.999'));
  filereport_pg.put_p('');
  filereport_pg.put_p('+'|| LPAD('-', 65, '-') || '+');
  filereport_pg.put_p('| Время |Мощность МВт | Время |Мощность МВт | Время |Мощность МВт  ');
  filereport_pg.put_p('+'|| LPAD('-', 65, '-') || '+');
  FOR i IN 1 .. 16 LOOP
   lv_name := '| ';
   FOR j IN 1 .. 3 LOOP
    IF  i = 16 AND j = 3 THEN
     lv_time := '24:00';
    ELSE
     lv_time := TO_CHAR(TRUNC(SYSDATE) + (16 * (j - 1) + i) / 48, 'HH24:MI');
    END IF;
    ln_tmp := lt_er(16 * (j - 1) + i);
    IF ln_bill <> 0 THEN
     ln_tmp := ln_tmp * ln_billm / ln_bill;
    END IF;
    lv_name := lv_name || lv_time || ' ' || TO_CHAR(ROUND(ln_tmp / 1000, 3), '99999990.999') || ' | ';
   END LOOP;
   filereport_pg.put_p(SUBSTR(lv_name, 1, 100));
  END LOOP;
  filereport_pg.put_p('+'|| LPAD('-', 65, '-') || '+');
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Трехстолбцовый график нагрузки для ЦТ ХЭС (поднимаем график) Для экспорта
 PROCEDURE report1y_p IS
  CURSOR lcur_sel IS
   SELECT     mid, DECODE(inverted, 'y', 1, 0) inv, npartly, nfromperiod, ntillperiod
         FROM GROUPS
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
   START WITH gid = filereport_pg.gn_group;
  CURSOR lcur_sel1(
   lc_mid         NUMBER,
   lc_inv         NUMBER,
   lc_dat         DATE,
   lc_partly      NUMBER,
   lc_nfromperiod NUMBER,
   lc_ntillperiod NUMBER) IS
   SELECT   TRUNC(
             TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 3600) +
            1 dt,
            SUM(
             DECODE(
              lc_inv, 1, -util_pg.sld(
                           mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                                          ed * DECODE(lc_partly, 1, 0, 1), 0)),
              util_pg.sld(
               mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                              ed * DECODE(lc_partly, 1, 0, 1), 0))) *
             DECODE(SIGN(date_time - TO_DATE(NVL(lc_nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(lc_ntillperiod, 299912), 'yyyymm')) + 1) - date_time), -1, NULL, 1))
              er
       FROM halfhour
      WHERE mid = lc_mid AND date_time > lc_dat AND date_time <= lc_dat + 1
   GROUP BY TRUNC(TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 3600);
  lt_er     common_pg.tt_number;
  lv_name   VARCHAR2(2000);
  ln_bill   NUMBER;
  ln_billm  NUMBER;
  ln_tmp    NUMBER;
  ld_dat    DATE                DEFAULT TRUNC(filereport_pg.gd_from);
  ln_invert NUMBER              DEFAULT -1;
 BEGIN
  filereport_pg.put_p('    График нагрузки по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   '      за '|| TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY') || ' по ' || TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY') ||
   '  кВт ');
  filereport_pg.put_p('');
  WHILE ld_dat <= TRUNC(filereport_pg.gd_till) LOOP
   FOR i IN 1 .. 24 LOOP
    lt_er(i) := 0; --null;
   END LOOP;
   ln_bill := 0;
   FOR lc IN lcur_sel LOOP
    FOR lc1 IN lcur_sel1(lc.mid, lc.inv, ld_dat, lc.npartly, lc.nfromperiod, lc.ntillperiod) LOOP
     IF lc1.er IS NOT NULL THEN
      lt_er(lc1.dt) := NVL(lt_er(lc1.dt), 0) + lc1.er;
      ln_bill := ln_bill + lc1.er;
     END IF;
    END LOOP;
   END LOOP;
   SELECT SUM(
           DECODE(
            g.inverted, 'y', -util_pg.sld(
                               h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                  h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
            util_pg.sld(
             h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
           DECODE(SIGN(h.date_time - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
           DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) er
     INTO ln_billm
     FROM bill h, GROUPS g
    WHERE h.mid = g.mid
      AND h.date_time > ld_dat
      AND h.date_time <= ld_dat + 1
      AND g.gid IN (SELECT     gid
                          FROM GROUPS
                         WHERE mid IS NOT NULL
                    CONNECT BY PRIOR gid = parent
                    START WITH gid = filereport_pg.gn_group);
   lv_name := TO_CHAR(ld_dat, 'dd.mm.yyyy') || CHR(9) || ROUND(ln_invert * ln_billm);
   FOR i IN 1 .. 24 LOOP
    ln_tmp := lt_er(i);
    IF ln_bill <> 0 THEN
     ln_tmp := ln_tmp * ln_billm / ln_bill;
    END IF;
    lv_name := lv_name || CHR(9) || ROUND(ln_invert * ln_tmp);
   END LOOP;
   filereport_pg.put_p(SUBSTR(lv_name, 1, 2000));
   ld_dat := ld_dat + 1;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE report1z_p IS
  CURSOR lcur_sel IS
   SELECT     mid, DECODE(inverted, 'y', 1, 0) inv, npartly, nfromperiod, ntillperiod
         FROM GROUPS
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
   START WITH gid = filereport_pg.gn_group;
  CURSOR lcur_sel1(lc_mid NUMBER, lc_inv NUMBER, lc_partly NUMBER, lc_nfromperiod NUMBER, lc_ntillperiod NUMBER) IS
   SELECT   TO_CHAR(date_time - 1 / 86400, 'HH24') + 1 dt,
            SUM(
             DECODE(
              lc_inv, 1, -util_pg.sld(
                           mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                                          ed * DECODE(lc_partly, 1, 0, 1), 0)),
              util_pg.sld(
               mid, NVL(er * DECODE(lc_partly, 2, 0, 1), 0), NVL(
                                                              ed * DECODE(lc_partly, 1, 0, 1), 0))) *
             DECODE(SIGN(TRUNC(date_time) - TO_DATE(NVL(lc_nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(lc_ntillperiod, 299912), 'yyyymm')) + 1) - date_time), -1, NULL, 1))
              er
       FROM halfhour
      WHERE mid = lc_mid AND date_time > filereport_pg.gd_from AND date_time <= filereport_pg.gd_till
   GROUP BY TO_CHAR(date_time - 1 / 86400, 'HH24');
  ln_bill NUMBER              DEFAULT 0;
  lt_er   common_pg.tt_number;
  lv_name VARCHAR2(2000);
  lv_time VARCHAR2(10);
 BEGIN
  FOR i IN 1 .. 24 LOOP
   lt_er(i) := 0; --null;
  END LOOP;
  FOR lc IN lcur_sel LOOP
   FOR lc1 IN lcur_sel1(lc.mid, lc.inv, lc.npartly, lc.nfromperiod, lc.ntillperiod) LOOP
    IF lc1.er IS NOT NULL THEN
     lt_er(lc1.dt) := NVL(lt_er(lc1.dt), 0) + lc1.er;
     ln_bill := ln_bill + lc1.er;
    END IF;
   END LOOP;
  END LOOP;
  filereport_pg.put_p('График нагрузки по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   '  за период с '|| TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY') || ' по ' ||
   TO_CHAR(filereport_pg.gd_till - 1, 'DD.MM.YYYY') || '  МВт ');
  filereport_pg.put_p('');
  filereport_pg.put_p('+'|| LPAD('-', 45, '-') || '+');
  filereport_pg.put_p('| Время |Мощность, МВт | Время |Мощность, МВт |');
  filereport_pg.put_p('+'|| LPAD('-', 45, '-') || '+');
  FOR i IN 1 .. 12 LOOP
   lv_name := '| ';
   FOR j IN 1 .. 2 LOOP
    IF  i = 12 AND j = 2 THEN
     lv_time := '24:00';
    ELSE
     lv_time := TO_CHAR(TRUNC(SYSDATE) + (12 * (j - 1) + i) / 24, 'HH24:MI');
    END IF;
    lv_name := lv_name || lv_time || ' ' ||
               TO_CHAR(ROUND(lt_er(12 * (j - 1) + i) / 1000, 3), '999999990.999') ||
               ' | ';
   END LOOP;
   filereport_pg.put_p(SUBSTR(lv_name, 1, 100));
  END LOOP;
  filereport_pg.put_p('+'|| LPAD('-', 45, '-') || '+');
  filereport_pg.put_p(RPAD('Суммарное потребление, тыс.кВтч ', 31, ' ') ||
                      TO_CHAR(ln_bill / 1000, '99999999990.999'));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Трафик сеансов связи
 PROCEDURE report2_p IS
  CURSOR lcur_sel IS
   SELECT   'COM' || LPAD(co.com_num, 3) com, TO_CHAR(t.dopen, 'dd.mm.yy hh24:mi:ss') dopen,
            ROUND(NVL((NVL(t.dstart, t.dopen) - t.dopen) * 1440 * 60, 0)) nsoed,
            ROUND(NVL((t.dend - NVL(t.dstart, t.dopen)) * 1440 * 60, 0)) nseans,
            ROUND(
             NVL((t.dend - NVL(t.dstart, t.dopen)) * 1440 * 60 + 15, 0)) noplatsek,
            NVL(
             ROUND(
              ((t.dend - NVL(t.dstart, t.dopen)) * 1440 * 60 + 15) * /* 0.38 */
              tariff_pg.gettariff(co.ntarifftype, t.dopen) / DECODE(util_pg.get_customer_id, 1, 100,60), 2), 0)
              noplatgrn,
            LPAD(NVL(SUBSTR(c.init_str, 4, 11), ' '), 11, ' ') tel, RPAD(NVL(c.vname, ' '), 31, ' ') cname,
            RPAD(DECODE(TRIM(t.vuser), 'Unnamed user', 'Система', '', 'Система', t.vuser), 12, ' ') inic,
            NVL(t.nsend, 0) nsend, NVL(t.nreceived, 0) nreceived
       FROM channels c, traffic t, comports co
      WHERE c.cid = t.cid
        AND c.com_id = co.com_id(+)
        AND co.ncomtype IN (4, 5, 7)
        AND t.dstart >= filereport_pg.gd_from
        AND t.dend < filereport_pg.gd_till
        AND t.cid IN (SELECT DISTINCT cid
                                 FROM chanpoint
                                WHERE mid IN (SELECT     mid
                                                    FROM GROUPS
                                              CONNECT BY PRIOR gid = parent
                                              START WITH gid = filereport_pg.gn_group))
   ORDER BY c.com_id, NVL(t.dstart, t.dopen);
  ln_soed      NUMBER DEFAULT 0;
  ln_seans     NUMBER DEFAULT 0;
  ln_oplatsek  NUMBER DEFAULT 0;
  ln_oplatgrn  NUMBER DEFAULT 0;
  ln_send      NUMBER DEFAULT 0;
  ln_received  NUMBER DEFAULT 0;
  ln_asoed     NUMBER DEFAULT 0;
  ln_aseans    NUMBER DEFAULT 0;
  ln_aoplatsek NUMBER DEFAULT 0;
  ln_aoplatgrn NUMBER DEFAULT 0;
  ln_all       NUMBER DEFAULT 136;
 BEGIN
  filereport_pg.put_p('     Трафик сеансов связи по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   ' с '|| TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY HH24:MI:SS') || ' по ' ||
   TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY HH24:MI:SS'));
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('-', ln_all, '-'));
  filereport_pg.put_p(
   ':Порт  :      Дата       :Соедине:Сеанс,:К оплате,:К оплате,:Отослано:Принято :  Телефон  : Инициатор  :          Канал                :');
  filereport_pg.put_p(
   ':      :    соединения   :ние,сек: сек  :   сек   :   грн   :        :        :           :            :                               :');
  filereport_pg.put_p(LPAD('-', ln_all, '-'));
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p(
    lc.com || ':' || lc.dopen || ':' || LPAD(lc.nsoed, 7, ' ') || ':' || LPAD(lc.nseans, 6, ' ') || ':' ||
    LPAD(lc.noplatsek, 9, ' ') || ':' || TO_CHAR(lc.noplatgrn, '99990.99') || ':' || LPAD(lc.nsend, 8, ' ') || ':' ||
    LPAD(lc.nreceived, 8, ' ') || ':' || lc.tel || ':' || lc.inic || ':' || lc.cname || ':');
   ln_soed := ln_soed + lc.nsoed;
   ln_seans := ln_seans + lc.nseans;
   ln_oplatsek := ln_oplatsek + lc.noplatsek;
   ln_oplatgrn := ln_oplatgrn + lc.noplatgrn;
   ln_send := ln_send + lc.nsend;
   ln_received := ln_received + lc.nreceived;
  END LOOP;
  filereport_pg.put_p(LPAD('-', ln_all, '-'));
  filereport_pg.put_p(
   ':                  ИТОГО :'|| LPAD(ln_soed, 7, ' ') || ':' || LPAD(ln_seans, 6, ' ') || ':' || LPAD(
                                                                                                    ln_oplatsek, 9, ' ') ||
   ':' || TO_CHAR(ln_oplatgrn, '99990.99') || ':' || LPAD(ln_send, 8, ' ') || ':' || LPAD(ln_received, 8, ' ') ||
   ':                                                        :');
  filereport_pg.put_p(LPAD('-', ln_all, '-'));
 END;
