-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE report7_p IS
  ld_from             DATE DEFAULT filereport_pg.gd_from;
  ld_till             DATE DEFAULT filereport_pg.gd_till;
  lv_tab     CONSTANT VARCHAR2(1) := CHR(9);
  ln_r                NUMBER DEFAULT 5;

  CURSOR lcur_sel IS
   SELECT   p.mid, p.NAME NAME, p1.NAME pname
   FROM     points p, points p1
   WHERE    p.mid IN(SELECT     mid
                     FROM       GROUPS
                     CONNECT BY PRIOR gid = PARENT
                     START WITH gid = filereport_pg.gn_group) AND p.PARENT = p1.mid(+)
   ORDER BY p1.NAME, p.NAME;

  CURSOR lcur_sel1(lc_mid NUMBER) IS
   SELECT   date_time, 2 * er / NVL(nkc, 1) er, 2 * ed / NVL(nkc, 1) ed, 2 * q1 / NVL(nkc, 1) q1, 2 * q3 / NVL(nkc, 1) q3
   FROM     halfhour
   WHERE    mid = lc_mid AND date_time > ld_from AND date_time <= ld_till
   ORDER BY date_time;
 BEGIN
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p('Подстанция:  ' || lc.pname);
   filereport_pg.put_p('Точка:  ' || lc.NAME);
   filereport_pg.put_p('За период с ' || TO_CHAR(ld_from, 'dd.mm.yyyy hh24:mi') || ' по ' || TO_CHAR(ld_till, 'dd.mm.yyyy hh24:mi'));
   filereport_pg.put_p(RPAD('-', 50, '-'));
   filereport_pg.put_p('Дата       ' || lv_tab || 'A+' || lv_tab || 'A-' || lv_tab || 'R+' || lv_tab || 'R-');
   filereport_pg.put_p(RPAD('-', 50, '-'));

   FOR lc1 IN lcur_sel1(lc.mid) LOOP
    filereport_pg.put_p(TO_CHAR(lc1.date_time, 'dd.mm.yyyy hh24:mi:ss')
     || lv_tab
     || TO_CHAR(ROUND(lc1.er * 1000, ln_r), '99990.00')
     || lv_tab
     || TO_CHAR(ROUND(lc1.ed * 1000, ln_r), '99990.00')
     || lv_tab
     || TO_CHAR(ROUND(lc1.q1 * 1000, ln_r), '99990.00')
     || lv_tab
     || TO_CHAR(ROUND(lc1.q3 * 1000, ln_r), '99990.00'));
   END LOOP;

   filereport_pg.put_p(RPAD('-', 50, '-'));
   filereport_pg.put_p('');
  END LOOP;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE report8_p IS
  CURSOR lcur_sel IS
   SELECT   e.com_id, c.com_num, c.nsrv, TO_CHAR(e.dlastevent, 'DD.MM.YYYY HH24:MI:SS') dt, e.vlastevent
   FROM     comportevents e, comports c
   WHERE    e.dlastevent BETWEEN filereport_pg.gd_from AND filereport_pg.gd_till AND e.com_id = c.com_id(+)
   ORDER BY e.com_id, e.norder;

  ln_com              NUMBER DEFAULT 0;
 BEGIN
  FOR lc IN lcur_sel LOOP
   IF ln_com <> lc.com_id THEN
    filereport_pg.put_p('');
    filereport_pg.put_p(RPAD('-', 50, '-'));
    filereport_pg.put_p('Порт: ' || LPAD(lc.com_num, 4) || ' ССД: ' || lc.nsrv);
    filereport_pg.put_p(RPAD('-', 50, '-'));
    ln_com := lc.com_id;
   END IF;

   filereport_pg.put_p(LPAD(lc.com_id, 3) || '  ' || lc.dt || '  ' || lc.vlastevent);
  END LOOP;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE report9_p IS
  CURSOR lcur_sel IS
   SELECT   TO_CHAR(j.date_time, 'DD.MM.YYYY HH24:MI:SS') dt, DECODE(p.ind, 3, pa.NAME || ' / ') || p.NAME NAME, d.veventtext || j.state_descr state_descr
   FROM     journal j, points p, points pa, metereventsdict d
   WHERE    j.date_time BETWEEN filereport_pg.gd_from AND filereport_pg.gd_till AND j.mid = p.mid(+) AND p.PARENT = pa.mid(+) AND j.nevent = d.nevent(+)
   ORDER BY j.date_time, pa.NAME, p.NAME;
 BEGIN
  filereport_pg.put_p('Журнал сообщений системы за период с '
   || TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY HH24:MI')
   || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY HH24:MI'));
  filereport_pg.put_p(' ');

  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p(lc.dt || '  ' || RPAD(lc.NAME, 40) || '  ' || lc.state_descr);
  END LOOP;
 END;

-----------------------------------------------------------------------------------------------------------------------
  --Метрология (получасовые мощьности) Add by KSS
 PROCEDURE report10_p IS
  ld_from             DATE DEFAULT util_pg.trunchh24_2(filereport_pg.gd_from);
  ld_till             DATE DEFAULT util_pg.trunchh24_2(filereport_pg.gd_till);
  lv_tab     CONSTANT VARCHAR2(1) := CHR(9);

  CURSOR lcur_sel IS
   SELECT   p.mid, p.NAME NAME, p1.NAME pname
   FROM     points p, points p1
   WHERE    p.mid IN(SELECT     mid
                     FROM       GROUPS
                     CONNECT BY PRIOR gid = PARENT
                     START WITH gid = filereport_pg.gn_group) AND p.PARENT = p1.mid(+)
   ORDER BY p1.NAME, p.NAME;

  CURSOR lcur_sel1(lc_mid NUMBER) IS
   SELECT   util_pg.trunchh24_2(date_time - 1 / 86400) + 1 / 48 dt, SUM(er) er, SUM(ed) ed, SUM(q1) q1, SUM(q3) q3
   FROM     halfhour
   WHERE    mid = lc_mid AND date_time > ld_from AND date_time <= ld_till
   GROUP BY util_pg.trunchh24_2(date_time - 1 / 86400) + 1 / 48;

  lt_er               common_pg.tt_number;
  lt_ed               common_pg.tt_number;
  lt_q1               common_pg.tt_number;
  lt_q3               common_pg.tt_number;
  ln_cn               NUMBER;
  ln_k                NUMBER;
  ln_off              NUMBER DEFAULT 0;
 BEGIN
  ln_cn := 48 *(ld_till - ld_from);

  IF ld_from = TRUNC(ld_from, 'HH24') THEN
   ln_off := 1;
  END IF;

  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p('Подстанция:  ' || lc.pname);
   filereport_pg.put_p('Точка:  ' || lc.NAME);
   filereport_pg.put_p('За период с ' || TO_CHAR(ld_from, 'dd.mm.yyyy hh24:mi') || ' по ' || TO_CHAR(ld_till, 'dd.mm.yyyy hh24:mi'));
   filereport_pg.put_p(RPAD('-', 70, '-'));
   filereport_pg.put_p('Дата       ' || lv_tab || 'Время' || lv_tab || 'A+' || lv_tab || 'A-' || lv_tab || 'R+' || lv_tab || 'R-');
   filereport_pg.put_p(RPAD('-', 70, '-'));

   FOR i IN 1 .. ln_cn LOOP
    lt_er(i) := NULL;
    lt_ed(i) := NULL;
    lt_q1(i) := NULL;
    lt_q3(i) := NULL;
   END LOOP;

   FOR lc1 IN lcur_sel1(lc.mid) LOOP
    ln_k := 48 *(lc1.dt - ld_from);
    lt_er(ln_k) := lc1.er;
    lt_ed(ln_k) := lc1.ed;
    lt_q1(ln_k) := lc1.q1;
    lt_q3(ln_k) := lc1.q3;
   END LOOP;

   FOR i IN 1 .. ln_cn LOOP
    filereport_pg.put_p(TO_CHAR(ld_from + i / 48, 'dd.mm.yyyy')
     || lv_tab
     || TO_CHAR(ld_from + i / 48, 'HH24:MI')
     || lv_tab
     || lt_er(i) * 2
     || lv_tab
     || lt_ed(i) * 2
     || lv_tab
     || lt_q1(i) * 2
     || lv_tab
     || lt_q3(i) * 2);
   END LOOP;

   filereport_pg.put_p(RPAD('-', 70, '-'));
   filereport_pg.put_p('');
  END LOOP;
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Отчёт по полноте заполнения БД Add by KSS
 PROCEDURE report11_p IS
  ld_from             DATE DEFAULT TRUNC(filereport_pg.gd_from);
  ld_till             DATE DEFAULT TRUNC(filereport_pg.gd_till);

  CURSOR c_dates IS
   SELECT *
   FROM   check_status
   WHERE  nprocedure = 14 AND ddate >= ld_from AND ddate <= ld_till;

  CURSOR c_points(cd_curr DATE) IS
   SELECT pr.NAME pname, pt.NAME NAME, r.nmustbe, r.nindeed
   FROM   check_results r, points pt, points pr
   WHERE  nprocedure = 14 AND ddate = cd_curr AND r.mid = pt.mid AND pt.PARENT = pr.mid;
 BEGIN
  filereport_pg.put_p('    Отчёт по полноте заполнения БД за период с ' || TO_CHAR(ld_from, 'dd.mm.yyyy') || ' по ' || TO_CHAR(ld_till, 'dd.mm.yyyy'));
  filereport_pg.put_p('');

  FOR c IN c_dates LOOP
   filereport_pg.put_p(RPAD('-', 70, '-'));
   filereport_pg.put_p(CHR(9) || 'Дата ' || TO_CHAR(c.ddate, 'dd.mm.yyyy') || ' - ' || c.vtext);

   FOR cur IN c_points(c.ddate) LOOP
    filereport_pg.put_p(cur.pname || CHR(9) || '   ' || RPAD(cur.NAME, 40, ' ') || 'отсутствует ' || cur.nindeed || ' из ' || cur.nmustbe);
   END LOOP;
  END LOOP;

  filereport_pg.put_p(RPAD('-', 70, '-'));
 END;

