 PROCEDURE report12_p IS
  CURSOR lcur_sel IS
   SELECT   e.com_id, c.com_num, c.nsrv, TO_CHAR(e.dlastevent, 'DD.MM.YYYY HH24:MI:SS') dt, e.vlastevent
   FROM     comportevents e, comports c
   WHERE    e.dlastevent BETWEEN filereport_pg.gd_from AND filereport_pg.gd_till
            AND(e.vlastevent LIKE '%Открыт канал связи с:%' OR e.vlastevent LIKE '%Закрыт канал связи с:%' OR e.vlastevent LIKE '%  -->   %')
            AND e.com_id = c.com_id AND c.ncomtype IN(4, 5, 7)
   ORDER BY e.com_id, e.norder;

  ln_com              NUMBER DEFAULT 0;
 BEGIN
  filereport_pg.put_p(' Каналы опрошенные по GSM c ' || TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(' выполнен ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));

  FOR lc IN lcur_sel LOOP
   IF ln_com <> lc.com_id THEN
    filereport_pg.put_p('');
    filereport_pg.put_p(RPAD('-', 50, '-'));
    filereport_pg.put_p('Порт: ' || LPAD(lc.com_num, 3) || ' ССД: ' || lc.nsrv);
    filereport_pg.put_p(RPAD('-', 50, '-'));
    ln_com := lc.com_id;
   END IF;

   filereport_pg.put_p(LPAD(lc.com_id, 2) || '  ' || lc.dt || '  ' || lc.vlastevent);
  END LOOP;
 END;

