 PROCEDURE report13_p IS
  CURSOR lcur_sel IS
   SELECT                                    --DECODE(monitoring_pg.get_group_point_status_f(NVL(g.mid, 0), filereport_pg.gd_from, 2, 0, 0, 0), 0, ' ', '*') f,
          CASE
           WHEN g.mid IS NULL THEN ' '
           WHEN halfhour IS NULL THEN '*'
           WHEN halfhour < filereport_pg.gd_from THEN '*'
           ELSE ' '
          END f, LPAD(' ',(lev - 1) * 5, ' ') || NAME n, TO_CHAR(halfhour, 'dd.mm.yyyy hh24:mi:ss') d, v
   FROM   (SELECT     gg.mid, gg.NAME, LEVEL lev, ls.halfhour, (SELECT vvalue
                                                                FROM   addpointparamval
                                                                WHERE  nsort = 0 AND mid = gg.mid) v
           FROM       GROUPS gg, last_save ls
           WHERE      gg.mid = ls.mid(+)
           CONNECT BY gg.PARENT = PRIOR gg.gid
           START WITH gg.gid = filereport_pg.gn_group) g;
 BEGIN
  filereport_pg.put_p(' Отчет об отсутствии получасовых данных по точкам на ' || TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p(' выполнен '
   || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss')
   || '  (1 - Наименование; 2 - * - нет данных ГН, пробел - есть данные ГН; 3 - дата и время последних данных ГН в БД; 4 - Примечание)');
  filereport_pg.put_p('');
  filereport_pg.put_p(RPAD('-', 128, '-'));
  filereport_pg.put_p('                           1                                           | 2 |          3          |               4 ');
  filereport_pg.put_p(RPAD('-', 128, '-'));

  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p(RPAD(lc.n, 70) || ' | ' || lc.f || ' | ' || RPAD(NVL(lc.d, ' '), 19) || ' | ' || lc.v);
  END LOOP;
 END;

