 PROCEDURE report13_tp_p IS
  CURSOR lcur_sel IS
   SELECT                                    --DECODE(monitoring_pg.get_group_point_status_f(NVL(g.mid, 0), filereport_pg.gd_from, 2, 0, 0, 0), 0, ' ', '*') f,
          CASE
           WHEN g.mid IS NULL THEN ' '
           WHEN date_time IS NULL THEN '*'
           WHEN date_time < filereport_pg.gd_till THEN '*'
           ELSE ' '
          END f, LPAD(' ',(lev - 1) * 5, ' ') || NAME n, DECODE(g.mid, NULL, '   папка', TO_CHAR(date_time, 'dd.mm.yyyy hh24:mi:ss')) d, v
   FROM   (SELECT     gg.mid, gg.NAME, LEVEL lev, h.date_time, (SELECT vvalue
                                                                FROM   addpointparamval
                                                                WHERE  nsort = 0 AND mid = gg.mid) v
           FROM       GROUPS gg,
                      (SELECT   mid, MAX(date_time) date_time
                       FROM     halfhour
                       WHERE    date_time > filereport_pg.gd_from AND mid IN(SELECT     mid
