 PROCEDURE report13_2_p IS
  gname               VARCHAR2(150);
  point_cnt           NUMBER;
  f_cnt               NUMBER;
  vf                  NUMBER;
  f_vf                NUMBER;
 BEGIN
  SELECT NAME
  INTO   gname
  FROM   points
  WHERE  mid = 1000;

  filereport_pg.put_p(' Статистика опроса точек учета по группам с '
   || TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss')
   || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss')
   || ' '
   || LPAD(TO_CHAR(gname), 32));
  filereport_pg.put_p('');
  filereport_pg.put_p(' выполнен ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(RPAD('-', 108, '-'));
  filereport_pg.put_p('|                                     |           |                                   |                    |');
  filereport_pg.put_p('|                                     |   Общее   |    Неопрашиваются точки учета     |                    |');
  filereport_pg.put_p('|             Наименование            |   кол-во  |-----------------------------------|                    |');
  filereport_pg.put_p('|              подстанции             |   точек   |           | Из них по |  Причина  |     Примечание     |');
  filereport_pg.put_p('|                                     |   учета   |   Всего   | известной | выясняется|                    |');
  filereport_pg.put_p('|                                     |           |           |  причине  |           |                    |');
  filereport_pg.put_p(RPAD('-', 108, '-'));

  FOR lc IN (SELECT   gid, NAME
             FROM     GROUPS
             WHERE    PARENT = filereport_pg.gn_group
             ORDER BY NAME) LOOP
   gname := lc.NAME;

   SELECT COUNT(*), SUM(f), SUM(SIGN(NVL(v, 0)) * f), SUM(f) - SUM(SIGN(NVL(v, 0)) * f)
   INTO   point_cnt, f_cnt, vf, f_vf
   FROM   (SELECT g.gid, g.mid, ls.halfhour, CASE
                   WHEN ls.halfhour IS NULL THEN 1
                   WHEN ls.halfhour < filereport_pg.gd_till THEN 1
                   ELSE 0
                  END f, (SELECT LENGTH(NVL(vvalue, 0))
                          FROM   addpointparamval
                          WHERE  mid = g.mid AND nsort = 0) v
           FROM   GROUPS g, last_save ls
           WHERE  g.mid = ls.mid(+) AND g.gid IN(SELECT     gid
                                                 FROM       GROUPS
                                                 WHERE      mid IS NOT NULL
                                                 CONNECT BY PRIOR gid = PARENT
                                                 START WITH gid = lc.gid));

   filereport_pg.put_p('| '
    || RPAD(NVL(gname, ' '), 35)
    || ' | '
    || LPAD(NVL(TO_CHAR(point_cnt, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(f_cnt, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(vf, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(f_vf, '99999999'), ' '), 9)
    || ' | '
    || RPAD(' ', 18)
    || ' |');
  END LOOP;

  filereport_pg.put_p(RPAD('-', 108, '-'));
 END;                                                                                                                                   --PROCEDURE report13_2_p

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE report13_3_p IS
  gname               VARCHAR2(150);
  point_cnt           NUMBER;
  f_cnt               NUMBER;
  vf                  NUMBER;
  f_vf                NUMBER;
  sum_er              NUMBER;
  sum_ed              NUMBER;
  nbalance            NUMBER;
  pbalance            NUMBER;
 BEGIN
  SELECT NAME
  INTO   gname
  FROM   points
  WHERE  mid = 1000;

  filereport_pg.put_p(' Статистика опроса точек учета по группам с '
   || TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss')
   || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss')
   || ' '
   || LPAD(TO_CHAR(gname), 32));
  filereport_pg.put_p('');
  filereport_pg.put_p(' выполнен ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(RPAD('-', 111, '-'));
  filereport_pg.put_p('|                                     |           |                                   |                       |');
  filereport_pg.put_p('|                                     |   Общее   |    Неопрашиваются точки учета     |                       |');
  filereport_pg.put_p('|             Наименование            |   кол-во  |-----------------------------------|                       |');
  filereport_pg.put_p('|              подстанции             |   точек   |           | Из них по |  Причина  |      Небаланс, %      |');
  filereport_pg.put_p('|                                     |   учета   |   Всего   | известной | выясняется|                       |');
  filereport_pg.put_p('|                                     |           |           |  причине  |           |                       |');
  filereport_pg.put_p(RPAD('-', 111, '-'));

  FOR lc IN (SELECT   gid, NAME
             FROM     GROUPS
             WHERE    PARENT = filereport_pg.gn_group
             ORDER BY NAME) LOOP
   gname := lc.NAME;

   SELECT COUNT(*), SUM(f), SUM(SIGN(NVL(v, 0)) * f), SUM(f) - SUM(SIGN(NVL(v, 0)) * f)
   INTO   point_cnt, f_cnt, vf, f_vf
   FROM   (SELECT g.gid, g.mid, ls.halfhour, CASE
                   WHEN ls.halfhour IS NULL THEN 1
                   WHEN ls.halfhour < filereport_pg.gd_till THEN 1
                   ELSE 0
                  END f, (SELECT LENGTH(NVL(vvalue, 0))
                          FROM   addpointparamval
                          WHERE  mid = g.mid AND nsort = 0) v
           FROM   GROUPS g, last_save ls
           WHERE  g.mid = ls.mid(+) AND g.gid IN(SELECT     gid
                                                 FROM       GROUPS
                                                 WHERE      mid IS NOT NULL
                                                 CONNECT BY PRIOR gid = PARENT
                                                 START WITH gid = lc.gid));

   SELECT SUM(er), SUM(ed)
   INTO   sum_er, sum_ed
   FROM   (SELECT h.mid, NVL(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1)), 0) er,
                  NVL(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)), 0) ed
           FROM   halfhour h, GROUPS g
           WHERE  h.date_time > filereport_pg.gd_from AND h.date_time <= filereport_pg.gd_till AND h.mid = g.mid AND g.gid IN(SELECT     gid
                                                                                                                              FROM       GROUPS
                                                                                                                              WHERE      mid IS NOT NULL
                                                                                                                              CONNECT BY PRIOR gid = PARENT
                                                                                                                              START WITH gid = lc.gid));

   nbalance := sum_er - sum_ed;

   IF sum_er = 0 THEN
    pbalance := 0;
   ELSE
    pbalance := nbalance / sum_er * 100;
   END IF;

   filereport_pg.put_p('| '
    || RPAD(NVL(gname, ' '), 35)
    || ' | '
    || LPAD(NVL(TO_CHAR(point_cnt, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(f_cnt, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(vf, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(f_vf, '99999999'), ' '), 9)
    || ' | '
    || LPAD(NVL(TO_CHAR(ROUND(pbalance, 3), '999.999'), ' '), 9)
    || ' / '
    || RPAD(' ', 9)
    || ' |');
  END LOOP;

  filereport_pg.put_p(RPAD('-', 111, '-'));
 END;                                                                                                                                   --PROCEDURE report13_3_p

