   --Макет 30817
 PROCEDURE report14_p IS
 BEGIN
  report15_p;
 END;

-----------------------------------------------------------------------------------------------------------------------
   --Макет 30817 с переносом остатков округлений
 PROCEDURE report15_p IS
  CURSOR lcur_mak IS
   SELECT   nmaket
   FROM     makets
   WHERE    nprocedure = 5
   ORDER BY vname;

  CURSOR lc_maketgroups(lc_maket NUMBER) IS
   SELECT ngroup, vcode
   FROM   maketgroups
   WHERE  nmaket = lc_maket;

  lv_str              VARCHAR2(1000);
  i                   NUMBER;
  nsign_              NUMBER;
  groupcode_          NUMBER;
  subgroupcode_       NUMBER;
  ntemp               NUMBER;
  ln_hc               NUMBER;                                                                                                     -- реал кол-во часов в сутках
  hc                  NUMBER;                                                                                                          -- кол-во часов в сутках
  ld_date             DATE DEFAULT TRUNC(filereport_pg.gd_from);
  ln_div              NUMBER;                                                                                                                        --Делитель
  ln_needround30817   NUMBER;
  ln_needtrunc        NUMBER;
 BEGIN
  FOR lcmak IN lcur_mak LOOP
   ln_hc := 24 - util_pg.is_dayswitch(ld_date);
   hc := ln_hc;

   -- Определяем формат вывода (в тыс. кВт*ч или кВт*ч)
   SELECT DECODE(COUNT(*), 1, 1000, 1)
   INTO   ln_div
   FROM   DUAL
   WHERE  EXISTS(SELECT *
                 FROM   makets
                 WHERE  nmaket = lcmak.nmaket AND util_pg.get_param(vparam, 1) = '1');

   SELECT COUNT(*)
   INTO   ln_needtrunc
   FROM   DUAL
   WHERE  EXISTS(SELECT *
                 FROM   makets
                 WHERE  nmaket = lcmak.nmaket AND util_pg.get_param(vparam, 9) = '1');

   -- Выборка в рабочую таблицу формул расчета агрегированных макетных строк
   DELETE FROM makettemp;

   INSERT INTO makettemp
               (ngroup, nsubgroup, nsign)
    SELECT ngroup, nsubgroup, nsign
    FROM   maketformulas
    WHERE  ngroup IN(SELECT ngroup
                     FROM   maketgroups
                     WHERE  nmaket = lcmak.nmaket);

   -- В рабочей таблице проставляются ид всех строк макета, кроме агрегированных
   DELETE FROM m30817;

   INSERT INTO m30817
               (ngroup, HOUR, kwh, err)
    SELECT ngroup, 0, 0, 0
    FROM   maketgroups
    WHERE  nmaket = lcmak.nmaket AND ngroup NOT IN(SELECT ngroup
                                                   FROM   makettemp);

   -- По тем строкам, где есть данные рассчитываются и сохраняются расходы без 25 часа
   INSERT INTO m30817
               (ngroup, HOUR, kwh)
    SELECT   p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24') + 1,
             SUM(p.nkc
              * DECODE(
                 ntype,
                 1, h.er,
                 2, h.ed,
                 3, h.q1,
                 4, h.q3,
                 5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                 6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                ))
    FROM     maketgroups g, maketpoints p, halfhour h
    WHERE    g.nmaket = lcmak.nmaket AND g.ngroup NOT IN(SELECT ngroup
                                                         FROM   makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC(ld_date)
             AND h.date_time <= TRUNC(ld_date) + 1 AND h.nsource NOT IN(19, 29, 39, 49, 59)
    GROUP BY p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24');

   -- Отдельно сохраняется 25 час, помеченный кодом источника 19
   IF hc = 25 THEN
    INSERT INTO m30817
                (ngroup, HOUR, kwh)
     SELECT   p.ngroup, 25,
              SUM(p.nkc
               * DECODE(
                  ntype,
                  1, h.er,
                  2, h.ed,
                  3, h.q1,
                  4, h.q3,
                  5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                  6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                 ))
     FROM     maketgroups g, maketpoints p, halfhour h
     WHERE    g.nmaket = lcmak.nmaket AND g.ngroup NOT IN(SELECT ngroup
                                                          FROM   makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC(ld_date)
              AND h.date_time <= TRUNC(ld_date) + 1 AND h.nsource IN(19, 29, 39, 49, 59)
     GROUP BY p.ngroup;
   END IF;

   -- По строкам, где не оказалось данных проставляются нули
   FOR i IN 1 .. hc LOOP
    INSERT INTO m30817
                (ngroup, HOUR, kwh, err)
     (SELECT ngroup, i, 0, 0
      FROM   m30817
      WHERE  HOUR = 0
      MINUS
      SELECT ngroup, i, 0, 0
      FROM   m30817
      WHERE  HOUR = i);
   END LOOP;

   -- Округление с учетом ошибки предыдущего шага, запись ошибки текущего шага
   ln_needround30817 := util_pg.needround30817_f;

   FOR i IN 1 .. hc LOOP
    IF NOT(ln_hc = 23 AND i = util_pg.switch_f + 1) THEN
     UPDATE m30817 m
     SET (kwh, err) =
          (SELECT util_pg.round_trunc(a.kwh / 1000 * ln_div, ln_needtrunc, b.err + NVL(c.err, 0)),
                  NVL(a.kwh, 0) / 1000 * ln_div + b.err + NVL(c.err, 0) - util_pg.round_trunc(NVL(a.kwh, 0) / 1000 * ln_div, ln_needtrunc,
                                                                          b.err + NVL(c.err, 0))
           FROM   m30817 a,
                  m30817 b,
                  (SELECT me.ngroup, DECODE(ln_needround30817, 1, DECODE(TO_CHAR(ld_date, 'DD'), 1, 0, me.err), 0) err
                   FROM   maketerr me
                   WHERE  i = 1 AND me.ddate = TRUNC(ld_date) - 1) c
           WHERE  a.ngroup = b.ngroup AND a.HOUR = b.HOUR + DECODE(i, util_pg.switch_f + 2, 2, 1) AND a.ngroup = m.ngroup AND a.HOUR = i AND a.ngroup = c.ngroup(+))
     WHERE  HOUR = i;
    END IF;
   END LOOP;

   --Запоминаем остатки округления на след день
   IF ln_needround30817 = 1 THEN
    DELETE FROM maketerr
    WHERE       ddate = TRUNC(ld_date) AND ngroup IN(SELECT ngroup
                                                     FROM   m30817);

    INSERT INTO maketerr
                (ngroup, ddate, err)
     SELECT ngroup, TRUNC(ld_date), err
     FROM   m30817
     WHERE  HOUR = hc;
   END IF;

   -- В рабочей таблице проставляются ид агрегированных строк и все часы суток
   FOR i IN 0 .. hc LOOP
    INSERT INTO m30817
                (ngroup, HOUR, kwh)
     SELECT ngroup, i, 0
     FROM   maketgroups
     WHERE  nmaket = lcmak.nmaket AND ngroup IN(SELECT ngroup
                                                FROM   makettemp);
   END LOOP;

   LOOP
    -- Выбираем из рабочей таблицы очередную составляющую агрегированной строки или выходим, если таблица пуста
    BEGIN
     SELECT ngroup, nsubgroup, nsign
     INTO   groupcode_, subgroupcode_, nsign_
     FROM   makettemp
     WHERE  nsubgroup NOT IN(SELECT ngroup
                             FROM   makettemp) AND ROWNUM = 1;
    EXCEPTION
     WHEN NO_DATA_FOUND THEN
      EXIT;
    END;

    -- Расчет и аккумулирование составляющей в агрегированной строке
    FOR i IN 1 .. hc LOOP
     BEGIN
      SELECT nsign_ * kwh
      INTO   ntemp
      FROM   m30817
      WHERE  ngroup = subgroupcode_ AND HOUR = i;
     EXCEPTION
      WHEN NO_DATA_FOUND THEN
       ntemp := 0;
     END;

     UPDATE m30817
     SET kwh = kwh + ntemp
     WHERE  ngroup = groupcode_ AND HOUR = i;
    END LOOP;

    -- удаляем из временной таблицы обработанную составляющую
    DELETE FROM makettemp
    WHERE       ngroup = groupcode_ AND nsubgroup = subgroupcode_;
   END LOOP;

   -- По всем строкам считается расход за сутки
   UPDATE m30817 m
   SET kwh = (SELECT SUM(kwh)
              FROM   m30817
              WHERE  ngroup = m.ngroup)
   WHERE  HOUR = 0;

   -- Формирование теста макета
   filereport_pg.put_p('((//30817:' || TO_CHAR(ld_date, 'MMDD') || ':' || TRIM(TO_CHAR(util_pg.enterprise_f, '000000')) || ':++');

   FOR lc IN lc_maketgroups(lcmak.nmaket) LOOP
    lv_str := '(' || lc.vcode || '):';

    FOR i IN 0 .. hc LOOP
     SELECT lv_str || SUM(kwh) || ':'
     INTO   lv_str
     FROM   m30817
     WHERE  ngroup = lc.ngroup AND HOUR = i;
    END LOOP;

    filereport_pg.put_p(lv_str);
   END LOOP;

   filereport_pg.put_p('==))');
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   RAISE;
 END;

