--Отчет об опросе счетчиков за день
 PROCEDURE report16_p IS
  ld_date             DATE DEFAULT TRUNC(filereport_pg.gd_from);
  lv_tab     CONSTANT VARCHAR2(2) := CHR(9);
  cn_n       CONSTANT NUMBER := 50;
  cn_shift   CONSTANT NUMBER := 1 / 3;

  CURSOR lcur_sel IS
   SELECT   pa.NAME paname, p.NAME pname, NVL(TO_CHAR(MIN(tr.mindopen), 'hh24:mi'), ' ') mindopen,
            NVL(TO_CHAR(LEAST(MAX(tr.maxdopen), ld_date + 2 - 1 / 86400), 'hh24:mi'), ' ') maxdopen, NVL(MAX(m.mtype), ' ') mtype,
            NVL(REPLACE(TO_CHAR(MAX(h.date_time), 'hh24:mi'), '00:00', '24:00'), ' ') hdt, NVL(TO_CHAR(MAX(b.date_time), 'hh24:mi'), ' ') bdt,
            DECODE(
               DECODE(SIGN(MAX(h.date_time) - ld_date - 1), 0, 1, 1, 1, -1, 0)
             + DECODE(SIGN(MAX(b.date_time) - ld_date - 1), 0, 1, 1, 1, -1, 0)
             + DECODE(SIGN(ld_date + 1 + cn_shift - MAX(h.denter)), 1, 1, 0)
             + DECODE(SIGN(ld_date + 1 + cn_shift - MAX(b.denter)), 1, 1, 0)
             + DECODE(MAX(cnth.cnt), util_pg.get_count_dt(ld_date, 1 / 48), 1, 0),
             5, ' ',
             'Нет '
            ) state,
            DECODE(SIGN(MAX(f.nblock) + MAX(ch.nblock)), 1, '*', ' ') nblock,
            REPLACE(NVL(TO_CHAR(MAX(h.denter), 'hh24:mi dd.mm.yy'), ' '), TO_CHAR(ld_date + 1, 'dd.mm.yy')) ht,
            REPLACE(NVL(TO_CHAR(MAX(b.denter), 'hh24:mi dd.mm.yy'), ' '), TO_CHAR(ld_date + 1, 'dd.mm.yy')) bt, NVL(MAX(cnth.cnt), 0) hcnt,
            NVL(MAX(tr.lucktr), 0) lucktr, NVL(MAX(tr.alltr), 0) alltr
   FROM     points p,
            points pa,
            meters m,
            halfhourold h,
            billorg b,
            feeders f,
            (SELECT   cp.mid, MIN(t.dopen) mindopen, MAX(NVL(t.dend, t.dopen)) maxdopen, SUM(DECODE(SIGN(t.nreceived), 1, 1, 0)) lucktr, COUNT(*) alltr
             FROM     traffic t, chanpoint cp
             WHERE    t.cid = cp.cid(+) AND t.dopen >= ld_date + 1 AND t.dopen < ld_date + 2
             GROUP BY cp.mid) tr,
            (SELECT   mid, COUNT(*) cnt
             FROM     (SELECT   mid
                       FROM     halfhourold
                       WHERE    date_time > ld_date AND date_time <= ld_date + 1 AND nsource = comsrv_pg.cn_auto
                       GROUP BY mid, util_pg.trunchh24_2(date_time - 1 / 86400)) hh
             GROUP BY hh.mid) cnth,
            (SELECT   cp.mid, MIN(channels_pg.is_block(c.cid, c.blocking, 0)) nblock
             FROM     chanpoint cp, channels c
             WHERE    cp.cid = c.cid(+)                                                                     
             GROUP BY cp.mid) ch
   WHERE    p.mid = ch.mid AND p.mid = f.mid(+) AND p.PARENT = pa.mid(+) AND p.mid = m.mid(+) AND p.mid = cnth.mid(+) AND p.mid = tr.mid(+) AND p.mid = h.mid(+)
            AND h.date_time(+) > ld_date AND h.date_time(+) <= ld_date + 1 AND h.nsource(+) = comsrv_pg.cn_auto AND p.mid = b.mid(+) AND b.date_time(+) >=
                                                                                                                                                     ld_date + 1
            AND b.date_time(+) < ld_date + 2 AND b.nsource(+) = comsrv_pg.cn_auto
   GROUP BY p.mid, pa.NAME, p.NAME
   ORDER BY 1, 2;
 BEGIN
  filereport_pg.put_p(' Отчет об опросе счетчиков за ' || TO_CHAR(ld_date, 'dd.mm.yyyy'));
  filereport_pg.put_p(' Выполнен ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(RPAD('Подстанция', cn_n)
   || lv_tab
   || RPAD('Точка учета', cn_n)
   || lv_tab
   || RPAD('Тип счетчика', 12)
   || lv_tab
   || RPAD('Пер опроса', 11)
   || lv_tab
   || RPAD('Кол опр', 7)
   || lv_tab
   || RPAD('ГН', 5)
   || lv_tab
   || RPAD('кГН', 3)
   || lv_tab
   || RPAD('Показ', 5)
   || lv_tab
   || RPAD('Сбор ГН', 14)
   || lv_tab
   || RPAD('Сбор Показ', 14)
   || lv_tab
   || 'Норм'
   || lv_tab
   || 'Бл');

  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p(RPAD(lc.paname, cn_n)
    || lv_tab
    || RPAD(lc.pname, cn_n)
    || lv_tab
    || RPAD(lc.mtype, 12)
    || lv_tab
    || RPAD(lc.mindopen, 5)
    || '-'
    || RPAD(lc.maxdopen, 5)
    || lv_tab
    || RPAD(lc.lucktr || '/' || lc.alltr, 7)
    || lv_tab
    || RPAD(lc.hdt, 5)
    || lv_tab
    || RPAD(lc.hcnt, 3)
    || lv_tab
    || RPAD(lc.bdt, 5)
    || lv_tab
    || RPAD(lc.ht, 14)
    || lv_tab
    || RPAD(lc.bt, 14)
    || lv_tab
    || RPAD(lc.state, 4)
    || lv_tab
    || RPAD(lc.nblock, 2));
  END LOOP;
 END;

