  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Отчет о попытках несанкционированного доступа
 PROCEDURE report18_p IS
  gname               VARCHAR2(150);
  cr_sel              common_pg.tcur;
  lv_os_username      VARCHAR2(255);
  lv_username         VARCHAR2(255);
  lv_userhost         VARCHAR2(255);
  lv_terminal         VARCHAR2(255);
  ld_timestamp        DATE;
 BEGIN
  SELECT MAX(NAME)
  INTO   gname
  FROM   points
  WHERE  mid = util_pg.cn_pntmid;

  filereport_pg.put_p(' Отчет о попытках несанкционированного доступа за период с '
   || TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss')
   || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss')
   || ' '
   || LPAD(TO_CHAR(gname), 32));
  filereport_pg.put_p('');
  filereport_pg.put_p(' выполнен ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(RPAD('-', 129, '-'));
  filereport_pg.put_p('|                    |                    |                    |                    |                      |                    |');
  filereport_pg.put_p('|  Пользователь ОС   | Пользователь АСКУЭ |        Узел        |      Терминал      |     Дата и время     |     Примечание     |');
  filereport_pg.put_p('|                    |     (Oracle)       |                    |                    |                      |                    |');
  filereport_pg.put_p(RPAD('-', 129, '-'));

  OPEN cr_sel FOR 'select OS_USERNAME, USERNAME, USERHOST, TERMINAL, TIMESTAMP
                from dba_audit_session where timestamp > :par1 and timestamp <= :par2
                and returncode in (1017) order by timestamp' USING filereport_pg.gd_from, filereport_pg.gd_till;

  LOOP
   FETCH cr_sel
