 PROCEDURE report20_p IS
  cr_sel              common_pg.tcur;
  mess                VARCHAR2(1000);
 BEGIN
  -- filereport_pg.put_p('Отчет ****'||TO_CHAR (filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') || ' по '||TO_CHAR (filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss')||' ************ '||filereport_pg.gn_group);
  filereport_pg.put_p(RPAD(' Дата', 20) || CHR(9) || RPAD('Служба', 30) || CHR(9) || 'Сообщение');
  filereport_pg.put_p(RPAD('-', 100, '-'));

  OPEN cr_sel FOR 'SELECT   TO_CHAR (i.dlastevent, ''DD.MM.YYYY HH24:MI:SS'') || chr(9)||RPAD(pp.name, 30)||chr(9)|| i.vlastevent mess
       FROM iccpevents i, points pp
      WHERE i.mid IN (SELECT     p.mid
                          FROM points p
                    CONNECT BY PRIOR p.mid = p.PARENT
                    START WITH p.mid = :an_id) AND pp.mid = i.mid AND i.dlastevent BETWEEN :dt_from AND :dt_till
   ORDER BY i.norder DESC' USING filereport_pg.gn_group, filereport_pg.gd_from, filereport_pg.gd_till;

  LOOP
   FETCH cr_sel
   INTO  mess;

   EXIT WHEN cr_sel%NOTFOUND;
   filereport_pg.put_p(mess);
  END LOOP;
 END;
