 PROCEDURE p_balance IS
  CURSOR lcur_1 IS
   SELECT   c.ddate ddate, p3.NAME pstan_name, p2.NAME point_name, c.vparam PLAN,
            ROUND(ABS(nmustbe - nindeed) / DECODE(SIGN(nmustbe), 0, 1, -1, -nmustbe, nmustbe) * 100, 3) fact, c.nmustbe nmustbe, c.nindeed nindeed
   FROM     check_resultsg c, GROUPS p2, GROUPS p3
   WHERE    c.nprocedure = check_pg.cn_balance AND p2.gid = c.gid AND c.gid IN(SELECT     gid
                                                                               FROM       GROUPS
                                                                               CONNECT BY PRIOR gid = PARENT
                                                                               START WITH gid = filereport_pg.gn_group) AND p3.gid = p2.PARENT
            AND TRUNC(ddate) > filereport_pg.gd_from AND TRUNC(ddate) <= filereport_pg.gd_till
   ORDER BY ddate DESC, p3.NAME, p2.NAME;

