 PROCEDURE p_checkmtrsn IS
  CURSOR lcur_1 IS
   SELECT   b.date_time ddate, pa.NAME pstan_name, p.NAME point_name, m.mtrsn nsi, b.er_mtrsn fact
   FROM     meters m,
            (SELECT   MAX(date_time) date_time, mid, er_mtrsn
             FROM     billorg
             WHERE    date_time >= TRUNC(filereport_pg.gd_from) AND date_time < TRUNC(filereport_pg.gd_till) + 1
             GROUP BY mid, er_mtrsn) b,
            points p,
            points pa
   WHERE    b.mid = m.mid AND m.mid IN(SELECT mid
                                       FROM   chanpoint)
            AND(LPAD(m.mtrsn, 100, '0') <> LPAD(b.er_mtrsn, 100, '0') OR(m.mtrsn IS NULL AND b.er_mtrsn IS NOT NULL)) AND b.mid = p.mid(+) AND p.PARENT = pa.mid(+)
            AND m.mid IN(
                SELECT     mid
                FROM       GROUPS
                CONNECT BY PRIOR gid = PARENT
                START WITH gid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 0
                UNION ALL
                SELECT     mid
                FROM       points
                CONNECT BY PRIOR mid = PARENT
                START WITH mid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 1)
   ORDER BY 1 DESC, 2, 3;

