------------------------------------------------------------------------------------------------------------------------
------------                   Контроль полноты сбора данных                                                ------------
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE p_checkcomplete IS
  CURSOR lcur_1 IS
   SELECT   c.ddate ddate, p3.NAME pstan_name, p2.NAME point_name, util_pg.allnumber_f(c.vparam) sm, c.nmustbe nlimit, c.nindeed nfact
   FROM     check_resultsg c, GROUPS p2, GROUPS p3
   WHERE    c.nprocedure = check_pg.cn_checkcomplete AND p2.gid = c.gid AND p3.gid = p2.PARENT AND TRUNC(ddate) > filereport_pg.gd_from
            AND TRUNC(ddate) <= filereport_pg.gd_till
   ORDER BY ddate DESC, p3.NAME, p2.NAME;

-------------------------
  t1_tab              common_pg.tt_varchar2;
  lv_str              VARCHAR2(265);
  lv_t1               VARCHAR2(265) DEFAULT LPAD('-', 112, '-');
-----------------------
 BEGIN
  filereport_pg.put_p(TO_CHAR(SYSDATE, 'dd.mm.yyyy') || '                    Контроль полноты сбора данных ГН по контролируемым группам');
  filereport_pg.put_p(TO_CHAR(SYSDATE, '  hh24:mi:ss')
   || '                        за период с '
   || TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY HH24:MI')
   || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY HH24:MI'));
  filereport_pg.put_p(' ');
  t1_tab(1) := lv_t1;
  t1_tab(2) := '                 !       Наименование      !         Наименование          !   Точек   !  Точек с  !   Расход  !';
  t1_tab(3) := '    Дата         !   родительской группы   !         группы учета          !   всего   ! непоными  ! тыс. кВтч !';
  t1_tab(4) := '                 !                         !                               !           !  данными  !           !';
  t1_tab(5) := lv_t1;

  FOR i IN 1 .. 5 LOOP
   filereport_pg.setheaderrow_p(t1_tab(i), i);                                                                                    --Заполняем таблицу gt_header
  END LOOP;

  t1_tab.DELETE;
  filereport_pg.setuseheader_p(TRUE);
  filereport_pg.printheader_p;                                                                                                      --Печатаем таблицу gt_header

  FOR c1_rec IN lcur_1 LOOP
   lv_str :=
       RPAD(TO_CHAR(c1_rec.ddate, 'dd.mm.yyyy hh24:mi'), 16)
    || ' !'
    || RPAD(NVL(SUBSTR(c1_rec.pstan_name, 1, 25), ' '), 25)
    || '!'
    || RPAD(NVL(SUBSTR(c1_rec.point_name, 1, 30), ' '), 31)
    || '!'
    || LPAD(NVL(TO_CHAR(c1_rec.nlimit), ' '), 11)
    || '!'
    || LPAD(NVL(TO_CHAR(c1_rec.nfact), ' '), 11)
    || '!'
    || LPAD(NVL(TO_CHAR(ROUND(c1_rec.sm / 1000, 3), '999990.000'), ' '), 11)
    || '!';
   filereport_pg.put_p(lv_str);
  END LOOP;

  filereport_pg.put_p(lv_t1);
 END;

