  filereport_pg.printheader_p;                                                                                                      --Печатаем таблицу gt_header

  FOR c1_rec IN lcur_1 LOOP
   lv_str :=
       RPAD(TO_CHAR(c1_rec.ddate, 'dd.mm.yyyy'), 10)
    || ' !'
    || RPAD(NVL(SUBSTR(c1_rec.pstan_name, 1, 25), ' '), 25)
    || '!'
    || RPAD(NVL(SUBSTR(c1_rec.point_name, 1, 30), ' '), 30)
    || '!'
    || ' '
    || RPAD(NVL(c1_rec.PLAN, ' '), 6)
    || ' !'
    || RPAD(NVL(TO_CHAR(c1_rec.fact), ' '), 10)
    || '!'
    || RPAD(NVL(TO_CHAR(c1_rec.nmustbe, '99999999'), ' '), 11)
    || '!'
    || RPAD(NVL(TO_CHAR(c1_rec.nindeed, '99999999'), ' '), 11);
   filereport_pg.put_p(lv_str);
  END LOOP;

  filereport_pg.put_p(lv_t1);
 END;                                                                                                                                    ---PROCEDURE P_fact_rep

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE p_balance_ IS
  gname               VARCHAR2(150);
  pname               VARCHAR2(150);
  sum_er              NUMBER;
  sum_ed              NUMBER;
  nbalance            NUMBER;
  pbalance            NUMBER;
  check_err_ok        VARCHAR2(12);
 BEGIN
  SELECT NAME
  INTO   gname
  FROM   points
  WHERE  mid = 1000;

  filereport_pg.put_p(' Отчет о балансах по получасовым данным и балансным группам с '
   || TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss')
   || ' по '
   || TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss')
   || ' '
   || LPAD(gname, 32));
  filereport_pg.put_p('');
  filereport_pg.put_p(' выполнен ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(RPAD('-', 138, '-'));
  filereport_pg.put_p
                  ('|                                     |                                     |           |           |           |           |              ');
  filereport_pg.put_p
                  ('|            Наименование             |             Наименование            |   Приём   |  Отдача   |  Небаланс |  Небаланс | Примечание   ');
  filereport_pg.put_p
                  ('|        родительской группы          |           балансной группы          |   кВт*ч   |   кВт*ч   |   кВт*ч   |     %     |              ');
  filereport_pg.put_p
                  ('|                                     |                                     |           |           |           |           |              ');
  filereport_pg.put_p(RPAD('-', 138, '-'));

  FOR lc IN (SELECT DISTINCT gp.gid, gp.NAME
             FROM            GROUPS gp, GROUPS gg
             WHERE           gp.gid = gg.PARENT AND LOWER(gg.vparam) LIKE '%баланс%'
             ORDER BY        gp.NAME) LOOP
   pname := lc.NAME;

   FOR lcc IN (SELECT   gid, NAME
               FROM     GROUPS
               WHERE    PARENT = lc.gid AND LOWER(vparam) LIKE '%баланс%'
               ORDER BY NAME) LOOP
    gname := lcc.NAME;

    SELECT SUM(er), SUM(ed), DECODE(SIGN(util_pg.get_countpoint_f(lcc.gid, 0) - COUNT(DISTINCT mid)), 1, 'Неполный', 'Ok')
    INTO   sum_er, sum_ed, check_err_ok
    FROM   (SELECT h.mid, NVL(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1)), 0) er,
                   NVL(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)), 0) ed
            FROM   halfhour h, GROUPS g
            WHERE  h.date_time > filereport_pg.gd_from AND h.date_time <= filereport_pg.gd_till AND h.mid = g.mid AND g.gid IN(SELECT     gid
                                                                                                                               FROM       GROUPS
                                                                                                                               WHERE      mid IS NOT NULL
                                                                                                                               CONNECT BY PRIOR gid = PARENT
                                                                                                                               START WITH gid = lcc.gid));

    nbalance := sum_er - sum_ed;

    IF sum_er = 0 THEN
     pbalance := 0;
    ELSE
     pbalance := nbalance / sum_er * 100;
    END IF;

    filereport_pg.put_p('| '
     || RPAD(NVL(pname, ' '), 35)
     || ' | '
     || RPAD(NVL(gname, ' '), 35)
     || ' |'
     || LPAD(NVL(TO_CHAR(ROUND(sum_er), '999999999'), ' '), 10)
     || ' |'
     || LPAD(NVL(TO_CHAR(ROUND(sum_ed), '999999999'), ' '), 10)
     || ' |'
     || LPAD(NVL(TO_CHAR(ROUND(nbalance), '999999999'), ' '), 10)
     || ' |'
     || LPAD(NVL(TO_CHAR(ROUND(pbalance, 3), '99999.999'), ' '), 10)
     || ' | '
     || RPAD(NVL(check_err_ok, ' '), 12));
   END LOOP;
  END LOOP;

  filereport_pg.put_p(RPAD('-', 138, '-'));
 END;                                                                                                                                     --PROCEDURE p_balance_

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE p_export_to_billing IS                                                                                                 -- Экспорт в биллинг Одесса ОЭ
  lc_raz     CONSTANT VARCHAR2(2) := '|';
  lc_sep     CONSTANT VARCHAR2(2) := ',';
  ln_customer         NUMBER := util_pg.get_customer_id;
 BEGIN
  IF ln_customer IN(0, 7) THEN
   FOR lc IN (SELECT   f.vaccount, TO_CHAR(b.date_time, 'dd/mm/yyyy') date_time, REPLACE(REPLACE(b.erm, ',', lc_sep), '.', lc_sep) erm,
                       REPLACE(REPLACE(b.aerm, ',', lc_sep), '.', lc_sep) aerm, REPLACE(REPLACE(b.berm, ',', lc_sep), '.', lc_sep) berm,
                       REPLACE(REPLACE(b.cerm, ',', lc_sep), '.', lc_sep) cerm
              FROM     (SELECT   mid, MAX(date_time) date_time, MAX(erm)KEEP (DENSE_RANK LAST ORDER BY date_time) erm,
                                 MAX(aerm)KEEP (DENSE_RANK LAST ORDER BY date_time) aerm, MAX(berm)KEEP (DENSE_RANK LAST ORDER BY date_time) berm,
                                 MAX(cerm)KEEP (DENSE_RANK LAST ORDER BY date_time) cerm
                        FROM     billorg
                        WHERE    mid IN(
                                  SELECT     mid
                                  FROM       GROUPS
                                  CONNECT BY PRIOR gid = PARENT
                                  START WITH gid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 0
                                  UNION ALL
                                  SELECT     mid
                                  FROM       points
                                  CONNECT BY PRIOR mid = PARENT
                                  START WITH mid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 1)
                                 AND date_time >= ADD_MONTHS(TRUNC(filereport_pg.gd_from) + 1, -1) AND date_time < TRUNC(filereport_pg.gd_from) + 1
                                 AND erm IS NOT NULL
                        GROUP BY mid) b,
                       feeders f
              WHERE    b.mid = f.mid AND TRIM(f.vaccount) IS NOT NULL
              ORDER BY f.vaccount, f.mid) LOOP
    filereport_pg.put_p(lc.vaccount || lc_raz || lc.date_time || lc_raz || lc.erm || lc_raz || lc.aerm || lc_raz || lc.berm || lc_raz || lc.cerm || lc_raz);
   END LOOP;
  ELSE
   filereport_pg.put_p('Заказчик не поддерживается.');
  END IF;
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                              --PACKAGE BODY
/


