CREATE OR REPLACE 
PACKAGE BODY priority_pg
IS
-----------------------------------------------------------------------------------------------------
  -- Возвращает первую и вторую ветку
 PROCEDURE getnode(an_parent NUMBER, ret_t OUT common_pg.tcur) IS

 BEGIN
  OPEN ret_t FOR
            select 1 havechild, p.mid, p.name,  0 norder,NULL dstart,NULL dend
            from points p   where    p.mid = an_parent
            union all
            select distinct 0 havechild, 0 mid,
            to_char(r.dstart,'dd.mm.yyyy')||' ... '||to_char(r.dend,'dd.mm.yyyy') name ,  0 norder , r.dstart, r.dend
            from priority r, points p where p.mid=r.mid and p.parent = an_parent and p.ind =3
            order by havechild desc,dstart;

 END;
 -------------------------------------------------------------------------------------------------------------
  -- Возвращает основной курсор
 PROCEDURE getinfo(an_parent NUMBER,ad_dstart DATE,ad_dend DATE, ret_t OUT common_pg.tcur) IS

 BEGIN

  OPEN ret_t FOR
  select 2 havechild,r.mid,p.name, r.norder,r.dstart,r.dend
                      from points p, priority r
                      where   p.mid=r.mid and p.parent = an_parent
                      and r.dstart= ad_dstart and r.dend= ad_dend and p.ind =3
                      order by r.norder ;

 END;
 ----------------------------------------------------------------
   -- Возвращает основной курсор
 PROCEDURE getadd(an_parent NUMBER, ret_t OUT common_pg.tcur) IS

 BEGIN

  OPEN ret_t FOR
          select 2 havechild,p.mid,p.name, p.norder
                      from points p
                      where   p.parent = an_parent and p.ind =3
                      order by p.norder ;

 END;
 ----------------------------------------------------------------

    -- Сохранение
 PROCEDURE upd_p(an_mid NUMBER,ad_oldstart DATE,ad_start DATE,ad_dend DATE,ad_oldend DATE,an_norder NUMBER) IS
 ln_count NUMBER;
 ld_dstart DATE;
 ld_dend DATE;
 ln_flag NUMBER DEFAULT 0;
 BEGIN


 UPDATE priority
     SET dstart= ad_start,
         dend = ad_dend,
         norder = an_norder
   WHERE mid = an_mid AND dstart= ad_oldstart AND dend= ad_oldend;
   IF SQL%ROWCOUNT = 0 THEN
   ln_flag:=1;
   END IF;

   --------------------
    SELECT count(*)
    INTO ln_count
    FROM priority
    WHERE mid=an_mid
    AND (ad_start< dend AND ad_dend > dstart);
    
   IF ((ln_count <> 1 AND ln_flag=0) OR (ln_count <> 0 AND ln_flag=1))  THEN
 
      SELECT dstart,dend
        INTO
          ld_dstart,
          ld_dend
        FROM priority
      WHERE mid=an_mid AND rownum <2
      AND (ad_start< dend AND ad_dend > dstart);
       raise_application_error(-20001, 'Данный период'||ad_start ||' - '||ad_dend ||'
        пересекается с периодом '||ld_dstart ||' - '||ld_dend ||
      ' для которого приоритет источников данных уже задан ');
    ---------------------
    
   ELSE
  
   IF ln_flag =1 THEN
  
         INSERT INTO priority
               (mid, dstart, dend, norder)
        VALUES (an_mid, ad_start, ad_dend, an_norder);
     END IF;
   COMMIT;
   
  END IF;
  
 EXCEPTION
   WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'PRIORITY_PG.upd_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ----------------------------------------------------------------
     -- Удаление
 PROCEDURE del_p(an_mid NUMBER, ad_start DATE,ad_end DATE) IS
 BEGIN
  DELETE FROM priority
        WHERE mid = an_mid AND TRUNC(dstart) = TRUNC(ad_start) AND TRUNC(dend)= TRUNC(ad_end);

 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'PRIORITY_PG.del_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
-------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.PRIORITY_PG

