CREATE OR REPLACE 
PACKAGE BODY qm_pg IS
-------------------------------------------------------------------------------
--пакет для работы с меткой качества
-- 08.10.2008 Сечин А.А.
-------------------------------------------------------------------------------
 gt_limit            vt_number := vt_number();

-------------------------------------------------------------------------------
 FUNCTION defqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_defqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION okqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_okqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION nodataqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_nodataqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION manualqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_manualqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION calcqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_calcqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION sbt(qm VARCHAR2, n NUMBER, val VARCHAR2)
  RETURN VARCHAR2 IS
  lv_qm               VARCHAR2(32) := NVL(qm, cv_defqm);
 BEGIN
  RETURN SUBSTR(lv_qm, 1, n - 1) || val || SUBSTR(lv_qm, n + 1);
 END;

-------------------------------------------------------------------------------
 FUNCTION sbt(qm VARCHAR2, n1 NUMBER, n2 NUMBER, val VARCHAR2)
  RETURN VARCHAR2 IS
  lv_qm               VARCHAR2(32) := NVL(qm, cv_defqm);
 BEGIN
  RETURN SUBSTR(lv_qm, 1, n1 - 1) || LPAD(val, n2 - n1 + 1, val) || SUBSTR(lv_qm, n2 + 1, cn_lenqm - n2);
 END;

-------------------------------------------------------------------------------
 FUNCTION gbt(qm VARCHAR2, n NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  RETURN SUBSTR(qm, n, 1);
 END;

-------------------------------------------------------------------------------
 FUNCTION sumqm(av_qm1 VARCHAR2, av_qm2 VARCHAR2)
  RETURN VARCHAR2 /*RESULT_CACHE*/ IS
  lv_qm1              CHAR(23) := SUBSTR(NVL(av_qm1, cv_defqm), 1, cn_lenqm);
  lv_qm2              CHAR(23) := SUBSTR(NVL(av_qm2, cv_defqm), 1, cn_lenqm);
  lv_ret              VARCHAR2(32);
  lv_ret1             VARCHAR2(32);
  lc_b1               CHAR;
  lc_b2               CHAR;
  lc_qm1              CHAR(9);
  lc_qm2              CHAR(9);
 BEGIN
  --Устанавливаем достоверность (1 бит)
  lc_b1 := SUBSTR(lv_qm1, 1, 1);
  lc_b2 := SUBSTR(lv_qm2, 1, 1);

  IF lc_b1 = cn_reserv OR lc_b2 = cn_reserv THEN                                                --Если есть хоть один cn_reserv то cn_reserv (неполнота данных)
   lv_ret := cn_reserv;
  ELSIF lc_b1 = cn_invalid OR lc_b2 = cn_invalid THEN                                                                   --Если есть хоть один инвалид то инвалид
   lv_ret := cn_invalid;
  ELSIF lc_b1 = cn_question OR lc_b2 = cn_question THEN                                                         --Если есть хоть один cn_question то cn_question
   lv_ret := cn_question;
  ELSE
   lv_ret := cn_ok;
  END IF;

  --Устанавливаем биты (2-12) Битовое "или"
  lv_ret := lv_ret || LPAD(REPLACE(SUBSTR(lv_qm1, 2, 11) + SUBSTR(lv_qm2, 2, 11), '2', cn_yes), 11, cn_no);
  --Устанавливаем биты (13-21) Красивая картинка
  lc_qm1 := SUBSTR(lv_qm1, 13, 9);
  lc_qm2 := SUBSTR(lv_qm2, 13, 9);

  FOR i IN 1 .. 9 LOOP
   lc_b1 := SUBSTR(lc_qm1, i, 1);
   lc_b2 := SUBSTR(lc_qm2, i, 1);

   IF lc_b1 = cn_add_err OR lc_b2 = cn_add_err THEN                                                                                     --Если Хоть одна ошибка
    lv_ret1 := lv_ret1 || cn_add_err;
   ELSIF lc_b1 = cn_add_ok AND lc_b2 = cn_add_ok THEN                                                                                        --Если везде все ОК
    lv_ret1 := lv_ret1 || cn_add_ok;
   ELSIF (lc_b1 = cn_add_def AND lc_b2 IN(cn_add_def, cn_add_ok)) OR(lc_b2 = cn_add_def AND lc_b1 IN(cn_add_def, cn_add_ok)) THEN
    --Если есть cn_add_def то cn_add_def
    lv_ret1 := lv_ret1 || cn_add_def;
   ELSE                                                                                                                              --Иначе недостаточно данных
    lv_ret1 := lv_ret1 || cn_add_insuff;
   END IF;
  END LOOP;

  lv_ret := lv_ret || lv_ret1;
  --Устанавливаем код источника (22 бит)
  lc_b1 := SUBSTR(lv_qm1, 22, 1);
  lc_b2 := SUBSTR(lv_qm2, 22, 1);

  IF lc_b1 = cn_add_def THEN                                                           -- Для (cn_add_def) по оптимизированному поэтому потом про cn_ov забываем
   lv_ret1 := lc_b2;
  ELSIF lc_b2 = cn_add_def THEN                                                        -- Для (cn_add_def) по оптимизированному поэтому потом про cn_ov забываем
   lv_ret1 := lc_b1;
  ELSIF lc_b1 = cn_ov OR lc_b2 = cn_ov THEN                                                  --Для (cn_ov) по оптимизированному поэтому потом про cn_ov забываем
   lv_ret1 := cn_ov;
  ELSIF lc_b1 = cn_calcr OR lc_b2 = cn_calcr THEN                                      --Для (cn_calcr) по оптимизированному поэтому потом про cn_calcr забываем
   lv_ret1 := cn_calcr;
  ELSIF lc_b1 = cn_calc THEN                                                                                                                        -- (cn_calc)
   IF lc_b2 IN(cn_prim, cn_dupl, cn_calc) THEN
    lv_ret1 := cn_calc;
   ELSE
    lv_ret1 := cn_calcr;
   END IF;
  ELSIF lc_b1 = cn_maket THEN                                                                                                                      -- (cn_maket)
   IF lc_b2 = cn_maket THEN
    lv_ret1 := cn_maket;
   ELSE
    lv_ret1 := cn_calcr;
   END IF;
  ELSIF lc_b1 = cn_manual THEN                                                                                                                    -- (cn_manual)
   IF lc_b2 = cn_manual THEN
    lv_ret1 := cn_manual;
   ELSE
    lv_ret1 := cn_calcr;
   END IF;
  ELSIF lc_b1 = cn_oik THEN                                                                                                                          -- (cn_oik)
   IF lc_b2 = cn_oik THEN
    lv_ret1 := cn_oik;
   ELSE
    lv_ret1 := cn_calcr;
   END IF;
  ELSIF lc_b1 = cn_dupl THEN                                                                                                                        -- (cn_dupl)
   IF lc_b2 = cn_dupl THEN
    lv_ret1 := cn_dupl;
   ELSIF lc_b2 IN(cn_prim, cn_calc) THEN
    lv_ret1 := cn_calc;
   ELSE
    lv_ret1 := cn_calcr;
   END IF;
  ELSIF lc_b1 = cn_prim THEN                                                                                                                        -- (cn_prim)
   IF lc_b2 = cn_prim THEN
    lv_ret1 := cn_prim;
   ELSIF lc_b2 IN(cn_dupl, cn_calc) THEN
    lv_ret1 := cn_calc;
   ELSE
    lv_ret1 := cn_calcr;
   END IF;
  END IF;

  --И устанавливаем признак отчетных данных (23 бит) в cn_no всегда (уже установлен)
  lv_ret := lv_ret || lv_ret1 || cn_no;
  --Последнее шаманство ссобственно с дорасчетом (20 бит)
  lc_b1 := SUBSTR(lv_ret, 1, 1);

  IF lc_b1 IN(cn_reserv, cn_invalid) THEN                                                                                        --если нет данных то нет данных
   lv_ret1 := cn_add_insuff;
  ELSIF lc_b1 = cn_question THEN                                                                                                              --если cn_question
   lv_ret1 := cn_add_err;
  ELSE                                                                                                                                                --иначе OK
   lv_ret1 := cn_add_ok;
  END IF;

  RETURN SUBSTR(lv_ret, 1, 19) || lv_ret1 || SUBSTR(lv_ret, 21);
 END;

-------------------------------------------------------------------------------
 FUNCTION setvalidity(av_qm VARCHAR2, av_validity VARCHAR2)
  RETURN VARCHAR2 IS                                                                                                         --Устанавливает метку достоверности
  lc_qm               CHAR := SUBSTR(av_qm, 1, 1);
 BEGIN
  IF (av_validity = cn_question AND lc_qm = cn_ok) OR(av_validity = cn_invalid AND lc_qm IN(cn_ok, cn_question, cn_reserv)) THEN
   RETURN av_validity || SUBSTR(av_qm, 2);
  END IF;

  RETURN av_qm;
 END;

-------------------------------------------------------------------------------
 FUNCTION rungqm(av_qm VARCHAR2)
  RETURN NUMBER IS                                                                                                                  --Для order by  - Ранг метки
  lv_qm               VARCHAR2(32) := NVL(av_qm, cv_defqm);
 BEGIN
  IF SUBSTR(lv_qm, 1, 1) = cn_ok THEN
   RETURN 1;
  ELSIF SUBSTR(lv_qm, 1, 1) = cn_question THEN
   RETURN 2;
  ELSIF SUBSTR(lv_qm, 1, 1) = cn_reserv THEN
   RETURN 3;
  ELSIF SUBSTR(lv_qm, 1, 1) = cn_invalid THEN
   RETURN 4;
  END IF;

  RETURN 1000;
 END;

-------------------------------------------------------------------------------
 FUNCTION intet_to_qm(an_status NUMBER)
  RETURN VARCHAR2 /*RESULT_CACHE*/ IS
  varstatus           VARCHAR2(32);
  evstatus            NUMBER;
  qm                  VARCHAR2(32) DEFAULT cv_okqm;
  valid               NUMBER;
  SOURCE              NUMBER;
  kodsource           NUMBER;
  l                   VARCHAR(1);
 BEGIN
  IF an_status = 0 THEN
   RETURN cv_okqm;
  ELSIF an_status - 100 < 0 THEN
   qm := sbt(qm, 1, 1, cn_reserv);
   qm := sbt(qm, 10, 10, cn_process);
   qm := sbt(qm, 22, 22, cn_add_def);
   RETURN qm;
  ELSIF gbt(TO_CHAR(an_status), 1) = '2' THEN
   qm := sbt(qm, 1, 1, cn_invalid);
   qm := sbt(qm, 10, 10, cn_process);
   qm := sbt(qm, 22, 22, cn_add_def);
   RETURN qm;
  ELSIF gbt(TO_CHAR(an_status), 1) = '1' THEN
   evstatus := an_status - 100;
   qm := cv_okqm;
   valid := cn_ok;
   SOURCE := cn_process;
   kodsource := cn_prim;

   WHILE evstatus > 0 LOOP
    varstatus := varstatus || TO_CHAR(MOD(evstatus, 2));
    evstatus := TRUNC(evstatus / 2);
   END LOOP;

   IF evstatus = 0 THEN
    varstatus := TO_CHAR(evstatus);
   END IF;

   FOR i IN 1 ..(TRUNC(LENGTH(varstatus) / 2)) LOOP
    l := SUBSTR(varstatus, i, 1);
    varstatus := sbt(varstatus, i, i, SUBSTR(varstatus, LENGTH(varstatus) - i + 1, 1));
    varstatus := sbt(varstatus, LENGTH(varstatus) - i + 1, LENGTH(varstatus) - i + 1, l);
   END LOOP;

   FOR i IN 1 .. LENGTH(varstatus) LOOP
    IF gbt(varstatus, i) = '1' THEN
     IF i = 1 THEN
      valid := cn_question;
      qm := sbt(qm, 7, cn_yes);
     ELSIF i = 2 THEN
      kodsource := cn_manual;
      SOURCE := cn_subst;
     ELSIF i = 5 AND kodsource <> cn_manual THEN
      kodsource := cn_calc;
     END IF;
    END IF;
   END LOOP;

   qm := sbt(qm, 1, TO_CHAR(valid));
   qm := sbt(qm, 10, TO_CHAR(SOURCE));
   qm := sbt(qm, 22, TO_CHAR(kodsource));
  END IF;

  RETURN qm;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN sbt(cv_defqm, 13, cn_add_err);
 END;

-------------------------------------------------------------------------------
 FUNCTION ev2_to_qm(an_status NUMBER)
  RETURN VARCHAR2 /*RESULT_CACHE*/ IS
  varstatus           VARCHAR2(32);
  evstatus            NUMBER;
  qm                  VARCHAR2(32) DEFAULT cv_okqm;
  valid               NUMBER;
  SOURCE              NUMBER;
  kodsource           NUMBER;
  l                   VARCHAR(1);
 BEGIN
  IF an_status = 0 THEN
   RETURN cv_okqm;
  ELSE
   evstatus := an_status;
   qm := cv_defqm;
   valid := cn_ok;
   SOURCE := cn_process;
   kodsource := cn_prim;

   WHILE evstatus > 0 LOOP
    varstatus := varstatus || TO_CHAR(MOD(evstatus, 2));
    evstatus := TRUNC(evstatus / 2);
   END LOOP;

   FOR i IN 1 ..(TRUNC(LENGTH(varstatus) / 2)) LOOP
    l := SUBSTR(varstatus, i, 1);
    varstatus := sbt(varstatus, i, i, SUBSTR(varstatus, LENGTH(varstatus) - i + 1, 1));
    varstatus := sbt(varstatus, LENGTH(varstatus) - i + 1, LENGTH(varstatus) - i + 1, l);
   END LOOP;

   FOR i IN 1 .. LENGTH(varstatus) LOOP
    IF gbt(varstatus, i) = '1' THEN
     IF i = 1 THEN
      kodsource := cn_prim;
     ELSIF i = 2 THEN
      SOURCE := cn_subst;
      kodsource := cn_manual;
     ELSIF i = 3 THEN
      valid := cn_question;
      qm := sbt(qm, 7, cn_yes);

      IF kodsource <> cn_manual THEN
       kodsource := cn_add_def;
      END IF;
     ELSIF i > 3 AND kodsource <> cn_manual THEN
      kodsource := cn_calc;
     END IF;
    END IF;
   END LOOP;

   qm := sbt(qm, 1, TO_CHAR(valid));
   qm := sbt(qm, 10, TO_CHAR(SOURCE));
   qm := sbt(qm, 22, TO_CHAR(kodsource));
  END IF;

  RETURN qm;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN sbt(cv_defqm, 13, cn_add_err);
 END;

-------------------------------------------------------------------------------
  --Возвращает метку качества по статусным байтам и преобразование меток Донбасс и Днепр
 FUNCTION get_qm_by_status(an_metertype NUMBER, an_status NUMBER, av_qm VARCHAR2)
  RETURN VARCHAR2 /*RESULT_CACHE*/ IS
  cn_maxp             NUMBER := 30;                                                                                             --Ограничение BITAND в Oracle9i
  cn_max              NUMBER := POWER(2, cn_maxp);
  lv_qm               VARCHAR2(32) DEFAULT NVL(av_qm, okqm);
 BEGIN
  IF gbt(lv_qm, 1) IN(cn_invalid, cn_reserv) THEN                               --Если данных нет или они недостоверны, то ставим недостаточно данных и выходим
   RETURN sbt(lv_qm, 15, cn_add_insuff);
  END IF;

  IF an_metertype = comsrv_pg.cn_lg_zxd THEN                                                                                                              -- ZxD
   lv_qm := sbt(lv_qm, 15, cn_add_ok);                                                                                                      --Сначала ставим ОК
   lv_qm := sbt(lv_qm, 4, cn_no);

   FOR lc IN (SELECT d.nbit, GREATEST(NVL(d.nvalidity, 0), NVL(d1.nvalidity, 0), NVL(d2.nvalidity, 0)) nvalidity
              FROM   meterstatusbitdict d, metereventsdict d1, metereventsdict d2
              WHERE  d.nmetertype = an_metertype AND d.nevent0 = d1.nevent(+) AND d.nevent1 = d2.nevent(+)
                     AND GREATEST(NVL(d.nvalidity, 0), NVL(d1.nvalidity, 0), NVL(d2.nvalidity, 0)) > 0) LOOP
    IF lc.nbit <= cn_maxp AND an_status <= cn_max AND BITAND(an_status, POWER(2, lc.nbit)) = POWER(2, lc.nbit) AND lc.nvalidity IN(1, 2) THEN
     IF lc.nvalidity = 1 THEN                                                                                             --Ставим достоверность "Под вопросом"
      lv_qm := sbt(lv_qm, 1, cn_question);
     ELSIF lc.nvalidity = 2 THEN                                                                                          --Ставим достоверность "Не достоверен"
      lv_qm := sbt(lv_qm, 1, cn_invalid);
     END IF;

     lv_qm := sbt(lv_qm, 4, cn_yes);
    END IF;

    IF gbt(lv_qm, 1) = cn_invalid THEN                                                                                       --Выходим если поставили cn_invalid
     EXIT;
    END IF;
   END LOOP;
  ELSIF an_metertype = comsrv_pg.cn_sl_7000 THEN                                                                                                       --SL-7000
   lv_qm := sbt(lv_qm, 15, cn_add_ok);                                                                                                      --Сначала ставим ОК
   lv_qm := sbt(lv_qm, 4, cn_no);

   FOR lc IN (SELECT nbit, GREATEST(NVL(d.nvalidity, 0), NVL(d1.nvalidity, 0), NVL(d2.nvalidity, 0)) nvalidity, d.nqm
              FROM   meterstatusbitdict d, metereventsdict d1, metereventsdict d2
              WHERE  d.nmetertype = an_metertype AND d.nevent0 = d1.nevent(+) AND d.nevent1 = d2.nevent(+)
                     AND GREATEST(NVL(d.nvalidity, 0), NVL(d1.nvalidity, 0), NVL(d2.nvalidity, 0)) > 0) LOOP
    IF lc.nbit <= cn_maxp AND an_status <= cn_max AND BITAND(an_status, POWER(2, lc.nbit)) = POWER(2, lc.nbit) AND lc.nvalidity IN(1, 2) THEN
     IF lc.nvalidity = 1 THEN                                                                                             --Ставим достоверность "Под вопросом"
      lv_qm := sbt(lv_qm, 1, cn_question);
     ELSIF lc.nvalidity = 2 THEN                                                                                          --Ставим достоверность "Не достоверен"
      lv_qm := sbt(lv_qm, 1, cn_invalid);
     END IF;

     IF lc.nqm BETWEEN 2 AND 9 THEN
      lv_qm := sbt(lv_qm, lc.nqm, cn_yes);
     END IF;
    END IF;

    IF gbt(lv_qm, 1) = cn_invalid THEN                                                                                       --Выходим если поставили cn_invalid
     EXIT;
    END IF;
   END LOOP;
  END IF;

  RETURN lv_qm;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN sbt(lv_qm, 15, cn_add_insuff);
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_limit(an_mid NUMBER)
  RETURN vt_number                                                                                                                              /*RESULT_CACHE*/
                  IS
 BEGIN
  --gt_limit(1) Это POINTS.MID
  IF gt_limit.COUNT = 0 OR NVL(gt_limit(1), 0) <> NVL(an_mid, 0) THEN
   gt_limit.DELETE;
   gt_limit.EXTEND(17);
   gt_limit(1) := an_mid;

   FOR lc IN (SELECT DECODE(nsort, -5, 1, -6, 2, -11, 3, -12, 4, -17, 5, -18, 6, -23, 7, -24, 8, -3, 9, -4, 10, -9, 11, -10, 12, -15, 13, -16, 14, -21,
                      15, -22, 16) + 1 nsort, util_pg.allnumber_f(a.vvalue) val
              FROM   addpointparamval a
              WHERE  a.mid = an_mid AND a.nsort IN(-24, -23, -18, -17, -12, -11, -6, -5, -22, -21, -16, -15, -10, -9, -4, -3) AND a.vvalue > 0) LOOP
    gt_limit(lc.nsort) := lc.val;
   END LOOP;
  END IF;

  RETURN gt_limit;
 END;

------------------------------------------------------------------------------------------------------------------------
--Контроль границ
 FUNCTION checklimit(an_mid NUMBER, av_qm VARCHAR2, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER)
  RETURN VARCHAR2 IS
  lv_qm               VARCHAR2(32) DEFAULT av_qm;
  ln_er               NUMBER DEFAULT an_er;
  ln_ed               NUMBER DEFAULT an_ed;
  ln_q1               NUMBER DEFAULT util_pg.sumn(an_q1, an_q2);
  ln_q3               NUMBER DEFAULT util_pg.sumn(an_q3, an_q4);
  ln_kc               NUMBER DEFAULT 2;
  lt_limit            vt_number;
 BEGIN
  IF gbt(av_qm, 1) IN(cn_invalid, cn_reserv) THEN                               --Если данных нет или они недостоверны, то ставим недостаточно данных и выходим
   RETURN sbt(lv_qm, 16, cn_add_insuff);
  END IF;

  lt_limit := get_limit(an_mid);
  ln_er := ln_kc * ln_er;
  ln_ed := ln_kc * ln_ed;
  ln_q1 := ln_kc * ln_q1;
  ln_q3 := ln_kc * ln_q3;

  IF (
      ln_er < lt_limit(2) OR ln_er > lt_limit(3) OR ln_ed < lt_limit(4) OR ln_ed > lt_limit(5) OR ln_q1 < lt_limit(6) OR ln_q1 > lt_limit(7)
      OR ln_q3 < lt_limit(8) OR ln_q3 > lt_limit(9)
     ) THEN
   --Если зашли за физ границу то достоверность invalid
   lv_qm := sbt(lv_qm, 16, cn_add_err);
   lv_qm := sbt(lv_qm, 3, cn_yes);
   lv_qm := sbt(lv_qm, 1, cn_invalid);
  ELSIF(
        ln_er < lt_limit(10) OR ln_er > lt_limit(11) OR ln_ed < lt_limit(12) OR ln_ed > lt_limit(13) OR ln_q1 < lt_limit(14) OR ln_q1 > lt_limit(15)
        OR ln_q3 < lt_limit(16) OR ln_q3 > lt_limit(17)
       ) THEN
   --Если зашли за авар границу то достоверность invalid
   lv_qm := sbt(lv_qm, 16, cn_add_err);
   lv_qm := sbt(lv_qm, 3, cn_yes);
   lv_qm := sbt(lv_qm, 1, cn_question);
  ELSE                                                                                                                                             --Все в норме
   lv_qm := sbt(lv_qm, 16, cn_add_ok);
   lv_qm := sbt(lv_qm, 3, cn_no);
  END IF;

  RETURN lv_qm;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN sbt(lv_qm, 16, cn_add_insuff);
 END;
------------------------------------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.QM_PG

