CREATE OR REPLACE 
PACKAGE BODY rates_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- тарификация по режимным суткам
   -- дата создания 23.04.2002 (Коваленко А.С.)
 gn_task_code NUMBER DEFAULT 60;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setendtime IS
 BEGIN
  UPDATE rates
     SET TIME = TIME - TRUNC(TIME, 'yyyy') + TRUNC(TIME, 'cc');
    
  UPDATE rates r
     SET endtime = (SELECT MIN(TIME)
                      FROM rates
                     WHERE rid = r.rid AND TIME > r.TIME);
  UPDATE rates r
     SET endtime = TRUNC(TIME) + 1 - 1 / 86400
   WHERE endtime IS NULL;
 --  commit;
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Сохранение изменений по тарифам на указанную дату
 PROCEDURE update_tariff_p(
  an_schdue      IN NUMBER, 
  an_rid         IN NUMBER, -- rid идентификатор тарифа
  ad_switch_date IN DATE, -- дата внедрения тарифа
  av_times       IN common_pg.tt_varchar2, -- массив строк - времена тарифных зон в формате 'hh24:mi:ss'
  av_rates       IN common_pg.tt_number -- массив строк - тарифы
  --an_fchange     IN NUMBER -- флаг изменения тарифов - 1-новый, 2-редактировать, 3-удалить
                          ) IS
  ln_rid  NUMBER;
  ln_date DATE;
  lv_msg  VARCHAR2(200);
 BEGIN
     SELECT switch_date
          INTO ln_date
           FROM rate_list
           WHERE rid = an_rid;
            ln_rid := an_rid;
      IF ln_date<>ad_switch_date THEN
      -- lv_msg := 'Изменено расписание на дату ' || TO_CHAR(ln_date, 'dd.mm.yyyy hh24:mi:ss');
       lv_msg := lv_msg || ' Новая дата ввода ' || TO_CHAR(ad_switch_date, 'dd.mm.yyyy hh24:mi:ss');
       admin_pg.fiscal_p(gn_task_code, 2, lv_msg);
       UPDATE rate_list
        SET switch_date = ad_switch_date,
            NSCHEDULELIST = an_schdue
       WHERE rid = an_rid;
       END IF;
       DELETE FROM rates
         WHERE rid = an_rid;
         FOR i IN 1 .. av_times.COUNT LOOP
            IF  av_times.EXISTS(i) AND av_rates.EXISTS(i) THEN
       INSERT INTO rates
                (rid, TIME, rate)
         VALUES (ln_rid, TO_DATE('20000101 '||av_times(i), 'YYYYMMDD hh24:mi'), av_rates(i));
          END IF;
          END LOOP;
        
     setendtime;
  lv_msg := 'Изменено расписание на дату ' || TO_CHAR(ln_date, 'dd.mm.yyyy hh24:mi:ss');
  EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'rates_pg.update_tariff_p: ' || CHR(10) || SQLERRM(SQLCODE));

 END;
 -------------------------------------------------------------------------------------------------
  PROCEDURE ins_tariff_p(
  an_schdue      IN NUMBER,
  ad_switch_date IN DATE, -- дата внедрения тарифа
  av_times       IN common_pg.tt_varchar2, -- массив строк - времена тарифных зон в формате 'hh24:mi:ss'
  av_rates       IN common_pg.tt_number, -- массив строк - тарифы
  an_rid         OUT NUMBER -- rid идентификатор тарифа
                          ) IS

  ln_rid  NUMBER;
  ln_date DATE;
  lv_msg  VARCHAR2(200);
  BEGIN
    SELECT limits_seq.NEXTVAL
             INTO ln_rid
             FROM DUAL;
             an_rid:=ln_rid;
              admin_pg.fiscal_p(
              gn_task_code, 1, 'Добавлено расписание тарифов на дату ' || TO_CHAR(ad_switch_date, 'dd.mm.yyyy hh24:mi:ss'));
            INSERT INTO rate_list
              (rid, switch_date, NSCHEDULELIST)
             VALUES (ln_rid, ad_switch_date, an_schdue);
              FOR i IN 1 .. av_times.COUNT LOOP
            IF  av_times.EXISTS(i) AND av_rates.EXISTS(i) THEN
           INSERT INTO rates
                (rid, TIME, rate)
         VALUES (ln_rid, TO_DATE('20000101 '||av_times(i), 'YYYYMMDD hh24:mi'), av_rates(i));
          END IF;
          END LOOP;
    setendtime;
   EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'rates_pg.ins_tariff_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
PROCEDURE del_tariff_p(
    an_rid         IN NUMBER) IS     -- rid идентификатор тарифа
  ln_date DATE;
 
 BEGIN
    SELECT switch_date
          INTO ln_date
           FROM rate_list
           WHERE rid = an_rid;
     admin_pg.fiscal_p(
     gn_task_code, 3, 'Удалено расписание тарифов на дату ' || TO_CHAR(ln_date, 'dd.mm.yyyy hh24:mi:ss'));
            
      DELETE FROM rate_list
         WHERE rid = an_rid;
  EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'rates_pg.del_tariff_p: ' || CHR(10) || SQLERRM(SQLCODE));
END;
----------------------------------------------------------------------------------------
 --Клонирование расписания на след год
 PROCEDURE clone_p (an_schdue IN NUMBER) IS
  ld_start DATE;
  ln_rid   NUMBER;
 BEGIN
  SELECT TRUNC(MAX(switch_date), 'YYYY')
    INTO ld_start
    FROM rate_list
    WHERE rate_list.NSCHEDULELIST = an_schdue; 
  FOR lc IN (SELECT rid, ADD_MONTHS(switch_date, 12) dat
               FROM rate_list
              WHERE switch_date >= ld_start AND rate_list.NSCHEDULELIST = an_schdue) LOOP
   SELECT limits_seq.NEXTVAL
     INTO ln_rid
     FROM DUAL;
   INSERT INTO rate_list
               (rid, switch_date, NSCHEDULELIST)
        VALUES (ln_rid, lc.dat, an_schdue);
   INSERT INTO rates
               (rid, TIME, rate, endtime)
    SELECT ln_rid, TIME, rate, endtime
      FROM rates
     WHERE rid = lc.rid;
  END LOOP;
  IF ld_start is not null then
   admin_pg.fiscal_p(
    gn_task_code, 1, 'Выполнено клонирование расписания тарифных зон на ' || TO_CHAR(ld_start, 'yyyy')||' год.');
   COMMIT;
  end if;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'rates_pg.clone_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
-- Процедура чтения id
 PROCEDURE select_rid_p (shedule NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
   SELECT r.rid, to_char(r.switch_date,'dd.mm.yyyy') switch_date1, r.NSCHEDULELIST
   FROM  rate_list r 
   WHERE r.NSCHEDULELIST = shedule
   ORDER BY switch_date desc;
 END;
 -------------------------------------------------------------------------------------------------------------------------
 -- Процедура чтения данных
 PROCEDURE read_data_p (an_rid NUMBER ,acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
   SELECT to_char(time,'hh24:mi')time1, rate
                  FROM  rates
                  WHERE rid =an_rid
                  ORDER BY time;
                  
 END;
 PROCEDURE get_shedues (shedues OUT common_pg.tcur) IS
 BEGIN
  OPEN shedues FOR
   SELECT s.NSCHEDULELIST, s.VNAME, s.NCOUNT
   FROM SCHEDULELIST s
   ORDER BY s.NSCHEDULELIST;
 END;
 -------------------------------------------------------------------------------------------------------------------------
END; -- Package Body RATE_PG
/


-- End of DDL Script for Package Body RYDA.RATES_PG

-- Start of DDL Script for Package Body RYDA.REORGANIZEHF_PG
-- Generated 14.04.2014 9:34:59 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY reorganizehf_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет реорганизации данных в таблице halfhour
  -- дата создания 03/01/2010 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE copydata (ad_date DATE) IS
  ld_date     DATE   := TRUNC (ad_date);
  ln_mid      NUMBER;
  ln_source   NUMBER;
 BEGIN
  --На основную точку
  INSERT INTO halfhourold
              (mid, date_time, nsource, er, q1, ed, q3, q2, q4, erm, q1m, edm, q3m, q2m, q4m, status, nswitch, nexceptcalc, dclosed, nkc, er_mtrsn, denter, vqm,
               nmetertype)
   SELECT   h.mid, h.date_time, DECODE (h.nsource, 50, 50, 59, 59, 19, 19, 29, 19, 39, 39, 49, 39, DECODE (TRUNC (nsource / 10), 3, 30, 4, 30, 10)) nsource, h.er,
            h.q1, h.ed, h.q3, h.q2, h.q4, h.erm, h.q1m, h.edm, h.q3m, h.q2m, h.q4m, h.status, h.nswitch, h.nexceptcalc, h.dclosed, h.nkc, h.er_mtrsn, nvl(h.denter,h.date_time) denter,
            h.vqm, h.nmetertype
       FROM halfhouroldold h
      WHERE h.date_time > ld_date AND h.date_time <= ld_date + 1 AND h.nsource BETWEEN 10 AND 59 AND h.nexceptcalc IS NULL AND h.mid IN (SELECT mid
                                                                                                                                           FROM points)
   ORDER BY mid, date_time;

  FOR lc IN (SELECT   h.mid, h.date_time, h.nsource, h.er, h.q1, h.ed, h.q3, h.q2, h.q4, h.erm, h.q1m, h.edm, h.q3m, h.q2m, h.q4m, h.status, h.nswitch,
                      h.nexceptcalc, h.dclosed, h.nkc, h.er_mtrsn, nvl(h.denter,h.date_time) denter, h.vqm, h.nmetertype
                 FROM halfhouroldold h
                WHERE h.date_time > ld_date AND h.date_time <= ld_date + 1 AND (h.nsource BETWEEN 10 AND 29 OR h.nsource IN (50, 59)) AND h.nswitch IS NULL
                      AND h.mid IN (SELECT mid
                                      FROM points)
             ORDER BY h.mid, h.date_time, h.nsource DESC) LOOP
   --На основной поставщик
   ln_mid := NULL;

   IF lc.nsource IN (50, 59) THEN
    ln_mid := util_pg.getsourcepoint (lc.mid, 5);
    ln_source := lc.nsource;
   ELSIF lc.nsource BETWEEN 10 AND 19 THEN   --  DECODE (h.nsource, 19, 19, 29, 19, 10)
    ln_mid := util_pg.getsourcepoint (lc.mid, 1);

    IF lc.nsource = 19 THEN
     ln_source := 19;
    ELSE
     ln_source := 10;
    END IF;
   ELSIF lc.nsource BETWEEN 20 AND 29 THEN   --  DECODE (h.nsource, 19, 19, 29, 19, 10)
    SELECT util_pg.getsourcepoint (lc.mid, DECODE (COUNT (*), 1, 2, 3))
      INTO ln_mid
      FROM DUAL
     WHERE EXISTS (SELECT *
                     FROM chanpoint cp, channels c
                    WHERE cp.mid = lc.mid AND cp.cid = c.cid AND c.protocol_id = 37);

    IF lc.nsource = 29 THEN
     ln_source := 19;
    ELSE
     ln_source := 10;
    END IF;
   END IF;

   IF ln_mid > 0 THEN
    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, nsource, er, q1, ed, q3, q2, q4, erm, q1m, edm, q3m, q2m, q4m, status, nswitch,
                  nexceptcalc, dclosed, nkc, er_mtrsn, denter, vqm, nmetertype
                 )
          VALUES (ln_mid, lc.date_time, ln_source, lc.er, lc.q1, lc.ed, lc.q3, lc.q2, lc.q4, lc.erm, lc.q1m, lc.edm, lc.q3m, lc.q2m, lc.q4m, lc.status, lc.nswitch,
                  lc.nexceptcalc, lc.dclosed, lc.nkc, lc.er_mtrsn, lc.denter, lc.vqm, lc.nmetertype
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      NULL;
     WHEN OTHERS THEN
      RAISE;
    END;
   END IF;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'REORGANIZEHF_PG.copydata: ad_date=' || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss') || CHR (10) || SQLERRM);
 END;

