 PROCEDURE copybill (ad_date DATE) IS
  ld_date   DATE   := TRUNC (ad_date);
  ln_mid    NUMBER;
 BEGIN
  --На основную точку
  FOR lc IN (SELECT b.mid, b.date_time, b.valid, b.SOURCE, b.remark, b.er_mtrsn, b.er_kc, b.erm, b.er, b.aerm, b.aer, b.berm, b.ber, b.cerm, b.cer, b.derm, b.der,
                    b.q1_mtrsn, b.q1_kc, b.q1m, b.q1, b.aq1m, b.aq1, b.bq1m, b.bq1, b.cq1m, b.cq1, b.dq1m, b.dq1, b.ed_mtrsn, b.ed_kc, b.edm, b.ed, b.aedm, b.aed,
                    b.bedm, b.bed, b.cedm, b.ced, b.dedm, b.ded, b.q3_mtrsn, b.q3_kc, b.q3m, b.q3, b.aq3m, b.aq3, b.bq3m, b.bq3, b.cq3m, b.cq3, b.dq3m, b.dq3,
                    b.q2_mtrsn, b.q2_kc, b.q2m, b.q2, b.aq2m, b.aq2, b.bq2m, b.bq2, b.cq2m, b.cq2, b.dq2m, b.dq2, b.q4_mtrsn, b.q4_kc, b.q4m, b.q4, b.aq4m, b.aq4,
                    b.bq4m, b.bq4, b.cq4m, b.cq4, b.dq4m, b.dq4, b.nwasteabs, b.nsource, nvl(b.denter,b.date_time) denter
               FROM billorg b
              WHERE b.date_time > ld_date AND b.date_time <= ld_date + 1) LOOP
   ln_mid := NULL;

   IF lc.nsource = 10 THEN
    ln_mid := util_pg.getsourcepoint (lc.mid, 1);

    IF NVL (ln_mid, 0) = 0 THEN
     ln_mid := util_pg.getsourcepoint (lc.mid, 2);
    END IF;
   ELSIF lc.nsource = 20 THEN
    ln_mid := util_pg.getsourcepoint (lc.mid, 3);
   ELSIF lc.nsource = 50 THEN
    ln_mid := util_pg.getsourcepoint (lc.mid, 5);
   END IF;

   IF ln_mid > 0 THEN
    BEGIN
     INSERT INTO billorg
                 (mid, date_time, valid, SOURCE, remark, er_mtrsn, er_kc, erm, er, aerm, aer, berm, ber, cerm, cer,
                  derm, der, q1_mtrsn, q1_kc, q1m, q1, aq1m, aq1, bq1m, bq1, cq1m, cq1, dq1m, dq1, ed_mtrsn, ed_kc,
                  edm, ed, aedm, aed, bedm, bed, cedm, ced, dedm, ded, q3_mtrsn, q3_kc, q3m, q3, aq3m, aq3,
                  bq3m, bq3, cq3m, cq3, dq3m, dq3, q2_mtrsn, q2_kc, q2m, q2, aq2m, aq2, bq2m, bq2, cq2m, cq2,
                  dq2m, dq2, q4_mtrsn, q4_kc, q4m, q4, aq4m, aq4, bq4m, bq4, cq4m, cq4, dq4m, dq4, nwasteabs,
                  nsource, denter
                 )
          VALUES (ln_mid, lc.date_time, lc.valid, lc.SOURCE, lc.remark, lc.er_mtrsn, lc.er_kc, lc.erm, lc.er, lc.aerm, lc.aer, lc.berm, lc.ber, lc.cerm, lc.cer,
                  lc.derm, lc.der, lc.q1_mtrsn, lc.q1_kc, lc.q1m, lc.q1, lc.aq1m, lc.aq1, lc.bq1m, lc.bq1, lc.cq1m, lc.cq1, lc.dq1m, lc.dq1, lc.ed_mtrsn, lc.ed_kc,
                  lc.edm, lc.ed, lc.aedm, lc.aed, lc.bedm, lc.bed, lc.cedm, lc.ced, lc.dedm, lc.ded, lc.q3_mtrsn, lc.q3_kc, lc.q3m, lc.q3, lc.aq3m, lc.aq3,
                  lc.bq3m, lc.bq3, lc.cq3m, lc.cq3, lc.dq3m, lc.dq3, lc.q2_mtrsn, lc.q2_kc, lc.q2m, lc.q2, lc.aq2m, lc.aq2, lc.bq2m, lc.bq2, lc.cq2m, lc.cq2,
                  lc.dq2m, lc.dq2, lc.q4_mtrsn, lc.q4_kc, lc.q4m, lc.q4, lc.aq4m, lc.aq4, lc.bq4m, lc.bq4, lc.cq4m, lc.cq4, lc.dq4m, lc.dq4, lc.nwasteabs,
