  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'REORGANIZEHF_PG.copybill: ad_date=' || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss') || CHR (10) || SQLERRM);
