CREATE OR REPLACE 
PACKAGE BODY reports1_pg IS
------------------------------------------------------------------------------------------------------------------------
 cn_rn      CONSTANT NUMBER := 10;                                                                                                          --Округляем расходы
 cn_rnm     CONSTANT NUMBER := 15;                                                                                                        --Округляем показания

------------------------------------------------------------------------------------------------------------------------
 FUNCTION frm_number(a NUMBER)
  RETURN VARCHAR2;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE begin_m30817(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2);

 PROCEDURE end_m30817(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2);

 PROCEDURE m30817base_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2, an_withqm NUMBER DEFAULT 0);

------------------------------------------------------------------------------------------------------------------------
   -- пакет по созданию отчетов в файл
   -- дата создания 27/07/2002 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
--Служебный ХАРТЭП
 PROCEDURE lastsave_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  lv_tab     CONSTANT VARCHAR2(1) := CHR(9);

  CURSOR lcur_sel IS
   SELECT      pp.NAME
            || lv_tab
            || p.NAME
            || lv_tab
            || TO_CHAR(PROFILE, 'DD.MM.YYYY HH24:MI:SS')
            || lv_tab
            || TO_CHAR(halfhour, 'DD.MM.YYYY HH24:MI:SS')
            || lv_tab
            || TO_CHAR(bill, 'DD.MM.YYYY HH24:MI:SS')
            || lv_tab
            || TO_CHAR(months, 'DD.MM.YYYY HH24:MI:SS')
            || lv_tab
            || clock
            || lv_tab
            || TO_CHAR(state_date, 'DD.MM.YYYY HH24:MI:SS')
            || lv_tab
            || state_cod
            || lv_tab
            || state_descr
            || lv_tab
            || TO_CHAR(luck, 'DD.MM.YYYY HH24:MI:SS')
            || lv_tab
            || TO_CHAR(trial, 'DD.MM.YYYY HH24:MI:SS') nn
   FROM     last_save b, points p, points pp
   WHERE    b.mid = p.mid AND p.PARENT = pp.mid
   ORDER BY pp.NAME, p.NAME;

  CURSOR lcur_sel1 IS
   SELECT      '('
            || mid
            || ',to_date('
            || TO_CHAR(date_time, 'yyyymmddhh24mi')
            || ',''yyyymmddhh24mi''),'
            || NVL(TO_CHAR(nsource), 'NULL')
            || ','
            || NVL(TO_CHAR(nkc), 'NULL')
            || ','
            || NVL(TO_CHAR(er), 'NULL')
            || ','
            || NVL(TO_CHAR(ed), 'NULL')
            || ','
            || NVL(TO_CHAR(q1), 'NULL')
            || ','
            || NVL(TO_CHAR(q3), 'NULL')
            || ');' t
   FROM     halfhour
   WHERE    date_time > ad_date AND date_time <= ad_date + 2
   ORDER BY mid, date_time, nsource;
 BEGIN
  file_pg.out_p('Отчет за:' || TO_CHAR(ad_date, 'DD.MM.YYYY HH24:MI:SS') || '  Текущая дата:' || TO_CHAR(SYSDATE, 'DD.MM.YYYY HH24:MI:SS'));

  FOR lc IN lcur_sel LOOP
   file_pg.out_p(lc.nn);
  END LOOP;

  IF util_pg.is_dayswitch(ad_date) <> 0 THEN
   file_pg.out_p(LPAD('-', 30, '-'));

   FOR lc IN lcur_sel1 LOOP
    file_pg.out_p(lc.t);
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.lastsave_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Макет 1010
 PROCEDURE m1010_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_g IS
   SELECT   ngroup, NVL(vcode, get_vcode(ngroup)) vcode
   FROM     maketgroups
   WHERE    nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mid, nkc, ntype
   FROM   maketpoints
   WHERE  ngroup = lc_group;

  CURSOR lcur_s(lc_group NUMBER) IS
   SELECT     nsubgroup, nsign
   FROM       maketformulas
   CONNECT BY PRIOR nsubgroup = ngroup
   START WITH ngroup = lc_group;

  ln_ras              NUMBER;
  ln_allras           NUMBER;
  ln_div              NUMBER;
  lv_bstr             VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  -- Определяем формат вывода (в тыс. кВт*ч или кВт*ч)
  IF util_pg.get_param(lv_bstr, 1) = '1' THEN
   ln_div := 1;
  ELSE
   ln_div := 1000;
  END IF;

  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  file_pg.out_p('##01010 ' || TRIM(util_pg.enterprise_f) || ' ' || TO_CHAR(ad_date, 'YYMMDD'));

  FOR lc_g IN lcur_g LOOP
   ln_allras := 0;

   FOR lc_p IN lcur_p(lc_g.ngroup) LOOP
    SELECT   lc_p.nkc
           * SUM(DECODE(
               lc_p.ntype,
               1, b.er,
               2, b.ed,
               3, b.q1,
               4, b.q3,
               5, util_pg.sld(b.mid, NVL(b.er, 0), NVL(b.ed, 0)),
               6, util_pg.sld(b.mid, NVL(b.q1, 0), NVL(b.q3, 0))
              ))
    INTO   ln_ras
    FROM   halfhour b
    WHERE  b.mid = lc_p.mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1;

    ln_allras := ln_allras + NVL(ln_ras, 0);
   END LOOP;

   FOR lc_s IN lcur_s(lc_g.ngroup) LOOP
    FOR lc_p IN lcur_p(lc_s.nsubgroup) LOOP
     SELECT   lc_p.nkc
            * SUM(DECODE(
                lc_p.ntype,
                1, b.er,
                2, b.ed,
                3, b.q1,
                4, b.q3,
                5, util_pg.sld(b.mid, NVL(b.er, 0), NVL(b.ed, 0)),
                6, util_pg.sld(b.mid, NVL(b.q1, 0), NVL(b.q3, 0))
               ))
     INTO   ln_ras
     FROM   halfhour b
     WHERE  b.mid = lc_p.mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1;

     ln_allras := ln_allras + NVL(ln_ras, 0) * lc_s.nsign;
    END LOOP;
   END LOOP;

   file_pg.out_p(TO_CHAR(ad_date, 'DD') || ' ' || lc_g.vcode || ' ' || ROUND(ln_allras / ln_div));
  END LOOP;

  file_pg.out_p('##');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m1010_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Макет 1010 с показаниями
 PROCEDURE m1010met_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_g IS
   SELECT   ngroup, NVL(vcode, get_vcode(ngroup)) vcode
   FROM     maketgroups
   WHERE    nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mid, nkc, ntype
   FROM   maketpoints
   WHERE  ngroup = lc_group;

  CURSOR lcur_s(lc_group NUMBER) IS
   SELECT     nsubgroup, nsign
   FROM       maketformulas
   CONNECT BY PRIOR nsubgroup = ngroup
   START WITH ngroup = lc_group;

  ln_ras              NUMBER;
  ln_allras           NUMBER;
  ln_met_st           NUMBER;
  ln_met_end          NUMBER;
  ln_type             NUMBER;
  ln_pcount           NUMBER;
  ln_div              NUMBER;
  lv_bstr             VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  -- Определяем формат вывода (в тыс. кВт*ч или кВт*ч)
  IF util_pg.get_param(lv_bstr, 1) = '1' THEN
   ln_div := 1;
  ELSE
   ln_div := 1000;
  END IF;

  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  file_pg.out_p('##01010 ' || TRIM(util_pg.enterprise_f) || ' ' || TO_CHAR(ad_date, 'YYMMDD'));

  FOR lc_g IN lcur_g LOOP                                                                                                        -- Вытягиваем все группы макета
   ln_allras := 0;
   ln_pcount := 0;

   FOR lc_p IN lcur_p(lc_g.ngroup) LOOP                                                                                        -- Цикл для всех точек по группе
    ln_met_st := NULL;
    ln_met_end := NULL;

    SELECT   lc_p.nkc
           * SUM(DECODE(
               lc_p.ntype,
               1, b.er,
               2, b.ed,
               3, b.q1,
               4, b.q3,
               5, util_pg.sld(b.mid, NVL(b.er, 0), NVL(b.ed, 0)),
               6, util_pg.sld(b.mid, NVL(b.q1, 0), NVL(b.q3, 0))
              ))
    INTO   ln_ras
    FROM   halfhour b
    WHERE  b.mid = lc_p.mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1;

    ln_allras := ln_allras + NVL(ln_ras, 0);

    SELECT DECODE(lc_p.ntype, 1, 1, 2, 2, 3, 3, 4, 5, NULL)
    INTO   ln_type
    FROM   DUAL;

    IF ln_type > 0 THEN
     ln_met_st := util_pg.get_meterage(lc_p.mid, TRUNC(ad_date), ln_type);
     ln_met_end := util_pg.get_meterage(lc_p.mid, TRUNC(ad_date) + 1, ln_type);
    END IF;

    ln_pcount := ln_pcount + 1;

    IF ln_pcount > 1 THEN
     ln_met_st := NULL;
     ln_met_end := NULL;
    END IF;
   END LOOP;

   FOR lc_s IN lcur_s(lc_g.ngroup) LOOP
    FOR lc_p IN lcur_p(lc_s.nsubgroup) LOOP
     SELECT   lc_p.nkc
            * SUM(DECODE(
                lc_p.ntype,
                1, b.er,
                2, b.ed,
                3, b.q1,
                4, b.q3,
                5, util_pg.sld(b.mid, NVL(b.er, 0), NVL(b.ed, 0)),
                6, util_pg.sld(b.mid, NVL(b.q1, 0), NVL(b.q3, 0))
               ))
     INTO   ln_ras
     FROM   halfhour b
     WHERE  b.mid = lc_p.mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1;

     ln_allras := ln_allras + NVL(ln_ras, 0) * lc_s.nsign;
    END LOOP;
   END LOOP;

   file_pg.out_p(TO_CHAR(ad_date, 'DD') || ' ' || lc_g.vcode || ' ' || ROUND(ln_allras / ln_div) || ' ' || ln_met_end || ' ' || ln_met_st);
  END LOOP;

  file_pg.out_p('##');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m1010_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE begin_m30817(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
 --
-- Purpose: Формирование М30817 с переносом остатков округлений
--
-- MODIFICATION HISTORY
-- Person      Date    Comments
-- ---------   ------  -------------------------------------------
-- Вештак      30.12.02
-- Вештак      28.10.04 Переход на зимнее/летнее время
  ln_sign             NUMBER;
  ln_groupcode        NUMBER;
  ln_subgroupcode     NUMBER;
  ln_temp             NUMBER;
  hc                  NUMBER;                                                                                                          -- кол-во часов в сутках
  ln_hc               NUMBER;                                                                                                     -- реал кол-во часов в сутках
  ln_div              NUMBER DEFAULT 1;                                                                                                              --Делитель
  lv_bstr             VARCHAR2(2000);
  ln_null             NUMBER DEFAULT 0;
  ln_needround30817   NUMBER;
  lb_full             BOOLEAN := TRUE;                                                                                                -- признак полноты данных
  ln_pcnt             NUMBER := 0;                                                                                                     -- кол-во точек в группе
  lv_qm               VARCHAR2(32);
  ln_needtrunc        NUMBER;                                                                                                      -- делать TRUNC вместо ROUND
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  -- Определяем формат вывода (в тыс. кВт*ч или кВт*ч)
  IF util_pg.get_param(lv_bstr, 1) = '1' THEN
   ln_div := 1000;
  END IF;

  IF util_pg.get_param(lv_bstr, 9) = '1' THEN
   ln_needtrunc := 1;
  ELSE
   ln_needtrunc := 0;
  END IF;

  ln_hc := 24 - util_pg.is_dayswitch(ad_date);
  hc := ln_hc;

  IF hc = 23 THEN
   hc := 24;
  END IF;

  -- Выборка в рабочую таблицу формул расчета агрегированных макетных строк
  DELETE FROM makettemp;

  INSERT INTO makettemp
              (ngroup, nsubgroup, nsign)
   SELECT ngroup, nsubgroup, nsign
   FROM   maketformulas
   WHERE  ngroup IN(SELECT ngroup
                    FROM   maketgroups
                    WHERE  nmaket = an_maket);

  -- В рабочей таблице проставляются ид всех строк макета, кроме агрегированных
  DELETE FROM m30817;

  INSERT INTO m30817
              (ngroup, HOUR, kwh, err)
   SELECT ngroup, 0, DECODE(ln_null, 0, 0, NULL), 0
   FROM   maketgroups
   WHERE  nmaket = an_maket AND ngroup NOT IN(SELECT ngroup
                                              FROM   makettemp);

  -- По тем строкам, где есть данные рассчитываются и сохраняются расходы без 25 часа
  INSERT INTO m30817
              (ngroup, HOUR, kwh, err, vqm)
   SELECT   p.ngroup, TO_CHAR(date_time - 1 / 1440, 'hh24') + 1,
            SUM(p.nkc
             * DECODE(
                ntype,
                1, h.er,
                2, h.ed,
                3, h.q1,
                4, h.q3,
                5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
               )),
            COUNT(*),
            DECODE(
             SIGN(util_pg.get_countpoint_f(p.ngroup, 2) - COUNT(DISTINCT h.mid)),
             1, qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm),
             NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm)
            ) vqm
   FROM     maketgroups g, maketpoints p, halfhour h
   WHERE    g.nmaket = an_maket AND g.ngroup NOT IN(SELECT ngroup
                                                    FROM   makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC(ad_date)
            AND h.date_time <= TRUNC(ad_date) + 1 AND h.nsource NOT IN(19, 29, 39, 49, 59)
            AND DECODE(
                ntype,
                1, h.er,
                2, h.ed,
                3, h.q1,
                4, h.q3,
                5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
               ) IS NOT NULL
   GROUP BY p.ngroup, TO_CHAR(h.date_time - 1 / 1440, 'hh24');

  -- Отдельно сохраняется 25 час, помеченный кодом источника 19
  IF hc = 25 THEN
   INSERT INTO m30817
               (ngroup, HOUR, kwh, err, vqm)
    SELECT   p.ngroup, 25,
             SUM(p.nkc
              * DECODE(
                 ntype,
                 1, h.er,
                 2, h.ed,
                 3, h.q1,
                 4, h.q3,
                 5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                 6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                )),
             COUNT(*),
             DECODE(
              SIGN(util_pg.get_countpoint_f(p.ngroup, 2) - COUNT(DISTINCT h.mid)),
              1, qm_pg.sumqm(NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.nodataqm),
              NVL(sumqm(NVL(h.vqm, qm_pg.defqm)), qm_pg.defqm)
             ) vqm
    FROM     maketgroups g, maketpoints p, halfhour h
    WHERE    g.nmaket = an_maket AND g.ngroup NOT IN(SELECT ngroup
                                                     FROM   makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC(ad_date)
             AND h.date_time <= TRUNC(ad_date) + 1 AND h.nsource IN(19, 29, 39, 49, 59)
             AND DECODE(
                 ntype,
                 1, h.er,
                 2, h.ed,
                 3, h.q1,
                 4, h.q3,
                 5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                 6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                ) IS NOT NULL
    GROUP BY p.ngroup;
  END IF;

  -- считаем полноту данных
  FOR lc IN (SELECT ngroup, err
             FROM   m30817
             WHERE  HOUR <> 0) LOOP
   SELECT COUNT(*)
   INTO   ln_pcnt
   FROM   maketpoints
   WHERE  ngroup = lc.ngroup;

   IF lc.err < ln_pcnt * 2 THEN                                                                                                         -- 2 получасовки в часе
    lb_full := FALSE;
    EXIT;
   END IF;
  END LOOP;

  -- а теперь убираем мусор из ошибок округления
  UPDATE m30817
  SET err = NULL
  WHERE  HOUR <> 0;

  -- Выставляем полноту данных
  IF lb_full = FALSE THEN
   file_pg.set_notfull;
  END IF;

  -- По строкам, где не оказалось данных проставляются нули
  FOR i IN 1 .. hc LOOP
   INSERT INTO m30817
               (ngroup, HOUR, kwh, err, vqm)
    (SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), 0, qm_pg.nodataqm vqm
     FROM   m30817
     WHERE  HOUR = 0
     MINUS
     SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), 0, qm_pg.nodataqm vqm
     FROM   m30817
     WHERE  HOUR = i);
  END LOOP;

  -- Округление с учетом ошибки предыдущего шага, запись ошибки текущего шага
  ln_needround30817 := util_pg.needround30817_f;

  FOR i IN 1 .. hc LOOP
   IF NOT(ln_hc = 23 AND i = util_pg.switch_f + 1) THEN
    IF ln_hc = 23 AND i = util_pg.switch_f + 2 THEN
     ln_temp := 2;
    ELSE
     ln_temp := 1;
    END IF;

    UPDATE m30817 m
    SET (kwh, err) =
         (SELECT util_pg.round_trunc(a.kwh / 1000 * ln_div, ln_needtrunc, b.err + NVL(c.err, 0)),
                 NVL(a.kwh, 0) / 1000 * ln_div + b.err + NVL(c.err, 0) - util_pg.round_trunc(a.kwh / 1000 * ln_div, ln_needtrunc, b.err + NVL(c.err, 0))
          FROM   m30817 a,
                 m30817 b,
                 (SELECT me.ngroup, DECODE(ln_needround30817, 1, DECODE(TO_CHAR(ad_date, 'DD'), 1, 0, me.err), 0) err
                  --Прощаем остатки в конце месяца
                  FROM   maketerr me
                  WHERE  i = 1 AND me.ddate = TRUNC(ad_date) - 1) c
          WHERE  a.ngroup = b.ngroup AND a.HOUR = b.HOUR + ln_temp AND a.ngroup = m.ngroup AND a.HOUR = i AND a.ngroup = c.ngroup(+))
    WHERE  HOUR = i;
   END IF;
  END LOOP;

  --Запоминаем остатки округления на след день
  IF ln_needround30817 = 1 THEN
   DELETE FROM maketerr
   WHERE       ddate = TRUNC(ad_date) AND ngroup IN(SELECT ngroup
                                                    FROM   m30817);

   INSERT INTO maketerr
               (ngroup, ddate, err)
    SELECT ngroup, TRUNC(ad_date), err
    FROM   m30817
    WHERE  HOUR = hc;
  END IF;

  -- В рабочей таблице проставляются ид агрегированных строк и все часы суток
  FOR i IN 0 .. hc LOOP
   INSERT INTO m30817
               (ngroup, HOUR, kwh, vqm)
    SELECT ngroup, i, DECODE(ln_null, 0, 0, NULL), qm_pg.okqm
    FROM   maketgroups
    WHERE  nmaket = an_maket AND ngroup IN(SELECT ngroup
                                           FROM   makettemp);
  END LOOP;

  LOOP
   -- Выбираем из рабочей таблицы очередную составляющую агрегированной строки или выходим, если таблица пуста
   BEGIN
    SELECT ngroup, nsubgroup, nsign
    INTO   ln_groupcode, ln_subgroupcode, ln_sign
    FROM   makettemp
    WHERE  nsubgroup NOT IN(SELECT ngroup
                            FROM   makettemp) AND ROWNUM = 1;
   EXCEPTION
    WHEN NO_DATA_FOUND THEN
     EXIT;
   END;

   -- Расчет и аккумулирование составляющей в агрегированной строке
   FOR i IN 1 .. hc LOOP
    BEGIN
     SELECT ln_sign * kwh, vqm
     INTO   ln_temp, lv_qm
     FROM   m30817
     WHERE  ngroup = ln_subgroupcode AND HOUR = i;
    EXCEPTION
     WHEN NO_DATA_FOUND THEN
      IF ln_null = 0 THEN
       ln_temp := 0;
      ELSE
       ln_temp := NULL;
      END IF;

      lv_qm := qm_pg.okqm;
    END;

    UPDATE m30817
    SET kwh = util_pg.sumn(kwh, ln_temp),
        vqm = qm_pg.sumqm(NVL(vqm, qm_pg.okqm), NVL(lv_qm, qm_pg.okqm))
    WHERE  ngroup = ln_groupcode AND HOUR = i;
   END LOOP;

   -- удаляем из временной таблицы обработанную составляющую
   DELETE FROM makettemp
   WHERE       ngroup = ln_groupcode AND nsubgroup = ln_subgroupcode;
  END LOOP;

  -- По всем строкам считается расход за сутки
  UPDATE m30817 m
  SET (m.kwh, m.vqm) = (SELECT SUM(kwh), sumqm(vqm)
                        FROM   m30817
                        WHERE  ngroup = m.ngroup)
  WHERE  m.HOUR = 0;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE end_m30817(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
 BEGIN
  DELETE FROM maket30817
  WHERE       ddate = TRUNC(ad_date) AND ngroup IN(SELECT ngroup
                                                   FROM   maketgroups
                                                   WHERE  nmaket = an_maket);

  -- Выгрузка временной таблицы в постоянную
  INSERT INTO maket30817
              (ddate, ngroup, HOUR, kwh, err)
   SELECT ad_date, ngroup, HOUR, kwh, err
   FROM   m30817;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE m30817base_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2, an_withqm NUMBER) IS
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  hc                  NUMBER;                                                                                                          -- кол-во часов в сутках
  lv_str              VARCHAR2(2000);
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  lv_type25           VARCHAR2(2000);
  lv_sumqm            VARCHAR2(128);                                                                                 -- суммарная метка качества по всем точкам
  lv_addcode          VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);
  hc := 24 - util_pg.is_dayswitch(ad_date);

  IF hc = 23 THEN
   hc := 24;
  END IF;

  --Заполняем расчетную таблицу
  begin_m30817(an_maket, ad_date, av_fname);

  -- Формирование теста макета
  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  IF TRIM(util_pg.get_param(lv_bstr, 10)) IS NOT NULL THEN
   lv_addcode := TRIM(util_pg.get_param(lv_bstr, 10)) || lv_tab;
  END IF;

  lv_type25 := TRIM(util_pg.get_param(lv_bstr, 7));
  file_pg.out_p('((//'
   || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '30817')
   || lv_tab
   || TO_CHAR(ad_date, NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 'MMDD'))
   || lv_tab
   || lv_ent
   || lv_tab
   || lv_addcode
   || '++');

  FOR lc IN (SELECT   ngroup, util_pg.get_param(vcode, 1, ':') vcode, util_pg.get_param(vcode, 2, ':') vadd
             FROM     maketgroups
             WHERE    nmaket = an_maket
             ORDER BY vname) LOOP
   lv_str := '(' || lc.vcode || '):';
   lv_sumqm := qm_pg.okqm;

   FOR i IN 0 .. hc LOOP
    IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ad_date) = -1 THEN
     --переход на зиму и 25 в середину (меняем местами)
     IF i <> hc THEN
      SELECT lv_str || SUM(kwh) || ':', sumqm(vqm) vqm
      INTO   lv_str, lv_sumqm
      FROM   m30817
      WHERE  ngroup = lc.ngroup AND HOUR = i;
     END IF;

     IF i = util_pg.switch_f + 1 THEN
      SELECT lv_str || SUM(kwh) || ':', sumqm(vqm) vqm
      INTO   lv_str, lv_sumqm
      FROM   m30817
      WHERE  ngroup = lc.ngroup AND HOUR = hc;
     END IF;
    ELSIF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ad_date) = 1 AND i = util_pg.switch_f + 1 THEN
     --переход на лето и дополнять нулями
     lv_str := lv_str || '0:';
    ELSIF NOT(util_pg.is_dayswitch(ad_date) = 1 AND i = util_pg.switch_f + 1) THEN                                                      --кроме перехода на лето
     SELECT lv_str || SUM(kwh) || ':', sumqm(vqm) vqm
     INTO   lv_str, lv_sumqm
     FROM   m30817
     WHERE  ngroup = lc.ngroup AND HOUR = i;
    END IF;
   END LOOP;

   IF an_withqm = 1 THEN
    lv_str := lv_str || ':' || convert_23to8bit_qm(lv_sumqm, util_pg.get_param(NVL(file_pg.gv_param, lv_bstr), 8));
   -- || ':'|| lv_sumqm;
   END IF;

   IF lc.vadd IS NOT NULL THEN
    lv_str := lv_str || lc.vadd || ':';
   END IF;

   file_pg.out_p(lv_str);
  END LOOP;

  file_pg.out_p('==))');
  --Очищаем расчетную таблицу
  end_m30817(an_maket, ad_date, av_fname);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.arround_m30817: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE arround_m30817(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
 BEGIN
  m30817base_p(an_maket, ad_date, av_fname);
 END;

------------------------------------------------------------------------------------------------------------------------
 -- added by KAG 06.07.2009
 PROCEDURE m30817qm_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
 BEGIN
  m30817base_p(an_maket, ad_date, av_fname, 1);
 END;                                                                                                                                    -- Procedure m30817qm_p

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE des_m30817(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  hc                  NUMBER;                                                                                                          -- кол-во часов в сутках
  lv_str              VARCHAR2(2000);
  lv_str1             VARCHAR2(2000);
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  lv_precision        VARCHAR2(32);
  ln_sum              NUMBER;
  lv_qm               VARCHAR2(32);
  cn_maxlength CONSTANT NUMBER := 72 - 2;
  lv_type25           VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  -- Определяем формат вывода (в тыс. кВт*ч или кВт*ч)
  IF util_pg.get_param(lv_bstr, 1) = '1' THEN
   lv_precision := 'KWT.H';
  ELSE
   lv_precision := 'MWT.H';
  END IF;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);
  hc := 24 - util_pg.is_dayswitch(ad_date);

  IF hc = 23 THEN
   hc := 24;
  END IF;

  --Заполняем расчетную таблицу
  begin_m30817(an_maket, ad_date, av_fname);

  -- Формирование теста макета
  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  lv_type25 := TRIM(util_pg.get_param(lv_bstr, 7));
  file_pg.out_p(TO_CHAR(SYSDATE, 'DD.MM.YY HH24:MI:SS'));
  file_pg.out_p('< DATE=' || TO_CHAR(ad_date, 'DDMMYY') || '; FORMAT=' || lv_precision || ' >');

  FOR lc IN (SELECT   ngroup, vcode
             FROM     maketgroups
             WHERE    nmaket = an_maket
             ORDER BY vname) LOOP
   SELECT util_pg.sumn(SUM(er), -SUM(ed)),
          DECODE(
           SIGN(MAX(DECODE(nsource, util_pg.cn_manualinput, 1, util_pg.cn_manualinputw, 1, 0))
            + MAX(DECODE(SIGN(nsource - 30), -1, 0, DECODE(TRUNC((nsource - 30) / 20), 0, 1, 0)))),
           1, 'r',
           ' '
          )
   INTO   ln_sum, lv_qm
   FROM   halfhour
   WHERE  mid IN(SELECT mid
                 FROM   maketpoints
                 WHERE  ngroup IN(SELECT     nsubgroup ngroup
                                  FROM       maketformulas
                                  CONNECT BY PRIOR nsubgroup = ngroup
                                  START WITH ngroup = lc.ngroup
                                  UNION ALL
                                  SELECT lc.ngroup
                                  FROM   DUAL)) AND date_time > TRUNC(ad_date) AND date_time <= TRUNC(ad_date) + 1;

   IF ln_sum IS NULL THEN
    file_pg.out_p('< ID=' || lc.vcode || '; ST=-; >');
   ELSE
    lv_str := '< ID=' || lc.vcode || '; E=';

    FOR i IN 0 .. hc LOOP
     IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ad_date) = -1 THEN
      --переход на зиму и 25 в середину (меняем местами)
      IF i <> hc THEN
       SELECT SUM(kwh) || DECODE(i, 0, ':', hc, ';', ',')
       INTO   lv_str1
       FROM   m30817
       WHERE  ngroup = lc.ngroup AND HOUR = i;
      END IF;

      IF i = util_pg.switch_f + 1 THEN                                                                                                          -- 25й всередину
       SELECT SUM(kwh) || DECODE(i, 0, ':', hc, ';', ',')
       INTO   lv_str1
       FROM   m30817
       WHERE  ngroup = lc.ngroup AND HOUR = hc;
      END IF;
     ELSIF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ad_date) = 1 AND i = util_pg.switch_f + 1 THEN
      --переход на лето и дополнять нулями
      lv_str1 := '0,';
     ELSIF NOT(util_pg.is_dayswitch(ad_date) = 1 AND i = util_pg.switch_f + 1) THEN
      -- всегда кроме 4го часа при переходе на лето
      SELECT SUM(kwh) || DECODE(i, 0, ':', hc, ';', ',')
      INTO   lv_str1
      FROM   m30817
      WHERE  ngroup = lc.ngroup AND HOUR = i;
     ELSE
      lv_str1 := '';
     END IF;

     -- сливаем буфер, если он не влазит в cn_maxlength
     IF (i >= hc - 1 AND LENGTH(lv_str || lv_str1 || ' ST=' || lv_qm || '; >') > cn_maxlength) OR(LENGTH(lv_str || lv_str1) > cn_maxlength) THEN
      file_pg.out_p(lv_str);
      lv_str := lv_str1;
     ELSE
      lv_str := lv_str || lv_str1;
     END IF;
    END LOOP;

    file_pg.out_p(lv_str || ' ST=' || lv_qm || '; >');
   END IF;
  END LOOP;

  --Очищаем расчетную таблицу
  end_m30817(an_maket, ad_date, av_fname);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.des_m30817: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Макет 30917 (почасово)
 PROCEDURE m30917h_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
 BEGIN
  m30917_p(an_maket, ad_date, av_fname);
 END;

------------------------------------------------------------------------------------------------------------------------
   --Макет 30917
 PROCEDURE m30917_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cn_step             NUMBER;
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  cn_row     CONSTANT NUMBER := 4;

  CURSOR lcur_g IS
   SELECT   ngroup, NVL(vcode, get_vcode(ngroup)) vcode
   FROM     maketgroups
   WHERE    nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mid, nkc, ntype
   FROM   maketpoints
   WHERE  ngroup = lc_group;

  CURSOR lcur_s(lc_group NUMBER) IS
   SELECT     nsubgroup, nsign
   FROM       maketformulas
   CONNECT BY PRIOR nsubgroup = ngroup
   START WITH ngroup = lc_group;

  CURSOR lcur_r(lc_mid NUMBER, lc_nkc NUMBER, lc_end NUMBER) IS
   SELECT   util_pg.get_num_dt(date_time - 1 / 86400, nsource, cn_step, lc_end) dt, ROUND(DECODE(SIGN(lc_nkc), -1, SUM(b.ed), SUM(b.er)), cn_rn) er,
            ROUND(DECODE(SIGN(lc_nkc), -1, SUM(b.er), SUM(b.ed)), cn_rn) ed,
            ROUND(DECODE(SIGN(lc_nkc), -1, util_pg.sumn(SUM(b.q3), SUM(b.q4)), util_pg.sumn(SUM(b.q1), SUM(b.q2))), cn_rn) q1,
            ROUND(DECODE(SIGN(lc_nkc), -1, util_pg.sumn(SUM(b.q1), SUM(b.q2)), util_pg.sumn(SUM(b.q3), SUM(b.q4))), cn_rn) q3
   FROM     halfhour b
   WHERE    b.mid = lc_mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1
   GROUP BY util_pg.get_num_dt(date_time - 1 / 86400, nsource, cn_step, lc_end);

  lt_ras              common_pg.tt_number;
  lt_str              common_pg.tt_varchar2;
  ln_col              NUMBER;
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  ln_ost              NUMBER := 0;
  ln_end              NUMBER := 1;
  lv_type25           VARCHAR2(2000);
  lb_full             BOOLEAN := TRUE;                                                                                                -- признак полноты данных
  lv_addcode          VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);

  IF TRIM(util_pg.get_param(lv_bstr, 6)) = '60' THEN
   cn_step := 1 / 24;
  ELSE
   cn_step := 1 / 48;
  END IF;

  lv_type25 := TRIM(util_pg.get_param(lv_bstr, 7));

  IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ad_date) = -1 THEN                                                                --25 час в средину
   ln_end := 0;
  END IF;

  IF TRIM(util_pg.get_param(lv_bstr, 10)) IS NOT NULL THEN
   lv_addcode := TRIM(util_pg.get_param(lv_bstr, 10)) || lv_tab;
  END IF;

  ln_col := util_pg.get_count_dt(ad_date, cn_step) + 1;
  file_pg.out_p('((//'
   || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '30917')
   || lv_tab
   || TO_CHAR(ad_date, NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 'MMDD'))
   || lv_tab
   || lv_ent
   || lv_tab
   || lv_addcode
   || '++');

  FOR lc_g IN lcur_g LOOP                                                                                                                 --Идем по всем группам
   FOR i IN 1 .. ln_col LOOP                                                                                                        --Занулили временный массив
    FOR j IN 1 .. cn_row LOOP
     lt_ras(ln_col *(j - 1) + i) := NULL;
     lt_str(j) := '';
    END LOOP;
   END LOOP;

   FOR lc_p IN lcur_p(lc_g.ngroup) LOOP                                                                                     -- Просуммировали все точки в группе
    FOR lc_r IN lcur_r(lc_p.mid, lc_p.nkc, ln_end) LOOP
     lt_ras(0 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(0 * ln_col + lc_r.dt), lc_r.er);
     lt_ras(1 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(1 * ln_col + lc_r.dt), lc_r.ed);
     lt_ras(2 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(2 * ln_col + lc_r.dt), lc_r.q1);
     lt_ras(3 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(3 * ln_col + lc_r.dt), lc_r.q3);
    END LOOP;
   END LOOP;

   FOR lc_s IN lcur_s(lc_g.ngroup) LOOP                                                                                  --Просуммировали все дочерние подгруппы
    FOR lc_p IN lcur_p(lc_s.nsubgroup) LOOP
     FOR lc_r IN lcur_r(lc_p.mid, lc_p.nkc * lc_s.nsign, ln_end) LOOP
      lt_ras(0 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(0 * ln_col + lc_r.dt), lc_r.er);
      lt_ras(1 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(1 * ln_col + lc_r.dt), lc_r.ed);
      lt_ras(2 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(2 * ln_col + lc_r.dt), lc_r.q1);
      lt_ras(3 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(3 * ln_col + lc_r.dt), lc_r.q3);
     END LOOP;
    END LOOP;
   END LOOP;

   IF util_pg.get_param(lv_bstr, 1) = '1' THEN                                                     --Округляем до целых, остатки переносим на следующее значение
    FOR j IN 1 .. cn_row LOOP
     ln_ost := 0;

     FOR i IN 1 .. ln_col - 1 LOOP
      lt_ras((j - 1) * ln_col + i) := lt_ras((j - 1) * ln_col + i) + ln_ost;
      -- в остатке нельзя допускать NULL edited by KAG
      ln_ost := NVL(lt_ras((j - 1) * ln_col + i) - TRUNC(lt_ras((j - 1) * ln_col + i)), 0);
      lt_ras((j - 1) * ln_col + i) := TRUNC(lt_ras((j - 1) * ln_col + i));
     END LOOP;
    END LOOP;
   END IF;

   FOR i IN 1 .. ln_col - 1 LOOP                                                                                             --Вычислили cn_row суточных расхода
    FOR j IN 1 .. cn_row LOOP
     lt_ras((j - 1) * ln_col + ln_col) := util_pg.sumn(lt_ras((j - 1) * ln_col + ln_col), lt_ras((j - 1) * ln_col + i));
     lt_str(j) := lt_str(j) || frm_number(lt_ras((j - 1) * ln_col + i)) || lv_tab;

     IF SUBSTR(lv_type25, 1, 1) = '1' AND ROUND((ln_col - 1) *(24 * cn_step), 5) = 23 AND ROUND(i *(24 * cn_step), 5) = util_pg.switch_f THEN
      --при переходе на лето 4 час =0
      FOR z IN 1 .. ROUND(1 /(24 * cn_step), 5) LOOP
       lt_str(j) := lt_str(j) || '0' || lv_tab;
      END LOOP;
     END IF;
    END LOOP;
   END LOOP;

   FOR j IN 1 .. cn_row LOOP                                                                                                              --Собрали cn_row сторк
    lt_str(j) := '(' || lc_g.vcode || j || ')' || lv_tab || REPLACE(lt_ras((j - 1) * ln_col + ln_col) || lv_tab || lt_str(j), '.', ',');

    IF lt_ras((j - 1) * ln_col + ln_col) IS NOT NULL THEN                                                                        --Если что-то есть, то выводим
     file_pg.out_p(lt_str(j));

----------------
     IF lb_full AND INSTR(lt_str(j), '::') <> 0 THEN                                                                                 -- added by KAG 30.03.2009
      lb_full := FALSE;
     END IF;
    END IF;
   END LOOP;

   lt_ras.DELETE;
   lt_str.DELETE;
  END LOOP;

  file_pg.out_p('==))');

  -- Выставляем полноту данных
  IF lb_full = FALSE THEN
   file_pg.set_notfull;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m30917_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 30818
 PROCEDURE m30818_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_p IS
   SELECT   mg.ngroup, NVL(mg.vcode, get_vcode(mg.ngroup)) vcode, mg.vname, MAX(mp.mid) mid, MAX(mp.nkc) nkc, MAX(mp.ntype) ntype, COUNT(*) cn
   FROM     maketgroups mg, maketpoints mp
   WHERE    mg.nmaket = an_maket AND mg.ngroup = mp.ngroup
   GROUP BY mg.ngroup, NVL(mg.vcode, get_vcode(mg.ngroup)), mg.vname
   ORDER BY mg.vname;

  CURSOR lcur_r(lc_mid NUMBER) IS
   SELECT date_time, erm, aerm, berm, cerm, derm, edm, aedm, bedm, cedm, dedm, q1m, aq1m, bq1m, cq1m, dq1m, q2m, aq2m, bq2m, cq2m, dq2m, q3m, aq3m, bq3m, cq3m,
          dq3m, q4m, aq4m, bq4m, cq4m, dq4m
   FROM   monthsorg
   WHERE  mid = lc_mid AND date_time = TRUNC(ad_date) + 1 AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL)
   UNION ALL
   SELECT date_time, erm, aerm, berm, cerm, derm, edm, aedm, bedm, cedm, dedm, q1m, aq1m, bq1m, cq1m, dq1m, q2m, aq2m, bq2m, cq2m, dq2m, q3m, aq3m, bq3m, cq3m,
          dq3m, q4m, aq4m, bq4m, cq4m, dq4m
   FROM   billorg
   WHERE  mid = lc_mid
          AND date_time =
              (SELECT MIN(date_time)
               FROM   billorg
               WHERE  mid = lc_mid AND date_time >= TRUNC(ad_date) + 1 AND date_time < TRUNC(ad_date) + 2
                      AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL))
          AND date_time >= TRUNC(ad_date) + 1 AND date_time < TRUNC(ad_date) + 2 AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL);

  CURSOR lcur_r1(lc_mid NUMBER) IS
   SELECT erm, edm, q1m, q2m, q3m, q4m
   FROM   halfhour
   WHERE  mid = lc_mid AND date_time = TRUNC(ad_date) + 1 AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL);

  lt_ras              common_pg.tt_number;
  lt_str              common_pg.tt_varchar2;
  lv_str              VARCHAR2(4000);
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  cn_col     CONSTANT NUMBER := 5;
  cn_row     CONSTANT NUMBER := 6;
  ld_date             DATE;
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  lb_full             BOOLEAN := TRUE;                                                                                                -- признак полноты данных
  ln_euro             NUMBER;                                                                            -- признак счетчика отпараметрированого по Европе (=1)
  ln_without_zone     NUMBER := 0;
  lv_addcode          VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);

  IF TRIM(util_pg.get_param(lv_bstr, 6)) = '1' THEN
   ln_without_zone := 1;
  END IF;

  IF TRIM(util_pg.get_param(lv_bstr, 10)) IS NOT NULL THEN
   lv_addcode := TRIM(util_pg.get_param(lv_bstr, 10)) || lv_tab;
  END IF;

  file_pg.out_p('((//'
   || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '30818')
   || lv_tab
   || TO_CHAR(ad_date, NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 'MMDD'))
   || lv_tab
   || lv_ent
   || lv_tab
   || lv_addcode
   || '++');

  FOR lc_p IN lcur_p LOOP                                                                                                                 --Идем по всем группам
   IF lc_p.cn <> 1 THEN                                                                                         --Если больше обной точке в группе, то ругаемся
    raise_application_error(-20001,
     'Для макета 30818 каждая группа должна содержать не более одной точки. Данное условие нарушено для группы: ''' || lc_p.vname || '''');
   END IF;

   FOR i IN 1 .. cn_col LOOP                                                                                                         --Занулили временный массив
    FOR j IN 1 .. cn_row LOOP
     lt_ras(cn_col *(j - 1) + i) := NULL;
     lt_str(j) := '';
    END LOOP;
   END LOOP;

   ld_date := NULL;

   FOR lc_r IN lcur_r(lc_p.mid) LOOP                                                                                                --Заполняем временный массив
    ld_date := lc_r.date_time;
    lt_ras(1) := lc_r.erm;
    lt_ras(2) := lc_r.aerm;
    lt_ras(3) := lc_r.berm;
    lt_ras(4) := lc_r.cerm;
    lt_ras(5) := lc_r.derm;
    lt_ras(6) := lc_r.edm;
    lt_ras(7) := lc_r.aedm;
    lt_ras(8) := lc_r.bedm;
    lt_ras(9) := lc_r.cedm;
    lt_ras(10) := lc_r.dedm;
    lt_ras(11) := lc_r.q1m;
    lt_ras(12) := lc_r.aq1m;
    lt_ras(13) := lc_r.bq1m;
    lt_ras(14) := lc_r.cq1m;
    lt_ras(15) := lc_r.dq1m;
    lt_ras(16) := lc_r.q2m;
    lt_ras(17) := lc_r.aq2m;
    lt_ras(18) := lc_r.bq2m;
    lt_ras(19) := lc_r.cq2m;
    lt_ras(20) := lc_r.dq2m;
    lt_ras(21) := lc_r.q3m;
    lt_ras(22) := lc_r.aq3m;
    lt_ras(23) := lc_r.bq3m;
    lt_ras(24) := lc_r.cq3m;
    lt_ras(25) := lc_r.dq3m;
    lt_ras(26) := lc_r.q4m;
    lt_ras(27) := lc_r.aq4m;
    lt_ras(28) := lc_r.bq4m;
    lt_ras(29) := lc_r.cq4m;
    lt_ras(30) := lc_r.dq4m;
    EXIT;
   END LOOP;

   -- проверяем счетчик
   SELECT COUNT(*)
   INTO   ln_euro
   FROM   DUAL
   WHERE  EXISTS(SELECT *
                 FROM   feeders
                 WHERE  mid = lc_p.mid AND ntimezonew = 1 AND ntimezones = 1);

   IF ld_date <> TRUNC(ld_date) THEN                                                                                                                     --По ГН
    IF ln_euro = 0 THEN
     FOR lc_r IN lcur_r1(lc_p.mid) LOOP                                                                                            --Заполняем временный массив
      lt_ras(1) := NVL(lc_r.erm, lt_ras(1));
      lt_ras(6) := NVL(lc_r.edm, lt_ras(6));
      lt_ras(11) := NVL(lc_r.q1m, lt_ras(11));
      lt_ras(16) := NVL(lc_r.q2m, lt_ras(16));
      lt_ras(21) := NVL(lc_r.q3m, lt_ras(21));
      lt_ras(26) := NVL(lc_r.q4m, lt_ras(26));
      EXIT;
     END LOOP;
    ELSE
     -- добавлен расчет показаний на 00:00 по ГН, если суточное показание не на 00:00 (только для европейских счетчиков)
     ld_date := TRUNC(ld_date);
     lt_ras(1) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 1, 0);
     lt_ras(2) := NULL;
     lt_ras(3) := NULL;
     lt_ras(4) := NULL;
     lt_ras(5) := NULL;
     lt_ras(6) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 2, 0);
     lt_ras(7) := NULL;
     lt_ras(8) := NULL;
     lt_ras(9) := NULL;
     lt_ras(10) := NULL;
     lt_ras(11) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 3, 0);
     lt_ras(12) := NULL;
     lt_ras(13) := NULL;
     lt_ras(14) := NULL;
     lt_ras(15) := NULL;
     lt_ras(16) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 4, 0);
     lt_ras(17) := NULL;
     lt_ras(18) := NULL;
     lt_ras(19) := NULL;
     lt_ras(20) := NULL;
     lt_ras(21) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 5, 0);
     lt_ras(22) := NULL;
     lt_ras(23) := NULL;
     lt_ras(24) := NULL;
     lt_ras(25) := NULL;
     lt_ras(26) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 6, 0);
     lt_ras(27) := NULL;
     lt_ras(28) := NULL;
     lt_ras(29) := NULL;
     lt_ras(30) := NULL;
    END IF;
   END IF;

   -- добавлен дорасчет для счетчиков по Европе, если на начало следующих за ad_date суток еще нет никаких суточных расходов
   IF ln_euro = 1 AND ld_date IS NULL THEN
    ld_date := TRUNC(ad_date) + 1;
    lt_ras(1) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 1, 0);
    lt_ras(6) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 2, 0);
    lt_ras(11) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 3, 0);
    lt_ras(16) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 4, 0);
    lt_ras(21) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 5, 0);
    lt_ras(26) := util_pg.get_meterage_vch2(lc_p.mid, ld_date, 6, 0);
   END IF;

   IF SIGN(lc_p.nkc) = -1 THEN                                                                                                                     --Инвертируем
    FOR i IN 1 .. cn_col LOOP
     util_pg.chdr(lt_ras(i), lt_ras(1 * cn_col + i), lt_ras(2 * cn_col + i), lt_ras(4 * cn_col + i), lt_ras(3 * cn_col + i), lt_ras(5 * cn_col + i));
    END LOOP;
   END IF;

   FOR j IN 1 .. cn_row LOOP                                                                                                              --Выводим cn_row строк
    IF lt_ras((j - 1) * cn_col + 1) IS NOT NULL THEN                                                                 --Если есть показание общенн, то и выводим
     FOR i IN 1 .. cn_col LOOP
      IF i > 1 AND ln_without_zone = 1 THEN                                                                            --Для макета без тарифных зон - не пишем
       NULL;
      ELSE
       lt_str(j) := lt_str(j) || frm_number(ROUND(lt_ras((j - 1) * cn_col + i), cn_rnm)) || lv_tab;
      END IF;

      IF lb_full AND lt_ras((j - 1) * cn_col + i) IS NULL THEN
       lb_full := FALSE;
      END IF;
     END LOOP;

     lt_str(j) := '(' || lc_p.vcode || j || ')' || lv_tab || REPLACE(lt_str(j), '.', ',');
     file_pg.out_p(lt_str(j));
    ELSE
     lb_full := FALSE;
    END IF;
   END LOOP;

   lt_ras.DELETE;
   lt_str.DELETE;
  END LOOP;

  file_pg.out_p('==))');

  -- Выставляем полноту данных
  IF lb_full = FALSE THEN
   file_pg.set_notfull;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m30818_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 30816
 PROCEDURE m30816_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_p IS
   SELECT   mg.ngroup, NVL(mg.vcode, get_vcode(mg.ngroup)) vcode, mg.vname, MAX(mp.mid) mid, MAX(mp.nkc) nkc, MAX(mp.ntype) ntype, COUNT(*) cn
   FROM     maketgroups mg, maketpoints mp
   WHERE    mg.nmaket = an_maket AND mg.ngroup = mp.ngroup
   GROUP BY mg.ngroup, NVL(mg.vcode, get_vcode(mg.ngroup)), mg.vname
   ORDER BY mg.vname;

  CURSOR lcur_r(lc_mid NUMBER) IS
   SELECT date_time, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, freq, cosf, volt volt1, volt2, volt3, currento curr1, curr2, curr3, nfiu1, nfiu2,
          nfiu3, nfii1, nfii2, nfii3, ni0
   FROM   curr_power
   WHERE  mid = lc_mid /* AND date_time = ad_date*/;

  lv_str              VARCHAR2(8000);
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  lv_addcode          VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);

  IF TRIM(util_pg.get_param(lv_bstr, 10)) IS NOT NULL THEN
   lv_addcode := TRIM(util_pg.get_param(lv_bstr, 10)) || lv_tab;
  END IF;

  file_pg.out_p('((//'
   || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '30816')
   || lv_tab
   || TO_CHAR(ad_date, NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 'MMDD'))
   || lv_tab
   || lv_ent
   || lv_tab
   || lv_addcode
   || '++');

  FOR lc_p IN lcur_p LOOP                                                                                                                 --Идем по всем группам
   IF lc_p.cn <> 1 THEN                                                                                         --Если больше обной точки в группе, то ругаемся
    raise_application_error(-20001,
     'Для макета 30816 каждая группа должна содержать не более одной точки. Данное условие нарушено для группы: ''' || lc_p.vname || '''');
   END IF;

   FOR lc_r IN lcur_r(lc_p.mid) LOOP
    lv_str :=
        '('
     || lc_p.vcode
     || ')'
     || lv_tab
     || TO_CHAR(lc_r.date_time, 'DD.MM.YYYY.HH24.MI.SS')
     || lv_tab
     || lc_r.er
     || lv_tab
     || lc_r.ed
     || lv_tab
     || lc_r.q1
     || lv_tab
     || lc_r.q3
     || lv_tab
     || lc_r.q2
     || lv_tab
     || lc_r.q4
     || lv_tab
     || lc_r.erm
     || lv_tab
     || lc_r.edm
     || lv_tab
     || lc_r.q1m
     || lv_tab
     || lc_r.q3m
     || lv_tab
     || lc_r.q2m
     || lv_tab
     || lc_r.q4m
     || lv_tab
     || lc_r.freq
     || lv_tab
     || lc_r.cosf
     || lv_tab
     || lc_r.volt1
     || lv_tab
     || lc_r.volt2
     || lv_tab
     || lc_r.volt3
     || lv_tab
     || lc_r.curr1
     || lv_tab
     || lc_r.curr2
     || lv_tab
     || lc_r.curr3
     || lv_tab
     || lc_r.nfiu1
     || lv_tab
     || lc_r.nfiu2
     || lv_tab
     || lc_r.nfiu3
     || lv_tab
     || lc_r.nfii1
     || lv_tab
     || lc_r.nfii2
     || lv_tab
     || lc_r.nfii3
     || lv_tab
     || lc_r.ni0;
    file_pg.out_p(lv_str);
   END LOOP;
  END LOOP;

  file_pg.out_p('==))');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m30816_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

