 --Макет Казахстан
 PROCEDURE mkazah_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  ln_step             NUMBER DEFAULT 15 / 1440;
  lc_tab     CONSTANT VARCHAR2(1) := '#';
  lc_season  CONSTANT VARCHAR2(1) := '0';                                                              -- указатель времени зима - лето, должен быть всегда = 0
  ld_date             DATE DEFAULT util_pg.trunc_d(ad_date, ln_step);
  lt_ras              common_pg.tt_number;

  CURSOR lcur_g IS
   SELECT   ngroup, NVL(vcode, get_vcode(ngroup)) vcode
   FROM     maketgroups
   WHERE    nmaket = an_maket
   ORDER BY NVL(vcode, get_vcode(ngroup)), vname;

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mid, nkc
   FROM   maketpoints
   WHERE  ngroup = lc_group;

  CURSOR lcur_r(lc_mid NUMBER) IS
   SELECT ROUND(SUM(b.er)) er, ROUND(SUM(b.ed)) ed, ROUND(SUM(b.q1)) q1, ROUND(SUM(b.q2)) q2, ROUND(SUM(b.q3)) q3, ROUND(SUM(b.q4)) q4
   FROM   halfhour b
   WHERE  b.mid = lc_mid AND b.date_time > ld_date AND b.date_time <= ld_date + ln_step;
 BEGIN
  FOR lc_g IN lcur_g LOOP
   FOR j IN 1 .. 6 LOOP
    lt_ras(j) := NULL;
   END LOOP;

   FOR lc_p IN lcur_p(lc_g.ngroup) LOOP
    FOR lc_r IN lcur_r(lc_p.mid) LOOP
     lt_ras(1) := util_pg.sumn(lt_ras(1), lc_p.nkc * lc_r.er);                                                                                             --er
     lt_ras(2) := util_pg.sumn(lt_ras(2), lc_p.nkc * lc_r.ed);                                                                                             --ed
     lt_ras(3) := util_pg.sumn(lt_ras(3), lc_p.nkc * lc_r.q1);                                                                                             --q1
     lt_ras(4) := util_pg.sumn(lt_ras(4), lc_p.nkc * lc_r.q2);                                                                                             --q2
     lt_ras(5) := util_pg.sumn(lt_ras(5), lc_p.nkc * lc_r.q3);                                                                                             --q3
     lt_ras(6) := util_pg.sumn(lt_ras(6), lc_p.nkc * lc_r.q4);                                                                                             --q4
    END LOOP;
   END LOOP;

   file_pg.out_p(lc_g.vcode
    || lc_tab
    || TO_CHAR(ld_date + ln_step, 'DD/MM/YYYY HH24:MI')
    || lc_tab
    || lc_season
    || lc_tab
    || util_pg.get_num_dt(ld_date, 10, ln_step)
    || lc_tab
    || lt_ras(1)
    || lc_tab
    || lt_ras(2)
    || lc_tab
    || lt_ras(3)
    || lc_tab
    || lt_ras(4)
    || lc_tab
    || lt_ras(5)
    || lc_tab
    || lt_ras(6)
    || lc_tab
    || util_pg.sumn(lt_ras(3), lt_ras(6))
    || lc_tab
    || util_pg.sumn(lt_ras(4), lt_ras(5))
    || lc_tab);
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.mkazah_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

