  --Макет журнал счетчика Казахстан
 PROCEDURE jourkazah_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cn_lock    CONSTANT NUMBER := 30;
  lc_tab     CONSTANT VARCHAR2(1) := '#';
  lc_season  CONSTANT VARCHAR2(1) := '0';                                                              -- указатель времени зима - лето, должен быть всегда = 0
  ld_date             DATE;

  CURSOR lcur_sel(lc_dat DATE) IS
   SELECT   NVL(mg.vcode, get_vcode(mg.ngroup)) vcode, e.evdate, e.evtype
   FROM     ea_events e, maketpoints mp, maketgroups mg
   WHERE    e.denter >= lc_dat AND e.mid = mp.mid AND mp.ngroup = mg.ngroup AND mg.nmaket = an_maket
   ORDER BY NVL(mg.vcode, get_vcode(mg.ngroup)), e.evdate, e.evtype;
 BEGIN
  IF admin_pg.lock_p(cn_lock, 'ea_events') <> 1 THEN
   raise_application_error(-20009,
    'Формирование файла не может быть произведено ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.', TRUE);
  END IF;

  SELECT NVL(MAX(dlastcreated), SYSDATE - 500)
  INTO   ld_date
  FROM   makets
  WHERE  nmaket = an_maket;

  IF file_pg.is_immediate = 1 THEN                                                                     --Если запущен вручную то уменьшаем до входного параметра
   ld_date := LEAST(NVL(ad_date, ld_date), ld_date);
  END IF;

  FOR lc IN lcur_sel(ld_date) LOOP
   file_pg.out_p(lc.vcode || lc_tab || TO_CHAR(lc.evdate, 'dd/mm/yyyy hh24:mi') || lc_tab || lc_season || lc_tab || lc.evtype || lc_tab || '0' || lc_tab || ''
    || lc_tab);
  END LOOP;

  SYS.DBMS_LOCK.sleep(1);
 END;

