  --Макет ГН
 PROCEDURE m4024_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cn_step    CONSTANT NUMBER := 1 / 48;                                                                                                            --:= CHR(9);
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  cn_row     CONSTANT NUMBER := 4;

  CURSOR lcur_g IS
   SELECT   ngroup, NVL(vcode, get_vcode(ngroup)) vcode
   FROM     maketgroups
   WHERE    nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mid, nkc
   FROM   maketpoints
   WHERE  ngroup = lc_group;

  CURSOR lcur_s(lc_group NUMBER) IS
   SELECT     nsubgroup, nsign
   FROM       maketformulas
   CONNECT BY PRIOR nsubgroup = ngroup
   START WITH ngroup = lc_group;

  CURSOR lcur_r(lc_mid NUMBER, lc_nkc NUMBER) IS
   SELECT   util_pg.get_num_dt(date_time - 1 / 86400, nsource, cn_step) dt, ROUND(DECODE(SIGN(lc_nkc), -1, SUM(b.ed), SUM(b.er)), cn_rn) er,
            ROUND(DECODE(SIGN(lc_nkc), -1, SUM(b.er), SUM(b.ed)), cn_rn) ed,
            ROUND(DECODE(SIGN(lc_nkc), -1, util_pg.sumn(SUM(b.q3), SUM(b.q4)), util_pg.sumn(SUM(b.q1), SUM(b.q2))), cn_rn) q1,
            ROUND(DECODE(SIGN(lc_nkc), -1, util_pg.sumn(SUM(b.q1), SUM(b.q2)), util_pg.sumn(SUM(b.q3), SUM(b.q4))), cn_rn) q3
   FROM     halfhour b
   WHERE    b.mid = lc_mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1
   GROUP BY util_pg.get_num_dt(date_time - 1 / 86400, nsource, cn_step);

  lt_ras              common_pg.tt_number;
  lt_str              common_pg.tt_varchar2;
  ln_col              NUMBER DEFAULT util_pg.get_count_dt(ad_date, cn_step) + 1;
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  ln_ost              NUMBER := 0;
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);
  file_pg.out_p('((//' || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '4024') || ':' || TO_CHAR(ad_date, 'yymmdd') || ':' || lv_ent || '++');

  FOR lc_g IN lcur_g LOOP                                                                                                                --Идем по всем группам
   FOR i IN 1 .. ln_col LOOP                                                                                                        --Занулили временный массив
    FOR j IN 1 .. cn_row LOOP
     lt_ras(ln_col *(j - 1) + i) := NULL;
     lt_str(j) := '';
    END LOOP;
   END LOOP;

   FOR lc_p IN lcur_p(lc_g.ngroup) LOOP                                                                                      --Просуммировали все точки в группе
    FOR lc_r IN lcur_r(lc_p.mid, lc_p.nkc) LOOP
     lt_ras(0 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(0 * ln_col + lc_r.dt), lc_r.er);
     lt_ras(1 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(1 * ln_col + lc_r.dt), lc_r.ed);
     lt_ras(2 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(2 * ln_col + lc_r.dt), lc_r.q1);
     lt_ras(3 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(3 * ln_col + lc_r.dt), lc_r.q3);
    END LOOP;
   END LOOP;

   FOR lc_s IN lcur_s(lc_g.ngroup) LOOP                                                                                  --Просуммировали все дочерние подгруппы
    FOR lc_p IN lcur_p(lc_s.nsubgroup) LOOP
     FOR lc_r IN lcur_r(lc_p.mid, lc_p.nkc * lc_s.nsign) LOOP
      lt_ras(0 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(0 * ln_col + lc_r.dt), lc_r.er);
      lt_ras(1 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(1 * ln_col + lc_r.dt), lc_r.ed);
      lt_ras(2 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(2 * ln_col + lc_r.dt), lc_r.q1);
      lt_ras(3 * ln_col + lc_r.dt) := util_pg.sumn(lt_ras(3 * ln_col + lc_r.dt), lc_r.q3);
     END LOOP;
    END LOOP;
   END LOOP;

   --Округляем до целых, остатки переносим на следующее значение
   FOR j IN 1 .. cn_row LOOP
    ln_ost := 0;

    FOR i IN 1 .. ln_col - 1 LOOP
     lt_ras((j - 1) * ln_col + i) := lt_ras((j - 1) * ln_col + i) + ln_ost;
     ln_ost := lt_ras((j - 1) * ln_col + i) - TRUNC(lt_ras((j - 1) * ln_col + i));
     lt_ras((j - 1) * ln_col + i) := TRUNC(lt_ras((j - 1) * ln_col + i));
    END LOOP;
   END LOOP;

   FOR i IN 1 .. ln_col - 1 LOOP                                                                                             --Вычислили cn_row суточных расхода
    FOR j IN 1 .. cn_row LOOP
     lt_ras((j - 1) * ln_col + ln_col) := util_pg.sumn(lt_ras((j - 1) * ln_col + ln_col), lt_ras((j - 1) * ln_col + i));

     IF i = ln_col - 1 THEN
      lt_str(j) := lt_str(j) || lt_ras((j - 1) * ln_col + i);
     ELSE
      lt_str(j) := lt_str(j) || lt_ras((j - 1) * ln_col + i) || lv_tab;
     END IF;
    END LOOP;
   END LOOP;

   FOR j IN 1 .. cn_row LOOP                                                                                                              --Собрали cn_row сторк
    lt_str(j) :=
     '(' || lc_g.vcode || ':0' || j || ':' || ROUND(24 * 60 * cn_step) || ')' || lv_tab
     || REPLACE(lt_ras((j - 1) * ln_col + ln_col) || lv_tab || lt_str(j), '.', ',');
    --IF lt_ras((j - 1) * ln_col + ln_col) IS NOT NULL THEN --Если что-то есть, то выводим
    file_pg.out_p(lt_str(j));
   --END IF;
   END LOOP;

   lt_ras.DELETE;
   lt_str.DELETE;
  END LOOP;

  file_pg.out_p('==))');
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 817-817 (для Днепр ЭС)
 PROCEDURE m817_818_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  lv_tab     CONSTANT VARCHAR2(1) := ':';
  ln_ras              NUMBER := 0;
  ln_allras           NUMBER := 0;
  ln_gr               NUMBER := 0;
  ln_str              NUMBER := 0;
  ln_col              NUMBER := 0;
  lv_res              VARCHAR2(4000) := '';

  CURSOR lcur_p(lc_group NUMBER) IS
   SELECT mid, nkc, ntype
   FROM   maketpoints
   WHERE  ngroup = lc_group;
 BEGIN
  file_pg.out_p('.040100 TRAS.');

  FOR lc_g IN (SELECT   ngroup, vcode, util_pg.allnumber_f(util_pg.get_param(vcode, 1, lv_tab)) p1, util_pg.allnumber_f(util_pg.get_param(vcode, 2, lv_tab))
                                                                                                                                                            p2,
                        util_pg.allnumber_f(util_pg.get_param(vcode, 3, lv_tab)) p3
               FROM     maketgroups
               WHERE    nmaket = an_maket
               ORDER BY 3, 4, 5, 1) LOOP
   ln_allras := 0;

   FOR lc_p IN lcur_p(lc_g.ngroup) LOOP                                                                                              -- находим сумму по группе
    SELECT   lc_p.nkc
           * SUM(DECODE(
               lc_p.ntype,
               1, b.er,
               2, b.ed,
               3, b.q1,
               4, b.q3,
               5, util_pg.sld(b.mid, NVL(b.er, 0), NVL(b.ed, 0)),
               6, util_pg.sld(b.mid, NVL(b.q1, 0), NVL(b.q3, 0))
              ))
    INTO   ln_ras
    FROM   halfhour b
    WHERE  b.mid = lc_p.mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1;

    ln_allras := ln_allras + NVL(ln_ras, 0);
   END LOOP;

   IF ln_gr = lc_g.p1 AND ln_str = lc_g.p2 AND ln_col <> lc_g.p3 THEN
    WHILE lc_g.p3 - ln_col > 1 LOOP
     lv_res := lv_res || '0:';
     ln_col := ln_col + 1;
    END LOOP;
   END IF;

   IF ln_str <> lc_g.p2 THEN
    IF lv_res IS NOT NULL THEN                                                                                                     -- выводим предыдущую строку
     IF ln_gr <> lc_g.p1 THEN
      file_pg.out_p(lv_res || '==))');
     ELSE
      file_pg.out_p(lv_res);
     END IF;

     lv_res := '';
    END IF;
   END IF;

   IF ln_gr <> lc_g.p1 THEN
    IF lv_res IS NOT NULL THEN                                                                                                 -- выгружаем с предыдущей группы
     file_pg.out_p(lv_res || '==))');
     lv_res := '';
    END IF;

    IF lv_res IS NULL THEN
     lv_res := '((//' || lc_g.p1 || ':' || TO_CHAR(ad_date, 'mmdd') || '2400:513100:++';
    END IF;

    file_pg.out_p(lv_res);
    lv_res := '';
    ln_col := 0;
   END IF;

   lv_res := lv_res || ln_allras || ':';
   ln_gr := lc_g.p1;
   ln_str := lc_g.p2;
   ln_col := lc_g.p3;
  END LOOP;

  IF lv_res IS NOT NULL THEN                                                                                                         -- выводим последнюю строку
   file_pg.out_p(lv_res || '==))');
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 817
 PROCEDURE m817_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_p IS
   SELECT   mg.ngroup, NVL(mg.vcode, get_vcode(mg.ngroup)) vcode, mg.vname, MAX(mp.mid) mid, MAX(mp.nkc) nkc, MAX(mp.ntype) ntype, COUNT(*) cn, f.vimportcode
   FROM     maketgroups mg, maketpoints mp, feeders f
   WHERE    mg.nmaket = an_maket AND mg.ngroup = mp.ngroup AND f.mid = mp.mid
   GROUP BY mg.ngroup, NVL(mg.vcode, get_vcode(mg.ngroup)), mg.vname, f.vimportcode
   ORDER BY mg.vname;

  lt_ras              common_pg.tt_number;
  lt_str              common_pg.tt_varchar2;
  lv_str              VARCHAR2(4000);
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  cn_row     CONSTANT NUMBER := 6;
  ld_date             DATE;
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  lv_tmp              VARCHAR2(2000);
  lv_res              VARCHAR2(2000);
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);
  file_pg.out_p('((//'
   || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '817')
   || lv_tab
   || TO_CHAR(ad_date, NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 'MMDD'))
   || lv_tab
   || lv_ent
   || lv_tab
   || '++');

  FOR lc_p IN lcur_p LOOP                                                                                                                 --Идем по всем группам
   IF lc_p.cn <> 1 THEN                                                                                         --Если больше обной точки в группе, то ругаемся
    raise_application_error(-20001,
     'Для макета 817 каждая группа должна содержать не более одной точки. Данное условие нарушено для группы: ''' || lc_p.vname || '''');
   END IF;

   FOR i IN 1 .. cn_row LOOP                                                                                                         --Занулили временный массив
    lt_ras(i) := NULL;
   END LOOP;

   ld_date := NULL;

   SELECT SUM(er) er, SUM(ed) ed, SUM(q1) q1, SUM(q3) q3, SUM(q2) q2, SUM(q4) q4
   INTO   lt_ras(1), lt_ras(2), lt_ras(3), lt_ras(4), lt_ras(5), lt_ras(6)
   FROM   halfhour
   WHERE  mid = lc_p.mid AND date_time > TRUNC(ad_date) AND date_time <= TRUNC(ad_date) + 1;

   FOR i IN 1 .. cn_row LOOP
    lv_tmp := util_pg.get_param(TRIM(UPPER(lc_p.vimportcode)), i, ';');

    IF i = 5 THEN
     lv_res := util_pg.sld(lc_p.mid, NVL(lt_ras(1), 0), NVL(lt_ras(2), 0));
    ELSIF i = 6 THEN
     lv_res := util_pg.sld(lc_p.mid, NVL(lt_ras(3), 0), NVL(lt_ras(4), 0));
    ELSE
     lv_res := lt_ras(i);
    END IF;

    IF lc_p.vcode IS NOT NULL THEN
     IF i = lc_p.ntype THEN
      file_pg.out_p('(' || lc_p.vcode || ')' || lv_tab || lv_res || lv_tab);
     END IF;
    ELSIF lv_tmp IS NOT NULL THEN
     file_pg.out_p('(' || lv_tmp || ')' || lv_tab || lv_res || lv_tab);
    END IF;
   END LOOP;

   lt_ras.DELETE;
  END LOOP;

  file_pg.out_p('==))');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m817_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

