 -- added by KAG 21.07.2009
 PROCEDURE maskp_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  lv_bstr             VARCHAR2(2000);
  ld_date             DATE DEFAULT TRUNC(ad_date);
  ln_daycnt           NUMBER;                                                                                             -- кол-во отчетных дней после ld_date
  ln_timeshift        NUMBER DEFAULT 0;                                                                             -- сдвиг времени относительно Украины зимой
  lv_power            VARCHAR2(32000);
  lv_qm               VARCHAR2(8000);
  ln_ktr              NUMBER;
  lb_switchsummer     BOOLEAN DEFAULT TRUE;                                       -- переход на лето (надо задавать 0 для получения пояса без перехода на лето)
  ln_rnd              NUMBER DEFAULT 3;                                                                                           -- число знаков после запятой
  lv_mask             VARCHAR2(100) := '99999999990';                                                                        -- маска для форматирования вывода
  ln_summersw         NUMBER DEFAULT 1;
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  ln_daycnt := NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 1);                                                                                                 --1
  ln_timeshift := (NVL(TRIM(util_pg.get_param(lv_bstr, 5)), 0) / 24) * -1;                                                                                 ---1
  lb_switchsummer :=(NVL(TRIM(util_pg.get_param(lv_bstr, 6)), 1) <> 0);                                                                                     --0
  ln_summersw := NVL(TRIM(util_pg.get_param(lv_bstr, 6)), 1);
  ln_rnd := NVL(TRIM(util_pg.get_param(lv_bstr, 7)), 3);                                                                                                    --4

  IF ln_rnd = 0 THEN
   lv_mask := '99999999990';
  ELSIF ln_rnd BETWEEN 1 AND 10 THEN
   lv_mask := RPAD('99999999990D', 12 + ln_rnd, '9');
  ELSE
   lv_mask := '99999999990D999';
  END IF;

  file_pg.out_p(TO_CHAR(SYSDATE, 'yy/mm/dd hh24:mi:ss') || ' ' || NVL(TRIM(util_pg.get_param(lv_bstr, 1)), util_pg.enterprisename_f));
  file_pg.out_p('');
  file_pg.out_p('');

  FOR lc IN (SELECT   mg.ngroup, mg.vcode, mg.vname, MAX(mp.mid) mid, MAX(mp.nkc) nkc, MAX(mp.ntype) ntype, COUNT(*) cn
             FROM     maketgroups mg, maketpoints mp
             WHERE    mg.nmaket = an_maket AND mg.ngroup = mp.ngroup
             GROUP BY mg.ngroup, mg.vcode, mg.vname
             ORDER BY mg.vname) LOOP
   IF lc.cn <> 1 THEN                                                                                           --Если больше обной точки в группе, то ругаемся
    raise_application_error(-20001,
     'Для макета АСКП каждая группа должна содержать не более одной точки. Данное условие нарушено для группы: ''' || lc.vname || '''');
   END IF;

   IF lc.vcode IS NULL THEN
    raise_application_error(-20001, 'В макете АСКП каждая группа должна иметь идентификатор. Данное условие нарушено для группы: ''' || lc.vname || '''');
   END IF;

   SELECT NVL(MAX(f.kc), 1)
   INTO   ln_ktr
   FROM   feeders f
   WHERE  f.mid = lc.mid;

   ld_date := TRUNC(ad_date);

   IF lb_switchsummer THEN
    file_pg.out_p('< REC=POINT; ID=' || lc.vcode || '; TIME=' ||(-1 - ln_timeshift * 24) || '; LTIME=1; KTR=' || ln_ktr || '; >');
   ELSE
    file_pg.out_p('< REC=POINT; ID=' || lc.vcode || '; TIME=' ||(-1 - ln_timeshift * 24) || '; LTIME=0; KTR=' || ln_ktr || '; >');
   END IF;

   FOR i IN 1 .. ln_daycnt LOOP
    lv_power := '';
    lv_qm := '';

    IF lb_switchsummer THEN                                                                                                         -- летом к зиме не приводим
     FOR lc_h IN (SELECT   MAX(qm) qm, SUM(pow) pow, dt
                  FROM     (SELECT   MAX(h.vqm) qm,
                                     SUM(DECODE(
                                       lc.ntype,
                                       1, h.er,
                                       2, h.ed,
                                       3, h.q1,
                                       4, h.q3,
                                       5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                                       6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                                      )) pow,
                                     util_pg.get_num_dt(h.date_time - 1 / 86400, nsource, 1 / 48, 0, ln_timeshift, ln_summersw) dt
                            --    TRUNC(TO_CHAR(h.date_time - 1 / 86400 + ln_timeshift, 'SSSSS') / 1800) dt
                            FROM     halfhour h
                            WHERE    h.mid = lc.mid AND h.date_time > ld_date - ln_timeshift AND h.date_time <= ld_date + 1 - ln_timeshift
                            GROUP BY util_pg.get_num_dt(h.date_time - 1 / 86400, nsource, 1 / 48, 0, ln_timeshift, ln_summersw)
                            --TRUNC(TO_CHAR(h.date_time - 1 / 86400 + ln_timeshift, 'SSSSS') / 1800)
                            UNION ALL
                            SELECT NULL qm, NULL pow, ROWNUM dt                                                                                  --ROWNUM - 1 dt
                            FROM   dict
                            WHERE  ROWNUM <= 48)
                  GROUP BY dt
                  ORDER BY dt) LOOP
      lv_power := lv_power || LTRIM(TO_CHAR(lc_h.pow / 1000 * 2, lv_mask)) || ',';

      -- переводим в мощность и мВт и учитываем Ктр
      IF lc_h.pow IS NULL THEN
       lv_qm := lv_qm || ',';
      ELSE
       lv_qm := lv_qm || ' ,';
      END IF;
     END LOOP;
    ELSE                                                                            -- всегда приводим сначала к зиме, а потом сдвигаем на нужный временной пояс
     FOR lc_h IN (SELECT   MAX(qm) qm, SUM(pow) pow, dt
                  FROM     (SELECT   MAX(h.vqm) qm,
                                     SUM(DECODE(
                                       lc.ntype,
                                       1, h.er,
                                       2, h.ed,
                                       3, h.q1,
                                       4, h.q3,
                                       5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                                       6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                                      )) pow,
                                     util_pg.get_num_dt(util_pg.to_unlocaltime(h.date_time - 1 / 86400, nsource), nsource, 1 / 48, 0, ln_timeshift,
                                      ln_summersw) dt
                            --util_pg.get_num_dt (h.date_time-1/86400,nsource, 1/48,0,ln_timeshift,1) dt
                            --   TRUNC(  TO_CHAR(  util_pg.to_unlocaltime(h.date_time)
                            --                   - 1 / 86400
                            --                   + ln_timeshift,
                             --                  'SSSSS')
                            --         / 1800) dt
                            FROM     halfhour h
                            WHERE    h.mid = lc.mid AND date_time >=(ld_date + 1 / 86400 + ln_timeshift - DECODE(ln_timeshift, 0, 0, 3 / 24))
                                     AND date_time <=(ld_date + 1 + ln_timeshift + DECODE(ln_timeshift, 0, 0, 3 / 24))
                                     AND util_pg.to_unlocaltime(h.date_time, nsource) >= ld_date + 1 / 86400 + ln_timeshift
                                     AND util_pg.to_unlocaltime(h.date_time, nsource) <= ld_date + 1 + ln_timeshift
                            --  and  h.mid=57693
                            GROUP BY util_pg.get_num_dt(util_pg.to_unlocaltime(h.date_time - 1 / 86400, nsource), nsource, 1 / 48, 0, ln_timeshift, ln_summersw)
                             /*     AND util_pg.to_unlocaltime(h.date_time) > ld_date - ln_timeshift
                                   AND util_pg.to_unlocaltime(h.date_time) <= ld_date + 1 - ln_timeshift
                              GROUP BY  util_pg.get_num_dt (h.date_time-1/86400,nsource, 1/48,0,ln_timeshift,1)  */
                            --  TRUNC(  TO_CHAR(util_pg.to_unlocaltime(h.date_time) - 1 / 86400
                            --                           + ln_timeshift,
                            --                           'SSSSS')
                            --                 / 1800)
                            UNION ALL
                            SELECT NULL qm, NULL pow, ROWNUM dt                                                                                 -- ROWNUM - 1 dt
                            FROM   dict
                            WHERE  ROWNUM <= 48)
                  GROUP BY dt
                  ORDER BY dt) LOOP
      lv_power := lv_power || LTRIM(TO_CHAR(lc_h.pow / 1000 * 2, lv_mask)) || ',';

      -- переводим в мощность и мВт и учитываем Ктр
      IF lc_h.pow IS NULL THEN
       lv_qm := lv_qm || ',';
      ELSE
       lv_qm := lv_qm || ' ,';
      END IF;
     END LOOP;
    END IF;

    lv_power := SUBSTR(lv_power, 1, LENGTH(lv_power) - 1);
    lv_qm := SUBSTR(lv_qm, 1, LENGTH(lv_qm) - 1);
    file_pg.out_p('< REC=DAY; DATE=' || TO_CHAR(ld_date, 'YYMMDD') || '; FORMAT=MWT; P48=' || lv_power || '; ST48=' || lv_qm || '; >');
    ld_date := ld_date + 1;
   END LOOP;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.mASKP_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

