 -- added by KAG 22.07.2009
 PROCEDURE mlg_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  lv_bstr             VARCHAR2(2000);
  ld_date             DATE DEFAULT TRUNC(ad_date);
  ln_daycnt           NUMBER;                                                                                             -- кол-во отчетных дней после ld_date
  lv_header           VARCHAR2(4000);
  ln_cnt              NUMBER DEFAULT 48;                                                                                        -- кол-во интегральных периодов
  ln_digits           NUMBER DEFAULT 6;                                                                             -- Размерность данных в десятичных позициях
  ln_timeshift        NUMBER DEFAULT 0;                                                                             -- сдвиг времени относительно Украины зимой
  lv_mask             VARCHAR2(1000);
  ln_sum              NUMBER;
  lv_power            VARCHAR2(4000);
  lb_switchsummer     BOOLEAN DEFAULT TRUE;
 -- переход на лето (надо задавать 0 для получения пояса без перехода на лето)
 BEGIN
  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  ln_cnt := NVL(TRIM(util_pg.get_param(lv_bstr, 2)), 48);
  ln_digits := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), 6);
  ln_daycnt := NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 1);
  ln_timeshift := NVL(TRIM(util_pg.get_param(lv_bstr, 5)), 0) / 24;
  lb_switchsummer :=(NVL(TRIM(util_pg.get_param(lv_bstr, 6)), 1) <> 0);

  IF ln_digits NOT IN(4, 6, 8) THEN
   raise_application_error(-20001, 'Для макета LG размерность данных должна принимать значения 4, 6 или 8 (3й параметр).');
  ELSE
   SELECT DECODE(ln_digits, 4, 'FM0000', 6, 'FM000000', 8, 'FM00000000', 'FM000000')
   INTO   lv_mask
   FROM   DUAL;
  END IF;

  IF ln_cnt NOT IN(24, 48) THEN
   raise_application_error(-20001, 'Для макета LG число периодов интеграции в сутках должно принимать значения 24 или 48 (2й параметр).');
  END IF;

  FOR lc IN (SELECT   mg.ngroup, mg.vname, MAX(mp.mid) mid, NVL(mg.vcode, get_vcode(mg.ngroup)) vcode, MAX(mp.nkc) nkc, MAX(mp.ntype) ntype,
                      MAX(NVL(p.short_name, p.NAME)) NAME, COUNT(*) cn
             FROM     maketgroups mg, maketpoints mp, points p
             WHERE    mg.nmaket = an_maket AND mg.ngroup = mp.ngroup AND mp.mid = p.mid
             GROUP BY mg.ngroup, mg.vname, NVL(mg.vcode, get_vcode(mg.ngroup))
             ORDER BY mid, ntype) LOOP
   IF lc.cn <> 1 THEN                                                                                           --Если больше обной точки в группе, то ругаемся
    raise_application_error(-20001,
     'Для макета LG каждая группа должна содержать не более одной точки. Данное условие нарушено для группы: ''' || lc.vname || '''');
   END IF;

   IF lc.vcode IS NULL THEN
    raise_application_error(-20001, 'В макете LG каждая группа должна иметь идентификатор. Данное условие нарушено для группы: ''' || lc.vname || '''');
   END IF;

   ld_date := TRUNC(ad_date);

   FOR i IN 1 .. ln_daycnt LOOP
    lv_power := '';
    ln_sum := 0;

    IF lb_switchsummer THEN                                                                                                          -- лето к зиме не приводим
     FOR lc_h IN (SELECT   SUM(pow) pow, dt
                  FROM     (SELECT   SUM(DECODE(
                                       lc.ntype,
                                       1, h.er,
                                       2, h.ed,
                                       3, h.q1,
                                       4, h.q3,
                                       5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                                       6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                                      )) pow,
                                     TRUNC(TO_CHAR(h.date_time - 1 / 86400 + ln_timeshift, 'SSSSS') /(86400 / ln_cnt)) dt
                            FROM     halfhour h
                            WHERE    h.mid = lc.mid AND h.date_time > ld_date - ln_timeshift AND h.date_time <= ld_date + 1 - ln_timeshift
                            GROUP BY TRUNC(TO_CHAR(h.date_time - 1 / 86400 + ln_timeshift, 'SSSSS') /(86400 / ln_cnt))
                            UNION ALL
                            SELECT 0 pow, ROWNUM - 1 dt
                            FROM   dict
                            WHERE  ROWNUM <= ln_cnt)
                  GROUP BY dt
                  ORDER BY dt) LOOP
      lv_power := lv_power || TO_CHAR(lc_h.pow * ln_cnt / 24, lv_mask) || '000';
      -- приводим к мощности при необходимости
      ln_sum := ln_sum + TO_CHAR(lc_h.pow * ln_cnt / 24, lv_mask);
     END LOOP;
    ELSE                                                                            -- всегда приводим сначала к зиме, а потом сдвигаем на нужный временной пояс
     FOR lc_h IN (SELECT   SUM(pow) pow, dt
                  FROM     (SELECT   SUM(DECODE(
                                       lc.ntype,
                                       1, h.er,
                                       2, h.ed,
                                       3, h.q1,
                                       4, h.q3,
                                       5, util_pg.sld(h.mid, NVL(h.er, 0), NVL(h.ed, 0)),
                                       6, util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0))
                                      )) pow,
                                     TRUNC(TO_CHAR(util_pg.to_unlocaltime(h.date_time) - 1 / 86400 + ln_timeshift, 'SSSSS') /(86400 / ln_cnt)) dt
                            FROM     halfhour h
                            WHERE    h.mid = lc.mid AND util_pg.to_unlocaltime(h.date_time) > ld_date - ln_timeshift
                                     AND util_pg.to_unlocaltime(h.date_time) <= ld_date + 1 - ln_timeshift
                            GROUP BY TRUNC(TO_CHAR(util_pg.to_unlocaltime(h.date_time) - 1 / 86400 + ln_timeshift, 'SSSSS') /(86400 / ln_cnt))
                            UNION ALL
                            SELECT 0 pow, ROWNUM - 1 dt
                            FROM   dict
                            WHERE  ROWNUM <= ln_cnt)
                  GROUP BY dt
                  ORDER BY dt) LOOP
      lv_power := lv_power || TO_CHAR(lc_h.pow * ln_cnt / 24, lv_mask) || '000';
      -- приводим к мощности при необходимости
      ln_sum := ln_sum + TO_CHAR(lc_h.pow * ln_cnt / 24, lv_mask);
     END LOOP;
    END IF;

    -- собираем заголовок
    lv_header :=
        RPAD(SUBSTR(lc.NAME, 1, 10), 10, '_')
     || LPAD(SUBSTR(lc.vcode, 1, 8), 8, '0')
     || TO_CHAR(ln_digits, 'FM00')
     || '03'
     || TO_CHAR(ld_date + 1 / ln_cnt, 'YYMMDDHH24MI')
     || '1'
     || TO_CHAR(1440 / ln_cnt, 'FM000')
     || TO_CHAR(ln_cnt, 'FM000000')
     || '000000000000000000000000000000';
    --file_pg.out_p('111111111111111'||chr(12),1);
    file_pg.out_p(lv_header || lv_power || TO_CHAR(ln_sum, 'FM000000000000') || '00000000002' || CHR(12));
    ld_date := ld_date + 1;
   END LOOP;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.mLG_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE m30902_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  lv_tab     CONSTANT VARCHAR2(1) := ':';                                                                                                          --:= CHR(9);
  hc                  NUMBER;                                                                                                          -- кол-во часов в сутках
  lv_str              VARCHAR2(2000);
  lv_bstr             VARCHAR2(2000);
  lv_ent              VARCHAR2(2000);
  lv_type25           VARCHAR2(2000);
  ld_date             DATE;
  ln_enddate          NUMBER;
  data_t              common_pg.tt_number;
  lv_strend           VARCHAR2(4000);
  ln_data             NUMBER;
  ln_test             NUMBER;
  ln_test2            NUMBER;
  lv_addcode          VARCHAR2(2000);
 BEGIN
  data_t.DELETE;

  SELECT MAX(vparam)
  INTO   lv_bstr
  FROM   makets
  WHERE  nmaket = an_maket;

  ld_date := TRUNC(ad_date, 'mm');
  ln_enddate := TO_CHAR(LAST_DAY(ad_date), 'dd') + 1;
  lv_ent := NVL(TRIM(util_pg.get_param(lv_bstr, 3)), util_pg.enterprise_char_f);
  lv_ent := lv_ent || ':' || NVL(TRIM(util_pg.get_param(lv_bstr, 6)), util_pg.enterprise_char_f);

  -- Формирование теста макета
  IF TRIM(util_pg.get_param(lv_bstr, 2)) IS NOT NULL THEN
   file_pg.out_p(util_pg.get_param(lv_bstr, 2));
  END IF;

  IF TRIM(util_pg.get_param(lv_bstr, 10)) IS NOT NULL THEN
   lv_addcode := TRIM(util_pg.get_param(lv_bstr, 10)) || lv_tab;
  END IF;

  lv_type25 := NVL(TRIM(util_pg.get_param(lv_bstr, 7)), '10');
  file_pg.out_p('((//'
   || NVL(TRIM(util_pg.get_param(lv_bstr, 5)), '30902')
   || lv_tab
   || TO_CHAR(ad_date, NVL(TRIM(util_pg.get_param(lv_bstr, 4)), 'YYMM'))
   || lv_tab
   || lv_ent
   || lv_tab
   || lv_addcode
   || '++');

  FOR i IN 1 .. ln_enddate - 1 LOOP
   hc := 24 - util_pg.is_dayswitch(ld_date);

   IF hc = 23 THEN
    hc := 24;
   END IF;

   -- hc:=25;
    --Заполняем расчетную таблицу
   begin_m30817(an_maket, ld_date, av_fname);
   ln_test := 0;

   FOR lc IN (SELECT   ngroup, util_pg.get_param(vcode, 1, ':') vcode, util_pg.get_param(vcode, 2, ':') vadd
              FROM     maketgroups
              WHERE    nmaket = an_maket
              ORDER BY vname) LOOP
    lv_str := '(' || lc.vcode || '):';

    IF i < 10 THEN
     lv_str := lv_str || '0' || i || ':';
    ELSE
     lv_str := lv_str || '' || i || ':';
    END IF;

    ln_test2 := data_t.COUNT;

    FOR i IN 1 .. 26 LOOP
     data_t(ln_test2 + i) := 0;
    END LOOP;

    FOR i IN 0 .. hc LOOP
     IF SUBSTR(lv_type25, 2, 1) = '1' AND util_pg.is_dayswitch(ld_date) = -1 THEN
      --переход на зиму и 25 в середину (меняем местами)
      IF i <> hc THEN
       SELECT lv_str || SUM(kwh) || ':'
       INTO   lv_str
       FROM   m30817
       WHERE  ngroup = lc.ngroup AND HOUR = i;
      END IF;

      IF i = util_pg.switch_f + 1 THEN
       SELECT lv_str || SUM(kwh) || ':'
       INTO   lv_str
       FROM   m30817
       WHERE  ngroup = lc.ngroup AND HOUR = hc;
      END IF;
     ELSIF SUBSTR(lv_type25, 1, 1) = '1' AND util_pg.is_dayswitch(ld_date) = 1 AND i = util_pg.switch_f + 1 THEN
      --переход на лето и дополнять нулями
      lv_str := lv_str || '0:';
     ELSIF NOT(util_pg.is_dayswitch(ld_date) = 1 AND i = util_pg.switch_f + 1) THEN                                                     --кроме перехода на лето
      SELECT lv_str || SUM(kwh) || ':'
      INTO   lv_str
      FROM   m30817
      WHERE  ngroup = lc.ngroup AND HOUR = i;
     END IF;

-------------------------------------------------------------------
     SELECT COUNT(*)
     INTO   ln_data
     FROM   m30817
     WHERE  ngroup = lc.ngroup AND HOUR = i;

     IF ln_data > 0 THEN
      SELECT SUM(kwh)
      INTO   ln_data
      FROM   m30817
      WHERE  ngroup = lc.ngroup AND HOUR = i;
     ELSE
      ln_data := 0;
     END IF;

     data_t((i + 1) + 26 * ln_test) := data_t((i + 1) + 26 * ln_test) + ln_data;
-----------------------------------------------------------
    END LOOP;

    IF NOT(util_pg.is_dayswitch(ld_date) = -1) THEN
     lv_str := lv_str || '0:';
    END IF;

    IF lc.vadd IS NOT NULL THEN
     lv_str := lv_str || lc.vadd || ':';
    END IF;

-------------------------------------------------
    ln_test := ln_test + 1;
--------------------------------------------
    file_pg.out_p(lv_str);
   END LOOP;

   end_m30817(an_maket, ld_date, av_fname);
   ld_date := ld_date + 1;
  END LOOP;

  ln_test := 0;

  FOR lc IN (SELECT   ngroup, util_pg.get_param(vcode, 1, ':') vcode, util_pg.get_param(vcode, 2, ':') vadd
             FROM     maketgroups
             WHERE    nmaket = an_maket
             ORDER BY vname) LOOP
   lv_str := '(' || lc.vcode || '):00:';

   FOR i IN 1 .. 26 LOOP
    lv_str := lv_str || data_t(i + 26 * ln_test) || ':';
   END LOOP;

   file_pg.out_p(lv_str);
   ln_test := ln_test + 1;
  END LOOP;

  file_pg.out_p('==))');
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'reports1_pg.m30902_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;

