 -- added by KAG 24.03.2010
 -- преобразует метку из 8битного десятичного числа в двоичный с 23 разрядами для АСУЭ
 FUNCTION convert_8to23bit_qm(av_8bitqm VARCHAR2, av_addparam VARCHAR2)
  RETURN VARCHAR2 IS
  lv_23bitqm          VARCHAR2(23) := qm_pg.cv_defqm;
  ln_8bitqm           NUMBER;
 BEGIN
  ln_8bitqm := util_pg.allnumber_f(TRIM(av_8bitqm));

  IF ln_8bitqm > 255 THEN
   raise_application_error(-20001, 'Входная метка больше 255!');
  END IF;

  -- проверяем 8 бит, маска 00000001
  IF BITAND(ln_8bitqm, 1) = 1 THEN                                                                                                                   -- 00000001
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 22, '5');
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 23, '1');
  ELSE
-- 00000000
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 22, '5');
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 23, '0');
  END IF;

  -- проверяем 2,3 биты, маска 01100000
  IF BITAND(ln_8bitqm, 96) = 0 THEN
-- 00000000
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 10, '0');
  ELSIF BITAND(ln_8bitqm, 96) = 32 THEN                                                                                                              -- 00100000
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 10, '0');
  ELSIF BITAND(ln_8bitqm, 96) = 64 THEN                                                                                                              -- 01000000
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 10, '1');
  ELSE                                                                                                                                               -- 01100000
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 10, '1');
  END IF;

  -- проверяем 4,5,6,7 биты, маска 00011110
  IF BITAND(ln_8bitqm, 30) = 30 THEN                                                                                                                 -- 00011110
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 1, '0');
  ELSE
   lv_23bitqm := qm_pg.sbt(lv_23bitqm, 1, '3');
  END IF;

  RETURN lv_23bitqm;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- added by KAG 30.03.2010
 -- преобразует 23битную метку качества в 8битный код подтверждения (для предварительного макета)
 FUNCTION convert_23to8bit_qm(av_23bitqm VARCHAR2, av_addparam VARCHAR2)
  RETURN NUMBER IS
  lv_23bitqm          VARCHAR2(128) := av_23bitqm;
  ln_8bitqm           PLS_INTEGER := 255;                                                                                                         -- = 11111111
 BEGIN
  -- код слегка избыточный, зато так понятней
  -- выставление 1 бита (отправка данныд)
  IF USER = 'RYDA' THEN                                                                                                       --01111111 автомат, иначе вручную
   ln_8bitqm := BITAND(ln_8bitqm, 127);
  END IF;

  -- выставление 2,3 бита (источник данных)
  IF qm_pg.gbt(lv_23bitqm, 22) IN(qm_pg.cn_prim, qm_pg.cn_ov, qm_pg.cn_calc, qm_pg.cn_maket) THEN
   ln_8bitqm := BITAND(ln_8bitqm, 159);                                                                                                --10011111 основной (00)
  ELSIF qm_pg.gbt(lv_23bitqm, 22) = qm_pg.cn_dupl THEN
   ln_8bitqm := BITAND(ln_8bitqm, 191);                                                                                                   --10111111 дубль (01)
  ELSIF qm_pg.gbt(lv_23bitqm, 22) IN(qm_pg.cn_add_def, qm_pg.cn_oik, qm_pg.cn_manual, qm_pg.cn_calcr) THEN
   ln_8bitqm := BITAND(ln_8bitqm, 223);                                                                                                  --11011111 расчет (10)
  ELSIF qm_pg.gbt(lv_23bitqm, 22) = qm_pg.cn_maket THEN
   ln_8bitqm := BITAND(ln_8bitqm, 255);                                                                                          --11111111 обратный конец (11)
  END IF;

  -- выставление 4 бита  (проверка по данным предыдущих периодов) приравниваем к конторолю границ
  IF NVL(qm_pg.gbt(lv_23bitqm, 16), ' ') <> qm_pg.cn_add_ok THEN                                                      --(проверка по данным предыдущих периодов)
   ln_8bitqm := BITAND(ln_8bitqm, 239);                                                         --11101111 проверка отсутствует или разница выхзодит за пределы
  END IF;

  -- выставление 5 бита  (проверка по дублям)
  IF NVL(qm_pg.gbt(lv_23bitqm, 18), ' ') <> qm_pg.cn_add_ok THEN
   ln_8bitqm := BITAND(ln_8bitqm, 247);                                                         --11110111 проверка отсутствует или разница выхзодит за пределы
  END IF;

  -- выставление 6 и 7 бита  (проверка по противоположному концу и балансу)
  IF NVL(qm_pg.gbt(lv_23bitqm, 21), ' ') <> qm_pg.cn_add_ok THEN
   ln_8bitqm := BITAND(ln_8bitqm, 249);
  --11111001 проверка отсутствует или разница выхзодит за пределы
  END IF;

  -- выставление 8 бита в 0 (для предварительного макета)
  IF NVL(TRIM(av_addparam), ' ') <> '1' THEN
   ln_8bitqm := BITAND(ln_8bitqm, 254);                                                                                                              --11111110
  END IF;

  RETURN ln_8bitqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION get_vcode(an_group NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(256);
  ln_mid              NUMBER;
 BEGIN
  SELECT DECODE(COUNT(*), 1, MAX(mid), 0)
  INTO   ln_mid
  FROM   maketpoints
  WHERE  ngroup = an_group;

  IF ln_mid > 0 THEN
   SELECT MAX(vcode)
   INTO   lv_ret
   FROM   feeders
   WHERE  mid = ln_mid;
  END IF;

  RETURN lv_ret;
 END;

-------------------------------------------------------------------------------
  --Выгрузка суточных показаний в расчетную систему
 PROCEDURE export_to_billing(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  lc_raz     CONSTANT VARCHAR2(2) := '|';
  lc_sep     CONSTANT VARCHAR2(2) := ',';
  ln_customer         NUMBER := util_pg.get_customer_id;
 BEGIN
  IF ln_customer IN(0, 7) THEN
   FOR lc IN (SELECT   f.vaccount, TO_CHAR(b.date_time, 'dd/mm/yyyy') date_time, REPLACE(REPLACE(b.erm, ',', lc_sep), '.', lc_sep) erm,
                       REPLACE(REPLACE(b.aerm, ',', lc_sep), '.', lc_sep) aerm, REPLACE(REPLACE(b.berm, ',', lc_sep), '.', lc_sep) berm,
                       REPLACE(REPLACE(b.cerm, ',', lc_sep), '.', lc_sep) cerm
              FROM     (SELECT   mid, MAX(date_time) date_time, MAX(erm)KEEP (DENSE_RANK LAST ORDER BY date_time) erm,
                                 MAX(aerm)KEEP (DENSE_RANK LAST ORDER BY date_time) aerm, MAX(berm)KEEP (DENSE_RANK LAST ORDER BY date_time) berm,
                                 MAX(cerm)KEEP (DENSE_RANK LAST ORDER BY date_time) cerm
                        FROM     billorg
                        WHERE    date_time >= ADD_MONTHS(TRUNC(ad_date) + 1, -1) AND date_time < TRUNC(ad_date) + 1 AND erm IS NOT NULL
                        GROUP BY mid) b,
                       feeders f
              WHERE    b.mid = f.mid AND TRIM(f.vaccount) IS NOT NULL
              ORDER BY f.vaccount, f.mid) LOOP
    file_pg.out_p(lc.vaccount || lc_raz || lc.date_time || lc_raz || lc.erm || lc_raz || lc.aerm || lc_raz || lc.berm || lc_raz || lc.cerm || lc_raz);
   END LOOP;
  ELSE
   file_pg.out_p('Заказчик не поддерживается.');
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION frm_number(a NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  IF SUBSTR(ABS(a), 1, 1) IN('.', ',') THEN
   IF a < 0 THEN
    RETURN '-0' || ABS(a);
   ELSE
    RETURN '0' || a;
   END IF;
  END IF;

  RETURN a;
 END;
------------------------------------------------------------------------------------------------------------------------
