------------------------------------------------------------------------------------------------------------------------
--Макет mRDF
PROCEDURE mRDF_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2)
IS
  CURSOR lcur_g IS
   SELECT   ngroup, vcode
       FROM maketgroups
      WHERE nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p (lc_group NUMBER) IS
   SELECT mid, nkc, ntype
     FROM maketpoints
    WHERE ngroup = lc_group;
    
  CURSOR lcur_h (lc_p NUMBER) IS
   SELECT TO_CHAR(date_time,'dd.mm.yyyy hh24:mi:ss') dt,
          NVL(er,0) er, NVL(ed,0) ed, NVL(q1,0) q1, NVL(q3,0) q3,
          vqm
     FROM halfhour
    WHERE mid = lc_p AND date_time > TRUNC (ad_date) AND date_time <= TRUNC (ad_date) + 1;           

  ln_cnt      NUMBER DEFAULT 0; -- число записей 
  lv_tmp      common_pg.tt_varchar2;
BEGIN
lv_tmp(1) := 'AP';
lv_tmp(2) := 'AM';
lv_tmp(3) := 'RP';
lv_tmp(4) := 'RM';
lv_tmp(9) := 'Active_Plus_value';
lv_tmp(10) := 'Active_Minus_value';
lv_tmp(11) := 'Reactive_Plus_value';
lv_tmp(12) := 'Reactive_Minus_value';

  file_pg.out_p('<?xml version="1.0" encoding="UTF-8" standalone="no"?>');
  file_pg.out_p('<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#" 
                          xmlns:cim=http://iec.ch/TC57/2007/CIM-schema-cim12#">');

  -- SubControlArea start
  file_pg.out_p('<cim:SubControlArea rdf:ID="'|| 'SCTRLAREA01' ||'">');
    file_pg.out_p('<cim:IdentifiedObject.name>'|| '3' ||'</cim:IdentifiedObject.name>');
    FOR lc_g IN lcur_g LOOP
     FOR lc_p IN lcur_p (lc_g.ngroup) LOOP
      FOR an_i IN 1..4 LOOP
        file_pg.out_p('<cim:PowerSystemResource.Contains_Measurements rdf:resource="#'|| lv_tmp(an_i)||'_d'||lc_p.mid ||'"/>');
      END LOOP;
     END LOOP;
    END LOOP;
    file_pg.out_p('<cim:SubControlArea.HostControlArea/>');
  file_pg.out_p('</cim:SubControlArea>');
  -- SubControlArea end

  FOR lc_g IN lcur_g LOOP
   FOR lc_p IN lcur_p (lc_g.ngroup) LOOP
    
    lv_tmp(5) := NULL;
    lv_tmp(6) := NULL;
    lv_tmp(7) := NULL;
    lv_tmp(8) := NULL;
    FOR lc_m IN (SELECT mrid, nmeasure FROM mrids 
    WHERE mid=lc_p.mid AND nmeasure IN (1,2,3,5)) LOOP
      IF lc_m.nmeasure=1 THEN
        lv_tmp(5) := lc_m.mrid;
      ELSIF lc_m.nmeasure=2 THEN
        lv_tmp(6) := lc_m.mrid;
      ELSIF lc_m.nmeasure=3 THEN
        lv_tmp(7) := lc_m.mrid;
      ELSIF lc_m.nmeasure=5 THEN
        lv_tmp(8) := lc_m.mrid;
      END IF;
    END LOOP;
file_pg.out_p('<!-------------------------------------------------'||lc_p.mid||'-->');
    -- Analog start
    FOR an_i IN 1..4 LOOP
       file_pg.out_p('<cim:Analog rdf:ID="'|| lv_tmp(an_i)||'_d'||lc_p.mid ||'">');
           file_pg.out_p('<cim:IdentifiedObject.mRID>'|| lv_tmp(an_i+4) ||'</cim:IdentifiedObject.mRID>');
           file_pg.out_p('<cim:IdentifiedObject.name>'|| lv_tmp(an_i)||'_d'||lc_p.mid ||'</cim:IdentifiedObject.name>');
           file_pg.out_p('<cim:Measurement.MeasurementType/>');
           file_pg.out_p('<cim:Measurement.Unit/>');
           file_pg.out_p('<cim:Measurement.MemberOf_PSR/>');
       file_pg.out_p('</cim:Analog>');
    END LOOP;
    -- Analog end
file_pg.out_p('<!------------- пошли данные для '||lc_p.mid||'-->');    
    FOR lc_h IN lcur_h(lc_p.mid) LOOP
       ln_cnt := ln_cnt+1; 
       -- AnalogValue start
       file_pg.out_p('<!-- measurement values - record '||to_char(ln_cnt)||' -->'); 
       FOR avq_i IN 1..4 LOOP
        file_pg.out_p('<cim:AnalogValue rdf:ID="'|| lv_tmp(avq_i)||'_val_000'||to_char(ln_cnt) ||'">');
          file_pg.out_p('<cim:IdentifiedObject.name>'|| lv_tmp(avq_i+8) ||'</cim:IdentifiedObject.name>');
          file_pg.out_p('<cim:AnalogValue.MemberOf_Measurement rdf:resource="#'|| lv_tmp(avq_i)||'_d'||lc_p.mid ||'"/>');
          file_pg.out_p('<cim:MeasurementValue.MeasurementValueQuality rdf:resource="'|| '#MQUAL000'||to_char(ln_cnt)  ||'"/>');
          file_pg.out_p('<cim:MeasurementValue.timeStamp>'|| lc_h.dt ||'</cim:MeasurementValue.timeStamp>');
          IF avq_i=1 THEN
            file_pg.out_p('<cim:AnalogValue.value>'|| lc_h.er ||'</cim:AnalogValue.value>');
          ELSIF avq_i=2 THEN
            file_pg.out_p('<cim:AnalogValue.value>'|| lc_h.ed ||'</cim:AnalogValue.value>');
          ELSIF avq_i=3 THEN
            file_pg.out_p('<cim:AnalogValue.value>'|| lc_h.q1 ||'</cim:AnalogValue.value>');
          ELSIF avq_i=4 THEN
            file_pg.out_p('<cim:AnalogValue.value>'|| lc_h.q3 ||'</cim:AnalogValue.value>');
          END IF;
          file_pg.out_p('<cim:MeasurementValue.MeasurementValueSource rdf:resource="'|| '#MeasurementValueSource_CCLink' ||'"/>');
        file_pg.out_p('</cim:AnalogValue>');
       END LOOP;
      -- AnalogValue end
        
      -- EMSQuality start
      file_pg.out_p('<!-- measurement quality label - record '||to_char(ln_cnt)||' -->');
      file_pg.out_p('<cim:EMSQuality rdf:ID="'|| 'MQUAL000'||to_char(ln_cnt) ||'"> <!-- початок блоку EMSQuality, rdf:ID -  внутрішній ідентифікатор екземпляра об’єкта EMSQuality -->');
        file_pg.out_p('<cim:Quality61850.validity>'|| get_vqm(lc_h.vqm,1) ||'</cim:Quality61850.validity> <!-- атрибут validity, тип Validity -->');
        file_pg.out_p('<cim:Quality61850.badReference>'|| get_vqm(lc_h.vqm,4) ||'</cim:Quality61850.badReference><!-- атрибут badReference, тип Boolean-->');
        file_pg.out_p('<cim:Quality61850.estimatorReplaced>'|| 'false' ||'</cim:Quality61850.estimatorReplaced><!-- атрибут estimatorReplaced, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.failure>'|| get_vqm(lc_h.vqm,6) ||'</cim:Quality61850.failure><!-- атрибут failure, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.oldData>'|| get_vqm(lc_h.vqm,7) ||'</cim:Quality61850.oldData><!-- атрибут oldData, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.operatorBlocked>'|| get_vqm(lc_h.vqm,12) ||'</cim:Quality61850.operatorBlocked><!-- атрибут operatorBlocked, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.oscillatory>'|| get_vqm(lc_h.vqm,5) ||'</cim:Quality61850.oscillatory><!-- атрибут oscillatory, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.outOfRange>'|| get_vqm(lc_h.vqm,3) ||'</cim:Quality61850.outOfRange><!-- атрибут outOfRange, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.overFlow>'|| get_vqm(lc_h.vqm,2) ||'</cim:Quality61850.overFlow><!-- атрибут overFlow, тип Boolean -->');
        file_pg.out_p('<cim:Quality61850.source>'|| get_vqm(lc_h.vqm,10) ||'</cim:Quality61850.source> <!-- атрибут source, тип Source -->');
        file_pg.out_p('<cim:EMSQuality.DataRecieve>'|| get_vqm(lc_h.vqm,13) ||'</cim:EMSQuality.DataRecieve> <!-- атрибут DataRecieve, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.DataOnTime>'|| get_vqm(lc_h.vqm,14) ||'</cim:EMSQuality.DataOnTime> <!-- атрибут DataOnTime, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.MeterLOGCheck>'|| get_vqm(lc_h.vqm,15) ||'</cim:EMSQuality.MeterLOGCheck> <!-- атрибут MeterLOGCheck, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.BoundaryCheck>'|| get_vqm(lc_h.vqm,16) ||'</cim:EMSQuality.BoundaryCheck> <!-- атрибут BoundaryCheck, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.PrimaryRepearing>'|| get_vqm(lc_h.vqm,17) ||'</cim:EMSQuality.PrimaryRepearing> <!-- атрибут PrimaryRepearing, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.PrimaryVerification>'|| get_vqm(lc_h.vqm,18) ||'</cim:EMSQuality.PrimaryVerification> <!-- атрибут PrimaryVerification, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.BypassUsing>'|| get_vqm(lc_h.vqm,19) ||'</cim:EMSQuality.BypassUsing> <!-- атрибут BypassUsing, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.Calculation>'|| get_vqm(lc_h.vqm,20) ||'</cim:EMSQuality.Calculation> <!-- атрибут Calculation, тип StageResult -->');
        file_pg.out_p('<cim:EMSQuality.XVerification>'|| get_vqm(lc_h.vqm,21) ||'</cim:EMSQuality.XVerification> <!-- атрибут XVerification, тип StageResult -->');
      file_pg.out_p('</cim:EMSQuality>');
      -- EMSQuality end    
    END LOOP;
    file_pg.out_p('<!------------- закончились данные для '||lc_p.mid||'-->'); 
    
   END LOOP;

  END LOOP;

  -- MeasurementValueSource start
  file_pg.out_p('<!-- data sources -->');
  file_pg.out_p('<cim:MeasurementValueSource rdf:ID="'|| 'MeasurementValueSource_CCLink' ||'">');
    file_pg.out_p('<cim:IdentifiedObject.name>'|| 'CCLink' ||'</cim:IdentifiedObject.name>');
  file_pg.out_p('</cim:MeasurementValueSource>');
  file_pg.out_p('<cim:MeasurementValueSource rdf:ID="'|| 'MeasurementValueSource_Operator' ||'">');
    file_pg.out_p('<cim:IdentifiedObject.name>'|| 'Operator' ||'</cim:IdentifiedObject.name>');
  file_pg.out_p('</cim:MeasurementValueSource>');
  -- MeasurementValueSource end

file_pg.out_p('</rdf:RDF>');

END;
------------------------------------------------------------------------------------------------------------------------
 -- функция разбора метки качества, возвращает для заданного бита метку соответствующего типа
 -- Kondakov A.G. 24.11.2008
 FUNCTION get_vqm (av_vqm VARCHAR2, an_bit NUMBER) 
 RETURN VARCHAR2 IS
  lv_res VARCHAR2(100);
  ln_type NUMBER;
  lv_bit VARCHAR2(1);
 BEGIN
   IF av_vqm IS NULL THEN 
        RETURN 'NO VQM'; 
   END IF;
   lv_bit := qm_pg.gbt(av_vqm,an_bit);
   IF an_bit = 1 THEN       -- Тип Validity
     SELECT decode(lv_bit,
                   '0','good',
                   '1','invalid',
                   '2','reserved',
                   '3','questionable',
                   'UNDEFINED VALUE BIT'
                   ) INTO lv_res FROM dual;
   ELSIF an_bit BETWEEN 2 AND 9 OR an_bit IN (11,12) THEN   -- Тип Boolean
     SELECT decode(lv_bit,
                   '0','false',
                   '1','true',
                   'UNDEFINED VALUE BIT'
                   ) INTO lv_res FROM dual;
   ELSIF an_bit=10 THEN             -- Тип Source
     SELECT decode(lv_bit,
                   '0','process',
                   '1','substituted',
                   'UNDEFINED VALUE BIT'
                   ) INTO lv_res FROM dual;
   ELSIF an_bit BETWEEN 13 AND 21 THEN      -- Тип StageResult
     SELECT decode(lv_bit,
                   '0','Default',
                   '1','NoData',
                   '2','OK',
                   '3','Error',
                   'UNDEFINED VALUE BIT'
                   ) INTO lv_res FROM dual;
   ELSIF an_bit = 22 THEN                   -- Тип Source
     SELECT decode(lv_bit,
                   '0','noData',
                   '1','Primary',
                   '2','Secondary',
                   '3','SCADA',
                   '4','Manual',
                   '5','Layout',
                   '6','Bypass',
                   '7','Calculated',
                   'UNDEFINED VALUE BIT'
                   ) INTO lv_res FROM dual;
   ELSE 
     lv_res := 'UNDEFINED NUMBER BIT';
   END IF;  
   
   RETURN lv_res;
   
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                               -- Package Body reports2_pg
/


