-- Start of DDL Script for Package Body RYDA.REPORTS3_PG
-- Generated 14.04.2014 9:34:59 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY reports3_pg
IS
    -- пакет с процедурами для отчетов
    -- дата создания 05/09/2005 Коваленко А.С.

    --------------------------------------------------------------------------------
    PROCEDURE add_point (
        an_gid                  NUMBER,
        av_name                 VARCHAR2,
        av_param                VARCHAR2,
        an_mid                  NUMBER,
        av_inverted             VARCHAR2,
        an_level                NUMBER,
        ad_st                   DATE,
        ad_fin                  DATE,
        an_wasteflag            NUMBER,
        at_cons        IN OUT   common_pg.tt_number,
        at_wast        IN OUT   common_pg.tt_number,
        an_zone NUMBER
    )
    IS
        ln_dmid            NUMBER;   -- ИД дубля
        lv_dname           VARCHAR2 (300);   -- Имя дубля
        ld_st_ov           DATE           DEFAULT NULL;
        ld_fin_ov          DATE           DEFAULT NULL;
        ln_id_ov           NUMBER;   -- ИД обводника или основной точки
        lv_ov_name         VARCHAR2 (300);   -- имя обводника
        lv_ov_mtype        VARCHAR2 (20);   -- тип счетчика обводника
        lv_ov_mtrsn        VARCHAR2 (20);   -- номер счетчика обводника
        ld_st_dub          DATE;
        ld_fin_dub         DATE;
        ln_met_type        NUMBER;   -- 1 работаем по дублю 0- по основному
        ld_st_ch           DATE;
        ld_fin_ch          DATE;
        ln_ch              NUMBER;   -- 1 было снятие 0- небыло
        lv_sm              VARCHAR2 (20);   -- показания на начало
        lv_em              VARCHAR2 (20);   -- показания на конец
        ln_cons            NUMBER;
        ln_wast            NUMBER;
        lv_curr_ins_name   VARCHAR2 (300);   -- имя которое формируем динамически и вставляем в таблицу
        ln_entype          NUMBER;
        ln_kc              NUMBER;
        ln_kc_point        NUMBER;

        -- возвращает даты переключение на ОВ и обратно за отчетный период
        CURSOR lcur_ov_period (an_mid NUMBER)   -- сюда передаем ид основного счетчика. Соотсетственно в группах для отчетов тоже должны быть основные
        IS
            SELECT   ad_st ddate, an_mid ID
                FROM DUAL
               WHERE NOT EXISTS (
                         SELECT sw1.nswitch
                           FROM switches sw1, switches sw2
                          WHERE sw1.ID = sw2.ID
                            AND sw1.mid = an_mid
                            AND sw1.dswitch = (SELECT MAX (dswitch)
                                                 FROM switches
                                                WHERE mid = an_mid AND dswitch <= ad_st)
                            AND sw2.descape = (SELECT MIN (descape)
                                                 FROM switches
                                                WHERE mid = an_mid AND descape > ad_st))
            UNION ALL
            SELECT   ad_st ddate, sw1.nswitch ID
                FROM switches sw1, switches sw2
               WHERE sw1.ID = sw2.ID
                 AND sw1.mid = an_mid
                 AND sw1.dswitch = (SELECT MAX (dswitch)
                                      FROM switches
                                     WHERE mid = an_mid AND dswitch <= ad_st)
                 AND sw2.descape = (SELECT MIN (descape)
                                      FROM switches
                                     WHERE mid = an_mid AND descape > ad_st)
            UNION ALL
            SELECT   dswitch ddate, nswitch ID
                FROM switches
               WHERE mid = an_mid AND dswitch > ad_st AND dswitch < ad_fin
            UNION ALL
            SELECT   descape ddate, an_mid ID
                FROM switches
               WHERE mid = an_mid AND descape > ad_st AND descape < ad_fin
            UNION ALL
            SELECT   ad_fin ddate, an_mid ID
                FROM DUAL
            ORDER BY 1;

-- Возвращает даты перехода на дублирующие счетчики и обратно
        CURSOR lcur_dubperiod (an_dmid NUMBER, ad_stdate DATE, ad_findate DATE)   -- суда суем ИД дублируущего
        IS
            SELECT   ad_stdate ddate, 1 dubl
                FROM DUAL
               WHERE EXISTS (
                         SELECT *
                           FROM calcbyduplication cd1, calcbyduplication cd2
                          WHERE cd1.dstart = cd2.dstart
                            AND cd1.mid = cd2.mid
                            AND cd1.mid = an_dmid
                            AND cd1.dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_dmid AND dstart <= ad_stdate)
                            AND (cd2.dend = (SELECT MIN (dend)
                                               FROM calcbyduplication
                                              WHERE mid = an_dmid AND dend > ad_stdate) OR cd2.dend IS NULL))
            UNION ALL
            SELECT   ad_stdate ddate, 0 dubl
                FROM DUAL
               WHERE NOT EXISTS (
                         SELECT *
                           FROM calcbyduplication cd1, calcbyduplication cd2
                          WHERE cd1.dstart = cd2.dstart
                            AND cd1.mid = cd2.mid
                            AND cd1.mid = an_dmid
                            AND cd1.dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_dmid AND dstart <= ad_stdate)
                            AND (cd2.dend = (SELECT MIN (dend)
                                               FROM calcbyduplication
                                              WHERE mid = an_dmid AND dend > ad_stdate) OR cd2.dend IS NULL))
            UNION ALL
            SELECT   dstart ddate, 1 dubl
                FROM calcbyduplication
               WHERE mid = an_dmid AND dstart > ad_stdate AND dstart < ad_findate
            UNION ALL
            SELECT   dend ddate, 0 dubl
                FROM calcbyduplication
               WHERE mid = an_dmid AND dend > ad_stdate AND dend < ad_findate
            UNION ALL
            SELECT   ad_findate ddate, 0 dubl
                FROM DUAL
            ORDER BY 1;

-- возвращает даты замены счетчиков
        CURSOR lcur_change_met (an_dmid NUMBER, ad_stdate DATE, ad_findate DATE, an_entype NUMBER)   -- суда суем ИД основного или дублирующего в зависимости от ситуации
        IS
            SELECT   '1' mtrsn, '1' mtype, ad_stdate ddate, 0 ch
                FROM DUAL
            UNION ALL
            SELECT   mtrsn, mtype, dend ddate, 1 ch
                FROM metershistory
               WHERE mid = an_dmid AND dend >= ad_stdate AND dend < ad_findate AND entype IN (an_entype, 7)
            UNION ALL
            SELECT   mtrsn, mtype, ad_findate ddate, 0 ch
                FROM metershistory
               WHERE mid = an_dmid AND entype IN (an_entype, 7) AND date_time <= ad_stdate AND dend >= ad_findate
            UNION ALL
            SELECT   mtrsn, mtype, ad_findate ddate, 0 ch
                FROM meters
               WHERE mid = an_dmid
                 AND entype IN (an_entype, 7)
                 AND NOT EXISTS (SELECT mtrsn, mtype, ad_findate ddate, 0 ch
                                   FROM metershistory
                                  WHERE mid = an_dmid AND entype IN (an_entype, 7) AND date_time <= ad_stdate AND dend >= ad_findate)
            ORDER BY 3;
    BEGIN
        at_cons (1) := 0;
        at_cons (2) := 0;
        at_cons (3) := 0;
        at_cons (4) := 0;
        at_wast (1) := 0;
        at_wast (2) := 0;
        at_wast (3) := 0;
        at_wast (4) := 0;
--  Для зон
-- А
        at_cons (5) := 0;
        at_cons (6) := 0;
        at_cons (7) := 0;
        at_cons (8) := 0;
        at_wast (5) := 0;
        at_wast (6) := 0;
        at_wast (7) := 0;
        at_wast (8) := 0;
-- В
        at_cons (9) := 0;
        at_cons (10) := 0;
        at_cons (11) := 0;
        at_cons (12) := 0;
        at_wast (9) := 0;
        at_wast (10) := 0;
        at_wast (11) := 0;
        at_wast (12) := 0;
-- С
        at_cons (13) := 0;
        at_cons (14) := 0;
        at_cons (15) := 0;
        at_cons (16) := 0;
        at_wast (13) := 0;
        at_wast (14) := 0;
        at_wast (15) := 0;
        at_wast (16) := 0;

        -- ищем ид дублирующего счетчика
        BEGIN
            SELECT f.mid, NAME
              INTO ln_dmid, lv_dname
              FROM feeders f, points p
             WHERE nmainpoint = an_mid AND f.mid = p.mid AND ROWNUM < 2;
        EXCEPTION
            WHEN NO_DATA_FOUND
            THEN
                ln_dmid := 0;
        END;

        SELECT kc
          INTO ln_kc_point
          FROM feeders
         WHERE mid = an_mid;

        FOR lc_ov IN lcur_ov_period (an_mid)   -- делаем цикл по переключениям ОВ
        LOOP
            IF ld_st_ov IS NOT NULL AND ld_fin_ov IS NULL
            THEN
                ld_fin_ov := lc_ov.ddate;

                SELECT kc
                  INTO ln_kc
                  FROM feeders
                 WHERE mid = ln_id_ov;

                IF ln_id_ov <> an_mid   -- т.е. было переключение на ОВ
                THEN
                    IF INSTR (NVL (av_param, ' '), 'априем') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 2, 1)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        -- Общее ---------------------------------------------------------------
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

                        IF an_wasteflag = 1
                        THEN
                            ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference'), 0));
                        ELSE
                            ln_wast := 0;
                        END IF;

                        at_cons (1) := at_cons (1) + ROUND (ln_cons * ln_kc);
                        at_wast (1) := at_wast (1) + ln_wast;

                        INSERT INTO rep_classic
                                    (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                     dif, kc, cons, waste, nall, norder
                                    )
                             VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Общ.', 'А+', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                     ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                    );
                        if an_zone = 1
                        then
                                -- Пик  ---------------------------------------------------------------
                                lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype+6, 0);
                                lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype+6, 0);
                                ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype+6, 0), 0);

                                IF an_wasteflag = 1
                                THEN
                                    ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference', 1), 0));
                                ELSE
                                    ln_wast := 0;
                                END IF;

                                at_cons (5) := at_cons (5) + ROUND (ln_cons * ln_kc);
                                at_wast (5) := at_wast (5) + ln_wast;

                                INSERT INTO rep_classic
                                            (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                             dif, kc, cons, waste, nall, norder
                                            )
                                     VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Пик', 'А+', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                             ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                            );
                                -- ПолуПик ---------------------------------------------------------------
                                lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype+12, 0);
                                lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype+12, 0);
                                ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype+12, 0), 0);

                                IF an_wasteflag = 1
                                THEN
                                    ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference', 2), 0));
                                ELSE
                                    ln_wast := 0;
                                END IF;

                                at_cons (9) := at_cons (9) + ROUND (ln_cons * ln_kc);
                                at_wast (9) := at_wast (9) + ln_wast;

                                INSERT INTO rep_classic
                                            (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                             dif, kc, cons, waste, nall, norder
                                            )
                                     VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Полупик', 'А+', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                             ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                            );
                                -- Ночь ---------------------------------------------------------------
                                lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype+18, 0);
                                lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype+18, 0);
                                ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype+18, 0), 0);

                                IF an_wasteflag = 1
                                THEN
                                    ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference', 3), 0));
                                ELSE
                                    ln_wast := 0;
                                END IF;

                                at_cons (13) := at_cons (13) + ROUND (ln_cons * ln_kc);
                                at_wast (13) := at_wast (13) + ln_wast;

                                INSERT INTO rep_classic
                                            (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                             dif, kc, cons, waste, nall, norder
                                            )
                                     VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Ночь', 'А+', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                             ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                            );

                        END IF;
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'аотдача') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 1, 2)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        -- Общее ---------------------------------------------------------------
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

                        IF an_wasteflag = 1
                        THEN
                            ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference'), 0));
                        ELSE
                            ln_wast := 0;
                        END IF;

                        at_cons (2) := at_cons (2) + ROUND (ln_cons * ln_kc);
                        at_wast (2) := at_wast (2) + ln_wast;

                        INSERT INTO rep_classic
                                    (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                     dif, kc, cons, waste, nall, norder
                                    )
                             VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Общ.', 'А-', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                     ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                    );
                        if an_zone = 1
                        then
                                -- Пик  ---------------------------------------------------------------
                                lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype+6, 0);
                                lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype+6, 0);
                                ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype+6, 0), 0);

                                IF an_wasteflag = 1
                                THEN
                                    ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference', 1), 0));
                                ELSE
                                    ln_wast := 0;
                                END IF;

                                at_cons (6) := at_cons (6) + ROUND (ln_cons * ln_kc);
                                at_wast (6) := at_wast (6) + ln_wast;

                                INSERT INTO rep_classic
                                            (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                             dif, kc, cons, waste, nall, norder
                                            )
                                     VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Пик', 'А-', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                             ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                            );
                                -- ПолуПик ---------------------------------------------------------------
                                lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype+12, 0);
                                lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype+12, 0);
                                ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype+12, 0), 0);

                                IF an_wasteflag = 1
                                THEN
                                    ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference', 2), 0));
                                ELSE
                                    ln_wast := 0;
                                END IF;

                                at_cons (10) := at_cons (10) + ROUND (ln_cons * ln_kc);
                                at_wast (10) := at_wast (10) + ln_wast;

                                INSERT INTO rep_classic
                                            (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                             dif, kc, cons, waste, nall, norder
                                            )
                                     VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Полупик', 'А-', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                             ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                            );
                                -- Ночь ---------------------------------------------------------------
                                lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype+18, 0);
                                lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype+18, 0);
                                ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype+18, 0), 0);

                                IF an_wasteflag = 1
                                THEN
                                    ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference', 3), 0));
                                ELSE
                                    ln_wast := 0;
                                END IF;

                                at_cons (14) := at_cons (14) + ROUND (ln_cons * ln_kc);
                                at_wast (14) := at_wast (14) + ln_wast;

                                INSERT INTO rep_classic
                                            (gid, objtype, nlevel, NAME, zone, etype, mtype, mtrsn, edate, em, sdate, sm,
                                             dif, kc, cons, waste, nall, norder
                                            )
                                     VALUES (an_gid, 1, an_level, lv_curr_ins_name, 'Ночь', 'А-', lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                             ln_cons, ln_kc, ROUND (ln_cons * ln_kc), ln_wast, ROUND (ln_cons * ln_kc) + ln_wast, rep_seq.NEXTVAL
                                            );

                        END IF;
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'рприем') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 5, 3)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        -- Общее ---------------------------------------------------------------
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

