                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (6) := at_cons (6) - at_wast (6);
                    END IF;
               -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Полупик', 'А-', at_wast (10), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (10) := at_cons (10) + at_wast (10);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (10) := at_cons (10) - at_wast (10);
                    END IF;
               -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Ночь', 'А-', at_wast (14), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (14) := at_cons (14) + at_wast (14);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (14) := at_cons (14) - at_wast (14);
                    END IF;
            end if;
        END IF;

        IF INSTR (NVL (av_param, ' '), 'потери_рпр') > 0
        THEN
            -- Общее ---------------------------------------------------------------
            INSERT INTO rep_classic
                        (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                        )
                 VALUES (an_gid, 1, an_level, av_name || ' потери', 'Общ.', 'Р+', at_wast (3), rep_seq.NEXTVAL
                        );

