            IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
            THEN
                at_cons (3) := at_cons (3) - at_wast (3);
            END IF;
            if an_zone = 1
            then
               -- Пик  ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Пик', 'Р+', at_wast (7), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (7) := at_cons (7) + at_wast (7);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (7) := at_cons (7) - at_wast (7);
                    END IF;
               -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Полупик', 'Р+', at_wast (11), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (11) := at_cons (11) + at_wast (11);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (11) := at_cons (11) - at_wast (11);
                    END IF;
               -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Ночь', 'Р+', at_wast (15), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (15) := at_cons (15) + at_wast (15);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (15) := at_cons (15) - at_wast (15);
                    END IF;
            end if;
        END IF;

        IF INSTR (NVL (av_param, ' '), 'потери_рген') > 0
        THEN
            -- Общее ---------------------------------------------------------------
            INSERT INTO rep_classic
                        (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                        )
                 VALUES (an_gid, 1, an_level, av_name || ' потери', 'Общ.', 'Р-', at_wast (4), rep_seq.NEXTVAL
                        );

            IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
            THEN
                at_cons (4) := at_cons (4) + at_wast (4);
            END IF;

            IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
            THEN
                at_cons (4) := at_cons (4) - at_wast (4);
            END IF;
            if an_zone = 1
            then
               -- Пик  ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Пик', 'Р-', at_wast (8), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (8) := at_cons (8) + at_wast (8);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (8) := at_cons (8) - at_wast (8);
                    END IF;
               -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Полупик', 'Р-', at_wast (12), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
                    THEN
                        at_cons (12) := at_cons (12) + at_wast (12);
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'потери_апр-') > 0
                    THEN
                        at_cons (12) := at_cons (12) - at_wast (12);
                    END IF;
               -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                                )
                         VALUES (an_gid, 1, an_level, av_name || ' потери', 'Ночь', 'Р-', at_wast (16), rep_seq.NEXTVAL
                                );

                    IF INSTR (NVL (av_param, ' '), 'потери_апр+') > 0
