--------------------------------------------------------------------------------
    PROCEDURE summ_group (
        an_gid                  NUMBER,
        av_name                 VARCHAR2,
        av_param                VARCHAR2,
        an_mid                  NUMBER,
        av_inverted             VARCHAR2,
        an_level                NUMBER,
        ad_st                   DATE,
        ad_fin                  DATE,
        an_wasteflag            NUMBER,
        at_cons        IN OUT   common_pg.tt_number,
        at_wast        IN OUT   common_pg.tt_number,
        an_zone NUMBER
    )
    IS
        CURSOR lcur_group
        IS
            SELECT   gid, NAME, inverted, mid, vparam
                FROM GROUPS
               WHERE PARENT = an_gid
            ORDER BY vparam;

        lt_cons    common_pg.tt_number;
        lt_wast    common_pg.tt_number;
        ln_saldo   NUMBER;
    BEGIN
        at_cons (1) := 0;
        at_cons (2) := 0;
        at_cons (3) := 0;
        at_cons (4) := 0;
        at_wast (1) := 0;
        at_wast (2) := 0;
        at_wast (3) := 0;
        at_wast (4) := 0;
--  Для зон
-- А
        at_cons (5) := 0;
        at_cons (6) := 0;
        at_cons (7) := 0;
        at_cons (8) := 0;
        at_wast (5) := 0;
        at_wast (6) := 0;
        at_wast (7) := 0;
        at_wast (8) := 0;
-- В
        at_cons (9) := 0;
        at_cons (10) := 0;
        at_cons (11) := 0;
        at_cons (12) := 0;
        at_wast (9) := 0;
        at_wast (10) := 0;
        at_wast (11) := 0;
        at_wast (12) := 0;
-- С
        at_cons (13) := 0;
        at_cons (14) := 0;
        at_cons (15) := 0;
        at_cons (16) := 0;
        at_wast (13) := 0;
        at_wast (14) := 0;
        at_wast (15) := 0;
        at_wast (16) := 0;

        IF an_mid IS NULL
        THEN   -- то есть группа
            INSERT INTO rep_classic
                        (gid, objtype, nlevel, NAME, norder
                        )
                 VALUES (an_gid, 0, an_level, av_name, rep_seq.NEXTVAL
                        );

            FOR lc IN lcur_group
            LOOP
                summ_group (lc.gid, lc.NAME, lc.vparam, lc.mid, lc.inverted, an_level + 1, ad_st, ad_fin, an_wasteflag, lt_cons, lt_wast, an_zone);
            END LOOP;

            IF INSTR (NVL (av_param, ' '), 'априем') > 0
            THEN
                -- Общее ---------------------------------------------------------------
                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                            )
                     VALUES (an_gid, 0, an_level, 'ИТОГО', 'Общ.', 'А+', lt_cons (1), lt_wast (1), lt_cons (1) + lt_wast (1), rep_seq.NEXTVAL
                            );
                if an_zone = 1
                then
                -- Пик  ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Пик', 'А+', lt_cons (5), lt_wast (5), lt_cons (5) + lt_wast (5), rep_seq.NEXTVAL
                                );
                -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Полупик', 'А+', lt_cons (9), lt_wast (9), lt_cons (9) + lt_wast (9), rep_seq.NEXTVAL
                                );
                -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Ночь', 'А+', lt_cons (13), lt_wast (13), lt_cons (13) + lt_wast (13), rep_seq.NEXTVAL
                                );
                end if;
            END IF;

            IF INSTR (NVL (av_param, ' '), 'аотдача') > 0
            THEN
                -- Общее ---------------------------------------------------------------
                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                            )
                     VALUES (an_gid, 0, an_level, 'ИТОГО', 'Общ.', 'А-', lt_cons (2), lt_wast (2), lt_cons (2) + lt_wast (2), rep_seq.NEXTVAL
                            );
                if an_zone = 1
                then
                -- Пик  ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Пик', 'А-', lt_cons (6), lt_wast (6), lt_cons (6) + lt_wast (6), rep_seq.NEXTVAL
                                );
                -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Полупик', 'А-', lt_cons (10), lt_wast (10), lt_cons (10) + lt_wast (10), rep_seq.NEXTVAL
                                );
                -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Ночь', 'А-', lt_cons (14), lt_wast (14), lt_cons (14) + lt_wast (14), rep_seq.NEXTVAL
                                );
                end if;
            END IF;

            IF INSTR (NVL (av_param, ' '), 'рприем') > 0
            THEN
                -- Общее ---------------------------------------------------------------
                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                            )
                     VALUES (an_gid, 0, an_level, 'ИТОГО', 'Общ.', 'Р+', lt_cons (3), lt_wast (3), lt_cons (3) + lt_wast (3), rep_seq.NEXTVAL
                            );
                if an_zone = 1
                then
                -- Пик  ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Пик', 'Р+', lt_cons (7), lt_wast (7), lt_cons (7) + lt_wast (7), rep_seq.NEXTVAL
                                );
                -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Полупик', 'Р+', lt_cons (11), lt_wast (11), lt_cons (11) + lt_wast (11), rep_seq.NEXTVAL
                                );
                -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Ночь', 'Р+', lt_cons (15), lt_wast (15), lt_cons (15) + lt_wast (15), rep_seq.NEXTVAL
                                );
                end if;
            END IF;

            IF INSTR (NVL (av_param, ' '), 'ргенер') > 0
            THEN
                -- Общее ---------------------------------------------------------------
                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                            )
                     VALUES (an_gid, 0, an_level, 'ИТОГО', 'Общ.', 'Р-', lt_cons (4), lt_wast (4), lt_cons (4) + lt_wast (4), rep_seq.NEXTVAL
                            );
                if an_zone = 1
                then
                -- Пик  ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Пик', 'Р-', lt_cons (8), lt_wast (8), lt_cons (8) + lt_wast (8), rep_seq.NEXTVAL
                                );
                -- ПолуПик ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Полупик', 'Р-', lt_cons (12), lt_wast (12), lt_cons (12) + lt_wast (12), rep_seq.NEXTVAL
                                );
                -- Ночь ---------------------------------------------------------------
                    INSERT INTO rep_classic
                                (gid, objtype, nlevel, NAME, zone, etype, cons, waste, nall, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', 'Ночь', 'Р-', lt_cons (16), lt_wast (16), lt_cons (16) + lt_wast (16), rep_seq.NEXTVAL
                                );
                end if;
            END IF;

            IF INSTR (NVL (av_param, ' '), 'асальдо') > 0
            THEN
                -- Общее ---------------------------------------------------------------
                IF INSTR (NVL (av_param, ' '), 'асальдо-') > 0
                THEN
                    ln_saldo := lt_cons (1) - lt_cons (2);
                ELSE
                    ln_saldo := ABS (lt_cons (1) - lt_cons (2));
                END IF;

                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'САЛЬДО', 'Общ.', 'А', ln_saldo, rep_seq.NEXTVAL
                            );
                if an_zone = 1
                then
                -- Пик  ---------------------------------------------------------------
                IF INSTR (NVL (av_param, ' '), 'асальдо-') > 0
                THEN
                    ln_saldo := lt_cons (5) - lt_cons (6);
                ELSE
                    ln_saldo := ABS (lt_cons (5) - lt_cons (6));
                END IF;

                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'САЛЬДО', 'Пик', 'А', ln_saldo, rep_seq.NEXTVAL
                            );
                -- ПолуПик ---------------------------------------------------------------
                IF INSTR (NVL (av_param, ' '), 'асальдо-') > 0
                THEN
                    ln_saldo := lt_cons (9) - lt_cons (10);
                ELSE
                    ln_saldo := ABS (lt_cons (9) - lt_cons (10));
                END IF;

                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'САЛЬДО', 'Полупик', 'А', ln_saldo, rep_seq.NEXTVAL
                            );
                -- Ночь ---------------------------------------------------------------
                IF INSTR (NVL (av_param, ' '), 'асальдо-') > 0
                THEN
                    ln_saldo := lt_cons (13) - lt_cons (14);
                ELSE
                    ln_saldo := ABS (lt_cons (13) - lt_cons (14));
                END IF;

                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, zone, etype, cons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'САЛЬДО', 'Ночь', 'А', ln_saldo, rep_seq.NEXTVAL
                            );
            END IF;
            end if;
        ELSE   -- тоесть точка
            add_point (an_gid, av_name, av_param, an_mid, av_inverted, an_level, ad_st, ad_fin, an_wasteflag, lt_cons, lt_wast, an_zone);
        END IF;

        at_cons (1) := lt_cons (1) + at_cons (1);
        at_cons (2) := lt_cons (2) + at_cons (2);
        at_cons (3) := lt_cons (3) + at_cons (3);
        at_cons (4) := lt_cons (4) + at_cons (4);
        at_wast (1) := lt_wast (1) + at_wast (1);
        at_wast (2) := lt_wast (2) + at_wast (2);
        at_wast (3) := lt_wast (3) + at_wast (3);
        at_wast (4) := lt_wast (4) + at_wast (4);

--  Для зон
-- А
        at_cons (5) := lt_cons (5) + at_cons (5);
        at_cons (6) := lt_cons (6) + at_cons (6);
        at_cons (7) := lt_cons (7) + at_cons (7);
        at_cons (8) := lt_cons (8) + at_cons (8);
        at_wast (5) := lt_wast (5) + at_wast (5);
        at_wast (6) := lt_wast (6) + at_wast (6);
        at_wast (7) := lt_wast (7) + at_wast (7);
        at_wast (8) := lt_wast (8) + at_wast (8);
-- В
        at_cons (9) := lt_cons (9) + at_cons (9);
        at_cons (10) := lt_cons (10) + at_cons (10);
        at_cons (11) := lt_cons (11) + at_cons (11);
        at_cons (12) := lt_cons (12) + at_cons (12);
        at_wast (9) := lt_wast (9) + at_wast (9);
        at_wast (10) := lt_wast (10) + at_wast (10);
        at_wast (11) := lt_wast (11) + at_wast (11);
        at_wast (12) := lt_wast (12) + at_wast (12);
-- С
        at_cons (13) := lt_cons (13) + at_cons (13);
        at_cons (14) := lt_cons (14) + at_cons (14);
        at_cons (15) := lt_cons (15) + at_cons (15);
        at_cons (16) := lt_cons (16) + at_cons (16);
        at_wast (13) := lt_wast (13) + at_wast (13);
        at_wast (14) := lt_wast (14) + at_wast (14);
        at_wast (15) := lt_wast (15) + at_wast (15);
        at_wast (16) := lt_wast (16) + at_wast (16);

    END;

