CREATE OR REPLACE 
PACKAGE BODY reports4_pg IS
------------------------------------------------------------------------------------------------------------------------
   -- пакет по созданию отчетов в файл
   -- дата создания 13/07/2009 Сечин А.А.
   --last edited 11/01/2010 by Kruglova
------------------------------------------------------------------------------------------------------------------------
--Служебный ХАРТЭП
 PROCEDURE report_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS  --макет посуточный
 BEGIN
    mainprocedure(an_maket,ad_date,av_fname,1);
 END;
------------------------------------------------------------------------------------------------------------------------ 
 PROCEDURE reportm_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS --макет помесячный
 BEGIN
    mainprocedure(an_maket,ad_date,av_fname,2);
 END;
------------------------------------------------------------------------------------------------------------------------ 
 PROCEDURE report_mon(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS  --Макет Отчет суточный с нарастающим итогом   
 BEGIN
    mainprocedure(an_maket,ad_date,av_fname,3);
 END;
------------------------------------------------------------------------------------------------------------------------ 
 PROCEDURE mainprocedure (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2, param NUMBER) IS
 an_cnfixcol                NUMBER              DEFAULT 3;
 an_cntitle                 NUMBER              DEFAULT 2;
 an_cnfooter                NUMBER              DEFAULT 1;
 id                         NUMBER;
 titlecl                    NUMBER;
 titleal                    NUMBER;
 datacl                     NUMBER;
 dataal                     NUMBER;
 nlock                      NUMBER;
 nwidth                     NUMBER;
 cnt                        NUMBER;                         --количество колонок
 ndxx                       NUMBER          DEFAULT 0;  --индекс курсора данных data_t
 an_fid                     NUMBER;                         --ид отчетной формы
 an_id                      NUMBER;                         --ид группы или точки
 an_ispoint                 NUMBER;                         --признак выбора по точкам
 an_TimeZone_show           NUMBER          DEFAULT 1;
 an_RateZone_show           NUMBER          DEFAULT 1;
 an_Date_show               NUMBER          DEFAULT 1;
 an_Quality_show           NUMBER          DEFAULT 1;
 
 --запоминаем текущие настройки
 tmp_gn_RateZona            NUMBER          DEFAULT     interior_pg.get_ratezona;            --временная переменная для хранения текущей тарифной зоны
 tmp_gn_TimeZone            NUMBER          DEFAULT     interior_pg.get_gn_timezone;         --временная переменная для хранения текущей временной зоны
 tmp_gn_povercoeff          NUMBER          DEFAULT     interior_pg.get_powercoeff;         -- временная переменная для коэффициента
 
 an_RateZona                NUMBER;                         --временная переменная для задания тарифной зоны
 an_TimeZone                NUMBER;                         --временная переменная для задания временной зоны
 an_povercoeff              NUMBER;
 
 maintitle                  VARCHAR(1000);
 rowtext                    VARCHAR(10000);
 vmasks                     VARCHAR2(32);
 av_string                  VARCHAR2(64)     DEFAULT NULL;
 srt                        NUMBER;
-- temp                       VARCHAR2(200);
 --temp2                      VARCHAR2(200);
 quality                   VARCHAR2 (64);
-- temptitle                  VARCHAR2(1000);
 
 ad_from                    DATE;
 ad_till                    DATE;
 ad_1                       DATE;
 ad_2                       DATE;
 ad_forming_data            DATE;
 col_t                      common_pg.tcur;
 row_t                      common_pg.tcur;
 data_t                     common_pg.tt_number;
 --widthmass                  common_pg.tt_number;
 titlemass                  common_pg.tt_varchar2;
 titlemass_                 common_pg.tt_varchar2;

 BEGIN
  
  IF param = 1 THEN       --посуточного макета
    ad_1 := trunc (ad_date);
    ad_2 := ad_1 + 1;
  ELSIF param = 2 THEN    --помесячного макета
    ad_1 := trunc(trunc(ad_date,'MON'));
    ad_2 := trunc(last_day(ad_1) + 1);
  ELSIF param = 3 THEN 
    ad_1 := trunc(trunc(ad_date,'MON')); --Макет Отчет суточный с нарастающим итогом
    ad_2 := trunc(ad_date + 1);
   -- ad_2 := trunc(ad_date);
  END IF;
  ad_from := ad_1;
  ad_till := ad_2;
  titlemass.DELETE;  
  ndxx := 0;
  file_pg.out_p ('Отчет за:' || TO_CHAR (ad_date, 'DD/MM/YYYY HH24:MI'));   
 
 --выбор параметров макета
  SELECT 
  nvl (util_pg.get_param (vparam,1,';'),1),  --часовой пояс - по умолч 1(Украина) из табл TimeZones
  nvl (util_pg.get_param (vparam,2,';'),1),  --тарифная зона - по умолч 1 из табл Schedulelist
  nvl (util_pg.get_param (vparam,3,';'),0),  --ид отч формы 
  nvl (util_pg.get_param (vparam,4,';'),0),  --ид группы/точки
  nvl (util_pg.get_param (vparam,5,';'),0),  --признак выбора по точкам
  nvl (util_pg.get_param (vparam,6,';'),1),  --вывод часового пояса
  nvl (util_pg.get_param (vparam,7,';'),1),  --вывод тарифной зоны
