  interior_pg.set_timezone(an_TimeZone);
  interior_pg.set_ratezona(an_RateZona);
  IF (an_povercoeff>0)THEN
    interior_pg.set_powercoeff(an_povercoeff);
  END IF;

  IF an_cntitle=1 THEN
    LOOP
     FETCH col_t INTO id, titlemass(cnt+an_cnfixcol+1), titlecl, titleal, datacl, dataal, nlock, nwidth, vmasks;           
      EXIT WHEN col_t%NOTFOUND; 
     rowtext:=rowtext||titlemass(cnt + an_cnfixcol + 1) || chr(9);
     cnt:=cnt+1;
     --widthmass(cnt):=nwidth;
    END LOOP;

  ELSIF an_cntitle=2 THEN
    LOOP    
      FETCH col_t INTO id, titlemass((cnt+an_cnfixcol)*2+1),  titlemass((cnt+an_cnfixcol)*2+2), titlecl, titleal, datacl, dataal, nlock, nwidth, vmasks;           
      EXIT WHEN col_t%NOTFOUND; 
