      cnt:=cnt+1;
      --widthmass(cnt):=nwidth;
    END LOOP;

  ELSIF an_cntitle=3 THEN
    LOOP    
      FETCH col_t INTO id,  titlemass((cnt+an_cnfixcol)*3+1),  titlemass((cnt+an_cnfixcol)*3+2),  titlemass((cnt+an_cnfixcol)*3+3), titlecl, titleal, datacl, dataal, nlock, nwidth, vmasks;           
      EXIT WHEN col_t%NOTFOUND; 
       rowtext := rowtext||titlemass((cnt+an_cnfixcol)*3+1) ||'|'|| titlemass((cnt+an_cnfixcol)*3+2)||'|'||titlemass((cnt+an_cnfixcol)*3+3)||chr(9);
