    END LOOP;
  END IF;

  --widthmass(0):=47;
 -- temp:=' ';
 -- temp2:=' '; 
  titlemass_.DELETE;
  
  FOR i IN 1.. an_cntitle LOOP
   titlemass_(i):=titlemass(i);
