   ELSE
    IF titlemass(i)=titlemass(i-an_cntitle) AND titlemass(i-1)=titlemass(i-an_cntitle-1) 
    THEN
        titlemass_(i):='';
    ELSE
        titlemass_(i):=titlemass(i);
    END IF;
   END IF;
  END LOOP;
   
  --file_pg.out_p (rowtext);
--------*********************************************************---------- 

--вызов ф-ции getmaketvalue
--т.к. в getmaketinfo параметры ad_from, ad_till - возвращаемые, то они изменены, поэтому переприсваиваем значения
 ad_from := ad_1; 
 ad_till := ad_2;--TO_DATE('14-июл-2009 14:16', 'DD-MM-YYYY HH24:MI');--TO_DATE('12-июл-2009 02:30', 'DD-MM-YYYY HH24:MI');
 
 data_t.DELETE;
 titlemass.DELETE;
 rowtext:='';

 UNIINTERIOR_PG.getmaketvalue(an_fid, an_ispoint, an_id, ad_from, ad_till, data_t, quality, ad_forming_data);
 
 IF an_TimeZone_show > 0 
