    FOR i IN 1 .. (cnt + an_cnfixcol) LOOP 
       maintitle := maintitle||nvl(titlemass_ (j + (an_cntitle * (i - 1))),'')||chr(9);
   END LOOP;
   file_pg.out_p (maintitle);
  END LOOP;
 IF an_cnfixcol = 1 THEN  
    LOOP
      FETCH row_t INTO id, titlemass(1), datacl, nlock, vmasks, srt;
      EXIT WHEN row_t % NOTFOUND; 
      IF data_t.count > 0 THEN
          FOR i IN 1..cnt LOOP
          rowtext:=rowtext||chr(9)||nvl(TO_CHAR (data_t(ndxx+i),'fm99999999999990.0009999999999999'),'');
          -- rowtext:=concat(rowtext,rpad(nvl(TO_CHAR (data_t(ndxx+i),'fm99990.000999'),' '),widthmass(i)/2.3333333333));
          END LOOP;
