           rowtext:=rowtext||chr(9)||nvl(TO_CHAR (data_t(ndxx+i),'fm99999999999990.0009999999999999'),'');
           --rowtext:=concat(rowtext,rpad(nvl(TO_CHAR (data_t(ndxx+i),'fm99990.000999'),' '),widthmass(i)/2.3333333333));
          END LOOP;
      END IF;
