           rowtext:=rowtext||chr(9)||nvl(TO_CHAR (data_t(ndxx+i),'fm99999999999990.0009999999999999'),'');
           --rowtext:=concat(rowtext,rpad(nvl(TO_CHAR (data_t(ndxx+i),'fm99990.000999'),' '),widthmass(i)/2.3333333333));
          END LOOP;
      END IF;
    file_pg.out_p (titlemass(1)||chr(9)||titlemass(2)||chr(9)||titlemass(3)||chr(9)||titlemass(4)||rowtext);
    --file_pg.out_p (rpad(nvl(titlemass(1),' '),widthmass(0-an_cnfixcol+1)/2.3333333333)||rpad(nvl(titlemass(2),' '),widthmass(0-an_cnfixcol+2)/2.3333333333)||rpad(nvl(titlemass(3),' '),widthmass(0-an_cnfixcol+3)/2.3333333333)||rpad(nvl(titlemass(4),' '),widthmass(0-an_cnfixcol+4)/2.3333333333)||'       '||rowtext);
