    file_pg.out_p (titlemass(1)||chr(9)||titlemass(2)||chr(9)||titlemass(3)||chr(9)||titlemass(4)||chr(9)||titlemass(5)||rowtext);
    --file_pg.out_p (rpad(nvl(titlemass(1),' '),widthmass(0-an_cnfixcol+1)/2.3333333333)||rpad(nvl(titlemass(2),' '),widthmass(0-an_cnfixcol+2)/2.3333333333)||rpad(nvl(titlemass(3),' '),widthmass(0-an_cnfixcol+3)/2.3333333333)||rpad(nvl(titlemass(4),' '),widthmass(0-an_cnfixcol+4)/2.3333333333)||rpad(nvl(titlemass(5),' '),widthmass(0-an_cnfixcol+5)/2.3333333333)||'       '||rowtext);
    rowtext:='';
    ndxx:=ndxx+cnt;
    END LOOP;
