    --возврат к старым значениям глобальных переменных
    interior_pg.set_timezone(tmp_gn_TimeZone);
    interior_pg.set_ratezona(tmp_gn_RateZona);
    interior_pg.set_powercoeff(tmp_gn_povercoeff);
