-- Start of DDL Script for Package Body RYDA.REPORTS5_PG
-- Generated 14.04.2014 9:35:00 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY reports5_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- пакет по созданию отчетов в файл
   -- дата создания 27/07/2002 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 -- функция разбора метки качества, возвращает для заданного бита метку соответствующего типа
 -- Kondakov A.G. 24.11.2008, Semeniuk A.D. 17.05.2010
 FUNCTION get_vqm (av_vqm VARCHAR2, an_bit NUMBER)
  RETURN VARCHAR2;

------------------------------------------------------------------------------------------------------------------------
--Макет mRDF
 PROCEDURE mrdf_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_g IS
   SELECT   ngroup, vcode
       FROM maketgroups
      WHERE nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p (lc_group NUMBER) IS
   SELECT mid, nkc, ntype
     FROM maketpoints
    WHERE ngroup = lc_group;

  CURSOR lcur_h (lc_p NUMBER) IS
   SELECT TO_CHAR (util_pg.to_unlocaltime (date_time, nsource), 'dd.mm.yyyy hh24:mi:ss') dt, er er, ed ed, q1 q1, q3 q3, vqm
     FROM halfhour
    WHERE mid = lc_p AND date_time > TRUNC (ad_date) AND date_time <= TRUNC (ad_date) + 1 order by util_pg.to_localtime (date_time, nsource);

  ln_cnt        NUMBER                DEFAULT 0;   -- число записей
  lv_tmp        common_pg.tt_varchar2;
  lv_meastype   common_pg.tt_varchar2;   --идентификаторы типов измерений
  lv_measunit   common_pg.tt_varchar2;   --идентификаторы единиц измерений
  ln_orgmid     NUMBER;   --идентификатор организации
  lv_orgname    VARCHAR2 (1000);   --Название организации
  lv_orgmrid    VARCHAR2 (1000);   --mRid организации
  ln_orgcode    NUMBER;   --код организации
  lv_anname     VARCHAR2 (1000);   --название текущего макета
  lc_temp       CHAR;
  ln_has_er     NUMBER;
  ln_has_ed     NUMBER;
  ln_has_q1     NUMBER;
  ln_has_q3     NUMBER;
  ln_has_wh     NUMBER;
  ln_has_var    NUMBER;
  lv_customer1  VARCHAR2(100);
  lv_customer2 VARCHAR2(100);

-----
  CURSOR maketgroups_cur IS
   SELECT vname
     FROM maketgroups
    WHERE nmaket = an_maket;
-----
 BEGIN
  SELECT mid
    INTO ln_orgmid
    FROM enterprise;

  lv_orgmrid := '';

  SELECT CASE
          WHEN EXISTS (SELECT 1
                         FROM mrids
                        WHERE mid = ln_orgmid) THEN '1'
          ELSE '0'
         END
    INTO lc_temp
    FROM DUAL;

  IF lc_temp = '1' THEN
   SELECT mrid
     INTO lv_orgmrid
     FROM mrids
    WHERE mid = ln_orgmid;
  END IF;

  SELECT p.NAME
    INTO lv_orgname
    FROM points p
   WHERE p.mid = ln_orgmid;

  SELECT cod
    INTO ln_orgcode
    FROM enterprise;

  IF lv_orgmrid IS NULL THEN
   lv_orgmrid := '';
  END IF;

  select decode(util_pg.get_customer_id,
                41,'Центральної',
                42,'Північної',
                43,'Західної',
                44,'Донбаської',
                45,'Дніпровської',
                ''
                ),
         decode(util_pg.get_customer_id,
                41,'CntrES_registry',
                42,'PivES_registry',
                43,'ZahES_registry',
                44,'DonES_registry',
                45,'DnES_registry',
                ''
                )
         into lv_customer1, lv_customer2 from dual;
    
  lv_tmp (1) := 'AP';
  lv_tmp (2) := 'AM';
  lv_tmp (3) := 'RP';
  lv_tmp (4) := 'RM';
  lv_meastype (1) := '#MEASTYPE_TotWh';
  lv_meastype (2) := '#MEASTYPE_TotVArh';
  lv_measunit (1) := '#UNIT_kWh';
  lv_measunit (2) := '#UNIT_kVArh';
  ln_has_wh := 0;
  ln_has_var := 0;
  file_pg.out_p ('<?xml version="1.0" encoding="UTF-8" standalone="no"?>');
  file_pg.out_p ('<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#" xmlns:cim="http://iec.ch/TC57/2007/CIM-schema-cim12#">');
  -- DataSet start
  file_pg.out_p ('');
  file_pg.out_p ('  <!-- data sets -->');
  file_pg.out_p ('  <cim:DataSet rdf:ID="' || lv_customer2 || '">');
  file_pg.out_p ('    <cim:IdentifiedObject.name>' || lv_customer2 || '</cim:IdentifiedObject.name>');
  file_pg.out_p ('    <cim:Document.docType>' || 'ReportedEnergyDelivery' || '</cim:Document.docType>');
  file_pg.out_p ('    <cim:Document.lastModified>' || TO_CHAR (SYSDATE, 'dd.mm.yyyy hh24:mi:ss') || '</cim:Document.lastModified>');
  file_pg.out_p ('    <cim:Document.docStatus>' || 'approved' || '</cim:Document.docStatus>');
  file_pg.out_p ('    <cim:Document.subject>' || 'Registry_data' || '</cim:Document.subject>');
  file_pg.out_p ('    <cim:Document.docTitle>' || 'Реєстр '||lv_customer1||' електроенергетичної системи' || '</cim:Document.docTitle>');
  file_pg.out_p ('    <cim:Document.Organisations rdf:resource="#' || 'Organization_' || ln_orgcode || '"/>');

  FOR lc_g IN lcur_g LOOP
   FOR lc_p IN lcur_p (lc_g.ngroup) LOOP
    SELECT NAME
      INTO lv_anname
      FROM points
     WHERE mid = lc_p.mid;

    ln_has_er := 0;
    ln_has_ed := 0;
    ln_has_q1 := 0;
    ln_has_q3 := 0;

    FOR lc_h IN lcur_h (lc_p.mid) LOOP
     IF NOT lc_h.er IS NULL THEN
      ln_has_er := 1;
     END IF;

     IF NOT lc_h.ed IS NULL THEN
      ln_has_ed := 1;
     END IF;

     IF NOT lc_h.q1 IS NULL THEN
      ln_has_q1 := 1;
     END IF;

     IF NOT lc_h.q3 IS NULL THEN
      ln_has_q3 := 1;
     END IF;
    END LOOP;

    IF ln_has_er = 1 THEN
     ln_has_wh := 1;
     file_pg.out_p ('    <cim:Document.Measurements rdf:resource="#' || lv_tmp (1) || '_d' || lc_p.mid || '"/> <!-- ' || lv_anname || ' -->');
    END IF;

    IF ln_has_ed = 1 THEN
     ln_has_wh := 1;
     file_pg.out_p ('    <cim:Document.Measurements rdf:resource="#' || lv_tmp (2) || '_d' || lc_p.mid || '"/> <!-- ' || lv_anname || ' -->');
    END IF;

    IF ln_has_q1 = 1 THEN
     ln_has_var := 1;
     file_pg.out_p ('    <cim:Document.Measurements rdf:resource="#' || lv_tmp (3) || '_d' || lc_p.mid || '"/> <!-- ' || lv_anname || ' -->');
    END IF;

    IF ln_has_q3 = 1 THEN
     ln_has_var := 1;
     file_pg.out_p ('    <cim:Document.Measurements rdf:resource="#' || lv_tmp (4) || '_d' || lc_p.mid || '"/> <!-- ' || lv_anname || ' -->');
    END IF;
   END LOOP;
  END LOOP;

  file_pg.out_p ('  </cim:DataSet>');
  -- DataSet end

  -- Organization start
  file_pg.out_p ('');
  file_pg.out_p ('  <!-- organizations -->');
  file_pg.out_p ('  <cim:Organization rdf:ID="' || 'Organization_' || ln_orgcode || '">');
  file_pg.out_p ('    <cim:IdentifiedObject.name>' || lv_orgname || '</cim:IdentifiedObject.name>');
  file_pg.out_p ('    <cim:IdentifiedObject.mRID>' || lv_orgmrid || '</cim:IdentifiedObject.mRID>');
  file_pg.out_p ('    <cim:Organization.organisationCode>' || ln_orgcode || '</cim:Organization.organisationCode>');
  file_pg.out_p ('    <cim:Organization.organisationType>' || 'EnergySystem' || '</cim:Organization.organisationType>');
  file_pg.out_p ('    <cim:Organization.marketRole>' || 'Transmission Operator' || '</cim:Organization.marketRole>');
  file_pg.out_p ('  </cim:Organization>');

  -- Organization end
  FOR lc_g IN lcur_g LOOP
   FOR lc_p IN lcur_p (lc_g.ngroup) LOOP
    SELECT NAME
      INTO lv_anname
      FROM points
     WHERE mid = lc_p.mid;

    lv_tmp (5) := NULL;
    lv_tmp (6) := NULL;
    lv_tmp (7) := NULL;
    lv_tmp (8) := NULL;

    FOR lc_m IN (SELECT mrid, nmeasure
                   FROM mrids
                  WHERE mid = lc_p.mid AND nmeasure IN (1, 2, 3, 5)) LOOP
     IF lc_m.nmeasure = 1 THEN
      lv_tmp (5) := lc_m.mrid;
     ELSIF lc_m.nmeasure = 2 THEN
      lv_tmp (6) := lc_m.mrid;
     ELSIF lc_m.nmeasure = 3 THEN
      lv_tmp (7) := lc_m.mrid;
     ELSIF lc_m.nmeasure = 5 THEN
