 -- функция разбора метки качества, возвращает для заданного бита метку соответствующего типа
 -- Kondakov A.G. 24.11.2008
 FUNCTION get_vqm (av_vqm VARCHAR2, an_bit NUMBER)
  RETURN VARCHAR2 IS
  lv_res    VARCHAR2 (100);
  ln_type   NUMBER;
  lv_bit    VARCHAR2 (1);
 BEGIN
  IF av_vqm IS NULL THEN
   RETURN 'NO VQM';
  END IF;

  lv_bit := qm_pg.gbt (av_vqm, an_bit);

  IF an_bit = 1 THEN   -- Тип Validity
   SELECT DECODE (lv_bit, '0', 'good', '1', 'invalid', '2', 'reserved', '3', 'questionable', 'UNDEFINED VALUE BIT')
     INTO lv_res
     FROM DUAL;
  ELSIF an_bit BETWEEN 2 AND 9 OR an_bit IN (11, 12) THEN   -- Тип Boolean
   SELECT DECODE (lv_bit, '0', 'false', '1', 'true', 'UNDEFINED VALUE BIT')
     INTO lv_res
     FROM DUAL;
  ELSIF an_bit = 10 THEN   -- Тип Source
   SELECT DECODE (lv_bit, '0', 'process', '1', 'substituted', 'UNDEFINED VALUE BIT')
     INTO lv_res
     FROM DUAL;
  ELSIF an_bit BETWEEN 13 AND 21 THEN   -- Тип StageResult
   SELECT DECODE (lv_bit, '0', 'Default', '1', 'NoData', '2', 'OK', '3', 'Error', 'UNDEFINED VALUE BIT')
     INTO lv_res
     FROM DUAL;
  ELSIF an_bit = 22 THEN   -- Тип Source
   SELECT DECODE (lv_bit,
                  '0', 'noData',
                  '1', 'Primary',
                  '2', 'Secondary',
                  '3', 'SCADA',
                  '4', 'Manual',
                  '5', 'Layout',
                  '6', 'Bypass',
                  '7', 'Calculated',
                  'UNDEFINED VALUE BIT'
                 )
     INTO lv_res
     FROM DUAL;
  ELSE
   lv_res := 'UNDEFINED NUMBER BIT';
  END IF;

  RETURN lv_res;
 END;
------------------------------------------------------------------------------------------------------------------------
