 --Макет ГН
 PROCEDURE mhour_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  ld_date             DATE DEFAULT TRUNC(ad_date);
  cn_step    CONSTANT NUMBER := 1 / 48;                                                                                                            --:= CHR(9);
  lv_str              VARCHAR2(4000);
  lv_er               VARCHAR2(3000);
  lv_ed               VARCHAR2(3000);
  lv_q1               VARCHAR2(3000);
  lv_q3               VARCHAR2(3000);
  lv_st               VARCHAR2(3000);
  lv_tmp              VARCHAR2(3000);
  ln_cod              NUMBER;
 BEGIN
  SELECT TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi:ss') || '    ' || p.NAME, e.cod
  INTO   lv_str, ln_cod
  FROM   enterprise e, points p
  WHERE  e.mid = p.mid;

  file_pg.out_p(lv_str);
  file_pg.out_p('');

  FOR lv IN (SELECT   f.mid, TO_CHAR(ln_cod) || f.vcode cod
             FROM     maketgroups g, maketpoints m, feeders f
             WHERE    g.nmaket = an_maket AND g.ngroup = m.ngroup AND m.mid = f.mid
             ORDER BY f.vcode, f.mid) LOOP
   lv_er := '';
   lv_ed := '';
   lv_q1 := '';
   lv_q3 := '';
   lv_st := '';

   FOR ld IN (SELECT er, ed, q1, q3, nsource
              FROM   (SELECT   util_pg.get_num_dt(date_time - 1 / 86400, nsource, cn_step) num, SUM(b.er) er, SUM(b.ed) ed,
                               util_pg.sumn(SUM(b.q1), SUM(b.q2)) q1, util_pg.sumn(SUM(b.q3), SUM(b.q4)) q3, MAX(nsource) nsource
                      FROM     halfhour b
                      WHERE    mid = lv.mid AND b.date_time > ld_date AND b.date_time <= ld_date + 1
                      GROUP BY util_pg.get_num_dt(date_time - 1 / 86400, nsource, cn_step)) v,
                     (SELECT ROWNUM num
                      FROM   dict
                      WHERE  ROWNUM <= util_pg.get_count_dt(ld_date, cn_step)) d
              WHERE  d.num = v.num(+)) LOOP
    lv_er := lv_er || ROUND(ld.er / 1000, 3) || ',';
    lv_ed := lv_ed || ROUND(ld.ed / 1000, 3) || ',';
    lv_q1 := lv_q1 || ROUND(ld.q1 / 1000, 3) || ',';
    lv_q3 := lv_q3 || ROUND(ld.q3 / 1000, 3) || ',';

    IF ld.er IS NOT NULL AND ld.nsource >= 50 AND ld.nsource < 60 THEN
     lv_tmp := 'm';
    ELSIF ld.er IS NOT NULL AND ld.nsource >= 30 AND ld.nsource < 50 THEN
     lv_tmp := 'r';
    ELSIF ld.er IS NOT NULL AND ld.nsource >= 10 AND ld.nsource < 30 THEN
     lv_tmp := ' ';
    ELSE
     lv_tmp := '';
    END IF;

    lv_st := lv_st || lv_tmp || ',';
   END LOOP;

   lv_er := SUBSTR(lv_er, 1, LENGTH(lv_er) - 1);
   lv_ed := SUBSTR(lv_ed, 1, LENGTH(lv_ed) - 1);
   lv_q1 := SUBSTR(lv_q1, 1, LENGTH(lv_q1) - 1);
   lv_q3 := SUBSTR(lv_q3, 1, LENGTH(lv_q3) - 1);
   lv_st := SUBSTR(lv_st, 1, LENGTH(lv_st) - 1);
   file_pg.out_p('<REC=POINT; ID=' || lv.cod || '01; TIME=-1; LTIME=1;>');
   file_pg.out_p('<REC=DAY; DATE=' || TO_CHAR(ld_date, 'yymmdd') || '; E48=' || lv_er || '; ST48=' || lv_st || ';>');
   file_pg.out_p('<REC=POINT; ID=' || lv.cod || '02; TIME=-1; LTIME=1;>');
   file_pg.out_p('<REC=DAY; DATE=' || TO_CHAR(ld_date, 'yymmdd') || '; E48=' || lv_ed || '; ST48=' || lv_st || ';>');
   file_pg.out_p('<REC=POINT; ID=' || lv.cod || '03; TIME=-1; LTIME=1;>');
   file_pg.out_p('<REC=DAY; DATE=' || TO_CHAR(ld_date, 'yymmdd') || '; E48=' || lv_q1 || '; ST48=' || lv_st || ';>');
   file_pg.out_p('<REC=POINT; ID=' || lv.cod || '04; TIME=-1; LTIME=1;>');
   file_pg.out_p('<REC=DAY; DATE=' || TO_CHAR(ld_date, 'yymmdd') || '; E48=' || lv_q3 || '; ST48=' || lv_st || ';>');
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 20020 с показаниями
 PROCEDURE m20020_p(an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cn_round   CONSTANT NUMBER := 3;
  ld_date             DATE DEFAULT TRUNC(ad_date);
  lt_ras              common_pg.tt_number;
  ld_tmp              DATE;
  ln_cod              NUMBER;
  lv_psname           VARCHAR2(4000);
  ln_euro             NUMBER;                                                                            -- признак счетчика отпараметрированого по Европе (=1)

  CURSOR lcur1(lc_mid NUMBER, lc_date DATE) IS
   SELECT date_time, erm, edm, q1m, q3m
   FROM   monthsorg
   WHERE  mid = lc_mid AND date_time = lc_date AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL)
   UNION ALL
   SELECT date_time, erm, edm, q1m, q3m
   FROM   billorg
   WHERE  mid = lc_mid
          AND date_time =
              (SELECT MIN(date_time)
               FROM   billorg
               WHERE  mid = lc_mid AND date_time >= lc_date AND date_time < lc_date + 1
                      AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL))
          AND date_time >= lc_date AND date_time < lc_date + 1 AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL);

  CURSOR lcur2(lc_mid NUMBER, lc_date DATE) IS
   SELECT erm, edm, q1m, q3m
   FROM   halfhour
   WHERE  mid = lc_mid AND date_time = lc_date AND(erm IS NOT NULL OR edm IS NOT NULL OR q1m IS NOT NULL OR q3m IS NOT NULL);
 BEGIN
  SELECT p.NAME, e.cod
  INTO   lv_psname, ln_cod
  FROM   enterprise e, points p
  WHERE  e.mid = p.mid;

  file_pg.out_p('((//20020;' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi:ss') || ';' || TO_CHAR(ln_cod) || ';++Ежесуточные показания ' || lv_psname);

  FOR lc IN (SELECT   f.mid, ln_cod || f.vcode cod
             FROM     maketgroups g, maketpoints m, feeders f
             WHERE    g.nmaket = an_maket AND g.ngroup = m.ngroup AND m.mid = f.mid
             ORDER BY f.vcode, f.mid) LOOP
   FOR i IN 1 .. 8 LOOP
    lt_ras(i) := NULL;
   END LOOP;

   -- проверяем счетчик
   SELECT COUNT(*)
   INTO   ln_euro
   FROM   DUAL
   WHERE  EXISTS(SELECT *
                 FROM   feeders
                 WHERE  mid = lc.mid AND ntimezonew = 1 AND ntimezones = 1);

   FOR i IN 1 .. 2 LOOP
    ld_tmp := NULL;

    FOR lc_r IN lcur1(lc.mid, ld_date + i - 1) LOOP                                                                                --Заполняем временный массив
     ld_tmp := lc_r.date_time;
     lt_ras(0 + i) := lc_r.erm;
     lt_ras(2 + i) := lc_r.edm;
     lt_ras(4 + i) := lc_r.q1m;
     lt_ras(6 + i) := lc_r.q3m;
     EXIT;
    END LOOP;

    IF ld_tmp IS NULL OR ld_tmp <> TRUNC(ld_tmp) THEN                                                                                                    --По ГН
     IF ln_euro = 0 THEN
      FOR lc_r IN lcur2(lc.mid, ld_date + i - 1) LOOP                                                                              --Заполняем временный массив
       lt_ras(0 + i) := NVL(lc_r.erm, lt_ras(0 + i));
       lt_ras(2 + i) := NVL(lc_r.edm, lt_ras(2 + i));
       lt_ras(4 + i) := NVL(lc_r.q1m, lt_ras(4 + i));
       lt_ras(6 + i) := NVL(lc_r.q3m, lt_ras(6 + i));
       EXIT;
      END LOOP;
     ELSE
      -- добавлен расчет показаний на 00:00 по ГН, если суточное показание не на 00:00 (только для европейских счетчиков)
      ld_tmp := NVL(TRUNC(ld_tmp), ld_date + i - 1);
      lt_ras(0 + i) := util_pg.get_meterage_vch2(lc.mid, ld_tmp, 1, 0);
      lt_ras(2 + i) := util_pg.get_meterage_vch2(lc.mid, ld_tmp, 2, 0);
      lt_ras(4 + i) := util_pg.get_meterage_vch2(lc.mid, ld_tmp, 3, 0);
      lt_ras(6 + i) := util_pg.get_meterage_vch2(lc.mid, ld_tmp, 5, 0);
     END IF;
    END IF;
   END LOOP;

   FOR i IN 1 .. 4 LOOP
    file_pg.out_p('<' || lc.cod || '0' || i || ';' || ROUND(lt_ras(2 * i - 1), cn_round) || ';' || ROUND(lt_ras(2 * i), cn_round) || ';10;' || '>');
   END LOOP;
  END LOOP;

  file_pg.out_p('==))');
 END;

