 --Макет 20031 окончания работы обходного
 PROCEDURE m20031_p(an_id NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  CURSOR lcur_sel IS
   SELECT s.mid, s.nswitch, s.dswitch, pa.NAME, util_pg.get_point_code(s.mid, 1, 0) midcode, util_pg.get_point_code(s.nswitch, 1, 0) switchcode,
          NVL(s.erme, util_pg.get_meterage(s.nswitch, s.dswitch, 1)) erm, NVL(s.edme, util_pg.get_meterage(s.nswitch, s.dswitch, 2)) edm,
          NVL(s.q1me, util_pg.get_meterage(s.nswitch, s.dswitch, 3)) q1m, NVL(s.q3me, util_pg.get_meterage(s.nswitch, s.dswitch, 5)) q3m
   FROM   switches s, points p, points pa
   WHERE  s.ID = an_id AND s.nswitch = p.mid(+) AND p.PARENT = pa.mid(+);

  lc                  lcur_sel%ROWTYPE;
  lb_found            BOOLEAN;
  lv_cod              VARCHAR2(256);
 BEGIN
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  lc;

  lb_found := lcur_sel%FOUND;

  CLOSE lcur_sel;

  SELECT MAX(mid), util_pg.get_point_code(MAX(mid), 1, 0)
  INTO   lc.mid, lc.midcode
  FROM   switches
  WHERE  nswitch = lc.nswitch AND dswitch = (SELECT MAX(dswitch)
                                             FROM   switches
                                             WHERE  nswitch = lc.nswitch AND dswitch = lc.dswitch AND mid IS NOT NULL);

  IF NOT lb_found OR lc.mid IS NULL OR lc.nswitch IS NULL OR(lc.erm IS NULL AND lc.edm IS NULL AND lc.q1m IS NULL AND lc.q3m IS NULL) THEN
   RETURN;
  END IF;

  file_pg.out_p('((//20031;' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss') || ';' || util_pg.enterprise_char_f || ';++Окончание работы обходного учета '
   || lc.NAME);

  IF lc.erm IS NOT NULL THEN
   file_pg.out_p('<' || lc.midcode || '01;' || lc.switchcode || '01;' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') || ';' || SUBSTR(TO_CHAR(lc.erm, cv_12_3), 2)
    || ';>');
  END IF;

  IF lc.edm IS NOT NULL THEN
   file_pg.out_p('<' || lc.midcode || '02;' || lc.switchcode || '02;' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') || ';' || SUBSTR(TO_CHAR(lc.edm, cv_12_3), 2)
    || ';>');
  END IF;

  IF lc.q1m IS NOT NULL THEN
   file_pg.out_p('<' || lc.midcode || '03;' || lc.switchcode || '03;' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') || ';' || SUBSTR(TO_CHAR(lc.q1m, cv_12_3), 2)
    || ';>');
  END IF;

  IF lc.q3m IS NOT NULL THEN
   file_pg.out_p('<' || lc.midcode || '04;' || lc.switchcode || '04;' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') || ';' || SUBSTR(TO_CHAR(lc.q3m, cv_12_3), 2)
    || ';>');
  END IF;

  file_pg.out_p('==))');
 END;

