 --Макет 20040 замены счетчика
 PROCEDURE m20040_p(an_id NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cv_mask1   CONSTANT VARCHAR2(256) := '000.000000';
  cv_duration CONSTANT VARCHAR2(256) := '30';
  ln_parent           NUMBER;
  lv_kc               VARCHAR2(256);
  lv_cod              VARCHAR2(256);
  lv_add              VARCHAR2(256);
 BEGIN
  SELECT MAX(p.PARENT), SUBSTR(TO_CHAR(MAX(f.kc), cv_12_3), 2)
  INTO   ln_parent, lv_kc
  FROM   points p, feeders f
  WHERE  p.mid = an_id AND p.mid = f.mid AND EXISTS(SELECT *
                                                    FROM   meters
                                                    WHERE  mid = an_id);

  IF ln_parent IS NULL THEN
   RETURN;
  END IF;

  file_pg.out_p('((//20040;' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss') || ';' || util_pg.enterprise_char_f || ';++Замена счетчика '
   || util_pg.get_pointname(ln_parent, 0, 0));
  lv_cod := util_pg.get_point_code(an_id, 1, 0);

  FOR lc IN (SELECT   mtrsn, entype, digits, mtype, mcurrent, mpower, mconst, mclass, mquarter, myear
             FROM     meters m
             WHERE    m.mid = an_id AND entype NOT IN(4, 6)
             ORDER BY DECODE(entype, 7, 1, 2), entype) LOOP
   IF lc.entype = 7 THEN
    FOR i IN 1 .. 4 LOOP
     SELECT SUBSTR(TO_CHAR(NVL(SUM(DECODE(i, 1, er, 2, ed, 3, NVL(q1, 0) + NVL(q2, 0), 4, NVL(q3, 0) + NVL(q4, 0))), 0), cv_12_3), 2)
     INTO   lv_add
     FROM   billorg
     WHERE  mid = an_id AND date_time = ad_date AND nsource = 8;

     file_pg.out_p('<'
      || lv_cod
      || '0'
      || i
      || ';'
      || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi')
      || ';'
      || cv_duration
      || ';'
      || SUBSTR(TO_CHAR(util_pg.get_meterage(an_id, ad_date, REPLACE(i, '4', '5'), 0, NULL), cv_12_3), 2)
      || ';'
      || SUBSTR(TO_CHAR(util_pg.get_meterage(an_id, ad_date, REPLACE(i, '4', '5'), 1, NULL), cv_12_3), 2)
      || ';'
      || LPAD(lc.mtrsn, 20)
      || ';'
      || LPAD(LENGTH(TRUNC(lc.digits)), 1)
      || ';'
      || LPAD(lc.mtype, 50)
      || ';'
      || lc.mcurrent
      || ';'
      || lc.mpower
      || ';'
      || lc.mconst
      || ';'
      || SUBSTR(TO_CHAR(lc.mclass, cv_mask1), 2)
      || ';'
      || SUBSTR(TO_CHAR(lc.mclass, cv_mask1), 2)
      || ';'
      || lc.mquarter
      || ';'
      || lc.myear
      || ';'
      || lv_kc
      || ';'
      || lv_add
      || ';>');
    END LOOP;

    EXIT;
   END IF;

   SELECT SUBSTR(TO_CHAR(NVL(SUM(DECODE(lc.entype, 1, er, 2, ed, 3, NVL(q1, 0) + NVL(q2, 0), 5, NVL(q3, 0) + NVL(q4, 0))), 0), cv_12_3), 2)
   INTO   lv_add
   FROM   billorg
   WHERE  mid = an_id AND date_time = ad_date AND nsource = 8;

   file_pg.out_p('<'
    || lv_cod
    || '0'
    || REPLACE(lc.entype, '5', '4')
    || ';'
    || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi')
    || ';'
    || cv_duration
    || ';'
    || SUBSTR(TO_CHAR(util_pg.get_meterage(an_id, ad_date, lc.entype, 0, NULL), cv_12_3), 2)
    || ';'
    || SUBSTR(TO_CHAR(util_pg.get_meterage(an_id, ad_date, lc.entype, 1, NULL), cv_12_3), 2)
    || ';'
    || LPAD(lc.mtrsn, 20)
    || ';'
    || LPAD(LENGTH(TRUNC(lc.digits)), 1)
    || ';'
    || LPAD(lc.mtype, 50)
    || ';'
    || lc.mcurrent
    || ';'
    || lc.mpower
    || ';'
    || lc.mconst
    || ';'
    || SUBSTR(TO_CHAR(lc.mclass, cv_mask1), 2)
    || ';'
    || SUBSTR(TO_CHAR(lc.mclass, cv_mask1), 2)
    || ';'
    || lc.mquarter
    || ';'
    || lc.myear
    || ';'
    || lv_kc
    || ';'
    || lv_add
    || ';>');
  END LOOP;

  file_pg.out_p('==))');
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 20120 замены коеф счетчика
 PROCEDURE m20120_p(an_id NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  ln_parent           NUMBER;
  lv_kc               VARCHAR2(256);
  lv_cod              VARCHAR2(256);
 BEGIN
  SELECT MAX(p.PARENT), SUBSTR(TO_CHAR(MAX(f.kc), cv_12_3), 2)
  INTO   ln_parent, lv_kc
  FROM   points p, feeders f
  WHERE  p.mid = an_id AND p.mid = f.mid AND EXISTS(SELECT *
                                                    FROM   meters
                                                    WHERE  mid = an_id);

  IF ln_parent IS NULL THEN
   RETURN;
  END IF;

  file_pg.out_p('((//20120;'
   || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss')
   || ';'
   || util_pg.enterprise_char_f
   || ';++Замена коэффициента счетчика '
   || util_pg.get_pointname(ln_parent, 0, 0));
  lv_cod := util_pg.get_point_code(an_id, 1, 0);

  FOR lc IN (SELECT   mtrsn, entype
             FROM     meters m
             WHERE    m.mid = an_id AND entype NOT IN(4, 6)
             ORDER BY DECODE(entype, 7, 1, 2), entype) LOOP
   IF lc.entype = 7 THEN
    FOR i IN 1 .. 4 LOOP
     file_pg.out_p('<' || lv_cod || '0' || i || ';' || lc.mtrsn || ';' || lv_kc || ';' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') || ';>');
    END LOOP;

    EXIT;
   END IF;

   file_pg.out_p('<' || lv_cod || '0' || REPLACE(lc.entype, '5', '4') || ';' || lc.mtrsn || ';' || lv_kc || ';' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi')
    || ';>');
  END LOOP;

  file_pg.out_p('==))');
 END;

------------------------------------------------------------------------------------------------------------------------
 --Макет 20161 введения поправок
 PROCEDURE m20161_p(an_id NUMBER, ad_from DATE, ad_till DATE, av_fname IN OUT VARCHAR2) IS
  ln_parent           NUMBER;
  lv_cod              VARCHAR2(256);
  lv_ras              VARCHAR2(256) DEFAULT SUBSTR(TO_CHAR(0, cv_12_3), 2);
  lt_ras              common_pg.tt_number;
 BEGIN
  SELECT MAX(p.PARENT)
  INTO   ln_parent
  FROM   points p
  WHERE  p.mid = an_id;

  IF ln_parent IS NULL THEN
   RETURN;
  END IF;

  file_pg.out_p('((//20161;' || TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss') || ';' || util_pg.enterprise_char_f || ';++Введение поправок '
   || util_pg.get_pointname(ln_parent, 0, 0));
  lv_cod := util_pg.get_point_code(an_id, 1, 0);

  SELECT SUM(er) er, SUM(ed) ed, util_pg.sumn(SUM(q1), SUM(q2)) q1, util_pg.sumn(SUM(q3), SUM(q4)) q3
  INTO   lt_ras(1), lt_ras(2), lt_ras(3), lt_ras(4)
  FROM   halfhour
  WHERE  mid = an_id AND date_time > ad_from AND date_time <= util_pg.ceil_d(ad_till, 1 / 48) AND nsource IN(util_pg.cn_manualinput, util_pg.cn_manualinputw);

  FOR lc IN (SELECT   mtrsn, entype
             FROM     meters m
             WHERE    m.mid = an_id AND entype NOT IN(4, 6)
             ORDER BY DECODE(entype, 7, 1, 2), entype) LOOP
   IF lc.entype = 7 THEN
    FOR i IN 1 .. 4 LOOP
     IF lt_ras(i) IS NOT NULL THEN
      file_pg.out_p('<' || lv_cod || '0' || i || ';' || lt_ras(i) || ';' || TO_CHAR(ad_from, 'dd.mm.yyyy hh24:mi') || ';'
       || TO_CHAR(ad_till, 'dd.mm.yyyy hh24:mi') || ';>');
     END IF;
    END LOOP;

    EXIT;
   END IF;

   IF lt_ras(REPLACE(lc.entype, '5', '4')) IS NOT NULL THEN
    file_pg.out_p('<' || lv_cod || '0' || REPLACE(lc.entype, '5', '4') || ';' || lt_ras(REPLACE(lc.entype, '5', '4')) || ';' || '>');
   END IF;
  END LOOP;

  file_pg.out_p('==))');
 END;
------------------------------------------------------------------------------------------------------------------------
END;                                                                                                                                 -- Package Body REPORTS1_PG
/


