   gr.nsubgroup gid,decode(p.ind,3,p.mid,0) mid, p.name name ,p.short_name,decode(p.ind,3,NULL,p.mid) is_group,
   REQUEST_MONITORING_PG.get_step_maket (p.mid,   to_date('''||lv_dattill||''',''dd.mm.yyyy hh24:mi:ss''))ll,
    0 blocking,
               0 nparent,
                     to_char(profile,''dd.mm.yyyy hh24:mi:ss'')Profile,
                    to_char(util_pg.to_localtime(ls.halfhour),''dd.mm.yyyy hh24:mi:ss'')Halfhour, 
                    to_char(bill,''dd.mm.yyyy hh24:mi:ss'')Bill,
                    to_char(months,''dd.mm.yyyy hh24:mi:ss'')Months,
                     REQUEST_MONITORING_PG.get_count_halfhour_maket(p.mid)halfcount,
                     REQUEST_MONITORING_PG.get_count_billorg_maket (p.mid) billcount,
                     REQUEST_MONITORING_PG.get_count_monthsorg_maket(p.mid)monthscount ,
                     REQUEST_MONITORING_PG.get_count_maket (p.mid) countpoint  
                      FROM ryda.maketformulas gr, ryda.maketgroups g , maketpoints mp,points p, last_save ls
                     WHERE gr.ngroup = '
    || an_mid
    || ' AND g.ngroup = gr.nsubgroup
                    AND  mp.ngroup=g.ngroup
                     AND mp.mid=p.mid 
                   
                    and p.mid = ls.mid(+) 
                   ORDER BY  name ';                                                                                                  -- подгруппы для агрегирующих групп
 
  END IF;
  
 ELSIF an_typetree=5 and (an_roleid=0 or an_roleid=1) THEN --по com; 
 IF an_mid IS NULL   THEN
  lv_sql :='select 1 HaveChild,
         1 type,
         c.nsrv gid,
         0 mid, 
      
           vname name,
           vname short_name,
            
                    REQUEST_MONITORING_PG.get_step_srv (c.nsrv,0,to_date('''||lv_dattill||''',''dd.mm.yyyy hh24:mi:ss''))ll,
                 1 is_group,
                 0 blocking,
                 -1 nparent, 
                
                    NULL Profile,
                    NULL Halfhour, 
                    NULL Bill,
                    NULL Months ,
                   
                   REQUEST_MONITORING_PG.get_count_halfhour_srv(c.nsrv,0)halfcount,
                   REQUEST_MONITORING_PG.get_count_billorg_srv (c.nsrv,0) billcount,
                    REQUEST_MONITORING_PG.get_count_monthsorg_srv(c.nsrv,0)monthscount,
                  REQUEST_MONITORING_PG.get_count_srv (c.nsrv,0) countpoint
                   from srv c
                    where exists (select * from comports cp where cp.nsrv=c.nsrv)
        union all
        
        select 0 HaveChild,
         1 type,
         c.nsrv gid,
         0 mid, 
        vname name,
           vname short_name,
            
                    REQUEST_MONITORING_PG.get_step_srv (c.nsrv,0,to_date('''||lv_dattill||''',''dd.mm.yyyy hh24:mi:ss''))ll,
                    1 is_group,
                    0 blocking,
                     -1 nparent, 
                    NULL Profile,
                    NULL Halfhour, 
                    NULL Bill,
                    NULL Months ,
                   
                   REQUEST_MONITORING_PG.get_count_halfhour_srv(c.nsrv,0)halfcount,
                    REQUEST_MONITORING_PG.get_count_billorg_srv (c.nsrv,0) billcount,
                    REQUEST_MONITORING_PG.get_count_monthsorg_srv(c.nsrv,0)monthscount,
                   REQUEST_MONITORING_PG.get_count_srv (c.nsrv,0) countpoint
                   from srv c
                    where not exists (select * from comports cp where cp.nsrv=c.nsrv)';  
 ELSE
   lv_sql :='select 1 HaveChild,
        2 type,
         c.com_id gid  ,
         0 mid , 
      
            name ,
           name short_name ,
            
                    REQUEST_MONITORING_PG.get_step_srv (0,c.com_id,to_date('''||lv_dattill||''',''dd.mm.yyyy hh24:mi:ss''))ll,
                 1 is_group,
               0 blocking,
                -1 nparent, 
                    NULL Profile,
                    NULL Halfhour, 
                    NULL Bill,
                    NULL Months ,
                   
                   REQUEST_MONITORING_PG.get_count_halfhour_srv(0,c.com_id)halfcount,
                   REQUEST_MONITORING_PG.get_count_billorg_srv (0,c.com_id) billcount,
                    REQUEST_MONITORING_PG.get_count_monthsorg_srv(0,c.com_id)monthscount,
                  REQUEST_MONITORING_PG.get_count_srv (0,c.com_id) countpoint
          from comports c
                    where 
                    c.nsrv='
    || an_mid
    || '
                    and  exists (select * from channels cp where cp.com_id=c.com_id)
        union all
        
        select 0 HaveChild,
         2 type,
         c.com_id gid,
         0 mid, 
         name,
           name short_name,
            
                     REQUEST_MONITORING_PG.get_step_srv (0,c.com_id,to_date('''||lv_dattill||''',''dd.mm.yyyy hh24:mi:ss''))ll,
                 1 is_group,
               0 blocking,
                -1 nparent, 
                    NULL Profile,
                    NULL Halfhour, 
                    NULL Bill,
                    NULL Months ,
                   
                   REQUEST_MONITORING_PG.get_count_halfhour_srv(0,c.com_id)halfcount,
                   REQUEST_MONITORING_PG.get_count_billorg_srv (0,c.com_id) billcount,
                    REQUEST_MONITORING_PG.get_count_monthsorg_srv(0,c.com_id)monthscount,
                  REQUEST_MONITORING_PG.get_count_srv (0,c.com_id) countpoint
                   from comports c
                    where 
                    c.nsrv='
    || an_mid
    || '
                    and  exists (select * from channels cp where cp.com_id=c.com_id)';
 END IF;            
  
 END IF; 
 --  insert into tmp_vil values(lv_sql);commit;
   OPEN acur_t FOR lv_sql;                 
   END;

