FUNCTION get_blocing(an_mid NUMBER)
RETURN NUMBER IS
ln_b NUMBER;
BEGIN
   SELECT MAX(f.nblock)
   INTO ln_b
   FROM feeders f
   WHERE f.mid=an_mid;
   RETURN nvl(ln_b,0);
END;
--------------------------------------------------------------------------------------------------------------
FUNCTION get_count_halfhour (ad_date VARCHAR2,an_gid NUMBER)
RETURN NUMBER IS
cn NUMBER;
BEGIN
          IF util_pg.get_customer_id = 1 THEN
     IF interior_pg.ifnroot_f(an_gid)>0 THEN
       select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid IN (select gr.mid from groups gr connect by ((prior gr.gid=gr.parent
       AND (ad_date BETWEEN  nvl(gr.nfromperiod,0) AND nvl(gr.ntillperiod,299912))  )
       or (prior gr.NROOT2=gr.NROOT2 and prior gr.nroot1>0 and gr.nroot1 is null 
       AND (ad_date BETWEEN  nvl(gr.nfromperiod,0) AND nvl(gr.ntillperiod,299912))  ))
       start with gr.gid=an_gid
       AND (ad_date BETWEEN  nvl(gr.nfromperiod,0) AND nvl(gr.ntillperiod,299912)) );
     ELSE
       select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid IN (select gr.mid from groups gr connect by prior 
       gr.gid=gr.parent  
       AND (ad_date BETWEEN  nvl(gr.nfromperiod,0) AND nvl(gr.ntillperiod,299912))
       start with gr.gid=an_gid
        AND (ad_date BETWEEN  nvl(gr.nfromperiod,0) AND nvl(gr.ntillperiod,299912)));
     END IF;
     ELSE
       select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid IN (select gr.mid from groups gr connect by prior 
       gr.gid=gr.parent start with gr.gid=an_gid);
       
   END IF;
      
         
   RETURN cn;                 
 END;
