FUNCTION get_count_halfhour_canal (an_mid NUMBER)
RETURN NUMBER IS
cn NUMBER;
BEGIN
IF (is_point(an_mid)=0) THEN 
   select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid IN (select p.mid from points p,channels ch 
                      where p.parent =an_mid  and p.mid=ch.cid(+)
                      union all
                     select p.mid from points p,chanpoint c 
                      where  c.cid=an_mid and p.mid=c.mid(+));
ELSE
 select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid =an_mid;
END IF;
   RETURN cn;  
END;
