PROCEDURE ins_table(ad_date DATE,ad_dender DATE)IS
lv_subh VARCHAR2(100);
lv_subb VARCHAR2(100);
lv_subm VARCHAR2(100);
lv_date VARCHAR2(100);
lv_sql  VARCHAR2(4000);
lv_denter VARCHAR2(100);
lv_subselect VARCHAR2(1000);
BEGIN
DELETE FROM archstat;
 COMMIT;
 IF ad_dender IS NOT NULL THEN
  lv_denter:=to_char(ad_dender,'dd.mm.yyyy hh24:mi:ss');
  lv_subh:='and h.denter<to_date('''||lv_denter||''',''dd.mm.yyyy hh24:mi:ss'')' ;
  lv_subb:='and b.denter<to_date('''||lv_denter||''',''dd.mm.yyyy hh24:mi:ss'')' ;
  lv_subm:='and m.denter<to_date('''||lv_denter||''',''dd.mm.yyyy hh24:mi:ss'')' ;
 ELSE
  lv_subh:=' ';
  lv_subb:=' ';
  lv_subm:=' ';
 END IF;
  lv_date:=to_char(ad_date,'dd.mm.yyyy hh24:mi:ss');
  
/* IF(util_pg.is_dayswitch(ad_date)<>0)THEN
  lv_subselect:=' util_pg.to_localtime(h.date_time-1/86400,h.nsource) ';
 ELSE
  lv_subselect:=' h.date_time-1/86400 ';
 END IF; */

lv_sql:='INSERT INTO archstat a (a.mid, a.cnh, a.cnb, a.cnm)
  SELECT distinct f.mid, nvl(tt.cn,0),nvl(kk.cnb,0),nvl(nn.cnm,0) 
  FROM(
  
   SELECT h.mid,
   /* count(distinct trunc(TO_CHAR ('||lv_subselect||', ''SSSSS'') / 1800)) cn */
    count(distinct util_pg.get_num_dt (h.date_time-1/86400,h.nsource, 1/48 )) cn  
   from halfhour h
   where h.date_time>to_date('''||lv_date||''',''dd.mm.yyyy hh24:mi:ss'')
   and h.date_time<=to_date('''||lv_date||''',''dd.mm.yyyy hh24:mi:ss'')+1
   and qm_pg.gbt(h.vqm, 22)<>''0''
   '||lv_subh||'
   group by 
   h.mid /*,trunc(h.date_time-1/86400)*/)tt,
   ( SELECT b.mid,1 cnb 
   from billorg b
   where b.date_time>=trunc(to_date('''||lv_date||''',''dd.mm.yyyy hh24:mi:ss''))+1
   and b.date_time<trunc(to_date('''||lv_date||''',''dd.mm.yyyy hh24:mi:ss''))+2
   '||lv_subb||'
   group by 
   b.mid)kk,
   (SELECT m.mid,1 cnm 
   from monthsorg m
   where m.date_time>=trunc(to_date('''||lv_date||''',''dd.mm.yyyy hh24:mi:ss''),''mm'')
   and m.date_time<add_months(trunc(to_date('''||lv_date||''',''dd.mm.yyyy hh24:mi:ss''),''mm''),1)
   '||lv_subm||'
   group by 
   m.mid)nn,
   feeders f
   where
   f.mid=tt.mid(+)
   and
   f.mid=kk.mid(+)
   and
   f.mid=nn.mid(+)';
--  delete from tmp_vil;
--  insert into tmp_vil values(lv_sql);commit; 
  EXECUTE IMMEDIATE lv_sql;
  COMMIT; 
END;   
   
 
------------------------------------------------------------------------------------------
--Возвращает сколько должно быть записей для канала в halfhour
FUNCTION get_step_cid (an_cid NUMBER,ad_dat DATE)
  RETURN NUMBER IS
  ln_val   NUMBER;
  ld_dat   DATE;
 
 BEGIN
 ld_dat := ad_dat +interior_pg.get_hourtimezone; 
 IF (is_point(an_cid)=0) THEN
 
 SELECT  SUM (24 * (60 / NVL (f.nintegralperiod, 30)) - 60 / NVL (f.nintegralperiod, 30) 
 * util_pg.is_dayswitch (ld_dat)) cn
 INTO ln_val
 from feeders f where f.mid in
(select distinct c.mid
 FROM chanpoint c 
 WHERE  c.cid IN
 (SELECT p.mid FROM points p CONNECT BY PRIOR p.mid=p.parent START WITH p.mid=an_cid
 UNION ALL
 SELECT ch.mid FROM chanpoint ch WHERE ch.cid=an_cid ));
 
 ELSE
  SELECT MAX (24 * (60 / NVL (nintegralperiod, 30)) - 60 / NVL (nintegralperiod, 30) * util_pg.is_dayswitch (ld_dat))
      INTO ln_val
      FROM feeders
     WHERE mid = an_cid;
 END IF;

 RETURN NVL (ln_val, 0);
 
END;
--------------------------------------------------------------------------------------------
FUNCTION get_step_maket (an_nmaket NUMBER,ad_dat DATE)
  RETURN NUMBER IS
  ln_val   NUMBER;
  ld_dat   DATE;
 
 BEGIN
 ld_dat := ad_dat +interior_pg.get_hourtimezone; 
 IF (is_point(an_nmaket)=0) THEN
 
 SELECT  SUM (24 * (60 / NVL (f.nintegralperiod, 30)) - 60 / NVL (f.nintegralperiod, 30) 
 * util_pg.is_dayswitch (ld_dat)) cn
 INTO ln_val
 from feeders f where f.mid in
(select mp.mid from  maketpoints mp
   where 
     mp.ngroup IN(
    select ngroup from makets m,maketgroups g where m.nmaket IN (select gr.mid from points gr 
       connect by prior 
       gr.mid=gr.parent 
       start with gr.mid=an_nmaket) and m.nmaket=g.nmaket));
 
 ELSE
  SELECT MAX (24 * (60 / NVL (nintegralperiod, 30)) - 60 / NVL (nintegralperiod, 30) * util_pg.is_dayswitch (ld_dat))
      INTO ln_val
      FROM feeders
     WHERE mid = an_nmaket;
 END IF;

 RETURN NVL (ln_val, 0);
 
END;
------------------------------------------------------------------------------------------
--Возвращает сколько точек в  канале 
FUNCTION get_count_cid (an_cid NUMBER)
  RETURN NUMBER IS
  ln_val   NUMBER;
  
 
 BEGIN
 
 IF (is_point(an_cid)=0) THEN 
     SELECT  count(distinct f.mid) cn
     INTO ln_val
      FROM feeders f,chanpoint c 
    WHERE f.mid=c.mid AND 
       c.cid IN
   (SELECT p.mid FROM points p CONNECT BY PRIOR p.mid=p.parent START WITH p.mid=an_cid
     UNION ALL
     SELECT ch.mid FROM chanpoint ch WHERE ch.cid=an_cid );
 ELSE
    SELECT  count(distinct c.mid) cn
    INTO ln_val
    FROM feeders f,chanpoint c 
    WHERE f.mid=c.mid AND c.mid =an_cid;
 END IF;
 RETURN NVL (ln_val, 0);
 
END;
--------------------------------------------------------------------------------------------------------
FUNCTION get_count_maket (an_maket NUMBER)
  RETURN NUMBER IS
  ln_val   NUMBER;
  
 
 BEGIN
 
 IF (is_point(an_maket)=0) THEN
 

SELECT  count(distinct f.mid) cn
     INTO ln_val
      FROM points f,maketpoints mp
   where f.mid=mp.mid
    AND mp.ngroup IN(
    select ngroup from makets m,maketgroups g 
    where m.nmaket IN (select gr.mid from points gr 
       connect by prior 
       gr.mid=gr.parent 
       start with gr.mid=an_maket) and m.nmaket=g.nmaket);
 ELSE
    SELECT  count(distinct c.mid) cn
    INTO ln_val
    FROM points f,maketpoints c 
    WHERE f.mid=c.mid AND c.mid =an_maket;
 END IF;
 RETURN NVL (ln_val, 0);
 
END;
---------------------------------------------------------------------------------------------------
FUNCTION is_point (an_mid NUMBER)
  RETURN NUMBER IS
  ln_val   NUMBER;
  
 
 BEGIN
 
   SELECT DECODE(MAX(ind),3,1,0)
    INTO ln_val
    FROM points WHERE mid=an_mid;
   
 RETURN NVL (ln_val, 0);
 
END;
------------------------------------------------------------------
FUNCTION get_step_point (an_mid NUMBER,ad_dat DATE)
  RETURN NUMBER IS
ln_val NUMBER;
ld_dat DATE;  
BEGIN  
ld_dat := ad_dat +interior_pg.get_hourtimezone;
IF util_pg.isfolder_spez (an_mid) = 1 THEN
    SELECT SUM (24 * (60 / NVL (nintegralperiod, 30)) - 60 / NVL (nintegralperiod, 30) * util_pg.is_dayswitch (ld_dat))
      INTO ln_val
      FROM feeders
     WHERE mid IN (SELECT     p.mid
                         FROM points p
                   CONNECT BY PRIOR p.mid = p.PARENT AND PRIOR p.ind NOT IN (3,4)
                   START WITH p.mid = an_mid);
   ELSE
    
    SELECT MAX (24 * (60 / NVL (nintegralperiod, 30)) - 60 / NVL (nintegralperiod, 30) * util_pg.is_dayswitch (ld_dat))
      INTO ln_val
      FROM feeders
     WHERE mid = an_mid;
   END IF;
  RETURN NVL (ln_val, 0);
END;
