FUNCTION get_count_halfhour_srv(an_srv NUMBER,an_com_id NUMBER)
 RETURN NUMBER IS
cn NUMBER; 
BEGIN
IF an_com_id=0 THEN
  select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid IN ( 
       select p.mid from points p,channels ch,comports c,chanpoint cp  
                      where   
                      p.mid=cp.mid(+)
                      and c.nsrv=an_srv
                      and ch.com_id=c.com_id
                      and cp.cid=ch.cid);
ELSE
   select SUM(cnh)
       INTO cn
       FROM archstat a
       where mid IN ( 
       select p.mid from points p,channels ch,chanpoint cp  
                      where   
                      p.mid=cp.mid(+)
                      and ch.com_id=an_com_id
                      and cp.cid=ch.cid);
END IF;
 RETURN cn;  
END;

