FUNCTION get_count_srv (an_srv NUMBER,an_com_id NUMBER)
  RETURN NUMBER IS
  ln_val   NUMBER;
  
 
 BEGIN
  IF an_com_id=0 THEN

     SELECT  count(distinct f.mid) cn
     INTO ln_val
    FROM feeders f
    WHERE 
       f.mid IN
      ( select p.mid from points p,channels ch,comports c,chanpoint cp  
                      where   
                      p.mid=cp.mid(+)
                      and c.nsrv=an_srv
                      and ch.com_id=c.com_id
                      and cp.cid=ch.cid);
ELSE
 SELECT  count(distinct f.mid) cn
     INTO ln_val
    FROM feeders f
    WHERE 
       f.mid IN
      ( select p.mid from points p,channels ch,chanpoint cp  
                      where   
                      p.mid=cp.mid(+)
                      and ch.com_id=an_com_id
                      and cp.cid=ch.cid);
END IF;
 
 RETURN NVL (ln_val, 0);
 
END;
-------------------------------------------------------------------------------------------------------- 
FUNCTION get_step_srv (an_srv NUMBER,an_com_id NUMBER,ad_dat DATE)
  RETURN NUMBER IS
  ln_val   NUMBER;
  ld_dat   DATE;
 
 BEGIN
 ld_dat := ad_dat +interior_pg.get_hourtimezone; 
 
 IF an_com_id=0 THEN
 SELECT  SUM (24 * (60 / NVL (f.nintegralperiod, 30)) - 60 / NVL (f.nintegralperiod, 30) 
 * util_pg.is_dayswitch (ld_dat)) cn
 INTO ln_val
 FROM feeders f
    WHERE 
       f.mid IN
      ( select distinct p.mid from points p,channels ch,comports c,chanpoint cp  
                      where   
                      p.mid=cp.mid(+)
                      and c.nsrv=an_srv
                      and ch.com_id=c.com_id
                      and cp.cid=ch.cid
                      and NVL (DECODE (ch.nkind, 100, ch.blocking2, ch.blocking), p.tag)=0);
ELSE
SELECT  SUM (24 * (60 / NVL (f.nintegralperiod, 30)) - 60 / NVL (f.nintegralperiod, 30) 
 * util_pg.is_dayswitch (ld_dat)) cn
 INTO ln_val
 FROM feeders f
    WHERE 
       f.mid IN
      ( select distinct p.mid from points p,channels ch,chanpoint cp  
                      where   
                      p.mid=cp.mid(+)
                      and ch.com_id=an_com_id
                      and cp.cid=ch.cid
                       and NVL (DECODE (ch.nkind, 100, ch.blocking2, ch.blocking), p.tag)=0);

END IF; 
 

 RETURN NVL (ln_val, 0);
 
END;
