     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
         FROM points gr
        WHERE gr.mid in (select * from table(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid))) AND EXISTS (SELECT *
                                                         FROM points gr1
                                                        WHERE gr1.PARENT = gr.mid)
     UNION ALL
     SELECT   2 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
         FROM points gr
        WHERE gr.mid in (select * from table(adminadd_pg.getfirst_accmid(util_pg.cn_pntmid))) AND NOT EXISTS (SELECT *
                                                             FROM points gr1
                                                            WHERE gr1.PARENT = gr.mid)
     ORDER BY NORDER,tt, vname;
     ELSE
    IF (an_lmid = 0) THEN
     OPEN acur_t FOR
      SELECT   1 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
          FROM points gr
         WHERE gr.mid in (select * from table(adminadd_pg.getfirst_accmid)) AND EXISTS (SELECT *
                                            FROM points gr1
                                           WHERE gr1.PARENT = gr.mid)
      UNION ALL
      SELECT   2 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname,decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
          FROM points gr
         WHERE gr.mid in (select * from table(adminadd_pg.getfirst_accmid)) AND NOT EXISTS (SELECT *
                                                FROM points gr1
                                               WHERE gr1.PARENT = gr.mid)
      ORDER BY NORDER,tt, vname;
    ELSE
     OPEN acur_t FOR
      SELECT   1 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
          FROM points gr
         WHERE mid = an_lmid AND EXISTS (SELECT *
                                           FROM points gr1
                                          WHERE gr1.PARENT = gr.mid)
      UNION ALL
      SELECT   2 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
          FROM points gr
         WHERE mid = an_lmid AND NOT EXISTS (SELECT *
                                               FROM points gr1
                                              WHERE gr1.PARENT = gr.mid)
      ORDER BY NORDER,tt, vname;
    END IF;
   END IF;
  ELSE
   OPEN acur_t FOR
    
    SELECT   1 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
        FROM points gr
       WHERE PARENT = an_data  and cod=0  AND EXISTS (SELECT *
                                            FROM points gr1
                                           WHERE gr1.PARENT = gr.mid and cod=0)
    UNION ALL
    SELECT   2 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9)tt
        FROM points gr
       WHERE PARENT = an_data and cod=0 AND NOT EXISTS (SELECT *
                                                FROM points gr1
                                               WHERE gr1.PARENT = gr.mid and cod=0)
    ORDER BY NORDER,tt, vname;
 
  END IF;
 END;

