 PROCEDURE selectpoint_read_node (an_gid NUMBER, an_flag NUMBER, acur_t OUT common_pg.tcur) IS
  -- added 01.08.2008  Kondakov A.G.
  -- используется в TfmSelectPoint::ReadNode и в TfmSetupFilters
  av_gid    VARCHAR2 (400);
  av_gid2   VARCHAR2 (400);
  lv_sql    VARCHAR2 (4000);
 BEGIN
  IF (an_gid = 0) THEN
   IF (an_flag = 1) THEN
    av_gid := ' Parent is NULL ';
   ELSIF (an_flag = 2) THEN
    av_gid := ' p.PARENT=1 ';
   ELSIF (an_flag = 3) THEN
    av_gid := ' p.PARENT IS NULL ';
   ELSIF (an_flag = 4) THEN
    av_gid := ' gid=indic_pg.getoutputgroup ';
   ELSIF (an_flag = 5) THEN
    av_gid := ' p.PARENT IS NULL AND p.COD=0 AND  EXISTS (SELECT * FROM points WHERE parent=p.mid)';
    av_gid2 := ' p.PARENT IS NULL AND p.COD=0 AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid)';
   ELSIF (an_flag = 6) THEN
    av_gid := ' p.nPARENT IS NULL ';
   ELSIF (an_flag = 8) THEN
    av_gid := ' p.PARENT IS NULL AND p.COD=0 ';
    av_gid2 := ' p.Parent is NULL ';
   ELSIF(an_flag = 9) THEN
    av_gid := ' cod=0 and mid=(select max(mid) from enterprise)
                        and exists (select * from points where parent=p.mid and cod=0) ';
    av_gid2:= ' cod=0 and mid=(select max(mid) from enterprise)
                        and not exists (select * from points where parent=p.mid and cod=0) ';
   ELSIF (an_flag = 10) THEN
    av_gid := ' p.PARENT=1 ';
   END IF;
  ELSE
   IF (an_flag = 1) THEN
    av_gid := ' parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 2) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 3) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 4) THEN
    av_gid := ' parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 5) THEN
      av_gid := ' p.PARENT= ' || TO_CHAR (an_gid)||'  AND  EXISTS (SELECT * FROM points WHERE parent=p.mid)';
      av_gid2 := ' p.PARENT= ' || TO_CHAR (an_gid)||'  AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid)';
   ELSIF (an_flag = 6) THEN
    av_gid := ' p.nparent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 8) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
    av_gid2 := ' p.parent=' || TO_CHAR (an_gid);
   ELSIF(an_flag = 9) THEN
     av_gid :=' cod=0 and parent='|| TO_CHAR (an_gid) ||'
                        and exists (select * from points where parent=p.mid and cod=0) ';
     av_gid2 :=' cod=0 and parent=' || TO_CHAR (an_gid) ||'
                        and not exists (select * from points where parent=p.mid and cod=0) ';
   ELSIF (an_flag = 10) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
   END IF;
  END IF;

  IF (an_flag = 1) THEN
   lv_sql :=
    'SELECT 1 HaveChild, gid mid , decode(mid,NULL,4,1) TYPE, nvl(NAME,'' '') NAME ,util_pg.get_pointname(mid, 2) pinfo
                  FROM GROUPS p
                  WHERE '
    || av_gid
    || '
                     AND EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
                  UNION ALL
                  SELECT 0 HaveChild, gid, decode(mid,NULL,4,1) TYPE, nvl(NAME,'' '') NAME ,util_pg.get_pointname(mid, 2) pinfo
                  FROM GROUPS p
                  WHERE '
    || av_gid || '
                     AND NOT EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
                  ORDER BY 3,4';
  ELSIF (an_flag = 2) THEN
   lv_sql :=
    'SELECT 1 HaveChild, p.mid, decode(c.cid,NULL,0,1) TYPE, nvl(c.vname,nvl(p.NAME,'' '')) NAME, ''Канал: ''||nvl(c.vname,nvl(p.NAME,'' '')) pinfo
                  FROM points p,channels c
                  WHERE '
    || av_gid
    || ' AND p.mid=c.cid(+) AND nvl(c.PROTOCOL_ID,37) in (37,113)
                     AND EXISTS (SELECT * FROM points WHERE parent=p.mid)
                  UNION ALL
                  SELECT 0 HaveChild, p.mid, decode(c.cid,NULL,0,1) TYPE, nvl(c.vname,nvl(p.NAME,'' '')) NAME, ''Канал: ''||nvl(c.vname,nvl(p.NAME,'' '')) pinfo
                  FROM points p,channels c
                  WHERE '
    || av_gid
    || ' AND p.mid=c.cid(+) AND nvl(c.PROTOCOL_ID,37) in (37,113)
                     AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid)
                  ORDER BY 3,4';
 ELSIF (an_flag = 3) THEN
   lv_sql :=
       'SELECT 1 HaveChild, p.mid, decode(p.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) TYPE ,
       p.NORDER,decode(p.ind,1,decode(p.cod,0,1,1000),2,decode(p.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9),
       nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo
                  FROM points p
                  WHERE '
    || av_gid
    || '
                     AND EXISTS (SELECT * FROM points WHERE parent=p.mid)
                  UNION ALL
                  SELECT 0 HaveChild, p.mid,  decode(p.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) TYPE ,
                  p.NORDER,decode(p.ind,1,decode(p.cod,0,1,1000),2,decode(p.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5,620,9),
                  nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo
                  FROM points p
                  WHERE '
    || av_gid || '
                     AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid)
                  ORDER BY 4,5,6';

  ELSIF (an_flag = 4) THEN
   lv_sql :=
    'SELECT 1 HaveChild, gid  mid , decode(mid,NULL,4,1) TYPE, nvl(NAME,'' '') NAME,util_pg.get_pointname(mid, 2) pinfo
                  FROM GROUPS p
                  WHERE '
    || av_gid
    || '
                     AND EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
                  UNION ALL
                  SELECT 0 HaveChild, gid , decode(mid,NULL,4,1) TYPE, nvl(NAME,'' '') NAME,util_pg.get_pointname(mid, 2) pinfo
                  FROM GROUPS p
                  WHERE '
    || av_gid || '
                     AND NOT EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
                  ORDER BY 3,4';
  ELSIF (an_flag = 5) OR (an_flag = 9)
   THEN
  lv_sql :=
     'SELECT 1 HaveChild, p.mid, decode(p.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) TYPE ,
     p.NORDER,decode(p.ind,1,1,2,1,3,3,4,3,600,6,610,8,500,5,620,9),
      nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo
                  FROM points p
                  WHERE '
    || av_gid   || '
                  UNION ALL
                  SELECT 0 HaveChild, p.mid,  decode(p.ind,1,0,2,0,3,1,600,6,610,8,500,7,620,9,5) TYPE ,
                  p.NORDER,decode(p.ind,1,1,2,1,3,3,4,3,600,6,610,8,500,5,620,9),
                   nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo
                  FROM points p
                  WHERE '
    || av_gid2 || ' ORDER BY 4,5,6';
 
  ELSIF (an_flag = 6) THEN
   lv_sql :=
    'SELECT 1 HaveChild, p.nid mid, decode(p.nevent,NULL,0,1) TYPE, nvl(decode(p.nevent,NULL,p.vNAME,d.VEVENTTEXT),'' '') NAME, nvl(p.vNAME,'' '') pinfo, p.nevent id_event
                  FROM FILTERS p,METEREVENTSDICT d
                  WHERE '
    || av_gid
    || '
                     AND p.nevent=d.nevent(+) AND EXISTS (SELECT * FROM FILTERS WHERE nparent=p.nid)
                  UNION ALL
                  SELECT 0 HaveChild, p.nid mid, decode(p.nevent,NULL,0,1) TYPE, nvl(decode(p.nevent,NULL,p.vNAME,d.VEVENTTEXT),'' '') NAME, nvl(p.vNAME,'' '') pinfo, p.nevent id_event
                  FROM FILTERS p,METEREVENTSDICT d
                  WHERE '
    || av_gid || '
                     AND p.nevent=d.nevent(+) AND NOT EXISTS (SELECT * FROM FILTERS WHERE nparent=p.nid)
                  ORDER BY 3,4';
  ELSIF (an_flag = 7) THEN
   IF (an_gid = 0) THEN
    lv_sql := 'SELECT 1 HaveChild, nmetertype mid, 0 TYPE, vname NAME, NVL(vname,'' '') pinfo, 0 id_event
         FROM metertype order by 4';
   ELSE
    lv_sql :=
     'SELECT 0 HaveChild, nevent mid, 1 TYPE, veventtext NAME, NVL(veventtext,'' '') pinfo, nevent id_event
        FROM metereventsdict
        WHERE nmetertype = '
     || an_gid || ' order by 4';
   END IF;
  ELSIF (an_flag = 8) THEN
   lv_sql :=
    'SELECT 1 HaveChild,1 IsPoint, p.mid, decode(p.ind,1,0,2,0,3,10,600,6,610,8,500,7,620,9,5) TYPE ,p.ind nsort ,nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo FROM points p WHERE '
    || av_gid || ' AND EXISTS (SELECT * FROM points WHERE parent=p.mid) '
    || 'UNION ALL SELECT 0 HaveChild,1 IsPoint, p.mid, decode(p.ind,1,0,2,0,3,10,600,6,610,8,500,7,620,9,5) TYPE ,p.ind nsort , nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo FROM points p WHERE '
    || av_gid || ' AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid) '
    || 'union all SELECT 1 HaveChild,0 IsPoint, gid mid , decode(mid,NULL,4,1) TYPE,decode(mid,NULL,11,12) nsort , nvl(NAME,'' '') NAME ,util_pg.get_pointname(mid, 2) pinfo FROM GROUPS p WHERE '
    || av_gid2 || ' AND EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
     UNION ALL '
    || 'SELECT 0 HaveChild,0 IsPoint, gid, decode(mid,NULL,4,1) TYPE,decode(mid,NULL,11,12) nsort , nvl(NAME,'' '') NAME ,util_pg.get_pointname(mid, 2) pinfo FROM GROUPS p WHERE '
    || av_gid2 || ' AND NOT EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid) ' || 'ORDER BY 5,6,7';
  ELSIF (an_flag = 10) THEN
   lv_sql :=
    'SELECT 1 HaveChild, p.mid, decode(c.cid,NULL,0,1) TYPE, nvl(c.vname,nvl(p.NAME,'' '')) NAME, ''Канал: ''||nvl(c.vname,nvl(p.NAME,'' '')) pinfo
                  FROM points p,channels c
                  WHERE '
    || av_gid
    || ' AND p.mid=c.cid(+) 
                     AND EXISTS (SELECT * FROM points WHERE parent=p.mid)
                  UNION ALL
                  SELECT 0 HaveChild, p.mid, decode(c.cid,NULL,0,1) TYPE, nvl(c.vname,nvl(p.NAME,'' '')) NAME, ''Канал: ''||nvl(c.vname,nvl(p.NAME,'' '')) pinfo
                  FROM points p,channels c
                  WHERE '
    || av_gid
    || ' AND p.mid=c.cid(+)
         AND EXISTS (SELECT * FROM  schemchannels
                      WHERE NOPERSCANSCHEMAS IN (SELECT NOPERSCANSCHEMAS FROM ROLES
                                                  WHERE role_id IN (SELECT role_id FROM users WHERE usr = '''||USER||'''))
                      AND cid = p.mid) 
         AND NOT EXISTS (SELECT * FROM points WHERE parent=p.mid)
         ORDER BY 3,4';
  END IF;

  OPEN acur_t FOR lv_sql;
 END;

---------------------------------------------------------------------------------------------------------
 PROCEDURE find_curr_node (an_mid NUMBER, an_flag NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TfmSelectPoint::FindCurrNode
 BEGIN
  IF (an_flag = 1) THEN
   OPEN acur_t FOR
    SELECT     gid mid
          FROM GROUPS
    CONNECT BY PRIOR PARENT = gid
    START WITH gid = an_mid;
  ELSIF (an_flag = 2) THEN
   OPEN acur_t FOR
    SELECT     mid
          FROM points
    CONNECT BY PRIOR PARENT = mid
    START WITH mid = an_mid;
  ELSIF (an_flag = 3) THEN
   OPEN acur_t FOR
    SELECT     nid mid
          FROM filters
    CONNECT BY PRIOR nparent = nid
    START WITH nid = an_mid;  
  ELSIF (an_flag = 4) THEN -- каналы
   OPEN acur_t FOR
    SELECT     mid
          FROM points
    WHERE mid NOT IN (1)
    CONNECT BY PRIOR PARENT = mid
    START WITH mid = an_mid;
  END IF;
 END;

--------------------------------------------------------------------------------------
   -- Процедура вставки и обновления фильтров
   -- added by Kondakov A.G. 30.09.2008
 PROCEDURE ins_upd_filter_p (an_nid IN OUT NUMBER,   --Ид точки
                                                  an_parent NUMBER,   --Ид родителя
                                                                   av_name VARCHAR2,   --Название
                                                                                    an_event NUMBER   --Ид события
                                                                                                   ) IS
  ln_nid      NUMBER;
  ln_parent   NUMBER DEFAULT an_parent;
  ln_event    NUMBER DEFAULT an_event;
 BEGIN
  IF ln_parent = 0 THEN
   ln_parent := NULL;
  END IF;

  IF ln_event = 0 THEN
   ln_event := NULL;
  END IF;

  IF (an_nid = 0) THEN
   SELECT forms_seq.NEXTVAL
     INTO ln_nid
     FROM DUAL;

   INSERT INTO filters
               (nid, nparent, vname, nevent
               )
        VALUES (ln_nid, ln_parent, av_name, ln_event
               );

   an_nid := ln_nid;
  ELSE
   UPDATE filters
      SET nparent = ln_parent,
          vname = av_name
    WHERE nid = an_nid;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'saa_select_pg.ins_upd_filter_p: Ошибка изменения фильтра событий. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Процедура удаления фильтров
 -- added Kondakov A.G. 30.09.2008
 PROCEDURE del_filter_p (an_nid NUMBER   --Ид фильтра
                                      ) IS
 BEGIN
  DELETE FROM filters
        WHERE nid = an_nid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'saa_select_pg.del_filter: Ошибка удаления фильтра событий. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Процедура вычитки типов измерений для формул
--Виленская Н.Б. 16.10.2008
 PROCEDURE read_meas_node (acur_t OUT common_pg.tcur, an_objtype NUMBER) IS
 BEGIN
  IF an_objtype IS NULL THEN
   OPEN acur_t FOR
    SELECT   m.nmeasure, m.vname, m.vcode
        FROM measures m
    ORDER BY 1;
  ELSE
   OPEN acur_t FOR
    SELECT   m.nmeasure, m.vname, m.vcode
        FROM measures m, objtypemeas o
       WHERE m.nmeasure = o.nmeasure AND o.ind = an_objtype
    ORDER BY 1;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------
--Процедура вычитки связки типов объектов и измерений
--Сечин А.А 06.11.2008
 PROCEDURE read_objtype_meas (acur_t OUT common_pg.tcur, an_objtype NUMBER) IS
 BEGIN
  IF an_objtype IS NULL THEN
   OPEN acur_t FOR
    SELECT   ind, nmeasure
        FROM objtypemeas
    ORDER BY ind, nmeasure;
  ELSE
   OPEN acur_t FOR
    SELECT   ind, nmeasure
        FROM objtypemeas
       WHERE ind = an_objtype
    ORDER BY ind, nmeasure;
  END IF;
 END;
------------------------------------------------------------------------------------------------------------
END;
