CREATE OR REPLACE 
PACKAGE BODY switches_pg IS
 -- пакет работы с переключениями ов
 -- дата создания 02/02/2009 (Коваленко А.O.)

 ------------------------------------------------------------------------------------------------------------------------
 gn_task_code        NUMBER DEFAULT 72;

 --функция проверяет, используется ли сейчас ОВ с ID anSwId
 FUNCTION check_switch(answid IN NUMBER)
  RETURN NUMBER IS
  res                 NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   res
  FROM   (SELECT *
          FROM   ryda.switches s
          WHERE  s.nswitch = answid AND s.descape IS NULL);

  RETURN res;
 END;

 PROCEDURE set_mask(fmid NUMBER, MASK OUT common_pg.tcur) IS
 BEGIN
  OPEN MASK FOR
   SELECT entype, digits, DECODE(f.q1234, '*', 1, 0) q1234
   FROM   meters m, feeders f
   WHERE  f.mid = fmid AND f.mid = m.mid;
 END;

 PROCEDURE is_free(nsw NUMBER, res OUT NUMBER) IS
 BEGIN
  SELECT COUNT(*)
  INTO   res
  FROM   (SELECT TO_CHAR(s.descape, 'dd.mm.yyyy hh24:mi') descape, s.ID, s.nswitch
          FROM   switches s, points sp, points g, points p, users u, feeders f
          WHERE  s.user_id = u.user_id(+) AND g.mid = sp.PARENT AND p.mid(+) = s.mid AND f.mid = s.nswitch AND sp.mid = s.nswitch)
  WHERE  nswitch = nsw AND descape IS NULL;
 END;

