 PROCEDURE get_pointlist(param NUMBER, pointlist OUT common_pg.tcur) IS
  prm                 NUMBER DEFAULT 0;
  prnt                NUMBER DEFAULT NULL;
 BEGIN
  prm := util_pg.getparamvalue_f(48);

  SELECT util_pg.get_pointparentid(p.mid)
  INTO   prnt
  FROM   points p
  WHERE  p.mid = param;

  IF prm = 1 THEN
   OPEN pointlist FOR
    SELECT   pp.mid, util_pg.get_pointname(pp.mid, 3, 0) || '\' || pp.NAME vname
    FROM     (SELECT     p.mid, p.NAME, p.PARENT vname
              FROM       points p
              CONNECT BY PRIOR p.mid = p.PARENT
              START WITH p.PARENT = prnt) pp,
             feeders f
    WHERE    pp.mid = f.mid AND f.nmainpoint IS NULL AND f.nswitch = 0 AND f.nlockswitch = 0
    ORDER BY vname;
  ELSE
   OPEN pointlist FOR
    SELECT   p.mid, p.NAME vname
    FROM     points gp, points p, feeders f
    WHERE    p.PARENT = gp.PARENT AND gp.mid = param AND p.mid = f.mid AND f.nmainpoint IS NULL AND f.nswitch = 0 AND f.nlockswitch = 0
    ORDER BY p.NAME;
  END IF;
 END;

