 PROCEDURE get_swlist(par NUMBER, plist OUT common_pg.tcur) IS
 BEGIN
  OPEN plist FOR
   SELECT   p.mid, util_pg.get_pointname(p.mid, 3, 0) || ' / ' || p.NAME vname
   FROM     points p, feeders f
   WHERE    p.mid = f.mid AND f.nswitch = par AND f.nmainpoint IS NULL
   ORDER BY vname;
 END;

 PROCEDURE get_eim(eim OUT NUMBER) IS
 BEGIN
  SELECT common_pg.get_acc_lockinputov eim
  INTO   eim
  FROM   DUAL;
 END;

 PROCEDURE get_date(ID NUMBER, res_date OUT common_pg.tcur) IS
 BEGIN
  OPEN res_date FOR
   SELECT   TO_CHAR(DECODE(NVL(s.mid, 0), 0, MIN(date_time) - 1 / 48, MAX(date_time) + 1 / 48), 'dd.mm.yy hh24:mi') datestr
   FROM     halfhourold h, switches s
   WHERE    s.nswitch = ID AND h.mid = s.nswitch AND s.descape = TO_DATE(30010101, 'yyyymmdd') AND h.date_time > s.dswitch
            AND(TRUNC(er, -2) <> 0 OR TRUNC(ed, -2) <> 0)
   GROUP BY s.mid;
 END;

 PROCEDURE get_state(order_by NUMBER, direct NUMBER, st OUT common_pg.tcur) IS
  query_str           VARCHAR2(5000);
 BEGIN
  query_str :=
      'SELECT nvl(util_pg.get_pointname (p2.mid, 3, 0)||'' / ''||p2.name,'''') SwitchName, 
               decode(p3.name, 
                      NULL,''В резерве'',
                           decode(s.descape, 
                                            NULL,p3.name,
                                             ''В резерве''))  PointName, 
               decode(s.descape, 
                        NULL,s.dswitch,
                             s.descape) SwDate,
               s.dswitch SwBegin, s.descape SwEnd,               
               s.id, s.nswitch, f.mid, s.mid pmid, p1.name pname 
               FROM feeders f,points p1, points p2, points p3,(select id,nswitch,dswitch,descape,mid from switches where (nswitch,dswitch) in (
               select nswitch,max(dswitch) from switches group by nswitch)) s 
               WHERE f.NSWITCH=1 and f.mid=p2.mid(+) and p2.parent=p1.mid(+)  and f.mid = s.nswitch(+) and f.nmainpoint is null and s.mid=p3.mid(+) ORDER BY '
   || TO_CHAR(order_by);

  IF (direct = 1) THEN
   query_str := query_str || ' DESC';
  ELSE
   query_str := query_str || ' ASC';
  END IF;

  OPEN st FOR query_str;
 END;

