 PROCEDURE get_switches_dynamic(dfrom VARCHAR2, dtill VARCHAR2, order_by NUMBER, direct NUMBER, filter_str NUMBER, sw1 OUT common_pg.tcur) IS
  query_str           VARCHAR2(5000);
 BEGIN
  --to_char(s.descape,''dd.mm.yyyy hh24:mi'')
  --to_char( s.dswitch, ''dd.mm.yyyy hh24:mi'')
  query_str :=
      'SELECT s.erme, s.edme,s.q1me,s.q2me, s.q3me, s.q4me, s.descape,
         s.dswitch, 
         util_pg.get_pointname(sp.mid, 3, 0) || '' / '' || sp.NAME SwitchName,
         decode(s.mid,NULL,sp.name,p.name) PointName, 
         s.denter dateenter, nvl(u.name,''Система'') person, 
         s.id, s.nswitch, decode(f.q1234,''*'',1,0)q1234, s.erm, s.edm, s.q1m, s.q2m, s.q3m, s.q4m, 
         nvl(s.mid,s.nswitch) nmid, p.mid pmid,f.mid, s.DENTERRET, u1.name personret
 FROM switches s, points sp, points g, points p, users u, feeders f, users u1 
 WHERE s.user_id=u.user_id(+) AND g.mid = sp.parent AND p.mid(+) = s.mid AND f.mid = s.nswitch AND sp.mid = s.nswitch AND s.user_idret = u1.user_id(+) 
 AND s.dswitch>=to_date(:dfrom,''dd.mm.yyyy hh24:mi:ss'') AND s.dswitch<=to_date(:dtill,''dd.mm.yyyy hh24:mi:ss'')';

  IF (filter_str <> 0) THEN
   query_str :=
       query_str
    || 'and s.nswitch in (select mid from points 
                            connect by prior mid=parent start with mid=:mid) ';
  END IF;

  query_str := query_str || ' ORDER BY ' || TO_CHAR(order_by);

  IF (direct = 1) THEN
   query_str := query_str || ' DESC';
  ELSE
   query_str := query_str || ' ASC';
  END IF;

IF (filter_str <> 0) THEN
  OPEN sw1 FOR query_str using dfrom,dtill,filter_str;
else
	OPEN sw1 FOR query_str using dfrom,dtill;
end if;  
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки
 PROCEDURE insupd_p(
 an_switch NUMBER,                                                                                                                                       --Ид ОВ
                  ad_switch DATE,                                                                                                            --Дата переключения
                                 ad_escape DATE, an_mid NUMBER,                                                                                       --Ид точки
                                                               an_erm NUMBER,                                                                     --Показание ОВ
                                                                             an_edm NUMBER,                                                       --Показание ОВ
                                                                                           an_q1m NUMBER,                                         --Показание ОВ
                                                                                                         an_q2m NUMBER,                           --Показание ОВ
                                                                                                                       an_q3m NUMBER,             --Показание ОВ
 an_q4m NUMBER,                                                                                                                                   --Показание ОВ
               an_ermlast NUMBER, an_edmlast NUMBER, an_q1last NUMBER, an_q2last NUMBER, an_q3last NUMBER, an_q4last NUMBER, retuser_id NUMBER,
 inpuser_id NUMBER, date_sw DATE, date_sl DATE, an_id IN OUT NUMBER                                                                                  --Ид строки
 ) IS
  is_valid            NUMBER;
 BEGIN
  IF an_switch = an_mid THEN
   raise_application_error(-20001, 'Обходной выключатель не может быть переведен сам на себя.');
  END IF;

  IF NVL(an_id, 0) = 0 THEN
   SELECT points_seq.NEXTVAL
   INTO   an_id
   FROM   DUAL;
  END IF;

  IF (ad_escape IS NULL) THEN
   SELECT COUNT(*)
   INTO   is_valid
   FROM   switches
   WHERE  switches.dswitch <= ad_switch AND NVL(switches.descape, TO_DATE(300001, 'YYYYMM')) >= ad_switch AND switches.nswitch = an_switch;
  ELSE
   SELECT COUNT(*)
   INTO   is_valid
   FROM   switches
   WHERE  switches.dswitch <= ad_switch AND switches.descape >= ad_switch AND switches.dswitch <= ad_escape AND switches.descape >= ad_escape
          AND switches.nswitch = an_switch;
  END IF;

  IF (is_valid <> 0) THEN
   raise_application_error(-20001, 'Недопустимый интервал переключения.');
  END IF;

--common_pg.userid_f
  INSERT INTO switches
              (ID, nswitch, dswitch, mid, erm, edm, q1m, q2m, q3m, q4m, denter, user_id, descape, erme, edme, q1me, q2me, q3me, q4me, denterret, user_idret)
  VALUES      (an_id, an_switch, ad_switch, an_mid, an_erm, an_edm, an_q1m, an_q2m, an_q3m, an_q4m, date_sw, inpuser_id, ad_escape, an_ermlast, an_edmlast,
               an_q1last, an_q2last, an_q3last, an_q4last, date_sl, retuser_id);

  DELETE FROM halfhourold
  WHERE       mid = an_mid AND(nsource BETWEEN 30 AND 49) AND date_time > ad_switch
              AND date_time <= NVL(util_pg.ceilhh24_2(ad_escape), TO_DATE(300001, 'YYYYMM'));

  INSERT INTO halfhourold
              (mid, date_time, nsource, nswitch, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, nkc, vqm)
   (SELECT   an_mid, date_time, DECODE(TRUNC((MIN(nsource) + 10) / 20), 1, MIN(nsource) + 20, DECODE(MAX(nsource), 59, 39, 30)) nsource, an_switch, SUM(er) er,
             SUM(ed) ed, SUM(q1) q1, SUM(q2) q2, SUM(q3) q3, SUM(q4) q4, MAX(erm) erm, MAX(edm) edm, MAX(q1m) q1m, MAX(q2m) q2m, MAX(q3m) q3m, MAX(q4m) q4m,
             MAX(nkc) nkc, qm_pg.sbt(qm_pg.sbt(NVL(MAX(vqm), qm_pg.cv_okqm), 22, qm_pg.cn_ov), 19, qm_pg.cn_add_ok)
    FROM     halfhour
    WHERE    mid = an_switch AND nswitch IS NULL AND date_time > ad_switch AND date_time <= NVL(util_pg.ceilhh24_2(ad_escape), TO_DATE(300001, 'YYYYMM'))
    GROUP BY mid, date_time,decode(nsource,9,9,19,9,29,9,39,9,49,9,59,9,10));

  file_pg.startbyevents_p(43, an_id, ad_switch);

  IF ad_escape IS NOT NULL THEN
   file_pg.startbyevents_p(44, an_id, ad_escape);
  END IF;

  admin_pg.fiscal_p(gn_task_code, 1,
      'Введено переключение ОВ '
   || util_pg.node_path_f(an_switch, 'points', 'mid', 'parent')
   || ' с '
   || TO_CHAR(ad_switch, 'dd.mm.yyyy hh24:mi')
   || ' на точку '
   || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001,
       'switches_pg.insupd_p: Ошибка ввода переключения ОВ. mid='
    || an_mid
    || ' nswitch='
    || an_switch
    || ' dswitch='''
    || TO_CHAR(ad_switch, 'DD.MM.YYYY HH24:MI:SS')
    || ''''
    || CHR(10)
    || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Процедура вставки
 PROCEDURE ins_p(
 an_switch NUMBER,                                                                                                                                       --Ид ОВ
                  ad_switch DATE,                                                                                                            --Дата переключения
                                 ad_escape DATE, an_mid NUMBER,                                                                                       --Ид точки
                                                               an_erm NUMBER,                                                                     --Показание ОВ
                                                                             an_edm NUMBER,                                                       --Показание ОВ
                                                                                           an_q1m NUMBER,                                         --Показание ОВ
                                                                                                         an_q2m NUMBER,                           --Показание ОВ
                                                                                                                       an_q3m NUMBER,             --Показание ОВ
 an_q4m NUMBER,                                                                                                                                   --Показание ОВ
               an_ermlast NUMBER, an_edmlast NUMBER, an_q1last NUMBER, an_q2last NUMBER, an_q3last NUMBER, an_q4last NUMBER, an_id OUT NUMBER        --Ид строки
 ) IS
  userret             NUMBER;
  dateret             DATE;
 BEGIN
  userret := common_pg.userid_f;
  dateret := SYSDATE;

  IF (ad_escape IS NULL) THEN
   userret := NULL;
   dateret := NULL;
  END IF;

  insupd_p(an_switch, ad_switch, ad_escape, an_mid, an_erm, an_edm, an_q1m, an_q2m, an_q3m, an_q4m, an_ermlast, an_edmlast, an_q1last, an_q2last, an_q3last,
   an_q4last, userret, common_pg.userid_f, SYSDATE, dateret, an_id);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления данных
 PROCEDURE upd_p(
 an_id NUMBER,                                                                                                                                       --Ид строки
              an_switch NUMBER, ad_switch DATE,                                                                                              --Дата переключения
                                               ad_switchlast DATE, an_mid NUMBER,                                                                     --Ид точки
                                                                                 an_erm NUMBER,                                                   --Показание ОВ
                                                                                               an_edm NUMBER,                                     --Показание ОВ
                                                                                                             an_q1m NUMBER,                       --Показание ОВ
                                                                                                                           an_q2m NUMBER,         --Показание ОВ
 an_q3m NUMBER,                                                                                                                                   --Показание ОВ
               an_q4m NUMBER,                                                                                                                     --Показание ОВ
                             an_ermlast NUMBER, an_edmlast NUMBER, an_q1last NUMBER, an_q2last NUMBER, an_q3last NUMBER, an_q4last NUMBER
 ) IS
  ln_id               NUMBER DEFAULT an_id;
  old_user_inp        NUMBER;
  old_user_ret        NUMBER;
  old_date_inp        DATE;
  old_date_ret        DATE;
  old_date_sw         DATE;
  old_date_sl         DATE;
 BEGIN
  SELECT s.user_id, s.user_idret, s.dswitch, s.descape, s.denter, s.denterret
  INTO   old_user_inp, old_user_ret, old_date_inp, old_date_ret, old_date_sw, old_date_sl
  FROM   switches s
  WHERE  s.ID = an_id;

  IF (old_date_inp <> ad_switch) THEN
   old_date_inp := ad_switch;
   old_user_inp := common_pg.userid_f;
   old_date_sw := SYSDATE;
  END IF;

  IF (old_date_ret <> ad_switchlast) OR((old_date_ret IS NULL) AND(NOT ad_switchlast IS NULL)) OR((NOT old_date_ret IS NULL) AND(ad_switchlast IS NULL)) THEN
   old_date_ret := ad_switchlast;
   old_user_ret := common_pg.userid_f;
   old_date_sl := SYSDATE;
  END IF;

  del_p(ln_id);
  insupd_p(an_switch, old_date_inp, old_date_ret, an_mid, an_erm, an_edm, an_q1m, an_q2m, an_q3m, an_q4m, an_ermlast, an_edmlast, an_q1last, an_q2last,
   an_q3last, an_q4last, old_user_ret, old_user_inp, old_date_sw, old_date_sl, ln_id);
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p(an_id NUMBER                                                                                                                        --Ид строки
                             ) IS
  ln_switch           NUMBER;
  ln_mid              NUMBER;
  ld_switch           DATE;
  ld_escape           DATE;
 BEGIN
  SELECT MAX(nswitch), MAX(mid), MAX(dswitch), MAX(descape)
  INTO   ln_switch, ln_mid, ld_switch, ld_escape
  FROM   switches
  WHERE  ID = an_id;

  IF ln_switch IS NULL THEN
   RETURN;
  END IF;

  DELETE FROM switches
  WHERE       ID = an_id;

  DELETE FROM halfhourold
  WHERE       mid = ln_mid AND nswitch = ln_switch AND date_time > ld_switch AND date_time <= NVL(ld_escape, TO_DATE(300001, 'YYYYMM'));

  admin_pg.fiscal_p(gn_task_code, 3,
   'Удалено переключение ОВ ' || util_pg.node_path_f(ln_switch, 'points', 'mid', 'parent') || ' за ' || TO_CHAR(ld_switch, 'dd.mm.yyyy hh24:mi'));
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'switches_pg.del_p: Ошибка удаления переключения ОВ. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура расчета
 PROCEDURE meterings(
 an_switch NUMBER, ad_switch DATE, time1 OUT DATE, er1 OUT VARCHAR2, ed1 OUT VARCHAR2, q11 OUT VARCHAR2, q21 OUT VARCHAR2, q31 OUT VARCHAR2, q41 OUT VARCHAR2,
 time2 OUT DATE, er2 OUT VARCHAR2, ed2 OUT VARCHAR2, q12 OUT VARCHAR2, q22 OUT VARCHAR2, q32 OUT VARCHAR2, q42 OUT VARCHAR2
 ) IS
  lv_sep              VARCHAR2(8) DEFAULT SUBSTR(11 / 10, 2, 1);
 BEGIN
  time1 := util_pg.trunchh24_2(ad_switch);
  er1 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time1, 1, 0), ',', lv_sep), '.', lv_sep));
  ed1 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time1, 2, 0), ',', lv_sep), '.', lv_sep));
  q11 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time1, 3, 0), ',', lv_sep), '.', lv_sep));
  q21 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time1, 4, 0), ',', lv_sep), '.', lv_sep));
  q31 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time1, 5, 0), ',', lv_sep), '.', lv_sep));
  q41 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time1, 6, 0), ',', lv_sep), '.', lv_sep));

  IF ad_switch <> time1 THEN
   time2 := time1 + 1 / 48;
   er2 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time2, 1, 0), ',', lv_sep), '.', lv_sep));
   ed2 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time2, 2, 0), ',', lv_sep), '.', lv_sep));
   q12 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time2, 3, 0), ',', lv_sep), '.', lv_sep));
   q22 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time2, 4, 0), ',', lv_sep), '.', lv_sep));
   q32 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time2, 5, 0), ',', lv_sep), '.', lv_sep));
   q42 := TO_NUMBER(REPLACE(REPLACE(util_pg.get_meterage_vch2(an_switch, time2, 6, 0), ',', lv_sep), '.', lv_sep));
  END IF;
 END;

