 -- added by KAG 15.02.2010
 -- возвращает для точки нижние и верхние предупредительные границы по измерениям А+ А- R+ R-
 PROCEDURE read_pointlimits_p(an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT MAX(DECODE(a.nsort, -1, a.vvalue, NULL)) ermin, MAX(DECODE(a.nsort, -2, a.vvalue, NULL)) ermax, MAX(DECODE(a.nsort, -7, a.vvalue, NULL)) edmin,
          MAX(DECODE(a.nsort, -8, a.vvalue, NULL)) edmax, MAX(DECODE(a.nsort, -13, a.vvalue, NULL)) q1min, MAX(DECODE(a.nsort, -14, a.vvalue, NULL)) q1max,
          MAX(DECODE(a.nsort, -19, a.vvalue, NULL)) q3min, MAX(DECODE(a.nsort, -20, a.vvalue, NULL)) q3max
   FROM   addpointparamval a
   WHERE  a.mid = an_mid AND a.nsort IN(-1, -2, -7, -8, -13, -14, -19, -20);
 END;
