PACKAGE BODY synhron_pg IS
------------------------------------------------------------------------
--Пакет для синхронизации таблицы точек в разных базах
--VNB 07.08.2009
------------------------------------------------------------------------
 PROCEDURE main_p;

------------------------------------------------------------------------
  --Синхронизация БД
 PROCEDURE synhrondb(an_maket NUMBER, ad_date DATE) IS
 BEGIN
  main_p;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE main_p IS
  lv_base             VARCHAR2(256);
 BEGIN
  lv_base := util_pg.getparamvaluev_f(47);
  -- ln_midparent := util_pg.getparamvalue_f (48);
  -- ln_midchild := util_pg.getparamvalue_f (49);
  main_point_p(lv_base);
  main_groups_p(lv_base);
 END;

------------------------------------------------------------------------
 PROCEDURE main_point_p(av_base VARCHAR2)                                                                                        -- начальный узел дочерней базы
                                         IS
  ln_midparent        NUMBER;
  ln_midchild         NUMBER;
  ln_tag              NUMBER;
  cur_t               common_pg.tcur;
  cur_t1              common_pg.tcur;
  lv_cname            VARCHAR2(256);
  ln_cind             NUMBER;
  lv_short_name       VARCHAR2(256);
  lv_sqlpoints        VARCHAR2(2000);
  ln_lv               NUMBER;
  ln_parent           NUMBER;
  ln_testparent       NUMBER;
  ln_pmid             NUMBER;
  ln_test             NUMBER;
  lv_sql              VARCHAR2(4000);
 BEGIN
-------------------------------------------------------------Вставка вершин дерева точек
  FOR ct IN (SELECT a.nid
             FROM   dbmain a
             WHERE  a.ntype = 0) LOOP
--------------------------------------------------------------------------------
   lv_sql :=
       '  select level lv,g.mid,g.parent FROM points@'
    || av_base
    || ' g 
             connect by prior g.parent=g.mid and g.mid <>'||util_pg.cn_pntmid||' start with g.mid=:mid order by lv desc';

   OPEN cur_t1 FOR lv_sql using ct.nid;

   LOOP
    FETCH cur_t1
    INTO  ln_lv, ln_parent, ln_testparent;

    EXIT WHEN cur_t1%NOTFOUND;
    ln_pmid := 0;

    SELECT MAX(mid)
    INTO   ln_pmid
    FROM   points
    WHERE  nroot = ln_parent;

    IF ln_testparent <> util_pg.cn_pntmid THEN
     SELECT MAX(mid)
     INTO   ln_test
     FROM   points
     WHERE  nroot = ln_testparent;
    ELSE
     ln_test := util_pg.cn_pntmid;
    END IF;

    IF ln_pmid IS NULL THEN
     lv_sqlpoints := 'select name,ind, short_name,tag from points@' || av_base || ' p  where mid=:mid';

     OPEN cur_t FOR lv_sqlpoints using ln_parent;

     LOOP
      FETCH cur_t
      INTO  lv_cname, ln_cind, lv_short_name, ln_tag;

      EXIT WHEN cur_t%NOTFOUND;
      ins_p(ln_parent, ln_test, lv_cname, ln_cind, lv_short_name, av_base, ln_tag, ln_pmid);
      COMMIT;
     END LOOP;

     CLOSE cur_t;
    ELSE
     IF ln_test IS NOT NULL THEN
      UPDATE points
      SET PARENT = ln_test
      WHERE  nroot = ln_parent;
     END IF;
    END IF;
   END LOOP;

   ln_midparent := ct.nid;
   ln_midchild := 0;

   SELECT MAX(mid)
   INTO   ln_midchild
   FROM   points
   WHERE  nroot = ln_midparent;

-------------------------------------------------------------Вставка  точек
   IF av_base IS NOT NULL AND ln_midparent > 0 AND ln_midchild > 0 THEN
    ins_upd_point_p(av_base, ln_midparent, ln_midchild);
   END IF;
  END LOOP;

  CLOSE cur_t1;
------------------------------------------end;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE main_groups_p(av_base VARCHAR2)                                                                                       -- начальный узел дочерней базы
                                          IS
  ln_midparent        NUMBER;
  ln_midchild         NUMBER;
  ln_gid              NUMBER;
  lv_sql              VARCHAR2(4000);
  cur_t2              common_pg.tcur;
  ln_lv               NUMBER;
  ln_testgid          NUMBER;
  ln_testparent       NUMBER;
  ln_bgid             NUMBER;
 BEGIN
  FOR lc IN (SELECT nroot3
             FROM   GROUPS
             WHERE  PARENT IS NULL AND nroot3 IS NOT NULL
             MINUS
             SELECT a.nid
             FROM   dbmain a
             WHERE  a.ntype = 1) LOOP
   SELECT MAX(gid)
   INTO   ln_gid
   FROM   GROUPS
   WHERE  nroot3 = lc.nroot3;

   IF ln_gid IS NOT NULL THEN
    editgroups_pg.del_p(ln_gid);
   END IF;
  END LOOP;

---------------------------------------------------------Вставка вершин дерева групп
  FOR ct1 IN (SELECT a.nid
              FROM   dbmain a
              WHERE  a.ntype = 1) LOOP
--------------------------------------------------------------------------------------
   lv_sql :=
       'select level lv,g.gid,g.parent FROM groups@'
    || av_base
    || ' g 
             connect by prior g.parent=g.gid  start with g.gid=:gid order by lv desc ';

   OPEN cur_t2 FOR lv_sql using ct1.nid;

   LOOP
    FETCH cur_t2
    INTO  ln_lv, ln_testgid, ln_testparent;

    EXIT WHEN cur_t2%NOTFOUND;
    ln_bgid := 0;

    SELECT MAX(gid)
    INTO   ln_bgid
    FROM   GROUPS
    WHERE  nroot3 = ln_testgid;

    IF ln_bgid IS NULL THEN
     ins_group(av_base, ln_testgid, ln_bgid);
    END IF;
   END LOOP;

   CLOSE cur_t2;

--------------------------------------------------------------------------
   ln_midparent := ct1.nid;
   ln_midchild := 0;

   SELECT MAX(gid)
   INTO   ln_midchild
   FROM   GROUPS
   WHERE  nroot3 = ln_midparent;

   IF ln_midchild IS NULL THEN
    ins_group(av_base, ln_midparent, ln_midchild);
   END IF;

   IF av_base IS NOT NULL AND ln_midparent > 0 AND ln_midchild > 0 THEN
    ins_upd_groups_p(av_base, ln_midparent, ln_midchild);
   END IF;
  END LOOP;
--------------------------------------end;
 END;

--------------------------------------------------------------------------------------------
 PROCEDURE ins_upd_point_p(av_base VARCHAR2,                                                                                          -- база с которой копируем
                                            an_midparent NUMBER,                                                              --начальный узел родительской базы
                                                                an_midchild NUMBER)                                              -- начальный узел дочерней базы
                                                                                   IS
  ln_mid              NUMBER;
--lv_name VARCHAR2(500);
--ln_ind NUMBER;
  ln_tag              NUMBER;
  ln_nroot            NUMBER;
  ln_parent           NUMBER DEFAULT an_midchild;
  cur_t               common_pg.tcur;
  cur_feeders         common_pg.tcur;
------------------------------ points
  ln_cmid             NUMBER;
  ln_cparent          NUMBER;
  lv_cname            VARCHAR2(500);
  ln_cind             NUMBER;
  lv_short_name       VARCHAR2(500);
  ln_level            NUMBER;
  ln_order            NUMBER;
-----------------------------------feeders
  lv_smart            VARCHAR2(100);
  lv_q1234            VARCHAR2(100);
  lv_cellnum          VARCHAR2(100);
  ln_power            NUMBER;
  ln_current1         NUMBER;
  ln_current2         NUMBER;
  ln_kc               NUMBER;
  ln_power2           NUMBER;
  ln_metkc            NUMBER;
  ln_nabc             NUMBER;
  ln_nswitch          NUMBER;
  ln_nworkinghours    NUMBER;
  ln_nfullhours       NUMBER;
  ln_ntcurrent        NUMBER;
  ln_ntpower          NUMBER;
  lv_vcode            VARCHAR2(100);
  ln_nclasstt         NUMBER;
  ln_nclasstn         NUMBER;
  ln_canal            NUMBER;
  ln_rescanal         NUMBER;
  lv_vinfo            VARCHAR2(100);
  lv_vimportcode      VARCHAR2(100);
-------------------------------------------------meters
  lv_mname            VARCHAR2(100);
  ln_mposition        NUMBER;
  ln_mentype          NUMBER;
  lv_msmart           VARCHAR2(100);
  lv_mtrsn            VARCHAR2(100);
  ld_mdate_time       DATE;
  ln_mdigits          NUMBER;
  lv_mtype            VARCHAR2(100);
  ln_mcurrent         NUMBER;
  ln_mpower           NUMBER;
  ln_mconst           NUMBER;
  ln_mclass           NUMBER;
  ln_myear            NUMBER;
  ln_mquarter         NUMBER;
  ln_mkc              NUMBER;
  ln_midtest          NUMBER;
---------------------------------------------------------------
  lv_sqldel           VARCHAR2(4000);
  lv_sqlpoints        VARCHAR2(4000);
  lv_sqlfeeders       VARCHAR2(4000);
  lv_sql              VARCHAR2(4000);
-------------------------------------------------
 BEGIN
  UPDATE points
  SET nroot = an_midparent
  WHERE  mid = an_midchild;

  COMMIT;
  lv_sqldel := ' select nroot from  points p
           MINUS
           select  mid from points@' || av_base;

  OPEN cur_t FOR lv_sqldel;

  LOOP
   FETCH cur_t
   INTO  ln_nroot;

   EXIT WHEN cur_t%NOTFOUND;

   -- Loop
   SELECT COUNT(*)
   INTO   ln_mid
   FROM   points
   WHERE  nroot = ln_nroot AND nroot IS NOT NULL;

   IF (ln_mid > 0) THEN
    SELECT MAX(mid)
    INTO   ln_mid
    FROM   points
    WHERE  nroot = ln_nroot;

    editfeeders_pg.del_p(ln_mid);
   END IF;
  END LOOP;

  CLOSE cur_t;

  lv_sqlpoints :=
      'select kk.lb,kk.mid,kk.parent,kk.name,kk.ind, kk.short_name  from
 ( select level lb, mid,parent,name,ind, short_name from points@'
   || av_base
   || ' p
     connect by prior mid=parent start with parent=:an_midparent  
  MINUS
   select tt.lb, tt.nroot, ll.nroot  parent, tt.name,tt.ind, tt.short_name
   from
   (select mid, nroot from points)ll,
  (select level lb,nroot,parent,name,ind
  , short_name
  from  points p connect by prior mid=parent  start with parent=:an_midchild)tt
  where ll.mid(+)=tt.parent
  )kk
  order by kk.lb,kk.ind ';

  OPEN cur_t FOR lv_sqlpoints using an_midparent,an_midchild;

  LOOP
   FETCH cur_t
   INTO  ln_level, ln_cmid, ln_cparent, lv_cname, ln_cind, lv_short_name;

   EXIT WHEN cur_t%NOTFOUND;

   --

   -- Loop
   SELECT points_seq.NEXTVAL
   INTO   ln_mid
   FROM   DUAL;

   SELECT MAX(mid)
   INTO   ln_parent
   FROM   points
   WHERE  nroot = ln_cparent;

   IF (ln_cmid <> an_midparent) THEN
    UPDATE points
    SET PARENT = ln_parent,
        NAME = lv_cname,
        cod = 0,
        ind = ln_cind,
        short_name = lv_short_name
    WHERE  nroot = ln_cmid;

    IF SQL%ROWCOUNT = 0 THEN
     EXECUTE IMMEDIATE ' select tag, norder  from points@' || av_base || ' where mid=:mid'
     INTO              ln_tag, ln_order USING ln_cmid;

     INSERT INTO points
                 (mid, PARENT, NAME, cod, ind, nroot, short_name, tag, norder)
     VALUES      (ln_mid, ln_parent, lv_cname, 0, ln_cind, ln_cmid, lv_short_name, ln_tag, ln_order);

-----------------------------------------------------------------------
     lv_sqlfeeders :=
         ' select smart,q1234,cellnum,power,current1,current2,kc,power2,metkc,nabc,nswitch,nworkinghours,
           nfullhours,NTCURRENT,ntpower,VCODE,nclasstt,nclasstn,canal,rescanal,vinfo,vimportcode
            from feeders@'
      || av_base
      || ' where  mid=:mid';

     OPEN cur_feeders FOR lv_sqlfeeders using ln_cmid;

     LOOP
      FETCH cur_feeders
      INTO  lv_smart, lv_q1234, lv_cellnum, ln_power, ln_current1, ln_current2, ln_kc, ln_power2, ln_metkc, ln_nabc, ln_nswitch, ln_nworkinghours,
            ln_nfullhours, ln_ntcurrent, ln_ntpower, lv_vcode, ln_nclasstt, ln_nclasstn, ln_canal, ln_rescanal, lv_vinfo, lv_vimportcode;

      EXIT WHEN cur_feeders%NOTFOUND;

      INSERT INTO feeders
                  (mid, smart, q1234, cellnum, POWER, current1, current2, kc, power2, metkc, nabc, nswitch, nworkinghours, nfullhours, ntcurrent, ntpower,
                   vcode, nclasstt, nclasstn, canal, rescanal, vinfo, vimportcode)
      VALUES      (ln_mid, lv_smart, lv_q1234, lv_cellnum, ln_power, ln_current1, ln_current2, ln_kc, ln_power2, ln_metkc, ln_nabc, ln_nswitch,
                   ln_nworkinghours, ln_nfullhours, ln_ntcurrent, ln_ntpower, lv_vcode, ln_nclasstt, ln_nclasstn, ln_canal, ln_rescanal, lv_vinfo,
                   lv_vimportcode);
     -- admin_pg.fiscal_p (gn_task_code, 1, 'Добавлена точка учета ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
     END LOOP;

     CLOSE cur_feeders;

---------------------------------------------------------------------------------------------
     INSERT INTO curr_power
                 (mid, date_time, obsolete)
     VALUES      (ln_mid, SYSDATE, 1);

     COMMIT;
    END IF;
   END IF;

   COMMIT;
  END LOOP;

  CLOSE cur_t;

 -- изменение  feeders если есть разница
-- FOR lc IN (
  lv_sqlfeeders :=
      'select a.mid,  a.smart,a.q1234,a.cellnum,a.power, a.current1,a.current2,a.kc,a.power2,a.metkc,a.nabc,a.nswitch,a.nworkinghours,
    a.nfullhours,a.NTCURRENT,a.ntpower,a.VCODE,a.nclasstt,a.nclasstn
    from feeders@'
   || av_base
   || ' a 
    WHERE a.mid in(select mid from points@'
   || av_base
   || ' p
     connect by prior mid=parent start with parent=:an_midparent)
     MINUS
   select p.nroot, f.smart,f.q1234,f.cellnum, f.power, f.current1,f.current2,f.kc,f.power2,f.metkc,f.nabc,f.nswitch,f.nworkinghours,
    f.nfullhours,f.NTCURRENT,f.ntpower,f.VCODE,f.nclasstt,f.nclasstn
    from feeders f,  points p  where p.mid=f.mid(+)
     and p.mid in 
    (select mid  from  points p connect by prior mid=parent  start with parent=:an_midchild)';
  OPEN cur_t FOR lv_sqlfeeders using an_midparent,an_midchild;

  LOOP
   FETCH cur_t
   INTO  ln_cmid, lv_smart, lv_q1234, lv_cellnum, ln_power, ln_current1, ln_current2, ln_kc, ln_power2, ln_metkc, ln_nabc, ln_nswitch, ln_nworkinghours,
         ln_nfullhours, ln_ntcurrent, ln_ntpower, lv_vcode, ln_nclasstt, ln_nclasstn;

   EXIT WHEN cur_t%NOTFOUND;

   -- LOOP
   IF (ln_cmid <> an_midparent) THEN
    UPDATE feeders
    SET smart = lv_smart,
        q1234 = lv_q1234,
        cellnum = lv_cellnum,
        POWER = ln_power,
        current1 = ln_current1,
        current2 = ln_current2,
        kc = ln_kc,
        power2 = ln_power2,
        metkc = ln_metkc,
        nabc = ln_nabc,
        nswitch = ln_nswitch,
        nworkinghours = ln_nworkinghours,
        nfullhours = ln_nfullhours,
        ntcurrent = ln_ntcurrent,
        ntpower = ln_ntpower,
        vcode = lv_vcode,
        nclasstt = ln_nclasstt,
        nclasstn = ln_nclasstn
    WHERE  mid = (SELECT mid
                  FROM   points
                  WHERE  nroot = ln_cmid);
   END IF;
  END LOOP;

  COMMIT;

  CLOSE cur_t;

  -- изменение  meters если есть разница
  lv_sql :=
      'SELECT  a.mid, a.name, a.position, a.entype, a.smart, a.mtrsn,
       a.date_time, a.digits, a.mtype, a.mcurrent, a.mpower, a.mconst,
       a.mclass, a.myear, a.mquarter, a.kc
  FROM meters@'
   || av_base
   || ' a
   WHERE a.mid in(select mid from points@'
   || av_base
   || ' p
     connect by prior mid=parent start with parent=:an_midparent)
  MINUS
 SELECT p.nroot, a.name, a.position, a.entype, a.smart, a.mtrsn,
       a.date_time, a.digits, a.mtype, a.mcurrent, a.mpower, a.mconst,
       a.mclass, a.myear, a.mquarter, a.kc
  FROM meters a,  points p  where p.mid=a.mid(+)
  and p.mid in 
  (select mid  from  points p connect by prior mid=parent  start with parent=:an_midchild)';

  OPEN cur_t FOR lv_sql using an_midparent,an_midchild;

  ln_midtest := 0;

  LOOP
   FETCH cur_t
   INTO  ln_cmid, lv_mname, ln_mposition, ln_mentype, lv_msmart, lv_mtrsn, ld_mdate_time, ln_mdigits, lv_mtype, ln_mcurrent, ln_mpower, ln_mconst, ln_mclass,
         ln_myear, ln_mquarter, ln_mkc;

   EXIT WHEN cur_t%NOTFOUND;
   ln_midtest := ln_cmid;

   IF (ln_cmid <> an_midparent AND ln_midtest <> ln_cmid) THEN
    DELETE FROM meters
    WHERE       mid = (SELECT mid
                       FROM   points
                       WHERE  nroot = ln_cmid);

    SELECT MAX(mid)
    INTO   ln_mid
    FROM   points
    WHERE  nroot = ln_cmid;

    -- FOR lc2 IN (
    lv_sqlfeeders :=
        ' SELECT name, position, entype, smart, mtrsn,
               date_time, digits, mtype, mcurrent, mpower, mconst,
               mclass, myear, mquarter, kc from meters@'
     || av_base
     || ' where mid=:ln_cmid';

    --) LOOP
    OPEN cur_feeders FOR lv_sqlfeeders using ln_cmid;

    LOOP
     FETCH cur_feeders
     INTO  lv_mname, ln_mposition, ln_mentype, lv_msmart, lv_mtrsn, ld_mdate_time, ln_mdigits, lv_mtype, ln_mcurrent, ln_mpower, ln_mconst, ln_mclass,
           ln_myear, ln_mquarter, ln_mkc;

     EXIT WHEN cur_feeders%NOTFOUND;

     INSERT INTO meters
                 (ID, mid, NAME, POSITION, entype, smart, mtrsn, date_time, digits, mtype, mcurrent, mpower, mconst, mclass, myear, mquarter, kc)
     VALUES      (points_seq.NEXTVAL, ln_mid, lv_mname, ln_mposition, ln_mentype, lv_msmart, lv_mtrsn, ld_mdate_time, ln_mdigits, lv_mtype, ln_mcurrent,
                  ln_mpower, ln_mconst, ln_mclass, ln_myear, ln_mquarter, ln_mkc);
    END LOOP;

    COMMIT;

    CLOSE cur_feeders;
   END IF;
  END LOOP;

  COMMIT;

  CLOSE cur_t;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'SYNHRON_PG.ins_upd_point_p: Ошибка синхронизации с БД ''' || av_base || '''. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------
 PROCEDURE ins_p(
 an_cmid NUMBER, an_cparent NUMBER, av_cname VARCHAR2, an_cind NUMBER, av_short_name VARCHAR2, av_base VARCHAR2, an_tag NUMBER, an_mid OUT NUMBER
 ) IS
  ln_parent           NUMBER;
  lv_sqlfeeders       VARCHAR2(4000);
-----------------------------------feeders
  lv_smart            VARCHAR2(100);
  lv_q1234            VARCHAR2(100);
  lv_cellnum          VARCHAR2(100);
  ln_power            NUMBER;
  ln_current1         NUMBER;
  ln_current2         NUMBER;
  ln_kc               NUMBER;
  ln_power2           NUMBER;
  ln_metkc            NUMBER;
  ln_nabc             NUMBER;
  ln_nswitch          NUMBER;
  ln_nworkinghours    NUMBER;
  ln_nfullhours       NUMBER;
  ln_ntcurrent        NUMBER;
  ln_ntpower          NUMBER;
  lv_vcode            VARCHAR2(100);
  ln_nclasstt         NUMBER;
  ln_nclasstn         NUMBER;
  ln_canal            NUMBER;
  ln_rescanal         NUMBER;
  lv_vinfo            VARCHAR2(100);
  lv_vimportcode      VARCHAR2(100);
  cur_feeders         common_pg.tcur;
 BEGIN
  -- Loop
  SELECT points_seq.NEXTVAL
  INTO   an_mid
  FROM   DUAL;

  INSERT INTO points
              (mid, PARENT, NAME, cod, ind, nroot, short_name, tag)
  VALUES      (an_mid, an_cparent, av_cname, 0, an_cind, an_cmid, av_short_name, an_tag);

-----------------------------------------------------------------------
  lv_sqlfeeders :=
      ' select smart,q1234,cellnum,power,current1,current2,kc,power2,metkc,nabc,nswitch,nworkinghours,
           nfullhours,NTCURRENT,ntpower,VCODE,nclasstt,nclasstn,canal,rescanal,vinfo,vimportcode
            from feeders@'
   || av_base
   || ' where  mid=:an_cmid';

  OPEN cur_feeders FOR lv_sqlfeeders using an_cmid;

  LOOP
   FETCH cur_feeders
   INTO  lv_smart, lv_q1234, lv_cellnum, ln_power, ln_current1, ln_current2, ln_kc, ln_power2, ln_metkc, ln_nabc, ln_nswitch, ln_nworkinghours, ln_nfullhours,
         ln_ntcurrent, ln_ntpower, lv_vcode, ln_nclasstt, ln_nclasstn, ln_canal, ln_rescanal, lv_vinfo, lv_vimportcode;

   EXIT WHEN cur_feeders%NOTFOUND;

   INSERT INTO feeders
               (mid, smart, q1234, cellnum, POWER, current1, current2, kc, power2, metkc, nabc, nswitch, nworkinghours, nfullhours, ntcurrent, ntpower, vcode,
                nclasstt, nclasstn, canal, rescanal, vinfo, vimportcode)
   VALUES      (an_mid, lv_smart, lv_q1234, lv_cellnum, ln_power, ln_current1, ln_current2, ln_kc, ln_power2, ln_metkc, ln_nabc, ln_nswitch, ln_nworkinghours,
                ln_nfullhours, ln_ntcurrent, ln_ntpower, lv_vcode, ln_nclasstt, ln_nclasstn, ln_canal, ln_rescanal, lv_vinfo, lv_vimportcode);
  -- admin_pg.fiscal_p (gn_task_code, 1, 'Добавлена точка учета ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
  END LOOP;

  CLOSE cur_feeders;

---------------------------------------------------------------------------------------------
  INSERT INTO curr_power
              (mid, date_time, obsolete)
  VALUES      (an_mid, SYSDATE, 1);

  COMMIT;
 END;

---------------------------------------------------------------------------------------------------------
 PROCEDURE ins_group(av_base VARCHAR2,                                                                                                -- база с которой копируем
                                      an_midparent NUMBER,                                                                    --начальный узел родительской базы
                                                          an_midchild OUT NUMBER)                                                -- начальный узел дочерней базы
                                                                                 IS
  ln_gid              NUMBER;
  lv_name             VARCHAR2(512);
  lv_short_name       VARCHAR2(512);
  ln_mid              NUMBER;
  lv_inverted         VARCHAR2(10);
  ln_group_total      VARCHAR2(10);
  ln_nemergencyreserve NUMBER;
  ln_ntechnologyreserve NUMBER;
  lv_vparam           VARCHAR2(512);
  ln_npartly          NUMBER;
  ln_nfromperiod      NUMBER;
  ln_ntillperiod      NUMBER;
  ln_nkc              NUMBER;
  ln_nroot1           NUMBER;
  ln_nroot2           NUMBER;
  cur_t               common_pg.tcur;
  lv_sqlgroups        VARCHAR2(4000);
  ln_parent           NUMBER;
  ln_gparent          NUMBER;
 BEGIN
  lv_sqlgroups :=
      'SELECT a.gid,a.parent,a.name, a.short_name, a.mid, a.inverted,
       a.group_total, 
       a.nemergencyreserve, a.ntechnologyreserve, 
       a.vparam, a.npartly, a.nfromperiod, a.ntillperiod,a.nroot1,a.nroot2,a.nkc
       FROM groups@'
   || av_base
   || '  a   where gid=:gid';

  OPEN cur_t FOR lv_sqlgroups using an_midparent;

  LOOP
   FETCH cur_t
   INTO  ln_gid, ln_parent, lv_name, lv_short_name, ln_mid, lv_inverted, ln_group_total, ln_nemergencyreserve, ln_ntechnologyreserve, lv_vparam, ln_npartly,
         ln_nfromperiod, ln_ntillperiod, ln_nroot1, ln_nroot2, ln_nkc;

   EXIT WHEN cur_t%NOTFOUND;

   SELECT groups_seq.NEXTVAL
   INTO   ln_gid
   FROM   DUAL;

   an_midchild := ln_gid;
   ln_gparent := NULL;

   SELECT MAX(gid)
   INTO   ln_gparent
   FROM   GROUPS
   WHERE  nroot3 = ln_parent;

   INSERT INTO GROUPS
               (gid, PARENT, NAME, short_name, mid, inverted, group_total, nroot1, nroot2, nroot3, nemergencyreserve, ntechnologyreserve, vparam, npartly,
                nfromperiod, ntillperiod, nkc)
   VALUES      (an_midchild, ln_gparent, lv_name, lv_short_name, ln_mid, lv_inverted, ln_group_total, ln_nroot1, ln_nroot2, an_midparent, ln_nemergencyreserve,
                ln_ntechnologyreserve, lv_vparam, ln_npartly, NVL(ln_nfromperiod, 190001), ln_ntillperiod, ln_nkc);

   /* VALUES (an_midchild, NULL, lv_name, lv_short_name, ln_mid,
            lv_inverted,ln_group_total,
            NULL,an_midparent, ln_nemergencyreserve, ln_ntechnologyreserve, lv_vparam, ln_npartly,
             NVL(ln_nfromperiod, 190001),
            ln_ntillperiod);*/
   COMMIT;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'editgroups_pg.ins_p: Ошибка вставки группы учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_upd_groups_p(av_base VARCHAR2,                                                                                         -- база с которой копируем
                                             an_midparent NUMBER,                                                             --начальный узел родительской базы
                                                                 an_midchild NUMBER)                                             -- начальный узел дочерней базы
                                                                                    IS
  ln_gid              NUMBER;
  ln_cgid             NUMBER;
  lv_name             VARCHAR2(512);
  ln_parent           NUMBER;
  ln_cparent          NUMBER;
  lv_short_name       VARCHAR2(512);
  ln_mid              NUMBER;
  ln_amid             NUMBER;
  ln_test             NUMBER;
  lv_inverted         VARCHAR2(10);
  ln_group_total      VARCHAR2(10);
  ln_nemergencyreserve NUMBER;
  ln_ntechnologyreserve NUMBER;
  lv_vparam           VARCHAR2(512);
  ln_npartly          NUMBER;
  ln_nfromperiod      NUMBER;
  ln_ntillperiod      NUMBER;
  ln_nkc              NUMBER;
  ln_nroot1           NUMBER;
  ln_nroot2           NUMBER;
  ln_lev              NUMBER;
  ln_agid             NUMBER;
  cur_t               common_pg.tcur;
  lv_sqlgroups        VARCHAR2(4000);
  lv_sqldel           VARCHAR2(4000);
  ln_nroot3           NUMBER;
 BEGIN
  lv_sqldel :=
      ' select nroot3 from groups where parent =
                   (select gid from groups where nroot3='
   || an_midparent
   || ') 
               MINUS
               SELECT gid  FROM groups@'
   || av_base
   || '  where  parent =:an_midparent';

  OPEN cur_t FOR lv_sqldel using an_midparent;

  LOOP
   FETCH cur_t
   INTO  ln_nroot3;

   EXIT WHEN cur_t%NOTFOUND;

   SELECT MAX(gid)
   INTO   ln_agid
   FROM   GROUPS
   WHERE  nroot3 = ln_nroot3;

   IF ln_agid IS NOT NULL THEN
    editgroups_pg.del_p(ln_agid);
   END IF;
  END LOOP;

  lv_sqlgroups :=
      ' SELECT level lb,g.gid,g.parent,g.name, g.short_name,g.mid,  g.inverted,
                g.group_total, 
                g.nemergencyreserve, g.ntechnologyreserve, 
                g.vparam, g.npartly, g.nfromperiod, g.ntillperiod,g.nroot1,g.nroot2,g.nkc
                FROM groups@'
   || av_base
   || '  g  
                connect by prior g.gid=g.parent start with g.parent=:an_midparent1
                 MINUS
                select  tt.lb, tt.nroot3, ll.nroot3  parent, tt.name, tt.short_name,tt.mid,tt.inverted,
                tt.group_total, 
                tt.nemergencyreserve, tt.ntechnologyreserve, 
                tt.vparam, tt.npartly, tt.nfromperiod, tt.ntillperiod,tt.nroot1,tt .nroot2,tt.nkc
                 from
                (select gid, nroot3 from groups )ll,
                (select level lb,nroot3,parent,name, a.short_name,(select nroot from points where mid=a.mid)mid, a.inverted,
                a.group_total, 
                a.nemergencyreserve, a.ntechnologyreserve, 
                a.vparam, a.npartly, a.nfromperiod, a.ntillperiod,a.nroot1,a.nroot2,a.nkc
                 from  groups a connect by prior gid=parent start with parent=(select gid from groups where nroot3= :an_midparent2)tt
                where ll.gid(+)=tt.parent
                order by lb ';

  OPEN cur_t FOR lv_sqlgroups using an_midparent,an_midparent;

  LOOP
   FETCH cur_t
   INTO  ln_lev, ln_cgid, ln_cparent, lv_name, lv_short_name, ln_mid, lv_inverted, ln_group_total, ln_nemergencyreserve, ln_ntechnologyreserve, lv_vparam,
         ln_npartly, ln_nfromperiod, ln_ntillperiod, ln_nroot1, ln_nroot2, ln_nkc;

   EXIT WHEN cur_t%NOTFOUND;
   ln_amid := NULL;
   ln_test := 0;

   IF ln_mid IS NOT NULL THEN
    SELECT MAX(mid)
    INTO   ln_amid
    FROM   points
    WHERE  nroot = ln_mid;

    IF ln_amid IS NULL THEN
     ln_test := 1;
    END IF;
   END IF;

   IF ln_test = 0 THEN
    SELECT groups_seq.NEXTVAL
    INTO   ln_gid
    FROM   DUAL;

    SELECT MAX(gid)
    INTO   ln_parent
    FROM   GROUPS
    WHERE  nroot3 = ln_cparent;

    UPDATE GROUPS
    SET PARENT = ln_parent,
        NAME = lv_name,
        short_name = lv_short_name,
        inverted = lv_inverted,
        group_total = ln_group_total,
        nemergencyreserve = ln_nemergencyreserve,
        ntechnologyreserve = ln_ntechnologyreserve,
        vparam = lv_vparam,
        npartly = ln_npartly,
        nfromperiod = NVL(ln_nfromperiod, 190001),
        ntillperiod = ln_ntillperiod,
        nroot1 = ln_nroot1,
        nroot2 = ln_nroot2,
        nkc = ln_nkc
    WHERE  nroot3 = ln_cgid;

    IF SQL%ROWCOUNT = 0 THEN
     INSERT INTO GROUPS
                 (gid, PARENT, NAME, short_name, mid, inverted, group_total, nroot1, nroot2, nroot3, nemergencyreserve, ntechnologyreserve, vparam, npartly,
                  nfromperiod, ntillperiod, nkc)
     VALUES      (ln_gid, ln_parent, lv_name, lv_short_name, ln_amid, lv_inverted, ln_group_total, ln_nroot1, ln_nroot2, ln_cgid, ln_nemergencyreserve,
                  ln_ntechnologyreserve, lv_vparam, ln_npartly, NVL(ln_nfromperiod, 190001), ln_ntillperiod, ln_nkc);
    END IF;
   END IF;

   COMMIT;
  END LOOP;
 END;
--------------------------------------------------------------------------------------------------------------------------
END;
/


