CREATE OR REPLACE 
PACKAGE BODY tablespaceusage_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет Tablespace usage
  -- дата создания 20/09/2011 Морозов Н.М.
------------------------------------------------------------------------------------------------------------------------
/*
grant select on dba_free_space to RYDA;
grant select on dba_data_files to RYDA;
grant select on dba_temp_files to RYDA;
grant select on v_$Temp_extent_pool to RYDA;
grant select on v_$TEMP_SPACE_HEADER to RYDA;
*/
------------------------------------------------------------------------------------------------------------------------
 --Процедура получения таблицы использования tablespace
 PROCEDURE get_tablespace_usage(acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR 'SELECT   a.tablespace_name,
                  ROUND (a.bytes_alloc / 1024 / 1024) megs_alloc,
                  ROUND (NVL (b.bytes_free, 0) / 1024 / 1024) megs_free,
                  ROUND ((a.bytes_alloc - NVL (b.bytes_free, 0)) / 1024 / 1024
                        ) megs_used,
                  ROUND ((NVL (b.bytes_free, 0) / a.bytes_alloc) * 100
                        ) pct_free,
                    100
                  - ROUND ((NVL (b.bytes_free, 0) / a.bytes_alloc) * 100)
                                                                    pct_used,
                  ROUND (maxbytes / 1048576) MAX,
                  ROUND (  (  (a.bytes_alloc - NVL (b.bytes_free, 0))
                            / 1024
                            / 1024
                           )
                         * 100
                         / (maxbytes / 1048576)
                        ) USAGE
             FROM (SELECT   f.tablespace_name, SUM (f.BYTES) bytes_alloc,
                            SUM (DECODE (f.autoextensible,
                                         ''YES'', f.maxbytes,
                                         ''NO'', f.BYTES
                                        )
                                ) maxbytes
                       FROM dba_data_files f
                   GROUP BY tablespace_name) a,
                  (SELECT   f.tablespace_name, SUM (f.BYTES) bytes_free
                       FROM dba_free_space f
                   GROUP BY tablespace_name) b
            WHERE a.tablespace_name = b.tablespace_name(+)
         UNION ALL
         SELECT   h.tablespace_name,
                  ROUND (SUM (h.bytes_free + h.bytes_used) / 1048576
                        ) megs_alloc,
                  ROUND (  SUM (  (h.bytes_free + h.bytes_used)
                                - NVL (p.bytes_used, 0)
                               )
                         / 1048576
                        ) megs_free,
                  ROUND (SUM (NVL (p.bytes_used, 0)) / 1048576) megs_used,
                  ROUND (  (  SUM (  (h.bytes_free + h.bytes_used)
                                   - NVL (p.bytes_used, 0)
                                  )
                            / SUM (h.bytes_used + h.bytes_free)
                           )
                         * 100
                        ) pct_free,
                    100
                  - ROUND (  (  SUM (  (h.bytes_free + h.bytes_used)
                                     - NVL (p.bytes_used, 0)
                                    )
                              / SUM (h.bytes_used + h.bytes_free)
                             )
                           * 100
                          ) pct_used,
                  ROUND (SUM (f.maxbytes) / 1048576) MAX,
                  ROUND (  (SUM (NVL (p.bytes_used, 0)) / 1048576)
                         * 100
                         / (SUM (f.maxbytes) / 1048576)
                        ) USAGE
             FROM SYS.v_$temp_space_header h,
                  SYS.v_$temp_extent_pool p,
                  dba_temp_files f
            WHERE p.file_id(+) = h.file_id
              AND p.tablespace_name(+) = h.tablespace_name
              AND f.file_id = h.file_id
              AND f.tablespace_name = h.tablespace_name
         GROUP BY h.tablespace_name
         ORDER BY 1';
 END;

------------------------------------------------------------------------------------------------------------------------
 --Процедура получения предупреждения об отсутствии возможности увеличения табл пространства При предупреждении возвращает 1
 FUNCTION get_tablespace_alert
  RETURN NUMBER IS
  ln_ret              NUMBER := 0;
 BEGIN
  EXECUTE IMMEDIATE 'SELECT max(ROUND (  (  (a.bytes_alloc - NVL (b.bytes_free, 0))/ 1024/ 1024)* 100/ (maxbytes / 1048576))) USAGE
             FROM (SELECT   f.tablespace_name, SUM (f.BYTES) bytes_alloc,SUM (DECODE (f.autoextensible,''YES'', f.maxbytes,''NO'', f.BYTES)) maxbytes
                       FROM dba_data_files f
                   GROUP BY tablespace_name) a,
                  (SELECT   f.tablespace_name, SUM (f.BYTES) bytes_free
                       FROM dba_free_space f
                   GROUP BY tablespace_name) b
            WHERE a.tablespace_name = b.tablespace_name(+)'
               INTO ln_ret;

  IF ln_ret > 95 THEN
   RETURN 1;
  END IF;

  RETURN 0;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN 0;
 END;
------------------------------------------------------------------------------------------------------------------------
END;
/


-- End of DDL Script for Package Body RYDA.TABLESPACEUSAGE_PG

