CREATE OR REPLACE 
PACKAGE BODY tariff_pg IS
 -----------------------------------------------------------------
 -- Пакет для работы с тарифами UMC
 -- создан 12,02,2003 by KSS
   gn_Task_Code NUMBER DEFAULT 610;
 -----------------------------------------------------------------
  -- Функция вычисления тарифа по дате
 FUNCTION gettariff(an_tarifftype NUMBER,ad_date DATE) -- дата, на которую нужно узнать тариф
  RETURN NUMBER IS
  ln_ret NUMBER;
 BEGIN
  SELECT MAX(nvalue)
    INTO ln_ret
    FROM tariff
   WHERE dstart = (SELECT MAX(dstart)
                     FROM tariff
                    WHERE dstart <= ad_date AND ntarifftype = an_tarifftype)
     AND ntarifftype = an_tarifftype;
  RETURN ln_ret;
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки тарифа в таблицу
 PROCEDURE ins_data(an_tarifftype NUMBER, --Тип тарифа
                                         ad_start DATE, --Дата ввода тарифа
                                                       an_value NUMBER --Значение тарифа
                                                                      ) IS
  ln_exists NUMBER;
  lv_tariffName VARCHAR2(200);
 BEGIN
  SELECT vname INTO lv_tariffName FROM tarifftype WHERE ntarifftype = an_tarifftype;
  admin_pg.fiscal_p(gn_Task_Code,1,'Добавлен тариф оператора связи '||lv_tariffName||' Дата ввода в действие '||to_char(ad_start,'dd.mm.yyyy hh24:mi:ss')||' Значение '||an_value);
  INSERT INTO tariff
              (ntarifftype, dstart, nvalue)
       VALUES (an_tarifftype, ad_start, an_value);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'tariff_pg.ins_data: Ошибка вставки тарифа в таблицу. ' || CHR(10) || SQLERRM(
                                                                                                          SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура обновления тарифа в таблице
 PROCEDURE upd_data(
  an_tarifftype NUMBER, --Тип тарифа
  ad_prim       DATE, --Ключ поиска
  ad_start      DATE, --Дата ввода тарифа
  an_value      NUMBER --Значение тарифа
                      ) IS
  ln_exists NUMBER;
  lv_tariffName VARCHAR2(200);
 BEGIN
  SELECT vname INTO lv_tariffName FROM tarifftype WHERE ntarifftype = an_tarifftype;
  admin_pg.fiscal_p(gn_Task_Code,2,'Изменен тариф оператора связи  '||lv_tariffName||' - '||to_char(ad_start,'dd.mm.yyyy hh24:mi:ss')||' Дата ввода в действие '||to_char(ad_start,'dd.mm.yyyy hh24:mi:ss')||' Значение '||an_value);
  UPDATE tariff
     SET nvalue = an_value,
         dstart = ad_start
   WHERE ntarifftype = an_tarifftype AND dstart = ad_prim;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'tariff_pg.upd_data: Ошибка изменения тарифа в таблице. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 -----------------------------------------------------------------------------------------------------------------------
   -- Процедура удаления тарифной зоны
 PROCEDURE del_t(an_tarifftype NUMBER, --Тип тарифа
                                      ad_start DATE --Дата ввода тарифа
                                                   ) IS
  lv_tariffName VARCHAR2(200);
 BEGIN
  SELECT vname INTO lv_tariffName FROM tarifftype WHERE ntarifftype = an_tarifftype;
  admin_pg.fiscal_p(gn_Task_Code,3,'Удален тариф оператора связи '||lv_tariffName||' Дата ввода в действие '||to_char(ad_start,'dd.mm.yyyy hh24:mi:ss'));
  DELETE FROM tariff
        WHERE ntarifftype = an_tarifftype AND dstart = ad_start;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'tariff_pg.del_t: Ошибка удаления тарифной зоны. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
-- Процедура чтения данных
 PROCEDURE load_p (an_tarifftype NUMBER,acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
   SELECT to_char(DSTART, 'dd.mm.yyyy')bData, NVALUE FROM TARIFF where ntarifftype=an_tarifftype ORDER BY DSTART desc;
 END;
 -----------------------------------------------------------------------------------------------------------------------
 -- Процедура заполнения списка типов тарифа
 PROCEDURE load_tarifftype_p (acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
   SELECT ntarifftype, vname FROM tarifftype order by vname;
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body TARIFF_PG
/


