CREATE OR REPLACE 
PACKAGE BODY tc_pg IS
------------------------------------------------------------------------------------------------------------------------
-- Процедура редактирования таблицы TCCONDITIONS
-- Выполняет обновление записей по заданному идентификатору условия
 PROCEDURE set_tcconditions (param NUMBER,   --Ид условия
                                          dates common_pg.tt_varchar2,   --Массив дат
                                                                      conditions common_pg.tt_varchar2   --Массив условий
                                                                                                      ) IS
  ln_test   NUMBER;
 BEGIN
  SAVEPOINT tcconditions_set;

  DELETE FROM tcconditions
        WHERE nparam = param;

  IF dates.COUNT > 0 AND LENGTH (dates (1)) > 0 THEN
   FOR i IN 1 .. dates.COUNT LOOP
    ln_test := check_condition (conditions (i), 1);

    INSERT INTO tcconditions
                (nparam, dstart, vcondition
                )
         VALUES (param, TO_DATE (dates (i), 'dd.mm.yyyy'), conditions (i)
                );
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT tcconditions_set;
   raise_application_error (-20001, 'tc_pg.set_tcconditions: Ошибка редактирования таблицы tcconditions. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--обновление записи в TC_PARAMS                                                        );
 PROCEDURE upd_params (aparam NUMBER,   --Ид условия
                                     aname VARCHAR2   --Наименование параметра
                                                   ) IS
 BEGIN
  SAVEPOINT tcparams_set;

  UPDATE tcparams
     SET vname = aname
   WHERE nparam = aparam;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT tcparams_set;
   raise_application_error (-20001, 'tc_pg.upd_params: Ошибка редактирования таблицы tcparams. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--добавление записи в TC_PARAMS
 PROCEDURE ins_params (aname VARCHAR2,   --Наименование параметра
                                      aparam OUT NUMBER   --Ид условия
                                                       ) IS
 BEGIN
  SAVEPOINT tcparams_set;

  SELECT points_seq.NEXTVAL
    INTO aparam
    FROM DUAL;

  INSERT INTO points
              (mid, NAME
              )
       VALUES (aparam, aname
              );

  INSERT INTO tcparams
              (nparam, vname
              )
       VALUES (aparam, aname
              );
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT tcparams_set;
   raise_application_error (-20001, 'tc_pg.upd_params: Ошибка вставки в таблицу tcparams. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_params (aparam NUMBER) AS
 BEGIN
  SAVEPOINT tcparams_set;

  DELETE FROM points
        WHERE mid = aparam;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT tcparams_set;
   raise_application_error (-20001, 'tc_pg.upd_params: Ошибка удаления из таблицы tcparams. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE set_tcsignals (amid NUMBER,   --Ид точки
                                      aclamps common_pg.tt_number,   --Массив клемм
                                                                  anparams common_pg.tt_number,   --Массив условий
                                                                                               avvalues common_pg.tt_varchar2   --Массив сигналов
 ) IS
 BEGIN
  SAVEPOINT tcsignals_set;

  DELETE FROM tcsignals
        WHERE mid = amid;

  IF aclamps.COUNT > 0 AND aclamps (1) > 0 THEN
   FOR i IN 1 .. aclamps.COUNT LOOP
    INSERT INTO tcsignals
                (mid, clamp, nparam, vvalue
                )
         VALUES (amid, aclamps (i), anparams (i), avvalues (i)
                );
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT tcsignals_set;
   raise_application_error (-20001, 'tc_pg.set_tcsignal: Ошибка редактирования таблицы tcsignals. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_condition (an_param NUMBER, ad_date DATE)
  RETURN VARCHAR2 IS
  lv_ret   VARCHAR2 (2000);
 BEGIN
  SELECT MAX (vcondition)
    INTO lv_ret
    FROM tcconditions
   WHERE nparam = an_param AND dstart = (SELECT MAX (dstart)
                                           FROM tcconditions
                                          WHERE dstart <= ad_date AND nparam = an_param);

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--проверка условия
 FUNCTION check_condition (av_condition VARCHAR2, an_raise NUMBER)
  RETURN NUMBER IS
  lv_condition      VARCHAR2 (4000) DEFAULT UPPER (av_condition);
  lv_retcondition   VARCHAR2 (4000) DEFAULT lv_condition;
  ln_k              NUMBER          := 1;
  ln_i              NUMBER          := 1;
  lv_id             VARCHAR2 (4000);
  ln_val            NUMBER;
  ln_ret            NUMBER          DEFAULT 0;
 BEGIN
  FOR lc IN (SELECT 'MID.' typeg
               FROM DUAL
             UNION ALL
             SELECT 'GID.' typeg
               FROM DUAL) LOOP
   ln_k := INSTR (lv_condition, lc.typeg, 1);

   WHILE ln_k > 0 LOOP
    ln_i := INSTR (lv_condition, ' ', ln_k);

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '(', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, ')', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '+', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '-', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '=', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '>', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '<', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '/', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := INSTR (lv_condition, '*', ln_k);
    END IF;

    IF ln_i = 0 THEN
     ln_i := LENGTH (lv_condition) + 1;
    END IF;

    IF ln_i > 0 THEN
     lv_id := SUBSTR (lv_condition, ln_k, ln_i - ln_k);
     lv_retcondition := REPLACE (lv_retcondition, lv_id, '(' || NVL (TO_CHAR (diagram_pg.get_modusinfo_byid (lv_id) * 1000), 'NULL') || ')');
    END IF;

    ln_k := INSTR (lv_condition, lc.typeg, ln_k + LENGTH (lc.typeg));
   END LOOP;
  END LOOP;

  IF lv_retcondition IS NOT NULL THEN
   EXECUTE IMMEDIATE 'select nvl(max(1),0) from dual where ' || lv_retcondition
                INTO ln_ret;
  END IF;

  RETURN ln_ret;
 EXCEPTION
  WHEN OTHERS THEN
   IF an_raise = 1 THEN
    raise_application_error (-20001,
                             'tc_pg.check_condition: Ошибка проверки валидности формулы: "' || av_condition || '" при преобразовании "' || lv_retcondition || '"'
                             || CHR (10) || SQLERRM (SQLCODE));
   END IF;

   RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE loadpointconditions (an_pointid NUMBER, acur_t OUT common_pg.tcur) IS
 -- Kondakov A.G. 28.07.2008
 -- используется в TfmPointConditions::LoadPointConditions
 BEGIN
  OPEN acur_t FOR SELECT s.CLAMP, s.NPARAM, s.VVALUE, p.vname, tc_pg.get_condition(s.nparam)Condition
             FROM tcsignals s, tcparams p
             WHERE s.mid= an_pointid AND s.NPARAM=p.nparam(+) ORDER BY 4;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE loadparams (acur_t OUT common_pg.tcur) IS
 -- Kondakov A.G. 28.07.2008
 -- используется в TfmPointConditions::LoadParams
 BEGIN
  OPEN acur_t FOR
   SELECT   p.nparam nparam, p.vname vname, tc_pg.get_condition (p.nparam) vcondition
       FROM tcparams p
   ORDER BY 2;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE loadinfo (an_param NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   vcondition, TO_CHAR (dstart, 'dd.mm.yy') dstartstr
       FROM tcconditions
      WHERE nparam = an_param
   ORDER BY 2 DESC;
 END;
------------------------------------------------------------------------------------------------------------------------
END;
/


