    -- Вставка (замена) данных
 FUNCTION sync_insert_replace_base(
 an_typeoffunc NUMBER,                                                                             -- 1- sync_insert 2 - sync_replace, иначе sync_insert_replace
                      an_typeofquery NUMBER,                        -- 0-NOTUSED, 1-CURRENTDATA, 2-MINUTEDATA, 3-HOURDATA, 4-DAYDATA, 5-MONTHDATA, 6-INSTANTDATA
                                            an_cid NUMBER,                                        -- Объект , с которого дадо получить информацию (channels.cid)
                                                          an_size NUMBER,                                                                        -- размер at_id
                                                                         at_id common_pg.tt_number,                                                 -- массив id
                                                                                                   at_datetime common_pg.tt_date,        -- массив меток времени
 at_er common_pg.tt_number,                                                                                                                    --массив значений
                           at_ed common_pg.tt_number,                                                                                          --массив значений
                                                     at_q1 common_pg.tt_number,                                                                --массив значений
                                                                               at_q3 common_pg.tt_number,                                      --массив значений
 at_qm common_pg.tt_varchar2                                                                                                             --массив меток качества
 )
  RETURN NUMBER IS
  cn_rn      CONSTANT NUMBER := 3;
  ld_sys              DATE DEFAULT SYSDATE;
  ln_mid              NUMBER DEFAULT 0;
  ln_null             NUMBER;
  ln_type             NUMBER;
  ln_exists           NUMBER;
  ln_er               NUMBER;
  ln_ed               NUMBER;
  ln_q1               NUMBER;
  ln_q3               NUMBER;
  ld_datetime         DATE;
 BEGIN
  IF an_typeofquery = cn_qt_hourdata THEN
   FOR i IN 1 .. an_size LOOP
    FOR lc IN (SELECT f.mid, f.nintegralperiod
               FROM   chanpoint c, feeders f
               WHERE  c.cid = an_cid AND c.mid = f.mid(+) AND DECODE(c.nuserescanal, 1, f.rescanal, f.canal) = at_id(i)
               UNION ALL
               SELECT mid, nintegralperiod
               FROM   feeders
               WHERE  an_cid = 0 AND mid = at_id(i)) LOOP
     IF NVL(at_er(i), 0) <> cn_rndend THEN                                                                                      --Если признак неполноты пакета
      IF an_typeoffunc IN(cn_tf_ins, cn_tf_rep) THEN
       SELECT COUNT(*)
       INTO   ln_exists
       FROM   DUAL
       WHERE  EXISTS(
               SELECT mid
               FROM   halfhourtmp
               WHERE  mid = lc.mid AND date_time = at_datetime(i)
               UNION ALL
               SELECT mid
               FROM   halfhour
               WHERE  mid = lc.mid AND date_time >= at_datetime(i) - 1 / 24 AND date_time <= at_datetime(i) + 1 / 24
                      AND util_pg.to_unlocaltime(date_time, nsource) = at_datetime(i) AND NOT(nsource BETWEEN 30 AND 49));

       IF ln_exists = 1 THEN
        IF an_typeoffunc = cn_tf_ins THEN
         ROLLBACK;
         RETURN cn_err_dataaccess;
        ELSIF an_typeoffunc = cn_tf_rep THEN
         GOTO to_continue;
        END IF;
       END IF;
      END IF;

      IF lc.nintegralperiod = 60 THEN                                                            --если данные только за час делим на получасовки VNB 26.05.2010
       FOR h IN 1 .. 2 LOOP
        IF h = 1 THEN
         ln_er := TRUNC(ROUND(at_er(i), cn_rn) / 2);
         ln_ed := TRUNC(ROUND(at_ed(i), cn_rn) / 2);
         ln_q1 := TRUNC(ROUND(at_q1(i), cn_rn) / 2);
         ln_q3 := TRUNC(ROUND(at_q3(i), cn_rn) / 2);
         ld_datetime := util_pg.ceil_d(at_datetime(i), 1 / 24) - 1 / 48;
        ELSE
         ln_er := ROUND(at_er(i), cn_rn) - TRUNC(ROUND(at_er(i), cn_rn) / 2);
         ln_ed := ROUND(at_ed(i), cn_rn) - TRUNC(ROUND(at_ed(i), cn_rn) / 2);
         ln_q1 := ROUND(at_q1(i), cn_rn) - TRUNC(ROUND(at_q1(i), cn_rn) / 2);
         ln_q3 := ROUND(at_q3(i), cn_rn) - TRUNC(ROUND(at_q3(i), cn_rn) / 2);
         ld_datetime := util_pg.ceil_d(at_datetime(i), 1 / 24);
        END IF;

        util_pg.chdr(lc.mid, ln_er, ln_ed, ln_q1, ln_q3);
        das_pg.ins_halfhourtmp(lc.mid, ld_datetime, NULL, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, NULL, comsrv_pg.cn_iccp, at_qm(i));
       END LOOP;
      ELSE
       ln_er := ROUND(at_er(i), cn_rn);
       ln_ed := ROUND(at_ed(i), cn_rn);
       ln_q1 := ROUND(at_q1(i), cn_rn);
       ln_q3 := ROUND(at_q3(i), cn_rn);
       util_pg.chdr(lc.mid, ln_er, ln_ed, ln_q1, ln_q3);
       das_pg.ins_halfhourtmp(lc.mid, at_datetime(i), NULL, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, NULL, comsrv_pg.cn_iccp, at_qm(i));
      END IF;
     END IF;

     IF ln_mid <> lc.mid THEN
      ln_mid := lc.mid;
      admin_pg.ins_last_save(lc.mid);
     END IF;

     --Если неполнота пакета (at_er (i)=cn_rndend) мы обновляем last_save.halfhour всегда
     UPDATE last_save
     SET halfhour =
          DECODE(
           at_er(i),
           cn_rndend, LEAST(NVL(halfhour, at_datetime(i) - 1 / 48), at_datetime(i) - 1 / 48),
           GREATEST(NVL(halfhour, at_datetime(i)), at_datetime(i))
          ),
         state_date = ld_sys,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;

     <<to_continue>>
     NULL;
    END LOOP;
   END LOOP;
  ELSIF an_typeofquery = cn_qt_currentdata THEN                                                                                                        --Текущие
   FOR i IN 1 .. an_size LOOP
    ln_mid := TRUNC(at_id(i) / cn_id_shift);
    ln_type := MOD(at_id(i), cn_id_shift);

    FOR lc IN (SELECT f.mid, f.nswitch, f.nintegralperiod
               FROM   chanpoint c, feeders f
               WHERE  c.cid = an_cid AND c.mid = f.mid(+) AND DECODE(c.nuserescanal, 1, f.rescanal, f.canal) = ln_mid
               UNION ALL
               SELECT mid, nswitch, nintegralperiod
               FROM   feeders
               WHERE  an_cid = 0 AND mid = at_id(i)) LOOP
     admin_pg.ins_last_save(lc.mid);

     IF NVL(at_er(i), 0) <> cn_rndend THEN                                                                                      --Если признак неполноты пакета
--На вход Метка времени зима ()
      FOR lc1 IN (SELECT DECODE(ln_type, cn_mt_er, at_er(i), util_pg.cn_random) er, DECODE(ln_type, cn_mt_ed, at_er(i), util_pg.cn_random) ed,
                         DECODE(ln_type, cn_mt_rr, at_er(i), util_pg.cn_random) q1, DECODE(ln_type, cn_mt_rd, at_er(i), util_pg.cn_random) q3
                  FROM   DUAL) LOOP
       IF lc.nintegralperiod = 60 THEN                                                          --если данные только за час делим на получасовки VNB 26.05.2010
        FOR h IN 1 .. 2 LOOP
         IF h = 1 THEN
          ln_er := TRUNC(lc1.er / 2);
          ln_ed := TRUNC(lc1.ed / 2);
          ln_q1 := TRUNC(lc1.q1 / 2);
          ln_q3 := TRUNC(lc1.q3 / 2);
          ld_datetime := util_pg.ceil_d(at_datetime(i), 1 / 24) - 1 / 48;
         ELSE
          ln_er := lc1.er - TRUNC(lc1.er / 2);
          ln_ed := lc1.ed - TRUNC(lc1.ed / 2);
          ln_q1 := lc1.q1 - TRUNC(lc1.q1 / 2);
          ln_q3 := lc1.q3 - TRUNC(lc1.q3 / 2);
          ld_datetime := util_pg.ceil_d(at_datetime(i), 1 / 24);
         END IF;

         util_pg.chdr(lc.mid, ln_er, ln_ed, ln_q1, ln_q3);
         calcformula_pg.ins_halfhouroldw(lc.mid, ld_datetime, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, NULL, comsrv_pg.cn_iccp, at_qm(i), lc.nswitch, NULL, NULL,
          1);
        END LOOP;
       ELSE
        ln_er := lc1.er;
        ln_ed := lc1.ed;
        ln_q1 := lc1.q1;
        ln_q3 := lc1.q3;
        util_pg.chdr(lc.mid, ln_er, ln_ed, ln_q1, ln_q3);
        calcformula_pg.ins_halfhouroldw(lc.mid, at_datetime(i), ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, NULL, comsrv_pg.cn_iccp, at_qm(i), lc.nswitch, NULL,
         NULL, 1);
       END IF;
      END LOOP;
     END IF;

     UPDATE last_save
     SET halfhour =
          DECODE(
           at_er(i),
           cn_rndend, LEAST(NVL(halfhour, at_datetime(i) - 1 / 48), at_datetime(i) - 1 / 48),
           GREATEST(NVL(halfhour, at_datetime(i)), at_datetime(i))
          ),
         state_date = SYSDATE,
         state_cod = 0,
         clock = 0
     WHERE  mid = lc.mid;
    END LOOP;
   END LOOP;
  ELSIF an_typeofquery = cn_qt_xmldayvalues THEN                                                                                                      --Суточные
   FOR i IN 1 .. an_size LOOP
    FOR lc IN (SELECT c.mid
               FROM   chanpoint c, feeders f
               WHERE  c.cid = an_cid AND c.mid = f.mid(+) AND DECODE(c.nuserescanal, 1, f.rescanal, f.canal) = at_id(i)
               UNION ALL
               SELECT at_id(i) mid
               FROM   DUAL
               WHERE  an_cid = 0) LOOP
     IF an_typeoffunc IN(cn_tf_ins, cn_tf_rep) THEN
      SELECT COUNT(*)
      INTO   ln_exists
      FROM   DUAL
      WHERE  EXISTS(SELECT mid
                    FROM   billorg
                    WHERE  mid = lc.mid AND date_time = at_datetime(i));

      IF ln_exists = 1 THEN
       IF an_typeoffunc = cn_tf_ins THEN
        ROLLBACK;
        RETURN cn_err_dataaccess;
       ELSIF an_typeoffunc = cn_tf_rep THEN
        GOTO to_continue;
       END IF;
      END IF;
     END IF;

     comsrv_pg.set_bill_meter(lc.mid, at_er(i), at_ed(i), at_q1(i), at_q3(i), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ICCP', NULL, at_datetime(i));

     IF ln_mid <> lc.mid THEN
      ln_mid := lc.mid;
      admin_pg.ins_last_save(lc.mid);
     END IF;

     UPDATE last_save
     SET bill = GREATEST(NVL(bill, at_datetime(i)), at_datetime(i))
     WHERE  mid = lc.mid;

     <<to_continue>>
     NULL;
    END LOOP;
   END LOOP;
  ELSE
   RETURN cn_err_badarg;
  END IF;

  COMMIT;

  IF an_typeofquery IN(cn_qt_hourdata, cn_qt_currentdata) THEN
   das_pg.checkhalfhour_without_err;
   COMMIT;
  END IF;

  RETURN cn_err_ok;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

