                                                                                                                at_ed common_pg.tt_number,     --массив значений
 at_q1 common_pg.tt_number,                                                                                                                    --массив значений
                           at_q3 common_pg.tt_number,                                                                                          --массив значений
                                                     at_qm common_pg.tt_varchar2                                                         --массив меток качества
 )
