--процедура для поиска "дырок" VNB 28.05.2010
 PROCEDURE get_notdataw(ad_date DATE, ad_date_end DATE) IS                                                                      --все входящие параметры по зиме
  cn_iccpclient_pid CONSTANT NUMBER := 77;
  ld_date             DATE;
  ld_date_end         DATE;
  ln_cnt              NUMBER;
  ln_cn               NUMBER;
  ln_stat             NUMBER;
  ld_max              DATE;
 BEGIN
  ld_date := ad_date;
  ld_date_end := ad_date_end;

  FOR lc IN (SELECT c.mid
             FROM   channels a, chanpoint c
             WHERE  a.protocol_id = cn_iccpclient_pid AND a.cid = c.cid) LOOP
------------------------------------------------------------DELETE
   DELETE FROM halfhourholes
   WHERE       mid = lc.mid
               AND date_time IN(SELECT util_pg.to_unlocaltime(hl.date_time, hl.nsource)
                                FROM   halfhour hl
                                WHERE  hl.mid = lc.mid AND hl.date_time > util_pg.to_localtime(ld_date) AND hl.date_time <= util_pg.to_localtime(ld_date_end));

   COMMIT;
--------------------------INSERT
   ln_cnt := TRUNC((ld_date_end - ld_date) * 48);

   SELECT util_pg.to_unlocaltime(MAX(h.date_time))
   INTO   ld_max                                                     --правильно max(util_pg.to_unlocaltime (h.date_time,h.nsource)) и halfhour, но так быстрее
   FROM   halfhourold h
   WHERE  mid = lc.mid AND h.date_time > util_pg.to_localtime(ld_date);

   IF ld_max >= ld_date AND ln_cnt > 0 THEN
    FOR lc1 IN (SELECT     ld_date + LEVEL / 48 dtime
                FROM       DUAL
                CONNECT BY LEVEL <= ln_cnt AND ld_date + LEVEL / 48 <= ld_max
                MINUS
                SELECT util_pg.to_unlocaltime(h.date_time, h.nsource) dtime
                FROM   halfhour h
                WHERE  mid = lc.mid AND h.date_time > util_pg.to_localtime(ld_date) AND h.date_time <= util_pg.to_localtime(ld_date_end)) LOOP
---------------------------если нет таких же записей то вставить,а если есть то увеличить счетчик попыток
     SELECT COUNT(*)
     INTO   ln_cn
     FROM   halfhourholes
     WHERE  mid = lc.mid AND date_time = lc1.dtime;

     IF ln_cn = 0 THEN
      INSERT INTO halfhourholes
                  (mid, date_time, nstat)
      VALUES      (lc.mid, lc1.dtime, 1);
     ELSE
      UPDATE halfhourholes
      SET nstat = ln_stat + 1
      WHERE  mid = lc.mid AND date_time = lc1.dtime AND nstat < cn_max_rep_try;
     END IF;
    END LOOP;
   END IF;

   COMMIT;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

-----------------------------------------------------------------------------------------------------------
--процедура для поиска "дырок" вызов для фонового процесса
 PROCEDURE get_notdata(an_maket NUMBER, ad_date DATE) IS
 BEGIN
  get_notdataw(util_pg.to_unlocaltime(TRUNC(ad_date)), util_pg.to_unlocaltime(TRUNC(ad_date) + 1));
 END;
---------------------------------------------------------------------------------------------------------------
END;                                                                                                                                     -- Package Body tsda_pg
/


