 PROCEDURE find_node (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::FindNode
 -- путь к точке начиная с коренного узла
 BEGIN
  OPEN acur_t FOR
   SELECT   mid
       FROM (SELECT     ROWNUM n, mid
                   FROM points
             CONNECT BY PRIOR PARENT = mid
             START WITH mid = an_mid)
   ORDER BY n DESC;
 END;
