 PROCEDURE createsubmenu_1 (an_mon NUMBER, an_id NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::createSubMenu_M
 BEGIN
  OPEN acur_t FOR
   SELECT   fid, nameform, 0 codetemplate
       FROM forms f
      WHERE monitor = an_mon AND PARENT IS NULL
            AND EXISTS (
                SELECT     *
                      FROM forms
                     WHERE codetemplate IN (1200, 1201, 1202, 1203, 1206) AND monitor = an_mon AND SUBSTR (enablecontrols, 7, 1) = '1'
                           AND (mid IS NULL OR mid IN (SELECT     mid
                                                             FROM points
                                                       CONNECT BY PRIOR PARENT = mid
                                                       START WITH mid = an_id))
                CONNECT BY PRIOR fid = PARENT
                START WITH fid = f.fid)
   ORDER BY 2;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE createsubmenu_2 (an_mon NUMBER, an_id NUMBER, an_fid NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::createSubMenu_M
 BEGIN
  OPEN acur_t FOR
   SELECT   f.fid, f.nameform, f.codetemplate, f.enablecontrols, f.stepprofile, f.namealert, f.mid
       FROM forms f
      WHERE monitor = an_mon AND PARENT = an_fid
            AND EXISTS (
                SELECT     *
                      FROM forms
                     WHERE codetemplate IN (1200, 1201, 1202, 1203, 1206) AND monitor = an_mon AND SUBSTR (enablecontrols, 7, 1) = '1'
                           AND (mid IS NULL OR mid IN (SELECT     mid
                                                             FROM points
                                                       CONNECT BY PRIOR PARENT = mid
                                                       START WITH mid = an_id))
                CONNECT BY PRIOR fid = PARENT
                START WITH fid = f.fid)
   ORDER BY 2;
 END;

