 PROCEDURE createsubmenu (an_fid NUMBER, an_mon NUMBER, an_gid NUMBER, acur_t OUT common_pg.tcur) IS
  -- используется в TMainForm::createSubMenu
  av_fid   VARCHAR2 (100);
 BEGIN
  IF (an_fid = 0) THEN
   av_fid := ' IS NULL ';
  ELSE
   av_fid := ' = ' || TO_CHAR (an_fid);
  END IF;

  OPEN acur_t FOR 'SELECT DISTINCT DECODE (f.codetemplate, NULL, 1, 0) CHILD, f.fid,
                f.codetemplate, f.nameform, f.commentform, f.enablecontrols,
                f.stepprofile, f.namealert, f.vprocname,'
                  || an_gid || ',f.mid
     FROM forms f
     WHERE PARENT ' || av_fid || ' AND monitor = ' || an_mon
                  || '
     CONNECT BY PRIOR PARENT = fid
     START WITH SUBSTR (enablecontrols, 7, 1) = ''1''
     AND ((f.CODETEMPLATE NOT IN (1200,1201,1202,1203,1206))
          OR (f.CODETEMPLATE IN (1200,1201,1202,1203,1206)
              AND (f.mid IS NULL OR f.mid IN (SELECT mid FROM points CONNECT BY PRIOR parent=mid START WITH mid='
                  || an_gid || '))
             )
         )
     ORDER BY 1, nameform DESC';
 END;

--------------------------------------------------------------------------------------
 PROCEDURE createsubmenu_g (an_fid NUMBER, an_mrole NUMBER, an_gid NUMBER, acur_t OUT common_pg.tcur) IS
  -- используется в TMainForm::createSubMenu_G
  av_fid   VARCHAR2 (100);
 BEGIN
  IF (an_fid = 0) THEN
   av_fid := ' IS NULL ';
  ELSE
   av_fid := ' = ' || TO_CHAR (an_fid);
  END IF;

  OPEN acur_t FOR 'SELECT DISTINCT DECODE (f.codetemplate, NULL, 1, 0) CHILD, f.fid, f.codetemplate, f.nameform, f.commentform,
                   f.enablecontrols, f.stepprofile, f.namealert, f.vprocname
    FROM forms f
    WHERE f.PARENT '
                  || av_fid || ' AND f.monitor = ' || an_mrole || '
          CONNECT BY PRIOR f.PARENT = f.fid
          START WITH f.monitor = ' || an_mrole
                  || '
                AND f.fid IN (SELECT fid FROM form_Group
                              WHERE gid IN (SELECT GID FROM GROUPS CONNECT BY PRIOR PARENT=GID START WITH GID='
                  || an_gid || '))
    ORDER BY 1, f.nameform DESC';
 END;

