 PROCEDURE loaddate (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT TO_CHAR (a.PROFILE, 'dd.mm.yyyy hh24:mi:ss') PROFILE, TO_CHAR (a.halfhour, 'dd.mm.yyyy hh24:mi:ss') halfhour,
          TO_CHAR (a.bill, 'dd.mm.yyyy hh24:mi:ss') bill, TO_CHAR (a.months, 'dd.mm.yyyy hh24:mi:ss') MONTH,
          DECODE (SIGN (c.cid),
                  1, a.clock,
                  DECODE (util_pg.getparamvalue_f (27),
                          0, a.clock,
                          DECODE (SIGN (ABS (a.clock) - util_pg.getparamvalue_f (27)), 1, util_pg.getparamvalue_f (27) * SIGN (a.clock), a.clock)
                         )
                 ) clock,
          TO_CHAR (a.state_date, 'dd.mm.yyyy hh24:mi:ss') state_date, a.state_cod,
          NVL (DECODE (SIGN (c.cid), 1, DECODE (a.trial, NULL, DECODE (c.was_dead, NULL, 'Опрос не производился'))), a.state_descr) state_descr,
          TO_CHAR (a.luck, 'dd.mm.yyyy hh24:mi:ss') luck, TO_CHAR (a.trial, 'dd.mm.yyyy hh24:mi:ss') trial,
          a.dcmdoff,a.ncmdoff,a.dexecmdoff,cp.noff,cp.doff
     FROM last_save a, channels c,curr_power cp
    WHERE a.mid = an_mid AND a.mid = c.cid(+) and a.mid=cp.mid(+);
 END;
