PROCEDURE chann_for_points (an_mid NUMBER,an_param NUMBER, acur_t OUT common_pg.tcur) is
BEGIN
    IF an_param IS NULL then
    OPEN acur_t FOR
        SELECT 1 havechilde, mid, parent, vname, imind 
        FROM(SELECT DISTINCT s.mid, s.PARENT, s.NAME vname, DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
        FROM(SELECT *
        FROM points p
        CONNECT BY PRIOR p.PARENT = p.mid
        START WITH p.mid IN
        (SELECT cp.cid
        FROM chanpoint cp 
        WHERE cp.mid = an_mid)) s,
        channels c
        WHERE PARENT IS NOT NULL AND c.cid(+) = s.mid) mm
        WHERE mm.mid = 3 or mm.parent = 1;
    ELSE
        OPEN acur_t FOR
        SELECT 1 havechilde, mid, parent, vname, imind 
        FROM(SELECT DISTINCT s.mid, s.PARENT, s.NAME vname, DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
        FROM(SELECT *
        FROM points p
        CONNECT BY PRIOR p.PARENT = p.mid
        START WITH p.mid IN
        (SELECT cp.cid
        FROM chanpoint cp 
        WHERE cp.mid = an_mid)) s,
        channels c
        WHERE PARENT IS NOT NULL AND c.cid(+) = s.mid) mm
        WHERE mm.parent = an_param AND
        EXISTS(SELECT * FROM points t_p WHERE mm.mid = t_p.parent)
        UNION ALL
        SELECT 0 havechilde, mid, parent, vname, imind 
        FROM(SELECT DISTINCT s.mid, s.PARENT, s.NAME vname, DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
        FROM(SELECT *
        FROM points p
        CONNECT BY PRIOR p.PARENT = p.mid
        START WITH p.mid IN
        (SELECT cp.cid
        FROM chanpoint cp 
        WHERE cp.mid = an_mid)) s,
        channels c
        WHERE PARENT IS NOT NULL AND c.cid(+) = s.mid) mm
        WHERE mm.parent = an_param AND
        EXISTS(SELECT * FROM channels ch  WHERE mm.mid = ch.cid);
    END IF;
END;
-------------------------------------------------------------------------------------------
PROCEDURE group_for_points(an_mid NUMBER,an_param NUMBER, acur_t OUT common_pg.tcur) is
BEGIN
    IF an_param IS NULL then
    OPEN acur_t FOR
        SELECT DISTINCT 1 havechilde, mm.gid mid, mm.PARENT, mm.NAME vname, DECODE (mm.mid, NULL, 2, DECODE (mm.inverted, 'y', 1, 0)) imind
        from
        (select *
        FROM GROUPS c
        CONNECT BY PRIOR c.PARENT = c.gid
        START WITH c.gid IN
        (SELECT cp.gid FROM GROUPS cp
        WHERE cp.mid = an_mid)
        ORDER BY 3) mm
        where parent is null;
    ELSE
    OPEN acur_t FOR
        SELECT DISTINCT decode(mm.mid, an_mid, 0,1) havechilde, mm.gid mid, mm.PARENT, mm.NAME vname, DECODE (mm.mid, NULL, 2, DECODE (mm.inverted, 'y', 1, 0)) imind
        from
        (select *
        FROM GROUPS c
        CONNECT BY PRIOR c.PARENT = c.gid
        START WITH c.gid IN
        (SELECT cp.gid FROM GROUPS cp
        WHERE cp.mid = an_mid)
        ORDER BY 3) mm
        where parent = an_param;
    END IF;
END;
-------------------------------------------------------------------------------------------

PROCEDURE maket_for_points(an_mid NUMBER, an_param NUMBER, acur_t OUT common_pg.tcur) IS
BEGIN
    IF an_param IS NULL then
    OPEN acur_t FOR
        select 1 havechilde, mid, parent, vname, imind
        from(SELECT DISTINCT m.nmaket mid, m.nmaket PARENT, m.vname, 3 imind
        FROM makets m, maketgroups cp, maketpoints p
        WHERE m.nmaket = cp.nmaket AND p.ngroup = cp.ngroup AND p.mid = an_mid
        UNION ALL
        SELECT   p.ngroup, cp.nmaket, cp.vname, 2 imind
        FROM maketgroups cp, maketpoints p
        WHERE p.ngroup = cp.ngroup AND p.mid = an_mid
        UNION ALL
        SELECT   m.mid, m.ngroup, util_pg.get_pointname (m.mid, 1), decode(sign(m.nkc),-1,1,0) imind
        FROM maketpoints m
        WHERE m.mid = an_mid
        ORDER BY 3) mm
        where mm.mid = mm.parent;
    ELSE
    OPEN acur_t FOR
        select decode(mid, an_mid, 0, 1) havechilde, mid, parent, vname, imind 
        from(SELECT DISTINCT m.nmaket mid, m.nmaket PARENT, m.vname, 3 imind
        FROM makets m, maketgroups cp, maketpoints p
        WHERE m.nmaket = cp.nmaket AND p.ngroup = cp.ngroup AND p.mid = an_mid
        UNION ALL
        SELECT   p.ngroup, cp.nmaket, cp.vname, 2 imind
        FROM maketgroups cp, maketpoints p
        WHERE p.ngroup = cp.ngroup AND p.mid = an_mid
        UNION ALL
        SELECT   m.mid, m.ngroup, util_pg.get_pointname (m.mid, 1), decode(sign(m.nkc),-1,1,0) imind
        FROM maketpoints m
        WHERE m.mid = an_mid
        ORDER BY 3) mm
        where mm.parent = an_param and mm.parent != mm.mid;
    END IF;
END;
-------------------------------------------------------------------------------------------

PROCEDURE chann_for_distribution(an_mid NUMBER,an_param NUMBER, acur_t OUT common_pg.tcur) IS
BEGIN
    OPEN acur_t FOR
    SELECT 0 havechilde, ndeportation mid, ndeportation PARENT, vname, DECODE (nblock, 0, 9, 11) imind
      FROM deportation
     WHERE nmaket = an_mid
     ORDER BY VNAME;
END;
-------------------------------------------------------------------------------------------

PROCEDURE chan_in_com(an_mid NUMBER,an_param NUMBER, acur_t OUT common_pg.tcur) IS
BEGIN
    IF an_param IS NULL then
    OPEN acur_t FOR
        SELECT 1 havechilde, mid, parent, vname, imind 
        FROM (SELECT DISTINCT s.mid, s.PARENT, s.NAME vname,
        DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
        FROM (SELECT     p.mid, p.PARENT, p.NAME, p.tag
        FROM points p
        CONNECT BY PRIOR p.PARENT = p.mid
        START WITH p.mid IN (SELECT c.cid
        FROM channels c
        WHERE c.com_id = an_mid)) s,
        channels c
        WHERE s.PARENT IS NOT NULL AND c.cid(+) = s.mid
        ORDER BY 3) mm
        WHERE mm.parent = 1;
    ELSE
    OPEN acur_t FOR
    SELECT 1 havechilde, mid, parent, vname, imind 
        FROM (SELECT DISTINCT s.mid, s.PARENT, s.NAME vname,
        DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
        FROM (SELECT     p.mid, p.PARENT, p.NAME, p.tag
        FROM points p
        CONNECT BY PRIOR p.PARENT = p.mid
        START WITH p.mid IN (SELECT c.cid
        FROM channels c
        WHERE c.com_id = an_mid)) s,
        channels c
        WHERE s.PARENT IS NOT NULL AND c.cid(+) = s.mid
        ORDER BY 3) mm
        WHERE mm.parent = an_param and EXISTS(SELECT * FROM points t_p WHERE mm.mid = t_p.parent)
        UNION ALL
        SELECT 0 havechilde, mid, parent, vname, imind 
        FROM (SELECT DISTINCT s.mid, s.PARENT, s.NAME vname,
        DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
        FROM (SELECT     p.mid, p.PARENT, p.NAME, p.tag
        FROM points p
        CONNECT BY PRIOR p.PARENT = p.mid
        START WITH p.mid IN (SELECT c.cid
        FROM channels c
        WHERE c.com_id = an_mid)) s,
        channels c
        WHERE s.PARENT IS NOT NULL AND c.cid(+) = s.mid
        ORDER BY 3) mm
        WHERE mm.parent = an_param and EXISTS(SELECT * FROM channels ch  WHERE mm.mid = ch.cid);
    END IF;
END;
-------------------------------------------------------------------------------------------

PROCEDURE showchannellist2 (an_mid NUMBER, an_param NUMBER, an_flag NUMBER, acur_t OUT common_pg.tcur) IS
BEGIN
    IF(an_flag = 1)THEN
        chan_in_com(an_mid, an_param, acur_t);    
    ELSIF(an_flag = 2) THEN
        chann_for_points(an_mid, an_param, acur_t);
    ELSIF (an_flag = 3) THEN
        group_for_points(an_mid, an_param, acur_t);
    ELSIF (an_flag = 4) THEN
        chann_for_distribution(an_mid, an_param, acur_t);    
    ELSIF (an_flag = 5) THEN
        maket_for_points(an_mid, an_param, acur_t);
    ELSIF (an_flag = 6) THEN 
        editformula_pg.read_tree_in_param2(an_mid, an_param, acur_t);    
    ELSE
    RETURN;
    END IF;
END;
-------------------------------------------------------------------------------------------
END;
/


