 cv_proc1   CONSTANT VARCHAR2(256) DEFAULT '1';
 cv_proc2   CONSTANT VARCHAR2(256) DEFAULT '2';
 cv_proc3   CONSTANT VARCHAR2(256) DEFAULT '3';
 cv_proc4   CONSTANT VARCHAR2(256) DEFAULT '4';
 cv_proc5   CONSTANT VARCHAR2(256) DEFAULT '5';
 cv_proc6   CONSTANT VARCHAR2(256) DEFAULT '6';
 cv_proc7   CONSTANT VARCHAR2(256) DEFAULT '7';
 cv_proc8   CONSTANT VARCHAR2(256) DEFAULT '8';
 cv_proc9   CONSTANT VARCHAR2(256) DEFAULT '9';
 cv_proc10  CONSTANT VARCHAR2(256) DEFAULT '10';
 cv_proc11  CONSTANT VARCHAR2(256) DEFAULT '11';                                                         --Параметры сети для группы точек за определенную дату
 cv_proc12  CONSTANT VARCHAR2(256) DEFAULT '12';                                                      --Показания точек технического учета на определенную дату
 cv_proc13  CONSTANT VARCHAR2(256) DEFAULT '13';                                                                               --Расход э\э по точкам и группам
 cv_proc14  CONSTANT VARCHAR2(256) DEFAULT '14';                                                                                         --Расход э\э за период
 cv_proc15  CONSTANT VARCHAR2(256) DEFAULT '15';                                                                                                              --
 cv_proc16  CONSTANT VARCHAR2(256) DEFAULT '16';                                                                       --сменный отчет о расходе электроэнергии
 cv_proc17  CONSTANT VARCHAR2(256) DEFAULT '17';                                                    --по передаче э/э по линиям м\гос перетоков - актив,реактив
 cv_proc18  CONSTANT VARCHAR2(256) DEFAULT '18';                                                           -- по передаче э/э по линиям м\гос перетоков - актив
 cv_proc20  CONSTANT VARCHAR2(256) DEFAULT '20';                                                -- согласованные графики перетоков электроэнергии по межгос ЛЭП
 cv_proc21  CONSTANT VARCHAR2(256) DEFAULT '21';                                                               -- межгос перетоки с разбивкой по тарифным зонам
 cv_proc22  CONSTANT VARCHAR2(256) DEFAULT '22';                                                                            -- отчет для сверки счетчиков с ОИК
 cv_proc28  CONSTANT VARCHAR2(256) DEFAULT '28';                                               -- согласованные графики перетоков электроэнергии по межгос. ЛЭП
 cv_proc29  CONSTANT VARCHAR2(256) DEFAULT '29';                                            --розрахунок перетоків електроенергії між ОЕС України та ЄЕС Росії.
 cv_proc30  CONSTANT VARCHAR2(256) DEFAULT '30';                                                                           --сальдо переток по тар зонам межгос
 cv_procmaketarm CONSTANT VARCHAR2(256) DEFAULT '100';                                                                       --для оперативной работы с макетом
 cv_procmaketarmr CONSTANT VARCHAR2(256) DEFAULT '110';                                                             --для оперативной работы с принятым макетом
 cv_proc31  CONSTANT VARCHAR2(256) DEFAULT '31';                                                                                  -- обобщенный отчет по точкам
 cv_proc32  CONSTANT VARCHAR2(256) DEFAULT '32';                                                                                       -- НСИ по тарифным зонам
 cv_proc33  CONSTANT VARCHAR2(256) DEFAULT '33';                                                              -- НСИ по точкам (отчет Общий список точек учета)
 cv_proc34  CONSTANT VARCHAR2(256) DEFAULT '34';                                                 -- НСИ по точкам (отчет Параметры расчетных точек) (пока нету)
 cv_proc35  CONSTANT VARCHAR2(256) DEFAULT '35';                                                                                              -- НСИ по группам
 cv_proc36  CONSTANT VARCHAR2(256) DEFAULT '36';                                                          -- НСИ. "Переключение ОВ" отчет "Журнал переключений"
 cv_proc37  CONSTANT VARCHAR2(256) DEFAULT '37';                                                                                           -- НСИ по COM портам
 cv_proc38  CONSTANT VARCHAR2(256) DEFAULT '38';                                                    -- НСИ по задаче "План опроса" отчет "Общий список каналов"
 cv_proc39  CONSTANT VARCHAR2(256) DEFAULT '39';                            -- НСИ по задаче "План опроса" отчет "Параметры и перечень точек, входящих в канал"
 cv_proc40  CONSTANT VARCHAR2(256) DEFAULT '40';                                           -- НСИ по задаче "Формирование макетов" отчет "Общий список макетов"
 cv_proc41  CONSTANT VARCHAR2(256) DEFAULT '41';                             -- НСИ по задаче "План рассылки макетов" отчет "Расписание плана рассылки макетов"
 cv_proc42  CONSTANT VARCHAR2(256) DEFAULT '42';                                                    -- Отчет о перетоках э/э по МГ ЛЭП со странами UCTE (С04-1)
 cv_proc43  CONSTANT VARCHAR2(256) DEFAULT '43';                                                                                -- 24-часовой отчет Центрэнерго
 cv_proc44  CONSTANT VARCHAR2(256) DEFAULT '44';                                                               -- Суточная сменная ведомость по учету э/энергии
 cv_proc45  CONSTANT VARCHAR2(256) DEFAULT '45';                                                   -- Сменная ведомость по учету э/энергии (выработка и отпуск)
 cv_proc46  CONSTANT VARCHAR2(256) DEFAULT '46';                                      -- Отображение точек, по которым были использованы данные не осн. прибора
 cv_proc47  CONSTANT VARCHAR2(256) DEFAULT '47';                                                              -- Почасовой сальдо переток электрической энергии
 cv_proc_pb3_b CONSTANT NUMBER DEFAULT 48;                                                                           -- Отчеты из пакета UNIINTERIOR3_PG начало
 cv_proc_pb3_e CONSTANT NUMBER DEFAULT 52;                                                                         -- Показания счетчиков UNIINTERIOR3_PG конец
 cn_proc_out1 CONSTANT NUMBER DEFAULT 151;                                      -- Для написания кода сторониими разработчиками Ид процедуры - начало диапазона
 cn_proc_out2 CONSTANT NUMBER DEFAULT 200;                                       -- написания кода сторониими разработчиками Ид процедуры - окончание диапазона
------------------------------------------------------------------------------------------------------------------------
 gn_aparam           NUMBER;
 gn_bparam           NUMBER;
 gn_cparam           NUMBER;
 gn_dparam           NUMBER;
 gn_id               NUMBER;
 gd_from             DATE;
 gd_till             DATE;
 gt_addparam 								common_pg.tt_varchar2;
------------------------------------------------------------------------------------------------------------------------
--Получение доп параметров
 FUNCTION ct_addparam  RETURN common_pg.tt_varchar2
 is
 begin
 	return gt_addparam;
 end;
------------------------------------------------------------------------------------------------------------------------
 FUNCTION f_gettypeproc(an_fid NUMBER)
  RETURN VARCHAR2 IS
  lv_proc             VARCHAR2(256);
 BEGIN
  IF (an_fid = -5555) THEN
   lv_proc := cv_procmaketarm;
  ELSIF(an_fid = -7777) THEN
   lv_proc := cv_procmaketarmr;
  ELSE
   SELECT UPPER(TRIM(MAX(vprocname)))
   INTO   lv_proc
   FROM   forms
   WHERE  fid = an_fid;
  END IF;

  RETURN lv_proc;
 END;

------------------------------------------------------------------------------------------------------------------------
--Цвет по типу параметра
 FUNCTION f_color(an_paramtype NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN cn_white;
 END;

------------------------------------------------------------------------------------------------------------------------
--Заголовок колонки родителя уровня i
 FUNCTION f_parenttitle(an_fid NUMBER, an_i NUMBER)
  RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(2000);
 BEGIN
  SELECT TRIM(MAX(vvalue))
  INTO   lv_ret
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = DECODE(an_i, 2, -13, -12);

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------

 --Блокировка вывода итоговых цифр
 FUNCTION f_locksum(an_fid NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)                                                                                      -- 0 значит не блокировать
  INTO   ln_ret
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -5;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Возвращает информацию по колонкам таблицы для макета
 PROCEDURE getmaketinfo(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER,
 an_cnfooter OUT NUMBER, col_t OUT common_pg.tcur, row_t OUT common_pg.tcur,at_addparam common_pg.tt_varchar2
 )
 is 
 begin
 gt_addparam.delete;
 for i in 1..at_addparam.count loop
	 gt_addparam(i):=at_addparam(i);
 end loop; 
 getmaketinfo( an_fid , an_ispoint , an_id , ad_from , ad_till , an_cnfixcol , an_cntitle , an_cnfooter , col_t , row_t );
 end;
------------------------------------------------------------------------------------------------------------------------
  -- Возвращает информацию по колонкам таблицы для макета
 PROCEDURE getmaketinfo(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER,
 an_cnfooter OUT NUMBER, col_t OUT common_pg.tcur, row_t OUT common_pg.tcur
 ) IS
   /*
  an_fid         - Ид формы
  an_ispoint      - Признак точки
  an_id           - Ид (точки или группы)
  ad_from         - Дата с
  ad_till         - Дата по
  an_cnfixcol --количество фикс колонок
  an_cntitle --количество строк в заголовке
  col_t -- информация по колонкам таблицы - курсор, строка которого есть
   id - идентификатор колонки
   Title1, Title2, ... (=an_cntitle) - наименование
   TitleCl - цвет заголовка
   TitleAl - выравнивание заголовка
   DataCl - цвет данных
   DataAl - выравнивание данных
   nlock - блокировка редактирования
   nwidth - ширина колонки (если<=0 то auto)
   vmasks - маска колонки (может быть NULL)

  row_t -- информация по строкам таблицы - курсор, строка которого есть
   id - идентификатор сторки
   Title1, Title2, ... (=an_cnfixcol) - наименование
   DataCl - цвет данных
   nlock - блокировка редактирования
   vmasks - маска строки (может быть NULL)
   srt - сортировка
   */
  lv_proc             VARCHAR2(256);
  ln_locksum          NUMBER DEFAULT f_locksum(an_fid);
  lv_lev              NUMBER DEFAULT 0;
  interv              NUMBER;
  data_t              common_pg.tt_number;
  lv_sql              VARCHAR2(4000);
  lv_sql1             VARCHAR2(4000);
  lv_sql2             VARCHAR2(4000);
 BEGIN
  lv_proc := f_gettypeproc(an_fid);

  IF util_pg.get_param(lv_proc, 1, ';') = cv_proc1 THEN
   an_cnfixcol := 3;
   an_cntitle := 2;
   an_cnfooter := 1;

   OPEN col_t FOR
    SELECT -1 ID, 'Наименование присоединения' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 200 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT -2 ID, '№ счетчика' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 70 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT -2 ID, 'Коэф.' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 1 ID, 'Актив (+)' title1, 'Конечные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 2 ID, 'Актив (+)' title1, 'Начальные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 3 ID, 'Актив (+)' title1, 'Разность' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 4 ID, 'Актив (+)' title1, 'Расход энергии, кВтч' title2, cn_btnface titlecl, cn_left titleal, cn_aqua datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 21 ID, 'Актив (-)' title1, 'Конечные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 22 ID, 'Актив (-)' title1, 'Начальные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 23 ID, 'Актив (-)' title1, 'Разность' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 24 ID, 'Актив (-)' title1, 'Расход энергии, кВтч' title2, cn_btnface titlecl, cn_left titleal, cn_aqua datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 31 ID, 'Реактив (+)' title1, 'Конечные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 32 ID, 'Реактив (+)' title1, 'Начальные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
           70 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 33 ID, 'Реактив (+)' title1, 'Разность' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 34 ID, 'Реактив (+)' title1, 'Расход энергии, кВАрч' title2, cn_btnface titlecl, cn_left titleal, cn_aqua datacl, cn_right dataal, 1 nlock,
           70 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 41 ID, 'Реактив (-)' title1, 'Конечные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 42 ID, 'Реактив (-)' title1, 'Начальные показания' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
           70 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 43 ID, 'Реактив (-)' title1, 'Разность' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 44 ID, 'Реактив (-)' title1, 'Расход энергии, кВАрч' title2, cn_btnface titlecl, cn_left titleal, cn_aqua datacl, cn_right dataal, 1 nlock,
           70 nwidth, '' vmasks
    FROM   DUAL;

   IF an_ispoint = 1 THEN
    OPEN row_t FOR
     SELECT *
     FROM   (SELECT   p.mid ID, DECODE(f.vcode, '', '', f.vcode || '.') || DECODE(util_pg.get_param(lv_proc, 2, ';'), 1, '', pa.NAME || ' / ') || p.NAME title1,
                      m.mtrsn title2, TO_CHAR(DECODE(SIGN(NVL(f.metkc, 1) - 1), 1, NVL(f.metkc, 1), NVL(f.kc, 1))) title3, cn_white datacl, 1 nlock, '' vmasks,
                      0 srt
             FROM     feeders f, meters m, points p, points pa
             WHERE    f.mid IN(SELECT     mid
                               FROM       points
                               CONNECT BY PRIOR mid = PARENT
                               START WITH mid = an_id) AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
             ORDER BY pa.NAME, pa.mid, p.NAME, p.mid)
     UNION ALL
     SELECT -1 ID, 'Итого расход:' title1, '' title2, '' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL;
   ELSE
    OPEN row_t FOR
     SELECT *
     FROM   (SELECT   p.mid ID,
                      NVL(util_pg.get_param(g.vparam, 2),
                       DECODE(f.vcode, '', '', f.vcode || '.') || DECODE(util_pg.get_param(lv_proc, 2, ';'), 1, '', pa.NAME || '/') || p.NAME) title1,
                      m.mtrsn title2, TO_CHAR(DECODE(SIGN(NVL(f.metkc, 1) - 1), 1, NVL(f.metkc, 1), NVL(f.kc, 1))) title3, cn_white datacl, 1 nlock, '' vmasks,
                      0 srt
             FROM     GROUPS g, feeders f, meters m, points p, points pa
             WHERE    g.gid IN(
                       SELECT     gid
                       FROM       GROUPS
                       CONNECT BY PRIOR gid = PARENT
                                  AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501))
                       START WITH gid = an_id
                                  AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501)))
                      AND g.mid = f.mid AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
             ORDER BY util_pg.allnumber_f(util_pg.get_param(g.vparam, 1, ';')), pa.NAME, pa.mid, p.NAME, p.mid)
     UNION ALL
     SELECT -1 ID, 'Итого расход:' title1, '' title2, '' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL;
   END IF;
  ------------------------------- addded by Kondakov A.G. 07.10.2008
  ELSIF util_pg.get_param(lv_proc, 1, ';') = cv_proc2 THEN
   uniinterior2_pg.proc_info_2(an_fid, an_ispoint, an_id, ad_from, ad_till, an_cnfixcol, an_cntitle, an_cnfooter, col_t, row_t, lv_proc);
  ------------------------------- addded by Kondakov A.G. 08.10.2008
  ELSIF lv_proc = cv_proc3 THEN
   an_cnfixcol := 3;
   an_cntitle := 3;

   IF ln_locksum = 0 THEN
    an_cnfooter := 4;
   ELSE
    an_cnfooter := 0;
   END IF;

   OPEN col_t FOR
    SELECT -3 ID, 'Наименование ПС' title1, '' title2, '1' title3, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 200 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT -2 ID, 'Присоединение' title1, '' title2, '2' title3, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 180 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT -1 ID, '№ счетчика' title1, '' title2, '3' title3, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 70 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 1 ID, 'Показания счетчика' title1, '24-00 час. последнего дня отчетного месяца' title2, '4' title3, cn_btnface titlecl, cn_left titleal,
           cn_white datacl, cn_right dataal, 1 nlock, 95 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 2 ID, 'Показания счетчика' title1, '00-00 час. первого дня отчетного месяца' title2, '5' title3, cn_btnface titlecl, cn_left titleal,
           cn_white datacl, cn_right dataal, 1 nlock, 95 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 3 ID, 'Разность' title1, '' title2, '6' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 95 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 4 ID, 'Коэффициент' title1, '' title2, '7' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 5 ID, 'Поступление' title1, '' title2, '8' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 95 nwidth,
           '' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 6 ID, 'Отдача' title1, '' title2, '9' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 95 nwidth, '' vmasks
    FROM   DUAL;

   IF an_ispoint = 1 THEN
    OPEN row_t FOR
     SELECT t.ID, t.title1, t.title2, t.title3, t.datacl, t.nlock, t.vmasks, 0 srt
     FROM   (SELECT   p.mid ID, DECODE(f.vcode, '', '', f.vcode || '.') || pa.NAME title1, p.NAME title2, m.mtrsn title3, d.r, cn_white datacl, 1 nlock,
                      '' vmasks
             FROM     feeders f,
                      meters m,
                      points p,
                      points pa,
                      (SELECT ROWNUM r
                       FROM   dict
                       WHERE  ROWNUM <= 2) d
             WHERE    f.mid IN(SELECT     mid
                               FROM       points
                               CONNECT BY PRIOR mid = PARENT
                               START WITH mid = an_id) AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
             ORDER BY pa.NAME, pa.mid, p.NAME, p.mid, d.r) t                                           -- сортировка по d.r значит - сначала прием, потом отдача
     UNION ALL
     SELECT -1 ID, 'Итого расход:' title1, 'за период' title2, 'кВт*ч' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL
     UNION ALL
     SELECT -1 ID, '' title1, '' title2, 'т.кВт*ч' title3, cn_yellow datacl, 0 nlock, '' vmasks, 1 srt
     FROM   DUAL
     UNION ALL
     SELECT -1 ID, '' title1, 'сальдо переток' title2, 'кВт*ч' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL
     UNION ALL
     SELECT -1 ID, '' title1, '' title2, 'т.кВт*ч' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL;
   ELSE
    OPEN row_t FOR
     SELECT t.ID, t.title1, t.title2, t.title3, t.datacl, t.nlock, t.vmasks, 0 srt
     FROM   (SELECT   p.mid ID, NVL(util_pg.get_param(g2.vparam, 2), DECODE(f.vcode, '', '', f.vcode || '.') || /*pa*/ g2.NAME) title1,
                      NVL(util_pg.get_param(g.vparam, 2), p.NAME) title2, m.mtrsn title3, d.r, cn_white datacl, 1 nlock, '' vmasks
             FROM     GROUPS g,
                      feeders f,
                      meters m,
                      points p,
                      /*points pa,*/
                      GROUPS g2,
                      (SELECT ROWNUM r
                       FROM   dict
                       WHERE  ROWNUM <= 2) d
             WHERE    g.gid IN(
                       SELECT     gid
                       FROM       GROUPS
                       CONNECT BY PRIOR gid = PARENT
                                  AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501))
                       START WITH gid = an_id
                                  AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501)))
