           '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 2 ID, 'Линейное напряжение, В' title1, 'Ub' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 80 nwidth,
           '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 3 ID, 'Линейное напряжение, В' title1, 'Uc' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 80 nwidth,
           '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 4 ID, 'Ток, А' title1, 'Ia' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 50 nwidth, '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 5 ID, 'Ток, А' title1, 'Ib' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 50 nwidth, '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 6 ID, 'Ток, А' title1, 'Ic' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 50 nwidth, '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 7 ID, 'Частота напряжения сети, Гц' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
           150 nwidth, '0.000' vmasks
    FROM   DUAL
    UNION ALL
    SELECT 8 ID, 'Фазовый сдвиг' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 80 nwidth,
           '0.000' vmasks
    FROM   DUAL;

   OPEN row_t FOR
    SELECT -1 ID, PARENT title1, NAME title2, TO_CHAR(dt, 'DD.MM.YYYY HH24:MI:SS') title3, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   (SELECT   g1.NAME PARENT, g.NAME NAME, g.mid, TO_DATE(tt.dt, 'DD.MM.YYYY HH24:MI:SS') dt
            FROM     (SELECT     NAME, PARENT, mid
                      FROM       GROUPS
                      WHERE      mid > 0
                      CONNECT BY PRIOR gid = PARENT
                      START WITH PARENT = an_id) g,
                     GROUPS g1,
                     (SELECT   mid, TO_CHAR(MAX(date_time), 'DD.MM.YYYY HH24:MI:SS') dt
                      FROM     curr_power_arch
                      WHERE    date_time <= ad_from AND mid IN(SELECT g.mid
                                                               FROM   (SELECT     NAME, PARENT, mid
                                                                       FROM       GROUPS
                                                                       WHERE      mid > 0
                                                                       CONNECT BY PRIOR gid = PARENT
                                                                       START WITH PARENT = an_id) g,
                                                                      GROUPS g1
                                                               WHERE  g1.gid = g.PARENT)
                      GROUP BY mid) tt
            WHERE    g1.gid = g.PARENT AND g.mid = tt.mid
            UNION ALL
            SELECT   g1.NAME PARENT, g.NAME NAME, g.mid, TO_DATE('', 'DD.MM.YYYY HH24:MI:SS') dt
            FROM     (SELECT     NAME, PARENT, mid
                      FROM       GROUPS
                      WHERE      mid > 0
                      CONNECT BY PRIOR gid = PARENT
                      START WITH PARENT = an_id) g,
                     GROUPS g1
            WHERE    g1.gid = g.PARENT
            MINUS
            SELECT   g1.NAME PARENT, g.NAME NAME, g.mid, TO_DATE('', 'DD.MM.YYYY HH24:MI:SS') dt
            FROM     (SELECT     NAME, PARENT, mid
                      FROM       GROUPS
                      WHERE      mid > 0
                      CONNECT BY PRIOR gid = PARENT
                      START WITH PARENT = an_id) g,
                     GROUPS g1
            WHERE    g1.gid = g.PARENT
                     AND g.mid IN(
                         (SELECT g.mid
                          FROM   (SELECT     NAME, PARENT, mid
                                  FROM       GROUPS
                                  WHERE      mid > 0
                                  CONNECT BY PRIOR gid = PARENT
                                  START WITH PARENT = an_id) g,
                                 GROUPS g1,
                                 (SELECT   mid, TO_CHAR(MAX(date_time), 'DD.MM.YYYY HH24:MI:SS') dt
                                  FROM     curr_power_arch
                                  WHERE    date_time <= ad_from AND mid IN(SELECT g.mid
                                                                           FROM   (SELECT     NAME, PARENT, mid
                                                                                   FROM       GROUPS
                                                                                   WHERE      mid > 0
                                                                                   CONNECT BY PRIOR gid = PARENT
                                                                                   START WITH PARENT = an_id) g,
                                                                                  GROUPS g1
                                                                           WHERE  g1.gid = g.PARENT)
                                  GROUP BY mid) tt
                          WHERE  g1.gid = g.PARENT AND g.mid = tt.mid))
            ORDER BY 1, 2);
 /*   SELECT -1 ID, g1.name title1,g.name title2, ''title3, cn_white datacl, 0 nlock, '' vmasks, 1000000000 srt FROM
    (SELECT NAME,parent,mid FROM GROUPS
    WHERE mid>0 CONNECT BY PRIOR gid=parent START WITH parent=an_id) g,
    GROUPS g1
    WHERE g1.gid=g.parent
    ORDER BY 1,2;*/
