   SELECT ABS(TO_DATE(ad_till, 'DD.MM.YYYY') - TO_DATE(ad_from, 'DD.MM.YYYY'))
   INTO   interv
   FROM   DUAL;

   interv := interv + 1;

   OPEN col_t FOR
    SELECT -2 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 25 nwidth, '' vmasks
    FROM   DUAL
    UNION ALL
