    UNION ALL
    SELECT 0 ID, PARENT title1, NAME title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '' vmasks
    FROM   (SELECT   g1.NAME PARENT, g.NAME NAME, g.mid, g.g
            FROM     (SELECT     NAME || ' Показ.сч.' NAME, PARENT, mid, 1 g
                      FROM       GROUPS
                      WHERE      mid > 0
                      CONNECT BY PRIOR gid = PARENT
                      START WITH PARENT = an_id
                      UNION ALL
                      SELECT     'Расход' NAME, PARENT, mid, 2 g
                      FROM       GROUPS
                      WHERE      mid > 0
                      CONNECT BY PRIOR gid = PARENT
                      START WITH PARENT = an_id
                      ORDER BY   3, 4) g,
                     GROUPS g1
            WHERE    g1.gid = g.PARENT
            ORDER BY 1, 3, 4);

