     WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;
    END IF;

    SELECT COUNT(c.currento)
    INTO   temp_i
    FROM   curr_power_arch c
    WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
