     WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;
    END IF;

    SELECT COUNT(c.curr3)
    INTO   temp_i
    FROM   curr_power_arch c
    WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT c.curr3
     INTO   data_t(data_t.COUNT + 1)
     FROM   curr_power_arch c
     WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;
    END IF;

    SELECT COUNT(c.freq)
    INTO   temp_i
    FROM   curr_power_arch c
    WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT c.freq
     INTO   data_t(data_t.COUNT + 1)
     FROM   curr_power_arch c
     WHERE  lc.mid = c.mid AND c.date_time = tmp_date1;
