  ELSIF lv_proc = cv_proc12 THEN
   FOR lc IN (SELECT   g1.NAME pname, g.NAME NAME, g.mid, m.mtrsn meter
              FROM     (SELECT     NAME, PARENT, mid
                        FROM       GROUPS
                        WHERE      mid > 0
                        CONNECT BY PRIOR gid = PARENT
                        START WITH PARENT = an_id) g,
                       GROUPS g1,
                       meters m
              WHERE    g1.gid = g.PARENT AND m.mid = g.mid
              ORDER BY 1, 2) LOOP
    temp_i := data_t.COUNT;
    temp_k := 0;
    tmp_date1 := '01-янв-1900';

    SELECT MAX(date_time)
    INTO   tmp_date1
    FROM   PROFILE
    WHERE  mid = lc.mid AND TO_DATE(date_time, 'DD.MM.YYYY HH24:MI:SS') <= TO_DATE(ad_from, 'DD.MM.YYYY HH24:MI:SS')
           AND TO_DATE(date_time, 'DD.MM.YYYY HH24:MI:SS') >= TO_DATE((ad_from - 0.02083), 'DD.MM.YYYY HH24:MI:SS');

    SELECT COUNT(er)
    INTO   temp_k
    FROM   PROFILE
    WHERE  date_time = tmp_date1 AND mid = lc.mid;

    IF temp_k = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT er
     INTO   data_t(data_t.COUNT + 1)
     FROM   PROFILE
     WHERE  date_time = tmp_date1 AND mid = lc.mid;
    END IF;

    temp_k := 0;

    SELECT COUNT(q1)
    INTO   temp_k
    FROM   PROFILE
    WHERE  date_time = tmp_date1 AND mid = lc.mid;

    IF temp_k = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT q1m
     INTO   data_t(data_t.COUNT + 1)
     FROM   PROFILE
     WHERE  date_time = tmp_date1 AND mid = lc.mid;
    END IF;

    temp_k := 0;

    SELECT COUNT(q3)
    INTO   temp_k
    FROM   PROFILE
    WHERE  date_time = tmp_date1 AND mid = lc.mid;

    IF temp_k = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT q3m
     INTO   data_t(data_t.COUNT + 1)
     FROM   PROFILE
     WHERE  date_time = tmp_date1 AND mid = lc.mid;
    END IF;
   END LOOP;

   RETURN;
  ------------------------------- added by Круглова 24.02.2009------------------
  ELSIF lv_proc = cv_proc13 THEN
   temp_k := 0;

   FOR lc IN (SELECT   g1.NAME pname, g.NAME, g.gid, g.PARENT PARENT
              FROM     (SELECT     NAME, PARENT, mid, gid
                        FROM       GROUPS
                        WHERE      mid > 0
                        CONNECT BY PRIOR gid = PARENT
                        START WITH PARENT = an_id) g,
                       GROUPS g1
              WHERE    g1.gid = g.PARENT
              ORDER BY 1, 2) LOOP
    temp_i := data_t.COUNT;

    SELECT ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)) * DECODE(g.inverted, 'y', -1, 1)), 0), 3) e,
           '' f
    INTO   data_t(temp_i + 1), data_t(temp_i + 2)
    FROM   halfhour h, GROUPS g
    WHERE  g.gid = lc.gid AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till;

    IF (pr_par <> -1) THEN
     data_t(temp_i) := '';
    END IF;

    IF ((pr_par <> lc.PARENT) AND(pr_par <> -1)) THEN
     data_t(temp_i) := temp_k;
     temp_k := data_t(temp_i + 1);
    ELSE
     temp_k := temp_k + data_t(temp_i + 1);
    END IF;

    data_t(temp_i + 2) := temp_k;
    pr_par := lc.PARENT;
   END LOOP;

   RETURN;
  ------------------------------- added by Круглова 24.02.2009------------------
