  ELSIF lv_proc = cv_proc14 THEN
   FOR lc IN (SELECT DISTINCT t.NAME, t.gid, m.mtrsn, m.mid
              FROM            (SELECT     NAME, gid, mid
                               FROM       GROUPS
                               WHERE      mid > 0
                               CONNECT BY PRIOR gid = PARENT
                               START WITH PARENT = an_id) t,
                              meters m
              WHERE           m.mid = t.mid
              ORDER BY        1, 2, 3) LOOP
    SELECT MAX(date_time)
    INTO   tmp_date1
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time <= ad_from;

    SELECT MAX(date_time)
    INTO   tmp_date2
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time <= ad_till;

    --актив
    SELECT COUNT(erm)
    INTO   temp_i
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time = tmp_date2;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT erm
     INTO   data_t(data_t.COUNT + 1)
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time = tmp_date2;
    END IF;

    SELECT COUNT(erm)
    INTO   temp_i
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time = tmp_date1;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT erm
     INTO   data_t(data_t.COUNT + 1)
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time = tmp_date1;
    END IF;

    data_t(data_t.COUNT + 1) := data_t(data_t.COUNT - 1) - data_t(data_t.COUNT);

    SELECT COUNT(nkc)
    INTO   temp_i
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time = tmp_date2;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT nkc
     INTO   data_t(data_t.COUNT + 1)
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time = tmp_date2;
    END IF;

    data_t(data_t.COUNT + 1) := data_t(data_t.COUNT) * data_t(data_t.COUNT - 1);

    --реактив
    SELECT COUNT(q1m)
    INTO   temp_i
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time = tmp_date2;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT q1m
     INTO   data_t(data_t.COUNT + 1)
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time = tmp_date2;
    END IF;

    SELECT COUNT(q1m)
    INTO   temp_i
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time = tmp_date1;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT q1m
     INTO   data_t(data_t.COUNT + 1)
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time = tmp_date1;
    END IF;

    data_t(data_t.COUNT + 1) := data_t(data_t.COUNT - 1) - data_t(data_t.COUNT);

    SELECT COUNT(nkc)
    INTO   temp_i
    FROM   halfhour
    WHERE  mid = lc.mid AND date_time = tmp_date2;

    IF temp_i = 0 THEN
     data_t(data_t.COUNT + 1) := 0;
    ELSE
     SELECT nkc
     INTO   data_t(data_t.COUNT + 1)
     FROM   halfhour
     WHERE  mid = lc.mid AND date_time = tmp_date2;
    END IF;

    data_t(data_t.COUNT + 1) := data_t(data_t.COUNT) * data_t(data_t.COUNT - 1);
   END LOOP;

   RETURN;
