-- Возвращает данные для графического представления состава макета (если график не поддерхивается возвращает 0)
 FUNCTION getmaketgrafvalue(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_col NUMBER, an_row NUMBER, av_title OUT VARCHAR2, av_xtitle OUT VARCHAR2,
 av_ytitle OUT VARCHAR2, x_t OUT common_pg.tt_number, y_t OUT common_pg.tt_number
 )
  RETURN NUMBER IS
  lv_proc             VARCHAR2(256);
  temp_i              NUMBER;
  ln_gid              NUMBER;
  ln_sort             NUMBER;
  ln_flag             NUMBER;
 BEGIN
  x_t.DELETE;
  y_t.DELETE;
  lv_proc := f_gettypeproc(an_fid);

  IF util_pg.get_param(lv_proc, 1, ';') = cv_proc1 THEN
   RETURN 0;
  ELSIF util_pg.get_param(lv_proc, 1, ';') = cv_proc10 THEN
   RETURN uniinterior_vil_pg.getmaketgrafvalue10(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t,
          util_pg.get_param(lv_proc, 2, ';'));
  ELSIF lv_proc = cv_procmaketarm THEN
   RETURN maketarm_pg.f_value_maketarm(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t);
  ELSIF util_pg.get_param(lv_proc, 1, ';') = cv_proc22 THEN
   RETURN uniinterior1_pg.getmaketgrafvalue22(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t,
          util_pg.get_param(lv_proc, 2, ';'));
  ELSIF lv_proc = cv_procmaketarmr THEN                                                                                                                        --
   RETURN maketrecieve_pg.f_getmakegraphvalue(an_id, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t);
  ELSIF util_pg.allnumber_f(util_pg.get_param(lv_proc, 1, ';')) BETWEEN cv_proc_pb3_b AND cv_proc_pb3_e THEN
   RETURN uniinterior3_pg.getgrafvalue(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t);
  ELSIF util_pg.allnumber_f(util_pg.get_param(lv_proc, 1, ';')) BETWEEN cn_proc_out1 AND cn_proc_out2 THEN                           --Для внешних разработчиков
   IF util_pg.get_customer_id = 0 THEN
    RETURN uniinterioroutdem_pg.getgrafvalue(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t);
   ELSE
    RETURN uniinteriorout_pg.getgrafvalue(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, av_title, av_xtitle, av_ytitle, x_t, y_t);
   END IF;
  ELSE                                                                                                                  --***********  Заглушка ****************
   RETURN 0;
  END IF;
 END;

