-- Сохраняет содержимое макета
 PROCEDURE savemaketvalue(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_col NUMBER, an_row NUMBER, an_value NUMBER) IS
  lv_proc             VARCHAR2(256);
 BEGIN
  lv_proc := f_gettypeproc(an_fid);

  IF util_pg.get_param(lv_proc, 1, ';') = cv_proc1 THEN
   NULL;
  ELSIF lv_proc = cv_procmaketarm THEN
   maketarm_pg.savemaketvalue_maketarm(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, an_value);
  ELSIF util_pg.allnumber_f(util_pg.get_param(lv_proc, 1, ';')) BETWEEN cn_proc_out1 AND cn_proc_out2 THEN                           --Для внешних разработчиков
   NULL;
  ELSIF util_pg.allnumber_f(util_pg.get_param(lv_proc, 1, ';')) BETWEEN cv_proc_pb3_b AND cv_proc_pb3_e THEN
   uniinterior3_pg.savevalue(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, an_value);
  ELSIF util_pg.allnumber_f(util_pg.get_param(lv_proc, 1, ';')) BETWEEN cn_proc_out1 AND cn_proc_out2 THEN                           --Для внешних разработчиков
   IF util_pg.get_customer_id = 0 THEN
    uniinterioroutdem_pg.savevalue(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, an_value);
   ELSE
    uniinteriorout_pg.savevalue(an_fid, an_ispoint, an_id, ad_from, ad_till, an_col, an_row, an_value);
   END IF;
  ELSE                                                                                                                  --***********  Заглушка ****************
   NULL;
  END IF;
 END;

