--Что печатать в заголовках
 PROCEDURE get_reportinfo(
 an_fid NUMBER, an_usedeftitle OUT NUMBER, an_usedefphr OUT NUMBER, ab_before IN OUT BLOB, ab_after IN OUT BLOB, an_reporttitle OUT NUMBER,
 an_quality OUT NUMBER, an_showtarzone OUT NUMBER, an_showtimezone OUT NUMBER, an_form_date OUT NUMBER, an_powercoeff OUT NUMBER
 ) IS
 BEGIN
  ab_before := NULL;
  ab_after := NULL;

  SELECT NVL(DECODE(MAX(vvalue), '1', 0, 1), 1)
  INTO   an_usedeftitle
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -1;

  SELECT NVL(DECODE(MAX(vvalue), '1', 0, 1), 1)
  INTO   an_usedefphr
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -2;

  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)
  INTO   an_reporttitle
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -6;

  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)                                                 ---вывод метки качества  (1-выводим, иначе - нет. Если пусто-0)
  INTO   an_quality
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -7;

  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)                                                   ---вывод тарифной зоны (1-выводим, иначе - нет. Если пусто-0)
  INTO   an_showtarzone
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -8;

  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)                                                  ---вывод часового пояса (1-выводим, иначе - нет. Если пусто-0)
  INTO   an_showtimezone
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -9;

  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)                                               ---вывод даты формирования (1-выводим, иначе - нет. Если пусто-0)
  INTO   an_form_date
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -10;

  SELECT NVL(DECODE(MAX(vvalue), '1', 1, 0), 0)                                    ---вывод формата представления данных (1-выводим, иначе - нет. Если пусто-0)
  INTO   an_powercoeff
  FROM   addformparamval
  WHERE  mid = an_fid AND nsort = -11;

  FOR lc IN (SELECT bvalue
             FROM   addformparamval
             WHERE  mid = an_fid AND nsort = -3) LOOP
   ab_before := lc.bvalue;
  END LOOP;

  FOR lc IN (SELECT bvalue
             FROM   addformparamval
             WHERE  mid = an_fid AND nsort = -4) LOOP
   ab_after := lc.bvalue;
  END LOOP;
 END;

-------------------------------------------------------------------------------
 FUNCTION get_number(an_id NUMBER, an_parent NUMBER)                                                                 --функция возвращает номер п/п (cv_proc 16)
  RETURN NUMBER IS
--Определяет номер текущей строки, если PARENT не NULL, и определяет номер родителя, если PARENT NULL
  num                 NUMBER DEFAULT 0;
  par                 NUMBER;
  par2                NUMBER;
  temp                NUMBER;
 BEGIN
  IF an_parent IS NULL THEN
   SELECT PARENT
   INTO   par
   FROM   GROUPS
   WHERE  gid = an_id;

   SELECT PARENT
   INTO   par2
   FROM   GROUPS
   WHERE  gid = par;

   SELECT s.gid, s.rnum
   INTO   temp, num
   FROM   (SELECT     ROWNUM rnum, g.gid, g.NAME
           FROM       GROUPS g
           WHERE      LEVEL = 1 AND g.gid IN(SELECT PARENT
                                             FROM   GROUPS)
           CONNECT BY PRIOR gid = PARENT
           START WITH PARENT = par2
           ORDER SIBLINGS BY NVL(util_pg.get_param(g.vparam, 1), g.NAME)) s
   WHERE  s.gid = par;
  ELSE
   SELECT s.gid, s.rnum
   INTO   temp, num
   FROM   (SELECT     ROWNUM rnum, g.gid, g.NAME
           FROM       GROUPS g
           WHERE      LEVEL = 1                                                                                       --AND g.GID IN (SELECT PARENT FROM GROUPS)
           CONNECT BY PRIOR gid = PARENT
           START WITH PARENT = an_parent
           ORDER SIBLINGS BY NVL(util_pg.get_param(g.vparam, 1), g.NAME)) s
   WHERE  s.gid = an_id;
  END IF;

  RETURN num;
 END;

