--Возвращает прием,отдачу,сальдо по тарифным зонам в зависимости от строчки
--an_gid в формате an_gid*10 + номер строки
 FUNCTION get_param(an_gid NUMBER, ad_from DATE, ad_till DATE)
  RETURN NUMBER IS
  an_param            NUMBER;
  ln_timezona         NUMBER DEFAULT interior_pg.get_hourtimezone;
  lv_ratezona         NUMBER DEFAULT interior_pg.get_ratezona;
  ln_summer           NUMBER DEFAULT interior_pg.get_dsummer;
  cur_t               common_pg.tcur;
  lv_sqltimezone      VARCHAR2(2000);
  lv_sql              VARCHAR2(10000);
 BEGIN
/*IF (((ln_timeZona=-1/24 AND ad_from>to_date('01.11.2010 00:00:00','dd.mm.yyyy hh24:mi:ss')) OR
 (ln_timeZona=0 AND ad_from>to_date('01.04.2011 00:00:00','dd.mm.yyyy hh24:mi:ss'))) AND ln_summer<>0 THEN
 ln_summer:=0;
 END IF;*/
  IF (gn_id = TRUNC(an_gid / 10) AND gd_from = ad_from AND gd_till = ad_till) THEN
   IF MOD(an_gid, 10) = 0 THEN
    RETURN gn_aparam;
   ELSIF MOD(an_gid, 10) = 3 THEN
    RETURN gn_bparam;
   ELSIF MOD(an_gid, 10) = 2 THEN
    RETURN gn_cparam;
   ELSIF MOD(an_gid, 10) = 1 THEN
    RETURN gn_dparam;
   END IF;
  ELSE
   IF (ln_summer = 0) THEN
    lv_sqltimezone :=
        'and P.date_time>= (to_date('''
     || TO_CHAR(ad_from, 'dd.mm.yyyy hh24:mi:ss')
