     || ln_timezona
     || ', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
                       AND TO_CHAR (P.date_time - 1 / 1440- '
     || ln_timezona
     || ', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';
   END IF;

   lv_sql :=
       ' select 
    sum((-util_pg.sld(dd.mid,dd.er,dd.ed))*DECODE( dd.inverted ,''y'',1,-1))/1000  AParam,
    sum((-util_pg.sld(dd.mid,dd.aer,dd.aed))*DECODE( dd.inverted ,''y'',1,-1))/1000 BParam,
    sum((-util_pg.sld(dd.mid,dd.ber,dd.bed))*DECODE( dd.inverted ,''y'',1,-1))/1000  CParam,
    sum((-util_pg.sld(dd.mid,dd.cer,dd.ced))*DECODE( dd.inverted ,''y'',1,-1))/1000  DParam
 FROM(
  SELECT
  p.mid,
  max(G.inverted) inverted,
  sum(p.er*decode(g.NPARTLY,2,0,1)) er,
  sum(p.ed*decode(g.NPARTLY,1,0,1) ) ed ,
  sum(DECODE(r.rate,0,p.er*decode(g.NPARTLY,2,0,1))) aer,
  sum(DECODE(r.rate,0,p.ed*decode(g.NPARTLY,1,0,1))) aed,
  sum(DECODE(r.rate,1,p.er*decode(g.NPARTLY,2,0,1))) ber,
  sum(DECODE(r.rate,1,p.ed*decode(g.NPARTLY,1,0,1))) bed,
  sum(DECODE(r.rate,2,p.er*decode(g.NPARTLY,2,0,1))) cer,
  sum(DECODE(r.rate,2,p.ed*decode(g.NPARTLY,1,0,1))) ced


 FROM halfhour P, GROUPS G, rates r
 WHERE p.mid=g.mid
 AND G.gid IN (SELECT gid FROM GROUPS CONNECT BY PRIOR gid=parent

                 START WITH gid=:par3)

 '
    || lv_sqltimezone
    || '
 AND r.rid=(SELECT rid FROM rate_list WHERE nschedulelist='
    || lv_ratezona
    || '
 AND SWITCH_DATE=(SELECT max(SWITCH_DATE) FROM rate_list
 WHERE SWITCH_DATE<=trunc(p.date_time- '
    || ln_timezona
    || ') AND nschedulelist='
    || lv_ratezona
    || '))
 GROUP BY p.mid ) dd ';

   -- insert into tmp_vil values (lv_RateZona);
   -- commit;
   OPEN cur_t FOR lv_sql USING ROUND(an_gid / 10);

   LOOP
    FETCH cur_t
    INTO  gn_aparam, gn_bparam, gn_cparam, gn_dparam;

    EXIT WHEN cur_t%NOTFOUND;
   END LOOP;

   IF MOD(an_gid, 10) = 0 THEN
    RETURN gn_aparam;
   ELSIF MOD(an_gid, 10) = 3 THEN
    RETURN gn_bparam;
   ELSIF MOD(an_gid, 10) = 2 THEN
    RETURN gn_cparam;
   ELSIF MOD(an_gid, 10) = 1 THEN
    RETURN gn_dparam;
   END IF;
  END IF;
 END;

