 PROCEDURE grouping_p (an_stepprofile NUMBER,ln_timeZona NUMBER, av_grouping OUT VARCHAR2,av_dsummer NUMBER) IS
 BEGIN
IF (av_dsummer=1) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    av_grouping := ' 0+to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymm'') ';
   ELSIF (an_stepprofile = gn_stpday) THEN
  --  av_grouping := ' 0+to_char(P.date_time-1/86400- '||ln_timeZona||',''ddd'') ';
  av_grouping := ' 0+ (trunc(P.date_time-1/86400- '||ln_timeZona||')-to_date(''01.01.1900'',''dd.mm.yyyy'')) ';
   ELSIF (an_stepprofile = gn_stphalfhour) THEN
    av_grouping := ' util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/'||an_stepprofile||' ,0,'||ln_timeZona||','||av_dsummer||') '; 
   END IF;
  ELSE
   IF (an_stepprofile = gn_stpmonth) THEN
    av_grouping := ' 0+to_char(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymm'') ';
   ELSIF (an_stepprofile = gn_stpday) THEN
   -- av_grouping := ' 0+to_char(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''ddd'') ';
    av_grouping := ' 0+(trunc(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource))-to_date(''01.01.1900'',''dd.mm.yyyy'')) ';
   ELSIF (an_stepprofile = gn_stphalfhour) THEN
    av_grouping := ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/'||an_stepprofile||' ,0,'||ln_timeZona||','||av_dsummer||') '; 
   END IF;
 END IF;
 END;
