 PROCEDURE proc_info_21 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE,
                         an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
                         an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur,
                         av_proc  VARCHAR2 ) IS
  ln_locksum   NUMBER         DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);
  an_stepprofile NUMBER;
  
 BEGIN
  IF nvl(util_pg.get_param(av_proc,2,';'),2)= 2 THEN
   an_stepprofile := gn_stpmonth;
   ELSE
   an_stepprofile :=gn_stpday;
   END IF;
   an_cnfixcol := 1;
   an_cntitle := 2;

  OPEN col_t FOR
  SELECT ROWNUM ID,kk. title1,kk. title2,cn_btnface titlecl, cn_left titleal, kk. datacl, cn_center dataal,
           1 nlock, kk. nwidth, '' vmasks FROM
   ( SELECT 1 ID,0 gid, 'Временной интервал' title1, '' title2,100 nwidth,cn_btnface datacl
      FROM DUAL
    UNION ALL
     SELECT tt.rn*10+ll.rn ID,tt.gid,tt.NAME title1, DECODE(ll.rn ,4,'Всего',1,'Ночь',2,'День',3,'Пик') title2,70 nwidth,cn_white datacl
      FROM (SELECT ROWNUM rn,gid, NAME FROM GROUPS WHERE parent=an_id)tt,
      (SELECT ROWNUM rn FROM dict WHERE ROWNUM<=4)ll
  ORDER BY 1, 2)kk;  

 IF(an_stepprofile=gn_stpday) THEN
    OPEN row_t FOR
    SELECT -1 ID,TO_CHAR(ad_from+tt.dt-1,'dd.Mon') title1,
     cn_white datacl, 1 nlock, '' vmasks, 0 srt
     FROM
     ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=
       --(SELECT to_char(ad_till,'ddd')-to_char(ad_from,'ddd')+1 FROM dual))tt
       (SELECT ad_till-ad_from+1 FROM dual))tt
       UNION ALL
     SELECT -1 ID,'Итого:' title1,  cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
       FROM DUAL
      WHERE ln_locksum = 0;

 ELSIF(an_stepprofile=gn_stpmonth) THEN
 
 OPEN row_t FOR
 SELECT -1 ID,TO_CHAR(ADD_MONTHS(ad_from,tt.dt-1),'Mon .YYYY') title1,
     cn_white datacl, 1 nlock, '' vmasks, 0 srt
     FROM
   ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=
   (SELECT ROUND(months_between( ad_till,ad_from))+1 FROM dual))tt
    UNION ALL
     SELECT  -1 ID,'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
       FROM DUAL
      WHERE ln_locksum = 0;
 END IF;
 
 IF(an_stepprofile=gn_stpmonth) THEN
  ad_from:=TRUNC(ad_from,'mm');
  ad_till:=TRUNC(LAST_DAY(ad_till)+1,'mm');
 END IF;
 END;
