  sum(DECODE(r.rate,1,p.er*decode(g.NPARTLY,2,0,1))) ber,
  sum(DECODE(r.rate,1,p.ed*decode(g.NPARTLY,1,0,1))) bed,
  sum(DECODE(r.rate,2,p.er*decode(g.NPARTLY,2,0,1))) cer,
  sum(DECODE(r.rate,2,p.ed*decode(g.NPARTLY,1,0,1))) ced,
  sumqm (p.vqm) vqm

 FROM halfhour P, GROUPS G, rates r
 WHERE p.mid=g.mid
 AND G.gid IN (SELECT gid FROM GROUPS CONNECT BY PRIOR gid=parent

                 START WITH gid=:par3)

 '||lv_sqltimezone||'
 AND r.rid=(SELECT rid FROM rate_list WHERE nschedulelist='||lv_RateZona||'
 AND SWITCH_DATE=(SELECT max(SWITCH_DATE) FROM rate_list
 WHERE SWITCH_DATE<=trunc(p.date_time- '||ln_timeZona||') AND nschedulelist='||lv_RateZona||'))
 GROUP BY p.mid, rollup( ' || lv_grouping || ')ORDER BY 1) dd,
                '||lv_subsel||'
               WHERE dd.BGroup(+)= pp.dat
               GROUP BY pp.dat
               ORDER BY 1 ';
   
       

 
