                 START WITH gid=:par3) ' ||lv_sqltimezone1;*/

FOR lc IN (SELECT ROWNUM rn,gid FROM GROUPS WHERE parent=an_id ORDER BY 1,2)LOOP
 
  test:=lc.rn;
  hh:=0;
 
   OPEN cur_t FOR lv_sql
       USING lc.gid,ld_from,ld_till,ld_from;
    LOOP
     FETCH cur_t INTO ln_BGroup,ln_AParam,ln_BParam,ln_CParam,ln_DParam,lv_qlt;
     EXIT WHEN cur_t%NOTFOUND;

    IF(test=1)THEN
       hh:=0;
       FOR i IN 1..(ln_count*4) LOOP
         data_t(data_t.COUNT+1):=NULL;
       END LOOP;
       temp_k:=data_t.COUNT-ln_count*4;
       
     ELSE
       temp_k:=(test-1)*4+(ln_count*4)*hh;
       hh:=hh+1;
     END IF;
     
       data_t(temp_k+1):=TRUNC(ln_DParam,3);
       data_t(temp_k+2):=TRUNC(ln_CParam,3);
       data_t(temp_k+3):=TRUNC(ln_BParam,3);
       data_t(temp_k+4):=TRUNC(ln_AParam,3);
     
 
                 
/*   OPEN cur_t1 FOR lv_qsql  
   USING lc.gid; 
   LOOP
    FETCH cur_t1 INTO lv_qlt;
    EXIT WHEN cur_t1%NOTFOUND;*/
     IF quantity='q' THEN
         quantity:=nvl(lv_qlt, 'q');
     ELSE
         quantity := qm_pg.sumqm (quantity,lv_qlt);
     END IF;
    
     
     
  /* END LOOP;              
   CLOSE cur_t1;*/
   
    
 
   
  END LOOP;
      
  CLOSE cur_t;
 
 END LOOP;
 
  IF quantity='q' THEN
         quantity:=qm_pg.nodataqm;
         ELSE
         SELECT decode (uniinterior1_pg.is_nodataqm(an_id, ld_from, ld_till), 1, qm_pg.sumqm (quantity,qm_pg.nodataqm), quantity) INTO quantity FROM dual;
     END IF;

 END;
