 PROCEDURE proc_info_28 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE , ad_till IN OUT DATE,
                         an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
                         an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur,
                         av_proc  VARCHAR2, Which_rep NUMBER DEFAULT 0) IS
  ln_locksum   NUMBER         DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);
  an_stepprofile NUMBER;

 BEGIN
  IF nvl(util_pg.get_param(av_proc,2,';'),2) = 1 THEN
    an_stepprofile := gn_stpday;   
  ELSIF nvl(util_pg.get_param(av_proc,2,';'),2) = 2 THEN
    an_stepprofile :=gn_stpmonth;
    if trunc(ad_till) = trunc(last_day(ad_till)) then
        ad_till := ad_till - 1;
    END IF;
  ELSIF nvl(util_pg.get_param(av_proc,2,';'),2) = 3 THEN 
    an_stepprofile := gn_stphalfhour;
  END IF;
  an_cnfixcol := 1;
  an_cntitle := 3;

    IF Which_rep = 1    --процедура 42
    THEN
    OPEN col_t FOR
  SELECT ROWNUM ID,kk. title1,kk. title2,kk. title3,cn_btnface titlecl, cn_left titleal, kk. datacl, cn_center dataal,
           1 nlock, kk. nwidth, '' vmasks FROM
   ( SELECT 1 ID,0 gid, 'Временной интервал' title1,'' title2, '' title3,100 nwidth,cn_btnface datacl
      FROM DUAL
    UNION ALL
     SELECT tt.rn*10+ll.rn ID,tt.gid,tt.NAME title1,'Актив [тыс.кВтч]' title2, DECODE(ll.rn ,1,'Прием',2,'Отдача',3,'Сальдо') title3,70 nwidth,cn_white datacl
      FROM (SELECT ROWNUM rn,gid, NAME FROM GROUPS WHERE parent=an_id)tt,
      (SELECT ROWNUM rn FROM dict WHERE ROWNUM<=3)ll
     UNION ALL
     SELECT 1000 ID,0 gid, 'Суммарный переток' title1,'Актив [тыс.кВтч]' title2, 'Прием' title3,70 nwidth,cn_white datacl
      FROM DUAL
     UNION ALL
     SELECT 1000 ID,0 gid, 'Суммарный переток' title1,'Актив [тыс.кВтч]' title2, 'Отдача' title3,70 nwidth,cn_white datacl
      FROM DUAL
     UNION ALL
     SELECT 1000 ID,0 gid, 'Суммарный переток' title1,'Актив [тыс.кВтч]' title2, 'Сальдо' title3,70 nwidth,cn_white datacl
      FROM DUAL
  ORDER BY 1, 2)kk;
      
    ELSE
  OPEN col_t FOR
  SELECT ROWNUM ID,kk. title1,kk. title2,kk. title3,cn_btnface titlecl, cn_left titleal, kk. datacl, cn_center dataal,
           1 nlock, kk. nwidth, '' vmasks FROM
   ( SELECT 1 ID,0 gid, 'Временной интервал' title1,'' title2, '' title3,100 nwidth,cn_btnface datacl
      FROM DUAL
    UNION ALL
     SELECT tt.rn*10+ll.rn ID,tt.gid,tt.NAME title1,'Актив [тыс.кВтч]' title2, DECODE(ll.rn ,1,'Прием',2,'Отдача',3,'Сальдо') title3,70 nwidth,cn_white datacl
      FROM (SELECT ROWNUM rn,gid, NAME FROM GROUPS WHERE parent=an_id)tt,
      (SELECT ROWNUM rn FROM dict WHERE ROWNUM<=3)ll
  ORDER BY 1, 2)kk;
  END IF;
  
 IF(an_stepprofile=gn_stpday) THEN
    OPEN row_t FOR
    SELECT -1 ID,  TO_CHAR(ad_from+tt.dt-1,'dd.Mon') title1,
     cn_white datacl, 1 nlock, '' vmasks, 0 srt
     FROM
     ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=
     (SELECT ad_till-ad_from+1 FROM dual))tt
      -- (SELECT to_char(ad_till,'ddd')-to_char(ad_from,'ddd')+1 FROM dual))tt
    UNION ALL -- edited by KAG 14.07.2009
     SELECT -1 ID, title1, cn_aqua datacl, 1 nlock, '' vmasks, 0 srt
       FROM (/*SELECT CASE 
                        WHEN MAX(sl.ncount)=3 THEN DECODE (r.rate,
                                                            0, 'Пик',
                                                            1, 'День',
                                                            2, 'Ночь',
                                                        CHR(r.rate+65))
                        ELSE CHR(r.rate+65)            
                   END title1
            FROM rates r, rate_list rl, schedulelist sl, 
            WHERE r.rid = rl.rid
                  AND rl.nschedulelist = interior_pg.get_ratezona
                  AND rl.SWITCH_DATE=(SELECT MAX(SWITCH_DATE) FROM rate_list
                                                             WHERE SWITCH_DATE<=TRUNC(ad_till) AND nschedulelist=interior_pg.get_ratezona)
                  AND rl.nschedulelist = sl.nschedulelist
            GROUP BY r.rate
            ORDER BY r.rate*/
            select decode(Which_rep,1, 'Тариф Т'||rownum, DECODE (rownum-1, --Kruglova edited 15.04.2010
                                0, 'Пик',
                                1, 'День',
                                2, 'Ночь',
                            CHR(rownum-1+65))) title1 from dict where rownum<=(select ncount from schedulelist where nschedulelist=interior_pg.get_ratezona)
        ) WHERE ln_locksum = 0
    UNION ALL
     SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
       FROM DUAL
      WHERE ln_locksum = 0;

 ELSIF(an_stepprofile=gn_stpmonth) THEN


 OPEN row_t FOR
 SELECT -1 ID, TO_CHAR(ADD_MONTHS(ad_from,tt.dt-1),'Mon .YYYY') title1,
     cn_white datacl, 1 nlock, '' vmasks, 0 srt
     FROM
   ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=
   (SELECT ROUND(months_between( ad_till,ad_from))+1 FROM dual))tt
   /* UNION ALL -- edited by KAG 14.07.2009
     SELECT  -1 ID, title1, cn_aqua datacl, 1 nlock, '' vmasks, 0 srt
       FROM (SELECT CASE WHEN Which_rep = 1  --Kruglova edited 15.04.2010
                    THEN  
                        'Тариф Т'||(r.rate+1)
                    ELSE
                        CASE 
                        WHEN MAX(sl.ncount)=3 THEN 
                        DECODE (r.rate,
                                                            0, 'Пик',
                                                            1, 'День',
                                                            2, 'Ночь',
                                                        CHR(r.rate+65))
                        ELSE CHR(r.rate+65)            
                    END 
                   END 
                   title1
            FROM rates r, rate_list rl, schedulelist sl
            WHERE r.rid = rl.rid
                  AND rl.nschedulelist = interior_pg.get_ratezona
                  AND rl.SWITCH_DATE=(SELECT MAX(SWITCH_DATE) FROM rate_list
                                                             WHERE SWITCH_DATE<=TRUNC(LAST_DAY(ad_till)+1,'mm') AND nschedulelist=interior_pg.get_ratezona)
                  AND rl.nschedulelist = sl.nschedulelist
            GROUP BY r.rate
            ORDER BY r.rate) WHERE ln_locksum = 0
            
            /*SELECT ROWNUM rn, rate, to_number(to_char(r.TIME,'SSSSS')) dat_from, to_number(to_char(r.endtime,'SSSSS')) dat_to 
    --FOR lc IN (SELECT ROWNUM rn, rate, to_number(to_char(r.TIME,'yyyymmddhh24miss')) dat_from, to_number(to_char(r.endtime,'yyyymmddhh24miss')) dat_to 
--FOR lc IN (SELECT ROWNUM rn, rate, r.TIME dat_from, r.endtime dat_to 
           FROM rates r
          WHERE r.rid=(SELECT rid FROM rate_list WHERE nschedulelist=interior_pg.get_RateZona
             AND SWITCH_DATE=(SELECT max(SWITCH_DATE) FROM rate_list
                      WHERE SWITCH_DATE <= dt AND nschedulelist=interior_pg.get_RateZona)) 
          ORDER BY r.TIME*/
          -- UNION ALL
          
    UNION ALL -- edited by KAG 14.07.2009
     SELECT -1 ID, title1, cn_aqua datacl, 1 nlock, '' vmasks, 0 srt
       FROM (select decode(Which_rep,1, 'Тариф Т'||rownum, DECODE (rownum-1, --Kruglova edited 15.04.2010
                                0, 'Пик',
                                1, 'День',
                                2, 'Ночь',
                            CHR(rownum-1+65))) title1 from dict where rownum<=(select ncount from schedulelist where nschedulelist=interior_pg.get_ratezona)
        ) WHERE ln_locksum = 0

    UNION ALL
     SELECT  -1 ID,'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
       FROM DUAL
      WHERE ln_locksum = 0;
      
 -- added by KAG 25.12.2009
 ELSIF(an_stepprofile=gn_stphalfhour) THEN
  OPEN row_t FOR
    SELECT -1 ID, DECODE(tt.dt,48,'24:00',TO_CHAR(TRUNC(ad_from)+tt.dt/48,'hh24:mi')) title1,
     cn_white datacl, 1 nlock, '' vmasks, 0 srt
     FROM
     ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=48
       /*(SELECT to_char(ad_till,'ddd')-to_char(ad_from,'ddd')+1 FROM dual)*/)tt
    UNION ALL 
     SELECT -1 ID, title1, cn_aqua datacl, 1 nlock, '' vmasks, 0 srt
       FROM (select 
       decode(Which_rep, 1, 'Тариф Т'||rownum, DECODE (rownum-1,  --Kruglova edited 15.04.2010
                                0, 'Пик',
                                1, 'День',
                                2, 'Ночь',
                            CHR(rownum-1+65))) title1 from dict where rownum<=(select ncount from schedulelist where nschedulelist=interior_pg.get_ratezona)
        ) WHERE ln_locksum = 0
    UNION ALL
     SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
       FROM DUAL
      WHERE ln_locksum = 0;
 END IF;
 IF(an_stepprofile=gn_stpmonth) THEN
  ad_from:=TRUNC(ad_from,'mm');
  ad_till:=TRUNC(LAST_DAY(ad_till)+1,'mm');
 END IF;
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_value_28 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE,
                          ad_till DATE, data_t IN OUT common_pg.tt_number,
                          av_proc  VARCHAR2, quantity     IN OUT   VARCHAR2, Which_rep NUMBER DEFAULT 0
   ) IS

  ln_locksum        NUMBER              DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);
  lv_grouping       VARCHAR2(1000);
  an_stepprofile    NUMBER;
  cur_t             common_pg.tcur;
  cur1_t             common_pg.tcur;
  cur2_t             common_pg.tcur;
  
  ln_gid NUMBER;
  ln_rn NUMBER;
  lv_sql2           VARCHAR2(10000);
 
  ln_timeZona       NUMBER              DEFAULT interior_pg.get_hourtimezone;
  lv_RateZona       NUMBER              DEFAULT interior_pg.get_RateZona;
  
  ln_dsummer        NUMBER              DEFAULT interior_pg.get_dsummer;
  ln_BGroup         NUMBER;
  hh                NUMBER;
  lv_sqltimezone1   VARCHAR2(2000);
  ld_till           DATE;
  ld_from           DATE;
  lv_sql            VARCHAR2(10000);
  lv_sql1            VARCHAR2(10000);
  lv_subsel         VARCHAR2(400);
  ---------
  ParamP            NUMBER;
  ParamO            NUMBER;
  ParamS            NUMBER;
  dt                DATE;
  dat               NUMBER;
  zone_bound        common_pg.tt_number;
  zone_code         common_pg.tt_number;
  step_cnt          NUMBER;
  zone_cnt          NUMBER; -- кол-во тарифов
  gr_cnt            NUMBER; -- кол-во групп в отчете
  bounds_cnt        NUMBER; -- кол-во тарифных зон в сутках
  next_switch       DATE DEFAULT to_date('01.01.1900','dd.mm.yyyy'); -- дата след переключения расписания
  curr_index        NUMBER;
  gr_i              NUMBER; -- номер текущей группы
  lv_qlt            VARCHAR2(1000) DEFAULT NULL;

 BEGIN
 quantity := 'q';
 data_t.DELETE;
 
 IF nvl(util_pg.get_param(av_proc,2,';'),2) = 1 THEN
    an_stepprofile := gn_stpday;   
    
  ELSIF nvl(util_pg.get_param(av_proc,2,';'),2) = 2 THEN
    an_stepprofile :=gn_stpmonth;

  ELSIF nvl(util_pg.get_param(av_proc,2,';'),2) = 3 THEN 
    an_stepprofile := gn_stphalfhour;
  END IF;

 grouping_p (an_stepprofile, ln_timeZona, lv_grouping, ln_dsummer);
 
 IF(an_stepprofile=gn_stpday) THEN
   ld_till:=trunc(ad_till) + 1;-- edited by KAG 17.06.2009
   ld_from:=trunc(ad_from);
 /*  lv_subsel:='( SELECT 0+TO_CHAR(:par1+tt.dt-1,''ddd'') dat
   FROM(
    SELECT ROWNUM dt
     FROM dict WHERE ROWNUM<=
      (SELECT to_char(:par2,''ddd'')
      -to_char(:par1,''ddd'') FROM dual))tt*/
    lv_subsel:='( SELECT 0+(:par1+tt.dt-1-to_date(''01.01.1900'',''dd.mm.yyyy'')) dat
  FROM(
    SELECT ROWNUM dt
     FROM dict WHERE ROWNUM<=
     (SELECT :par2-:par1   FROM dual))tt  
      ) pp ';
   step_cnt := trunc(ld_till) - trunc(ld_from);   

 ELSIF(an_stepprofile=gn_stpmonth) THEN
   ld_from:=TRUNC(ad_from,'mm');
   ld_till   := ad_till;
   if trunc(ld_till) = trunc(last_day(ld_till)) then
        ld_till := ld_till - 1;
    END IF;
    
    ld_till:=TRUNC(LAST_DAY(ld_till)+1,'mm');
   
   lv_subsel:=' ( SELECT 0+TO_CHAR(ADD_MONTHS(:par1,tt.dt-1),''yyyymm'')dat
    FROM
    ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=
     (SELECT ROUND(months_between( :par2,:par1)) FROM dual))tt
     ) pp';
   step_cnt := ROUND(months_between(ld_till, ld_from));
 -- added by KAG 25.12.2009
 ELSIF(an_stepprofile=gn_stphalfhour) THEN
   ld_till:=ad_till;
   ld_from:=ad_from;
   lv_subsel:='( SELECT ROWNUM dat, to_char(:par1,''hh24:mi'') p1, to_char(:par2,''hh24:mi'') p2, to_char(:par1,''hh24:mi'') p3
                   FROM dict WHERE ROWNUM<=48 ) pp ';
   select util_pg.get_count_dt(ld_from,1/48) into step_cnt from dual;
 END IF;
--raise_application_error(-20001,to_char(ld_till,'dd.mm.yy hh24:mi:ss'));
/* IF (ln_dsummer=0) THEN
  lv_sqltimezone :=
         ' and P.date_time>= (to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400 +'||ln_timeZona||' - DECODE('||ln_timeZona_tariff||',0,0,3/24))
         AND  P.date_time <=(to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona||' + DECODE('||ln_timeZona_tariff||',0,0,3/24))
         AND  util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona_tariff||'
         AND  util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona_tariff;
--         AND TO_CHAR (util_pg.to_unlocaltime (P.date_time- 1 / 1440, nsource) - '||ln_timeZona_tariff||', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
--         AND TO_CHAR (util_pg.to_unlocaltime (P.date_time- 1 / 1440, nsource)- '||ln_timeZona_tariff||', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';

 ELSE
  lv_sqltimezone :=
           ' AND  P.date_time >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
            AND  P.date_time <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
--            AND TO_CHAR (P.date_time - 1 / 1440- '||ln_timeZona_tariff||', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
--            AND TO_CHAR (P.date_time - 1 / 1440- '||ln_timeZona_tariff||', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';

 END IF;*/
IF (ln_dsummer=0) THEN
 lv_sqltimezone1 :=
         'and P.date_time>= (to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400 +'||ln_timeZona||' - DECODE('||ln_timeZona||',0,0,3/24))
         AND  P.date_time <=(to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona||' + DECODE('||ln_timeZona||',0,0,3/24))
         AND  util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
         AND  util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
 ELSE
  lv_sqltimezone1 :=
           ' AND  P.date_time >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
            AND  P.date_time <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
  
END IF;

 SELECT count(*)
 INTO gr_cnt
 FROM GROUPS WHERE parent=an_id;
 
 IF Which_rep = 1      --Kruglova 15.04.2010
 THEN
    gr_cnt := gr_cnt + 1;
 END IF;
  
 SELECT ncount 
 INTO zone_cnt
 FROM schedulelist
 WHERE nschedulelist = interior_pg.get_RateZona;
 
 FOR i IN 1 .. (gr_cnt*3*(step_cnt+zone_cnt+1)) LOOP 
  data_t(i) := NULL;
 END LOOP;

 lv_sql :=' select pp.dat,dd.AParam,dd.BParam,dd.CParam,vqm
 FROM(
 SELECT
 ' || lv_grouping || ' BGroup,
   SUM (DECODE (g.inverted, ''y'', NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0), NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0))
   )/ 1000 AParam

   ,SUM (DECODE (g.inverted, ''y'', NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0))
   )/ 1000 BParam

  ,SUM (-util_pg.sld (p.mid, NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0), (NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0)))
  *DECODE(g.inverted ,''y'',1,-1)) / 1000 CParam,
  
  sumqm (p.vqm) vqm

  FROM halfhour p, GROUPS g
  WHERE P.mid=G.mid
  '||lv_sqltimezone1||'
        AND G.gid IN (SELECT gid FROM GROUPS CONNECT BY PRIOR gid=parent
         START WITH gid=:par4)
        GROUP BY  ' || lv_grouping || '
        ORDER BY 1 ) dd,
  '||lv_subsel ||'
   WHERE dd.BGroup(+)= pp.dat
   ORDER BY 1';
-- dbms_output.put_line(lv_sql);
-- insert into tmp_vil values(to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss'));
-- commit;

IF Which_rep = 1
THEN
    lv_sql2 := 'SELECT rn, gid FROM
                (SELECT ROWNUM rn, gid FROM GROUPS WHERE parent=:an_id ORDER BY 1,2)
                UNION ALL
                SELECT :gr_cnt rn, gid FROM GROUPS WHERE gid=:an_id 
                ';
ELSE
    lv_sql2 := 'SELECT ROWNUM rn,gid FROM GROUPS WHERE parent=:an_id ORDER BY 1,2';
END IF;

--FOR lc IN (SELECT ROWNUM rn,gid FROM GROUPS WHERE parent=an_id ORDER BY 1,2) LOOP
IF Which_rep = 1
THEN
    OPEN cur2_t FOR lv_sql2 USING an_id, gr_cnt, an_id;
ELSE
    OPEN cur2_t FOR lv_sql2 USING an_id;
END IF;

LOOP
  FETCH cur2_t INTO ln_rn, ln_gid;
   EXIT WHEN cur2_t%NOTFOUND;

 gr_i:=ln_rn;
 hh:=0;
 ParamP := NULL;
 ParamO := NULL;
 ParamS := NULL;
 lv_qlt := NULL;

 OPEN cur_t FOR lv_sql
   USING ln_gid,ld_from,ld_till,ld_from;
   LOOP
   FETCH cur_t INTO ln_BGroup,ParamP,ParamO,ParamS,lv_qlt;
   EXIT WHEN cur_t%NOTFOUND;
    
    curr_index := hh*gr_cnt*3 + (gr_i-1)*3;
    data_t(curr_index+1) := TRUNC(ParamP,3);
    data_t(curr_index+2) := TRUNC(ParamO,3);
    data_t(curr_index+3) := TRUNC(ParamS,3);
    --raise_application_error(-20001,'**** '||nvl(lv_qlt, 'q')||' *****');
    IF quantity='q' THEN
         quantity:=nvl(lv_qlt, 'q');
         ELSE
         quantity := qm_pg.sumqm (quantity,lv_qlt);
        END IF;
   --- raise_application_error(-20001,'**** '||nvl(lv_qlt, 'q')||' *****');
    --quantity:='**** '||nvl(lv_qlt, 'q')||' *****';

    hh := hh + 1;   
 END LOOP;
 
 CLOSE cur_t;
 --raise_application_error(-20001,quantity);
 IF quantity='q' THEN
         quantity:=qm_pg.nodataqm;
         ELSE
         SELECT decode (uniinterior1_pg.is_nodataqm(an_id, ld_from, ld_till), 1, qm_pg.sumqm (quantity,qm_pg.nodataqm), quantity) INTO quantity FROM dual;

        END IF;
 

 -- added by KAG 16.07.2009
 lv_sql1 :=
       'select
       p.date_time, 
       to_number(to_char(p.date_time - 1/86400,''sssss'')) dat,
       --to_number(to_char(p.date_time - 1/86400,''yyyymmddhh24miss'')) dat,
       --p.date_time dat,
       sum(DECODE(g.inverted, ''y'', p.ed*decode(g.NPARTLY,1,0,1), p.er*decode(g.NPARTLY,2,0,1))) P,
       sum(DECODE(g.inverted, ''y'', p.er*decode(g.NPARTLY,2,0,1), p.ed*decode(g.NPARTLY,1,0,1))) O,
       sum(util_pg.sld(p.mid,p.er*decode(g.NPARTLY,2,0,1),p.ed*decode(g.NPARTLY,1,0,1))*DECODE(g.inverted,''y'',-1,1)) S
       FROM halfhour P, GROUPS g 
       WHERE p.mid=g.mid
       '||lv_sqltimezone1||'
       AND g.gid IN (SELECT gid FROM GROUPS CONNECT BY PRIOR gid=parent
               START WITH gid=:par1)        
        
       GROUP BY p.date_time
       ORDER BY p.date_time ';
        
 ParamP := NULL;
 ParamO := NULL;
 ParamS := NULL;
 
 
 OPEN cur1_t FOR lv_sql1
     USING ln_gid;
  LOOP
   FETCH cur1_t INTO dt, dat, ParamP,ParamO,ParamS;
   EXIT WHEN cur1_t%NOTFOUND;
 
   IF dt>next_switch THEN -- перерасчет действующего расписания
    bounds_cnt := 0;
    FOR lc IN (SELECT ROWNUM rn, rate, to_number(to_char(r.TIME,'SSSSS')) dat_from, to_number(to_char(r.endtime,'SSSSS')) dat_to 
    --FOR lc IN (SELECT ROWNUM rn, rate, to_number(to_char(r.TIME,'yyyymmddhh24miss')) dat_from, to_number(to_char(r.endtime,'yyyymmddhh24miss')) dat_to 
--FOR lc IN (SELECT ROWNUM rn, rate, r.TIME dat_from, r.endtime dat_to 
           FROM rates r
          WHERE r.rid=(SELECT rid FROM rate_list WHERE nschedulelist=interior_pg.get_RateZona
             AND SWITCH_DATE=(SELECT max(SWITCH_DATE) FROM rate_list
                      WHERE SWITCH_DATE <= dt AND nschedulelist=interior_pg.get_RateZona)) 
          ORDER BY r.TIME) LOOP
      zone_bound(lc.rn) := lc.dat_to;
      zone_code(lc.rn) := lc.rate; 
      bounds_cnt := bounds_cnt + 1;
    END LOOP;
    
    -- получение след даты переключения
    SELECT nvl(min(SWITCH_DATE), sysdate) 
     INTO next_switch
     FROM rate_list
     WHERE SWITCH_DATE>=dt AND nschedulelist=interior_pg.get_RateZona; 
    
   END IF;
   
   -- поиск текущей тарифной зоны
   FOR i IN 1..bounds_cnt LOOP
   --raise_application_error(-20001, 'dat '||dat||' zone_bound(i-1) '||zone_bound(i)); 
     IF dat <= zone_bound(i) AND zone_code(i)<zone_cnt THEN
  
      curr_index := gr_cnt*3*step_cnt + 3*(gr_i-1) + gr_cnt*3*zone_code(i);
      data_t(curr_index+1) := util_pg.sumn(data_t(curr_index+1), ParamP);
      data_t(curr_index+2) := util_pg.sumn(data_t(curr_index+2), ParamO);
      data_t(curr_index+3) := util_pg.sumn(data_t(curr_index+3), ParamS);
      EXIT;
     END IF; 
   END LOOP;
   
   --raise_application_error(-20001,zone_cnt); 
   -- подсчет строчки итого (итого может быть больше суммы по тарифам если некоторые тарифные зоны были не учтены)
   curr_index := gr_cnt*3*(step_cnt+zone_cnt) + 3*(gr_i-1);
   data_t(curr_index+1) := util_pg.sumn(data_t(curr_index+1), ParamP);
   data_t(curr_index+2) := util_pg.sumn(data_t(curr_index+2), ParamO);
   data_t(curr_index+3) := util_pg.sumn(data_t(curr_index+3), ParamS);

  END LOOP;
  
 CLOSE cur1_t;
 END LOOP;
 FOR i IN (gr_cnt*step_cnt*3+1) .. (gr_cnt*3*(step_cnt+zone_cnt+1)) LOOP 
  data_t(i) := TRUNC(data_t(i)/1000,3);
  IF data_t(i) IS NULL THEN
   data_t(i) := 0;
  END IF;
 END LOOP; 

END;
 -------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_info_29 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE , ad_till IN OUT DATE,
             an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
             an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur) IS
 BEGIN
 an_cnfixcol := 2;
  an_cntitle := 2;
   OPEN col_t FOR
   SELECT  1 ID, '№ п/п' title1,'' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 20 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  2 ID, ' Найменування перетікання ' title1,'' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 315 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  3 ID, 'Сума всіх зон' title1,'Прийом тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  4 ID, 'Сума всіх зон' title1,'Віддача тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  5 ID, 'Сума всіх зон' title1,'Сальдо тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  6 ID, 'Нічна зона' title1,'Прийом тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  7 ID, 'Нічна зона' title1,'Віддача тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  8 ID, 'Нічна зона' title1,'Сальдо тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  9 ID, 'Денна зона' title1,'Прийом тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  10 ID, 'Денна зона' title1,'Віддача тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  11 ID, 'Денна зона' title1,'Сальдо тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
   UNION ALL
  SELECT  12 ID, 'Пікова зона' title1,'Прийом тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  13 ID, 'Пікова зона' title1,'Віддача тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  UNION ALL
  SELECT  14 ID, 'Пікова зона' title1,'Сальдо тис.кВтг.' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 75 nwidth, '' vmasks
    FROM DUAL
  ORDER BY 1;

  OPEN row_t FOR
  /* select rownum title1,kk.gid ID, kk.name title2,DECODE(kk.mid,NULL,cn_aqua, cn_white) datacl, 0 nlock, '' vmasks from
   (SELECT gid,mid, NAME,parent FROM GROUPS CONNECT BY PRIOR gid=parent START WITH parent=an_id)kk
   WHERE kk.parent<>an_id;*/
  SELECT ID, title1, title2, datacl, nlock, vmasks, srt from
     (SELECT kk.gid ID, to_char(kk.sortl) title1 , kk.NAME title2,DECODE(kk.mid,NULL,cn_aqua, cn_white) datacl, 1 nlock, '' vmasks, 0 srt, kk.sortl , kk.rn FROM
      (SELECT nvl(to_number(vparam),100) sortl,ROWNUM rn,gid,mid, NAME,g.parent ,vparam FROM GROUPS g CONNECT BY PRIOR gid=parent START WITH parent=an_id)kk
       WHERE parent<>an_id
       UNION ALL
      /* select 200 sort, '' title1,0 gid, 'Украина-Центр' name, cn_aqua datacl,0 nlock, '' vmasks from dict where rownum=1
       UNION ALL
       SELECT 400 SORT, '' title1, 0 gid, 'Украина-Северный Кавказ' NAME, cn_aqua datacl,0 nlock, '' vmasks FROM dict WHERE ROWNUM=1
       UNION ALL*/
       SELECT gid,'' title1, 'Разом Україна-Росія' vname ,cn_yellow datacl, 1 nlock, '' vmasks , 0 srt,50000 sortl,50000 rn FROM GROUPS WHERE gid=an_id
       UNION ALL
       SELECT gid,'' title1, NAME||'-Росія' vname ,cn_yellow datacl, 1 nlock, '' vmasks , 0 srt,60000 sortl,60000 rn FROM GROUPS WHERE parent=an_id)
  ORDER BY sortl, rn;
END;
