 PROCEDURE proc_value_29 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE,
             ad_till DATE, data_t IN OUT common_pg.tt_number,quantity     IN OUT   VARCHAR2
             ) IS
 
 
 
 temp_i      NUMBER;
 ln_timeZona_tariff    NUMBER       DEFAULT interior_pg.get_hourtimezone;
 lv_RateZona    NUMBER       DEFAULT interior_pg.get_RateZona;
 ln_dsummer    NUMBER       DEFAULT interior_pg.get_dsummer;
 lc1_AParamP    NUMBER;
 lc1_AParamO    NUMBER;
 lc1_AParamS    NUMBER;
 lc1_DParamP    NUMBER;
 lc1_DParamO    NUMBER;
 lc1_DParamS    NUMBER;
 lc1_CParamP    NUMBER;
 lc1_CParamO    NUMBER;
 lc1_CParamS    NUMBER;
 lc1_BParamP    NUMBER;
 lc1_BParamO    NUMBER;
 lc1_BParamS    NUMBER;
 cur_t       common_pg.tcur;
 lv_sqltimezone  VARCHAR2(2000);
 lv_sql      VARCHAR2(10000);
 lv_qlt            VARCHAR2(1000) DEFAULT NULL;
 BEGIN
 quantity := 'q';
 data_t.DELETE;
 temp_i:=0;
 
 IF (ln_dsummer=0) THEN
  lv_sqltimezone :=
         'and P.date_time>= (to_date('''||to_char(ad_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400 +'||ln_timeZona_tariff||' - DECODE('||ln_timeZona_tariff||',0,0,3/24))
         AND  P.date_time <=(to_date('''||to_char(ad_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona_tariff||' + DECODE('||ln_timeZona_tariff||',0,0,3/24))
         AND  util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''||to_char(ad_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona_tariff||'
         AND  util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''||to_char(ad_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona_tariff||'
         AND TO_CHAR (util_pg.to_unlocaltime (P.date_time- 1 / 1440, nsource) - '||ln_timeZona_tariff||', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
         AND TO_CHAR (util_pg.to_unlocaltime (P.date_time- 1 / 1440, nsource)- '||ln_timeZona_tariff||', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';

 ELSE
  lv_sqltimezone :=
           ' AND  P.date_time >= to_date('''||to_char(ad_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona_tariff||'
            AND  P.date_time <= to_date('''||to_char(ad_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona_tariff ||'
            AND TO_CHAR (P.date_time - 1 / 1440- '||ln_timeZona_tariff||', ''sssss'') >= TO_CHAR (r.TIME, ''sssss'')
            AND TO_CHAR (P.date_time - 1 / 1440- '||ln_timeZona_tariff||', ''sssss'') < TO_CHAR (r.endtime, ''sssss'') ';

 END IF;
 lv_sql :=' select
  sum(DECODE( dd.inverted ,''y'',dd.ed, dd.er))/1000 AParamP,
  sum(DECODE( dd.inverted ,''y'',dd.er, dd.ed))/1000 AParamO,
  sum((-util_pg.sld(dd.mid,dd.er,dd.ed))*DECODE( dd.inverted ,''y'',1,-1))/1000 AParamS,

  sum(DECODE( dd.inverted ,''y'',dd.ced , dd.cer))/1000 DParamP,
  sum(DECODE( dd.inverted ,''y'',dd.cer ,dd.ced))/1000 DParamO,
  sum((-util_pg.sld(dd.mid,dd.cer,dd.ced))*DECODE( dd.inverted ,''y'',1,-1))/1000 DParamS,

  sum(DECODE( dd.inverted ,''y'',dd.bed , dd.ber))/1000 CParamP,
  sum(DECODE( dd.inverted ,''y'',dd.ber, dd.bed))/1000 CParamO,
  sum((-util_pg.sld(dd.mid,dd.ber,dd.bed))*DECODE( dd.inverted ,''y'',1,-1))/1000 CParamS,

  sum(DECODE( dd.inverted ,''y'',dd.aed , dd.aer))/1000 BParamP,
  sum(DECODE( dd.inverted ,''y'',dd.aer, dd.aed))/1000 BParamO,
  sum((-util_pg.sld(dd.mid,dd.aer,dd.aed))*DECODE( dd.inverted ,''y'',1,-1))/1000 BParamS,
  SUMQM(dd. decnsour) decnsour
 FROM(
 SELECT
 p.mid,
 max(G.inverted) inverted,
 sum(p.er*decode(g.NPARTLY,2,0,1)) er,
 sum(p.ed*decode(g.NPARTLY,1,0,1) ) ed ,
 sum(DECODE(r.rate,0,p.er*decode(g.NPARTLY,2,0,1))) aer,
 sum(DECODE(r.rate,0,p.ed*decode(g.NPARTLY,1,0,1))) aed,
 sum(DECODE(r.rate,1,p.er*decode(g.NPARTLY,2,0,1))) ber,
 sum(DECODE(r.rate,1,p.ed*decode(g.NPARTLY,1,0,1))) bed,
 sum(DECODE(r.rate,2,p.er*decode(g.NPARTLY,2,0,1))) cer,
 sum(DECODE(r.rate,2,p.ed*decode(g.NPARTLY,1,0,1))) ced,
 sumqm (p.vqm) decnsour
 FROM halfhour P, GROUPS G, rates r
 WHERE p.mid=g.mid
 AND G.gid IN (SELECT gid FROM GROUPS CONNECT BY PRIOR gid=parent
         START WITH gid=:par1)

 '||lv_sqltimezone||'
 AND r.rid=(SELECT rid FROM rate_list WHERE nschedulelist='||lv_RateZona||'
 AND SWITCH_DATE=(SELECT max(SWITCH_DATE) FROM rate_list
 WHERE SWITCH_DATE<=trunc(p.date_time- '||ln_timeZona_tariff||') AND nschedulelist='||lv_RateZona||'))
 GROUP BY p.mid) dd ';

  FOR lc IN (SELECT kk.SORT,kk.rn, kk.gid gid,kk.parent parent,kk.vparam vparam FROM
   (SELECT nvl(to_number(vparam),100) SORT,ROWNUM rn,gid,parent,vparam
   FROM GROUPS CONNECT BY PRIOR gid=parent START WITH parent=an_id)kk
   WHERE kk.parent<>an_id
   UNION ALL
   SELECT 50000 SORT,50000 rn, gid,parent,vparam FROM GROUPS WHERE gid=an_id
   UNION ALL
   SELECT 60000 SORT,60000 rn,gid,parent,vparam FROM GROUPS WHERE parent=an_id
   ORDER BY 1,2
   ) LOOP
 -- IF lc.parent<> an_id AND lc.gid<>an_id THEN
   FOR z IN 1..12 LOOP
   data_t (temp_i + z):=NULL;
   END LOOP;
 /* ELSE
   FOR z IN 1..12 LOOP --Северная
   temp_summ (temp_k + z):=NULL;
   END LOOP;
  END IF;*/

-- delete from tmp_vil;
-- insert into tmp_vil values (an_id||' '||lv_sql);commit;


 OPEN cur_t FOR lv_sql
   USING lc.gid;
   LOOP
   FETCH cur_t INTO lc1_AParamP,lc1_AParamO,lc1_AParamS,
           lc1_DParamP,lc1_DParamO,lc1_DParamS,
           lc1_CParamP,lc1_CParamO,lc1_CParamS,
           lc1_BParamP,lc1_BParamO,lc1_BParamS,lv_qlt;
   EXIT WHEN cur_t%NOTFOUND;

      -- IF lc.parent<> an_id AND lc.gid<>an_id THEN
         data_t (temp_i+1):=TRUNC(lc1_AParamP,3);
         data_t (temp_i+2):=TRUNC(lc1_AParamO,3);
         data_t (temp_i+3):=TRUNC(lc1_AParamS,3);

         data_t (temp_i+4):=TRUNC(lc1_DParamP,3);
         data_t (temp_i+5):=TRUNC(lc1_DParamO,3);
         data_t (temp_i+6):=TRUNC(lc1_DParamS,3);

         data_t (temp_i+7):=TRUNC(lc1_CParamP,3);
         data_t (temp_i+8):=TRUNC(lc1_CParamO,3);
         data_t (temp_i+9):=TRUNC(lc1_CParamS,3);

         data_t (temp_i+10):=TRUNC(lc1_BParamP,3);
         data_t (temp_i+11):=TRUNC(lc1_BParamO,3);
         data_t (temp_i+12):=TRUNC(lc1_BParamS,3);
      /* ELSE
         temp_summ (temp_k+1):=lc1.AParamP;
         temp_summ (temp_k+2):=lc1.AParamO;
         temp_summ (temp_k+3):=lc1.AParamS;

         temp_summ (temp_k+4):=lc1.DParamP;
         temp_summ (temp_k+5):=lc1.DParamO;
         temp_summ (temp_k+6):=lc1.DParamS;

         temp_summ (temp_k+7):=lc1.CParamP;
         temp_summ (temp_k+8):=lc1.CParamO;
         temp_summ (temp_k+9):=lc1.CParamS;

         temp_summ (temp_k+10):=lc1.BParamP;
         temp_summ (temp_k+11):=lc1.BParamO;
         temp_summ (temp_k+12):=lc1.BParamS;
       END IF;*/
        IF quantity='q' THEN
         quantity:=nvl(lv_qlt, 'q');
         ELSE
         quantity := qm_pg.sumqm (quantity,lv_qlt);
        END IF;
       
      END LOOP;
 CLOSE cur_t;
   temp_i:=data_t.COUNT;
   -- temp_k:=temp_summ.COUNT;
 END LOOP;
 
  IF quantity='q' THEN
         quantity:=qm_pg.nodataqm;
         ELSE
         SELECT decode (uniinterior1_pg.is_nodataqm(an_id, ad_from, ad_till), 1, qm_pg.sumqm (quantity,qm_pg.nodataqm), quantity) INTO quantity FROM dual;

        END IF;

 /* FOR k IN 1..24 LOOP
  data_t(data_t.COUNT +1):=NULL;
  END LOOP;

  FOR i IN 1..temp_summ.COUNT LOOP
  data_t(data_t.COUNT +1):=temp_summ(i);
  END LOOP;*/
END;
 -------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_info_10 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE,
             an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
             an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur,
             av_proc VARCHAR2 )IS
 an_stepprofile NUMBER;
 lv_subsel VARCHAR2(1000);
 ld_from NUMBER;
 ln_www NUMBER;
 ld_fromm DATE;
 ld_tilll DATE;
 lv_selrow VARCHAR(4000);
 BEGIN
  an_cnfixcol := 4;
  an_cntitle := 2;
  
 IF util_pg.get_param(av_proc,2,';')= 2 THEN
  ld_fromm:=TRUNC(ad_from,'yyyy')+1/86400;
  ld_tilll:=ADD_MONTHS(TRUNC(ad_from,'yyyy'),12);
 ELSIF nvl(util_pg.get_param(av_proc,2,';'),1)= 1 THEN
  ld_fromm:=TRUNC(ad_from,'mm')+1/86400;
  ld_tilll:=TRUNC(LAST_DAY(ad_from)+1,'mm');
 ELSIF util_pg.get_param(av_proc,2,';')= 3 THEN
  ld_fromm:=ad_from+1/86400;
  ld_tilll:=ad_from+1;
 END IF;
  
  
  IF(interior_pg.get_powercoeff=1000)THEN
  ln_www:=60;
  ELSE
  ln_www:=90;
  END IF;
 IF util_pg.get_param(av_proc,2,';')=2 THEN
  an_stepprofile := gn_stpmonth;
  lv_subsel:='SELECT  t.ID + 6, ''Расход c'' || '' '' || TO_CHAR (:par1, ''dd.Mon.yyyy'')|| ''  по '' || TO_CHAR (:par2, ''dd.Mon.yyyy'')||'' '' ||''год'' title1,
  TO_CHAR (TO_DATE ( t.ID, ''mm''), ''Mon'') title2,
       '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_white||' datacl, '||cn_right||' dataal, 1 nlock, '||ln_www||' nwidth, '''' vmasks
    FROM (SELECT ROWNUM ID
        FROM dict
        WHERE ROWNUM <= 12

       ) t ';
 ELSIF nvl(util_pg.get_param(av_proc,2,';'),1)= 1 THEN
  an_stepprofile :=gn_stpday;
  ld_from:= TO_CHAR(LAST_DAY(ad_from),'dd');
  ad_from:=LAST_DAY(ad_from);
  lv_subsel:='SELECT  t.ID + 6, ''Расход c'' || '' '' || TO_CHAR (:par1, ''dd.Mon.yyyy'')|| ''  по '' || TO_CHAR (:par2, ''dd.Mon.yyyy'') title1,
  TO_CHAR (TO_DATE ( t.ID, ''dd''), ''dd'') title2,
       '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_white||' datacl, '||cn_right||' dataal, 1 nlock, '||ln_www||' nwidth, '''' vmasks
    FROM (SELECT ROWNUM ID
        FROM dict
        WHERE ROWNUM <= '||ld_from||'

       ) t ';
  
 ELSIF util_pg.get_param(av_proc,2,';')= 3 THEN
  an_stepprofile :=gn_stphour;
  lv_subsel:='SELECT  t.ID + 6, ''Расход с'' || '' '' || TO_CHAR (:par1, ''dd.mm.yyyy'')|| ''  по '' || TO_CHAR (:par2, ''dd.mm.yyyy'') title1, DECODE(t.ID,25,''25:00'',TO_CHAR (TO_DATE (DECODE (t.ID, 24, 0, t.ID), ''hh24''), ''hh24:mi'')) title2,
       '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_white||' datacl, '||cn_right||' dataal, 1 nlock, '||ln_www||' nwidth, '''' vmasks
    FROM (SELECT ROWNUM ID
        FROM dict
              WHERE ROWNUM <= 25

       ) t ';
 END IF;
 


  OPEN col_t FOR
  ' SELECT  1 ID, ''Наименование'' title1, '''' title2, '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_btnface||' datacl, '||cn_left||' dataal, 1 nlock, 240 nwidth, '''' vmasks
    FROM DUAL
  UNION ALL
  SELECT  2 ID, '' Прием / Отдача Сальдо '' title1, '''' title2, '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_btnface||' datacl, '||cn_left||' dataal, 1 nlock, 50 nwidth, '''' vmasks
    FROM DUAL
  UNION ALL
  SELECT  3 ID, '' Код объекта '' title1, '''' title2, '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_btnface||' datacl, '||cn_left||' dataal, 1 nlock, 50 nwidth, '''' vmasks
    FROM DUAL
  UNION ALL
  SELECT  4 ID, '' Код канала учета '' title1, '''' title2, '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_btnface||' datacl, '||cn_left||' dataal, 1 nlock, 50 nwidth, '''' vmasks
    FROM DUAL
  UNION ALL
  SELECT  5 ID, ''Сумма'' title1, '''' title2, '||cn_btnface||' titlecl, '||cn_center||' titleal, '||cn_yellow||' datacl, '||cn_right||' dataal, 1 nlock, 90 nwidth, '''' vmasks
    FROM DUAL
  UNION ALL
   '||lv_subsel||'
  
  ORDER BY 1 '
--  USING ad_from , ad_till;
USING ld_fromm , ld_tilll;
  
IF an_ispoint=1 THEN
 IF util_pg.isfolder (an_id) = 1 THEN
  lv_selrow:=' SELECT tt.gid ID, decode(nvl(tt.npartly,0),1,tt.NAME,2,tt.NAME,decode(tt.SORT,1,tt.NAME,'' '')) title1, tt.title2, tt.title3,tt.title4, tt.datacl, 1 nlock, '''' vmasks, 0 srt

   FROM (
     SELECT  NVL (mid, 0) mid, PARENT, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid))NAME, '' Прием '' title2, UNIINTERIOR_VIL_PG.get_cod(mid,-41,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(mid,-31,'||an_ispoint||') title4, 1 SORT, (mid * 10 + 1) gid, NULL npartly, '||cn_white||' datacl
     
        FROM points p
     WHERE p.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) and cod=0 start with mid='||an_id||') and p.ind  in (3,4)
      UNION ALL
      
      SELECT  NVL (mid, 0) mid, PARENT, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, '' Отдача '' title2,
      UNIINTERIOR_VIL_PG.get_cod(mid,-42,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(mid,-32,'||an_ispoint||') title4, 2 SORT, (mid * 10 + 2) gid, NULL npartly, '||cn_white||' datacl
        FROM points p
     WHERE p.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) and cod=0 start with mid='||an_id||') and p.ind  in (3,4)
      UNION ALL
     
      SELECT  NVL (mid, 0) mid, PARENT,nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, '' Сальдо '' title2,
      UNIINTERIOR_VIL_PG.get_cod(mid,-45,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(mid,-35,'||an_ispoint||') title4, 3 SORT, (mid * 10) gid, NULL npartly, '||cn_aqua||' datacl
        FROM points p
     WHERE p.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) and cod=0 start with mid='||an_id||') and p.ind  in (3,4)
      ORDER BY 2, 3, 7) tt';
 ELSE
     lv_selrow:=' SELECT tt.gid ID, decode(nvl(tt.npartly,0),1,tt.NAME,2,tt.NAME,decode(tt.SORT,1,tt.NAME,'' '')) title1, tt.title2, tt.title3,tt.title4, tt.datacl, 1 nlock, '''' vmasks, 0 srt

   FROM (
     SELECT  NVL (mid, 0) mid, PARENT, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid))NAME, '' Прием '' title2,
     UNIINTERIOR_VIL_PG.get_cod(mid,-41,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(mid,-31,'||an_ispoint||') title4, 1 SORT, (mid * 10 + 1) gid, NULL npartly, '||cn_white||' datacl
     
        FROM points p
     WHERE p.mid= '||an_id||'
      UNION ALL
      
      SELECT  NVL (mid, 0) mid, PARENT, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, '' Отдача '' title2,
      UNIINTERIOR_VIL_PG.get_cod(mid,-42,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(mid,-32,'||an_ispoint||') title4, 2 SORT, (mid * 10 + 2) gid, NULL npartly, '||cn_white||' datacl
        FROM points p
      WHERE p.mid= '||an_id||'
      UNION ALL
     
      SELECT  NVL (mid, 0) mid, PARENT,nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, '' Сальдо '' title2,
      UNIINTERIOR_VIL_PG.get_cod(mid,-45,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(mid,-35,'||an_ispoint||') title4, 3 SORT, (mid * 10) gid, NULL npartly, '||cn_aqua||' datacl
        FROM points p
     WHERE p.mid= '||an_id||'
      ORDER BY 2, 3, 7) tt';
 END IF;
ELSE
  lv_selrow:=' SELECT tt.gid ID, decode(nvl(tt.npartly,0),1,tt.NAME,2,tt.NAME,decode(tt.SORT,1,tt.NAME,'' '')) title1, tt.title2, tt.title3,tt.title4, tt.datacl, 1 nlock, '''' vmasks, 0 srt

   FROM (
     SELECT  NVL (mid, 0) mid, PARENT, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid))NAME, '' Прием '' title2,
     UNIINTERIOR_VIL_PG.get_cod(gid,-41,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(gid,-31,'||an_ispoint||') title4, 1 SORT, (gid * 10 + 1) gid, npartly, '||cn_white||' datacl
     
        FROM GROUPS g
        WHERE gid IN (SELECT   gid
                  FROM GROUPS
               CONNECT BY PRIOR gid = PARENT
               START WITH PARENT = '||an_id||') AND mid > 0 AND (g.npartly IS NULL OR g.npartly = 1)
      UNION ALL
      
      SELECT  NVL (mid, 0) mid, PARENT, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, '' Отдача '' title2,
      UNIINTERIOR_VIL_PG.get_cod(gid,-42,'||an_ispoint||') title3,
     UNIINTERIOR_VIL_PG.get_cod(gid,-32,'||an_ispoint||') title4, 2 SORT, (gid * 10 + 2) gid, npartly, '||cn_white||' datacl
        FROM GROUPS g
        WHERE gid IN (SELECT   gid
                  FROM GROUPS
               CONNECT BY PRIOR gid = PARENT
               START WITH PARENT = '||an_id||') AND mid > 0 AND (g.npartly IS NULL OR g.npartly = 2)
      UNION ALL
     
      SELECT  NVL (mid, 0) mid, PARENT,nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, '' Сальдо '' title2,
      UNIINTERIOR_VIL_PG.get_cod(gid,-45,'||an_ispoint||') title3,
      UNIINTERIOR_VIL_PG.get_cod(gid,-35,'||an_ispoint||') title4, 3 SORT, (gid * 10) gid, npartly, '||cn_aqua||' datacl
        FROM GROUPS g
        WHERE gid IN (SELECT   gid
                  FROM GROUPS
               CONNECT BY PRIOR gid = PARENT
               START WITH PARENT = '||an_id||') AND mid > 0 AND (npartly IS NULL)
      ORDER BY 2, 3, 7) tt';
      
END IF;
  -- insert into 
  OPEN row_t FOR lv_selrow;
 
END;
-----------------------------------------------------------------------------------------------------------------
PROCEDURE proc_value_10 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE,
             ad_till DATE, data_t IN OUT common_pg.tt_number,
             av_proc VARCHAR2 ) IS

 temp_i      NUMBER;
 temp_k      NUMBER;
 ln_flag      NUMBER;
 an_stepprofile  NUMBER;
 ld_from      DATE;
 ld_till      DATE;
 av_grouping    VARCHAR2(1000);
 ln_count     NUMBER;
 cur_t       common_pg.tcur;
 lc          common_pg.tcur;
 lv_sql1      VARCHAR2(4000);
 lv_sql2      VARCHAR2(4000);
 lv_sql3      VARCHAR2(4000);
 ln_BGroup     NUMBER;
 ln_AParam     NUMBER;
 ln_BParam     NUMBER;
 ln_CParam     NUMBER;
 ln_DParam     NUMBER;
 ln_timeZona   NUMBER              DEFAULT interior_pg.get_hourtimezone;
 ln_dsummer    NUMBER              DEFAULT interior_pg.get_dsummer;
 lv_sqltimezone VARCHAR2(2000);
 ln_rowcof NUMBER DEFAULT interior_pg.get_powercoeff;
 lv_subsel   VARCHAR2(1000);
 lv_table VARCHAR2(256);
 lv_selmid  VARCHAR2(4000);
 lv_selgid  VARCHAR(60);
 
 ln_mid NUMBER;
 ln_parent NUMBER;
 ln_gid NUMBER;
 lv_name VARCHAR2(256);
 ln_sort NUMBER;
BEGIN

/* IF (((ln_timeZona=-1/24 AND ad_from>to_date('01.11.2010 00:00:00','dd.mm.yyyy hh24:mi:ss')) OR
 (ln_timeZona=0 AND ad_from>to_date('01.04.2011 00:00:00','dd.mm.yyyy hh24:mi:ss'))) AND ln_summer<>0 THEN
 ln_summer:=0;
 END IF;*/

 IF util_pg.get_param(av_proc,2,';')= 2 THEN
  an_stepprofile := gn_stpmonth;
  ln_count:=13;
  ld_from:=TRUNC(ad_from,'yyyy')+1/86400;
  ld_till:=ADD_MONTHS(TRUNC(ad_from,'yyyy'),12);
 ELSIF nvl(util_pg.get_param(av_proc,2,';'),1)= 1 THEN
  an_stepprofile :=gn_stpday;
  SELECT TO_CHAR(LAST_DAY(ad_from),'dd')+1
  INTO ln_count
  FROM dual;
  ld_from:=TRUNC(ad_from,'mm')+1/86400;
  ld_till:=TRUNC(LAST_DAY(ad_from)+1,'mm');
 ELSIF util_pg.get_param(av_proc,2,';')= 3 THEN
  an_stepprofile :=gn_stphour;
  ln_count:=26;
  ld_from:=ad_from+1/86400;
  ld_till:=ad_from+1;
 END IF;
IF (an_stepprofile = gn_stpmonth OR an_stepprofile = gn_stpday) THEN
interior_pg.grouping_p (an_stepprofile ,to_char(ld_from,'dd.mm.yyyy hh24:mi:ss'),24,av_grouping);
ELSE
  IF (ln_dsummer=1) THEN
  av_grouping := ' util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/24 ,1,'||ln_timeZona||','||ln_dsummer||') ';
  ELSE
  av_grouping := ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/24 ,1,'||ln_timeZona||','||ln_dsummer||') ';
  END IF;
END IF;

 IF an_ispoint=1 THEN 
       IF util_pg.isfolder (an_id) = 1 THEN
          lv_subsel := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) and cod=0 start with mid='||an_id||') and G.ind  in (3,4)';
        ELSE
          lv_subsel := ' G.mid=' || an_id;
      END IF;
         lv_table:='points ';
         lv_selgid:='NULL gid ';
      --   lv_inverted := ' ''n'' ';
      --   lv_partly_er := ' ';
      --   lv_partly_ed := ' ';
 ELSE 
     lv_subsel :=
         ' G.gid IN (SELECT   gid
                   FROM GROUPS
                CONNECT BY PRIOR gid = PARENT
                START WITH PARENT = '||an_id||') AND G.mid > 0 ';
     lv_table:='groups ';
     lv_selgid:='G.gid gid ';
    -- lv_inverted := 'G.inverted';
    -- lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
    -- lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
  END IF;
  
  
 lv_selmid:='
        SELECT  NVL (G.mid, 0) mid, PARENT,nvl(util_pg.get_shortname_f(G.short_name,G.mid),util_pg.get_name_f(G.NAME,G.mid)) NAME, 1 SORT,'||lv_selgid||'
         FROM '||lv_table||' G
         WHERE '||lv_subsel||'
       ORDER BY 2, 3, 4';

/* FOR lc IN (SELECT  NVL (mid, 0) mid, PARENT,nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(NAME,mid)) NAME, 1 SORT, gid
         FROM GROUPS
         WHERE gid IN (SELECT   gid
                   FROM GROUPS
                CONNECT BY PRIOR gid = PARENT
                START WITH PARENT = an_id) AND mid > 0
       ORDER BY 2, 3, 4) LOOP*/
  OPEN lc FOR lv_selmid;
  LOOP
  FETCH lc INTO  ln_mid,  ln_parent, lv_name,ln_sort, ln_gid;
  EXIT WHEN lc%NOTFOUND;
       
  temp_k := data_t.COUNT;

  temp_i := data_t.COUNT;
  ln_flag:=0;

  
   IF (ln_dsummer=0) THEN
   lv_sqltimezone :=
                  'and P.date_time>= (to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400 +'||ln_timeZona||' - DECODE('||ln_timeZona||',0,0,3/24))
                  AND   P.date_time <=(to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona||' + DECODE('||ln_timeZona||',0,0,3/24))
                  AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
                  AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
                  

  ELSE
   lv_sqltimezone :=
                     ' AND   P.date_time >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
                       AND   P.date_time <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
                       
  END IF;
  
 IF an_ispoint=1 THEN 
  lv_sql1:=' SELECT round (tt.aparam, 3) aparam, bgroup
         FROM (SELECT  DECODE (GROUPING ('||av_grouping||'),
                     1, 0,
                     '||av_grouping||'
                    ) bgroup,
                 SUM (p.er) / '||ln_rowcof||' aparam
             FROM halfhour p, points g
             WHERE p.mid = g.mid 
             '||lv_sqltimezone||'
             AND p.mid = '||ln_mid||'
             GROUP BY ROLLUP ('||av_grouping||')
            ORDER BY 1) tt ';
ELSE
  lv_sql1:=' SELECT round (DECODE (NVL (tt.npartly, 0), 2, NULL, tt.aparam), 3) aparam, bgroup
         FROM (SELECT  DECODE (GROUPING ('||av_grouping||'),
                     1, 0,
                     '||av_grouping||'
                    ) bgroup,
                 SUM (DECODE (g.inverted, ''y'', NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0), NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0))
                   * DECODE (SIGN (TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm'')) - NVL (g.nfromperiod, 0)), -1, NULL, 1)
                   * DECODE (SIGN (NVL (ntillperiod, 299912) - TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm''))), -1, NULL, 1))
                 / '||ln_rowcof||' aparam,
                 MIN (g.npartly) npartly
              FROM halfhour p, GROUPS g
             WHERE p.mid = g.mid AND (npartly IS NULL OR g.npartly = 1)
             '||lv_sqltimezone||'
             AND gid = '||ln_gid||'
             AND (200902 BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
             GROUP BY ROLLUP ('||av_grouping||')
            ORDER BY 1) tt ';
END IF;
--  insert into tmp_vil values(lv_sql1);commit;
   OPEN cur_t FOR lv_sql1;
 --  USING ld_from,ld_till;
   LOOP
   FETCH cur_t INTO ln_AParam,ln_BGroup;
   EXIT WHEN cur_t%NOTFOUND;
            
  IF(ln_flag=0) THEN
   FOR z IN 1..ln_count LOOP
   data_t (temp_i + z):=NULL;
   END LOOP;
   ln_flag:=1;
  END IF;
   IF (ln_AParam IS NOT NULL) THEN
   data_t (temp_i +1+ ln_BGroup) := ln_AParam;
   ELSE
   data_t (temp_i +1+ ln_BGroup) := 0;
   END IF;

  END LOOP;
  CLOSE cur_t;
  
  temp_i := data_t.COUNT;
  ln_flag:=0;
 IF an_ispoint=1 THEN 
  lv_sql2:=' SELECT round (tt.aparam, 3) aparam, bgroup
         FROM (SELECT  DECODE (GROUPING ('||av_grouping||'),
                     1, 0,
                     '||av_grouping||'
                    ) bgroup,
                 SUM (p.ed) / '||ln_rowcof||' aparam
             FROM halfhour p, points g
             WHERE p.mid = g.mid 
             '||lv_sqltimezone||'
             AND p.mid = '||ln_mid||'
             GROUP BY ROLLUP ('||av_grouping||')
            ORDER BY 1) tt ';
ELSE
  lv_sql2:='SELECT round (DECODE (NVL (tt.npartly, 0), 1, NULL, tt.bparam), 3) bparam,bgroup
         FROM (SELECT  DECODE (GROUPING ('||av_grouping||'),
                     1, 0,
                     '||av_grouping||'
                    ) bgroup,
                 SUM (DECODE (g.inverted, ''y'', NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0))
                   * DECODE (SIGN (TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm'')) - NVL (g.nfromperiod, 0)), -1, NULL, 1)
                   * DECODE (SIGN (NVL (ntillperiod, 299912) - TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm''))), -1, NULL, 1))
                 / '||ln_rowcof||' bparam,
                 MIN (g.npartly) npartly
              FROM halfhour p, GROUPS g
              WHERE p.mid = g.mid AND (npartly IS NULL OR g.npartly = 2)
               '||lv_sqltimezone||'

                                 AND gid = '||ln_gid||'
                                 AND (200902 BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))

                        GROUP BY ROLLUP ('||av_grouping||')
                        ORDER BY 1) tt';
END IF;
     OPEN cur_t FOR lv_sql2;
     -- USING ld_from,ld_till;
     LOOP
     FETCH cur_t INTO ln_BParam,ln_BGroup;
     EXIT WHEN cur_t%NOTFOUND;
    IF(ln_flag=0) THEN
      FOR z IN 1..ln_count LOOP
      data_t (temp_i + z):=NULL;
      END LOOP;
      ln_flag:=1;
    END IF;
     IF (ln_BParam IS NOT NULL) THEN
      data_t (temp_i +1+ ln_BGroup) := ln_BParam;
     ELSE
      data_t (temp_i +1+ ln_BGroup) := 0;
     END IF;
    END LOOP;
   CLOSE cur_t;
   
    temp_i := data_t.COUNT;
    ln_flag:=0;
 IF an_ispoint=1 THEN 
  lv_sql3:=' SELECT round (tt.aparam, 3) aparam, bgroup
         FROM (SELECT  DECODE (GROUPING ('||av_grouping||'),
                     1, 0,
                     '||av_grouping||'
                    ) bgroup,
                SUM (-util_pg.sld (p.mid, p.er, p.ed )) / '||ln_rowcof||' aparam
             FROM halfhour p, points g
             WHERE p.mid = g.mid 
             '||lv_sqltimezone||'
             AND p.mid = '||ln_mid||'
             GROUP BY ROLLUP ('||av_grouping||')
            ORDER BY 1) tt ';
ELSE
    lv_sql3:='SELECT round (DECODE (NVL (tt.npartly, 0), 0, tt.cparam, NULL), 3) cparam,
                 bgroup
                 
                FROM   (SELECT   DECODE (GROUPING ('||av_grouping||'),
                                         1, 0,
                                         '||av_grouping||'
                                        ) bgroup,
                                 SUM (-util_pg.sld (p.mid, NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0), (NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0)))
                                      * DECODE (g.inverted, ''y'', 1, -1)
                                      * DECODE (SIGN (TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm'')) - NVL (g.nfromperiod, 0)), -1, NULL, 1)
                                      * DECODE (SIGN (NVL (ntillperiod, 299912) - TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm''))), -1, NULL, 1))
                                 / '||ln_rowcof||' cparam,

                                 MIN (g.npartly) npartly
                       FROM halfhour p, GROUPS g
                        WHERE p.mid = g.mid AND (g.npartly IS NULL)
                         '||lv_sqltimezone||'
                        AND gid = '||ln_gid||'
                        AND (200902 BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
                        GROUP BY ROLLUP ('||av_grouping||')
                        ORDER BY 1) tt';
END IF;                        
     OPEN cur_t FOR lv_sql3;
    -- USING ld_from,ld_till;
     LOOP
     FETCH cur_t INTO ln_CParam,ln_BGroup;
     EXIT WHEN cur_t%NOTFOUND;
     IF(ln_flag=0) THEN
      FOR z IN 1..ln_count LOOP
      data_t (temp_i + z):=NULL;
      END LOOP;
      ln_flag:=1;
    END IF;
     IF (ln_CParam IS NOT NULL) THEN
      data_t (temp_i +1+ ln_BGroup) := ln_CParam;
     ELSE
      data_t (temp_i +1+ ln_BGroup) := 0;
     END IF;



    END LOOP;
    CLOSE cur_t;
    temp_i := data_t.COUNT;
    ln_flag:=0;
    IF (temp_i = temp_k) THEN
     IF an_ispoint=1 THEN 
      temp_k:=0;
     ELSE 
     SELECT NVL (npartly, 0)
       INTO temp_k
       FROM GROUPS
      WHERE gid = ln_gid AND mid = ln_mid;
     END IF;

     IF temp_k = 0 THEN
      FOR i IN 1 .. (ln_count*3) LOOP
       temp_i := data_t.COUNT;
       data_t (temp_i + 1) := NULL;
      END LOOP;
     ELSE
      FOR i IN 1 .. ln_count LOOP
       temp_i := data_t.COUNT;
       data_t (temp_i + 1) := NULL;
      END LOOP;
     END IF;
    END IF;
   END LOOP;
 CLOSE lc;
END;
---------------------------------------------------------------------------------------------------------------
FUNCTION get_cod (an_gid NUMBER , an_sort NUMBER, an_ispoint NUMBER)
RETURN VARCHAR2 IS
lv_val VARCHAR2(20);
BEGIN
 IF an_ispoint=1 THEN
   SELECT max(vvalue)
   INTO lv_val
   FROM addpointparamval
   WHERE mid =an_gid
   AND nsort=an_sort;
 ELSE

   SELECT max(vvalue)
   INTO lv_val
   FROM addpointparamval
   WHERE mid =(SELECT max(mid) FROM GROUPS WHERE gid=an_gid)
   AND nsort=an_sort;
END IF;   
 
RETURN NVL(lv_val,' ');
END;

