--для Иляшевского 03,10,2012
PROCEDURE proc_info_47 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE,
                         an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
                         an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
                          ) IS
  ln_locksum   NUMBER         DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);
  an_stepprofile NUMBER;
  ln_vname VARCHAR2(256);
 BEGIN

   an_cnfixcol := 1;
   an_cntitle := 3;
  --'Почасовой сальдо переток электрической энергии'
  SELECT 'Почасовой сальдо переток электрической энергии по '||MAX(name) INTO ln_vname FROM GROUPS WHERE gid=an_id;

  OPEN col_t FOR
  SELECT ROWNUM ID,kk. title1, kk.title2, kk. title3, cn_btnface titlecl, cn_center titleal, kk. datacl, cn_center dataal,
           1 nlock, kk. nwidth, '' vmasks FROM
   ( SELECT 1 ID,0 gid, ln_vname  title1,'Дни'  title2,'месяца'  title3,70 nwidth,cn_btnface datacl
      FROM DUAL
   UNION ALL
     SELECT 2 ID,0 gid, ln_vname title1, 'Всего за'  title2, 'сутки' title3,70 nwidth,cn_yellow datacl
      FROM DUAL
    UNION ALL
     SELECT ll.rn+2 ID,0 gid, ln_vname title1,'Значение сальдо перетока электрической энергии в каждом часе отчетных суток ' title2, TO_CHAR(ll.rn)  title3,70 nwidth,cn_white datacl
      FROM  (SELECT ROWNUM rn FROM dict WHERE ROWNUM<=25)ll
   ORDER BY 1)kk;  

-- IF(an_stepprofile=gn_stpday) THEN
    OPEN row_t FOR
    SELECT -1 ID,TO_CHAR(ad_from+tt.dt-1,'dd.Mon') title1,
     cn_white datacl, 1 nlock, '' vmasks, 0 srt
     FROM
     ( SELECT ROWNUM dt FROM dict WHERE ROWNUM<=
       --(SELECT to_char(ad_till,'ddd')-to_char(ad_from,'ddd')+1 FROM dual))tt
       (SELECT ad_till-1-ad_from+1 FROM dual))tt
       UNION ALL
     SELECT -1 ID,'Всего:' title1,  cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
       FROM DUAL
      WHERE ln_locksum = 0;

 
 END;
--------------------------------------------------------------------------------------------------------------------
PROCEDURE proc_value_47 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE,
                          ad_till DATE, data_t IN OUT common_pg.tt_number, quantity     IN OUT   VARCHAR2,
                          av_proc  VARCHAR2 ) IS

  ln_locksum        NUMBER              DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);
  lv_grouping       VARCHAR2(1000);
  an_stepprofile    NUMBER;
  cur_t             common_pg.tcur;
  cur_t1             common_pg.tcur;
  ln_count          NUMBER;
  ln_timeZona       NUMBER              DEFAULT interior_pg.get_hourtimezone;
  lv_RateZona       NUMBER              DEFAULT interior_pg.get_RateZona;
  ln_dsummer        NUMBER              DEFAULT interior_pg.get_dsummer;
  ln_BGroup         NUMBER;
  ln_AParam         NUMBER;
  ln_BParam         NUMBER;
  ln_CParam         NUMBER;
  ln_DParam         NUMBER;
  temp_k            NUMBER;
  test              NUMBER;
  hh                NUMBER;
  ld_till           DATE;
  ld_from           DATE;
  sumdat_t           common_pg.tt_number;
  
  
  lv_sql            VARCHAR2(10000);
  lv_subsel         VARCHAR2(1000);
  lv_subparam       VARCHAR2(1000);
  lv_sqltimezone    VARCHAR2(2000);
  ld_firstdate      DATE;
  ld_lastdate       DATE;
  lv_qlt            VARCHAR2(1000) DEFAULT NULL;
  lv_table          VARCHAR2(128);
  lv_partly_er      VARCHAR2(128);
  lv_partly_ed     VARCHAR2(128); 
  ln_povercoeff     NUMBER;
  
  
 BEGIN
 

 quantity := 'q';
 data_t.DELETE;
 sumdat_t.DELETE;
 an_stepprofile := gn_stpday;
 

 
 --grouping_p (an_stepprofile ,ln_timeZona ,lv_grouping,ln_dsummer );

-- lv_grouping :='util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/24,1,'||ln_timeZona||','||ln_dsummer||')';
--saa 19/11/2013
 if ln_dsummer=1 then
 lv_grouping :='util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/24,1,'||ln_timeZona||','||ln_dsummer||')';
 else
 lv_grouping :='util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/24,1,'||ln_timeZona||','||ln_dsummer||')';
 end if;


 ld_till:=TRUNC(ad_till)-1;
 ld_from:=TRUNC(ad_from);
 
 FOR i IN 1..26 LOOP
   sumdat_t(i):=NULL;
 END LOOP;

                   
 lv_subsel:='SELECT ROWNUM dat FROM dict WHERE ROWNUM<=25';
 -- av_firstdate:=to_char(ld_from,'dd.mm.yyyy hh24:mi:ss');     
 -- av_lastdate:=to_char(ld_till,'dd.mm.yyyy hh24:mi:ss');  
 
 IF (ln_dsummer = 0) THEN
   lv_sqltimezone :=
    ' and  date_time>= (:par1 + ' || ln_timeZona || ' - DECODE(' || ln_timeZona
    || ',0,0,3/24))
                    and   date_time <=(:par2 + ' || ln_timeZona || ' + DECODE(' || ln_timeZona
    || ',0,0,3/24))
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) >= :par1 + ' || ln_timeZona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= :par2 + ' || ln_timeZona;
  ELSE
   lv_sqltimezone :=
    ' AND   P.date_time >= :par1 + ' || ln_timeZona || '
      AND   P.date_time <= :par2 + ' || ln_timeZona;
  END IF;
 
-- IF an_ispoint=1 THEN lv_table:='points';
-- ELSE 
 lv_table:='groups';
--  ELSE
 --   lv_subsel :=
 --        ' G.gid in (select gr.gid from groups gr connect by prior gr.gid=gr.parent  start with gr.gid=' || an_idgroup ||') ';
 --  END IF;

   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) * abs(nvl(g.NKC,1)) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) * abs(nvl(g.NKC,1)) ';
--  END IF;
-- END IF;
   ln_povercoeff:=interior_pg.get_powercoeff;
   
 IF nvl(util_pg.get_param(av_proc,2,';'),1)= 1 THEN --актив
    lv_subparam:=' sum( -util_pg.sld( P.mid, P.er '|| lv_partly_er || '  , P.ed  '|| lv_partly_ed || ' ) *DECODE( G.inverted  ,''y'',1,-1)   )/'||ln_povercoeff|| ' ';
 ELSE --реактив
   lv_subparam:= ' util_pg.sumn(sum(( -util_pg.sld( P.mid,P.q1 ,P.q3  ))*DECODE( G.inverted  ,''y'',1,-1)) , sum(( -util_pg.sld( P.mid, P.q2  , P.q4  ))*DECODE( G.inverted  ,''y'',1,-1)))/' || ln_povercoeff || ' ';
 END IF; 
   
   
 lv_sql :=' select pp.dat,sum(decode(pp.dat,25,nvl(dd.AParam,0),dd.AParam)) aparam,SUMQM(dd.decnsour) vqm FROM
 (select decode(grouping('|| lv_grouping ||'),1,0, '|| lv_grouping ||' ) BGroup ,
 '||lv_subparam||'  AParam ,
      decode(grouping( '|| lv_grouping ||' ),1 , qm_pg.sumqm(nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm),qm_pg.nodataqm),nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm) ) decnsour 
     from   '||lv_table||'   G,  halfhour  P where G.mid=P.mid
    '||lv_sqltimezone||'
     AND G.gid IN (select gr.gid from groups gr connect by prior gr.gid=gr.parent  
                       start with gr.gid='||an_id||') 
     group by rollup( '|| lv_grouping ||' ))dd,
     (SELECT ROWNUM dat FROM dict WHERE ROWNUM<=25
      union all
      SELECT 0 dat FROM dual)pp
      WHERE pp.dat=dd.BGroup(+)
                GROUP BY pp.dat
                 ORDER BY 1  ';
-- insert into tmp_vil values(lv_sql);commit;
-- /*sum( -util_pg.sld( P.mid, P.er '|| lv_partly_er || '  , P.ed  '|| lv_partly_ed || ' ) *DECODE( G.inverted  ,''y'',1,-1)   )/'||ln_povercoeff||'  AParam ,*/
  WHILE(ld_from<=ld_till)LOOP
  
  -- av_firstdate:=to_char(ld_from,'dd.mm.yyyy hh24:mi:ss');     
  -- av_lastdate:=to_char(ld_till,'dd.mm.yyyy hh24:mi:ss');  
   
--  insert into tmp_vil values(to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||'  ' ||lv_sql);commit;
    ld_firstdate:=ld_from+1/86400;
    ld_lastdate:=ld_from+1;
 IF (ln_dsummer = 0) THEN 
               OPEN cur_t FOR lv_sql
               USING ld_firstdate,ld_lastdate,ld_firstdate,ld_lastdate;               
 ELSE
             OPEN cur_t FOR lv_sql
               USING ld_firstdate,ld_lastdate;
--             insert into tmp_vil values(lv_sql||' '||to_char(ld_firstdate,'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_lastdate,'dd.mm.yyyy hh24:mi:ss'));commit;  
 END IF;
    
    LOOP
     FETCH cur_t INTO ln_BGroup,ln_AParam,lv_qlt;
     EXIT WHEN cur_t%NOTFOUND;
     
   temp_k:=data_t.COUNT;
 
   IF (ln_AParam IS NOT NULL) THEN
     data_t (temp_k +1) := TRUNC(ln_AParam,3);
   ELSE
     data_t (temp_k +1) := NULL;
   END IF;
   
      IF (data_t (temp_k +1) IS NOT NULL) THEN
        sumdat_t(ln_BGroup+1):=nvl(sumdat_t(ln_BGroup+1),0)+data_t (temp_k +1);
      END IF;

                 
    IF quantity='q' THEN
         quantity:=nvl(lv_qlt, 'q');
     ELSE
         quantity := qm_pg.sumqm (quantity,lv_qlt);
     END IF;
    
     
     
 
    
 
   
  END LOOP;
     
  CLOSE cur_t;
  ld_from:=ld_from+1;
 
  
END LOOP;
   temp_k:=data_t.COUNT;
   FOR h IN 1..26  LOOP
        
      data_t (temp_k +h) := sumdat_t(h);
    --  insert into tmp_vil values(h);commit;
   END LOOP;

 
  IF quantity='q' THEN
         quantity:=qm_pg.nodataqm;
         ELSE
         SELECT decode (uniinterior1_pg.is_nodataqm(an_id, ld_from, ld_till), 1, qm_pg.sumqm (quantity,qm_pg.nodataqm), quantity) INTO quantity FROM dual;
     END IF;

END;                          
------------------------------------------------------------------------------------------------------------------------
 FUNCTION getmaketgrafvalue10 (
      an_fid             NUMBER,
      an_ispoint         NUMBER,
      an_id              NUMBER,
      ad_from            DATE,
      ad_till            DATE,
      an_col             NUMBER,
      an_row             NUMBER,
      av_title     OUT   VARCHAR2,
      av_xtitle    OUT   VARCHAR2,
      av_ytitle    OUT   VARCHAR2,
      x_t          OUT   common_pg.tt_number,
      y_t          OUT   common_pg.tt_number,
      an_period             NUMBER
   )
      RETURN NUMBER
   IS
   temp_i      NUMBER;
 temp_k      NUMBER;
 ln_flag      NUMBER;
 an_stepprofile  NUMBER;
 ld_from      DATE;
 ld_till      DATE;
 av_grouping    VARCHAR2(1000);
 ln_count     NUMBER;
 cur_t       common_pg.tcur;
 lc          common_pg.tcur;
 lv_sql1      VARCHAR2(4000);
 lv_sql2      VARCHAR2(4000);
 lv_sql3      VARCHAR2(4000);
 ln_BGroup     NUMBER;
 ln_AParam     NUMBER;
 ln_BParam     NUMBER;
 ln_CParam     NUMBER;
 ln_DParam     NUMBER;
 ln_timeZona   NUMBER              DEFAULT interior_pg.get_hourtimezone;
 ln_dsummer    NUMBER              DEFAULT interior_pg.get_dsummer;
 lv_sqltimezone VARCHAR2(2000);
 ln_rowcof NUMBER DEFAULT interior_pg.get_powercoeff;
 lv_subsel   VARCHAR2(1000);
 lv_table VARCHAR2(256);
 lv_selmid  VARCHAR2(4000);
 lv_selgid  VARCHAR(60);
 
-- ln_mid NUMBER;
 ln_parent NUMBER;
 ln_gid NUMBER;
 lv_name VARCHAR2(256);
 ln_sort NUMBER;
 
BEGIN
   ln_gid := TRUNC (an_row / 10);
   ln_sort := MOD (an_row, 10);
   ln_flag:=0;
   
   av_xtitle := 'Час.';
 IF  ln_rowcof=1 THEN
   av_ytitle := 'КВтч.';
 ELSE
   av_ytitle := 'тКВтч.';
 END IF;

------------------------------------------------------
 --  IF (ln_sort = 0) THEN   --Сальдо

 IF an_period= 2 THEN
  an_stepprofile := gn_stpmonth;
  ln_count:=13;
  ld_from:=TRUNC(ad_from,'yyyy')+1/86400;
  ld_till:=ADD_MONTHS(TRUNC(ad_from,'yyyy'),12);
 ELSIF nvl(an_period,1)= 1 THEN
  an_stepprofile :=gn_stpday;
  SELECT TO_CHAR(LAST_DAY(ad_from),'dd')+1
  INTO ln_count
  FROM dual;
  ld_from:=TRUNC(ad_from,'mm')+1/86400;
  ld_till:=TRUNC(LAST_DAY(ad_from)+1,'mm');
 ELSIF an_period= 3 THEN
  an_stepprofile :=gn_stphour;
  ln_count:=26;
  ld_from:=ad_from+1/86400;
  ld_till:=ad_from+1;
 END IF;
 
IF (an_stepprofile = gn_stpmonth OR an_stepprofile = gn_stpday) THEN
interior_pg.grouping_p (an_stepprofile ,to_char(ld_from,'dd.mm.yyyy hh24:mi:ss'),24,av_grouping);

ELSE
  IF (ln_dsummer=1) THEN
  av_grouping := ' util_pg.get_num_dt (P.date_time-1/86400,nsource, 1/24 ,1,'||ln_timeZona||','||ln_dsummer||') ';
  ELSE
  av_grouping := ' util_pg.get_num_dt (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/24 ,1,'||ln_timeZona||','||ln_dsummer||') ';
  END IF;
END IF;

 IF an_ispoint=1 THEN 
     /*  IF util_pg.isfolder (an_id) = 1 THEN
          lv_subsel := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) and cod=0 start with mid='||an_id||') and G.ind  in (3,4)';
       ELSE*/
          lv_subsel := ' G.mid=' || ln_gid;
     --  END IF;
         lv_table:='points ';
     --    lv_selgid:='NULL gid ';
    
 ELSE 
 /*   lv_subsel :=
         ' G.gid IN (SELECT   gid
                   FROM GROUPS
                CONNECT BY PRIOR gid = PARENT
                START WITH PARENT = '||an_id||') AND G.mid > 0 ';*/
     lv_subsel :=' G.gid =' || ln_gid;
     lv_table:='groups ';
   --  lv_selgid:='G.gid gid ';
  
  END IF;
  

  
 lv_selmid:='
        SELECT  nvl(util_pg.get_shortname_f(G.short_name,G.mid),util_pg.get_name_f(G.NAME,G.mid)) NAME
         FROM '||lv_table||' G
         WHERE '||lv_subsel;
     


  OPEN lc FOR lv_selmid;
  LOOP
  FETCH lc INTO av_title;
  EXIT WHEN lc%NOTFOUND;
  END LOOP;
  CLOSE lc;
       
 -- temp_k := data_t.COUNT;

 -- temp_i := data_t.COUNT;
--  ln_flag:=0;

  
   IF (ln_dsummer=0) THEN
   lv_sqltimezone :=
                  'and P.date_time>= (to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400 +'||ln_timeZona||' - DECODE('||ln_timeZona||',0,0,3/24))
                  AND   P.date_time <=(to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona||' + DECODE('||ln_timeZona||',0,0,3/24))
                  AND   util_pg.to_unlocaltime (P.date_time, nsource) >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
                  AND   util_pg.to_unlocaltime (P.date_time, nsource) <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
                  

  ELSE
   lv_sqltimezone :=
                     ' AND   P.date_time >= to_date('''||to_char(ld_from,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + 1 / 86400+ '||ln_timeZona||'
                       AND   P.date_time <= to_date('''||to_char(ld_till,'dd.mm.yyyy hh24:mi:ss')||''',''dd.mm.yyyy hh24:mi:ss'') + '||ln_timeZona;
                       
  END IF;

 IF (ln_sort = 1) THEN   --Прием
   temp_i := y_t.COUNT;
  
 IF an_ispoint=1 THEN 
  lv_sql1:=' SELECT round (tt.aparam, 3) aparam, bgroup
         FROM (SELECT  
                     '||av_grouping||'
                     bgroup,
                 SUM (p.er) / '||ln_rowcof||' aparam
             FROM halfhour p, points g
             WHERE p.mid = g.mid 
             '||lv_sqltimezone||'
             AND p.mid = '||ln_gid||'
             GROUP BY  ('||av_grouping||')
            ORDER BY 1) tt ';
ELSE
  lv_sql1:=' SELECT round (DECODE (NVL (tt.npartly, 0), 2, NULL, tt.aparam), 3) aparam, bgroup
         FROM (SELECT 
                     '||av_grouping||'
                     bgroup,
                 SUM (DECODE (g.inverted, ''y'', NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0), NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0))
                   * DECODE (SIGN (TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm'')) - NVL (g.nfromperiod, 0)), -1, NULL, 1)
                   * DECODE (SIGN (NVL (ntillperiod, 299912) - TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm''))), -1, NULL, 1))
                 / '||ln_rowcof||' aparam,
                 MIN (g.npartly) npartly
              FROM halfhour p, GROUPS g
             WHERE p.mid = g.mid AND (npartly IS NULL OR g.npartly = 1)
             '||lv_sqltimezone||'
             AND gid = '||ln_gid||'
             AND (200902 BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
             GROUP BY  ('||av_grouping||')
            ORDER BY 1) tt ';
END IF;
--  insert into tmp_vil values(lv_sql1);commit;
   OPEN cur_t FOR lv_sql1;
 --  USING ld_from,ld_till;
   LOOP
   FETCH cur_t INTO ln_AParam,ln_BGroup;
   EXIT WHEN cur_t%NOTFOUND;
            
   IF(ln_flag=0) THEN
       FOR z IN 1..ln_count LOOP
       y_t (temp_i + z):=NULL;
       END LOOP;
      ln_flag:=1;
    END IF;
  
      y_t (temp_i + ln_BGroup) := ln_AParam;
  
    END LOOP;
  
  
    FOR lc2 IN (SELECT ROWNUM ID
                          FROM dict
                         WHERE ROWNUM <= ln_count)  LOOP
     temp_i := x_t.COUNT;
     x_t (temp_i + 1) := lc2.ID;
    END LOOP;
    CLOSE cur_t;
    
    ln_flag:=0;
    av_title := 'Прием с' || ' ' || TO_CHAR (ad_from, 'dd.mm.yyyy')||' по' || ' ' || TO_CHAR (ld_till, 'dd.mm.yyyy')  || ' по точке ' || av_title || '.';
    
    RETURN y_t.COUNT;
    
  ELSIF (ln_sort = 2) THEN   --Сальдо
   temp_i := y_t.COUNT;   
    
 IF an_ispoint=1 THEN 
  lv_sql2:=' SELECT round (tt.aparam, 3) aparam, bgroup
         FROM (SELECT  
                     '||av_grouping||'
                    bgroup,
                 SUM (p.ed) / '||ln_rowcof||' aparam
             FROM halfhour p, points g
             WHERE p.mid = g.mid 
             '||lv_sqltimezone||'
             AND p.mid = '||ln_gid||'
             GROUP BY ('||av_grouping||')
            ORDER BY 1) tt ';
ELSE
  lv_sql2:='SELECT round (DECODE (NVL (tt.npartly, 0), 1, NULL, tt.bparam), 3) bparam,bgroup
         FROM (SELECT  
                     '||av_grouping||'
                     bgroup,
                 SUM (DECODE (g.inverted, ''y'', NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0))
                   * DECODE (SIGN (TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm'')) - NVL (g.nfromperiod, 0)), -1, NULL, 1)
                   * DECODE (SIGN (NVL (ntillperiod, 299912) - TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm''))), -1, NULL, 1))
                 / '||ln_rowcof||' bparam,
                 MIN (g.npartly) npartly
              FROM halfhour p, GROUPS g
              WHERE p.mid = g.mid AND (npartly IS NULL OR g.npartly = 2)
               '||lv_sqltimezone||'

                                 AND gid = '||ln_gid||'
                                 AND (200902 BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))

                        GROUP BY  ('||av_grouping||')
                        ORDER BY 1) tt';
END IF;
     OPEN cur_t FOR lv_sql2;
     -- USING ld_from,ld_till;
     LOOP
     FETCH cur_t INTO ln_BParam,ln_BGroup;
     EXIT WHEN cur_t%NOTFOUND;
   IF(ln_flag=0) THEN
       FOR z IN 1..ln_count LOOP
       y_t (temp_i + z):=NULL;
       END LOOP;
      ln_flag:=1;
    END IF;
  
      y_t (temp_i + ln_BGroup) := ln_BParam;
  
    END LOOP;
  
  
    FOR lc2 IN (SELECT ROWNUM ID
                          FROM dict
                         WHERE ROWNUM <= ln_count)  LOOP
     temp_i := x_t.COUNT;
     x_t (temp_i + 1) := lc2.ID;
    END LOOP;
    CLOSE cur_t;
    
    ln_flag:=0;
    av_title := 'Отдача с' || ' ' || TO_CHAR (ad_from, 'dd.mm.yyyy')||' по' || ' ' || TO_CHAR (ld_till, 'dd.mm.yyyy')  || ' по точке ' || av_title || '.';
    
    RETURN y_t.COUNT;
    
    
  ELSIF (ln_sort = 0) THEN   --отдача
   temp_i := y_t.COUNT;   
    
 IF an_ispoint=1 THEN 
  lv_sql3:=' SELECT round (tt.aparam, 3) aparam, bgroup
         FROM (SELECT 
                     '||av_grouping||'
                     bgroup,
                SUM (-util_pg.sld (p.mid, p.er, p.ed )) / '||ln_rowcof||' aparam
             FROM halfhour p, points g
             WHERE p.mid = g.mid 
             '||lv_sqltimezone||'
             AND p.mid = '||ln_gid||'
             GROUP BY  ('||av_grouping||')
            ORDER BY 1) tt ';
ELSE
    lv_sql3:='SELECT round (DECODE (NVL (tt.npartly, 0), 0, tt.cparam, NULL), 3) cparam,
                 bgroup
                 
                FROM   (SELECT  
                                         '||av_grouping||'
                                         bgroup,
                                 SUM (-util_pg.sld (p.mid, NVL (p.er * DECODE (g.npartly, 2, 0, 1), 0), (NVL (p.ed * DECODE (g.npartly, 1, 0, 1), 0)))
                                      * DECODE (g.inverted, ''y'', 1, -1)
                                      * DECODE (SIGN (TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm'')) - NVL (g.nfromperiod, 0)), -1, NULL, 1)
                                      * DECODE (SIGN (NVL (ntillperiod, 299912) - TO_NUMBER (TO_CHAR (date_time - 1 / 86400, ''yyyymm''))), -1, NULL, 1))
                                 / '||ln_rowcof||' cparam,

                                 MIN (g.npartly) npartly
                       FROM halfhour p, GROUPS g
                        WHERE p.mid = g.mid AND (g.npartly IS NULL)
                         '||lv_sqltimezone||'
                        AND gid = '||ln_gid||'
                        AND (200902 BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
                        GROUP BY  ('||av_grouping||')
                        ORDER BY 1) tt';
END IF;                        
     OPEN cur_t FOR lv_sql3;
    -- USING ld_from,ld_till;
     LOOP
     FETCH cur_t INTO ln_CParam,ln_BGroup;
     EXIT WHEN cur_t%NOTFOUND;
    IF(ln_flag=0) THEN
       FOR z IN 1..ln_count LOOP
       y_t (temp_i + z):=NULL;
       END LOOP;
      ln_flag:=1;
    END IF;
  
      y_t (temp_i + ln_BGroup) := ln_CParam;
  
    END LOOP;
  
  
    FOR lc2 IN (SELECT ROWNUM ID
                          FROM dict
                         WHERE ROWNUM <=ln_count)  LOOP
     temp_i := x_t.COUNT;
     x_t (temp_i + 1) := lc2.ID;
    END LOOP;
    CLOSE cur_t;
    
    ln_flag:=0;
    av_title := 'Сальдо с' || ' ' || TO_CHAR (ad_from, 'dd.mm.yyyy')||' по' || ' ' || TO_CHAR (ld_till, 'dd.mm.yyyy')  || ' по точке ' || av_title || '.';
    
    RETURN y_t.COUNT;
    

 
END IF; 
 
END;
-------------------------------------------------------------------------------------------------------------------------
END;
