CREATE OR REPLACE 
PACKAGE BODY uniinterior1_pg IS
---------------------------------------------------------------------------------------------
 cn_btnface CONSTANT NUMBER := uniinterior_pg.cn_btnface;
 cn_white   CONSTANT NUMBER := uniinterior_pg.cn_white;
 cn_yellow  CONSTANT NUMBER := uniinterior_pg.cn_yellow;
 cn_blue    CONSTANT NUMBER := uniinterior_pg.cn_blue;
 cn_green   CONSTANT NUMBER := uniinterior_pg.cn_green;
 cn_red     CONSTANT NUMBER := uniinterior_pg.cn_red;
 cn_aqua    CONSTANT NUMBER := uniinterior_pg.cn_aqua;
-------------------------------------------------------------------------------------------
 cn_left    CONSTANT NUMBER := uniinterior_pg.cn_left;
 cn_right   CONSTANT NUMBER := uniinterior_pg.cn_right;
 cn_center  CONSTANT NUMBER := uniinterior_pg.cn_center;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_info_17(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
 an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur, av_param VARCHAR2
 ) IS
  parametr            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 2);       --1-получасовые, 2-часовые, 3-суточные, 4-месячные
  fact_from           DATE;
  fact_till           DATE;
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  is_day_switch       NUMBER;                                                                                         --0 - нет перехода, 1 - весна, -1 - осень
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  day_switch          DATE;
  temp_date           DATE;
  str_timeswitch1     VARCHAR2(10);
  str_timeswitch2     VARCHAR2(10);
  str_sort1           VARCHAR2(10);
  str_sort2           VARCHAR2(10);
------------
  point               VARCHAR2(100);
  time_poyas          VARCHAR2(100);
  period              VARCHAR2(100);
------------
  ln_timezona         NUMBER;
 BEGIN
  an_cnfixcol := 1;
  an_cntitle := 2;
  ln_timezona := interior_pg.get_hourtimezone;
  ln_dsummer := interior_pg.get_dsummer;

  --переход на лето. 0 - нет, 1 - да
  SELECT DECODE(ln_locksum, 0, 1, 0)
  INTO   an_cnfooter
  FROM   DUAL;

  IF parametr = 1 THEN                                                                                                                            --получасовки
   fact_from := util_pg.trunc_d(ad_from, 1 / 48) + 1 / 48;
   fact_till := util_pg.trunc_d(ad_till, 1 / 48);
  ELSIF parametr = 2 THEN                                                                                                                              --часовые
   fact_from := util_pg.trunc_d(ad_from, 1 / 24) + 1 / 24;
   fact_till := util_pg.trunc_d(ad_till, 1 / 24);
  ELSIF parametr = 3 THEN                                                                                                                          -- посуточные
   fact_from := ad_from;
   fact_till := ad_till;
  ELSIF parametr = 4 THEN                                                                                                                          -- помесячные
   fact_from := TRUNC(ad_from, 'MM');
   fact_till := LAST_DAY(ad_till);
  END IF;

  OPEN col_t FOR
   SELECT -1 ID, 'Временной интервал' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 100 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 0 ID, 'Актив [тыс.кВт ч]' title1, 'прием' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Актив [тыс.кВт ч]' title1, 'отдача' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Актив [тыс.кВт ч]' title1, 'сальдо' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 3 ID, 'Реактив [тыс.кВт ч]' title1, 'прием' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 4 ID, 'Реактив [тыс.кВт ч]' title1, 'отдача' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 5 ID, 'Реактив [тыс.кВт ч]' title1, 'сальдо' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth,
          '#0.000' vmasks
   FROM   DUAL;

  temp_date := fact_from;

  WHILE(temp_date <= fact_till) LOOP
   day_switch := temp_date;
   is_day_switch := util_pg.is_dayswitch(temp_date);
   EXIT WHEN util_pg.is_dayswitch(temp_date) <> 0;
   temp_date := temp_date + 1;
  END LOOP;

  IF parametr = 1 THEN
   IF ln_timezona = 0 THEN                                                                                                                            --Украина
    str_timeswitch1 := '03:30';
    str_timeswitch2 := '04:00';
    str_sort1 := '0330';
    str_sort2 := '0400';
   --str_sort3:='0330';
   --str_sort4:='0400';
   ELSIF ln_timezona = -1 / 24 THEN                                                                                                                     --Россия
    str_timeswitch1 := '04:30';
    str_timeswitch2 := '05:00';
    str_sort1 := '0430';
    str_sort2 := '0500';
   --str_sort3:='0430';
   --str_sort4:='0500';
   ELSIF ln_timezona = 1 / 24 THEN                                                                                                                      --Европа
    str_timeswitch1 := '02:30';
    str_timeswitch2 := '03:00';
    str_sort1 := '0230';
    str_sort2 := '0300';
   --str_sort3:='0430';
   --str_sort4:='0500';
   END IF;
  ELSE
   IF ln_timezona = 0 THEN                                                                                                                            --Украина
    str_timeswitch1 := '04:00';
    str_sort1 := '0401';
    str_sort2 := '0400';
   ELSIF ln_timezona = -1 / 24 THEN                                                                                                                     --Россия
    str_timeswitch1 := '05:00';
    str_sort1 := '0501';
    str_sort2 := '0500';
   ELSIF ln_timezona = 1 / 24 THEN                                                                                                                      --Европа
    str_timeswitch1 := '03:00';
    str_sort1 := '0301';
    str_sort2 := '0300';
   END IF;
  END IF;

  IF parametr = 1 THEN
   IF ln_dsummer <> 0 THEN
    IF is_day_switch = -1 THEN                                                                                                     --если день перехода на зиму
     --raise_application_error(-20001,TO_CHAR(day_switch,'DD.MM.YYYY ')||str_timeswitch1 ||'*'|| TO_CHAR(day_switch,'yyyymmdd')||str_sort1);
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'yyyymmddhh24mi') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
      UNION ALL
      SELECT   ROWNUM ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'yyyymmdd') || str_sort1 srt
      FROM     DUAL
      UNION ALL
      SELECT   ROWNUM ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch2 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'yyyymmdd') || str_sort2 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSIF is_day_switch = 1 THEN                                                                                                    --если день перехода на лето
     OPEN row_t FOR
      SELECT     1 ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'YYYYMMDDHH24MI') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
      MINUS
      SELECT   1 ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'YYYYMMDD') || str_sort1 srt
      FROM     DUAL
      MINUS
      SELECT   1 ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch2 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'YYYYMMDD') || str_sort2 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSE                                                                                                                                     --если обычный день
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
      UNION ALL
      SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM   DUAL;
    END IF;
   ELSE
    OPEN row_t FOR                                                                                                       --если перехода на лето не должно быть
     SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM       DUAL
     CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
     UNION ALL
     SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM   DUAL;
   END IF;
  ELSIF parametr = 2 THEN
   IF ln_dsummer <> 0 THEN
    IF is_day_switch = -1 THEN
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'yyyymmddhh24mi') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
      UNION ALL
      SELECT   ROWNUM ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'yyyymmdd') || str_sort1 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSIF is_day_switch = 1 THEN
     OPEN row_t FOR
      SELECT     1 ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'YYYYMMDDHH24MI') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
      MINUS
      SELECT   1 ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'YYYYMMDD') || str_sort2 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSE
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
      UNION ALL
      SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM   DUAL;
    END IF;
   ELSE
    OPEN row_t FOR
     SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM       DUAL
     CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
     UNION ALL
     SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM   DUAL;
   END IF;
  ELSIF parametr = 3 THEN
   OPEN row_t FOR
    SELECT     ROWNUM ID, TO_CHAR(fact_from + ROWNUM - 1, 'DD.MM.YYYY') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM       DUAL
    CONNECT BY fact_from + ROWNUM - 1 <= fact_till
    UNION ALL
    SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL;
  ELSIF parametr = 4 THEN
   OPEN row_t FOR
    SELECT     ROWNUM ID, RPAD(RTRIM(TO_CHAR(ADD_MONTHS(fact_from, ROWNUM - 1), 'Month')), 10) || TO_CHAR(ADD_MONTHS(fact_from, ROWNUM - 1), ' YYYY') title1,
               cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM       DUAL
    CONNECT BY ADD_MONTHS(fact_from,(ROWNUM - 1)) <= fact_till
    UNION ALL
    SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL;
  END IF;

  ad_from := fact_from;
  ad_till := fact_till;
 END;

---------------------------------------------
 PROCEDURE proc_info_18(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
 an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur, av_param VARCHAR2
 ) IS
  parametr            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 2);       --1-получасовые, 2-часовые, 3-суточные, 4-месячные
  fact_from           DATE;
  fact_till           DATE;
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  is_day_switch       NUMBER;                                                                                         --0 - нет перехода, 1 - весна, -1 - осень
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  day_switch          DATE;
  temp_date           DATE;
  str_timeswitch1     VARCHAR2(10);
  str_timeswitch2     VARCHAR2(10);
  str_sort1           VARCHAR2(10);
  str_sort2           VARCHAR2(10);
  ln_timezona         NUMBER;
 BEGIN
  an_cnfixcol := 1;
  an_cntitle := 3;
  ln_timezona := interior_pg.get_hourtimezone;

  SELECT DECODE(ln_locksum, 0, 1, 0)
  INTO   an_cnfooter
  FROM   DUAL;

  IF parametr = 1 THEN                                                                                                                            --получасовки
   fact_from := util_pg.trunc_d(ad_from, 1 / 48) + 1 / 48;
   fact_till := util_pg.trunc_d(ad_till, 1 / 48);
  ELSIF parametr = 2 THEN                                                                                                                              --часовые
   fact_from := util_pg.trunc_d(ad_from, 1 / 24) + 1 / 24;
   fact_till := util_pg.trunc_d(ad_till, 1 / 24);
  ELSIF parametr = 3 THEN                                                                                                                          -- посуточные
   fact_from := ad_from;
   fact_till := ad_till;
  ELSIF parametr = 4 THEN                                                                                                                          -- помесячные
   fact_from := TRUNC(ad_from, 'MM');
   fact_till := LAST_DAY(ad_till);
  END IF;

  OPEN col_t FOR
   SELECT -1 ID, 'Временной интервал' title1, '' title2, '' title3, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 100 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 0 ID, NAME title1, 'Актив [ тыс.кВт ч ]' title2, peretok title3, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock,
          70 nwidth, '#0.000' vmasks
   FROM   (SELECT   1 srt, ROWNUM, vparam, NAME, 'Прием' peretok
           FROM     GROUPS
           WHERE    PARENT = an_id
           UNION ALL
           SELECT   2 srt, ROWNUM, vparam, NAME, 'Отдача' peretok
           FROM     GROUPS
           WHERE    PARENT = an_id
           UNION ALL
           SELECT   3 srt, ROWNUM, vparam, NAME, 'Сальдо' peretok
           FROM     GROUPS
           WHERE    PARENT = an_id
           ORDER BY 3, 4, 2, 1)
   UNION ALL
   SELECT 1 ID, 'Суммарный переток' title1, 'Актив [ тыс.кВт ч ]' title2, 'Прием' title3, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Суммарный переток' title1, 'Актив [ тыс.кВт ч ]' title2, 'Отдача' title3, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 3 ID, 'Суммарный переток' title1, 'Актив [ тыс.кВт ч ]' title2, 'Сальдо' title3, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
   FROM   DUAL;

  temp_date := fact_from;

  WHILE(temp_date <= fact_till) LOOP
   day_switch := temp_date;
   is_day_switch := util_pg.is_dayswitch(temp_date);
   EXIT WHEN util_pg.is_dayswitch(temp_date) <> 0;
   temp_date := temp_date + 1;
  END LOOP;

  IF parametr = 1 THEN
   IF ln_timezona = 0 THEN                                                                                                                            --Украина
    str_timeswitch1 := '03:30';
    str_timeswitch2 := '04:00';
    str_sort1 := '0330';
    str_sort2 := '0400';
   --str_sort3:='0330';
   --str_sort4:='0400';
   ELSIF ln_timezona = -1 / 24 THEN                                                                                                                     --Россия
    str_timeswitch1 := '04:30';
    str_timeswitch2 := '05:00';
    str_sort1 := '0430';
    str_sort2 := '0500';
   --str_sort3:='0430';
   --str_sort4:='0500';
   ELSIF ln_timezona = 1 / 24 THEN                                                                                                                      --Европа
    str_timeswitch1 := '02:30';
    str_timeswitch2 := '03:00';
    str_sort1 := '0230';
    str_sort2 := '0300';
   --str_sort3:='0430';
   --str_sort4:='0500';
   END IF;
  ELSE
   IF ln_timezona = 0 THEN                                                                                                                            --Украина
    str_timeswitch1 := '04:00';
    str_sort1 := '0401';
    str_sort2 := '0400';
   ELSIF ln_timezona = -1 / 24 THEN                                                                                                                     --Россия
    str_timeswitch1 := '05:00';
    str_sort1 := '0501';
    str_sort2 := '0500';
   ELSIF ln_timezona = 1 / 24 THEN                                                                                                                      --Европа
    str_timeswitch1 := '03:00';
    str_sort1 := '0301';
    str_sort2 := '0300';
   END IF;
  END IF;

  IF parametr = 1 THEN
   IF ln_dsummer <> 0 THEN
    IF is_day_switch = -1 THEN
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'yyyymmddhh24mi') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
      UNION ALL
      SELECT   ROWNUM ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'yyyymmdd') || str_sort1 srt
      FROM     DUAL
      UNION ALL
      SELECT   ROWNUM ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch2 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'yyyymmdd') || str_sort2 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSIF is_day_switch = 1 THEN
     OPEN row_t FOR
      SELECT     1 ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'YYYYMMDDHH24MI') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
      MINUS
      SELECT   1 ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'YYYYMMDD') || str_sort1 srt
      FROM     DUAL
      MINUS
      SELECT   1 ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch2 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'YYYYMMDD') || str_sort2 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSE
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
      UNION ALL
      SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM   DUAL;
    END IF;
   ELSE
    OPEN row_t FOR
     SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 48, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM       DUAL
     CONNECT BY fact_from + (ROWNUM - 1) / 48 <= fact_till
     UNION ALL
     SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM   DUAL;
   END IF;
  ELSIF parametr = 2 THEN
   IF ln_dsummer <> 0 THEN
    --IF ln_timeZona <> 1/24  THEN
    IF is_day_switch = -1 THEN
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'yyyymmddhh24mi') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
      UNION ALL
      SELECT   ROWNUM ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'yyyymmdd') || str_sort1 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSIF is_day_switch = 1 THEN
     OPEN row_t FOR
      SELECT     1 ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks,
                 TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'YYYYMMDDHH24MI') srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
      MINUS
      SELECT   1 ID, TO_CHAR(day_switch, 'DD.MM.YYYY ') || str_timeswitch1 title1, cn_white datacl, 1 nlock, '' vmasks,
               TO_CHAR(day_switch, 'YYYYMMDD') || str_sort2 srt
      FROM     DUAL
      UNION ALL
      SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, '999999999999' srt
      FROM     DUAL
      ORDER BY 6;
    ELSE
     OPEN row_t FOR
      SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM       DUAL
      CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
      UNION ALL
      SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
      FROM   DUAL;
    END IF;
   ELSE
    OPEN row_t FOR
     SELECT     ROWNUM ID, TO_CHAR(fact_from + (ROWNUM - 1) / 24, 'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM       DUAL
     CONNECT BY fact_from + (ROWNUM - 1) / 24 <= fact_till
     UNION ALL
     SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
     FROM   DUAL;
   END IF;
  ELSIF parametr = 3 THEN
   OPEN row_t FOR
    SELECT     ROWNUM ID, TO_CHAR(fact_from + ROWNUM - 1, 'DD.MM.YYYY') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM       DUAL
    CONNECT BY fact_from + ROWNUM - 1 <= ad_till
    UNION ALL
    SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL;
  ELSIF parametr = 4 THEN
   OPEN row_t FOR
    SELECT     ROWNUM ID, RPAD(RTRIM(TO_CHAR(ADD_MONTHS(fact_from, ROWNUM - 1), 'Month')), 10) || TO_CHAR(ADD_MONTHS(fact_from, ROWNUM - 1), ' YYYY') title1,
               cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM       DUAL
    CONNECT BY ADD_MONTHS(fact_from,(ROWNUM - 1)) <= fact_till
    UNION ALL
    SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL;
  END IF;

  ad_from := fact_from;
  ad_till := fact_till;
 END;

------------------------------------------------------------------
 PROCEDURE proc_value_17(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, av_param VARCHAR2, quantity IN OUT VARCHAR2
 ) IS
  parametr            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 2);       --1-получасовые, 2-часовые, 3-суточные, 4-месячные
  fact_from           DATE;
  fact_till           DATE;
  dat_from2           DATE;
  dat_till2           DATE;
  temp_summ           common_pg.tt_number;
  lv_sql              VARCHAR2(4000);
  lv_grouping1        VARCHAR2(1000);
  lv_grouping2        VARCHAR2(1000);
  lv_sqltimezone      VARCHAR2(2000);
  lv_seldate          VARCHAR2(1000);
  lv_allrows          VARCHAR2(1000);
  cur_t               common_pg.tcur;
  ln_1                NUMBER DEFAULT NULL;
  ln_2                NUMBER DEFAULT NULL;
  ln_3                NUMBER DEFAULT NULL;
  ln_4                NUMBER DEFAULT NULL;
  ln_5                NUMBER DEFAULT NULL;
  ln_6                NUMBER DEFAULT NULL;
  ln_7                NUMBER DEFAULT NULL;
  lv_8                VARCHAR2(35) DEFAULT NULL;
  ln_timezona         NUMBER;
  ndx                 NUMBER;
  is_day_switch       NUMBER DEFAULT 0;
  --0 - нет перехода, 1 - весна, -1 - осень
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  day_switch          DATE;
  temp_date           DATE;
  str_timeswitch1     VARCHAR2(10);
  str_timeswitch2     VARCHAR2(10);
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  all_rows            NUMBER DEFAULT 0;
  is_rows             NUMBER DEFAULT 0;
  tmp1                NUMBER;
 BEGIN
--raise_application_error(-20001, an_fid ||'      '|| an_ispoint||'      '||an_id||'      '||ad_from||'      '||ad_till||'      '||data_t(1)||'         '||av_param||'      '||quantity);
  ndx := 0;
  ln_timezona := interior_pg.get_hourtimezone;
  quantity := 'q';

  FOR i IN 1 .. 6 LOOP                                                                                                                         --обнуляем итоги
   temp_summ(i) := NULL;
  END LOOP;

  --to_unlocaltime только для поясов без перехода
  --группировка
  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   --IF (ln_timeZona  <= 0) THEN
   IF (parametr = 1) THEN
    lv_grouping1 :=
        ' util_pg.get_param(to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'')';
--' substr(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,12) ';
   ELSIF(parametr = 2) THEN
    lv_grouping1 :=
        ' util_pg.get_param(to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'')';
--' substr(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,10) ';
   ELSIF(parametr = 3) THEN
    lv_grouping1 := ' to_char(P.date_time-1/86400- ' || ln_timezona || ',''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping1 := ' to_char(P.date_time-1/86400- ' || ln_timezona || ',''yyyymm'') ';
   END IF;
  ELSE
   IF (parametr = 1) THEN
    lv_grouping1 :=
        ' util_pg.get_param(TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'') ';
   ELSIF(parametr = 2) THEN
    lv_grouping1 :=
        ' util_pg.get_param(TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'') ';
   ELSIF(parametr = 3) THEN
    lv_grouping1 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ',nsource),''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping1 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ',nsource),''yyyymm'') ';
   END IF;
  END IF;

  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   --IF (ln_timeZona  <= 0) THEN
   IF (parametr = 1) THEN
    lv_grouping2 :=
        ' to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 2) THEN
    lv_grouping2 :=
        ' to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 3) THEN
    lv_grouping2 := lv_grouping1;
   --' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping2 := lv_grouping1;
   --' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymm'') ';
   END IF;
  ELSE
   IF (parametr = 1) THEN
    lv_grouping2 :=
        ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 2) THEN
    lv_grouping2 :=
        ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 3) THEN
    lv_grouping2 := lv_grouping1;
--' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''ddmmyyyy'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping2 := lv_grouping1;
--' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymm'') ';
   END IF;
  END IF;

  IF ln_dsummer = 0 THEN                                                                                                        --если часовой пояс без перехода
   --IF (interior_pg.get_hourtimezone > 0) THEN
   lv_sqltimezone :=
    ' AND   util_pg.to_unlocaltime (P.date_time, nsource) >= :d_from+1/86400
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= :d_till ';
  ELSE
   lv_sqltimezone :=
    ' AND   util_pg.to_unlocaltime (P.date_time, nsource) >= util_pg.to_unlocaltime (:d_from)+1/86400 
      AND   util_pg.to_unlocaltime (P.date_time, nsource) <= util_pg.to_unlocaltime (:d_till) ';
  END IF;

  --преведение границ времени
  IF parametr = 1 THEN                                                                                                                             --получасовки
   fact_from := util_pg.trunc_d(ad_from, 1 / 48) + interior_pg.get_hourtimezone;
   fact_till := util_pg.trunc_d(ad_till, 1 / 48) + interior_pg.get_hourtimezone;
  ELSIF parametr = 2 THEN                                                                                                                              --часовые
   fact_from := util_pg.trunc_d(ad_from, 1 / 24) + interior_pg.get_hourtimezone;
   fact_till := util_pg.trunc_d(ad_till, 1 / 24) + interior_pg.get_hourtimezone;
  ELSIF parametr = 3 THEN                                                                                                        --OR parametr=4 THEN --суточные
   fact_from := ad_from + interior_pg.get_hourtimezone;
   fact_till := ad_till + interior_pg.get_hourtimezone;
  ELSIF parametr = 4 THEN                                                                                                                            -- месячные
   fact_from := TRUNC(ad_from, 'MM') + interior_pg.get_hourtimezone;
   fact_till := LAST_DAY(ad_till) + interior_pg.get_hourtimezone;
  END IF;

  dat_from2 := fact_from - interior_pg.get_hourtimezone;
  dat_till2 := fact_till - interior_pg.get_hourtimezone;

  IF parametr = 1 THEN                                                                                                                             --получасовки
   --fact_from:=dat_from2+1/48;
   dat_from2 := dat_from2 + 1 / 48;
  ELSIF parametr = 2 THEN
   dat_from2 := dat_from2 + 1 / 24;
  END IF;

  --raise_application_error(-20001, 'fact_from '||to_char(fact_from,'dd-mon-yyyy hh24:mi') ||'fact_till '||to_char(fact_till,'dd-mon-yyyy hh24:mi'));
  IF parametr = 3 OR parametr = 4 THEN
   --  fact_till := fact_till + 1;
   fact_till := fact_till;
  --только для вывода посуточных и помесячных
  END IF;

  temp_date := dat_from2;

  WHILE(temp_date <= dat_till2) LOOP
   day_switch := temp_date;
   is_day_switch := util_pg.is_dayswitch(temp_date);
   EXIT WHEN util_pg.is_dayswitch(temp_date) <> 0;
   temp_date := temp_date + 1;
  END LOOP;

  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   IF parametr = 1 THEN
    IF ln_timezona = 0 THEN                                                                                                                           --Украина
     str_timeswitch1 := '0329';
     str_timeswitch2 := '0359';
    ELSIF ln_timezona = -1 / 24 THEN                                                                                                                    --Россия
     str_timeswitch1 := '0429';
     str_timeswitch2 := '0459';
    ELSIF ln_timezona = 1 / 24 THEN                                                                                                                     --Европа
     str_timeswitch1 := '0229';
     str_timeswitch2 := '0259';
    END IF;
   ELSE
    IF ln_timezona = 0 THEN                                                                                                                           --Украина
     str_timeswitch1 := '03';
     str_timeswitch2 := '0401';
    ELSIF ln_timezona = -1 / 24 THEN                                                                                                                    --Россия
     str_timeswitch1 := '04';
     str_timeswitch2 := '0501';
    ELSIF ln_timezona = 1 / 24 THEN                                                                                                                     --Европа
     str_timeswitch1 := '02';
     str_timeswitch2 := '0301';
    END IF;
   END IF;
  END IF;

  --подзапрос для выбора всех дат
  IF (parametr = 1) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     lv_seldate :=
      'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw1 BGroup FROM DUAL
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw2 BGroup FROM DUAL';
    ELSE
     lv_seldate :=
            'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2';
    END IF;
   ELSE
    lv_seldate :=
            'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2';
   END IF;
  ELSIF(parametr = 2) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     lv_seldate :=
      'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw1 BGroup FROM DUAL';
    ELSE
     lv_seldate :=
              'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2';
    END IF;
   ELSE
    lv_seldate :=
              'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2';
   END IF;
  ELSIF(parametr = 3) THEN                                                                                                                        ---   -1/86400
   lv_seldate := 'SELECT TO_CHAR(:d_from2+ROWNUM-1,''yyyymmdd'') BGroup
                FROM DUAL  CONNECT BY :d_from2+ROWNUM-1<= :d_till2';
  ELSIF(parametr = 4) THEN
   lv_seldate :=
        'SELECT TO_CHAR(ADD_MONTHS(:ad_from2, ROWNUM-1), ''yyyymm'') BGroup
                FROM DUAL  CONNECT BY ADD_MONTHS (:d_from2,(ROWNUM-1))<= :d_till2';
  END IF;

------------------
  IF is_day_switch = -1 THEN
   IF ln_dsummer = 0 THEN                                                                                                       --если часовой пояс с переходом
    IF parametr = 1 THEN
     lv_seldate :=
         lv_seldate
      || ' MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||''0329'' BGroup FROM DUAL
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||''0359'' BGroup FROM DUAL ';
    ELSIF parametr = 2 THEN
     lv_seldate := lv_seldate || ' MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||''03'' BGroup FROM DUAL ';
    END IF;
   END IF;
  END IF;

--закоммент строки в отдельной ф-ции (is_nodataqm)
/* ---------подсчет общего кол-ва строк (для метки качества)
 ln_1 := round((fact_till - fact_from)*24, 1);
 --raise_application_error(-20001, ln_1*2);
SELECT SUM (ln_1 * (60 / NVL (nintegralperiod, 30)) - 60 / NVL (nintegralperiod, 30) * is_day_switch) INTO all_rows
      FROM feeders
     WHERE mid IN (SELECT     p.mid
                         FROM GROUPS p
                   WHERE p.mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = an_id);


 ---------подсчет имеющегося кол-ва строк (для метки качества)
 ln_1 := NULL;
 is_rows := 0;
 FOR lc IN (SELECT     p.mid midd
                         FROM GROUPS p
                   WHERE p.mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = an_id)

 LOOP
    SELECT count(DISTINCT trunc(date_time, 'mi')) INTO ln_1 FROM halfhour P, GROUPS g
               WHERE g.mid = lc.midd AND g.mid = P.mid AND P.date_time> fact_from
     AND   date_time <=fact_till;

     is_rows := ln_1 + is_rows;
     ln_1 := NULL;
 END LOOP;*/

  --raise_application_error(-20001, all_rows||'  '||is_rows);
 ---------------------------------------------------------
--построение динамического запроса
  lv_sql :=
      'SELECT distinct b.BGroup, a.er, a.ed, a.sldA, a.q1, a.q3, a.sldR, a.vqm from
    
    (SELECT '
   || lv_grouping1
   || ' BGroup,
    --Актив
        SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 er,
        SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 ed,
        SUM (util_pg.sld (P.mid, P.er * DECODE (g.npartly, 2, 0, 1),P.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,''y'', -1,1))/1000 sldA,
    --Реактив    
        SUM (DECODE (g.inverted, ''y'', (nvl(P.q3,0)+nvl(P.q4,0)) * DECODE (g.npartly, 1, 0, 1), (nvl(P.q1,0)+nvl(P.q2,0)) * DECODE (g.npartly, 2, 0, 1)))/1000 q1,
        SUM (DECODE (g.inverted, ''y'', (nvl(P.q1,0)+nvl(P.q2,0)) * DECODE (g.npartly, 2, 0, 1), (nvl(P.q3,0)+nvl(P.q4,0)) * DECODE (g.npartly, 1, 0, 1)))/1000 q3,
        SUM (util_pg.sld (P.mid, (nvl(P.q1,0)+nvl(P.q2,0)) * DECODE (g.npartly, 2, 0, 1),(nvl(P.q3,0)+nvl(P.q4,0)) * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,''y'', -1,1))/1000 sldR,
        sumqm (P.vqm) vqm
        FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                                    WHERE mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :an_id 
                               UNION ALL 
                               SELECT gid FROM GROUPS WHERE gid=:an_id) AND g.mid = P.mid AND P.date_time>= (:d_from - DECODE(interior_pg.get_hourtimezone,0,0,3/24)
                               )
     AND   date_time <=(:d_till + DECODE(interior_pg.get_hourtimezone,0,0,3/24)) '
   || lv_sqltimezone
   || ' group by ('
   || lv_grouping2
   || '))a,
                               
     ('
   || lv_seldate
   || ') b
     
       WHERE b.BGroup=a.BGroup(+) ORDER BY 1';

  IF (parametr = 1) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     OPEN cur_t FOR lv_sql
     USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2, day_switch, str_timeswitch1, day_switch,
           str_timeswitch2;
    ELSE
     OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
    END IF;
   ELSE
    IF is_day_switch = -1 THEN
     OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2, day_switch, day_switch;
    ELSE
     OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
    END IF;
   END IF;
  ELSIF(parametr = 2) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch,
     str_timeswitch1;
    ELSE
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
    END IF;
   ELSE
    IF is_day_switch = -1 THEN
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch;
    ELSE
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
    END IF;
   END IF;
  ELSE
   OPEN cur_t FOR lv_sql USING an_id, an_id, fact_from, fact_till, fact_from, fact_till, dat_from2, dat_from2, dat_till2;   -- fact_from, fact_from, fact_till;
  END IF;

  -- raise_application_error(-20001,an_id||'    '||TO_CHAR(fact_from, 'dd-mm-yyyy hh24:mi')||'   '||TO_CHAR(fact_till, 'dd-mm-yyyy hh24:mi')||'    '||TO_CHAR(dat_from2, 'dd-mm-yyyy hh24:mi')||'    '|| TO_CHAR(dat_till2, 'dd-mm-yyyy hh24:mi'));
  LOOP
   FETCH cur_t
   INTO  ln_1, ln_2, ln_3, ln_4, ln_5, ln_6, ln_7, lv_8;

   EXIT WHEN cur_t%NOTFOUND;
   data_t(ndx + 1) := ln_2;
   data_t(ndx + 2) := ln_3;
   data_t(ndx + 3) := ln_4;
   data_t(ndx + 4) := ln_5;
   data_t(ndx + 5) := ln_6;
   data_t(ndx + 6) := ln_7;

   IF quantity = 'q' THEN
    quantity := NVL(lv_8, 'q');
   ELSE
    quantity := qm_pg.sumqm(quantity, lv_8);
   END IF;

   --raise_application_error(-20001,quantity);
   FOR i IN 1 .. 6 LOOP
    temp_summ(i) := util_pg.sumn(temp_summ(i), data_t(ndx + i));
   END LOOP;

   ndx := ndx + 6;
  END LOOP;

  IF quantity = 'q' THEN
   quantity := qm_pg.nodataqm;
  ELSE
   SELECT DECODE(is_nodataqm(an_id, fact_from, fact_till), 1, qm_pg.sumqm(quantity, qm_pg.nodataqm), quantity)
   INTO   quantity
   FROM   DUAL;
  END IF;

  --SELECT decode (is_nodataqm(an_id, fact_from, fact_till), 1, qm_pg.sumqm (quantity,qm_pg.nodataqm), quantity) INTO quantity FROM dual;
  -- raise_application_error(-20001,data_t.count);
  FOR i IN 1 .. 6 LOOP
   data_t(data_t.COUNT + 1) := temp_summ(i);
  END LOOP;
 --raise_application_error(-20001,data_t.count);
 END;

---------------------------------
 PROCEDURE proc_value_18(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, av_param VARCHAR2, quantity IN OUT VARCHAR2
 ) IS
  parametr            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 2);       --1-получасовые, 2-часовые, 3-суточные, 4-месячные
  fact_from           DATE;
  fact_till           DATE;
  ndx                 NUMBER;
  temp_summ           common_pg.tt_number;
  ln_cnt              NUMBER;
  sum_prm             NUMBER;
  sum_otd             NUMBER;
  sum_sld             NUMBER;
  lv_sql              VARCHAR2(4000);
  lv_grouping1        VARCHAR2(1000);
  ln_cnt_rows         NUMBER;
  dat_from2           DATE;
  dat_till2           DATE;
  lv_grouping2        VARCHAR2(1000);
  lv_sqltimezone      VARCHAR2(2000);
  lv_seldate          VARCHAR2(1000);
  cur_t               common_pg.tcur;
  ln_1                NUMBER DEFAULT NULL;
  ln_2                NUMBER DEFAULT NULL;
  ln_3                NUMBER DEFAULT NULL;
  ln_4                NUMBER DEFAULT NULL;
  ln_5                NUMBER DEFAULT NULL;
  ln_6                NUMBER DEFAULT NULL;
  ln_7                NUMBER DEFAULT NULL;
  lv_8                VARCHAR2(35) DEFAULT NULL;
  ln_timezona         NUMBER;
  ndx_sum             NUMBER;
  is_day_switch       NUMBER;                                                                                         --0 - нет перехода, 1 - весна, -1 - осень
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  day_switch          DATE;
  temp_date           DATE;
  str_timeswitch1     VARCHAR2(10);
  str_timeswitch2     VARCHAR2(10);
 BEGIN
  quantity := 'q';
  ndx := 0;
  ln_cnt := 0;
  sum_prm := NULL;
  sum_otd := NULL;
  sum_sld := NULL;
  ln_timezona := interior_pg.get_hourtimezone;

  SELECT COUNT(gid)
  INTO   ln_cnt
  FROM   GROUPS
  WHERE  PARENT = an_id;

  FOR i IN 1 ..((ln_cnt + 1) * 3) LOOP                                                                                                         --обнуляем суммы
   temp_summ(i) := NULL;
  END LOOP;

--группировка
  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   --IF (ln_timeZona  <= 0) THEN
   IF (parametr = 1) THEN
    lv_grouping1 :=
        ' util_pg.get_param(to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'')';
--' substr(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,12) ';
   ELSIF(parametr = 2) THEN
    lv_grouping1 :=
        ' util_pg.get_param(to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'')';
--' substr(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,10) ';
   ELSIF(parametr = 3) THEN
    lv_grouping1 := ' to_char(P.date_time -1/86400-' || ln_timezona || ',''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping1 := ' to_char(P.date_time-1/86400- ' || ln_timezona || ',''yyyymm'') ';
   END IF;
  ELSE
   IF (parametr = 1) THEN
    lv_grouping1 :=
        ' util_pg.get_param(TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'') ';
   ELSIF(parametr = 2) THEN
    lv_grouping1 :=
        ' util_pg.get_param(TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || '),1,''.'') ';
   ELSIF(parametr = 3) THEN
    lv_grouping1 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ',nsource),''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping1 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- ' || ln_timezona || ',nsource),''yyyymm'') ';
   END IF;
  END IF;

  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   --IF (ln_timeZona  <= 0) THEN
   IF (parametr = 1) THEN
    lv_grouping2 :=
        ' to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 2) THEN
    lv_grouping2 :=
        ' to_char(P.date_time-1/86400- '
     || ln_timezona
     || ',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 3) THEN
    lv_grouping2 := lv_grouping1;
   --' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping2 := lv_grouping1;
   --' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymm'') ';
   END IF;
  ELSE
   IF (parametr = 1) THEN
    lv_grouping2 :=
        ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 2) THEN
    lv_grouping2 :=
        ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '
     || ln_timezona
     || ',nsource),''yyyymmddhh24'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'
     || ln_timezona
     || ') ';
   ELSIF(parametr = 3) THEN
    lv_grouping2 := lv_grouping1;
--' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymmdd'') ';
   ELSIF(parametr = 4) THEN
    lv_grouping2 := lv_grouping1;
--' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymm'') ';
   END IF;
  END IF;

  IF ln_dsummer = 0 THEN                                                                                                         --если часовой пояс с переходом
   --IF (ln_timeZona > 0) THEN
   lv_sqltimezone :=
          ' AND   util_pg.to_unlocaltime (P.date_time, nsource) >= :d_from
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= :d_till';
  ELSE
   lv_sqltimezone :=
    ' AND   util_pg.to_unlocaltime (P.date_time, nsource) >= util_pg.to_unlocaltime (:d_from)
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= util_pg.to_unlocaltime (:d_till)';
  END IF;

  --преведение границ времени
  IF parametr = 1 THEN                                                                                                                             --получасовки
   fact_from := util_pg.trunc_d(ad_from, 1 / 48) + interior_pg.get_hourtimezone;
   fact_till := util_pg.trunc_d(ad_till, 1 / 48) + interior_pg.get_hourtimezone;
  ELSIF parametr = 2 THEN                                                                                                                              --часовые
   fact_from := util_pg.trunc_d(ad_from, 1 / 24) + interior_pg.get_hourtimezone;
   fact_till := util_pg.trunc_d(ad_till, 1 / 24) + interior_pg.get_hourtimezone;
  ELSIF parametr = 3 THEN                                                                                                        --OR parametr=4 THEN --суточные
   fact_from := ad_from + interior_pg.get_hourtimezone;
   fact_till := ad_till + interior_pg.get_hourtimezone;
  ELSIF parametr = 4 THEN                                                                                                                            -- месячные
   fact_from := TRUNC(ad_from, 'MM') + interior_pg.get_hourtimezone;
   fact_till := LAST_DAY(ad_till) + interior_pg.get_hourtimezone;
  END IF;

  dat_from2 := fact_from - interior_pg.get_hourtimezone;
  dat_till2 := fact_till - interior_pg.get_hourtimezone;

  IF parametr = 1 THEN                                                                                                                             --получасовки
   --fact_from:=dat_from2+1/48;
   dat_from2 := dat_from2 + 1 / 48;
  ELSIF parametr = 2 THEN
   dat_from2 := dat_from2 + 1 / 24;
  END IF;

  IF parametr = 3 OR parametr = 4 THEN
   --  fact_till := fact_till + 1;
   fact_till := fact_till;
  --только для вывода посуточных и помесячных
  END IF;

  temp_date := dat_from2;

  WHILE(temp_date <= dat_till2) LOOP
   day_switch := temp_date;
   is_day_switch := util_pg.is_dayswitch(temp_date);
   EXIT WHEN util_pg.is_dayswitch(temp_date) <> 0;
   temp_date := temp_date + 1;
  END LOOP;

  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   -- IF ln_timeZona <> 1/24 THEN
   IF parametr = 1 THEN
    IF ln_timezona = 0 THEN                                                                                                                           --Украина
     str_timeswitch1 := '0329';
     str_timeswitch2 := '0359';
    ELSIF ln_timezona = -1 / 24 THEN                                                                                                                    --Россия
     str_timeswitch1 := '0429';
     str_timeswitch2 := '0459';
    ELSIF ln_timezona = 1 / 24 THEN                                                                                                                     --Европа
     str_timeswitch1 := '0229';
     str_timeswitch2 := '0259';
    END IF;
   ELSE
    IF ln_timezona = 0 THEN                                                                                                                           --Украина
     str_timeswitch1 := '03';
     str_timeswitch2 := '0401';
    ELSIF ln_timezona = -1 / 24 THEN                                                                                                                    --Россия
     str_timeswitch1 := '04';
     str_timeswitch2 := '0501';
    ELSIF ln_timezona = 1 / 24 THEN                                                                                                                     --Европа
     str_timeswitch1 := '02';
     str_timeswitch2 := '0301';
    END IF;
   END IF;
  END IF;

  --подзапрос для выбора всех дат
  IF (parametr = 1) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     lv_seldate :=
      'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw1 BGroup FROM DUAL
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw2 BGroup FROM DUAL';
    ELSE
     lv_seldate :=
            'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2';
    END IF;
   ELSE
    lv_seldate :=
            'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2';
   END IF;
  ELSIF(parametr = 2) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     lv_seldate :=
      'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw1 BGroup FROM DUAL';
    ELSE
     lv_seldate :=
              'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2';
    END IF;
   ELSE
    lv_seldate :=
              'SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2';
   END IF;
  ELSIF(parametr = 3) THEN                                                                                                                --!!!!!!!!!!  -1/86400
   lv_seldate := 'SELECT TO_CHAR(:d_from2+ROWNUM-1,''yyyymmdd'') BGroup    
                FROM DUAL  CONNECT BY :d_from2+ROWNUM-1<= :d_till2';
  ELSIF(parametr = 4) THEN
   lv_seldate :=
        'SELECT TO_CHAR(ADD_MONTHS(:ad_from2, ROWNUM-1), ''yyyymm'') BGroup
                FROM DUAL  CONNECT BY ADD_MONTHS (:d_from2,(ROWNUM-1))<= :d_till2';
  END IF;

  --выбор количества записей
  IF (parametr = 1) THEN
   SELECT     COUNT(dat_from2 + (ROWNUM - 1) / 48 - 1 / 86400)
   INTO       ln_cnt_rows
   FROM       DUAL
   CONNECT BY dat_from2 + (ROWNUM - 1) / 48 <= dat_till2;
  ELSIF(parametr = 2) THEN
   SELECT     COUNT(TO_CHAR(dat_from2 + (ROWNUM - 1) / 24 - 1 / 86400, 'yyyymmddhh24'))
   INTO       ln_cnt_rows
   FROM       DUAL
   CONNECT BY dat_from2 + (ROWNUM - 1) / 24 <= dat_till2;
  ELSIF(parametr = 3) THEN
   SELECT     COUNT(TO_CHAR(dat_from2 + ROWNUM - 1 - 1 / 86400, 'yyyymmdd'))
   INTO       ln_cnt_rows
   FROM       DUAL
   CONNECT BY dat_from2 + ROWNUM - 1 <= dat_till2;
  ELSIF(parametr = 4) THEN
   SELECT     COUNT(TO_CHAR(ADD_MONTHS(dat_from2, ROWNUM - 1), 'yyyymm'))
   INTO       ln_cnt_rows
   FROM       DUAL
   CONNECT BY ADD_MONTHS(dat_from2,(ROWNUM - 1)) <= dat_till2;
  END IF;

  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   IF is_day_switch = -1 THEN                                                                                                                           --весна
    IF parametr = 1 THEN
     ln_cnt_rows := ln_cnt_rows - 2;
    ELSIF parametr = 2 THEN
     ln_cnt_rows := ln_cnt_rows - 1;
    END IF;
   ELSIF is_day_switch = 1 THEN                                                                                                                          --осень
    IF parametr = 1 THEN
     ln_cnt_rows := ln_cnt_rows + 2;
    ELSIF parametr = 2 THEN
     ln_cnt_rows := ln_cnt_rows + 1;
    END IF;
   END IF;
  END IF;

  ndx_sum := 0;

------------------
  IF is_day_switch = -1 THEN
   IF ln_dsummer = 0 THEN                                                                                                      --если часовой пояс без перехода
    IF parametr = 1 THEN
     lv_seldate :=
         lv_seldate
      || ' MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||''0329'' BGroup FROM DUAL
                MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||''0359'' BGroup FROM DUAL ';
    ELSIF parametr = 2 THEN
     lv_seldate := lv_seldate || ' MINUS 
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||''03'' BGroup FROM DUAL ';
    END IF;
   END IF;
  END IF;

------------------
--   cv_sm := 'qm_pg.sumqm(nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm),qm_pg.nodataqm),nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm)';
 --  av_decnsourcesec :=
   -- ' ,decode(sign(count(*)-count(*)),1,qm_pg.sumqm(nvl(SUMQM(nvl(P.vqm,qm_pg.defqm)),qm_pg.defqm),qm_pg.nodataqm),nvl(SUMQM(nvl(P.vqm,qm_pg.defqm)),qm_pg.defqm)) ';

  --построение динамического запроса
  lv_sql :=
      'SELECT distinct b.BGroup, a.er, a.ed, a.sldA, a.vqm from
    
    (SELECT '
   || lv_grouping1
   || ' BGroup,
    --Актив
        SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 er,
        SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 ed,
        SUM (util_pg.sld (P.mid, P.er * DECODE (g.npartly, 2, 0, 1),P.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,''y'', -1,1))/1000 sldA,
        sumqm (P.vqm) vqm
        FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                                    WHERE mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :an_id 
                               UNION ALL 
                               SELECT gid FROM GROUPS WHERE gid=:an_id) AND g.mid = P.mid AND P.date_time>= (:d_from - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
     AND   date_time <=(:d_till + DECODE(interior_pg.get_hourtimezone,0,0,3/24)) '
   || lv_sqltimezone
   || ' group by ('
   || lv_grouping2
   || '))a,
                               
     ('
   || lv_seldate
   || ') b
     
       WHERE b.BGroup=a.BGroup(+) ORDER BY 1';

  FOR lc IN (SELECT vparam, NAME, gid, ROWNUM rn
             FROM   (SELECT   vparam, NAME, gid
                     FROM     GROUPS
                     WHERE    PARENT = an_id
                     ORDER BY 1, 2)) LOOP
   IF (parametr = 1) THEN
    IF ln_dsummer <> 0 THEN                                                                                                     --если часовой пояс с переходом
     IF is_day_switch = 1 THEN
      OPEN cur_t FOR lv_sql
      USING 48, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2, day_switch, str_timeswitch1, day_switch,
            str_timeswitch2;
     ELSE
      OPEN cur_t FOR lv_sql USING 48, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
     END IF;
    ELSE
     IF is_day_switch = -1 THEN
      OPEN cur_t FOR lv_sql USING 48, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2, day_switch, day_switch;
     ELSE
      OPEN cur_t FOR lv_sql USING 48, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
     END IF;
    END IF;
   ELSIF(parametr = 2) THEN
    IF ln_dsummer <> 0 THEN                                                                                                     --если часовой пояс с переходом
     IF is_day_switch = 1 THEN
      OPEN cur_t FOR lv_sql USING 24, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch,
      str_timeswitch1;
     ELSE
      OPEN cur_t FOR lv_sql USING 24, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
     END IF;
    ELSE
     IF is_day_switch = -1 THEN
      OPEN cur_t FOR lv_sql USING 24, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch;
     ELSE
      OPEN cur_t FOR lv_sql USING 24, lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
     END IF;
    END IF;
   ELSE
    OPEN cur_t FOR lv_sql USING lc.gid, lc.gid, fact_from, fact_till, fact_from, fact_till, dat_from2, dat_from2, dat_till2;
                                                                                                                            -- fact_from, fact_from, fact_till;
   END IF;

   LOOP
    FETCH cur_t
    INTO  ln_1, ln_2, ln_3, ln_4, lv_8;

    EXIT WHEN cur_t%NOTFOUND;
    data_t(ndx + 1) := ln_2;
    data_t(ndx + 2) := ln_3;
    data_t(ndx + 3) := ln_4;

    FOR i IN 1 .. 3 LOOP
     temp_summ(i + ndx_sum) := util_pg.sumn(temp_summ(i + ndx_sum), data_t(ndx + i));
    END LOOP;

    ndx := ndx +((ln_cnt + 1) * 3);
   END LOOP;

   ndx := ndx + 6;
   ndx_sum := ndx_sum + 3;
   ndx := lc.rn * 3;

   CLOSE cur_t;
  END LOOP;

  --запуск запроса для вывода суммир столбца
  IF (parametr = 1) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     OPEN cur_t FOR lv_sql
     USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2, day_switch, str_timeswitch1, day_switch,
           str_timeswitch2;
    ELSE
     OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
    END IF;
   ELSE
    IF is_day_switch = -1 THEN
     OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2, day_switch, day_switch;
    ELSE
     OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
    END IF;
   END IF;
  ELSIF(parametr = 2) THEN
   IF ln_dsummer <> 0 THEN                                                                                                      --если часовой пояс с переходом
    IF is_day_switch = 1 THEN
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch,
     str_timeswitch1;
    ELSE
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
    END IF;
   ELSE
    IF is_day_switch = -1 THEN
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch;
    ELSE
     OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
    END IF;
   END IF;
  ELSE
   /*OPEN cur_t FOR lv_sql USING an_id, an_id, fact_from,fact_till, fact_from,fact_till, fact_from, fact_from, fact_till;*/
   OPEN cur_t FOR lv_sql USING an_id, an_id, fact_from, fact_till, fact_from, fact_till, dat_from2, dat_from2, dat_till2;   -- fact_from, fact_from, fact_till;
  END IF;

  LOOP
   FETCH cur_t
   INTO  ln_1, ln_2, ln_3, ln_4, lv_8;

   EXIT WHEN cur_t%NOTFOUND;
   data_t(ndx + 1) := ln_2;
   data_t(ndx + 2) := ln_3;
   data_t(ndx + 3) := ln_4;

   -- quantity := lv_8; --qm_pg.sumqm (quantity, lv_8);
   IF quantity = 'q' THEN
    quantity := NVL(lv_8, 'q');
   ELSE
    quantity := qm_pg.sumqm(quantity, lv_8);
   END IF;

   FOR i IN 1 .. 3 LOOP
    temp_summ(i + ndx_sum) := util_pg.sumn(temp_summ(i + ndx_sum), data_t(ndx + i));
   END LOOP;

   ndx := ndx +((ln_cnt + 1) * 3);
  END LOOP;

  ndx := data_t.COUNT;

  CLOSE cur_t;

  SELECT DECODE(is_nodataqm(an_id, fact_from, fact_till), 1, qm_pg.sumqm(quantity, qm_pg.nodataqm), quantity)
  INTO   quantity
  FROM   DUAL;

  -----вывод сумм
  FOR i IN 1 ..((ln_cnt + 1) * 3) LOOP
   data_t(ndx + i) := temp_summ(i);
  END LOOP;
 --raise_application_error(-20001,data_t.count);
 END;

---------------------------------------------------------------------------------
 FUNCTION get_num(d DATE, an_source NUMBER, an_dif NUMBER, an_in_end NUMBER DEFAULT 1, an_shifttz NUMBER DEFAULT 0)
--an_dif - как делить 1/2 - это пол дня, 1/24 - по часам , 1/48 - по получасам
 RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(10);
 BEGIN
  lv_ret := util_pg.get_num_dt(d, an_source, an_dif, 0, an_shifttz, interior_pg.get_dsummer);

  IF (lv_ret < 10) THEN
   lv_ret := '0' || lv_ret;
  END IF;

  RETURN lv_ret;
 END;

---------------------------------------------------------------------------------
 FUNCTION get_oik_mid(an_gid NUMBER, an_cid NUMBER)
  RETURN NUMBER IS
  ret                 NUMBER;
 BEGIN
  SELECT p2.mid
  INTO   ret
  FROM   points p1, points p2
  WHERE  p1.mid = an_gid AND p1.PARENT = p2.PARENT AND p2.mid IN(SELECT mid
                                                                 FROM   chanpoint
                                                                 WHERE  cid = an_cid);

  RETURN ret;
 END;

---------------------------------------------------------------------------------
 /*2 PROCEDURE proc_info_17 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
 an_cnfooter IN OUT  NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur,av_param VARCHAR2) IS
  parametr           NUMBER     DEFAULT nvl(util_pg.allnumber_f(util_pg.get_param(av_param,2,';')),2); --1-получасовые, 2-часовые, 3-суточные, 4-месячные
  fact_from          DATE;
  fact_till          DATE;
  ln_locksum         NUMBER     DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);
  ln_dsummer         NUMBER     DEFAULT INTERIOR_PG.get_dsummer;            --переход на лето. 0 - нет, 1 - да
  ------------
  point              VARCHAR2(100);
  time_poyas         VARCHAR2(100);
  period             VARCHAR2(100);
  str3               VARCHAR2(100);
  str4               VARCHAR2(100);
  str5               VARCHAR2(100);
  str6               VARCHAR2(100);

  ------------
  ln_timeZona        NUMBER;


 BEGIN
    an_cnfixcol := 1;
    an_cntitle := 2;

    ln_timeZona:=INTERIOR_PG.get_hourtimezone;
    ln_dsummer:= INTERIOR_PG.get_dsummer;        --переход на лето. 0 - нет, 1 - да


   SELECT DECODE (ln_locksum, 0, 1, 0)
     INTO an_cnfooter
     FROM DUAL;

    IF parametr=1   THEN   --получасовки
     fact_from:=util_pg.trunc_d(ad_from,1/48)+1/48;
     fact_till:=util_pg.trunc_d(ad_till,1/48);

    ELSIF parametr=2 THEN --часовые
     fact_from:=util_pg.trunc_d(ad_from,1/24)+1/24;
     fact_till:=util_pg.trunc_d(ad_till,1/24);

    ELSIF parametr=3 THEN -- посуточные
       fact_from:=ad_from;
       fact_till:=ad_till;

    ELSIF parametr=4 THEN -- помесячные
       fact_from:=trunc(ad_from,'MM');
       fact_till:=LAST_DAY(ad_till);
    END IF;

 OPEN col_t FOR
    SELECT -1 ID, 'Временной интервал' title1,'' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 100 nwidth, '' vmasks
      FROM DUAL
      UNION ALL
    SELECT 0 ID, 'Актив [тыс.кВт ч]' title1, 'прием' title2,  cn_btnface titlecl, cn_center titleal,  cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
      FROM DUAL
    UNION ALL
    SELECT 1 ID, 'Актив [тыс.кВт ч]' title1, 'отдача' title2,  cn_btnface titlecl, cn_center titleal,  cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
      FROM DUAL
    UNION ALL
    SELECT 2 ID, 'Актив [тыс.кВт ч]' title1, 'сальдо' title2,  cn_btnface titlecl, cn_center titleal,  cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
      FROM DUAL
    UNION ALL
    SELECT 3 ID, 'Реактив [тыс.кВт ч]' title1, 'прием' title2,  cn_btnface titlecl, cn_center titleal,  cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
      FROM DUAL
    UNION ALL
    SELECT 4 ID, 'Реактив [тыс.кВт ч]' title1, 'отдача' title2,  cn_btnface titlecl, cn_center titleal,  cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
      FROM DUAL
    UNION ALL
    SELECT 5 ID, 'Реактив [тыс.кВт ч]' title1, 'сальдо' title2,  cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
      FROM DUAL;

    IF parametr=1 THEN
        IF  ln_timeZona=0 THEN              --Украина
            str3:=' 03:30';
            str4:=' 04:00';
            str5:='0330';
            str6:='0400';
        ELSIF ln_timeZona=-1/24  THEN       --Россия
            str3:=' 04:30';
            str4:=' 05:00';
            str5:='0430';
            str6:='0500';
        ELSIF ln_timeZona=1/24   THEN       --Европа
            str3:=' 02:30';
            str4:=' 03:00';
            str5:='0230';
            str6:='0300';
        END IF;
    ELSE
        IF  ln_timeZona=0 THEN              --Украина
            str3:=' 04:00';
        ELSIF ln_timeZona=-1/24   THEN      --Россия
            str3:=' 05:00';
        ELSIF ln_timeZona=1/24    THEN      --Европа
            str3:=' 03:00';
        END IF;
    END IF;

    IF parametr=1 THEN
        IF ln_dsummer<>0  THEN
            OPEN row_t FOR
            SELECT ROWNUM id, t.title1, cn_white datacl, 0 nlock, '' vmasks, t.srt FROM
            (SELECT q.title1 title1, q.srt FROM
            (SELECT ROWNUM, title1, srt FROM(SELECT TO_CHAR(fact_from+(ROWNUM-1)/48, 'DD.MM.YYYY HH24:MI') title1, TO_CHAR(fact_from+(ROWNUM-1)/48,'yyyymmddhh24mi') srt FROM dual CONNECT BY fact_from+(ROWNUM-1)/48 <= fact_till))q
            WHERE q.title1 NOT IN
            (SELECT qq.title1 FROM(
            SELECT DISTINCT decode((util_pg.is_dayswitch(fact_from+(ROWNUM-1)/48)), 1, to_char(fact_from+(ROWNUM-1)/48, 'DD.MM.YYYY')||str3, NULL) title1 FROM dual CONNECT BY fact_from+(ROWNUM-1)/48 <= fact_till
            UNION ALL
            SELECT DISTINCT decode((util_pg.is_dayswitch(fact_from+(ROWNUM-1)/48)), 1,
            to_char(fact_from+(ROWNUM-1)/48, 'DD.MM.YYYY')||str4, NULL) title1
            FROM dual CONNECT BY fact_from+(ROWNUM-1)/48 <=
            fact_till)qq WHERE qq.title1 IS NOT NULL)
            UNION ALL
            SELECT DISTINCT qq.title1, qq.srt FROM(
            SELECT DISTINCT decode((util_pg.is_dayswitch(fact_from+(ROWNUM-1)/48)), -1, to_char(fact_from+(ROWNUM-1)/48, 'DD.MM.YYYY')||str3, NULL) title1, TO_CHAR(fact_from+(ROWNUM-1)/48,'yyyymmdd')||str5 srt FROM dual CONNECT BY fact_from+(ROWNUM-1)/48 <= fact_till
            UNION ALL
            SELECT DISTINCT decode((util_pg.is_dayswitch(fact_from+(ROWNUM-1)/48)), -1,
            to_char(fact_from+(ROWNUM-1)/48, 'DD.MM.YYYY')||str4, NULL) title1, TO_CHAR(fact_from+(ROWNUM-1)/48,'yyyymmdd')||str6 srt
            FROM dual CONNECT BY fact_from+(ROWNUM-1)/48 <=
            fact_till)qq WHERE qq.title1 IS NOT NULL)t
            UNION ALL
            SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl,  0 nlock, '' vmasks, '999999999999' srt
            FROM DUAL ORDER BY 6;
        ELSE
            OPEN row_t FOR              --если перехода на лето не должно быть
            SELECT ROWNUM ID, TO_CHAR(fact_from+(ROWNUM-1)/48,'DD.MM.YYYY HH24:MI') title1, cn_white datacl, 0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL  CONNECT BY fact_from+(ROWNUM-1)/48<= fact_till
            UNION ALL
            SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl, 0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL;
        END IF;


    ELSIF parametr=2 THEN
        IF ln_dsummer<>0  THEN
            OPEN row_t FOR SELECT ROWNUM id, t.title1, cn_white datacl, 0 nlock, '' vmasks, t.srt FROM
            (SELECT q.title1 title1, q.srt FROM (
            SELECT ROWNUM, title1, srt FROM(SELECT TO_CHAR(fact_from+(ROWNUM-1)/24, 'DD.MM.YYYY HH24:MI') title1, TO_CHAR(fact_from+(ROWNUM-1)/24,'yyyymmddhh24mi') srt FROM dual CONNECT BY fact_from+(ROWNUM-1)/24 <= fact_till))q
            WHERE q.title1 NOT IN
            (SELECT qq.title1 FROM(
            SELECT DISTINCT decode((util_pg.is_dayswitch(fact_from+(ROWNUM-1)/24)), 1, to_char(fact_from+(ROWNUM-1)/24, 'DD.MM.YYYY')||str3, NULL) title1 FROM dual CONNECT BY fact_from+(ROWNUM-1)/48 <= fact_till)qq WHERE qq.title1 IS NOT NULL)
            UNION ALL
            SELECT qq.title1, qq.srt FROM(
            SELECT DISTINCT decode((util_pg.is_dayswitch(fact_from+(ROWNUM-1)/24)), -1, to_char(fact_from+(ROWNUM-1)/24, 'DD.MM.YYYY')||str3, NULL) title1, TO_CHAR(fact_from+(ROWNUM-1)/48,'yyyymmddhh24mi') srt FROM dual CONNECT BY fact_from+(ROWNUM-1)/24 <= fact_till)qq WHERE qq.title1 IS NOT NULL)t
            UNION ALL
            SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl,  0 nlock, '' vmasks, '999999999999' srt
            FROM DUAL ORDER BY 6;
        ELSE
            OPEN row_t FOR
            SELECT ROWNUM ID, TO_CHAR(fact_from+(ROWNUM-1)/24,'DD.MM.YYYY HH24:MI') title1, cn_white datacl,  0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL  CONNECT BY fact_from+(ROWNUM-1)/24<= fact_till
            UNION ALL
            SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl,  0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL;
        END IF;


    ELSIF parametr=3 THEN
        OPEN row_t FOR
            SELECT ROWNUM ID, TO_CHAR(fact_from+ROWNUM-1,'DD.MM.YYYY') title1, cn_white datacl,  0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL  CONNECT BY fact_from+ROWNUM-1<= fact_till
            UNION ALL
            SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl,  0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL;

    ELSIF parametr=4 THEN
        OPEN row_t FOR
            SELECT ROWNUM ID, RPAD(RTRIM(TO_CHAR(ADD_MONTHS(fact_from, ROWNUM-1), 'Month')),10)||TO_CHAR(ADD_MONTHS(fact_from, ROWNUM-1), ' YYYY') title1, cn_white datacl,  0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL  CONNECT BY ADD_MONTHS (fact_from,(ROWNUM-1))<= fact_till
            UNION ALL
            SELECT   -1 ID, 'Итого:' title1, cn_yellow datacl,  0 nlock, '' vmasks, 1000000000 srt
            FROM DUAL;
    END IF;

 ad_from:=fact_from;
 ad_till:=fact_till;
 END;
 ------------------------------------------------------------------------------------
 PROCEDURE proc_value_17 (an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number,av_param VARCHAR2, quantity IN OUT VARCHAR2) IS
    parametr            NUMBER                  DEFAULT nvl(util_pg.allnumber_f(util_pg.get_param(av_param,2,';')),2); --1-получасовые, 2-часовые, 3-суточные, 4-месячные
    fact_from           DATE;
    fact_till           DATE;
    dat_from2           DATE;
    dat_till2           DATE;
    temp_summ           common_pg.tt_number;
    lv_sql              VARCHAR2(4000);
    lv_grouping1        VARCHAR2(1000);
    lv_grouping2        VARCHAR2(1000);
    lv_sqltimezone      VARCHAR2(2000);
    lv_seldate          VARCHAR2(10000);
    cur_t               common_pg.tcur;
    ln_1                NUMBER       DEFAULT NULL;
    ln_2                NUMBER       DEFAULT NULL;
    ln_3                NUMBER       DEFAULT NULL;
    ln_4                NUMBER       DEFAULT NULL;
    ln_5                NUMBER       DEFAULT NULL;
    ln_6                NUMBER       DEFAULT NULL;
    ln_7                NUMBER       DEFAULT NULL;
    lv_8                VARCHAR2(35) DEFAULT NULL;
    ln_timeZona         NUMBER;
    ndx                 NUMBER;
    is_day_switch       NUMBER       DEFAULT 0;                              --0 - нет перехода, 1 - весна, -1 - осень
    ln_dsummer          NUMBER       DEFAULT INTERIOR_PG.get_dsummer;        --переход на лето. 0 - нет, 1 - да
  day_switch            DATE;
  temp_date             DATE;
  str_timeswitch1       VARCHAR2(10);
  str_timeswitch2       VARCHAR2(10);
  str3                  VARCHAR2(100);
  str4                  VARCHAR2(100);
  ln_locksum            NUMBER       DEFAULT UNIINTERIOR_PG.f_locksum(an_fid);

 BEGIN
--raise_application_error(-20001, an_fid ||'      '|| an_ispoint||'      '||an_id||'      '||ad_from||'      '||ad_till||'      '||data_t(1)||'         '||av_param||'      '||quantity);

  ndx:=0;
  ln_timeZona:=interior_pg.get_hourtimezone;
  quantity:='';


  FOR i IN 1 .. 6 LOOP     --обнуляем итоги
    temp_summ (i) := NULL;
   END LOOP;

  --to_unlocaltime только для поясов без перехода
  --группировка
  IF ln_dsummer<>0 THEN     --если часовой пояс с переходом
  --IF (ln_timeZona  <= 0) THEN

   IF (parametr=1) THEN
    lv_grouping1 := ' util_pg.get_param(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,''.'')';--' substr(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,12) ';
   ELSIF (parametr=2) THEN
    lv_grouping1 := ' util_pg.get_param(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,''.'')';--' substr(to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||'),1,10) ';
   ELSIF (parametr = 3) THEN
    lv_grouping1 := ' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmdd'') ';
   ELSIF (parametr = 4) THEN
    lv_grouping1 := ' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymm'') ';
   END IF;

  ELSE

   IF (parametr=1) THEN
    lv_grouping1 := ' util_pg.get_param(TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'||ln_timeZona||'),1,''.'') ';
   ELSIF (parametr=2) THEN
    lv_grouping1 := ' util_pg.get_param(TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymmddhh24'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'||ln_timeZona||'),1,''.'') ';
   ELSIF (parametr = 3) THEN
    lv_grouping1 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymmdd'') ';
   ELSIF (parametr = 4) THEN
    lv_grouping1 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymm'') ';

   END IF;
 END IF;

 IF ln_dsummer<>0 THEN     --если часовой пояс с переходом
 --IF (ln_timeZona  <= 0) THEN

   IF (parametr=1) THEN
    lv_grouping2 := ' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||') ';
   ELSIF (parametr=2) THEN
    lv_grouping2 := ' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmddhh24'') ||''.''||uniinterior1_pg.get_num (P.date_time-1/86400,nsource, 1/:par4 ,0,'||ln_timeZona||') ';
   ELSIF (parametr = 3) THEN
    lv_grouping2 := lv_grouping1;--' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymmdd'') ';
   ELSIF (parametr = 4) THEN
    lv_grouping2 := lv_grouping1;--' to_char(P.date_time-1/86400- '||ln_timeZona||',''yyyymm'') ';
   END IF;

  ELSE

   IF (parametr=1) THEN
    lv_grouping2 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymmddhh24mi'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'||ln_timeZona||') ';
   ELSIF (parametr=2) THEN
    lv_grouping2 := ' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymmddhh24'')||''.''||uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,nsource),nsource, 1/:par4 ,0,'||ln_timeZona||') ';
   ELSIF (parametr = 3) THEN
    lv_grouping2 := lv_grouping1;--' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''ddmmyyyy'') ';
   ELSIF (parametr = 4) THEN
    lv_grouping2 := lv_grouping1;--' TO_CHAR(util_pg.to_unlocaltime (P.date_time-1/86400- '||ln_timeZona||',nsource),''yyyymm'') ';

   END IF;
 END IF;

  IF ln_dsummer=0 THEN     --если часовой пояс без перехода
  --IF (interior_pg.get_hourtimezone > 0) THEN
   lv_sqltimezone :=
                  ' AND   util_pg.to_unlocaltime (P.date_time, nsource) >= :d_from+1/86400
                    AND   util_pg.to_unlocaltime (P.date_time, nsource) <= :d_till ';
  ELSE
   lv_sqltimezone :=
    ' AND   util_pg.to_unlocaltime (P.date_time, nsource) >= util_pg.to_unlocaltime (:d_from)+1/86400
      AND   util_pg.to_unlocaltime (P.date_time, nsource) <= util_pg.to_unlocaltime (:d_till) ';
  END IF;


  --преведение границ времени
    IF parametr=1   THEN --получасовки
        fact_from:=util_pg.trunc_d(ad_from,1/48)+ interior_pg.get_hourtimezone;
        fact_till:=util_pg.trunc_d(ad_till,1/48)+ interior_pg.get_hourtimezone;

    ELSIF parametr=2 THEN  --часовые
       fact_from:=util_pg.trunc_d(ad_from,1/24)+ interior_pg.get_hourtimezone;
       fact_till:=util_pg.trunc_d(ad_till,1/24)+ interior_pg.get_hourtimezone;

    ELSIF parametr=3 THEN --OR parametr=4 THEN --суточные
       fact_from:=ad_from+ interior_pg.get_hourtimezone;
       fact_till:=ad_till+ interior_pg.get_hourtimezone;

    ELSIF parametr=4 THEN -- месячные
       fact_from:=trunc(ad_from,'MM')+ interior_pg.get_hourtimezone;
       fact_till:=LAST_DAY(ad_till)+ interior_pg.get_hourtimezone;
    END IF;

    dat_from2:=fact_from-interior_pg.get_hourtimezone;
    dat_till2:=fact_till-interior_pg.get_hourtimezone;

     IF parametr=1   THEN --получасовки
     --fact_from:=dat_from2+1/48;
     dat_from2:=dat_from2+1/48;
     ELSIF parametr=2 THEN
     dat_from2:=dat_from2+1/24;
     END IF;

    --raise_application_error(-20001, 'fact_from '||to_char(fact_from,'dd-mon-yyyy hh24:mi') ||'fact_till '||to_char(fact_till,'dd-mon-yyyy hh24:mi'));

    IF parametr=3 OR parametr=4 THEN fact_till:=fact_till+1;   --только для вывода посуточных и помесячных
    END IF;

    temp_date:=dat_from2;
    WHILE (temp_date<=dat_till2) LOOP
       day_switch:=temp_date;
       is_day_switch:=util_pg.is_dayswitch(temp_date);
       EXIT WHEN util_pg.is_dayswitch(temp_date) <> 0;
       temp_date:=temp_date+1;
    END LOOP;

 IF ln_dsummer<>0 THEN     --если часовой пояс с переходом

  IF parametr=1 THEN
        IF  ln_timeZona=0 THEN              --Украина
            str3:='0329';
            str4:='0359';
        ELSIF   ln_timeZona=-1/24   THEN    --Россия
            str3:='0429';
            str4:='0459';
        ELSIF   ln_timeZona=1/24    THEN    --Европа
            str3:='0229';
            str4:='0259';
        END IF;
    ELSE
        IF  ln_timeZona=0 THEN              --Украина
            str_timeswitch1:='03';
            str_timeswitch2:='0401';
        ELSIF   ln_timeZona=-1/24    THEN   --Россия
            str_timeswitch1:='04';
            str_timeswitch2:='0501';
        ELSIF   ln_timeZona=1/24     THEN   --Европа
            str_timeswitch1:='02';
            str_timeswitch2:='0301';
        END IF;
    END IF;

    END IF;


    --подзапрос для выбора всех дат
  IF (parametr=1) THEN
  IF ln_dsummer<>0 THEN     --если часовой пояс с переходом
        lv_seldate:= ' SELECT q.title1 BGroup FROM
            (SELECT title1 FROM(SELECT TO_CHAR(:fact_from+(ROWNUM-1)/48-1/86400, ''yyyymmddhh24mi'') title1
            FROM dual CONNECT BY :fact_from+(ROWNUM-1)/48-1/86400 <= :fact_till))q
            WHERE q.title1 NOT IN
            (SELECT qq.title1 FROM(
            SELECT DISTINCT decode((util_pg.is_dayswitch(:fact_from+(ROWNUM-1)/48-1/86400)), 1,
            to_char(:fact_from+(ROWNUM-1)/48-1/86400, ''yyyymmdd'')||:str3, NULL) title1
            FROM dual CONNECT BY :fact_from+(ROWNUM-1)/48-1/86400 <= :fact_till
            UNION ALL
            SELECT DISTINCT decode((util_pg.is_dayswitch(:fact_from+(ROWNUM-1)/48-1/86400)), 1,
            to_char(:fact_from+(ROWNUM-1)/48-1/86400, ''yyyymmdd'')||:str4, NULL) title1
            FROM dual CONNECT BY :fact_from+(ROWNUM-1)/48-1/86400 <=
            :fact_till)qq WHERE qq.title1 IS NOT NULL)
            UNION ALL
            SELECT qq.title1 FROM(
            SELECT DISTINCT decode((util_pg.is_dayswitch(:fact_from+(ROWNUM-1)/48-1/86400)), -1,
            to_char(:fact_from+(ROWNUM-1)/48-1/86400, ''yyyymmdd'')||:str3, NULL) title1 FROM dual
            CONNECT BY :fact_from+(ROWNUM-1)/48-1/86400 <= :fact_till
            UNION ALL
            SELECT DISTINCT decode((util_pg.is_dayswitch(:fact_from+(ROWNUM-1)/48-1/86400)), -1,
            to_char(:fact_from+(ROWNUM-1)/48-1/86400, ''yyyymmdd'')||:str4, NULL) title1
            FROM dual CONNECT BY :fact_from+(ROWNUM-1)/48-1/86400 <=
            :fact_till)qq WHERE qq.title1 IS NOT NULL ORDER BY 1';

        ELSE
        lv_seldate:='SELECT TO_CHAR(:d_from2+(ROWNUM-1)/48-1/86400,''yyyymmddhh24mi'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/48<= :d_till2';
  END IF;

  ELSIF (parametr=2) THEN
  IF ln_dsummer<>0 THEN     --если часовой пояс с переходом
    IF is_day_switch=1 THEN
        lv_seldate:='SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2
                MINUS
                SELECT TO_CHAR(:day_switch, ''yyyymmdd'')||:tsw1 BGroup FROM DUAL';
    ELSE
        lv_seldate:='SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2';
    END IF;
  ELSE
    lv_seldate:='SELECT TO_CHAR(:d_from2+(ROWNUM-1)/24-1/86400,''yyyymmddhh24'') BGroup
                FROM DUAL  CONNECT BY :d_from2+(ROWNUM-1)/24<= :d_till2';
  END IF;

  ELSIF (parametr=3) THEN   ---   -1/86400
    lv_seldate:='SELECT TO_CHAR(:d_from2+ROWNUM-1,''yyyymmdd'') BGroup
                FROM DUAL  CONNECT BY :d_from2+ROWNUM-1<= :d_till2';

  ELSIF (parametr=4) THEN
    lv_seldate:='SELECT TO_CHAR(ADD_MONTHS(:ad_from2, ROWNUM-1), ''yyyymm'') BGroup
                FROM DUAL  CONNECT BY ADD_MONTHS (:d_from2,(ROWNUM-1))<= :d_till2';

  END IF;

    ------------------


    ------------------
    --построение динамического запроса
    lv_sql:='SELECT distinct b.BGroup, a.er, a.ed, a.sldA, a.q1, a.q3, a.sldR, a.vqm from

    (SELECT ' || lv_grouping1 || ' BGroup,
    --Актив
        SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 er,
        SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 ed,
        SUM (util_pg.sld (P.mid, P.er * DECODE (g.npartly, 2, 0, 1),P.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,''y'', -1,1))/1000 sldA,
    --Реактив
        SUM (DECODE (g.inverted, ''y'', (nvl(P.q3,0)+nvl(P.q4,0)) * DECODE (g.npartly, 1, 0, 1), (nvl(P.q1,0)+nvl(P.q2,0)) * DECODE (g.npartly, 2, 0, 1)))/1000 q1,
        SUM (DECODE (g.inverted, ''y'', (nvl(P.q1,0)+nvl(P.q2,0)) * DECODE (g.npartly, 2, 0, 1), (nvl(P.q3,0)+nvl(P.q4,0)) * DECODE (g.npartly, 1, 0, 1)))/1000 q3,
        SUM (util_pg.sld (P.mid, (nvl(P.q1,0)+nvl(P.q2,0)) * DECODE (g.npartly, 2, 0, 1),(nvl(P.q3,0)+nvl(P.q4,0)) * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,''y'', -1,1))/1000 sldR,
        sumqm (P.vqm) vqm
        FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                                    WHERE mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :an_id
                               UNION ALL
                               SELECT gid FROM GROUPS WHERE gid=:an_id) AND g.mid = P.mid AND P.date_time>= (:d_from - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
     AND   date_time <=(:d_till + DECODE(interior_pg.get_hourtimezone,0,0,3/24)) '
                               ||lv_sqltimezone
                               ||' group by (' || lv_grouping2 || '))a,

     ('||lv_seldate||') b

       WHERE b.BGroup=a.BGroup(+) ORDER BY 1';

       IF (parametr=1) THEN
        IF ln_dsummer<>0 THEN     --если часовой пояс с переходом
               OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2,dat_from2,dat_from2,
               str3, dat_from2, dat_till2,
            dat_from2,dat_from2,str4,dat_from2,dat_till2,
            dat_from2, dat_from2, str3, dat_from2, dat_till2,
            dat_from2, dat_from2,str4,
            dat_from2,
            dat_till2;


            ELSE
                OPEN cur_t FOR lv_sql USING 48, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 48, dat_from2, dat_from2, dat_till2;
        END IF;

       ELSIF (parametr=2) THEN
        IF ln_dsummer<>0 THEN     --если часовой пояс с переходом
            IF is_day_switch=1  THEN
                OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from,fact_till, fact_from,fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch, str_timeswitch1;
            ELSE
                OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from,fact_till, fact_from,fact_till, 24, dat_from2, dat_from2, dat_till2;
            END IF;
        ELSE
            IF is_day_switch=-1  THEN
               OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2, day_switch;

            ELSE
               OPEN cur_t FOR lv_sql USING 24, an_id, an_id, fact_from, fact_till, fact_from, fact_till, 24, dat_from2, dat_from2, dat_till2;
            END IF;
        END IF;

       ELSE
                          OPEN cur_t FOR lv_sql USING an_id, an_id, fact_from,fact_till, fact_from,fact_till,dat_from2, dat_from2, dat_till2; -- fact_from, fact_from, fact_till;
       END IF;

     -- raise_application_error(-20001,an_id||'    '||TO_CHAR(fact_from, 'dd-mm-yyyy hh24:mi')||'   '||TO_CHAR(fact_till, 'dd-mm-yyyy hh24:mi')||'    '||TO_CHAR(dat_from2, 'dd-mm-yyyy hh24:mi')||'    '|| TO_CHAR(dat_till2, 'dd-mm-yyyy hh24:mi'));
      LOOP
        FETCH cur_t INTO ln_1, ln_2, ln_3, ln_4, ln_5, ln_6, ln_7, lv_8;
        EXIT WHEN cur_t%NOTFOUND;
            data_t(ndx+1):=ln_2;
            data_t(ndx+2):=ln_3;
            data_t(ndx+3):=ln_4;
            data_t(ndx+4):=ln_5;
            data_t(ndx+5):=ln_6;
            data_t(ndx+6):=ln_7;
            quantity:=qm_pg.sumqm(quantity,lv_8);
            FOR i IN 1..6 LOOP
            temp_summ (i) :=util_pg.sumn(temp_summ(i),data_t(ndx+i));
            END LOOP;
            ndx:=ndx+6;
     END LOOP;

    -- raise_application_error(-20001,data_t.count);
     FOR i IN 1..6 LOOP
     data_t(data_t.count+1):=temp_summ(i);
    END LOOP;
--raise_application_error(-20001,data_t.count);
 END;*/
 PROCEDURE proc_info_36(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
 an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 6;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT 0 ID, 'Дата включения присоединения на ОВ' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock,
          95 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Дата отключения присоединения на работу через ОВ' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal,
          1 nlock, 95 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Название ОВ' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 3 ID, 'Название точки учета, которую переводили на ОВ' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal,
          1 nlock, 150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 4 ID, 'Дата ввода операции/Пользователь' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock,
          150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 5 ID, 'Дата вывода операции/Пользователь' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock,
          150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 6 ID, 'Начальные показания ОВ' title1, 'А+' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 7 ID, 'Начальные показания ОВ' title1, 'А-' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 8 ID, 'Начальные показания ОВ' title1, 'R+' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 9 ID, 'Начальные показания ОВ' title1, 'R-' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 10 ID, 'Конечные показания ОВ' title1, 'А+' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 11 ID, 'Конечные показания ОВ' title1, 'А-' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '#0.000' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 12 ID, 'Конечные показания ОВ' title1, 'R+' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 13 ID, 'Конечные показания ОВ' title1, 'R-' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT ID, title1, title2, title3, title4, title5, title6, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   (SELECT   ROWNUM ID, s.ID idd, NVL(TO_CHAR(s.dswitch, 'DD.MM.YYYY HH24:MI'), '') title1, NVL(TO_CHAR(s.descape, 'DD.MM.YYYY HH24:MI'), '') title2,
                    s.nswitch, NVL2(p.PARENT, pp.NAME || '/', '') || p.NAME title3, s.mid, z.NAME title4,
                    TO_CHAR(s.denter, 'DD.MM.YYYY HH24:MI') || NVL2(s.denter, '/', '') || NVL2(s.denter, NVL(uu.NAME, 'Система'), '') title5, s.user_id,
                    TO_CHAR(s.denterret, 'DD.MM.YYYY HH24:MI') || NVL2(s.denterret, '/', '') || NVL2(s.denterret, NVL(u.NAME, 'Система'), '') title6,
                    s.user_idret
           FROM     switches s, points p, points z, users u, users uu, points pp
           WHERE    s.mid IN(SELECT     mid
                             FROM       points
                             WHERE      mid IS NOT NULL
                             CONNECT BY PRIOR mid = PARENT
                             START WITH mid = an_id
                             UNION ALL
                             SELECT mid
                             FROM   points
                             WHERE  mid = an_id) AND(s.dswitch BETWEEN ad_from AND ad_till OR s.descape BETWEEN ad_from AND ad_till) AND s.nswitch = p.mid
                    AND s.mid = z.mid AND s.user_idret = u.user_id(+) AND s.user_id = uu.user_id(+) AND p.PARENT = pp.mid
           ORDER BY s.ID);
 END;

