 PROCEDURE proc_value_36(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  cur_t               common_pg.tcur;
  ndx                 NUMBER DEFAULT 0;
  ln_1                NUMBER;
  ln_2                NUMBER;
  ln_3                NUMBER;
  ln_4                NUMBER;
  ln_5                NUMBER;
  ln_6                NUMBER;
  ln_7                NUMBER;
  ln_8                NUMBER;
 BEGIN
  OPEN cur_t FOR
   SELECT a1_prm, a1_otd, r1_prm, r1_otd, a2_prm, a2_otd, r2_prm, r2_otd
   FROM   (SELECT   s.ID, s.dswitch, s.descape, s.mid, NVL(s.erm, '') a1_prm, NVL(s.edm, '') a1_otd, NVL(util_pg.sumn(s.q1m, s.q2m), '') r1_prm,
                    NVL(util_pg.sumn(s.q3m, s.q4m), '') r1_otd, NVL(s.erme, '') a2_prm, NVL(s.edme, '') a2_otd, NVL(util_pg.sumn(s.q1me, s.q2me), '') r2_prm,
                    NVL(util_pg.sumn(s.q3me, s.q4me), '') r2_otd
           FROM     switches s
           WHERE    s.mid IN(SELECT     mid
                             FROM       points
                             WHERE      mid IS NOT NULL
                             CONNECT BY PRIOR mid = PARENT
                             START WITH mid = an_id
                             UNION ALL
                             SELECT mid
                             FROM   points
                             WHERE  mid = an_id) AND(s.dswitch BETWEEN ad_from AND ad_till OR s.descape BETWEEN ad_from AND ad_till)
           ORDER BY s.ID);

  LOOP
   FETCH cur_t
   INTO  ln_1, ln_2, ln_3, ln_4, ln_5, ln_6, ln_7, ln_8;

   EXIT WHEN cur_t%NOTFOUND;
   data_t(ndx + 1) := NVL(ln_1, '');
   data_t(ndx + 2) := NVL(ln_2, '');
   data_t(ndx + 3) := NVL(ln_3, '');
   data_t(ndx + 4) := NVL(ln_4, '');
   data_t(ndx + 5) := NVL(ln_5, '');
   data_t(ndx + 6) := NVL(ln_6, '');
   data_t(ndx + 7) := NVL(ln_7, '');
   data_t(ndx + 8) := NVL(ln_8, '');
   ndx := ndx + 8;
  END LOOP;
 END;

--------------------------------------------------------------------------------
 FUNCTION getmaketgrafvalue22(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_col NUMBER, an_row NUMBER, av_title OUT VARCHAR2, av_xtitle OUT VARCHAR2,
 av_ytitle OUT VARCHAR2, x_t OUT common_pg.tt_number, y_t OUT common_pg.tt_number, an_cid NUMBER
 )
  RETURN NUMBER IS
  an_gid              NUMBER;
  an_str              NUMBER;
  sql_qr              VARCHAR2(2000);
  cur_t               common_pg.tcur;
  ln1                 VARCHAR2(10);
  ln2                 NUMBER;
  i                   NUMBER;
  is_day_switch       NUMBER;                                                                                         --0 - нет перехода, 1 - весна, -1 - осень
  lv_grouping1        VARCHAR2(1000);                                                                                                     --по чем группировать
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  lv_sqltimezone      VARCHAR2(2000);                                                                                              --выбор временного интервала
  an_add              NUMBER;
--здесь будет храниться час перехода по текущей зоне (она нужна, если переход есть)
  lv_seldate          VARCHAR2(1000);                                                                                      --подзапрос выбирает все нужные даты
  lv_sql_x            VARCHAR2(1000);
  ln_timezona         NUMBER DEFAULT interior_pg.get_hourtimezone;
 --0 - Украина, -1/24- Россия, 1/24 - Европа
 BEGIN
  i := 1;

  SELECT MAX(gid), MAX(r)
  INTO   an_gid, an_str
  FROM   (SELECT g.gid * 10 + t.r ID, g.gid gid, t.r r
          FROM   (SELECT 0 sm, gid, 0 prm, NAME
                  FROM   GROUPS
                  WHERE  gid = an_id
                  UNION ALL
                  SELECT 1 sm, gid, NVL(util_pg.allnumber_f(util_pg.get_param(vparam, 1, ';')), 1) prm, NAME
                  FROM   GROUPS
                  WHERE  PARENT = an_id) g,
                 (SELECT ROWNUM r
                  FROM   dict
                  WHERE  ROWNUM <= 8) t)
  WHERE  ID = an_col;

  SELECT    MAX(NAME)
         || ' "'
         || DECODE(
             an_str,
             1, 'счетчик прием',
             2, 'ОИК прием',
             3, 'небаланс (прием)',
             5, 'счетчик отдача',
             6, 'ОИК отдача',
             7, 'небаланс (отдача)',
             4, '% небаланс (прием)',
             '% небаланс (отдача)'
            )
         || '" '
         || TO_CHAR(ad_from, 'dd.mm.yyyy')
  INTO   av_title
  FROM   GROUPS
  WHERE  gid = an_gid;

  av_xtitle := 'Час.';
  av_ytitle := 'тКВтч.';
  --заполнение значений Y-ов
  is_day_switch := util_pg.is_dayswitch(ad_from);

  --является ли день днем перехода

  ----to_unlocaltime только для поясов без перехода
  --группировка
  IF ln_dsummer <> 0 THEN                                                                                                        --если часовой пояс с переходом
   lv_grouping1 := ' to_char(uniinterior1_pg.get_num (P.date_time-1/86400,P.nsource, 1/24 ,0,' || ln_timezona || '))';
  ELSE
   lv_grouping1 := ' to_char(uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time-1/86400,P.nsource),P.nsource, 1/24 ,0,' || ln_timezona || '))';
  END IF;

  IF ln_dsummer = 0 THEN                                                                                                        --если часовой пояс без перехода
   lv_sqltimezone :=
       ' AND  P.date_time> trunc(:ad_from) + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24)
                    AND   P.date_time <=trunc(:ad_from)+1 + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24)
              AND util_pg.to_unlocaltime (P.date_time, P.nsource) > trunc(:ad_from)+ '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, P.nsource) <= trunc(:ad_from)+1+'
    || ln_timezona
    || ' ';
  ELSE
   lv_sqltimezone := ' AND   P.date_time > trunc(:ad_from)+ ' || ln_timezona || ' 
      AND   P.date_time <= trunc(:ad_from)+1+' || ln_timezona || ' ';
  END IF;

  IF ln_dsummer <> 0 AND is_day_switch <> 0
                                           --только если переход происходит и происходит в текущий день
  THEN
   SELECT DECODE(ln_timezona, 0, 4, 1 / 24, 5, -1 / 24, 3)
   INTO   an_add
   FROM   DUAL;
  END IF;

  --построение запроса для вывода таблицы со всеми датами
  IF ln_dsummer <> 0 AND is_day_switch = 1                                                                         --переход должен быть и день перехода на лето
                                          THEN
   lv_seldate := ' (SELECT (case when rownum<10 THEN ''0''||rownum else  to_char(rownum) end) h FROM dict WHERE rownum <= 23)';
  ELSIF ln_dsummer <> 0 AND is_day_switch = -1
                                              --переход должен быть и день перехода на зиму
  THEN
   lv_seldate := ' (SELECT (case when rownum<10 THEN ''0''||rownum else  to_char(rownum) end) h FROM dict WHERE rownum <= 25)';
  ELSE                                                                                                                --обычный день или перехода не должно быть
   lv_seldate := ' (SELECT (case when rownum<10 THEN ''0''||rownum else  to_char(rownum) end) h FROM dict WHERE rownum <= 24)';
  END IF;

  --построение динамического запроса
  IF an_str = 1 THEN                                                                                                                             --счетчик прием
   sql_qr :=
       'SELECT b.h h, a.er er FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 er
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lcgid) AND g.mid = P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ') a, 
     '
    || lv_seldate
    || 'b WHERE  b.h=a.h(+) ORDER BY 1';
  ELSIF an_str = 2 THEN                                                                                                                              --ОИК прием
   sql_qr :=
       'SELECT bb.h h, aa.oiker oiker FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 oiker
    FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :lcgid) AND UNIINTERIOR1_PG.get_oik_mid(g.mid,:an_cid)=P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ')aa,
     '
    || lv_seldate
    || 'bb WHERE  bb.h=aa.h(+) ORDER BY 1';
  ELSIF an_str = 3 THEN                                                                                                                       --небаланс (прием)
   sql_qr :=
       'SELECT t.h, t.er-t1.oiker nebal
             FROM
    (SELECT b.h, a.er FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 er
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lcgid) AND g.mid = P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ') a, 
     '
    || lv_seldate
    || 'b WHERE  b.h=a.h(+) ORDER BY 1)t,
     
    (SELECT bb.h, aa.oiker FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 oiker
    FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :lcgid) AND UNIINTERIOR1_PG.get_oik_mid(g.mid,:an_cid)=P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ')aa,
     '
    || lv_seldate
    || 'bb WHERE  bb.h=aa.h(+) ORDER BY 1 )t1 WHERE t.h=t1.h';
  ELSIF an_str = 4 THEN                                                                                                                     --% небаланс (прием)
   sql_qr :=
       'SELECT t.h, decode(t.er,0,0,(t.er-t1.oiker)*100/t.er) nebal
             FROM
    (SELECT b.h, a.er FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 er
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lcgid) AND g.mid = P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ') a, 
     '
    || lv_seldate
    || 'b WHERE  b.h=a.h(+) ORDER BY 1)t,
     
    (SELECT bb.h, aa.oiker FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000 oiker
    FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :lcgid) AND UNIINTERIOR1_PG.get_oik_mid(g.mid,:an_cid)=P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ')aa,
     '
    || lv_seldate
    || 'bb WHERE  bb.h=aa.h(+) ORDER BY 1 )t1 WHERE t.h=t1.h';
  ELSIF an_str = 5 THEN                                                                                                                         --счетчик отдача
   sql_qr :=
       'SELECT b.h h, a.ed ed FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 ed
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lcgid) AND g.mid = P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ') a, 
     '
    || lv_seldate
    || 'b WHERE  b.h=a.h(+) ORDER BY 1';
  ELSIF an_str = 6 THEN                                                                                                                             --ОИК отдача
   sql_qr :=
       'SELECT bb.h h, aa.oiked oiked FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 oiked
    FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :lcgid) AND UNIINTERIOR1_PG.get_oik_mid(g.mid,:an_cid)=P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ')aa,
     '
    || lv_seldate
    || 'bb WHERE  bb.h=aa.h(+) ORDER BY 1';
  ELSIF an_str = 7 THEN                                                                                                                        --небаланс отдача
   sql_qr :=
       'SELECT t.h, t.ed-t1.oiked nebal
             FROM
    (SELECT b.h, a.ed FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 ed
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lcgid) AND g.mid = P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ') a, 
     '
    || lv_seldate
    || 'b WHERE  b.h=a.h(+) ORDER BY 1)t,
     
    (SELECT bb.h, aa.oiked FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 oiked
    FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :lcgid) AND UNIINTERIOR1_PG.get_oik_mid(g.mid,:an_cid)=P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ')aa,
     '
    || lv_seldate
    || 'bb WHERE  bb.h=aa.h(+) ORDER BY 1 )t1 WHERE t.h=t1.h';
  ELSE                                                                                                                                       --% небаланс отдача
   sql_qr :=
       'SELECT t.h, decode(t.ed,0,0,(t.ed-t1.oiked)*100/t.ed) nebal
             FROM
    (SELECT b.h, a.ed FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 ed
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lcgid) AND g.mid = P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ') a, 
     '
    || lv_seldate
    || 'b WHERE  b.h=a.h(+) ORDER BY 1)t,
     
    (SELECT bb.h, aa.oiked FROM (SELECT '
    || lv_grouping1
    || ' h, 
    SUM (DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000 oiked
    FROM halfhour P, GROUPS g
               WHERE g.gid IN (SELECT     gid
                                     FROM GROUPS
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = :lcgid) AND UNIINTERIOR1_PG.get_oik_mid(g.mid,:an_cid)=P.mid'
    || lv_sqltimezone
    || ' GROUP BY'
    || lv_grouping1
    || ')aa,
     '
    || lv_seldate
    || 'bb WHERE  bb.h=aa.h(+) ORDER BY 1 )t1 WHERE t.h=t1.h';
  END IF;

  IF an_str = 1 OR an_str = 5 THEN
   IF ln_dsummer <> 0 THEN
    OPEN cur_t FOR sql_qr USING an_gid, ad_from, ad_from;
   ELSE
    OPEN cur_t FOR sql_qr USING an_gid, ad_from, ad_from, ad_from, ad_from;
   END IF;
  ELSIF an_str = 2 OR an_str = 6 THEN
   IF ln_dsummer <> 0 THEN
    OPEN cur_t FOR sql_qr USING an_gid, an_cid, ad_from, ad_from;
   ELSE
    OPEN cur_t FOR sql_qr USING an_gid, an_cid, ad_from, ad_from, ad_from, ad_from;
   END IF;
  ELSE                                                                                                                                              /* 3,4,7,8*/
   IF ln_dsummer <> 0 THEN
    OPEN cur_t FOR sql_qr USING an_gid, ad_from, ad_from, an_gid, an_cid, ad_from, ad_from;
   ELSE
    OPEN cur_t FOR sql_qr USING an_gid, ad_from, ad_from, ad_from, ad_from, an_gid, an_cid, ad_from, ad_from, ad_from, ad_from;
   END IF;
  END IF;

  LOOP
   FETCH cur_t
   INTO  ln1, ln2;

   EXIT WHEN cur_t%NOTFOUND;
   --x_t(i) :=ln1+1;
   y_t(i) := ln2;
   i := i + 1;
  END LOOP;

--заполнение значений Х-ов
  i := 1;
  ln1 := NULL;

  CLOSE cur_t;

  IF ln_dsummer <> 0 AND is_day_switch = 1                                                                         --переход должен быть и день перехода на лето
                                          THEN
   lv_sql_x :=
    '
        SELECT h FROM 
        (SELECT ROWNUM h FROM dict WHERE ROWNUM <= 24
         MINUS
         SELECT :an_add h FROM DUAL
         ORDER BY 1)';
  ELSIF ln_dsummer <> 0 AND is_day_switch = -1
                                              --переход должен быть и день перехода на зиму
  THEN
   lv_sql_x :=
    '
        SELECT h FROM 
        (SELECT ROWNUM h FROM dict WHERE ROWNUM <= 24
         UNION ALL
         SELECT :an_add h FROM DUAL
         ORDER BY 1)';
  ELSE                                                                                                                --обычный день или перехода не должно быть
   lv_sql_x := '
        SELECT ROWNUM h FROM dict WHERE ROWNUM <= 24';
  END IF;

  IF ln_dsummer <> 0 AND is_day_switch <> 0                                                                        --переход должен быть и день перехода на лето
                                           THEN
   OPEN cur_t FOR lv_sql_x USING an_add;
  ELSE
   OPEN cur_t FOR lv_sql_x;
  END IF;

  LOOP
   FETCH cur_t
   INTO  ln1;

   EXIT WHEN cur_t%NOTFOUND;
   x_t(i) := ln1;
   i := i + 1;
  END LOOP;

  --raise_application_error(-20001,x_t(24)||' '||y_t(24));
  CLOSE cur_t;

  RETURN y_t.COUNT;
 END;

--------------------------------------------------------------------------------
--отчет для сверки счетчиков с оик
 PROCEDURE proc_info_22(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER,
 an_cnfooter IN OUT NUMBER, col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  is_day_switch       NUMBER;                                                                                         --0 - нет перехода, 1 - весна, -1 - осень
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  ln_timezona         NUMBER DEFAULT interior_pg.get_hourtimezone;
  --0 - Украина, -1/24- Россия, 1/24 - Европа
  an_add              NUMBER;
--здесь будет храниться час перехода по текущей зоне (она нужна, если переход есть)
 BEGIN
  an_cnfixcol := 1;
  an_cntitle := 2;
  an_cnfooter := 0;
  --ln_timezona := interior_pg.get_hourtimezone;
  --ln_dsummer := interior_pg.get_dsummer;
  is_day_switch := util_pg.is_dayswitch(ad_from);

  --является ли день днем перехода
  OPEN col_t FOR
   SELECT 0 ID, ' ' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT z.*
   FROM   (SELECT   g.gid * 10 + t.r ID, g.NAME title1,
                    DECODE(t.r, 1, 'счетчик прием', 2, 'ОИК прием', 3, 'небаланс', 5, 'счетчик отдача', 6, 'ОИК отдача', 7, 'небаланс', '% небаланс') title2,
                    cn_btnface titlecl, cn_left titleal, g.datacl, cn_left dataal, 1 nlock, 70 nwidth, '#0.000' vmasks
           FROM     (SELECT 0 sm, gid, 0 prm, NAME, cn_yellow datacl
                     FROM   GROUPS
                     WHERE  gid = an_id
                     UNION ALL
                     SELECT 1 sm, gid, NVL(util_pg.allnumber_f(util_pg.get_param(vparam, 1, ';')), 1) prm, NAME, cn_white datacl
                     FROM   GROUPS
                     WHERE  PARENT = an_id) g,
                    (SELECT ROWNUM r
                     FROM   dict
                     WHERE  ROWNUM <= 8) t
           ORDER BY g.sm, g.prm, g.NAME, g.gid, t.r) z;

  IF ln_dsummer <> 0 AND is_day_switch <> 0
                                           --только если переход происходит и происходит в текущий день
  THEN
   SELECT DECODE(ln_timezona, 0, 4, 1 / 24, 5, -1 / 24, 3)
   INTO   an_add
   FROM   DUAL;
  END IF;

  IF ln_dsummer <> 0 AND is_day_switch = 1                                                                         --переход должен быть и день перехода на лето
                                          THEN
   OPEN row_t FOR
    SELECT 0 ID, TO_CHAR(TRUNC(ad_from), 'DD.MM.YYYY') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL
    UNION ALL
    SELECT ROWNUM ID, t.title1 title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   (SELECT   ROWNUM r, TO_CHAR((TRUNC(ad_from) + ROWNUM / 24), 'HH24:MI') title1
            FROM     dict
            WHERE    ROWNUM <= 24
            MINUS
            SELECT   an_add r, TO_CHAR((TRUNC(ad_from) + an_add / 24), 'HH24:MI') title1
            FROM     DUAL
            ORDER BY 1) t;
  ELSIF ln_dsummer <> 0 AND is_day_switch = -1
                                              --переход должен быть и день перехода на зиму
  THEN
   OPEN row_t FOR
    SELECT 0 ID, TO_CHAR(TRUNC(ad_from), 'DD.MM.YYYY') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL
    UNION ALL
    SELECT ROWNUM ID, t.title1 title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   (SELECT   ROWNUM r, TO_CHAR((TRUNC(ad_from) + ROWNUM / 24), 'HH24:MI') title1
            FROM     dict
            WHERE    ROWNUM <= 24
            UNION ALL
            SELECT   an_add r, TO_CHAR((TRUNC(ad_from) + an_add / 24), 'HH24:MI') title1
            FROM     DUAL
            ORDER BY 1) t;
  ELSE                                                                                                                --обычный день или перехода не должно быть
   OPEN row_t FOR
    SELECT 0 ID, TO_CHAR(TRUNC(ad_from), 'DD.MM.YYYY') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   DUAL
    UNION ALL
    SELECT ROWNUM ID, TO_CHAR((TRUNC(ad_from) + ROWNUM / 24), 'HH24:MI') title1, cn_white datacl, 1 nlock, '' vmasks, 1000000000 srt
    FROM   dict
    WHERE  ROWNUM <= 24;
  END IF;
 END;

--------------------------------------------------------------------------------
 PROCEDURE proc_value_22(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, an_cid NUMBER) IS
  cur_i               NUMBER;
  cnt                 NUMBER;
  cur_i_forsum        NUMBER;
  lv_grouping1        VARCHAR2(1000);                                                                                                     --по чем группировать
  is_day_switch       NUMBER;                                                                                         --0 - нет перехода, 1 - весна, -1 - осень
  ln_dsummer          NUMBER DEFAULT interior_pg.get_dsummer;
  --переход на лето. 0 - нет, 1 - да
  ln_timezona         NUMBER DEFAULT interior_pg.get_hourtimezone;
  --0 - Украина, -1/24- Россия, 1/24 - Европа
  lv_sqltimezone      VARCHAR2(2000);                                                                                              --выбор временного интервала
  lv_seldate          VARCHAR2(1000);                                                                                      --подзапрос выбирает все нужные даты
  an_add              NUMBER;
--здесь будет храниться час перехода по текущей зоне (она нужна, если переход есть)
  lv_sql              VARCHAR2(4000);                                                                                                    --для главного запроса
  cur_t               common_pg.tcur;
  hours               common_pg.tt_number;                                                                                             --массив со всеми часами
  a1                  common_pg.tt_number;
  a2                  common_pg.tt_number;
  a3                  common_pg.tt_varchar2;
  sums                common_pg.tt_number;
  ii                  NUMBER;
  --  lnstart          NUMBER;
  tmp                 NUMBER DEFAULT NULL;
 BEGIN
  hours.DELETE;
  sums.DELETE;
  a1.DELETE;
  a2.DELETE;
  a3.DELETE;
  ii := 1;
  is_day_switch := util_pg.is_dayswitch(ad_from);
  tmp := NULL;

                                         --является ли день днем перехода
  --lnstart := 0;

  ----to_unlocaltime только для поясов без перехода
  --группировка
  IF ln_dsummer <> 0 THEN                                                                                                       --если часовой пояс с переходом
   lv_grouping1 := ' to_char(uniinterior1_pg.get_num (P.date_time - 1 / 86400,P.nsource, 1 / 24, 0,' || ln_timezona || '))';
   lv_sqltimezone :=
             ' AND   P.date_time > trunc(:ad_from) + ' || ln_timezona || ' 
                AND   P.date_time <= trunc(:ad_from) + 1 + ' || ln_timezona || ' ';
  ELSE
   lv_grouping1 := ' to_char(uniinterior1_pg.get_num (util_pg.to_unlocaltime (P.date_time - 1 / 86400,P.nsource),P.nsource, 1 / 24, 0,' || ln_timezona || '))';
   lv_sqltimezone :=
       ' AND  P.date_time > trunc(:ad_from) + '
    || ln_timezona
    || ' - DECODE('
    || ln_timezona
    || ',0,0,3/24)
                    AND   P.date_time <= trunc(:ad_from) + 1 + '
    || ln_timezona
    || ' + DECODE('
    || ln_timezona
    || ',0,0,3/24)
              AND util_pg.to_unlocaltime (P.date_time, P.nsource) > trunc(:ad_from) + '
    || ln_timezona
    || '
                    AND   util_pg.to_unlocaltime (P.date_time, P.nsource) <= trunc(:ad_from) + 1 + '
    || ln_timezona
    || ' ';
  END IF;

  IF ln_dsummer <> 0 AND is_day_switch <> 0
                                           --только если переход происходит и происходит в текущий день
  THEN
   SELECT DECODE(ln_timezona, 0, 4, 1 / 24, 5, -1 / 24, 3)
   INTO   an_add
   FROM   DUAL;
  END IF;

  --построение запроса для вывода таблицы со всеми датами
  IF ln_dsummer <> 0 AND is_day_switch = 1                                                                         --переход должен быть и день перехода на лето
                                          THEN
   lv_seldate := ' (SELECT (case when rownum < 10 THEN ''0''||rownum else  to_char(rownum) end) h FROM dict WHERE rownum <= 23)';

   FOR i IN 1 .. 23 LOOP
    hours(i) := i;
   END LOOP;
  ELSIF ln_dsummer <> 0 AND is_day_switch = -1
                                              --переход должен быть и день перехода на зиму
  THEN
   lv_seldate := ' (SELECT (case when rownum < 10 THEN ''0''||rownum else  to_char(rownum) end) h FROM dict WHERE rownum <= 25)';

   FOR i IN 1 .. 25 LOOP
    hours(i) := i;
   END LOOP;
  ELSE                                                                                                                --обычный день или перехода не должно быть
   lv_seldate := ' (SELECT (case when rownum < 10 THEN ''0''||rownum else  to_char(rownum) end) h FROM dict WHERE rownum <= 24)';

   FOR i IN 1 .. 24 LOOP
    hours(i) := i;
   END LOOP;
  END IF;

--'||lv_grouping1||' h,
--строим запрос
  lv_sql :=
      '
            SELECT 
     round(sum(DECODE (g.inverted, ''y'', P.ed * DECODE (g.npartly, 1, 0, 1), P.er * DECODE (g.npartly, 2, 0, 1)))/1000, 3) er,
     round(sum(DECODE (g.inverted, ''y'', P.er * DECODE (g.npartly, 2, 0, 1), P.ed * DECODE (g.npartly, 1, 0, 1)))/1000, 3) ed,
     '
   || lv_grouping1
   || '||decode (p.mid, g.mid, ''A'',''O'') s
    FROM halfhour P, GROUPS g
    WHERE g.gid IN (SELECT gid
    FROM GROUPS
        CONNECT BY PRIOR gid = PARENT
        START WITH gid = :lc_gid ) AND 
        (g.mid = P.mid OR 
        UNIINTERIOR1_PG.get_oik_mid (g.mid, :an_cid) = P.mid
        )'
   || lv_sqltimezone
   || ' group by '
   || lv_grouping1
   || ', decode (p.mid, g.mid, ''A'',''O'') order by 3
';

  SELECT COUNT(*)
  INTO   cnt
  FROM   (SELECT gid
          FROM   GROUPS
          WHERE  gid = an_id
          UNION ALL
          SELECT gid
          FROM   GROUPS
          WHERE  PARENT = an_id);

  FOR i IN 1 .. 8 * cnt * hours.COUNT LOOP
   data_t(i) := NULL;
  END LOOP;

  cur_i := 8 * cnt + 1;
  cur_i_forsum := 1;

  --  cur_i_forsum := 1;
  FOR lc IN (SELECT ROWNUM rt, gid, r, sm
             FROM   (SELECT   gid, 0 sm, 0 r, NAME
                     FROM     GROUPS
                     WHERE    gid = an_id
                     UNION ALL
                     SELECT   gid, 1 sm, NVL(util_pg.allnumber_f(util_pg.get_param(vparam, 1, ';')), 1) r, NAME
                     FROM     GROUPS
                     WHERE    PARENT = an_id
                     --order by 2,3
                     ORDER BY sm, r, NAME, gid)) LOOP
     --      lnstart := 0;
   --  insert into tmp_vil values(lc.gid||' '||an_cid||' '||lv_sql);
   --   commit;
   IF ln_dsummer = 0 THEN
    OPEN cur_t FOR lv_sql USING lc.gid, an_cid, ad_from, ad_from, ad_from, ad_from;
   ELSE
    OPEN cur_t FOR lv_sql USING lc.gid, an_cid, ad_from, ad_from;
   END IF;

   ii := 1;
   a1.DELETE;
   a2.DELETE;
   a3.DELETE;
   sums.DELETE;
   sums(1) := 0;
   sums(2) := 0;
   sums(3) := 0;
   sums(4) := 0;
   sums(5) := 0;
   sums(6) := 0;
   sums(7) := 0;
   sums(8) := 0;
   data_t(cur_i_forsum) := 0;
   data_t(cur_i_forsum + 1) := 0;
   data_t(cur_i_forsum + 2) := 0;
   data_t(cur_i_forsum + 3) := 0;
   data_t(cur_i_forsum + 4) := 0;
   data_t(cur_i_forsum + 5) := 0;
   data_t(cur_i_forsum + 6) := 0;
   data_t(cur_i_forsum + 7) := 0;

   FETCH cur_t
   BULK COLLECT INTO a1, a2, a3;

   FOR i IN 1 .. hours.COUNT LOOP
    data_t(cur_i) := NULL;
    data_t(cur_i + 1) := NULL;
    data_t(cur_i + 2) := NULL;
    data_t(cur_i + 3) := NULL;
    data_t(cur_i + 4) := NULL;
    data_t(cur_i + 5) := NULL;
    data_t(cur_i + 6) := NULL;
    data_t(cur_i + 7) := NULL;

    IF a3.COUNT >= ii THEN
     IF TO_NUMBER(SUBSTR(a3(ii), 1, 2)) = hours(i) THEN
      IF a1.COUNT >= ii THEN
       data_t(cur_i) := a1(ii);
      --sums(1) := util_pg.sumn(sums(1), a1(ii));
      END IF;

      IF a2.COUNT >= ii THEN
       data_t(cur_i + 4) := a2(ii);
      --sums(5) := util_pg.sumn(sums(5), a2(ii));
      END IF;

      ii := ii + 1;
     END IF;
    END IF;

    IF a3.COUNT >= ii THEN
     IF TO_NUMBER(SUBSTR(a3(ii), 1, 2)) = hours(i) THEN
      IF a1.COUNT >= ii THEN
       data_t(cur_i + 1) := a1(ii);
      --sums(2) := util_pg.sumn(sums(2), a1(ii));
      END IF;

      IF a2.COUNT >= ii THEN
       data_t(cur_i + 5) := a2(ii);
      --sums(6) := util_pg.sumn(sums(6), a2(ii));
      END IF;

      ii := ii + 1;
     END IF;
    END IF;

    IF data_t(cur_i) IS NOT NULL AND data_t(cur_i + 1) IS NOT NULL THEN
     data_t(cur_i + 2) := ROUND(data_t(cur_i) - data_t(cur_i + 1), 3);

     SELECT ROUND(DECODE(data_t(cur_i), 0, 0,(data_t(cur_i) - data_t(cur_i + 1)) * 100 / data_t(cur_i)), 3)
     INTO   data_t(cur_i + 3)
     FROM   DUAL;
    END IF;

    IF data_t(cur_i + 4) IS NOT NULL AND data_t(cur_i + 5) IS NOT NULL THEN
     data_t(cur_i + 6) := ROUND(data_t(cur_i + 4) - data_t(cur_i + 5), 3);

     SELECT ROUND(DECODE(data_t(cur_i + 4), 0, 0,(data_t(cur_i + 4) - data_t(cur_i + 5)) * 100 / data_t(cur_i + 4)), 3)
     INTO   data_t(cur_i + 7)
     FROM   DUAL;
    END IF;

    sums(1) := util_pg.sumn(sums(1), data_t(cur_i));
    sums(2) := util_pg.sumn(sums(2), data_t(cur_i + 1));
    -- sums(3) := util_pg.sumn(sums(3), data_t(cur_i+2));
    -- sums(4) := util_pg.sumn(sums(4), data_t(cur_i+3));
    sums(5) := util_pg.sumn(sums(5), data_t(cur_i + 4));
    sums(6) := util_pg.sumn(sums(6), data_t(cur_i + 5));
    -- sums(7) := util_pg.sumn(sums(7), data_t(cur_i+6));
    -- sums(8) := util_pg.sumn(sums(8), data_t(cur_i+7));
    cur_i := 8 * cnt + cur_i;
   END LOOP;

   --raise_application_error(-20001,' 1='||sums(1)||' 2='||sums(2)||' 3='||sums(3)||' 4='||sums(4)||' 5='||sums(5)||' 6='||sums(6)||' 7='||sums(7)||' 8='||sums(8));
   data_t(cur_i_forsum) := 0;
   data_t(cur_i_forsum + 1) := 0;
   data_t(cur_i_forsum + 2) := 0;
   data_t(cur_i_forsum + 3) := 0;
   data_t(cur_i_forsum + 4) := 0;
   data_t(cur_i_forsum + 5) := 0;
   data_t(cur_i_forsum + 6) := 0;
   data_t(cur_i_forsum + 7) := 0;
   data_t(cur_i_forsum) := ROUND(sums(1), 3);
   data_t(cur_i_forsum + 1) := ROUND(sums(2), 3);
   data_t(cur_i_forsum + 2) := ROUND(data_t(cur_i_forsum) - data_t(cur_i_forsum + 1), 3);

   --select decode(data_t(cur_i_forsum),0,0,data_t(cur_i_forsum)-data_t(cur_i_forsum+1)*100/data_t(cur_i_forsum)) into data_t(cur_i_forsum+3) from dual;
   SELECT ROUND(DECODE(sums(1), 0, 0, data_t(cur_i_forsum + 2) * 100 / data_t(cur_i_forsum)), 3)
   INTO   data_t(cur_i_forsum + 3)
   FROM   DUAL;

   data_t(cur_i_forsum + 4) := ROUND(sums(5), 3);
   data_t(cur_i_forsum + 5) := ROUND(sums(6), 3);
   data_t(cur_i_forsum + 6) := ROUND(data_t(cur_i_forsum + 4) - data_t(cur_i_forsum + 5), 3);

   --select decode(data_t(cur_i_forsum+4),0,0,data_t(cur_i_forsum+4)-data_t(cur_i_forsum+5)*100/data_t(cur_i_forsum+4)) into data_t(cur_i_forsum+7) from dual;
   SELECT ROUND(DECODE(sums(5), 0, 0, data_t(cur_i_forsum + 6) * 100 / data_t(cur_i_forsum + 4)), 3)
   INTO   data_t(cur_i_forsum + 7)
   FROM   DUAL;

   cur_i := 8 * lc.rt + 8 * cnt + 1;
   cur_i_forsum := 8 * lc.rt + 1;
  END LOOP;

  CLOSE cur_t;
 END;

