 FUNCTION is_nodataqm(an_id NUMBER, fact_from DATE, fact_till DATE)
  --функция возвращает 1 - если по точке в указанном промежутке отсутствуют данные,
  --0 - если все данные присутствуют
 RETURN NUMBER IS
  ln_ret              NUMBER DEFAULT 0;
  ln_cnt              NUMBER DEFAULT 0;
  all_rows            NUMBER DEFAULT 0;
  is_rows             NUMBER DEFAULT 0;
  is_day_switch       NUMBER DEFAULT 0;
  temp_date           DATE DEFAULT fact_from;
  minutes             NUMBER DEFAULT 30;
 BEGIN
  WHILE(temp_date <= fact_till) LOOP
   is_day_switch := util_pg.is_dayswitch(temp_date);
   EXIT WHEN util_pg.is_dayswitch(temp_date) <> 0;
   temp_date := temp_date + 1;
  END LOOP;

  ---------подсчет требуемого кол-ва строк (для метки качества)
  ln_cnt := ROUND((fact_till - fact_from) * 24, 1);

  --raise_application_error(-20001, ln_1*2);
  SELECT SUM(ln_cnt *(60 / NVL(nintegralperiod, 30)) - 60 / NVL(nintegralperiod, 30) * is_day_switch)
  INTO   all_rows
  FROM   feeders
  WHERE  mid IN(SELECT     p.mid
                FROM       GROUPS p
                WHERE      p.mid IS NOT NULL
                CONNECT BY PRIOR gid = PARENT
                START WITH gid = an_id);

  ---------подсчет имеющегося кол-ва строк (для метки качества)
  ln_cnt := 0;

  FOR lc IN (SELECT DISTINCT p.mid midd
             FROM            GROUPS p
             WHERE           p.mid IS NOT NULL
             CONNECT BY      PRIOR p.gid = p.PARENT
             START WITH      p.gid = an_id) LOOP
   SELECT NVL(f.nintegralperiod, 30)
   INTO   minutes
   FROM   feeders f
   WHERE  f.mid = lc.midd;

   SELECT COUNT(*)
   INTO   ln_cnt
   FROM   (SELECT DISTINCT round_min(p.date_time, minutes), p.nsource
           FROM            halfhour p
           WHERE           p.mid = lc.midd AND p.date_time > fact_from AND p.date_time <= fact_till) ll;

   is_rows := ln_cnt + is_rows;
  END LOOP;

  SELECT DECODE(SIGN(all_rows - is_rows), 1, 1, 0)
  INTO   ln_ret
  FROM   DUAL;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------
 FUNCTION round_min(dt DATE, mn NUMBER)                                          --возвращает последнюю минуту, округленную до mn (f.e. 25:16 --> 25:15 mn = 15,
  -- 25:26 --> 25:15 при mn = 15)
 RETURN DATE IS
  ddt                 DATE DEFAULT dt;
  n                   NUMBER;
 BEGIN
  n := TO_NUMBER(TO_CHAR(dt, 'mi'));

  WHILE n >= mn LOOP
   n := n - mn;
  END LOOP;

  ddt := dt - n / 1440;
  RETURN ddt;
 END;
--------------------------------------------------------------------------------
END;
