 PROCEDURE proc_info_20(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 1;
  an_cntitle := 3;

  SELECT DECODE(ln_locksum, 0, 1, 0)
  INTO   an_cnfooter
  FROM   DUAL;

  OPEN col_t FOR
   SELECT 1 ID, 'Временной интервал' title1, '' title2, '' title3, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_center dataal, 1 nlock,
          100 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT hdr.ID, g.NAME title1, hdr.title2, hdr.title3, hdr.titlecl, hdr.titleal, hdr.datacl, hdr.dataal, hdr.nlock, hdr.nwidth, hdr.vmasks
   FROM   (SELECT 1 ID, '1' title1, 'Актив [тыс.кВтч]' title2, 'прием' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 2 ID, '1' title1, 'Актив [тыс.кВтч]' title2, 'отдача' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 3 ID, '1' title1, 'Актив [тыс.кВтч]' title2, 'сальдо' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 1 ID, '2' title1, 'Актив [тыс.кВтч]' title2, 'прием' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 2 ID, '2' title1, 'Актив [тыс.кВтч]' title2, 'отдача' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 3 ID, '2' title1, 'Актив [тыс.кВтч]' title2, 'сальдо' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 1 ID, '3' title1, 'Актив [тыс.кВтч]' title2, 'прием' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 2 ID, '3' title1, 'Актив [тыс.кВтч]' title2, 'отдача' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 3 ID, '3' title1, 'Актив [тыс.кВтч]' title2, 'сальдо' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 1 ID, '4' title1, 'Актив [тыс.кВтч]' title2, 'прием' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 2 ID, '4' title1, 'Актив [тыс.кВтч]' title2, 'отдача' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 3 ID, '4' title1, 'Актив [тыс.кВтч]' title2, 'сальдо' title3, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock,
                  70 nwidth, '' vmasks
           FROM   DUAL) hdr,
          GROUPS g
   WHERE  g.PARENT = an_id AND util_pg.get_param(g.vparam, 1) = hdr.title1;

  OPEN row_t FOR
   SELECT -1 ID, TO_CHAR(t.dt, 'dd.Mon') title1, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   (SELECT   TRUNC(h.date_time - 1 / 86400) dt
           FROM     halfhour h, ryda.GROUPS g
           WHERE    g.mid = h.mid AND g.gid IN(SELECT     gid
                                               FROM       ryda.GROUPS
                                               CONNECT BY PRIOR gid = PARENT
                                               START WITH gid = an_id) AND h.date_time - 1 / 86400 > ad_from AND h.date_time - 1 / 86400 <= ad_till
           GROUP BY TRUNC(h.date_time - 1 / 86400)
           ORDER BY dt) t
   UNION ALL
   SELECT -1 ID, 'Ночь' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0
   UNION ALL
   SELECT -1 ID, 'День' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0
   UNION ALL
   SELECT -1 ID, 'Пик' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0
   UNION ALL
   SELECT -1 ID, 'Итого:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0;
 END;

