 PROCEDURE proc_value_20(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  ln_par              NUMBER DEFAULT 0;
 BEGIN
  FOR lc IN (SELECT   tmp.pgid, tmp.vpar, TRUNC(tmp.date_time - 1 / 86400) dt, SUM(DECODE(rate, 0, tmp.sld, 0)) asld, SUM(DECODE(rate, 1, tmp.sld, 0)) bsld,
                      SUM(DECODE(rate, 2, tmp.sld, 0)) csld, SUM(DECODE(rate, 3, tmp.sld, 0)) dsld, SUM(tmp.sld) sld
             FROM     (SELECT   gp.gid pgid, gp.vpar, h.date_time,
                                NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))
                                  * DECODE(g.inverted, 'y', -1, 1)),
                                 0) sld
                       FROM     halfhour h,
                                ryda.GROUPS g,
                                (SELECT gid, util_pg.get_param(vparam, 1) vpar
                                 FROM   GROUPS
                                 WHERE  PARENT = an_id) gp
                       WHERE    g.mid = h.mid AND g.gid IN(SELECT     gid
                                                           FROM       ryda.GROUPS
                                                           CONNECT BY PRIOR gid = PARENT
                                                           START WITH gid = an_id) AND h.date_time - 1 / 86400 > ad_from AND h.date_time - 1 / 86400 <= ad_till
                                AND gp.gid = (SELECT     gid
                                              FROM       GROUPS
                                              WHERE      PARENT = an_id
                                              CONNECT BY PRIOR PARENT = gid
                                              START WITH gid = g.gid)
                       GROUP BY gp.gid, gp.vpar, h.date_time
                       ORDER BY pgid, date_time) tmp,
                      rates r
             WHERE    TO_CHAR(tmp.date_time - 1 / 86400, 'sssss') > TO_CHAR(r.TIME, 'sssss')
                      AND TO_CHAR(tmp.date_time - 1 / 86400, 'sssss') <= TO_CHAR(r.endtime, 'sssss')
                      AND r.rid = (SELECT MAX(rid)
                                   FROM   rate_list
                                   WHERE  switch_date = (SELECT MAX(switch_date)
                                                         FROM   rate_list
                                                         WHERE  switch_date <= tmp.date_time - 1 / 86400) AND nschedulelist = 1)
             GROUP BY tmp.pgid, tmp.vpar, TRUNC(tmp.date_time - 1 / 86400), r.rid, CUBE(r.rate)
             HAVING   GROUPING_ID(r.rate) > 0
             ORDER BY dt, vpar) LOOP
   IF ln_par = 4 THEN                                                                                                    -- обнуляем группу после прошлого раза
    ln_par := 0;
   END IF;

   WHILE lc.vpar - ln_par > 1 LOOP                                                                                 -- если есть пропущенные, то добавляем пустые
    data_t(data_t.COUNT + 1) := NULL;
    data_t(data_t.COUNT + 1) := NULL;
    data_t(data_t.COUNT + 1) := NULL;
    data_t(data_t.COUNT + 1) := NULL;
    ln_par := ln_par + 1;
   END LOOP;

   ln_par := lc.vpar;
   data_t(data_t.COUNT + 1) := lc.csld;
   data_t(data_t.COUNT + 1) := lc.bsld;
   data_t(data_t.COUNT + 1) := lc.asld;
   data_t(data_t.COUNT + 1) := lc.sld;
  END LOOP;

  -- а теперь считаем итоги
  IF ln_locksum = 0 THEN
   FOR j IN 1 .. 16 LOOP                                                                                                                             -- столбцы
    data_t(data_t.COUNT + 1) := 0;

    FOR i IN 1 .. TRUNC(data_t.COUNT / 16) LOOP                                                                                                       -- строки
     data_t(data_t.COUNT) := data_t(data_t.COUNT) + data_t((i - 1) * 16 + j);
    END LOOP;
   END LOOP;
  END IF;
 END;

