 PROCEDURE proc_info_16(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  smena               DATE;
 BEGIN
  an_cnfixcol := 2;
  an_cntitle := 2;
  an_cnfooter := 0;

  IF (TO_CHAR(ad_from, 'HH24')) < 20 AND(TO_CHAR(ad_from, 'HH24')) >= 8 THEN
   smena := TO_DATE('01-01-2009 08:00', 'DD-MM-YYYY HH24:MI');
  ELSE
   smena := TO_DATE('01-01-2009 20:00', 'DD-MM-YYYY HH24:MI');
  END IF;

  OPEN col_t FOR
   SELECT -1 ID, '№ п/п' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 0 ID, 'Наименование показателя' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 200 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena + 0.042, 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 2), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 3), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 4), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 5), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 6), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 7), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 8), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 9), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 10), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 11), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Час смены' title1, TO_CHAR(smena +(0.042 * 12), 'HH24') || ':00' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Всего за смену' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT     gid ID,
              DECODE(
               LEVEL,
               1, LPAD('.', 2 *(LEVEL - 1), TO_CHAR(uniinterior_pg.get_number(gid, NULL)) || '.') || TO_CHAR(uniinterior_pg.get_number(gid, PARENT)),
               2, LPAD('.', 2 *(LEVEL - 1), TO_CHAR(uniinterior_pg.get_number(gid, NULL)) || '.') || TO_CHAR(uniinterior_pg.get_number(gid, PARENT)),
               ''
              )
               --DECODE (LEVEL, 1, TO_CHAR (get_number(gid,an_id)),  '')
              title1,
              LPAD(' ', 2 *(LEVEL - 1)) || NAME title2, cn_white datacl, 1 nlock, '' vmasks,                   --utilrep_pg.f_sortbyl_n (ROWNUM, gid, an_id) srt
                                                                                            0 srt
   FROM       GROUPS
   WHERE      LEVEL IN(1, 2)
   CONNECT BY PRIOR gid = PARENT
   START WITH PARENT = an_id
   ORDER SIBLINGS BY NVL(util_pg.get_param(vparam, 1), NAME);
 END;

