 PROCEDURE proc_value_16(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  ln_rassum           NUMBER;                                                                                     -- позиция начала строчки с суммой по расходу
  ln_vyrsum           NUMBER;                                                                                   -- позиция начала строчки с суммой по выработке
  ln_ud               NUMBER;                                                                                             -- позиция начала строчки с удельными
 BEGIN
   /*   IF (TO_CHAR(ad_from,'HH24'))>=8 AND (TO_CHAR(ad_from,'HH24'))<20 THEN
        tmp_date1:=TRUNC(ad_from)+8/24;
     ELSIF (TO_CHAR(ad_from,'HH24'))>=20 THEN
        tmp_date1:=TRUNC(ad_from)+20/24;
     ELSE
        tmp_date1:=TRUNC(ad_from)-1 + 20/24;
     END IF;

  FOR lc IN (SELECT gid, NAME
               FROM GROUPS
              WHERE LEVEL IN (1,2)--GID IN (SELECT PARENT FROM GROUPS)
                    CONNECT BY PRIOR gid = PARENT
                    START WITH PARENT = an_id
                    ORDER SIBLINGS BY NVL(util_pg.get_param (vparam, 1), NAME))
          LOOP
              FOR i IN 1..12
              LOOP
                  SELECT
                      --SUM (DECODE (g.inverted, 'y', h.ed * DECODE (g.npartly, 1, 0, 1), h.er * DECODE (g.npartly, 2, 0, 1)))
                      SUM(util_pg.sld(h.mid,NVL(h.er*DECODE(g.NPARTLY,2,0,1),0),NVL(h.ed*DECODE(g.NPARTLY,1,0,1),0))*DECODE(G.INVERTED,'y',-1,1))
                      INTO data_t(data_t.count+1)
                      FROM HALFHOUR h, GROUPS g
                      WHERE g.gid IN (SELECT gid FROM GROUPS
                                       WHERE mid>0 CONNECT BY PRIOR gid=parent START WITH parent=lc.gid)
                      AND h.mid=g.mid
                      AND h.DATE_TIME > tmp_date1 + (i-1)/24
                      AND h.DATE_TIME <= tmp_date1 + i/24;
              END LOOP;
              -- находим сумму за сутки (по строчке)
              data_t(data_t.count+1):=data_t(data_t.count);
              FOR i IN 2..12
              LOOP
                 IF data_t(data_t.count) IS NULL AND data_t(data_t.count-i) IS NOT NULL THEN
                   data_t(data_t.count):=0+data_t(data_t.count-i);
                 ELSIF data_t(data_t.count) IS NOT NULL AND data_t(data_t.count-i) IS NULL THEN
                   data_t(data_t.count):=data_t(data_t.count)+0;
                 ELSE
                   data_t(data_t.count):=data_t(data_t.count)+data_t(data_t.count-i);
                 END IF;
              END LOOP;
          END LOOP;*/
  FOR lc IN (SELECT   t.pnm, DECODE(GROUPING(t.nm), 1, -1, t.nm) nm,
                                                                    --t.NAME,
                                                                    SUM(er1) er1, SUM(er2) er2, SUM(er3) er3, SUM(er4) er4, SUM(er5) er5, SUM(er6) er6,
                      SUM(er7) er7, SUM(er8) er8, SUM(er9) er9, SUM(er10) er10, SUM(er11) er11, SUM(er12) er12
             FROM     (SELECT     (SELECT NVL(ryda.util_pg.get_param(vparam, 1), NAME)
                                   FROM   ryda.GROUPS
                                   WHERE  gid = g.PARENT) pnm, g.gid, g.NAME, ryda.util_pg.allnumber_f(ryda.util_pg.get_param(g.vparam, 1)) nm, NULL er1,
                                  NULL er2, NULL er3, NULL er4, NULL er5, NULL er6, NULL er7, NULL er8, NULL er9, NULL er10, NULL er11, NULL er12
                       FROM       ryda.GROUPS g
                       WHERE      LEVEL = 2
                       CONNECT BY PRIOR gid = PARENT
                       START WITH PARENT = an_id
                       UNION ALL
                       SELECT   NVL(ryda.util_pg.get_param(g1.vparam, 1), g1.NAME) pnm, g2.gid, g2.NAME,
                                ryda.util_pg.allnumber_f(ryda.util_pg.get_param(g2.vparam, 1)) nm,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '08', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '20', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er1,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '09', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '21', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er2,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '10', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '22', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er3,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '11', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '23', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er4,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '12', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '00', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er5,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '13', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '01', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er6,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '14', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '02', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er7,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '15', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '03', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er8,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '16', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '04', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er9,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '17', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '05', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er10,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '18', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '06', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er11,
                                SUM(DECODE(
                                  TO_CHAR(date_time - 1 / 86400, 'HH24'),
                                  '19', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1),
                                  '07', ryda.util_pg.sld(h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0))
                                   * DECODE(g.inverted, 'y', -1, 1)
                                 )) er12
                       FROM     ryda.halfhour h,
                                ryda.GROUPS g,
                                (SELECT     gid, PARENT, vparam, NAME
                                 FROM       ryda.GROUPS gp
                                 WHERE      LEVEL = 2
                                 CONNECT BY PRIOR gp.gid = gp.PARENT
                                 START WITH gp.PARENT = an_id) g2,
                                (SELECT     gid, PARENT, vparam, NAME
                                 FROM       ryda.GROUPS
                                 WHERE      LEVEL = 1
                                 CONNECT BY PRIOR gid = PARENT
                                 START WITH PARENT = an_id) g1
                       WHERE    g.gid IN(SELECT     gid
                                         FROM       ryda.GROUPS
                                         CONNECT BY PRIOR gid = PARENT
                                         START WITH PARENT = an_id) AND h.mid = g.mid AND g.PARENT = g2.gid AND g2.PARENT = g1.gid
                                AND h.date_time >
                                    (
                                     CASE
                                      WHEN TO_CHAR(ad_from, 'HH24') >= 8 AND TO_CHAR(ad_from, 'HH24') < 20 THEN TRUNC(ad_from) + 8 / 24
                                      WHEN TO_CHAR(ad_from, 'HH24') >= 20 THEN TRUNC(ad_from) + 20 / 24
                                      ELSE TRUNC(ad_from) - 1 + 20 / 24
                                     END
                                    )
                                AND h.date_time <=
                                      (
                                       CASE
                                        WHEN TO_CHAR(ad_from, 'HH24') >= 8 AND TO_CHAR(ad_from, 'HH24') < 20 THEN TRUNC(ad_from) + 8 / 24
                                        WHEN TO_CHAR(ad_from, 'HH24') >= 20 THEN TRUNC(ad_from) + 20 / 24
                                        ELSE TRUNC(ad_from) - 1 + 20 / 24
                                       END
                                      )
                                    + 12 / 24
                       GROUP BY NVL(ryda.util_pg.get_param(g1.vparam, 1), g1.NAME), g2.gid, g2.NAME,
                                ryda.util_pg.allnumber_f(ryda.util_pg.get_param(g2.vparam, 1))) t
             GROUP BY /*t.gid, t.NAME,*/ ROLLUP(t.pnm, t.nm)
             ORDER BY t.pnm, nm) LOOP
   IF lc.pnm IS NOT NULL THEN                                                                                             -- откидываем общую суммарную строчку
    IF lc.nm = -1 THEN
     IF lc.pnm = 1 THEN
      ln_rassum := data_t.COUNT;                                                                          -- запоминаем позицию начала строки с суммами расхода
      data_t(data_t.COUNT + 1) := lc.er1;
      data_t(data_t.COUNT + 1) := lc.er2;
      data_t(data_t.COUNT + 1) := lc.er3;
      data_t(data_t.COUNT + 1) := lc.er4;
      data_t(data_t.COUNT + 1) := lc.er5;
      data_t(data_t.COUNT + 1) := lc.er6;
      data_t(data_t.COUNT + 1) := lc.er7;
      data_t(data_t.COUNT + 1) := lc.er8;
      data_t(data_t.COUNT + 1) := lc.er9;
      data_t(data_t.COUNT + 1) := lc.er10;
      data_t(data_t.COUNT + 1) := lc.er11;
      data_t(data_t.COUNT + 1) := lc.er12;
     ELSIF lc.pnm = 2 THEN
      ln_vyrsum := data_t.COUNT;                                                                        -- запоминаем позицию начала строки с суммами выработки
      data_t(data_t.COUNT + 1) := lc.er1;
      data_t(data_t.COUNT + 1) := lc.er2;
      data_t(data_t.COUNT + 1) := lc.er3;
      data_t(data_t.COUNT + 1) := lc.er4;
      data_t(data_t.COUNT + 1) := lc.er5;
      data_t(data_t.COUNT + 1) := lc.er6;
      data_t(data_t.COUNT + 1) := lc.er7;
      data_t(data_t.COUNT + 1) := lc.er8;
      data_t(data_t.COUNT + 1) := lc.er9;
      data_t(data_t.COUNT + 1) := lc.er10;
      data_t(data_t.COUNT + 1) := lc.er11;
      data_t(data_t.COUNT + 1) := lc.er12;
     ELSIF lc.pnm = 3 THEN
      ln_ud := data_t.COUNT;

      FOR i IN 1 .. 12 LOOP                                                                                                          -- считаем удельный расход
       IF data_t(ln_vyrsum + i) = 0 THEN
        data_t(data_t.COUNT + 1) := 0;
       ELSIF data_t(ln_vyrsum + i) IS NULL THEN
        data_t(data_t.COUNT + 1) := NULL;
       ELSE
        data_t(data_t.COUNT + 1) := TRUNC(data_t(ln_rassum + i) / data_t(ln_vyrsum + i), 3);
       END IF;
      END LOOP;
     END IF;
    ELSE                                                                                                                                      -- обычные строчки
     data_t(data_t.COUNT + 1) := lc.er1;
     data_t(data_t.COUNT + 1) := lc.er2;
     data_t(data_t.COUNT + 1) := lc.er3;
     data_t(data_t.COUNT + 1) := lc.er4;
     data_t(data_t.COUNT + 1) := lc.er5;
     data_t(data_t.COUNT + 1) := lc.er6;
     data_t(data_t.COUNT + 1) := lc.er7;
     data_t(data_t.COUNT + 1) := lc.er8;
     data_t(data_t.COUNT + 1) := lc.er9;
     data_t(data_t.COUNT + 1) := lc.er10;
     data_t(data_t.COUNT + 1) := lc.er11;
     data_t(data_t.COUNT + 1) := lc.er12;

     ----------- пересчет кВт
     IF lc.pnm = 2 THEN                                                                                          -- надо пересчитать кВт с учетом NULL в тоннах
      FOR i IN 1 .. 12 LOOP
       IF (lc.nm * 13 + i) < ln_vyrsum AND data_t(data_t.COUNT - 12 + i) IS NULL THEN
        NULL;
        data_t(lc.nm * 13 + 13) := util_pg.sumn(data_t(lc.nm * 13 + 13), -data_t(lc.nm * 13 + i));                         -- уменьшаем сумму расходов за смену
        data_t(ln_rassum + i) := util_pg.sumn(data_t(ln_rassum + i), -data_t(lc.nm * 13 + i));                               -- уменьшаем сумму расходов за час
        data_t(ln_rassum + 13) := util_pg.sumn(data_t(ln_rassum + 13), -data_t(lc.nm * 13 + i));          -- уменьшаем общую сумму расходов за сутки по секциям
        data_t(lc.nm * 13 + i) := NULL;
       END IF;
      END LOOP;
     END IF;
    END IF;

    -- находим сумму за сутки (по текущей строчке)
    IF lc.pnm = 3 THEN
     IF data_t(data_t.COUNT - ln_vyrsum + 14) = 0 THEN
      data_t(data_t.COUNT + 1) := 0;
     ELSIF data_t(data_t.COUNT - ln_vyrsum + 14) IS NULL THEN
      data_t(data_t.COUNT + 1) := NULL;
     ELSE
      data_t(data_t.COUNT + 1) := TRUNC(data_t(data_t.COUNT - ln_ud + 1) / data_t(data_t.COUNT - ln_vyrsum + 14), 3);
     END IF;
    ELSE
     data_t(data_t.COUNT + 1) := data_t(data_t.COUNT);

     FOR i IN 2 .. 12 LOOP
      data_t(data_t.COUNT) := util_pg.sumn(data_t(data_t.COUNT), data_t(data_t.COUNT - i));
     END LOOP;
    END IF;
   END IF;                                                                                                                                 -- lc.pnm is not null
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_info_2(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur, av_param VARCHAR2
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  lv_param            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 1);
 BEGIN
  an_cnfixcol := 4;
  an_cntitle := 2;

  SELECT DECODE(ln_locksum, 0, 3, 0)
  INTO   an_cnfooter
  FROM   DUAL;

  OPEN col_t FOR
   SELECT -1 ID, '№ п/п' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -2 ID, 'Назва лінії' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 300 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -2 ID, '№ лічильника' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -2 ID, 'Напрямок перетоку' title1, '' title2, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 55 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Показання лічильника' title1, 'на 0 г. 1-го числа звітного місяця' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 100 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Показання лічильника' title1, 'на 24 г. останнього числа звітного місяця' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 100 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 3 ID, 'Різниця показників лічильників' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 100 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 4 ID, 'Коефіцієнт лічильника' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 85 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 5 ID, 'Кіл-ть електроенергії облікованої лічильником' || CHR(13) || 'тис. кВт/г.' title1, '' title2, cn_btnface titlecl, cn_left titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 120 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 6 ID, DECODE(lv_param, 1, 'Примітка', 2, 'Кіл-ть електроенергії за даними АСОЕ' || CHR(13) || 'тис. кВт/г.') title1, '' title2, cn_btnface titlecl,
          cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 120 nwidth, '' vmasks
   FROM   DUAL;

  IF an_ispoint = 1 THEN
   OPEN row_t FOR
    SELECT t.ID, TO_CHAR(ROWNUM) title1, t.title2, t.title3, t.title4, t.datacl, t.nlock, t.vmasks, 0 srt
    FROM   (SELECT   p.mid ID, DECODE(f.vcode, '', '', f.vcode || '.') || pa.NAME || ' / ' || p.NAME title2, m.mtrsn title3, d.t title4, cn_white datacl,
                     1 nlock, '' vmasks
            FROM     feeders f,
                     meters m,
                     points p,
                     points pa,
                     (SELECT ROWNUM r, DECODE(ROWNUM, 1, 'прийом', 'віддача') t
                      FROM   dict
                      WHERE  ROWNUM <= 2) d
            WHERE    f.mid IN(SELECT     mid
                              FROM       points
                              CONNECT BY PRIOR mid = PARENT
                              START WITH mid = an_id) AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
            ORDER BY pa.NAME, pa.mid, p.NAME, p.mid, d.t) t                                            -- сортировка по d.t значит - сначала отдача, потом прием
    UNION ALL
    SELECT -1 ID, '' title1, '' title2, 'Разом:' title3, 'віддача' title4, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  ln_locksum = 0
    UNION ALL
    SELECT -1 ID, '' title1, '' title2, '' title3, 'прийом' title4, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  ln_locksum = 0
    UNION ALL
    SELECT -1 ID, '' title1, '' title2, '' title3, 'сальдо' title4, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  ln_locksum = 0;
  ELSE
   OPEN row_t FOR
    SELECT t.ID, TO_CHAR(ROWNUM) title1, t.title2, t.title3, t.title4, t.datacl, t.nlock, t.vmasks, 0 srt
    FROM   (SELECT   p.mid ID, NVL(util_pg.get_param(g.vparam, 2), DECODE(f.vcode, '', '', f.vcode || '.') || pa.NAME || '/' || p.NAME) title2, m.mtrsn title3,
                     d.t title4, cn_white datacl, 1 nlock, '' vmasks
            FROM     GROUPS g,
                     feeders f,
                     meters m,
                     points p,
                     points pa,
                     (SELECT ROWNUM r, DECODE(ROWNUM, 1, 'прийом', 'віддача') t
                      FROM   dict
                      WHERE  ROWNUM <= 2) d
            WHERE    g.gid IN(
                      SELECT     gid
                      FROM       GROUPS
                      CONNECT BY PRIOR gid = PARENT
                                 AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501))
                      START WITH gid = an_id
                                 AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501)))
                     AND g.mid = f.mid AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
            ORDER BY util_pg.allnumber_f(util_pg.get_param(g.vparam, 1, ';')), pa.NAME, pa.mid, p.NAME, p.mid, d.t) t
                                                                                                       -- сортировка по d.t значит - сначала отдача, потом прием
    UNION ALL
    SELECT -1 ID, '' title1, '' title2, 'Разом:' title3, 'віддача' title4, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  ln_locksum = 0
    UNION ALL
    SELECT -1 ID, '' title1, '' title2, '' title3, 'прийом' title4, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  ln_locksum = 0
    UNION ALL
    SELECT -1 ID, '' title1, '' title2, '' title3, 'сальдо' title4, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
    FROM   DUAL
    WHERE  ln_locksum = 0;
  END IF;
 END;

