 PROCEDURE proc_value_2(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, av_param VARCHAR2) IS
  lt_tmp              common_pg.tt_number;
  temp_i              NUMBER;
  temp_k              NUMBER;
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  lv_param            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 1);
  ld_firstdate        DATE;
  ld_lastdate         DATE;
  lv_sqltimezone      VARCHAR2(2000);
  ln_footer_cells_cnt NUMBER DEFAULT 18;
 BEGIN
  lt_tmp(0) := 0;                                                                                                                               -- сумма приема
  lt_tmp(1) := 0;                                                                                                                               -- сумма отдачи
  lt_tmp(2) := 0;                                                                                                                          -- сумма приема АСОЕ
  lt_tmp(3) := 0;                                                                                                                          -- сумма отдачи АСОЕ
  ld_firstdate := (ad_from) + interior_pg.get_hourtimezone;                                                                               -- приводим к Украине
  ld_lastdate := (ad_till) + interior_pg.get_hourtimezone;                                                                                -- приводим к Украине

  IF (interior_pg.get_hourtimezone > 0) THEN                                                                                                     -- Европа 1/24
   lv_sqltimezone := ' AND   util_pg.to_unlocaltime (h.date_time, nsource) > :par1
      AND   util_pg.to_unlocaltime (h.date_time, nsource) <= :par2 ';
  ELSE
   lv_sqltimezone :=
    ' AND   util_pg.to_unlocaltime (h.date_time, nsource) > util_pg.to_unlocaltime (:par1)
      AND   util_pg.to_unlocaltime (h.date_time, nsource) <= util_pg.to_unlocaltime (:par2) ';
  END IF;

  IF an_ispoint = 1 THEN
   FOR lc IN (SELECT   p.mid, DECODE(SIGN(NVL(f.metkc, 1) - 1), 1, NVL(f.metkc, 1), NVL(f.kc, 1)) kc
              FROM     feeders f, points p, points pa
              WHERE    f.mid IN(SELECT     mid
                                FROM       points
                                CONNECT BY PRIOR mid = PARENT
                                START WITH mid = an_id) AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
              ORDER BY pa.NAME, pa.mid, p.NAME, p.mid) LOOP
    -- отдача A-  -- согласно сортировке по d.t в getmaketinfo - сначала отдача, потом прием
    data_t(data_t.COUNT + 1) := util_pg.get_meterage_vch2(lc.mid, ad_from, 2, 0);
    data_t(data_t.COUNT + 1) := util_pg.get_meterage_vch2(lc.mid, ad_till, 2, 0);
    data_t(data_t.COUNT + 1) := util_pg.indicoverturn(data_t(data_t.COUNT) - data_t(data_t.COUNT - 1), NULL);
    data_t(data_t.COUNT + 1) := lc.kc;
    data_t(data_t.COUNT + 1) := data_t(data_t.COUNT - 1) * lc.kc;
    lt_tmp(1) := lt_tmp(1) + NVL(data_t(data_t.COUNT), 0);                                                                                  -- суммируем отдачу

    IF lv_param = 1 THEN                                                                                                                            -- прымитка
     data_t(data_t.COUNT + 1) := NULL;
    ELSIF lv_param = 2 THEN                                                                                                                              -- АСОЕ
     EXECUTE IMMEDIATE    'SELECT ROUND (NVL (SUM (util_pg.sld (h.mid, h.er, h.ed)),0),3)
          FROM halfhour h
         WHERE h.mid=:mid
               AND h.date_time >= (:par1 - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
               AND h.date_time <= (:par2 + DECODE(interior_pg.get_hourtimezone,0,0,3/24)) '
                       || lv_sqltimezone
     INTO              data_t(data_t.COUNT + 1)
     USING             lc.mid, ld_firstdate, ld_lastdate, ld_firstdate, ld_lastdate;
    END IF;

    lt_tmp(3) := lt_tmp(3) + NVL(data_t(data_t.COUNT), 0);                                                                              -- суммируем отдачу АСОЕ
    -- прием А+
    data_t(data_t.COUNT + 1) := util_pg.get_meterage_vch2(lc.mid, ad_from, 1, 0);
    data_t(data_t.COUNT + 1) := util_pg.get_meterage_vch2(lc.mid, ad_till, 1, 0);
    data_t(data_t.COUNT + 1) := util_pg.indicoverturn(data_t(data_t.COUNT) - data_t(data_t.COUNT - 1), NULL);
    data_t(data_t.COUNT + 1) := lc.kc;
    data_t(data_t.COUNT + 1) := data_t(data_t.COUNT - 1) * lc.kc;
    lt_tmp(0) := lt_tmp(0) + NVL(data_t(data_t.COUNT), 0);                                                                                    -- суммируем прием

    IF lv_param = 1 THEN                                                                                                                             -- прымитка
     data_t(data_t.COUNT + 1) := NULL;
    ELSIF lv_param = 2 THEN                                                                                                                              -- АСОЕ
     EXECUTE IMMEDIATE    'SELECT ROUND (NVL (SUM (util_pg.sld (h.mid, h.er, h.ed)),0),3)
          FROM halfhour h
         WHERE h.mid=:mid
               AND h.date_time >= (:par1 - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
               AND h.date_time <= (:par2 + DECODE(interior_pg.get_hourtimezone,0,0,3/24)) '
                       || lv_sqltimezone
     INTO              data_t(data_t.COUNT + 1)
     USING             lc.mid, ld_firstdate, ld_lastdate, ld_firstdate, ld_lastdate;
    END IF;

    lt_tmp(2) := lt_tmp(2) + NVL(data_t(data_t.COUNT), 0);                                                                               -- суммируем прием АСОЕ
   END LOOP;
  ELSE
   FOR lc IN (SELECT   p.mid, DECODE(SIGN(NVL(f.metkc, 1) - 1), 1, NVL(f.metkc, 1), NVL(f.kc, 1)) kc, g.inverted, g.npartly
              FROM     GROUPS g, feeders f, points p, points pa, meters m
              WHERE    g.gid IN(
                        SELECT     gid
                        FROM       GROUPS
                        CONNECT BY PRIOR gid = PARENT
                                   AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501))
                        START WITH gid = an_id
                                   AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501)))
                       AND g.mid = f.mid AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+) AND m.entype(+) = 7 AND f.mid = m.mid(+)      -- added by KAG 13.05.2009
              ORDER BY util_pg.allnumber_f(util_pg.get_param(g.vparam, 1, ';')), pa.NAME, pa.mid, p.NAME, p.mid) LOOP
    FOR i IN REVERSE 1 .. 2 LOOP                                                                                        -- здесь задается порядок отдачи/приема
     IF lc.inverted = 'y' THEN
      IF i = 1 THEN
       temp_i := 2;
      ELSIF i = 2 THEN
       temp_i := 1;
      END IF;

      temp_k := uniinterior_pg.get_koef_npartly(lc.npartly, i, lc.inverted);
      data_t(data_t.COUNT + 1) := temp_k * util_pg.get_meterage_vch2(lc.mid, ad_from, temp_i, 0);
      data_t(data_t.COUNT + 1) := temp_k * util_pg.get_meterage_vch2(lc.mid, ad_till, temp_i, 0);
     ELSIF lc.inverted = 'n' THEN
      temp_k := uniinterior_pg.get_koef_npartly(lc.npartly, i, lc.inverted);
      data_t(data_t.COUNT + 1) := temp_k * util_pg.get_meterage_vch2(lc.mid, ad_from, i, 0);
      data_t(data_t.COUNT + 1) := temp_k * util_pg.get_meterage_vch2(lc.mid, ad_till, i, 0);
     END IF;

     data_t(data_t.COUNT + 1) := util_pg.indicoverturn(data_t(data_t.COUNT) - data_t(data_t.COUNT - 1), NULL);
     data_t(data_t.COUNT + 1) := lc.kc;
     data_t(data_t.COUNT + 1) := data_t(data_t.COUNT - 1) * lc.kc;
     lt_tmp(i - 1) := lt_tmp(i - 1) + NVL(data_t(data_t.COUNT), 0);                                                                -- суммируем отдачу или прием

     IF lv_param = 1 THEN                                                                                                                            -- прымитка
      data_t(data_t.COUNT + 1) := NULL;
     ELSIF lv_param = 2 THEN                                                                                                                             -- АСОЕ
      /*SELECT --ROUND (NVL (SUM (DECODE (lc.inverted, 'y', h.ed * DECODE (lc.npartly, 1, 0, 1), h.er * DECODE (lc.npartly, 2, 0, 1))), 0), 3)
             ROUND (NVL (SUM (util_pg.sld (h.mid, h.er * DECODE (lc.npartly, 2, 0, 1),
                                                  h.ed * DECODE (lc.npartly, 1, 0, 1)) * DECODE (lc.inverted,'y', -1,1)),0),3)
        INTO data_t (data_t.COUNT + 1)
        FROM halfhour h
       WHERE h.mid=lc.mid AND h.date_time > TRUNC(ad_from) AND h.date_time <= TRUNC(ad_till);*/
      EXECUTE IMMEDIATE    'SELECT --ROUND (NVL (SUM (DECODE (lc.inverted, ''y'', h.ed * DECODE (lc.npartly, 1, 0, 1), h.er * DECODE (lc.npartly, 2, 0, 1))), 0), 3)
                ROUND (NVL (SUM (util_pg.sld (h.mid, h.er * DECODE (:npartly, 2, 0, 1),
                                                     h.ed * DECODE (:npartly, 1, 0, 1)) * DECODE (:inverted,''y'', -1,1)),0),3)
           FROM halfhour h
          WHERE h.mid=:mid
                AND h.date_time >= (:par1 - DECODE(interior_pg.get_hourtimezone,0,0,3/24))
                AND h.date_time <= (:par2 + DECODE(interior_pg.get_hourtimezone,0,0,3/24)) '
                        || lv_sqltimezone
      INTO              data_t(data_t.COUNT + 1)
      USING             lc.npartly, lc.npartly, lc.inverted, lc.mid, ld_firstdate, ld_lastdate, ld_firstdate, ld_lastdate;

      lt_tmp(i + 1) := lt_tmp(i + 1) + NVL(data_t(data_t.COUNT), 0);                                                          -- суммируем отдачу или прием АСОЕ
     END IF;
    END LOOP;
   END LOOP;
  END IF;

  IF ln_locksum = 0 THEN                                                                                                           -- вывод итоговых показателей
   FOR i IN data_t.COUNT + 1 .. data_t.COUNT + ln_footer_cells_cnt LOOP
    data_t(i) := NULL;
   END LOOP;

   data_t(data_t.COUNT - ln_footer_cells_cnt + 5) := lt_tmp(1);
   data_t(data_t.COUNT - ln_footer_cells_cnt + 11) := lt_tmp(0);
   data_t(data_t.COUNT - ln_footer_cells_cnt + 17) := lt_tmp(0) - lt_tmp(1);                                                                   -- прием - отдача

   IF lv_param = 2 THEN                                                                                                                                  -- АСОЕ
    data_t(data_t.COUNT - ln_footer_cells_cnt + 6) := lt_tmp(3);
    data_t(data_t.COUNT - ln_footer_cells_cnt + 12) := lt_tmp(2);
    data_t(data_t.COUNT - ln_footer_cells_cnt + 18) := lt_tmp(2) - lt_tmp(3);                                                            -- прием - отдача АСОЕ
   END IF;
  END IF;
 END;

---------------------------------------------------------------------------------------------
 PROCEDURE proc_info_4(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur, av_param VARCHAR2
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  lv_param            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 1);
 BEGIN
  SELECT DECODE(lv_param, 1, 2, 2, 3, 3, 3)
  INTO   an_cnfixcol
  FROM   DUAL;

  an_cntitle := 3;

  IF ln_locksum = 0 THEN
   an_cnfooter := 1;
  ELSE
   an_cnfooter := 0;
  END IF;

  OPEN col_t FOR
   SELECT *
   FROM   (SELECT -3 ID, '№ з/п' title1, '' title2, '' title3, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 20 nwidth,
                  '' vmasks
           FROM   DUAL)
   WHERE  lv_param IN(2, 3)
   UNION ALL
   SELECT -2 ID, 'Найм. ПС' title1, '' title2, '' title3, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 180 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Клас напруги' title1, '' title2, 'кВ' title3, cn_btnface titlecl, cn_right titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 50 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 0 ID, 'Баланс по межі балансової належності ПС' title1, 'Прийом' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 1 ID, 'Баланс по межі балансової належності ПС' title1, 'Віддача' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Баланс по межі балансової належності ПС' title1, 'Нбфакт.' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 2 ID, 'Баланс по межі балансової належності ПС' title1, 'Нбфакт.' title2, '%' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 3 ID, 'Баланс по межі балансової належності ПС' title1, 'Нбдоп.' title2, '%' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT *
   FROM   (SELECT 0 ID, 'СН---->ПЛ 110(150 кВ)' title1, 'Прийом' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
                  cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 1 ID, 'СН---->ПЛ 110(150 кВ)' title1, 'Віддача' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
                  cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 2 ID, 'СН---->ПЛ 110(150 кВ)' title1, 'Нбфакт.' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl,
                  cn_right dataal, 1 nlock, 70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 3 ID, 'СН---->ПЛ 110(150 кВ)' title1, 'Нбфакт.' title2, '%' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl, cn_right dataal,
                  1 nlock, 60 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT 3 ID, 'СН---->ПЛ 110(150 кВ)' title1, 'Нбдоп.' title2, '%' title3, cn_btnface titlecl, cn_right titleal, cn_white datacl, cn_right dataal,
                  1 nlock, 60 nwidth, '' vmasks
           FROM   DUAL)
   WHERE  lv_param = 1
   UNION ALL
   SELECT 5 ID, DECODE(lv_param, 1, 'ВП', 'Споживання е/е на власні потреби') title1, '' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_left titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT 6 ID, DECODE(lv_param, 1, 'ГП', 'Споживання е/е на господарські потреби') title1, '' title2, 'тис.кВт.г' title3, cn_btnface titlecl, cn_left titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL;

  IF an_ispoint <> 1 THEN
   IF lv_param = 1 THEN
    OPEN row_t FOR
     SELECT t.ID, t.title1, t.title2, t.datacl, t.nlock, t.vmasks, 0 srt
     FROM   (SELECT   g2.gid ID, NVL(util_pg.get_param(g1.vparam, 2), g1.NAME) title1, NVL(util_pg.get_param(g2.vparam, 2), g2.NAME) title2, cn_white datacl,
                      1 nlock, '' vmasks
             FROM     GROUPS g1, GROUPS g2
             WHERE    g1.PARENT = an_id AND g2.PARENT = g1.gid
                      AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g1.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g1.nfromperiod, 160501))
                      AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g2.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g2.nfromperiod, 160501))
             ORDER BY util_pg.allnumber_f(util_pg.get_param(g1.vparam, 1, ';')), g1.NAME, util_pg.allnumber_f(util_pg.get_param(g2.vparam, 1, ';')), g2.NAME,
                      g2.gid) t                                                                        -- сортировка по d.r значит - сначала прием, потом отдача
     UNION ALL
     SELECT -1 ID, 'Итого:' title1, '' title2, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL
     WHERE  ln_locksum = 0;
   ELSIF lv_param = 2 THEN                                                                                                                                -- ДЭС
    OPEN row_t FOR
     SELECT tt.ID, tt.title1, tt.title2, tt.title3, tt.datacl, tt.nlock, tt.vmasks, 0 srt
     FROM   (SELECT DISTINCT t.rn ID, t.nm title1, t.title2, DECODE(t.PARENT, an_id, NULL, NVL(util_pg.get_param(g.vparam, 2), g.NAME)) title3, cn_white datacl,
                             1 nlock, '' vmasks
             FROM            (SELECT     NVL(util_pg.get_param(vparam, 2), NAME) title2, PARENT, ROWNUM rn, gid,
                                         DECODE(LEVEL, 2, NULL, 3, uniinterior_pg.get_number(gid, PARENT)) nm
                              FROM       GROUPS
                              WHERE      LEVEL IN(2, 3)
                                         AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501))
                              START WITH gid = an_id
                              CONNECT BY PRIOR gid = PARENT
                              ORDER SIBLINGS BY util_pg.allnumber_f(util_pg.get_param(vparam, 1, ';')), NAME) t,
                             GROUPS g
             WHERE           g.PARENT = t.gid
             ORDER BY        t.rn) tt
     UNION ALL
     SELECT -1 ID, '' title1, '' title2, 'Итого:' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL
     WHERE  ln_locksum = 0;
   ELSIF lv_param = 3 THEN                                                                                                                                -- ЗЭС
    OPEN row_t FOR
     SELECT t.ID, TO_CHAR(ROWNUM) title1, t.title2, t.title3, datacl, nlock, vmasks, 0 srt
     FROM   (SELECT   g2.gid ID, NVL(util_pg.get_param(g1.vparam, 2), g1.NAME) title2, NVL(util_pg.get_param(g2.vparam, 2), g2.NAME) title3, cn_white datacl,
                      1 nlock, '' vmasks
             FROM     GROUPS g1, GROUPS g2
             WHERE    g1.PARENT = an_id AND g2.PARENT = g1.gid
                      AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g1.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g1.nfromperiod, 160501))
                      AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g2.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g2.nfromperiod, 160501))
             ORDER BY util_pg.allnumber_f(util_pg.get_param(g1.vparam, 1, ';')), g1.NAME, util_pg.allnumber_f(util_pg.get_param(g2.vparam, 1, ';')), g2.NAME,
                      g2.gid) t                                                                        -- сортировка по d.r значит - сначала прием, потом отдача
     UNION ALL
     SELECT -1 ID, '' title1, '' title2, 'Итого:' title3, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
     FROM   DUAL
     WHERE  ln_locksum = 0;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_value_4(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, av_param VARCHAR2) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  lv_param            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 1);
  temp_i              NUMBER;                                                                                                  -- текущий номер строки в отчете
  lt_tmp              common_pg.tt_number;
  ln_cln_cnt          NUMBER;                                                                                                        -- число столбцов в отчете
 BEGIN
  IF an_ispoint <> 1 THEN
   temp_i := 0;
   lt_tmp(0) := 0;                                                                                                                                  -- сумма ВП
   lt_tmp(1) := 0;                                                                                                                                  -- сумма ГП

   IF lv_param = 1 THEN
    ln_cln_cnt := 12;

    FOR lc IN (SELECT   g2.gid, NVL(util_pg.get_param(g1.vparam, 2), g1.NAME) title1, NVL(util_pg.get_param(g2.vparam, 2), g2.NAME) title2, cn_white datacl,
                        cn_right dataal, 1 nlock, '' vmasks
               FROM     GROUPS g1, GROUPS g2
               WHERE    g1.PARENT = an_id AND g2.PARENT = g1.gid
                        AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g1.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g1.nfromperiod, 160501))
                        AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g2.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g2.nfromperiod, 160501))
               ORDER BY util_pg.allnumber_f(util_pg.get_param(g1.vparam, 1, ';')), g1.NAME, util_pg.allnumber_f(util_pg.get_param(g2.vparam, 1, ';')), g2.NAME,
                        g2.gid) LOOP
     FOR lc1 IN (SELECT TO_NUMBER(util_pg.get_param(vparam, 1)) cln, gid                                            -- cln - группа столбцов (НБ1, НБ2, ВП, ГП)
                 FROM   GROUPS
                 WHERE  PARENT = lc.gid AND TO_NUMBER(util_pg.get_param(vparam, 1)) BETWEEN 1 AND 4) LOOP
      IF lc1.cln = 1 OR lc1.cln = 2 THEN
       SELECT er, ed, e, DECODE(er, 0, 0, ROUND(e / er * 100, 2)), ROUND(NVL(util_pg.get_ad_balance(lc1.gid, ad_from, ad_till, 1, 'halfhour'), 0), 2)
       INTO   data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 1), data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 2),
              data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 3), data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 4),
              data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 5)
       FROM   (SELECT ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er,
                      ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))), 0), 3) ed,
                      ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)) * DECODE(g.inverted, 'y', -1, 1)),
                        0), 3) e
               FROM   halfhour h, GROUPS g
               WHERE  g.gid IN(SELECT     gid
                               FROM       GROUPS
                               WHERE      mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = lc1.gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till);
      ELSIF lc1.cln = 3 OR lc1.cln = 4 THEN
       SELECT DECODE(lc1.cln, 3, er_, 4, er)
       INTO   data_t(temp_i * ln_cln_cnt + lc1.cln + 8)
       FROM   (SELECT ROUND(NVL(SUM(DECODE(g.inverted, 'y', -h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er_,
                      ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er
               --ROUND (NVL (SUM (DECODE (g.inverted, 'y', h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1))), 0), 3) ed,
               --ROUND (NVL (SUM (util_pg.sld (h.mid, h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,'y', -1,1)),0),3) e
               FROM   halfhour h, GROUPS g
               WHERE  g.gid IN(SELECT     gid
                               FROM       GROUPS
                               WHERE      mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = lc1.gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till);

       lt_tmp(lc1.cln - 3) := lt_tmp(lc1.cln - 3) + data_t(temp_i * ln_cln_cnt + lc1.cln + 8);                                                      -- суммируем
      END IF;
     END LOOP;

     temp_i := temp_i + 1;
    END LOOP;

    IF ln_locksum = 0 THEN                                                                                                         -- вывод итоговых показателей
     temp_i := temp_i + 1;
     data_t(temp_i * ln_cln_cnt - 1) := lt_tmp(0);
     data_t(temp_i * ln_cln_cnt) := lt_tmp(1);
    END IF;
-------------
   ELSIF lv_param = 2 THEN                                                                                                                                -- ДЭС
    ln_cln_cnt := 7;

    FOR lc IN (SELECT DISTINCT t.rn ID, t.nm title1, t.title2, DECODE(t.PARENT, an_id, NULL, NVL(util_pg.get_param(g.vparam, 2), g.NAME)) title3,
                               DECODE(t.PARENT, an_id, NULL, g.gid) gid
               FROM            (SELECT     NVL(util_pg.get_param(vparam, 2), NAME) title2, PARENT, ROWNUM rn, gid,
                                           DECODE(LEVEL, 2, NULL, 3, uniinterior_pg.get_number(gid, PARENT)) nm
                                FROM       GROUPS
                                WHERE      LEVEL IN(2, 3)
                                           AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(nfromperiod, 160501))
                                START WITH gid = an_id
                                CONNECT BY PRIOR gid = PARENT
                                ORDER SIBLINGS BY util_pg.allnumber_f(util_pg.get_param(vparam, 1, ';')), NAME) t,
                               GROUPS g
               WHERE           g.PARENT = t.gid
               ORDER BY        t.rn) LOOP
     IF lc.gid IS NULL THEN
      FOR i IN 1 .. ln_cln_cnt LOOP
       data_t(temp_i * ln_cln_cnt + i) := NULL;
      END LOOP;
     ELSE
      FOR lc1 IN (SELECT TO_NUMBER(util_pg.get_param(vparam, 1)) cln, gid                                           -- cln - группа столбцов (НБ1, НБ2, ВП, ГП)
                  FROM   GROUPS
                  WHERE  PARENT = lc.gid AND TO_NUMBER(util_pg.get_param(vparam, 1)) BETWEEN 1 AND 3) LOOP
       IF lc1.cln = 1 THEN
        SELECT er, ed, e, DECODE(er, 0, 0, ROUND(e / er * 100, 2)), ROUND(NVL(util_pg.get_ad_balance(lc1.gid, ad_from, ad_till, 1, 'halfhour'), 0), 2)
        INTO   data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 1), data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 2),
               data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 3), data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 4),
               data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 5)
        FROM   (SELECT ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er,
                       ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))), 0), 3) ed,
                       ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)) * DECODE(
                                                                                                                                g.inverted,
                                                                                                                                'y', -1,
                                                                                                                                1
                                                                                                                               )), 0), 3) e
                FROM   halfhour h, GROUPS g
                WHERE  g.gid IN(SELECT     gid
                                FROM       GROUPS
                                WHERE      mid IS NOT NULL
                                CONNECT BY PRIOR gid = PARENT
                                START WITH gid = lc1.gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till);
       ELSIF lc1.cln = 2 OR lc1.cln = 3 THEN
        SELECT DECODE(lc1.cln, 2, er_, 3, er)
        INTO   data_t(temp_i * ln_cln_cnt + lc1.cln + 4)
        FROM   (SELECT ROUND(NVL(SUM(DECODE(g.inverted, 'y', -h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er_,
                       ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er
                --ROUND (NVL (SUM (DECODE (g.inverted, 'y', h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1))), 0), 3) ed,
                --ROUND (NVL (SUM (util_pg.sld (h.mid, h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,'y', -1,1)),0),3) e
                FROM   halfhour h, GROUPS g
                WHERE  g.gid IN(SELECT     gid
                                FROM       GROUPS
                                WHERE      mid IS NOT NULL
                                CONNECT BY PRIOR gid = PARENT
                                START WITH gid = lc1.gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till);

        lt_tmp(lc1.cln - 2) := lt_tmp(lc1.cln - 2) + data_t(temp_i * ln_cln_cnt + lc1.cln + 4);                                                     -- суммируем
       END IF;
      END LOOP;
     END IF;                                                                                                                                   -- lc.gid is null

     temp_i := temp_i + 1;
    END LOOP;

    IF ln_locksum = 0 THEN                                                                                                         -- вывод итоговых показателей
     temp_i := temp_i + 1;
     data_t(temp_i * ln_cln_cnt - 1) := lt_tmp(0);
     data_t(temp_i * ln_cln_cnt) := lt_tmp(1);
    END IF;
-----------------
   ELSIF lv_param = 3 THEN                                                                                                                                -- ЗЭС
    ln_cln_cnt := 7;

    FOR lc IN (SELECT   g2.gid, NVL(util_pg.get_param(g1.vparam, 2), g1.NAME) title1, NVL(util_pg.get_param(g2.vparam, 2), g2.NAME) title2, cn_white datacl,
                        cn_right dataal, 1 nlock, '' vmasks
               FROM     GROUPS g1, GROUPS g2
               WHERE    g1.PARENT = an_id AND g2.PARENT = g1.gid
                        AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g1.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g1.nfromperiod, 160501))
                        AND(TO_CHAR(ad_from, 'yyyymm') <= NVL(g2.ntillperiod, 299912) AND TO_CHAR(ad_till, 'yyyymm') >= NVL(g2.nfromperiod, 160501))
               ORDER BY util_pg.allnumber_f(util_pg.get_param(g1.vparam, 1, ';')), g1.NAME, util_pg.allnumber_f(util_pg.get_param(g2.vparam, 1, ';')), g2.NAME,
                        g2.gid) LOOP
     FOR lc1 IN (SELECT TO_NUMBER(util_pg.get_param(vparam, 1)) cln, gid                                            -- cln - группа столбцов (НБ1, НБ2, ВП, ГП)
                 FROM   GROUPS
                 WHERE  PARENT = lc.gid AND TO_NUMBER(util_pg.get_param(vparam, 1)) BETWEEN 1 AND 3) LOOP
      IF lc1.cln = 1 THEN
       SELECT er, ed, e, DECODE(er, 0, 0, ROUND(e / er * 100, 2)), ROUND(NVL(util_pg.get_ad_balance(lc1.gid, ad_from, ad_till, 1, 'halfhour'), 0), 2)
       INTO   data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 1), data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 2),
              data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 3), data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 4),
              data_t(temp_i * ln_cln_cnt + (lc1.cln - 1) * 5 + 5)
       FROM   (SELECT ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er,
                      ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))), 0), 3) ed,
                      ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)) * DECODE(g.inverted, 'y', -1, 1)),
                        0), 3) e
               FROM   halfhour h, GROUPS g
               WHERE  g.gid IN(SELECT     gid
                               FROM       GROUPS
                               WHERE      mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = lc1.gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till);
      ELSIF lc1.cln = 2 OR lc1.cln = 3 THEN
       SELECT DECODE(lc1.cln, 2, er_, 3, er)
       INTO   data_t(temp_i * ln_cln_cnt + lc1.cln + 4)
       FROM   (SELECT ROUND(NVL(SUM(DECODE(g.inverted, 'y', -h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er_,
                      ROUND(NVL(SUM(DECODE(g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0), 3) er
               --ROUND (NVL (SUM (DECODE (g.inverted, 'y', h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1))), 0), 3) ed,
               --ROUND (NVL (SUM (util_pg.sld (h.mid, h.er * DECODE (g.npartly, 2, 0, 1), h.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,'y', -1,1)),0),3) e
               FROM   halfhour h, GROUPS g
               WHERE  g.gid IN(SELECT     gid
                               FROM       GROUPS
                               WHERE      mid IS NOT NULL
                               CONNECT BY PRIOR gid = PARENT
                               START WITH gid = lc1.gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till);

       lt_tmp(lc1.cln - 2) := lt_tmp(lc1.cln - 2) + data_t(temp_i * ln_cln_cnt + lc1.cln + 4);                                                      -- суммируем
      END IF;
     END LOOP;

     temp_i := temp_i + 1;
    END LOOP;

    IF ln_locksum = 0 THEN                                                                                                         -- вывод итоговых показателей
     temp_i := temp_i + 1;
     data_t(temp_i * ln_cln_cnt - 1) := lt_tmp(0);
     data_t(temp_i * ln_cln_cnt) := lt_tmp(1);
    END IF;
   END IF;                                                                                                                                          -- lv_param=
  END IF;                                                                                                                                     -- an_ispoint <> 1
 END;

------------------------------------------------------------------------------------------------------------------------
 -- обобщенный отчет по точкам
 PROCEDURE proc_info_31(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 18;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT ID, title1, TO_CHAR(ROWNUM) title2, titlecl, titleal, datacl, dataal, nlock, nwidth, vmasks
   FROM   (SELECT -1 ID, 'Наименование точки учёта' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 210 nwidth,
                  '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Краткое имя' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 62 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Зав. номер счётчика' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 65 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Разрядность счётчика' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Тип счётчика, его модификация' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 100 nwidth,
                  '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Кол. импульсов' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 65 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Класс точности счётчика' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 60 nwidth,
                  '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Пломба, год' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 60 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Пломба, квартал' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Номер ячейки' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'U первич. (ТН), кВ' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'U вторич. (ТН), кВ' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'I первич. (ТТ), А' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'I вторич. (ТТ), А' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Коэф. расчётный' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 60 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Класс точности ТН' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Класс точности ТТ' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, 'Примечание' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 100 nwidth, '' vmasks
           FROM   DUAL
           UNION ALL
           SELECT -1 ID, '' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
           FROM   DUAL);

  OPEN row_t FOR
   SELECT   1 ID, p.NAME title1, p.short_name title2, m.mtrsn title3, m.digits title4, m.mtype title5, m.mconst title6, m.mclass title7, m.myear title8,
            m.mquarter title9, f.cellnum title10, f.POWER title11, f.power2 title12, f.current1 title13, f.current2 title14, f.kc title15, f.nclasstn title16,
            f.nclasstt title17, f.vinfo title18, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM     points p, feeders f, meters m
   WHERE    p.mid IN(SELECT     mid
                     FROM       points
                     CONNECT BY PRIOR mid = PARENT
                     START WITH mid = an_id) AND p.mid = f.mid AND p.mid = m.mid(+) AND m.entype(+) = 7
   ORDER BY p.PARENT, p.mid;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по группам
 PROCEDURE proc_info_35(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 6;
  an_cntitle := 1;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Наименование групп и подгрупп, входящих в них' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock,
          240 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Полное название точки учета/счетчика' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 250 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'ИД объекта' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 80 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Сумма по группе (0/1)' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Инверсия (0/1)' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры группы' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 220 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT     1 ID, LPAD('   ', 2 *(LEVEL - 1)) || DECODE(g.mid, NULL, g.NAME, '') title1, DECODE(g.mid, NULL, '', g.NAME) title2, g.gid title3,
              DECODE(g.mid, NULL, DECODE(g.group_total, 'y', 1, 'n', 0), '') title4, DECODE(g.mid, NULL, '', DECODE(g.inverted, 'y', 1, 'n', 0)) title5,
              g.vparam title6, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM       GROUPS g
   CONNECT BY PRIOR gid = PARENT
   START WITH gid = an_id
   ORDER SIBLINGS BY g.NAME;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по точкам (отчет Общий список точек учета)
 PROCEDURE proc_info_33(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 17;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название групп, содержащих точки учета и счетчики' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl,
          cn_left dataal, 1 nlock, 217 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Полное название точки учета/счетчика' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock,
          225 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'ИД объекта' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип точки учета' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'УСД А+' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'УСД А-' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'УСД R+' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'УСД R-' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Инт. счетчик (0/1)' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 45 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Связной №' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 53 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Расчетный коэффициент' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_right dataal, 1 nlock, 73 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'UTC зима' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_center dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'UTC лето' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_center dataal, 1 nlock, 30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Доп. информация' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_center dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Инверсия направл. (0/1)' title2, cn_btnface titlecl,
          cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 55 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Тип начисления' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_left dataal, 1 nlock, 106 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры точек учета и счетчиков (расчетных точек)' title1, 'Расчетная формула' title2, cn_btnface titlecl, cn_center titleal,
          cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT 1 ID, p.title1, p.title2, p.title3,
          DECODE(p.ind, 4, 'Обобщенная ТУ', 3, DECODE(f.ncalcpointtype, NULL, DECODE(f.smart, '*', 'Инт. счетчик', 'ТУ/Счетчик'), 'Расчетная ТУ'), '') title4,
          f.er_position title5, f.ed_position title6, f.q1_position title7, f.q3_position title8, DECODE(f.mid, NULL, '', DECODE(f.smart, '*', 1, 0)) title9,
          f.canal title10, f.kc title11, f.ntimezonew title12, f.ntimezones title13, f.vaddparams title14, f.ninverted title15,
          DECODE(f.mid, NULL, '', DECODE(cpt.ncalcpointtype, NULL, 'Не производить', cpt.vname)) title16, editfeeders_pg.formulameas_p(f.mid) title17,
          cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   (SELECT     LPAD('   ', 2 *(LEVEL - 1)) || DECODE(ind, 3, '', 4, '', NAME) title1, DECODE(ind, 3, NAME, 4, NAME, '') title2,
                      DECODE(ind, 3, mid, 4, mid, '') title3, mid, ind
           FROM       (SELECT -1 mid, mid PARENT, cod, 10000 ind, '' NAME, short_name, norder
                       FROM   points
                       WHERE  mid IN(SELECT     PARENT
                                     FROM       points
                                     WHERE      ind IN(3, 4) AND mid <> an_id
                                     CONNECT BY PRIOR mid = PARENT
                                     START WITH mid = an_id
                                     GROUP BY   PARENT) AND mid <> an_id
                       UNION ALL
                       SELECT     mid, PARENT, cod, ind, NAME, short_name, norder
                       FROM       points
                       CONNECT BY PRIOR mid = PARENT
                       START WITH mid = an_id)
           CONNECT BY PRIOR mid = PARENT
           START WITH mid = an_id
           ORDER SIBLINGS BY ind, NAME) p,
          feeders f,
          calcpointtype cpt
   WHERE  p.mid = f.mid(+) AND p.ind IN(2, 3, 4, 10000) AND f.ncalcpointtype = cpt.ncalcpointtype(+);
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по точкам (отчет Параметры расчетных точек)
 PROCEDURE proc_info_34(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 9;
  an_cntitle := 1;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название группы' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 280 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Полное название расчетной точки' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 200 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'ИД расчетной точки' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Поле объекта' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 80 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Расчетная формула' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 115 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Обозначение аргумента' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'ИД объекта' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 85 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Имя' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 180 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Назначение' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 170 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT   1 ID, title1, title2, title3, title4, title5, title6, title7, title8, title9, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM     (SELECT REPLACE(uniinterior2_pg.point_parents(p.mid, '/'), '/' || p.NAME || '/') title1, p.NAME title2, p.mid title3,
                    DECODE(pf.nmeas, 0, 'Общая', 1, 'A+', 2, 'A-', 3, 'R+', 5, 'R-', ' ') title4, pf.vformula title5, NULL title6, NULL title7, NULL title8,
                    NULL title9, p.PARENT, p.NAME, pf.nmeas, -1 norder
             FROM   points p, feeders f, pointformula pf
             WHERE  p.ind = 3 AND p.mid = f.mid AND f.ncalcpointtype = 6                                                             -- только Расчет по формуле
                    AND p.mid IN(SELECT     mid
                                 FROM       points
                                 CONNECT BY PRIOR mid = PARENT
                                 START WITH mid = an_id) AND p.mid = pf.mid(+)
             UNION ALL
             SELECT NULL title1, NULL title2, NULL title3, NULL title4, NULL title5, fp.vname title6, fp.vparam title7,
                    editformula_pg.get_objnamebyparam(fp.vparam) title8, fp.vmemo title9, p.PARENT, p.NAME, pf.nmeas, fp.norder
             FROM   points p, feeders f, pointformula pf, formulparams fp
             WHERE  p.ind = 3 AND p.mid = f.mid AND f.ncalcpointtype = 6                                                             -- только Расчет по формуле
                    AND p.mid IN(SELECT     mid
                                 FROM       points
                                 CONNECT BY PRIOR mid = PARENT
                                 START WITH mid = an_id) AND p.mid = pf.mid AND pf.nid = fp.nid)
   ORDER BY PARENT, NAME, nmeas, norder;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по тарифным зонам
 PROCEDURE proc_info_32(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 4;
  an_cntitle := 1;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Дата ввода в действие тарифного соглашения' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          200 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Время начала временной зоны' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Время окончания временной зоны' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 90 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Условное название временной зоны' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 95 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT   1 ID, DECODE(TO_CHAR(r.TIME, 'sssss'), 0, TO_CHAR(rl.switch_date, 'dd/mm/yyyy'), '') title1, TO_CHAR(r.TIME, 'hh24:mi') title2,
            TO_CHAR(r.endtime, 'hh24:mi') title3, DECODE(r.rate, 0, 'A (пик)', 1, 'B (день)', 2, 'C (ночь)', 3, 'D (полупик)', CHR(r.rate + 65)) title4,
            cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM     rate_list rl,
            rates r,
            (SELECT     util_pg.get_param(vparam, 1) nschedulelist
             FROM       GROUPS
             WHERE      util_pg.get_param(vparam, 1) IS NOT NULL
             CONNECT BY PRIOR gid = PARENT
             START WITH gid = an_id) g
   WHERE    rl.nschedulelist = g.nschedulelist AND rl.rid = r.rid
   ORDER BY rl.nschedulelist, rl.switch_date, r.TIME;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_info_37(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 7;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название COM портов' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 60 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Атрибуты COM порта' title1, 'Скорость' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 53 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Атрибуты COM порта' title1, 'Тип соединения' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          130 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Атрибуты COM порта' title1, 'Разрядность (бит)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Атрибуты COM порта' title1, 'Кол-во стоп. бит' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Атрибуты COM порта' title1, 'Контроль четности' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Список каналов, использующих этот COM порт' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 810 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT   1 ID, cp.NAME title1, cp.baudrate title2, cpt.vname title3, cp.bytesize title4, cp.stopbits title5,
            DECODE(cp.parity, 0, 'нет', 1, 'четность', 2, 'нечетность') title6, uniinterior2_pg.sum_channels(cp.com_id) title7, cn_white datacl, 1 nlock,
            '' vmasks, 0 srt
   FROM     comports cp, comporttype cpt
   WHERE    cp.ncomtype = cpt.ncomtype
   ORDER BY util_pg.allnumber_f(util_pg.get_param(cp.NAME, 2, 'COM')), cp.NAME;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по задаче "План опроса" отчет "Общий список каналов"
 PROCEDURE proc_info_38(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 14;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название канала связи' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 220 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Блокировка канала (0/1)' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 68 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Ид канала' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock,
          63 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Протокол' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock,
          115 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Порт' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 47 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Строка инициализации модема' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_left dataal, 1 nlock, 285 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Адрес УСД' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          40 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Пауза между циклами опроса' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Кол. попыток соединения' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal,
          1 nlock, 63 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Пауза' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock,
          40 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Время ожидания установки соединения' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 63 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Время начала опроса' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal,
          1 nlock, 59 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Время окончания опроса' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal,
          1 nlock, 59 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры канала' title1, 'Не читать текущие сутки (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_center dataal, 1 nlock, 47 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT 1 ID, p.cname title1, c.blocking title2, c.cid title3, p.NAME title4, cp.NAME title5, c.init_str title6, c.addr title7, c.cycle_tout title8,
          c.retries title9, c.retries_tout title10, c.nwait title11, TO_CHAR(c.dstart, 'hh24:mi') title12, TO_CHAR(c.dend, 'hh24:mi') title13,
          c.nnotreadcurr title14, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   (SELECT     LPAD('  ', 2 *(LEVEL - 1)) || NAME cname, mid
           FROM       points
           CONNECT BY PRIOR mid = PARENT
           START WITH mid IN(SELECT mid
                             FROM   srv)
           ORDER SIBLINGS BY NAME) p,
          channels c,
          protocols p,
          comports cp
   WHERE  p.mid = c.cid(+) AND c.protocol_id = p.protocol_id(+) AND c.com_id = cp.com_id(+);
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по задаче "План опроса" отчет "Параметры и перечень точек, входящих в канал"
 PROCEDURE proc_info_39(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 15;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название (подстанция/фидер)' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock,
          480 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Ид объекта' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          55 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Блок. опроса (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal,
          1 nlock, 45 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Связной номер' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'А+' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 30 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'А-' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 30 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'R+' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 30 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'R-' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 30 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'ТЭГ' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 30 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Доп. инфо' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock,
          220 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Точка УСД' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock,
          43 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Отсутствие данных (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_center dataal, 1 nlock, 60 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Блок. кор. данных (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_center dataal, 1 nlock, 45 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Врем. пояс (зима)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal,
          1 nlock, 40 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основные параметры фидера' title1, 'Врем. пояс (лето)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal,
          1 nlock, 40 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT 1 ID, pp.NAME || '/' || p.NAME title1, f.mid title2, f.nblock title3, f.canal title4, f.er_position title5, f.ed_position title6,
          f.q1_position title7, f.q3_position title8, p.tag title9, f.vinfo title10, f.nusd title11, f.ndataabsence title12, f.nlockcorrecttime title13,
          f.ntimezonew title14, f.ntimezones title15, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   (SELECT     mid
           FROM       points p
           CONNECT BY PRIOR mid = PARENT
           START WITH mid = an_id) chnls,
          points pp,
          points p,
          channels c,
          chanpoint cp,
          feeders f
   WHERE  c.cid = chnls.mid AND c.cid = cp.cid AND cp.mid = p.mid AND p.PARENT = pp.mid AND p.mid = f.mid;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- НСИ по задаче "Формирование макетов" отчет "Общий список макетов"
 PROCEDURE proc_info_40(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 15;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название макетов, входящих в них групп и точек учета      (# - группы, ' || CHR(38) || CHR(38) || ' - точки)' title1, '' title2,
          cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 300 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'ИД объекта' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры макета' title1, 'Процедура формирования макета' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal,
          1 nlock, 270 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры макета' title1, 'Вып. невыполненные (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal,
          1 nlock, 87 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры макета' title1, 'Блокировка (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          66 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры макета' title1, 'Сдвиг времени (мин.)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock,
          48 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры группы' title1, 'Код строки макета' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock,
          75 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры группы' title1, 'Итоговая группа (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          52 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Коэфф-т вхождения' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 63 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип измерения по группам и ТУ' title1, 'A+ (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип измерения по группам и ТУ' title1, 'A- (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип измерения по группам и ТУ' title1, 'R+ (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип измерения по группам и ТУ' title1, 'R- (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock,
          30 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип измерения по группам и ТУ' title1, 'Сальдо A (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal,
          1 nlock, 40 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Тип измерения по группам и ТУ' title1, 'Сальдо R (0/1)' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal,
          1 nlock, 40 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT     1 ID, title1, title2, title3, title4, title5, title6, title7, title8, title9, title10, title11, title12, title13, title14, title15,
              cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM       (                                                                                                                                              --1
               SELECT 0 PARENT, nmaket mid, m.vname title1, nmaket title2, d.vname title3, ncycle title4, nblock title5, nshift title6, NULL title7,
                      NULL title8, NULL title9, NULL title10, NULL title11, NULL title12, NULL title13, NULL title14, NULL title15, 1 title16
               FROM   makets m, deportprocedures d
               WHERE  m.nprocedure = d.nprocedure AND d.ntype = 0
               --EXISTS (SELECT * FROM DEPORTPROCEDURES WHERE nprocedure=m.nprocedure AND ntype=0)
               UNION ALL
               --2 4
               SELECT mg.nmaket PARENT, mg.ngroup mid, '#' || mg.vname title1, mg.ngroup title2, NULL title3, NULL title4, NULL title5, NULL title6,
                      mg.vcode title7, makets_pg.isagregat(mg.ngroup) title8, NULL title9, NULL title10, NULL title11, NULL title12, NULL title13, NULL title14,
                      NULL title15, 24 title16
               FROM   maketgroups mg, makets m
               WHERE  m.nmaket = mg.nmaket
               UNION ALL
               -- 5
               SELECT mf.ngroup PARENT, -mg.ngroup mid, '#' || mg.vname title1, mg.ngroup title2, NULL title3, NULL title4, NULL title5, NULL title6,
                      mg.vcode title7, makets_pg.isagregat(mg.ngroup) title8, mf.nsign title9, NULL title10, NULL title11, NULL title12, NULL title13,
                      NULL title14, NULL title15, 5 title16
               FROM   maketgroups mg, makets m, maketformulas mf
               WHERE  m.nmaket = mg.nmaket AND mg.ngroup = mf.nsubgroup
               UNION ALL
               -- 3
               SELECT mp.ngroup PARENT, mp.mid, CHR(38) || CHR(38) || util_pg.get_pointname(mp.mid, 1) title1, mp.mid title2, NULL title3, NULL title4,
                      NULL title5, NULL title6, NULL title7, NULL title8, mp.nkc title9, DECODE(mp.ntype, 1, 1, 0) title10, DECODE(mp.ntype, 2, 1, 0) title11,
                      DECODE(mp.ntype, 3, 1, 0) title12, DECODE(mp.ntype, 4, 1, 0) title13, DECODE(mp.ntype, 5, 1, 0) title14, DECODE(
                                                                                                                               mp.ntype,
                                                                                                                               6, 1,
                                                                                                                               0
                                                                                                                              ) title15, 3 title16
               FROM   maketpoints mp, points p, maketgroups mg
               WHERE  mg.ngroup = mp.ngroup AND p.mid = mp.mid AND EXISTS(SELECT *
                                                                          FROM   makets
                                                                          WHERE  nmaket = mg.nmaket))
   CONNECT BY PRIOR mid = PARENT
   START WITH PARENT = 0
   ORDER SIBLINGS BY title1;
 END;

-----------------------------------------------------------------------------------------------------------------------
 -- НСИ по задаче "План рассылки макетов" отчет "Расписание плана рассылки макетов"
 PROCEDURE proc_info_41(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
 BEGIN
  an_cnfixcol := 12;
  an_cntitle := 1;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Название задачи по рассылке макетов' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 200 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Ид объекта' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 48 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Блокировка (0/1)' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 65 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Название макета, который должен рассылаться' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock,
          150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Способ передачи данных' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 55 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Адрес получателя' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 240 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Основной канал' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 130 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Параметры отсылки' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Время начала' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 46 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Время окончания' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 59 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Кол. попыток' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Пауза (мин.)' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_center dataal, 1 nlock, 50 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT   1 ID, d.vname title1, d.ndeportation title2, d.nblock title3, m.vname title4, DECODE(d.ntype, 0, 'E-mail', 1, 'FTP', 2, 'Сеть') title5,
            d.vaddress title6, dp.vname title7, d.vparam title8, TO_CHAR(d.dfrom, 'hh24:mi') title9, TO_CHAR(d.dtill, 'hh24:mi') title10, d.nretries title11,
            d.nretries_tout title12, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM     deportation d, makets m, deportation dp
   WHERE    d.nmaket = m.nmaket(+) AND d.nparent = dp.ndeportation(+)
   ORDER BY d.vname;
 END;

-----------------------------------------------------------------------------------------------------------------------
 -- 24-часовой отчет Центрэнерго
 PROCEDURE proc_info_43(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 1;
  an_cntitle := 2;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'Часы' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 34 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT ID, title1, title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 47 nwidth, '' vmasks
   FROM   (SELECT   TO_NUMBER(util_pg.get_param(vparam, 1, ';')) ID, NVL(short_name, NAME) title1, get_name_cols(util_pg.get_param(vparam, 2, ';'),
                                                                                                   t.rn) title2
           FROM     GROUPS g,
                    (SELECT ROWNUM rn
                     FROM   dict
                     WHERE  ROWNUM <= 3) t
           WHERE    PARENT = an_id AND mid IS NULL AND t.rn <= get_cnt_cols(util_pg.get_param(vparam, 2, ';'))
           ORDER BY ID, title1, t.rn);

  OPEN row_t FOR
   SELECT 1 ID, ROWNUM title1, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   dict
   WHERE  ROWNUM <= 24;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_info_44(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur, av_param VARCHAR2
 ) IS
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  lv_param            NUMBER DEFAULT NVL(util_pg.allnumber_f(util_pg.get_param(av_param, 2, ';')), 1);
  ln_schedule         NUMBER DEFAULT 6;
 BEGIN
  an_cnfixcol := 1;
  an_cntitle := 2;

  SELECT DECODE(ln_locksum, 0, 4, 0)
  INTO   an_cnfooter
  FROM   DUAL;

  OPEN col_t FOR
   SELECT -1 ID, 'Дата' title1, 'Смена' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 115 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT ID, DECODE(lv_param, 1, 'Выработка электроэнергии Углегорской ТЭС, кВт.ч', 2, 'Расход электроэнергии на СН Углегорской ТЭС, кВт.ч', ' ') title1,
          title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   (SELECT   TO_NUMBER(util_pg.get_param(vparam, 1, ';')) ID, NAME title2
           FROM     GROUPS g
           WHERE    PARENT = an_id AND mid IS NULL
           ORDER BY ID, title2);

  OPEN row_t FOR
   SELECT ROWNUM ID, ROWNUM || ' смена' title1, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM   dict
   WHERE  ROWNUM <= (SELECT COUNT(*)
                     FROM   rates
                     WHERE  rid = (SELECT a.rid
                                   FROM   rate_list a
                                   WHERE  a.nschedulelist = ln_schedule AND a.switch_date = (SELECT MAX(switch_date)
                                                                                             FROM   rate_list
                                                                                             WHERE  nschedulelist = ln_schedule)))
   UNION ALL
   SELECT -1 ID, 'Всего за сутки:' title1, cn_yellow datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0
   UNION ALL
   SELECT -1 ID, 'С начала месяца:' title1, cn_aqua datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0
   UNION ALL
   SELECT -1 ID, 'Дата, формат' title1, cn_btnface datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0
   UNION ALL
   SELECT -1 ID, TO_CHAR(ad_from, 'dd.mm.yyyy') title1, cn_btnface datacl, 1 nlock, '' vmasks, 0 srt
   FROM   DUAL
   WHERE  ln_locksum = 0;
 END;

