 PROCEDURE proc_value_31(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  ln_cnt              NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_cnt
  FROM   points p, feeders f, meters m
  WHERE  p.mid IN(SELECT     mid
                  FROM       points
                  CONNECT BY PRIOR mid = PARENT
                  START WITH mid = an_id) AND p.mid = f.mid AND p.mid = m.mid(+) AND m.entype(+) = 7;

  FOR i IN 1 .. ln_cnt LOOP
   data_t(data_t.COUNT + 1) := NULL;
  END LOOP;
 END;

