 PROCEDURE proc_value_35(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  ln_cnt              NUMBER;
 BEGIN
  SELECT     COUNT(*)
  INTO       ln_cnt
  FROM       GROUPS g
  CONNECT BY PRIOR gid = PARENT
  START WITH gid = an_id;

  FOR i IN 1 .. ln_cnt LOOP
   data_t(data_t.COUNT + 1) := NULL;
  END LOOP;
 END;

