 PROCEDURE proc_value_33(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number) IS
  ln_cnt              NUMBER;
 BEGIN
  SELECT     COUNT(*)
  INTO       ln_cnt
  FROM       GROUPS g
  CONNECT BY PRIOR gid = PARENT
  START WITH gid = an_id;

  FOR i IN 1 .. ln_cnt LOOP
   data_t(data_t.COUNT + 1) := NULL;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_value_43(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, av_param VARCHAR2) IS
  ln_cnt              NUMBER := 0;
  ln_rnd              NUMBER := 0;
  ln_koeff            NUMBER := 1000;
  ln_currkoef         NUMBER := 1;
  ln_vcoef1           NUMBER := 1.905;
  ln_vcoef2           NUMBER := 5.716;

  CURSOR lcur_pa(lc_gid NUMBER, lc_date DATE) IS
   SELECT   ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)) * DECODE(g.inverted, 'y', -1, 1)), 0)
             / ln_koeff, ln_rnd) pa,
            TO_CHAR(TRUNC(h.date_time - 1 / 86400, 'hh24'), 'hh24') dt
   FROM     halfhour h, GROUPS g
   WHERE    g.gid IN(SELECT     gid
                     FROM       GROUPS
                     WHERE      mid IS NOT NULL
                     CONNECT BY PRIOR gid = PARENT
                     START WITH gid = lc_gid) AND g.mid = h.mid AND h.date_time > TRUNC(lc_date) AND h.date_time <= TRUNC(lc_date) + 1
   GROUP BY TRUNC(h.date_time - 1 / 86400, 'hh24')
   ORDER BY dt;

  CURSOR lcur_pp(lc_gid NUMBER, lc_date DATE) IS
   SELECT   ROUND(NVL(SUM(util_pg.sld(h.mid, h.q1 * DECODE(g.npartly, 2, 0, 1), h.q3 * DECODE(g.npartly, 1, 0, 1)) * DECODE(g.inverted, 'y', -1, 1)), 0)
             / ln_koeff, ln_rnd) pp,
            TO_CHAR(TRUNC(h.date_time - 1 / 86400, 'hh24'), 'hh24') dt
   FROM     halfhour h, GROUPS g
   WHERE    g.gid IN(SELECT     gid
                     FROM       GROUPS
                     WHERE      mid IS NOT NULL
                     CONNECT BY PRIOR gid = PARENT
                     START WITH gid = lc_gid) AND g.mid = h.mid AND h.date_time > TRUNC(lc_date) AND h.date_time <= TRUNC(lc_date) + 1
   GROUP BY TRUNC(h.date_time - 1 / 86400, 'hh24')
   ORDER BY dt;

  CURSOR lcur_voltcurrfreq(lc_gid NUMBER, lc_date DATE) IS
   SELECT   NVL(MAX(h.volt), 0) volt1, NVL(MAX(h.volt2), 0) volt2, NVL(MAX(h.volt3), 0) volt3, ROUND(NVL(MAX(h.currento), 0) * ln_currkoef, ln_rnd) curr1,
            ROUND(NVL(MAX(h.curr2), 0) * ln_currkoef, ln_rnd) curr2, ROUND(NVL(MAX(h.curr3), 0) * ln_currkoef, ln_rnd) curr3,
            ROUND(NVL(MAX(h.freq), 0), 3) freq, TO_CHAR(TRUNC(h.date_time - 1 / 86400, 'hh24'), 'hh24') dt
   FROM     curr_power_arch h, GROUPS g
   WHERE    g.gid IN(SELECT     gid
                     FROM       GROUPS
                     WHERE      mid IS NOT NULL
                     CONNECT BY PRIOR gid = PARENT
                     START WITH gid = lc_gid) AND g.mid = h.mid AND h.date_time > TRUNC(lc_date) AND h.date_time <= TRUNC(lc_date) + 1
   GROUP BY TRUNC(h.date_time - 1 / 86400, 'hh24')
   ORDER BY dt;
 BEGIN
  -- считаем кол-во колонок в отчете
  FOR lc IN (SELECT TO_NUMBER(util_pg.get_param(vparam, 2, ';')) col_type
             FROM   GROUPS
             WHERE  PARENT = an_id) LOOP
   ln_cnt := ln_cnt + get_cnt_cols(lc.col_type);
  END LOOP;

  -- зануляем все ячейки
  FOR i IN 1 .. ln_cnt * 24 LOOP
   data_t(i) := NULL;
  END LOOP;

  -- заполнение массива
  FOR lc IN (SELECT ROWNUM col_num, val_type, col_type, gid
             FROM   (SELECT   t.rn val_type, TO_NUMBER(util_pg.get_param(g.vparam, 1, ';')) ord, NAME title1, util_pg.get_param(g.vparam, 2, ';') col_type,
                              g.gid
                     FROM     GROUPS g,
                              (SELECT ROWNUM rn
                               FROM   dict
                               WHERE  ROWNUM <= 3) t
                     WHERE    g.PARENT = an_id AND g.mid IS NULL AND t.rn <= get_cnt_cols(util_pg.get_param(g.vparam, 2, ';'))
                     ORDER BY ord, title1, t.rn)) LOOP
   IF lc.col_type = 1 OR lc.col_type = 2 THEN                                                                                        -- Pp, Pa или суммарная Pa
    IF lc.val_type = 1 THEN                                                                                                              -- Pa или суммарная Pa
     FOR lc1 IN lcur_pa(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.pa;
     END LOOP;
    ELSIF lc.val_type = 2 THEN                                                                                                                             -- Pp
     FOR lc1 IN lcur_pp(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.pp;
     END LOOP;
    END IF;
   ELSIF lc.col_type = 3 THEN                                                                                                      -- Частота (теперь заполняем)
    FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
     data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.freq;
    END LOOP;
   ELSIF lc.col_type = 4 THEN                                                                            -- Ис. ш. кв. 110 330 (теперь заполняем) старый вариант
    IF lc.val_type = 1 THEN                                                                                                                              -- 110
     FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := ROUND(lc1.volt1, ln_rnd);
     END LOOP;
    ELSIF lc.val_type = 2 THEN                                                                                                                            -- 330
     FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := ROUND(lc1.volt2, ln_rnd);
     END LOOP;
    END IF;
   ELSIF lc.col_type = 41 THEN                                                                                   -- Ис. ш. кв. 110 (с умножением на коэффициент)
    FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
     data_t(ln_cnt * lc1.dt + lc.col_num) := ROUND(lc1.volt1 * ln_vcoef1, ln_rnd);
    END LOOP;
   ELSIF lc.col_type = 42 THEN                                                                                   -- Ис. ш. кв. 330 (с умножением на коэффициент)
    FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
     data_t(ln_cnt * lc1.dt + lc.col_num) := ROUND(lc1.volt1 * ln_vcoef2, ln_rnd);
    END LOOP;
   ELSIF lc.col_type = 5 THEN                                                                                                                         -- I Pa Pp
    IF lc.val_type = 1 THEN                                                                                                                                -- I
     SELECT DECODE(MAX(current1), 0, 1, MAX(current1))
     INTO   ln_currkoef
     FROM   feeders
     WHERE  mid IN(SELECT     mid
                   FROM       GROUPS
                   WHERE      mid IS NOT NULL
                   CONNECT BY PRIOR gid = PARENT
                   START WITH gid = lc.gid);

     FOR lc1 IN (SELECT TRUNC(ad_from) + ROWNUM / 24 dat, ROWNUM - 1 dt
                 FROM   dict
                 WHERE  ROWNUM <= 24) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := get_hour_curr(lc.gid, lc1.dat) * ln_currkoef;
     END LOOP;
    ELSIF lc.val_type = 2 THEN                                                                                                                             -- Pa
     FOR lc1 IN lcur_pa(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.pa;
     END LOOP;
    ELSIF lc.val_type = 3 THEN                                                                                                                             -- Pp
     FOR lc1 IN lcur_pp(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.pp;
     END LOOP;
    END IF;
   ELSIF lc.col_type = 6 THEN                                                                                              --  I110 I330 Iоб. (теперь заполняем)
    SELECT DECODE(MAX(current1), 0, 1, MAX(current1))
    INTO   ln_currkoef
    FROM   feeders
    WHERE  mid IN(SELECT     mid
                  FROM       GROUPS
                  WHERE      mid IS NOT NULL
                  CONNECT BY PRIOR gid = PARENT
                  START WITH gid = lc.gid);

    IF lc.val_type = 1 THEN                                                                                                                              -- 110
     FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.curr1;
     END LOOP;
    ELSIF lc.val_type = 2 THEN                                                                                                                            -- 330
     FOR lc1 IN lcur_voltcurrfreq(lc.gid, ad_from) LOOP
      data_t(ln_cnt * lc1.dt + lc.col_num) := lc1.curr2;
     END LOOP;
    END IF;
   ELSIF lc.col_type = 7 THEN                                                                                                                     -- температура
    NULL;
   ELSE                                                                                                                                -- неопределенные колонки
    NULL;
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE proc_value_44(an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t IN OUT common_pg.tt_number, av_param VARCHAR2) IS
  ln_cnt              NUMBER;
  ln_schedule         NUMBER DEFAULT 6;
  ln_locksum          NUMBER DEFAULT uniinterior_pg.f_locksum(an_fid);
  ln_smena_cnt        NUMBER;
  ln_col_cnt          NUMBER;
  ln_currow           NUMBER;
  ld_from             DATE;
  ld_till             DATE;
  ln_rnd              NUMBER DEFAULT 0;
 BEGIN
  ld_from := TRUNC(ad_from);
  ld_till := TRUNC(ad_from) + 1;

  -- кол-во смен в отчете
  SELECT COUNT(*)
  INTO   ln_smena_cnt
  FROM   rates
  WHERE  rid = (SELECT a.rid
                FROM   rate_list a
                WHERE  a.nschedulelist = ln_schedule AND a.switch_date = (SELECT MAX(switch_date)
                                                                          FROM   rate_list
                                                                          WHERE  nschedulelist = ln_schedule));

  -- кол-во колонок в отчете
  SELECT COUNT(*)
  INTO   ln_col_cnt
  FROM   GROUPS
  WHERE  PARENT = an_id AND mid IS NULL;

  -- зануляем весь массив данных
  IF ln_locksum = 0 THEN
   FOR i IN 1 .. ln_col_cnt *(ln_smena_cnt + 2) LOOP
    data_t(i) := NULL;
   END LOOP;
  ELSE
   FOR i IN 1 .. ln_col_cnt * ln_smena_cnt LOOP
    data_t(i) := NULL;
   END LOOP;
  END IF;

  FOR lc IN (SELECT ROWNUM col_num, gid, vp
             FROM   (SELECT   gid, TO_NUMBER(util_pg.get_param(vparam, 2, ';')) vp
                     FROM     GROUPS
                     WHERE    PARENT = an_id
                     ORDER BY TO_NUMBER(util_pg.get_param(vparam, 1, ';')), NAME)) LOOP
   -- записываем посменные показатели
   ln_currow := 0;

   IF lc.vp IN(3, 7) THEN
    ln_rnd := 3;
   ELSE
    ln_rnd := 0;
   END IF;

   FOR lc1 IN (SELECT   ROUND(SUM(tmp.er), ln_rnd) val, r.rate
               FROM     (SELECT   h.date_time,
                                  ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))
                                     * DECODE(g.inverted, 'y', -1, 1)),
                                    0),
                                   3) er
                         FROM     halfhour h, GROUPS g
                         WHERE    g.PARENT = lc.gid AND g.mid = h.mid AND h.date_time > ld_from AND h.date_time <= ld_till
                         GROUP BY h.date_time) tmp,
                        rates r
               WHERE    TO_CHAR(tmp.date_time - 1 / 86400, 'sssss') > TO_CHAR(r.TIME, 'sssss')
                        AND TO_CHAR(tmp.date_time - 1 / 86400, 'sssss') <= TO_CHAR(r.endtime, 'sssss')
                        AND r.rid = (SELECT a.rid
                                     FROM   rate_list a
                                     WHERE  a.nschedulelist = ln_schedule AND a.switch_date = (SELECT MAX(switch_date)
                                                                                               FROM   rate_list
                                                                                               WHERE  nschedulelist = ln_schedule))
               GROUP BY r.rate, TO_CHAR(r.TIME, 'sssss')
               ORDER BY TO_CHAR(TIME, 'sssss')) LOOP
    ln_currow := ln_currow + 1;
    EXIT WHEN ln_currow > ln_smena_cnt;
    data_t((ln_currow - 1) * ln_col_cnt + lc.col_num) := lc1.val;

    IF ln_locksum = 0 THEN                                                        -- теперь сумма за сутки считается здесь, чтоб учитывать округление слагаемых
     data_t(ln_smena_cnt * ln_col_cnt + lc.col_num) := util_pg.sumn(data_t(ln_smena_cnt * ln_col_cnt + lc.col_num), lc1.val);
    END IF;
   END LOOP;

   -- записываем суммарные показатели
   IF ln_locksum = 0 THEN
    -- всего за сутки
    /*SELECT ROUND (NVL (SUM (util_pg.sld (h.mid, h.er * DECODE (g.npartly, 2, 0, 1),
                                                h.ed * DECODE (g.npartly, 1, 0, 1)) * DECODE (g.inverted,'y', -1,1)),0),ln_rnd)
      INTO data_t (ln_smena_cnt*ln_col_cnt + lc.col_num)
      FROM halfhour h, GROUPS g
     WHERE g.parent = lc.gid AND g.mid=h.mid
           AND h.date_time>ld_from AND h.date_time<=ld_till;    */
    -- с начала месяца
    SELECT ROUND(NVL(SUM(util_pg.sld(h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)) * DECODE(g.inverted, 'y', -1, 1)), 0),
            ln_rnd)
    INTO   data_t((ln_smena_cnt + 1) * ln_col_cnt + lc.col_num)
    FROM   halfhour h, GROUPS g
    WHERE  g.PARENT = lc.gid AND g.mid = h.mid AND h.date_time > TRUNC(ad_from, 'mm') AND h.date_time <= ld_till;
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Отображение точек, по которым были использованы данные не осн. прибора
 PROCEDURE proc_info_46(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, an_cnfixcol IN OUT NUMBER, an_cntitle IN OUT NUMBER, an_cnfooter IN OUT NUMBER,
 col_t IN OUT common_pg.tcur, row_t IN OUT common_pg.tcur
 ) IS
 BEGIN
  an_cnfixcol := 8;
  an_cntitle := 1;
  an_cnfooter := 0;

  OPEN col_t FOR
   SELECT -1 ID, 'ИД точки' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_center dataal, 1 nlock, 70 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Наименование' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 270 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Дата' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 110 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Источник' title1, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 150 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, DECODE(ROWNUM, 1, 'Расход A+', 2, 'Расход A-', 3, 'Расход Q1', 4, 'Расход Q3') title1, cn_btnface titlecl, cn_center titleal, cn_white datacl,
          cn_right dataal, 1 nlock, 120 nwidth, '' vmasks
   FROM   dict
   WHERE  ROWNUM <= 4
   UNION ALL
   SELECT -1 ID, '' title1, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_left dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  OPEN row_t FOR
   SELECT   1 ID, p.mid title1, p.NAME title2, TO_CHAR(h.date_time, 'dd.mm.yyyy hh24:mi:ss') title3,
            DECODE(
             qm_pg.gbt(h.vqm, 22),
             '0', 'Нет данных',
             '1', 'Осн.прибор',
             '2', 'Дуб.прибор',
             '3', 'ОИК',
             '4', 'Ручн.ввод',
             '5', 'Макет',
             '6', 'Прибор ОВ',
             '7', 'Рез.вычисл автоматич.',
             '8', 'Рез.вычисл с замещением',
             'UNDEFINED'
            ) title4,
            h.er title5, h.ed title6, h.q1 title7, h.q3 title8, cn_white datacl, 1 nlock, '' vmasks, 0 srt
   FROM     halfhour h, points p
   WHERE    p.ind = 4 AND p.mid IN(SELECT     mid
                                   FROM       GROUPS g
                                   CONNECT BY PRIOR gid = PARENT
                                   START WITH gid = an_id) AND p.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till AND h.vqm IS NOT NULL
            AND qm_pg.gbt(h.vqm, 22) <> '1' AND(h.er IS NOT NULL OR h.ed IS NOT NULL OR h.q1 IS NOT NULL OR h.q3 IS NOT NULL)
   ORDER BY p.NAME, h.date_time;
 END;

------------------------------------------------------------------------------------------------------------------------
-- возвращает все каналы порта
 FUNCTION sum_channels(an_port NUMBER)
  RETURN VARCHAR2 IS
  lv_channels         VARCHAR(4000);
  ln_parent           NUMBER DEFAULT -1;
 BEGIN
  FOR lc IN (SELECT   c.vname, p.mid, p.PARENT
             FROM     channels c, points p
             WHERE    c.com_id = an_port AND c.cid = p.mid
             ORDER BY p.PARENT, c.vname) LOOP
   IF ln_parent <> lc.PARENT THEN
    lv_channels := lv_channels || point_parents(lc.PARENT, ': ');
    ln_parent := lc.PARENT;
   END IF;

   lv_channels := lv_channels || lc.vname || '; ';
  END LOOP;

  lv_channels := RTRIM(lv_channels, '; ');
  RETURN lv_channels;
 END;

------------------------------------------------------------------------------------------------------------------------
-- возвращает кол-во колонок для группы в отчете 43
 FUNCTION get_cnt_cols(an_type NUMBER)
  RETURN NUMBER IS
  ln_result           NUMBER DEFAULT 1;
 BEGIN
  SELECT DECODE(an_type, 1, 2, 2, 1, 3, 1, 4, 2, 5, 3, 6, 2, 7, 1, 1)
  INTO   ln_result
  FROM   DUAL;

  RETURN ln_result;
 END;

------------------------------------------------------------------------------------------------------------------------
-- возвращает title2 для группы в отчете 43
 FUNCTION get_name_cols(an_type NUMBER, an_col NUMBER)
  RETURN VARCHAR2 IS
  lv_result           VARCHAR2(40) := '';
 BEGIN
  SELECT DECODE(
          an_type,
          1, DECODE(an_col, 1, 'Pa, МВт', 2, 'Pp, МВт', ''),
          2, '',
          3, '',
          4, DECODE(an_col, 1, '110', 2, '330', ''),
          41, DECODE(an_col, 1, '110', ''),
          42, DECODE(an_col, 1, '330', ''),
          5, DECODE(an_col, 1, 'I, A', 2, 'Pa, МВт', 3, 'Pp, МВт', ''),
          6, DECODE(an_col, 1, 'I110, A', 2, 'I330, A', 3, 'Iоб., A', ''),
          7, DECODE(an_col, 1, 'гр.С', ''),
          ''
         )
  INTO   lv_result
  FROM   DUAL;

  RETURN lv_result;
 END;

------------------------------------------------------------------------------------------------------------------------
-- возвращает ток за указанный час для группы в отчете 43
 FUNCTION get_hour_curr(an_gid NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_result           NUMBER;
 BEGIN
  FOR lc IN (SELECT   mid, ind, NAME, norder
             FROM     (SELECT     mid, ind, NAME, norder                                                              -- зеленые точки в группе и синие под ними
                       FROM       points
                       START WITH mid IN(SELECT mid
                                         FROM   GROUPS
                                         WHERE  PARENT = an_gid) AND ind = 4
                       CONNECT BY PARENT = PRIOR mid
                       UNION ALL
                       SELECT mid, ind, NAME, 10000 norder
                       FROM   points                                                                                                     -- синие точки в группе
                       WHERE  mid IN(SELECT mid
                                     FROM   GROUPS
                                     WHERE  PARENT = an_gid) AND ind = 3)
             ORDER BY ind DESC, norder, NAME) LOOP
   SELECT MAX(curr2)
   INTO   ln_result                                                                                                                    -- заменил на ток фазы В
   FROM   curr_power_arch
   WHERE  mid = lc.mid AND date_time = (SELECT MIN(date_time)
                                        FROM   curr_power_arch
                                        WHERE  mid = lc.mid AND date_time > ad_date AND date_time <= ad_date + 1 / 24);

   IF ln_result IS NOT NULL THEN
    RETURN ln_result;
   END IF;
  END LOOP;

  RETURN ln_result;
 END;

------------------------------------------------------------------------------------------------------------------------
-- возвращает родителей точки
 FUNCTION point_parents(an_mid NUMBER, av_delimiter VARCHAR2)
  RETURN VARCHAR2 IS
  lv_parents          VARCHAR(4000);
 BEGIN
  FOR lc IN (SELECT     NAME
             FROM       points
             WHERE      cod IS NOT NULL                                                                                                     --and mid <> an_mid
             CONNECT BY PRIOR PARENT = mid
             START WITH mid = an_mid
             ORDER BY   LEVEL DESC) LOOP
   lv_parents := lv_parents || lc.NAME || av_delimiter;
  END LOOP;

  RETURN lv_parents;
 END;
------------------------------------------------------------------------------------------------------------------------
END;
/


