 FUNCTION get_sql48(an_fid NUMBER, an_ispoint NUMBER, an_cnfixcol OUT NUMBER)
  RETURN VARCHAR2 IS
  cn_shift   CONSTANT NUMBER := cn_shift48;
  lv_title1           VARCHAR(2000) := uniinterior_pg.f_parenttitle(an_fid, 1);
  lv_title2           VARCHAR(2000) := uniinterior_pg.f_parenttitle(an_fid, 2);
  ln_start            NUMBER := 1;
  lv_sql              VARCHAR(4000);
  lv_sqlselect        VARCHAR(4000);
  lv_sqltable         VARCHAR(4000);
  lv_sqlwhere         VARCHAR(4000);
  lv_sqlorder         VARCHAR(4000) := ' ORDER BY ';
  lv_tab              VARCHAR(32) := 'POINTS';
  lv_col              VARCHAR(32) := 'MID';
 BEGIN
  IF an_ispoint = 0 THEN
   lv_tab := 'GROUPS';
   lv_col := 'GID';
  END IF;

  lv_title1 := NVL(lv_title1, lv_title2);                                                                            --Выравниваем, если задали только lv_title2

  IF lv_title1 IS NOT NULL THEN
   ln_start := ln_start + 1;

   IF lv_title2 IS NOT NULL THEN
    ln_start := ln_start + 1;
   END IF;
  END IF;

  an_cnfixcol := cn_shift +(ln_start - 1);

  FOR i IN 1 .. ln_start LOOP
   lv_sqlorder := lv_sqlorder ||(i + 1) || ',';
   lv_sqlselect := lv_sqlselect || 'p' ||((ln_start + 1) - i) || '.NAME title' || i || ',';
   lv_sqltable := lv_sqltable || ',' || lv_tab || ' p' || i;

   IF i > 1 THEN
    lv_sqlwhere := lv_sqlwhere || ' AND p' ||(i - 1) || '.parent=p' || i || '.' || lv_col || '(+)';
   END IF;
  END LOOP;

  lv_sqlorder := lv_sqlorder || '1';
  lv_sql :=
      'SELECT p1.'
   || lv_col
   || ' ID, '
   || lv_sqlselect
   || ' m.mtrsn title'
   || (ln_start + 1)
   || ', f.kc title'
   || (ln_start + 2)
   || ', '
   || cn_white
   || ' datacl, 1 nlock, '''' vmasks  
			FROM feeders f'
   || lv_sqltable
   || ',meters m
			WHERE p1.'
   || lv_col
   || ' in (SELECT '
   || lv_col
   || ' FROM '
   || lv_tab
   || ' CONNECT BY PRIOR '
   || lv_col
   || ' = PARENT START WITH '
   || lv_col
   || ' = :an_id) AND f.mid = p1.mid'
   || lv_sqlwhere
   || ' AND f.mid = m.mid(+) AND m.entype(+) = 7'
   || lv_sqlorder;
  RETURN lv_sql;
 END;

