  lv_col              VARCHAR(32) := 'MID';
 BEGIN
  IF an_ispoint = 0 THEN
   lv_tab := 'GROUPS';
   lv_col := 'GID';
  END IF;

  lv_title1 := NVL(lv_title1, lv_title2);                                                                            --Выравниваем, если задали только lv_title2

  IF lv_title1 IS NOT NULL THEN
   ln_start := ln_start + 1;

   IF lv_title2 IS NOT NULL THEN
    ln_start := ln_start + 1;
   END IF;
  END IF;

  an_cnfixcol := cn_shift +(ln_start - 1);

  FOR i IN 1 .. ln_start LOOP
   lv_sqlorder := lv_sqlorder ||(i + 1) || ',';
   lv_sqlselect := lv_sqlselect || 'p' ||((ln_start + 1) - i) || '.NAME title' || i || ',';
   lv_sqltable := lv_sqltable || ',' || lv_tab || ' p' || i;

   IF i > 1 THEN
    lv_sqlwhere := lv_sqlwhere || ' AND p' ||(i - 1) || '.parent=p' || i || '.' || lv_col || '(+)';
   END IF;
  END LOOP;

  lv_sqlorder := lv_sqlorder || '1';
  lv_sql :=
      'SELECT p1.'
   || lv_col
   || ' ID, '
   || lv_sqlselect
   || ' to_char((select max(date_time) date_time from billorg where mid=p1.mid),''dd.mm.yyyy hh24:mi'') title'
   || (ln_start + 1)
   || ', l.STATE_DESCR title'
   || (ln_start + 2)
   || ', (select MAX(ls.state_descr)KEEP (DENSE_RANK LAST ORDER BY ls.trial NULLS FIRST) as state_descr from last_save ls,chanpoint cp where cp.mid=p1.mid and cp.cid=ls.mid group by cp.mid) title'
   || (ln_start + 3)
   || ', fe.vnote title'
   || (ln_start + 4)
   || ', '
   || cn_white
   || ' datacl, 1 nlock, '''' vmasks  
			FROM meters m'
   || lv_sqltable
   || ',last_save l,feeders fe	WHERE p1.'
   || lv_col
   || ' in  (SELECT '
   || lv_col
   || ' FROM '
   || lv_tab
   || ' CONNECT BY PRIOR '
   || lv_col
   || ' = PARENT START WITH '
   || lv_col
   || ' = :an_id)'
   || lv_sqlwhere
   || ' AND p1.mid = m.mid(+) AND m.entype(+) = 7 and p1.mid = l.mid(+) and p1.mid = fe.mid(+)
			and p1.mid not in (select mid from billorg where date_time>=:ad_date and date_time<:ad_date+1 and (erm is not null or edm is not null))
			and p1.mid in (select mid from chanpoint)'
   || lv_sqlorder;
--delete from tmp_vil; insert into tmp_vil values(lv_sql||' an_fid='||an_fid); commit;
  RETURN lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_sql52(an_fid NUMBER, an_ispoint NUMBER, an_cnfixcol OUT NUMBER)
  RETURN VARCHAR2 IS
  cn_shift   CONSTANT NUMBER := cn_shift52;
  lv_title1           VARCHAR(2000) := NVL(uniinterior_pg.f_parenttitle(an_fid, 1), 'Родительская папка 1');
  lv_title2           VARCHAR(2000) := NVL(uniinterior_pg.f_parenttitle(an_fid, 2), 'Родительская папка 2');
  ln_start            NUMBER := 1;
  lv_sql              VARCHAR(4000);
  lv_sqlselect        VARCHAR(4000);
  lv_sqltable         VARCHAR(4000);
  lv_sqlwhere         VARCHAR(4000);
  lv_sqlorder         VARCHAR(4000) := ' ORDER BY ';
  lv_tab              VARCHAR(32) := 'POINTS';
  lv_col              VARCHAR(32) := 'MID';
 BEGIN
  IF an_ispoint = 0 THEN
   lv_tab := 'GROUPS';
   lv_col := 'GID';
  END IF;

  lv_title1 := NVL(lv_title1, lv_title2);                                                                            --Выравниваем, если задали только lv_title2

  IF lv_title1 IS NOT NULL THEN
   ln_start := ln_start + 1;

   IF lv_title2 IS NOT NULL THEN
    ln_start := ln_start + 1;
   END IF;
  END IF;

  an_cnfixcol := cn_shift +(ln_start - 1);

  FOR i IN 1 .. ln_start LOOP
   lv_sqlorder := lv_sqlorder ||(i + 1) || ',';
   lv_sqlselect := lv_sqlselect || 'p' ||((ln_start + 1) - i) || '.NAME title' || i || ',';
   lv_sqltable := lv_sqltable || ',' || lv_tab || ' p' || i;

   IF i > 1 THEN
    lv_sqlwhere := lv_sqlwhere || ' AND p' ||(i - 1) || '.parent=p' || i || '.' || lv_col || '(+)';
   END IF;
  END LOOP;

  lv_sqlorder := lv_sqlorder || '1';
  lv_sql :=
      'select t.*,t.er1 title'||(ln_start + 1)||',t.er2 title'||(ln_start + 2)||',t.er2-t.er1 title'||(ln_start + 3)||',decode(t.er1,0,0,round(100*(t.er2-t.er1)/t.er1,2)) title'||(ln_start + 4)||' from (SELECT p1.'
   || lv_col
   || ' ID, '
   || lv_sqlselect
   || cn_white
   || ' datacl, 1 nlock, '''' vmasks, 
			round(util_pg.get_meterage_difference(p1.mid,:dstart1,:dend1,:ntype1,1,1)*f.kc) er1, 
			round(util_pg.get_meterage_difference(p1.mid,:dstart2,:dend2,:ntype2,1,1)*f.kc) er2 
			FROM feeders f'
   || lv_sqltable
   || ',meters m
			WHERE p1.'
   || lv_col
   || ' in (SELECT '
   || lv_col
   || ' FROM '
   || lv_tab
   || ' CONNECT BY PRIOR '
   || lv_col
   || ' = PARENT START WITH '
   || lv_col
   || ' = :an_id) AND f.mid = p1.mid'
   || lv_sqlwhere
   || ' AND f.mid = m.mid(+) AND m.entype(+) = 7) t where abs(t.er2-t.er1)>nvl(:nlim,0) and 100*abs(t.er2-t.er1)>=nvl(:nproc,10)*t.er1 '
   || lv_sqlorder;
  RETURN lv_sql;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE getinfo48(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER,
