 PROCEDURE getinfo49(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from IN OUT DATE, ad_till IN OUT DATE, an_cnfixcol OUT NUMBER, an_cntitle OUT NUMBER,
 an_cnfooter OUT NUMBER, col_t OUT common_pg.tcur, row_t OUT common_pg.tcur
 ) IS
  lv_sql              VARCHAR(4000);
  lv_addsql           VARCHAR(4000);
  cn_groupby CONSTANT NUMBER := 48;
  cn_rnd     CONSTANT NUMBER := 0;
  cn_kc      CONSTANT NUMBER := 1;
  ln_cnt              NUMBER;
 BEGIN
  an_cnfixcol := 6;
  an_cntitle := 1;
  an_cnfooter := 0;
  ad_from := util_pg.trunchh24_2(ad_from);
  ad_till := util_pg.trunchh24_2(ad_till);
  ln_cnt := ROUND(cn_groupby *(ad_till - ad_from));

  OPEN col_t FOR
   SELECT -1 ID, 'Наименование потребителя' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_left dataal, 1 nlock, 320 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Дата/время' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_btnface datacl, cn_right dataal, 1 nlock, 100 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Нагрузка, кВт|Факт' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 110 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Нагрузка, кВт|Лимит' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 110 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Нагрузка, кВт|Разница' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_red datacl, cn_right dataal, 1 nlock, 110 nwidth,
          '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, 'Ид. группы' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 90 nwidth, '' vmasks
   FROM   DUAL
   UNION ALL
   SELECT -1 ID, '' title1, '' title2, cn_btnface titlecl, cn_center titleal, cn_white datacl, cn_right dataal, 1 nlock, 1 nwidth, '' vmasks
   FROM   DUAL;

  IF an_ispoint = 0 AND an_id > 1 THEN
   lv_addsql := 'and gl.gid in (select gid from groups connect by prior gid=parent start with gid=' || an_id || ')';
  END IF;

  lv_sql :=
      'SELECT   1 ID, t.NAME title1, TO_CHAR(t.dat, ''dd.mm.yyyy hh24:mi'') title2, t.sld title3, t.lim title4, t.sld - t.lim title5, t.gid title6, '
   || cn_white
   || ' datacl,
            1 nlock, '''' vmasks, 0 srt
   FROM     (SELECT g.gid, g.NAME, dd.dt + 1 / '
   || cn_groupby
   || ' dat, '
   || cn_groupby
   || '/24 * ROUND(util_pg.get_saldo(g.gid, dd.dt, dd.dt + 1 / '
   || cn_groupby
   || ') / '
   || cn_kc
   || ', '
   || cn_rnd
   || ') sld,
                    ROUND(util_pg.get_grouplimit(g.gid, dd.dt + 1 / '
   || cn_groupby
   || ') / '
   || cn_kc
   || ', '
   || cn_rnd
   || ') lim
             FROM   GROUPS g,(SELECT :ld_from + (ROWNUM - 1) / '
   || cn_groupby
   || ' dt FROM DUAL CONNECT BY LEVEL <= '
   || ln_cnt
   || ') dd
             WHERE  g.gid IN(SELECT DISTINCT gl.gid FROM grouplimit gl WHERE gl.dstart <= :ld_till AND NVL(gl.nlimitcapm, 0) + NVL(gl.nlimitcape, 0) <> 0 '
   || lv_addsql
   || ' )) t
   WHERE    t.sld > t.lim
   ORDER BY t.NAME, t.gid, t.dat';

  OPEN row_t FOR lv_sql USING ad_from, ad_till;
 END;

