 PROCEDURE getvalue48(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t OUT common_pg.tt_number, quality OUT VARCHAR2, ad_forming_data OUT DATE
 ) IS
  cr_sel              common_pg.tcur;
  lv_sql              VARCHAR(4000);
  ln_tmp              NUMBER;
  ln_mid              NUMBER;
  ln_inv              NUMBER := 0;
 BEGIN
  lv_sql := 'select tt.id from (' || get_sql48(an_fid, an_ispoint, ln_tmp) || ') tt';

  OPEN cr_sel FOR lv_sql USING an_id;

  LOOP
   FETCH cr_sel
   INTO  ln_mid;

   EXIT WHEN cr_sel%NOTFOUND;

   IF an_ispoint = 0 THEN
    SELECT MAX(mid), MAX(DECODE(inverted, 'y', 1, 0))
    INTO   ln_mid, ln_inv
    FROM   GROUPS
    WHERE  gid = ln_mid;
   END IF;

   ln_tmp := data_t.COUNT;

   FOR i IN 1 .. TO_CHAR(LAST_DAY(ad_from), 'DD') LOOP                                                                                                --занулили
    data_t(ln_tmp + i) := NULL;
   END LOOP;

   FOR lc1 IN (SELECT   TO_CHAR(TRUNC(date_time), 'DD') dt, MIN(erm) erm, MIN(DECODE(ln_inv, 1, edm, erm)) inverm
               FROM     billorg
               WHERE    mid = ln_mid AND date_time >= TRUNC(ad_from, 'MONTH') AND date_time < ADD_MONTHS(TRUNC(ad_from, 'MONTH'), 1)
               GROUP BY TRUNC(date_time)) LOOP
    data_t(ln_tmp + lc1.dt) := lc1.erm;
   END LOOP;
  END LOOP;

  CLOSE cr_sel;
 END;

--------------------------------------------------------------------------------------------------------------------------
 PROCEDURE getvalue50(
 an_fid NUMBER, an_ispoint NUMBER, an_id NUMBER, ad_from DATE, ad_till DATE, data_t OUT common_pg.tt_number, quality OUT VARCHAR2, ad_forming_data OUT DATE
 ) IS
  cr_sel              common_pg.tcur;
  lv_sql              VARCHAR(4000);
  ln_tmp              NUMBER;
  ln_mid              NUMBER;
  ln_inv              NUMBER := 0;
  ln_dat              NUMBER;
 BEGIN
  lv_sql := 'select tt.id from (' || get_sql48(an_fid, an_ispoint, ln_tmp) || ') tt';
  ln_dat := TO_CHAR(ad_from, 'yyyymm');

  OPEN cr_sel FOR lv_sql USING an_id;

  LOOP
   FETCH cr_sel
   INTO  ln_mid;

   EXIT WHEN cr_sel%NOTFOUND;

   IF an_ispoint = 0 THEN
    SELECT MAX(mid), MAX(DECODE(inverted, 'y', 1, 0))
    INTO   ln_mid, ln_inv
    FROM   GROUPS
    WHERE  gid = ln_mid;
   END IF;

   ln_tmp := data_t.COUNT;

   FOR i IN 1 .. TO_CHAR(LAST_DAY(ad_from), 'DD') LOOP                                                                                                --занулили
    data_t(ln_tmp + i) := 0;
   END LOOP;

   FOR lc1 IN (SELECT   TO_CHAR(TRUNC(date_time), 'DD') dt,
                        TRUNC(100 * COUNT(*) / interior_pg.get_step(ln_mid, 1, TRUNC(date_time), 0, 24, 190001, 300001, ln_dat), 3) er
               FROM     halfhour
               WHERE    mid = ln_mid AND date_time >= TRUNC(ad_from, 'MONTH') AND date_time < ADD_MONTHS(TRUNC(ad_from, 'MONTH'), 1)
               GROUP BY TRUNC(date_time)) LOOP
    data_t(ln_tmp + lc1.dt) := lc1.er;
   END LOOP;
  END LOOP;

  CLOSE cr_sel;
 END;

