CREATE OR REPLACE 
PACKAGE BODY userforum_pg
IS
-------------------------------------------------------------------------------------------------------------
   PROCEDURE receiveTopics -- Возвращает список тем
     ( user_id IN NUMBER, date_from IN DATE, date_till IN DATE, order_by IN VARCHAR2, o_direction IN NUMBER, s_result OUT r_Tab)
    IS
     query_string  VARCHAR2(4000);
   BEGIN 
   query_string :=
     'SELECT uf.ddate, u.name, uf.vsubject, 
        (SELECT count(ufd.ddate) FROM userforumdet ufd WHERE ufd.nmessage = uf.nmessage) AS total_replies,
        (SELECT max(ufd.ddate) FROM userforumdet ufd WHERE ufd.nmessage = uf.nmessage) AS last_reply,
        uf.nmessage, uf.vmessage  
        FROM userforum uf, users u 
        WHERE uf.user_id = u.user_id 
        AND uf.ddate BETWEEN ''' || date_from || ''' AND ''' || date_till || '''';
   IF (user_id > 0) THEN
     query_string := query_string || ' AND uf.user_id = ' || to_char(user_id);
   END IF;
   
   query_string := query_string || ' ORDER BY ' || order_by;
   IF (o_direction > 0) THEN
     query_string := query_string || ' ASC';
   ELSE
     query_string := query_string || ' DESC';
   END IF;  
   
   OPEN s_result FOR query_string;
  END;
-------------------------------------------------------------------------------------------------------------
   PROCEDURE receiveUsers -- Возвращает список пользователей, создавших хотя бы одну тему
     (s_result OUT r_Tab)
    IS
   BEGIN 
   OPEN s_result FOR 
     SELECT DISTINCT u.user_id, u.name
       FROM users u, userforum uf
       WHERE u.user_id = uf.user_id
       ORDER BY u.name;
  END;
-------------------------------------------------------------------------------------------------------------
  PROCEDURE addTopic -- Добавляет новую тему
   (user_name IN VARCHAR2, subject IN VARCHAR2, message IN VARCHAR2)
    IS
  BEGIN
    INSERT INTO userforum uf
    (uf.nmessage, uf.user_id, uf.vsubject, uf.vmessage)
    VALUES
     (userforum_seq.NEXTVAL,
      (SELECT u.user_id FROM users u WHERE UPPER(u.usr) = UPPER(user_name)),
      subject,
      message);
  END;
-------------------------------------------------------------------------------------------------------------
  PROCEDURE receiveReplies -- Возвращает список ответов по выбранной теме
   (topic_id IN NUMBER, s_result OUT r_Tab)
    IS
  BEGIN
    OPEN s_result FOR
     SELECT ufd.ddate, ufd.vmessage, u.name,
      (SELECT count(ufd.ddate) FROM userforumdet ufd WHERE ufd.nmessage = topic_id) AS total_replies, 
      (SELECT max(ufd.ddate) FROM userforumdet ufd WHERE ufd.nmessage = topic_id) AS last_reply 
       FROM users u, userforumdet ufd
       WHERE u.user_id = ufd.user_id
       AND ufd.nmessage = topic_id
       ORDER BY ufd.ddate ASC;
  END;
-------------------------------------------------------------------------------------------------------------
  PROCEDURE addReply -- Добавляет ответ
   (user_name IN VARCHAR2, topic_id IN NUMBER, message IN VARCHAR2)
    IS
  BEGIN
    INSERT INTO userforumdet ufd
    (ufd.nmessage, ufd.user_id, ufd.vmessage)
    VALUES
     (topic_id,
      (SELECT u.user_id FROM users u WHERE UPPER(u.usr) = UPPER(user_name)),
      message);
  END;
-------------------------------------------------------------------------------------------------------------


END;
/


-- End of DDL Script for Package Body RYDA.USERFORUM_PG

