------------------------------------------------------------------------------------------------------------------------
--Отсечение даты до декады
 FUNCTION truncdec(d DATE)
  RETURN DATE IS
 BEGIN
  IF TO_NUMBER(TO_CHAR(d, 'DD')) <= 10 THEN
   RETURN TRUNC(d, 'MM');
  ELSIF TO_NUMBER(TO_CHAR(d, 'DD')) <= 20 THEN
   RETURN TRUNC(d, 'MM') + 10;
  END IF;

  RETURN TRUNC(d, 'MM') + 20;
 END;

------------------------------------------------------------------------------------------------------------------------
--Вычисление декады
 FUNCTION getdec(d DATE)
  RETURN NUMBER IS
 BEGIN
  IF TO_NUMBER(TO_CHAR(d, 'DD')) <= 10 THEN
   RETURN 1;
  ELSIF TO_NUMBER(TO_CHAR(d, 'DD')) <= 20 THEN
   RETURN 2;
  END IF;

  RETURN 3;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION add_dec(d DATE, i INTEGER)
  RETURN DATE IS
  ln_sec              NUMBER;
  ln_daydec           NUMBER;
  ln_dec              NUMBER;
  ret                 DATE;
 BEGIN
  ln_sec := TO_NUMBER(TO_CHAR(d, 'SSSSS')) / 86400;
  ln_daydec := TRUNC(d) - truncdec(d) + 1;
  ln_dec := getdec(d);
  ret := ADD_MONTHS(TRUNC(d, 'MM'), TRUNC(i / 3));

  IF MOD(i, 3) = -2 THEN
   IF ln_dec = 1 THEN
    ret := ADD_MONTHS(ret, -1);
    ln_dec := 2;
   ELSIF ln_dec = 2 THEN
    ret := ADD_MONTHS(ret, -1);
    ln_dec := 3;
   ELSE
    ln_dec := 1;
   END IF;
  ELSIF MOD(i, 3) = -1 THEN
   IF ln_dec = 1 THEN
    ret := ADD_MONTHS(ret, -1);
    ln_dec := 3;
   ELSIF ln_dec = 2 THEN
    ln_dec := 1;
   ELSE
    ln_dec := 2;
   END IF;
  ELSIF MOD(i, 3) = 1 THEN
   IF ln_dec = 1 THEN
    ln_dec := 2;
   ELSIF ln_dec = 2 THEN
    ln_dec := 3;
   ELSE
    ret := ADD_MONTHS(ret, 1);
    ln_dec := 1;
   END IF;
  ELSIF MOD(i, 3) = 2 THEN
   IF ln_dec = 1 THEN
    ln_dec := 3;
   ELSIF ln_dec = 2 THEN
    ret := ADD_MONTHS(ret, 1);
    ln_dec := 1;
   ELSE
    ret := ADD_MONTHS(ret, 1);
    ln_dec := 2;
   END IF;
  END IF;

  IF ln_dec = 1 OR ln_dec = 2 THEN
   ret := ret + LEAST(10 *(ln_dec - 1) + ln_daydec, 10 * ln_dec) - 1;
  ELSE
   ret := ret + LEAST(20 + ln_daydec, TO_NUMBER(TO_CHAR(LAST_DAY(ret), 'DD'))) - 1;
  END IF;

  RETURN ret + ln_sec;
 END;

------------------------------------------------------------------------------------------------------------------------
--Отсечение до получасовок
 FUNCTION trunchh24_2(d DATE)
  RETURN DATE IS
 BEGIN
  RETURN trunc_d(d, 1 / 48);
 END;

------------------------------------------------------------------------------------------------------------------------
--Отсечение до an_dif - как делить 1/2 - это пол дня, 1/24 - по часам , 1/48 - по получасам,1/480 - 3 минутки
 FUNCTION trunc_d(d DATE, an_dif NUMBER)
  RETURN DATE IS
  cn_rn      CONSTANT NUMBER := 22;
 BEGIN
  RETURN TRUNC(d) + TRUNC(TO_CHAR(d, 'SSSSS') / ROUND(86400 * an_dif, cn_rn)) * an_dif;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает порядковый номер данных при группировке (для макетов 25 час и, т, д)
 FUNCTION get_num_dt(d DATE, an_source NUMBER, an_dif NUMBER, an_in_end NUMBER, an_shifttz NUMBER, an_summer NUMBER)
  --an_dif - как делить 1/2 - это пол дня, 1/24 - по часам , 1/48 - по получасам
 RETURN NUMBER IS
  cn_rn      CONSTANT NUMBER := 22;
  ln_isdsw            NUMBER DEFAULT is_dayswitch(d);
  ln_ret              NUMBER;
 BEGIN
  IF NOT(an_dif > 0 AND an_dif <= 1) THEN
   RETURN NULL;
  END IF;

  IF an_summer = 1 THEN
   IF ln_isdsw = -1 THEN                                                                                                                                --осень
    IF an_in_end = 1 THEN                                                                                                                   --добавляем в конец
     IF an_source IN(19, 29, 39, 49, 59) THEN                                                                                              --Время лишнего часа
      ln_ret := TRUNC(TO_CHAR(d - TO_CHAR(d, 'HH24') / 24, 'SSSSS') / ROUND(86400 * an_dif, cn_rn)) + 1 + 1 / an_dif;
     END IF;
    ELSE                                                                                                                                             --посредине
     IF (d > TRUNC(d) + (switch_f + 1) / 24) OR(d > TRUNC(d) + (switch_f) / 24 AND an_source IN(19, 29, 39, 49, 59)) THEN
      --ЕСЛИ БОЛЬШЕ (switch_f+1) или > switch_f и не сдвиг добавляем 1
      ln_ret := TRUNC(TO_CHAR(d, 'SSSSS') / ROUND(86400 * an_dif, cn_rn)) + 1 + 1 / 24 / an_dif;
     END IF;
    END IF;
   ELSIF ln_isdsw = 1 THEN                                                                                                                               --весна
    IF d > TRUNC(d) + switch_f / 24 THEN                                                                                   --ЕСЛИ БОЛЬШЕ 3 НОЧИ, ТО УБИРАЕМ ЧАС
     ln_ret := TRUNC(TO_CHAR(d - 1 / 24, 'SSSSS') / ROUND(86400 * an_dif, cn_rn)) + 1;
    END IF;
   END IF;
  END IF;

  ln_ret := ROUND(NVL(ln_ret, TRUNC(TO_CHAR(d, 'SSSSS') / ROUND(86400 * an_dif, cn_rn)) + 1)) - ROUND((24 * an_shifttz) *(1 / 24 /(an_dif)));

  IF an_shifttz < 0 THEN                                                                                                                                --Россия
   IF ln_ret > ROUND(1 /(an_dif) - is_dayswitch(d) *(1 / 24 /(an_dif))) THEN
    ln_ret := ln_ret + ROUND((24 * an_shifttz) * 1 /(an_dif) + is_dayswitch(d) *(1 / 24 /(an_dif)));
   END IF;
  ELSIF an_shifttz > 0 THEN                                                                                                                             --Европа
   IF ln_ret < 1 THEN
    IF is_dayswitch(d - 1) <> 1 THEN
     ln_ret := ln_ret + ROUND(1 / 24 /(an_dif)) + ROUND((1 /(an_dif) - is_dayswitch(d - 1) *(1 / 24 /(an_dif))) - ROUND((24 * an_shifttz) *(1 / 24 /(an_dif))));
    ELSE
     ln_ret := ln_ret + ROUND(1 / 24 /(an_dif)) + ROUND((1 /(an_dif) - is_dayswitch(d - 1) *(1 / 24 /(an_dif))));
    END IF;
   END IF;

   IF is_dayswitch(d - 1) = -1 AND ln_ret > 24 * ROUND(1 / 24 /(an_dif)) THEN
    ln_ret := ln_ret - ROUND(1 / 24 /(an_dif));
   END IF;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает количество, записей в сутках (для макетов 25 час и, т, д)
 FUNCTION get_count_dt(d DATE, an_dif NUMBER)
  --an_dif - как делить 1/2 - это пол дня, 1/24 - по часам , 1/48 - по получасам
 RETURN NUMBER IS
 BEGIN
  IF NOT(an_dif > 0 AND an_dif <= 1) THEN
   RETURN NULL;
  END IF;

  RETURN ROUND(1 / an_dif - is_dayswitch(d) / 24 / an_dif);
 END;

------------------------------------------------------------------------------------------------------------------------
 --Потолок до получасовок
 FUNCTION ceilhh24_2(d DATE)
  RETURN DATE IS
 BEGIN
  IF d = trunchh24_2(d) THEN
   RETURN d;
  ELSE
   RETURN trunchh24_2(d) + 1 / 48;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Потолок до получасовок
 FUNCTION ceil_d(d DATE, an_dif NUMBER)
  RETURN DATE IS
 BEGIN
  IF d = trunc_d(d, an_dif) THEN
   RETURN d;
  ELSE
   RETURN trunc_d(d, an_dif) + an_dif;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
--Приведение даты к лету (+1 час если лето)
 FUNCTION to_localtime(d DATE, u NUMBER)
  RETURN DATE IS
  ln_m                NUMBER DEFAULT TO_CHAR(d, 'MM');
 BEGIN
  IF /*locksummertime_f = 0 AND*/ d < cd_alwayssummer THEN
   IF ln_m > 3 AND ln_m < 10 THEN
    RETURN d + 1 / 24;
   ELSIF ln_m = 3 AND d > TRUNC(last_dayw(d, 7)) + switch_f / 24 THEN
    RETURN d + 1 / 24;
   ELSIF ln_m = 10 AND d <= TRUNC(last_dayw(d, 7)) + switch_f / 24 THEN
    RETURN d + 1 / 24;
   ELSIF u = 1 AND ln_m = 10 AND d <= TRUNC(last_dayw(d, 7)) + (switch_f + 1) / 24 THEN
    RETURN TRUNC(last_dayw(d, 7)) + (switch_f + 1) / 24 + 1 / 86400;
   END IF;
  END IF;

  RETURN d;
 END;

------------------------------------------------------------------------------------------------------------------------
--Приведение даты к зиме (-1 час если лето) (обратная к to_localtime)
 FUNCTION to_unlocaltime(d DATE, an_source NUMBER)
  RETURN DATE IS
  ln_m                NUMBER DEFAULT TO_CHAR(d, 'MM');
 BEGIN
  IF /*locksummertime_f = 0 AND*/ d < cd_alwayssummer THEN
   IF ln_m > 3 AND ln_m < 10 THEN
    RETURN d - 1 / 24;
   ELSIF ln_m = 3 AND d > TRUNC(last_dayw(d, 7)) + switch_f / 24 THEN
    RETURN d - 1 / 24;
   ELSIF ln_m = 10 AND d <= TRUNC(last_dayw(d, 7)) + switch_f / 24 THEN
    RETURN d - 1 / 24;
   ELSIF ln_m = 10
                  --Если время перехода и не повторная запись то мы вычитаем
         AND d <= TRUNC(last_dayw(d, 7)) + switch_f / 24 + 1 / 24 AND an_source NOT IN(19, 29, 39, 49, 59) THEN
    RETURN d - 1 / 24;
   END IF;
  END IF;

  RETURN d;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Лето ли у нас?
 FUNCTION is_summer(d DATE)
  RETURN NUMBER IS
  ln_m                NUMBER DEFAULT TO_CHAR(d, 'MM');
 BEGIN
  IF /*locksummertime_f = 0 AND*/ d < cd_alwayssummer THEN
   IF ln_m > 3 AND ln_m < 10 THEN
    RETURN 1;
   ELSIF ln_m = 3 AND d > TRUNC(last_dayw(d, 7)) + switch_f / 24 THEN
    RETURN 1;
   ELSIF ln_m = 10 AND d <= TRUNC(last_dayw(d, 7)) + switch_f / 24 THEN
    RETURN 1;
   END IF;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Находит последний день месяца a=1 - понедельник, ... a=7 - воскресенье
 FUNCTION last_dayw(d DATE, a NUMBER)
  RETURN DATE IS
  cv_date    CONSTANT VARCHAR2(32) := TO_CHAR(TO_DATE('07.04.2003', 'DD.MM.YYYY') - 1 + a, 'DAY');
 BEGIN
  RETURN NEXT_DAY(LAST_DAY(d) - 7, cv_date);
 END;

------------------------------------------------------------------------------------------------------------------------
--Проверяет является ли день днем перевода времени 1 весна(на час вперед), -1 осень(на час назад) иначе 0
 FUNCTION is_dayswitch(d DATE)
  RETURN NUMBER IS
  ld_date             DATE;
 BEGIN
  IF /*locksummertime_f = 0 AND*/ d < cd_alwayssummer THEN
   ld_date := last_dayw(d, 7);

   IF d = ld_date AND TO_NUMBER(TO_CHAR(d, 'MM')) = 3 THEN
    RETURN 1;
   ELSIF d = ld_date AND TO_NUMBER(TO_CHAR(d, 'MM')) = 10 THEN
    RETURN -1;
   END IF;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Проверяет является ли время - временем перевода (>03:00<=04:00) времени 1 весна(на час вперед), -1 осень(на час назад) иначе 0
 FUNCTION is_timeswitch(d DATE)
  RETURN NUMBER IS
 BEGIN
  IF /*locksummertime_f = 0 AND*/ d < cd_alwayssummer THEN
   IF d > TRUNC(d) + switch_f / 24 AND d <= TRUNC(d) + (switch_f + 1) / 24 THEN
    RETURN is_dayswitch(d);
   END IF;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_half_num(d DATE)
  RETURN NUMBER IS
 BEGIN
  RETURN 2 * TO_CHAR(d, 'HH24') + TRUNC(TO_CHAR(d, 'MI') / 30) + 1;
 END;

