 FUNCTION needchdr_f(an_mid NUMBER)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  IF gn_inverted = 1 THEN
   SELECT DECODE(MAX(ninverted), 1, 1, 0)
   INTO   ln_ret
   FROM   feeders
   WHERE  mid = an_mid;

   RETURN ln_ret;
  ELSIF gn_inverted = 2 THEN
   RETURN 1;
  ELSIF gn_inverted = 3 THEN
   SELECT DECODE(MAX(ninverted), 1, 0, 1)
   INTO   ln_ret
   FROM   feeders
   WHERE  mid = an_mid;

   RETURN ln_ret;
  ELSE
   RETURN 0;
  END IF;
 END;

