-- возвращает mid ближайшей подстанции для синих под зелеными
 FUNCTION get_pointparentid(an_mid NUMBER)
  RETURN NUMBER IS
  ln_mid              NUMBER;
 BEGIN
  SELECT MAX(pa.mid)
  INTO   ln_mid
  FROM   points p, points pa, feeders f
  WHERE  p.mid = an_mid AND pa.mid IN(SELECT     PARENT
                                      FROM       points
                                      CONNECT BY PRIOR PARENT = mid AND ind IN(3, 4)
                                      START WITH mid = an_mid) AND pa.ind IN(1, 2) AND p.mid = f.mid(+);

  RETURN ln_mid;
 END;

-------------------------------------------------------------------------------------------------
 --длиное название группы
 FUNCTION get_groupname(an_gid NUMBER, an_detal NUMBER DEFAULT 1)
  --степень детализации
 RETURN VARCHAR2 IS
  lv_ret              VARCHAR2(2000);

  CURSOR lcur_sel IS
   SELECT     DECODE(LEVEL, 1, NAME, NAME || ' \ ') NAME
   FROM       GROUPS
   WHERE      LEVEL <= DECODE(SIGN(an_detal), 0, 1, NULL, 1, -1, 1, TRUNC(an_detal))
   CONNECT BY PRIOR PARENT = gid
   START WITH gid = an_gid;
 BEGIN
  FOR lc IN lcur_sel LOOP
   lv_ret := lc.NAME || lv_ret;
  END LOOP;

  RETURN SUBSTR(NVL(lv_ret, ' '), 1, 255);
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возвращает показания счетчика (рассчет показаний производится на основании
-- месячных или показаний занесенных в таблицу MAN_IMP_HHOUR показаний,
-- путем прибавление пролучасовых расходов)
-- параметр an_etype может принимать значения:
-- 1 - erm
-- 2 - edm
-- 3 - q1m
-- 4 - q2m
-- 5 - q3m
-- 6 - q4m
-- параметр an_meterage_table может принимать значения:
-- 1 - man_inp_hhour
-- 2 - months
-- 3 - billorg
 FUNCTION get_meterage(an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_meterage_table NUMBER)
  RETURN NUMBER IS
  ld_lastdate_met     DATE := NULL;
  ln_m_erm            NUMBER;
  ln_m_edm            NUMBER;
  ln_m_q1m            NUMBER;
  ln_m_q2m            NUMBER;
  ln_m_q3m            NUMBER;
  ln_m_q4m            NUMBER;
  ln_erm              NUMBER;
  ln_edm              NUMBER;
  ln_q1m              NUMBER;
  ln_q2m              NUMBER;
  ln_q3m              NUMBER;
  ln_q4m              NUMBER;
  ln_ret              NUMBER;
 BEGIN
  IF an_meterage_table = 1 THEN
   SELECT MAX(date_time)
   INTO   ld_lastdate_met
   FROM   man_inp_hhour
   WHERE  mid = an_mid AND date_time <= ad_date;

   SELECT erm, edm, q1m, q2m, q3m, q4m
   INTO   ln_m_erm, ln_m_edm, ln_m_q1m, ln_m_q2m, ln_m_q3m, ln_m_q4m
   FROM   man_inp_hhour
   WHERE  mid = an_mid AND date_time = ld_lastdate_met;
  ELSIF an_meterage_table = 2 THEN
   SELECT MAX(date_time)
   INTO   ld_lastdate_met
   FROM   months
   WHERE  mid = an_mid AND date_time <= ad_date;

   SELECT erm, edm, q1m, q2m, q3m, q4m
   INTO   ln_m_erm, ln_m_edm, ln_m_q1m, ln_m_q2m, ln_m_q3m, ln_m_q4m
   FROM   months
   WHERE  mid = an_mid AND date_time = ld_lastdate_met;
  ELSIF an_meterage_table = 3 THEN
   SELECT MAX(date_time)
   INTO   ld_lastdate_met
   FROM   billorg
   WHERE  mid = an_mid AND date_time <= ad_date;

   SELECT erm, edm, q1m, q2m, q3m, q4m
   INTO   ln_m_erm, ln_m_edm, ln_m_q1m, ln_m_q2m, ln_m_q3m, ln_m_q4m
   FROM   billorg
   WHERE  mid = an_mid AND date_time = ld_lastdate_met;
  END IF;

  SELECT NVL(SUM(er / DECODE(kc, 0, 1, kc)), 0), NVL(SUM(ed / DECODE(kc, 0, 1, kc)), 0), NVL(SUM(q1 / DECODE(kc, 0, 1, kc)), 0),
         NVL(SUM(q2 / DECODE(kc, 0, 1, kc)), 0), NVL(SUM(q3 / DECODE(kc, 0, 1, kc)), 0), NVL(SUM(q4 / DECODE(kc, 0, 1, kc)), 0)
  INTO   ln_erm, ln_edm, ln_q1m, ln_q2m, ln_q3m, ln_q4m
  FROM   halfhour h, feeders f
  WHERE  f.mid = an_mid AND f.mid = h.mid AND date_time > ld_lastdate_met AND date_time <= ad_date;

  IF an_etype = 1 THEN
   ln_ret := ln_m_erm + ln_erm;
  ELSIF an_etype = 2 THEN
   ln_ret := ln_m_edm + ln_edm;
  ELSIF an_etype = 3 THEN
   ln_ret := ln_m_q1m + ln_q1m;
  ELSIF an_etype = 4 THEN
   ln_ret := ln_m_q2m + ln_q2m;
  ELSIF an_etype = 5 THEN
   ln_ret := ln_m_q3m + ln_q3m;
  ELSIF an_etype = 6 THEN
   ln_ret := ln_m_q4m + ln_q4m;
  END IF;

  RETURN ln_ret;
 /* EXCEPTION
   WHEN OTHERS THEN
    RETURN -1;*/
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возвращает показания счетчика (рассчет показаний производится на основании
-- месячных или показаний занесенных в таблицу MAN_IMP_HHOUR показаний,
-- путем прибавление пролучасовых расходов)
-- параметр an_etype может принимать значения:
-- 1 - erm
-- 2 - edm
-- 3 - q1m
-- 4 - q2m
-- 5 - q3m
-- 6 - q4m

 -- 7 - aerm
 -- 8 - aedm
 -- 9 - aq1m
 -- 10 - aq2m
 -- 11 - aq3m
 -- 12 - aq4m

 -- 13 - berm
 -- 14 - bedm
 -- 15 - bq1m
 -- 16 - bq2m
 -- 17 - bq3m
 -- 18 - bq4m

 -- 19 - cerm
 -- 20 - cedm
 -- 21 - cq1m
 -- 22 - cq2m
 -- 23 - cq3m
 -- 24 - cq4m
 FUNCTION get_meterage(an_mid NUMBER, ad_date DATE, an_etype NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN get_meterage(an_mid, ad_date, an_etype, 0, NULL);
 END;

 ------------------------------------------------------------------------------------------------------------------------
 -- an_mettype принимает значения
--    0 - На момент снятия счетчика или в штатной ситуации( NSOURCE = 7 или NSOURCE > 8)
--    Иначе - На момент установки счетчика или в штатной ситуации ( NSOURCE = 8 или NSOURCE > 8)
 -- параметр an_table может принимать значения:
 -- 1 - man_inp_hhour
 -- 2 - monthsorg
 -- 3 - billorg
 -- 4 - halfhour
 -- 0,NULL - по всем таблицам
 -- Иначе return NULL;
 FUNCTION get_meterage(an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, an_table NUMBER, an_withoutcalc NUMBER)                         -- Умная
  RETURN NUMBER IS
  CURSOR lcur_sel IS
   SELECT   0 t, MIN(date_time - ad_date) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     halfhour
   WHERE    NOT(NVL(get_customer_id, 0) = 16 AND an_etype IN(3, 4, 5, 6) AND mid IN(3154, 3156)) AND mid = an_mid AND date_time = ad_date
            AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 4, an_table) = 4
   UNION ALL
   SELECT   1 t, MIN(date_time - ad_date) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     billorg
   WHERE    mid = an_mid AND date_time >= ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   2 t, MIN(ad_date - date_time) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     billorg
   WHERE    mid = an_mid AND date_time < ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(ad_date - date_time) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   3 t, MIN(date_time - ad_date) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     monthsorg
   WHERE    mid = an_mid AND date_time >= ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   4 t, MIN(ad_date - date_time) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     monthsorg
   WHERE    mid = an_mid AND date_time < ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(ad_date - date_time) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   5 t, MIN(date_time - ad_date) dif, 0
   FROM     man_inp_hhour
   WHERE    mid = an_mid AND date_time >= ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT   6 t, MIN(ad_date - date_time) dif, 0
   FROM     man_inp_hhour
   WHERE    mid = an_mid AND date_time < ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(ad_date - date_time) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT   7 t, MIN(dswitch - ad_date) dif, 0
   FROM     switches
   WHERE    nswitch = an_mid AND dswitch = ad_date AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) > 0
   HAVING   MIN(dswitch - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   UNION ALL
   SELECT   8 t, MIN(descape - ad_date) dif, 0
   FROM     switches
   WHERE    nswitch = an_mid AND descape = ad_date AND DECODE(an_etype, 2, edme, 3, q1me, 4, q2me, 5, q3me, 6, q4me, erme) > 0
   HAVING   MIN(descape - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   ORDER BY 3, 2, 1;

  ln_val              NUMBER;
  ln_ret              NUMBER;
  ln_retdat           DATE;
  ln_difdat           NUMBER;                                                                                                                --date_time-ad_date
  lv_tab              VARCHAR2(32);
  lv_what             VARCHAR2(32);
  lb_add              BOOLEAN DEFAULT TRUE;
  lv_sql              VARCHAR2(4000);
  lv_agr              VARCHAR2(32);
  ln_entype           NUMBER;
  ln_digits           NUMBER;
  ln_kc               NUMBER;
  ln_tmp              NUMBER;
 BEGIN
  IF ad_date <> TRUNC(ad_date) THEN
   --Если время не на границе суток и показания на начало и конец совпадают то их и возвращаем.
   ln_tmp := get_meterage(an_mid, TRUNC(ad_date), an_etype, an_mettype, an_table, an_withoutcalc);

   IF ln_tmp = get_meterage(an_mid, TRUNC(ad_date) + 1, an_etype, an_mettype, an_table, an_withoutcalc) THEN
    RETURN ln_tmp;
   END IF;
  END IF;

  IF an_withoutcalc = 1 THEN
   RETURN get_meterage_wc(an_mid, ad_date, an_etype, an_mettype, an_table);
  END IF;

  FOR lc IN lcur_sel LOOP
   IF MOD(lc.t, 2) = 1 THEN
    ln_difdat := lc.dif;
   ELSE
    ln_difdat := -lc.dif;
   END IF;

   IF lc.t = 0 THEN
    lv_tab := 'halfhour';
   ELSIF lc.t <= 2 THEN
    lv_tab := 'billorg';
   ELSIF lc.t <= 4 THEN
    lv_tab := 'monthsorg';
   ELSIF lc.t IN(7, 8) THEN
    lv_tab := 'switches';
    lb_add := FALSE;
   ELSE
    lv_tab := 'MAN_INP_HHOUR';
    lb_add := FALSE;
   END IF;

   IF an_etype = 2 THEN
    lv_what := 'edm';
    ln_entype := 2;
   ELSIF an_etype = 3 THEN
    lv_what := 'q1m';
    ln_entype := 3;
   ELSIF an_etype = 4 THEN
    lv_what := 'q2m';
    ln_entype := 3;
   ELSIF an_etype = 5 THEN
    lv_what := 'q3m';
    ln_entype := 5;
   ELSIF an_etype = 6 THEN
    lv_what := 'q4m';
    ln_entype := 5;
   ELSIF lc.t = 0 THEN
    lv_what := 'erm';
    ln_entype := 1;
   --зона A
   ELSIF an_etype = 7 THEN
    lv_what := 'aerm';
    ln_entype := 1;
   ELSIF an_etype = 8 THEN
    lv_what := 'aedm';
    ln_entype := 2;
   ELSIF an_etype = 9 THEN
    lv_what := 'aq1m';
    ln_entype := 3;
   ELSIF an_etype = 10 THEN
    lv_what := 'aq2m';
    ln_entype := 3;
   ELSIF an_etype = 11 THEN
    lv_what := 'aq3m';
    ln_entype := 5;
   ELSIF an_etype = 12 THEN
    lv_what := 'aq4m';
    ln_entype := 5;
   --зона B
   ELSIF an_etype = 13 THEN
    lv_what := 'berm';
    ln_entype := 1;
   ELSIF an_etype = 14 THEN
    lv_what := 'bedm';
    ln_entype := 2;
   ELSIF an_etype = 15 THEN
    lv_what := 'bq1m';
    ln_entype := 3;
   ELSIF an_etype = 16 THEN
    lv_what := 'bq2m';
    ln_entype := 3;
   ELSIF an_etype = 17 THEN
    lv_what := 'bq3m';
    ln_entype := 5;
   ELSIF an_etype = 18 THEN
    lv_what := 'bq4m';
    ln_entype := 5;
   --зона C
   ELSIF an_etype = 19 THEN
    lv_what := 'cerm';
    ln_entype := 1;
   ELSIF an_etype = 20 THEN
    lv_what := 'cedm';
    ln_entype := 2;
   ELSIF an_etype = 21 THEN
    lv_what := 'cq1m';
    ln_entype := 3;
   ELSIF an_etype = 22 THEN
    lv_what := 'cq2m';
    ln_entype := 3;
   ELSIF an_etype = 23 THEN
    lv_what := 'cq3m';
    ln_entype := 5;
   ELSIF an_etype = 24 THEN
    lv_what := 'cq4m';
    ln_entype := 5;
   ELSE
    lv_what := 'erm';
    ln_entype := 1;
   END IF;

   IF lc.t = 7 THEN                                                                                                                               --для switches
    lv_sql := 'select dswitch date_time,' || lv_what || ' from ' || lv_tab || ' where nswitch=:1 and dswitch-:2=:3 and ' || lv_what || ' is not null';
   ELSIF lc.t = 8 THEN
    lv_what := lv_what || 'e';
    lv_sql := 'select descape date_time,' || lv_what || ' from ' || lv_tab || ' where nswitch=:1 and descape-:2=:3 and ' || lv_what || ' is not null';
   ELSE
    lv_sql := 'select date_time,' || lv_what || ' from ' || lv_tab || ' where mid=:1 and date_time-:2=:3 and ' || lv_what || ' is not null';
   END IF;

   IF lb_add THEN
    IF an_mettype = 0 THEN
     lv_agr := 'min';
    ELSE
     lv_agr := 'max';
    END IF;

    lv_sql :=
            lv_sql || ' and nsource=(select ' || lv_agr || '(nsource) from ' || lv_tab || ' where mid=:4 and date_time-:5=:6 and ' || lv_what || ' is not null)';

    EXECUTE IMMEDIATE lv_sql
    INTO              ln_retdat, ln_ret
    USING             an_mid, ad_date, ln_difdat, an_mid, ad_date, ln_difdat;
   ELSE
    EXECUTE IMMEDIATE lv_sql
    INTO              ln_retdat, ln_ret
    USING             an_mid, ad_date, ln_difdat;
   END IF;

   IF ln_retdat = ad_date THEN
    EXIT;
   ELSIF an_withoutcalc = 1 THEN                                                                                                                 --без дорасчета
    IF TRUNC(ln_retdat) = TRUNC(ad_date) THEN
     NULL;
    ELSE
     ln_ret := NULL;
    END IF;

    EXIT;
   END IF;

   IF get_customer_id IN(41, 42, 43, 44, 45) THEN                                                                                    -- НЭК Центр,СЭС,ЗЭС,Дон ЭС
    SELECT MAX(DECODE(SIGN(NVL(metkc, 1) - 1), 1, NVL(metkc, 1), NVL(kc, 1)))
    INTO   ln_kc
    FROM   feeders
    WHERE  mid = an_mid;
   ELSE
    ln_kc := NULL;
   END IF;

   SELECT NVL(SUM(DECODE(an_etype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) / NVL(DECODE(NVL(ln_kc, nkc), 0, 1, NVL(ln_kc, nkc)), 1)), 0)
   INTO   ln_val
   FROM   halfhour
   WHERE  mid = an_mid AND date_time > LEAST(ad_date, ln_retdat) AND date_time <= GREATEST(ad_date, ln_retdat) AND(NVL(nsource, 0) < 30 OR NVL(nsource, 0) > 49);

   SELECT NVL(MAX(digits), cn_def_digits)
   INTO   ln_digits
   FROM   meters
   WHERE  mid = an_mid AND entype = (SELECT MAX(DECODE(smart, '*', 7, ln_entype))
                                     FROM   feeders
                                     WHERE  mid = an_mid);

   ln_ret :=
    ROUND(ABS(MOD(ln_ret - SIGN(ln_retdat - ad_date) * ln_val, POWER(10, LENGTH(GREATEST(ABS(TRUNC(ln_digits)), ABS(TRUNC(ln_ret))))))),
     LENGTH(1 + ABS(ln_digits - TRUNC(ln_digits))));
   EXIT;
  END LOOP;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_meterage_wc(an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, an_table NUMBER)                                             -- Умная
  RETURN NUMBER IS
  CURSOR lcur_sel IS
   SELECT 1 t,
          DECODE(
           an_etype,
           2, edm,
           3, q1m,
           4, q2m,
           5, q3m,
           6, q4m,
           7, aerm,
           8, aedm,
           9, aq1m,
           10, aq2m,
           11, aq3m,
           12, aq4m,
           13, berm,
           14, bedm,
           15, bq1m,
           16, bq2m,
           17, bq3m,
           18, bq4m,
           19, cerm,
           20, cedm,
           21, cq1m,
           22, cq2m,
           23, cq3m,
           24, cq4m,
           erm
          ) dif
   FROM   billorg
   WHERE  mid = an_mid AND date_time = ad_date
          AND DECODE(
              an_etype,
              2, edm,
              3, q1m,
              4, q2m,
              5, q3m,
              6, q4m,
              7, aerm,
              8, aedm,
              9, aq1m,
              10, aq2m,
              11, aq3m,
              12, aq4m,
              13, berm,
              14, bedm,
              15, bq1m,
              16, bq2m,
              17, bq3m,
              18, bq4m,
              19, cerm,
              20, cedm,
              21, cq1m,
              22, cq2m,
              23, cq3m,
              24, cq4m,
              erm
             ) IS NOT NULL
          AND DECODE(NVL(an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT 3 t,
          DECODE(
           an_etype,
           2, edm,
           3, q1m,
           4, q2m,
           5, q3m,
           6, q4m,
           7, aerm,
           8, aedm,
           9, aq1m,
           10, aq2m,
           11, aq3m,
           12, aq4m,
           13, berm,
           14, bedm,
           15, bq1m,
           16, bq2m,
           17, bq3m,
           18, bq4m,
           19, cerm,
           20, cedm,
           21, cq1m,
           22, cq2m,
           23, cq3m,
           24, cq4m,
           erm
          ) dif
   FROM   monthsorg
   WHERE  mid = an_mid AND date_time = ad_date
          AND DECODE(
              an_etype,
              2, edm,
              3, q1m,
              4, q2m,
              5, q3m,
              6, q4m,
              7, aerm,
              8, aedm,
              9, aq1m,
              10, aq2m,
              11, aq3m,
              12, aq4m,
              13, berm,
              14, bedm,
              15, bq1m,
              16, bq2m,
              17, bq3m,
              18, bq4m,
              19, cerm,
              20, cedm,
              21, cq1m,
              22, cq2m,
              23, cq3m,
              24, cq4m,
              erm
             ) IS NOT NULL
          AND DECODE(NVL(an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT 0 t, DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) dif
   FROM   halfhour
   WHERE  NOT(NVL(get_customer_id, 0) = 16 AND an_etype IN(3, 4, 5, 6) AND mid IN(3154, 3156)) AND mid = an_mid AND date_time = ad_date
          AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 4, an_table) = 4
   UNION ALL
   SELECT 5 t,
          DECODE(
           an_etype,
           2, edm,
           3, q1m,
           4, q2m,
           5, q3m,
           6, q4m,
           7, aerm,
           8, aedm,
           9, aq1m,
           10, aq2m,
           11, aq3m,
           12, aq4m,
           13, berm,
           14, bedm,
           15, bq1m,
           16, bq2m,
           17, bq3m,
           18, bq4m,
           19, cerm,
           20, cedm,
           21, cq1m,
           22, cq2m,
           23, cq3m,
           24, cq4m,
           erm
          ) dif
   FROM   man_inp_hhour
   WHERE  mid = an_mid AND date_time = ad_date
          AND DECODE(
              an_etype,
              2, edm,
              3, q1m,
              4, q2m,
              5, q3m,
              6, q4m,
              7, aerm,
              8, aedm,
              9, aq1m,
              10, aq2m,
              11, aq3m,
              12, aq4m,
              13, berm,
              14, bedm,
              15, bq1m,
              16, bq2m,
              17, bq3m,
              18, bq4m,
              19, cerm,
              20, cedm,
              21, cq1m,
              22, cq2m,
              23, cq3m,
              24, cq4m,
              erm
             ) IS NOT NULL
          AND DECODE(NVL(an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT 7 t, DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) dif
   FROM   switches
   WHERE  nswitch = an_mid AND dswitch = ad_date AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) > 0
          AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   UNION ALL
   SELECT 8 t, DECODE(an_etype, 2, edme, 3, q1me, 4, q2me, 5, q3me, 6, q4me, erme) dif
   FROM   switches
   WHERE  nswitch = an_mid AND descape = ad_date AND DECODE(an_etype, 2, edme, 3, q1me, 4, q2me, 5, q3me, 6, q4me, erme) > 0
          AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5;

  ln_ret              NUMBER;
 BEGIN
  FOR lc IN lcur_sel LOOP
   RETURN lc.dif;
  END LOOP;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- an_mettype принимает значения
 --    0 - На момент снятия счетчика или в штатной ситуации( NSOURCE = 7 или NSOURCE > 8)
 --    Иначе - На момент установки счетчика или в штатной ситуации ( NSOURCE = 8 или NSOURCE > 8)
 -- параметр an_table может принимать значения:
 -- 1 - man_inp_hhour
 -- 2 - monthsorg
 -- 3 - billorg
 -- 4 - halfhour
 -- 0,NULL - по всем таблицам
 -- возвращает 1 - показания реальные, 0 - показания расчитаны
 FUNCTION get_meterage_exists(an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, an_table NUMBER, an_withoutcalc NUMBER)
  RETURN NUMBER IS
  CURSOR lcur_sel IS
   SELECT   0 t, MIN(date_time - ad_date) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     halfhour
   WHERE    NOT(NVL(get_customer_id, 0) = 16 AND an_etype IN(3, 4, 5, 6) AND mid IN(3154, 3156)) AND mid = an_mid AND date_time = ad_date
            AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 4, an_table) = 4
   UNION ALL
   SELECT   1 t, MIN(date_time - ad_date) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     billorg
   WHERE    mid = an_mid AND date_time >= ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   2 t, MIN(ad_date - date_time) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     billorg
   WHERE    mid = an_mid AND date_time < ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(ad_date - date_time) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   3 t, MIN(date_time - ad_date) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     monthsorg
   WHERE    mid = an_mid AND date_time >= ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   4 t, MIN(ad_date - date_time) dif, DECODE(get_customer_id, 2, -1, 0)
   FROM     monthsorg
   WHERE    mid = an_mid AND date_time < ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(ad_date - date_time) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   5 t, MIN(date_time - ad_date) dif, 0
   FROM     man_inp_hhour
   WHERE    mid = an_mid AND date_time >= ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(date_time - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT   6 t, MIN(ad_date - date_time) dif, 0
   FROM     man_inp_hhour
   WHERE    mid = an_mid AND date_time < ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
   HAVING   MIN(ad_date - date_time) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT   7 t, MIN(dswitch - ad_date) dif, 0
   FROM     switches
   WHERE    nswitch = an_mid AND dswitch = ad_date AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) > 0
   HAVING   MIN(dswitch - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   UNION ALL
   SELECT   8 t, MIN(descape - ad_date) dif, 0
   FROM     switches
   WHERE    nswitch = an_mid AND descape = ad_date AND DECODE(an_etype, 2, edme, 3, q1me, 4, q2me, 5, q3me, 6, q4me, erme) > 0
   HAVING   MIN(descape - ad_date) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   ORDER BY 3, 2, 1;

  ln_val              NUMBER;
  ln_ret              NUMBER;
  ln_retdat           DATE;
  ln_difdat           NUMBER;                                                                                                                --date_time-ad_date
  lv_tab              VARCHAR2(32);
  lv_what             VARCHAR2(32);
  lb_add              BOOLEAN DEFAULT TRUE;
  lv_sql              VARCHAR2(4000);
  lv_agr              VARCHAR2(32);
  ln_entype           NUMBER;
  ln_digits           NUMBER;
  ln_kc               NUMBER;
  ln_tmp              NUMBER;
 BEGIN
  IF an_withoutcalc = 1 THEN
   RETURN get_meterage_exists_wc(an_mid, ad_date, an_etype, an_mettype, an_table);
  END IF;

  FOR lc IN lcur_sel LOOP
   IF MOD(lc.t, 2) = 1 THEN
    ln_difdat := lc.dif;
   ELSE
    ln_difdat := -lc.dif;
   END IF;

   IF lc.t = 0 THEN
    lv_tab := 'halfhour';
   ELSIF lc.t <= 2 THEN
    lv_tab := 'billorg';
   ELSIF lc.t <= 4 THEN
    lv_tab := 'monthsorg';
   ELSIF lc.t IN(7, 8) THEN
    lv_tab := 'switches';
    lb_add := FALSE;
   ELSE
    lv_tab := 'MAN_INP_HHOUR';
    lb_add := FALSE;
   END IF;

   IF an_etype = 2 THEN
    lv_what := 'edm';
    ln_entype := 2;
   ELSIF an_etype = 3 THEN
    lv_what := 'q1m';
    ln_entype := 3;
   ELSIF an_etype = 4 THEN
    lv_what := 'q2m';
    ln_entype := 3;
   ELSIF an_etype = 5 THEN
    lv_what := 'q3m';
    ln_entype := 5;
   ELSIF an_etype = 6 THEN
    lv_what := 'q4m';
    ln_entype := 5;
   ELSIF lc.t = 0 THEN
    lv_what := 'erm';
    ln_entype := 1;
   --зона A
   ELSIF an_etype = 7 THEN
    lv_what := 'aerm';
    ln_entype := 1;
   ELSIF an_etype = 8 THEN
    lv_what := 'aedm';
    ln_entype := 2;
   ELSIF an_etype = 9 THEN
    lv_what := 'aq1m';
    ln_entype := 3;
   ELSIF an_etype = 10 THEN
    lv_what := 'aq2m';
    ln_entype := 3;
   ELSIF an_etype = 11 THEN
    lv_what := 'aq3m';
    ln_entype := 5;
   ELSIF an_etype = 12 THEN
    lv_what := 'aq4m';
    ln_entype := 5;
   --зона B
   ELSIF an_etype = 13 THEN
    lv_what := 'berm';
    ln_entype := 1;
   ELSIF an_etype = 14 THEN
    lv_what := 'bedm';
    ln_entype := 2;
   ELSIF an_etype = 15 THEN
    lv_what := 'bq1m';
    ln_entype := 3;
   ELSIF an_etype = 16 THEN
    lv_what := 'bq2m';
    ln_entype := 3;
   ELSIF an_etype = 17 THEN
    lv_what := 'bq3m';
    ln_entype := 5;
   ELSIF an_etype = 18 THEN
    lv_what := 'bq4m';
    ln_entype := 5;
   --зона C
   ELSIF an_etype = 19 THEN
    lv_what := 'cerm';
    ln_entype := 1;
   ELSIF an_etype = 20 THEN
    lv_what := 'cedm';
    ln_entype := 2;
   ELSIF an_etype = 21 THEN
    lv_what := 'cq1m';
    ln_entype := 3;
   ELSIF an_etype = 22 THEN
    lv_what := 'cq2m';
    ln_entype := 3;
   ELSIF an_etype = 23 THEN
    lv_what := 'cq3m';
    ln_entype := 5;
   ELSIF an_etype = 24 THEN
    lv_what := 'cq4m';
    ln_entype := 5;
   ELSE
    lv_what := 'erm';
    ln_entype := 1;
   END IF;

   IF lc.t = 7 THEN                                                                                                                               --для switches
    lv_sql := 'select dswitch date_time,' || lv_what || ' from ' || lv_tab || ' where nswitch=:1 and dswitch-:2=:3 and ' || lv_what || ' is not null';
   ELSIF lc.t = 8 THEN
    lv_what := lv_what || 'e';
    lv_sql := 'select descape date_time,' || lv_what || ' from ' || lv_tab || ' where nswitch=:1 and descape-:2=:3 and ' || lv_what || ' is not null';
   ELSE
    lv_sql := 'select date_time,' || lv_what || ' from ' || lv_tab || ' where mid=:1 and date_time-:2=:3 and ' || lv_what || ' is not null';
   END IF;

   IF lb_add THEN
    IF an_mettype = 0 THEN
     lv_agr := 'min';
    ELSE
     lv_agr := 'max';
    END IF;

    lv_sql :=
            lv_sql || ' and nsource=(select ' || lv_agr || '(nsource) from ' || lv_tab || ' where mid=:4 and date_time-:5=:6 and ' || lv_what || ' is not null)';

    EXECUTE IMMEDIATE lv_sql
    INTO              ln_retdat, ln_ret
    USING             an_mid, ad_date, ln_difdat, an_mid, ad_date, ln_difdat;
   ELSE
    EXECUTE IMMEDIATE lv_sql
    INTO              ln_retdat, ln_ret
    USING             an_mid, ad_date, ln_difdat;
   END IF;

   IF ln_retdat = ad_date THEN
    RETURN 1;
   ELSE
    RETURN 0;
   END IF;
  END LOOP;

  RETURN 0;
 END;

