 FUNCTION get_meterage_exists_wc(an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, an_table NUMBER)
  RETURN NUMBER IS
  CURSOR lcur_sel IS
   SELECT   1 t
   FROM     billorg
   WHERE    mid = an_mid AND date_time = ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
            AND DECODE(NVL(an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   3 t
   FROM     monthsorg
   WHERE    mid = an_mid AND date_time = ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
            AND DECODE(NVL(an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   0 t
   FROM     halfhour
   WHERE    NOT(NVL(get_customer_id, 0) = 16 AND an_etype IN(3, 4, 5, 6) AND mid IN(3154, 3156)) AND mid = an_mid AND date_time = ad_date
            AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL AND DECODE(NVL(an_table, 0), 0, 4, an_table) = 4
   UNION ALL
   SELECT   5 t
   FROM     man_inp_hhour
   WHERE    mid = an_mid AND date_time = ad_date
            AND DECODE(
                an_etype,
                2, edm,
                3, q1m,
                4, q2m,
                5, q3m,
                6, q4m,
                7, aerm,
                8, aedm,
                9, aq1m,
                10, aq2m,
                11, aq3m,
                12, aq4m,
                13, berm,
                14, bedm,
                15, bq1m,
                16, bq2m,
                17, bq3m,
                18, bq4m,
                19, cerm,
                20, cedm,
                21, cq1m,
                22, cq2m,
                23, cq3m,
                24, cq4m,
                erm
               ) IS NOT NULL
            AND DECODE(NVL(an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT   7 t
   FROM     switches
   WHERE    nswitch = an_mid AND dswitch = ad_date AND DECODE(an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) > 0
            AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   UNION ALL
   SELECT   8 t
   FROM     switches
   WHERE    nswitch = an_mid AND descape = ad_date AND DECODE(an_etype, 2, edme, 3, q1me, 4, q2me, 5, q3me, 6, q4me, erme) > 0
            AND DECODE(NVL(an_table, 0), 0, 5, an_table) = 5
   ORDER BY 1;

  ln_val              NUMBER;
  ln_ret              NUMBER;
  ln_retdat           DATE;
  ln_difdat           NUMBER;                                                                                                                --date_time-ad_date
  lv_tab              VARCHAR2(32);
  lv_what             VARCHAR2(32);
  lb_add              BOOLEAN DEFAULT TRUE;
  lv_sql              VARCHAR2(4000);
  lv_agr              VARCHAR2(32);
  ln_entype           NUMBER;
  ln_digits           NUMBER;
  ln_kc               NUMBER;
  ln_tmp              NUMBER;
 BEGIN
  FOR lc IN lcur_sel LOOP
   RETURN 1;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Возвращает показания счетчика по формату разрядности счетчика
  -- если разрядность не введена, функция не работает
  -- an_mid - Ид точки
  -- ad_date - дата показаниц
  -- an_mettype принимает значения
  --    0 - На момент снятия счетчика или в штатной ситуации( NSOURCE = 7 или NSOURCE > 8)
  --    Иначе - На момент установки счетчика или в штатной ситуации ( NSOURCE = 8 или NSOURCE > 8)
 FUNCTION get_meterage_vch2(an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, av_sep VARCHAR2, an_withoutcalc NUMBER)
  RETURN VARCHAR2 IS
  lndigits            NUMBER;
  lnentype            NUMBER;
  ln_ret              NUMBER;
  lv_sep              VARCHAR2(32) DEFAULT NVL(av_sep, '.');
 BEGIN
  IF an_etype = 1 OR an_etype = 7 OR an_etype = 13 OR an_etype = 19 THEN
   lnentype := 1;
  END IF;

  IF an_etype = 2 OR an_etype = 8 OR an_etype = 14 OR an_etype = 20 THEN
   lnentype := 2;
  END IF;

  IF an_etype = 3 OR an_etype = 9 OR an_etype = 15 OR an_etype = 21 OR an_etype = 4 OR an_etype = 10 OR an_etype = 16 OR an_etype = 22 THEN
   lnentype := 3;
  END IF;

  IF an_etype = 5 OR an_etype = 11 OR an_etype = 17 OR an_etype = 23 OR an_etype = 6 OR an_etype = 12 OR an_etype = 18 OR an_etype = 24 THEN
   lnentype := 5;
  END IF;

  SELECT NVL(MAX(digits), cn_def_digits)
  INTO   lndigits
  FROM   meters
  WHERE  mid = an_mid AND entype IN(lnentype, 7);

  ln_ret := get_meterage(an_mid, ad_date, an_etype, an_mettype, NULL, an_withoutcalc);
  lndigits := LPAD('9', GREATEST(LENGTH(ABS(TRUNC(lndigits))), LENGTH(ABS(TRUNC(ln_ret)))), '9') +(lndigits - TRUNC(lndigits));
  --Берем больше разрядность до запятой если значение больше
  RETURN REPLACE(TO_CHAR(TRUNC(ln_ret, LENGTH(lndigits) - INSTR(REPLACE(TO_CHAR(lndigits), ',', '.'), '.')),
          REPLACE(REPLACE(TO_CHAR(lndigits), '9', '0'), ',', '.')), '.', lv_sep);
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_meterage_difference(an_mid NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, an_mettype NUMBER, an_withoutcalc NUMBER)            -- Умная
  RETURN NUMBER IS
  lnentype            NUMBER;
  lnret               NUMBER;
  ln_mettype1         NUMBER DEFAULT 1;
  ln_mettype2         NUMBER DEFAULT 1;
  lv_sep              VARCHAR2(8) DEFAULT SUBSTR(11 / 10, 2, 1);
  ln_calcpoint        NUMBER;
 BEGIN
  SELECT COUNT(*)
  INTO   ln_calcpoint
  FROM   feeders
  WHERE  mid = an_mid AND ncalcpointtype > 0;

  IF ln_calcpoint > 0 THEN                                                                                                                 --считаем по расходу
   SELECT SUM(DECODE(an_etype, 1, er, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er))
   INTO   lnret
   FROM   billorg
   WHERE  mid = an_mid AND date_time > ad_stdate AND date_time <= ad_findate;

   IF lnret IS NULL THEN
    SELECT SUM(DECODE(an_etype, 1, er, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er))
    INTO   lnret
    FROM   halfhour
    WHERE  mid = an_mid AND date_time > ad_stdate AND date_time <= ad_findate;
   END IF;

   RETURN lnret;
  END IF;

  IF an_etype = 1 OR an_etype = 7 OR an_etype = 13 OR an_etype = 19 THEN
   lnentype := 1;
  END IF;

  IF an_etype = 2 OR an_etype = 8 OR an_etype = 14 OR an_etype = 20 THEN
   lnentype := 2;
  END IF;

  IF an_etype = 3 OR an_etype = 9 OR an_etype = 15 OR an_etype = 21 OR an_etype = 4 OR an_etype = 10 OR an_etype = 16 OR an_etype = 22 THEN
   lnentype := 3;
  END IF;

  IF an_etype = 5 OR an_etype = 11 OR an_etype = 17 OR an_etype = 23 OR an_etype = 6 OR an_etype = 12 OR an_etype = 18 OR an_etype = 24 THEN
   lnentype := 5;
  END IF;

  IF an_mettype = 0 THEN
   ln_mettype1 := 1;
   ln_mettype2 := 0;
  END IF;

  lnret :=
   indicoverturn(REPLACE(REPLACE(get_meterage_vch2(an_mid, ad_findate, an_etype, ln_mettype2, '', an_withoutcalc), ',', lv_sep), '.', lv_sep)
    - REPLACE(REPLACE(get_meterage_vch2(an_mid, ad_stdate, an_etype, ln_mettype1, '', an_withoutcalc), ',', lv_sep), '.', lv_sep),
    NULL);
  RETURN lnret;
 END;

