------------------------------------------------------------------------------------------------------------------------
--Возвращает часы работы за период
-- an_objtype = 0 - для точки
-- an_objtype = 1 - для трансформатора
 FUNCTION get_workhours(an_mid NUMBER, an_period NUMBER, an_objtype NUMBER DEFAULT 0)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  IF an_objtype = 0 THEN
   SELECT MAX(NVL(ph.nworkinghours, f.nworkinghours))
   INTO   ln_ret
   FROM   pointfullhours ph, feeders f
   WHERE  f.mid = an_mid AND f.mid = ph.mid(+) AND naccperiod(+) = an_period;
  END IF;

  IF an_objtype = 1 THEN
   SELECT MAX(NVL(ph.nworkinghours, cp.nworkinghours))
   INTO   ln_ret
   FROM   pointfullhours ph, connectionparam cp
   WHERE  cp.mid = an_mid AND cp.mid = ph.mid(+) AND naccperiod(+) = an_period;
  END IF;

  RETURN NVL(ln_ret, 24 * TO_CHAR(LAST_DAY(TO_DATE(an_period, 'YYYYMM')), 'DD'));
 END;

 ------------------------------------------------------------------------------------------------------------------------
--Возвращает полные часы
-- an_objtype = 0 - для точки
-- an_objtype = 1 - для трансформатора
 FUNCTION get_follhours(an_mid NUMBER, an_period NUMBER, an_objtype NUMBER DEFAULT 0)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  IF an_objtype = 0 THEN
   SELECT MAX(NVL(ph.nfullhours, f.nfullhours))
   INTO   ln_ret
   FROM   pointfullhours ph, feeders f
   WHERE  f.mid = an_mid AND f.mid = ph.mid(+) AND naccperiod(+) = an_period;
  END IF;

  IF an_objtype = 1 THEN
   SELECT MAX(NVL(ph.nfullhours, cp.nfullhours))
   INTO   ln_ret
   FROM   pointfullhours ph, connectionparam cp
   WHERE  cp.mid = an_mid AND cp.mid = ph.mid(+) AND naccperiod(+) = an_period;
  END IF;

  RETURN NVL(ln_ret, 24 * TO_CHAR(LAST_DAY(TO_DATE(an_period, 'YYYYMM')), 'DD'));
 END;

