------------------------------------------------------------------------------------------------------------------------
-- Возвращает время достижения максимальной нагрузки
 FUNCTION get_timemaxpower(an_gid NUMBER, ad_from DATE, ad_till DATE)
  RETURN DATE IS
  ld_ret              DATE;

  CURSOR lcur_sel IS
   SELECT   t.dt
   FROM     (SELECT     (
                         SUM(DECODE(
                           gr.inverted,
                           'y', -sld(gr.mid, NVL(h.er * DECODE(gr.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(gr.npartly, 1, 0, 1), 0)),
                           sld(gr.mid, NVL(h.er * DECODE(gr.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(gr.npartly, 1, 0, 1), 0))
                          ))
                        )
                      * 2 er,
                      trunchh24_2(h.date_time - 1 / 86400) + 1 / 48 dt, get_grouplimit(an_gid, trunchh24_2(h.date_time - 1 / 86400) + 1 / 48) lim
             FROM     halfhour h,
                      (SELECT     mid, gid, inverted, npartly
                       FROM       GROUPS g
                       CONNECT BY PRIOR gid = PARENT
                       START WITH gid = an_gid) gr
             WHERE    gr.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till
             GROUP BY trunchh24_2(h.date_time - 1 / 86400)) t
   WHERE    t.er > t.lim
   ORDER BY t.er - t.lim DESC, t.dt;
 BEGIN
  OPEN lcur_sel;

  FETCH lcur_sel
  INTO  ld_ret;

  CLOSE lcur_sel;

  RETURN ld_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возвращает расход за период
 FUNCTION get_saldo(an_gid NUMBER, ad_from DATE, ad_till DATE, an_act NUMBER DEFAULT 1)
  RETURN NUMBER IS
  ln_ret              NUMBER;
 BEGIN
  IF ad_from IS NULL THEN
   SELECT (
           SUM(DECODE(
             gr.inverted,
             'y', -sld(gr.mid, NVL(h.er * DECODE(gr.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(gr.npartly, 1, 0, 1), 0)),
             sld(gr.mid, NVL(h.er * DECODE(gr.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(gr.npartly, 1, 0, 1), 0))
            ))
          ) er
   INTO   ln_ret
   FROM   curr_power h,
          (SELECT     mid, gid, inverted, npartly
           FROM       GROUPS g
           CONNECT BY PRIOR gid = PARENT
           START WITH gid = an_gid) gr
   WHERE  gr.mid = h.mid AND SIGN(obsolescence_f / 1440 - ABS(SYSDATE - h.date_time)) = 1;
  ELSE
   SELECT (
           SUM(DECODE(
             gr.inverted,
             'y', -sld(gr.mid, NVL(h.er * DECODE(gr.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(gr.npartly, 1, 0, 1), 0)),
             sld(gr.mid, NVL(h.er * DECODE(gr.npartly, 2, 0, 1), 0), NVL(h.ed * DECODE(gr.npartly, 1, 0, 1), 0))
            ))
          ) er
   INTO   ln_ret
   FROM   halfhour h,
          (SELECT     mid, gid, inverted, npartly
           FROM       GROUPS g
           CONNECT BY PRIOR gid = PARENT
           START WITH gid = an_gid) gr
   WHERE  gr.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_ad_balance(an_gid NUMBER, ad_from DATE, ad_till DATE, an_proc NUMBER, av_oratable VARCHAR2)
  RETURN NUMBER IS
  cv_sigma2  CONSTANT VARCHAR2(32) DEFAULT '100 / 100';
  cn_defmeterclass CONSTANT NUMBER DEFAULT 1;
  ln_ret              NUMBER;
  lv_sql              VARCHAR2(10000);
 BEGIN
  IF ad_from IS NULL THEN
   lv_sql :=
       ' SELECT POWER (SUM (t.deltar2 * t.itr2 + t.deltad2 * t.itd2), 1 / 2) * DECODE (:an_proc, 1, 1, GREATEST (MAX (t.er), MAX (t.ed)) / 100) nb
     FROM (SELECT NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) * NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) itr2,
                  NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) * NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) itd2,'
    || cv_sigma2
    || '
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, ''y'', mr.dclass, mr.eclass), '
    || TO_CHAR(cn_defmeterclass)
    || ' )
                       * NVL (DECODE (gr.inverted, ''y'', mr.dclass, mr.eclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                    ) deltar2,'
    || cv_sigma2
    || '* (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, ''y'', mr.eclass, mr.dclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                       * NVL (DECODE (gr.inverted, ''y'', mr.eclass, mr.dclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                    ) deltad2,
                  sm.er, sm.ed
             FROM (SELECT   g.gid, NVL (SUM (DECODE (g.inverted, ''y'', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, ''y'', h.er, h.ed)), 0) ed
                       FROM GROUPS g, curr_power h
                      WHERE g.gid IN (SELECT     gid
                                            FROM GROUPS
                                      CONNECT BY PRIOR gid = PARENT
                                      START WITH gid = :an_gid) AND g.mid = h.mid AND SIGN (util_pg.obsolescence_f / 1440 - ABS (SYSDATE - h.date_time)) = 1
                   GROUP BY g.gid) it,
                  (SELECT NVL (SUM (DECODE (g.inverted, ''y'', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, ''y'', h.er, h.ed)), 0) ed
                     FROM GROUPS g, curr_power h
                    WHERE g.gid IN (SELECT     gid
                                          FROM GROUPS
                                    CONNECT BY PRIOR gid = PARENT
                                    START WITH gid = :an_gid) AND g.mid = h.mid AND SIGN (util_pg.obsolescence_f / 1440 - ABS (SYSDATE - h.date_time)) = 1) sm,
                  (SELECT   mid, MAX (DECODE (entype, 1, mclass, 7, mclass, NULL)) eclass, MAX (DECODE (entype, 2, mclass, 7, mclass, NULL)) dclass
                       FROM meters
                   GROUP BY mid) mr,
                  GROUPS gr,
                  feeders fr
            WHERE it.gid = gr.gid(+) AND gr.mid = fr.mid(+) AND gr.mid = mr.mid(+)) t ';

   EXECUTE IMMEDIATE lv_sql
   INTO              ln_ret
   USING             an_proc, an_gid, an_gid;
  ELSE
   lv_sql :=
       ' SELECT POWER (SUM (t.deltar2 * t.itr2 + t.deltad2 * t.itd2), 1 / 2) * DECODE ( :an_proc, 1, 1, GREATEST (MAX (t.er), MAX (t.ed)) / 100) nb
    
     FROM (SELECT NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) * NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) itr2,
                  NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) * NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) itd2,'
    || cv_sigma2
    || '
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, ''y'', mr.dclass, mr.eclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                       * NVL (DECODE (gr.inverted, ''y'', mr.dclass, mr.eclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                    ) deltar2,'
    || cv_sigma2
    || '
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, ''y'', mr.eclass, mr.dclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                       * NVL (DECODE (gr.inverted, ''y'', mr.eclass, mr.dclass), '
    || TO_CHAR(cn_defmeterclass)
    || ')
                    ) deltad2,
                  sm.er, sm.ed
             FROM (SELECT   g.gid, NVL (SUM (DECODE (g.inverted, ''y'', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, ''y'', h.er, h.ed)), 0) ed
                       FROM GROUPS g,'
    || av_oratable
    || ' h
                     
                      WHERE g.gid IN (SELECT     gid
                                            FROM GROUPS
                                      CONNECT BY PRIOR gid = PARENT
                                      START WITH gid = :an_gid) AND g.mid = h.mid AND h.date_time > :ad_from AND h.date_time <= :ad_till
                   GROUP BY g.gid) it,
                  (SELECT NVL (SUM (DECODE (g.inverted, ''y'', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, ''y'', h.er, h.ed)), 0) ed
                     FROM GROUPS g, '
    || av_oratable
    || ' h
                 
                    WHERE g.gid IN (SELECT     gid
                                          FROM GROUPS
                                    CONNECT BY PRIOR gid = PARENT
                                    START WITH gid = :an_gid) AND g.mid = h.mid AND h.date_time > :ad_from AND h.date_time <= :ad_till) sm,
                  (SELECT   mid, MAX (DECODE (entype, 1, mclass, 7, mclass, NULL)) eclass, MAX (DECODE (entype, 2, mclass, 7, mclass, NULL)) dclass
                       FROM meters
                   GROUP BY mid) mr,
                  GROUPS gr,
                  feeders fr
            WHERE it.gid = gr.gid(+) AND gr.mid = fr.mid(+) AND gr.mid = mr.mid(+)) t ';

   EXECUTE IMMEDIATE lv_sql
   INTO              ln_ret
   USING             an_proc, an_gid, ad_from, ad_till, an_gid, ad_from, ad_till;
  END IF;

  RETURN ln_ret;
 END;

