------------------------------------------------------------------------------------------------------------------------
  --Приводит время счетчика к часовому поясу украины
 FUNCTION convertmeterdate_f(an_mid NUMBER, ad_date DATE)
  RETURN DATE IS
  ln_tzw              NUMBER;
  ln_tzs              NUMBER;
 BEGIN
  SELECT NVL(MAX(ntimezonew), cn_tzw), NVL(MAX(ntimezones), cn_tzs)
  INTO   ln_tzw, ln_tzs
  FROM   feeders
  WHERE  mid = an_mid;

  RETURN convertmeterdate_f(ad_date, ln_tzw, ln_tzs);
 END;

------------------------------------------------------------------------------------------------------------------------
  --Приводит время счетчика к часовому поясу украины с Европой без перехода
 FUNCTION convertmeterdate_e_f(an_mid NUMBER, ad_date DATE)
  RETURN DATE IS
  ln_tzw              NUMBER;
  ln_tzs              NUMBER;
 BEGIN
  SELECT NVL(MAX(ntimezonew), cn_tzw), NVL(MAX(ntimezones), cn_tzs)
  INTO   ln_tzw, ln_tzs
  FROM   feeders
  WHERE  mid = an_mid;

  IF taketimezone = 1 THEN
   IF ln_tzw = ln_tzs THEN
    RETURN to_localtime(ad_date + (cn_tzw - ln_tzw) / 24);
   ELSE
    RETURN ad_date + (cn_tzw - ln_tzw) / 24;
   END IF;
  END IF;

  RETURN ad_date;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Приводит время счетчика к часовому поясу украины
 FUNCTION convertmeterdate_f(ad_date DATE, an_tzw NUMBER, an_tzs NUMBER)
  RETURN DATE IS
 BEGIN
  IF taketimezone = 1 THEN
   RETURN ad_date + (cn_tzw - an_tzw) / 24;
  END IF;

  RETURN ad_date;
 END;

