-- Поиск точки поставки
 FUNCTION getsupplypoint(an_mid NUMBER, an_maxlevel NUMBER)
  RETURN NUMBER IS
  ln_mid              NUMBER DEFAULT an_mid;
  ln_i                NUMBER DEFAULT 0;
 BEGIN
  FOR lc IN (SELECT     mid
             FROM       points
             CONNECT BY PRIOR PARENT = mid AND ind IN(3, 4)
             START WITH mid = an_mid) LOOP
   ln_mid := lc.mid;
   ln_i := ln_i + 1;

   IF ln_i > an_maxlevel THEN
    EXIT;
   END IF;
  END LOOP;

  RETURN ln_mid;
 END;

