--Прием с отдачей убираем минус
 PROCEDURE invert_p(an_er IN OUT NUMBER, an_ed IN OUT NUMBER, an_witherr NUMBER) IS
  ln_tmp              NUMBER;
 BEGIN
  --Мы так метим тех, кого считать не надо
  IF an_er = cn_random THEN
   an_er := NULL;
  END IF;

  IF an_ed = cn_random THEN
   an_ed := NULL;
  END IF;

  IF an_ed < 0 AND an_er < 0 THEN
   ln_tmp := an_er;
   an_er := -an_ed;
   an_ed := -ln_tmp;
  ELSIF NOT(NVL(an_witherr, 0) = 1 AND gn_en_negative = 1) THEN
   --По просьбе Жернова ELSIF NOT (NVL (an_witherr, 0) = 1 AND get_customer_id = 44) надо ELSE
   IF an_ed < 0 THEN
    an_er := sumn(-an_ed, an_er);
    an_ed := 0;
   ELSIF an_er < 0 THEN
    an_ed := sumn(-an_er, an_ed);
    an_er := 0;
   END IF;
  END IF;
 END;

