--Текст предупреждения пользователю
 FUNCTION warning_f
  RETURN VARCHAR2 IS
  ln_dat              NUMBER;                                                                                 -- кол-во дней до истечения срока действия пароля
  max_dat             NUMBER DEFAULT 45;                                                                      -- начиная с какого срока выдавать предупреждение
  lv_ret              VARCHAR2(256);                                                                                             -- предупреждение пользователю
  lv_sql              VARCHAR2(256);                                                                                                      -- строка SQL-запроса
 BEGIN
  IF get_customer_id <> 1 THEN
   RETURN '';
  END IF;

  lv_ret := '';
  lv_sql := 'select trunc(expiry_date) - trunc(sysdate) from auddba.db_users where username=:1';

  EXECUTE IMMEDIATE lv_sql
  INTO              ln_dat
  USING             USER;

  IF NVL(ln_dat, max_dat) <= 0 THEN
   lv_ret := 'Срок действия Вашего пароля истек! Обязательно смените его сегодня!     ';
  ELSIF NVL(ln_dat, max_dat) < max_dat THEN
   lv_ret := 'Срок действия Вашего пароля истекает через ' || ln_dat;

   IF MOD(ln_dat, 10) = 0 OR MOD(ln_dat, 10) >= 5 OR(MOD(ln_dat, 100) >= 11 AND MOD(ln_dat, 100) < 20) THEN
    lv_ret := lv_ret || ' дней';
   ELSIF MOD(ln_dat, 10) = 1 THEN
    lv_ret := lv_ret || ' день';
   ELSE
    lv_ret := lv_ret || ' дня';
   END IF;

   lv_ret := lv_ret || '! Не забудьте сменить его до ' || TO_CHAR(SYSDATE + ln_dat, 'dd.mm.yyyy') || ' !     ';
  END IF;

  RETURN lv_ret;
 EXCEPTION
  WHEN OTHERS THEN
   RETURN '';
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION convertclob(ac_data CLOB)
  RETURN common_pg.tt_varchar2 IS
  lt_data             common_pg.tt_varchar2;
  lv_instr   CONSTANT VARCHAR2(4) := CHR(13) || CHR(10);
  i                   INTEGER DEFAULT 1;
  k                   INTEGER;
 BEGIN
  k := INSTR(ac_data, lv_instr, i);

  WHILE k > 0 LOOP
   lt_data(lt_data.COUNT + 1) := SUBSTR(ac_data, i, k - i);
   i := k + 2;
   k := INSTR(ac_data, lv_instr, i);
  END LOOP;

  lt_data(lt_data.COUNT + 1) := SUBSTR(ac_data, i);
  RETURN lt_data;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION convertclob(at_data common_pg.tt_varchar2)
  RETURN CLOB IS
  lc_data             CLOB;
 BEGIN
  FOR i IN 1 .. at_data.COUNT LOOP
   IF i > 1 THEN
    lc_data := lc_data || CHR(13) || CHR(10) || at_data(i);
   ELSE
    lc_data := at_data(i);
   END IF;
  END LOOP;

  RETURN lc_data;
 END;

--------------------------------------------------------------------------------------------------------------
 --BITOR
 FUNCTION bitor(x NUMBER, y NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN(x + y - BITAND(x, y));
 END;

------------------------------------------------------------------------------------------------------------------------
 --BITXOR
 FUNCTION bitxor(x NUMBER, y NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN(bitor(x, y) - BITAND(x, y));
 END;

------------------------------------------------------------------------------------------------------------------------

 --BITNOT
 FUNCTION bitnot(x NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN(-1 - x);
 END;

------------------------------------------------------------------------------------------------------------------------
 --BITSET
 FUNCTION bitset(x NUMBER, bit NUMBER, bitval NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF bitval = 0 THEN
   RETURN BITAND(x, bitnot(POWER(2, bit)));
  ELSE
   RETURN bitor(x, POWER(2, bit));
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------
--возвращает числовое представление метки качества при загрузке из таблицы PQ
 FUNCTION varch2tonum(an_test VARCHAR2)
  RETURN NUMBER IS
  lv_test             VARCHAR2(100);
  ln_a                NUMBER;
  ln_b                NUMBER;
 BEGIN
  ln_a := 0;
  ln_b := 0;
  lv_test := TRIM(UPPER(an_test));
  lv_test := SUBSTR(lv_test, 1, INSTR(lv_test, ':') - 1);

  IF lv_test IS NULL THEN
   RETURN 0;
  END IF;

  ln_a := INSTR(lv_test, 'PQEN');

  IF ln_a > 0 THEN
   --LENGTH('PQEN')=4
   ln_b := SUBSTR(lv_test, ln_a + 4, LENGTH(lv_test) - 4);

   IF ln_b > 0 AND ln_b < 13 THEN
    RETURN POWER(2, ln_b + 12) + 3;
   ELSE
    RETURN 0;
   END IF;
  ELSE
   ln_a := INSTR(lv_test, 'PQE');

   IF ln_a > 0 THEN
    --LENGTH('PQE')=3
    ln_b := SUBSTR(lv_test, ln_a + 3, LENGTH(lv_test) - 3);

    IF ln_b > 0 AND ln_b < 11 THEN
     RETURN POWER(2, ln_b + 2) + 5;
    ELSE
     RETURN 0;
    END IF;
   ELSE
    RETURN 0;
   END IF;
  END IF;
 END;

--------------------------------------------------------------------------------------------------------
--возвращает бинарное представление метки качества переведенное в строковое т.е.
-- первый символ соответствует нулевому биту и т.д.
 FUNCTION num_to_bin(an_test NUMBER)
  RETURN VARCHAR2 IS
  b                   NUMBER;
  s                   VARCHAR2(50);
 BEGIN
  b := an_test;

  IF an_test = 0 OR an_test IS NULL THEN
   s := '0';
  END IF;

  WHILE b > 0 LOOP
   s := s || MOD(b, 2);
   b := TRUNC(b / 2);
  END LOOP;

  s := RPAD(s, 25, '0');
  /* IF LENGTH (s) < 25 THEN
    FOR i IN 1 .. 25 - LENGTH (s) LOOP
     s := '0' || s;
    END LOOP;
   END IF;*/
  RETURN s;
 END;

