 -- added by KAG 10.11.2010
 -- возвращает математически округленное или усеченное до целого значение
 FUNCTION round_trunc(an_val NUMBER, an_trunc NUMBER, an_err NUMBER)                                                   -- an_trunc=1 то будет TRUNC, иначе ROUND
  RETURN NUMBER IS
 /*Если an_err не задан то считаем что данные передаются уже с остатком лкругления, иначе без него*/
 BEGIN
  IF an_trunc = 1 THEN
   RETURN TRUNC(an_val + NVL(an_err, 0));
  ELSIF an_val = 0 AND an_err = -1 / 2 THEN                                              --Ето изменяет алгоритм, когда входящий остаток равен -1/2 и пошли нули
   RETURN 0;
  ELSE
   RETURN ROUND(an_val + NVL(an_err, 0));
  END IF;
 END;

