-- Start of DDL Script for Package Body RYDA.UTILREP_PG
-- Generated 14.04.2014 9:35:00 from RYDA@oe

CREATE OR REPLACE 
PACKAGE BODY utilrep_pg IS
------------------------------------------------------------------------------------------------------------------------
--Вспомогательный пакет для отчетов PL_SQL
-- 20/11/2008
------------------------------------------------------------------------------------------------------------------------
 gt_sortobject    common_pg.tt_number;
 gt_objectindex   common_pg.tt_number;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE f_preparesortbyl_n IS
 BEGIN
  gt_sortobject.DELETE;
  gt_objectindex.DELETE;
 END;

-------------------------------------------------------------------------------------------------
 FUNCTION f_recursort (an_id NUMBER, an_sort NUMBER, an_objtype NUMBER)
  RETURN NUMBER IS
  ln_sort    NUMBER DEFAULT an_sort;
  ln_index   NUMBER DEFAULT 0;
 BEGIN
  IF an_objtype = 1 THEN   --Дерево групп
   IF an_id IS NULL THEN
    FOR lc IN (SELECT   gid
                   FROM GROUPS
                  WHERE PARENT IS NULL
               ORDER BY NAME) LOOP
     ln_sort := ln_sort + 1;
     ln_index := ln_index + 1;
     gt_sortobject (lc.gid) := ln_sort;
     gt_objectindex (lc.gid) := ln_index;
     ln_sort := f_recursort (lc.gid, ln_sort, an_objtype);
    END LOOP;
   ELSE
    FOR lc IN (SELECT   gid
                   FROM GROUPS
                  WHERE PARENT = an_id
               ORDER BY NAME) LOOP
     ln_sort := ln_sort + 1;
     ln_index := ln_index + 1;
     gt_sortobject (lc.gid) := ln_sort;
     gt_objectindex (lc.gid) := ln_index;
     ln_sort := f_recursort (lc.gid, ln_sort, an_objtype);
    END LOOP;
   END IF;
  END IF;

  RETURN ln_sort;
 END;

-------------------------------------------------------------------------------------------------
 FUNCTION f_sortbyl_n (an_needread NUMBER, an_id NUMBER, an_start NUMBER, an_objtype NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN gt_sortobject (an_id);
 EXCEPTION
  WHEN OTHERS THEN
   RETURN 100000000;
 END;

-------------------------------------------------------------------------------------------------
 FUNCTION f_makeindex (an_needread NUMBER, an_id NUMBER, an_start NUMBER, an_objtype NUMBER)
  RETURN NUMBER IS
  ln_sort   NUMBER DEFAULT 0;
 BEGIN
  IF NVL (an_needread, 1) <= 1 THEN
   gt_objectindex (an_id) := ln_sort;
   ln_sort := f_recursort (an_start, ln_sort, an_objtype);
  END IF;

  RETURN gt_objectindex (an_id);
 EXCEPTION
  WHEN OTHERS THEN
   RETURN 100000000;
 END;
-------------------------------------------------------------------------------------------------

END;   -- Package Body UTILREP_PG
/


