-----------------------------------------------------------------------
 --построение таблицы для профиля день
 PROCEDURE get_day_values(an_id NUMBER, av_date VARCHAR2, an_in_tbl NUMBER, acur_t OUT common_pg.tcur) IS
  lv_grouping         VARCHAR2(200);
  ld_firstdate        DATE;
  ld_lastdate         DATE;
  lv_sql              VARCHAR2(10000);
  lv_sub              VARCHAR2(500);
 BEGIN
  ld_firstdate := TO_DATE(av_date, 'dd.mm.yyyy') + interior_pg.get_hourtimezone;
  ld_lastdate := TO_DATE(av_date, 'dd.mm.yyyy') + 1 + interior_pg.get_hourtimezone;
  lv_grouping := ' util_pg.get_num_dt (date_time-1/86400,nsource, 1/24 ,0,interior_pg.get_hourtimezone,interior_pg.get_dsummer) ';

  IF util_pg.get_customer_id = 1 THEN
   lv_sub :=
    ' g.gid IN (SELECT     gid
                             FROM GROUPS
                       CONNECT BY ((PRIOR gid = PARENT) OR (PRIOR nroot2 = nroot2 AND PRIOR nroot1 > 0 AND nroot1 IS NULL))
                       START WITH gid = :par1) ';
  ELSE
   lv_sub :=
    ' g.gid IN (SELECT     gid
                             FROM GROUPS
                       CONNECT BY (PRIOR gid = PARENT) 
                       START WITH gid = :par1) ';
  END IF;

  IF an_in_tbl = 0 THEN
   lv_sql :=
       'SELECT   decode(grouping('
    || lv_grouping
    || '),1,0,'
    || lv_grouping
    || ') i,
             SUM (DECODE (g.inverted, ''y'', NVL (h.ed * DECODE (g.npartly, 1, 0, 1), 0), NVL (h.er * DECODE (g.npartly, 2, 0, 1), 0))) er,
             SUM (DECODE (g.inverted, ''y'', NVL (h.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (g.npartly, 1, 0, 1), 0))) ed,
             SUM (DECODE (g.inverted, ''y'', NVL (h.q3, 0), NVL (h.q1, 0))) q1, SUM (DECODE (g.inverted, ''y'', NVL (h.q1, 0), NVL (h.q3, 0))) q3,
             SUM (DECODE (g.inverted, ''y'', NVL (h.q4, 0), NVL (h.q2, 0))) q2, SUM (DECODE (g.inverted, ''y'', NVL (h.q2, 0), NVL (h.q4, 0))) q4,
             NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
        FROM GROUPS g, halfhour h 
       WHERE  '
    || lv_sub
    || '
             AND h.mid = g.mid 
             AND date_time > :par2 AND date_time <= :par3
    GROUP BY rollup('
    || lv_grouping
    || ')    
    ORDER BY 1';

   --  insert into tmp_vil values(an_in_tbl||' '||an_id||' '||to_char(ld_firstdate,'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_lastdate,'dd.mm.yyyy hh24:mi:ss')||' '||lv_sql);commit;
   OPEN acur_t FOR lv_sql USING an_id, ld_firstdate, ld_lastdate;
  ELSIF an_in_tbl = 1 THEN
   lv_sql :=
       'SELECT  '
    || lv_grouping
    || ' i, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
             NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
        FROM halfhour
       WHERE mid IN (SELECT     mid
                           FROM points
                     CONNECT BY PRIOR mid = PARENT
                     START WITH mid = :par1) 
             AND date_time > :par2 AND date_time <= :par3
    GROUP BY '
    || lv_grouping
    || '
    UNION ALL
    SELECT   0 i, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2, NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4,
             NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
        FROM halfhour
       WHERE mid IN (SELECT     mid
                           FROM points
                     CONNECT BY PRIOR mid = PARENT
                     START WITH mid = :par4) 
             AND date_time > :par5 AND date_time <= :par6
    ORDER BY 1 ';

   -- insert into tmp_vil values(an_in_tbl||' '||an_id||' '||to_char(ld_firstdate,'dd.mm.yyyy hh24:mi:ss')||' '||to_char(ld_lastdate,'dd.mm.yyyy hh24:mi:ss')||' '||lv_sql);commit;
   OPEN acur_t FOR lv_sql USING an_id, ld_firstdate, ld_lastdate, an_id, ld_firstdate, ld_lastdate;
  END IF;
 END;

-----------------------------------------------------------------------------
 --построение таблицы для профиля месяц
 PROCEDURE get_month_values(an_id NUMBER, av_date VARCHAR2, an_in_tbl NUMBER, acur_t OUT common_pg.tcur) IS
  lv_grouping         VARCHAR2(200);
  ld_firstdate        DATE;
  ld_lastdate         DATE;
  lv_sql              VARCHAR2(10000);
  lv_table            VARCHAR2(200);
  lv_sub              VARCHAR2(500);
 BEGIN
  ld_firstdate := TRUNC(TO_DATE(av_date, 'dd.mm.yyyy'), 'MM') + interior_pg.get_hourtimezone;
  ld_lastdate := ADD_MONTHS(TRUNC(TO_DATE(av_date, 'dd.mm.yyyy'), 'MM'), 1) + interior_pg.get_hourtimezone;
  lv_grouping := ' 0 + TO_CHAR(date_time - 1/86400 - interior_pg.get_hourtimezone, ''DD'') ';

  IF (interior_pg.get_hourtimezone = 0) THEN
   lv_table := ' bill ';
  ELSE
   lv_table := ' halfhour ';
  END IF;

  IF util_pg.get_customer_id = 1 THEN
   lv_sub :=
    ' g.gid IN (SELECT     gid
                             FROM GROUPS
                       CONNECT BY ((PRIOR gid = PARENT) OR (PRIOR nroot2 = nroot2 AND PRIOR nroot1 > 0 AND nroot1 IS NULL))
                       START WITH gid = :par1) ';
  ELSE
   lv_sub :=
    ' g.gid IN (SELECT     gid
                              FROM GROUPS
                       CONNECT BY (PRIOR gid = PARENT)
                       START WITH gid = :par1) ';
  END IF;

  IF an_in_tbl = 0 THEN
   lv_sql :=
       'SELECT '
    || util_pg.hint_ordered
    || 'decode(grouping('
    || lv_grouping
    || '),1,0,'
    || lv_grouping
    || ') i,
             SUM (DECODE (g.inverted, ''y'', NVL (b.ed * DECODE (g.npartly, 1, 0, 1), 0), NVL (b.er * DECODE (g.npartly, 2, 0, 1), 0))) er,
             SUM (DECODE (g.inverted, ''y'', NVL (b.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (b.ed * DECODE (g.npartly, 1, 0, 1), 0))) ed,
             SUM (DECODE (g.inverted, ''y'', NVL (b.q3, 0), NVL (b.q1, 0))) q1, SUM (DECODE (g.inverted, ''y'', NVL (b.q1, 0), NVL (b.q3, 0))) q3,
             SUM (DECODE (g.inverted, ''y'', NVL (b.q4, 0), NVL (b.q2, 0))) q2, SUM (DECODE (g.inverted, ''y'', NVL (b.q2, 0), NVL (b.q4, 0))) q4,
             NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
        FROM GROUPS g, '
    || lv_table
    || ' b 
       WHERE '
    || lv_sub
    || '
             AND b.mid = g.mid 
             AND date_time > :par2 AND date_time <= :par3
    GROUP BY rollup('
    || lv_grouping
    || ')
    ORDER BY 1';

   OPEN acur_t FOR lv_sql USING an_id, ld_firstdate, ld_lastdate;
  ELSIF an_in_tbl = 1 THEN
   lv_sql :=
       'SELECT decode(grouping('
    || lv_grouping
    || '),1,0,'
    || lv_grouping
    || ') i,
             NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
             NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
        FROM '
    || lv_table
    || '
       WHERE mid IN (SELECT     mid
                           FROM points
                     CONNECT BY PRIOR mid = PARENT
                     START WITH mid = :par1) 
             AND date_time > :par2 AND date_time <= :par3
    GROUP BY rollup('
    || lv_grouping
    || ')
    ORDER BY 1';

   OPEN acur_t FOR lv_sql USING an_id, ld_firstdate, ld_lastdate;
  END IF;
 END;

