 BEGIN
  ld_firstdate := TO_DATE(av_date, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  lv_table := ' curr_power_arch ';

  IF util_pg.get_customer_id = 1 THEN
   lv_sub :=
    ' g.gid IN (SELECT     gid
                             FROM GROUPS
                       CONNECT BY ((PRIOR gid = PARENT) OR (PRIOR nroot2 = nroot2 AND PRIOR nroot1 > 0 AND nroot1 IS NULL))
                       START WITH gid = :par1) ';
  ELSE
   lv_sub :=
    ' g.gid IN (SELECT     gid
                              FROM GROUPS
                       CONNECT BY (PRIOR gid = PARENT)
                       START WITH gid = :par1) ';
  END IF;

  ------------------ вернул заглушку по просьбе Олега
  IF FALSE THEN
   lv_sql := 'SELECT 1 i,10 er,11 ed,12 q1,13 q2, 12 q3,13 q4, qm_pg.defqm qm FROM dual  ORDER BY 1';

   OPEN acur_t FOR lv_sql;
  ELSIF an_in_tbl = 0 THEN
   --IF an_in_tbl = 0 THEN  -- из дерева групп
   lv_sql :=
       'SELECT 1 i,
             NVL (SUM (DECODE (g.inverted, ''y'', NVL (b.ed * DECODE (g.npartly, 1, 0, 1), 0), NVL (b.er * DECODE (g.npartly, 2, 0, 1), 0))), 0) er,
             NVL (SUM (DECODE (g.inverted, ''y'', NVL (b.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (b.ed * DECODE (g.npartly, 1, 0, 1), 0))), 0) ed,
             NVL (SUM (DECODE (g.inverted, ''y'', NVL (b.q3, 0), NVL (b.q1, 0))), 0) q1, NVL (SUM (DECODE (g.inverted, ''y'', NVL (b.q1, 0), NVL (b.q3, 0))), 0) q3,
             NVL (SUM (DECODE (g.inverted, ''y'', NVL (b.q4, 0), NVL (b.q2, 0))), 0) q2, NVL (SUM (DECODE (g.inverted, ''y'', NVL (b.q2, 0), NVL (b.q4, 0))), 0) q4,
             qm_pg.defqm qm
        FROM '
    || lv_table
    || ' b, GROUPS g
       WHERE '
    || lv_sub
    || '
             AND b.mid = g.mid 
             AND b.date_time = :par2
    ORDER BY 1';

   OPEN acur_t FOR lv_sql USING an_id, ld_firstdate;
  ELSIF an_in_tbl = 1 THEN                                                                                                                    -- из дерева точек
   lv_sql :=
       'SELECT 1 i,
             NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
             NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, qm_pg.defqm qm
        FROM '
    || lv_table
    || ' 
        WHERE mid IN (SELECT     mid
                           FROM points
                     CONNECT BY PRIOR mid = PARENT
                     START WITH mid = :par1) 
             AND date_time = :par2 
    ORDER BY 1';

   OPEN acur_t FOR lv_sql USING an_id, ld_firstdate;
  END IF;
 END;

-----------------------------------------------------------------------
-- получение узлов дерева точек и групп
-- Kondakov A.G.
 PROCEDURE select_node(an_parent NUMBER, an_in_tbl NUMBER, an_cnt_child OUT NUMBER, acur_t OUT common_pg.tcur) IS
 -- an_parent  - ИД родительского узла, может быть NULL для корневых узлов
 -- an_in_tbl  - 0-тянем из групп, 1-тянем из точек, если an_parent=NULL, то задаем любым
 -- an_cnt_child - количество детей для an_parentы
 -- an_out_tbl - 0-узел из групп, 1-узел из точек
 -- is_point   - 0-папка, 1-точка
 BEGIN
  IF an_parent IS NULL THEN
   OPEN acur_t FOR
    SELECT   gid ID, PARENT, NAME, short_name, DECODE(mid, NULL, 0, 1) is_point, 0 an_out_tbl,decode(mid,NULL,1,3) TYPE,0 ncalcpointtype
    FROM     GROUPS
    WHERE    gid IN(SELECT gid
                    FROM   role_groups
                    WHERE  role_id = (SELECT MAX(role_id)
                                      FROM   users
                                      WHERE  usr = USER)
                    UNION
                    SELECT gid
                    FROM   GROUPS
                    WHERE  PARENT IS NULL AND USER = 'RYDA')
    UNION ALL
    SELECT   p.mid ID, p.PARENT, p.NAME, p.short_name, 0 is_point, 1 an_out_tbl,DECODE(p.ind, 1, 1, 2, 2, 3, 3, 4) TYPE,
NVL(f.ncalcpointtype, 0) ncalcpointtype
    FROM     points p, feeders f
    WHERE    p.mid = util_pg.cn_pntmid AND EXISTS(SELECT *
                                   FROM   users
                                   WHERE  (usr = USER AND ADMIN = '*') OR USER = 'RYDA' OR util_pg.get_customer_id = 52)
                                    AND p.mid = f.mid(+)
    ORDER BY an_out_tbl, is_point, NAME;

   SELECT COUNT(*)
   INTO   an_cnt_child
   FROM   (SELECT gid ID
           FROM   GROUPS
           WHERE  gid IN(SELECT gid
                         FROM   role_groups
                         WHERE  role_id = (SELECT MAX(role_id)
                                           FROM   users
                                           WHERE  usr = USER)
                         UNION
                         SELECT gid
                         FROM   GROUPS
                         WHERE  PARENT IS NULL AND USER = 'RYDA')
           UNION ALL
           SELECT mid ID
           FROM   points
           WHERE  mid = util_pg.cn_pntmid AND EXISTS(SELECT *
                                        FROM   users
                                        WHERE  usr = USER AND ADMIN = '*' OR USER = 'RYDA' OR util_pg.get_customer_id = 52));
  ELSE
   IF an_in_tbl = 0 THEN                                                                                                                      -- тянем из групп
    OPEN acur_t FOR
     SELECT   gid ID, PARENT, NAME, short_name, DECODE(mid, NULL, 0, 1) is_point, 0 an_out_tbl,decode(mid,NULL,1,3) TYPE,0 ncalcpointtype 
     FROM     GROUPS
     WHERE    PARENT = an_parent
     ORDER BY an_out_tbl, is_point, NAME;

    SELECT COUNT(*)
    INTO   an_cnt_child
    FROM   GROUPS
    WHERE  PARENT = an_parent;
   ELSIF an_in_tbl = 1 THEN                                                                                                                    -- тянем из точек
    OPEN acur_t FOR
     SELECT   p.mid ID, p.PARENT, p.NAME, p.short_name, /* DECODE (p.ind, 1, 0, 2, 0,1) */ 0 is_point, 1 an_out_tbl,
     DECODE(p.ind, 1, 1, 2, 2, 3, 3, 4) TYPE,
NVL(f.ncalcpointtype, 0) ncalcpointtype
     FROM     points p, feeders f
     WHERE    p.PARENT = an_parent AND EXISTS(SELECT *
                                              FROM   points ps
                                              WHERE  ps.PARENT = p.mid)
                                              AND p.mid = f.mid(+)
     UNION ALL
     SELECT   p.mid ID, p.PARENT, p.NAME, p.short_name, DECODE(p.ind, 1, 0, 2, 0, 1) is_point, 1 an_out_tbl,
     DECODE(p.ind, 1, 1, 2, 2, 3, 3, 4) TYPE,
NVL(f.ncalcpointtype, 0) ncalcpointtype
     FROM     points p, feeders f
     WHERE    p.PARENT = an_parent AND NOT EXISTS(SELECT *
                                                  FROM   points ps
                                                  WHERE  ps.PARENT = p.mid)
                                                  AND p.mid = f.mid(+)
     ORDER BY an_out_tbl, is_point, NAME;

    SELECT COUNT(*)
    INTO   an_cnt_child
    FROM   points
    WHERE  PARENT = an_parent;
   END IF;
  END IF;
 END;
----------------------------------------------------------------------------------------

END;
/


-- End of DDL Script for Package Body RYDA.WEBCLIENT1_PG

declare
begin
for lc in
(select 'ALTER PACKAGE '||OBJECT_NAME||' COMPILE PACKAGE' c from user_objects where OBJECT_TYPE = 'PACKAGE'AND STATUS = 'INVALID'
union all select 'ALTER VIEW '||OBJECT_NAME||' COMPILE' c from user_objects where OBJECT_TYPE = 'VIEW'AND STATUS = 'INVALID'
union all select 'ALTER PROCEDURE '||OBJECT_NAME||' COMPILE' c from user_objects where OBJECT_TYPE = 'PROCEDURE'AND STATUS = 'INVALID'
union all select 'ALTER FUNCTION ' ||OBJECT_NAME||' COMPILE' c from user_objects where OBJECT_TYPE = 'FUNCTION' AND STATUS = 'INVALID'
union all select 'ALTER PACKAGE '||OBJECT_NAME||' COMPILE BODY' c from user_objects where OBJECT_TYPE = 'PACKAGE BODY' AND STATUS = 'INVALID'
union all select 'ALTER TRIGGER ' ||OBJECT_NAME||' COMPILE' c from user_objects where OBJECT_TYPE = 'TRIGGER' AND STATUS = 'INVALID') loop
begin
execute immediate lc.c;
exception
 when others then null;
end;
end loop;
end;
/

/*

(select 'ALTER PACKAGE '||OBJECT_NAME||' COMPILE PACKAGE;' c from user_objects where OBJECT_TYPE = 'PACKAGE'AND STATUS = 'INVALID'
union all select 'ALTER VIEW '||OBJECT_NAME||' COMPILE;' c from user_objects where OBJECT_TYPE = 'VIEW'AND STATUS = 'INVALID'
union all select 'ALTER PROCEDURE '||OBJECT_NAME||' COMPILE;' c from user_objects where OBJECT_TYPE = 'PROCEDURE'AND STATUS = 'INVALID'
union all select 'ALTER FUNCTION ' ||OBJECT_NAME||' COMPILE;' c from user_objects where OBJECT_TYPE = 'FUNCTION' AND STATUS = 'INVALID'
union all select 'ALTER PACKAGE '||OBJECT_NAME||' COMPILE BODY;' c from user_objects where OBJECT_TYPE = 'PACKAGE BODY' AND STATUS = 'INVALID'
union all select 'ALTER TRIGGER ' ||OBJECT_NAME||' COMPILE;' c from user_objects where OBJECT_TYPE = 'TRIGGER' AND STATUS = 'INVALID')

*/

DECLARE
lv_role varchar2(256):='ASKUE_WORK';
BEGIN
 IF user='OIK' THEN
  lv_role:='OIK_WORK';
 END IF;

 FOR lc IN (SELECT 'grant select on ' || table_name || ' to '||lv_role c
              FROM user_tables WHERE table_name NOT IN ('USERPASS')
            UNION ALL
            SELECT 'grant select on ' || view_name || ' to '||lv_role c
              FROM user_views
            UNION ALL
            SELECT 'grant execute on ' || object_name || ' to '||lv_role c
              FROM user_objects
             WHERE object_type in ('PROCEDURE','FUNCTION','PACKAGE')) LOOP
  BEGIN
   EXECUTE IMMEDIATE lc.c;
  EXCEPTION
   WHEN OTHERS THEN
    NULL;
  END;
 END LOOP;
END;
/

